import React, { useEffect, useState } from 'react';
import { useSelector } from 'react-redux';
import axios from 'axios';
import FirstLoginPasswordReset from './FirstLoginPasswordReset';
import { API_BASE_URL } from '../../config/api.config';
import { STORAGE_KEYS } from '../../config/app.config';

/**
 * First Login Check Component
 * Automatically checks if user needs to reset password after authentication
 * Soft-coded with proper error handling
 */
const FirstLoginCheck = ({ children, onPasswordChanged }) => {
  const { isAuthenticated, user } = useSelector((state) => state.auth);
  const [checking, setChecking] = useState(false);
  const [mustResetPassword, setMustResetPassword] = useState(false);
  const [checked, setChecked] = useState(false);

  // Reset state on logout so the check reruns on the next login
  useEffect(() => {
    if (!isAuthenticated) {
      setChecked(false);
      setMustResetPassword(false);
    }
  }, [isAuthenticated]);

  useEffect(() => {
    const checkFirstLogin = async () => {
      if (!isAuthenticated || checked) {
        return;
      }

      setChecking(true);

      try {
        const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
        
        if (!token) {
          setChecked(true);
          setChecking(false);
          return;
        }

        const response = await axios.get(
          `${API_BASE_URL}/users/check-first-login/`,
          {
            headers: {
              'Authorization': `Bearer ${token}`,
              'Content-Type': 'application/json'
            },
            validateStatus: (status) => status < 500 // Don't throw on 404
          }
        );

        // Handle successful response
        if (response.status === 200) {
          console.log('[FirstLoginCheck] Response:', response.data);

          if (response.data.must_reset_password) {
            setMustResetPassword(true);
          }
        } else if (response.status === 404) {
          console.warn('[FirstLoginCheck] Endpoint not available (404) - skipping check');
        }
        
        setChecked(true);
      } catch (error) {
        console.warn('[FirstLoginCheck] Check failed - not blocking app:', error.message);
        
        // Don't block app if check fails
        setChecked(true);
      } finally {
        setChecking(false);
      }
    };

    checkFirstLogin();
  }, [isAuthenticated, checked]);

  // Show loading while checking
  if (checking) {
    return (
      <div className="fixed inset-0 bg-white bg-opacity-90 flex items-center justify-center z-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Checking authentication...</p>
        </div>
      </div>
    );
  }

  // Show first login password reset modal if needed
  if (mustResetPassword && isAuthenticated) {
    return (
      <>
        {children}
        <FirstLoginPasswordReset
          user={user}
          onSuccess={() => {
            setMustResetPassword(false);
            setChecked(true);
            if (onPasswordChanged) onPasswordChanged();
          }}
        />
      </>
    );
  }

  return children;
};

export default FirstLoginCheck;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import axios from 'axios';
import { API_BASE_URL } from '../../config/api.config';
import { STORAGE_KEYS } from '../../config/app.config';
import { logout, updateUser } from '../../store/slices/authSlice';
import passwordExpiryService from '../../services/passwordExpiry.service';

// Soft-coded post-change behaviour constants
const POST_CHANGE_REDIRECT       = '/login';
const POST_CHANGE_REDIRECT_DELAY = 2000; // ms
const SUCCESS_HEADING            = 'Password Updated!';
const SUCCESS_BODY               = 'Your password has been changed. Redirecting to login page...';

/**
 * First Login Password Reset Component
 * Forces users to change their password on first login
 * Soft-coded with proper validation and error handling
 */
const FirstLoginPasswordReset = ({ user, onSuccess }) => {
  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [formData, setFormData] = useState({
    current_password: '',
    new_password: '',
    confirm_password: ''
  });
  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [passwordStrength, setPasswordStrength] = useState({
    score: 0,
    label: '',
    color: ''
  });

  // Password strength calculator
  const calculatePasswordStrength = (password) => {
    if (!password) {
      return { score: 0, label: '', color: '' };
    }

    let score = 0;
    const checks = {
      length: password.length >= 8,
      uppercase: /[A-Z]/.test(password),
      lowercase: /[a-z]/.test(password),
      numbers: /[0-9]/.test(password),
      special: /[^A-Za-z0-9]/.test(password)
    };

    score = Object.values(checks).filter(Boolean).length;

    const strengthMap = {
      0: { label: 'Very Weak', color: 'text-red-600' },
      1: { label: 'Very Weak', color: 'text-red-600' },
      2: { label: 'Weak', color: 'text-orange-600' },
      3: { label: 'Fair', color: 'text-yellow-600' },
      4: { label: 'Good', color: 'text-green-600' },
      5: { label: 'Strong', color: 'text-green-700' }
    };

    return { score, ...strengthMap[score] };
  };

  useEffect(() => {
    setPasswordStrength(calculatePasswordStrength(formData.new_password));
  }, [formData.new_password]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
    // Clear error for this field
    setErrors(prev => ({ ...prev, [name]: '' }));
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.current_password) {
      newErrors.current_password = 'Current password is required';
    }

    if (!formData.new_password) {
      newErrors.new_password = 'New password is required';
    } else if (formData.new_password.length < 8) {
      newErrors.new_password = 'Password must be at least 8 characters';
    } else if (formData.new_password === formData.current_password) {
      newErrors.new_password = 'New password must be different from current password';
    }

    if (!formData.confirm_password) {
      newErrors.confirm_password = 'Please confirm your new password';
    } else if (formData.new_password !== formData.confirm_password) {
      newErrors.confirm_password = 'Passwords do not match';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    setLoading(true);

    try {
      // Get token using proper storage key
      const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN) || 
                    localStorage.getItem('access_token') || 
                    localStorage.getItem('access');
      
      console.log('[FirstLoginPasswordReset] Token found:', !!token);
      
      if (!token) {
        setErrors({ submit: 'Authentication token not found. Please login again.' });
        setLoading(false);
        return;
      }

      const response = await axios.post(
        `${API_BASE_URL}/users/reset-first-login-password/`,
        {
          current_password: formData.current_password,
          new_password: formData.new_password,
          confirm_password: formData.confirm_password
        },
        {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        }
      );

      if (response.data.success) {
        // Show inline success state — no browser alert()
        setSuccess(true);
        // Notify the parent so it can close any other password-required
        // popup (e.g. ChangePasswordModal) that may be showing underneath
        if (onSuccess) onSuccess();
        // Clear expiry banner immediately
        passwordExpiryService.clearAndNotify();
        passwordExpiryService.stopPeriodicCheck();

        // Re-fetch the fresh profile and sync Redux so must_change_password
        // reflects the change immediately instead of the stale login-time value
        try {
          const meResponse = await axios.get(`${API_BASE_URL}/rbac/users/me/`, {
            headers: { 'Authorization': `Bearer ${token}` }
          });
          dispatch(updateUser(meResponse.data));
        } catch (refreshError) {
          console.error('Failed to refresh user data after password reset:', refreshError);
        }

        // Log out properly via Redux (clears localStorage + Redux state)
        // then redirect to login for a fresh session
        setTimeout(() => {
          dispatch(logout());
          navigate(POST_CHANGE_REDIRECT);
        }, POST_CHANGE_REDIRECT_DELAY);
      }
    } catch (error) {
      console.error('Error resetting password:', error);
      console.error('Error response:', error.response?.data);
      console.error('Error status:', error.response?.status);
      
      let errorMessage = 'Failed to reset password';
      
      if (error.response) {
        if (error.response.status === 401) {
          errorMessage = 'Authentication failed. Your session may have expired. Please login again.';
        } else if (error.response.status === 400) {
          errorMessage = error.response.data?.error || error.response.data?.message || 'Invalid request. Please check your passwords.';
        } else if (error.response.data?.error) {
          errorMessage = error.response.data.error;
        } else if (error.response.data?.message) {
          errorMessage = error.response.data.message;
        }
      } else if (error.request) {
        errorMessage = 'Cannot connect to server. Please check your connection.';
      }
      
      setErrors({ submit: errorMessage });
    } finally {
      setLoading(false);
    }
  };

  // Success screen — shown after password is changed, before redirect
  if (success) {
    return (
      <div className="fixed inset-0 bg-gray-900 bg-opacity-75 flex items-center justify-center p-4 z-50">
        <div className="bg-white rounded-lg max-w-md w-full p-6 text-center">
          <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-green-100 mb-4">
            <svg className="h-10 w-10 text-green-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-gray-900 mb-2">{SUCCESS_HEADING}</h2>
          <p className="text-gray-600">{SUCCESS_BODY}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 bg-gray-900 bg-opacity-75 flex items-center justify-center p-4 z-50">
      <div className="bg-white rounded-lg max-w-md w-full p-6">
        <div className="mb-6">
          <h2 className="text-2xl font-bold text-gray-900 mb-2">
            Password Reset Required
          </h2>
          <p className="text-gray-600">
            Welcome, {(() => {
              // Extract nested user object (user.user.first_name)
              const userData = user?.user || user;
              return userData?.first_name || userData?.email?.split('@')[0] || 'User';
            })()}! For security reasons, please change your temporary password before continuing.
          </p>
        </div>

        <form onSubmit={handleSubmit} className="space-y-4">
          {/* Current Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Current (Temporary) Password *
            </label>
            <input
              type="password"
              name="current_password"
              value={formData.current_password}
              onChange={handleChange}
              className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 ${
                errors.current_password ? 'border-red-500' : 'border-gray-300'
              }`}
              disabled={loading}
            />
            {errors.current_password && (
              <p className="mt-1 text-sm text-red-600">{errors.current_password}</p>
            )}
          </div>

          {/* New Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              New Password *
            </label>
            <input
              type="password"
              name="new_password"
              value={formData.new_password}
              onChange={handleChange}
              className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 ${
                errors.new_password ? 'border-red-500' : 'border-gray-300'
              }`}
              disabled={loading}
            />
            {formData.new_password && (
              <div className="mt-1 flex items-center gap-2">
                <span className="text-sm">Strength:</span>
                <span className={`text-sm font-medium ${passwordStrength.color}`}>
                  {passwordStrength.label}
                </span>
                <div className="flex-1 h-2 bg-gray-200 rounded-full overflow-hidden">
                  <div
                    className={`h-full transition-all ${
                      passwordStrength.score <= 2 ? 'bg-red-500' :
                      passwordStrength.score === 3 ? 'bg-yellow-500' :
                      'bg-green-500'
                    }`}
                    style={{ width: `${(passwordStrength.score / 5) * 100}%` }}
                  />
                </div>
              </div>
            )}
            {errors.new_password && (
              <p className="mt-1 text-sm text-red-600">{errors.new_password}</p>
            )}
            <p className="mt-1 text-xs text-gray-500">
              Must be at least 8 characters with uppercase, lowercase, numbers, and special characters
            </p>
          </div>

          {/* Confirm Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Confirm New Password *
            </label>
            <input
              type="password"
              name="confirm_password"
              value={formData.confirm_password}
              onChange={handleChange}
              className={`w-full px-3 py-2 border rounded-lg focus:ring-2 focus:ring-indigo-500 ${
                errors.confirm_password ? 'border-red-500' : 'border-gray-300'
              }`}
              disabled={loading}
            />
            {errors.confirm_password && (
              <p className="mt-1 text-sm text-red-600">{errors.confirm_password}</p>
            )}
          </div>

          {/* Submit Error */}
          {errors.submit && (
            <div className="p-3 bg-red-50 border border-red-200 rounded-lg">
              <p className="text-sm text-red-600">{errors.submit}</p>
            </div>
          )}

          {/* Submit Button */}
          <div className="flex gap-3 pt-4">
            <button
              type="submit"
              disabled={loading}
              className="flex-1 bg-indigo-600 text-white px-4 py-2 rounded-lg hover:bg-indigo-700 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
            >
              {loading ? 'Updating...' : 'Update Password'}
            </button>
          </div>
        </form>

        <div className="mt-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
          <p className="text-sm text-blue-800">
            <strong>Note:</strong> You will be logged out after updating your password and will need to login again with your new credentials.
          </p>
        </div>
      </div>
    </div>
  );
};

export default FirstLoginPasswordReset;

import { radaiAlert } from '../services/radaiDialog'
/**
 * CRS PDF Processor Component
 * Add this to your existing CRSDocuments.jsx page
 * 
 * This component provides UI for:
 * 1. Uploading ConsolidatedComments PDF
 * 2. Processing and extracting comments
 * 3. Downloading populated CRS template
 */

import React, { useState } from 'react';
import { API_BASE_URL } from '../config/api.config';

const CRSPDFProcessor = ({ document }) => {
  const [pdfFile, setPdfFile] = useState(null);
  const [processing, setProcessing] = useState(false);
  const [result, setResult] = useState(null);

  const API_URL = API_BASE_URL.replace('/api/v1', '');

  const handleFileSelect = async (e) => {
    const file = e.target.files[0];
    if (file && file.type === 'application/pdf') {
      setPdfFile(file);
      setResult(null);
    } else {
      await radaiAlert('Please select a valid PDF file');
    }
  };

  const processAndDownload = async () => {
    if (!pdfFile) {
      await radaiAlert('Please select a PDF file first');
      return;
    }

    setProcessing(true);
    
    try {
      const formData = new FormData();
      formData.append('pdf_file', pdfFile);
      formData.append('metadata', JSON.stringify({
        project_name: document.project_name || 'N/A',
        document_number: document.document_number || 'N/A',
        revision: document.version || '1.0',
      }));

      const token = localStorage.getItem('token');
      const response = await fetch(
        `${API_URL}/api/v1/crs-documents/${document.id}/process-pdf-comments/`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`
          },
          body: formData
        }
      );

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Processing failed');
      }

      // Get comment count from headers
      const commentCount = response.headers.get('X-Comment-Count') || 'unknown';

      // Download the file
      const blob = await response.blob();
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `CRS_Populated_${document.document_number || 'document'}.xlsx`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      window.URL.revokeObjectURL(url);

      setResult({
        success: true,
        commentCount: commentCount,
        message: `Successfully extracted ${commentCount} comments and populated CRS template`
      });

      // Clear file after success
      setPdfFile(null);
      
    } catch (error) {
      console.error('Error:', error);
      setResult({
        success: false,
        message: error.message
      });
    } finally {
      setProcessing(false);
    }
  };

  const extractCommentsOnly = async () => {
    if (!pdfFile) {
      await radaiAlert('Please select a PDF file first');
      return;
    }

    setProcessing(true);
    
    try {
      const formData = new FormData();
      formData.append('pdf_file', pdfFile);

      const token = localStorage.getItem('token');
      const response = await fetch(
        `${API_URL}/api/v1/crs-documents/${document.id}/extract-comments-only/`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`
          },
          body: formData
        }
      );

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Extraction failed');
      }

      const data = await response.json();
      
      setResult({
        success: true,
        comments: data.comments,
        statistics: data.statistics,
        message: data.message
      });

    } catch (error) {
      console.error('Error:', error);
      setResult({
        success: false,
        message: error.message
      });
    } finally {
      setProcessing(false);
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-lg p-6 border border-gray-200">
      {/* Header */}
      <div className="flex items-center gap-3 mb-6">
        <div className="w-12 h-12 bg-gradient-to-br from-purple-500 to-indigo-600 rounded-xl flex items-center justify-center">
          <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
        </div>
        <div>
          <h3 className="text-xl font-bold text-gray-900">
            📋 CRS Document Intelligence
          </h3>
          <p className="text-sm text-gray-600">
            Extract comments from PDF and populate CRS template
          </p>
        </div>
      </div>

      {/* File Upload */}
      <div className="mb-6">
        <label className="block text-sm font-semibold text-gray-700 mb-2">
          Upload ConsolidatedComments PDF
        </label>
        <div className="relative">
          <input
            type="file"
            accept=".pdf"
            onChange={handleFileSelect}
            className="block w-full text-sm text-gray-500
              file:mr-4 file:py-3 file:px-6
              file:rounded-xl file:border-0
              file:text-sm file:font-semibold
              file:bg-blue-50 file:text-blue-700
              hover:file:bg-blue-100
              transition-all cursor-pointer"
          />
        </div>
        {pdfFile && (
          <p className="mt-2 text-sm text-green-600 flex items-center gap-2">
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
            Selected: {pdfFile.name}
          </p>
        )}
      </div>

      {/* Action Buttons */}
      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-6">
        <button
          onClick={processAndDownload}
          disabled={!pdfFile || processing}
          className={`px-6 py-4 rounded-xl font-semibold transition-all flex items-center justify-center gap-2 ${
            !pdfFile || processing
              ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
              : 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white hover:shadow-lg hover:scale-105'
          }`}
        >
          {processing ? (
            <>
              <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
              Processing...
            </>
          ) : (
            <>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
              </svg>
              Process & Download CRS
            </>
          )}
        </button>

        <button
          onClick={extractCommentsOnly}
          disabled={!pdfFile || processing}
          className={`px-6 py-4 rounded-xl font-semibold transition-all flex items-center justify-center gap-2 ${
            !pdfFile || processing
              ? 'bg-gray-100 text-gray-400 cursor-not-allowed'
              : 'bg-white text-gray-700 border-2 border-gray-300 hover:border-blue-500 hover:shadow-md'
          }`}
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
          </svg>
          Preview Comments Only
        </button>
      </div>

      {/* Results */}
      {result && (
        <div className={`p-4 rounded-xl border-2 ${
          result.success 
            ? 'bg-green-50 border-green-200' 
            : 'bg-red-50 border-red-200'
        }`}>
          <div className="flex items-start gap-3">
            <div className={`w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 ${
              result.success ? 'bg-green-500' : 'bg-red-500'
            }`}>
              {result.success ? (
                <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                </svg>
              ) : (
                <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              )}
            </div>
            <div className="flex-1">
              <p className={`font-semibold ${result.success ? 'text-green-900' : 'text-red-900'}`}>
                {result.success ? '✅ Success!' : '❌ Error'}
              </p>
              <p className={`text-sm mt-1 ${result.success ? 'text-green-700' : 'text-red-700'}`}>
                {result.message}
              </p>
              
              {result.statistics && (
                <div className="mt-3 grid grid-cols-2 gap-2">
                  <div className="bg-white rounded-lg p-2">
                    <div className="text-xs text-gray-600">Total Comments</div>
                    <div className="text-lg font-bold text-gray-900">{result.statistics.total}</div>
                  </div>
                  <div className="bg-white rounded-lg p-2">
                    <div className="text-xs text-gray-600">Pages</div>
                    <div className="text-lg font-bold text-gray-900">{result.statistics.pages_with_comments}</div>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}

      {/* Info */}
      <div className="mt-6 p-4 bg-blue-50 rounded-xl border border-blue-200">
        <div className="flex items-start gap-3">
          <svg className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <div className="text-sm text-blue-900">
            <p className="font-semibold mb-1">How it works:</p>
            <ul className="list-disc list-inside space-y-1 text-blue-800">
              <li>Upload your ConsolidatedComments PDF</li>
              <li>System extracts reviewer comments automatically</li>
              <li>CRS template is populated with extracted data</li>
              <li>Download ready-to-use Excel file (format preserved)</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );
};

