              onClick={() => setLiveMode(!liveMode)}
              className={`px-5 py-2.5 rounded-lg font-medium transition-all shadow-sm ${
                liveMode
                  ? 'bg-green-500 text-white hover:bg-green-600'
                  : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
              }`}
            >
