                            <p className="text-sm font-medium text-gray-900 mb-1">
                              {issue.message}
                            </p>
                            <div className="text-xs text-gray-600 space-y-1">
                              {issue.sheet_name && (
                                <div>Sheet: <span className="font-medium">{issue.sheet_name}</span></div>
