import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  MagnifyingGlassIcon,
  FunnelIcon,
  DocumentTextIcon,
  CheckCircleIcon,
  ExclamationCircleIcon,
  ClockIcon,
  ChartBarIcon
} from '@heroicons/react/24/outline';
import apiClient from '../../../services/api.service';

/**
 * Excel Documents Dashboard
 * Lists all uploaded documents with filters and status
 */
const ExcelDocumentsDashboard = () => {
  const navigate = useNavigate();
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterEquipmentType, setFilterEquipmentType] = useState('');
  const [filterStatus, setFilterStatus] = useState('');
  const [sortBy, setSortBy] = useState('uploaded_at');
  const [sortOrder, setSortOrder] = useState('desc');

  useEffect(() => {
    fetchDocuments();
  }, [filterEquipmentType, filterStatus, sortBy, sortOrder]);

  const fetchDocuments = async () => {
    try {
      setLoading(true);
      
      const params = new URLSearchParams();
      if (filterEquipmentType) params.append('equipment_type', filterEquipmentType);
      if (filterStatus) params.append('status', filterStatus);
      if (searchTerm) params.append('search', searchTerm);
      
      const ordering = sortOrder === 'desc' ? `-${sortBy}` : sortBy;
      params.append('ordering', ordering);

      const response = await apiClient.get(
        `/electrical-datasheet/excel/excel-documents/?${params.toString()}`
      );
      
      setDocuments(response.data.results || response.data);
      setError(null);
    } catch (err) {
      console.error('Error fetching documents:', err);
      setError('Failed to load documents');
    } finally {
      setLoading(false);
    }
  };

  const handleSearch = () => {
    fetchDocuments();
  };

  const handleDocumentClick = (documentId) => {
    navigate(`/engineering/electrical/datasheet/quality-checker/${documentId}`);
  };

  const getStatusBadge = (status) => {
    const statusConfig = {
      pending: { color: 'gray', icon: ClockIcon, text: 'Pending' },
      processing: { color: 'blue', icon: ClockIcon, text: 'Processing' },
      validated: { color: 'green', icon: CheckCircleIcon, text: 'Validated' },
      failed: { color: 'red', icon: ExclamationCircleIcon, text: 'Failed' },
      error: { color: 'red', icon: ExclamationCircleIcon, text: 'Error' },
    };

    const config = statusConfig[status] || statusConfig.pending;
    const Icon = config.icon;

    return (
      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-${config.color}-100 text-${config.color}-800`}>
        <Icon className="h-3 w-3 mr-1" />
        {config.text}
      </span>
    );
  };

  const getScoreColor = (score) => {
    if (score >= 90) return 'text-green-600';
    if (score >= 70) return 'text-yellow-600';
    return 'text-red-600';
  };

  return (
    <div className="max-w-7xl mx-auto p-6">
      {/* Header */}
      <div className="mb-6">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">
          Excel Quality Checker Dashboard
        </h1>
        <p className="text-gray-600">
          View and manage uploaded electrical datasheets
        </p>
      </div>

      {/* Controls */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-6">
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {/* Search */}
          <div className="md:col-span-2">
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Search
            </label>
            <div className="relative">
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
                placeholder="Search by filename, document number..."
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-md focus:ring-yellow-500 focus:border-yellow-500"
              />
              <MagnifyingGlassIcon className="absolute left-3 top-2.5 h-5 w-5 text-gray-400" />
            </div>
          </div>

          {/* Equipment Type Filter */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Equipment Type
            </label>
            <select
              value={filterEquipmentType}
              onChange={(e) => setFilterEquipmentType(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-yellow-500 focus:border-yellow-500"
            >
              <option value="">All Types</option>
              <option value="ups">UPS</option>
              <option value="vfd">VFD</option>
              <option value="power_cable">Power Cable</option>
              <option value="control_cable">Control Cable</option>
              <option value="earthing_cable">Earthing Cable</option>
              <option value="ner">NER</option>
              <option value="transformer">Transformer</option>
              <option value="motor">Motor</option>
            </select>
          </div>

          {/* Status Filter */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-1">
              Status
            </label>
            <select
              value={filterStatus}
              onChange={(e) => setFilterStatus(e.target.value)}
              className="w-full px-3 py-2 border border-gray-300 rounded-md focus:ring-yellow-500 focus:border-yellow-500"
            >
              <option value="">All Status</option>
              <option value="pending">Pending</option>
              <option value="processing">Processing</option>
              <option value="validated">Validated</option>
              <option value="failed">Failed</option>
              <option value="error">Error</option>
            </select>
          </div>
        </div>

        {/* Sort */}
        <div className="flex items-center space-x-4 mt-4">
          <FunnelIcon className="h-5 w-5 text-gray-400" />
          <span className="text-sm text-gray-600">Sort by:</span>
          <select
            value={sortBy}
            onChange={(e) => setSortBy(e.target.value)}
            className="px-3 py-1 border border-gray-300 rounded-md text-sm focus:ring-yellow-500 focus:border-yellow-500"
          >
            <option value="uploaded_at">Upload Date</option>
            <option value="validation_score">Validation Score</option>
            <option value="error_count">Error Count</option>
          </select>
          <button
            onClick={() => setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc')}
            className="text-sm text-gray-600 hover:text-gray-900"
          >
            {sortOrder === 'asc' ? '↑ Ascending' : '↓ Descending'}
          </button>
        </div>
      </div>

      {/* Documents Table */}
      <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
        {loading ? (
          <div className="p-12 text-center">
            <div className="inline-block animate-spin rounded-full h-8 w-8 border-b-2 border-yellow-600"></div>
            <p className="mt-2 text-sm text-gray-600">Loading documents...</p>
          </div>
        ) : error ? (
          <div className="p-12 text-center">
            <ExclamationCircleIcon className="mx-auto h-12 w-12 text-red-500 mb-4" />
            <p className="text-red-600">{error}</p>
            <button
              onClick={fetchDocuments}
              className="mt-4 px-4 py-2 bg-yellow-600 text-white rounded-md hover:bg-yellow-700"
            >
              Retry
            </button>
          </div>
        ) : documents.length === 0 ? (
          <div className="p-12 text-center">
            <DocumentTextIcon className="mx-auto h-12 w-12 text-gray-400 mb-4" />
            <p className="text-gray-600">No documents found</p>
            <button
              onClick={() => navigate('/engineering/electrical/datasheet/quality-checker/upload')}
              className="mt-4 px-4 py-2 bg-yellow-600 text-white rounded-md hover:bg-yellow-700"
            >
              Upload First Document
            </button>
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full divide-y divide-gray-200">
              <thead className="bg-gray-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Document
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Equipment Type
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Revision
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Status
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Score
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Issues
                  </th>
                  <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                    Uploaded
                  </th>
                </tr>
              </thead>
              <tbody className="bg-white divide-y divide-gray-200">
                {documents.map((doc) => (
                  <tr
                    key={doc.id}
                    onClick={() => handleDocumentClick(doc.id)}
                    className="hover:bg-gray-50 cursor-pointer transition-colors"
                  >
                    <td className="px-6 py-4">
                      <div className="flex items-center">
                        <DocumentTextIcon className="h-5 w-5 text-gray-400 mr-3" />
                        <div>
                          <div className="text-sm font-medium text-gray-900">
                            {doc.filename}
                          </div>
                          {doc.company_doc_number && (
                            <div className="text-xs text-gray-500">
                              {doc.company_doc_number}
                            </div>
                          )}
                        </div>
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm text-gray-900">
                        {doc.equipment_type_display}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className="text-sm text-gray-900">
                        {doc.revision || '-'}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {getStatusBadge(doc.status)}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      {doc.validation_score !== null ? (
                        <div className="flex items-center">
                          <ChartBarIcon className="h-4 w-4 mr-1 text-gray-400" />
                          <span className={`text-sm font-semibold ${getScoreColor(doc.validation_score)}`}>
                            {doc.validation_score}%
                          </span>
                        </div>
                      ) : (
                        <span className="text-sm text-gray-400">-</span>
                      )}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <div className="flex items-center space-x-4 text-sm">
                        {doc.error_count > 0 && (
                          <span className="text-red-600 font-medium">
                            {doc.error_count} errors
                          </span>
                        )}
                        {doc.warning_count > 0 && (
                          <span className="text-yellow-600 font-medium">
                            {doc.warning_count} warnings
                          </span>
                        )}
                        {doc.error_count === 0 && doc.warning_count === 0 && (
                          <span className="text-gray-400">No issues</span>
                        )}
                      </div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                      <div>
                        {new Date(doc.uploaded_at).toLocaleDateString()}
                      </div>
                      <div className="text-xs">
                        {doc.uploaded_by_name || 'Unknown'}
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Upload Button */}
      <div className="mt-6 flex justify-center">
        <button
          onClick={() => navigate('/engineering/electrical/datasheet/quality-checker/upload')}
          className="px-6 py-3 bg-yellow-600 text-white rounded-md hover:bg-yellow-700 font-medium transition-colors"
        >
          + Upload New Document
        </button>
      </div>
    </div>
  );
};

export default ExcelDocumentsDashboard;

import React, { useState } from 'react';
import {
  CloudArrowUpIcon,
  DocumentIcon,
  XMarkIcon,
  CheckCircleIcon,
  ExclamationCircleIcon,
  ArrowDownTrayIcon
} from '@heroicons/react/24/outline';

const FileUploadSection = ({ 
  onFileUpload, 
  existingFiles = [], 
  onFileRemove,
  onFileDownload,
  acceptedTypes = '.pdf,.xlsx,.xls',
  maxSize = 10 * 1024 * 1024, // 10MB
  showADNOCValidation = true
}) => {
  const [dragActive, setDragActive] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadError, setUploadError] = useState(null);

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(true);
    } else if (e.type === 'dragleave') {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);

    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e) => {
    e.preventDefault();
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  const validateFile = (file) => {
    // Check file size
    if (file.size > maxSize) {
      return `File size exceeds ${(maxSize / 1024 / 1024).toFixed(0)}MB limit`;
    }

    // Check file type
    const fileExtension = '.' + file.name.split('.').pop().toLowerCase();
    const acceptedTypesArray = acceptedTypes.split(',').map(t => t.trim());
    
    if (!acceptedTypesArray.includes(fileExtension)) {
      return `File type ${fileExtension} not supported. Accepted types: ${acceptedTypes}`;
    }

    return null;
  };

  const handleFile = async (file) => {
    setUploadError(null);

    // Validate file
    const validationError = validateFile(file);
    if (validationError) {
      setUploadError(validationError);
      return;
    }

    setUploading(true);
    setUploadProgress(0);

    try {
      // Simulate progress for better UX
      const progressInterval = setInterval(() => {
        setUploadProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 10;
        });
      }, 200);

      await onFileUpload(file);
      
      clearInterval(progressInterval);
      setUploadProgress(100);
      
      // Reset after success
      setTimeout(() => {
        setUploading(false);
        setUploadProgress(0);
      }, 1500);
    } catch (error) {
      setUploadError(error.message || 'Upload failed');
      setUploading(false);
      setUploadProgress(0);
    }
  };

  const getFileIcon = (fileName) => {
    const ext = fileName.split('.').pop().toLowerCase();
    if (ext === 'pdf') {
      return '📄';
    } else if (ext === 'xlsx' || ext === 'xls') {
      return '📊';
    }
    return '📎';
  };

  const formatFileSize = (bytes) => {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
  };

  return (
    <div className="space-y-4">
      {/* Upload Area */}
      <div
        className={`
          relative border-2 border-dashed rounded-lg p-6 transition-all
          ${dragActive ? 'border-purple-500 bg-purple-50' : 'border-gray-300 hover:border-purple-400'}
          ${uploading ? 'pointer-events-none opacity-50' : ''}
        `}
        onDragEnter={handleDrag}
        onDragLeave={handleDrag}
        onDragOver={handleDrag}
        onDrop={handleDrop}
      >
        <input
          type="file"
          id="file-upload"
          className="hidden"
          accept={acceptedTypes}
          onChange={handleChange}
          disabled={uploading}
        />

        <label
          htmlFor="file-upload"
          className="flex flex-col items-center justify-center cursor-pointer"
        >
          <CloudArrowUpIcon className="w-12 h-12 text-purple-500 mb-3" />
          
          <p className="text-sm font-medium text-gray-700 mb-1">
            Click to upload or drag and drop
          </p>
          
          <p className="text-xs text-gray-500">
            {acceptedTypes.split(',').join(', ').toUpperCase()} up to {(maxSize / 1024 / 1024).toFixed(0)}MB
          </p>

          {showADNOCValidation && (
            <div className="mt-3 px-3 py-1.5 bg-purple-100 rounded-full">
              <p className="text-xs font-medium text-purple-700">
                ✨ Automatic ADNOC Standards Validation
              </p>
            </div>
          )}
        </label>

        {/* Upload Progress */}
        {uploading && (
          <div className="mt-4">
            <div className="flex justify-between text-sm text-gray-600 mb-2">
              <span>Uploading...</span>
              <span>{uploadProgress}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div
                className="bg-purple-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${uploadProgress}%` }}
              />
            </div>
          </div>
        )}
      </div>

      {/* Upload Error */}
      {uploadError && (
        <div className="flex items-start space-x-2 p-3 bg-red-50 border border-red-200 rounded-lg">
          <ExclamationCircleIcon className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
          <div className="flex-1">
            <p className="text-sm font-medium text-red-800">Upload Error</p>
            <p className="text-xs text-red-600 mt-1">{uploadError}</p>
          </div>
          <button
            onClick={() => setUploadError(null)}
            className="text-red-400 hover:text-red-600"
          >
            <XMarkIcon className="w-5 h-5" />
          </button>
        </div>
      )}

      {/* Existing Files List */}
      {existingFiles.length > 0 && (
        <div className="space-y-2">
          <h4 className="text-sm font-medium text-gray-700 mb-2">
            Attached Files ({existingFiles.length})
          </h4>
          
          {existingFiles.map((file, index) => (
            <div
              key={index}
              className="flex items-center justify-between p-3 bg-gray-50 rounded-lg border border-gray-200 hover:border-purple-300 transition-colors"
            >
              <div className="flex items-center space-x-3 flex-1 min-w-0">
                <span className="text-2xl flex-shrink-0">
                  {getFileIcon(file.file_name)}
                </span>
                
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-medium text-gray-900 truncate">
                    {file.file_name}
                  </p>
                  
                  <div className="flex items-center space-x-3 mt-1">
                    {file.file_type && (
                      <span className="text-xs text-gray-500 capitalize">
                        {file.file_type.replace('_', ' ')}
                      </span>
                    )}
                    
                    {file.file_size && (
                      <span className="text-xs text-gray-500">
                        {formatFileSize(file.file_size)}
                      </span>
                    )}
                    
                    {file.uploaded_at && (
                      <span className="text-xs text-gray-500">
                        {new Date(file.uploaded_at).toLocaleDateString()}
                      </span>
                    )}
                  </div>
                </div>

                {file.validation_status && (
                  <div className="flex-shrink-0">
                    {file.validation_status === 'passed' ? (
                      <div className="flex items-center space-x-1 text-green-600">
                        <CheckCircleIcon className="w-4 h-4" />
                        <span className="text-xs font-medium">Validated</span>
                      </div>
                    ) : file.validation_status === 'failed' ? (
                      <div className="flex items-center space-x-1 text-red-600">
                        <ExclamationCircleIcon className="w-4 h-4" />
                        <span className="text-xs font-medium">Issues Found</span>
                      </div>
                    ) : (
                      <span className="text-xs text-yellow-600 font-medium">Pending</span>
                    )}
                  </div>
                )}
              </div>

              <div className="flex items-center space-x-2 ml-4">
                {onFileDownload && (
                  <button
                    onClick={() => onFileDownload(file, index)}
                    className="p-1.5 text-gray-400 hover:text-purple-600 hover:bg-purple-50 rounded transition-colors"
                    title="Download file"
                  >
                    <ArrowDownTrayIcon className="w-4 h-4" />
                  </button>
                )}
                
                {onFileRemove && (
                  <button
                    onClick={() => onFileRemove(file, index)}
                    className="p-1.5 text-gray-400 hover:text-red-600 hover:bg-red-50 rounded transition-colors"
                    title="Remove file"
                  >
                    <XMarkIcon className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Info Banner */}
      {showADNOCValidation && existingFiles.length === 0 && (
        <div className="bg-purple-50 border border-purple-200 rounded-lg p-4">
          <div className="flex items-start space-x-3">
            <DocumentIcon className="w-5 h-5 text-purple-600 flex-shrink-0 mt-0.5" />
            <div className="flex-1">
              <h4 className="text-sm font-medium text-purple-900 mb-1">
                ADNOC Standards Validation
              </h4>
              <p className="text-xs text-purple-700 leading-relaxed">
                Uploaded datasheets will be automatically validated against ADNOC engineering standards 
                including IEC 60076 (transformers) and IEC 62271 (switchgear). The system will check 
                voltage ratings, power ratings, impedance, cooling types, and other critical parameters.
              </p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default FileUploadSection;

import React, { useState } from 'react';
import apiClient from '../../services/api.service';
import {
  CheckCircleIcon,
  XCircleIcon,
  ExclamationTriangleIcon,
  SparklesIcon,
  DocumentCheckIcon,
  ChartBarIcon,
  LightBulbIcon,
  ArrowPathIcon,
  DocumentArrowDownIcon
} from '@heroicons/react/24/outline';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000';

const QualityCheckerReport = ({ datasheetId, onClose }) => {
  const [loading, setLoading] = useState(false);
  const [report, setReport] = useState(null);
  const [error, setError] = useState(null);

  const runQualityCheck = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const response = await apiClient.post(`/electrical-datasheet/datasheets/${datasheetId}/quality_check/`, {});
      
      setReport(response.data);
    } catch (err) {
      console.error('Error running quality check:', err);
      setError('Failed to run quality check. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'passed':
        return 'bg-green-100 text-green-800 border-green-300';
      case 'warning':
        return 'bg-yellow-100 text-yellow-800 border-yellow-300';
      case 'failed':
        return 'bg-red-100 text-red-800 border-red-300';
      default:
        return 'bg-gray-100 text-gray-800 border-gray-300';
    }
  };

  const getStatusIcon = (status) => {
    switch (status) {
      case 'passed':
        return <CheckCircleIcon className="w-8 h-8 text-green-600" />;
      case 'warning':
        return <ExclamationTriangleIcon className="w-8 h-8 text-yellow-600" />;
      case 'failed':
        return <XCircleIcon className="w-8 h-8 text-red-600" />;
      default:
        return <DocumentCheckIcon className="w-8 h-8 text-gray-600" />;
    }
  };

  const getSeverityBadge = (severity) => {
    const config = {
      high: 'bg-red-100 text-red-800',
      medium: 'bg-yellow-100 text-yellow-800',
      low: 'bg-blue-100 text-blue-800'
    };
    return config[severity] || 'bg-gray-100 text-gray-800';
  };

  const getPriorityBadge = (priority) => {
    const config = {
      high: 'bg-red-500 text-white',
      medium: 'bg-yellow-500 text-white',
      low: 'bg-blue-500 text-white'
    };
    return config[priority] || 'bg-gray-500 text-white';
  };

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
      <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
        <div className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity" onClick={onClose}></div>

        <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>

        <div className="inline-block align-bottom bg-white rounded-lg text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-6xl sm:w-full">
          {/* Header */}
          <div className="bg-gradient-to-r from-indigo-600 to-purple-600 px-6 py-4">
            <div className="flex items-center justify-between">
              <div className="flex items-center">
                <SparklesIcon className="w-8 h-8 text-white mr-3" />
                <div>
                  <h3 className="text-lg leading-6 font-bold text-white">
                    AI-Powered Quality Checker
                  </h3>
                  <p className="mt-1 text-sm text-indigo-100">
                    Comprehensive Consistency Report & Intelligent Analysis
                  </p>
                </div>
              </div>
              <button
                onClick={onClose}
                className="text-white hover:text-gray-200 transition-colors"
              >
                <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </div>
          </div>

          {/* Content */}
          <div className="px-6 py-4 max-h-[80vh] overflow-y-auto">
            {!report && !loading && (
              <div className="text-center py-12">
                <DocumentCheckIcon className="w-20 h-20 text-gray-400 mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">Ready to Run Quality Check</h3>
                <p className="text-sm text-gray-500 mb-6">
                  Our AI will analyze your datasheet for completeness, consistency, standards compliance, and provide intelligent recommendations.
                </p>
                <button
                  onClick={runQualityCheck}
                  className="inline-flex items-center px-6 py-3 border border-transparent text-base font-medium rounded-md shadow-sm text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                >
                  <SparklesIcon className="w-5 h-5 mr-2" />
                  Run Quality Check
                </button>
              </div>
            )}

            {loading && (
              <div className="text-center py-12">
                <ArrowPathIcon className="w-12 h-12 text-indigo-600 animate-spin mx-auto mb-4" />
                <h3 className="text-lg font-medium text-gray-900 mb-2">Analyzing Datasheet...</h3>
                <p className="text-sm text-gray-500">
                  Running comprehensive checks and generating AI-powered insights
                </p>
              </div>
            )}

            {error && (
              <div className="bg-red-50 border border-red-200 rounded-md p-4 mb-4">
                <div className="flex">
                  <XCircleIcon className="w-5 h-5 text-red-400" />
                  <div className="ml-3">
                    <h3 className="text-sm font-medium text-red-800">Error</h3>
                    <p className="mt-2 text-sm text-red-700">{error}</p>
                  </div>
                </div>
              </div>
            )}

            {report && (
              <div className="space-y-6">
                {/* Overall Score Card */}
                <div className={`border-2 rounded-lg p-6 ${getStatusColor(report.status)}`}>
                  <div className="flex items-center justify-between">
                    <div className="flex items-center">
                      {getStatusIcon(report.status)}
                      <div className="ml-4">
                        <h4 className="text-xl font-bold">{report.summary.status_text}</h4>
                        <p className="text-sm mt-1">Tag: {report.tag_number} | Type: {report.equipment_type}</p>
                      </div>
                    </div>
                    <div className="text-center">
                      <div className="text-4xl font-bold">{report.overall_score}</div>
                      <div className="text-sm">out of 100</div>
                    </div>
                  </div>
                </div>

                {/* Quick Stats */}
                <div className="grid grid-cols-1 gap-5 sm:grid-cols-4">
                  <div className="bg-blue-50 overflow-hidden rounded-lg px-4 py-5">
                    <div className="text-sm font-medium text-blue-600 truncate">Completeness</div>
                    <div className="mt-1 text-3xl font-semibold text-blue-900">
                      {report.checks.completeness.completion_percentage}%
                    </div>
                  </div>
                  <div className="bg-green-50 overflow-hidden rounded-lg px-4 py-5">
                    <div className="text-sm font-medium text-green-600 truncate">Consistency</div>
                    <div className="mt-1 text-3xl font-semibold text-green-900">
                      {report.checks.consistency.consistency_score || 100}%
                    </div>
                  </div>
                  <div className="bg-red-50 overflow-hidden rounded-lg px-4 py-5">
                    <div className="text-sm font-medium text-red-600 truncate">Critical Issues</div>
                    <div className="mt-1 text-3xl font-semibold text-red-900">
                      {report.issues.length}
                    </div>
                  </div>
                  <div className="bg-yellow-50 overflow-hidden rounded-lg px-4 py-5">
                    <div className="text-sm font-medium text-yellow-600 truncate">Warnings</div>
                    <div className="mt-1 text-3xl font-semibold text-yellow-900">
                      {report.warnings.length}
                    </div>
                  </div>
                </div>

                {/* Summary Section */}
                <div className="bg-white border border-gray-200 rounded-lg p-6">
                  <h4 className="text-lg font-semibold text-gray-900 mb-4 flex items-center">
                    <ChartBarIcon className="w-5 h-5 mr-2 text-indigo-600" />
                    Executive Summary
                  </h4>
                  
                  {report.summary.key_findings.length > 0 && (
                    <div className="mb-4">
                      <h5 className="font-medium text-gray-700 mb-2">Key Findings:</h5>
                      <ul className="list-disc list-inside space-y-1">
                        {report.summary.key_findings.map((finding, idx) => (
                          <li key={idx} className="text-sm text-gray-600">{finding}</li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {report.summary.strengths.length > 0 && (
                    <div className="mb-4">
                      <h5 className="font-medium text-green-700 mb-2">Strengths:</h5>
                      <ul className="list-disc list-inside space-y-1">
                        {report.summary.strengths.map((strength, idx) => (
                          <li key={idx} className="text-sm text-green-600">{strength}</li>
                        ))}
                      </ul>
                    </div>
                  )}

                  {report.summary.action_required.length > 0 && (
                    <div>
                      <h5 className="font-medium text-red-700 mb-2">Action Required:</h5>
                      <ul className="list-disc list-inside space-y-1">
                        {report.summary.action_required.map((action, idx) => (
                          <li key={idx} className="text-sm text-red-600">{action}</li>
                        ))}
                      </ul>
                    </div>
                  )}
                </div>

                {/* Issues Section */}
                {report.issues.length > 0 && (
                  <div className="bg-red-50 border border-red-200 rounded-lg p-6">
                    <h4 className="text-lg font-semibold text-red-900 mb-4 flex items-center">
                      <XCircleIcon className="w-5 h-5 mr-2" />
                      Critical Issues ({report.issues.length})
                    </h4>
                    <div className="space-y-3">
                      {report.issues.map((issue, idx) => (
                        <div key={idx} className="bg-white rounded-md p-4 border border-red-200">
                          <div className="flex items-start">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getSeverityBadge(issue.severity)} mr-3`}>
                              {issue.severity}
                            </span>
                            <div className="flex-1">
                              <p className="text-sm font-medium text-gray-900">{issue.category}</p>
                              <p className="text-sm text-gray-600 mt-1">{issue.message}</p>
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Warnings Section */}
                {report.warnings.length > 0 && (
                  <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-6">
                    <h4 className="text-lg font-semibold text-yellow-900 mb-4 flex items-center">
                      <ExclamationTriangleIcon className="w-5 h-5 mr-2" />
                      Warnings ({report.warnings.length})
                    </h4>
                    <div className="space-y-3">
                      {report.warnings.slice(0, 5).map((warning, idx) => (
                        <div key={idx} className="bg-white rounded-md p-4 border border-yellow-200">
                          <div className="flex items-start">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getSeverityBadge(warning.severity)} mr-3`}>
                              {warning.severity}
                            </span>
                            <div className="flex-1">
                              <p className="text-sm font-medium text-gray-900">{warning.check || warning.category}</p>
                              <p className="text-sm text-gray-600 mt-1">{warning.message}</p>
                              {warning.details && (
                                <p className="text-xs text-gray-500 mt-1">{warning.details}</p>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                      {report.warnings.length > 5 && (
                        <p className="text-sm text-gray-500 text-center">
                          ... and {report.warnings.length - 5} more warnings
                        </p>
                      )}
                    </div>
                  </div>
                )}

                {/* ADNOC Standards Validation Results */}
                {report.checks?.standards_compliance?.adnoc_validation && (
                  <div className="bg-gradient-to-r from-purple-50 to-pink-50 border border-purple-300 rounded-lg p-6 mt-6">
                    <h4 className="text-lg font-semibold text-purple-900 mb-4 flex items-center">
                      <DocumentCheckIcon className="w-5 h-5 mr-2" />
                      ADNOC Standards Validation
                    </h4>
                    
                    {(() => {
                      const adnocValidation = report.checks.standards_compliance.adnoc_validation;
                      
                      if (adnocValidation.status === 'skipped') {
                        return (
                          <div className="text-sm text-gray-600">
                            {adnocValidation.message}
                          </div>
                        );
                      }
                      
                      return (
                        <div className="space-y-4">
                          {/* Compliance Summary */}
                          <div className="grid grid-cols-4 gap-4">
                            <div className="bg-white rounded-lg p-4 border border-purple-200">
                              <div className="text-2xl font-bold text-purple-600">
                                {adnocValidation.voltage_class?.toUpperCase() || 'N/A'}
                              </div>
                              <div className="text-xs text-gray-600 mt-1">Voltage Class</div>
                            </div>
                            
                            <div className="bg-white rounded-lg p-4 border border-purple-200">
                              <div className="text-2xl font-bold text-purple-600">
                                {adnocValidation.compliance_percentage || 0}%
                              </div>
                              <div className="text-xs text-gray-600 mt-1">Compliance</div>
                            </div>
                            
                            <div className="bg-white rounded-lg p-4 border border-green-200">
                              <div className="text-2xl font-bold text-green-600">
                                {adnocValidation.checks_passed || 0}
                              </div>
                              <div className="text-xs text-gray-600 mt-1">Checks Passed</div>
                            </div>
                            
                            <div className="bg-white rounded-lg p-4 border border-red-200">
                              <div className="text-2xl font-bold text-red-600">
                                {adnocValidation.checks_failed || 0}
                              </div>
                              <div className="text-xs text-gray-600 mt-1">Checks Failed</div>
                            </div>
                          </div>
                          
                          {/* Standard Source */}
                          {adnocValidation.standard_source && (
                            <div className="bg-white rounded-lg p-3 border border-purple-200">
                              <p className="text-xs text-gray-600">
                                <strong>Reference Standard:</strong> {adnocValidation.standard_source}
                              </p>
                            </div>
                          )}
                          
                          {/* Detailed Validation Results */}
                          {adnocValidation.details && adnocValidation.details.length > 0 && (
                            <div className="mt-4">
                              <h5 className="text-sm font-semibold text-gray-900 mb-3">
                                Detailed Validation Results
                              </h5>
                              <div className="space-y-2">
                                {adnocValidation.details.map((detail, idx) => (
                                  <div
                                    key={idx}
                                    className={`
                                      rounded-lg p-3 border flex items-start
                                      ${detail.status === 'passed' 
                                        ? 'bg-green-50 border-green-300' 
                                        : detail.status === 'failed'
                                        ? 'bg-red-50 border-red-300'
                                        : 'bg-gray-50 border-gray-300'
                                      }
                                    `}
                                  >
                                    <div className="flex-shrink-0 mt-0.5 mr-3">
                                      {detail.status === 'passed' ? (
                                        <CheckCircleIcon className="w-5 h-5 text-green-600" />
                                      ) : detail.status === 'failed' ? (
                                        <XCircleIcon className="w-5 h-5 text-red-600" />
                                      ) : (
                                        <ExclamationTriangleIcon className="w-5 h-5 text-yellow-600" />
                                      )}
                                    </div>
                                    
                                    <div className="flex-1 min-w-0">
                                      <div className="flex items-center justify-between">
                                        <p className="text-sm font-medium text-gray-900">
                                          {detail.check}
                                        </p>
                                        <span className={`
                                          ml-2 inline-flex items-center px-2 py-0.5 rounded text-xs font-medium
                                          ${detail.status === 'passed' ? 'bg-green-100 text-green-800' : ''}
                                          ${detail.status === 'failed' ? 'bg-red-100 text-red-800' : ''}
                                          ${detail.status === 'skipped' ? 'bg-gray-100 text-gray-800' : ''}
                                          ${detail.status === 'error' ? 'bg-yellow-100 text-yellow-800' : ''}
                                        `}>
                                          {detail.status}
                                        </span>
                                      </div>
                                      
                                      {detail.value && (
                                        <p className="text-xs text-gray-700 mt-1">
                                          <strong>Actual Value:</strong> {detail.value}
                                        </p>
                                      )}
                                      
                                      {detail.standard_range && (
                                        <p className="text-xs text-gray-700 mt-0.5">
                                          <strong>ADNOC Standard:</strong> {detail.standard_range}
                                        </p>
                                      )}
                                      
                                      {detail.standard && (
                                        <p className="text-xs text-gray-700 mt-0.5">
                                          <strong>Standard:</strong> {detail.standard}
                                        </p>
                                      )}
                                      
                                      {detail.standard_options && (
                                        <p className="text-xs text-gray-700 mt-0.5">
                                          <strong>Approved Options:</strong> {Array.isArray(detail.standard_options) ? detail.standard_options.join(', ') : detail.standard_options}
                                        </p>
                                      )}
                                      
                                      {detail.message && (
                                        <p className="text-xs text-gray-600 mt-1 italic">
                                          {detail.message}
                                        </p>
                                      )}
                                    </div>
                                  </div>
                                ))}
                              </div>
                            </div>
                          )}
                          
                          {/* Overall Status Badge */}
                          <div className="mt-4 pt-4 border-t border-purple-200">
                            <div className="flex items-center justify-center">
                              <span className={`
                                px-4 py-2 rounded-full text-sm font-semibold
                                ${adnocValidation.status === 'passed' 
                                  ? 'bg-green-100 text-green-800 border-2 border-green-300' 
                                  : 'bg-red-100 text-red-800 border-2 border-red-300'
                                }
                              `}>
                                {adnocValidation.status === 'passed' 
                                  ? '✓ ADNOC Standards: COMPLIANT' 
                                  : '✗ ADNOC Standards: NON-COMPLIANT'}
                              </span>
                            </div>
                          </div>
                        </div>
                      );
                    })()}
                  </div>
                )}

                {/* AI Insights & Recommendations */}
                {report.recommendations.length > 0 && (
                  <div className="bg-gradient-to-r from-purple-50 to-indigo-50 border border-purple-200 rounded-lg p-6">
                    <h4 className="text-lg font-semibold text-purple-900 mb-4 flex items-center">
                      <LightBulbIcon className="w-5 h-5 mr-2" />
                      AI-Powered Recommendations
                    </h4>
                    <div className="space-y-4">
                      {report.recommendations.map((rec, idx) => (
                        <div key={idx} className="bg-white rounded-md p-4 border border-purple-200">
                          <div className="flex items-start">
                            <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium ${getPriorityBadge(rec.priority)} mr-3 mt-1`}>
                              {rec.priority}
                            </span>
                            <div className="flex-1">
                              <p className="text-sm font-semibold text-gray-900">{rec.title}</p>
                              <p className="text-sm text-gray-600 mt-1">{rec.description}</p>
                              {rec.potential_benefit && (
                                <div className="mt-2 bg-green-50 rounded-md p-2">
                                  <p className="text-xs text-green-700">
                                    <strong>Benefit:</strong> {rec.potential_benefit}
                                  </p>
                                </div>
                              )}
                            </div>
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}

                {/* Detailed Checks */}
                <div className="bg-white border border-gray-200 rounded-lg p-6">
                  <h4 className="text-lg font-semibold text-gray-900 mb-4">Detailed Check Results</h4>
                  
                  <div className="space-y-4">
                    {/* Completeness Details */}
                    <div className="border-l-4 border-blue-500 pl-4">
                      <h5 className="font-medium text-gray-900">Data Completeness</h5>
                      <p className="text-sm text-gray-600 mt-1">
                        {report.checks.completeness.completed_fields} of {report.checks.completeness.total_fields} fields completed
                      </p>
                      {report.checks.completeness.missing_required.length > 0 && (
                        <p className="text-sm text-red-600 mt-1">
                          {report.checks.completeness.missing_required.length} required fields missing
                        </p>
                      )}
                    </div>

                    {/* Consistency Details */}
                    {report.checks.consistency.total_checks > 0 && (
                      <div className="border-l-4 border-green-500 pl-4">
                        <h5 className="font-medium text-gray-900">Internal Consistency</h5>
                        <p className="text-sm text-gray-600 mt-1">
                          {report.checks.consistency.passed_checks} of {report.checks.consistency.total_checks} checks passed
                        </p>
                        {report.checks.consistency.failed_checks.length > 0 && (
                          <p className="text-sm text-yellow-600 mt-1">
                            {report.checks.consistency.failed_checks.length} consistency checks failed
                          </p>
                        )}
                      </div>
                    )}

                    {/* Standards Compliance */}
                    {report.checks.standards_compliance.applicable_standards.length > 0 && (
                      <div className="border-l-4 border-purple-500 pl-4">
                        <h5 className="font-medium text-gray-900">Standards Compliance</h5>
                        <p className="text-sm text-gray-600 mt-1">
                          Applicable Standards: {report.checks.standards_compliance.applicable_standards.join(', ')}
                        </p>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="bg-gray-50 px-6 py-4 border-t border-gray-200 flex justify-between">
            <button
              onClick={onClose}
              className="px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
            >
              Close
            </button>
            {report && (
              <div className="flex space-x-3">
                <button
                  onClick={runQualityCheck}
                  className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-indigo-600 hover:bg-indigo-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                >
                  <ArrowPathIcon className="w-4 h-4 mr-2" />
                  Re-run Check
                </button>
                <button
                  onClick={() => {
                    const dataStr = JSON.stringify(report, null, 2);
                    const dataBlob = new Blob([dataStr], { type: 'application/json' });
                    const url = URL.createObjectURL(dataBlob);
                    const link = document.createElement('a');
                    link.href = url;
                    link.download = `quality-report-${report.tag_number}-${new Date().toISOString().split('T')[0]}.json`;
                    link.click();
                  }}
                  className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
                >
                  <DocumentArrowDownIcon className="w-4 h-4 mr-2" />
                  Export Report
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default QualityCheckerReport;

/**
 * ProjectLegendPanel.jsx — shared "Project Legend" status panel.
 *
 * Shows which legend a tool will resolve for the active project, following
 * the inheritance chain:
 *   Project legend pack (inherited) → user's active legend → built-in default
 *
 * Adopted by Line List / Equipment List / Instrument Index so engineers
 * configure a legend ONCE per project instead of per application.
 *
 * SOFT-CODED: section + labels via props; all colours from the V1 palette.
 *
 * Props:
 *   section      {string}  legend section code (e.g. 'line_list')
 *   projectId    {string}  active Project Organizer project_id (optional)
 *   projectName  {string}  display name for the project
 *   onManage     {func}    opens the LegendSheetsModal
 *   enabled      {bool}    false → render nothing
 */
import React, { useCallback, useEffect, useRef, useState } from 'react';
import { BookOpenIcon, Cog6ToothIcon, ArrowUpTrayIcon } from '@heroicons/react/24/outline';
import { listLegends, uploadLegendPack } from '../../services/pidCheckerV2API';
import projectOrganizerService from '../../services/projectOrganizerService';

// SOFT-CODED: enable name-based bridging so tools whose projects live only in
// localStorage (e.g. Instrument Index) still attach to a shared Project
// Organizer project by matching name (case-insensitive). No backend change.
const RESOLVE_PROJECT_BY_NAME = true;

const ProjectLegendPanel = ({
  section,
  projectId = null,
  projectName = '',
  onManage,
  enabled = true,
  refreshToken = 0,          // bump to force re-fetch (e.g. after modal closes)
}) => {
  const [activeLegend, setActiveLegend] = useState(null);   // resolved legend
  const [inherited, setInherited]       = useState(false);  // came from project pack?
  const [loaded, setLoaded]             = useState(false);
  const [resolvedProjectId, setResolvedProjectId] = useState(projectId || null);

  // Phase 2: AI legend-pack upload state
  const packInputRef = useRef(null);
  const [packBusy, setPackBusy]   = useState(false);
  const [packMsg, setPackMsg]     = useState(null); // { tone: 'ok'|'err', text }

  const handlePackUpload = async (e) => {
    const file = e.target.files?.[0];
    e.target.value = '';
    if (!file || !resolvedProjectId) return;
    setPackBusy(true); setPackMsg(null);
    try {
      const res = await uploadLegendPack({ file, projectId: resolvedProjectId, name: projectName });
      setPackMsg({ tone: 'ok', text: `Legend pack applied — ${res.sections} section${res.sections === 1 ? '' : 's'} configured for this project (${res.method}).` });
      refresh();
    } catch (err) {
      setPackMsg({ tone: 'err', text: err?.response?.data?.error || 'Legend pack upload failed.' });
    } finally {
      setPackBusy(false);
    }
  };

  // Bridge: resolve a shared Project Organizer project_id from the name when
  // the caller only has a local project (Instrument Index). Runs once per name.
  useEffect(() => {
    if (projectId) { setResolvedProjectId(projectId); return; }
    if (!RESOLVE_PROJECT_BY_NAME || !projectName) { setResolvedProjectId(null); return; }
    let live = true;
    (async () => {
      try {
        const items = await projectOrganizerService.listProjects({ q: projectName });
        const match = (items || []).find(p => (p.name || '').toLowerCase() === projectName.toLowerCase())
                   || (items || [])[0] || null;
        if (live) setResolvedProjectId(match?.project_id || null);
      } catch {
        if (live) setResolvedProjectId(null);
      }
    })();
    return () => { live = false; };
  }, [projectId, projectName]);

  const refresh = useCallback(async () => {
    if (!enabled || !section) return;
    try {
      const rows = await listLegends(section, resolvedProjectId || undefined);
      const list = rows || [];
      // Prefer an ACTIVE row; within a project scope prefer the inherited one.
      const active = list.find(l => l.is_active && l.inherited)
                  || list.find(l => l.is_active)
                  || list.find(l => l.inherited)
                  || null;
      setActiveLegend(active);
      setInherited(!!active?.inherited);
    } catch {
      /* non-fatal — legend is optional */
    } finally {
      setLoaded(true);
    }
  }, [enabled, section, resolvedProjectId]);

  useEffect(() => { refresh(); }, [refresh, refreshToken]);

  if (!enabled) return null;

  const statusColor = activeLegend ? (inherited ? '#6366f1' : '#10b981') : '#3b82f6';
  const statusLabel = !loaded
    ? 'Loading legend…'
    : activeLegend
      ? (inherited ? 'Project Legend (inherited)' : 'Custom Legend Active')
      : 'Using Built-in Defaults';

  return (
    <div className="rounded-2xl mb-4 overflow-hidden" style={{
      background: 'white',
      border: '1px solid rgba(59,130,246,0.18)',
      boxShadow: '0 2px 16px rgba(59,130,246,0.07)',
    }}>
      {/* Panel header — V1 legend panel style */}
      <div className="px-5 py-3.5 flex items-center gap-3"
        style={{ background: 'linear-gradient(90deg, rgba(59,130,246,0.06), rgba(99,102,241,0.08))', borderBottom: '1px solid rgba(59,130,246,0.14)' }}>
        <div className="w-9 h-9 rounded-lg flex items-center justify-center flex-shrink-0"
          style={{ background: 'linear-gradient(135deg,#3b82f6,#6366f1)', boxShadow: '0 4px 12px rgba(59,130,246,0.35)' }}>
          <BookOpenIcon className="w-4 h-4 text-white" />
        </div>
        <div className="flex-1 min-w-0">
          <h2 className="text-sm font-bold text-slate-800 leading-tight">Legend Sheets</h2>
          <p className="text-xs text-slate-500 mt-0.5">
            {resolvedProjectId ? `One legend per project — shared by every tool${projectName ? ` in "${projectName}"` : ''}` : 'Managed once — applied to every extraction'}
          </p>
        </div>
        {resolvedProjectId && (
          <>
            <input ref={packInputRef} type="file" accept=".pdf,.png,.jpg,.jpeg,.tiff,.tif,.bmp" className="hidden" onChange={handlePackUpload} />
            <button onClick={() => packInputRef.current?.click()} disabled={packBusy}
              title="Upload one project legend pack (PDF/image) — AI splits it into every section automatically"
              className="inline-flex items-center gap-2 px-4 py-2 rounded-lg text-white text-sm font-bold transition-all hover:-translate-y-0.5 disabled:opacity-50"
              style={{ background: 'linear-gradient(135deg,#8b5cf6,#6366f1)', boxShadow: '0 4px 12px rgba(139,92,246,0.35)' }}>
              <ArrowUpTrayIcon className="w-4 h-4" /> {packBusy ? 'Applying…' : 'Upload Pack (AI)'}
            </button>
          </>
        )}
        {onManage && (
          <button onClick={onManage}
            className="inline-flex items-center gap-2 px-4 py-2 rounded-lg text-white text-sm font-bold transition-all hover:-translate-y-0.5"
            style={{ background: 'linear-gradient(135deg,#3b82f6,#6366f1)', boxShadow: '0 4px 12px rgba(59,130,246,0.35)' }}>
            <Cog6ToothIcon className="w-4 h-4" /> Manage Legends
          </button>
        )}
      </div>

      {/* Status row */}
      <div className="px-5 py-4 flex items-start gap-4 flex-wrap">
        {packMsg && (
          <div className="w-full mb-1 px-3 py-2 rounded-lg text-xs font-semibold"
            style={packMsg.tone === 'ok'
              ? { background: '#f0fdf4', border: '1px solid #86efac', color: '#15803d' }
              : { background: '#fef2f2', border: '1px solid #fca5a5', color: '#b91c1c' }}>
            {packMsg.text}
          </div>
        )}
        <div className="flex-1 min-w-[220px]">
          <div className="flex items-center gap-2 mb-1.5">
            <div className="w-2.5 h-2.5 rounded-full" style={{
              background: statusColor,
              animation: activeLegend ? 'pulse 2s ease-in-out infinite' : 'none',
            }} />
            <span className="text-sm font-semibold text-slate-700">{statusLabel}</span>
            {inherited && (
              <span className="text-[10px] font-bold uppercase tracking-wide px-2 py-0.5 rounded-full"
                style={{ background: 'rgba(99,102,241,0.10)', color: '#6366f1', border: '1px solid rgba(99,102,241,0.25)' }}>
                Project Pack
              </span>
            )}
          </div>
          {activeLegend ? (
            <div className="pl-4">
              <p className="text-sm text-slate-600 mb-0.5">
                <span className="font-bold" style={{ color: inherited ? '#6366f1' : '#059669' }}>{activeLegend.name}</span>
              </p>
              <p className="text-xs text-slate-500">
                {activeLegend.definition?.fields?.length || 0} custom fields defined
                {activeLegend.definition?.sections ? ` · ${Object.keys(activeLegend.definition.sections).length} sections` : ''}
              </p>
            </div>
          ) : loaded && (
            <div className="pl-4">
              <p className="text-sm text-slate-600 mb-0.5">Industry-standard legend with smart recognition</p>
              <p className="text-xs text-slate-500">
                {resolvedProjectId
                  ? 'No project legend pack yet — open Manage Legends and save one to this project to share it across all tools'
                  : 'Resolves codes & descriptions automatically for 90%+ of drawings'}
              </p>
            </div>
          )}
        </div>
        <div className="flex-shrink-0 bg-blue-50 border border-blue-200 rounded-lg px-3 py-2" style={{ maxWidth: 320 }}>
          <p className="text-xs font-semibold text-blue-800 mb-0.5">🔄 Configure once per project</p>
          <p className="text-xs text-blue-600 leading-snug">
            A legend saved to the active project is inherited by Line List, Equipment List, Instrument Index and P&ID QC — no per-app setup.
          </p>
        </div>
      </div>
    </div>
  );
};

export default ProjectLegendPanel;

/**
 * WrenchAiDocAssist — reusable "AI Document Assist (Wrench)" panel.
 * ==================================================================
 * Mirrors the panel used on /engineering/process/pid-verification but is
 * fully soft-coded so any engineering page can drop it in:
 *
 *   <WrenchAiDocAssist
 *      title="AI Document Assist"
 *      subtitle="Let RAD AI pick the right Valve MTO from Wrench DMS"
 *      defaultHint="valve mto material take off"
 *      acceptedExts={['pdf','xls','xlsx','csv']}
 *      onFileSelected={(file) => importFile(file)}
 *   />
 *
 * Backend contract (unchanged — re-uses existing endpoints):
 *   GET /wrench/sync/projects/
 *   GET /wrench/sync/pid-recommendations/
 *   GET /wrench/sync/document-download/?idoc_id=...&doc_no=...
 *
 * No core logic is touched in the host page; the panel calls onFileSelected
 * with a `File` instance built from the Wrench download blob and the host
 * page feeds that into its existing import flow.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import axios from 'axios';
import {
  Sparkles, Brain, Loader, Download, AlertTriangle,
  ChevronDown, ChevronUp, FolderTree, X as XIcon,
} from 'lucide-react';
import { API_BASE_URL } from '../../config/api.config';

// ───── Soft-coded defaults (override any of these via props) ─────────────
const DEFAULTS = {
  endpointProjects:    '/wrench/sync/projects/',
  endpointRecommend:   '/wrench/sync/pid-recommendations/',
  endpointFolders:     '/wrench/sync/project-folders/',
  timeoutFoldersMs:    60000,
  foldersMinForSearch: 8,
  foldersListMaxH:     '180px',
  topN:                5,
  minHighlightScore:   80,
  acceptedExts:        ['pdf', 'xls', 'xlsx', 'csv'],
  // LocalStorage cache for the Wrench project list (shared across pages by key).
  lsKey:               'radai.wrench.projects.v1',
  lsTtlMs:             24 * 60 * 60 * 1000,   // hard expiry — 24 h
  lsFreshMs:           30 * 60 * 1000,        // background revalidate after 30 m
  minForSearch:        10,
  timeoutProjectsMs:   120000,
  timeoutRecommendMs:  60000,
  timeoutDownloadMs:   120000,
  brandGradient:       'linear-gradient(135deg,#6366f1,#a855f7)',
};

const _authHeader = () => {
  const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
  return token ? { Authorization: `Bearer ${token}` } : {};
};

const _readLS = (lsKey, ttlMs) => {
  try {
    const raw = localStorage.getItem(lsKey);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed?.ts || !Array.isArray(parsed?.projects)) return null;
    if (Date.now() - parsed.ts > ttlMs) return null;
    return parsed;
  } catch { return null; }
};

const _writeLS = (lsKey, payload) => {
  try {
    localStorage.setItem(lsKey, JSON.stringify({
      ts:       Date.now(),
      projects: payload?.projects || [],
      total:              payload?.total || 0,
      transmittal_count:  payload?.transmittal_count || 0,
      fetched_at_server:  payload?.fetched_at || null,
    }));
  } catch { /* ignore quota errors */ }
};

const WrenchAiDocAssist = ({
  // Display
  title       = 'AI Document Assist',
  subtitleTag = '(Wrench · optional)',
  subtitle    = 'Let RAD AI pick & recommend the right document for this project from Wrench DMS',
  defaultHint = '',
  hintPlaceholder = 'e.g. valve mto, gate valve, material take off',
  // Behaviour
  projectName  = '',
  initialOpen  = false,
  acceptedExts = DEFAULTS.acceptedExts,
  topN         = DEFAULTS.topN,
  // Callbacks
  onFileSelected,
  onError,
  // Overrides (rarely needed)
  endpointProjects  = DEFAULTS.endpointProjects,
  endpointRecommend = DEFAULTS.endpointRecommend,
  endpointFolders   = DEFAULTS.endpointFolders,
  lsKey             = DEFAULTS.lsKey,
}) => {
  const [open,         setOpen]         = useState(initialOpen);
  const [orderNo,      setOrderNo]      = useState('');
  const [hint,         setHint]         = useState(defaultHint);
  const [loading,      setLoading]      = useState(false);
  const [errorMsg,     setErrorMsg]     = useState('');
  const [result,       setResult]       = useState(null);
  const [fetchingDoc,  setFetchingDoc]  = useState(null);

  const [projects,         setProjects]         = useState([]);
  const [projectsLoading,  setProjectsLoading]  = useState(false);
  const [projectsSyncing,  setProjectsSyncing]  = useState(false);
  const [projectsError,    setProjectsError]    = useState('');
  const [projectsLoaded,   setProjectsLoaded]   = useState(false);
  const [projectFilter,    setProjectFilter]    = useState('');
  const [projectsFetched,  setProjectsFetched]  = useState(0);

  // ── Sub-folder picker state (additive, soft-coded) ────────────────
  const [folders,         setFolders]         = useState([]);   // [{path, segments, count, file_exts[]}]
  const [foldersOrderNo,  setFoldersOrderNo]  = useState('');
  const [foldersLoading,  setFoldersLoading]  = useState(false);
  const [foldersError,    setFoldersError]    = useState('');
  const [selectedFolders, setSelectedFolders] = useState([]);   // string[] of folder paths
  const [folderFilter,    setFolderFilter]    = useState('');

  const acceptList = useMemo(
    () => acceptedExts.map((e) => e.toLowerCase().replace(/^\./, '')),
    [acceptedExts],
  );

  // ── Load Wrench projects (cache-first) ────────────────────────────────
  const loadProjects = useCallback(async ({ force = false } = {}) => {
    let hadLocalSnapshot = false;
    if (!force && !projectsLoaded) {
      const snap = _readLS(lsKey, DEFAULTS.lsTtlMs);
      if (snap && snap.projects.length) {
        setProjects(snap.projects);
        setProjectsFetched(snap.ts);
        setProjectsLoaded(true);
        hadLocalSnapshot = true;
        if (Date.now() - snap.ts < DEFAULTS.lsFreshMs) return;
      }
    }
    if (projectsLoading || projectsSyncing) return;
    if (hadLocalSnapshot || projectsLoaded) setProjectsSyncing(true);
    else                                    setProjectsLoading(true);
    setProjectsError('');
    try {
      const res = await axios.get(`${API_BASE_URL}${endpointProjects}`, {
        params:  force ? { refresh: 1 } : {},
        headers: _authHeader(),
        timeout: DEFAULTS.timeoutProjectsMs,
      });
      const data = res.data || {};
      const list = Array.isArray(data.projects) ? data.projects : [];
      setProjects(list);
      setProjectsLoaded(true);
      setProjectsFetched(Date.now());
      _writeLS(lsKey, data);
    } catch (err) {
      setProjectsError(err?.response?.data?.detail || err?.message || 'Failed to load Wrench projects.');
    } finally {
      setProjectsLoading(false);
      setProjectsSyncing(false);
    }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [endpointProjects, lsKey, projectsLoaded, projectsLoading, projectsSyncing]);

  // Auto-load when the panel is opened for the first time.
  useEffect(() => {
    if (open && !projectsLoaded && !projectsLoading) loadProjects();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  // ── Load sub-folders for the resolved project (cache by order_no) ──────
  const loadFolders = useCallback(async (ord, projName) => {
    const key = (ord || '').trim() || (projName || '').trim();
    if (!key) return;
    if (foldersLoading) return;
    if (foldersOrderNo === key && folders.length) return;   // already cached
    setFoldersLoading(true);
    setFoldersError('');
    try {
      const res = await axios.get(`${API_BASE_URL}${endpointFolders}`, {
        params: {
          ...(ord      ? { order_no:     ord }      : {}),
          ...(projName ? { project_name: projName } : {}),
        },
        headers: _authHeader(),
        timeout: DEFAULTS.timeoutFoldersMs,
      });
      const list = Array.isArray(res.data?.folders) ? res.data.folders : [];
      setFolders(list);
      setFoldersOrderNo(key);
      // Reset previous selections when project changes.
      setSelectedFolders([]);
    } catch (err) {
      setFolders([]);
      setFoldersError(err?.response?.data?.detail || err?.message || 'Failed to load sub-folders.');
    } finally {
      setFoldersLoading(false);
    }
  }, [endpointFolders, folders.length, foldersLoading, foldersOrderNo]);

  // Auto-fetch folders when the user picks an order_no, or when projectName
  // is provided (auto-resolved on the backend).
  useEffect(() => {
    if (!open) return;
    const ord  = (orderNo || '').trim();
    const proj = (projectName || '').trim();
    if (!ord && !proj) return;
    loadFolders(ord, proj);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open, orderNo, projectName]);

  const toggleFolder = useCallback((path) => {
    setSelectedFolders((prev) => prev.includes(path)
      ? prev.filter((p) => p !== path)
      : [...prev, path]);
  }, []);
  const clearFolders = useCallback(() => setSelectedFolders([]), []);

  // ── Ask the backend for ranked recommendations ────────────────────────
  const runRecommend = useCallback(async () => {
    const ord  = (orderNo    || '').trim();
    const proj = (projectName || '').trim();
    if (!ord && !proj) {
      setErrorMsg('Select a Project Number or open a RAD AI project first.');
      return;
    }
    setLoading(true);
    setErrorMsg('');
    setResult(null);
    try {
      const res = await axios.get(`${API_BASE_URL}${endpointRecommend}`, {
        params: {
          ...(ord  ? { order_no:     ord  } : {}),
          ...(proj ? { project_name: proj } : {}),
          ...(hint ? { drawing_hint: hint } : {}),
          ...(selectedFolders.length ? { folders: selectedFolders.join(',') } : {}),
          top: topN,
        },
        headers: _authHeader(),
        timeout: DEFAULTS.timeoutRecommendMs,
      });
      setResult(res.data);
      if (!ord && res.data?.order_no) setOrderNo(res.data.order_no);
    } catch (err) {
      const msg = err?.response?.data?.detail || err?.message || 'AI assist failed.';
      setErrorMsg(msg);
      onError && onError(msg);
    } finally {
      setLoading(false);
    }
  }, [orderNo, projectName, hint, topN, endpointRecommend, onError, selectedFolders]);

  // ── Fetch a recommended doc via the Wrench download proxy ─────────────
  const useRecommendedDoc = useCallback(async (rec) => {
    if (!rec?.download_url) return;
    setFetchingDoc(rec.doc_no);
    setErrorMsg('');
    try {
      const downloadPath = rec.download_url.startsWith('http')
        ? rec.download_url
        : `${API_BASE_URL.replace(/\/api\/v1$/, '')}${rec.download_url}`;
      const res = await axios.get(downloadPath, {
        headers: _authHeader(),
        responseType: 'blob',
        timeout: DEFAULTS.timeoutDownloadMs,
      });
      const ctype = res.headers?.['content-type'] || '';
      if (ctype.includes('application/json')) {
        const txt  = await res.data.text();
        const json = JSON.parse(txt);
        if (json?.download_url) {
          window.open(json.download_url, '_blank', 'noopener,noreferrer');
          setErrorMsg(`Opening Wrench document ${rec.doc_no} in a new tab — please save and upload manually.`);
          return;
        }
        throw new Error(json?.detail || 'Wrench did not return file bytes.');
      }
      const ext = (rec.file_ext || 'pdf').toLowerCase().replace(/^\./, '');
      if (acceptList.length && !acceptList.includes(ext)) {
        throw new Error(`File extension .${ext} is not accepted by this importer (allowed: ${acceptList.join(', ')}).`);
      }
      const fileName = `${rec.doc_no || 'wrench-document'}.${ext}`;
      const blobType = res.data.type || (ext === 'pdf' ? 'application/pdf' : 'application/octet-stream');
      const fileObj  = new File([res.data], fileName, { type: blobType });
      onFileSelected && onFileSelected(fileObj, rec);
    } catch (err) {
      const msg = err?.response?.data?.detail || err?.message || 'Failed to download document from Wrench.';
      setErrorMsg(msg);
      onError && onError(msg);
    } finally {
      setFetchingDoc(null);
    }
  }, [acceptList, onFileSelected, onError]);

  const projectsAge = useMemo(() => {
    if (!projectsFetched) return '';
    const m = Math.max(0, Math.round((Date.now() - projectsFetched) / 60000));
    if (m < 1)  return 'just now';
    if (m < 60) return `${m}m ago`;
    const h = Math.round(m / 60);
    if (h < 24) return `${h}h ago`;
    return `${Math.round(h / 24)}d ago`;
  }, [projectsFetched]);

  return (
    <div className="rounded-2xl overflow-hidden border border-slate-200 bg-white">
      {/* Header / toggle */}
      <div
        className="px-4 py-3 flex items-center gap-3 cursor-pointer select-none"
        style={{ background: open
          ? 'linear-gradient(135deg,#eef2ff,#f0f9ff)'
          : 'linear-gradient(135deg,#fafbff,#f7f8ff)' }}
        onClick={() => setOpen((v) => !v)}
      >
        <div
          className="w-8 h-8 rounded-lg flex items-center justify-center flex-shrink-0"
          style={{ background: DEFAULTS.brandGradient }}
        >
          <Sparkles className="w-4 h-4 text-white" />
        </div>
        <div className="flex-1">
          <p className="text-sm font-bold text-slate-800 leading-tight">
            {title} <span className="text-xs font-normal text-slate-400">{subtitleTag}</span>
          </p>
          <p className="text-xs text-slate-500 mt-0.5">{subtitle}</p>
        </div>
        <label className="inline-flex items-center cursor-pointer" onClick={(e) => e.stopPropagation()}>
          <input
            type="checkbox"
            className="sr-only peer"
            checked={open}
            onChange={() => setOpen((v) => !v)}
          />
          <div className="w-10 h-5 bg-slate-200 rounded-full peer-checked:bg-indigo-500 transition-colors relative">
            <span className={`absolute top-0.5 left-0.5 w-4 h-4 bg-white rounded-full shadow transition-transform ${open ? 'translate-x-5' : ''}`} />
          </div>
        </label>
        {open ? <ChevronUp className="w-4 h-4 text-slate-400" /> : <ChevronDown className="w-4 h-4 text-slate-400" />}
      </div>

      {/* Body */}
      {open && (
        <div className="px-4 py-4 border-t border-slate-100 space-y-3">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-2">
            {/* Project picker */}
            <div>
              <div className="flex items-center justify-between mb-1">
                <label className="block text-[11px] font-semibold text-slate-500 uppercase tracking-wide">Project Number</label>
                <div className="flex items-center gap-1.5">
                  {projectsSyncing && (
                    <span className="inline-flex items-center gap-1 text-[10px] text-indigo-500">
                      <Loader className="w-3 h-3 animate-spin" />syncing…
                    </span>
                  )}
                  {projectsFetched > 0 && !projectsLoading && (
                    <span className="text-[10px] text-slate-400" title={new Date(projectsFetched).toLocaleString()}>
                      {projectsAge}
                    </span>
                  )}
                  <button
                    type="button"
                    onClick={() => loadProjects({ force: true })}
                    disabled={projectsLoading || projectsSyncing}
                    className="text-[10px] font-semibold text-indigo-600 hover:text-indigo-800 disabled:opacity-50"
                    title="Force refresh from Wrench (bypass cache)"
                  >
                    {projectsLoading ? 'Loading…' : 'Refresh'}
                  </button>
                </div>
              </div>

              {projectsLoading && projects.length === 0 ? (
                <div className="space-y-1.5 animate-pulse">
                  <div className="h-7 bg-slate-100 rounded-lg" />
                  <div className="h-3 bg-slate-100 rounded w-2/3" />
                </div>
              ) : (
                <>
                  {projects.length >= DEFAULTS.minForSearch && (
                    <input
                      type="text"
                      value={projectFilter}
                      onChange={(e) => setProjectFilter(e.target.value)}
                      placeholder="Search project number or description…"
                      className="w-full text-xs border border-slate-200 rounded-lg px-2 py-1 mb-1 focus:outline-none focus:ring-1 focus:ring-indigo-300"
                    />
                  )}
                  <select
                    value={orderNo}
                    onChange={(e) => setOrderNo(e.target.value)}
                    disabled={projectsLoading}
                    className="w-full text-sm border border-slate-200 rounded-lg px-2.5 py-1.5 focus:outline-none focus:ring-2 focus:ring-indigo-300 bg-white disabled:bg-slate-50"
                  >
                    <option value="">
                      {projects.length
                        ? `— auto-resolve from project name (${projects.length} available) —`
                        : (projectsError ? '(failed to load — using project name)' : '(no projects loaded yet)')}
                    </option>
                    {projects
                      .filter((p) => !projectFilter || (p.label || '').toLowerCase().includes(projectFilter.toLowerCase()))
                      .map((p) => (
                        <option key={p.order_no} value={p.order_no}>{p.label}</option>
                      ))}
                  </select>
                  {projectsError && projects.length === 0 && (
                    <p className="text-[10px] text-red-500 mt-1 truncate" title={projectsError}>
                      {projectsError}
                    </p>
                  )}
                </>
              )}
            </div>

            {/* Hint */}
            <div className="sm:col-span-2">
              <label className="block text-[11px] font-semibold text-slate-500 uppercase tracking-wide mb-1">Document hint (optional)</label>
              <input
                type="text"
                value={hint}
                onChange={(e) => setHint(e.target.value)}
                placeholder={hintPlaceholder}
                className="w-full text-sm border border-slate-200 rounded-lg px-2.5 py-1.5 focus:outline-none focus:ring-2 focus:ring-indigo-300"
              />
            </div>
          </div>

          {/* ── Sub-folders (multi-select, optional) ──────────────────── */}
          {(foldersLoading || folders.length > 0 || foldersError || foldersOrderNo) && (
            <div className="rounded-lg border border-slate-200 bg-slate-50/50 px-3 py-2">
              <div className="flex items-center justify-between mb-1.5">
                <label className="flex items-center gap-1.5 text-[11px] font-semibold text-slate-600 uppercase tracking-wide">
                  <FolderTree className="w-3.5 h-3.5 text-indigo-500" />
                  Sub-folders (optional, multi-select)
                  {foldersLoading && <Loader className="w-3 h-3 animate-spin text-indigo-400" />}
                </label>
                <div className="flex items-center gap-2 text-[10px] text-slate-500">
                  {folders.length > 0 && (
                    <span>
                      {selectedFolders.length
                        ? `${selectedFolders.length} of ${folders.length} selected`
                        : `${folders.length} folder${folders.length === 1 ? '' : 's'} available`}
                    </span>
                  )}
                  {selectedFolders.length > 0 && (
                    <button
                      type="button"
                      onClick={clearFolders}
                      className="inline-flex items-center gap-0.5 text-indigo-600 hover:text-indigo-800 font-semibold"
                    >
                      <XIcon className="w-3 h-3" /> clear
                    </button>
                  )}
                </div>
              </div>

              {foldersError && folders.length === 0 ? (
                <p className="text-[10px] text-red-500 truncate" title={foldersError}>{foldersError}</p>
              ) : folders.length === 0 && !foldersLoading ? (
                <p className="text-[10px] text-slate-400 italic">
                  No sub-folders are indexed for this project — recommendations will scan the whole project.
                </p>
              ) : (
                <>
                  {folders.length >= DEFAULTS.foldersMinForSearch && (
                    <input
                      type="text"
                      value={folderFilter}
                      onChange={(e) => setFolderFilter(e.target.value)}
                      placeholder="Filter sub-folders…"
                      className="w-full text-xs border border-slate-200 rounded-lg px-2 py-1 mb-1.5 focus:outline-none focus:ring-1 focus:ring-indigo-300"
                    />
                  )}
                  <div
                    className="flex flex-wrap gap-1.5 overflow-y-auto pr-1"
                    style={{ maxHeight: DEFAULTS.foldersListMaxH }}
                  >
                    {folders
                      .filter((f) => !folderFilter
                        || f.path.toLowerCase().includes(folderFilter.toLowerCase()))
                      .map((f) => {
                        const checked = selectedFolders.includes(f.path);
                        return (
                          <button
                            key={f.path}
                            type="button"
                            onClick={() => toggleFolder(f.path)}
                            title={`${f.path}  ·  ${f.count} document${f.count === 1 ? '' : 's'}${
                              f.file_exts?.length ? `  ·  ${f.file_exts.join(', ')}` : ''
                            }`}
                            className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-full text-[11px] font-medium border transition ${
                              checked
                                ? 'bg-indigo-500 text-white border-indigo-500 shadow-sm'
                                : 'bg-white text-slate-700 border-slate-200 hover:border-indigo-300 hover:bg-indigo-50'
                            }`}
                          >
                            <FolderTree className={`w-3 h-3 ${checked ? 'text-white' : 'text-indigo-400'}`} />
                            <span className="truncate max-w-[18rem]">{f.path}</span>
                            <span className={`px-1 rounded text-[9px] ${
                              checked ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'
                            }`}>{f.count}</span>
                          </button>
                        );
                      })}
                  </div>
                  {selectedFolders.length > 0 && (
                    <p className="text-[10px] text-indigo-600 mt-1.5">
                      AI will scan only the selected sub-folder(s).
                    </p>
                  )}
                </>
              )}
            </div>
          )}

          <div className="flex items-center gap-2">
            <button
              onClick={runRecommend}
              disabled={loading}
              className="inline-flex items-center gap-2 px-3.5 py-2 rounded-lg text-sm font-semibold text-white disabled:opacity-60"
              style={{ background: DEFAULTS.brandGradient }}
            >
              {loading
                ? <><Loader className="w-4 h-4 animate-spin" />Asking AI…</>
                : <><Brain className="w-4 h-4" />Recommend documents</>}
            </button>
            {result?.order_no && (
              <span className="text-xs text-slate-500">
                Matched <span className="font-semibold text-slate-700">{result.order_no}</span>
                {result.matched_via && result.matched_via !== 'explicit' && (
                  <span className="ml-1 text-slate-400">· {result.matched_via}</span>
                )}
              </span>
            )}
          </div>

          {errorMsg && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-3 flex items-start gap-2">
              <AlertTriangle className="w-4 h-4 text-red-500 flex-shrink-0 mt-0.5" />
              <p className="text-xs text-red-600">{errorMsg}</p>
            </div>
          )}

          {result && !result.recommendations?.length && (
            <div className="bg-amber-50 border border-amber-200 rounded-lg p-3 text-xs text-amber-700">
              {result.note || 'No matching documents were found in Wrench for this project.'}
            </div>
          )}

          {result?.recommendations?.length > 0 && (
            <div className="space-y-2">
              <p className="text-[11px] font-semibold text-slate-500 uppercase tracking-wide">
                Top {result.recommendations.length} of {result.total_scanned} document(s)
              </p>
              {result.recommendations.map((rec, idx) => {
                const isTop      = rec.score >= DEFAULTS.minHighlightScore;
                const isFetching = fetchingDoc === rec.doc_no;
                const ext        = (rec.file_ext || '').toLowerCase();
                const accepted   = !acceptList.length || acceptList.includes(ext);
                return (
                  <div
                    key={`${rec.doc_no}-${idx}`}
                    className={`flex items-start gap-3 p-3 rounded-lg border ${
                      isTop ? 'border-emerald-200 bg-emerald-50/40' : 'border-slate-200 bg-white'
                    }`}
                  >
                    <div className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 text-xs font-bold ${
                      isTop ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-600'
                    }`}>{rec.score}</div>
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-semibold text-slate-800 truncate">{rec.doc_no || '(no DOC_NO)'}</p>
                      {rec.doc_description && (
                        <p className="text-xs text-slate-500 truncate mt-0.5">{rec.doc_description}</p>
                      )}
                      <div className="mt-1 flex flex-wrap items-center gap-1.5 text-[10px]">
                        {rec.discipline && (
                          <span className="px-1.5 py-0.5 rounded bg-blue-50 text-blue-700 border border-blue-100">{rec.discipline}</span>
                        )}
                        {rec.revision && (
                          <span className="px-1.5 py-0.5 rounded bg-slate-50 text-slate-600 border border-slate-200">Rev {rec.revision}</span>
                        )}
                        {rec.file_ext && (
                          <span className={`px-1.5 py-0.5 rounded uppercase border ${
                            accepted ? 'bg-violet-50 text-violet-700 border-violet-100'
                                     : 'bg-rose-50 text-rose-700 border-rose-200'
                          }`}>{rec.file_ext}</span>
                        )}
                        {rec.reasons?.slice(0, 2).map((r, i) => (
                          <span key={i} className="px-1.5 py-0.5 rounded bg-slate-50 text-slate-500 border border-slate-200">{r}</span>
                        ))}
                      </div>
                    </div>
                    <button
                      onClick={() => useRecommendedDoc(rec)}
                      disabled={isFetching || !rec.download_url || !accepted}
                      title={!accepted
                        ? `Extension .${ext} not accepted by this importer (allowed: ${acceptList.join(', ')})`
                        : undefined}
                      className="flex-shrink-0 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold border border-indigo-200 bg-indigo-50 text-indigo-700 hover:bg-indigo-100 disabled:opacity-60"
                    >
                      {isFetching
                        ? <><Loader className="w-3.5 h-3.5 animate-spin" />Loading…</>
                        : <><Download className="w-3.5 h-3.5" />Use this</>}
                    </button>
                  </div>
                );
              })}
              <p className="text-[10px] text-slate-400 italic">
                Scores come from soft-coded heuristics (pattern + discipline + file-type + hint tokens).
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

