      indigo: 'bg-indigo-100 text-indigo-700 border-indigo-300'
    }
    return colorMap[badge.color] || 'bg-gray-100 text-gray-700 border-gray-300'
  }

  // Status badge colors
  const getStatusColors = (status) => {
    const colorMap = {
      active: 'bg-green-100 text-green-700',
      beta: 'bg-yellow-100 text-yellow-700',
      new: 'bg-blue-100 text-blue-700',
      preview: 'bg-purple-100 text-purple-700',
      coming_soon: 'bg-gray-100 text-gray-700'
    }
    return colorMap[status?.id] || 'bg-gray-100 text-gray-700'
  }

  // Category gradient mapping
  const getCategoryGradient = (color) => {
    const gradientMap = {
      blue: 'from-blue-500 to-indigo-600',
      purple: 'from-purple-500 to-pink-600',
      green: 'from-green-500 to-emerald-600',
      indigo: 'from-indigo-500 to-blue-600',
      orange: 'from-orange-500 to-red-600',
      red: 'from-red-500 to-pink-600'
    }
    return gradientMap[color] || 'from-gray-500 to-gray-600'
  }

  // Render star rating
  const renderRating = (rating) => {
    const stars = []
    for (let i = 1; i <= 5; i++) {
      stars.push(
        i <= Math.round(rating) ? (
          <StarIconSolid key={i} className="w-4 h-4 text-yellow-400" />
        ) : (
          <StarIcon key={i} className="w-4 h-4 text-gray-300" />
        )
      )
    }
    return <div className="flex items-center gap-0.5">{stars}</div>
  }

  if (compact) {
    return (
      <div
        onClick={() => feature.path && navigate(feature.path)}
        className="group relative bg-white rounded-xl border-2 border-gray-200 p-4 hover:border-blue-500 hover:shadow-lg transition-all cursor-pointer"
      >
        <div className="flex items-center justify-between mb-2">
          <h3 className="font-bold text-gray-900 group-hover:text-blue-600 transition-colors">
            {feature.shortName || feature.name}
          </h3>
          {feature.status && (
            <span className={`px-2 py-0.5 rounded-full text-xs font-semibold ${getStatusColors(feature.status)}`}>
              {feature.status.label}
            </span>
          )}
        </div>
        <p className="text-sm text-gray-600 line-clamp-2">{feature.description}</p>
        {feature.badges && feature.badges.length > 0 && (
          <div className="flex flex-wrap gap-1 mt-2">
            {feature.badges.map((badge) => (
              <span
                key={badge.id}
                className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium border ${getBadgeColors(badge)}`}
              >
                <span>{badge.icon}</span>
                <span>{badge.label}</span>
              </span>
            ))}
          </div>
        )}
      </div>
    )
  }

  return (
    <div
      onClick={() => feature.path && navigate(feature.path)}
      className="group relative bg-white rounded-2xl border-2 border-gray-200 hover:border-blue-500 hover:shadow-2xl transition-all duration-300 overflow-hidden cursor-pointer"
    >
      {/* Decorative gradient bar */}
      <div className={`h-2 bg-gradient-to-r ${getCategoryGradient(feature.categoryColor)}`}></div>

      <div className="p-6">
        {/* Header Section */}
        <div className="flex items-start justify-between mb-4">
          <div className="flex-1">
            <div className="flex items-center gap-3 mb-2">
              <h3 className="text-xl font-bold text-gray-900 group-hover:text-blue-600 transition-colors">
                {feature.name}
              </h3>
              {feature.status && (
                <span className={`px-3 py-1 rounded-full text-xs font-semibold ${getStatusColors(feature.status)}`}>
                  {feature.status.label}
                </span>
              )}
            </div>
            <p className="text-sm text-gray-500 font-medium">{feature.categoryName}</p>
          </div>
          
          {/* Usage Stats Summary */}
          {showMetrics && feature.usageStats && (
            <div className="flex flex-col items-end gap-1">
              {feature.usageStats.avgRating && (
                <div className="flex items-center gap-2">
                  {renderRating(feature.usageStats.avgRating)}
                  <span className="text-sm font-semibold text-gray-700">
                    {feature.usageStats.avgRating.toFixed(1)}
                  </span>
                </div>
              )}
              {feature.usageStats.monthlyUses && (
                <div className="flex items-center gap-1 text-xs text-gray-500">
                  <ChartBarIcon className="w-4 h-4" />
                  <span>{feature.usageStats.monthlyUses.toLocaleString()} uses/mo</span>
                </div>
              )}
            </div>
          )}
        </div>

        {/* Description */}
        <p className="text-gray-600 mb-4 line-clamp-2">
          {feature.longDescription || feature.description}
        </p>

        {/* Badges */}
        {feature.badges && feature.badges.length > 0 && (
          <div className="flex flex-wrap gap-2 mb-4">
            {feature.badges.map((badge) => (
              <span
                key={badge.id}
                className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium border ${getBadgeColors(badge)}`}
              >
                <span className="text-base">{badge.icon}</span>
                <span>{badge.label}</span>
              </span>
            ))}
          </div>
        )}

        {/* Key Capabilities */}
        {feature.capabilities && feature.capabilities.length > 0 && (
          <div className="mb-4">
            <h4 className="text-sm font-semibold text-gray-700 mb-2 flex items-center gap-2">
              <CheckCircleIcon className="w-4 h-4 text-green-600" />
              Key Capabilities
            </h4>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
              {feature.capabilities.slice(0, 4).map((capability, idx) => (
                <div key={idx} className="flex items-start gap-2 text-sm text-gray-600">
                  <span className="text-green-500 mt-0.5">✓</span>
                  <span>{capability}</span>
                </div>
              ))}
            </div>
            {feature.capabilities.length > 4 && (
              <p className="text-xs text-gray-500 mt-2">
                +{feature.capabilities.length - 4} more capabilities
              </p>
            )}
          </div>
        )}

        {/* Metrics Section */}
        {showMetrics && feature.metrics && Object.keys(feature.metrics).length > 0 && (
          <div className="bg-gradient-to-r from-blue-50 to-indigo-50 rounded-xl p-4 mb-4">
            <h4 className="text-sm font-semibold text-gray-700 mb-3 flex items-center gap-2">
              <SparklesIcon className="w-4 h-4 text-blue-600" />
              Performance Metrics
            </h4>
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
              {Object.entries(feature.metrics).map(([key, value]) => (
                <div key={key}>
                  <p className="text-xs text-gray-500 mb-0.5">
                    {key.replace(/([A-Z])/g, ' $1').replace(/^./, str => str.toUpperCase())}
                  </p>
                  <p className="text-lg font-bold text-gray-900">{value}</p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Footer Actions */}
        <div className="flex items-center justify-between pt-4 border-t border-gray-200">
          <div className="flex items-center gap-4 text-sm text-gray-500">
            {feature.usageStats?.totalUses && (
              <div className="flex items-center gap-1">
                <ArrowTrendingUpIcon className="w-4 h-4" />
                <span>{feature.usageStats.totalUses.toLocaleString()} total uses</span>
              </div>
            )}
            {feature.usageStats?.lastUsed && (
              <div className="flex items-center gap-1">
                <ClockIcon className="w-4 h-4" />
                <span>Last used {new Date(feature.usageStats.lastUsed).toLocaleDateString()}</span>
              </div>
            )}
          </div>
          
          <button
            className="px-6 py-2 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-lg hover:shadow-lg transition-all font-medium group-hover:scale-105"
          >
            Open Feature →
          </button>
        </div>
      </div>
    </div>
  )
}

export default AdvancedFeatureCard

/**
 * Features Browser Component
 * Advanced features exploration with search, filters, and multiple views
 */

import React, { useState, useMemo } from 'react'
import {
  MagnifyingGlassIcon,
  FunnelIcon,
  Squares2X2Icon,
  ListBulletIcon,
  ChartBarIcon,
  SparklesIcon,
  StarIcon,
  AdjustmentsHorizontalIcon
} from '@heroicons/react/24/outline'
import AdvancedFeatureCard from './AdvancedFeatureCard'
import {
  FEATURES_CATALOG,
  getAllFeatures,
  searchFeatures,
  getFeaturesByCategory,
  sortFeatures,
  getCategoryStats,
  FEATURE_STATUS
} from '../../config/featuresCatalog.config'

const FeaturesBrowser = ({ userModules = [], isAdmin = false }) => {
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedCategory, setSelectedCategory] = useState('all')
  const [selectedStatus, setSelectedStatus] = useState('all')
  const [sortBy, setSortBy] = useState('popularity')
  const [viewMode, setViewMode] = useState('grid') // grid, list, compact
  const [showMetrics, setShowMetrics] = useState(true)
  const [showFilters, setShowFilters] = useState(false)

  // Get filtered and sorted features
  const filteredFeatures = useMemo(() => {
    let features = getAllFeatures()

    // Filter by search query
    if (searchQuery.trim()) {
      features = searchFeatures(searchQuery)
    }

    // Filter by category
    if (selectedCategory !== 'all') {
      features = features.filter(f => f.categoryId === selectedCategory)
    }

    // Filter by status
    if (selectedStatus !== 'all') {
      features = features.filter(f => f.status?.id === selectedStatus)
    }

    // Filter by user access
    if (!isAdmin) {
      features = features.filter(f => 
        !f.moduleCode || userModules.includes(f.moduleCode)
      )
    }

    // Sort features
    features = sortFeatures(features, sortBy)

    return features
  }, [searchQuery, selectedCategory, selectedStatus, sortBy, userModules, isAdmin])

  // Get statistics
  const stats = useMemo(() => {
    const allFeatures = getAllFeatures()
    return {
      total: allFeatures.length,
      ai: allFeatures.filter(f => f.badges?.some(b => b.id === 'ai')).length,
      popular: allFeatures.filter(f => f.badges?.some(b => b.id === 'popular')).length,
      new: allFeatures.filter(f => f.status?.id === 'new').length,
      filtered: filteredFeatures.length
    }
  }, [filteredFeatures])

  // Categories for filter
  const categories = Object.values(FEATURES_CATALOG)

  return (
    <div className="space-y-6">
      {/* Statistics Bar */}
      <div className="bg-gradient-to-r from-blue-50 to-indigo-50 rounded-2xl p-6 border border-blue-200">
        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
          <div className="text-center">
            <p className="text-3xl font-bold text-blue-600">{stats.total}</p>
            <p className="text-sm text-gray-600 mt-1">Total Features</p>
          </div>
          <div className="text-center">
            <p className="text-3xl font-bold text-purple-600">{stats.ai}</p>
            <p className="text-sm text-gray-600 mt-1">AI-Powered</p>
          </div>
          <div className="text-center">
            <p className="text-3xl font-bold text-yellow-600">{stats.popular}</p>
            <p className="text-sm text-gray-600 mt-1">Popular</p>
          </div>
          <div className="text-center">
            <p className="text-3xl font-bold text-green-600">{stats.new}</p>
            <p className="text-sm text-gray-600 mt-1">New</p>
          </div>
          <div className="text-center">
            <p className="text-3xl font-bold text-indigo-600">{stats.filtered}</p>
            <p className="text-sm text-gray-600 mt-1">Showing</p>
          </div>
        </div>
      </div>

      {/* Search and Filter Bar */}
      <div className="bg-white rounded-2xl border-2 border-gray-200 p-4">
        <div className="flex flex-col md:flex-row gap-4">
          {/* Search */}
          <div className="flex-1 relative">
            <MagnifyingGlassIcon className="absolute left-4 top-1/2 -translate-y-1/2 w-5 h-5 text-gray-400" />
            <input
              type="text"
              placeholder="Search features, capabilities, or keywords..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-12 pr-4 py-3 bg-gray-50 border-2 border-gray-200 rounded-xl focus:border-blue-500 focus:ring-2 focus:ring-blue-200 outline-none transition-all"
            />
          </div>

          {/* View Mode Toggle */}
          <div className="flex items-center gap-2 bg-gray-100 rounded-xl p-1">
            <button
              onClick={() => setViewMode('grid')}
              className={`p-2 rounded-lg transition-all ${
                viewMode === 'grid' ? 'bg-white shadow-md text-blue-600' : 'text-gray-600 hover:text-gray-900'
              }`}
              title="Grid View"
            >
              <Squares2X2Icon className="w-5 h-5" />
            </button>
            <button
              onClick={() => setViewMode('list')}
              className={`p-2 rounded-lg transition-all ${
                viewMode === 'list' ? 'bg-white shadow-md text-blue-600' : 'text-gray-600 hover:text-gray-900'
              }`}
              title="List View"
            >
              <ListBulletIcon className="w-5 h-5" />
            </button>
          </div>

          {/* Filter Toggle */}
          <button
            onClick={() => setShowFilters(!showFilters)}
            className={`px-4 py-3 rounded-xl font-medium transition-all flex items-center gap-2 ${
              showFilters 
                ? 'bg-blue-600 text-white shadow-lg' 
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            <FunnelIcon className="w-5 h-5" />
            Filters
          </button>
        </div>

        {/* Advanced Filters Panel */}
        {showFilters && (
          <div className="mt-4 pt-4 border-t border-gray-200 grid grid-cols-1 md:grid-cols-3 gap-4">
            {/* Category Filter */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Category</label>
              <select
                value={selectedCategory}
                onChange={(e) => setSelectedCategory(e.target.value)}
                className="w-full px-4 py-2 bg-white border-2 border-gray-200 rounded-xl focus:border-blue-500 outline-none"
              >
                <option value="all">All Categories</option>
                {categories.map(cat => (
                  <option key={cat.id} value={cat.id}>
                    {cat.icon} {cat.name}
                  </option>
                ))}
              </select>
            </div>

            {/* Status Filter */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Status</label>
              <select
                value={selectedStatus}
                onChange={(e) => setSelectedStatus(e.target.value)}
                className="w-full px-4 py-2 bg-white border-2 border-gray-200 rounded-xl focus:border-blue-500 outline-none"
              >
                <option value="all">All Status</option>
                {Object.values(FEATURE_STATUS).map(status => (
                  <option key={status.id} value={status.id}>
                    {status.label}
                  </option>
                ))}
              </select>
            </div>

            {/* Sort By */}
            <div>
              <label className="block text-sm font-semibold text-gray-700 mb-2">Sort By</label>
              <select
                value={sortBy}
                onChange={(e) => setSortBy(e.target.value)}
                className="w-full px-4 py-2 bg-white border-2 border-gray-200 rounded-xl focus:border-blue-500 outline-none"
              >
                <option value="popularity">Most Popular</option>
                <option value="rating">Highest Rated</option>
                <option value="name">Name (A-Z)</option>
                <option value="category">Category</option>
              </select>
            </div>
          </div>
        )}
      </div>

      {/* Results Header */}
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-gray-900">
          {searchQuery ? `Search Results (${filteredFeatures.length})` : 'Available Features'}
        </h2>
        <div className="flex items-center gap-4">
          <label className="flex items-center gap-2 text-sm text-gray-600 cursor-pointer">
            <input
              type="checkbox"
              checked={showMetrics}
              onChange={(e) => setShowMetrics(e.target.checked)}
              className="w-4 h-4 text-blue-600 rounded border-gray-300 focus:ring-blue-500"
            />
            Show Metrics
          </label>
        </div>
      </div>

      {/* Features Grid/List */}
      {filteredFeatures.length > 0 ? (
        <div className={
          viewMode === 'grid' 
            ? 'grid grid-cols-1 md:grid-cols-2 gap-6'
            : viewMode === 'list'
            ? 'space-y-4'
            : 'grid grid-cols-1 md:grid-cols-3 gap-4'
        }>
          {filteredFeatures.map((feature) => (
            <AdvancedFeatureCard
              key={feature.id}
              feature={feature}
              showMetrics={showMetrics}
              compact={viewMode === 'compact'}
            />
          ))}
        </div>
      ) : (
        <div className="bg-white rounded-2xl shadow-lg p-12 text-center border border-gray-200">
          <div className="w-20 h-20 bg-gradient-to-br from-gray-100 to-gray-200 rounded-full flex items-center justify-center mx-auto mb-4">
            <MagnifyingGlassIcon className="w-10 h-10 text-gray-400" />
          </div>
          <h3 className="text-xl font-bold text-gray-900 mb-2">No Features Found</h3>
          <p className="text-gray-600 mb-4">
            {searchQuery 
              ? `No features match "${searchQuery}". Try different keywords.`
              : 'No features available with current filters.'}
          </p>
          <button
            onClick={() => {
              setSearchQuery('')
              setSelectedCategory('all')
              setSelectedStatus('all')
            }}
            className="px-6 py-2.5 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-colors font-medium"
          >
            Clear Filters
          </button>
        </div>
      )}

      {/* Category Breakdown */}
      {selectedCategory === 'all' && !searchQuery && (
        <div className="bg-white rounded-2xl border-2 border-gray-200 p-6">
          <h3 className="text-xl font-bold text-gray-900 mb-4">Features by Category</h3>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {categories.map(category => {
              const categoryStats = getCategoryStats(category.id)
              return (
                <div
                  key={category.id}
                  onClick={() => setSelectedCategory(category.id)}
                  className="p-4 bg-gradient-to-br from-gray-50 to-white border-2 border-gray-200 rounded-xl hover:border-blue-500 hover:shadow-lg transition-all cursor-pointer"
                >
                  <div className="flex items-center gap-3 mb-3">
                    <span className="text-3xl">{category.icon}</span>
                    <div>
                      <h4 className="font-bold text-gray-900">{category.name}</h4>
                      <p className="text-xs text-gray-500">{categoryStats.total} features</p>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-2 text-xs">
                    <div className="bg-green-100 text-green-700 px-2 py-1 rounded-lg text-center font-semibold">
                      {categoryStats.active} Active
                    </div>
                    {categoryStats.ai > 0 && (
                      <div className="bg-purple-100 text-purple-700 px-2 py-1 rounded-lg text-center font-semibold">
                        {categoryStats.ai} AI
                      </div>
                    )}
                  </div>
                </div>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

export default FeaturesBrowser

/**
 * Field Suggestion Components
 * Reusable UI components for displaying field recommendations
 */

import React from 'react';
import './FieldSuggestions.css';

/**
 * Badge showing recommendation metadata
 */
export const RecommendationBadge = ({ type = 'common', count, onClick }) => {
  const badges = {
    common: { label: `Used ${count}x`, className: 'badge-common', emoji: '🔥' },
    recent: { label: 'Recent', className: 'badge-recent', emoji: '📅' },
    suggested: { label: 'Suggested', className: 'badge-suggested', emoji: '💡' },
    average: { label: 'Average', className: 'badge-average', emoji: '📊' }
  };

  const badge = badges[type] || badges.suggested;

  return (
    <span 
      className={`recommendation-badge ${badge.className}`}
      onClick={onClick}
      title={`${badge.emoji} ${badge.label}`}
    >
      {badge.emoji} {badge.label}
    </span>
  );
};

/**
 * Suggestion dropdown for text fields
 */
export const SuggestionDropdown = ({ 
  suggestions = [], 
  onSelect, 
  visible = true,
  fieldName 
}) => {
  if (!visible || suggestions.length === 0) return null;

  return (
    <div className="suggestion-dropdown">
      <div className="suggestion-header">
        💡 Suggestions for {fieldName}
      </div>
      <div className="suggestion-list">
        {suggestions.map((suggestion, index) => (
          <div
            key={index}
            className={`suggestion-item priority-${suggestion.priority || 'medium'}`}
            onClick={() => onSelect(suggestion.value)}
            title={suggestion.badge}
          >
            <span className="suggestion-value">{suggestion.label}</span>
            <RecommendationBadge 
              type={suggestion.badge === 'Recent' ? 'recent' : 'common'}
              count={suggestion.count}
            />
          </div>
        ))}
      </div>
    </div>
  );
};

/**
 * Numeric field suggestion with statistics
 */
export const NumericSuggestion = ({ 
  suggestion, 
  onApply, 
  fieldName,
  currentValue 
}) => {
  if (!suggestion) return null;

  const hasSuggestion = suggestion.suggested !== null && suggestion.suggested !== undefined;
  const isDifferent = hasSuggestion && currentValue != suggestion.suggested;

  if (!hasSuggestion) return null;

  return (
    <div className="numeric-suggestion">
      <button
        type="button"
        className={`suggestion-apply-btn ${isDifferent ? 'highlight' : ''}`}
        onClick={() => onApply(suggestion.suggested)}
        title={suggestion.tooltip}
        disabled={!isDifferent}
      >
        💡 Suggested: {suggestion.suggested}
        {isDifferent && ' (Click to apply)'}
      </button>
      <div className="numeric-stats">
        <span className="stat-item">Avg: {suggestion.average?.toFixed(2)}</span>
        <span className="stat-item">Max: {suggestion.max?.toFixed(2)}</span>
      </div>
    </div>
  );
};

/**
 * Auto-fill button for quick form population
 */
export const AutoFillButton = ({ 
  onClick, 
  loading = false, 
  disabled = false,
  fieldsCount = 0 
}) => {
  return (
    <button
      type="button"
      className="auto-fill-button"
      onClick={onClick}
      disabled={disabled || loading}
      title={`Auto-fill ${fieldsCount} fields with intelligent suggestions`}
    >
      {loading ? (
        <>⏳ Loading suggestions...</>
      ) : (
        <>✨ Auto-Fill Suggestions ({fieldsCount} fields)</>
      )}
    </button>
  );
};

/**
 * Smart combination suggestion (e.g., motor type + efficiency)
 */
export const SmartCombinationHint = ({ 
  title, 
  suggestion, 
  onApply 
}) => {
  if (!suggestion) return null;

  return (
    <div className="smart-combination-hint">
      <span className="hint-icon">🧠</span>
      <span className="hint-text">{title}: {suggestion}</span>
      <button
        type="button"
        className="hint-apply-btn"
        onClick={onApply}
      >
        Apply
      </button>
    </div>
  );
};

/**
 * Context info showing what data recommendations are based on
 */
export const RecommendationContext = ({ context }) => {
  if (!context || context.total_records_analyzed === 0) return null;

  return (
    <div className="recommendation-context">
      <span className="context-icon">📊</span>
      <span className="context-text">
        Based on {context.total_records_analyzed} recent records
        {context.project_context !== 'all_projects' && ` from project ${context.project_context}`}
      </span>
    </div>
  );
};

/**
 * Inline suggestion for text inputs
 */
export const InlineSuggestion = ({ 
  value, 
  onApply, 
  badge = 'suggested',
  visible = true 
}) => {
  if (!visible || !value) return null;

  return (
    <div className="inline-suggestion">
      <span className="inline-suggestion-value">💡 {value}</span>
      <button
        type="button"
        className="inline-apply-btn"
        onClick={() => onApply(value)}
      >
        Apply
      </button>
      <RecommendationBadge type={badge} />
    </div>
  );
};

export default {
  RecommendationBadge,
  SuggestionDropdown,
  NumericSuggestion,
  AutoFillButton,
  SmartCombinationHint,
  RecommendationContext,
  InlineSuggestion
};

import { useCallback, useEffect, useState } from 'react'
import {
  ArrowPathIcon,
  CheckCircleIcon,
  CircleStackIcon,
  ExclamationTriangleIcon,
  LinkIcon,
  WrenchScrewdriverIcon,
} from '@heroicons/react/24/outline'
import hrFoundationService from '../../services/hrFoundation.service'

const EmployeeDataQualityPanel = ({ employee }) => {
  const [report, setReport] = useState(null)
  const [loading, setLoading] = useState(true)
  const [repairing, setRepairing] = useState(false)
  const [error, setError] = useState('')

  const load = useCallback(async () => {
    const identifier = employee?.employee_master_id || employee?.user?.id || employee?.id
    if (!identifier) return
    setLoading(true)
    setError('')
    try {
      const canonical = employee?.employee_master_id
        ? { id: employee.employee_master_id }
        : await hrFoundationService.resolveEmployee(identifier)
      setReport(await hrFoundationService.getIdentityHealth(canonical.id))
    } catch (requestError) {
      setError(requestError?.response?.data?.detail || 'Employee identity health could not be loaded.')
    } finally {
      setLoading(false)
    }
  }, [employee?.employee_master_id, employee?.id, employee?.user?.id])

  useEffect(() => { load() }, [load])

  const repair = async () => {
    if (!report?.employee_id) return
    setRepairing(true)
    setError('')
    try {
      await hrFoundationService.repairIdentity(report.employee_id)
      await load()
    } catch (requestError) {
      setError(requestError?.response?.data?.detail || 'Identity repair could not be completed.')
    } finally {
      setRepairing(false)
    }
  }

  if (loading) return <div className="flex items-center justify-center gap-2 rounded-xl border border-slate-200 bg-white p-10 text-sm text-slate-500"><ArrowPathIcon className="h-4 w-4 animate-spin" /> Checking employee records…</div>

  if (error && !report) return <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{error}</div>

  return (
    <div className="mx-auto w-full max-w-5xl space-y-4">
      <section className={`rounded-xl border p-5 ${report?.healthy ? 'border-emerald-200 bg-emerald-50' : 'border-amber-200 bg-amber-50'}`}>
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex items-start gap-3">
            {report?.healthy ? <CheckCircleIcon className="h-7 w-7 text-emerald-700" /> : <ExclamationTriangleIcon className="h-7 w-7 text-amber-700" />}
            <div>
              <h3 className="font-bold text-slate-950">{report?.healthy ? 'Employee identity is consistent' : `${report?.issue_count || 0} data issue${report?.issue_count === 1 ? '' : 's'} found`}</h3>
              <p className="mt-1 text-sm text-slate-600">EmployeeMaster is the canonical record used to link HR, RBAC, payroll, onboarding and timesheets.</p>
            </div>
          </div>
          {!report?.healthy && <button type="button" onClick={repair} disabled={repairing} className="inline-flex items-center gap-2 rounded-lg bg-blue-700 px-3.5 py-2 text-xs font-bold text-white hover:bg-blue-800 disabled:opacity-60">{repairing ? <ArrowPathIcon className="h-4 w-4 animate-spin" /> : <WrenchScrewdriverIcon className="h-4 w-4" />} Repair from canonical record</button>}
        </div>
        {error && <p className="mt-3 text-sm text-red-700">{error}</p>}
      </section>

      {(report?.issues || []).length > 0 && <section className="overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
        <div className="border-b border-slate-200 px-5 py-4"><h3 className="text-sm font-bold text-slate-950">Field differences</h3></div>
        <div className="divide-y divide-slate-100">{report.issues.map((issue, index) => <div key={`${issue.system}-${issue.field}-${index}`} className="grid gap-2 px-5 py-3 text-sm sm:grid-cols-[120px_150px_1fr_1fr]"><span className="font-bold uppercase text-slate-500">{issue.system}</span><span className="font-semibold text-slate-800">{issue.field.replaceAll('_', ' ')}</span><span><span className="text-[10px] font-bold uppercase text-slate-400">Canonical</span><br />{issue.canonical || '—'}</span><span><span className="text-[10px] font-bold uppercase text-slate-400">Current</span><br />{issue.actual || '—'}</span></div>)}</div>
      </section>}

      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
        <div className="mb-4 flex items-center gap-2 border-b border-slate-100 pb-3"><LinkIcon className="h-5 w-5 text-blue-700" /><h3 className="text-sm font-bold text-slate-950">Linked system identifiers</h3><span className="ml-auto rounded-full bg-slate-100 px-2 py-1 text-xs font-bold text-slate-600">{report?.aliases?.length || 0}</span></div>
        {(report?.aliases || []).length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{report.aliases.map((alias) => <article key={alias.id} className="rounded-lg border border-slate-200 p-3"><div className="flex items-center gap-2"><CircleStackIcon className="h-4 w-4 text-slate-400" /><span className="text-[10px] font-bold uppercase tracking-wider text-slate-500">{alias.source} · {alias.identifier_type.replaceAll('_', ' ')}</span></div><p className="mt-2 break-all text-sm font-semibold text-slate-900">{alias.value}</p></article>)}</div> : <p className="text-sm text-slate-500">No linked identifiers were found.</p>}
        {(report?.conflicts || []).length > 0 && <div className="mt-4 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700">Conflicting identifiers require manual HR review and were not changed automatically.</div>}
      </section>
    </div>
  )
}

export default EmployeeDataQualityPanel

import { useSearchParams } from 'react-router-dom'
import OvertimeManagement from '../../pages/HR/OvertimeManagement'
import { radaiPrompt } from '../../services/radaiDialog'
import { useCallback, useEffect, useMemo, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import hrFoundationService from '../../services/hrFoundation.service'
import EmployeeTabLoading from './EmployeeTabLoading'

const TYPES = [
  ['overtime', 'Overtime', '', 'ClockIcon'],
  ['expense', 'Expense', 'Receipt, amount and business purpose', 'ReceiptPercentIcon'],
  ['travel', 'Travel', 'Business trip and travel authorization', 'PaperAirplaneIcon'],
  ['asset', 'Asset', 'Laptop, phone, software or other equipment', 'ComputerDesktopIcon'],
  ['hr_helpdesk', 'HR Helpdesk', 'HR letters, benefits and policy support', 'LifebuoyIcon'],
]
const EMPTY = { request_type: 'expense', title: '', description: '', amount: '', currency: 'AED', destination: '', start_date: '', end_date: '', category: '', priority: 'normal' }

const statusTone = (status) => ({
  pending: 'bg-amber-50 text-amber-700', approved: 'bg-blue-50 text-blue-700',
  fulfilled: 'bg-emerald-50 text-emerald-700', rejected: 'bg-rose-50 text-rose-700',
  cancelled: 'bg-slate-100 text-slate-600', in_progress: 'bg-violet-50 text-violet-700',
}[status] || 'bg-slate-100 text-slate-600')

export default function EmployeeServiceRequestsPanel({ employeeIdentifier }) {
  const [params, setParams] = useSearchParams()
  const overtimeSelected = params.get('request_type') === 'overtime' || params.get('tab') === 'overtime'
  const [employee, setEmployee] = useState(null)
  const [requests, setRequests] = useState([])
  const [form, setForm] = useState(EMPTY)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [message, setMessage] = useState('')

  const load = useCallback(async () => {
    if (!employeeIdentifier) return
    setLoading(true)
    try {
      const resolved = await hrFoundationService.resolveEmployee(employeeIdentifier)
      setEmployee(resolved)
      setRequests(await hrFoundationService.getServiceRequests())
    } catch (error) {
      setMessage(error?.response?.data?.detail || 'Could not load employee requests.')
    } finally { setLoading(false) }
  }, [employeeIdentifier])

  useEffect(() => { load() }, [load])
  const approvals = useMemo(() => requests.filter((item) => item.can_approve), [requests])

  const submit = async (event) => {
    event.preventDefault()
    if (!employee) return
    setSaving(true); setMessage('')
    try {
      const data = { ...form, employee: employee.id }
      if (form.request_type !== 'expense') delete data.amount
      if (form.request_type !== 'travel') { delete data.destination; delete data.start_date; delete data.end_date }
      await hrFoundationService.createServiceRequest(data)
      setForm(EMPTY); setMessage('Request submitted successfully.'); await load()
    } catch (error) {
      const data = error?.response?.data
      setMessage(typeof data === 'string' ? data : JSON.stringify(data || { detail: 'Request could not be submitted.' }))
    } finally { setSaving(false) }
  }

  const decide = async (item, decision) => {
    const note = decision === 'reject' ? (await radaiPrompt('Enter the rejection reason')) : ''
    if (decision === 'reject' && !note) return
    try { await hrFoundationService.decideServiceRequest(item.id, decision, note); await load() }
    catch (error) { setMessage(error?.response?.data?.detail || `Could not ${decision} request.`) }
  }

  if (loading && !overtimeSelected) return <EmployeeTabLoading message="Loading your service requests…" />
  return (
    <div className="space-y-5">
      <div className="flex flex-wrap gap-2">{TYPES.map(([id, label, , icon]) => {
        const Icon = HeroIcons[icon]
        const selected = overtimeSelected ? id === 'overtime' : form.request_type === id
        return <button type="button" key={id} onClick={() => {
          setForm({ ...EMPTY, request_type: id === 'overtime' ? 'expense' : id })
          const next = new URLSearchParams(params)
          next.set('tab', 'requests'); next.set('request_type', id); next.delete('request')
          setParams(next, { replace: true })
        }} className={`inline-flex items-center gap-2 rounded-lg border px-3 py-2 text-sm ${selected ? 'border-indigo-200 bg-indigo-50 text-indigo-700' : 'border-slate-200 bg-white text-slate-600'}`}><Icon className="h-4 w-4" />{label}</button>
      })}</div>
      {overtimeSelected ? <OvertimeManagement /> : <>

      {message && <div className="rounded-xl border border-blue-200 bg-blue-50 px-4 py-3 text-sm text-blue-800">{message}</div>}
      {approvals.length > 0 && (
        <section className="rounded-2xl border border-amber-200 bg-white shadow-sm">
          <div className="border-b border-amber-100 px-5 py-4"><h3 className="font-semibold text-slate-900">Manager approval inbox</h3><p className="text-xs text-slate-500">Requests from your team requiring action</p></div>
          <div className="divide-y divide-slate-100">{approvals.map((item) => <RequestRow key={item.id} item={item} onDecide={decide} />)}</div>
        </section>
      )}
      <div className="grid gap-5 xl:grid-cols-[420px_1fr]">
        <form onSubmit={submit} className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
          <h3 className="font-semibold text-slate-900">Create a request</h3>

          <div className="mt-4 space-y-3">
            <input required placeholder="Request title" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" />
            <textarea required rows={3} placeholder="Business reason and details" value={form.description} onChange={(e) => setForm({ ...form, description: e.target.value })} className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" />
            <div className="grid grid-cols-2 gap-3"><input placeholder="Category" value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><select value={form.priority} onChange={(e) => setForm({ ...form, priority: e.target.value })} className="rounded-lg border border-slate-300 px-3 py-2 text-sm"><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option><option value="low">Low</option></select></div>
            {form.request_type === 'expense' && <div className="grid grid-cols-[1fr_90px] gap-3"><input required min="0.01" step="0.01" type="number" placeholder="Amount" value={form.amount} onChange={(e) => setForm({ ...form, amount: e.target.value })} className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><input maxLength={3} value={form.currency} onChange={(e) => setForm({ ...form, currency: e.target.value.toUpperCase() })} className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /></div>}
            {form.request_type === 'travel' && <><input required placeholder="Destination" value={form.destination} onChange={(e) => setForm({ ...form, destination: e.target.value })} className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm" /><div className="grid grid-cols-2 gap-3"><input required type="date" value={form.start_date} onChange={(e) => setForm({ ...form, start_date: e.target.value })} className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><input required type="date" value={form.end_date} onChange={(e) => setForm({ ...form, end_date: e.target.value })} className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /></div></>}
            <button disabled={saving} className="w-full rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-50">{saving ? 'Submitting…' : 'Submit request'}</button>
          </div>
        </form>
        <section className="rounded-2xl border border-slate-200 bg-white shadow-sm">
          <div className="border-b border-slate-100 px-5 py-4"><h3 className="font-semibold text-slate-900">Request tracker</h3><p className="text-xs text-slate-500">Your requests and visible team requests</p></div>
          {requests.length ? <div className="divide-y divide-slate-100">{requests.map((item) => <RequestRow key={item.id} item={item} onDecide={decide} />)}</div> : <div className="p-10 text-center text-sm text-slate-500">No requests yet.</div>}
        </section>
      </div>
      </>}
    </div>
  )
}

function RequestRow({ item, onDecide }) {
  return <div className="flex flex-wrap items-center justify-between gap-3 px-5 py-4"><div><div className="flex items-center gap-2"><span className="font-medium text-slate-900">{item.title}</span><span className={`rounded-full px-2 py-0.5 text-xs ${statusTone(item.status)}`}>{item.status?.replaceAll('_', ' ')}</span></div><div className="mt-1 text-xs text-slate-500">{item.request_number} · {item.employee_name} · {item.request_type?.replaceAll('_', ' ')}{item.current_stage ? ` · ${item.current_stage}` : ''}</div></div>{item.can_approve && <div className="flex gap-2"><button onClick={() => onDecide(item, 'reject')} className="rounded-lg border border-rose-200 px-3 py-1.5 text-xs font-medium text-rose-700">Reject</button><button onClick={() => onDecide(item, 'approve')} className="rounded-lg bg-emerald-600 px-3 py-1.5 text-xs font-medium text-white">Approve</button></div>}</div>
}

import { Loader } from 'lucide-react'

/**
 * Shared loading state for every employee self-service tab.
 */
export default function EmployeeTabLoading({ message = 'Loading your employee profile…' }) {
  return (
    <div
      className="flex min-h-64 w-full items-center justify-center rounded-2xl bg-[#F0F2F5]"
      role="status"
      aria-live="polite"
      aria-label={message}
    >
      <div className="text-center">
        <Loader className="mx-auto mb-4 h-12 w-12 animate-spin text-blue-600" aria-hidden="true" />
        <p className="font-medium text-slate-600">{message}</p>
      </div>
    </div>
  )
}

import ProfileMetricCard from './ProfileMetricCard'
import { radaiPrompt } from '../../services/radaiDialog'
import { useCallback, useEffect, useMemo, useState } from 'react'
import {
  AcademicCapIcon, ChatBubbleLeftRightIcon, CheckCircleIcon,
  FlagIcon, PlusIcon, SparklesIcon, StarIcon, TrophyIcon,
} from '@heroicons/react/24/outline'
import hrFoundationService from '../../services/hrFoundation.service'
import EmployeeTabLoading from './EmployeeTabLoading'

const statusTone = (status) => ({ active: 'bg-emerald-100 text-emerald-700', completed: 'bg-blue-100 text-blue-700', submitted: 'bg-violet-100 text-violet-700', approved: 'bg-emerald-100 text-emerald-700', pending: 'bg-amber-100 text-amber-700' }[status] || 'bg-slate-100 text-slate-600')

const EmployeeTalentPerformancePanel = ({ employee, profileWorkspace = false }) => {
  const [employeeId, setEmployeeId] = useState('')
  const [data, setData] = useState({ cycles: [], goals: [], reviews: [], feedback: [], plans: [], talent: [], promotions: [] })
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [goalForm, setGoalForm] = useState({ title: '', description: '', weight: 20, due_date: '' })
  const [feedbackForm, setFeedbackForm] = useState({ feedback_type: 'recognition', content: '' })

  const load = useCallback(async () => {
    setLoading(true); setError('')
    try {
      const resolved = employee?.employee_master_id ? { id: employee.employee_master_id } : await hrFoundationService.resolveEmployee(employee?.user?.id || employee?.id)
      setEmployeeId(resolved.id)
      const requests = await Promise.allSettled([
        hrFoundationService.getPerformanceCycles(), hrFoundationService.getGoals({ employee: resolved.id }),
        hrFoundationService.getReviews({ employee: resolved.id }), hrFoundationService.getFeedback({ employee: resolved.id }),
        hrFoundationService.getDevelopmentPlans({ employee: resolved.id }), hrFoundationService.getTalentAssessments({ employee: resolved.id }),
        hrFoundationService.getPromotionCases({ employee: resolved.id }),
      ])
      const value = (index) => requests[index].status === 'fulfilled' ? requests[index].value : []
      setData({ cycles: value(0), goals: value(1), reviews: value(2), feedback: value(3), plans: value(4), talent: value(5), promotions: value(6) })
    } catch (requestError) {
      setError(requestError?.response?.data?.detail || 'Performance and talent records could not be loaded.')
    } finally { setLoading(false) }
  }, [employee?.employee_master_id, employee?.id, employee?.user?.id])

  useEffect(() => { load() }, [load])
  const activeCycle = useMemo(() => data.cycles.find((cycle) => cycle.status === 'active') || data.cycles[0], [data.cycles])

  const createGoal = async (event) => {
    event.preventDefault(); if (!activeCycle || !goalForm.title.trim()) return
    setSaving(true); setError('')
    try {
      const goal = await hrFoundationService.createGoal({ ...goalForm, employee: employeeId, cycle: activeCycle.id, goal_type: 'individual' })
      await hrFoundationService.submitGoal(goal.id)
      setGoalForm({ title: '', description: '', weight: 20, due_date: '' }); await load()
    } catch (requestError) { setError(requestError?.response?.data ? JSON.stringify(requestError.response.data) : 'Goal could not be created.') }
    finally { setSaving(false) }
  }

  const addCheckIn = async (goal) => {
    const raw = (await radaiPrompt('Enter progress percentage (0–100)', String(goal.progress || 0)))
    if (raw === null) return
    const progress = Number(raw)
    if (!Number.isFinite(progress) || progress < 0 || progress > 100) { setError('Progress must be between 0 and 100.'); return }
    setSaving(true)
    try { await hrFoundationService.checkInGoal({ goal: goal.id, progress, note: 'Progress update' }); await load() }
    catch (requestError) { setError(requestError?.response?.data ? JSON.stringify(requestError.response.data) : 'Check-in failed.') }
    finally { setSaving(false) }
  }

  const createFeedback = async (event) => {
    event.preventDefault(); if (!feedbackForm.content.trim()) return
    setSaving(true)
    try { await hrFoundationService.createFeedback({ ...feedbackForm, employee: employeeId, visibility: 'employee' }); setFeedbackForm({ feedback_type: 'recognition', content: '' }); await load() }
    catch (requestError) { setError(requestError?.response?.data ? JSON.stringify(requestError.response.data) : 'Feedback could not be saved.') }
    finally { setSaving(false) }
  }

  if (loading) return <EmployeeTabLoading message="Loading performance and talent records…" />

  const submittedReviews = data.reviews.filter((review) => ['submitted', 'acknowledged'].includes(review.status))
  const average = submittedReviews.length ? (submittedReviews.reduce((sum, review) => sum + Number(review.overall_score || 0), 0) / submittedReviews.length).toFixed(2) : '—'
  const latestTalent = data.talent[0]

  return <div className="space-y-5">
    {error && <div className="rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}
    <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
      {[[FlagIcon, 'Active goals', data.goals.filter((g) => g.status === 'active').length, 'text-blue-600'], [StarIcon, 'Review score', average, 'text-violet-600'], [AcademicCapIcon, 'Development plans', data.plans.filter((p) => p.status === 'active').length, 'text-emerald-600'], [TrophyIcon, 'Nine-box', latestTalent?.nine_box || 'Not assessed', 'text-amber-600']].map(([Icon, label, value, tone]) => profileWorkspace
        ? <ProfileMetricCard key={label} icon={<Icon />} label={label} value={value} tone={({ 'text-blue-600': 'blue', 'text-violet-600': 'purple', 'text-emerald-600': 'green', 'text-amber-600': 'amber' })[tone]} />
        : <div key={label} className="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><Icon className={`h-5 w-5 ${tone}`} /><p className="mt-3 text-2xl font-bold text-slate-950">{value}</p><p className="text-xs text-slate-500">{label}</p></div>)}
    </div>

    <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm">
      <div className="flex items-center justify-between border-b border-slate-100 pb-3"><div><h3 className="text-sm font-bold text-slate-950">Goals and KPIs</h3><p className="text-xs text-slate-500">{activeCycle ? activeCycle.name : 'HR must activate a performance cycle'}</p></div><FlagIcon className="h-5 w-5 text-blue-700" /></div>
      <div className="mt-4 space-y-3">{data.goals.length ? data.goals.map((goal) => <article key={goal.id} className="rounded-lg border border-slate-200 p-4"><div className="flex items-start justify-between gap-3"><div><p className="font-semibold text-slate-900">{goal.title}</p><p className="mt-1 text-xs text-slate-500">{goal.weight}% weight · Due {goal.due_date || 'not set'}</p></div><span className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase ${statusTone(goal.status)}`}>{goal.status}</span></div><div className="mt-3 h-2 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-blue-600" style={{ width: `${goal.progress || 0}%` }} /></div><div className="mt-2 flex items-center justify-between text-xs"><span className="font-bold text-blue-700">{goal.progress || 0}%</span>{['active', 'completed'].includes(goal.status) && <button type="button" onClick={() => addCheckIn(goal)} className="font-bold text-blue-700 hover:text-blue-900">Add check-in</button>}</div></article>) : <p className="py-5 text-center text-sm text-slate-400">No goals have been created for this cycle.</p>}</div>
      {activeCycle && <form onSubmit={createGoal} className="mt-5 grid gap-3 border-t border-slate-100 pt-4 sm:grid-cols-2"><input value={goalForm.title} onChange={(e) => setGoalForm({ ...goalForm, title: e.target.value })} placeholder="New goal title" required className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><input type="date" value={goalForm.due_date} onChange={(e) => setGoalForm({ ...goalForm, due_date: e.target.value })} min={activeCycle.start_date} max={activeCycle.end_date} className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><textarea value={goalForm.description} onChange={(e) => setGoalForm({ ...goalForm, description: e.target.value })} placeholder="Success criteria and description" className="rounded-lg border border-slate-300 px-3 py-2 text-sm sm:col-span-2" /><div className="flex items-center gap-2"><label className="text-xs font-semibold text-slate-600">Weight %</label><input type="number" min="0" max="100" value={goalForm.weight} onChange={(e) => setGoalForm({ ...goalForm, weight: Number(e.target.value) })} className="w-24 rounded-lg border border-slate-300 px-3 py-2 text-sm" /></div><button disabled={saving} className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-60"><PlusIcon className="h-4 w-4" /> Create and submit goal</button></form>}
    </section>

    <div className="grid gap-5 lg:grid-cols-2">
      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="mb-4 flex items-center gap-2"><StarIcon className="h-5 w-5 text-violet-700" /><h3 className="text-sm font-bold">Reviews and 360° feedback</h3></div>{data.reviews.length ? <div className="space-y-2">{data.reviews.map((review) => <div key={review.id} className="flex items-center justify-between rounded-lg bg-slate-50 p-3"><div><p className="text-sm font-semibold capitalize">{review.review_type.replaceAll('_', ' ')}</p><p className="text-xs text-slate-500">{review.reviewer_name}</p></div><div className="text-right"><p className="font-bold text-violet-700">{review.overall_score ? `${review.overall_score}/5` : 'Draft'}</p><span className={`text-[10px] font-bold uppercase ${statusTone(review.status)}`}>{review.status}</span></div></div>)}</div> : <p className="text-sm text-slate-400">No review assignments yet.</p>}</section>
      <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="mb-4 flex items-center gap-2"><AcademicCapIcon className="h-5 w-5 text-emerald-700" /><h3 className="text-sm font-bold">Development and career</h3></div>{data.plans.length ? data.plans.map((plan) => <div key={plan.id} className="mb-2 rounded-lg border border-slate-200 p-3"><div className="flex justify-between"><p className="text-sm font-semibold">{plan.title}</p><span className={`rounded-full px-2 py-0.5 text-[10px] font-bold uppercase ${statusTone(plan.status)}`}>{plan.status}</span></div><p className="mt-1 text-xs text-slate-500">Target role: {plan.target_role || 'Not set'} · {plan.actions?.length || 0} actions</p></div>) : <p className="text-sm text-slate-400">No development plan recorded.</p>}{data.promotions.map((item) => <div key={item.id} className="mt-3 rounded-lg bg-violet-50 p-3 text-sm text-violet-900"><SparklesIcon className="mr-2 inline h-4 w-4" />Promotion: {item.current_title} → {item.proposed_title} ({item.status})</div>)}</section>
    </div>

    <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="mb-4 flex items-center gap-2"><ChatBubbleLeftRightIcon className="h-5 w-5 text-cyan-700" /><h3 className="text-sm font-bold">Continuous feedback</h3></div><div className="space-y-2">{data.feedback.slice(0, 5).map((item) => <div key={item.id} className="rounded-lg bg-slate-50 p-3"><div className="flex justify-between text-xs"><span className="font-bold capitalize text-slate-700">{item.feedback_type}</span><span className="text-slate-400">{item.author_name}</span></div><p className="mt-1 text-sm text-slate-700">{item.content}</p>{item.acknowledged_at && <span className="mt-2 inline-flex items-center gap-1 text-[10px] font-bold text-emerald-700"><CheckCircleIcon className="h-3 w-3" /> Acknowledged</span>}</div>)}</div><form onSubmit={createFeedback} className="mt-4 grid gap-3 border-t border-slate-100 pt-4 sm:grid-cols-[160px_1fr_auto]"><select value={feedbackForm.feedback_type} onChange={(e) => setFeedbackForm({ ...feedbackForm, feedback_type: e.target.value })} className="rounded-lg border border-slate-300 px-3 py-2 text-sm"><option value="recognition">Recognition</option><option value="coaching">Coaching</option><option value="general">General</option></select><input value={feedbackForm.content} onChange={(e) => setFeedbackForm({ ...feedbackForm, content: e.target.value })} required placeholder="Write specific, actionable feedback" className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><button disabled={saving} className="rounded-lg border border-blue-200 px-4 py-2 text-sm font-bold text-blue-700">Add feedback</button></form></section>
  </div>
}

export default EmployeeTalentPerformancePanel

import { useCallback, useEffect, useState } from 'react'
import { CalendarDaysIcon, ClockIcon, PlusIcon } from '@heroicons/react/24/outline'
import hrFoundationService from '../../services/hrFoundation.service'
import EmployeeTabLoading from './EmployeeTabLoading'

const EmployeeWorkforceSchedulePanel = ({ employee }) => {
  const [employeeId, setEmployeeId] = useState('')
  const [assignments, setAssignments] = useState([])
  const [overtime, setOvertime] = useState([])
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')
  const [form, setForm] = useState({ work_date: new Date().toISOString().slice(0, 10), requested_hours: 1, reason: '' })

  const load = useCallback(async () => {
    setLoading(true); setError('')
    try {
      const resolved = employee?.employee_master_id ? { id: employee.employee_master_id } : await hrFoundationService.resolveEmployee(employee?.user?.id || employee?.id)
      setEmployeeId(resolved.id)
      const [shiftRows, overtimeRows] = await Promise.all([
        hrFoundationService.getShiftAssignments({ employee: resolved.id }),
        hrFoundationService.getOvertimeRequests({ employee: resolved.id }),
      ])
      setAssignments(shiftRows); setOvertime(overtimeRows)
    } catch (requestError) { setError(requestError?.response?.data?.detail || 'Schedule and overtime records could not be loaded.') }
    finally { setLoading(false) }
  }, [employee?.employee_master_id, employee?.id, employee?.user?.id])

  useEffect(() => { load() }, [load])

  const submit = async (event) => {
    event.preventDefault(); setSaving(true); setError('')
    try { await hrFoundationService.createOvertimeRequest({ ...form, employee: employeeId }); setForm({ work_date: new Date().toISOString().slice(0, 10), requested_hours: 1, reason: '' }); await load() }
    catch (requestError) { setError(requestError?.response?.data ? JSON.stringify(requestError.response.data) : 'Overtime request could not be submitted.') }
    finally { setSaving(false) }
  }

  if (loading) return <EmployeeTabLoading message="Loading shifts and overtime…" />

  return <div className="mx-auto w-full max-w-5xl space-y-5">
    {error && <div className="rounded-xl border border-red-200 bg-red-50 p-3 text-sm text-red-700">{error}</div>}
    <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center justify-between border-b border-slate-100 pb-3"><div><h3 className="text-sm font-bold text-slate-950">Published shift roster</h3><p className="text-xs text-slate-500">Upcoming and historical scheduled shifts</p></div><CalendarDaysIcon className="h-5 w-5 text-blue-700" /></div><div className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{assignments.length ? assignments.map((item) => <article key={item.id} className="rounded-lg border border-slate-200 p-3"><div className="flex items-center justify-between"><span className="text-xs font-bold text-blue-700">{item.date}</span><span className="rounded-full bg-slate-100 px-2 py-0.5 text-[10px] font-bold uppercase text-slate-600">{item.status}</span></div><p className="mt-2 font-semibold text-slate-900">{item.shift_name}</p><p className="mt-1 text-xs text-slate-500">{item.shift_code?.toUpperCase()} · {item.location || 'Default location'}</p></article>) : <p className="py-6 text-sm text-slate-400">No shift assignments have been published.</p>}</div></section>
    <section className="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><div className="flex items-center gap-2 border-b border-slate-100 pb-3"><ClockIcon className="h-5 w-5 text-violet-700" /><div><h3 className="text-sm font-bold text-slate-950">Overtime approval</h3><p className="text-xs text-slate-500">Recorded overtime is payroll-eligible only after workflow approval.</p></div></div><div className="mt-4 space-y-2">{overtime.map((item) => <div key={item.id} className="grid items-center gap-2 rounded-lg bg-slate-50 p-3 text-sm sm:grid-cols-[120px_90px_1fr_auto]"><span className="font-semibold">{item.work_date}</span><span>{item.requested_hours} hours</span><span className="truncate text-slate-600">{item.reason}</span><span className={`rounded-full px-2 py-1 text-[10px] font-bold uppercase ${item.status === 'approved' ? 'bg-emerald-100 text-emerald-700' : item.status === 'rejected' ? 'bg-red-100 text-red-700' : 'bg-amber-100 text-amber-700'}`}>{item.status}{item.current_stage ? ` · ${item.current_stage}` : ''}</span></div>)}</div><form onSubmit={submit} className="mt-5 grid gap-3 border-t border-slate-100 pt-4 sm:grid-cols-[160px_110px_1fr_auto]"><input type="date" value={form.work_date} onChange={(e) => setForm({ ...form, work_date: e.target.value })} required className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><input type="number" min="0.25" max="24" step="0.25" value={form.requested_hours} onChange={(e) => setForm({ ...form, requested_hours: Number(e.target.value) })} required className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><input value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} required placeholder="Business reason for overtime" className="rounded-lg border border-slate-300 px-3 py-2 text-sm" /><button disabled={saving} className="inline-flex items-center justify-center gap-2 rounded-lg bg-blue-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-60"><PlusIcon className="h-4 w-4" /> Submit</button></form></section>
  </div>
}

export default EmployeeWorkforceSchedulePanel

import useOrganizationCatalog from '../../hooks/useOrganizationCatalog'
import { organizationDepartmentOptions, organizationRoleLabels } from '../../utils/organizationCatalog'

export default function OrganizationSuggestions({ id }) {
  const { catalog } = useOrganizationCatalog()
  return <>
    <datalist id={`${id}-departments`}>
      {organizationDepartmentOptions(catalog).map(option => <option key={option.value} value={option.value} />)}
    </datalist>
    <datalist id={`${id}-roles`}>
