  </>
}

import { useEffect, useMemo, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import probationPerformanceService from '../../services/probationPerformance.service'

const RATING_FIELDS = [
  ['job_knowledge_rating', 'Job knowledge'],
  ['work_quality_rating', 'Quality of work'],
  ['reliability_rating', 'Reliability'],
  ['teamwork_rating', 'Teamwork'],
]

const RATING_LABELS = ['Needs support', 'Developing', 'Meets expectations', 'Very good', 'Excellent']

const INSIGHT_FIELDS = [
  ['achievements', 'Key achievements', HeroIcons.TrophyIcon, 'border-amber-200 bg-amber-50/60 text-amber-700'],
  ['strengths', 'Strengths', HeroIcons.SparklesIcon, 'border-emerald-200 bg-emerald-50/60 text-emerald-700'],
  ['improvement_areas', 'Areas for improvement', HeroIcons.ArrowTrendingUpIcon, 'border-orange-200 bg-orange-50/60 text-orange-700'],
  ['next_period_goals', 'Goals for the next period', HeroIcons.FlagIcon, 'border-blue-200 bg-blue-50/60 text-blue-700'],
  ['overall_comments', 'Overall assessment', HeroIcons.DocumentTextIcon, 'border-violet-200 bg-violet-50/60 text-violet-700'],
]

const roleCode = (role) => String(role?.code || role?.name || role || '').toLowerCase().replace(/[^a-z0-9]+/g, '_')

const canGenerateReport = (currentUser, employee) => {
  const user = currentUser?.user || currentUser
  if (user?.is_superuser) return true
  const roles = [...(currentUser?.roles || []), ...(user?.roles || [])].map(roleCode)
  if (roles.some((role) => ['super_admin', 'admin', 'hr_admin', 'hr_manager', 'human_resource'].includes(role))) return true
  const manager = employee?.manager_detail
  return Boolean(
    (manager?.id && currentUser?.id && String(manager.id) === String(currentUser.id)) ||
    (manager?.email && user?.email && manager.email.toLowerCase() === user.email.toLowerCase()),
  )
}

const formatDate = (value, withTime = false) => value
  ? new Intl.DateTimeFormat('en-GB', {
      day: 'numeric', month: 'short', year: 'numeric',
      ...(withTime ? { hour: '2-digit', minute: '2-digit' } : {}),
      timeZone: 'UTC',
    }).format(new Date(withTime ? value : `${value}T00:00:00Z`))
  : '—'

const errorMessage = (error, fallback) => {
  const data = error?.response?.data || error?.originalError?.response?.data
  if (typeof data?.detail === 'string') return data.detail
  if (typeof data === 'object' && data) {
    const first = Object.values(data).flat()[0]
    if (first) return String(first)
  }
  return fallback
}

const Metric = ({ label, value, suffix = '' }) => (
  <div className="rounded-xl border border-white/10 bg-white/10 px-3 py-2.5 backdrop-blur-sm">
    <p className="text-[10px] font-semibold uppercase tracking-wider text-blue-100">{label}</p>
    <p className="mt-0.5 text-lg font-bold text-white">{value ?? 0}{suffix}</p>
  </div>
)

export default function ProbationPerformancePanel({ employee, currentUser }) {
  const employeeId = employee?.user?.id
  const [report, setReport] = useState(null)
  const [form, setForm] = useState({})
  const [previewOpen, setPreviewOpen] = useState(false)
  const [loading, setLoading] = useState(false)
  const [saving, setSaving] = useState(false)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState('')
  const [success, setSuccess] = useState('')
  const mayGenerate = useMemo(() => canGenerateReport(currentUser, employee), [currentUser, employee])

  const applyReport = (next) => {
    setReport(next)
    setForm(next || {})
  }

  useEffect(() => {
    setPreviewOpen(false)
    setReport(null)
    setForm({})
    setLoading(false)
    setError('')
    setSuccess('')
  }, [employeeId])

  const loadPreview = async () => {
    if (!employeeId) return
    setPreviewOpen(true)
    setLoading(true)
    setError('')
    setSuccess('')
    try {
      const rows = await probationPerformanceService.getForEmployee(employeeId)
      applyReport(rows[0] || null)
    } catch (requestError) {
      setError(errorMessage(requestError, 'The 100-day report could not be loaded.'))
    } finally {
      setLoading(false)
    }
  }

  const generate = async () => {
    setSaving(true)
    setError('')
    try {
      const next = await probationPerformanceService.generate(employeeId)
      applyReport(next)
      setSuccess('100-day report generated from current RADAI records.')
    } catch (requestError) {
      setError(errorMessage(requestError, 'The report could not be generated.'))
    } finally {
      setSaving(false)
    }
  }

  const refreshInsights = async () => {
    setRefreshing(true)
    setError('')
    setSuccess('')
    try {
      const next = await probationPerformanceService.refreshInsights(report.id)
      applyReport(next)
      setSuccess('RADAI insights refreshed with the latest available records.')
    } catch (requestError) {
      setError(errorMessage(requestError, 'RADAI insights could not be refreshed.'))
    } finally {
      setRefreshing(false)
    }
  }

  const save = async (submit = false) => {
    setSaving(true)
    setError('')
    setSuccess('')
    const payload = Object.fromEntries([
      ...RATING_FIELDS.map(([field]) => [field, form[field] ? Number(form[field]) : null]),
      ['status', submit ? 'submitted' : 'draft'],
    ])
    try {
      const next = await probationPerformanceService.update(report.id, payload)
      applyReport(next)
      setSuccess(submit ? 'Performance report submitted.' : 'Manager ratings saved as a draft.')
    } catch (requestError) {
      setError(errorMessage(requestError, 'The report could not be saved.'))
    } finally {
      setSaving(false)
    }
  }

  if (!previewOpen) {
    return (
      <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
        <div className="flex flex-wrap items-center justify-between gap-5 px-6 py-6">
          <div className="flex items-start gap-4">
            <span className="flex h-11 w-11 items-center justify-center rounded-xl bg-blue-50 text-blue-700"><HeroIcons.DocumentChartBarIcon className="h-5 w-5" /></span>
            <div>
              <p className="text-[11px] font-bold uppercase tracking-[0.16em] text-blue-700">Probation checkpoint</p>
              <h3 className="mt-1 text-base font-bold text-slate-950">100-day performance report</h3>
              <p className="mt-1 text-sm text-slate-500">Open the report only when you are ready to review its RADAI insights.</p>
            </div>
          </div>
          <button type="button" onClick={loadPreview} disabled={!employeeId} className="inline-flex items-center gap-2 rounded-xl bg-blue-700 px-4 py-2.5 text-xs font-bold text-white shadow-sm hover:bg-blue-800 disabled:opacity-50"><HeroIcons.EyeIcon className="h-4 w-4" />Preview report</button>
        </div>
      </section>
    )
  }

  if (loading) return <div className="rounded-2xl border border-slate-200 bg-white p-10 text-center text-sm text-slate-500"><HeroIcons.ArrowPathIcon className="mx-auto mb-2 h-6 w-6 animate-spin text-blue-600" />Loading report preview…</div>

  if (!report) {
    return (
      <section className="overflow-hidden rounded-2xl border border-blue-200 bg-white shadow-sm">
        <div className="bg-gradient-to-br from-slate-950 via-blue-950 to-indigo-900 px-6 py-7 text-white">
          <div className="flex flex-wrap items-center justify-between gap-5">
            <div className="flex items-start gap-4"><span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/15"><HeroIcons.DocumentChartBarIcon className="h-6 w-6" /></span><div><p className="text-[11px] font-bold uppercase tracking-[0.2em] text-blue-200">Probation checkpoint</p><h3 className="mt-1 text-xl font-bold">100-day performance report</h3><p className="mt-1 max-w-xl text-sm text-blue-100">Generate an evidence-based review from RADAI activity, project, profile and attendance records.</p></div></div>
            {mayGenerate && <button type="button" onClick={generate} disabled={saving} className="rounded-xl bg-white px-4 py-2.5 text-xs font-bold text-blue-950 shadow-sm hover:bg-blue-50 disabled:opacity-50">{saving ? 'Generating…' : 'Generate from RADAI'}</button>}
          </div>
        </div>
        {(error || !mayGenerate) && <p className={`m-5 rounded-xl px-4 py-3 text-xs ${error ? 'bg-red-50 text-red-700' : 'bg-slate-50 text-slate-600'}`}>{error || 'Only HR or this employee’s direct line manager can generate the report.'}</p>}
      </section>
    )
  }

  const editable = report.can_edit !== false && report.status !== 'submitted'
  const snapshot = report.system_snapshot || {}
  const activity = snapshot.activity || {}
  const attendance = snapshot.attendance || {}
  const ratedFields = RATING_FIELDS.filter(([field]) => form[field])
  const averageRating = ratedFields.length
    ? RATING_FIELDS.reduce((sum, [field]) => sum + (Number(form[field]) || 0), 0) / ratedFields.length
    : 0

  return (
    <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
      <header className="bg-gradient-to-br from-slate-950 via-blue-950 to-indigo-900 px-6 py-6 text-white">
        <div className="flex flex-wrap items-start justify-between gap-4">
          <div className="flex items-start gap-4"><span className="flex h-12 w-12 items-center justify-center rounded-2xl bg-white/15 ring-1 ring-white/20"><HeroIcons.DocumentChartBarIcon className="h-6 w-6" /></span><div><div className="flex flex-wrap items-center gap-2"><h3 className="text-lg font-bold">100-day performance report</h3><span className={`rounded-full px-2.5 py-1 text-[10px] font-bold uppercase tracking-wide ${report.status === 'submitted' ? 'bg-emerald-400/20 text-emerald-100 ring-1 ring-emerald-300/30' : 'bg-amber-300/20 text-amber-100 ring-1 ring-amber-200/30'}`}>{report.status}</span></div><p className="mt-1 text-xs text-blue-100">Review period {formatDate(snapshot.period?.start || report.joining_date)} – {formatDate(snapshot.period?.end || report.due_date)} · Due {formatDate(report.due_date)}</p><p className="mt-1 text-xs text-blue-200">Created by {report.created_by_name || 'HR / Manager'}</p></div></div>
          {editable && <button type="button" onClick={refreshInsights} disabled={refreshing} className="inline-flex items-center gap-2 rounded-xl border border-white/20 bg-white/10 px-3.5 py-2 text-xs font-bold text-white hover:bg-white/15 disabled:opacity-50"><HeroIcons.ArrowPathIcon className={`h-4 w-4 ${refreshing ? 'animate-spin' : ''}`} />{refreshing ? 'Refreshing…' : 'Refresh RADAI insights'}</button>}
        </div>
        <div className="mt-5 grid grid-cols-2 gap-2.5 sm:grid-cols-3 lg:grid-cols-6">
          <Metric label="Activities" value={activity.total_actions} />
          <Metric label="Success rate" value={activity.success_rate} suffix="%" />
          <Metric label="AI requests" value={activity.ai_requests} />
          <Metric label="Features" value={activity.features_used} />
          <Metric label="Projects" value={snapshot.projects?.length || 0} />
          <Metric label="Attendance" value={attendance.days_present} suffix=" days" />
        </div>
      </header>

      <div className="space-y-7 p-6">
        <section>
          <div className="mb-4 flex flex-wrap items-end justify-between gap-2"><div><p className="text-[11px] font-bold uppercase tracking-[0.16em] text-blue-700">Manager assessment</p><h4 className="mt-1 text-base font-bold text-slate-950">Performance ratings</h4></div>{averageRating > 0 && <p className="text-sm font-semibold text-slate-600">Average <span className="ml-1 text-xl font-bold text-blue-700">{averageRating.toFixed(1)}</span><span className="text-slate-400"> / 5</span></p>}</div>
          <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-4">
            {RATING_FIELDS.map(([field, label]) => (
              <div key={field} className="rounded-xl border border-slate-200 bg-slate-50/70 p-3.5">
                <p className="text-xs font-bold text-slate-800">{label}</p>
                <div className="mt-3 flex gap-1.5">{[1,2,3,4,5].map((rating) => <button key={rating} type="button" disabled={!editable} title={RATING_LABELS[rating - 1]} onClick={() => setForm((previous) => ({ ...previous, [field]: rating }))} className={`flex h-8 flex-1 items-center justify-center rounded-lg text-xs font-bold transition ${Number(form[field]) === rating ? 'bg-blue-700 text-white shadow-sm' : 'border border-slate-200 bg-white text-slate-500 hover:border-blue-300 hover:text-blue-700'} disabled:cursor-default disabled:hover:border-slate-200`}>{rating}</button>)}</div>
                <p className="mt-2 min-h-4 text-[10px] font-medium text-slate-500">{form[field] ? RATING_LABELS[Number(form[field]) - 1] : 'Select 1–5'}</p>
              </div>
            ))}
          </div>
        </section>

        <section>
          <div className="mb-4 flex flex-wrap items-center justify-between gap-3"><div><p className="text-[11px] font-bold uppercase tracking-[0.16em] text-violet-700">System-generated analysis</p><h4 className="mt-1 text-base font-bold text-slate-950">RADAI performance insights</h4></div><div className="inline-flex items-center gap-1.5 rounded-full bg-violet-50 px-3 py-1.5 text-[10px] font-bold text-violet-700"><HeroIcons.SparklesIcon className="h-3.5 w-3.5" />Generated {formatDate(report.insights_generated_at, true)}</div></div>
          <div className="grid gap-4 lg:grid-cols-2">
            {INSIGHT_FIELDS.map(([field, label, InsightIcon, tone], index) => <article key={field} className={`rounded-xl border p-4 ${tone} ${index === INSIGHT_FIELDS.length - 1 ? 'lg:col-span-2' : ''}`}><div className="flex items-start gap-3"><span className="mt-0.5 flex h-8 w-8 shrink-0 items-center justify-center rounded-lg bg-white/80"><InsightIcon className="h-4 w-4" /></span><div><div className="flex items-center gap-2"><h5 className="text-xs font-bold uppercase tracking-wide">{label}</h5><HeroIcons.LockClosedIcon className="h-3 w-3 opacity-60" title="Generated from RADAI records" /></div><p className="mt-2 text-sm leading-6 text-slate-700">{report[field] || 'No system insight is currently available.'}</p></div></div></article>)}
          </div>
          <p className="mt-3 flex items-start gap-2 text-[11px] leading-5 text-slate-500"><HeroIcons.InformationCircleIcon className="mt-0.5 h-4 w-4 shrink-0" />Narrative sections are generated only from recorded RADAI data and cannot be manually edited. Refresh before submission to include the latest records.</p>
        </section>

        {error && <p className="rounded-xl bg-red-50 px-4 py-3 text-xs text-red-700">{error}</p>}
        {success && <p className="rounded-xl bg-emerald-50 px-4 py-3 text-xs text-emerald-700">{success}</p>}
        {editable && <footer className="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 pt-5"><p className="text-xs text-slate-500">All four manager ratings are required before submission.</p><div className="flex gap-2"><button type="button" disabled={saving} onClick={() => save(false)} className="rounded-xl border border-slate-300 px-4 py-2.5 text-xs font-bold text-slate-700 hover:bg-slate-50 disabled:opacity-50">Save ratings</button><button type="button" disabled={saving} onClick={() => save(true)} className="inline-flex items-center gap-2 rounded-xl bg-blue-700 px-4 py-2.5 text-xs font-bold text-white shadow-sm hover:bg-blue-800 disabled:opacity-50"><HeroIcons.PaperAirplaneIcon className="h-4 w-4" />{saving ? 'Submitting…' : 'Submit report'}</button></div></footer>}
        {report.status === 'submitted' && <p className="rounded-xl border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs text-emerald-800">Submitted by {report.submitted_by_name || 'HR / Manager'} on {formatDate(report.submitted_at, true)}. The report is now read-only.</p>}
      </div>
    </section>
  )
}

import ProfileMetricCard from './ProfileMetricCard'
import { useState } from 'react'
import { CalendarDaysIcon, ClockIcon, ChevronDownIcon } from '@heroicons/react/24/outline'

const pendingStatuses = ['PENDING', 'RM_APPROVED']
const statusMeta = {
  PENDING: ['Awaiting manager', 'border-amber-200 bg-amber-50 text-amber-800'],
  RM_APPROVED: ['Awaiting HR', 'border-indigo-200 bg-indigo-50 text-indigo-800'],
  APPROVED: ['Approved', 'border-emerald-200 bg-emerald-50 text-emerald-800'],
  RM_REJECTED: ['Declined by manager', 'border-rose-200 bg-rose-50 text-rose-800'],
  REJECTED: ['Declined by HR', 'border-rose-200 bg-rose-50 text-rose-800'],
  CANCELLED: ['Cancelled', 'border-slate-200 bg-slate-50 text-slate-600'],
}
const days = value => Number(value || 0).toLocaleString(undefined, { maximumFractionDigits: 1 })
const duration = value => `${days(value)} ${Number(value) === 1 ? 'day' : 'days'}`
const leaveName = request => request.leave_type_detail?.name || request.leave_type_display || 'Leave request'
const dateLabel = value => value ? new Date(`${value.slice(0, 10)}T12:00:00`).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' }) : '\u2014'

export function LeavePanel({ title, subtitle, children }) {
  return <section className="min-w-0 rounded-xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900">
    <div className="border-b border-slate-100 px-5 py-4 dark:border-slate-700"><h3 className="text-base font-semibold text-slate-900 dark:text-slate-100">{title}</h3>{subtitle && <p className="mt-1 text-xs text-slate-500 dark:text-slate-400">{subtitle}</p>}</div>
    <div className="p-5">{children}</div>
  </section>
}

export function ProfileLeaveSummary({ leaveRecord, requests = [], loading, typeConfig }) {
  const approved = requests.filter(request => request.status?.toUpperCase() === 'APPROVED')
  const pending = requests.filter(request => pendingStatuses.includes(request.status?.toUpperCase()))
  const metrics = [
    ['Available annual leave', leaveRecord ? `${days(leaveRecord.leave_balance)} days` : '\u2014', leaveRecord ? `${days(leaveRecord.total_earned)} days earned` : 'Balance not configured', 'blue'],
    ['Approved leave', `${days(approved.reduce((total, request) => total + Number(request.days_requested || 0), 0))} days`, 'Across loaded approved requests', 'emerald'],
    ['Awaiting approval', pending.length, `${pending.filter(request => request.status?.toUpperCase() === 'PENDING').length} with manager / ${pending.filter(request => request.status?.toUpperCase() === 'RM_APPROVED').length} with HR`, 'amber'],
    ['Encashed annual leave', leaveRecord ? `${days(leaveRecord.total_encashed)} days` : '\u2014', 'Recorded leave encashment', 'indigo'],
  ]
  return <div className="space-y-3">
    <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-4" aria-busy={loading}>
      {metrics.map(([label, value, sub, tone]) => <ProfileMetricCard key={label} icon={<CalendarDaysIcon />} label={label} value={loading ? '\u2014' : value} sub={sub} tone={tone === 'emerald' ? 'green' : tone === 'indigo' ? 'purple' : tone} />)}
    </div>
    <details className="rounded-xl border border-slate-200 bg-white dark:border-slate-700 dark:bg-slate-900">
      <summary className="cursor-pointer px-5 py-3 text-sm font-medium text-slate-700 dark:text-slate-200">Leave types and allowances <span className="ml-2 text-xs font-normal text-slate-500">View breakdown</span></summary>
      <div className="overflow-x-auto border-t border-slate-100 px-5 pb-3 dark:border-slate-700"><table className="w-full text-left text-sm"><thead><tr className="text-xs text-slate-500"><th className="py-3 font-medium">Leave type</th><th className="py-3 text-right font-medium">Configured allowance</th><th className="py-3 text-right font-medium">Approved days*</th></tr></thead><tbody className="divide-y divide-slate-100 dark:divide-slate-700">{Object.entries(typeConfig).filter(([, config]) => config.enabled !== false).map(([key, config]) => {
        const usage = approved.filter(request => (request.leave_type_detail?.category || '').toLowerCase() === key || (!request.leave_type_detail?.category && leaveName(request).toLowerCase() === config.label.toLowerCase())).reduce((total, request) => total + Number(request.days_requested || 0), 0)
        const allowance = key === 'annual' ? leaveRecord?.annual_entitlement ?? config.entitlement : config.entitlement
        return <tr key={key}><td className="py-2.5 text-slate-700 dark:text-slate-200">{config.label}</td><td className="py-2.5 text-right text-slate-500">{allowance > 0 ? `${days(allowance)} days` : 'As applicable'}</td><td className="py-2.5 text-right tabular-nums text-slate-700 dark:text-slate-200">{loading ? '\u2014' : days(usage)}</td></tr>
      })}</tbody></table><p className="mt-2 text-xs text-slate-500">*From loaded approved requests. Eligibility and available balances are confirmed by HR.</p></div>
    </details>
  </div>
}

export function ProfileLeaveRequests({ requests = [], loading }) {
  const [filter, setFilter] = useState('all')
  const options = [['all', 'All requests'], ['pending', 'Awaiting approval'], ['approved', 'Approved'], ['closed', 'Closed']]
  const visible = [...requests].filter(request => {
    const status = request.status?.toUpperCase()
    return filter === 'all' || (filter === 'pending' && pendingStatuses.includes(status)) || (filter === 'approved' && status === 'APPROVED') || (filter === 'closed' && ['REJECTED', 'RM_REJECTED', 'CANCELLED'].includes(status))
  }).sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')))
  return <LeavePanel title="My leave requests" subtitle="Track your request, current approver and decision history.">
    <div className="mb-4 flex flex-wrap gap-2" aria-label="Filter leave requests">{options.map(([id, label]) => <button key={id} type="button" onClick={() => setFilter(id)} aria-pressed={filter === id} className={`rounded-lg border px-3 py-1.5 text-xs font-medium ${filter === id ? 'border-indigo-300 bg-indigo-50 text-indigo-800 dark:border-indigo-700 dark:bg-indigo-950 dark:text-indigo-200' : 'border-slate-200 text-slate-600 hover:bg-slate-50 dark:border-slate-700 dark:text-slate-300 dark:hover:bg-slate-800'}`}>{label}</button>)}</div>
    {loading ? <p role="status" className="py-10 text-center text-sm text-slate-500">Loading your requests...</p> : !visible.length ? <div className="rounded-lg border border-dashed border-slate-200 px-4 py-12 text-center dark:border-slate-700"><CalendarDaysIcon className="mx-auto h-7 w-7 text-slate-400" /><p className="mt-3 text-sm font-medium text-slate-700 dark:text-slate-200">{requests.length ? 'No requests match this filter' : 'Your next break starts here'}</p><p className="mt-1 text-xs text-slate-500">{requests.length ? 'Choose another status to see your requests.' : 'Submit a leave request to start the approval process.'}</p></div> : <div className="divide-y divide-slate-100 dark:divide-slate-700">{visible.map(request => {
      const status = request.status?.toUpperCase()
      const [label, tone] = statusMeta[status] || [request.status_display || 'Unknown', 'border-slate-200 bg-slate-50 text-slate-600']
      return <details key={request.id} className="group py-3 first:pt-0">
        <summary className="flex cursor-pointer list-none flex-wrap items-center justify-between gap-3 rounded-lg py-1 [&::-webkit-details-marker]:hidden">
          <div className="min-w-0"><p className="text-sm font-semibold text-slate-900 dark:text-slate-100">{leaveName(request)} <span className="ml-2 font-normal text-slate-500">{duration(request.days_requested ?? request.duration_days)}</span></p><p className="mt-1 text-xs text-slate-500">{dateLabel(request.start_date)} to {dateLabel(request.end_date)}</p></div>
          <div className="flex items-center gap-2"><span className={`rounded-md border px-2 py-1 text-xs font-medium ${tone}`}>{label}</span><ChevronDownIcon className="h-4 w-4 text-slate-400 group-open:rotate-180" /></div>
        </summary>
        {pendingStatuses.includes(status) && <p className="mt-2 flex items-center gap-1.5 text-xs text-slate-500"><ClockIcon className="h-3.5 w-3.5" />Next: {status === 'PENDING' ? request.line_manager_name || 'Line manager review' : 'HR final review'}</p>}
        <div className="mt-3 space-y-3 rounded-lg bg-slate-50 p-3 text-xs text-slate-600 dark:bg-slate-800 dark:text-slate-300"><p className="whitespace-pre-wrap"><span className="font-medium">Reason: </span>{request.reason || 'No reason provided.'}</p><ol className="space-y-2"><li>Submitted / {dateLabel(request.created_at)}</li><li>Line manager / {request.rm_reviewed_by_name || (status === 'PENDING' ? 'Awaiting review' : 'No recorded decision')}{request.rm_reviewed_at && ` / ${dateLabel(request.rm_reviewed_at)}`}{request.rm_note && <p className="mt-1 whitespace-pre-wrap">{request.rm_note}</p>}</li><li>HR / {request.reviewed_by_name || (status === 'RM_APPROVED' ? 'Awaiting review' : status === 'PENDING' ? 'After manager approval' : 'No recorded decision')}{request.reviewed_at && ` / ${dateLabel(request.reviewed_at)}`}{request.reviewer_note && <p className="mt-1 whitespace-pre-wrap">{request.reviewer_note}</p>}</li></ol></div>
      </details>
    })}<p className="pt-3 text-xs text-slate-500">{visible.length} of {requests.length} loaded requests</p></div>}
  </LeavePanel>
}

import React, { useEffect, useMemo, useRef, useState } from 'react'
import { useNavigate } from 'react-router-dom'
import {
  BellIcon,
  ChartBarSquareIcon,
  CheckBadgeIcon,
  ClockIcon,
  DocumentTextIcon,
  MagnifyingGlassIcon,
  ShieldCheckIcon,
  Squares2X2Icon,
  UserCircleIcon,
  UsersIcon,
  XMarkIcon,
} from '@heroicons/react/24/outline'
import { HEADER_SEARCH_CONFIG, HEADER_SEARCH_ITEMS } from '../../config/headerSearch.config'
import { getAllFeatures } from '../../config/featuresCatalog.config'

const ADMIN_MODULE_CODES = new Set([
  'admin_dashboard',
  'user_mgmt',
  'role_access_mgmt',
  'wrench_integration',
  'ai_champion',
  'enquiry_management',
])

const SEARCH_ICONS = {
  bell: BellIcon,
  clock: ClockIcon,
  dashboard: ChartBarSquareIcon,
  document: DocumentTextIcon,
  module: Squares2X2Icon,
  search: MagnifyingGlassIcon,
  shield: ShieldCheckIcon,
  user: UserCircleIcon,
  users: UsersIcon,
  workflow: CheckBadgeIcon,
}

const normalise = (value) => String(value || '').trim().toLowerCase()

const SEARCH_PROMPTS = [
  HEADER_SEARCH_CONFIG.placeholder,
  'Find employees, projects, and approvals...',
  'Search policies, documents, and requests...',
  'Open any RADAI workspace...',
]

const GlobalSearch = ({ user, rbacData }) => {
  const navigate = useNavigate()
  const rootRef = useRef(null)
  const desktopInputRef = useRef(null)
  const mobileInputRef = useRef(null)
  const [open, setOpen] = useState(false)
  const [query, setQuery] = useState('')
  const [activeIndex, setActiveIndex] = useState(0)
  const [inputFocused, setInputFocused] = useState(false)
  const [animatedPlaceholder, setAnimatedPlaceholder] = useState(SEARCH_PROMPTS[0])

  const userData = user?.user || user
  const moduleCodes = useMemo(
    () => new Set((rbacData?.modules || []).map((module) => normalise(module.code))),
    [rbacData],
  )
  const hasSuperAdminAccess = Boolean(
    userData?.is_superuser ||
    user?.roles?.some((role) => role.code === 'super_admin'),
  )
  const hasAdminAccess = Boolean(
    hasSuperAdminAccess ||
    user?.roles?.some((role) => ['admin', 'ict_admin'].includes(role.code)) ||
    [...moduleCodes].some((code) => ADMIN_MODULE_CODES.has(code)),
  )

  const catalogItems = useMemo(
    () => getAllFeatures()
      .filter((feature) => Boolean(feature.path))
      .map((feature) => ({
        id: `feature-${feature.id}`,
        label: feature.name,
        description: feature.description || feature.longDescription || 'Open platform module',
        category: feature.categoryName || 'Modules',
        path: feature.path,
        icon: 'module',
        moduleCode: feature.moduleCode,
        keywords: [
          feature.shortName,
          feature.moduleCode,
          feature.status?.label,
          ...(feature.capabilities || []),
        ].filter(Boolean),
      })),
    [],
  )

  const indexedItems = useMemo(() => {
    const seenPaths = new Set()
    return [...HEADER_SEARCH_ITEMS, ...catalogItems].filter((item) => {
      const pathKey = String(item.path).toLowerCase()
      if (seenPaths.has(pathKey)) return false
      seenPaths.add(pathKey)
      return true
    })
  }, [catalogItems])

  const availableItems = useMemo(
    () => indexedItems.filter((item) => {
      if (item.adminOnly && !hasAdminAccess) return false
      if (item.moduleCode && !hasSuperAdminAccess && !moduleCodes.has(normalise(item.moduleCode))) return false
      return true
    }),
    [hasAdminAccess, hasSuperAdminAccess, indexedItems, moduleCodes],
  )

  const results = useMemo(() => {
    const term = normalise(query)
    if (!term) return availableItems.slice(0, HEADER_SEARCH_CONFIG.resultLimit)
    return availableItems
      .map((item) => {
        const label = normalise(item.label)
        const searchable = normalise([
          item.label,
          item.description,
          item.category,
          ...(item.keywords || []),
        ].join(' '))
        const score = label === term ? 3 : label.startsWith(term) ? 2 : searchable.includes(term) ? 1 : 0
        return { item, score }
      })
      .filter(({ score }) => score > 0)
      .sort((a, b) => b.score - a.score || a.item.label.localeCompare(b.item.label))
      .slice(0, HEADER_SEARCH_CONFIG.resultLimit)
      .map(({ item }) => item)
  }, [availableItems, query])

  useEffect(() => {
    setActiveIndex(0)
  }, [query])

  useEffect(() => {
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches
    if (reducedMotion || inputFocused || query) {
      setAnimatedPlaceholder(SEARCH_PROMPTS[0])
      return undefined
    }

    let promptIndex = 0
    let displayedText = SEARCH_PROMPTS[0]
    let phase = 'hold'
    let timer

    const advancePrompt = () => {
      if (phase === 'hold') {
        phase = 'delete'
        timer = window.setTimeout(advancePrompt, 22)
        return
      }

      if (phase === 'delete') {
        displayedText = displayedText.slice(0, -1)
        setAnimatedPlaceholder(displayedText)
        if (displayedText.length === 0) {
          promptIndex = (promptIndex + 1) % SEARCH_PROMPTS.length
          phase = 'type'
        }
        timer = window.setTimeout(advancePrompt, 22)
        return
      }

      const nextPrompt = SEARCH_PROMPTS[promptIndex]
      displayedText = nextPrompt.slice(0, displayedText.length + 1)
      setAnimatedPlaceholder(displayedText)
      if (displayedText === nextPrompt) phase = 'hold'
      timer = window.setTimeout(advancePrompt, displayedText === nextPrompt ? 2200 : 38)
    }

    timer = window.setTimeout(advancePrompt, 2200)
    return () => window.clearTimeout(timer)
  }, [inputFocused, query])

  useEffect(() => {
    const handlePointerDown = (event) => {
      if (rootRef.current && !rootRef.current.contains(event.target)) setOpen(false)
    }
    const handleShortcut = (event) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') {
        event.preventDefault()
        setOpen(true)
        window.setTimeout(() => {
          const target = window.matchMedia('(min-width: 768px)').matches
            ? desktopInputRef.current
            : mobileInputRef.current
          target?.focus()
        }, 0)
      }
      if (event.key === 'Escape') setOpen(false)
    }
    document.addEventListener('mousedown', handlePointerDown)
    document.addEventListener('keydown', handleShortcut)
    return () => {
      document.removeEventListener('mousedown', handlePointerDown)
      document.removeEventListener('keydown', handleShortcut)
    }
  }, [])

  const selectResult = (item) => {
    setOpen(false)
    setQuery('')
    navigate(item.path)
  }

  const handleKeyDown = (event) => {
    if (event.key === 'ArrowDown') {
      event.preventDefault()
      setActiveIndex((index) => Math.min(index + 1, results.length - 1))
    } else if (event.key === 'ArrowUp') {
      event.preventDefault()
      setActiveIndex((index) => Math.max(index - 1, 0))
    } else if (event.key === 'Enter' && results[activeIndex]) {
      event.preventDefault()
      selectResult(results[activeIndex])
    }
  }

  const inputProps = {
    value: query,
    onChange: (event) => setQuery(event.target.value),
    onFocus: () => {
      setInputFocused(true)
      setOpen(true)
    },
    onBlur: () => setInputFocused(false),
    onKeyDown: handleKeyDown,
    placeholder: animatedPlaceholder,
    role: 'combobox',
    'aria-label': 'Global search',
    'aria-expanded': open,
    'aria-controls': 'global-search-results',
    'aria-autocomplete': 'list',
  }

  return (
    <div ref={rootRef} className="relative flex w-full max-w-4xl justify-start">
      <div className="hidden w-full md:block">
        <div className="relative h-full w-full rounded-lg border border-slate-200 bg-slate-50 transition-colors hover:border-slate-300 hover:bg-white focus-within:border-blue-400 focus-within:bg-white focus-within:ring-2 focus-within:ring-blue-100 dark:border-slate-700 dark:bg-slate-900/50 dark:hover:border-slate-600 dark:hover:bg-slate-900 dark:focus-within:border-blue-500 dark:focus-within:ring-blue-950">
          <MagnifyingGlassIcon className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
          <input
            ref={desktopInputRef}
            {...inputProps}
            className="h-10 w-full rounded-lg bg-transparent pl-9 pr-20 text-sm text-slate-800 outline-none placeholder:text-slate-400 dark:text-slate-100 dark:placeholder:text-slate-500"
          />
          <span className="pointer-events-none absolute right-2.5 top-1/2 -translate-y-1/2 rounded border border-slate-200 bg-white px-1.5 py-0.5 text-[10px] font-semibold text-slate-400 dark:border-slate-600 dark:bg-slate-800 dark:text-slate-500">
            Ctrl K
          </span>
        </div>
      </div>

      <button
        type="button"
        onClick={() => {
          setOpen(true)
          window.setTimeout(() => mobileInputRef.current?.focus(), 0)
        }}
        className="inline-flex h-9 w-9 items-center justify-center rounded-lg text-slate-600 hover:bg-slate-100 hover:text-slate-950 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-500 dark:text-slate-300 dark:hover:bg-slate-700 dark:hover:text-white md:hidden"
        aria-label="Open global search"
      >
        <MagnifyingGlassIcon className="h-5 w-5" />
      </button>

      {open && (
        <div className="fixed left-4 right-4 top-16 overflow-hidden rounded-xl border border-slate-200/80 bg-white text-slate-900 shadow-[0_20px_50px_rgba(15,23,42,0.2)] ring-1 ring-slate-900/5 md:absolute md:left-0 md:right-0 md:top-full md:mt-2 dark:border-slate-700 dark:bg-slate-900 dark:text-slate-100">
          <div className="flex items-center gap-2 border-b border-slate-100 p-3 md:hidden dark:border-slate-800">
            <MagnifyingGlassIcon className="h-5 w-5 text-slate-400" />
            <input
              ref={mobileInputRef}
              {...inputProps}
              className="min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-slate-400"
            />
            <button type="button" onClick={() => setOpen(false)} className="rounded-lg p-1 text-slate-400 hover:bg-slate-100" aria-label="Close search">
              <XMarkIcon className="h-5 w-5" />
            </button>
          </div>

          <div className="flex items-center justify-between px-4 pb-2 pt-3">
            <span className="text-[10px] font-bold uppercase tracking-[0.16em] text-slate-400">
              {query ? 'Search results' : HEADER_SEARCH_CONFIG.quickAccessLabel}
            </span>
            <span className="hidden text-[10px] text-slate-400 md:block">↑↓ Navigate · Enter Open · Esc Close</span>
          </div>

          <div id="global-search-results" role="listbox" className="max-h-[min(420px,65vh)] overflow-y-auto px-2 pb-2">
            {results.map((item, index) => {
              const Icon = SEARCH_ICONS[item.icon] || MagnifyingGlassIcon
              const active = index === activeIndex
              return (
                <button
