            </div>
          </div>
        </div>

        {/* Trust Signals */}
        <div className="px-8 py-4">
          <div className="grid grid-cols-2 gap-2">
            {trustSignals.map((signal) => (
              <div key={signal} className="flex items-center gap-2 text-xs text-gray-400">
                <svg className="w-4 h-4 flex-shrink-0" style={{ color: theme.secondary }} fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                </svg>
                <span>{signal}</span>
              </div>
            ))}
          </div>
        </div>

        {/* Technical Details (Expandable) */}
        <div className="px-8 py-4">
          <button
            onClick={() => setShowTechnical(!showTechnical)}
            className="w-full flex items-center justify-between p-3 rounded-lg transition-all"
            style={{ background: 'rgba(255, 255, 255, 0.03)' }}
          >
            <span className="text-xs font-semibold text-gray-300">Technical Details</span>
            <svg
              className={`w-4 h-4 text-gray-400 transition-transform ${showTechnical ? 'rotate-180' : ''}`}
              fill="none" stroke="currentColor" viewBox="0 0 24 24"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          </button>

          {showTechnical && (
            <div className="mt-3 p-4 rounded-lg text-xs text-gray-400 space-y-2"
              style={{
                background: 'rgba(0, 0, 0, 0.2)',
                animation: 'slideDown 0.2s ease-out'
              }}
            >
              <div className="flex justify-between">
                <span>Download Size:</span>
                <span className="text-white font-semibold">{technicalInfo.size}</span>
              </div>
              <div className="flex justify-between">
                <span>Platform:</span>
                <span className="text-white font-semibold">{technicalInfo.platform}</span>
              </div>
              <div className="flex justify-between">
                <span>Requirements:</span>
                <span className="text-white font-semibold">{technicalInfo.requirements}</span>
              </div>
              <div className="flex justify-between">
                <span>Updates:</span>
                <span className="text-white font-semibold">{technicalInfo.updates}</span>
              </div>
              <div className="flex justify-between">
                <span>Security:</span>
                <span className="text-white font-semibold">{technicalInfo.security}</span>
              </div>
            </div>
          )}
        </div>

        {/* Action Buttons */}
        <div className="px-8 py-6 flex gap-3">
          <button
            onClick={onInstall}
            className="flex-1 py-4 rounded-xl font-bold text-white transition-all hover:scale-105 flex items-center justify-center gap-2 shadow-lg"
            style={{
              background: cta.primary.gradient,
              boxShadow: '0 8px 24px rgba(42, 167, 132, 0.3)'
            }}
          >
            <span className="text-xl">{cta.primary.icon}</span>
            <span>{cta.primary.text}</span>
          </button>

          <button
            onClick={onClose}
            className="px-6 py-4 rounded-xl font-semibold text-gray-300 transition-all hover:bg-white/5"
            style={{ border: '1px solid rgba(255, 255, 255, 0.1)' }}
          >
            <span className="text-sm">{cta.secondary.icon}</span>
            <span className="ml-2 text-sm">{cta.secondary.text}</span>
          </button>
        </div>
      </div>

      {/* Animations */}
      <style>{`
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }

        @keyframes modalPop {
          from {
            opacity: 0;
            transform: scale(0.9) translateY(30px);
          }
          to {
            opacity: 1;
            transform: scale(1) translateY(0);
          }
        }

        @keyframes slideInUp {
          from {
            opacity: 0;
            transform: translateY(20px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }

        @keyframes fadeInScale {
          from {
            opacity: 0;
            transform: scale(0.8);
          }
          to {
            opacity: 1;
            transform: scale(1);
          }
        }

        @keyframes slideDown {
          from {
            opacity: 0;
            max-height: 0;
          }
          to {
            opacity: 1;
            max-height: 500px;
          }
        }

        @keyframes logoGlow {
          0%, 100% {
            opacity: 0.5;
            transform: scale(1);
          }
          50% {
            opacity: 0.8;
            transform: scale(1.05);
          }
        }
      `}</style>
    </div>
  )
}

export default PWAInstallModal

import { radaiAlert } from '../services/radaiDialog'
import React, { useState, useEffect } from 'react'
import PWAInstallModal from './PWAInstallModal'

/**
 * PWA Install Prompt Component
 * Shows an install button for desktop and mobile PWA installation
 * 
 * Strategy:
 * - Always shows button by default (except if already installed)
 * - Captures beforeinstallprompt event when available
 * - Provides fallback instructions if browser doesn't support PWA
 */
const PWAInstallPrompt = () => {
  const [deferredPrompt, setDeferredPrompt] = useState(null)
  const [showInstall, setShowInstall] = useState(true) // Show by default
  const [isInstalled, setIsInstalled] = useState(false)
  const [showModal, setShowModal] = useState(false)
  const [debugInfo, setDebugInfo] = useState({ hasPrompt: false, swReady: false })

  useEffect(() => {
    console.log('🚀 PWA: Component mounted, checking installation status...')
    
    // Check if already installed (standalone mode)
    if (window.matchMedia('(display-mode: standalone)').matches) {
      setIsInstalled(true)
      setShowInstall(false)
      console.log('✅ PWA: Already installed (running in standalone mode)')
      return
    }

    // Check if running as PWA on iOS
    if (window.navigator.standalone === true) {
      setIsInstalled(true)
      setShowInstall(false)
      console.log('✅ PWA: Already installed (iOS standalone)')
      return
    }

    // Show the install button by default
    setShowInstall(true)
    console.log('📱 PWA: Install button visible')

    // Listen for the beforeinstallprompt event
    const handleBeforeInstallPrompt = (e) => {
      console.log('✅✅✅ PWA: beforeinstallprompt event captured! Browser supports native install!')
      // Prevent the mini-infobar from appearing on mobile
      e.preventDefault()
      // Stash the event so it can be triggered later
      setDeferredPrompt(e)
      setDebugInfo(prev => ({ ...prev, hasPrompt: true }))
      // Ensure button is visible
      setShowInstall(true)
    }

    // Listen for successful installation
    const handleAppInstalled = () => {
      console.log('🎉 PWA: App installed successfully!')
      setIsInstalled(true)
      setShowInstall(false)
      setDeferredPrompt(null)
    }

    window.addEventListener('beforeinstallprompt', handleBeforeInstallPrompt)
    window.addEventListener('appinstalled', handleAppInstalled)

    // Check service worker status
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.getRegistrations().then(registrations => {
        console.log(`✅ PWA: ${registrations.length} service worker(s) registered`)
        if (registrations.length > 0) {
          registrations.forEach(reg => {
            console.log('   - SW State:', reg.active ? reg.active.state : 'no active worker')
          })
        }
      })
      
      navigator.serviceWorker.ready.then(() => {
        console.log('✅ PWA: Service Worker is ready and active')
        setDebugInfo(prev => ({ ...prev, swReady: true }))
      }).catch(err => {
        console.error('❌ PWA: Service Worker error:', err)
      })
    } else {
      console.warn('⚠️ PWA: Service Workers not supported in this browser')
    }

    // Debug: Log current URL and protocol
    console.log(`📍 PWA: Running on ${window.location.protocol}//${window.location.host}`)
    console.log(`🔐 PWA: HTTPS: ${window.location.protocol === 'https:'}`)
    
    // Check after a delay if prompt was captured
    setTimeout(() => {
      if (!deferredPrompt) {
        console.warn('⚠️ PWA: No beforeinstallprompt event after 2 seconds')
        console.warn('💡 This is NORMAL on localhost - browser may not fire the event in dev mode')
        console.warn('💡 Users can still install via browser menu (⋮) → "Install app"')
      }
    }, 2000)

    return () => {
      window.removeEventListener('beforeinstallprompt', handleBeforeInstallPrompt)
      window.removeEventListener('appinstalled', handleAppInstalled)
    }
  }, [])

  const handleInstallClick = async () => {
    console.log('🖱️ PWA: Install button clicked!')
    console.log('   - Has deferred prompt:', !!deferredPrompt)
    console.log('   - Service Worker ready:', debugInfo.swReady)
    
    // If we have the native prompt ready, use it immediately
    if (deferredPrompt) {
      console.log('🚀 PWA: Using native browser install prompt...')
      try {
        // Show the browser's native install prompt
        await deferredPrompt.prompt()

        // Wait for the user to respond to the prompt
        const { outcome } = await deferredPrompt.userChoice
        console.log('👤 PWA: User choice:', outcome)

        if (outcome === 'accepted') {
          console.log('✅ PWA: User accepted installation')
          setShowInstall(false)
        } else {
          console.log('❌ PWA: User dismissed installation')
        }

        // Clear the deferred prompt
        setDeferredPrompt(null)
      } catch (error) {
        console.error('❌ PWA: Install prompt failed:', error)
        console.log('📱 PWA: Falling back to modal with instructions')
        // Fallback to modal
        setShowModal(true)
      }
    } else {
      // No native prompt available - show our custom modal with instructions
      console.log('ℹ️ PWA: No native prompt available, showing installation modal')
      console.log('💡 This is normal on localhost - browser may require HTTPS for auto-install')
      setShowModal(true)
    }
  }

  const handleModalInstall = async () => {
    // Close modal first
    setShowModal(false)
    
    // If we still have a deferred prompt, try using it
    if (deferredPrompt) {
      console.log('📱 PWA: Triggering native browser install prompt from modal...')
      
      // Small delay for better UX
      await new Promise(resolve => setTimeout(resolve, 300))

      try {
        // Show the browser's native install prompt
        deferredPrompt.prompt()

        // Wait for the user to respond to the prompt
        const { outcome } = await deferredPrompt.userChoice

        if (outcome === 'accepted') {
          console.log('✅ PWA: User accepted installation')
          setShowInstall(false)
        } else {
          console.log('❌ PWA: User dismissed installation')
        }

        // Clear the deferred prompt
        setDeferredPrompt(null)
        return
      } catch (error) {
        console.error('❌ PWA: Install prompt failed:', error)
      }
    }

    // No deferred prompt - provide browser-specific instructions
    console.log('ℹ️ PWA: No beforeinstallprompt event - showing browser-specific instructions')
    
    // Small delay after closing modal
    await new Promise(resolve => setTimeout(resolve, 300))
    
    // Detect browser
    const isChrome = /Chrome/.test(navigator.userAgent) && /Google Inc/.test(navigator.vendor)
    const isEdge = /Edg/.test(navigator.userAgent)
    const isSafari = /Safari/.test(navigator.userAgent) && !/Chrome/.test(navigator.userAgent)
    const isFirefox = /Firefox/.test(navigator.userAgent)
    
    let instructions = '📱 RADAI Installation Guide\n\n'
    
    if (isChrome || isEdge) {
      instructions += '✅ Chrome/Edge Installation:\n\n'
      instructions += '1. Look for the 🖥️ install icon in the address bar (right side)\n'
      instructions += '   OR\n'
      instructions += '2. Click the ⋮ menu (top-right corner)\n'
      instructions += '3. Select "Install RADAI" or "Install app"\n'
      instructions += '4. Click "Install" in the popup\n\n'
      instructions += '💡 The app will appear on your desktop and start menu!'
    } else if (isSafari) {
      instructions += '✅ Safari Installation (iOS/Mac):\n\n'
      instructions += '1. Tap the Share button (📤) at the bottom\n'
      instructions += '2. Scroll down and tap "Add to Home Screen"\n'
      instructions += '3. Tap "Add" to confirm\n\n'
      instructions += '💡 The app icon will appear on your home screen!'
    } else if (isFirefox) {
      instructions += '✅ Firefox Installation:\n\n'
      instructions += '1. Click the ⋮ menu button\n'
      instructions += '2. Select "Install" or "Add to Home Screen"\n'
      instructions += '3. Confirm the installation\n\n'
      instructions += '💡 The app will be added to your applications!'
    } else {
      instructions += '✅ Installation Options:\n\n'
      instructions += '1. Look for install options in your browser menu (⋮)\n'
      instructions += '2. Or use Chrome/Edge for best PWA support\n\n'
      instructions += '💡 For the best experience, we recommend Chrome or Edge!'
    }
    
    await radaiAlert(instructions)
  }

  // Don't render if already installed
  if (isInstalled || !showInstall) return null

  return (
    <>
      {/* Floating install button */}
      <button
        onClick={handleInstallClick}
        className="fixed bottom-6 right-6 z-50 group"
        style={{
          background: 'linear-gradient(135deg, #0891b2 0%, #06b6d4 50%, #0e7490 100%)',
          boxShadow: '0 10px 40px -10px rgba(8, 145, 178, 0.6), 0 0 0 2px rgba(115, 189, 200, 0.2)'
        }}
      >
        <div className="relative px-6 py-3 rounded-xl overflow-hidden">
          {/* Animated background shimmer */}
          <div 
            className="absolute inset-0 opacity-0 group-hover:opacity-100 transition-opacity duration-500"
            style={{
              background: 'linear-gradient(110deg, transparent 30%, rgba(255,255,255,0.3) 50%, transparent 70%)',
              backgroundSize: '200% 100%',
              animation: 'shimmer 2s ease-in-out infinite'
            }}
          />

          {/* Content */}
          <div className="relative z-10 flex items-center space-x-3">
            {/* Download icon */}
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" />
            </svg>
            
            <div className="text-left">
              <div className="text-white font-black text-sm leading-tight">
                Install RADAI
              </div>
              <div className="text-cyan-100 text-xs font-semibold">
                Desktop, tablet, or mobile
              </div>
            </div>

            {/* Arrow icon */}
            <svg className="w-5 h-5 text-white transform group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14 5l7 7m0 0l-7 7m7-7H3" />
            </svg>
          </div>
        </div>

        {/* Keyframe animations */}
        <style>{`
          @keyframes shimmer {
            0% { background-position: 200% center; }
            100% { background-position: -200% center; }
          }
        `}</style>
      </button>

      {/* Professional Installation Modal */}
      <PWAInstallModal
        isOpen={showModal}
        onClose={() => setShowModal(false)}
        onInstall={handleModalInstall}
      />
    </>
  )
}

export default PWAInstallPrompt

/**
 * ===================================================================
 * PAGE CONTROL BUTTONS COMPONENT
 * ===================================================================
 * 
 * Purpose: Reusable UI controls for Hide Sidebar, Auto-Refresh, Fullscreen
 * Usage: Import and place in any page header
 * 
 * Features:
 * - Material-UI IconButtons with Tooltips
 * - Responsive design
 * - Visual feedback (colors, animations)
 * - Accessible (ARIA labels, keyboard support)
 * 
 * Soft-coded Design:
 * - All icons and labels configurable
 * - Conditional rendering based on enabled features
 * - Customizable styling via props
 * 
 * @example
 * <PageControlButtons controls={pageControls} />
 */

import React from 'react';
import { IconButton, Tooltip } from '@mui/material';
import { 
  Bars3Icon, 
  Bars3BottomLeftIcon 
} from '@heroicons/react/24/outline';
import { 
  RefreshCw, 
  Maximize2, 
  Minimize2 
} from 'lucide-react';

/**
 * Soft-coded configuration for button appearance
 */
const BUTTON_CONFIG = {
  size: 'small',
  sx: {
    transition: 'all 0.2s ease-in-out',
    '&:hover': {
      transform: 'scale(1.1)',
    },
  },
};

const ICON_SIZE = {
  heroicon: 'w-4 h-4',
  lucide: 16,
};

/**
 * PageControlButtons Component
 * 
 * @param {Object} props
 * @param {Object} props.controls - Page controls object from usePageControls hook
 * @param {string} props.className - Additional CSS classes
 * @param {Object} props.buttonProps - Additional props for IconButtons
 * @param {boolean} props.showLabels - Show text labels (for larger screens)
 * 
 * @returns {JSX.Element} Rendered control buttons
 */
export const PageControlButtons = ({ 
  controls, 
  className = '', 
  buttonProps = {},
  showLabels = false 
}) => {
  if (!controls) {
    console.warn('[PageControlButtons] No controls provided');
    return null;
  }

  const {
    isFullscreen,
    autoRefreshEnabled,
    sidebarVisible,
    isRefreshing,
    toggleFullscreen,
    toggleSidebar,
    toggleAutoRefresh,
    manualRefresh,
    features,
  } = controls;

  return (
    <div 
      className={`flex items-center gap-2 ${className}`}
      role="toolbar"
      aria-label="Page Controls"
    >
      {/* Sidebar Toggle Button */}
      {features.sidebarToggle && (
        <Tooltip 
          title={sidebarVisible ? 'Hide Sidebar' : 'Show Sidebar'}
          arrow
          placement="bottom"
        >
          <IconButton
            {...BUTTON_CONFIG}
            {...buttonProps}
            onClick={toggleSidebar}
            aria-label={sidebarVisible ? 'Hide sidebar' : 'Show sidebar'}
            sx={{
              ...BUTTON_CONFIG.sx,
              ...buttonProps.sx,
              color: sidebarVisible ? 'primary.main' : 'text.secondary',
            }}
          >
            {sidebarVisible ? (
              <Bars3Icon className={ICON_SIZE.heroicon} />
            ) : (
              <Bars3BottomLeftIcon className={ICON_SIZE.heroicon} />
            )}
          </IconButton>
        </Tooltip>
      )}

      {/* Auto-Refresh Toggle Button */}
      {features.autoRefresh && (
        <Tooltip 
          title={autoRefreshEnabled ? 'Auto-refresh ON (30s)' : 'Auto-refresh OFF (Click to enable)'}
          arrow
          placement="bottom"
        >
          <IconButton
            {...BUTTON_CONFIG}
            {...buttonProps}
            onClick={toggleAutoRefresh}
            onDoubleClick={manualRefresh}
            aria-label={autoRefreshEnabled ? 'Disable auto-refresh' : 'Enable auto-refresh'}
            sx={{
              ...BUTTON_CONFIG.sx,
              ...buttonProps.sx,
              color: autoRefreshEnabled ? 'success.main' : 'text.secondary',
            }}
          >
            <RefreshCw 
              size={ICON_SIZE.lucide} 
              className={isRefreshing ? 'animate-spin' : ''} 
            />
          </IconButton>
        </Tooltip>
      )}

      {/* Fullscreen Toggle Button */}
      {features.fullscreen && (
        <Tooltip 
          title={isFullscreen ? 'Exit Fullscreen (ESC)' : 'Enter Fullscreen (F11)'}
          arrow
          placement="bottom"
        >
          <IconButton
            {...BUTTON_CONFIG}
            {...buttonProps}
            onClick={toggleFullscreen}
            aria-label={isFullscreen ? 'Exit fullscreen mode' : 'Enter fullscreen mode'}
            sx={{
              ...BUTTON_CONFIG.sx,
              ...buttonProps.sx,
              color: isFullscreen ? 'primary.main' : 'text.secondary',
            }}
          >
            {isFullscreen ? (
              <Minimize2 size={ICON_SIZE.lucide} />
            ) : (
              <Maximize2 size={ICON_SIZE.lucide} />
            )}
          </IconButton>
        </Tooltip>
      )}

      {/* Optional: Text Labels for larger screens */}
      {showLabels && (
        <div className="hidden lg:flex items-center gap-2 ml-2 text-xs text-gray-600">
          {features.sidebarToggle && (
            <span className={sidebarVisible ? 'text-blue-600' : 'text-gray-400'}>
              Sidebar
            </span>
          )}
          {features.autoRefresh && (
            <span className={autoRefreshEnabled ? 'text-green-600' : 'text-gray-400'}>
              Auto-refresh
            </span>
          )}
          {features.fullscreen && (
            <span className={isFullscreen ? 'text-blue-600' : 'text-gray-400'}>
              Fullscreen
            </span>
          )}
        </div>
      )}
    </div>
  );
};

/**
 * Compact variant for smaller headers
 */
export const PageControlButtonsCompact = (props) => (
  <PageControlButtons
    {...props}
    buttonProps={{ size: 'small', ...props.buttonProps }}
    className={`gap-1 ${props.className || ''}`}
  />
);

/**
 * Variant with labels for desktop
 */
export const PageControlButtonsWithLabels = (props) => (
  <PageControlButtons
    {...props}
    showLabels={true}
  />
);

export default PageControlButtons;

/**
 * Percentage-Based Allowance Deduction Modal
 * AI-Driven Smart Deduction Calculator with Real-Time Preview
 * SOFT-CODED: Uses deductible allowance configuration from backend
 */
import React, { useState, useEffect } from 'react';
import {
  XMarkIcon,
  CalculatorIcon,
  CheckCircleIcon,
  ExclamationTriangleIcon,
  InformationCircleIcon,
  SparklesIcon,
} from '@heroicons/react/24/outline';

// ═══════════════════════════════════════════════════════════════════════════
// SOFT-CODED CONFIGURATION
// ═══════════════════════════════════════════════════════════════════════════

const DEDUCTION_PRESETS = [5, 10, 15, 20, 25, 30, 50, 75, 100];

const DEDUCTIBLE_COMPONENTS = [
  { key: 'housing_allowance', label: 'Housing Allowance', icon: '🏠' },
  { key: 'transportation_allowance', label: 'Transportation', icon: '🚗' },
  { key: 'home_leave_allowance', label: 'Home Leave', icon: '✈️' },
  { key: 'other_allowance', label: 'Other Allowance', icon: '💰' },
  { key: 'others_allowance', label: 'Other Pay', icon: '💵' },
];

const DeductionModal = ({ slip, onClose, onSuccess }) => {
  const [percentage, setPercentage] = useState(10);
  const [reason, setReason] = useState('');
  const [preview, setPreview] = useState(null);
  const [aiRecommendation, setAiRecommendation] = useState(null);
  const [loading, setLoading] = useState(false);
  const [applying, setApplying] = useState(false);
  const [error, setError] = useState(null);

  // ═══════════════════════════════════════════════════════════════════════
  // AUTO-LOAD AI RECOMMENDATION ON MOUNT
  // ═══════════════════════════════════════════════════════════════════════
  useEffect(() => {
    fetchPreview(percentage, true);
  }, []);

  // ═══════════════════════════════════════════════════════════════════════
  // FETCH PREVIEW (DEBOUNCED)
  // ═══════════════════════════════════════════════════════════════════════
  useEffect(() => {
    const timer = setTimeout(() => {
      if (percentage >= 0 && percentage <= 100) {
        fetchPreview(percentage);
      }
    }, 300);

    return () => clearTimeout(timer);
  }, [percentage]);

  const fetchPreview = async (pct, isInitial = false) => {
    setLoading(true);
    setError(null);

    try {
      const token = localStorage.getItem('access_token');
      const response = await fetch(
        `/api/v1/finance/salary-slips/${slip.id}/apply-deduction/`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            percentage: pct,
            preview: true,
          }),
        }
      );

      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.error || 'Preview failed');
      }

      const data = await response.json();
      setPreview(data);

      if (data.ai_recommendation) {
        setAiRecommendation(data.ai_recommendation);
        
        // Auto-set AI recommendation on initial load
        if (isInitial) {
          setPercentage(data.ai_recommendation.percentage);
        }
      }
    } catch (err) {
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  // ═══════════════════════════════════════════════════════════════════════
  // APPLY DEDUCTION
  // ═══════════════════════════════════════════════════════════════════════
  const handleApply = async () => {
    if (!reason.trim()) {
      setError('Please provide a reason for the deduction');
      return;
    }

    setApplying(true);
    setError(null);

    try {
      const token = localStorage.getItem('access_token');
      const response = await fetch(
        `/api/v1/finance/salary-slips/${slip.id}/apply-deduction/`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
          body: JSON.stringify({
            percentage,
            preview: false,
            reason,
          }),
        }
      );

      if (!response.ok) {
        const errData = await response.json();
        throw new Error(errData.error || 'Failed to apply deduction');
      }

      const data = await response.json();
      onSuccess?.(data);
      onClose();
    } catch (err) {
      setError(err.message);
    } finally {
      setApplying(false);
    }
  };

  // ═══════════════════════════════════════════════════════════════════════
  // SEVERITY BADGE COLORS
  // ═══════════════════════════════════════════════════════════════════════
  const getSeverityColor = (severity) => {
    switch (severity) {
      case 'info':
        return 'bg-blue-50 text-blue-700 border-blue-200';
      case 'warning':
        return 'bg-amber-50 text-amber-700 border-amber-200';
      case 'error':
        return 'bg-red-50 text-red-700 border-red-200';
      default:
        return 'bg-gray-50 text-gray-700 border-gray-200';
    }
  };

  const getSeverityIcon = (severity) => {
    switch (severity) {
      case 'info':
        return <InformationCircleIcon className="h-5 w-5" />;
      case 'warning':
        return <ExclamationTriangleIcon className="h-5 w-5" />;
      case 'error':
        return <ExclamationTriangleIcon className="h-5 w-5" />;
      default:
        return <InformationCircleIcon className="h-5 w-5" />;
    }
  };

  return (
    <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-3xl max-h-[90vh] overflow-hidden flex flex-col">
        {/* HEADER */}
        <div className="bg-gradient-to-r from-purple-600 to-indigo-600 px-6 py-4 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-white/20 rounded-lg p-2">
              <CalculatorIcon className="h-6 w-6 text-white" />
            </div>
            <div>
              <h2 className="text-xl font-bold text-white">
                Smart Deduction Calculator
              </h2>
              <p className="text-purple-100 text-sm">
                AI-powered percentage-based allowance deduction
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="text-white/80 hover:text-white transition-colors"
          >
            <XMarkIcon className="h-6 w-6" />
          </button>
        </div>

        {/* BODY */}
        <div className="flex-1 overflow-y-auto p-6 space-y-6">
          {/* AI RECOMMENDATION BANNER */}
          {aiRecommendation && (
            <div
              className={`border rounded-lg p-4 flex items-start gap-3 ${getSeverityColor(
                aiRecommendation.severity
              )}`}
            >
              <SparklesIcon className="h-6 w-6 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <div className="flex items-center justify-between mb-1">
                  <h3 className="font-semibold">AI Recommendation</h3>
                  <span className="text-sm font-bold">
                    {aiRecommendation.percentage}%
                  </span>
                </div>
                <p className="text-sm">{aiRecommendation.reason}</p>
                {percentage !== aiRecommendation.percentage && (
                  <button
                    onClick={() => setPercentage(aiRecommendation.percentage)}
                    className="mt-2 text-sm font-medium underline hover:no-underline"
                  >
                    Apply AI Recommendation
                  </button>
                )}
              </div>
            </div>
          )}

          {/* EMPLOYEE INFO */}
          <div className="bg-slate-50 rounded-lg p-4">
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div>
                <span className="text-slate-500">Employee:</span>
                <span className="ml-2 font-medium">{slip.employee_name}</span>
              </div>
              <div>
                <span className="text-slate-500">Department:</span>
                <span className="ml-2 font-medium">{slip.department || '—'}</span>
              </div>
              <div>
                <span className="text-slate-500">Current Net Salary:</span>
                <span className="ml-2 font-bold text-green-600">
                  AED {parseFloat(slip.net_salary).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </div>
              <div>
                <span className="text-slate-500">Slip Number:</span>
                <span className="ml-2 font-medium">{slip.slip_number}</span>
              </div>
            </div>
          </div>

          {/* PERCENTAGE SELECTOR */}
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-3">
              Deduction Percentage
            </label>

            {/* PRESET BUTTONS */}
            <div className="flex flex-wrap gap-2 mb-4">
              {DEDUCTION_PRESETS.map((preset) => (
                <button
                  key={preset}
                  onClick={() => setPercentage(preset)}
                  className={`px-4 py-2 rounded-lg text-sm font-medium transition-all ${
                    percentage === preset
                      ? 'bg-indigo-600 text-white shadow-md scale-105'
                      : 'bg-slate-100 text-slate-700 hover:bg-slate-200'
                  }`}
                >
                  {preset}%
                </button>
              ))}
            </div>

            {/* SLIDER */}
            <div className="space-y-2">
              <input
                type="range"
                min="0"
                max="100"
                step="0.5"
                value={percentage}
                onChange={(e) => setPercentage(parseFloat(e.target.value))}
                className="w-full h-2 bg-slate-200 rounded-lg appearance-none cursor-pointer accent-indigo-600"
              />
              <div className="flex items-center justify-between">
                <span className="text-xs text-slate-500">0%</span>
                <input
                  type="number"
                  min="0"
                  max="100"
                  step="0.1"
                  value={percentage}
                  onChange={(e) => setPercentage(parseFloat(e.target.value) || 0)}
                  className="w-20 px-3 py-1 text-center border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-sm font-semibold"
                />
                <span className="text-xs text-slate-500">100%</span>
              </div>
            </div>
          </div>

          {/* DEDUCTIBLE COMPONENTS BREAKDOWN */}
          {preview && (
            <div>
              <h3 className="text-sm font-semibold text-slate-700 mb-3">
                Deduction Breakdown (by Component)
              </h3>
              <div className="bg-slate-50 rounded-lg border border-slate-200 divide-y divide-slate-200">
                {DEDUCTIBLE_COMPONENTS.map((comp) => {
                  const currentAmount = slip.allowances_breakdown?.[comp.key] || 0;
                  const deductionAmount =
                    preview.component_deductions?.[comp.key] || 0;

                  if (currentAmount <= 0) return null;

                  return (
                    <div key={comp.key} className="p-3 flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <span className="text-xl">{comp.icon}</span>
                        <span className="text-sm font-medium text-slate-700">
                          {comp.label}
                        </span>
                      </div>
                      <div className="text-right">
                        <div className="text-xs text-slate-500">
                          AED {parseFloat(currentAmount).toLocaleString('en-US', { minimumFractionDigits: 2 })} →{' '}
                          <span className="text-red-600 font-medium">
                            -{parseFloat(deductionAmount).toLocaleString('en-US', { minimumFractionDigits: 2 })}
                          </span>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          {/* PREVIEW SUMMARY */}
          {preview && (
            <div className="bg-gradient-to-br from-indigo-50 to-purple-50 rounded-lg p-5 border-2 border-indigo-200">
              <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
                <CalculatorIcon className="h-5 w-5 text-indigo-600" />
                Deduction Summary
              </h3>
              <div className="space-y-3">
                <div className="flex justify-between items-center">
                  <span className="text-slate-600">Total Deduction Amount:</span>
                  <span className="text-xl font-bold text-red-600">
                    -AED {parseFloat(preview.total_deduction_amount).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                  </span>
                </div>
                <div className="h-px bg-slate-300"></div>
                <div className="flex justify-between items-center">
                  <span className="text-slate-600">New Net Salary:</span>
                  <span className="text-2xl font-bold text-green-600">
                    AED {parseFloat(preview.new_net_salary).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                  </span>
                </div>
                <div className="flex justify-between items-center text-sm">
                  <span className="text-slate-500">Reduction:</span>
                  <span className="font-medium text-slate-700">
                    AED {(parseFloat(preview.current_net_salary) - parseFloat(preview.new_net_salary)).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })} ({percentage}%)
                  </span>
                </div>
              </div>
            </div>
          )}

          {/* REASON INPUT */}
          <div>
            <label className="block text-sm font-semibold text-slate-700 mb-2">
              Reason for Deduction <span className="text-red-500">*</span>
            </label>
            <textarea
              value={reason}
              onChange={(e) => setReason(e.target.value)}
              placeholder="e.g., Salary adjustment for Q2 2026, Housing allowance reduction, etc."
              rows={3}
              className="w-full px-4 py-3 border border-slate-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent resize-none text-sm"
            />
          </div>

          {/* ERROR DISPLAY */}
          {error && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 flex items-start gap-3">
              <ExclamationTriangleIcon className="h-5 w-5 text-red-600 flex-shrink-0 mt-0.5" />
              <div className="text-sm text-red-700">{error}</div>
            </div>
          )}
        </div>

        {/* FOOTER */}
        <div className="bg-slate-50 px-6 py-4 flex items-center justify-between border-t border-slate-200">
          <button
            onClick={onClose}
            disabled={applying}
            className="px-5 py-2.5 text-slate-700 font-medium hover:bg-slate-200 rounded-lg transition-colors disabled:opacity-50"
          >
            Cancel
          </button>
          <button
            onClick={handleApply}
            disabled={loading || applying || !reason.trim() || !preview}
            className="px-6 py-2.5 bg-gradient-to-r from-indigo-600 to-purple-600 text-white font-semibold rounded-lg hover:from-indigo-700 hover:to-purple-700 transition-all shadow-md hover:shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
          >
            {applying ? (
              <>
                <div className="animate-spin rounded-full h-4 w-4 border-2 border-white border-t-transparent"></div>
                Applying...
              </>
            ) : (
              <>
                <CheckCircleIcon className="h-5 w-5" />
                Apply Deduction
              </>
            )}
          </button>
        </div>
      </div>
    </div>
  );
};

