import { radaiConfirm, radaiAlert } from '../../services/radaiDialog'
/**
 * Process Datasheet Dashboard
 * Overview and management of all datasheets
 * Soft-coded filtering and display options
 */

import React, { useState, useEffect } from 'react';
import api from '../../services/api.service';
import {
  Card,
  CardContent,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  TablePagination,
  Chip,
  Button,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  IconButton,
  Menu,
  Grid,
  Paper
} from '@mui/material';
import {
  Add,
  Edit,
  Delete,
  Visibility,
  CloudUpload,
  CheckCircle,
  Warning,
  MoreVert,
  FilterList,
  Refresh
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';
import { CompactWorkflowProgress } from './WorkflowProgressTracker';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000/api/v1';

// Soft-coded status configurations
const STATUS_CONFIG = {
  draft: {
    label: 'Draft',
    color: 'default',
    icon: '📝'
  },
  pending_validation: {
    label: 'Pending Validation',
    color: 'warning',
    icon: '⏳'
  },
  validated: {
    label: 'Validated',
    color: 'info',
    icon: '✓'
  },
  approved: {
    label: 'Approved',
    color: 'success',
    icon: '✅'
  },
  rejected: {
    label: 'Rejected',
    color: 'error',
    icon: '❌'
  }
};

/**
 * Dashboard Statistics Cards
 */
const StatisticsCards = ({ stats }) => {
  return (
    <Grid container spacing={3} className="mb-6">
      <Grid item xs={12} sm={6} md={3}>
        <Paper className="p-4 bg-gradient-to-br from-blue-50 to-blue-100">
          <div className="text-3xl font-bold text-blue-600">
