          </div>
          <div className="text-sm text-gray-600">Total Datasheets</div>
        </Paper>
      </Grid>

      <Grid item xs={12} sm={6} md={3}>
        <Paper className="p-4 bg-gradient-to-br from-green-50 to-green-100">
