};

/**
 * Datasheet Table Row
 */
const DatasheetRow = ({ datasheet, onView, onEdit, onDelete, onValidate }) => {
  const [anchorEl, setAnchorEl] = useState(null);
  const statusConfig = STATUS_CONFIG[datasheet.status] || STATUS_CONFIG.draft;

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  return (
    <TableRow hover>
      <TableCell>
        <div className="font-semibold">{datasheet.tag_number || datasheet.id.slice(0, 8)}</div>
        <div className="text-sm text-gray-600">{datasheet.equipment_type_name}</div>
      </TableCell>

      <TableCell>
        <Chip
          label={statusConfig.label}
          color={statusConfig.color}
          size="small"
          icon={<span>{statusConfig.icon}</span>}
        />
      </TableCell>

      <TableCell>
        {datasheet.validation_score ? (
          <div className="flex items-center gap-2">
            <div className={`text-sm font-semibold ${
              datasheet.validation_score >= 0.8 ? 'text-green-600' :
              datasheet.validation_score >= 0.6 ? 'text-yellow-600' :
              'text-red-600'
            }`}>
              {(datasheet.validation_score * 100).toFixed(0)}%
            </div>
            {datasheet.validation_score >= 0.8 ? (
              <CheckCircle fontSize="small" className="text-green-600" />
            ) : (
              <Warning fontSize="small" className="text-yellow-600" />
            )}
          </div>
        ) : (
          <span className="text-gray-400">Not validated</span>
        )}
      </TableCell>

      <TableCell>
        <div className="text-sm">
          {new Date(datasheet.created_at).toLocaleDateString()}
        </div>
        <div className="text-xs text-gray-500">
          {new Date(datasheet.created_at).toLocaleTimeString()}
        </div>
      </TableCell>

      <TableCell>
        <div className="text-sm">{datasheet.created_by_name || 'Unknown'}</div>
      </TableCell>

      <TableCell align="right">
        <IconButton size="small" onClick={() => onView(datasheet)}>
          <Visibility fontSize="small" />
        </IconButton>
        <IconButton size="small" onClick={() => onEdit(datasheet)}>
          <Edit fontSize="small" />
        </IconButton>
        <IconButton size="small" onClick={handleMenuOpen}>
          <MoreVert fontSize="small" />
        </IconButton>

        <Menu
          anchorEl={anchorEl}
          open={Boolean(anchorEl)}
          onClose={handleMenuClose}
        >
          <MenuItem onClick={() => { onValidate(datasheet); handleMenuClose(); }}>
            Validate
          </MenuItem>
          <MenuItem onClick={() => { onDelete(datasheet); handleMenuClose(); }}>
            Delete
          </MenuItem>
        </Menu>
      </TableCell>
    </TableRow>
  );
};

/**
 * Main Dashboard Component
 */
const DatasheetDashboard = () => {
  const navigate = useNavigate();
  
  // State
  const [datasheets, setDatasheets] = useState([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [totalCount, setTotalCount] = useState(0);
  const [stats, setStats] = useState({});
  
  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [equipmentTypeFilter, setEquipmentTypeFilter] = useState('all');
  const [equipmentTypes, setEquipmentTypes] = useState([]);

  // Load data on mount and filter changes
  useEffect(() => {
    loadDatasheets();
    loadStatistics();
    loadEquipmentTypes();
  }, [page, rowsPerPage, statusFilter, equipmentTypeFilter, searchQuery]);

  /**
   * Load datasheets from API
   */
  const loadDatasheets = async () => {
    setLoading(true);
    try {
      const params = {
        page: page + 1,
        page_size: rowsPerPage
      };

      if (searchQuery) params.search = searchQuery;
      if (statusFilter !== 'all') params.status = statusFilter;
      if (equipmentTypeFilter !== 'all') params.equipment_type = equipmentTypeFilter;

      const response = await axios.get(`${API_BASE_URL}/process-datasheet/datasheets/`, {
        params
      });

      setDatasheets(response.data.results || []);
      setTotalCount(response.data.count || 0);
    } catch (error) {
      console.error('Error loading datasheets:', error);
    } finally {
      setLoading(false);
    }
  };

  /**
   * Load statistics
   */
  const loadStatistics = async () => {
    try {
      const response = await api.get('/process-datasheet/datasheets/statistics/');
      setStats(response.data);
    } catch (error) {
      console.error('Error loading statistics:', error);
    }
  };

  /**
   * Load equipment types for filter
   */
  const loadEquipmentTypes = async () => {
    try {
      const response = await api.get('/process-datasheet/equipment-types/');
      // Handle paginated response - extract results array
      const types = response.data.results || response.data;
      setEquipmentTypes(Array.isArray(types) ? types : []);
    } catch (error) {
      console.error('Error loading equipment types:', error);
      setEquipmentTypes([]);
    }
  };

  /**
   * Handle actions
   */
  const handleView = (datasheet) => {
    navigate(`/engineering/process/datasheet/view/${datasheet.id}`);
  };

  const handleEdit = (datasheet) => {
    navigate(`/engineering/process/datasheet/edit/${datasheet.id}`);
  };

  const handleDelete = async (datasheet) => {
    if ((await radaiConfirm('Are you sure you want to delete this datasheet?'))) {
      try {
        await api.delete(`/process-datasheet/datasheets/${datasheet.id}/`);
        loadDatasheets();
        loadStatistics();
      } catch (error) {
        console.error('Error deleting datasheet:', error);
        await radaiAlert('Failed to delete datasheet');
      }
    }
  };

  const handleValidate = async (datasheet) => {
    try {
      await api.post(`/process-datasheet/datasheets/${datasheet.id}/validate/`);
      loadDatasheets();
      await radaiAlert('Validation completed successfully');
    } catch (error) {
      console.error('Error validating datasheet:', error);
      await radaiAlert('Failed to validate datasheet');
    }
  };

  const handleCreateNew = () => {
    navigate('/engineering/process/datasheet/create');
  };

  const handleUploadPDF = () => {
    navigate('/engineering/process/datasheet/upload');
  };

  return (
    <div className="max-w-7xl mx-auto p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h1 className="text-3xl font-bold text-gray-800">Process Datasheets</h1>
          <p className="text-gray-600 mt-1">Manage and track engineering datasheets</p>
        </div>
        
        <div className="flex gap-2">
          <Button
            variant="outlined"
            startIcon={<CloudUpload />}
            onClick={handleUploadPDF}
          >
            Upload PDF
          </Button>
          <Button
            variant="contained"
            startIcon={<Add />}
            onClick={handleCreateNew}
          >
            Create New
          </Button>
        </div>
      </div>

      {/* Statistics */}
      <StatisticsCards stats={stats} />

      {/* Filters */}
      <Card className="mb-6">
        <CardContent>
          <div className="flex items-center gap-4">
            <FilterList className="text-gray-400" />
            
            <TextField
              label="Search"
              variant="outlined"
              size="small"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Tag number, description..."
              className="flex-1"
            />

            <FormControl size="small" style={{ minWidth: 150 }}>
              <InputLabel>Status</InputLabel>
              <Select
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
                label="Status"
              >
                <MenuItem value="all">All Status</MenuItem>
                {Object.entries(STATUS_CONFIG).map(([key, config]) => (
                  <MenuItem key={key} value={key}>
                    {config.icon} {config.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <FormControl size="small" style={{ minWidth: 180 }}>
              <InputLabel>Equipment Type</InputLabel>
              <Select
                value={equipmentTypeFilter}
                onChange={(e) => setEquipmentTypeFilter(e.target.value)}
                label="Equipment Type"
              >
                <MenuItem value="all">All Types</MenuItem>
                {equipmentTypes.map((type) => (
                  <MenuItem key={type.id} value={type.id}>
                    {type.name}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>

            <IconButton onClick={loadDatasheets}>
              <Refresh />
            </IconButton>
          </div>
        </CardContent>
      </Card>

      {/* Datasheets Table */}
      <Card>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell>Tag / Equipment</TableCell>
                <TableCell>Status</TableCell>
                <TableCell>Validation Score</TableCell>
                <TableCell>Created</TableCell>
                <TableCell>Created By</TableCell>
                <TableCell align="right">Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {loading ? (
                <TableRow>
                  <TableCell colSpan={6} align="center">
                    Loading...
                  </TableCell>
                </TableRow>
              ) : datasheets.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} align="center">
                    No datasheets found
                  </TableCell>
                </TableRow>
              ) : (
                datasheets.map((datasheet) => (
                  <DatasheetRow
                    key={datasheet.id}
                    datasheet={datasheet}
                    onView={handleView}
                    onEdit={handleEdit}
                    onDelete={handleDelete}
                    onValidate={handleValidate}
                  />
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>

        <TablePagination
          component="div"
          count={totalCount}
          page={page}
          onPageChange={(e, newPage) => setPage(newPage)}
          rowsPerPage={rowsPerPage}
          onRowsPerPageChange={(e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          }}
          rowsPerPageOptions={[5, 10, 25, 50]}
        />
      </Card>
    </div>
  );
};

export default DatasheetDashboard;

/**
 * Datasheet Form Builder Component
 * Configuration-driven dynamic form generation
 * No hardcoded fields - all from backend config
 */

import React, { useState, useEffect } from 'react';
import { Button, CircularProgress, Alert, Tabs, Tab, Box } from '@mui/material';
import { Save, Calculate, CheckCircle, Refresh } from '@mui/icons-material';
import { FieldGroupRenderer } from './FieldRenderer';
import datasheetConfigService from '../../services/datasheetConfigService';
import api from '../../services/api.service';

/**
 * Main Datasheet Form Builder
 */
const DatasheetFormBuilder = ({
  equipmentTypeId,
  datasheetId = null,
  onSave,
  onCalculate,
  onValidate,
  readonly = false
}) => {
  // State
  const [config, setConfig] = useState(null);
  const [values, setValues] = useState({});
  const [errors, setErrors] = useState({});
  const [validationResults, setValidationResults] = useState({});
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [calculating, setCalculating] = useState(false);
  const [validating, setValidating] = useState(false);
  const [activeTab, setActiveTab] = useState(0);
  const [calculatedFields, setCalculatedFields] = useState([]);

  // Load configuration and datasheet data
  useEffect(() => {
    loadConfiguration();
  }, [equipmentTypeId, datasheetId]);

  /**
   * Load equipment configuration and existing datasheet
   */
  const loadConfiguration = async () => {
    setLoading(true);
    try {
      // Load configuration
      const configData = await datasheetConfigService.getCompleteConfig(equipmentTypeId);
      setConfig(configData);

      // Get calculated fields
      const calcFields = datasheetConfigService.getCalculatedFields(configData.calculations);
      setCalculatedFields(calcFields);

      // Load existing datasheet or build initial values
      if (datasheetId) {
        const response = await api.get(
          `/process-datasheet/datasheets/${datasheetId}/`
        );
        setValues(response.data.field_values || {});
        setValidationResults(response.data.validation_results || {});
      } else {
        const initialValues = datasheetConfigService.buildInitialValues(configData.fields);
        setValues(initialValues);
      }
    } catch (error) {
      console.error('Error loading configuration:', error);
      setErrors({ _general: 'Failed to load form configuration' });
    } finally {
      setLoading(false);
    }
  };

  /**
   * Handle field value change
   */
  const handleFieldChange = (fieldName, value) => {
    setValues(prev => ({
      ...prev,
      [fieldName]: value
    }));

    // Clear error for this field
    setErrors(prev => {
      const newErrors = { ...prev };
      delete newErrors[fieldName];
      return newErrors;
    });

    // Clear validation result for this field
    setValidationResults(prev => {
      const newResults = { ...prev };
      delete newResults[fieldName];
      return newResults;
    });
  };

  /**
   * Validate form
   */
  const validateForm = () => {
    const newErrors = {};
    
    config.fields.forEach(field => {
      const fieldErrors = datasheetConfigService.validateField(field, values[field.field_name]);
      if (fieldErrors.length > 0) {
        newErrors[field.field_name] = fieldErrors[0];
      }
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  /**
   * Handle save
   */
  const handleSave = async () => {
    if (!validateForm()) {
      return;
    }

    setSaving(true);
    try {
      const payload = {
        equipment_type: equipmentTypeId,
        field_values: values,
        status: 'draft'
      };

      let response;
      if (datasheetId) {
        // Update existing
        response = await api.patch(
          `/process-datasheet/datasheets/${datasheetId}/`,
          payload
        );
      } else {
        // Create new
        response = await api.post(
          `/process-datasheet/datasheets/`,
          payload
        );
      }

      if (onSave) {
        onSave(response.data);
      }
    } catch (error) {
      console.error('Error saving datasheet:', error);
      setErrors({ _general: 'Failed to save datasheet' });
    } finally {
      setSaving(false);
    }
  };

  /**
   * Handle calculate
   */
  const handleCalculate = async () => {
    if (!datasheetId) {
      setErrors({ _general: 'Please save the datasheet before calculating' });
      return;
    }

    setCalculating(true);
    try {
      const response = await api.post(
        `/process-datasheet/datasheets/${datasheetId}/calculate/`
      );

      // Update values with calculated results
      setValues(prev => ({
        ...prev,
        ...response.data.calculated_values
      }));

      if (onCalculate) {
        onCalculate(response.data);
      }
    } catch (error) {
      console.error('Error calculating values:', error);
      setErrors({ _general: 'Failed to calculate values' });
    } finally {
      setCalculating(false);
    }
  };

  /**
   * Handle validate
   */
  const handleValidate = async () => {
    if (!datasheetId) {
      setErrors({ _general: 'Please save the datasheet before validating' });
      return;
    }

    setValidating(true);
    try {
      const response = await api.post(
        `/process-datasheet/datasheets/${datasheetId}/validate/`
      );

      setValidationResults(response.data.validation_results || {});

      if (onValidate) {
        onValidate(response.data);
      }
    } catch (error) {
      console.error('Error validating datasheet:', error);
      setErrors({ _general: 'Failed to validate datasheet' });
    } finally {
      setValidating(false);
    }
  };

  /**
   * Handle refresh/reload
   */
  const handleRefresh = () => {
    loadConfiguration();
  };

  // Loading state
  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <CircularProgress />
      </div>
    );
  }

  // Error state
  if (!config) {
    return (
      <Alert severity="error" className="m-4">
        Failed to load form configuration
      </Alert>
    );
  }

  // Group sections
  const sectionTabs = config.sections.sort((a, b) => a.display_order - b.display_order);

  return (
    <div className="max-w-7xl mx-auto p-6">
      {/* Header */}
      <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-800">
              {config.equipmentType.name} Datasheet
            </h1>
            <p className="text-gray-600 mt-1">
              {config.equipmentType.description}
            </p>
          </div>
          
          {/* Action Buttons */}
          <div className="flex gap-2">
            <Button
              variant="outlined"
              startIcon={<Refresh />}
              onClick={handleRefresh}
              disabled={saving || calculating || validating}
            >
              Refresh
            </Button>
            
            {!readonly && (
              <>
                <Button
                  variant="outlined"
                  startIcon={<Calculate />}
                  onClick={handleCalculate}
                  disabled={!datasheetId || calculating || saving}
                >
                  {calculating ? 'Calculating...' : 'Calculate'}
                </Button>

                <Button
                  variant="outlined"
                  startIcon={<CheckCircle />}
                  onClick={handleValidate}
                  disabled={!datasheetId || validating || saving}
                >
                  {validating ? 'Validating...' : 'Validate'}
                </Button>

                <Button
                  variant="contained"
                  startIcon={<Save />}
                  onClick={handleSave}
                  disabled={saving || calculating}
                >
                  {saving ? 'Saving...' : 'Save'}
                </Button>
              </>
            )}
          </div>
        </div>

        {/* General Error */}
        {errors._general && (
          <Alert severity="error" className="mt-4">
            {errors._general}
          </Alert>
        )}
      </div>

      {/* Tabs for Sections */}
      <Box className="bg-white rounded-lg shadow-sm mb-6">
        <Tabs 
          value={activeTab} 
          onChange={(e, newValue) => setActiveTab(newValue)}
          variant="scrollable"
          scrollButtons="auto"
        >
          {sectionTabs.map((section, index) => (
            <Tab 
              key={section.name} 
              label={section.label}
              icon={
                // Show validation status on tab
                Object.keys(errors).some(key => 
                  config.fields.find(f => f.field_name === key && f.section === section.name)
                ) ? '❌' : 
                Object.keys(validationResults).some(key => 
                  config.fields.find(f => f.field_name === key && f.section === section.name) &&
                  validationResults[key].status === 'success'
                ) ? '✅' : null
              }
              iconPosition="end"
            />
          ))}
        </Tabs>
      </Box>

      {/* Section Content */}
      {sectionTabs.map((section, index) => (
        <div
          key={section.name}
          role="tabpanel"
          hidden={activeTab !== index}
        >
          {activeTab === index && (
            <FieldGroupRenderer
              section={section}
              fields={config.fields}
              values={values}
              onChange={handleFieldChange}
              errors={errors}
              validationResults={validationResults}
              calculatedFields={calculatedFields}
              disabled={readonly || saving || calculating}
            />
          )}
        </div>
      ))}

      {/* Form Summary */}
      <div className="bg-white rounded-lg shadow-sm p-6 mt-6">
        <h3 className="text-lg font-semibold mb-4">Form Summary</h3>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="text-center p-4 bg-blue-50 rounded">
            <div className="text-3xl font-bold text-blue-600">
              {config.fields.length}
            </div>
            <div className="text-sm text-gray-600">Total Fields</div>
          </div>
          
          <div className="text-center p-4 bg-green-50 rounded">
            <div className="text-3xl font-bold text-green-600">
              {Object.keys(values).filter(k => values[k]).length}
            </div>
            <div className="text-sm text-gray-600">Filled Fields</div>
          </div>
          
          <div className="text-center p-4 bg-purple-50 rounded">
            <div className="text-3xl font-bold text-purple-600">
              {calculatedFields.length}
            </div>
            <div className="text-sm text-gray-600">Calculated Fields</div>
          </div>
          
          <div className="text-center p-4 bg-yellow-50 rounded">
            <div className="text-3xl font-bold text-yellow-600">
              {Object.keys(errors).length}
            </div>
            <div className="text-sm text-gray-600">Errors</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DatasheetFormBuilder;

/**
 * Dynamic Field Renderer Component
 * Soft-coded field rendering based on field configuration
 * Supports all field types without hardcoding
 */

import React from 'react';
import { TextField, Select, MenuItem, FormControl, InputLabel, FormHelperText, Checkbox, FormControlLabel } from '@mui/material';

// Soft-coded field type configurations
const FIELD_TYPE_CONFIG = {
  text: {
    component: 'TextField',
    props: { type: 'text', fullWidth: true, variant: 'outlined' }
  },
  number: {
    component: 'TextField',
    props: { type: 'number', fullWidth: true, variant: 'outlined' }
  },
  decimal: {
    component: 'TextField',
    props: { type: 'number', inputProps: { step: 0.01 }, fullWidth: true, variant: 'outlined' }
  },
  select: {
    component: 'Select',
    props: { fullWidth: true, variant: 'outlined' }
  },
  multiselect: {
    component: 'Select',
    props: { fullWidth: true, variant: 'outlined', multiple: true }
  },
  checkbox: {
    component: 'Checkbox',
    props: {}
  },
  textarea: {
    component: 'TextField',
    props: { multiline: true, rows: 4, fullWidth: true, variant: 'outlined' }
  },
  date: {
    component: 'TextField',
    props: { type: 'date', fullWidth: true, variant: 'outlined', InputLabelProps: { shrink: true } }
  },
  email: {
    component: 'TextField',
    props: { type: 'email', fullWidth: true, variant: 'outlined' }
  },
  url: {
    component: 'TextField',
    props: { type: 'url', fullWidth: true, variant: 'outlined' }
  },
  password: {
    component: 'TextField',
    props: { type: 'password', fullWidth: true, variant: 'outlined' }
  }
};

// Validation state colors (soft-coded)
const VALIDATION_COLORS = {
  error: '#ef4444',
  warning: '#f59e0b',
  success: '#10b981',
  info: '#3b82f6'
};

/**
 * Dynamic Field Renderer
 * Renders any field type based on configuration
 */
const FieldRenderer = ({
  field,
  value,
  onChange,
  onBlur,
  error,
  helperText,
  disabled = false,
  validation = null,
  calculated = false,
  showUnit = true
}) => {
  // Get field configuration
  const fieldConfig = FIELD_TYPE_CONFIG[field.field_type] || FIELD_TYPE_CONFIG.text;
  
  // Build display label with unit
  const displayLabel = showUnit && field.unit 
    ? `${field.label} (${field.unit})`
    : field.label;

  // Add validation styling
  const validationStyle = validation?.status 
    ? { borderColor: VALIDATION_COLORS[validation.status] }
    : {};

  // Handle calculated field display
  if (calculated) {
    return (
      <TextField
        label={displayLabel}
        value={value || ''}
        fullWidth
        variant="outlined"
        disabled
        helperText={
          <span className="flex items-center gap-1">
            <span className="text-blue-600">🔢 Calculated</span>
            {helperText && <span> • {helperText}</span>}
          </span>
        }
        InputProps={{
          style: { backgroundColor: '#f0f9ff', ...validationStyle }
        }}
      />
    );
  }

  // Render based on field type
  switch (fieldConfig.component) {
    case 'TextField':
      return (
        <TextField
          {...fieldConfig.props}
          label={displayLabel}
          value={value || ''}
          onChange={(e) => onChange(field.field_name, e.target.value)}
          onBlur={onBlur}
          error={!!error}
          helperText={error || helperText || field.help_text}
          disabled={disabled || field.is_readonly}
          required={field.is_required}
          placeholder={field.placeholder}
          InputProps={{
            style: validationStyle
          }}
        />
      );

    case 'Select':
      return (
        <FormControl 
          fullWidth 
          error={!!error} 
          disabled={disabled || field.is_readonly}
          required={field.is_required}
        >
          <InputLabel>{displayLabel}</InputLabel>
          <Select
            {...fieldConfig.props}
            value={value || (fieldConfig.props.multiple ? [] : '')}
            onChange={(e) => onChange(field.field_name, e.target.value)}
            onBlur={onBlur}
            label={displayLabel}
            style={validationStyle}
          >
            {field.choices?.map((choice) => (
              <MenuItem key={choice.value} value={choice.value}>
                {choice.label}
              </MenuItem>
            ))}
          </Select>
          {(error || helperText || field.help_text) && (
            <FormHelperText>{error || helperText || field.help_text}</FormHelperText>
          )}
        </FormControl>
      );

    case 'Checkbox':
      return (
        <FormControlLabel
          control={
            <Checkbox
              checked={!!value}
              onChange={(e) => onChange(field.field_name, e.target.checked)}
              onBlur={onBlur}
              disabled={disabled || field.is_readonly}
              style={validationStyle}
            />
          }
          label={
            <span>
              {displayLabel}
              {field.is_required && <span className="text-red-500 ml-1">*</span>}
            </span>
          }
        />
      );

    default:
      return (
        <TextField
          label={displayLabel}
          value={value || ''}
          onChange={(e) => onChange(field.field_name, e.target.value)}
          onBlur={onBlur}
          error={!!error}
          helperText={error || helperText || field.help_text}
          disabled={disabled || field.is_readonly}
          required={field.is_required}
          fullWidth
          variant="outlined"
        />
      );
  }
};

/**
 * Field Group Renderer
 * Renders a section of related fields
 */
export const FieldGroupRenderer = ({
  section,
  fields,
  values,
  onChange,
  errors = {},
  validationResults = {},
  calculatedFields = [],
  disabled = false
}) => {
  // Filter fields for this section
  const sectionFields = fields.filter(f => f.section === section.name);

  // Get section validation summary
  const sectionErrors = sectionFields.filter(f => errors[f.field_name]).length;
  const sectionWarnings = sectionFields.filter(
    f => validationResults[f.field_name]?.status === 'warning'
  ).length;

  return (
    <div className="bg-white rounded-lg shadow-sm p-6 mb-6">
      {/* Section Header */}
      <div className="flex items-center justify-between mb-4 pb-3 border-b">
        <div>
          <h3 className="text-lg font-semibold text-gray-800">{section.label}</h3>
          {section.description && (
            <p className="text-sm text-gray-600 mt-1">{section.description}</p>
          )}
        </div>
        
        {/* Validation Summary */}
        {(sectionErrors > 0 || sectionWarnings > 0) && (
          <div className="flex gap-2">
            {sectionErrors > 0 && (
              <span className="bg-red-100 text-red-700 px-3 py-1 rounded-full text-xs font-medium">
                {sectionErrors} error{sectionErrors !== 1 ? 's' : ''}
              </span>
            )}
            {sectionWarnings > 0 && (
              <span className="bg-yellow-100 text-yellow-700 px-3 py-1 rounded-full text-xs font-medium">
                {sectionWarnings} warning{sectionWarnings !== 1 ? 's' : ''}
              </span>
            )}
          </div>
        )}
      </div>

      {/* Fields Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {sectionFields.map((field) => {
          const isCalculated = calculatedFields.includes(field.field_name);
          
          return (
            <div 
              key={field.field_name} 
              className={`${field.width_class || 'col-span-1'}`}
            >
              <FieldRenderer
                field={field}
                value={values[field.field_name]}
                onChange={onChange}
                error={errors[field.field_name]}
                validation={validationResults[field.field_name]}
                calculated={isCalculated}
                disabled={disabled}
              />
              
              {/* Validation Feedback */}
              {validationResults[field.field_name]?.message && (
                <div 
                  className="mt-1 text-xs flex items-center gap-1"
                  style={{ color: VALIDATION_COLORS[validationResults[field.field_name].status] }}
                >
                  {validationResults[field.field_name].status === 'error' && '❌'}
                  {validationResults[field.field_name].status === 'warning' && '⚠️'}
                  {validationResults[field.field_name].status === 'success' && '✅'}
                  {validationResults[field.field_name].message}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default FieldRenderer;

/**
 * PDF Upload Component with AI Extraction
 * Drag & drop interface with real-time progress tracking
 * Integrates with backend workflow system
 */

import React, { useState, useCallback } from 'react';
import { 
  Button, 
  LinearProgress, 
  Alert, 
  Card, 
  CardContent, 
  Select, 
  MenuItem, 
  FormControl, 
  InputLabel,
  Chip,
  Stepper,
  Step,
  StepLabel
} from '@mui/material';
import { 
  CloudUpload, 
  Description, 
  Check, 
  Error as ErrorIcon,
  Refresh 
} from '@mui/icons-material';
import api from '../../services/api.service';

// Soft-coded workflow configurations
const WORKFLOW_OPTIONS = {
  pdf_extraction_complete: {
    label: 'Complete Extraction (Recommended)',
    description: 'Full AI pipeline: Analysis → Extraction → Validation → QA',
    duration: '30-60 seconds',
    steps: ['Analyze', 'Extract', 'Validate', 'Quality Check']
  },
  quick_extraction: {
    label: 'Quick Extraction',
    description: 'Fast extraction only, no validation',
    duration: '10-15 seconds',
    steps: ['Extract']
  },
  validation_only: {
    label: 'Validation Only',
    description: 'Validate existing datasheet',
    duration: '15-20 seconds',
    steps: ['Validate', 'Quality Check']
  }
};

/**
 * PDF Upload & Extraction Component
 */
const PDFUploadExtractor = ({ 
  equipmentTypeId, 
  onExtractionComplete,
  onDatasheetCreated 
}) => {
  // State
  const [selectedFile, setSelectedFile] = useState(null);
  const [dragging, setDragging] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [extractionJob, setExtractionJob] = useState(null);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState(null);
  const [selectedWorkflow, setSelectedWorkflow] = useState('pdf_extraction_complete');
  const [extractionResult, setExtractionResult] = useState(null);
  const [activeStep, setActiveStep] = useState(0);

  /**
   * Handle file selection
   */
  const handleFileSelect = (file) => {
    if (file && file.type === 'application/pdf') {
      setSelectedFile(file);
      setError(null);
      setExtractionResult(null);
      setActiveStep(0);
    } else {
      setError('Please select a valid PDF file');
    }
  };

  /**
   * Handle drag & drop
   */
  const handleDragOver = useCallback((e) => {
    e.preventDefault();
    setDragging(true);
  }, []);

  const handleDragLeave = useCallback((e) => {
    e.preventDefault();
    setDragging(false);
  }, []);

  const handleDrop = useCallback((e) => {
    e.preventDefault();
    setDragging(false);
    
    const file = e.dataTransfer.files[0];
    handleFileSelect(file);
  }, []);

  /**
   * Handle file input change
   */
  const handleFileInputChange = (e) => {
    const file = e.target.files[0];
    handleFileSelect(file);
  };

  /**
   * Upload and start extraction
   */
  const handleUploadAndExtract = async () => {
    if (!selectedFile) {
      setError('Please select a file');
      return;
    }

    if (!equipmentTypeId) {
      setError('Please select an equipment type');
      return;
    }

    setUploading(true);
    setError(null);
    setProgress(10);

    try {
      // Create FormData
      const formData = new FormData();
      formData.append('pdf_file', selectedFile);
      formData.append('equipment_type', equipmentTypeId);
      formData.append('job_type', selectedWorkflow);
      formData.append('extraction_mode', 'hybrid'); // Use hybrid extraction

      setProgress(20);

      // Upload and start extraction
      const response = await api.post(
        '/process-datasheet/extraction-jobs/',
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data'
          }
        }
      );

      setExtractionJob(response.data);
      setProgress(30);
      setActiveStep(1);

      // Start polling for status
      pollExtractionStatus(response.data.id);

    } catch (err) {
      console.error('Upload error:', err);
      setError(err.response?.data?.detail || 'Failed to upload and extract PDF');
      setProgress(0);
    } finally {
      setUploading(false);
    }
  };

  /**
   * Poll extraction job status
   */
  const pollExtractionStatus = async (jobId) => {
    const pollInterval = 3000; // 3 seconds - more stable for AI
    const maxAttempts = 200; // 10 minutes (3s × 200 = 600s)
    let attempts = 0;
    let lastProgress = 30;

    const poll = setInterval(async () => {
      try {
        const response = await api.get(
          `/process-datasheet/extraction-jobs/${jobId}/`
        );

        const job = response.data;
        setExtractionJob(job);

        // Calculate elapsed time
        const elapsedSeconds = Math.floor(attempts * (pollInterval / 1000));
        const elapsedMinutes = Math.floor(elapsedSeconds / 60);
        const remainingSeconds = elapsedSeconds % 60;

        // Update progress based on status
        if (job.status === 'processing' || job.status === 'pending') {
          const workflowSteps = WORKFLOW_OPTIONS[selectedWorkflow].steps;
          
          // Smooth progress curve
          const progressCurve = Math.sin((attempts / maxAttempts) * Math.PI);
          const smoothProgress = 30 + progressCurve * 60;
          const newProgress = Math.min(smoothProgress, 90);
          
          if (newProgress > lastProgress) {
            setProgress(newProgress);
            lastProgress = newProgress;
          }
          
          // Update active step based on progress
          const currentStep = Math.min(
            Math.floor((newProgress - 30) / (60 / workflowSteps.length)),
            workflowSteps.length - 1
          );
          setActiveStep(currentStep + 1);

          // Live status messages
          if (elapsedSeconds < 30) {
            setError(`🚀 Starting AI extraction... (${elapsedSeconds}s)`);
          } else if (elapsedSeconds < 120) {
            setError(`🤖 AI analyzing document... (${elapsedMinutes}m ${remainingSeconds}s)`);
          } else if (elapsedSeconds < 300) {
            setError(`⚙️ Processing data... (${elapsedMinutes}m ${remainingSeconds}s)`);
          } else {
            setError(`🔍 Finalizing... (${elapsedMinutes}m ${remainingSeconds}s)`);
          }
        }

        // Check completion
        if (job.status === 'completed') {
          clearInterval(poll);
          setProgress(100);
          setActiveStep(WORKFLOW_OPTIONS[selectedWorkflow].steps.length);
          setExtractionResult(job);
          setError('');
          
          if (onExtractionComplete) {
            onExtractionComplete(job);
          }

          // Create datasheet if not exists
          if (job.datasheet) {
            if (onDatasheetCreated) {
              onDatasheetCreated(job.datasheet);
            }
          }
        }

        // Check failure
        if (job.status === 'failed') {
          clearInterval(poll);
          setError(`❌ ${job.error_message || 'Extraction failed'}`);
          setProgress(0);
        }

        attempts++;
        if (attempts >= maxAttempts) {
          clearInterval(poll);
          setError('⏱️ Still processing... Check Dashboard later or try a smaller PDF');
          setProgress(0);
        }

      } catch (err) {
        console.error('Polling error:', err);
        attempts++;
        if (attempts >= maxAttempts) {
          clearInterval(poll);
          setError('❌ Connection lost - please try again');
          setProgress(0);
        }
      }
    }, pollInterval);
  };

  /**
   * Reset form
   */
  const handleReset = () => {
    setSelectedFile(null);
    setExtractionJob(null);
    setExtractionResult(null);
    setProgress(0);
    setError(null);
    setActiveStep(0);
  };

  // Get workflow configuration
  const workflowConfig = WORKFLOW_OPTIONS[selectedWorkflow];

  return (
    <div className="max-w-4xl mx-auto p-6">
      {/* Header */}
      <div className="mb-6">
        <h2 className="text-2xl font-bold text-gray-800 mb-2">
          PDF Extraction & AI Analysis
        </h2>
        <p className="text-gray-600">
          Upload a PDF datasheet for automatic extraction using AI agents
        </p>
      </div>

      {/* Workflow Selection */}
      {!extractionJob && (
        <Card className="mb-6">
          <CardContent>
            <FormControl fullWidth>
              <InputLabel>Extraction Workflow</InputLabel>
              <Select
                value={selectedWorkflow}
                onChange={(e) => setSelectedWorkflow(e.target.value)}
                label="Extraction Workflow"
                disabled={uploading}
              >
                {Object.entries(WORKFLOW_OPTIONS).map(([key, config]) => (
                  <MenuItem key={key} value={key}>
                    <div>
                      <div className="font-semibold">{config.label}</div>
                      <div className="text-sm text-gray-600">{config.description}</div>
                      <div className="text-xs text-gray-500">Duration: {config.duration}</div>
                    </div>
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </CardContent>
        </Card>
      )}

      {/* File Upload Area */}
      {!extractionJob && (
        <Card className="mb-6">
          <CardContent>
            <div
              className={`
                border-2 border-dashed rounded-lg p-8 text-center
                transition-colors duration-200
                ${dragging ? 'border-blue-500 bg-blue-50' : 'border-gray-300'}
                ${selectedFile ? 'bg-green-50 border-green-500' : ''}
              `}
              onDragOver={handleDragOver}
              onDragLeave={handleDragLeave}
              onDrop={handleDrop}
            >
              {!selectedFile ? (
                <>
                  <CloudUpload className="text-gray-400 mb-4" style={{ fontSize: 64 }} />
                  <h3 className="text-lg font-semibold mb-2">
                    Drag & Drop PDF Here
                  </h3>
                  <p className="text-gray-600 mb-4">or</p>
                  <input
                    type="file"
                    accept="application/pdf"
                    onChange={handleFileInputChange}
                    style={{ display: 'none' }}
                    id="file-input"
                  />
                  <label htmlFor="file-input">
                    <Button
                      variant="contained"
                      component="span"
                      startIcon={<Description />}
                    >
                      Browse Files
                    </Button>
                  </label>
                </>
              ) : (
                <>
                  <Description className="text-green-600 mb-4" style={{ fontSize: 64 }} />
                  <h3 className="text-lg font-semibold mb-2 text-green-700">
                    {selectedFile.name}
                  </h3>
                  <p className="text-gray-600 mb-4">
                    {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
                  </p>
                  <div className="flex gap-2 justify-center">
                    <Button
                      variant="contained"
                      onClick={handleUploadAndExtract}
                      disabled={uploading}
                      startIcon={<CloudUpload />}
                    >
                      {uploading ? 'Uploading...' : 'Upload & Extract'}
                    </Button>
                    <Button
                      variant="outlined"
                      onClick={handleReset}
                      disabled={uploading}
                    >
                      Cancel
                    </Button>
                  </div>
                </>
              )}
            </div>
          </CardContent>
        </Card>
      )}

      {/* Extraction Progress */}
      {extractionJob && extractionJob.status === 'processing' && (
        <Card className="mb-6">
          <CardContent>
            <h3 className="text-lg font-semibold mb-4">Extracting Data...</h3>
            
            {/* Progress Bar */}
            <LinearProgress 
              variant="determinate" 
              value={progress} 
              className="mb-4"
            />
            <p className="text-center text-sm text-gray-600 mb-4">
              {progress}% Complete
            </p>

            {/* Workflow Steps */}
            <Stepper activeStep={activeStep} className="mb-4">
              {workflowConfig.steps.map((step, index) => (
                <Step key={step}>
                  <StepLabel>{step}</StepLabel>
                </Step>
              ))}
            </Stepper>

            {/* Job Details */}
            <div className="bg-gray-50 rounded p-4 text-sm">
              <div className="grid grid-cols-2 gap-2">
                <div>
                  <span className="font-semibold">Job ID:</span> {extractionJob.id.slice(0, 8)}
                </div>
                <div>
                  <span className="font-semibold">Workflow:</span> {workflowConfig.label}
                </div>
                <div>
                  <span className="font-semibold">Status:</span> 
                  <Chip 
                    label={extractionJob.status} 
                    size="small" 
                    color="primary" 
                    className="ml-2"
                  />
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Extraction Result */}
      {extractionResult && extractionResult.status === 'completed' && (
        <Card className="mb-6">
          <CardContent>
            <div className="flex items-center gap-2 mb-4">
              <Check className="text-green-600" style={{ fontSize: 32 }} />
              <h3 className="text-lg font-semibold text-green-700">
                Extraction Completed Successfully!
              </h3>
            </div>

            {/* Extraction Metrics */}
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-4">
              <div className="bg-blue-50 p-4 rounded text-center">
                <div className="text-2xl font-bold text-blue-600">
                  {extractionResult.fields_extracted || 0}
                </div>
                <div className="text-sm text-gray-600">Fields Extracted</div>
              </div>
              
              <div className="bg-green-50 p-4 rounded text-center">
                <div className="text-2xl font-bold text-green-600">
                  {extractionResult.confidence_score 
                    ? `${(extractionResult.confidence_score * 100).toFixed(0)}%`
                    : 'N/A'}
                </div>
                <div className="text-sm text-gray-600">Confidence</div>
              </div>
              
              <div className="bg-purple-50 p-4 rounded text-center">
                <div className="text-2xl font-bold text-purple-600">
                  {extractionResult.validation_score 
                    ? `${(extractionResult.validation_score * 100).toFixed(0)}%`
                    : 'N/A'}
                </div>
                <div className="text-sm text-gray-600">Validation Score</div>
              </div>
              
              <div className="bg-yellow-50 p-4 rounded text-center">
                <div className="text-2xl font-bold text-yellow-600">
                  {extractionResult.processing_time 
                    ? `${extractionResult.processing_time.toFixed(1)}s`
                    : 'N/A'}
                </div>
                <div className="text-sm text-gray-600">Processing Time</div>
              </div>
            </div>

            {/* Actions */}
            <div className="flex gap-2 justify-center">
              {extractionResult.datasheet && (
                <Button
                  variant="contained"
                  onClick={() => {
                    if (onDatasheetCreated) {
                      onDatasheetCreated(extractionResult.datasheet);
                    }
                  }}
                >
                  View Datasheet
                </Button>
              )}
              <Button
                variant="outlined"
                startIcon={<Refresh />}
                onClick={handleReset}
              >
                Extract Another PDF
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Error Display */}
      {error && (
        <Alert 
          severity="error" 
          className="mb-6"
          action={
            <Button color="inherit" size="small" onClick={handleReset}>
              Try Again
            </Button>
          }
        >
          {error}
        </Alert>
      )}
    </div>
  );
};

export default PDFUploadExtractor;

/**
 * Pump Hydraulic — History Panel (slide-over)
 * ===========================================
 * A right-side drawer that lists snapshots grouped by project. Lets the
 * user load, re-download, or delete any past document.
 *
 * Soft-coded:
 *   • Pulls metadata fields from `HISTORY_META_FIELDS` — extending
 *     metadata is a one-line change in the history config.
 *   • Source-badge palette is module-level — no inline magic.
 *   • Uses the existing exporter for the "Download" action so the
 *     user gets the same .xlsx artifact for any snapshot.
 *
 * No backend calls — pure client-side state.
 */
import { useEffect, useMemo, useState } from 'react';
import {
  X, History as HistoryIcon, Download, Upload, Trash2, FolderOpen,
  Sparkles, User, Save as SaveIcon, Search, AlertCircle, Cloud, HardDrive,
  RefreshCw,
} from 'lucide-react';
import {
  listProjects, listSnapshots, loadSnapshot, deleteSnapshot, deleteProject,
  HISTORY_EVENT, SNAPSHOT_SOURCES, HISTORY_META_FIELDS,
} from '../../config/pumpHydraulicHistory';
import {
  cloudListSnapshots, cloudListProjects, isCloudAvailable,
} from '../../config/pumpHydraulicHistoryCloud';
import exportPumpHydraulicWorkbook from '../../config/pumpHydraulicExporter';
import { STORAGE_KEY as FORM_STORAGE_KEY } from '../../config/pumpHydraulicTemplate.config';
import { REFRESH_EVENT } from '../../config/pumpHydraulicAIMapper';

// ─── Soft-coded UI constants ─────────────────────────────────────────────
const SOURCE_BADGES = {
  [SNAPSHOT_SOURCES.AI_EXTRACTION]: { label: 'AI Extracted', icon: Sparkles, color: 'bg-amber-100 text-amber-800 border-amber-200' },
  [SNAPSHOT_SOURCES.MANUAL]:        { label: 'Manual Save',  icon: User,     color: 'bg-blue-100 text-blue-800 border-blue-200'   },
  [SNAPSHOT_SOURCES.AUTO]:          { label: 'Auto Save',    icon: SaveIcon, color: 'bg-slate-100 text-slate-700 border-slate-200' },
};

const formatTime = (iso) => {
  if (!iso) return '';
  try {
    const d = new Date(iso);
    return d.toLocaleString(undefined, { dateStyle: 'medium', timeStyle: 'short' });
  } catch { return iso; }
};

// ──────────────────────────────────────────────────────────────────────────
const PumpHydraulicHistoryPanel = ({ open, onClose, onAfterLoad }) => {
  const [tick, setTick]               = useState(0); // re-render trigger
  const [activeProject, setActive]    = useState(null); // null = "All projects"
  const [filter, setFilter]           = useState('');
  const [confirm, setConfirm]         = useState(null); // { type, id|key }
  // Cloud mode — when ON, the panel shows snapshots from the Postgres
  // (Railway) backend instead of localStorage. Soft-coded default: cloud
  // when authenticated, local otherwise.
  const cloudOk = isCloudAvailable();
  const [mode, setMode]               = useState(cloudOk ? 'cloud' : 'local');
  const [cloudSnapshots, setCloudSnapshots] = useState([]);
  const [cloudProjects,  setCloudProjects]  = useState([]);
  const [cloudLoading,   setCloudLoading]   = useState(false);
  const [cloudError,     setCloudError]     = useState('');

  // Refresh whenever history mutates anywhere in the app.
  useEffect(() => {
    const bump = () => setTick((n) => n + 1);
    window.addEventListener(HISTORY_EVENT, bump);
    const onStorage = (e) => { if (e.key === FORM_STORAGE_KEY || e.key === null) bump(); };
    window.addEventListener('storage', onStorage);
    return () => {
      window.removeEventListener(HISTORY_EVENT, bump);
      window.removeEventListener('storage', onStorage);
    };
  }, []);

  // Cloud fetch — runs on open / mode toggle / project change / tick.
  useEffect(() => {
    if (!open || mode !== 'cloud') return;
    let cancelled = false;
    setCloudLoading(true);
    setCloudError('');
    Promise.all([
      cloudListSnapshots(activeProject ? { projectKey: activeProject } : {}),
      cloudListProjects(),
    ])
      .then(([snaps, projs]) => {
        if (cancelled) return;
        setCloudSnapshots(snaps);
        setCloudProjects(projs);
      })
      .catch((err) => {
        if (cancelled) return;
        setCloudError(err?.response?.data?.detail || err?.message || 'Cloud fetch failed');
      })
      .finally(() => { if (!cancelled) setCloudLoading(false); });
    return () => { cancelled = true; };
  }, [open, mode, activeProject, tick]);

  const projects  = useMemo(
    () => (mode === 'cloud' ? cloudProjects : listProjects()),
    [mode, cloudProjects, tick],
  );
  const snapshots = useMemo(
    () => (mode === 'cloud'
      ? cloudSnapshots
      : listSnapshots(activeProject ? { projectKey: activeProject } : {})),
    [mode, cloudSnapshots, tick, activeProject],
  );

  const filtered = useMemo(() => {
    if (!filter.trim()) return snapshots;
    const q = filter.trim().toLowerCase();
    return snapshots.filter((s) => {
      if ((s.label || '').toLowerCase().includes(q))      return true;
      if ((s.projectKey || '').toLowerCase().includes(q)) return true;
      for (const { key } of HISTORY_META_FIELDS) {
        if (String(s.meta?.[key] ?? '').toLowerCase().includes(q)) return true;
      }
      return false;
    });
  }, [snapshots, filter]);

  if (!open) return null;

  const handleLoad = (id) => {
    if (mode === 'cloud') {
      const snap = cloudSnapshots.find((s) => s.id === id);
      if (!snap) return;
      try {
        localStorage.setItem(FORM_STORAGE_KEY, JSON.stringify(snap.formState || {}));
        window.dispatchEvent(new CustomEvent(REFRESH_EVENT, { detail: { source: 'cloud', id } }));
        window.dispatchEvent(new StorageEvent('storage', { key: FORM_STORAGE_KEY }));
      } catch { /* no-op */ }
      onAfterLoad?.(id);
      onClose?.();
      return;
    }
    if (loadSnapshot(id)) {
      onAfterLoad?.(id);
      onClose?.();
    }
  };

  const handleDownload = (snap) => {
    // Temporarily swap form state, export, then restore current state.
    const current = localStorage.getItem(FORM_STORAGE_KEY);
    try {
      localStorage.setItem(FORM_STORAGE_KEY, JSON.stringify(snap.formState || {}));
      const safeName = (snap.meta?.pump_tag_no || snap.meta?.job_no || snap.projectKey || 'Pump_Hydraulic')
        .replace(/[\\/*?:[\]\s]+/g, '_');
      exportPumpHydraulicWorkbook(`${safeName}_${snap.id}.xlsx`);
    } finally {
      if (current !== null) localStorage.setItem(FORM_STORAGE_KEY, current);
      else localStorage.removeItem(FORM_STORAGE_KEY);
    }
  };

  const doConfirm = () => {
    if (!confirm) return;
    if (confirm.type === 'snapshot') deleteSnapshot(confirm.id);
    else if (confirm.type === 'project') deleteProject(confirm.key);
    setConfirm(null);
  };

  return (
    <div className="fixed inset-0 z-50 flex">
      {/* Backdrop */}
      <button
        type="button"
        aria-label="Close history"
        onClick={onClose}
        className="flex-1 bg-slate-900/40 backdrop-blur-sm"
      />
      {/* Drawer */}
      <aside className="w-full max-w-3xl bg-white shadow-2xl flex flex-col h-full">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-slate-200 bg-gradient-to-r from-blue-600 to-blue-700 text-white">
          <div className="flex items-center gap-2">
            <HistoryIcon className="w-5 h-5" />
            <h2 className="text-lg font-bold">Document History</h2>
            <span className="text-xs opacity-80 ml-2">Per-project snapshot archive</span>
          </div>
          <div className="flex items-center gap-2">
            {/* Cloud / Local toggle */}
            <div className="inline-flex bg-white/15 rounded-lg overflow-hidden text-xs">
              <button
                onClick={() => cloudOk && setMode('cloud')}
                disabled={!cloudOk}
                className={`px-2.5 py-1.5 inline-flex items-center gap-1 transition-colors ${
                  mode === 'cloud' ? 'bg-white text-blue-700' : 'text-white hover:bg-white/15 disabled:opacity-50'
                }`}
                title={cloudOk ? 'Show snapshots stored in the cloud database' : 'Sign in to enable cloud sync'}
              >
                <Cloud className="w-3.5 h-3.5" /> Cloud
              </button>
              <button
                onClick={() => setMode('local')}
                className={`px-2.5 py-1.5 inline-flex items-center gap-1 transition-colors ${
                  mode === 'local' ? 'bg-white text-blue-700' : 'text-white hover:bg-white/15'
                }`}
                title="Show snapshots stored on this device"
              >
                <HardDrive className="w-3.5 h-3.5" /> Local
              </button>
            </div>
            {mode === 'cloud' && (
              <button
                onClick={() => setTick((n) => n + 1)}
                className="p-1.5 hover:bg-white/15 rounded transition-colors"
                aria-label="Refresh"
                title="Refresh"
              >
                <RefreshCw className={`w-4 h-4 ${cloudLoading ? 'animate-spin' : ''}`} />
              </button>
            )}
            <button
              onClick={onClose}
              className="p-1.5 hover:bg-white/15 rounded transition-colors"
              aria-label="Close"
            >
              <X className="w-5 h-5" />
            </button>
          </div>
        </div>

        {mode === 'cloud' && cloudError && (
          <div className="px-5 py-2 text-xs bg-rose-50 border-b border-rose-200 text-rose-800 flex items-center gap-2">
            <AlertCircle className="w-3.5 h-3.5" /> {cloudError}
          </div>
        )}

        {/* Search */}
        <div className="px-5 py-3 border-b border-slate-200 bg-slate-50">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400" />
            <input
              type="text"
              value={filter}
              onChange={(e) => setFilter(e.target.value)}
              placeholder="Search by project, pump tag, label, calc no…"
              className="w-full pl-9 pr-3 py-2 text-sm border border-slate-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-hidden flex">
          {/* Project sidebar */}
          <div className="w-60 border-r border-slate-200 overflow-y-auto bg-slate-50">
            <button
              onClick={() => setActive(null)}
              className={`w-full text-left px-4 py-3 text-sm border-b border-slate-200 transition-colors ${
                activeProject === null ? 'bg-blue-50 text-blue-800 font-semibold' : 'hover:bg-white'
              }`}
            >
              <div className="flex items-center gap-2">
                <FolderOpen className="w-4 h-4" />
                All Projects
                <span className="ml-auto text-xs bg-slate-200 text-slate-700 rounded-full px-2 py-0.5">
                  {snapshots.length || projects.reduce((n, p) => n + p.count, 0)}
                </span>
              </div>
            </button>
            {projects.length === 0 && (
              <div className="px-4 py-6 text-xs text-slate-500 italic text-center">
                No projects yet. Save a snapshot to get started.
              </div>
            )}
            {projects.map((p) => (
              <button
                key={p.projectKey}
                onClick={() => setActive(p.projectKey)}
                className={`w-full text-left px-4 py-3 text-sm border-b border-slate-200 transition-colors group ${
                  activeProject === p.projectKey ? 'bg-blue-50 text-blue-800 font-semibold' : 'hover:bg-white'
                }`}
              >
                <div className="flex items-center gap-2">
                  <FolderOpen className="w-4 h-4 flex-shrink-0" />
                  <span className="truncate flex-1" title={p.projectKey}>{p.projectKey}</span>
                  <span className="text-xs bg-slate-200 text-slate-700 rounded-full px-2 py-0.5">
                    {p.count}
                  </span>
                </div>
                {p.meta?.client_name && (
                  <div className="text-[11px] text-slate-500 mt-1 truncate pl-6">
                    {p.meta.client_name}
                  </div>
                )}
              </button>
            ))}
          </div>

          {/* Snapshot list */}
          <div className="flex-1 overflow-y-auto">
            {activeProject && (
              <div className="px-5 py-3 border-b border-slate-200 bg-white flex items-center justify-between">
                <div className="text-sm font-semibold text-slate-700 truncate">
                  Project: <span className="text-blue-700">{activeProject}</span>
                </div>
                <button
                  onClick={() => setConfirm({ type: 'project', key: activeProject })}
                  className="inline-flex items-center gap-1 text-xs text-rose-600 hover:text-rose-800"
                >
                  <Trash2 className="w-3.5 h-3.5" /> Delete project
                </button>
              </div>
            )}

            {filtered.length === 0 ? (
              <div className="p-10 text-center text-sm text-slate-500">
                <HistoryIcon className="w-10 h-10 mx-auto mb-3 text-slate-300" />
                {filter ? 'No snapshots match your search.' : 'No snapshots yet for this view.'}
              </div>
            ) : (
              <ul className="divide-y divide-slate-200">
                {filtered.map((s) => {
                  const badge = SOURCE_BADGES[s.source] || SOURCE_BADGES[SNAPSHOT_SOURCES.MANUAL];
                  const Badge = badge.icon;
                  return (
                    <li key={s.id} className="p-4 hover:bg-slate-50 transition-colors">
                      <div className="flex items-start justify-between gap-3">
                        <div className="min-w-0 flex-1">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className={`inline-flex items-center gap-1 px-2 py-0.5 text-[11px] font-medium border rounded-full ${badge.color}`}>
                              <Badge className="w-3 h-3" /> {badge.label}
                            </span>
                            <span className="text-xs text-slate-500">{formatTime(s.savedAt)}</span>
                          </div>
                          <div className="mt-1.5 text-sm font-semibold text-slate-900 truncate">
                            {s.label || s.meta?.pump_tag_no || s.projectKey}
                          </div>
                          <div className="mt-1 grid grid-cols-2 gap-x-4 gap-y-0.5 text-[11px] text-slate-600">
                            {HISTORY_META_FIELDS.map(({ key, label }) => {
                              const v = s.meta?.[key];
                              if (!v) return null;
                              return (
                                <div key={key} className="truncate">
                                  <span className="text-slate-400">{label}:</span>{' '}
                                  <span className="text-slate-700">{v}</span>
                                </div>
                              );
                            })}
                          </div>
                          {s.context?.total ? (
                            <div className="mt-1 text-[11px] text-amber-700">
                              {s.context.total} pump(s){s.context.drawing_ref ? ` from ${s.context.drawing_ref}` : ''}
                            </div>
                          ) : null}
                        </div>
                        <div className="flex flex-col gap-1.5 flex-shrink-0">
                          <button
                            onClick={() => handleLoad(s.id)}
                            className="inline-flex items-center gap-1 px-2.5 py-1.5 text-xs font-medium text-white bg-blue-600 hover:bg-blue-700 rounded transition-colors"
                            title="Restore this snapshot into the active form"
                          >
                            <Upload className="w-3.5 h-3.5" /> Load
                          </button>
                          <button
                            onClick={() => handleDownload(s)}
