export default PumpHydraulicHistoryPanel;

import { radaiConfirm } from '../../services/radaiDialog'
/**
 * PumpHydraulicSheetRenderer
 * ==========================
 * Renders a single sub-sheet (tab) of the Pump Hydraulic Calculation
 * datasheet. All structure comes from the soft-coded config; this
 * component contains NO domain logic — it only handles UI and
 * persists user input to localStorage.
 */
import { useCallback, useEffect, useMemo, useState } from 'react';
import { Save, RotateCcw, Sparkles } from 'lucide-react';
import { STORAGE_KEY } from '../../config/pumpHydraulicTemplate.config';
import { REFRESH_EVENT } from '../../config/pumpHydraulicAIMapper';

// ─── Soft-coded UI constants ──────────────────────────────────────────────
const COMPUTED_BG  = 'bg-amber-50';
const COMPUTED_TXT = 'text-amber-900';
const HEADER_BG    = 'bg-slate-100';
const SECTION_BG   = 'bg-gradient-to-r from-blue-600 to-blue-700';
const INPUT_CLS    = 'w-full px-2 py-1 text-sm border border-slate-300 rounded focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent';

// ─── Storage helpers ──────────────────────────────────────────────────────
const loadState = () => {
  try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}'); }
  catch { return {}; }
};
const saveState = (state) => {
  try { localStorage.setItem(STORAGE_KEY, JSON.stringify(state)); } catch { /* quota */ }
};

// ─── Field input renderer ─────────────────────────────────────────────────
const FieldInput = ({ field, value, onChange }) => {
  const isComputed = field.computed || field.readonly;
  const cls = `${INPUT_CLS} ${isComputed ? `${COMPUTED_BG} ${COMPUTED_TXT}` : ''}`;
  if (field.type === 'textarea') {
    return (
      <textarea
        className={cls}
        rows={field.rows || 3}
        readOnly={isComputed}
        value={value ?? field.default ?? ''}
        onChange={(e) => onChange(e.target.value)}
        placeholder={field.placeholder}
      />
    );
  }
  if (field.type === 'select') {
    return (
      <select className={cls} value={value ?? ''} onChange={(e) => onChange(e.target.value)} disabled={isComputed}>
        <option value="">—</option>
        {(field.options || []).map((opt) => <option key={opt} value={opt}>{opt}</option>)}
      </select>
    );
  }
  if (field.type === 'image') {
    return (
      <input
        type="file"
        accept="image/*"
        className="text-sm"
        onChange={(e) => {
          const f = e.target.files?.[0];
          if (!f) return;
          const reader = new FileReader();
          reader.onload = () => onChange(reader.result);
          reader.readAsDataURL(f);
        }}
      />
    );
  }
  return (
    <input
      type={field.type === 'number' ? 'number' : (field.type || 'text')}
      step="any"
      className={cls}
      readOnly={isComputed}
      value={value ?? field.default ?? ''}
      onChange={(e) => onChange(e.target.value)}
      placeholder={field.placeholder}
    />
  );
};

// ─── Section renderer ─────────────────────────────────────────────────────
const SectionRenderer = ({ section, state, setVal }) => {
  const hasMatrixCols = !!section.columns;
  return (
    <div className="border border-slate-200 rounded-lg overflow-hidden mb-6 shadow-sm">
      {section.title && (
        <div className={`${SECTION_BG} text-white px-4 py-2 text-sm font-semibold tracking-wide`}>
          {section.title}
        </div>
      )}
      <div className="bg-white">
        {hasMatrixCols ? (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className={HEADER_BG}>
                  {section.columns.map((c) => (
                    <th key={c} className="px-3 py-2 text-left font-semibold text-slate-700 border border-slate-200 whitespace-nowrap">{c}</th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {section.rows.map((row, idx) => (
                  <RowRenderer key={`${section.title || ''}-${idx}`} row={row} state={state} setVal={setVal} columns={section.columns} />
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
            {section.rows.map((row, idx) => (
              <FlatRowRenderer key={`${section.title || ''}-${idx}`} row={row} state={state} setVal={setVal} />
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// ─── Flat (non-matrix) row ───────────────────────────────────────────────
const FlatRowRenderer = ({ row, state, setVal }) => {
  if (row.kind === 'header') {
    return <div className="md:col-span-2 mt-2 mb-1 text-xs font-bold uppercase tracking-wide text-blue-700">{row.text}</div>;
  }
  if (row.kind === 'note') {
    return <div className="md:col-span-2 text-xs italic text-slate-500">{row.text}</div>;
  }
  if (row.kind === 'field') {
    return (
      <div className="flex flex-col gap-1">
        <label className="text-xs font-medium text-slate-700 flex items-center gap-1">
          {row.label}
          {row.unit && <span className="text-slate-400">[{row.unit}]</span>}
          {row.computed && <Sparkles className="w-3 h-3 text-amber-500" title="Computed" />}
        </label>
        <FieldInput field={row} value={state[row.key]} onChange={(v) => setVal(row.key, v)} />
        {row.hint && <span className="text-[10px] text-slate-400">{row.hint}</span>}
      </div>
    );
  }
  return null;
};

// ─── Matrix row (label + N column inputs) ────────────────────────────────
const RowRenderer = ({ row, state, setVal, columns }) => {
  if (row.kind === 'header') {
    return (
      <tr className={HEADER_BG}>
        <td colSpan={columns.length} className="px-3 py-1.5 text-xs font-bold uppercase tracking-wide text-blue-700 border border-slate-200">
          {row.text}
        </td>
      </tr>
    );
  }
  if (row.kind === 'note') {
    return (
      <tr>
        <td colSpan={columns.length} className="px-3 py-1.5 text-xs italic text-slate-500 border border-slate-200">{row.text}</td>
      </tr>
    );
  }
  if (row.kind === 'matrixRow') {
    const total = columns.length;
    const hasUnit = total - 1 - row.cols >= 1; // first col is label, last N are inputs, optional unit
    return (
      <tr className="hover:bg-slate-50">
        <td className="px-3 py-1.5 border border-slate-200 text-slate-800 align-middle">
          <span className="flex items-center gap-1">
            {row.label}
            {row.computed && <Sparkles className="w-3 h-3 text-amber-500" />}
          </span>
        </td>
        {hasUnit && (
          <td className="px-3 py-1.5 border border-slate-200 text-slate-500 text-xs align-middle">{row.unit || ''}</td>
        )}
        {Array.from({ length: row.cols }, (_, i) => {
          const cellKey = `${row.key}.${i}`;
          return (
            <td key={cellKey} className="px-1.5 py-1 border border-slate-200">
              <FieldInput field={row} value={state[cellKey]} onChange={(v) => setVal(cellKey, v)} />
            </td>
          );
        })}
      </tr>
    );
  }
  if (row.kind === 'matrix') {
    // free-form matrix with `defaultRows` × `cols` cells
    const rowsCount = row.defaultRows || 5;
    return (
      <>
        {Array.from({ length: rowsCount }, (_, r) => (
          <tr key={`${row.key}-r${r}`} className="hover:bg-slate-50">
            {Array.from({ length: row.cols }, (_, c) => {
              const cellKey = `${row.key}.${r}.${c}`;
              const isFixedFirst = row.fixedFirstCol && c === 0;
              const isComputedCol = row.computedCols?.includes(c);
              const field = { type: 'text', readonly: isFixedFirst, computed: isComputedCol };
              const val = isFixedFirst ? r + 1 : state[cellKey];
              return (
                <td key={cellKey} className="px-1.5 py-1 border border-slate-200">
                  <FieldInput field={field} value={val} onChange={(v) => setVal(cellKey, v)} />
                </td>
              );
            })}
          </tr>
        ))}
      </>
    );
  }
  if (row.kind === 'field') {
    // single field embedded in a matrix-section: span all columns
    return (
      <tr>
        <td colSpan={columns.length} className="px-3 py-2 border border-slate-200">
          <div className="flex flex-col gap-1">
            <label className="text-xs font-medium text-slate-700 flex items-center gap-1">
              {row.label}
              {row.unit && <span className="text-slate-400">[{row.unit}]</span>}
              {row.computed && <Sparkles className="w-3 h-3 text-amber-500" />}
            </label>
            <FieldInput field={row} value={state[row.key]} onChange={(v) => setVal(row.key, v)} />
          </div>
        </td>
      </tr>
    );
  }
  return null;
};

// ─── Top-level tab renderer ───────────────────────────────────────────────
export default function PumpHydraulicSheetRenderer({ tab }) {
  const [state, setState] = useState(() => loadState());
  const [savedAt, setSavedAt] = useState(null);

  // Auto-save (debounced via timeout)
  useEffect(() => {
    const id = setTimeout(() => { saveState(state); setSavedAt(new Date()); }, 600);
    return () => clearTimeout(id);
  }, [state]);

  // Re-read state when an external source (AI extraction) writes to it.
  useEffect(() => {
    const onRefresh = () => setState(loadState());
    const onStorage = (e) => { if (e.key === STORAGE_KEY) setState(loadState()); };
    window.addEventListener(REFRESH_EVENT, onRefresh);
    window.addEventListener('storage', onStorage);
    return () => {
      window.removeEventListener(REFRESH_EVENT, onRefresh);
      window.removeEventListener('storage', onStorage);
    };
  }, []);

  const setVal = useCallback((key, value) => {
    setState((prev) => ({ ...prev, [key]: value }));
  }, []);

  const handleManualSave = () => { saveState(state); setSavedAt(new Date()); };
  const handleReset = async () => {
    if ((await radaiConfirm('Reset all fields on this datasheet? This cannot be undone.'))) {
      setState({}); saveState({}); setSavedAt(new Date());
    }
  };

  const savedLabel = useMemo(() => savedAt ? `Saved ${savedAt.toLocaleTimeString()}` : 'Not saved yet', [savedAt]);

  return (
    <div>
      <div className="flex items-center justify-between mb-4">
        <div>
          {tab.description && <p className="text-sm text-slate-600">{tab.description}</p>}
        </div>
        <div className="flex items-center gap-2">
          <span className="text-xs text-slate-500">{savedLabel}</span>
          <button
            onClick={handleManualSave}
            className="inline-flex items-center gap-1 px-3 py-1.5 text-sm bg-blue-600 text-white rounded hover:bg-blue-700"
          >
            <Save className="w-4 h-4" /> Save
          </button>
          <button
            onClick={handleReset}
            className="inline-flex items-center gap-1 px-3 py-1.5 text-sm bg-white border border-slate-300 text-slate-700 rounded hover:bg-slate-50"
          >
            <RotateCcw className="w-4 h-4" /> Reset
          </button>
        </div>
      </div>

      {tab.sections.map((section, idx) => (
        <SectionRenderer key={idx} section={section} state={state} setVal={setVal} />
      ))}

      <div className="mt-2 flex items-center gap-2 text-xs text-slate-500">
        <Sparkles className="w-3 h-3 text-amber-500" />
        Fields highlighted in amber are computed / auto-populated by the engine.
      </div>
    </div>
  );
}

/**
 * Validation Feedback Display Component
 * Shows validation results with severity levels
 * Soft-coded validation rules from backend
 */

import React, { useState } from 'react';
import { 
  Card, 
  CardContent, 
  Accordion, 
  AccordionSummary, 
  AccordionDetails,
  Chip,
  Alert,
  LinearProgress,
  Button,
  Tabs,
  Tab,
  Box
} from '@mui/material';
import {
  ExpandMore,
  Error as ErrorIcon,
  Warning as WarningIcon,
  CheckCircle,
  Info as InfoIcon,
  Build
} from '@mui/icons-material';

// Soft-coded severity configurations
const SEVERITY_CONFIG = {
  critical: {
    icon: <ErrorIcon />,
    color: 'error',
    bgColor: 'bg-red-50',
    textColor: 'text-red-700',
    borderColor: 'border-red-500',
    label: 'Critical'
  },
  high: {
    icon: <ErrorIcon />,
    color: 'error',
    bgColor: 'bg-red-50',
    textColor: 'text-red-600',
    borderColor: 'border-red-400',
    label: 'High'
  },
  medium: {
    icon: <WarningIcon />,
    color: 'warning',
    bgColor: 'bg-yellow-50',
    textColor: 'text-yellow-700',
    borderColor: 'border-yellow-500',
    label: 'Medium'
  },
  low: {
    icon: <InfoIcon />,
    color: 'info',
    bgColor: 'bg-blue-50',
    textColor: 'text-blue-700',
    borderColor: 'border-blue-500',
    label: 'Low'
  }
};

const VALIDATION_TYPE_CONFIG = {
  technical: {
    label: 'Technical Validation',
    icon: '🔧',
    description: 'Engineering calculations and sizing'
  },
  safety: {
    label: 'Safety Validation',
    icon: '⚠️',
    description: 'Safety margins and requirements'
  },
  standards: {
    label: 'Standards Compliance',
    icon: '📋',
    description: 'Code and standard adherence'
  },
  consistency: {
    label: 'Consistency Check',
    icon: '🔄',
    description: 'Cross-field relationships'
  },
  completeness: {
    label: 'Completeness Check',
    icon: '✓',
    description: 'Required field completion'
  }
};

/**
 * Validation Issue Card
 */
const ValidationIssue = ({ issue, onFix }) => {
  const severityConfig = SEVERITY_CONFIG[issue.severity] || SEVERITY_CONFIG.medium;

  return (
    <div className={`p-4 rounded-lg border-l-4 ${severityConfig.bgColor} ${severityConfig.borderColor} mb-3`}>
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-2">
            <Chip 
              label={severityConfig.label} 
              color={severityConfig.color} 
              size="small"
            />
            <span className={`text-sm font-semibold ${severityConfig.textColor}`}>
              {issue.field_label || issue.field_name}
            </span>
          </div>
          
          <p className="text-gray-700 mb-2">{issue.message}</p>
          
          {issue.suggestion && (
            <div className="bg-white rounded p-2 mt-2">
              <div className="text-sm font-semibold text-gray-700 mb-1">
                💡 Suggestion:
              </div>
              <div className="text-sm text-gray-600">{issue.suggestion}</div>
            </div>
          )}

          {issue.rule_description && (
            <div className="text-xs text-gray-500 mt-2">
              Rule: {issue.rule_description}
            </div>
          )}
        </div>

        {onFix && issue.can_auto_fix && (
          <Button
            size="small"
            variant="outlined"
            startIcon={<Build />}
            onClick={() => onFix(issue)}
          >
            Auto Fix
          </Button>
        )}
      </div>
    </div>
  );
};

/**
 * Validation Type Group
 */
const ValidationTypeGroup = ({ type, issues, onFix }) => {
  const typeConfig = VALIDATION_TYPE_CONFIG[type] || {
    label: type,
    icon: '📝',
    description: ''
  };

  const criticalCount = issues.filter(i => i.severity === 'critical').length;
  const highCount = issues.filter(i => i.severity === 'high').length;
  const mediumCount = issues.filter(i => i.severity === 'medium').length;
  const lowCount = issues.filter(i => i.severity === 'low').length;

  return (
    <Accordion defaultExpanded={criticalCount > 0 || highCount > 0}>
      <AccordionSummary expandIcon={<ExpandMore />}>
        <div className="flex items-center justify-between w-full pr-4">
          <div className="flex items-center gap-2">
            <span className="text-2xl">{typeConfig.icon}</span>
            <div>
              <div className="font-semibold">{typeConfig.label}</div>
              <div className="text-sm text-gray-600">{typeConfig.description}</div>
            </div>
          </div>
          
          <div className="flex gap-2">
            {criticalCount > 0 && (
              <Chip label={criticalCount} color="error" size="small" />
            )}
            {highCount > 0 && (
              <Chip label={highCount} color="error" size="small" variant="outlined" />
            )}
            {mediumCount > 0 && (
              <Chip label={mediumCount} color="warning" size="small" />
            )}
            {lowCount > 0 && (
              <Chip label={lowCount} color="info" size="small" />
            )}
          </div>
        </div>
      </AccordionSummary>
      
      <AccordionDetails>
        {issues.map((issue, index) => (
          <ValidationIssue 
            key={index} 
            issue={issue} 
            onFix={onFix}
          />
        ))}
      </AccordionDetails>
    </Accordion>
  );
};

/**
 * Main Validation Feedback Display
 */
const ValidationFeedback = ({ 
  validationResult, 
  onRevalidate,
  onFixIssue 
}) => {
  const [activeTab, setActiveTab] = useState(0);

  if (!validationResult) {
    return (
      <Alert severity="info">
        No validation results available. Please validate the datasheet.
      </Alert>
    );
  }

  // Calculate overall stats
  const totalIssues = validationResult.issues?.length || 0;
  const criticalIssues = validationResult.issues?.filter(i => i.severity === 'critical').length || 0;
  const highIssues = validationResult.issues?.filter(i => i.severity === 'high').length || 0;
  const mediumIssues = validationResult.issues?.filter(i => i.severity === 'medium').length || 0;
  const lowIssues = validationResult.issues?.filter(i => i.severity === 'low').length || 0;
  
  const validationScore = validationResult.validation_score || 0;
  const completenessScore = validationResult.completeness_score || 0;

  // Group issues by type
  const issuesByType = {};
  validationResult.issues?.forEach(issue => {
    const type = issue.validation_type || 'other';
    if (!issuesByType[type]) {
      issuesByType[type] = [];
    }
    issuesByType[type].push(issue);
  });

  // Group issues by severity
  const issuesBySeverity = {
    critical: validationResult.issues?.filter(i => i.severity === 'critical') || [],
    high: validationResult.issues?.filter(i => i.severity === 'high') || [],
    medium: validationResult.issues?.filter(i => i.severity === 'medium') || [],
    low: validationResult.issues?.filter(i => i.severity === 'low') || []
  };

  return (
    <div className="space-y-6">
      {/* Overall Status */}
      <Card>
        <CardContent>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-xl font-bold">Validation Results</h2>
            {onRevalidate && (
              <Button 
                variant="outlined" 
                onClick={onRevalidate}
                size="small"
              >
                Revalidate
              </Button>
            )}
          </div>

          {/* Score Indicators */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-semibold">Validation Score</span>
                <span className={`text-lg font-bold ${
                  validationScore >= 0.8 ? 'text-green-600' :
                  validationScore >= 0.6 ? 'text-yellow-600' :
                  'text-red-600'
                }`}>
                  {(validationScore * 100).toFixed(0)}%
                </span>
              </div>
              <LinearProgress 
                variant="determinate" 
                value={validationScore * 100}
                color={
                  validationScore >= 0.8 ? 'success' :
                  validationScore >= 0.6 ? 'warning' :
                  'error'
                }
              />
            </div>

            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-semibold">Completeness</span>
                <span className={`text-lg font-bold ${
                  completenessScore >= 0.9 ? 'text-green-600' :
                  completenessScore >= 0.7 ? 'text-yellow-600' :
                  'text-red-600'
                }`}>
                  {(completenessScore * 100).toFixed(0)}%
                </span>
              </div>
              <LinearProgress 
                variant="determinate" 
                value={completenessScore * 100}
                color={
                  completenessScore >= 0.9 ? 'success' :
                  completenessScore >= 0.7 ? 'warning' :
                  'error'
                }
              />
            </div>
          </div>

          {/* Issue Summary */}
          <div className="grid grid-cols-2 md:grid-cols-5 gap-3">
            <div className="bg-gray-50 p-3 rounded text-center">
              <div className="text-2xl font-bold text-gray-700">{totalIssues}</div>
              <div className="text-xs text-gray-600">Total Issues</div>
            </div>
            
            <div className="bg-red-50 p-3 rounded text-center">
              <div className="text-2xl font-bold text-red-600">{criticalIssues}</div>
              <div className="text-xs text-gray-600">Critical</div>
            </div>
            
            <div className="bg-red-50 p-3 rounded text-center">
              <div className="text-2xl font-bold text-red-500">{highIssues}</div>
              <div className="text-xs text-gray-600">High</div>
            </div>
            
            <div className="bg-yellow-50 p-3 rounded text-center">
              <div className="text-2xl font-bold text-yellow-600">{mediumIssues}</div>
              <div className="text-xs text-gray-600">Medium</div>
            </div>
            
            <div className="bg-blue-50 p-3 rounded text-center">
              <div className="text-2xl font-bold text-blue-600">{lowIssues}</div>
              <div className="text-xs text-gray-600">Low</div>
            </div>
          </div>

          {/* Approval Status */}
          {validationResult.is_approved !== undefined && (
            <Alert 
              severity={validationResult.is_approved ? 'success' : 'warning'}
              className="mt-4"
              icon={validationResult.is_approved ? <CheckCircle /> : <WarningIcon />}
            >
              {validationResult.is_approved 
                ? 'Datasheet meets all validation requirements and is approved for use'
                : 'Datasheet has validation issues that must be resolved before approval'
              }
            </Alert>
          )}
        </CardContent>
      </Card>

      {/* Issues Display */}
      {totalIssues > 0 && (
        <Card>
          <CardContent>
            <Tabs value={activeTab} onChange={(e, v) => setActiveTab(v)}>
              <Tab label="By Type" />
              <Tab label="By Severity" />
            </Tabs>

            <Box className="mt-4">
              {/* By Type View */}
              {activeTab === 0 && (
                <div>
                  {Object.entries(issuesByType).map(([type, issues]) => (
                    <ValidationTypeGroup
                      key={type}
                      type={type}
                      issues={issues}
                      onFix={onFixIssue}
                    />
                  ))}
                </div>
              )}

              {/* By Severity View */}
              {activeTab === 1 && (
                <div className="space-y-4">
                  {Object.entries(issuesBySeverity).map(([severity, issues]) => (
                    issues.length > 0 && (
                      <div key={severity}>
                        <h3 className="text-lg font-semibold mb-3 flex items-center gap-2">
                          {SEVERITY_CONFIG[severity]?.icon}
                          {SEVERITY_CONFIG[severity]?.label} Issues ({issues.length})
                        </h3>
                        {issues.map((issue, index) => (
                          <ValidationIssue 
                            key={index} 
                            issue={issue}
                            onFix={onFixIssue}
                          />
                        ))}
                      </div>
                    )
                  ))}
                </div>
              )}
            </Box>
          </CardContent>
        </Card>
      )}

      {/* No Issues */}
      {totalIssues === 0 && (
        <Alert severity="success" icon={<CheckCircle />}>
          <div className="font-semibold mb-1">Perfect! No validation issues found.</div>
          <div className="text-sm">
            The datasheet has passed all validation checks and is ready for approval.
          </div>
        </Alert>
      )}
    </div>
  );
};

export default ValidationFeedback;

/**
 * Workflow Progress Tracker Component
 * Real-time visualization of AI agent workflow execution
 * Soft-coded workflow steps from backend
 */

import React, { useState, useEffect } from 'react';
import {
  Card,
  CardContent,
  Stepper,
  Step,
  StepLabel,
  StepContent,
  Chip,
  LinearProgress,
  Alert,
  Avatar
} from '@mui/material';
import {
  Timeline,
  TimelineItem,
  TimelineSeparator,
  TimelineConnector,
  TimelineContent,
  TimelineDot,
  TimelineOppositeContent
} from '@mui/lab';
import {
  CheckCircle,
  Error as ErrorIcon,
  HourglassEmpty,
  PlayArrow,
  Psychology,
  Assessment,
  Verified,
  Speed
} from '@mui/icons-material';

// Soft-coded agent configurations
const AGENT_CONFIG = {
  document_analyzer: {
    name: 'Document Analyzer',
    icon: <Assessment />,
    color: '#3b82f6',
    description: 'Analyzes document structure and metadata'
  },
  field_extractor: {
    name: 'Field Extractor',
    icon: <Psychology />,
    color: '#8b5cf6',
    description: 'Extracts field values using AI vision'
  },
  validation_agent: {
    name: 'Validation Agent',
    icon: <Verified />,
    color: '#f59e0b',
    description: 'Validates extracted data against rules'
  },
  quality_checker: {
    name: 'Quality Checker',
    icon: <CheckCircle />,
    color: '#10b981',
    description: 'Performs final quality assessment'
  },
  calculation_service: {
    name: 'Calculation Engine',
    icon: <Speed />,
    color: '#06b6d4',
    description: 'Executes engineering calculations'
  }
};

// Soft-coded step status configurations
const STEP_STATUS_CONFIG = {
  pending: {
    icon: <HourglassEmpty />,
    color: 'default',
    label: 'Pending',
    bgColor: 'bg-gray-100',
    textColor: 'text-gray-600'
  },
  in_progress: {
    icon: <PlayArrow />,
    color: 'primary',
    label: 'In Progress',
    bgColor: 'bg-blue-100',
    textColor: 'text-blue-600'
  },
  completed: {
    icon: <CheckCircle />,
    color: 'success',
    label: 'Completed',
    bgColor: 'bg-green-100',
    textColor: 'text-green-600'
  },
  failed: {
    icon: <ErrorIcon />,
    color: 'error',
    label: 'Failed',
    bgColor: 'bg-red-100',
    textColor: 'text-red-600'
  }
};

/**
 * Agent Step Card
 */
const AgentStepCard = ({ agent, step, status, duration, output }) => {
  const agentConfig = AGENT_CONFIG[agent] || {
    name: agent,
    icon: <Psychology />,
    color: '#6b7280',
    description: 'Processing...'
  };

  const statusConfig = STEP_STATUS_CONFIG[status] || STEP_STATUS_CONFIG.pending;

  return (
    <div className={`rounded-lg p-4 ${statusConfig.bgColor} border-l-4`}
         style={{ borderLeftColor: agentConfig.color }}>
      <div className="flex items-start gap-3">
        <Avatar sx={{ bgcolor: agentConfig.color }}>
          {agentConfig.icon}
        </Avatar>
        
        <div className="flex-1">
          <div className="flex items-center justify-between mb-2">
            <h4 className="font-semibold text-gray-800">{agentConfig.name}</h4>
            <Chip
              icon={statusConfig.icon}
              label={statusConfig.label}
              color={statusConfig.color}
              size="small"
            />
          </div>
          
          <p className="text-sm text-gray-600 mb-2">{agentConfig.description}</p>
          
          {status === 'in_progress' && (
            <LinearProgress className="mb-2" />
          )}
          
          {duration && status === 'completed' && (
            <div className="text-xs text-gray-500">
              ⏱️ Completed in {duration.toFixed(2)}s
            </div>
          )}
          
          {output && status === 'completed' && (
            <div className="mt-2 bg-white rounded p-2 text-sm">
              <div className="font-semibold text-gray-700 mb-1">Output:</div>
              <div className="text-gray-600">
                {output.fields_extracted && (
                  <div>📝 Extracted {output.fields_extracted} fields</div>
                )}
                {output.confidence && (
                  <div>✨ Confidence: {(output.confidence * 100).toFixed(0)}%</div>
                )}
                {output.issues_found !== undefined && (
                  <div>🔍 Found {output.issues_found} issues</div>
                )}
                {output.quality_score && (
                  <div>⭐ Quality: {(output.quality_score * 100).toFixed(0)}%</div>
                )}
              </div>
            </div>
          )}
          
          {step.error_message && status === 'failed' && (
            <Alert severity="error" className="mt-2">
              {step.error_message}
            </Alert>
          )}
        </div>
      </div>
    </div>
  );
};

/**
 * Timeline View of Workflow
 */
const WorkflowTimeline = ({ steps }) => {
  return (
    <Timeline position="alternate">
      {steps.map((step, index) => {
        const statusConfig = STEP_STATUS_CONFIG[step.status] || STEP_STATUS_CONFIG.pending;
        const agentConfig = AGENT_CONFIG[step.agent] || { name: step.agent, color: '#6b7280' };
        
        return (
          <TimelineItem key={index}>
            <TimelineOppositeContent color="text.secondary">
              {step.completed_at ? new Date(step.completed_at).toLocaleTimeString() : '--:--'}
            </TimelineOppositeContent>
            
            <TimelineSeparator>
              <TimelineDot sx={{ bgcolor: agentConfig.color }}>
                {statusConfig.icon}
              </TimelineDot>
              {index < steps.length - 1 && <TimelineConnector />}
            </TimelineSeparator>
            
            <TimelineContent>
              <Card>
                <CardContent>
                  <div className="font-semibold">{agentConfig.name}</div>
                  <div className="text-sm text-gray-600">{step.action}</div>
                  <Chip 
                    label={statusConfig.label} 
                    color={statusConfig.color} 
                    size="small"
                    className="mt-2"
                  />
                </CardContent>
              </Card>
            </TimelineContent>
          </TimelineItem>
        );
      })}
    </Timeline>
  );
};

/**
 * Main Workflow Progress Tracker
 */
const WorkflowProgressTracker = ({ 
  workflowId,
  workflowType,
  steps = [],
  overallStatus = 'pending',
  startTime,
  endTime,
  showTimeline = false
}) => {
  const [currentStep, setCurrentStep] = useState(0);
  const [totalDuration, setTotalDuration] = useState(0);

  useEffect(() => {
    // Find current step index
    const inProgressIndex = steps.findIndex(s => s.status === 'in_progress');
    const lastCompletedIndex = steps.map((s, i) => s.status === 'completed' ? i : -1)
                                   .filter(i => i >= 0)
                                   .pop();
    
    if (inProgressIndex >= 0) {
      setCurrentStep(inProgressIndex);
    } else if (lastCompletedIndex >= 0) {
      setCurrentStep(lastCompletedIndex + 1);
    }

    // Calculate total duration
    if (startTime && endTime) {
      const duration = (new Date(endTime) - new Date(startTime)) / 1000;
      setTotalDuration(duration);
    }
  }, [steps, startTime, endTime]);

  // Calculate progress percentage
  const completedSteps = steps.filter(s => s.status === 'completed').length;
  const totalSteps = steps.length;
  const progressPercent = totalSteps > 0 ? (completedSteps / totalSteps) * 100 : 0;

  return (
    <div className="space-y-6">
      {/* Workflow Header */}
      <Card>
        <CardContent>
          <div className="flex items-center justify-between mb-4">
            <div>
              <h2 className="text-xl font-bold">Workflow Progress</h2>
              <p className="text-sm text-gray-600">
                {workflowType?.replace(/_/g, ' ').toUpperCase() || 'Processing'}
              </p>
            </div>
            
            <Chip
              icon={STEP_STATUS_CONFIG[overallStatus]?.icon}
              label={STEP_STATUS_CONFIG[overallStatus]?.label}
              color={STEP_STATUS_CONFIG[overallStatus]?.color}
            />
          </div>

          {/* Overall Progress */}
          <div className="mb-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-sm font-semibold">Overall Progress</span>
              <span className="text-sm font-semibold">
                {completedSteps} / {totalSteps} steps
              </span>
            </div>
            <LinearProgress 
              variant="determinate" 
              value={progressPercent}
              color={
                overallStatus === 'completed' ? 'success' :
                overallStatus === 'failed' ? 'error' :
                'primary'
              }
            />
          </div>

          {/* Timing Info */}
          <div className="flex gap-4 text-sm text-gray-600">
            {startTime && (
              <div>
                <span className="font-semibold">Started:</span>{' '}
                {new Date(startTime).toLocaleString()}
              </div>
            )}
            {totalDuration > 0 && (
              <div>
                <span className="font-semibold">Duration:</span>{' '}
                {totalDuration.toFixed(1)}s
              </div>
            )}
            {workflowId && (
              <div>
                <span className="font-semibold">ID:</span>{' '}
                {workflowId.slice(0, 8)}
              </div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Workflow Steps */}
      {!showTimeline ? (
        <Card>
          <CardContent>
            <Stepper activeStep={currentStep} orientation="vertical">
              {steps.map((step, index) => (
                <Step key={index} completed={step.status === 'completed'}>
                  <StepLabel error={step.status === 'failed'}>
                    <div className="flex items-center gap-2">
                      {AGENT_CONFIG[step.agent]?.name || step.agent}
                      {step.status === 'in_progress' && (
                        <Chip label="Processing" size="small" color="primary" />
                      )}
                    </div>
                  </StepLabel>
                  <StepContent>
                    <AgentStepCard
                      agent={step.agent}
                      step={step}
                      status={step.status}
                      duration={step.duration}
                      output={step.output}
                    />
                  </StepContent>
                </Step>
              ))}
            </Stepper>
          </CardContent>
        </Card>
      ) : (
        <Card>
          <CardContent>
            <WorkflowTimeline steps={steps} />
          </CardContent>
        </Card>
      )}

      {/* Workflow Result */}
      {overallStatus === 'completed' && (
        <Alert severity="success" icon={<CheckCircle />}>
          <div className="font-semibold mb-1">Workflow completed successfully!</div>
          <div className="text-sm">
            All {totalSteps} steps completed in {totalDuration.toFixed(1)} seconds.
          </div>
        </Alert>
      )}

      {overallStatus === 'failed' && (
        <Alert severity="error" icon={<ErrorIcon />}>
          <div className="font-semibold mb-1">Workflow failed</div>
          <div className="text-sm">
            One or more steps encountered errors. Please check the details above.
          </div>
        </Alert>
      )}
    </div>
  );
};

/**
 * Compact Progress Indicator (for inline display)
 */
export const CompactWorkflowProgress = ({ steps, status }) => {
  const completedSteps = steps.filter(s => s.status === 'completed').length;
  const totalSteps = steps.length;
  const progressPercent = (completedSteps / totalSteps) * 100;

  return (
    <div className="flex items-center gap-3">
      <div className="flex-1">
        <div className="text-xs text-gray-600 mb-1">
          {completedSteps} / {totalSteps} steps
        </div>
        <LinearProgress 
          variant="determinate" 
          value={progressPercent}
          color={status === 'completed' ? 'success' : 'primary'}
          sx={{ height: 6, borderRadius: 3 }}
        />
      </div>
      <Chip
        icon={STEP_STATUS_CONFIG[status]?.icon}
        label={STEP_STATUS_CONFIG[status]?.label}
        color={STEP_STATUS_CONFIG[status]?.color}
        size="small"
      />
    </div>
  );
};

export default WorkflowProgressTracker;

import { radaiConfirm } from '../../services/radaiDialog'
import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import {
  Trophy, Award, Medal, Sparkles, Plus, X, Edit2, Check,
  ExternalLink, Calendar, MapPin, Building2, Star, Trash2
} from 'lucide-react';
import { API_BASE_URL } from '../../config/api.config';

/**
 * Achievement Section — Sports, Academics, Professional, Genius Records
 * Soft-coded categories fetched from backend
 */
const AchievementSection = () => {
  const [achievements, setAchievements] = useState([]);
  const [categories, setCategories] = useState([]);
  const [levels, setLevels] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);
  
  // Form state
  const [formData, setFormData] = useState({
    title: '',
    category: '',
    description: '',
    level: '',
    achieved_date: '',
    location: '',
    organization: '',
    certificate_url: '',
    media_url: '',
    is_public: true,
  });

  useEffect(() => {
    fetchAchievements();
    fetchCategories();
    fetchLevels();
  }, []);

  const fetchAchievements = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/achievements/?mine=true`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Failed to fetch achievements');
      const data = await res.json();
      setAchievements(Array.isArray(data) ? data : data.results || []);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchCategories = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/achievements/categories/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setCategories(data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const fetchLevels = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/achievements/levels/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setLevels(data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.title || !formData.category) {
      toast.error('Title and category are required');
      return;
    }

    setIsLoading(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const url = editingId
        ? `${API_BASE_URL}/rbac/achievements/${editingId}/`
        : `${API_BASE_URL}/rbac/achievements/`;
      
      const res = await fetch(url, {
        method: editingId ? 'PATCH' : 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (!res.ok) {
        const error = await res.json().catch(() => ({}));
        const fieldError = Object.values(error)
          .flat()
          .find(value => typeof value === 'string' && value.trim());
        throw new Error(error.detail || error.error || fieldError || 'Failed to save achievement');
      }

      toast.success(editingId ? 'Achievement updated!' : 'Achievement added!');
      await fetchAchievements();
      resetForm();
    } catch (err) {
      toast.error(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleEdit = (achievement) => {
    setEditingId(achievement.id);
    setFormData({
      title: achievement.title,
      category: achievement.category,
      description: achievement.description || '',
      level: achievement.level || '',
      achieved_date: achievement.achieved_date || '',
      location: achievement.location || '',
      organization: achievement.organization || '',
      certificate_url: achievement.certificate_url || '',
      media_url: achievement.media_url || '',
      is_public: achievement.is_public,
    });
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (!(await radaiConfirm('Delete this achievement?'))) return;
    
    setIsLoading(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/achievements/${id}/`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error('Failed to delete');
      toast.success('Achievement deleted');
      await fetchAchievements();
    } catch (err) {
      toast.error(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      title: '',
      category: '',
      description: '',
      level: '',
      achieved_date: '',
      location: '',
      organization: '',
      certificate_url: '',
      media_url: '',
      is_public: true,
    });
    setEditingId(null);
    setShowForm(false);
  };

  const getCategoryConfig = (categoryCode) => {
    return categories.find(c => c.value === categoryCode) || {};
  };

  const getLevelConfig = (levelCode) => {
    return levels.find(l => l.value === levelCode) || {};
  };

  const inputCls = 'w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white text-gray-900 placeholder-gray-400 transition-all';
  const labelCls = 'block text-sm font-medium text-gray-700 mb-1.5';

  // Group achievements by category
  const groupedAchievements = achievements.reduce((acc, ach) => {
    if (!acc[ach.category]) acc[ach.category] = [];
    acc[ach.category].push(ach);
    return acc;
  }, {});

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
            <Trophy className="w-6 h-6 text-yellow-500" />
            Achievements & Milestones
          </h2>
          <p className="text-sm text-gray-500 mt-1">
            Showcase your sports, academic, professional achievements and genius records
          </p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2 font-semibold transition-all"
        >
          <Plus className="w-4 h-4" />
          Add Achievement
        </button>
      </div>

      {/* Add/Edit Form */}
      {showForm && (
        <div className="bg-gradient-to-br from-blue-50 to-purple-50 rounded-xl p-6 border-2 border-blue-200">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900">
              {editingId ? 'Edit Achievement' : 'New Achievement'}
            </h3>
            <button onClick={resetForm} className="text-gray-400 hover:text-gray-600">
              <X className="w-5 h-5" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div className="sm:col-span-2">
                <label className={labelCls}>Achievement Title *</label>
                <input
                  type="text"
                  value={formData.title}
                  onChange={e => setFormData(p => ({ ...p, title: e.target.value }))}
                  className={inputCls}
                  placeholder="e.g., First Place - Regional Football Championship"
                  required
                />
              </div>

              <div>
                <label className={labelCls}>Category *</label>
                <select
                  value={formData.category}
                  onChange={e => setFormData(p => ({ ...p, category: e.target.value }))}
                  className={inputCls}
                  required
                >
                  <option value="">Select category...</option>
                  {categories.map(cat => (
                    <option key={cat.value} value={cat.value}>
                      {cat.icon} {cat.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className={labelCls}>Achievement Level</label>
                <select
                  value={formData.level}
                  onChange={e => setFormData(p => ({ ...p, level: e.target.value }))}
                  className={inputCls}
                >
                  <option value="">Select level...</option>
                  {levels.map(lvl => (
                    <option key={lvl.value} value={lvl.value}>
                      {lvl.icon} {lvl.label}
                    </option>
                  ))}
                </select>
              </div>

              <div>
                <label className={labelCls}>Date Achieved</label>
                <input
                  type="date"
                  value={formData.achieved_date}
                  onChange={e => setFormData(p => ({ ...p, achieved_date: e.target.value }))}
                  className={inputCls}
                />
              </div>

              <div>
                <label className={labelCls}>Location</label>
                <input
                  type="text"
                  value={formData.location}
                  onChange={e => setFormData(p => ({ ...p, location: e.target.value }))}
                  className={inputCls}
                  placeholder="City, Country or Event Location"
                />
              </div>

              <div className="sm:col-span-2">
                <label className={labelCls}>Organization / Institution</label>
                <input
                  type="text"
                  value={formData.organization}
                  onChange={e => setFormData(p => ({ ...p, organization: e.target.value }))}
                  className={inputCls}
                  placeholder="Issuing organization or institution"
                />
              </div>

              <div className="sm:col-span-2">
                <label className={labelCls}>Description</label>
                <textarea
                  value={formData.description}
                  onChange={e => setFormData(p => ({ ...p, description: e.target.value }))}
                  rows={3}
                  className={`${inputCls} resize-none`}
                  placeholder="Detailed description of your achievement..."
                />
              </div>

              <div>
                <label className={labelCls}>Certificate URL</label>
                <input
                  type="url"
                  value={formData.certificate_url}
                  onChange={e => setFormData(p => ({ ...p, certificate_url: e.target.value }))}
                  className={inputCls}
                  placeholder="https://..."
                />
              </div>

              <div>
                <label className={labelCls}>Media URL (Photo/Video)</label>
                <input
                  type="url"
                  value={formData.media_url}
                  onChange={e => setFormData(p => ({ ...p, media_url: e.target.value }))}
                  className={inputCls}
                  placeholder="https://..."
                />
              </div>

              <div className="sm:col-span-2 flex items-center gap-2">
                <input
                  type="checkbox"
                  id="is_public"
                  checked={formData.is_public}
                  onChange={e => setFormData(p => ({ ...p, is_public: e.target.checked }))}
                  className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                />
                <label htmlFor="is_public" className="text-sm font-medium text-gray-700">
                  Show on public profile
                </label>
              </div>
            </div>

            <div className="flex gap-3 justify-end pt-2">
              <button
                type="button"
                onClick={resetForm}
                className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-semibold"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={isLoading}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2 font-semibold"
              >
                {isLoading ? 'Saving...' : (editingId ? 'Update' : 'Add Achievement')}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Achievement Display */}
      {achievements.length === 0 ? (
        <div className="text-center py-12 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200">
          <Trophy className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-600 mb-2">No achievements yet</h3>
          <p className="text-gray-400 mb-4">Start showcasing your accomplishments!</p>
          <button
            onClick={() => setShowForm(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 inline-flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Add First Achievement
          </button>
        </div>
      ) : (
        <div className="space-y-6">
          {Object.entries(groupedAchievements).map(([categoryCode, categoryAchievements]) => {
            const catConfig = getCategoryConfig(categoryCode);
            return (
              <div key={categoryCode} className="space-y-3">
                <h3 className="text-lg font-semibold text-gray-800 flex items-center gap-2">
                  <span className="text-2xl">{catConfig.icon}</span>
                  {catConfig.label}
                  <span className="text-sm font-normal text-gray-400">
                    ({categoryAchievements.length})
                  </span>
                </h3>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {categoryAchievements.map(achievement => {
                    const levelConfig = getLevelConfig(achievement.level);
                    return (
                      <div
                        key={achievement.id}
                        className={`bg-gradient-to-br from-white to-${catConfig.color}-50 border-2 border-${catConfig.color}-200 rounded-xl p-5 hover:shadow-lg transition-all group`}
                      >
                        <div className="flex items-start justify-between mb-3">
                          <div className="flex items-start gap-3 flex-1">
                            <div className={`w-12 h-12 rounded-full bg-${catConfig.color}-100 flex items-center justify-center text-2xl flex-shrink-0`}>
                              {catConfig.icon}
                            </div>
                            <div className="flex-1 min-w-0">
                              <h4 className="font-bold text-gray-900 text-base leading-tight mb-1">
                                {achievement.title}
                              </h4>
                              {levelConfig.icon && (
                                <span className="text-xs px-2 py-0.5 rounded-full bg-yellow-100 text-yellow-700 font-semibold inline-flex items-center gap-1">
                                  <span>{levelConfig.icon}</span>
                                  {levelConfig.label}
                                </span>
                              )}
                            </div>
                          </div>
                          <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                            <button
                              onClick={() => handleEdit(achievement)}
                              className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg"
                              title="Edit"
                            >
                              <Edit2 className="w-4 h-4" />
                            </button>
                            <button
                              onClick={() => handleDelete(achievement.id)}
                              className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg"
                              title="Delete"
                            >
                              <Trash2 className="w-4 h-4" />
                            </button>
                          </div>
                        </div>

                        {achievement.description && (
                          <p className="text-sm text-gray-600 mb-3 line-clamp-2">
                            {achievement.description}
                          </p>
                        )}

                        <div className="flex flex-wrap gap-2 text-xs text-gray-500">
                          {achievement.achieved_date && (
                            <span className="flex items-center gap-1">
                              <Calendar className="w-3.5 h-3.5" />
                              {new Date(achievement.achieved_date).toLocaleDateString('en-US', {
                                month: 'short',
                                year: 'numeric'
                              })}
                            </span>
                          )}
                          {achievement.location && (
                            <span className="flex items-center gap-1">
                              <MapPin className="w-3.5 h-3.5" />
                              {achievement.location}
                            </span>
                          )}
                          {achievement.organization && (
                            <span className="flex items-center gap-1">
                              <Building2 className="w-3.5 h-3.5" />
                              {achievement.organization}
                            </span>
                          )}
                        </div>

                        {(achievement.certificate_url || achievement.media_url) && (
                          <div className="flex gap-2 mt-3 pt-3 border-t border-gray-100">
                            {achievement.certificate_url && (
                              <a
                                href={achievement.certificate_url}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-xs text-blue-600 hover:text-blue-700 flex items-center gap-1 font-medium"
                              >
                                <ExternalLink className="w-3.5 h-3.5" />
                                Certificate
                              </a>
                            )}
                            {achievement.media_url && (
                              <a
                                href={achievement.media_url}
                                target="_blank"
                                rel="noopener noreferrer"
                                className="text-xs text-purple-600 hover:text-purple-700 flex items-center gap-1 font-medium"
                              >
                                <ExternalLink className="w-3.5 h-3.5" />
                                Media
                              </a>
                            )}
                          </div>
                        )}

                        {achievement.is_verified && (
                          <div className="mt-3 flex items-center gap-1 text-xs text-green-600">
                            <Check className="w-3.5 h-3.5" />
                            <span className="font-medium">Verified</span>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
};

export default AchievementSection;

import './ProfileDocumentsList.css';
import { radaiConfirm } from '../../services/radaiDialog'
import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'react-toastify';
import {
  FileText, Upload, X, Edit2, Check, Trash2, Calendar,
  AlertCircle, CheckCircle, Clock, XCircle, Eye, Download, Loader2
} from 'lucide-react';
import { API_BASE_URL } from '../../config/api.config';
import { DOCUMENT_UPLOAD_CONFIG, validateDocument, formatFileSize } from '../../config/s3Upload.config';

/**
 * Document Upload Section — Emirates ID, Driving License, Country ID, etc.
 * Soft-coded document types fetched from backend
 */
const DocumentUploadSection = () => {
  const [documents, setDocuments] = useState([]);
  const [documentTypes, setDocumentTypes] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [uploadingType, setUploadingType] = useState(null);
  const [editingDoc, setEditingDoc] = useState(null);
  const [isEditingDetails, setIsEditingDetails] = useState(false); // ✅ SOFT-CODED: Track if editing details only
  const [previewDocument, setPreviewDocument] = useState(null);
  const [previewUrl, setPreviewUrl] = useState('');
  const [previewMimeType, setPreviewMimeType] = useState('');
  const [isPreviewLoading, setIsPreviewLoading] = useState(false);
  const [isExtracting, setIsExtracting] = useState(false);
  const fileInputRef = useRef(null);

  // Form state
  const [formData, setFormData] = useState({
    document_type: '',
    document_file: null,
    document_number: '',
    issue_date: '',
    expiry_date: '',
    issuing_authority: '',
    notes: ''
  });

  useEffect(() => {
    fetchDocuments();
    fetchDocumentTypes();
  }, []);

  useEffect(() => () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
  }, [previewUrl]);

  const fetchDocuments = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/profile-documents/my_documents/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Failed to fetch documents');
      const data = await res.json();
      setDocuments(data);
    } catch (err) {
      console.error(err);
      toast.error('Failed to load documents');
    }
  };

  const fetchDocumentTypes = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      // ✅ USE FILTERED ENDPOINT: Only fetch document types shown in profile page (identity + health)
      const res = await fetch(`${API_BASE_URL}/rbac/profile-documents/document-types/profile/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setDocumentTypes(data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const extractMetadata = async (file, documentType) => {
    setIsExtracting(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const extractionData = new FormData();
      extractionData.append('document_file', file);
      extractionData.append('document_type', documentType);

      const res = await fetch(`${API_BASE_URL}/rbac/profile-documents/extract-metadata/`, {
        method: 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: extractionData,
      });
      const result = await res.json().catch(() => ({}));
      if (!res.ok) {
        throw new Error(result.detail || 'Automatic detection was not available');
      }

      setFormData(prev => ({
        ...prev,
        document_number: result.document_number || prev.document_number,
        issuing_authority: result.issuing_authority || prev.issuing_authority,
        issue_date: result.issue_date || prev.issue_date,
        expiry_date: result.expiry_date || prev.expiry_date,
      }));

      if (result.detected_fields?.length) {
        toast.success(`${result.detected_fields.length} document detail(s) detected. Please verify them.`);
      } else {
        toast.info('No details were detected. Please complete the fields manually.');
      }
    } catch (err) {
      console.error(err);
      toast.info(`${err.message}. You can enter the details manually.`);
    } finally {
      setIsExtracting(false);
    }
  };

  const handleFileSelect = (e, documentType) => {
    const file = e.target.files[0];
    if (!file) return;

    const validation = validateDocument(file);
    if (!validation.isValid) {
      toast.error(validation.errors.join(', '));
      return;
    }

    setFormData(prev => ({
      ...prev,
      document_type: documentType,
      document_file: file
    }));
    setUploadingType(documentType);
    extractMetadata(file, documentType);
  };

  const handleUpload = async () => {
    // ✅ SOFT-CODED: Allow saving details without file for edit mode
    if (!isEditingDetails && (!formData.document_file || !formData.document_type)) {
      toast.error('Please select a file');
      return;
    }

    setIsLoading(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');

      const formDataToSend = new FormData();
      formDataToSend.append('document_type', formData.document_type);

      // ✅ SOFT-CODED: Only append file if provided (for replace) or if new upload
      if (formData.document_file) {
        formDataToSend.append('document_file', formData.document_file);
      }

      if (formData.document_number) formDataToSend.append('document_number', formData.document_number);
      if (formData.issue_date) formDataToSend.append('issue_date', formData.issue_date);
      if (formData.expiry_date) formDataToSend.append('expiry_date', formData.expiry_date);
      if (formData.issuing_authority) formDataToSend.append('issuing_authority', formData.issuing_authority);
      if (formData.notes) formDataToSend.append('notes', formData.notes);

      const url = editingDoc
        ? `${API_BASE_URL}/rbac/profile-documents/${editingDoc.id}/`
        : `${API_BASE_URL}/rbac/profile-documents/`;

      const res = await fetch(url, {
        method: editingDoc ? 'PATCH' : 'POST',
        headers: { Authorization: `Bearer ${token}` },
        body: formDataToSend,
      });

      if (!res.ok) {
        const error = await res.json();
        throw new Error(error.detail || 'Upload failed');
      }

      const actionMessage = isEditingDetails
        ? 'Document details updated successfully'
        : DOCUMENT_UPLOAD_CONFIG.messages.uploadSuccess;

      toast.success(actionMessage);
      resetForm();
      fetchDocuments();
    } catch (err) {
      console.error(err);
      toast.error(err.message || DOCUMENT_UPLOAD_CONFIG.messages.uploadFailed);
    } finally {
      setIsLoading(false);
    }
  };

  const handleDelete = async (docId) => {
    if (!(await radaiConfirm('Are you sure you want to delete this document?'))) return;

    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/profile-documents/${docId}/`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error('Delete failed');

      toast.success(DOCUMENT_UPLOAD_CONFIG.messages.deleteSuccess);
      fetchDocuments();
    } catch (err) {
      console.error(err);
      toast.error(DOCUMENT_UPLOAD_CONFIG.messages.deleteFailed);
    }
  };

  const resetForm = () => {
    setFormData({
      document_type: '',
      document_file: null,
      document_number: '',
      issue_date: '',
      expiry_date: '',
      issuing_authority: '',
      notes: ''
    });
    setUploadingType(null);
    setEditingDoc(null);
    setIsEditingDetails(false); // ✅ SOFT-CODED: Reset edit mode
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  // ✅ SOFT-CODED: Handle Edit Details action (no file upload required)
  const handleEditDetails = (doc, type) => {
    setEditingDoc(doc);
    setIsEditingDetails(true);
    setUploadingType(type.code);
    setFormData({
      document_type: type.code,
      document_file: null, // No file required for details edit
      document_number: doc.document_number || '',
      issue_date: doc.issue_date || '',
      expiry_date: doc.expiry_date || '',
      issuing_authority: doc.issuing_authority || '',
      notes: doc.notes || ''
    });
  };

  // ✅ SOFT-CODED: Handle Replace File action (requires new file)
  const handleReplaceFile = async (doc, type) => {
    const actions = DOCUMENT_UPLOAD_CONFIG.actions;
    if (actions.replace.requiresConfirmation &&
        !(await radaiConfirm(actions.replace.confirmMessage))) {
      return;
    }

    setEditingDoc(doc);
    setIsEditingDetails(false);
    setUploadingType(type.code);
    setFormData({
      document_type: type.code,
      document_file: null,
      document_number: doc.document_number || '',
      issue_date: doc.issue_date || '',
      expiry_date: doc.expiry_date || '',
      issuing_authority: doc.issuing_authority || '',
      notes: doc.notes || ''
    });
  };

  // ✅ SOFT-CODED: Handle Download action
  const fetchDocumentBlob = async (doc) => {
    const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
    const res = await fetch(`${API_BASE_URL}/rbac/profile-documents/${doc.id}/content/`, {
      headers: { Authorization: `Bearer ${token}` },
    });
    if (!res.ok) {
      const error = await res.json().catch(() => ({}));
      throw new Error(error.detail || 'Document file not available');
    }
    return res.blob();
  };

  const handleDownload = async (doc) => {
    try {
      const blob = await fetchDocumentBlob(doc);
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = doc.document_file_name || 'document';
      document.body.appendChild(link);
      link.click();
      link.remove();
      URL.revokeObjectURL(url);
    } catch (err) {
      toast.error(err.message);
    }
  };

  // ✅ SOFT-CODED: Handle View action
  const handleView = async (doc) => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewDocument(doc);
    setPreviewUrl('');
    setPreviewMimeType('');
    setIsPreviewLoading(true);
    try {
      const blob = await fetchDocumentBlob(doc);
      setPreviewMimeType(blob.type);
      setPreviewUrl(URL.createObjectURL(blob));
    } catch (err) {
      toast.error(err.message);
      setPreviewDocument(null);
    } finally {
      setIsPreviewLoading(false);
    }
  };

  const closePreview = () => {
    if (previewUrl) URL.revokeObjectURL(previewUrl);
    setPreviewUrl('');
    setPreviewMimeType('');
    setPreviewDocument(null);
  };

  const getVerificationBadge = (status) => {
    const badges = {
      pending: { icon: Clock, text: 'Pending', color: 'yellow' },
      verified: { icon: CheckCircle, text: 'Verified', color: 'green' },
      rejected: { icon: XCircle, text: 'Rejected', color: 'red' },
      expired: { icon: AlertCircle, text: 'Expired', color: 'gray' }
    };

    const badge = badges[status] || badges.pending;
    const Icon = badge.icon;

    return (
      <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-xs font-medium bg-${badge.color}-100 text-${badge.color}-700`}>
        <Icon size={14} />
        {badge.text}
      </span>
    );
  };

  const renderDocumentRow = (type) => {
    const doc = documents[type.code];
    if (!doc?.id) return null;
    return <tr key={type.code}>
      <td><div className="document-table-name"><span className="document-table-icon" aria-hidden="true">{type.icon}</span><div>
        <strong>{type.label}</strong><span title={doc.document_file_name}>{doc.document_file_name || doc.document_number || type.description}</span>
      </div></div></td>
      <td className="document-number">{doc.document_number || "Not provided"}</td>
      <td>{getVerificationBadge(doc.verification_status)}</td>
      <td><span className={doc.is_expired ? 'text-red-600' : doc.expires_soon ? 'text-orange-600' : ''}>
        {doc.expiry_date ? new Date(`${doc.expiry_date}T00:00:00`).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : 'No expiry'}
        {doc.is_expired ? ' - Expired' : doc.expires_soon ? ' - Expiring soon' : ''}
      </span></td>
      <td><div className="document-table-actions">
        {DOCUMENT_UPLOAD_CONFIG.actions.view.enabled && <button type="button" title="View" aria-label={`View ${type.label}`} onClick={() => handleView({...doc, document_type: type.code})}><Eye size={16} aria-hidden="true" /></button>}
        {DOCUMENT_UPLOAD_CONFIG.actions.replace.enabled && <button type="button" title="Re-upload" aria-label={`Re-upload ${type.label}`} onClick={() => handleReplaceFile(doc, type)}><Upload size={16} aria-hidden="true" /></button>}
        {DOCUMENT_UPLOAD_CONFIG.actions.delete.enabled && <button type="button" className="document-delete" title="Delete" aria-label={`Delete ${type.label}`} onClick={() => handleDelete(doc.id)}><Trash2 size={16} aria-hidden="true" /></button>}
      </div></td>
    </tr>;
  };

  const renderUploadForm = () => {
    if (!uploadingType) return null;

    const type = documentTypes.find(t => t.code === uploadingType);
    if (!type) return null;

    return (
      <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
        <div className="bg-white rounded-xl shadow-xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
          {/* Header */}
          <div className="sticky top-0 bg-white border-b border-gray-200 px-6 py-4 flex items-center justify-between">
            <h2 className="text-xl font-bold text-gray-900">
              {/* ✅ SOFT-CODED: Dynamic title based on action */}
              {isEditingDetails
                ? `${DOCUMENT_UPLOAD_CONFIG.actions.edit.label} — ${type.label}`
                : editingDoc
                  ? `${DOCUMENT_UPLOAD_CONFIG.actions.replace.label} — ${type.label}`
                  : `Upload ${type.label}`
              }
            </h2>
            <button onClick={resetForm} className="text-gray-400 hover:text-gray-600">
              <X size={24} />
            </button>
          </div>

          {/* Form */}
          <div className="p-6 space-y-4">
            {/* ✅ SOFT-CODED: Show file upload section only if not in edit-details-only mode */}
            {!isEditingDetails && (
              <>
                {/* File Info */}
                {formData.document_file && (
                  <div className="p-4 bg-blue-50 rounded-lg border border-blue-200">
                    <div className="flex items-center gap-3">
                      <FileText size={24} className="text-blue-600" />
                      <div className="flex-1">
                        <p className="font-medium text-gray-900">{formData.document_file.name}</p>
                        <p className="text-sm text-gray-600">{formatFileSize(formData.document_file.size)}</p>
                      </div>
                      <button
                        onClick={() => {
                          setFormData(prev => ({ ...prev, document_file: null }));
                          if (fileInputRef.current) fileInputRef.current.value = '';
                        }}
                        className="text-red-600 hover:text-red-800"
                      >
                        <X size={20} />
                      </button>
                    </div>
                  </div>
                )}

                {!formData.document_file && (
                  <div>
                    <input
                      ref={fileInputRef}
                      type="file"
                      accept={DOCUMENT_UPLOAD_CONFIG.allowedExtensions.join(',')}
                      onChange={(e) => {
                        const file = e.target.files[0];
                        if (!file) return;
                        const validation = validateDocument(file);
                        if (!validation.isValid) {
                          toast.error(validation.errors.join(', '));
                          e.target.value = '';
                          return;
                        }
                        setFormData(prev => ({ ...prev, document_file: file }));
                        extractMetadata(file, uploadingType);
                      }}
                      className="hidden"
                      id="upload-file"
                    />
                    <label
                      htmlFor="upload-file"
                      className="flex flex-col items-center justify-center gap-2 p-8 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-blue-500 hover:bg-blue-50 transition-all"
                    >
                      <Upload size={48} className="text-gray-400" />
                      <span className="text-sm text-gray-600">
                        {editingDoc ? 'Click to select new file' : 'Click to select file'}
                      </span>
                      <span className="text-xs text-gray-400">PDF, JPG, JPEG, PNG (max {formatFileSize(type.max_file_size_mb * 1024 * 1024)})</span>
                    </label>
                  </div>
                )}
              </>
            )}

            {/* ✅ SOFT-CODED: Info message for edit details mode */}
            {isEditingDetails && (
              <div className="p-4 bg-orange-50 border border-orange-200 rounded-lg">
                <div className="flex items-start gap-3">
                  <AlertCircle size={20} className="text-orange-600 flex-shrink-0 mt-0.5" />
                  <div>
                    <p className="text-sm font-medium text-orange-900">Editing Document Details</p>
                    <p className="text-xs text-orange-700 mt-1">
                      You are updating the document information only. To replace the file, use the &quot;Replace File&quot; button.
                    </p>
                  </div>
                </div>
              </div>
            )}

            {isExtracting && (
              <div className="flex items-center gap-3 rounded-lg border border-blue-200 bg-blue-50 p-3 text-sm text-blue-800">
                <Loader2 size={18} className="animate-spin flex-shrink-0" />
                Detecting document number, authority, issue date, and expiry date…
              </div>
            )}

            {/* Document Details */}
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Document Number <span className="text-gray-400">(Optional)</span>
                </label>
                <input
                  type="text"
                  value={formData.document_number}
                  onChange={(e) => setFormData(prev => ({ ...prev, document_number: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="e.g., 784-1234-5678-9"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Issuing Authority <span className="text-gray-400">(Optional)</span>
                </label>
                <input
                  type="text"
                  value={formData.issuing_authority}
                  onChange={(e) => setFormData(prev => ({ ...prev, issuing_authority: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  placeholder="e.g., UAE Government"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Issue Date <span className="text-gray-400">(Optional)</span>
                </label>
                <input
                  type="date"
                  value={formData.issue_date}
                  onChange={(e) => setFormData(prev => ({ ...prev, issue_date: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Expiry Date <span className="text-gray-400">(Optional)</span>
                </label>
                <input
                  type="date"
                  value={formData.expiry_date}
                  onChange={(e) => setFormData(prev => ({ ...prev, expiry_date: e.target.value }))}
                  className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">
                Notes <span className="text-gray-400">(Optional)</span>
              </label>
              <textarea
                value={formData.notes}
                onChange={(e) => setFormData(prev => ({ ...prev, notes: e.target.value }))}
                rows={3}
                className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                placeholder="Any additional information..."
              />
            </div>
          </div>

          {/* Footer */}
          <div className="sticky bottom-0 bg-gray-50 border-t border-gray-200 px-6 py-4 flex gap-3">
            <button
              onClick={resetForm}
              className="flex-1 px-4 py-2 border border-gray-300 rounded-lg text-gray-700 hover:bg-gray-100 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleUpload}
              disabled={(!isEditingDetails && !formData.document_file) || isLoading || isExtracting}
              className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:bg-gray-300 disabled:cursor-not-allowed transition-colors flex items-center justify-center gap-2"
            >
              {isLoading ? (
                <>
                  <div className="w-4 h-4 border-2 border-white border-t-transparent rounded-full animate-spin" />
                  {isEditingDetails ? 'Saving...' : 'Uploading...'}
                </>
              ) : (
                <>
                  {isEditingDetails ? (
                    <>
                      <Check size={16} />
                      Save Changes
                    </>
                  ) : editingDoc ? (
                    <>
                      <Upload size={16} />
                      Replace Document
                    </>
                  ) : (
                    <>
                      <Upload size={16} />
                      Upload Document
                    </>
                  )}
                </>
              )}
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900">Documents</h2>
          <p className="text-gray-600 mt-1">
            Upload your identification documents for verification
          </p>
        </div>
      </div>

      <div className="document-table-scroll">
        <table className="profile-document-table">
          <caption className="sr-only">Uploaded profile documents</caption>
          <thead><tr><th scope="col">Document</th><th scope="col">Document Number</th><th scope="col">Status</th><th scope="col">Expiry</th><th scope="col">Actions</th></tr></thead>
          <tbody>{[...documentTypes].sort((a, b) => a.display_order - b.display_order).map(renderDocumentRow)}
            {!documentTypes.some(type => documents[type.code]?.id) && <tr><td colSpan={5}>No documents uploaded yet.</td></tr>}
          </tbody>
        </table>
      </div>
      {documentTypes.some(type => !documents[type.code]?.id) && <details className="document-missing"><summary>Upload missing documents</summary>
        <ul>{documentTypes.filter(type => !documents[type.code]?.id).map(type => <li key={type.code}>
          <span>{type.label}{type.required ? ' ? Required' : ''}</span>
          <label className="document-open">Upload<input type="file" className="sr-only" aria-label={`Upload ${type.label}`} accept={DOCUMENT_UPLOAD_CONFIG.allowedExtensions.join(',')} onChange={event => handleFileSelect(event, type.code)} /></label>
        </li>)}</ul>
      </details>}

      {/* Upload Form Modal */}
      {renderUploadForm()}

      {/* In-page document preview */}
      {previewDocument && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 p-4">
          <div className="flex h-[90vh] w-full max-w-6xl flex-col overflow-hidden rounded-xl bg-white shadow-2xl">
            <div className="flex items-center justify-between gap-4 border-b border-gray-200 px-5 py-4">
              <div className="min-w-0">
                <h2 className="truncate text-lg font-bold text-gray-900">
                  {previewDocument.document_type_label || 'Document Preview'}
                </h2>
                <p className="truncate text-sm text-gray-500">
                  {previewDocument.document_file_name || previewDocument.document_number}
                </p>
              </div>
              <div className="flex items-center gap-2">
                <button
                  type="button"
                  onClick={() => handleDownload(previewDocument)}
                  className="inline-flex items-center gap-2 rounded-lg border border-gray-300 px-3 py-2 text-sm font-medium text-gray-700 hover:bg-gray-50"
                >
                  <Download size={16} /> Download
                </button>
                <button
                  type="button"
                  onClick={closePreview}
                  className="rounded-lg p-2 text-gray-500 hover:bg-gray-100 hover:text-gray-800"
                  aria-label="Close document preview"
                >
                  <X size={22} />
                </button>
              </div>
            </div>

            <div className="grid min-h-0 flex-1 grid-cols-1 lg:grid-cols-[1fr_260px]">
              <div className="min-h-0 bg-gray-100 p-3">
                {isPreviewLoading ? (
                  <div className="flex h-full items-center justify-center gap-3 text-gray-600">
                    <Loader2 size={24} className="animate-spin" />
                    Loading document preview…
                  </div>
                ) : previewUrl && (previewMimeType.startsWith('image/') || /\.(png|jpe?g)$/i.test(previewDocument.document_file_name || '')) ? (
                  <div className="flex h-full items-center justify-center overflow-auto">
                    <img
                      src={previewUrl}
                      alt={previewDocument.document_type_label || 'Uploaded document'}
                      className="max-h-full max-w-full rounded bg-white object-contain shadow"
                    />
                  </div>
                ) : previewUrl ? (
                  <iframe
                    src={previewUrl}
                    title={previewDocument.document_file_name || 'Document preview'}
                    className="h-full min-h-[500px] w-full rounded border-0 bg-white"
                  />
                ) : (
                  <div className="flex h-full items-center justify-center text-gray-500">
                    Preview unavailable
                  </div>
                )}
              </div>

              <aside className="overflow-y-auto border-l border-gray-200 bg-white p-5">
                <h3 className="mb-4 font-semibold text-gray-900">Document Details</h3>
            <div className="profile-document-actions">
              {/* View Button */}
              {DOCUMENT_UPLOAD_CONFIG.actions.view.enabled &&
               DOCUMENT_UPLOAD_CONFIG.actions.view.showInCard && (
                <button
                  onClick={() => handleView(previewDocument)}
                  className={`flex items-center justify-center gap-2 px-3 py-2 ${DOCUMENT_UPLOAD_CONFIG.actions.view.bgColor} ${DOCUMENT_UPLOAD_CONFIG.actions.view.textColor} rounded-lg ${DOCUMENT_UPLOAD_CONFIG.actions.view.hoverColor} transition-colors text-sm font-medium`}
                  title={DOCUMENT_UPLOAD_CONFIG.actions.view.label}
                >
                  <Eye size={16} />
                  <span className="hidden sm:inline">{DOCUMENT_UPLOAD_CONFIG.actions.view.label}</span>
                </button>
              )}

              {/* Download Button */}
              {DOCUMENT_UPLOAD_CONFIG.actions.download.enabled &&
               DOCUMENT_UPLOAD_CONFIG.actions.download.showInCard && (
                <button
                  onClick={() => handleDownload(previewDocument)}
                  className={`flex items-center justify-center gap-2 px-3 py-2 ${DOCUMENT_UPLOAD_CONFIG.actions.download.bgColor} ${DOCUMENT_UPLOAD_CONFIG.actions.download.textColor} rounded-lg ${DOCUMENT_UPLOAD_CONFIG.actions.download.hoverColor} transition-colors text-sm font-medium`}
                  title={DOCUMENT_UPLOAD_CONFIG.actions.download.label}
                >
                  <Download size={16} />
                  <span className="hidden sm:inline">{DOCUMENT_UPLOAD_CONFIG.actions.download.label}</span>
                </button>
              )}

              {/* Edit Details Button */}
              {DOCUMENT_UPLOAD_CONFIG.actions.edit.enabled &&
               DOCUMENT_UPLOAD_CONFIG.actions.edit.showInCard && (
                <button
                  onClick={() => { closePreview(); handleEditDetails(previewDocument, documentTypes.find(item => item.code === previewDocument.document_type)); }}
                  className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 ${DOCUMENT_UPLOAD_CONFIG.actions.edit.bgColor} ${DOCUMENT_UPLOAD_CONFIG.actions.edit.textColor} rounded-lg ${DOCUMENT_UPLOAD_CONFIG.actions.edit.hoverColor} transition-colors text-sm font-medium`}
                  title={DOCUMENT_UPLOAD_CONFIG.actions.edit.description}
                >
                  <Edit2 size={16} />
                  <span>{DOCUMENT_UPLOAD_CONFIG.actions.edit.label}</span>
                </button>
              )}

              {/* Replace File Button */}
              {DOCUMENT_UPLOAD_CONFIG.actions.replace.enabled &&
               DOCUMENT_UPLOAD_CONFIG.actions.replace.showInCard && (
                <button
                  onClick={() => { closePreview(); handleReplaceFile(previewDocument, documentTypes.find(item => item.code === previewDocument.document_type)); }}
                  className={`flex-1 flex items-center justify-center gap-2 px-3 py-2 ${DOCUMENT_UPLOAD_CONFIG.actions.replace.bgColor} ${DOCUMENT_UPLOAD_CONFIG.actions.replace.textColor} rounded-lg ${DOCUMENT_UPLOAD_CONFIG.actions.replace.hoverColor} transition-colors text-sm font-medium`}
                  title={DOCUMENT_UPLOAD_CONFIG.actions.replace.description}
                >
                  <Upload size={16} />
                  <span>{DOCUMENT_UPLOAD_CONFIG.actions.replace.label}</span>
                </button>
              )}

              {/* Delete Button */}
              {DOCUMENT_UPLOAD_CONFIG.actions.delete.enabled &&
               DOCUMENT_UPLOAD_CONFIG.actions.delete.showInCard && (
                <button
                  onClick={async () => {
                    if (DOCUMENT_UPLOAD_CONFIG.actions.delete.requiresConfirmation) {
                      if ((await radaiConfirm(DOCUMENT_UPLOAD_CONFIG.actions.delete.confirmMessage))) {
                        handleDelete(previewDocument.id);
                      }
                    } else {
                      handleDelete(previewDocument.id);
                    }
                  }}
                  className={`flex items-center justify-center gap-2 px-3 py-2 ${DOCUMENT_UPLOAD_CONFIG.actions.delete.bgColor} ${DOCUMENT_UPLOAD_CONFIG.actions.delete.textColor} rounded-lg ${DOCUMENT_UPLOAD_CONFIG.actions.delete.hoverColor} transition-colors text-sm font-medium`}
                  title={DOCUMENT_UPLOAD_CONFIG.actions.delete.label}
                >
                  <Trash2 size={16} />
                  <span className="hidden sm:inline">{DOCUMENT_UPLOAD_CONFIG.actions.delete.label}</span>
                </button>
              )}
            </div>
                <dl className="space-y-4 text-sm">
                  <div>
                    <dt className="text-gray-500">Document Number</dt>
                    <dd className="mt-1 break-words font-medium text-gray-900">{previewDocument.document_number || '—'}</dd>
                  </div>
                  <div>
                    <dt className="text-gray-500">Issuing Authority</dt>
                    <dd className="mt-1 break-words font-medium text-gray-900">{previewDocument.issuing_authority || '—'}</dd>
                  </div>
                  <div>
                    <dt className="text-gray-500">Issue Date</dt>
                    <dd className="mt-1 font-medium text-gray-900">{previewDocument.issue_date || '—'}</dd>
                  </div>
                  <div>
                    <dt className="text-gray-500">Expiry Date</dt>
                    <dd className="mt-1 font-medium text-gray-900">{previewDocument.expiry_date || '—'}</dd>
                  </div>
                  <div>
                    <dt className="text-gray-500">Verification</dt>
                    <dd className="mt-2">{getVerificationBadge(previewDocument.verification_status)}</dd>
                  </div>
                </dl>
              </aside>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default DocumentUploadSection;

import { radaiConfirm } from '../../services/radaiDialog'
import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import {
  Globe, Plus, X, Edit2, Trash2, ExternalLink, Check,
  Linkedin, Github, Twitter, BookOpen, GraduationCap,
  PenTool, Youtube, Award,
} from 'lucide-react';
import { API_BASE_URL } from '../../config/api.config';

// Icon mapping for social platforms
const PLATFORM_ICONS = {
  linkedin: Linkedin,
  github: Github,
  twitter: Twitter,
  'book-open': BookOpen,
  'id-card': Award,
  'graduation-cap': GraduationCap,
  'pen-tool': PenTool,
  youtube: Youtube,
  globe: Globe,
};

/**
 * Social Media Links Section
 * Connect professional and social network profiles
 */
const SocialMediaLinksSection = () => {
  const [links, setLinks] = useState([]);
  const [platforms, setPlatforms] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);

  // Form state
  const [formData, setFormData] = useState({
    platform: '',
    url: '',
    username: '',
    is_public: true,
  });

  useEffect(() => {
    fetchLinks();
    fetchPlatforms();
  }, []);

  const fetchLinks = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/social-links/?mine=true`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Failed to fetch links');
      const data = await res.json();
      setLinks(Array.isArray(data) ? data : data.results || []);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchPlatforms = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/social-links/platforms/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setPlatforms(data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.platform || !formData.url) {
      toast.error('Platform and URL are required');
      return;
    }

    setIsLoading(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const url = editingId
        ? `${API_BASE_URL}/rbac/social-links/${editingId}/`
        : `${API_BASE_URL}/rbac/social-links/`;
      
      const res = await fetch(url, {
        method: editingId ? 'PATCH' : 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(formData),
      });

      if (!res.ok) {
        const error = await res.json().catch(() => ({}));
        const fieldError = Object.values(error)
          .flat()
          .find(value => typeof value === 'string' && value.trim());
        throw new Error(error.detail || error.error || fieldError || 'Failed to save link');
      }

      toast.success(editingId ? 'Link updated!' : 'Link added!');
      await fetchLinks();
      resetForm();
    } catch (err) {
      toast.error(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleEdit = (link) => {
    setEditingId(link.id);
    setFormData({
      platform: link.platform,
      url: link.url,
      username: link.username || '',
      is_public: link.is_public,
    });
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (!(await radaiConfirm('Delete this link?'))) return;
    
    setIsLoading(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/social-links/${id}/`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error('Failed to delete');
      toast.success('Link deleted');
      await fetchLinks();
    } catch (err) {
      toast.error(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      platform: '',
      url: '',
      username: '',
      is_public: true,
    });
    setEditingId(null);
    setShowForm(false);
  };

  const getPlatformConfig = (platformCode) => {
    return platforms.find(p => p.value === platformCode) || {};
  };

  const getPlatformIcon = (iconName) => {
    return PLATFORM_ICONS[iconName] || Globe;
  };

  const inputCls = 'w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white text-gray-900 placeholder-gray-400 transition-all';
  const labelCls = 'block text-sm font-medium text-gray-700 mb-1.5';

  // Get available platforms (exclude already linked ones if not editing)
  const availablePlatforms = platforms.filter(p => {
    const isAlreadyLinked = links.some(link => link.platform === p.value);
    if (editingId) {
      // When editing, show current platform + unused platforms
      const currentPlatform = links.find(link => link.id === editingId)?.platform;
      return p.value === currentPlatform || !isAlreadyLinked;
    }
    return !isAlreadyLinked;
  });

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
            <Globe className="w-6 h-6 text-green-500" />
            Social Media & Professional Networks
          </h2>
          <p className="text-sm text-gray-500 mt-1">
            Connect your LinkedIn, GitHub, ResearchGate, and other professional profiles
          </p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2 font-semibold transition-all"
          disabled={availablePlatforms.length === 0 && !showForm}
        >
          <Plus className="w-4 h-4" />
          Add Link
        </button>
      </div>

      {/* Add/Edit Form */}
      {showForm && (
        <div className="bg-gradient-to-br from-green-50 to-cyan-50 rounded-xl p-6 border-2 border-green-200">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900">
              {editingId ? 'Edit Social Link' : 'Add Social Link'}
            </h3>
            <button onClick={resetForm} className="text-gray-400 hover:text-gray-600">
              <X className="w-5 h-5" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 gap-4">
              <div>
                <label className={labelCls}>Platform *</label>
                <select
                  value={formData.platform}
                  onChange={e => {
                    setFormData(p => ({ ...p, platform: e.target.value }));
                    const selectedPlatform = platforms.find(pl => pl.value === e.target.value);
                    if (selectedPlatform && !formData.url) {
                      setFormData(p => ({ ...p, url: selectedPlatform.placeholder }));
                    }
                  }}
                  className={inputCls}
                  required
                  disabled={editingId !== null} // Cannot change platform when editing
                >
                  <option value="">Select platform...</option>
                  {availablePlatforms.map(platform => (
                    <option key={platform.value} value={platform.value}>
                      {platform.label}
                    </option>
                  ))}
                </select>
                {formData.platform && (
                  <p className="text-xs text-gray-500 mt-1">
                    {getPlatformConfig(formData.platform).placeholder}
                  </p>
                )}
              </div>

              <div>
                <label className={labelCls}>Profile URL *</label>
                <input
                  type="url"
                  value={formData.url}
                  onChange={e => setFormData(p => ({ ...p, url: e.target.value }))}
                  className={inputCls}
                  placeholder={formData.platform ? getPlatformConfig(formData.platform).placeholder : 'https://...'}
                  required
                />
              </div>

              <div>
                <label className={labelCls}>Username / Handle (Optional)</label>
                <input
                  type="text"
                  value={formData.username}
                  onChange={e => setFormData(p => ({ ...p, username: e.target.value }))}
                  className={inputCls}
                  placeholder="@username"
                />
              </div>

              <div className="flex items-center gap-2">
                <input
                  type="checkbox"
                  id="is_public_social"
                  checked={formData.is_public}
                  onChange={e => setFormData(p => ({ ...p, is_public: e.target.checked }))}
                  className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                />
                <label htmlFor="is_public_social" className="text-sm font-medium text-gray-700">
                  Show on public profile
                </label>
              </div>
            </div>

            <div className="flex gap-3 justify-end pt-2">
              <button
                type="button"
                onClick={resetForm}
                className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-semibold"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={isLoading}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2 font-semibold"
              >
                {isLoading ? 'Saving...' : (editingId ? 'Update' : 'Add Link')}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Social Links Display */}
      {links.length === 0 ? (
        <div className="text-center py-12 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200">
          <Globe className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-600 mb-2">No social links added yet</h3>
          <p className="text-gray-400 mb-4">Connect your professional network profiles</p>
          <button
            onClick={() => setShowForm(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 inline-flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Add First Link
          </button>
        </div>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          {links.map(link => {
            const platformConfig = getPlatformConfig(link.platform);
            const IconComponent = getPlatformIcon(link.platform_icon);
            
            return (
              <a
                key={link.id}
                href={link.url}
                target="_blank"
                rel="noopener noreferrer"
                className="group relative bg-white border-2 border-gray-100 rounded-xl p-5 hover:border-blue-300 hover:shadow-lg transition-all flex items-center gap-4"
              >
                {/* Platform Icon */}
                <div
                  className="w-14 h-14 rounded-lg flex items-center justify-center flex-shrink-0 text-white"
                  style={{ backgroundColor: link.platform_color || '#6B7280' }}
                >
                  <IconComponent className="w-7 h-7" />
                </div>

                {/* Platform Info */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="font-bold text-gray-900">{link.platform_label}</h3>
                    {link.is_verified && (
                      <Check className="w-4 h-4 text-green-500" title="Verified" />
                    )}
                    <ExternalLink className="w-3.5 h-3.5 text-gray-400 group-hover:text-blue-500 transition-colors ml-auto" />
                  </div>
                  {link.username && (
                    <p className="text-sm text-gray-600 truncate">
                      {link.username}
                    </p>
                  )}
                </div>

                {/* Action buttons */}
                <div className="absolute top-2 right-2 flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button
                    onClick={(e) => {
                      e.preventDefault();
                      handleEdit(link);
                    }}
                    className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg bg-white shadow"
                    title="Edit"
                  >
                    <Edit2 className="w-3.5 h-3.5" />
                  </button>
                  <button
                    onClick={(e) => {
                      e.preventDefault();
                      handleDelete(link.id);
                    }}
                    className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg bg-white shadow"
                    title="Delete"
                  >
                    <Trash2 className="w-3.5 h-3.5" />
                  </button>
                </div>
              </a>
            );
          })}
        </div>
      )}

      {/* Platform suggestions if less than 3 links */}
      {links.length > 0 && links.length < 3 && (
        <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
          <p className="text-sm text-blue-700 flex items-center gap-2">
            <Globe className="w-4 h-4" />
            <strong>Tip:</strong> Add at least 3 professional links to earn the "Well Connected" badge!
          </p>
        </div>
      )}
    </div>
  );
};

export default SocialMediaLinksSection;

import { radaiConfirm } from '../../services/radaiDialog'
import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import {
  Briefcase, Plus, X, Edit2, Trash2, Calendar, MapPin, Building2,
  Check, ExternalLink, Clock, TrendingUp,
} from 'lucide-react';
import { API_BASE_URL } from '../../config/api.config';

/**
 * Work Experience Timeline Section
 * Shows professional career progression with company roles
 */
const WorkExperienceSection = () => {
  const [experiences, setExperiences] = useState([]);
  const [employmentTypes, setEmploymentTypes] = useState([]);
  const [industries, setIndustries] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingId, setEditingId] = useState(null);

  // Form state
  const [formData, setFormData] = useState({
    company_name: '',
    company_logo_url: '',
    job_title: '',
    employment_type: '',
    industry: '',
    location: '',
    start_date: '',
    end_date: '',
    is_current: false,
    description: '',
    achievements_text: '',
    skills_used: [],
    is_public: true,
  });

  const [skillInput, setSkillInput] = useState('');

  useEffect(() => {
    fetchExperiences();
    fetchEmploymentTypes();
    fetchIndustries();
  }, []);

  const fetchExperiences = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/work-experience/?mine=true`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (!res.ok) throw new Error('Failed to fetch experience');
      const data = await res.json();
      setExperiences(Array.isArray(data) ? data : data.results || []);
    } catch (err) {
      console.error(err);
    }
  };

  const fetchEmploymentTypes = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/work-experience/employment_types/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setEmploymentTypes(data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const fetchIndustries = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/work-experience/industries/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      if (res.ok) {
        const data = await res.json();
        setIndustries(data);
      }
    } catch (err) {
      console.error(err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.company_name || !formData.job_title || !formData.start_date) {
      toast.error('Company name, job title, and start date are required');
      return;
    }

    setIsLoading(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const url = editingId
        ? `${API_BASE_URL}/rbac/work-experience/${editingId}/`
        : `${API_BASE_URL}/rbac/work-experience/`;
      
      const res = await fetch(url, {
        method: editingId ? 'PATCH' : 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          ...formData,
          // Optional date inputs use an empty string in React, while the API
          // expects a real ISO date or null.
          end_date: formData.end_date || null,
        }),
      });

      if (!res.ok) {
        const error = await res.json().catch(() => ({}));
        const fieldError = Object.values(error)
          .flat()
          .find(value => typeof value === 'string' && value.trim());
        throw new Error(error.detail || error.error || fieldError || 'Failed to save experience');
      }

      toast.success(editingId ? 'Experience updated!' : 'Experience added!');
      await fetchExperiences();
      resetForm();
    } catch (err) {
      toast.error(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const handleEdit = (experience) => {
    setEditingId(experience.id);
    setFormData({
      company_name: experience.company_name,
      company_logo_url: experience.company_logo_url || '',
      job_title: experience.job_title,
      employment_type: experience.employment_type || '',
      industry: experience.industry || '',
      location: experience.location || '',
      start_date: experience.start_date,
      end_date: experience.end_date || '',
      is_current: experience.is_current,
      description: experience.description || '',
      achievements_text: experience.achievements_text || '',
      skills_used: experience.skills_used || [],
      is_public: experience.is_public,
    });
    setShowForm(true);
  };

  const handleDelete = async (id) => {
    if (!(await radaiConfirm('Delete this experience entry?'))) return;
    
    setIsLoading(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const res = await fetch(`${API_BASE_URL}/rbac/work-experience/${id}/`, {
        method: 'DELETE',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!res.ok) throw new Error('Failed to delete');
      toast.success('Experience deleted');
      await fetchExperiences();
    } catch (err) {
      toast.error(err.message);
    } finally {
      setIsLoading(false);
    }
  };

  const resetForm = () => {
    setFormData({
      company_name: '',
      company_logo_url: '',
      job_title: '',
      employment_type: '',
      industry: '',
      location: '',
      start_date: '',
      end_date: '',
      is_current: false,
      description: '',
      achievements_text: '',
      skills_used: [],
      is_public: true,
    });
    setSkillInput('');
    setEditingId(null);
    setShowForm(false);
  };

  const addSkill = () => {
    if (!skillInput.trim()) return;
    if (formData.skills_used.includes(skillInput.trim())) {
      toast.info('Skill already added');
      return;
    }
    setFormData(p => ({
      ...p,
      skills_used: [...p.skills_used, skillInput.trim()]
    }));
    setSkillInput('');
  };

  const removeSkill = (skill) => {
    setFormData(p => ({
      ...p,
      skills_used: p.skills_used.filter(s => s !== skill)
    }));
  };

  const inputCls = 'w-full px-4 py-2.5 border border-gray-200 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent bg-white text-gray-900 placeholder-gray-400 transition-all';
  const labelCls = 'block text-sm font-medium text-gray-700 mb-1.5';

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
            <Briefcase className="w-6 h-6 text-blue-500" />
            Work Experience
          </h2>
          <p className="text-sm text-gray-500 mt-1">
            Build your professional timeline and showcase career progression
          </p>
        </div>
        <button
          onClick={() => setShowForm(!showForm)}
          className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 flex items-center gap-2 font-semibold transition-all"
        >
          <Plus className="w-4 h-4" />
          Add Experience
        </button>
      </div>

      {/* Add/Edit Form */}
      {showForm && (
        <div className="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-xl p-6 border-2 border-blue-200">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-lg font-semibold text-gray-900">
              {editingId ? 'Edit Experience' : 'Add Experience'}
            </h3>
            <button onClick={resetForm} className="text-gray-400 hover:text-gray-600">
              <X className="w-5 h-5" />
            </button>
          </div>

          <form onSubmit={handleSubmit} className="space-y-4">
            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
              <div>
                <label className={labelCls}>Company Name *</label>
                <input
                  type="text"
                  value={formData.company_name}
                  onChange={e => setFormData(p => ({ ...p, company_name: e.target.value }))}
                  className={inputCls}
                  placeholder="e.g., Shell Global"
                  required
                />
              </div>

              <div>
                <label className={labelCls}>Job Title *</label>
                <input
                  type="text"
                  value={formData.job_title}
                  onChange={e => setFormData(p => ({ ...p, job_title: e.target.value }))}
                  className={inputCls}
                  placeholder="e.g., Senior Process Engineer"
                  required
                />
              </div>

              <div>
                <label className={labelCls}>Employment Type</label>
                <select
                  value={formData.employment_type}
                  onChange={e => setFormData(p => ({ ...p, employment_type: e.target.value }))}
                  className={inputCls}
                >
                  <option value="">Select type...</option>
                  {employmentTypes.map(type => (
                    <option key={type.value} value={type.value}>{type.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className={labelCls}>Industry</label>
                <select
                  value={formData.industry}
                  onChange={e => setFormData(p => ({ ...p, industry: e.target.value }))}
                  className={inputCls}
                >
                  <option value="">Select industry...</option>
                  {industries.map(ind => (
                    <option key={ind.value} value={ind.value}>{ind.label}</option>
                  ))}
                </select>
              </div>

              <div>
                <label className={labelCls}>Location</label>
                <input
                  type="text"
                  value={formData.location}
                  onChange={e => setFormData(p => ({ ...p, location: e.target.value }))}
                  className={inputCls}
                  placeholder="City, Country"
                />
              </div>

              <div>
                <label className={labelCls}>Company Logo URL</label>
                <input
                  type="url"
                  value={formData.company_logo_url}
                  onChange={e => setFormData(p => ({ ...p, company_logo_url: e.target.value }))}
                  className={inputCls}
                  placeholder="https://..."
                />
              </div>

              <div>
                <label className={labelCls}>Start Date *</label>
                <input
                  type="date"
                  value={formData.start_date}
                  onChange={e => setFormData(p => ({ ...p, start_date: e.target.value }))}
                  className={inputCls}
                  required
                />
              </div>

              <div>
                <label className={labelCls}>End Date</label>
                <input
                  type="date"
                  value={formData.end_date}
                  onChange={e => setFormData(p => ({ ...p, end_date: e.target.value }))}
                  className={inputCls}
                  disabled={formData.is_current}
                />
              </div>

              <div className="sm:col-span-2 flex items-center gap-2">
                <input
                  type="checkbox"
                  id="is_current"
                  checked={formData.is_current}
                  onChange={e => setFormData(p => ({ ...p, is_current: e.target.checked, end_date: e.target.checked ? '' : p.end_date }))}
                  className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                />
                <label htmlFor="is_current" className="text-sm font-medium text-gray-700">
                  I currently work here
                </label>
              </div>

              <div className="sm:col-span-2">
                <label className={labelCls}>Role Description</label>
                <textarea
                  value={formData.description}
                  onChange={e => setFormData(p => ({ ...p, description: e.target.value }))}
                  rows={3}
                  className={`${inputCls} resize-none`}
                  placeholder="Brief description of your role and responsibilities..."
                />
              </div>

              <div className="sm:col-span-2">
                <label className={labelCls}>Key Achievements</label>
                <textarea
                  value={formData.achievements_text}
                  onChange={e => setFormData(p => ({ ...p, achievements_text: e.target.value }))}
                  rows={3}
                  className={`${inputCls} resize-none`}
                  placeholder="Notable accomplishments and impact in this role..."
                />
              </div>

              <div className="sm:col-span-2">
                <label className={labelCls}>Skills & Tools Used</label>
                <div className="flex gap-2 mb-2">
                  <input
                    type="text"
                    value={skillInput}
                    onChange={e => setSkillInput(e.target.value)}
                    onKeyPress={e => e.key === 'Enter' && (e.preventDefault(), addSkill())}
                    className={inputCls}
                    placeholder="e.g., HYSYS, AutoCAD, Python"
                  />
                  <button
                    type="button"
                    onClick={addSkill}
                    className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 font-semibold"
                  >
                    Add
                  </button>
                </div>
                {formData.skills_used.length > 0 && (
                  <div className="flex flex-wrap gap-2">
                    {formData.skills_used.map(skill => (
                      <span
                        key={skill}
                        className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm flex items-center gap-2"
                      >
                        {skill}
                        <button
                          type="button"
                          onClick={() => removeSkill(skill)}
                          className="hover:text-blue-900"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </span>
                    ))}
                  </div>
                )}
              </div>

              <div className="sm:col-span-2 flex items-center gap-2">
                <input
                  type="checkbox"
                  id="is_public"
                  checked={formData.is_public}
                  onChange={e => setFormData(p => ({ ...p, is_public: e.target.checked }))}
                  className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
                />
                <label htmlFor="is_public" className="text-sm font-medium text-gray-700">
                  Show on public profile
                </label>
              </div>
            </div>

            <div className="flex gap-3 justify-end pt-2">
              <button
                type="button"
                onClick={resetForm}
                className="px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-semibold"
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={isLoading}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 flex items-center gap-2 font-semibold"
              >
                {isLoading ? 'Saving...' : (editingId ? 'Update' : 'Add Experience')}
              </button>
            </div>
          </form>
        </div>
      )}

      {/* Experience Timeline */}
      {experiences.length === 0 ? (
        <div className="text-center py-12 bg-gray-50 rounded-xl border-2 border-dashed border-gray-200">
          <Briefcase className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-semibold text-gray-600 mb-2">No experience added yet</h3>
          <p className="text-gray-400 mb-4">Build your professional timeline</p>
          <button
            onClick={() => setShowForm(true)}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 inline-flex items-center gap-2"
          >
            <Plus className="w-4 h-4" />
            Add First Experience
          </button>
        </div>
      ) : (
        <div className="relative">
          {/* Timeline line */}
          <div className="absolute left-8 top-0 bottom-0 w-0.5 bg-gradient-to-b from-blue-500 via-purple-500 to-pink-500" />

          <div className="space-y-8">
            {experiences.map((exp, index) => (
              <div key={exp.id} className="relative pl-20">
                {/* Timeline dot */}
                <div className={`absolute left-6 top-6 w-5 h-5 rounded-full border-4 border-white ${exp.is_current ? 'bg-green-500 ring-4 ring-green-100' : 'bg-blue-500'} shadow-lg z-10`} />

                {/* Experience card */}
                <div className="bg-white rounded-xl border-2 border-gray-100 p-6 hover:shadow-xl hover:border-blue-200 transition-all group">
                  <div className="flex items-start justify-between mb-4">
                    <div className="flex items-start gap-4 flex-1">
                      {exp.company_logo_url && (
                        <img
                          src={exp.company_logo_url}
                          alt={exp.company_name}
                          className="w-12 h-12 rounded-lg object-contain bg-gray-50 border border-gray-200"
                          onError={e => e.target.style.display = 'none'}
                        />
                      )}
                      <div className="flex-1 min-w-0">
                        <h3 className="text-lg font-bold text-gray-900">{exp.job_title}</h3>
                        <p className="text-blue-600 font-semibold">{exp.company_name}</p>
                        {exp.employment_type_label && (
                          <span className="text-xs px-2 py-0.5 rounded-full bg-gray-100 text-gray-600 mt-1 inline-block">
                            {exp.employment_type_label}
                          </span>
                        )}
                      </div>
                    </div>

                    <div className="flex gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                      <button
                        onClick={() => handleEdit(exp)}
                        className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg"
                        title="Edit"
                      >
                        <Edit2 className="w-4 h-4" />
                      </button>
                      <button
                        onClick={() => handleDelete(exp.id)}
                        className="p-1.5 text-red-600 hover:bg-red-50 rounded-lg"
                        title="Delete"
                      >
                        <Trash2 className="w-4 h-4" />
                      </button>
                    </div>
                  </div>

                  <div className="flex flex-wrap gap-3 text-sm text-gray-500 mb-4">
                    <span className="flex items-center gap-1.5">
                      <Calendar className="w-4 h-4" />
                      {new Date(exp.start_date).toLocaleDateString('en-US', { month: 'short', year: 'numeric' })}
                      {' - '}
                      {exp.is_current ? (
                        <span className="text-green-600 font-semibold">Present</span>
                      ) : exp.end_date ? (
                        new Date(exp.end_date).toLocaleDateString('en-US', { month: 'short', year: 'numeric' })
                      ) : 'N/A'}
                      {exp.duration_text && (
                        <span className="text-gray-400">· {exp.duration_text}</span>
                      )}
                    </span>
                    {exp.location && (
                      <span className="flex items-center gap-1.5">
                        <MapPin className="w-4 h-4" />
                        {exp.location}
                      </span>
                    )}
                    {exp.industry && (
                      <span className="flex items-center gap-1.5">
                        <Building2 className="w-4 h-4" />
                        {exp.industry}
                      </span>
                    )}
                  </div>

                  {exp.description && (
                    <p className="text-sm text-gray-600 mb-3 leading-relaxed">
                      {exp.description}
                    </p>
                  )}

                  {exp.achievements_text && (
                    <div className="bg-yellow-50 border-l-4 border-yellow-400 p-3 rounded mb-3">
                      <p className="text-xs font-semibold text-yellow-700 mb-1 flex items-center gap-1">
                        <TrendingUp className="w-3.5 h-3.5" />
                        Key Achievements
                      </p>
                      <p className="text-sm text-gray-700">{exp.achievements_text}</p>
                    </div>
                  )}

                  {exp.skills_used && exp.skills_used.length > 0 && (
                    <div className="flex flex-wrap gap-2">
                      {exp.skills_used.map(skill => (
                        <span
                          key={skill}
                          className="px-2.5 py-1 bg-blue-50 text-blue-700 rounded-full text-xs font-medium"
                        >
                          {skill}
                        </span>
                      ))}
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default WorkExperienceSection;

/**
 * ProjectCard — generic project grid card (generalized from
 * SpecProjectsPage.jsx's ProjectCard). Shows activity_count instead of a
 * tool-specific extraction count so it applies to any adopting tool.
 */
import { PencilSquareIcon, TrashIcon, ArrowRightIcon, ChartBarIcon } from '@heroicons/react/24/outline';
import { statusMeta } from '../../config/projectOrganizer.config';

const Tag = ({ label, value, theme }) => (
  <span style={{
    background: theme.accentSoft, color: theme.accent,
    padding: '2px 8px', borderRadius: 4, fontWeight: 600, fontSize: 11,
  }}>{label}: {value}</span>
);

const IconBtn = ({ children, theme, danger, ...rest }) => (
  <button {...rest} style={{
    background: 'transparent',
    border: `1px solid ${danger ? '#fca5a5' : theme.accentBorder}`,
    color: danger ? '#b91c1c' : theme.accent,
    padding: '5px 8px', borderRadius: 6, cursor: 'pointer',
    display: 'inline-flex', alignItems: 'center',
  }}>{children}</button>
);

const ProjectCard = ({ project, theme, onOpen, onEdit, onDelete, openLabel = 'Open' }) => {
  const meta = statusMeta(project.status);
  const activityCount = project.activity_count || 0;
  const initials = String(project.name || 'P')
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((s) => s[0]?.toUpperCase() || '')
    .join('');

  return (
    <div
      style={{
        background: 'linear-gradient(155deg, #ffffff 0%, #f8fffd 85%)',
        border: `1px solid ${theme.accentBorder}`,
        borderRadius: 16,
        padding: 16,
        position: 'relative',
        overflow: 'hidden',
        boxShadow: '0 2px 10px rgba(2,6,23,0.05), 0 18px 34px rgba(15,118,110,0.08)',
        transition: 'transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease',
      }}
      onMouseEnter={(e) => {
        e.currentTarget.style.transform = 'translateY(-4px)';
        e.currentTarget.style.boxShadow = '0 8px 20px rgba(2,6,23,0.10), 0 24px 44px rgba(15,118,110,0.16)';
        e.currentTarget.style.borderColor = 'rgba(8,145,178,0.34)';
      }}
      onMouseLeave={(e) => {
        e.currentTarget.style.transform = 'translateY(0)';
        e.currentTarget.style.boxShadow = '0 2px 10px rgba(2,6,23,0.05), 0 18px 34px rgba(15,118,110,0.08)';
        e.currentTarget.style.borderColor = theme.accentBorder;
      }}
    >
      <div style={{
        position: 'absolute',
        inset: 0,
        pointerEvents: 'none',
        background: 'radial-gradient(circle at 90% -10%, rgba(8,145,178,0.18), transparent 42%)',
      }} />
      <div style={{
        position: 'absolute',
        left: 0,
        right: 0,
        top: 0,
        height: 4,
        background: `linear-gradient(135deg, ${theme.accent}, ${theme.accentAlt || theme.accent})`,
      }} />

      <div style={{ position: 'relative', zIndex: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', marginBottom: 12, gap: 10 }}>
        <div style={{ flex: 1, minWidth: 0, display: 'flex', alignItems: 'center', gap: 10 }}>
          <div style={{
            width: 36,
            height: 36,
            borderRadius: 10,
            background: `linear-gradient(135deg, ${theme.accentSoft}, rgba(8,145,178,0.14))`,
            border: `1px solid ${theme.accentBorder}`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: theme.accent,
            fontSize: 12,
            fontWeight: 800,
          }}>
            {initials}
          </div>
          <div style={{ minWidth: 0 }}>
            <h3 style={{ margin: 0, fontSize: 15, fontWeight: 800, color: theme.text,
                         whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
            {project.name}
            </h3>
            {project.code && (
              <div style={{ fontSize: 11, color: theme.muted, marginTop: 2, letterSpacing: 0.3, textTransform: 'uppercase' }}>{project.code}</div>
            )}
          </div>
        </div>
        <span style={{
          background: meta.bg, color: meta.color, fontSize: 11, fontWeight: 700,
          padding: '4px 9px', borderRadius: 999, whiteSpace: 'nowrap', border: '1px solid rgba(148,163,184,0.22)',
        }}>{meta.label}</span>
      </div>

      <div style={{ position: 'relative', zIndex: 1, fontSize: 12, color: theme.muted, marginBottom: 12, minHeight: 36, lineHeight: 1.55 }}>
        {project.description?.slice(0, 110) || <em>No description.</em>}
        {project.description?.length > 110 && '...'}
      </div>

      <div style={{ position: 'relative', zIndex: 1, display: 'flex', gap: 8, fontSize: 11, color: theme.muted, marginBottom: 14, flexWrap: 'wrap' }}>
        {project.plant      && <Tag label="Plant"      value={project.plant}      theme={theme} />}
        {project.client     && <Tag label="Client"     value={project.client}     theme={theme} />}
        {project.discipline && <Tag label="Discipline" value={project.discipline} theme={theme} />}
      </div>

      <div style={{
        position: 'relative',
        zIndex: 1,
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        borderTop: `1px solid ${theme.accentBorder}`,
        paddingTop: 11,
      }}>
        <div style={{
          fontSize: 11,
          color: theme.muted,
          display: 'inline-flex',
          alignItems: 'center',
          gap: 6,
          background: 'rgba(255,255,255,0.85)',
          border: `1px solid ${theme.accentBorder}`,
          padding: '4px 8px',
          borderRadius: 999,
        }}>
          <ChartBarIcon width={13} />
          {activityCount} activit{activityCount === 1 ? 'y' : 'ies'}
        </div>
        <div style={{ display: 'flex', gap: 6 }}>
          {onEdit && <IconBtn title="Edit" onClick={onEdit} theme={theme}><PencilSquareIcon width={14} /></IconBtn>}
          {onDelete && <IconBtn title="Delete" onClick={onDelete} theme={theme} danger><TrashIcon width={14} /></IconBtn>}
          {onOpen && (
            <button onClick={onOpen} style={{
              display: 'inline-flex', alignItems: 'center', gap: 4,
              background: `linear-gradient(135deg, ${theme.accent}, ${theme.accentAlt || theme.accent})`,
              color: '#fff', border: 'none',
              padding: '6px 12px', borderRadius: 8, fontSize: 12, fontWeight: 700, cursor: 'pointer',
              boxShadow: '0 4px 12px rgba(8,145,178,0.32)',
            }}>
              {openLabel} <ArrowRightIcon width={12} />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default ProjectCard;

/**
 * ProjectFormModal — generic create/edit form (generalized from
 * SpecProjectsPage.jsx's ProjectFormModal). Any tool adopting the Project
 * Organizer reuses this instead of building its own modal.
 */
import { useEffect, useState } from 'react';
import { FolderPlusIcon, XMarkIcon, CheckIcon } from '@heroicons/react/24/outline';
import { PROJECT_ORGANIZER_CONFIG } from '../../config/projectOrganizer.config';

const Field = ({ label, value, onChange, theme, required }) => (
  <div>
    <label style={{ fontSize: 12, fontWeight: 600, color: theme.muted }}>{label}</label>
    <input
      type="text"
      value={value}
      required={required}
      onChange={(e) => onChange(e.target.value)}
      style={{
        width: '100%', padding: '8px 10px', borderRadius: 6,
        border: `1px solid ${theme.accentBorder}`, fontSize: 13, marginTop: 4,
      }}
    />
  </div>
);

const ProjectFormModal = ({ initial, onClose, onSubmit, busy, theme, formError = '' }) => {
  const [form, setForm] = useState(() => ({
    name:        initial?.name        || '',
    code:        initial?.code        || '',
    client:      initial?.client      || '',
    plant:       initial?.plant       || '',
    discipline:  initial?.discipline  || '',
    description: initial?.description || '',
    status:      initial?.status      || 'active',
  }));
  const [showAdvanced, setShowAdvanced] = useState(
    Boolean(initial && (initial.code || initial.client || initial.plant || initial.discipline))
  );
  const [nameTouched, setNameTouched] = useState(false);
  const [codeTouched, setCodeTouched] = useState(Boolean(initial?.code));
  const update = (k, v) => setForm((f) => ({ ...f, [k]: v }));
  const trimmedName = form.name.trim();
  const nameError = nameTouched && trimmedName.length === 0 ? 'Project name is required.' : '';
  const canSubmit = trimmedName.length > 0 && !busy;

  useEffect(() => {
    if (initial || codeTouched) return;
    const suggested = trimmedName
      .toUpperCase()
      .replace(/[^A-Z0-9]+/g, '-')
      .replace(/^-+|-+$/g, '')
      .slice(0, 24);
    setForm((prev) => ({ ...prev, code: suggested }));
  }, [trimmedName, codeTouched, initial]);

  const handleSubmit = (e) => {
    e?.preventDefault?.();
    setNameTouched(true);
    if (!canSubmit) return;
    onSubmit({
      ...form,
      name: trimmedName,
      code: form.code.trim(),
      client: form.client.trim(),
      plant: form.plant.trim(),
      discipline: form.discipline.trim(),
      description: form.description.trim(),
    });
  };

  return (
    <div style={{
      position: 'fixed', inset: 0, background: 'rgba(15,23,42,0.45)',
      display: 'flex', alignItems: 'center', justifyContent: 'center', zIndex: 50,
    }}>
      <form onSubmit={handleSubmit} style={{
        background: '#fff', borderRadius: 14, padding: 0, width: 'min(520px, 92vw)',
        maxHeight: '90vh', overflow: 'hidden', boxShadow: '0 18px 50px rgba(0,0,0,0.25)',
        display: 'flex', flexDirection: 'column',
      }}>
        <div style={{
          display: 'flex', alignItems: 'center', gap: 12, padding: '18px 22px',
          background: `linear-gradient(135deg, ${theme.accentSoft}, rgba(8,145,178,0.05))`,
          borderBottom: `1px solid ${theme.accentBorder}`,
        }}>
          <div style={{
            width: 36, height: 36, borderRadius: 10,
            background: theme.cardBg, border: `1px solid ${theme.accentBorder}`,
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}>
            <FolderPlusIcon width={18} style={{ color: theme.accent }} />
          </div>
          <div style={{ flex: 1 }}>
            <h2 style={{ margin: 0, fontSize: 16, fontWeight: 700, color: theme.text }}>
              {initial ? 'Edit project' : 'Create new project'}
            </h2>
            <p style={{ margin: '2px 0 0', fontSize: 12, color: theme.muted }}>
              {initial ? 'Update the project details.' : 'Create a project to organise your work.'}
            </p>
          </div>
          <button type="button" onClick={onClose} style={{ background: 'none', border: 'none', cursor: 'pointer', padding: 4 }}>
            <XMarkIcon width={20} style={{ color: theme.muted }} />
          </button>
        </div>

        <div style={{ padding: '20px 22px', overflow: 'auto', display: 'grid', gap: 14 }}>
          {formError && (
            <div style={{
              border: '1px solid #fecaca',
              background: '#fef2f2',
              color: '#991b1b',
              fontSize: 12,
              fontWeight: 600,
              borderRadius: 8,
              padding: '10px 12px',
            }}>
              {formError}
            </div>
          )}

          <div>
            <label style={{ display: 'block', fontSize: 11, fontWeight: 700, color: theme.text,
                            textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 6 }}>
              Project Name *
            </label>
            <input
              type="text"
              value={form.name}
              autoFocus
              required
              maxLength={PROJECT_ORGANIZER_CONFIG.nameMaxLen}
              onChange={(e) => update('name', e.target.value)}
              onBlur={() => setNameTouched(true)}
              placeholder="e.g., ADNOC LNG Train-3"
              style={{
                width: '100%', padding: '10px 12px', borderRadius: 8,
                border: nameError ? '1px solid #ef4444' : `1px solid ${theme.accentBorder}`,
                fontSize: 14, outline: 'none',
              }}
            />
            {nameError && (
              <div style={{ marginTop: 6, fontSize: 12, color: '#b91c1c', fontWeight: 600 }}>
                {nameError}
              </div>
            )}
          </div>

          <div>
            <label style={{ display: 'block', fontSize: 11, fontWeight: 700, color: theme.text,
                            textTransform: 'uppercase', letterSpacing: 0.5, marginBottom: 6 }}>
              Description <span style={{ color: theme.muted, fontWeight: 400, textTransform: 'none' }}>(optional)</span>
            </label>
            <textarea
              value={form.description}
              maxLength={PROJECT_ORGANIZER_CONFIG.descMaxLen}
              onChange={(e) => update('description', e.target.value)}
              rows={3}
              placeholder="Brief project description…"
              style={{
                width: '100%', padding: '10px 12px', borderRadius: 8,
                border: `1px solid ${theme.accentBorder}`, fontSize: 13,
                resize: 'vertical', fontFamily: 'inherit', outline: 'none',
              }}
            />
          </div>

          <button
            type="button"
            onClick={() => setShowAdvanced((v) => !v)}
            style={{ background: 'transparent', border: 'none', color: theme.accent,
                     fontSize: 12, fontWeight: 600, cursor: 'pointer', textAlign: 'left', padding: 0 }}
          >
            {showAdvanced ? '− Hide advanced fields' : '+ Add code, client, plant, discipline, status'}
          </button>

          {showAdvanced && (
            <div style={{ display: 'grid', gap: 12, padding: 14, background: theme.accentSoft, borderRadius: 8 }}>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                <Field label="Code"       value={form.code}       onChange={(v) => { setCodeTouched(true); update('code', v); }} theme={theme} />
                <Field label="Client"     value={form.client}     onChange={(v) => update('client', v)} theme={theme} />
              </div>
              <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 10 }}>
                <Field label="Plant"      value={form.plant}      onChange={(v) => update('plant', v)} theme={theme} />
                <Field label="Discipline" value={form.discipline} onChange={(v) => update('discipline', v)} theme={theme} />
              </div>
              <div>
                <label style={{ fontSize: 11, fontWeight: 600, color: theme.muted,
                                textTransform: 'uppercase', letterSpacing: 0.4 }}>Status</label>
                <select
                  value={form.status}
                  onChange={(e) => update('status', e.target.value)}
                  style={{
                    width: '100%', padding: '8px 10px', borderRadius: 6,
                    border: `1px solid ${theme.accentBorder}`, fontSize: 13, marginTop: 4, background: '#fff',
                  }}
                >
                  {PROJECT_ORGANIZER_CONFIG.statuses.map((s) => (
                    <option key={s.value} value={s.value}>{s.label}</option>
                  ))}
                </select>
              </div>
            </div>
          )}
        </div>

        <div style={{
          display: 'flex', justifyContent: 'flex-end', gap: 10,
          padding: '14px 22px', borderTop: `1px solid ${theme.accentBorder}`, background: '#fafafa',
        }}>
          <button type="button" onClick={onClose} style={{
            background: 'transparent', border: `1px solid ${theme.accentBorder}`,
            color: theme.muted, padding: '9px 16px', borderRadius: 8,
            fontSize: 13, fontWeight: 500, cursor: 'pointer',
          }}>Cancel</button>
          <button
            type="submit"
            disabled={!canSubmit}
            style={{
              background: canSubmit ? `linear-gradient(135deg, ${theme.accent}, ${theme.accentAlt})` : '#cbd5e1',
              color: '#fff', border: 'none', padding: '9px 20px', borderRadius: 8,
              fontSize: 13, fontWeight: 700, cursor: canSubmit ? 'pointer' : 'not-allowed',
              display: 'inline-flex', alignItems: 'center', gap: 6,
            }}
          >
            <CheckIcon width={14} /> {busy ? 'Saving…' : (initial ? 'Save changes' : 'Create project')}
          </button>
        </div>
      </form>
    </div>
  );
};

export default ProjectFormModal;

/**
 * ProjectSwitcher — dropdown pill (generalized from SpecCustomizationPage.jsx's
 * inline ProjectSwitcher). Shows the active project + a popover to switch,
 * create or clear it.
 */
import { useEffect, useRef, useState } from 'react';
import {
  FolderIcon, ChevronDownIcon, CheckIcon, PlusIcon, Squares2X2Icon, XMarkIcon,
} from '@heroicons/react/24/outline';

const ProjectSwitcher = ({
  projects, activeProject, loading, theme,
  onSwitch, onCreate, onClear, onManage,
}) => {
  const [open, setOpen] = useState(false);
  const containerRef = useRef(null);

  useEffect(() => {
    if (!open) return undefined;
    const onKey = (e) => { if (e.key === 'Escape') setOpen(false); };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [open]);

  return (
    <div ref={containerRef} style={{ position: 'relative' }}>
      <button
        onClick={() => setOpen((v) => !v)}
        disabled={loading}
        style={{
          display: 'inline-flex', alignItems: 'center', gap: 8,
          padding: '7px 12px', fontSize: 13, fontWeight: 600, color: theme.text,
          background: theme.cardBg, border: `1px solid ${theme.accentBorder}`,
          borderRadius: 8, cursor: 'pointer', opacity: loading ? 0.6 : 1,
        }}
        title="Switch project"
      >
        <FolderIcon width={16} style={{ color: theme.accent }} />
        <span style={{ maxWidth: 200, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {loading ? 'Loading…' : (activeProject?.name || 'No project selected')}
        </span>
        <ChevronDownIcon width={14} style={{ color: theme.muted, transform: open ? 'rotate(180deg)' : 'none', transition: 'transform 0.15s' }} />
      </button>

      {open && (
        <>
          <div style={{ position: 'fixed', inset: 0, zIndex: 30 }} onClick={() => setOpen(false)} />
          <div style={{
            position: 'absolute', right: 0, top: '100%', marginTop: 8, width: 320, zIndex: 40,
            background: theme.cardBg, border: `1px solid ${theme.accentBorder}`,
            borderRadius: 12, boxShadow: '0 20px 40px rgba(0,0,0,0.18)', overflow: 'hidden',
          }}>
            <div style={{ padding: '10px 12px', borderBottom: `1px solid ${theme.accentBorder}`,
                          display: 'flex', alignItems: 'center', gap: 8 }}>
              <FolderIcon width={16} style={{ color: theme.accent }} />
              <div style={{ fontSize: 11, fontWeight: 700, color: theme.text, textTransform: 'uppercase',
                            letterSpacing: 0.5, flex: 1 }}>Projects</div>
              <span style={{ fontSize: 10, color: theme.muted }}>{projects.length}</span>
            </div>
            <div style={{ maxHeight: 280, overflowY: 'auto' }}>
              {projects.length === 0 ? (
                <div style={{ padding: '24px 12px', textAlign: 'center', fontSize: 12, color: theme.muted }}>
                  No projects yet.
                </div>
              ) : (
                projects.map((p) => {
                  const active = p.project_id === activeProject?.project_id;
                  return (
                    <button
                      key={p.project_id}
                      onClick={() => { onSwitch(p); setOpen(false); }}
                      style={{
                        width: '100%', textAlign: 'left', padding: '8px 12px',
                        display: 'flex', alignItems: 'flex-start', gap: 8, border: 'none', cursor: 'pointer',
                        background: active ? theme.accentSoft : 'transparent',
                      }}
                    >
                      <div style={{ marginTop: 2, width: 16, height: 16, flexShrink: 0, color: active ? theme.accent : 'transparent' }}>
                        <CheckIcon width={16} />
                      </div>
                      <div style={{ minWidth: 0, flex: 1 }}>
                        <div style={{ fontSize: 13, fontWeight: 600, color: theme.text,
                                      whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{p.name}</div>
                        <div style={{ fontSize: 11, color: theme.muted, whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                          {(p.activity_count || 0)} activit{(p.activity_count || 0) === 1 ? 'y' : 'ies'}
                          {p.code ? ` · ${p.code}` : ''}
                        </div>
                      </div>
                    </button>
                  );
                })
              )}
            </div>
            <div style={{ padding: 8, borderTop: `1px solid ${theme.accentBorder}`,
                          display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: 6 }}>
              <button
                onClick={() => { setOpen(false); onCreate(); }}
                style={{
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                  padding: '7px 8px', fontSize: 12, fontWeight: 600, color: '#fff', border: 'none',
                  borderRadius: 6, cursor: 'pointer',
                  background: `linear-gradient(135deg, ${theme.accent}, ${theme.accentAlt})`,
                }}
              ><PlusIcon width={14} /> New</button>
              <button
                onClick={() => { setOpen(false); onManage(); }}
                style={{
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                  padding: '7px 8px', fontSize: 12, fontWeight: 500, color: theme.text,
                  border: `1px solid ${theme.accentBorder}`, borderRadius: 6, cursor: 'pointer', background: 'transparent',
                }}
              ><Squares2X2Icon width={14} /> Manage</button>
              <button
                onClick={() => { setOpen(false); onClear(); }}
                disabled={!activeProject}
                style={{
                  display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 6,
                  padding: '7px 8px', fontSize: 12, fontWeight: 500, color: theme.text,
                  border: `1px solid ${theme.accentBorder}`, borderRadius: 6,
                  cursor: activeProject ? 'pointer' : 'not-allowed', opacity: activeProject ? 1 : 0.4, background: 'transparent',
                }}
                title="Clear active project"
              ><XMarkIcon width={14} /> Clear</button>
            </div>
          </div>
        </>
      )}
    </div>
  );
};

export default ProjectSwitcher;

/**
 * Sub-Feature Grid Component
 * Smart, reusable grid for displaying sub-features with intelligent interactions
 * Supports actions, badges, and visual hierarchy
 */

import React from 'react';

const SubFeatureGrid = ({ subFeatures, onFeatureClick, columns = 3 }) => {
  if (!subFeatures || subFeatures.length === 0) {
    return null;
  }

  const getActionLabel = (action) => {
    const labels = {
      view: 'View',
      create: 'Create',
      analyze: 'Analyze',
      manage: 'Manage',
      browse: 'Browse',
      generate: 'Generate',
      configure: 'Configure',
      forecast: 'Forecast',
      predict: 'Predict',
      score: 'Score',
      monitor: 'Monitor',
      segment: 'Segment'
    };
    return labels[action] || 'Open';
  };

  const getActionIcon = (action) => {
    const icons = {
      view: '👁️',
      create: '✨',
      analyze: '🔬',
      manage: '⚙️',
      browse: '🔍',
      generate: '📝',
      configure: '🛠️',
      forecast: '🔮',
      predict: '🎯',
      score: '⭐',
      monitor: '📡',
      segment: '🎯'
    };
    return icons[action] || '→';
  };

  const gridColumns = {
    2: 'grid-cols-1 md:grid-cols-2',
    3: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-3',
    4: 'grid-cols-1 md:grid-cols-2 lg:grid-cols-4',
    6: 'grid-cols-2 md:grid-cols-3 lg:grid-cols-6'
  };

  return (
    <div className={`grid ${gridColumns[columns]} gap-4`}>
      {subFeatures
        .filter(feature => feature.enabled)
        .map((feature, index) => (
          <button
            key={feature.id}
            onClick={() => onFeatureClick && onFeatureClick(feature)}
            disabled={!feature.enabled}
            className="group relative bg-white rounded-2xl shadow-lg border-2 border-gray-200 hover:border-blue-400 hover:shadow-2xl transition-all duration-300 p-6 text-left overflow-hidden transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed"
            style={{ animationDelay: `${index * 50}ms` }}
          >
            {/* Gradient Background */}
            <div className={`absolute inset-0 bg-gradient-to-br ${feature.gradient} opacity-0 group-hover:opacity-10 transition-opacity duration-300`}></div>
            
            <div className="relative z-10">
              {/* Header with Icon and Badge */}
              <div className="flex items-start justify-between mb-4">
                <div className={`w-14 h-14 rounded-xl bg-gradient-to-br ${feature.gradient} flex items-center justify-center text-3xl shadow-md transform group-hover:rotate-12 group-hover:scale-110 transition-all duration-300`}>
                  {feature.icon}
                </div>
                {feature.badge && (
                  <span className="px-2 py-1 text-xs font-bold bg-gradient-to-r from-purple-500 to-pink-500 text-white rounded-full shadow-sm animate-pulse">
                    {feature.badge}
                  </span>
                )}
              </div>
              
              {/* Title */}
              <h3 className="font-bold text-gray-900 text-lg mb-2 group-hover:text-blue-600 transition-colors">
                {feature.title}
              </h3>
              
              {/* Description */}
              <p className="text-sm text-gray-600 mb-4 line-clamp-2">
                {feature.description}
              </p>
              
              {/* Action Button */}
              <div className="flex items-center justify-between">
                <span className={`inline-flex items-center gap-2 px-3 py-1.5 bg-gradient-to-r ${feature.gradient} text-white text-xs font-semibold rounded-lg shadow-sm group-hover:shadow-md transition-shadow`}>
                  <span>{getActionIcon(feature.action)}</span>
                  <span>{getActionLabel(feature.action)}</span>
                </span>
                
                {/* Arrow indicator */}
                <div className="text-2xl text-gray-400 opacity-0 group-hover:opacity-100 transform translate-x-0 group-hover:translate-x-1 transition-all duration-300">
                  →
                </div>
              </div>
            </div>
            
            {/* Hover Glow Effect */}
            <div className={`absolute -inset-1 bg-gradient-to-r ${feature.gradient} rounded-2xl blur-lg opacity-0 group-hover:opacity-20 transition-opacity duration-300 -z-10`}></div>
          </button>
        ))}
    </div>
  );
};

export default SubFeatureGrid;

/**
 * Department Usage Chart Component
 * 
 * Bar chart showing usage by department
 */

import React from 'react';
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  Cell,
} from 'recharts';
