  BuildingOfficeIcon,
} from '@heroicons/react/24/outline';

const UsageOverviewCards = ({ data, timeRange }) => {
  const cards = [
    {
      title: 'Total Requests',
      value: data.total_requests?.toLocaleString() || '0',
