/**
 * CreateUserForm - Robust User Creation Form
 * Soft-coded, step-by-step wizard with comprehensive validation
 * Redesigned from scratch for reliability
 */

import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import rbacService from '../../services/rbac.service';

// Soft-coded configuration
const FORM_CONFIG = {
  steps: [
    {
      id: 1,
      title: 'Basic Information',
      subtitle: 'Enter user details',
      icon: '👤',
      fields: ['email', 'first_name', 'last_name']
    },
    {
      id: 2,
      title: 'Password Setup',
      subtitle: 'Create secure password',
      icon: '🔒',
      fields: ['password', 'confirmPassword']
    },
    {
      id: 3,
      title: 'Organization Details',
      subtitle: 'Work information',
      icon: '🏢',
      fields: ['organization_id', 'department', 'job_title', 'phone']
    },
    {
      id: 4,
      title: 'Access Control',
      subtitle: 'Assign permissions',
      icon: '🔑',
      fields: ['role_ids', 'module_ids']
    }
  ],
  
  validation: {
    email: {
      required: true,
      pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
      message: 'Valid email address is required'
    },
    first_name: {
      required: true,
      minLength: 2,
      message: 'First name must be at least 2 characters'
    },
    last_name: {
      required: true,
      minLength: 2,
      message: 'Last name must be at least 2 characters'
    },
    password: {
      required: true,
      minLength: 8,
      message: 'Password must be at least 8 characters'
    },
    confirmPassword: {
      required: true,
      matchField: 'password',
      message: 'Passwords must match'
    }
  },
  
  messages: {
    success: 'User created successfully!',
    error: 'Failed to create user. Please try again.',
    loading: 'Creating user...'
  }
};

const CreateUserForm = ({ onSuccess, onCancel }) => {
  const { roles, modules } = useSelector((state) => state.rbac);
  const [currentStep, setCurrentStep] = useState(1);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});
  const [organizations, setOrganizations] = useState([]);
  
  // Form data state
  const [formData, setFormData] = useState({
    email: '',
    first_name: '',
    last_name: '',
    password: '',
    confirmPassword: '',
    organization_id: '',
    department: '',
    job_title: '',
    phone: '',
    role_ids: [],
    module_ids: []
  });
  
  // Load organizations on mount
  useEffect(() => {
    loadOrganizations();
  }, []);
  
  const loadOrganizations = async () => {
    try {
      const response = await rbacService.getOrganizations();
      const orgs = response?.data?.data || response?.data || [];
      setOrganizations(Array.isArray(orgs) ? orgs : []);
      
      // Auto-select first organization if available
      if (orgs.length > 0 && !formData.organization_id) {
        setFormData(prev => ({ ...prev, organization_id: orgs[0].id }));
      }
    } catch (error) {
      console.error('[CreateUserForm] Failed to load organizations:', error);
    }
  };
  
  // Validate current step
  const validateStep = (step) => {
    const stepConfig = FORM_CONFIG.steps.find(s => s.id === step);
    if (!stepConfig) return true;
    
    const stepErrors = {};
    
    stepConfig.fields.forEach(field => {
      const validation = FORM_CONFIG.validation[field];
      if (!validation) return;
      
      const value = formData[field];
      
      // Required validation
      if (validation.required && (!value || (Array.isArray(value) && value.length === 0))) {
        stepErrors[field] = validation.message || `${field} is required`;
        return;
      }
      
      // Pattern validation
      if (validation.pattern && value && !validation.pattern.test(value)) {
        stepErrors[field] = validation.message;
        return;
      }
      
      // Min length validation
      if (validation.minLength && value && value.length < validation.minLength) {
        stepErrors[field] = validation.message;
        return;
      }
      
      // Match field validation
      if (validation.matchField && value !== formData[validation.matchField]) {
        stepErrors[field] = validation.message;
        return;
      }
    });
    
    setErrors(stepErrors);
    return Object.keys(stepErrors).length === 0;
  };
  
  // Handle next step
  const handleNext = () => {
    if (validateStep(currentStep)) {
      setCurrentStep(prev => Math.min(prev + 1, FORM_CONFIG.steps.length));
    }
  };
  
  // Handle previous step
  const handlePrevious = () => {
    setCurrentStep(prev => Math.max(prev - 1, 1));
    setErrors({});
  };
  
  // Handle form submission
  const handleSubmit = async () => {
    if (!validateStep(currentStep)) {
      return;
    }
    
    setLoading(true);
    setErrors({});
    
    try {
      // Prepare payload (remove confirmPassword)
      const { confirmPassword, ...payload } = formData;
      
      // Ensure data is properly formatted
      const finalPayload = {
        email: payload.email?.trim().toLowerCase(),
        first_name: payload.first_name?.trim(),
        last_name: payload.last_name?.trim(),
        password: payload.password,
        organization_id: payload.organization_id || null,
        department: payload.department?.trim() || null,
        job_title: payload.job_title?.trim() || null,
        phone: payload.phone?.trim() || null,
        role_ids: Array.isArray(payload.role_ids) ? payload.role_ids : [],
        module_ids: Array.isArray(payload.module_ids) ? payload.module_ids : []
      };
      
      console.log('[CreateUserForm] Submitting payload:', finalPayload);
      
      const response = await rbacService.createUser(finalPayload);
      console.log('[CreateUserForm] Success:', response);
      
      if (onSuccess) {
        onSuccess(response.data);
      }
    } catch (error) {
      console.error('[CreateUserForm] Error:', error);
      console.error('[CreateUserForm] Error response:', error.response?.data);
      
      // Parse error response
      const errorData = error.response?.data;
      if (errorData && typeof errorData === 'object') {
        const fieldErrors = {};
        Object.entries(errorData).forEach(([field, messages]) => {
          if (field !== 'detail' && field !== 'message') {
            fieldErrors[field] = Array.isArray(messages) ? messages[0] : messages;
          }
        });
        setErrors(fieldErrors);
      } else {
        setErrors({ general: FORM_CONFIG.messages.error });
      }
    } finally {
      setLoading(false);
    }
  };
  
  // Handle input change
  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error for this field
    if (errors[field]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[field];
        return newErrors;
      });
    }
  };
  
  // Render step 1: Basic Information
  const renderStep1 = () => (
    <div className="space-y-4">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Email Address <span className="text-red-500">*</span>
        </label>
        <input
          type="email"
          value={formData.email}
          onChange={(e) => handleChange('email', e.target.value)}
          className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
            errors.email ? 'border-red-500' : 'border-gray-300'
          }`}
          placeholder="user@example.com"
          autoFocus
        />
        {errors.email && (
          <p className="mt-1 text-sm text-red-600">{errors.email}</p>
        )}
      </div>
      
      <div className="grid grid-cols-2 gap-4">
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            First Name <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            value={formData.first_name}
            onChange={(e) => handleChange('first_name', e.target.value)}
            className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
              errors.first_name ? 'border-red-500' : 'border-gray-300'
            }`}
            placeholder="John"
          />
          {errors.first_name && (
            <p className="mt-1 text-sm text-red-600">{errors.first_name}</p>
          )}
        </div>
        
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Last Name <span className="text-red-500">*</span>
          </label>
          <input
            type="text"
            value={formData.last_name}
            onChange={(e) => handleChange('last_name', e.target.value)}
            className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
              errors.last_name ? 'border-red-500' : 'border-gray-300'
            }`}
            placeholder="Doe"
          />
          {errors.last_name && (
            <p className="mt-1 text-sm text-red-600">{errors.last_name}</p>
          )}
        </div>
      </div>
    </div>
  );
  
  // Render step 2: Password Setup
  const renderStep2 = () => (
    <div className="space-y-4">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Password <span className="text-red-500">*</span>
        </label>
        <input
          type="password"
          value={formData.password}
          onChange={(e) => handleChange('password', e.target.value)}
          className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
            errors.password ? 'border-red-500' : 'border-gray-300'
          }`}
          placeholder="Enter password (min 8 characters)"
          autoFocus
        />
        {errors.password && (
          <p className="mt-1 text-sm text-red-600">{errors.password}</p>
        )}
      </div>
      
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Confirm Password <span className="text-red-500">*</span>
        </label>
        <input
          type="password"
          value={formData.confirmPassword}
          onChange={(e) => handleChange('confirmPassword', e.target.value)}
          className={`w-full px-4 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 ${
            errors.confirmPassword ? 'border-red-500' : 'border-gray-300'
          }`}
          placeholder="Confirm password"
        />
        {errors.confirmPassword && (
          <p className="mt-1 text-sm text-red-600">{errors.confirmPassword}</p>
        )}
      </div>
      
      <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
        <p className="text-sm text-blue-800">
          <strong>Password Requirements:</strong>
          <ul className="mt-2 ml-4 list-disc">
            <li>Minimum 8 characters</li>
            <li>At least one uppercase letter recommended</li>
            <li>At least one number recommended</li>
          </ul>
        </p>
      </div>
    </div>
  );
  
  // Render step 3: Organization Details
  const renderStep3 = () => (
    <div className="space-y-4">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Organization
        </label>
        <select
          value={formData.organization_id}
          onChange={(e) => handleChange('organization_id', e.target.value)}
          className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
        >
          <option value="">Select organization</option>
          {organizations.map(org => (
            <option key={org.id} value={org.id}>
              {org.name}
            </option>
          ))}
        </select>
      </div>
      
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Department
        </label>
        <input
          type="text"
          value={formData.department}
          onChange={(e) => handleChange('department', e.target.value)}
          className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
          placeholder="e.g., Engineering"
        />
      </div>
      
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Job Title
        </label>
        <input
          type="text"
          value={formData.job_title}
          onChange={(e) => handleChange('job_title', e.target.value)}
          className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
          placeholder="e.g., Software Engineer"
        />
      </div>
      
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Phone Number
        </label>
        <input
          type="tel"
          value={formData.phone}
          onChange={(e) => handleChange('phone', e.target.value)}
          className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
          placeholder="+971501234567"
        />
      </div>
    </div>
  );
  
  // Render step 4: Access Control
  const renderStep4 = () => (
    <div className="space-y-6">
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-3">
          Roles (Optional)
        </label>
        <div className="grid grid-cols-2 gap-3 max-h-64 overflow-y-auto p-2">
          {Array.isArray(roles) && roles.map(role => (
            <label
              key={role.id}
              className={`flex items-center p-3 border-2 rounded-lg cursor-pointer transition-all ${
                formData.role_ids.includes(role.id)
                  ? 'border-blue-500 bg-blue-50'
                  : 'border-gray-200 hover:border-blue-300'
              }`}
            >
              <input
                type="checkbox"
                checked={formData.role_ids.includes(role.id)}
                onChange={(e) => {
                  const newRoles = e.target.checked
                    ? [...formData.role_ids, role.id]
                    : formData.role_ids.filter(id => id !== role.id);
                  handleChange('role_ids', newRoles);
                }}
                className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
              />
              <div className="ml-3">
                <span className="text-sm font-medium text-gray-900">{role.name}</span>
                {role.description && (
                  <p className="text-xs text-gray-500 mt-0.5">{role.description}</p>
                )}
              </div>
            </label>
          ))}
        </div>
      </div>
      
      <div>
        <label className="block text-sm font-medium text-gray-700 mb-3">
          Accessible Modules (Optional)
        </label>
        <div className="grid grid-cols-3 gap-3 max-h-64 overflow-y-auto p-2">
          {Array.isArray(modules) && modules.map(module => (
            <label
              key={module.id}
              className={`flex flex-col items-center p-4 border-2 rounded-lg cursor-pointer transition-all ${
                formData.module_ids.includes(module.id)
                  ? 'border-purple-500 bg-purple-50'
                  : 'border-gray-200 hover:border-purple-300'
              }`}
            >
              <input
                type="checkbox"
                checked={formData.module_ids.includes(module.id)}
                onChange={(e) => {
                  const newModules = e.target.checked
                    ? [...formData.module_ids, module.id]
                    : formData.module_ids.filter(id => id !== module.id);
                  handleChange('module_ids', newModules);
                }}
                className="mb-2 w-4 h-4 text-purple-600 border-gray-300 rounded focus:ring-purple-500"
              />
              <span className="text-sm font-medium text-gray-900 text-center">{module.name}</span>
            </label>
          ))}
        </div>
        {errors.module_ids && (
          <p className="mt-2 text-sm text-red-600">{errors.module_ids}</p>
        )}
      </div>
    </div>
  );
  
  const currentStepConfig = FORM_CONFIG.steps.find(s => s.id === currentStep);
  
  return (
    <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-hidden">
      {/* Header */}
      <div className="bg-gradient-to-r from-blue-600 to-purple-600 p-6 text-white">
        <div className="flex items-center justify-between">
          <div>
            <h2 className="text-2xl font-bold">Create New User</h2>
            <p className="text-blue-100 mt-1">Step {currentStep} of {FORM_CONFIG.steps.length}</p>
          </div>
          <button
            onClick={onCancel}
            className="text-white hover:text-gray-200 transition-colors"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
        
        {/* Progress bar */}
        <div className="mt-4 bg-white/20 rounded-full h-2">
          <div
            className="bg-white rounded-full h-2 transition-all duration-300"
            style={{ width: `${(currentStep / FORM_CONFIG.steps.length) * 100}%` }}
          />
        </div>
      </div>
      
      {/* Content */}
      <div className="p-8 overflow-y-auto" style={{ maxHeight: 'calc(90vh - 240px)' }}>
        {/* Step indicator */}
        <div className="text-center mb-8">
          <div className="text-4xl mb-3">{currentStepConfig?.icon}</div>
          <h3 className="text-xl font-bold text-gray-900">{currentStepConfig?.title}</h3>
          <p className="text-gray-600 mt-1">{currentStepConfig?.subtitle}</p>
        </div>
        
        {/* General error */}
        {errors.general && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg">
            <p className="text-sm text-red-800">{errors.general}</p>
          </div>
        )}
        
        {/* Form fields */}
        <div className="max-w-2xl mx-auto">
          {currentStep === 1 && renderStep1()}
          {currentStep === 2 && renderStep2()}
          {currentStep === 3 && renderStep3()}
          {currentStep === 4 && renderStep4()}
        </div>
      </div>
      
      {/* Footer */}
      <div className="border-t border-gray-200 p-6 bg-gray-50 flex items-center justify-between">
        <button
          onClick={handlePrevious}
          disabled={currentStep === 1}
          className="px-6 py-3 text-gray-700 bg-white border border-gray-300 rounded-lg hover:bg-gray-50 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
        >
          ← Previous
        </button>
        
        <div className="flex items-center space-x-2">
          {FORM_CONFIG.steps.map(step => (
            <div
              key={step.id}
              className={`w-2 h-2 rounded-full ${
                step.id === currentStep ? 'bg-blue-600' : step.id < currentStep ? 'bg-green-500' : 'bg-gray-300'
              }`}
            />
          ))}
        </div>
        
        {currentStep < FORM_CONFIG.steps.length ? (
          <button
            onClick={handleNext}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            Next →
          </button>
        ) : (
          <button
            onClick={handleSubmit}
            disabled={loading}
            className="px-8 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
          >
            {loading ? (
              <>
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z" />
                </svg>
                Creating...
              </>
            ) : (
              '✓ Create User'
            )}
          </button>
        )}
      </div>
    </div>
  );
};

export default CreateUserForm;

﻿import React, { useState, useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import rbacService from '../../services/rbac.service';
import { fetchOrganizations, fetchDepartments, fetchJobTitles, fetchRoles } from '../../store/slices/rbacSlice';
import {
  ROLE_LEVEL_COLORS,
  DEFAULT_LEVEL_COLOR,
  ROLE_LEVEL_LABELS,
  CUSTOM_ROLE_PREFIX,
  SENSITIVE_ROLE_CODES,
  SUPER_ADMIN_ROLE_CODE,
} from '../../config/rbacAccess.config';

/**
 * Simple Create User Form — basic profile + role assignment.
 * The role list is sourced live from Admin › Roles & Access Management
 * (/admin/roles). Module access is derived automatically from the assigned roles.
 */

const FORM_CONFIG = {
  title: 'Create New User',
  subtitle: 'Fill in the required information below',
  requiredFields: ['email', 'first_name', 'last_name', 'password'],
  sections: [
    {
      id: 'basic',
      title: 'Basic Information',
      description: 'Essential user details',
      icon: 'M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z',
      collapsible: false,
      collapsed: false
    },
    {
      id: 'work',
      title: 'Work Information',
      description: 'Job-related details (Optional)',
      icon: 'M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z',
      collapsible: true,
      collapsed: true
    },
    {
      id: 'roles',
      title: 'Role Assignment',
      description: 'Pick one or more roles — access to modules follows from roles',
      icon: 'M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z',
      collapsible: true,
      collapsed: false
    }
  ],
  validation: {
    email: { pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/, message: 'Invalid email format' },
    password: { minLength: 8, message: 'Password must be at least 8 characters' },
    first_name: { minLength: 2, message: 'First name must be at least 2 characters' },
    last_name: { minLength: 2, message: 'Last name must be at least 2 characters' }
  },
  messages: {
    success: 'User created successfully!',
    loading: 'Creating user...',
    error: 'Failed to create user. Please try again.'
  }
};

const SimpleCreateUserForm = ({ onSuccess, onCancel }) => {
  const dispatch = useDispatch();
  const { organizations, departments, jobTitles, roles } = useSelector((state) => state.rbac);
  
  const [formData, setFormData] = useState({
    email: '',
    first_name: '',
    last_name: '',
    password: '',
    organization_id: '',
    department: '',
    job_title: '',
    phone: '',
    role_ids: []
  });
  
  const [errors, setErrors] = useState({});
  const [isLoading, setIsLoading] = useState(false);
  const [isCheckingEmail, setIsCheckingEmail] = useState(false);
  const [expandedSections, setExpandedSections] = useState({});

  // Dynamic role list — excludes internal `custom_*` per-user roles.
  const assignableRoles = useMemo(
    () => (roles || []).filter(r => r?.code && !r.code.startsWith(CUSTOM_ROLE_PREFIX)),
    [roles]
  );

  // Initialize expanded sections based on configuration
  useEffect(() => {
    const initialExpanded = {};
    FORM_CONFIG.sections.forEach(section => {
      initialExpanded[section.id] = !section.collapsed;
    });
    setExpandedSections(initialExpanded);
  }, []);

  useEffect(() => {
    dispatch(fetchOrganizations());
    dispatch(fetchDepartments());
    dispatch(fetchJobTitles());
    dispatch(fetchRoles());
  }, [dispatch]);

  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    // Clear error for this field
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: null }));
    }
  };
  // Check if email already exists (debounced)
  const checkEmailExists = async (email) => {
    if (!email || !email.includes('@')) return;
    
    setIsCheckingEmail(true);
    try {
      const response = await rbacService.getUsers({ search: email });
      const existingUser = response.results?.find(u => u.email?.toLowerCase() === email.toLowerCase());
      
      if (existingUser) {
        setErrors(prev => ({ 
          ...prev, 
          email: `User already exists: ${existingUser.first_name} ${existingUser.last_name}` 
        }));
        return true;
      }
      return false;
    } catch (error) {
      console.error('[SimpleCreateUserForm] Error checking email:', error);
      return false;
    } finally {
      setIsCheckingEmail(false);
    }
  };
  const handleToggleRole = (roleId) => {
    setFormData(prev => ({
      ...prev,
      role_ids: prev.role_ids.includes(roleId)
        ? prev.role_ids.filter(id => id !== roleId)
        : [...prev.role_ids, roleId]
    }));
  };

  const toggleSection = (sectionId) => {
    setExpandedSections(prev => ({
      ...prev,
      [sectionId]: !prev[sectionId]
    }));
  };

  const validateField = (field, value) => {
    const validation = FORM_CONFIG.validation[field];
    if (!validation) return null;

    if (validation.pattern && !validation.pattern.test(value)) {
      return validation.message;
    }
    if (validation.minLength && value.length < validation.minLength) {
      return validation.message;
    }
    return null;
  };

  const validateForm = () => {
    const newErrors = {};
    
    // Check required fields
    FORM_CONFIG.requiredFields.forEach(field => {
      if (!formData[field] || formData[field].trim() === '') {
        newErrors[field] = `${field.replace('_', ' ')} is required`;
      } else {
        const error = validateField(field, formData[field]);
        if (error) newErrors[field] = error;
      }
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      return;
    }

    // Check if email already exists before submitting
    const emailExists = await checkEmailExists(formData.email);
    if (emailExists) {
      return; // Stop submission if email exists
    }

    setIsLoading(true);
    
    try {
      // Prepare payload - trim strings and remove empty optionals
      const payload = {
        email: formData.email.trim(),
        first_name: formData.first_name.trim(),
        last_name: formData.last_name.trim(),
        password: formData.password,
        ...(formData.organization_id && { organization_id: formData.organization_id }),
        ...(formData.department && { department: formData.department.trim() }),
        ...(formData.job_title && { job_title: formData.job_title.trim() }),
        ...(formData.phone && { phone: formData.phone.trim() }),
        ...(formData.role_ids.length > 0 && { role_ids: formData.role_ids })
      };

      console.log('[SimpleCreateUserForm] Submitting:', payload);
      const response = await rbacService.createUser(payload);
      console.log('[SimpleCreateUserForm] Success:', response);
      
      if (onSuccess) {
        onSuccess(response);
      }
    } catch (error) {
      console.error('[SimpleCreateUserForm] Error:', error);
      
      // Parse backend errors
      if (error.response?.data) {
        const backendErrors = {};
        Object.keys(error.response.data).forEach(key => {
          const errorValue = error.response.data[key];
          if (Array.isArray(errorValue)) {
            backendErrors[key] = errorValue[0];
          } else if (typeof errorValue === 'object') {
            backendErrors[key] = JSON.stringify(errorValue);
          } else {
            backendErrors[key] = errorValue;
          }
        });
        setErrors(backendErrors);
        
        // Show general error notification for email conflicts
        if (backendErrors.email && backendErrors.email.includes('already exists')) {
          setErrors(prev => ({
            ...prev,
            general: '❌ Cannot create user: This email address is already registered in the system. Please use a different email.'
          }));
        }
      } else if (error.response?.status === 400) {
        setErrors({ general: '❌ Invalid data provided. Please check all fields and try again.' });
      } else {
        setErrors({ general: FORM_CONFIG.messages.error });
      }
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="bg-white rounded-xl shadow-2xl max-w-4xl w-full max-h-[90vh] overflow-hidden flex flex-col">
      {/* Header - Matching EditUserModal */}
      <div className="px-6 py-4 border-b border-gray-200 bg-gradient-to-r from-blue-600 to-indigo-600">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="p-2 bg-white bg-opacity-20 rounded-lg">
              <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z" />
              </svg>
            </div>
            <div>
              <h2 className="text-2xl font-bold text-white">{FORM_CONFIG.title}</h2>
              <p className="text-blue-100 text-sm">{FORM_CONFIG.subtitle}</p>
            </div>
          </div>
          <button
            onClick={onCancel}
            type="button"
            className="text-white hover:text-gray-200 transition-colors p-2 hover:bg-white hover:bg-opacity-20 rounded-lg"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
            </svg>
          </button>
        </div>
      </div>

      {/* Form Content - Scrollable */}
      <div className="flex-1 overflow-y-auto">
        <form onSubmit={handleSubmit} className="p-6 space-y-6">
          
          {/* General Error */}
          {errors.general && (
            <div className="bg-red-50 border-l-4 border-red-500 text-red-700 px-4 py-3 rounded-lg flex items-start">
              <svg className="w-5 h-5 mr-2 mt-0.5" fill="currentColor" viewBox="0 0 20 20">
                <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
              </svg>
              {errors.general}
            </div>
          )}

          {/* Basic Information Section */}
          {renderSection('basic', (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Email */}
              <div className="col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Email Address <span className="text-red-500 ml-1">*</span>
                </label>
                <div className="relative">
                  <input
                    type="email"
                    value={formData.email}
                    onChange={(e) => handleChange('email', e.target.value)}
                    onBlur={(e) => e.target.value && checkEmailExists(e.target.value)}
                    className={`w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all ${
                      errors.email ? 'border-red-500' : 'border-gray-300'
                    }`}
                    placeholder="user@example.com"
                    disabled={isLoading || isCheckingEmail}
                  />
                  {isCheckingEmail && (
                    <div className="absolute right-3 top-3">
                      <svg className="animate-spin h-5 w-5 text-blue-500" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                    </div>
                  )}
                </div>
                {errors.email && (
                  <p className="text-xs text-red-600 mt-1 flex items-center">
                    <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                    {errors.email}
                  </p>
                )}
              </div>

              {/* First Name */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  First Name <span className="text-red-500 ml-1">*</span>
                </label>
                <input
                  type="text"
                  value={formData.first_name}
                  onChange={(e) => handleChange('first_name', e.target.value)}
                  className={`w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all ${
                    errors.first_name ? 'border-red-500' : 'border-gray-300'
                  }`}
                  placeholder="John"
                  disabled={isLoading}
                />
                {errors.first_name && (
                  <p className="text-xs text-red-600 mt-1 flex items-center">
                    <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                    {errors.first_name}
                  </p>
                )}
              </div>

              {/* Last Name */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Last Name <span className="text-red-500 ml-1">*</span>
                </label>
                <input
                  type="text"
                  value={formData.last_name}
                  onChange={(e) => handleChange('last_name', e.target.value)}
                  className={`w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all ${
                    errors.last_name ? 'border-red-500' : 'border-gray-300'
                  }`}
                  placeholder="Doe"
                  disabled={isLoading}
                />
                {errors.last_name && (
                  <p className="text-xs text-red-600 mt-1 flex items-center">
                    <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                    {errors.last_name}
                  </p>
                )}
              </div>

              {/* Password */}
              <div className="col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Password <span className="text-red-500 ml-1">*</span>
                </label>
                <input
                  type="password"
                  value={formData.password}
                  onChange={(e) => handleChange('password', e.target.value)}
                  className={`w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all ${
                    errors.password ? 'border-red-500' : 'border-gray-300'
                  }`}
                  placeholder="Minimum 8 characters"
                  disabled={isLoading}
                />
                {errors.password && (
                  <p className="text-xs text-red-600 mt-1 flex items-center">
                    <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                    {errors.password}
                  </p>
                )}
                {!errors.password && (
                  <p className="text-xs text-gray-500 mt-1">Minimum 8 characters required</p>
                )}
              </div>

              {/* Organization */}
              <div className="col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Organization
                </label>
                <select
                  value={formData.organization_id}
                  onChange={(e) => handleChange('organization_id', e.target.value)}
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900"
                  disabled={isLoading}
                >
                  <option value="">Select organization (optional)</option>
                  {organizations?.map(org => (
                    <option key={org.id} value={org.id}>
                      {org.name}
                    </option>
                  ))}
                </select>
                <p className="text-xs text-gray-500 mt-1">If not selected, default organization will be assigned</p>
              </div>
            </div>
          ))}

          {/* Work Information Section - Collapsible */}
          {renderSection('work', (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Department - Dynamic Dropdown */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Department</label>
                <select
                  value={formData.department}
                  onChange={(e) => handleChange('department', e.target.value)}
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all bg-white"
                  disabled={isLoading}
                >
                  <option value="">Select Department</option>
                  {departments.map((dept) => (
                    <option key={dept} value={dept}>
                      {dept}
                    </option>
                  ))}
                </select>
              </div>

              {/* Job Title - Dynamic Dropdown */}
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-2">Organizational role / Job title</label>
                <select
                  value={formData.job_title}
                  onChange={(e) => handleChange('job_title', e.target.value)}
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all bg-white"
                  disabled={isLoading}
                >
                  <option value="">Select organizational role / job title</option>
                  {jobTitles.map((title) => (
                    <option key={title} value={title}>
                      {title}
                    </option>
                  ))}
                </select>
              </div>

              {/* Phone Number */}
              <div className="col-span-2">
                <label className="block text-sm font-medium text-gray-700 mb-2">Phone Number</label>
                <input
                  type="tel"
                  value={formData.phone}
                  onChange={(e) => handleChange('phone', e.target.value)}
                  className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
                  placeholder="+971501234567"
                  disabled={isLoading}
                />
              </div>
            </div>
          ))}

          {/* Role Assignment Section */}
          {renderSection('roles', (
            <div className="space-y-4">
              <div className="flex items-start gap-3 rounded-lg border border-blue-200 bg-blue-50 px-4 py-3">
                <span className="text-xl">🛡️</span>
                <div className="flex-1 text-sm text-blue-900">
                  <p className="font-semibold">Access follows from roles.</p>
                  <p className="text-blue-800 mt-0.5">
                    Roles listed below come from <span className="font-semibold">Admin › Roles & Access Management</span>.
                    Assigned roles grant module access automatically. Users left unassigned get the system Default role.
                  </p>
                </div>
              </div>

              {formData.role_ids.length > 0 && (
                <div className="flex items-center justify-between rounded-lg border border-purple-200 bg-gradient-to-r from-purple-50 to-pink-50 px-4 py-2.5">
                  <div className="flex items-center gap-2">
                    <span className="inline-flex items-center justify-center w-6 h-6 bg-purple-600 text-white rounded-full text-xs font-bold">
                      {formData.role_ids.length}
                    </span>
                    <span className="text-sm font-semibold text-purple-900">
                      Role{formData.role_ids.length !== 1 ? 's' : ''} selected
                    </span>
                  </div>
                  <button
                    type="button"
                    onClick={() => setFormData(prev => ({ ...prev, role_ids: [] }))}
                    className="text-xs text-purple-700 hover:text-purple-900 underline"
                    disabled={isLoading}
                  >
                    Clear all
                  </button>
                </div>
              )}

              <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-h-96 overflow-y-auto border-2 border-gray-200 rounded-xl p-3 bg-white">
                {assignableRoles.length === 0 ? (
                  <div className="col-span-2 text-center py-8 text-gray-500 bg-gray-50 rounded-lg">
                    <div className="text-3xl mb-2">🔒</div>
                    <div className="text-sm font-medium">No assignable roles found.</div>
                    <div className="text-xs mt-1">Define roles at /admin/roles first.</div>
                  </div>
                ) : (
                  assignableRoles.map((role) => {
                    const isSelected = formData.role_ids.includes(role.id);
                    const color = ROLE_LEVEL_COLORS[role.level] || DEFAULT_LEVEL_COLOR;
                    const levelLabel = ROLE_LEVEL_LABELS[role.level] || 'Custom';
                    const isSensitive = SENSITIVE_ROLE_CODES.includes(role.code);
                    const isSuper = role.code === SUPER_ADMIN_ROLE_CODE;
                    return (
                      <label
                        key={role.id}
                        className={`flex items-start gap-3 p-3 border-2 rounded-lg cursor-pointer transition-all ${
                          isSelected
                            ? `${color.border || 'border-blue-500'} ${color.bg} shadow-sm`
                            : 'border-gray-200 bg-white hover:border-blue-300'
                        }`}
                      >
                        <input
                          type="checkbox"
                          checked={isSelected}
                          onChange={() => handleToggleRole(role.id)}
                          className="mt-1 w-4 h-4 text-blue-600 rounded focus:ring-2 focus:ring-blue-500"
                          disabled={isLoading}
                        />
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 flex-wrap">
                            <span className={`inline-flex items-center gap-1.5 px-2 py-0.5 rounded-full text-xs font-semibold ${color.bg} ${color.text}`}>
                              <span className={`w-1.5 h-1.5 rounded-full ${color.dot}`} />
                              L{role.level ?? '-'} · {levelLabel}
                            </span>
                            <span className="text-sm font-semibold text-gray-900 truncate">{role.name}</span>
                            {isSuper && <span className="text-xs">👑</span>}
                            {isSensitive && (
                              <span className="inline-flex items-center gap-1 text-xs font-semibold text-amber-800 bg-amber-100 px-1.5 py-0.5 rounded">
                                ⚠️ Sensitive
                              </span>
                            )}
                          </div>
                          {role.description && (
                            <p className="text-xs text-gray-600 mt-1 line-clamp-2">{role.description}</p>
                          )}
                        </div>
                      </label>
                    );
                  })
                )}
              </div>
            </div>
          ))}

        </form>
      </div>
      {/* End Form Content */}

      {/* Footer - Fixed */}
      <div className="px-6 py-4 border-t border-gray-200 bg-gray-50 flex items-center justify-end gap-3">
        <button
          type="button"
          onClick={onCancel}
          disabled={isLoading}
          className="px-6 py-2.5 border-2 border-gray-300 rounded-lg text-gray-700 font-medium hover:bg-gray-100 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
        >
          Cancel
        </button>
        <button
          onClick={handleSubmit}
          disabled={isLoading || isCheckingEmail}
          className="px-6 py-2.5 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-lg font-medium hover:from-blue-700 hover:to-indigo-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
        >
          {isLoading ? (
            <>
              <svg className="animate-spin h-5 w-5" fill="none" viewBox="0 0 24 24">
                <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
              </svg>
              <span>{FORM_CONFIG.messages.loading}</span>
            </>
          ) : (
            <>
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M18 9v3m0 0v3m0-3h3m-3 0h-3m-2-5a4 4 0 11-8 0 4 4 0 018 0zM3 20a6 6 0 0112 0v1H3v-1z" />
              </svg>
              <span>Create User</span>
            </>
          )}
        </button>
      </div>
    </div>
  );

  // Helper function to render collapsible sections
  function renderSection(sectionId, content) {
    const section = FORM_CONFIG.sections.find(s => s.id === sectionId);
    if (!section) return null;

    const isExpanded = expandedSections[sectionId];
    const isCollapsible = section.collapsible;

    return (
      <div key={sectionId} className="border-b border-gray-200 pb-6 last:border-b-0">
        <div
          className={`flex items-center justify-between mb-4 ${isCollapsible ? 'cursor-pointer' : ''}`}
          onClick={() => isCollapsible && toggleSection(sectionId)}
        >
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-100 rounded-lg">
              <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={section.icon} />
              </svg>
            </div>
            <div>
              <h3 className="text-lg font-semibold text-gray-900">{section.title}</h3>
              {section.description && (
                <p className="text-sm text-gray-600">{section.description}</p>
              )}
            </div>
          </div>
          {isCollapsible && (
            <svg
              className={`w-5 h-5 text-gray-500 transition-transform ${isExpanded ? 'transform rotate-180' : ''}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          )}
        </div>

        {isExpanded && content}
      </div>
    );
  }
};

export default SimpleCreateUserForm;

import { radaiAlert } from '../../services/radaiDialog'
import React, { useState, useMemo } from 'react';

/**
 * Access to All Users Modal
 * Allows bulk assignment of selected modules/apps to all users in the system
 * Smart, soft-coded implementation with multi-select capability
 */
const AccessToAllModal = ({
  isOpen,
  onClose,
  onAssign,
  modules = [],
  totalUsers = 0,
  loading = false
}) => {
  const [selectedModules, setSelectedModules] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [confirmationStep, setConfirmationStep] = useState(false);

  // Filter modules based on search
  const filteredModules = useMemo(() => {
    if (!searchTerm.trim()) return modules;
    
    const search = searchTerm.toLowerCase();
    return modules.filter(module => 
      module.name?.toLowerCase().includes(search) ||
      module.code?.toLowerCase().includes(search) ||
      module.description?.toLowerCase().includes(search)
    );
  }, [modules, searchTerm]);

  // Toggle module selection
  const toggleModule = (moduleCode) => {
    setSelectedModules(prev => 
      prev.includes(moduleCode)
        ? prev.filter(code => code !== moduleCode)
        : [...prev, moduleCode]
    );
  };

  // Select all filtered modules
  const selectAll = () => {
    const allCodes = filteredModules.map(m => m.code);
    setSelectedModules(allCodes);
  };

  // Clear all selections
  const clearAll = () => {
    setSelectedModules([]);
  };

  // Handle confirmation and assignment
  const handleConfirm = async () => {
    if (selectedModules.length === 0) {
      await radaiAlert('Please select at least one app/module');
      return;
    }
    setConfirmationStep(true);
  };

  // Execute the assignment
  const handleFinalAssign = async () => {
    try {
      await onAssign(selectedModules);
      // Reset on success
      setSelectedModules([]);
      setSearchTerm('');
      setConfirmationStep(false);
      onClose();
    } catch (error) {
      console.error('Failed to assign modules:', error);
    }
  };

  // Cancel and reset
  const handleCancel = () => {
    setSelectedModules([]);
    setSearchTerm('');
    setConfirmationStep(false);
    onClose();
  };

  // Go back from confirmation
  const handleBack = () => {
    setConfirmationStep(false);
  };

  if (!isOpen) return null;

  // Get selected module names for confirmation
  const selectedModuleNames = modules
    .filter(m => selectedModules.includes(m.code))
    .map(m => m.name || m.code)
    .join(', ');

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-3xl w-full max-h-[90vh] overflow-hidden flex flex-col">
        {/* Header */}
        <div className="px-6 py-4 border-b border-gray-200 bg-gradient-to-r from-purple-600 to-indigo-600">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
              </svg>
              <div>
                <h2 className="text-2xl font-bold text-white">
                  {confirmationStep ? 'Confirm Access Assignment' : 'Grant Access to All Users'}
                </h2>
                <p className="text-purple-100 text-sm">
                  {confirmationStep 
                    ? `Assigning to ${totalUsers} users`
                    : `Select apps/modules to grant access to all ${totalUsers} users`
                  }
                </p>
              </div>
            </div>
            <button
              onClick={handleCancel}
              className="text-white hover:text-gray-200 transition-colors"
              disabled={loading}
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-y-auto p-6">
          {!confirmationStep ? (
            // Step 1: Module Selection
            <>
              {/* Search and Actions */}
              <div className="mb-4 space-y-3">
                <div className="relative">
                  <input
                    type="text"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    placeholder="Search apps/modules..."
                    className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent"
                  />
                  <svg className="w-5 h-5 text-gray-400 absolute left-3 top-1/2 transform -translate-y-1/2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                  </svg>
                </div>

                <div className="flex items-center justify-between">
                  <div className="text-sm text-gray-600">
                    {selectedModules.length} of {filteredModules.length} selected
                  </div>
                  <div className="flex gap-2">
                    <button
                      onClick={selectAll}
                      className="px-3 py-1 text-sm text-purple-600 hover:bg-purple-50 rounded-lg transition-colors"
                    >
                      Select All
                    </button>
                    <button
                      onClick={clearAll}
                      className="px-3 py-1 text-sm text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                    >
                      Clear All
                    </button>
                  </div>
                </div>
              </div>

              {/* Module List */}
              <div className="space-y-2">
                {filteredModules.length === 0 ? (
                  <div className="text-center py-8 text-gray-500">
                    <svg className="w-16 h-16 mx-auto mb-2 text-gray-300" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M20 13V6a2 2 0 00-2-2H6a2 2 0 00-2 2v7m16 0v5a2 2 0 01-2 2H6a2 2 0 01-2-2v-5m16 0h-2.586a1 1 0 00-.707.293l-2.414 2.414a1 1 0 01-.707.293h-3.172a1 1 0 01-.707-.293l-2.414-2.414A1 1 0 006.586 13H4" />
                    </svg>
                    <p>No apps/modules found</p>
                  </div>
                ) : (
                  filteredModules.map((module) => {
                    const isSelected = selectedModules.includes(module.code);
                    return (
                      <div
                        key={module.id || module.code}
                        onClick={() => toggleModule(module.code)}
                        className={`p-4 border-2 rounded-lg cursor-pointer transition-all ${
                          isSelected
                            ? 'border-purple-500 bg-purple-50'
                            : 'border-gray-200 hover:border-purple-300 bg-white'
                        }`}
                      >
                        <div className="flex items-start gap-3">
                          <div className="flex-shrink-0 mt-1">
                            <div className={`w-5 h-5 rounded border-2 flex items-center justify-center ${
                              isSelected
                                ? 'bg-purple-600 border-purple-600'
                                : 'border-gray-300'
                            }`}>
                              {isSelected && (
                                <svg className="w-3 h-3 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                                </svg>
                              )}
                            </div>
                          </div>
                          <div className="flex-1">
                            <div className="flex items-center justify-between">
                              <h3 className="font-semibold text-gray-900">
                                {module.name || module.code}
                              </h3>
                              <span className="text-xs font-mono text-gray-500 bg-gray-100 px-2 py-1 rounded">
                                {module.code}
                              </span>
                            </div>
                            {module.description && (
                              <p className="text-sm text-gray-600 mt-1">
                                {module.description}
                              </p>
                            )}
                          </div>
                        </div>
                      </div>
                    );
                  })
                )}
              </div>
            </>
          ) : (
            // Step 2: Confirmation
            <div className="space-y-6">
              <div className="bg-yellow-50 border-l-4 border-yellow-400 p-4 rounded">
                <div className="flex items-start">
                  <svg className="w-6 h-6 text-yellow-400 mr-3 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                  <div>
                    <h3 className="text-lg font-semibold text-yellow-800">Confirm Bulk Access Assignment</h3>
                    <p className="text-yellow-700 mt-1">
                      You are about to grant access to the following apps/modules to <strong>ALL {totalUsers} users</strong> in the system.
                    </p>
                  </div>
                </div>
              </div>

              <div className="bg-gray-50 rounded-lg p-4">
                <h4 className="font-semibold text-gray-900 mb-3">Selected Apps/Modules:</h4>
                <div className="space-y-2">
                  {modules
                    .filter(m => selectedModules.includes(m.code))
                    .map(module => (
                      <div key={module.code} className="flex items-center gap-2 bg-white p-3 rounded border border-gray-200">
                        <svg className="w-5 h-5 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                        </svg>
                        <span className="font-medium text-gray-900">{module.name || module.code}</span>
                        <span className="text-xs font-mono text-gray-500 bg-gray-100 px-2 py-1 rounded ml-auto">
                          {module.code}
                        </span>
                      </div>
                    ))}
                </div>
              </div>

              <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                <p className="text-sm text-blue-800">
                  <strong>Note:</strong> This action will grant access to these modules for all users. 
                  Individual user permissions may need to be adjusted separately if needed.
                </p>
              </div>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-gray-200 bg-gray-50 flex items-center justify-between">
          {!confirmationStep ? (
            <>
              <button
                onClick={handleCancel}
                className="px-4 py-2 text-gray-700 hover:bg-gray-200 rounded-lg transition-colors"
                disabled={loading}
              >
                Cancel
              </button>
              <button
                onClick={handleConfirm}
                disabled={selectedModules.length === 0 || loading}
                className="px-6 py-2 bg-gradient-to-r from-purple-600 to-indigo-600 text-white rounded-lg hover:from-purple-700 hover:to-indigo-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                <span>Continue</span>
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7l5 5m0 0l-5 5m5-5H6" />
                </svg>
              </button>
            </>
          ) : (
            <>
              <button
                onClick={handleBack}
                className="px-4 py-2 text-gray-700 hover:bg-gray-200 rounded-lg transition-colors flex items-center gap-2"
                disabled={loading}
              >
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 17l-5-5m0 0l5-5m-5 5h12" />
                </svg>
                <span>Back</span>
              </button>
              <button
                onClick={handleFinalAssign}
                disabled={loading}
                className="px-6 py-2 bg-gradient-to-r from-green-600 to-emerald-600 text-white rounded-lg hover:from-green-700 hover:to-emerald-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
              >
                {loading ? (
                  <>
                    <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    <span>Assigning...</span>
                  </>
                ) : (
                  <>
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                    </svg>
                    <span>Confirm & Assign to All Users</span>
                  </>
                )}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
};

export default AccessToAllModal;

import { radaiConfirm } from '../../services/radaiDialog'
import React, { useState, useEffect } from 'react';
import { toast } from 'react-toastify';
import rbacService from '../../services/rbac.service';
import { 
  DUPLICATE_DETECTION_CONFIG, 
  formatDuplicateData,
  determineUserToKeep 
} from '../../config/duplicateDetection.config';
import { 
  ExclamationTriangleIcon, 
  CheckCircleIcon,
  XMarkIcon,
  TrashIcon,
  UserIcon 
} from '@heroicons/react/24/outline';

/**
 * Duplicate Detection Modal
 * Soft-coded component for detecting and resolving duplicate user accounts
 */
const DuplicateDetectionModal = ({ isOpen, onClose, onResolved }) => {
  const [loading, setLoading] = useState(false);
  const [duplicates, setDuplicates] = useState([]);
  const [selectedDuplicate, setSelectedDuplicate] = useState(null);
  const [selectedUserId, setSelectedUserId] = useState(null);
  const [resolutionStrategy, setResolutionStrategy] = useState(
    DUPLICATE_DETECTION_CONFIG.resolution.default
  );

  const config = DUPLICATE_DETECTION_CONFIG;

  useEffect(() => {
    if (isOpen) {
      checkForDuplicates();
    }
  }, [isOpen]);

  const checkForDuplicates = async () => {
    setLoading(true);
    try {
      const response = await rbacService.checkDuplicateUsers();
      setDuplicates(response.data.duplicates || []);
      
      if (response.data.duplicates?.length > 0) {
        toast.info(
          `Found ${response.data.total_duplicates} duplicate email(s) with ${response.data.total_duplicate_users} total users`,
          { autoClose: 5000 }
        );
      } else {
        toast.success(config.ui.modal.noDataMessage);
      }
    } catch (error) {
      console.error(config.logging.prefix, 'Error checking duplicates:', error);
      toast.error(config.messages.error.checkFailed);
    } finally {
      setLoading(false);
    }
  };

  const handleResolveDuplicate = async (email, keepUserId = null) => {
    if (!keepUserId && resolutionStrategy === config.resolution.strategies.MANUAL_SELECT) {
      toast.error(config.messages.error.noSelection);
      return;
    }

    const confirmed = (await radaiConfirm(config.messages.confirm.resolve));
    if (!confirmed) return;

    setLoading(true);
    try {
      await rbacService.resolveDuplicate(email, keepUserId, resolutionStrategy);
      toast.success(config.messages.success.resolved);
      
      // Refresh duplicates list
      await checkForDuplicates();
      setSelectedDuplicate(null);
      setSelectedUserId(null);
      
      if (onResolved) onResolved();
    } catch (error) {
      console.error(config.logging.prefix, 'Error resolving duplicate:', error);
      toast.error(config.messages.error.resolveFailed);
    } finally {
      setLoading(false);
    }
  };

  const handleSelectUser = (duplicate) => {
    setSelectedDuplicate(duplicate);
    const recommendedUser = determineUserToKeep(duplicate.users, resolutionStrategy);
    setSelectedUserId(recommendedUser?.id || null);
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'Never';
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 z-50 overflow-y-auto">
      <div className="flex items-center justify-center min-h-screen px-4 pt-4 pb-20 text-center sm:block sm:p-0">
        {/* Overlay */}
        <div 
          className="fixed inset-0 transition-opacity bg-gray-500 bg-opacity-75" 
          onClick={onClose}
        ></div>

        {/* Modal */}
        <div className="inline-block w-full max-w-6xl my-8 overflow-hidden text-left align-middle transition-all transform bg-white shadow-2xl rounded-2xl">
          {/* Header */}
          <div className="px-6 py-4 bg-gradient-to-r from-amber-500 to-orange-600">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <ExclamationTriangleIcon className="w-8 h-8 text-white" />
                <h3 className="text-2xl font-bold text-white">
                  {config.ui.modal.title}
                </h3>
              </div>
              <button
                onClick={onClose}
                className="p-1 text-white transition-colors rounded-full hover:bg-white hover:bg-opacity-20"
              >
                <XMarkIcon className="w-6 h-6" />
              </button>
            </div>
            <p className="mt-2 text-sm text-white text-opacity-90">
              {config.ui.modal.description}
            </p>
          </div>

          {/* Content */}
          <div className="p-6">
            {loading && !duplicates.length ? (
              <div className="flex items-center justify-center py-12">
                <div className="animate-spin rounded-full h-12 w-12 border-4 border-blue-500 border-t-transparent"></div>
              </div>
            ) : duplicates.length === 0 ? (
              <div className="py-12 text-center">
                <CheckCircleIcon className="w-16 h-16 mx-auto text-green-500 mb-4" />
                <p className="text-xl font-semibold text-gray-700">
                  {config.ui.modal.noDataMessage}
                </p>
              </div>
            ) : (
              <div className="space-y-6">
                {/* Strategy Selector */}
                <div className="p-4 bg-blue-50 rounded-lg border border-blue-200">
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Resolution Strategy:
                  </label>
                  <select
                    value={resolutionStrategy}
                    onChange={(e) => setResolutionStrategy(e.target.value)}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                  >
                    {Object.entries(config.resolution.strategies).map(([key, value]) => (
                      <option key={value} value={value}>
                        {config.resolution.descriptions[key]}
                      </option>
                    ))}
                  </select>
                </div>

                {/* Duplicates List */}
                <div className="space-y-4">
                  {duplicates.map((duplicate, index) => {
                    const formattedDup = formatDuplicateData(duplicate);
                    const isSelected = selectedDuplicate?.email === duplicate.email;

                    return (
                      <div 
                        key={index} 
                        className="border-2 border-gray-200 rounded-xl overflow-hidden hover:shadow-lg transition-shadow"
                      >
                        {/* Duplicate Header */}
                        <div className={`px-4 py-3 bg-gradient-to-r ${
                          formattedDup.severity === 'danger' ? 'from-red-50 to-red-100' :
                          formattedDup.severity === 'warning' ? 'from-amber-50 to-amber-100' :
                          'from-blue-50 to-blue-100'
                        }`}>
                          <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                              <span className="text-2xl">
                                {config.ui.icons[formattedDup.severity]}
                              </span>
                              <div>
                                <h4 className="text-lg font-bold text-gray-900">
                                  {duplicate.email}
                                </h4>
                                <p className="text-sm text-gray-600">
                                  {duplicate.count} duplicate accounts found
                                </p>
                              </div>
                            </div>
                            <button
                              onClick={() => handleSelectUser(duplicate)}
                              className="px-4 py-2 bg-white text-blue-600 font-semibold rounded-lg hover:bg-blue-50 transition-colors border border-blue-200"
                            >
                              {isSelected ? 'Selected' : 'Select to Resolve'}
                            </button>
                          </div>
                        </div>

                        {/* User Details (when selected) */}
                        {isSelected && (
                          <div className="p-4 bg-white">
                            <div className="grid grid-cols-1 gap-4">
                              {duplicate.users.map((user) => (
                                <div
                                  key={user.id}
                                  className={`p-4 border-2 rounded-lg transition-all ${
                                    selectedUserId === user.id
                                      ? 'border-green-500 bg-green-50'
                                      : 'border-gray-200 hover:border-blue-300'
                                  }`}
                                >
                                  <div className="flex items-start justify-between">
                                    <div className="flex-1">
                                      <div className="flex items-center gap-3 mb-2">
                                        <UserIcon className="w-6 h-6 text-gray-400" />
                                        <div>
                                          <h5 className="font-semibold text-gray-900">
                                            {user.first_name} {user.last_name}
                                          </h5>
                                          <p className="text-sm text-gray-500">
                                            ID: {user.id} | {user.username}
                                          </p>
                                        </div>
                                      </div>
                                      
                                      <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-sm">
                                        <div>
                                          <span className="text-gray-500">Status:</span>
                                          <span className={`ml-2 font-semibold ${
                                            user.is_active ? 'text-green-600' : 'text-red-600'
                                          }`}>
                                            {user.is_active ? 'Active' : 'Inactive'}
                                          </span>
                                        </div>
                                        <div>
                                          <span className="text-gray-500">Created:</span>
                                          <span className="ml-2 font-semibold text-gray-700">
                                            {formatDate(user.date_joined)}
                                          </span>
                                        </div>
                                        <div>
                                          <span className="text-gray-500">Last Login:</span>
                                          <span className="ml-2 font-semibold text-gray-700">
                                            {formatDate(user.last_login)}
                                          </span>
                                        </div>
                                        <div>
                                          <span className="text-gray-500">Modules:</span>
                                          <span className="ml-2 font-semibold text-gray-700">
                                            {user.module_count || 0}
                                          </span>
                                        </div>
                                      </div>

                                      {user.department && (
                                        <div className="mt-2 text-sm">
                                          <span className="text-gray-500">Department:</span>
                                          <span className="ml-2 text-gray-700">{user.department}</span>
                                        </div>
                                      )}
                                    </div>

                                    <div className="flex flex-col gap-2 ml-4">
                                      {selectedUserId === user.id ? (
                                        <span className="px-3 py-1 text-xs font-bold text-green-700 bg-green-100 rounded-full">
                                          ✓ Keeping
                                        </span>
                                      ) : (
                                        <button
                                          onClick={() => setSelectedUserId(user.id)}
                                          className="px-3 py-1 text-xs font-semibold text-blue-600 bg-blue-100 rounded-full hover:bg-blue-200 transition-colors"
                                        >
                                          Select
                                        </button>
                                      )}
                                    </div>
                                  </div>
                                </div>
                              ))}
                            </div>

                            {/* Action Buttons */}
                            <div className="flex gap-3 mt-4">
                              <button
                                onClick={() => handleResolveDuplicate(duplicate.email, selectedUserId)}
                                disabled={loading || !selectedUserId}
                                className="flex-1 px-6 py-3 bg-gradient-to-r from-green-500 to-emerald-600 text-white font-semibold rounded-lg hover:from-green-600 hover:to-emerald-700 transition-all disabled:opacity-50 disabled:cursor-not-allowed"
                              >
                                {loading ? 'Processing...' : 'Resolve Duplicate'}
                              </button>
                              <button
                                onClick={() => {
                                  setSelectedDuplicate(null);
                                  setSelectedUserId(null);
                                }}
                                className="px-6 py-3 bg-gray-200 text-gray-700 font-semibold rounded-lg hover:bg-gray-300 transition-colors"
                              >
                                Cancel
                              </button>
                            </div>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>

          {/* Footer */}
          <div className="px-6 py-4 bg-gray-50 border-t border-gray-200">
            <div className="flex justify-between items-center">
              <button
                onClick={checkForDuplicates}
                disabled={loading}
                className="px-4 py-2 text-blue-600 font-semibold hover:text-blue-700 disabled:opacity-50"
              >
                🔄 Refresh
              </button>
              <button
                onClick={onClose}
                className="px-6 py-2 bg-gray-600 text-white font-semibold rounded-lg hover:bg-gray-700 transition-colors"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default DuplicateDetectionModal;

import { radaiConfirm } from '../../services/radaiDialog'
import React, { useState, useEffect, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { fetchDepartments, fetchJobTitles } from '../../store/slices/rbacSlice';
import { EDIT_USER_CONFIG, initializeFormData, validateField, hasChanges } from '../../config/editUser.config';
import { groupModulesByCategory, MODULE_CATEGORIES_CONFIG } from '../../config/moduleCategories.config';
import {
  ALLOW_PER_USER_MODULE_ASSIGNMENT,
  ACCESS_NOTICE,
  SENSITIVE_MODULE_CODES,
  isSensitiveModule,
} from '../../config/rbacAccess.config';

/**
 * Read-only panel showing the modules a user inherits from their assigned
 * roles. Rendered inside EditUserModal when ALLOW_PER_USER_MODULE_ASSIGNMENT
 * is false (the default). Replaces the legacy editable module checkboxes.
 */
const InheritedModulesReadOnly = ({ user, modules }) => {
  // Build a lookup: module code -> module row (for name/description).
  const moduleByCode = useMemo(() => {
    const m = new Map();
    (Array.isArray(modules) ? modules : []).forEach((mod) => {
      if (mod?.code) m.set(mod.code, mod);
    });
    return m;
  }, [modules]);

  // Normalize accessible_modules into a list of codes (accepts strings or objects).
  const codes = useMemo(() => {
    const list = Array.isArray(user?.accessible_modules) ? user.accessible_modules : [];
    return list
      .map((entry) => (typeof entry === 'string' ? entry : entry?.code))
      .filter(Boolean);
  }, [user]);

  const roleLabels = useMemo(() => {
    const roles = Array.isArray(user?.roles) ? user.roles : [];
    return roles.map((r) => r?.name || r?.code).filter(Boolean);
  }, [user]);

  return (
    <div className="rounded-xl border border-gray-200 bg-gradient-to-br from-white to-blue-50/40 p-5">
      <div className="flex items-center justify-between mb-3">
        <div>
          <h4 className="text-sm font-bold text-gray-900 flex items-center gap-2">
            <span className="text-lg">🛡️</span>
            Modules (inherited from Roles)
          </h4>
          <p className="text-xs text-gray-600 mt-0.5">{ACCESS_NOTICE.BODY}</p>
        </div>
        <span className="shrink-0 text-xs font-semibold px-3 py-1 rounded-full bg-blue-100 text-blue-800">
          {codes.length} module{codes.length === 1 ? '' : 's'}
        </span>
      </div>

      {roleLabels.length > 0 && (
        <p className="text-xs text-gray-500 mb-3">
          via {roleLabels.join(', ')}
        </p>
      )}

      {codes.length === 0 ? (
        <p className="text-sm text-gray-500 italic">
          No modules granted. Assign a role to give this user access.
        </p>
      ) : (
        <div className="flex flex-wrap gap-2">
          {codes.map((code) => {
            const mod = moduleByCode.get(code);
            const label = mod?.name || code;
            const sensitive = isSensitiveModule(code);
            return (
              <span
                key={code}
                title={mod?.description || label}
                className={
                  sensitive
                    ? 'inline-flex items-center gap-1 text-xs font-medium px-2.5 py-1 rounded-full border border-amber-300 bg-amber-50 text-amber-900'
                    : 'inline-flex items-center gap-1 text-xs font-medium px-2.5 py-1 rounded-full border border-gray-200 bg-white text-gray-700'
                }
              >
                {sensitive && <span aria-hidden>🔒</span>}
                {label}
              </span>
            );
          })}
        </div>
      )}
    </div>
  );
};

/**
 * Comprehensive Edit User Modal
 * Feature-rich, soft-coded user editing interface
 * Supports all user attributes, roles, modules, and advanced features
 */
const EditUserModal = ({
  isOpen,
  onClose,
  user,
  onSave,
  organizations = [],
  modules = [],
  roles = [],
  loading = false,
  currentUser = null
}) => {
  const dispatch = useDispatch();
  const { departments, jobTitles } = useSelector((state) => state.rbac);
  const [formData, setFormData] = useState({});
  const [originalData, setOriginalData] = useState({});
  const [errors, setErrors] = useState({});
  const [expandedSections, setExpandedSections] = useState({});
  const [showUnsavedWarning, setShowUnsavedWarning] = useState(false);
  const [moduleSearch, setModuleSearch] = useState('');

  // Fetch departments and job titles on mount
  useEffect(() => {
    dispatch(fetchDepartments());
    dispatch(fetchJobTitles());
  }, [dispatch]);

  // Initialize form data when user changes
  useEffect(() => {
    if (user) {
      const initialData = initializeFormData(user);
      setFormData(initialData);
      setOriginalData(initialData);
      
      // Initialize expanded sections (collapse only collapsible ones)
      const initialExpanded = {};
      EDIT_USER_CONFIG.sections.forEach(section => {
        initialExpanded[section.id] = !section.collapsed;
      });
      setExpandedSections(initialExpanded);
    }
  }, [user]);

  // Check for unsaved changes
  const hasUnsavedChanges = useMemo(() => {
    return hasChanges(originalData, formData);
  }, [originalData, formData]);

  // Handle field change
  const handleFieldChange = (fieldName, value) => {
    setFormData(prev => ({
      ...prev,
      [fieldName]: value
    }));

    // Clear error for this field
    if (errors[fieldName]) {
      setErrors(prev => {
        const newErrors = { ...prev };
        delete newErrors[fieldName];
        return newErrors;
      });
    }
  };

  // Handle module toggle
  const handleModuleToggle = (moduleId) => {
    setFormData(prev => ({
      ...prev,
      module_ids: prev.module_ids?.includes(moduleId)
        ? prev.module_ids.filter(id => id !== moduleId)
        : [...(prev.module_ids || []), moduleId]
    }));
  };

  // Handle role toggle
  const handleRoleToggle = (roleId) => {
    setFormData(prev => ({
      ...prev,
      role_ids: prev.role_ids?.includes(roleId)
        ? prev.role_ids.filter(id => id !== roleId)
        : [...(prev.role_ids || []), roleId]
    }));
  };

  // Validate form
  const validateForm = () => {
    const newErrors = {};

    EDIT_USER_CONFIG.sections.forEach(section => {
      section.fields.forEach(field => {
        const error = validateField(field, formData[field.name]);
        if (error) {
          newErrors[field.name] = error;
        }
      });
    });

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  // Handle submit
  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) {
      return;
    }

    if (EDIT_USER_CONFIG.behavior.confirmBeforeSave) {
      if (!(await radaiConfirm(EDIT_USER_CONFIG.messages.confirmation.save))) {
        return;
      }
    }

    // Defensive UUID normalization — backend PrimaryKeyRelatedField rejects
    // role/module objects. Keep this even though initializeFormData normalizes,
    // in case any code path pushes an object into the array.
    const normalizeIds = (arr) =>
      Array.isArray(arr)
        ? arr.map((item) => (typeof item === 'object' && item ? item.id : item)).filter(Boolean)
        : [];

    const cleanFormData = {
      ...formData,
      role_ids: normalizeIds(formData.role_ids),
      module_ids: normalizeIds(formData.module_ids),
    };

    // Access is role-based: strip module_ids unless the flag is on.
    const { module_ids, ...roleOnlyPayload } = cleanFormData;
    const payload = ALLOW_PER_USER_MODULE_ASSIGNMENT ? cleanFormData : roleOnlyPayload;
    await onSave(payload);

    if (EDIT_USER_CONFIG.behavior.closeOnSuccess) {
      handleClose();
    }
  };

  // Handle close with unsaved changes warning
  const handleClose = async () => {
    if (hasUnsavedChanges && EDIT_USER_CONFIG.behavior.showUnsavedWarning) {
      if (!(await radaiConfirm('You have unsaved changes. Are you sure you want to close?'))) {
        return;
      }
    }
    onClose();
  };

  // Handle section toggle
  const toggleSection = (sectionId) => {
    setExpandedSections(prev => ({
      ...prev,
      [sectionId]: !prev[sectionId]
    }));
  };

  // Select all modules
  const handleSelectAllModules = () => {
    setFormData(prev => ({
      ...prev,
      module_ids: modules.map(m => m.id)
    }));
  };

  // Clear all modules
  const handleClearAllModules = () => {
    setFormData(prev => ({
      ...prev,
      module_ids: []
    }));
  };

  // Filter modules based on search
  const filteredModules = useMemo(() => {
    if (!moduleSearch) return modules;
    const search = moduleSearch.toLowerCase();
    return modules.filter(module =>
      module.name?.toLowerCase().includes(search) ||
      module.description?.toLowerCase().includes(search)
    );
  }, [modules, moduleSearch]);

  // Sections shown in the modal. Only per-user module access is hidden
  // (that always inherits from roles). Role assignment is shown so admins
  // can pick/replace roles directly here; the source list of roles is
  // managed at Admin › Roles & Access Management.
  const visibleSections = useMemo(() => {
    const hidden = new Set(['module_access']);
    return EDIT_USER_CONFIG.sections.filter((s) => !hidden.has(s.id));
  }, []);

  // Render field based on type
  const renderField = (field) => {
    const value = formData[field.name] || '';
    const error = errors[field.name];

    switch (field.type) {
      case 'text':
      case 'email':
      case 'tel':
        return (
          <div key={field.name} className={`${field.gridCols || 'col-span-2'}`}>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              {field.label}
              {field.required && <span className="text-red-500 ml-1">*</span>}
            </label>
            <input
              type={field.type}
              value={value}
              onChange={(e) => handleFieldChange(field.name, e.target.value)}
              placeholder={field.placeholder}
              disabled={field.disabled}
              required={field.required}
              className={`w-full px-4 py-2.5 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all ${
                field.disabled 
                  ? 'bg-gray-100 text-gray-600 cursor-not-allowed' 
                  : 'bg-white text-gray-900'
              } ${
                error ? 'border-red-500' : 'border-gray-300'
              }`}
            />
            {field.helpText && !error && (
              <p className="text-xs text-gray-500 mt-1">{field.helpText}</p>
            )}
            {error && (
              <p className="text-xs text-red-600 mt-1 flex items-center">
                <svg className="w-4 h-4 mr-1" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                </svg>
                {error}
              </p>
            )}
          </div>
        );

      case 'select':
        // Determine options based on field name
        let selectOptions = [];
        if (field.name === 'organization_id') {
          selectOptions = organizations;
        } else if (field.name === 'department') {
          selectOptions = departments.map(dept => ({ id: dept, name: dept }));
        } else if (field.name === 'job_title') {
          selectOptions = jobTitles.map(title => ({ id: title, name: title }));
        } else {
          selectOptions = field.options || [];
        }
        // Preserve a recorded value if it is absent from the latest catalog.
        if (['department', 'job_title'].includes(field.name) && value && !selectOptions.some(option => option.id === value)) {
          selectOptions = [{ id: value, name: value }, ...selectOptions];
        }

        return (
          <div key={field.name} className={`${field.gridCols || 'col-span-2'}`}>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              {field.label}
              {field.required && <span className="text-red-500 ml-1">*</span>}
            </label>
            <select
              value={value}
              onChange={(e) => handleFieldChange(field.name, e.target.value)}
              required={field.required}
              className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-blue-500 bg-white text-gray-900"
            >
              <option value="">{field.placeholder || 'Select...'}</option>
              {selectOptions.map((option) => (
                <option key={option.id || option.name} value={option.id || option.name}>
                  {option.name}
                </option>
              ))}
            </select>
            {field.helpText && (
              <p className="text-xs text-gray-500 mt-1">{field.helpText}</p>
            )}
          </div>
        );

      case 'badge':
        const statusConfig = EDIT_USER_CONFIG.statusColors[value] || EDIT_USER_CONFIG.statusColors.active;
        return (
          <div key={field.name} className={`${field.gridCols || 'col-span-1'}`}>
            <label className="block text-sm font-medium text-gray-700 mb-2">{field.label}</label>
            <div className={`inline-flex items-center px-3 py-1.5 rounded-full text-sm font-medium border ${statusConfig.bg} ${statusConfig.text} ${statusConfig.border}`}>
              {value.charAt(0).toUpperCase() + value.slice(1)}
            </div>
          </div>
        );

      case 'date-display':
        const displayDate = value ? new Date(value).toLocaleDateString('en-US', {
          year: 'numeric',
          month: 'long',
          day: 'numeric',
          hour: '2-digit',
          minute: '2-digit'
        }) : 'Never';
        return (
          <div key={field.name} className={`${field.gridCols || 'col-span-1'}`}>
            <label className="block text-sm font-medium text-gray-700 mb-2">{field.label}</label>
            <div className="text-gray-900 font-medium">{displayDate}</div>
          </div>
        );

      case 'number-display':
        return (
          <div key={field.name} className={`${field.gridCols || 'col-span-1'}`}>
            <label className="block text-sm font-medium text-gray-700 mb-2">{field.label}</label>
            <div className="text-2xl font-bold text-blue-600">{value || 0}</div>
          </div>
        );

      case 'toggle':
        return (
          <div key={field.name} className={`${field.gridCols || 'col-span-1'}`}>
            <label className="flex items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-200 hover:bg-gray-100 cursor-pointer transition-colors">
              <div className="flex-1">
                <div className="text-sm font-medium text-gray-900">{field.label}</div>
                {field.helpText && (
                  <div className="text-xs text-gray-600 mt-1">{field.helpText}</div>
                )}
              </div>
              <div className="relative inline-block w-12 h-6 ml-4">
                <input
                  type="checkbox"
                  checked={value || false}
                  onChange={async (e) => {
                    if (field.requireConfirmation) {
                      if ((await radaiConfirm(field.confirmMessage))) {
                        handleFieldChange(field.name, e.target.checked);
                      }
                    } else {
                      handleFieldChange(field.name, e.target.checked);
                    }
                  }}
                  className="sr-only peer"
                />
                <div className={`block w-12 h-6 rounded-full transition-colors ${
                  value ? 'bg-blue-600' : 'bg-gray-300'
                }`}></div>
                <div className={`absolute left-1 top-1 w-4 h-4 bg-white rounded-full transition-transform ${
                  value ? 'transform translate-x-6' : ''
                }`}></div>
              </div>
            </label>
          </div>
        );

      case 'checkbox-group':
        // Use centralized category configuration
        const groupedModules = groupModulesByCategory(modules);
        
        // Filter modules by search term if provided
        const filteredGroupedModules = {};
        Object.entries(groupedModules).forEach(([categoryId, categoryData]) => {
          const filteredModules = categoryData.modules.filter(module =>
            !moduleSearch || 
            module.name.toLowerCase().includes(moduleSearch.toLowerCase()) ||
            module.description?.toLowerCase().includes(moduleSearch.toLowerCase()) ||
            module.code?.toLowerCase().includes(moduleSearch.toLowerCase())
          );
          
          if (filteredModules.length > 0) {
            filteredGroupedModules[categoryId] = {
              ...categoryData,
              modules: filteredModules
            };
          }
        });
        
        return (
          <div key={field.name} className={`${field.gridCols || 'col-span-2'}`}>
            <div className="flex items-center justify-between mb-4">
              <label className="block text-sm font-medium text-gray-700">
                {field.label}
                {field.required && <span className="text-red-500 ml-1">*</span>}
              </label>
              {field.showSelectAll && MODULE_CATEGORIES_CONFIG.features.enableQuickActions && (
                <div className="flex gap-3">
                  <button
                    type="button"
                    onClick={handleSelectAllModules}
                    className="text-xs bg-blue-100 text-blue-700 hover:bg-blue-200 px-3 py-1.5 rounded-md font-medium transition-colors"
                  >
                    ✓ Select All
                  </button>
                  <button
                    type="button"
                    onClick={handleClearAllModules}
                    className="text-xs bg-gray-100 text-gray-700 hover:bg-gray-200 px-3 py-1.5 rounded-md font-medium transition-colors"
                  >
                    ✕ Clear All
                  </button>
                </div>
              )}
            </div>

            {/* Selected Count Badge */}
            {formData.module_ids?.length > 0 && (
              <div className="mb-4 p-3 bg-gradient-to-r from-blue-50 to-indigo-50 border-l-4 border-blue-500 rounded-lg">
                <div className="flex items-center justify-between">
                  <p className="text-sm font-semibold text-blue-900">
                    <span className="inline-flex items-center justify-center w-6 h-6 bg-blue-600 text-white rounded-full text-xs mr-2">
                      {formData.module_ids.length}
                    </span>
                    Module{formData.module_ids.length !== 1 ? 's' : ''} Selected
                  </p>
                  <span className="text-xs text-blue-700">
                    of {modules.length} total
                  </span>
                </div>
              </div>
            )}

            {/* Search Bar */}
            {field.showSearch && MODULE_CATEGORIES_CONFIG.features.enableSearch && modules.length > 3 && (
              <div className="mb-4">
                <div className="relative">
                  <input
                    type="text"
                    value={moduleSearch}
                    onChange={(e) => setModuleSearch(e.target.value)}
                    placeholder="🔍 Search modules by name, code, or category..."
                    className="w-full pl-4 pr-10 py-2.5 border-2 border-gray-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
                  />
                  {moduleSearch && (
                    <button
                      type="button"
                      onClick={() => setModuleSearch('')}
                      className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
                    >
                      ✕
                    </button>
                  )}
                </div>
              </div>
            )}

            {/* Categorized Modules */}
            <div className="space-y-4 max-h-[500px] overflow-y-auto border-2 border-gray-200 rounded-xl p-4 bg-white">
              {field.showCategoryGroups && Object.keys(filteredGroupedModules).length > 0 ? (
                Object.entries(filteredGroupedModules).map(([categoryId, categoryData]) => {
                  const { config, modules: categoryModules } = categoryData;
                  
                  const selectedInCategory = categoryModules.filter(m => 
                    formData.module_ids?.includes(m.id)
                  ).length;

                  return (
                    <div key={categoryId} className="border-b border-gray-200 last:border-0 pb-4 last:pb-0">
                      {/* Category Header */}
                      <div className={`flex items-center justify-between mb-3 ${config.bgColor} px-3 py-2.5 rounded-lg border ${config.borderColor}`}>
                        <div className="flex items-center gap-2">
                          {MODULE_CATEGORIES_CONFIG.display.showIcons && (
                            <span className="text-lg">{config.icon}</span>
                          )}
                          <h4 className={`text-sm font-bold ${config.textColor} uppercase tracking-wider`}>
                            {config.name}
                          </h4>
                          {MODULE_CATEGORIES_CONFIG.display.showDescriptions && (
                            <span className="hidden lg:inline text-xs text-gray-600 ml-2 font-normal normal-case">
                              {config.description}
                            </span>
                          )}
                        </div>
                        <span className={`text-xs ${config.badgeColor} ${config.textColor} px-2 py-1 rounded-full font-medium`}>
                          {selectedInCategory}/{categoryModules.length}
                        </span>
                      </div>

                      {/* Modules in Category */}
                      <div className="grid grid-cols-1 md:grid-cols-2 gap-2 ml-2">
                        {categoryModules.map((module) => {
                          const isSelected = formData.module_ids?.includes(module.id);
                          return (
                            <label
                              key={module.id}
                              className={`flex items-start p-3 border-2 rounded-lg cursor-pointer transition-all hover:shadow-md ${
                                isSelected
                                  ? `${config.borderColor} ${config.bgColor} shadow-sm`
                                  : 'border-gray-200 bg-white hover:border-blue-300'
                              }`}
                            >
                              <input
                                type="checkbox"
                                checked={isSelected}
                                onChange={() => handleModuleToggle(module.id)}
                                className="mt-1 w-5 h-5 text-blue-600 rounded focus:ring-2 focus:ring-blue-500 cursor-pointer"
                              />
                              <div className="ml-3 flex-1">
                                <div className="font-semibold text-gray-900 text-sm">
                                  {module.name}
                                </div>
                                {EDIT_USER_CONFIG.moduleDisplay.showDescription && module.description && (
                                  <div className="text-xs text-gray-600 mt-1 line-clamp-2">
                                    {module.description}
                                  </div>
                                )}
                                {MODULE_CATEGORIES_CONFIG.features.showModuleCodes && module.code && (
                                  <div className="text-xs text-gray-400 mt-1 font-mono">
                                    {module.code}
                                  </div>
                                )}
                              </div>
                            </label>
                          );
                        })}
                      </div>
                    </div>
                  );
                })
              ) : (
                /* No modules found */
                <div className="text-center py-8 text-gray-500">
                  <div className="text-4xl mb-2">🔍</div>
                  <div className="font-medium">
                    {moduleSearch ? 'No modules found matching your search' : 'No modules available'}
                  </div>
                  {moduleSearch && (
                    <button
                      type="button"
                      onClick={() => setModuleSearch('')}
                      className="mt-3 text-sm text-blue-600 hover:text-blue-800 underline"
                    >
                      Clear search
                    </button>
                  )}
                </div>
              )}
            </div>

            {field.helpText && (
              <p className="text-xs text-gray-600 mt-3 flex items-start">
                <svg className="w-4 h-4 mr-1 mt-0.5 text-blue-500" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                </svg>
                {field.helpText}
              </p>
            )}
          </div>
        );

      case 'role-selector':
        return (
          <div key={field.name} className={`${field.gridCols || 'col-span-2'}`}>
            <div className="flex items-center justify-between mb-4">
              <label className="block text-sm font-medium text-gray-700">
                {field.label}
                {field.required && <span className="text-red-500 ml-1">*</span>}
              </label>
            </div>

            {/* Selected Roles Summary */}
            {formData.role_ids?.length > 0 && (
              <div className="mb-4 p-3 bg-gradient-to-r from-purple-50 to-pink-50 border-l-4 border-purple-500 rounded-lg">
                <div className="flex items-center justify-between">
                  <p className="text-sm font-semibold text-purple-900">
                    <span className="inline-flex items-center justify-center w-6 h-6 bg-purple-600 text-white rounded-full text-xs mr-2">
                      {formData.role_ids.length}
                    </span>
                    Role{formData.role_ids.length !== 1 ? 's' : ''} Assigned
                  </p>
                  <span className="text-xs text-purple-700">
                    {roles.filter(r => formData.role_ids.includes(r.id)).map(r => r.name).join(', ')}
                  </span>
                </div>
              </div>
            )}

            {/* Roles Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3 max-h-96 overflow-y-auto border-2 border-gray-200 rounded-xl p-4 bg-white">
              {roles.length > 0 ? (
                roles.map((role) => {
                  const isSelected = formData.role_ids?.includes(role.id);
                  const isAdmin = role.name?.toLowerCase().includes('admin');
                  const isSuperAdmin = role.name?.toLowerCase().includes('super');
                  
                  // Choose icon based on role type
                  const roleIcon = isSuperAdmin ? '👑' : isAdmin ? '🛡️' : '👤';

                  return (
                    <label
                      key={role.id}
                      className={`flex items-start p-4 border-2 rounded-xl cursor-pointer transition-all hover:shadow-lg ${
                        isSelected
                          ? isAdmin && EDIT_USER_CONFIG.roleDisplay.highlightAdmin
                            ? 'border-purple-500 bg-gradient-to-br from-purple-50 to-pink-50 shadow-md'
                            : 'border-blue-500 bg-blue-50 shadow-md'
                          : 'border-gray-200 bg-white hover:border-blue-300 hover:bg-blue-25'
                      }`}
                    >
                      <input
                        type="checkbox"
                        checked={isSelected}
                        onChange={() => handleRoleToggle(role.id)}
                        className="mt-1 w-5 h-5 text-blue-600 rounded focus:ring-2 focus:ring-blue-500 cursor-pointer"
                      />
                      <div className="ml-3 flex-1">
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            <span className="text-xl">{roleIcon}</span>
                            <div className="font-bold text-gray-900">{role.name}</div>
                          </div>
                          {EDIT_USER_CONFIG.roleDisplay.showPermissionCount && role.permissions?.length > 0 && (
                            <span className="text-xs bg-blue-100 text-blue-700 px-2.5 py-1 rounded-full font-semibold">
                              {role.permissions.length} perms
                            </span>
                          )}
                        </div>
                        {EDIT_USER_CONFIG.roleDisplay.showDescription && role.description && (
                          <div className="text-xs text-gray-600 mt-2 line-clamp-2">
                            {role.description}
                          </div>
                        )}
                        {isAdmin && (
                          <div className="mt-2 inline-flex items-center text-xs font-semibold text-purple-700 bg-purple-100 px-2 py-1 rounded-md">
                            ⚡ Elevated Access
                          </div>
                        )}
                      </div>
                    </label>
                  );
                })
              ) : (
                <div className="col-span-2 text-center py-8 text-gray-500 bg-gray-50 rounded-xl">
                  <div className="text-4xl mb-2">🔒</div>
                  <div className="font-medium">No roles available</div>
                </div>
              )}
            </div>

            {field.helpText && (
              <p className="text-xs text-gray-600 mt-3 flex items-start">
                <svg className="w-4 h-4 mr-1 mt-0.5 text-purple-500" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                </svg>
                {field.helpText}
              </p>
            )}
          </div>
        );

      default:
        return null;
    }
  };

  // Render section
  const renderSection = (section) => {
    
    const isExpanded = expandedSections[section.id];
    const isCollapsible = section.collapsible;

    return (
      <div key={section.id} className="border-b border-gray-200 pb-6 last:border-b-0">
        <div
          className={`flex items-center justify-between mb-4 ${isCollapsible ? 'cursor-pointer' : ''}`}
          onClick={() => isCollapsible && toggleSection(section.id)}
        >
          <div className="flex items-center gap-3">
            <div className="p-2 bg-blue-100 rounded-lg">
              <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={section.icon} />
              </svg>
            </div>
            <div>
              <h3 className="text-lg font-semibold text-gray-900">{section.title}</h3>
              {section.description && (
                <p className="text-sm text-gray-600">{section.description}</p>
              )}
            </div>
          </div>
          {isCollapsible && (
            <svg
              className={`w-5 h-5 text-gray-500 transition-transform ${isExpanded ? 'transform rotate-180' : ''}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
            </svg>
          )}
        </div>

        {isExpanded && (
          <div className={`grid grid-cols-1 md:grid-cols-2 gap-4 ${section.readOnly ? 'bg-gray-50 p-4 rounded-lg' : ''}`}>
            {section.fields.map(renderField)}
          </div>
        )}
      </div>
    );
  };

  if (!isOpen || !user) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className={`bg-white rounded-xl shadow-2xl ${EDIT_USER_CONFIG.modal.maxWidth} w-full ${EDIT_USER_CONFIG.modal.maxHeight} overflow-hidden flex flex-col`}>
        {/* Header */}
        <div className="px-6 py-4 border-b border-gray-200 bg-gradient-to-r from-blue-600 to-indigo-600">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div className="p-2 bg-white bg-opacity-20 rounded-lg">
                <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M11 5H6a2 2 0 00-2 2v11a2 2 0 002 2h11a2 2 0 002-2v-5m-1.414-9.414a2 2 0 112.828 2.828L11.828 15H9v-2.828l8.586-8.586z" />
                </svg>
              </div>
              <div>
                <h2 className="text-2xl font-bold text-white">{EDIT_USER_CONFIG.modal.title}</h2>
                <p className="text-blue-100 text-sm">
                  Editing: {formData.first_name} {formData.last_name} ({formData.email})
                </p>
              </div>
            </div>
            <button
              onClick={handleClose}
              className="text-white hover:text-gray-200 transition-colors p-2 hover:bg-white hover:bg-opacity-20 rounded-lg"
            >
              <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>
        </div>

        {/* Form Content */}
        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto">
          <div className="p-6 space-y-6">
            {visibleSections.map(renderSection)}
          </div>

          {/* Footer */}
          <div className="px-6 py-4 border-t border-gray-200 bg-gray-50 flex items-center justify-between">
            <div className="flex items-center gap-2">
              {hasUnsavedChanges && EDIT_USER_CONFIG.behavior.highlightChanges && (
                <div className="flex items-center gap-2 text-orange-600">
                  <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                  </svg>
                  <span className="text-sm font-medium">Unsaved changes</span>
                </div>
              )}
            </div>

            <div className="flex gap-3">
              <button
                type="button"
                onClick={handleClose}
                disabled={loading}
                className={EDIT_USER_CONFIG.buttons.cancel.className}
              >
                {EDIT_USER_CONFIG.buttons.cancel.label}
              </button>

              <button
                type="submit"
                disabled={loading || !hasUnsavedChanges}
                className={`${EDIT_USER_CONFIG.buttons.save.className} ${
                  !hasUnsavedChanges ? 'opacity-50 cursor-not-allowed' : ''
                } flex items-center gap-2`}
              >
                {loading ? (
                  <>
                    <svg className="animate-spin h-5 w-5" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                    <span>{EDIT_USER_CONFIG.buttons.save.loadingLabel}</span>
                  </>
                ) : (
                  <>
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={EDIT_USER_CONFIG.buttons.save.icon} />
                    </svg>
                    <span>{EDIT_USER_CONFIG.buttons.save.label}</span>
                  </>
                )}
              </button>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

export default EditUserModal;

/**
 * InheritedModulesPopover
 *
 * Read-only display of the modules a user gets from their assigned roles.
 * The user's access is *derived* from their roles \u2014 there is no per-user
 * module store. To change what a user can access, change their roles
 * (this component links to /admin/roles for role configuration).
 *
 * The backend already returns the union in `user.accessible_modules`, but
 * we render the source role on each chip so admins can trace where the
 * access comes from.
 *
 * Props:
 *   user         : UserProfile object  (contains roles[] and accessible_modules)
 *   modulesIndex : Map<code, moduleObj> \u2014 optional lookup for display names
 */
import React, { useState, useRef, useEffect } from 'react';
import {
  MODULES_POPOVER_COPY,
  SENSITIVE_MODULE_CODES,
  ACCESS_NOTICE,
} from '../../config/rbacAccess.config';

function InheritedModulesPopover({ user, modulesIndex = new Map() }) {
  const [open, setOpen] = useState(false);
  const triggerRef = useRef(null);
  const popoverRef = useRef(null);

  const accessibleModules = Array.isArray(user?.accessible_modules) ? user.accessible_modules : [];
  const count = accessibleModules.length;

  useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (
        popoverRef.current && !popoverRef.current.contains(e.target) &&
        triggerRef.current && !triggerRef.current.contains(e.target)
      ) {
        setOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  // The backend returns accessible_modules as an array of codes (strings).
  // Look up the display name; fall back to code if the modules catalog isn't loaded.
  const chips = accessibleModules.map((codeOrObj) => {
    const code = typeof codeOrObj === 'string' ? codeOrObj : codeOrObj?.code;
    const mod = modulesIndex.get(code);
    return {
      code,
      name: mod?.name || code,
      sensitive: SENSITIVE_MODULE_CODES.includes(code),
    };
  });

  const roles = Array.isArray(user?.roles) ? user.roles : [];

  return (
    <div className="relative inline-block">
      <button
        ref={triggerRef}
        type="button"
        onClick={() => setOpen((v) => !v)}
        className="text-sm text-blue-600 hover:text-blue-800 hover:underline font-medium focus:outline-none"
        title={MODULES_POPOVER_COPY.HEADER}
      >
        {count} module{count === 1 ? '' : 's'}
      </button>

      {open && (
        <div
          ref={popoverRef}
          className="absolute z-40 mt-2 w-80 bg-white rounded-xl shadow-2xl border border-gray-200 p-4 right-0"
        >
          <div className="flex items-start justify-between mb-2">
            <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide">
              {MODULES_POPOVER_COPY.HEADER}
            </p>
            <button
              onClick={() => setOpen(false)}
              className="text-gray-400 hover:text-gray-600 -mt-1"
              aria-label="Close"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
              </svg>
            </button>
          </div>

          {/* Roles that feed this access */}
          {roles.length > 0 ? (
            <p className="text-[11px] text-gray-500 mb-3">
              {MODULES_POPOVER_COPY.SOURCE_LABEL}{' '}
              {roles.map((r, i) => (
                <span key={r.id || r.code} className="font-semibold text-gray-700">
                  {r.name}{i < roles.length - 1 ? ', ' : ''}
                </span>
              ))}
            </p>
          ) : (
            <p className="text-xs text-amber-600 mb-3">No active roles \u2014 user has no access.</p>
          )}

          {chips.length === 0 ? (
            <p className="text-xs text-gray-500 italic py-2">{MODULES_POPOVER_COPY.EMPTY}</p>
          ) : (
            <div className="flex flex-wrap gap-1.5 max-h-56 overflow-y-auto">
              {chips.map((c) => (
                <span
                  key={c.code}
                  className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium border ${
                    c.sensitive
                      ? 'bg-amber-50 text-amber-800 border-amber-200'
                      : 'bg-slate-50 text-slate-700 border-slate-200'
                  }`}
                  title={c.code}
                >
                  {c.sensitive && (
                    <svg className="w-3 h-3 text-amber-500 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" clipRule="evenodd"
                        d="M10 1.944A11.954 11.954 0 012.166 5C2.056 5.649 2 6.319 2 7c0 5.225 3.34 9.67 8 11.317C14.66 16.67 18 12.225 18 7c0-.682-.057-1.35-.166-2.001A11.954 11.954 0 0110 1.944z" />
                    </svg>
                  )}
                  {c.name}
                </span>
              ))}
            </div>
          )}

          <div className="mt-3 pt-3 border-t border-gray-100">
            <a
              href={ACCESS_NOTICE.ROLES_LINK_PATH}
              className="text-[11px] text-blue-600 hover:text-blue-800 hover:underline inline-flex items-center gap-1"
            >
              <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                  d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
              </svg>
              {MODULES_POPOVER_COPY.MANAGE_HINT}
            </a>
          </div>
        </div>
      )}
    </div>
  );
}

export default InheritedModulesPopover;

/**
 * PendingActivationAlert
 * ----------------------
 * Surfaces users whose account is **not active** (status !== 'active') at the
 * top of `/admin/users` so administrators can see — and one-click activate —
 * accounts that are stuck in onboarding limbo.
 *
 * BACKGROUND
 * ----------
 * The login endpoint (`backend/apps/users/serializers_jwt.py`) gates
 * authentication on `user.is_active`. When `is_active=False`, the user sees:
 *
 *   "Your account is pending administrator approval. You will be notified
 *    once your account is activated."
 *
 * That error is correct security behavior — it is NOT a password problem.
 * The fix is a single admin action: activate the account. This component
 * just makes that fix discoverable without changing any core logic.
 *
 * SOFT-CODED
 * ----------
 * Every threshold, label, color and "what counts as pending" rule lives in
 * `PENDING_ALERT_CONFIG` below. Tune freely — no JSX edits needed.
 */
import React, { useMemo, useState } from 'react'

// ────────────────────────────────────────────────────────────────────────────
// Soft-coded configuration
// ────────────────────────────────────────────────────────────────────────────
const PENDING_ALERT_CONFIG = {
  // Statuses considered "needs activation". Order = display priority.
  pendingStatuses: ['pending', 'inactive', 'on_leave'],
  // Visual maximum before collapsing into a "+N more" pill.
  maxInlineRows: 5,
  // Friendly status badge palettes
  statusPalette: {
    pending:  { dot: 'bg-amber-500',  pill: 'bg-amber-50 text-amber-700 border-amber-200',  label: 'Pending approval' },
    inactive: { dot: 'bg-slate-400',  pill: 'bg-slate-50 text-slate-700 border-slate-200',  label: 'Inactive' },
    on_leave: { dot: 'bg-blue-500',   pill: 'bg-blue-50 text-blue-700 border-blue-200',     label: 'On leave' },
    suspended:{ dot: 'bg-red-500',    pill: 'bg-red-50 text-red-700 border-red-200',        label: 'Suspended' },
  },
  // Copy
  copy: {
    titleSingular: '1 account is pending activation',
    titlePlural:   'accounts are pending activation',
    subtitle:
      'These users have correct credentials but cannot log in until an administrator activates their account. ' +
      'Click "Activate" to unblock them instantly. No password reset needed.',
    activateBtn: 'Activate',
    activatingBtn: 'Activating…',
    activateAllBtn: 'Activate all visible',
    expandBtn: 'Show all',
    collapseBtn: 'Show less',
    dismissBtn: 'Dismiss for this session',
    emptyHidden:
      'All accounts are active. New sign-ups awaiting approval will appear here automatically.',
  },
}

const PENDING_ALERT_DISMISS_KEY = 'radai.userMgmt.pendingAlert.dismissed.v1'

// ────────────────────────────────────────────────────────────────────────────
// Helpers (pure)
// ────────────────────────────────────────────────────────────────────────────
const getEmail = (u) => u?.user?.email || u?.email || u?.user?.username || ''
const getName  = (u) => {
  const f = u?.user?.first_name || u?.first_name || ''
  const l = u?.user?.last_name  || u?.last_name  || ''
  return `${f} ${l}`.trim() || u?.full_name || getEmail(u) || 'Unnamed user'
}
const getInitials = (u) => {
  const n = getName(u)
  return n.split(/\s+/).filter(Boolean).slice(0, 2).map((p) => p[0]?.toUpperCase()).join('') || '?'
}

// ────────────────────────────────────────────────────────────────────────────
// Component
// ────────────────────────────────────────────────────────────────────────────
const PendingActivationAlert = ({ users = [], onActivate, actionLoading = {} }) => {
  const [expanded, setExpanded] = useState(false)
  const [dismissed, setDismissed] = useState(
    () => sessionStorage.getItem(PENDING_ALERT_DISMISS_KEY) === '1'
  )

  // Derive pending list — soft-coded match rule
  const pending = useMemo(() => {
    if (!Array.isArray(users)) return []
    const set = new Set(PENDING_ALERT_CONFIG.pendingStatuses)
    return users.filter((u) => {
      const s = (u?.status || '').toLowerCase()
      // Treat explicit pending statuses OR is_active=false as needing activation
      return set.has(s) || u?.is_active === false || u?.user?.is_active === false
    })
  }, [users])

  if (dismissed || pending.length === 0) return null

  const visible = expanded ? pending : pending.slice(0, PENDING_ALERT_CONFIG.maxInlineRows)
  const hiddenCount = pending.length - visible.length

  const handleDismiss = () => {
    sessionStorage.setItem(PENDING_ALERT_DISMISS_KEY, '1')
    setDismissed(true)
  }

  const handleActivateAll = async () => {
    for (const u of visible) {
      if (typeof onActivate === 'function') {
        // Sequential to keep API friendly and notifications coherent
        // eslint-disable-next-line no-await-in-loop
        await onActivate(u.id, u.status).catch(() => {})
      }
    }
  }

  const title = pending.length === 1
    ? PENDING_ALERT_CONFIG.copy.titleSingular
    : `${pending.length} ${PENDING_ALERT_CONFIG.copy.titlePlural}`

  return (
    <div className="mb-6 rounded-xl border border-amber-200 bg-gradient-to-br from-amber-50 to-orange-50 shadow-sm overflow-hidden">
      {/* Header */}
      <div className="flex items-start gap-3 p-4 border-b border-amber-100">
        <div className="w-10 h-10 rounded-lg bg-amber-100 text-amber-700 flex items-center justify-center flex-shrink-0">
          <svg xmlns="http://www.w3.org/2000/svg" className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
              d="M12 9v2m0 4h.01M5.07 19h13.86a2 2 0 001.74-3L13.74 4a2 2 0 00-3.48 0L3.34 16a2 2 0 001.73 3z" />
          </svg>
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="text-sm font-bold text-amber-900">{title}</h3>
          <p className="text-xs text-amber-800 mt-0.5 leading-relaxed">
            {PENDING_ALERT_CONFIG.copy.subtitle}
          </p>
        </div>
        <button
          type="button"
          onClick={handleDismiss}
          className="text-xs text-amber-700 hover:text-amber-900 hover:underline flex-shrink-0"
          title={PENDING_ALERT_CONFIG.copy.dismissBtn}
        >
          ✕
        </button>
      </div>

      {/* Rows */}
      <ul className="divide-y divide-amber-100">
        {visible.map((u) => {
          const status = (u.status || '').toLowerCase()
          const palette = PENDING_ALERT_CONFIG.statusPalette[status] || PENDING_ALERT_CONFIG.statusPalette.pending
          const isLoading = !!actionLoading[`status_${u.id}`]
          return (
            <li key={u.id} className="flex items-center gap-3 px-4 py-2.5 bg-white/40">
              <div className="w-9 h-9 rounded-full bg-gradient-to-br from-amber-500 to-orange-600 text-white flex items-center justify-center text-xs font-semibold flex-shrink-0">
                {getInitials(u)}
              </div>
              <div className="flex-1 min-w-0">
                <div className="text-sm font-semibold text-slate-900 truncate">{getName(u)}</div>
                <div className="text-xs text-slate-500 truncate">{getEmail(u) || '—'}</div>
              </div>
              <span className={`hidden sm:inline-flex items-center gap-1 text-[11px] font-semibold px-2 py-0.5 rounded-md border ${palette.pill}`}>
                <span className={`w-1.5 h-1.5 rounded-full ${palette.dot}`} />
                {palette.label}
              </span>
              <button
                type="button"
                onClick={() => typeof onActivate === 'function' && onActivate(u.id, u.status)}
                disabled={isLoading}
                className="px-3 py-1.5 rounded-md bg-emerald-600 hover:bg-emerald-700 text-white text-xs font-semibold disabled:opacity-60 disabled:cursor-not-allowed flex items-center gap-1 flex-shrink-0"
              >
                {isLoading ? (
                  <>
                    <svg className="w-3 h-3 animate-spin" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v4l3.5-3.5L12 1v3a8 8 0 100 16v-4l-3.5 3.5L12 23v-3a8 8 0 01-8-8z" />
                    </svg>
                    {PENDING_ALERT_CONFIG.copy.activatingBtn}
                  </>
                ) : (
                  <>
                    <svg className="w-3 h-3" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M5 13l4 4L19 7" />
                    </svg>
                    {PENDING_ALERT_CONFIG.copy.activateBtn}
                  </>
                )}
              </button>
            </li>
          )
        })}
      </ul>

      {/* Footer */}
      <div className="flex items-center justify-between gap-3 px-4 py-2.5 bg-amber-50/50 border-t border-amber-100">
        <div className="text-[11px] text-amber-800">
          {hiddenCount > 0 && (
            <button
              type="button"
              onClick={() => setExpanded(true)}
              className="font-semibold hover:underline"
            >
              + {hiddenCount} more {PENDING_ALERT_CONFIG.copy.expandBtn.toLowerCase()}
            </button>
          )}
          {expanded && pending.length > PENDING_ALERT_CONFIG.maxInlineRows && (
            <button
              type="button"
              onClick={() => setExpanded(false)}
              className="font-semibold hover:underline"
            >
              {PENDING_ALERT_CONFIG.copy.collapseBtn}
            </button>
          )}
        </div>
        {visible.length > 1 && (
          <button
            type="button"
            onClick={handleActivateAll}
            className="text-xs font-semibold text-emerald-700 hover:text-emerald-900 hover:underline"
          >
            ⚡ {PENDING_ALERT_CONFIG.copy.activateAllBtn} ({visible.length})
          </button>
        )}
      </div>
    </div>
  )
}

export default PendingActivationAlert

/**
 * RoleAssignPopover — inline role badge display + assignment popover per user row.
 *
 * - Shows colour-coded level badges for the user's current roles.
 * - Super Admin users can click to open a checkbox popover and change roles.
 * - Non-super-admins see badges only (read-only), with a lock tooltip.
 * - Sensitive roles (hr_admin) are flagged with an amber shield badge.
 *
 * All thresholds, labels, and colours are soft-coded in the constants below.
 */
import React, { useState, useRef, useEffect, useCallback } from 'react';
import rbacService from '../../services/rbac.service';
import {
  ROLE_LEVEL_COLORS,
  DEFAULT_LEVEL_COLOR,
  SENSITIVE_ROLE_CODES,
  isSensitiveRole,
  CUSTOM_ROLE_PREFIX,
} from '../../config/rbacAccess.config';
import SensitiveRoleConfirmModal from './SensitiveRoleConfirmModal';

// Max badges to show inline before "+N more" truncation
const MAX_VISIBLE_BADGES = 2;

// ────────────────────────────────────────────────────────────────────────────

function RoleAssignPopover({ userId, userLabel = '', currentRoles = [], allRoles = [], isSuperAdmin, onRolesChange }) {
  const [open, setOpen] = useState(false);
  const [saving, setSaving] = useState(false);
  const [localRoles, setLocalRoles] = useState(currentRoles);
  const [error, setError] = useState(null);
  // Sensitive-role typed-confirmation gate — soft-coded via rbacAccess.config
  const [pendingSensitive, setPendingSensitive] = useState(null); // Role obj awaiting confirmation
  const popoverRef = useRef(null);
  const triggerRef = useRef(null);

  // Keep localRoles in sync when parent updates
  useEffect(() => {
    setLocalRoles(currentRoles);
  }, [currentRoles]);

  // Close popover on outside click
  useEffect(() => {
    if (!open) return;
    const handler = (e) => {
      if (
        popoverRef.current && !popoverRef.current.contains(e.target) &&
        triggerRef.current && !triggerRef.current.contains(e.target)
      ) {
        setOpen(false);
        setError(null);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [open]);

  const getLevelColor = (level) => ROLE_LEVEL_COLORS[level] || DEFAULT_LEVEL_COLOR;

  const isAssigned = useCallback(
    (roleId) => localRoles.some((r) => r.id === roleId),
    [localRoles]
  );

  const performAssign = useCallback(
    async (role) => {
      await rbacService.assignRole(userId, role.id);
      const updated = [...localRoles, role];
      setLocalRoles(updated);
      onRolesChange?.(userId, updated);
    },
    [userId, localRoles, onRolesChange]
  );

  const handleToggle = useCallback(
    async (role) => {
      if (!isSuperAdmin || saving) return;
      setError(null);

      // Revoke path — no confirmation gate
      if (isAssigned(role.id)) {
        setSaving(true);
        try {
          await rbacService.revokeRole(userId, role.id);
          const updated = localRoles.filter((r) => r.id !== role.id);
          setLocalRoles(updated);
          onRolesChange?.(userId, updated);
        } catch (err) {
          setError(err?.response?.data?.detail || err?.message || 'Failed to revoke role.');
        } finally {
          setSaving(false);
        }
        return;
      }

      // Assign path — gate sensitive roles behind typed confirmation
      if (isSensitiveRole(role.code)) {
        setPendingSensitive(role);
        return;
      }

      setSaving(true);
      try {
        await performAssign(role);
      } catch (err) {
        setError(err?.response?.data?.detail || err?.message || 'Failed to assign role.');
      } finally {
        setSaving(false);
      }
    },
    [isSuperAdmin, saving, isAssigned, userId, localRoles, onRolesChange, performAssign]
  );

  const handleConfirmSensitive = useCallback(async () => {
    if (!pendingSensitive) return;
    setSaving(true);
    try {
      await performAssign(pendingSensitive);
      setPendingSensitive(null);
    } finally {
      setSaving(false);
    }
  }, [pendingSensitive, performAssign]);

  const visibleBadges = localRoles.slice(0, MAX_VISIBLE_BADGES);
  const overflowCount = localRoles.length - MAX_VISIBLE_BADGES;
  const hasSensitive = localRoles.some((r) => SENSITIVE_ROLE_CODES.includes(r.code));

  return (
    <div className="relative inline-flex items-center gap-1 flex-wrap">
      {/* Role badges */}
      {localRoles.length === 0 ? (
        <span className="text-xs text-gray-400 italic">No roles</span>
      ) : (
        <>
          {visibleBadges.map((role) => {
            const c = getLevelColor(role.level);
            const sensitive = SENSITIVE_ROLE_CODES.includes(role.code);
            return (
              <span
                key={role.id}
                className={`inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full text-xs font-medium border ${c.bg} ${c.text} ${c.border}`}
                title={role.description || role.name}
              >
                {sensitive && (
                  <svg className="w-3 h-3 text-amber-500 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M10 1.944A11.954 11.954 0 012.166 5C2.056 5.649 2 6.319 2 7c0 5.225 3.34 9.67 8 11.317C14.66 16.67 18 12.225 18 7c0-.682-.057-1.35-.166-2.001A11.954 11.954 0 0110 1.944z" clipRule="evenodd" />
                  </svg>
                )}
                {role.name}
              </span>
            );
          })}
          {overflowCount > 0 && (
            <span className="px-2 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-600 border border-gray-200">
              +{overflowCount}
            </span>
          )}
          {hasSensitive && (
            <span
              className="px-1.5 py-0.5 rounded text-xs font-bold bg-amber-50 text-amber-700 border border-amber-200"
              title="This user has access to sensitive HR / Payroll data"
            >
              SENSITIVE
            </span>
          )}
        </>
      )}

      {/* Edit trigger */}
      {isSuperAdmin ? (
        <button
          ref={triggerRef}
          onClick={() => { setOpen((v) => !v); setError(null); }}
          className="p-1 rounded text-gray-400 hover:text-blue-600 hover:bg-blue-50 transition-colors ml-1"
          title="Assign / revoke roles"
        >
          <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15.232 5.232l3.536 3.536m-2.036-5.036a2.5 2.5 0 113.536 3.536L6.5 21.036H3v-3.572L16.732 3.732z" />
          </svg>
        </button>
      ) : (
        <span className="ml-1 text-gray-300" title="Only Super Administrators can change roles">
          <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
          </svg>
        </span>
      )}

      {/* Popover */}
      {open && isSuperAdmin && (
        <div
          ref={popoverRef}
          className="absolute z-50 top-8 left-0 w-64 bg-white rounded-xl shadow-xl border border-gray-200 p-3"
        >
          <p className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">Assign Roles</p>
          {error && (
            <p className="text-xs text-red-600 bg-red-50 rounded px-2 py-1 mb-2">{error}</p>
          )}
          <ul className="space-y-1 max-h-56 overflow-y-auto">
            {allRoles
              .filter((r) => r.is_active !== false)
              // Hide legacy per-user custom_<email> roles — they must be removed via
              // the backend cleanup_custom_roles management command, not the UI.
              .filter((r) => !r.code?.startsWith(CUSTOM_ROLE_PREFIX))
              .map((role) => {
              const assigned = isAssigned(role.id);
              const sensitive = SENSITIVE_ROLE_CODES.includes(role.code);
              const c = getLevelColor(role.level);
              return (
                <li key={role.id}>
                  <label className="flex items-center gap-2 px-2 py-1.5 rounded-lg hover:bg-gray-50 cursor-pointer">
                    <input
                      type="checkbox"
                      checked={assigned}
                      disabled={saving}
                      onChange={() => handleToggle(role)}
                      className="rounded border-gray-300 text-blue-600 focus:ring-blue-500 disabled:opacity-50"
                    />
                    <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-xs font-medium ${c.bg} ${c.text}`}>
                      {sensitive && (
                        <svg className="w-3 h-3 text-amber-500" fill="currentColor" viewBox="0 0 20 20">
                          <path fillRule="evenodd" d="M10 1.944A11.954 11.954 0 012.166 5C2.056 5.649 2 6.319 2 7c0 5.225 3.34 9.67 8 11.317C14.66 16.67 18 12.225 18 7c0-.682-.057-1.35-.166-2.001A11.954 11.954 0 0110 1.944z" clipRule="evenodd" />
                        </svg>
                      )}
                      {role.name}
                    </span>
                    {role.level && (
                      <span className="text-xs text-gray-400 ml-auto">L{role.level}</span>
                    )}
                  </label>
                </li>
              );
            })}
          </ul>
          {saving && (
            <p className="text-xs text-blue-600 mt-2 text-center animate-pulse">Saving…</p>
          )}
          <button
            onClick={() => setOpen(false)}
            className="mt-2 w-full text-xs text-center text-gray-500 hover:text-gray-700 py-1"
          >
            Close
          </button>
        </div>
      )}

      {/* Typed-confirmation gate for sensitive-role assignment */}
      <SensitiveRoleConfirmModal
        open={!!pendingSensitive}
        role={pendingSensitive}
        userLabel={userLabel}
        busy={saving}
        onCancel={() => setPendingSensitive(null)}
        onConfirm={handleConfirmSensitive}
      />
    </div>
  );
}

export default RoleAssignPopover;

/**
 * SensitiveRoleConfirmModal
 *
 * Blocks the assignment of a sensitive role (e.g. hr_admin) behind a
 * typed-confirmation gate. All copy comes from SENSITIVE_CONFIRM_CONFIG in
 * the shared rbacAccess.config so behavior can be tuned without touching
 * this component.
 *
 * Props:
 *   open      : boolean
 *   role      : { code, name, level } — the role being assigned
 *   userLabel : string  (e.g. "john.doe@radai.ae")
 *   onCancel  : () => void
 *   onConfirm : () => Promise<void>   — perform the actual assignment
 *   busy      : boolean               — external loading flag
 */
import React, { useState, useEffect } from 'react';
import { SENSITIVE_CONFIRM_CONFIG } from '../../config/rbacAccess.config';

function SensitiveRoleConfirmModal({ open, role, userLabel, onCancel, onConfirm, busy = false }) {
  const [typed, setTyped] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    if (open) {
      setTyped('');
      setError('');
    }
  }, [open]);

  if (!open || !role) return null;

  const matches = typed.trim() === SENSITIVE_CONFIRM_CONFIG.CONFIRM_TOKEN;

  const handleConfirm = async () => {
    if (!matches || busy) {
      setError(SENSITIVE_CONFIRM_CONFIG.MISMATCH_MSG);
      return;
    }
    setError('');
    try {
      await onConfirm();
    } catch (err) {
      setError(err?.response?.data?.detail || err?.message || 'Failed to grant role.');
    }
  };

  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 backdrop-blur-sm p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-md w-full overflow-hidden border border-amber-200">
        {/* Header */}
        <div className="px-5 py-4 bg-gradient-to-r from-amber-500 to-orange-500 flex items-center gap-3">
          <div className="p-2 bg-white/20 rounded-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2}
                d="M12 9v2m0 4h.01M4.93 19h14.14a2 2 0 001.74-3l-7.07-12a2 2 0 00-3.48 0L3.19 16a2 2 0 001.74 3z" />
            </svg>
          </div>
          <div>
            <h3 className="text-lg font-bold text-white">{SENSITIVE_CONFIRM_CONFIG.TITLE}</h3>
            <p className="text-xs text-amber-100">Audited action — Super Administrator only</p>
          </div>
        </div>

        {/* Body */}
        <div className="p-5 space-y-4">
          <p className="text-sm text-gray-700 leading-relaxed">
            {SENSITIVE_CONFIRM_CONFIG.WARNING}
          </p>

          <div className="rounded-lg border border-amber-200 bg-amber-50 p-3 text-sm">
            <div className="flex items-center justify-between">
              <span className="text-gray-600">Role:</span>
              <span className="font-semibold text-amber-800">
                {role.name}
                <span className="ml-2 text-xs text-amber-600">({role.code})</span>
              </span>
            </div>
            {userLabel && (
              <div className="flex items-center justify-between mt-2">
                <span className="text-gray-600">User:</span>
                <span className="font-medium text-gray-900 truncate ml-2">{userLabel}</span>
              </div>
            )}
          </div>

          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-1">
              {SENSITIVE_CONFIRM_CONFIG.INSTRUCTION}
            </label>
            <input
              type="text"
              value={typed}
              onChange={(e) => {
                setTyped(e.target.value);
                if (error) setError('');
              }}
              placeholder={SENSITIVE_CONFIRM_CONFIG.CONFIRM_TOKEN}
              autoFocus
              className={`w-full px-3 py-2 rounded-lg border-2 text-sm font-mono tracking-widest uppercase
                ${matches ? 'border-green-400 bg-green-50' : 'border-gray-300 bg-white'}
                focus:outline-none focus:ring-2 focus:ring-amber-400`}
            />
            {error && (
              <p className="mt-2 text-xs text-red-600 flex items-center gap-1">
                <svg className="w-4 h-4" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" clipRule="evenodd"
                    d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7 4a1 1 0 11-2 0 1 1 0 012 0zm-1-9a1 1 0 00-1 1v4a1 1 0 102 0V6a1 1 0 00-1-1z" />
                </svg>
                {error}
              </p>
            )}
          </div>
        </div>

        {/* Footer */}
        <div className="px-5 py-3 bg-gray-50 border-t border-gray-200 flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={onCancel}
            disabled={busy}
            className="px-4 py-2 rounded-lg border border-gray-300 text-sm text-gray-700 hover:bg-gray-100 transition disabled:opacity-50"
          >
            {SENSITIVE_CONFIRM_CONFIG.CANCEL_BTN}
          </button>
          <button
            type="button"
            onClick={handleConfirm}
            disabled={!matches || busy}
            className={`px-4 py-2 rounded-lg text-sm font-semibold text-white transition shadow-sm
              ${matches && !busy
                ? 'bg-gradient-to-r from-amber-500 to-orange-500 hover:from-amber-600 hover:to-orange-600'
                : 'bg-gray-300 cursor-not-allowed'}`}
          >
            {busy ? 'Granting…' : SENSITIVE_CONFIRM_CONFIG.CONFIRM_BTN}
          </button>
        </div>
      </div>
    </div>
  );
}

