// Tone → Tailwind colour token. Soft-coded so adding a new accent is
// a single line.
const TONE_CLASSES = {
  green:   'bg-green-100 text-green-700 ring-green-300',
  red:     'bg-red-100 text-red-700 ring-red-300',
  amber:   'bg-amber-100 text-amber-700 ring-amber-300',
  blue:    'bg-blue-100 text-blue-700 ring-blue-300',
  cyan:    'bg-cyan-100 text-cyan-700 ring-cyan-300',
  teal:    'bg-teal-100 text-teal-700 ring-teal-300',
  indigo:  'bg-indigo-100 text-indigo-700 ring-indigo-300',
  violet:  'bg-violet-100 text-violet-700 ring-violet-300',
  purple:  'bg-purple-100 text-purple-700 ring-purple-300',
  fuchsia: 'bg-fuchsia-100 text-fuchsia-700 ring-fuchsia-300',
  slate:   'bg-slate-100 text-slate-700 ring-slate-300',
  zinc:    'bg-zinc-100 text-zinc-700 ring-zinc-300',
};

const TIP_ROTATION_MS = 7000;
const PULSE_FRESH_MS = 5000;

const formatRelative = (date) => {
  if (!date) return 'never';
  const diff = Math.max(0, Date.now() - new Date(date).getTime());
  const s = Math.floor(diff / 1000);
  if (s < 5) return 'just now';
  if (s < 60) return `${s}s ago`;
  const m = Math.floor(s / 60);
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
};

/**
 * LiveTabFrame
 *
 * Wrapper that adds a unified, real-time, user-friendly chrome around any
 * admin dashboard tab body. Driven entirely by `TAB_LIVE_CONFIG` —
 * adding a new tab requires only a single config entry.
 *
 * Props:
 *   - tabId      : key into TAB_LIVE_CONFIG
 *   - children   : actual tab body (untouched)
 *   - context    : data bag forwarded to KPI accessors (analyticsData,
 *                  realtimeActivity, securityAlerts, predictions, mlMetrics, …)
 *   - onRefresh  : manual refresh callback (calls the existing loader)
 *   - lastUpdated: timestamp of the most recent successful fetch
 *   - autoRefresh: boolean — whether the parent timer is active
 *   - onToggleAutoRefresh : optional toggle callback
 *   - loading    : boolean — show spinner on the refresh icon
 */
const LiveTabFrame = ({
  tabId,
  children,
  context = {},
  onRefresh,
  lastUpdated,
  autoRefresh = true,
  onToggleAutoRefresh,
  loading = false,
}) => {
  const cfg = TAB_LIVE_CONFIG[tabId];
  const [tipIndex, setTipIndex] = useState(0);
  const [, forceTick] = useState(0);

  // Rotate the innovation tip every TIP_ROTATION_MS.
  useEffect(() => {
    if (!cfg?.tips?.length) return undefined;
    const id = setInterval(
      () => setTipIndex((i) => (i + 1) % cfg.tips.length),
      TIP_ROTATION_MS,
    );
    return () => clearInterval(id);
  }, [cfg]);

  // Drive the relative timestamp.
  useEffect(() => {
    const id = setInterval(() => forceTick((t) => t + 1), 1000);
    return () => clearInterval(id);
  }, []);

  const kpis = useMemo(
    () => (cfg?.kpis ? cfg.kpis(context) : []),
    [cfg, context],
  );

  if (!cfg) return <>{children}</>;

  const isFresh =
    lastUpdated && Date.now() - new Date(lastUpdated).getTime() < PULSE_FRESH_MS;

  return (
    <div className="space-y-4">
      {/* Live header strip */}
      <div
        className={`relative overflow-hidden rounded-xl bg-gradient-to-r ${cfg.accent} text-white shadow-lg`}
      >
        <div
          aria-hidden="true"
          className="absolute inset-0 opacity-10"
          style={{
            backgroundImage:
              'radial-gradient(circle at 20% 20%, white 1px, transparent 1px)',
            backgroundSize: '24px 24px',
          }}
        />
        <div className="relative p-4 sm:p-5">
          <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
            {/* Title + live pulse */}
            <div className="flex items-center gap-3 min-w-0">
              <div className="flex-shrink-0 w-11 h-11 rounded-lg bg-white/15 backdrop-blur-sm flex items-center justify-center text-2xl">
                <span aria-hidden="true">{cfg.icon}</span>
              </div>
              <div className="min-w-0">
                <div className="flex items-center gap-2">
                  <h3 className="text-base sm:text-lg font-bold truncate">
                    {cfg.title}
                  </h3>
                  <span
                    className={`relative flex h-2.5 w-2.5 ${
                      autoRefresh ? '' : 'opacity-40'
                    }`}
                    title={
                      autoRefresh
                        ? 'Auto-refresh ON'
                        : 'Auto-refresh paused'
                    }
                  >
                    {autoRefresh && (
                      <span
                        className={`animate-ping absolute inline-flex h-full w-full rounded-full ${
                          isFresh ? 'bg-green-300' : 'bg-white/60'
                        } opacity-75`}
                      />
                    )}
                    <span
                      className={`relative inline-flex rounded-full h-2.5 w-2.5 ${
                        autoRefresh
                          ? isFresh
                            ? 'bg-green-300'
                            : 'bg-white'
                          : 'bg-white/60'
                      }`}
                    />
                  </span>
                </div>
                <p className="text-xs sm:text-sm text-white/80 truncate">
                  {cfg.subtitle}
                </p>
              </div>
            </div>

            {/* Controls */}
            <div className="flex flex-wrap items-center gap-2 text-xs">
              <span className="px-2.5 py-1 rounded-full bg-white/15 backdrop-blur-sm">
                Updated{' '}
                <span className="font-semibold">
                  {formatRelative(lastUpdated)}
                </span>
              </span>
              {onToggleAutoRefresh && (
                <button
                  type="button"
                  onClick={onToggleAutoRefresh}
                  className="px-2.5 py-1 rounded-full bg-white/15 hover:bg-white/25 backdrop-blur-sm transition"
                  title="Toggle auto-refresh"
                >
                  {autoRefresh ? '⏸ Pause' : '▶ Resume'}
                </button>
              )}
              {onRefresh && (
                <button
                  type="button"
                  onClick={onRefresh}
                  disabled={loading}
                  className="px-2.5 py-1 rounded-full bg-white/20 hover:bg-white/30 backdrop-blur-sm transition disabled:opacity-50 flex items-center gap-1"
                  title="Refresh now"
                >
                  <svg
                    className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`}
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                    />
                  </svg>
                  Refresh
                </button>
              )}
            </div>
          </div>

          {/* KPI mini-strip */}
          {kpis.length > 0 && (
            <div className="mt-4 grid grid-cols-3 gap-2 sm:gap-3">
              {kpis.map((k, i) => (
                <div
                  key={`${k.label}-${i}`}
                  className="rounded-lg bg-white/10 backdrop-blur-sm px-3 py-2 ring-1 ring-white/20"
                >
                  <div className="text-[10px] uppercase tracking-wide text-white/70">
                    {k.label}
                  </div>
                  <div className="mt-0.5 flex items-center gap-1.5">
                    <span
                      className={`inline-flex w-2 h-2 rounded-full ring-2 ${
                        TONE_CLASSES[k.tone] || TONE_CLASSES.slate
                      }`}
                    />
                    <span className="text-sm sm:text-base font-bold truncate">
                      {k.value}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          )}

          {/* Innovation tip ribbon */}
          {cfg.tips?.length > 0 && (
            <div className="mt-3 text-xs text-white/85 italic flex items-start gap-1.5">
              <span aria-hidden="true">💡</span>
              <span className="flex-1">{cfg.tips[tipIndex]}</span>
            </div>
          )}
        </div>
      </div>

      {/* Inner tab body — untouched */}
      <div>{children}</div>
    </div>
  );
};

export default LiveTabFrame;

import React, { useEffect, useRef, useState } from 'react';
import { AlertCircle, Bell, RefreshCw, Search, X } from 'lucide-react';
import analyticsService from '../../services/analyticsService';
import './NotificationHistoryTab.css';

const CHANNELS = [['notification', 'Notification'], ['email', 'Email'], ['teams', 'Teams'], ['web_push', 'Web push'], ['other', 'Other']];
const OUTCOMES = [['recorded', 'Recorded'], ['sent', 'Send recorded'], ['read', 'Marked read'], ['archived', 'Archived'], ['failed', 'Failed'], ['skipped', 'Skipped'], ['unknown', 'Unknown']];
const DELIVERY_STATUSES = ['sent', 'failed', 'skipped', 'not_applicable', 'unknown'];
const READ_STATUSES = { read: 'Marked read', unread: 'Unread' };
const text = value => typeof value === 'string' || typeof value === 'number' ? String(value) : '';
const channelLabel = value => CHANNELS.find(([key]) => key === value)?.[1] || 'Other';
const outcomeLabel = row => row.outcome_label || OUTCOMES.find(([key]) => key === row.outcome)?.[1] || 'Unknown';
const deliveryLabel = row => DELIVERY_STATUSES.includes(row.delivery_status) ? row.delivery_status_label || 'Unknown' : 'Unknown';
const readLabel = row => Object.hasOwn(READ_STATUSES, row.read_status) ? READ_STATUSES[row.read_status] : 'Unknown';
const timestamp = (value, timezone) => {
  const date = new Date(value);
  if (!value || Number.isNaN(date.getTime())) return 'Not recorded';
  try { return date.toLocaleString('en-GB', { timeZone: timezone || 'UTC', dateStyle: 'medium', timeStyle: 'medium' }); }
  catch { return date.toISOString(); }
};

// Keep the details view limited to the public history projection.
function historyRow(row) {
  return {
    id: text(row.id), timestamp: text(row.timestamp), notification_id: text(row.notification_id),
    recipient: { id: text(row.recipient?.id), name: text(row.recipient?.name), email: text(row.recipient?.email), username: text(row.recipient?.username) },
    category: text(row.category), action: text(row.action), event_label: text(row.event_label),
    channel: text(row.channel), outcome: text(row.outcome), outcome_label: text(row.outcome_label), reason_label: text(row.reason_label),
    delivery_status: text(row.delivery_status), delivery_status_label: text(row.delivery_status_label),
    read_status: text(row.read_status),
  };
}

export default function NotificationHistoryTab({ hours = 24, refreshToken }) {
  const [filters, setFilters] = useState({ search: '', channel: '', outcome: '', page_size: 25, page: 1, hours });
  const [search, setSearch] = useState('');
  const [retry, setRetry] = useState(0);
  const [snapshot, setSnapshot] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [selected, setSelected] = useState(null);
  const requestId = useRef(0);
  const dialogRef = useRef(null);
  const triggerRef = useRef(null);
  const page = filters.hours === hours ? filters.page : 1;
  const { channel, outcome, page_size: pageSize, search: appliedSearch } = filters;
  const queryKey = JSON.stringify([hours, page, pageSize, appliedSearch, channel, outcome]);
  const current = snapshot?.key === queryKey ? snapshot : null;
  const detail = selected?.key === queryKey ? selected.row : null;
  const hasFilters = Boolean(appliedSearch || channel || outcome);
  const changeFilters = change => setFilters(previous => ({ ...previous, ...change, hours, page: change.page ?? 1 }));
  const clearFilters = () => { setSearch(''); changeFilters({ search: '', channel: '', outcome: '' }); };

  useEffect(() => {
    const sequence = ++requestId.current;
    const controller = new AbortController();
    setLoading(true);
    setError('');
    analyticsService.getNotificationHistory({ hours, page, page_size: pageSize, ...(appliedSearch ? { search: appliedSearch } : {}), ...(channel ? { channel } : {}), ...(outcome ? { outcome } : {}) }, { signal: controller.signal })
      .then(response => {
        if (controller.signal.aborted || sequence !== requestId.current) return;
        if (!Array.isArray(response?.results) || !Number.isInteger(response.count) || response.count < 0) throw new Error('Invalid history response');
        if (page > 1 && !response.results.length) { setFilters(previous => ({ ...previous, hours, page: 1 })); return; }
        const rows = response.results.map(historyRow);
        setSnapshot({ key: queryKey, rows, count: response.count, timezone: text(response.timezone) || 'UTC' });
        setSelected(previous => {
          const row = previous?.key === queryKey ? rows.find(item => item.id === previous.row.id) : null;
          return row ? { key: queryKey, row } : null;
        });
      })
      .catch(failure => {
        if (controller.signal.aborted || sequence !== requestId.current) return;
        if (failure?.response?.status === 404 && page > 1) { setFilters(previous => ({ ...previous, hours, page: 1 })); return; }
        if ([401, 403].includes(failure?.response?.status)) {
          setSnapshot(null);
          setSelected(null);
          setError('denied');
        } else setError('failed');
      })
      .finally(() => { if (!controller.signal.aborted && sequence === requestId.current) setLoading(false); });
    return () => controller.abort();
  }, [hours, page, pageSize, appliedSearch, channel, outcome, queryKey, refreshToken, retry]);

  useEffect(() => {
    if (detail) dialogRef.current?.showModal();
    else dialogRef.current?.close();
  }, [detail]);

  return <section className="ac-notification-history ac-panel" aria-labelledby="notification-history-title">
    <div className="ac-panel-heading"><h2 id="notification-history-title"><Bell size={18} />Notification Logs History</h2>{current && <span>Times: {current.timezone}</span>}</div>
    <form className="ac-notification-filters" onSubmit={event => { event.preventDefault(); changeFilters({ search: search.trim() }); }}>
      <label className="ac-notification-search"><span>Recipient or notification ID</span><div><Search size={16} aria-hidden="true" /><input aria-label="Recipient or notification ID" type="search" value={search} maxLength={200} onChange={event => setSearch(event.target.value)} placeholder="Search history" /><button type="submit">Search</button></div></label>
      <label><span>Channel</span><select aria-label="Channel" value={channel} onChange={event => changeFilters({ channel: event.target.value })}><option value="">All channels</option>{CHANNELS.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
      <label><span>Outcome</span><select aria-label="Outcome" value={outcome} onChange={event => changeFilters({ outcome: event.target.value })}><option value="">All outcomes</option>{OUTCOMES.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
      <button type="button" className="ac-notification-clear" onClick={clearFilters} disabled={!hasFilters && !search}>Clear filters</button>
    </form>
    {error && <div role="alert" className="ac-notification-error"><AlertCircle size={18} /><p>{error === 'denied' ? 'You do not have access to notification history.' : current ? 'History could not be refreshed. Previous results are shown.' : 'Notification history could not be loaded.'}</p><button type="button" disabled={loading} onClick={() => setRetry(value => value + 1)}><RefreshCw size={14} />Retry</button></div>}
    {loading && <p role="status" className="ac-notification-loading">{current ? 'Refreshing notification history…' : 'Loading notification history…'}</p>}
    {current && <>
      {current.rows.length ? <div className="ac-table-scroll" role="region" aria-label="Notification history results" tabIndex={0}><table>
        <thead><tr>{['Time', 'Recipient', 'Notification ID', 'Category', 'Channel', 'Delivery Status', 'Read Status', 'Outcome', 'Details'].map(title => <th key={title} scope="col">{title}</th>)}</tr></thead>
        <tbody>{current.rows.map(row => <tr key={row.id}>
          <td className="ac-notification-time"><time dateTime={row.timestamp}>{timestamp(row.timestamp, current.timezone)}</time></td>
          <td><strong>{row.recipient.name || row.recipient.username || 'Not recorded'}</strong><small>{row.recipient.email || row.recipient.username}</small></td>
          <td>{row.notification_id || 'Not recorded'}</td><td>{row.category.replaceAll('_', ' ') || 'Not recorded'}</td><td>{channelLabel(row.channel)}</td>
          <td><span className={`ac-notification-outcome ${DELIVERY_STATUSES.includes(row.delivery_status) ? row.delivery_status : 'unknown'}`}>{deliveryLabel(row)}</span></td>
          <td><span className={`ac-notification-outcome ${Object.hasOwn(READ_STATUSES, row.read_status) ? row.read_status : 'unknown'}`}>{readLabel(row)}</span></td>
          <td><span className={`ac-notification-outcome ${OUTCOMES.some(([key]) => key === row.outcome) ? row.outcome : 'unknown'}`}>{outcomeLabel(row)}</span></td>
          <td><button type="button" className="ac-text-button" aria-label={`View event ${row.id}`} onClick={event => { triggerRef.current = event.currentTarget; setSelected({ key: queryKey, row }); }}>View</button></td>
        </tr>)}</tbody>
      </table></div> : <div className="ac-notification-empty"><Bell size={28} /><p>{hasFilters ? 'No notification events match these filters.' : 'No notification events recorded in this period.'}</p>{hasFilters && <button type="button" onClick={clearFilters}>Clear filters</button>}</div>}
      <nav className="ac-notification-pagination" aria-label="Notification history pagination">
        <p aria-live="polite">{current.count ? `${(page - 1) * pageSize + 1}–${Math.min(page * pageSize, current.count)} of ${current.count} events` : '0 events'}</p>
        <label>Rows per page<select aria-label="Rows per page" value={pageSize} onChange={event => changeFilters({ page_size: Number(event.target.value) })}>{[25, 50, 100].map(size => <option key={size} value={size}>{size}</option>)}</select></label>
        <div><button type="button" disabled={loading || page <= 1} onClick={() => changeFilters({ page: page - 1 })}>Previous</button><span>Page {page} of {Math.max(1, Math.ceil(current.count / pageSize))}</span><button type="button" disabled={loading || page * pageSize >= current.count} onClick={() => changeFilters({ page: page + 1 })}>Next</button></div>
      </nav>
    </>}
    <dialog ref={dialogRef} className="ac-notification-dialog" aria-labelledby="notification-event-title" onClose={() => { setSelected(null); triggerRef.current?.focus(); }} onClick={event => { if (event.target === event.currentTarget) dialogRef.current.close(); }}>
      {detail && <><div className="ac-panel-heading"><h2 id="notification-event-title">Notification event details</h2><button type="button" aria-label="Close notification event details" autoFocus onClick={() => dialogRef.current.close()}><X size={18} /></button></div>
        <dl>{[
          ['Event ID', detail.id], ['Time', timestamp(detail.timestamp, current?.timezone)], ['Timezone', current?.timezone],
          ['Recipient', detail.recipient.name || detail.recipient.username], ['Email', detail.recipient.email],
          ['Notification ID', detail.notification_id], ['Category', detail.category.replaceAll('_', ' ')],
          ['Event', detail.event_label], ['Channel', channelLabel(detail.channel)], ['Outcome', outcomeLabel(detail)],
          ['Delivery Status', deliveryLabel(detail)], ['Read Status', readLabel(detail)],
          ...(detail.reason_label ? [['Reason', detail.reason_label]] : []),
        ].map(([label, value]) => <React.Fragment key={label}><dt>{label}</dt><dd>{value || 'Not recorded'}</dd></React.Fragment>)}</dl>
      </>}
    </dialog>
  </section>;
}

import { radaiAlert } from '../../services/radaiDialog'
import React, { useState, useEffect } from 'react';
import analyticsService from '../../services/analyticsService';
import qhseService from '../../services/qhse.service';
import { 
  AI_MODELS_REGISTRY, 
  AI_PROVIDERS, 
  AI_MODEL_CATEGORIES,
  AI_MODELS_STATS,
  getModelsByCategory,
  getModelsByProvider 
} from '../../config/aiModels.config';

/**
 * AI Predictions and Insights Component
 * Machine learning powered recommendations + Comprehensive AI Models Information
 * Real-time model tracking with dynamic updates
 */
const PredictionsTab = ({ predictions: initialPredictions, onRefresh }) => {
  const [predictions, setPredictions] = useState(initialPredictions || []);
  const [acknowledging, setAcknowledging] = useState(false);
  const [activeView, setActiveView] = useState('models'); // 'predictions' or 'models'
  const [selectedModel, setSelectedModel] = useState(null);
  const [filterCategory, setFilterCategory] = useState('all');
  
  // Dynamic AI Models State
  const [dynamicModels, setDynamicModels] = useState([]);
  const [modelsLoading, setModelsLoading] = useState(false);
  const [modelsStats, setModelsStats] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);

  // Fetch dynamic AI models from backend
  useEffect(() => {
    if (activeView === 'models') {
      fetchAIModels();
    }
  }, [activeView]);

  const fetchAIModels = async () => {
    setModelsLoading(true);
    try {
      const response = await qhseService.ai.getModelsRegistry();
      if (response.success) {
        setDynamicModels(response.models);
        setModelsStats(response.statistics);
        setLastUpdated(response.timestamp);
      }
    } catch (error) {
      console.error('Failed to fetch AI models:', error);
      // Fallback to static config if API fails
      setDynamicModels([]);
    } finally {
      setModelsLoading(false);
    }
  };

  const getImpactBadge = (impact) => {
    const styles = {
      high: 'bg-red-100 text-red-800',
      medium: 'bg-yellow-100 text-yellow-800',
      low: 'bg-green-100 text-green-800',
    };
    return styles[impact] || styles.medium;
  };

  const getInsightIcon = (type) => {
    const icons = {
      usage_forecast: (
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z" />
        </svg>
      ),
      capacity_planning: (
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
        </svg>
      ),
      user_churn_risk: (
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
        </svg>
      ),
      performance_optimization: (
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
        </svg>
      ),
      cost_optimization: (
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      ),
      security_risk: (
        <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 15v2m-6 4h12a2 2 0 002-2v-6a2 2 0 00-2-2H6a2 2 0 00-2 2v6a2 2 0 002 2zm10-10V7a4 4 0 00-8 0v4h8z" />
        </svg>
      ),
    };
    return icons[type] || icons.usage_forecast;
  };

  const handleAcknowledge = async (insightId) => {
    setAcknowledging(true);
    try {
      await analyticsService.acknowledgeInsight(insightId);
      setPredictions(predictions.filter(p => p.id !== insightId));
      onRefresh();
    } catch (error) {
      console.error('Failed to acknowledge insight:', error);
      await radaiAlert('Failed to acknowledge insight');
    } finally {
      setAcknowledging(false);
    }
  };

  // Merge static and dynamic models (dynamic takes priority)
  const allModels = React.useMemo(() => {
    const models = [...AI_MODELS_REGISTRY];
    
    // Add or update with dynamic QHSE models
    dynamicModels.forEach(dynModel => {
      const existingIndex = models.findIndex(m => m.id === dynModel.id);
      if (existingIndex >= 0) {
        // Update existing model with live data
        models[existingIndex] = {
          ...models[existingIndex],
          ...dynModel,
          specifications: dynModel.configuration,
          usedIn: dynModel.usedIn || models[existingIndex].usedIn
        };
      } else {
        // Add new model
        models.push({
          id: dynModel.id,
          name: dynModel.name,
          provider: { 
            id: dynModel.provider, 
            name: dynModel.provider === 'custom' ? 'QHSE Custom Models' : 'OpenAI',
            logo: dynModel.provider === 'custom' ? '⚡' : '🤖',
            color: 'from-blue-500 to-cyan-600'
          },
          category: dynModel.category,
          version: dynModel.configuration?.version || '1.0',
          description: dynModel.description,
          capabilities: dynModel.capabilities,
          usedIn: dynModel.usedIn,
          specifications: dynModel.configuration,
          status: dynModel.status,
          lastUpdated: dynModel.last_updated
        });
      }
    });
    
    return models;
  }, [dynamicModels]);

  // Calculate comprehensive stats
  const comprehensiveStats = React.useMemo(() => {
    if (modelsStats) {
      return {
        totalModels: allModels.length,
        activeModels: modelsStats.active_models + AI_MODELS_STATS.activeModels,
        providers: modelsStats.providers + AI_MODELS_STATS.providers,
        categories: new Set([...allModels.map(m => m.category)]).size,
        totalModules: new Set([...allModels.flatMap(m => m.usedIn?.map(u => u.module) || [])]).size,
        totalPredictions: modelsStats.total_predictions || 0
      };
    }
    return {
      totalModels: allModels.length,
      activeModels: allModels.filter(m => m.status === 'active').length,
      providers: new Set(allModels.map(m => m.provider?.id || m.provider)).size,
      categories: new Set(allModels.map(m => m.category)).size,
      totalModules: new Set(allModels.flatMap(m => m.usedIn?.map(u => u.module) || [])).size,
      totalPredictions: 0
    };
  }, [allModels, modelsStats]);

  // Filter models based on category
  const filteredModels = filterCategory === 'all' 
    ? allModels 
    : allModels.filter(m => m.category === filterCategory);

  // AI Models View Component
  const renderAIModelsView = () => (
    <div className="space-y-6">
      {/* Stats Overview with Real-time Data */}
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-4 rounded-xl border-2 border-blue-200">
          <div className="text-2xl font-bold text-blue-600">{comprehensiveStats.totalModels}</div>
          <div className="text-sm text-blue-900 font-medium">Total AI Models</div>
          {modelsLoading && <div className="text-xs text-blue-700 mt-1">Updating...</div>}
        </div>
        <div className="bg-gradient-to-br from-green-50 to-green-100 p-4 rounded-xl border-2 border-green-200">
          <div className="text-2xl font-bold text-green-600">{comprehensiveStats.activeModels}</div>
          <div className="text-sm text-green-900 font-medium">Active Models</div>
          {lastUpdated && <div className="text-xs text-green-700 mt-1">Live</div>}
        </div>
        <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-4 rounded-xl border-2 border-purple-200">
          <div className="text-2xl font-bold text-purple-600">{comprehensiveStats.providers}</div>
          <div className="text-sm text-purple-900 font-medium">AI Providers</div>
        </div>
        <div className="bg-gradient-to-br from-orange-50 to-orange-100 p-4 rounded-xl border-2 border-orange-200">
          <div className="text-2xl font-bold text-orange-600">{comprehensiveStats.categories}</div>
          <div className="text-sm text-orange-900 font-medium">Categories</div>
        </div>
        <div className="bg-gradient-to-br from-cyan-50 to-cyan-100 p-4 rounded-xl border-2 border-cyan-200">
          <div className="text-2xl font-bold text-cyan-600">{comprehensiveStats.totalModules}</div>
          <div className="text-sm text-cyan-900 font-medium">Modules</div>
        </div>
      </div>

      {/* Last Updated Timestamp */}
      {lastUpdated && (
        <div className="flex items-center justify-between bg-blue-50 px-4 py-2 rounded-lg border border-blue-200">
          <div className="flex items-center space-x-2">
            <svg className="w-5 h-5 text-blue-600 animate-pulse" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
            <span className="text-sm font-medium text-blue-900">Real-time Data</span>
          </div>
          <div className="text-xs text-blue-700">
            Last updated: {new Date(lastUpdated).toLocaleString()}
          </div>
          <button
            onClick={fetchAIModels}
            disabled={modelsLoading}
            className="px-3 py-1 bg-blue-600 text-white text-xs rounded hover:bg-blue-700 disabled:opacity-50"
          >
            {modelsLoading ? 'Refreshing...' : 'Refresh Now'}
          </button>
        </div>
      )}

      {/* Category Filter */}
      <div className="flex items-center space-x-2 overflow-x-auto pb-2">
        <button
          onClick={() => setFilterCategory('all')}
          className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap transition-all ${
            filterCategory === 'all'
              ? 'bg-blue-600 text-white'
              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
          }`}
        >
          All Models ({AI_MODELS_REGISTRY.length})
        </button>
        {Object.entries(AI_MODEL_CATEGORIES).map(([key, value]) => (
          <button
            key={value}
            onClick={() => setFilterCategory(value)}
            className={`px-4 py-2 rounded-lg font-medium whitespace-nowrap transition-all ${
              filterCategory === value
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            {key.replace('_', ' ')} ({getModelsByCategory(value).length})
          </button>
        ))}
      </div>

      {/* Models Grid */}
      <div className="grid grid-cols-1 gap-6">
        {filteredModels.map((model) => (
          <div
            key={model.id}
            className="bg-white border-2 border-gray-200 rounded-xl p-6 hover:border-blue-400 transition-all cursor-pointer"
            onClick={() => setSelectedModel(selectedModel?.id === model.id ? null : model)}
          >
            {/* Model Header */}
            <div className="flex items-start justify-between mb-4">
              <div className="flex items-center space-x-4">
                <div className={`w-16 h-16 bg-gradient-to-br ${model.provider.color} rounded-xl flex items-center justify-center text-3xl shadow-lg`}>
                  {model.provider.logo}
                </div>
                <div>
                  <h4 className="text-xl font-bold text-gray-900">{model.name}</h4>
                  <p className="text-sm text-gray-600">{model.provider.name} • {model.version}</p>
                  <span className="inline-block mt-1 px-3 py-1 bg-green-100 text-green-800 text-xs font-semibold rounded-full">
                    {model.status.toUpperCase()}
                  </span>
                </div>
              </div>
              <svg
                className={`w-6 h-6 text-gray-400 transition-transform ${selectedModel?.id === model.id ? 'rotate-180' : ''}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
              </svg>
            </div>

            {/* Model Description */}
            <p className="text-gray-700 mb-4">{model.description}</p>

            {/* Capabilities Pills */}
            <div className="flex flex-wrap gap-2 mb-4">
              {model.capabilities.map((capability, idx) => (
                <span
                  key={idx}
                  className="px-3 py-1 bg-blue-50 text-blue-700 text-xs font-medium rounded-full"
                >
                  {capability}
                </span>
              ))}
            </div>

            {/* Used In Count */}
            <div className="text-sm text-gray-600 font-medium mb-2">
              Used in {model.usedIn.length} feature{model.usedIn.length !== 1 ? 's' : ''}
            </div>

            {/* Expanded Details */}
            {selectedModel?.id === model.id && (
              <div className="mt-6 pt-6 border-t-2 border-gray-200 space-y-6">
                {/* Usage Details */}
                <div>
                  <h5 className="text-lg font-bold text-gray-900 mb-3 flex items-center">
                    <svg className="w-5 h-5 mr-2 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2" />
                    </svg>
                    Usage in Application
                  </h5>
                  <div className="space-y-4">
                    {model.usedIn.map((usage, idx) => (
                      <div key={idx} className="bg-gradient-to-br from-purple-50 to-indigo-50 p-4 rounded-lg border-2 border-purple-200">
                        <div className="flex items-start justify-between mb-2">
                          <div>
                            <h6 className="font-bold text-purple-900">{usage.feature}</h6>
                            <p className="text-sm text-purple-700 font-medium">{usage.module}</p>
                          </div>
                          <div className="text-right">
                            <div className="text-sm font-semibold text-green-600">{usage.accuracy} Accuracy</div>
                            <div className="text-xs text-gray-600">{usage.avgResponseTime}</div>
                          </div>
                        </div>
                        <p className="text-sm text-gray-700 mb-2">{usage.purpose}</p>
                        <p className="text-xs text-gray-500 font-mono bg-white px-2 py-1 rounded">
                          📁 {usage.file}
                        </p>
                      </div>
                    ))}
                  </div>
                </div>

                {/* Technical Specifications */}
                <div>
                  <h5 className="text-lg font-bold text-gray-900 mb-3 flex items-center">
                    <svg className="w-5 h-5 mr-2 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10.325 4.317c.426-1.756 2.924-1.756 3.35 0a1.724 1.724 0 002.573 1.066c1.543-.94 3.31.826 2.37 2.37a1.724 1.724 0 001.065 2.572c1.756.426 1.756 2.924 0 3.35a1.724 1.724 0 00-1.066 2.573c.94 1.543-.826 3.31-2.37 2.37a1.724 1.724 0 00-2.572 1.065c-.426 1.756-2.924 1.756-3.35 0a1.724 1.724 0 00-2.573-1.066c-1.543.94-3.31-.826-2.37-2.37a1.724 1.724 0 00-1.065-2.572c-1.756-.426-1.756-2.924 0-3.35a1.724 1.724 0 001.066-2.573c-.94-1.543.826-3.31 2.37-2.37.996.608 2.296.07 2.572-1.065z" />
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                    </svg>
                    Technical Specifications
                  </h5>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <pre className="text-sm text-gray-800 overflow-x-auto">
                      {JSON.stringify(model.specifications, null, 2)}
                    </pre>
                  </div>
                </div>

                {/* Last Updated */}
                <div className="text-sm text-gray-500">
                  <span className="font-semibold">Last Updated:</span> {model.lastUpdated}
                </div>
              </div>
            )}
          </div>
        ))}
      </div>
    </div>
  );

  return (
    <div className="p-6">
      {/* Header with View Switcher */}
      <div className="flex justify-between items-center mb-6">
        <div>
          <h3 className="text-xl font-bold text-gray-900">AI Insights & Models</h3>
          <p className="text-gray-600 mt-1">
            {activeView === 'predictions' 
              ? 'Machine learning predictions and recommendations' 
              : 'Comprehensive AI/ML models used in the application'}
          </p>
        </div>
        <div className="flex items-center space-x-2">
          <button
            onClick={() => setActiveView('models')}
            className={`px-4 py-2 rounded-lg font-medium transition-all ${
              activeView === 'models'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            AI Models
          </button>
          <button
            onClick={() => setActiveView('predictions')}
            className={`px-4 py-2 rounded-lg font-medium transition-all ${
              activeView === 'predictions'
                ? 'bg-blue-600 text-white'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
          >
            Predictions ({predictions?.length || 0})
          </button>
          <button
            onClick={onRefresh}
            className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700"
          >
            Refresh
          </button>
        </div>
      </div>

      {/* Content */}
      {activeView === 'models' ? renderAIModelsView() : (
        <>
          {predictions && predictions.length > 0 ? (
            <div className="grid grid-cols-1 gap-6">
              {predictions.map((prediction) => (
                <div key={prediction.id} className="bg-white border-2 border-purple-200 rounded-lg p-6 hover:border-purple-400 transition-colors">
                  <div className="flex items-start space-x-4">
                    <div className="p-3 bg-purple-100 rounded-lg text-purple-600">
                      {getInsightIcon(prediction.insight_type)}
                    </div>
                    
                    <div className="flex-1">
                      <div className="flex items-center justify-between mb-3">
                        <h4 className="text-lg font-bold text-gray-900">{prediction.title}</h4>
                        <span className={`px-3 py-1 rounded-full text-sm font-semibold ${getImpactBadge(prediction.impact_level)}`}>
                          {prediction.impact_level.toUpperCase()} IMPACT
                        </span>
                      </div>

                      <p className="text-gray-700 mb-4">{prediction.description}</p>

                      <div className="grid grid-cols-2 gap-4 mb-4">
                        <div className="bg-gray-50 p-3 rounded-lg">
                          <p className="text-sm text-gray-600 mb-1">Confidence Score</p>
                          <div className="flex items-center space-x-2">
                            <div className="flex-1 bg-gray-200 rounded-full h-2">
                              <div
                                className="bg-purple-600 h-2 rounded-full transition-all"
                                style={{ width: `${prediction.confidence_score * 100}%` }}
                              />
                            </div>
                            <span className="text-sm font-bold text-purple-600">
                              {(prediction.confidence_score * 100).toFixed(0)}%
                            </span>
                          </div>
                        </div>

                        <div className="bg-gray-50 p-3 rounded-lg">
                          <p className="text-sm text-gray-600 mb-1">Affected Area</p>
                          <p className="text-sm font-semibold text-gray-900">{prediction.affected_area}</p>
                        </div>
                      </div>

                      {prediction.recommendations && prediction.recommendations.length > 0 && (
                        <div className="bg-blue-50 p-4 rounded-lg mb-4">
                          <p className="text-sm font-semibold text-blue-900 mb-2 flex items-center">
                            <svg className="w-4 h-4 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
                            </svg>
                            Recommendations
                          </p>
                          <ul className="space-y-1">
                            {prediction.recommendations.map((rec, idx) => (
                              <li key={idx} className="text-sm text-blue-800 flex items-start">
                                <svg className="w-4 h-4 mr-2 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                                </svg>
                                {rec}
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}

                      {prediction.action_items && prediction.action_items.length > 0 && (
                        <div className="bg-yellow-50 p-4 rounded-lg mb-4">
                          <p className="text-sm font-semibold text-yellow-900 mb-2">Action Items:</p>
                          <ul className="space-y-1">
                            {prediction.action_items.map((item, idx) => (
                              <li key={idx} className="text-sm text-yellow-800 flex items-start">
                                <input type="checkbox" className="mt-1 mr-2" />
                                {item}
                              </li>
                            ))}
                          </ul>
                        </div>
                      )}

                      {prediction.estimated_benefit && (
                        <div className="bg-green-50 p-3 rounded-lg mb-4">
                          <p className="text-sm text-green-900">
                            <span className="font-semibold">Estimated Benefit: </span>
                            {prediction.estimated_benefit}
                          </p>
                        </div>
                      )}

                      <div className="flex items-center justify-between pt-4 border-t border-gray-200">
                        <div className="text-sm text-gray-600">
                          <span className="font-semibold">Model:</span> {prediction.ml_model_used}
                        </div>
                        <button
                          onClick={() => handleAcknowledge(prediction.id)}
                          disabled={acknowledging}
                          className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors disabled:bg-gray-400"
                        >
                          {acknowledging ? 'Acknowledging...' : 'Acknowledge'}
                        </button>
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          ) : (
            <div className="text-center py-12 bg-gray-50 rounded-lg">
              <svg className="w-16 h-16 mx-auto mb-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
              </svg>
              <p className="text-lg font-semibold text-gray-900">No Active Insights</p>
              <p className="text-gray-600 mt-2">AI is analyzing your system patterns</p>
            </div>
          )}
        </>
      )}
    </div>
  );
};

export default PredictionsTab;

import React, { useState, useEffect, useMemo } from 'react';
import { useActivityStream } from '../../hooks/useActivityStream';
import { 
  ACTIVITY_CONFIG, 
  formatActivityDescription, 
  getActivityStyle, 
  formatTimestamp 
} from '../../config/activity.config';

/**
 * Real-time Activity Stream Component
 * Live monitoring of all system activities with WebSocket updates
 */
const RealTimeActivityTab = () => {
  const {
    activities,
    activeUsers,
    statistics,
    connectionStatus,
    isConnected,
    error,
    getFilteredActivities,
    requestStatistics,
  } = useActivityStream();

  // Filter state
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [selectedSeverity, setSelectedSeverity] = useState('all');
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedTimeRange, setSelectedTimeRange] = useState('realtime');

  // View state
  const [autoScroll, setAutoScroll] = useState(true);
  const [showDetails, setShowDetails] = useState(false);

  /**
   * Get filtered activities based on current filters
   */
  const filteredActivities = useMemo(() => {
    const timeRange = ACTIVITY_CONFIG.filters.timeRanges.find(r => r.id === selectedTimeRange);
    
    return getFilteredActivities({
      category: selectedCategory,
      severity: selectedSeverity,
      search: searchTerm,
      minutes: timeRange?.minutes,
    });
  }, [activities, selectedCategory, selectedSeverity, searchTerm, selectedTimeRange, getFilteredActivities]);

  /**
   * Auto-scroll to top when new activities arrive
   */
  useEffect(() => {
    if (autoScroll && filteredActivities.length > 0) {
      const container = document.getElementById('activity-list');
      if (container) {
        container.scrollTop = 0;
      }
    }
  }, [filteredActivities, autoScroll]);

  /**
   * Refresh statistics periodically
   */
  useEffect(() => {
    const interval = setInterval(() => {
      if (isConnected) {
        requestStatistics();
      }
    }, 30000); // Every 30 seconds

    return () => clearInterval(interval);
  }, [isConnected, requestStatistics]);

  /**
   * Connection status indicator
   */
  const ConnectionStatus = () => (
    <div className="flex items-center space-x-2">
      <div className={`w-3 h-3 rounded-full ${
        connectionStatus === 'connected' ? 'bg-green-500 animate-pulse' :
        connectionStatus === 'connecting' ? 'bg-yellow-500 animate-pulse' :
        'bg-red-500'
      }`} />
      <span className="text-sm font-medium text-gray-700">
        {connectionStatus === 'connected' ? 'Live' :
         connectionStatus === 'connecting' ? 'Connecting...' :
         'Disconnected'}
      </span>
      {error && (
        <span className="text-xs text-red-600">({error})</span>
      )}
    </div>
  );

  /**
   * Statistics cards
   */
  const StatisticsPanel = () => (
    <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
      {/* Total Activities (Last Hour) */}
      <div className="bg-gradient-to-br from-blue-50 to-blue-100 rounded-lg p-4 border border-blue-200">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-blue-600">Last Hour</p>
            <p className="text-2xl font-bold text-blue-900">
              {statistics.total_last_hour || 0}
            </p>
          </div>
          <div className="text-3xl">⏱️</div>
        </div>
      </div>

      {/* Total Activities (Last 24h) */}
      <div className="bg-gradient-to-br from-purple-50 to-purple-100 rounded-lg p-4 border border-purple-200">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-purple-600">Last 24 Hours</p>
            <p className="text-2xl font-bold text-purple-900">
              {statistics.total_last_24h || 0}
            </p>
          </div>
          <div className="text-3xl">📊</div>
        </div>
      </div>

      {/* Success Rate */}
      <div className="bg-gradient-to-br from-green-50 to-green-100 rounded-lg p-4 border border-green-200">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-green-600">Success Rate</p>
            <p className="text-2xl font-bold text-green-900">
              {statistics.success_rate?.toFixed(1) || 100}%
            </p>
          </div>
          <div className="text-3xl">✅</div>
        </div>
      </div>

      {/* Active Users */}
      <div className="bg-gradient-to-br from-orange-50 to-orange-100 rounded-lg p-4 border border-orange-200">
        <div className="flex items-center justify-between">
          <div>
            <p className="text-sm font-medium text-orange-600">Active Users</p>
            <p className="text-2xl font-bold text-orange-900">
              {activeUsers.length}
            </p>
          </div>
          <div className="text-3xl">👥</div>
        </div>
      </div>
    </div>
  );

  /**
   * Filters panel
   */
  const FiltersPanel = () => (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mb-6">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        {/* Category Filter */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Category
          </label>
          <select
            value={selectedCategory}
            onChange={(e) => setSelectedCategory(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            {ACTIVITY_CONFIG.categories.map(cat => (
              <option key={cat.id} value={cat.id}>
                {cat.icon} {cat.label}
              </option>
            ))}
          </select>
        </div>

        {/* Severity Filter */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Severity
          </label>
          <select
            value={selectedSeverity}
            onChange={(e) => setSelectedSeverity(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="all">All Severities</option>
            {Object.entries(ACTIVITY_CONFIG.severityLevels).map(([key, level]) => (
              <option key={key} value={key}>
                {level.label}
              </option>
            ))}
          </select>
        </div>

        {/* Time Range Filter */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Time Range
          </label>
          <select
            value={selectedTimeRange}
            onChange={(e) => setSelectedTimeRange(e.target.value)}
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            {ACTIVITY_CONFIG.filters.timeRanges.map(range => (
              <option key={range.id} value={range.id}>
                {range.label}
              </option>
            ))}
          </select>
        </div>

        {/* Search */}
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-2">
            Search
          </label>
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Search activities..."
            className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          />
        </div>
      </div>

      {/* View Options */}
      <div className="flex items-center space-x-4 mt-4 pt-4 border-t border-gray-200">
        <label className="flex items-center space-x-2 cursor-pointer">
          <input
            type="checkbox"
            checked={autoScroll}
            onChange={(e) => setAutoScroll(e.target.checked)}
            className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
          />
          <span className="text-sm text-gray-700">Auto-scroll</span>
        </label>
        
        <label className="flex items-center space-x-2 cursor-pointer">
          <input
            type="checkbox"
            checked={showDetails}
            onChange={(e) => setShowDetails(e.target.checked)}
            className="w-4 h-4 text-blue-600 border-gray-300 rounded focus:ring-blue-500"
          />
          <span className="text-sm text-gray-700">Show details</span>
        </label>

        <div className="flex-1" />
        
        <span className="text-sm text-gray-600">
          Showing {filteredActivities.length} activities
        </span>
      </div>
    </div>
  );

  /**
   * Activity card component
   */
  const ActivityCard = ({ activity }) => {
    const style = getActivityStyle(activity);
    const description = formatActivityDescription(activity);
    const timestamp = formatTimestamp(activity.timestamp);

    return (
      <div className={`
        bg-white rounded-lg shadow-sm border-l-4 p-4 mb-3 
        transition-all duration-300 hover:shadow-md
        ${style.severity.borderClass}
        animate-fade-in
      `}>
        <div className="flex items-start space-x-3">
          {/* Icon */}
          <div className={`
            flex-shrink-0 w-10 h-10 rounded-full 
            flex items-center justify-center text-xl
            ${style.severity.bgClass}
          `}>
            {style.icon}
          </div>

          {/* Content */}
          <div className="flex-1 min-w-0">
            {/* Header */}
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <p className="text-sm font-semibold text-gray-900">
                  {description}
                </p>
                
                {showDetails && activity.details && (
                  <div className="mt-2 text-xs text-gray-600 bg-gray-50 rounded p-2">
                    <pre className="whitespace-pre-wrap overflow-x-auto">
                      {JSON.stringify(activity.details, null, 2)}
                    </pre>
                  </div>
                )}
              </div>
              
              {/* Severity Badge */}
              <span className={`
                ml-2 px-2 py-1 text-xs font-medium rounded-full
                ${style.severity.bgClass} ${style.severity.textClass}
              `}>
                {style.severity.label}
              </span>
            </div>

            {/* Footer */}
            <div className="mt-2 flex items-center space-x-4 text-xs text-gray-500">
              {activity.user_name && (
                <span className="flex items-center space-x-1">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />
                  </svg>
                  <span>{activity.user_name}</span>
                </span>
              )}
              
              {activity.ip_address && showDetails && (
                <span className="flex items-center space-x-1">
                  <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 01-9 9m9-9a9 9 0 00-9-9m9 9H3m9 9a9 9 0 01-9-9m9 9c1.657 0 3-4.03 3-9s-1.343-9-3-9m0 18c-1.657 0-3-4.03-3-9s1.343-9 3-9m-9 9a9 9 0 019-9" />
                  </svg>
                  <span>{activity.ip_address}</span>
                </span>
              )}
              
              <span className="flex items-center space-x-1">
                <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
                <span>{timestamp}</span>
              </span>

              {activity.duration && showDetails && (
                <span className="flex items-center space-x-1">
                  <span>⏱️ {activity.duration}ms</span>
                </span>
              )}
            </div>
          </div>
        </div>
      </div>
    );
  };

  /**
   * Active users sidebar
   */
  const ActiveUsersSidebar = () => (
    <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4">
      <h3 className="text-sm font-semibold text-gray-900 mb-3 flex items-center">
        <span className="w-2 h-2 bg-green-500 rounded-full animate-pulse mr-2" />
        Active Users ({activeUsers.length})
      </h3>
      
      <div className="space-y-2 max-h-96 overflow-y-auto">
        {activeUsers.length === 0 ? (
          <p className="text-sm text-gray-500 italic">No active users</p>
        ) : (
          activeUsers.map((user, index) => (
            <div key={index} className="flex items-center space-x-2 text-sm">
              <div className="w-8 h-8 bg-gradient-to-br from-blue-400 to-purple-500 rounded-full flex items-center justify-center text-white font-semibold">
                {user.name?.charAt(0).toUpperCase() || user.email?.charAt(0).toUpperCase() || '?'}
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-gray-900 font-medium truncate">
                  {user.name || user.email || 'Unknown'}
                </p>
                {user.email && user.name && (
                  <p className="text-xs text-gray-500 truncate">{user.email}</p>
                )}
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="p-6 bg-gray-50 min-h-screen">
      {/* Header */}
      <div className="mb-6 flex items-center justify-between">
        <div>
          <h2 className="text-3xl font-bold text-gray-900 flex items-center">
            <span className="mr-3">📡</span>
            Real-time Activity Stream
          </h2>
          <p className="text-gray-600 mt-1">Live monitoring of all system activities</p>
        </div>
        <ConnectionStatus />
      </div>

      {/* Statistics Panel */}
      <StatisticsPanel />

      {/* Main Content */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Activity Feed */}
        <div className="lg:col-span-3">
          {/* Filters */}
          <FiltersPanel />

          {/* Activity List */}
          <div
            id="activity-list"
            className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 max-h-[calc(100vh-500px)] overflow-y-auto"
          >
            {filteredActivities.length === 0 ? (
              <div className="text-center py-16">
                <div className="text-6xl mb-4">📭</div>
                <h3 className="text-lg font-semibold text-gray-900 mb-2">
                  No activities found
                </h3>
                <p className="text-gray-600">
                  {!isConnected
                    ? 'Connecting to activity stream...'
                    : searchTerm
                    ? 'Try adjusting your search or filters'
                    : 'Activities will appear here in real-time'}
                </p>
              </div>
            ) : (
              <div className="space-y-3">
                {filteredActivities.map((activity) => (
                  <ActivityCard key={activity.id} activity={activity} />
                ))}
              </div>
            )}
          </div>
        </div>

        {/* Sidebar */}
        <div className="lg:col-span-1">
          <ActiveUsersSidebar />
          
          {/* Category Statistics */}
          {statistics.by_category && Object.keys(statistics.by_category).length > 0 && (
            <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-4 mt-6">
              <h3 className="text-sm font-semibold text-gray-900 mb-3">
                Activity by Category
              </h3>
              <div className="space-y-2">
                {Object.entries(statistics.by_category)
                  .sort((a, b) => b[1] - a[1])
                  .slice(0, 8)
                  .map(([category, count]) => {
                    const categoryConfig = ACTIVITY_CONFIG.categories.find(c => c.id === category);
                    return (
                      <div key={category} className="flex items-center justify-between text-sm">
                        <span className="flex items-center space-x-2">
                          <span>{categoryConfig?.icon || '📌'}</span>
                          <span className="text-gray-700 truncate">
                            {categoryConfig?.label || category}
                          </span>
                        </span>
                        <span className="font-semibold text-gray-900">{count}</span>
                      </div>
                    );
                  })}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default RealTimeActivityTab;

/**
 * Real-time Alert Dashboard Component
 * Advanced ML-powered alert monitoring with live updates
 */
import React, { useState, useEffect, useMemo } from 'react';
import { useRealTimeDetection, useSystemMetrics } from '../../hooks/useRealTimeDetection';
import { 
  BellIcon, 
  ExclamationTriangleIcon, 
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
  ChartBarIcon,
  CpuChipIcon,
  SignalIcon
} from '@heroicons/react/24/outline';
import axios from 'axios';
import { API_BASE_URL } from '../../config/api.config';


const SEVERITY_CONFIG = {
  critical: {
    color: 'red',
    bgClass: 'bg-red-100',
    borderClass: 'border-red-500',
    textClass: 'text-red-700',
    icon: ExclamationTriangleIcon,
    label: 'Critical'
  },
  high: {
    color: 'orange',
    bgClass: 'bg-orange-100',
    borderClass: 'border-orange-500',
    textClass: 'text-orange-700',
    icon: ExclamationTriangleIcon,
    label: 'High'
  },
  medium: {
    color: 'yellow',
    bgClass: 'bg-yellow-100',
    borderClass: 'border-yellow-500',
    textClass: 'text-yellow-700',
    icon: BellIcon,
    label: 'Medium'
  },
  low: {
    color: 'blue',
    bgClass: 'bg-blue-100',
    borderClass: 'border-blue-500',
    textClass: 'text-blue-700',
    icon: BellIcon,
    label: 'Low'
  }
};


const RealTimeAlertDashboard = () => {
  const [selectedAlert, setSelectedAlert] = useState(null);
  const [filter, setFilter] = useState('all'); // all, critical, high, new
  const [dashboardStats, setDashboardStats] = useState(null);
  
  // Real-time hooks
  const {
    isConnected,
    alerts,
    metrics,
    lastUpdate,
    error: wsError,
    acknowledgeAlert
  } = useRealTimeDetection({
    autoConnect: true,
    onAlert: (alert) => {
      // Play sound or show notification for critical alerts
      if (alert.severity === 'critical') {
        playAlertSound();
        showBrowserNotification(alert);
      }
    }
  });

  const {
    isConnected: metricsConnected,
    metrics: systemMetrics
  } = useSystemMetrics({ autoConnect: true });

  // Fetch dashboard stats
  useEffect(() => {
    fetchDashboardStats();
    const interval = setInterval(fetchDashboardStats, 300000); // Refresh every 5 min (was 30s)
    return () => clearInterval(interval);
  }, []);

  const fetchDashboardStats = async () => {
    try {
      const token = localStorage.getItem('token');
      const response = await axios.get(
        `${API_BASE_URL}/api/ml-detection/alerts/dashboard_summary/`,
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );
      setDashboardStats(response.data);
    } catch (error) {
      console.error('Failed to fetch dashboard stats:', error);
    }
  };

  // Filter alerts
  const filteredAlerts = useMemo(() => {
    if (filter === 'all') return alerts;
    if (filter === 'new') return alerts.filter((a) => a.status === 'new');
    return alerts.filter((a) => a.severity === filter);
  }, [alerts, filter]);

  // Statistics
  const stats = useMemo(() => {
    return {
      total: alerts.length,
      critical: alerts.filter((a) => a.severity === 'critical').length,
      high: alerts.filter((a) => a.severity === 'high').length,
      new: alerts.filter((a) => a.status === 'new').length,
      acknowledged: alerts.filter((a) => a.status === 'acknowledged').length
    };
  }, [alerts]);

  const handleAcknowledge = async (alertId) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        `${API_BASE_URL}/api/ml-detection/alerts/${alertId}/acknowledge/`,
        {},
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );
      acknowledgeAlert(alertId);
    } catch (error) {
      console.error('Failed to acknowledge alert:', error);
    }
  };

  const handleResolve = async (alertId) => {
    try {
      const token = localStorage.getItem('token');
      await axios.post(
        `${API_BASE_URL}/api/ml-detection/alerts/${alertId}/resolve/`,
        { notes: 'Resolved from dashboard' },
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );
    } catch (error) {
      console.error('Failed to resolve alert:', error);
    }
  };

  const playAlertSound = () => {
    // Play alert sound
    const audio = new Audio('/alert-sound.mp3');
    audio.play().catch((e) => console.log('Audio play failed:', e));
  };

  const showBrowserNotification = (alert) => {
    if ('Notification' in window && Notification.permission === 'granted') {
      new Notification('🚨 Critical Alert', {
        body: alert.title,
        icon: '/logo.png'
      });
    }
  };

  // Request notification permission
  useEffect(() => {
    if ('Notification' in window && Notification.permission === 'default') {
      Notification.requestPermission();
    }
  }, []);

  return (
    <div className="space-y-6">
      {/* Connection Status */}
      <div className="flex items-center justify-between bg-white rounded-lg shadow-sm p-4 border-l-4 border-blue-500">
        <div className="flex items-center space-x-3">
          <div className={`w-3 h-3 rounded-full ${isConnected ? 'bg-green-500 animate-pulse' : 'bg-red-500'}`}></div>
          <div>
            <p className="font-semibold text-gray-900">
              {isConnected ? '🟢 Real-time Detection Active' : '🔴 Disconnected'}
            </p>
            <p className="text-sm text-gray-600">
              {lastUpdate ? `Last update: ${new Date(lastUpdate).toLocaleTimeString()}` : 'No updates yet'}
            </p>
          </div>
        </div>
        
        {wsError && (
          <div className="text-sm text-red-600 bg-red-50 px-3 py-1 rounded">
            {wsError}
          </div>
        )}
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
        <StatCard
          title="Total Alerts"
          value={stats.total}
          icon={BellIcon}
          color="blue"
          subtitle="All time"
        />
        <StatCard
          title="Critical"
          value={stats.critical}
          icon={ExclamationTriangleIcon}
          color="red"
          subtitle="Requires immediate action"
          pulse={stats.critical > 0}
        />
        <StatCard
          title="High Priority"
          value={stats.high}
          icon={ExclamationTriangleIcon}
          color="orange"
          subtitle="Needs attention"
        />
        <StatCard
          title="New Alerts"
          value={stats.new}
          icon={ClockIcon}
          color="purple"
          subtitle="Unacknowledged"
        />
        <StatCard
          title="Acknowledged"
          value={stats.acknowledged}
          icon={CheckCircleIcon}
          color="green"
          subtitle="In progress"
        />
      </div>

      {/* System Metrics */}
      {systemMetrics && (
        <div className="bg-gradient-to-br from-indigo-50 to-purple-50 rounded-lg shadow-sm p-4 border-2 border-indigo-200">
          <div className="flex items-center space-x-2 mb-3">
            <CpuChipIcon className="w-5 h-5 text-indigo-600" />
            <h3 className="font-bold text-gray-900">System Performance</h3>
            <span className={`w-2 h-2 rounded-full ${metricsConnected ? 'bg-green-500 animate-pulse' : 'bg-gray-400'}`}></span>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <MetricBar label="CPU" value={systemMetrics.cpu_usage} max={100} unit="%" />
            <MetricBar label="Memory" value={systemMetrics.memory_usage} max={100} unit="%" />
            <MetricBar label="Disk" value={systemMetrics.disk_usage} max={100} unit="%" />
            <div className="text-center">
              <p className="text-sm text-gray-600">Active Streams</p>
              <p className="text-2xl font-bold text-indigo-600">{systemMetrics.active_streams}</p>
            </div>
          </div>
        </div>
      )}

      {/* ML Detection Metrics */}
      {metrics && (
        <div className="bg-gradient-to-br from-purple-50 to-pink-50 rounded-lg shadow-sm p-4 border-2 border-purple-200">
          <div className="flex items-center space-x-2 mb-3">
            <ChartBarIcon className="w-5 h-5 text-purple-600" />
            <h3 className="font-bold text-gray-900">ML Detection Performance</h3>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div className="text-center">
              <p className="text-sm text-gray-600">Alerts (1h)</p>
              <p className="text-2xl font-bold text-purple-600">{metrics.total_alerts_last_hour}</p>
            </div>
            <div className="text-center">
              <p className="text-sm text-gray-600">Critical (1h)</p>
              <p className="text-2xl font-bold text-red-600">{metrics.critical_alerts_last_hour}</p>
            </div>
            <div className="text-center">
              <p className="text-sm text-gray-600">Accuracy</p>
              <p className="text-2xl font-bold text-green-600">{(metrics.accuracy * 100).toFixed(1)}%</p>
            </div>
            <div className="text-center">
              <p className="text-sm text-gray-600">Precision</p>
              <p className="text-2xl font-bold text-blue-600">{(metrics.precision * 100).toFixed(1)}%</p>
            </div>
          </div>
        </div>
      )}

      {/* Filter Tabs */}
      <div className="bg-white rounded-lg shadow-sm p-2">
        <div className="flex space-x-2">
          {['all', 'critical', 'high', 'new'].map((f) => (
            <button
              key={f}
              onClick={() => setFilter(f)}
              className={`px-4 py-2 rounded-lg font-medium transition-all ${
                filter === f
                  ? 'bg-blue-600 text-white shadow-lg'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {f.charAt(0).toUpperCase() + f.slice(1)}
              {f !== 'all' && (
                <span className="ml-2 px-2 py-0.5 bg-white bg-opacity-20 rounded-full text-xs">
                  {f === 'new' ? stats.new : f === 'critical' ? stats.critical : stats.high}
                </span>
              )}
            </button>
          ))}
        </div>
      </div>

      {/* Alerts List */}
      <div className="space-y-3">
        {filteredAlerts.length === 0 ? (
          <div className="bg-white rounded-lg shadow-sm p-8 text-center">
            <CheckCircleIcon className="w-16 h-16 text-green-500 mx-auto mb-4" />
            <h3 className="text-xl font-bold text-gray-900 mb-2">No Alerts</h3>
            <p className="text-gray-600">All systems operating normally</p>
          </div>
        ) : (
          filteredAlerts.map((alert) => (
            <AlertCard
              key={alert.id}
              alert={alert}
              onAcknowledge={handleAcknowledge}
              onResolve={handleResolve}
              onSelect={setSelectedAlert}
            />
          ))
        )}
      </div>

      {/* Alert Details Modal */}
      {selectedAlert && (
        <AlertDetailsModal
          alert={selectedAlert}
          onClose={() => setSelectedAlert(null)}
          onAcknowledge={handleAcknowledge}
          onResolve={handleResolve}
        />
      )}
    </div>
  );
};


// Sub-components
const StatCard = ({ title, value, icon: Icon, color, subtitle, pulse }) => {
  const colorClasses = {
    blue: 'from-blue-50 to-blue-100 border-blue-200 text-blue-600',
    red: 'from-red-50 to-red-100 border-red-200 text-red-600',
    orange: 'from-orange-50 to-orange-100 border-orange-200 text-orange-600',
    purple: 'from-purple-50 to-purple-100 border-purple-200 text-purple-600',
    green: 'from-green-50 to-green-100 border-green-200 text-green-600'
  };

  return (
    <div className={`bg-gradient-to-br ${colorClasses[color]} rounded-lg shadow-sm p-4 border-2`}>
      <div className="flex items-center justify-between mb-2">
        <Icon className={`w-8 h-8 ${pulse ? 'animate-pulse' : ''}`} />
        <span className={`text-3xl font-bold`}>{value}</span>
      </div>
      <p className="text-sm font-semibold mb-1">{title}</p>
      <p className="text-xs opacity-75">{subtitle}</p>
    </div>
  );
};


const MetricBar = ({ label, value, max, unit }) => {
  const percentage = (value / max) * 100;
  const color = percentage > 80 ? 'bg-red-500' : percentage > 60 ? 'bg-yellow-500' : 'bg-green-500';

  return (
    <div>
      <div className="flex justify-between items-center mb-1">
        <span className="text-sm text-gray-600">{label}</span>
        <span className="text-sm font-bold text-gray-900">{value.toFixed(1)}{unit}</span>
      </div>
      <div className="w-full bg-gray-200 rounded-full h-2">
        <div className={`${color} h-2 rounded-full transition-all duration-500`} style={{ width: `${percentage}%` }}></div>
      </div>
    </div>
  );
};


const AlertCard = ({ alert, onAcknowledge, onResolve, onSelect }) => {
  const config = SEVERITY_CONFIG[alert.severity] || SEVERITY_CONFIG.low;
  const Icon = config.icon;

  return (
    <div
      className={`${config.bgClass} border-l-4 ${config.borderClass} rounded-lg shadow-sm p-4 hover:shadow-md transition-all cursor-pointer`}
      onClick={() => onSelect(alert)}
    >
      <div className="flex items-start justify-between">
        <div className="flex items-start space-x-3 flex-1">
          <Icon className={`w-6 h-6 ${config.textClass} flex-shrink-0 mt-1`} />
          <div className="flex-1">
            <div className="flex items-center space-x-2 mb-1">
              <h4 className="font-bold text-gray-900">{alert.title}</h4>
              <span className={`px-2 py-0.5 ${config.bgClass} ${config.textClass} rounded-full text-xs font-semibold`}>
                {config.label}
              </span>
              {alert.is_critical && (
                <span className="px-2 py-0.5 bg-red-600 text-white rounded-full text-xs font-semibold animate-pulse">
                  CRITICAL
                </span>
              )}
            </div>
            <p className="text-sm text-gray-700 mb-2">{alert.description}</p>
            <div className="flex items-center space-x-4 text-xs text-gray-600">
              <span>🎯 Confidence: {(alert.confidence * 100).toFixed(1)}%</span>
              <span>⏰ {new Date(alert.detected_at).toLocaleTimeString()}</span>
              <span className={`px-2 py-0.5 rounded ${
                alert.status === 'new' ? 'bg-yellow-100 text-yellow-700' :
                alert.status === 'acknowledged' ? 'bg-blue-100 text-blue-700' :
                'bg-green-100 text-green-700'
              }`}>
                {alert.status}
              </span>
            </div>
          </div>
        </div>

        <div className="flex space-x-2 ml-4">
          {alert.status === 'new' && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                onAcknowledge(alert.id);
              }}
              className="px-3 py-1 bg-blue-600 text-white rounded hover:bg-blue-700 transition-colors text-sm font-medium"
            >
              Acknowledge
            </button>
          )}
          {alert.status === 'acknowledged' && (
            <button
              onClick={(e) => {
                e.stopPropagation();
                onResolve(alert.id);
              }}
              className="px-3 py-1 bg-green-600 text-white rounded hover:bg-green-700 transition-colors text-sm font-medium"
            >
              Resolve
            </button>
          )}
        </div>
      </div>
    </div>
  );
};


const AlertDetailsModal = ({ alert, onClose, onAcknowledge, onResolve }) => {
  const config = SEVERITY_CONFIG[alert.severity] || SEVERITY_CONFIG.low;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
      <div className="bg-white rounded-xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
        <div className={`${config.bgClass} border-b-4 ${config.borderClass} p-6`}>
          <div className="flex items-start justify-between">
            <div>
              <h2 className="text-2xl font-bold text-gray-900 mb-2">{alert.title}</h2>
              <div className="flex items-center space-x-2">
                <span className={`px-3 py-1 ${config.bgClass} ${config.textClass} rounded-full text-sm font-semibold`}>
                  {config.label}
                </span>
                <span className="text-sm text-gray-600">
                  {new Date(alert.detected_at).toLocaleString()}
                </span>
              </div>
            </div>
            <button
              onClick={onClose}
              className="text-gray-400 hover:text-gray-600 transition-colors"
            >
              <XCircleIcon className="w-8 h-8" />
            </button>
          </div>
        </div>

        <div className="p-6 space-y-4">
          <div>
            <h3 className="font-bold text-gray-900 mb-2">Description</h3>
            <p className="text-gray-700">{alert.description}</p>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <h3 className="font-bold text-gray-900 mb-2">Confidence</h3>
              <p className="text-2xl font-bold text-blue-600">{(alert.confidence * 100).toFixed(1)}%</p>
            </div>
            <div>
              <h3 className="font-bold text-gray-900 mb-2">Status</h3>
              <p className="text-lg font-semibold text-gray-700 capitalize">{alert.status}</p>
            </div>
          </div>

          <div className="flex space-x-3">
            {alert.status === 'new' && (
              <button
                onClick={() => {
                  onAcknowledge(alert.id);
                  onClose();
                }}
                className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors font-medium"
              >
                Acknowledge Alert
              </button>
            )}
            {alert.status === 'acknowledged' && (
              <button
                onClick={() => {
                  onResolve(alert.id);
                  onClose();
                }}
                className="flex-1 px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors font-medium"
              >
                Resolve Alert
              </button>
            )}
            <button
              onClick={onClose}
              className="flex-1 px-4 py-2 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors font-medium"
            >
              Close
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};


export default RealTimeAlertDashboard;

import { radaiPrompt, radaiConfirm, radaiAlert } from '../../services/radaiDialog'
