const SystemHealthTab = ({ healthData }) => {
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [refreshInterval, setRefreshInterval] = useState(30);
  const [simulatedMetrics, setSimulatedMetrics] = useState({});
  const [selectedComponent, setSelectedComponent] = useState(null);

  // Simulate real-time metrics
  useEffect(() => {
    const generateMetrics = () => {
      const metrics = {};
      RESOURCE_METRICS_CONFIG.forEach(metric => {
        const baseValue = 45;
        const variation = Math.random() * 30;
        metrics[metric.id] = Math.min(100, baseValue + variation);
      });
      
      // Component-specific metrics
      SYSTEM_COMPONENTS_CONFIG.forEach(component => {
        metrics[component.id] = {
          status: Math.random() > 0.1 ? 'healthy' : Math.random() > 0.5 ? 'degraded' : 'critical',
          responseTime: Math.floor(Math.random() * 200 + 50),
          uptime: 99.8 + Math.random() * 0.2,
          requests: Math.floor(Math.random() * 1000 + 500)
        };
      });
      
      setSimulatedMetrics(metrics);
    };

    generateMetrics();
    
    if (autoRefresh) {
      const interval = setInterval(generateMetrics, refreshInterval * 1000);
      return () => clearInterval(interval);
    }
  }, [autoRefresh, refreshInterval]);

  const getStatusColor = (status) => {
    const config = HEALTH_STATUS_CONFIG[status] || HEALTH_STATUS_CONFIG.unknown;
    return `${config.textClass} ${config.bgClass}`;
  };

  const getStatusIcon = (status) => {
    const config = HEALTH_STATUS_CONFIG[status] || HEALTH_STATUS_CONFIG.unknown;
    return (
      <svg className={`w-6 h-6 ${config.textClass}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d={config.icon} />
      </svg>
    );
  };

  const getOverallHealth = () => {
    if (!simulatedMetrics || Object.keys(simulatedMetrics).length === 0) return 100;
    
    const componentStatuses = SYSTEM_COMPONENTS_CONFIG.map(c => 
      simulatedMetrics[c.id]?.status || 'healthy'
    );
    
    const healthyCount = componentStatuses.filter(s => s === 'healthy').length;
    const degradedCount = componentStatuses.filter(s => s === 'degraded').length;
    
    return Math.round((healthyCount * 100 + degradedCount * 50) / componentStatuses.length);
  };

  const getStatusFromScore = (score) => {
    if (score >= 90) return 'healthy';
    if (score >= 60) return 'degraded';
    return 'critical';
  };

  const renderProgressBar = (value, config) => {
    const percentage = Math.min(100, Math.max(0, value));
    let barColor = config.color;
    
    if (percentage >= config.criticalThreshold) {
      barColor = '#EF4444'; // red
    } else if (percentage >= config.warningThreshold) {
      barColor = '#F59E0B'; // yellow
    }

    return (
      <div className="relative">
        <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
          <div
            className="h-full rounded-full transition-all duration-500"
            style={{
              width: `${percentage}%`,
              backgroundColor: barColor
            }}
          />
        </div>
        <span className="absolute right-0 top-4 text-xs font-semibold text-gray-700">
          {percentage.toFixed(1)}{config.unit}
        </span>
      </div>
    );
  };

  const overallHealth = getOverallHealth();
  const overallStatus = getStatusFromScore(overallHealth);

  if (!simulatedMetrics || Object.keys(simulatedMetrics).length === 0) {
    return (
      <div className="p-6">
        <div className="text-center py-12">
          <svg className="w-16 h-16 mx-auto mb-4 text-blue-600 animate-spin" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
          <p className="text-gray-600 font-medium">Initializing system health monitoring...</p>
          <p className="text-sm text-gray-500 mt-2">Real-time metrics loading</p>
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 space-y-6">
      {/* Header with Controls */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-2xl font-bold text-gray-900">System Health Monitoring</h3>
          <p className="text-gray-600 mt-1">Real-time status of all system components</p>
        </div>
        
        <div className="flex items-center space-x-3">
          {/* Auto Refresh Toggle */}
          <div className="flex items-center space-x-2 bg-white px-4 py-2 rounded-lg border-2 border-gray-200">
            <span className="text-sm font-medium text-gray-700">Auto-refresh:</span>
            <button
              onClick={() => setAutoRefresh(!autoRefresh)}
              className={`relative inline-flex h-6 w-11 items-center rounded-full transition-colors ${
                autoRefresh ? 'bg-blue-600' : 'bg-gray-300'
              }`}
            >
              <span
                className={`inline-block h-4 w-4 transform rounded-full bg-white transition-transform ${
                  autoRefresh ? 'translate-x-6' : 'translate-x-1'
                }`}
              />
            </button>
          </div>

          {/* Refresh Interval Selector */}
          {autoRefresh && (
            <select
              value={refreshInterval}
              onChange={(e) => setRefreshInterval(Number(e.target.value))}
              className="px-3 py-2 bg-white border-2 border-gray-200 rounded-lg text-sm font-medium text-gray-700"
            >
              <option value={10}>Every 10s</option>
              <option value={30}>Every 30s</option>
              <option value={60}>Every 60s</option>
            </select>
          )}

          {/* Manual Refresh Button */}
          <button
            onClick={() => setSimulatedMetrics(prev => ({ ...prev }))}
            className="px-4 py-2 bg-gradient-to-r from-blue-500 to-purple-600 text-white rounded-lg font-medium hover:shadow-lg transition-all"
          >
            🔄 Refresh
          </button>
        </div>
      </div>

      {/* Overall Health Score */}
      <div className="bg-gradient-to-br from-blue-500 via-purple-600 to-pink-500 rounded-xl p-8 text-white shadow-xl">
        <div className="flex items-center justify-between">
          <div className="flex-1">
            <h4 className="text-lg font-semibold mb-2 opacity-90">Overall System Health</h4>
            <p className="text-4xl font-bold mb-2">{overallHealth}%</p>
            <div className="flex items-center space-x-3">
              <span className={`inline-block px-4 py-1 rounded-full text-sm font-bold ${
                HEALTH_STATUS_CONFIG[overallStatus].bgClass
              } ${HEALTH_STATUS_CONFIG[overallStatus].textClass}`}>
                {HEALTH_STATUS_CONFIG[overallStatus].label.toUpperCase()}
              </span>
              <span className="text-sm opacity-90">
                All systems {overallHealth >= 90 ? 'operational' : overallHealth >= 60 ? 'partially operational' : 'experiencing issues'}
              </span>
            </div>
          </div>
          
          {/* Circular Progress */}
          <div className="relative w-32 h-32">
            <svg className="transform -rotate-90 w-32 h-32">
              <circle
                cx="64"
                cy="64"
                r="56"
                stroke="rgba(255,255,255,0.2)"
                strokeWidth="10"
                fill="none"
              />
              <circle
                cx="64"
                cy="64"
                r="56"
                stroke="white"
                strokeWidth="10"
                fill="none"
                strokeDasharray={`${2 * Math.PI * 56}`}
                strokeDashoffset={`${2 * Math.PI * 56 * (1 - overallHealth / 100)}`}
                strokeLinecap="round"
                className="transition-all duration-1000"
              />
            </svg>
            <div className="absolute inset-0 flex items-center justify-center">
              <div className="text-center">
                <div className="text-3xl font-bold">{overallHealth}</div>
                <div className="text-xs opacity-75">Score</div>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Resource Metrics */}
      <div>
        <h4 className="text-lg font-bold text-gray-900 mb-4">📊 Resource Utilization</h4>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          {RESOURCE_METRICS_CONFIG.map(metric => {
            const value = simulatedMetrics[metric.id] || 0;
            return (
              <div key={metric.id} className="bg-white rounded-xl p-5 border-2 border-gray-200 shadow hover:shadow-lg transition-all">
                <div className="flex items-center justify-between mb-3">
                  <span className="text-2xl">{metric.icon}</span>
                  <span className="text-sm font-semibold text-gray-600">{metric.name}</span>
                </div>
                <div className="mb-2">
                  {renderProgressBar(value, metric)}
                </div>
                <div className="flex items-center justify-between mt-4 text-xs">
                  <span className="text-gray-500">
                    {value < metric.warningThreshold ? '✅ Normal' : value < metric.criticalThreshold ? '⚠️ Warning' : '🔴 Critical'}
                  </span>
                  <span className="font-bold" style={{ color: metric.color }}>
                    {value.toFixed(1)}{metric.unit}
                  </span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* System Components Status */}
      <div>
        <h4 className="text-lg font-bold text-gray-900 mb-4">⚙️ System Components</h4>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
          {SYSTEM_COMPONENTS_CONFIG.map(component => {
            const componentData = simulatedMetrics[component.id] || {};
            const status = componentData.status || 'healthy';
            const statusConfig = HEALTH_STATUS_CONFIG[status];

            return (
              <div
                key={component.id}
                className={`bg-white rounded-xl p-5 border-2 ${statusConfig.borderClass} shadow hover:shadow-lg transition-all cursor-pointer ${
                  selectedComponent === component.id ? 'ring-4 ring-blue-300' : ''
                }`}
                onClick={() => setSelectedComponent(selectedComponent === component.id ? null : component.id)}
              >
                <div className="flex items-center justify-between mb-3">
                  <div className="flex items-center space-x-3">
                    <span className="text-3xl">{component.icon}</span>
                    <div>
                      <h5 className="font-bold text-gray-900">{component.name}</h5>
                      <p className="text-xs text-gray-500">{component.description}</p>
                    </div>
                  </div>
                  {getStatusIcon(status)}
                </div>

                <div className="space-y-2">
                  <span className={`inline-block px-3 py-1 rounded-full text-xs font-bold ${statusConfig.bgClass} ${statusConfig.textClass}`}>
                    {statusConfig.label.toUpperCase()}
                  </span>

                  {/* Metrics */}
                  <div className="grid grid-cols-2 gap-2 mt-3 pt-3 border-t-2 border-gray-100">
                    <div>
                      <p className="text-xs text-gray-500">Response Time</p>
                      <p className="text-sm font-bold text-gray-900">{componentData.responseTime}ms</p>
                    </div>
                    <div>
                      <p className="text-xs text-gray-500">Uptime</p>
                      <p className="text-sm font-bold text-gray-900">{componentData.uptime?.toFixed(2)}%</p>
                    </div>
                    <div className="col-span-2">
                      <p className="text-xs text-gray-500">Requests/min</p>
                      <p className="text-sm font-bold text-gray-900">{componentData.requests}</p>
                    </div>
                  </div>

                  {/* Expanded Details */}
                  {selectedComponent === component.id && (
                    <div className="mt-4 p-3 bg-gray-50 rounded-lg border-2 border-gray-200 animate-fadeIn">
                      <p className="text-xs font-semibold text-gray-700 mb-2">Detailed Metrics</p>
                      <div className="space-y-1 text-xs">
                        <div className="flex justify-between">
                          <span className="text-gray-600">Category:</span>
                          <span className="font-semibold text-gray-900 capitalize">{component.category}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gray-600">Critical Threshold:</span>
                          <span className="font-semibold text-gray-900">{component.criticalThreshold}%</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-gray-600">Last Check:</span>
                          <span className="font-semibold text-gray-900">{new Date().toLocaleTimeString()}</span>
                        </div>
                      </div>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
      {/* Performance Insights */}
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Quick Stats */}
        <div className="bg-gradient-to-br from-green-50 to-emerald-50 rounded-xl p-6 border-2 border-green-200">
          <h4 className="text-lg font-bold text-gray-900 mb-4 flex items-center">
            <svg className="w-5 h-5 mr-2 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 7h8m0 0v8m0-8l-8 8-4-4-6 6" />
            </svg>
            Performance Insights
          </h4>
          <div className="space-y-3">
            <div className="flex justify-between items-center p-3 bg-white rounded-lg">
              <span className="text-sm text-gray-700">✅ Components Healthy</span>
              <span className="font-bold text-green-600">
                {SYSTEM_COMPONENTS_CONFIG.filter(c => (simulatedMetrics[c.id]?.status === 'healthy')).length}/{SYSTEM_COMPONENTS_CONFIG.length}
              </span>
            </div>
            <div className="flex justify-between items-center p-3 bg-white rounded-lg">
              <span className="text-sm text-gray-700">⚡ Avg Response Time</span>
              <span className="font-bold text-blue-600">
                {Math.round(SYSTEM_COMPONENTS_CONFIG.reduce((sum, c) => sum + (simulatedMetrics[c.id]?.responseTime || 0), 0) / SYSTEM_COMPONENTS_CONFIG.length)}ms
              </span>
            </div>
            <div className="flex justify-between items-center p-3 bg-white rounded-lg">
              <span className="text-sm text-gray-700">🎯 Avg Uptime</span>
              <span className="font-bold text-purple-600">
                {(SYSTEM_COMPONENTS_CONFIG.reduce((sum, c) => sum + (simulatedMetrics[c.id]?.uptime || 0), 0) / SYSTEM_COMPONENTS_CONFIG.length).toFixed(2)}%
              </span>
            </div>
            <div className="flex justify-between items-center p-3 bg-white rounded-lg">
              <span className="text-sm text-gray-700">📊 Total Requests</span>
              <span className="font-bold text-orange-600">
                {SYSTEM_COMPONENTS_CONFIG.reduce((sum, c) => sum + (simulatedMetrics[c.id]?.requests || 0), 0).toLocaleString()}/min
              </span>
            </div>
          </div>
        </div>

        {/* Recommendations */}
        <div className="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-xl p-6 border-2 border-blue-200">
          <h4 className="text-lg font-bold text-gray-900 mb-4 flex items-center">
            <svg className="w-5 h-5 mr-2 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
            </svg>
            AI Recommendations
          </h4>
          <div className="space-y-2">
            {(() => {
              const recommendations = [];
              
              RESOURCE_METRICS_CONFIG.forEach(metric => {
                const value = simulatedMetrics[metric.id] || 0;
                if (value >= metric.criticalThreshold) {
                  recommendations.push({
                    type: 'critical',
                    message: `${metric.name} is at ${value.toFixed(0)}%. Consider scaling resources immediately.`,
                    icon: '🔴'
                  });
                } else if (value >= metric.warningThreshold) {
                  recommendations.push({
                    type: 'warning',
                    message: `${metric.name} approaching threshold at ${value.toFixed(0)}%. Monitor closely.`,
                    icon: '⚠️'
                  });
                }
              });

              SYSTEM_COMPONENTS_CONFIG.forEach(component => {
                const status = simulatedMetrics[component.id]?.status;
                if (status === 'degraded') {
                  recommendations.push({
                    type: 'warning',
                    message: `${component.name} is degraded. Review logs for details.`,
                    icon: '⚠️'
                  });
                } else if (status === 'critical') {
                  recommendations.push({
                    type: 'critical',
                    message: `${component.name} is critical! Immediate action required.`,
                    icon: '🔴'
                  });
                }
              });

              if (recommendations.length === 0) {
                recommendations.push({
                  type: 'success',
                  message: 'All systems operating within normal parameters.',
                  icon: '✅'
                });
                recommendations.push({
                  type: 'info',
                  message: 'Consider implementing automated backup schedules.',
                  icon: '💡'
                });
                recommendations.push({
                  type: 'info',
                  message: 'Review security patches and updates weekly.',
                  icon: '🔒'
                });
              }

              return recommendations.slice(0, 5).map((rec, idx) => (
                <div
                  key={idx}
                  className={`p-3 rounded-lg text-sm flex items-start space-x-2 ${
                    rec.type === 'critical' ? 'bg-red-100 border-2 border-red-300' :
                    rec.type === 'warning' ? 'bg-yellow-100 border-2 border-yellow-300' :
                    rec.type === 'success' ? 'bg-green-100 border-2 border-green-300' :
                    'bg-white border-2 border-blue-200'
                  }`}
                >
                  <span className="text-lg">{rec.icon}</span>
                  <span className={`flex-1 ${
                    rec.type === 'critical' ? 'text-red-800' :
                    rec.type === 'warning' ? 'text-yellow-800' :
                    rec.type === 'success' ? 'text-green-800' :
                    'text-blue-800'
                  }`}>
                    {rec.message}
                  </span>
                </div>
              ));
            })()}
          </div>
        </div>
      </div>

      {/* System Status Timeline */}
      <div className="bg-white rounded-xl p-6 border-2 border-gray-200 shadow">
        <h4 className="text-lg font-bold text-gray-900 mb-4">📅 System Status History</h4>
        <div className="flex items-center space-x-2 overflow-x-auto pb-2">
          {Array.from({ length: 24 }, (_, i) => {
            const health = 85 + Math.random() * 15;
            const status = getStatusFromScore(health);
            const statusConfig = HEALTH_STATUS_CONFIG[status];
            
            return (
              <div
                key={i}
                className="flex-shrink-0 text-center"
                title={`${23 - i} hours ago: ${health.toFixed(0)}%`}
              >
                <div
                  className={`w-8 h-16 rounded ${statusConfig.bgClass} border-2 ${statusConfig.borderClass}`}
                  style={{ height: `${health * 0.6}px` }}
                />
                <p className="text-xs text-gray-500 mt-1">-{23 - i}h</p>
              </div>
            );
          })}
        </div>
        <div className="flex items-center justify-center space-x-4 mt-4 text-xs">
          <div className="flex items-center space-x-1">
            <div className="w-3 h-3 rounded bg-green-100 border-2 border-green-200" />
            <span className="text-gray-600">Healthy</span>
          </div>
          <div className="flex items-center space-x-1">
            <div className="w-3 h-3 rounded bg-yellow-100 border-2 border-yellow-200" />
            <span className="text-gray-600">Degraded</span>
          </div>
          <div className="flex items-center space-x-1">
            <div className="w-3 h-3 rounded bg-red-100 border-2 border-red-200" />
            <span className="text-gray-600">Critical</span>
          </div>
        </div>
      </div>

      {/* Footer */}
      <div className="text-center text-sm text-gray-500 bg-gray-50 rounded-lg p-4">
        <p>
          🕐 Last updated: {new Date().toLocaleString()} • 
          {autoRefresh ? ` Auto-refreshing every ${refreshInterval}s` : ' Auto-refresh disabled'} • 
          Monitoring {SYSTEM_COMPONENTS_CONFIG.length} components
        </p>
      </div>
    </div>
  );
};

export default SystemHealthTab;

import { useEffect, useRef, useState } from 'react'
import { CalendarDaysIcon, CheckIcon, ClockIcon, DocumentTextIcon, ArrowRightIcon, UserIcon, PrinterIcon } from '@heroicons/react/24/outline'
import { printLeaveRequest } from './printLeaveRequest'
import apiClient from '../../services/api.service'

export const leaveError = error => {
  const data = error?.response?.data
  if (!data) return error.message || 'The request could not be completed.'
  return typeof data === 'string' ? data : Object.values(data).flat().join(' ')
}

export default function LeaveApprovalReview({ requestId, onClose, onUpdated, page = false }) {
  const dialog = useRef(null)
  const [request, setRequest] = useState(null)
  const [error, setError] = useState('')
  const [note, setNote] = useState('')
  const [saving, setSaving] = useState(false)
  const [printing, setPrinting] = useState(false)
  const [failedPhoto, setFailedPhoto] = useState(null)
  useEffect(() => {
    let active = true
    if (!page) dialog.current?.showModal()
    setRequest(null)
    setError('')
    setNote('')
    apiClient.get(`/payroll/leave-requests/${requestId}/`).then(({ data }) => {
      if (active) setRequest(data)
    }).catch(err => { if (active) setError(leaveError(err)) })
    return () => { active = false }
  }, [requestId, page])
  const decide = async action => {
    if (saving) return
    if (action === 'reject' && !note.trim()) { setError('Please enter a rejection reason.'); return }
    setSaving(true)
    setError('')
    try {
      const endpoint = request.status === 'PENDING' && request.review_stage !== 'hr_review' ? `rm-${action}` : action
      const { data } = await apiClient.post(`/payroll/leave-requests/${requestId}/${endpoint}/`, { note })
      setRequest(data)
      onUpdated()
    } catch (err) {
      setError(leaveError(err))
      // Refresh stale approval rights after another approver acts.
      apiClient.get(`/payroll/leave-requests/${requestId}/`).then(({ data }) => setRequest(data)).catch(() => {})
      onUpdated()
    } finally { setSaving(false) }
  }
  const canPrint = request?.status === 'APPROVED' && (!request.workflow_status || request.workflow_status === 'approved')
  const print = async () => {
    if (!canPrint || saving || printing) return
    setPrinting(true)
    try { await printLeaveRequest(dialog.current) }
    catch (err) { setError(err.message || 'Unable to print this request.') }
    finally { setPrinting(false) }
  }
  const Container = page ? 'section' : 'dialog'
  const status = request?.status
  const directHR = status === 'PENDING' && request?.review_stage === 'hr_review'
  const pending = ['PENDING', 'RM_APPROVED'].includes(status)
  const declined = ['RM_REJECTED', 'REJECTED'].includes(status)
  const statusLabel = directHR ? 'Awaiting HR' : ({ PENDING: 'Awaiting manager', RM_APPROVED: 'Awaiting HR', APPROVED: 'Approved', RM_REJECTED: 'Declined by manager', REJECTED: 'Declined by HR', CANCELLED: 'Cancelled' })[status] || request?.status_display
  const statusStyle = declined ? 'border-rose-200 bg-rose-50 text-rose-700' : status === 'APPROVED' ? 'border-emerald-200 bg-emerald-50 text-emerald-700' : pending ? 'border-amber-200 bg-amber-50 text-amber-800' : 'border-slate-200 bg-slate-50 text-slate-600'
  const date = (value, time = false) => {
    if (!value) return 'Not recorded'
    const parsed = new Date(time ? value : `${value.slice(0, 10)}T12:00:00`)
    return Number.isNaN(parsed.getTime()) ? 'Not recorded' : parsed.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric', ...(time ? { hour: '2-digit', minute: '2-digit' } : {}) })
  }
  const managerDone = Boolean(request?.rm_reviewed_at) || ['RM_APPROVED', 'APPROVED', 'REJECTED'].includes(status)
  const steps = request ? [
    { title: 'Request submitted', detail: request.employee_name, at: request.created_at, complete: true },
    { title: 'Manager review', detail: request.rm_reviewed_by_name || request.line_manager_name || (directHR ? 'No manager assigned' : 'Manager not available'), at: request.rm_reviewed_at, note: request.rm_note, complete: managerDone && status !== 'RM_REJECTED', rejected: status === 'RM_REJECTED', active: status === 'PENDING' && !directHR, skipped: directHR, label: status === 'PENDING' && !directHR ? 'Awaiting review' : null },
    { title: 'HR approval', detail: request.reviewed_by_name || (status === 'PENDING' && !directHR ? 'After manager approval' : status === 'RM_APPROVED' ? 'Awaiting review' : 'No pending action'), at: request.reviewed_at, note: request.reviewer_note, complete: status === 'APPROVED', rejected: status === 'REJECTED', active: status === 'RM_APPROVED' || directHR },
  ] : []
  return (
    <Container ref={dialog} onCancel={event => { event.preventDefault(); if (!saving) onClose() }} className={`${page ? 'w-full' : 'm-auto w-[min(94vw,960px)]'} overflow-hidden rounded-2xl border border-slate-200 bg-white p-0 text-slate-900 shadow-sm backdrop:bg-slate-950/40`} aria-labelledby="leave-review-title">
      <header className="flex flex-wrap items-center justify-between gap-3 border-b border-slate-200 bg-gradient-to-r from-indigo-50/60 via-white to-white px-6 py-4">
        <div className="flex items-center gap-3"><span className="rounded-lg border border-indigo-100 bg-white p-2 text-indigo-600"><CalendarDaysIcon className="h-5 w-5" /></span><div><h2 id="leave-review-title" className="text-base font-semibold">Leave request</h2><p className="mt-0.5 text-xs text-slate-500">Employee leave & approval</p></div></div>
        <div className="flex items-center gap-2"><button type="button" disabled={!canPrint || saving || printing} onClick={print} title={canPrint ? 'Print selected leave request' : 'Available after all required approvals are complete'} className="inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm font-medium text-slate-600 hover:border-indigo-300 hover:text-indigo-700 focus-visible:outline-indigo-600 disabled:cursor-not-allowed disabled:opacity-40"><PrinterIcon className="h-4 w-4" />{printing ? 'Preparing...' : 'Print'}</button>{!page && <button type="button" disabled={saving} onClick={onClose} className="rounded-lg px-3 py-2 text-sm text-slate-600">Close</button>}</div>
      </header>
      <div className={page ? '' : 'max-h-[75vh] overflow-y-auto'}>
        {error && <p role="alert" className="m-5 rounded-lg border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800">{error}</p>}
        {!request && !error && <p role="status" className="p-8 text-sm text-slate-500">Loading request...</p>}
        {request && <>
          <div className="flex flex-wrap items-center justify-between gap-4 px-6 py-6">
            <div className="flex min-w-0 items-center gap-4">{request.employee_photo_url && failedPhoto !== request.employee_photo_url ? <img src={request.employee_photo_url} alt={`${request.employee_name || 'Employee'} profile`} onError={() => setFailedPhoto(request.employee_photo_url)} className="h-12 w-12 shrink-0 rounded-xl object-cover" /> : <div aria-hidden="true" className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-indigo-100 text-lg font-semibold text-indigo-700">{(request.employee_name || 'Employee').split(' ').filter(Boolean).slice(0, 2).map(word => word[0]).join('')}</div>}<div className="min-w-0"><h3 className="break-words text-xl font-semibold tracking-tight">{request.employee_name || 'Employee'}</h3><p className="mt-1 text-sm text-slate-500">{[request.employee_code, request.department].filter(Boolean).join(' / ') || 'Leave application'}</p></div></div>
            <span className={`inline-flex items-center gap-2 rounded-full border px-3 py-1.5 text-xs font-medium ${statusStyle}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{statusLabel}</span>
          </div>
          <div className="mx-6 mb-6 grid grid-cols-1 divide-y divide-indigo-100 overflow-hidden rounded-xl border border-indigo-100 bg-indigo-50/40 sm:grid-cols-[1fr_1.6fr_0.8fr] sm:divide-x sm:divide-y-0">
            <div className="px-4 py-4"><p className="text-xs text-slate-500">Leave type</p><p className="mt-2 text-sm font-semibold">{request.leave_type_detail?.name || 'Leave'}</p></div>
            <div className="px-4 py-4"><p className="text-xs text-slate-500">Requested dates</p><p className="mt-2 flex flex-wrap items-center gap-2 text-sm font-semibold">{date(request.start_date)}<ArrowRightIcon aria-hidden="true" className="h-4 w-4 text-indigo-400" />{date(request.end_date)}</p></div>
            <div className="px-4 py-3"><p className="text-xs text-slate-500">Duration</p><p className="mt-1 text-2xl font-semibold text-indigo-700">{Number(request.days_requested)} <span className="text-sm font-normal text-slate-600">{Number(request.days_requested) === 1 ? 'day' : 'days'}</span></p>{request.half_day && <p className="text-xs text-indigo-600">Half-day request</p>}</div>
          </div>
          <div className={`grid border-t border-slate-100 ${page ? 'lg:grid-cols-[minmax(0,1.5fr)_minmax(300px,1fr)]' : 'md:grid-cols-2'}`}>
            <section className="min-w-0 space-y-6 p-6" aria-label="Request details">
              <h4 className="flex items-center gap-2 text-sm font-semibold"><DocumentTextIcon className="h-4 w-4 text-indigo-500" />Request details</h4>
              <dl className="grid grid-cols-1 gap-x-6 gap-y-5 sm:grid-cols-2 text-sm">
                {[
                  ['Manager', request.line_manager_name || (directHR ? 'No manager assigned' : 'Manager not available')],
                  ['Substitute', request.substitute_employee_name || request.substitute_name || 'Not provided'],
                  ['Contact during leave', request.contact_number || 'Not provided'],
                  ['Submitted on', date(request.created_at, true)],
                ].map(([label, value]) => <div key={label}><dt className="text-xs text-slate-500">{label}</dt><dd className="mt-1.5 break-words font-medium text-slate-700">{value}</dd></div>)}
              </dl>
              <div className="border-t border-slate-100 pt-5"><h4 className="text-xs font-medium text-slate-500">Reason for leave</h4><p className="mt-2 whitespace-pre-wrap break-words text-sm leading-6 text-slate-700">{request.reason || 'No reason provided.'}</p></div>
              {request.attachment && <a className="inline-flex items-center gap-2 rounded-lg border border-indigo-100 bg-indigo-50 px-3 py-2 text-sm font-medium text-indigo-700 hover:bg-indigo-100" href={request.attachment} target="_blank" rel="noreferrer"><DocumentTextIcon className="h-4 w-4" />View supporting document</a>}
            </section>
            <aside className="border-t border-slate-100 bg-slate-50/70 p-6 lg:border-l lg:border-t-0">
              <h4 className="flex items-center gap-2 text-sm font-semibold"><ClockIcon className="h-4 w-4 text-indigo-500" />Approval progress</h4>
              <ol className="mt-5" aria-label="Approval history">{steps.map((step, index) => <li key={step.title} className="relative flex gap-3 pb-5 last:pb-0">
                {index < steps.length - 1 && <span aria-hidden="true" className="absolute bottom-0 left-3.5 top-7 w-px bg-slate-200" />}
                <span aria-hidden="true" className={`relative flex h-7 w-7 shrink-0 items-center justify-center rounded-full border text-xs font-semibold ${step.rejected ? 'border-rose-200 bg-rose-50 text-rose-600' : step.complete ? 'border-emerald-200 bg-emerald-50 text-emerald-600' : step.active ? 'border-indigo-200 bg-indigo-100 text-indigo-700' : 'border-slate-200 bg-white text-slate-400'}`}>{step.complete ? <CheckIcon className="h-4 w-4" /> : step.rejected ? '!' : index + 1}</span>
                <div className="min-w-0 pt-0.5"><p className="text-sm font-medium">{step.title}<span className="ml-2 text-xs font-normal text-slate-500">{step.skipped ? 'Not required' : step.rejected ? 'Declined' : step.complete ? 'Complete' : step.active ? 'Current step' : pending ? 'Waiting' : 'Not completed'}</span></p><p className="mt-1 break-words text-xs text-slate-500">{step.detail}{step.label ? ` / ${step.label}` : ''}</p>{step.at && <p className="mt-1 text-xs text-slate-400">{date(step.at, true)}</p>}{step.note && <p className="mt-2 whitespace-pre-wrap break-words rounded-lg border border-slate-200 bg-white p-2 text-xs text-slate-600">{step.note}</p>}</div>
              </li>)}</ol>
            </aside>
          </div>
          <footer className="border-t border-slate-200 bg-white p-6">
            {request.can_review ? <div className="space-y-4"><div><h4 className="text-sm font-semibold">Your decision</h4><p className="mt-1 text-xs text-slate-500">{status === 'PENDING' && !directHR ? 'Your approval sends this request to HR for the final decision.' : 'Your approval completes the leave approval process.'}</p></div><label className="block text-sm font-medium text-slate-700">Comment <span className="font-normal text-slate-500">(required to reject)</span><textarea value={note} onChange={event => setNote(event.target.value)} disabled={saving} placeholder="Add a comment for the employee..." className="mt-2 w-full rounded-lg border border-slate-200 bg-slate-50/50 p-3 text-sm outline-none focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100" rows={3} /></label><div className="flex flex-wrap justify-end gap-3"><button type="button" disabled={saving} onClick={() => decide('reject')} className="rounded-lg border border-rose-200 px-4 py-2.5 text-sm font-medium text-rose-700 hover:bg-rose-50 disabled:opacity-50">Reject</button><button type="button" disabled={saving} onClick={() => decide('approve')} className="rounded-lg bg-indigo-700 px-5 py-2.5 text-sm font-medium text-white shadow-sm hover:bg-indigo-800 disabled:opacity-50">{saving ? 'Saving...' : status === 'PENDING' && !directHR ? 'Approve and send to HR' : 'Approve leave'}</button></div></div> : <div className="flex items-start gap-3 text-sm"><UserIcon className="mt-0.5 h-5 w-5 shrink-0 text-indigo-500" /><div><p className="font-medium text-slate-700">{pending ? 'With the current approver' : 'Review complete'}</p><p className="mt-1 text-xs leading-5 text-slate-500">{status === 'PENDING' && !directHR ? 'Awaiting the assigned manager. HR can act after manager approval.' : status === 'RM_APPROVED' || directHR ? 'Awaiting the assigned HR approver.' : 'This request has no pending approval action.'}</p></div></div>}
          </footer>
        </>}
      </div>
    </Container>
  )
}

/**
 * RadAIChatWidget.jsx — global floating RADAI Chat assistant.
 *
 * A soft-coded, floating chat bubble + panel available app-wide. It grounds
 * answers in whatever data the current page published to the chat context
 * store (extracted rows, uploaded document, active project) and talks to the
 * backend /pid-checker-v2/chat/ endpoint using BYOK (server-managed key when
 * configured, else the user's Claude/OpenAI key entered once per session).
 *
 * Mount once near the app root (Layout). Pure UI + service wiring — no page
 * logic changes required to adopt it beyond a page publishing its context.
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { createPortal } from 'react-dom'
import { toast } from 'react-toastify'
import {
  MessageSquare, X, Send, Sparkles, Trash2, Minimize2, Loader2,
  KeyRound, FileText, Database, Bot, User as UserIcon, Paperclip,
} from 'lucide-react'
import { askRadAIChat, archiveRadAIChat } from '../../services/radaiChat.service'
import apiClient from '../../services/api.service'
import {
  getChatContext, subscribeChatContext, getChatContextVersion,
  getChatActionHandler, getChatUploadHandler,
} from '../../services/chatContext.store'
import useAIProviderStatus from '../../hooks/useAIProviderStatus'

// ─── Soft-coded configuration ─────────────────────────────────────────
const CHAT_CFG = {
  enabled: true,
  title: 'RADAI Assistant',
  subtitle: 'Ask about the data on this page',
  placeholder: 'Ask about the extracted data or the uploaded document…',
  accentFrom: '#3b82f6',
  accentTo: '#6366f1',
  // BYOK session keys (tab-scoped; cleared when the tab closes). The managed
  // server key is preferred — these are only a fallback for unmanaged setups.
  ssProvider: 'radai_chat_byok_provider',
  ssApiKey: 'radai_chat_byok_apikey',
  ssUseOwnKey: 'radai_chat_byok_use_own',   // '1' = user opted to override the managed key
  providers: [
    { id: 'claude', label: 'Claude' },
    { id: 'openai', label: 'OpenAI' },
  ],
  maxHistory: 20,           // turns kept in the panel + sent for continuity
  // Conversation archiving to the project's S3 data lake (backend:
  // pid_checker_v2 RadAIChatArchiveView → designiq s3_utils archive layout).
  // Fire-and-forget after each completed exchange; never blocks the UI.
  archiveEnabled: true,
  ssSessionId: 'radai_chat_session_id',
  welcomeMessage:
    "Hi! I'm the RADAI assistant. Ask me anything about the data on this page — counts, specific tags, summaries, or what's in the uploaded document.",
}

const readSS = (k) => { try { return sessionStorage.getItem(k) || '' } catch { return '' } }
const writeSS = (k, v) => { try { v ? sessionStorage.setItem(k, v) : sessionStorage.removeItem(k) } catch { /* storage may be disabled */ } }

// ─── Assistant edit-control actions (soft-coded protocol) ────────────────
// The backend instructs the model to propose row edits as fenced
// ```radai_action {"op": "update_row"|"delete_row", ...} ``` blocks (only for
// pages whose profile allows it).  The widget strips the block from the
// displayed text and renders an Apply/Reject card — nothing changes until
// the user clicks Apply.
const ACTION_BLOCK_RE = /```radai_action\s*([\s\S]*?)```/g

function parseActions(answer) {
  const actions = []
  let text = String(answer || '')
  let m
  while ((m = ACTION_BLOCK_RE.exec(text)) !== null) {
    try {
      const parsed = JSON.parse(m[1])
      if (parsed && typeof parsed === 'object' && parsed.op) {
        actions.push({
          op: String(parsed.op),
          match: parsed.match && typeof parsed.match === 'object' ? parsed.match : {},
          set: parsed.set && typeof parsed.set === 'object' ? parsed.set : {},
          status: 'pending',   // pending → applied | rejected | failed
          detail: '',
        })
      }
    } catch { /* ignore malformed blocks */ }
  }
  text = text.replace(ACTION_BLOCK_RE, '').replace(/\n{3,}/g, '\n\n').trim()
  return { text, actions }
}

/** Human summary of a proposed action for the confirmation card. */
function describeAction(a) {
  const key = Object.keys(a.match)[0] || 'row'
  const target = a.match[key] || '?'
  if (a.op === 'delete_row') return `Delete row ${key}=${target}`
  const changes = Object.entries(a.set).map(([k, v]) => `${k} → "${v}"`).join(', ')
  return `Update row ${key}=${target}: ${changes}`
}

const RadAIChatWidget = () => {
  const [open, setOpen] = useState(false)
  const [input, setInput] = useState('')
  const [busy, setBusy] = useState(false)
  const [messages, setMessages] = useState([
    { role: 'assistant', content: CHAT_CFG.welcomeMessage, ts: Date.now() },
  ])

  // BYOK fallback (only used when the platform has no managed key — or when
  // the user explicitly opts to use their own key instead)
  const [provider, setProvider] = useState(() => readSS(CHAT_CFG.ssProvider) || 'claude')
  const [apiKey, setApiKey] = useState(() => readSS(CHAT_CFG.ssApiKey))
  const [useOwnKey, setUseOwnKey] = useState(() => readSS(CHAT_CFG.ssUseOwnKey) === '1')
  const [showKeyForm, setShowKeyForm] = useState(false)
  // Key panel view: 'status' shows the active-key summary, 'entry' shows the
  // input form.  MUST be separate state — keying the view off `apiKey` makes
  // the form unmount on the FIRST typed character (apiKey becomes truthy),
  // which made it impossible to enter a replacement key.
  const [keyView, setKeyView] = useState('status')

  // Auto-select the provider that has a ready managed key (server-side), so
  // the widget never defaults to a provider with no configured credential
  // (e.g. only OpenAI is configured on this deployment → use it).
  // Never override a user's saved BYOK provider choice — their key belongs
  // to the provider THEY picked.
  useEffect(() => {
    let live = true
    if (readSS(CHAT_CFG.ssApiKey)) return undefined  // user has their own key+provider
    apiClient.get('/rbac/ai-provider-status/', { suppressErrorToast: true, timeout: 30000 })
      .then(({ data }) => {
        if (!live) return
        const rows = data?.providers || []
        const ready = rows.find(r => r?.managed && r?.ready)
        if (ready?.provider) {
          const p = ready.provider === 'anthropic' ? 'claude' : ready.provider
          if (CHAT_CFG.providers.some(x => x.id === p)) setProvider(p)
        }
      })
      .catch(() => { /* keep the default */ })
    return () => { live = false }
  }, [])

  // Live page context
  const [ctxVersion, setCtxVersion] = useState(getChatContextVersion())
  const context = useMemo(() => getChatContext(), [ctxVersion]) // eslint-disable-line react-hooks/exhaustive-deps

  // Managed-key readiness (server-side). A user's saved custom key takes
  // precedence only when they explicitly opted in (useOwnKey).
  const providerStatus = useAIProviderStatus(provider)
  const hasManagedKey = Boolean(providerStatus?.managed && providerStatus?.ready)
  const useManagedKey = hasManagedKey && !(useOwnKey && apiKey)
  const needsKey = !useManagedKey && !apiKey

  // Auto-open the BYOK setup when the panel opens and no usable key exists —
  // the header key icon alone was too subtle and users never found it.
  // Waits until the managed-key probe finishes so deployments WITH a managed
  // key never flash the form.
  const providerStatusLoaded = providerStatus?.loading === false
  useEffect(() => {
    if (open && providerStatusLoaded && !useManagedKey && !apiKey) {
      setKeyView('entry')
      setShowKeyForm(true)
    }
  }, [open, providerStatusLoaded, useManagedKey, apiKey])

  // Stable per-tab conversation id for S3 archiving (survives re-renders,
  // resets when the tab closes)
  const sessionIdRef = useRef(null)
  if (!sessionIdRef.current) {
    sessionIdRef.current = readSS(CHAT_CFG.ssSessionId)
      || `chat-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`
    writeSS(CHAT_CFG.ssSessionId, sessionIdRef.current)
  }

  const endRef = useRef(null)
  const listRef = useRef(null)
  useEffect(() => subscribeChatContext(v => setCtxVersion(v)), [])
  // Scroll ONLY the message list — never scrollIntoView: on a portaled,
  // fixed-position panel it also scrolls every scrollable ancestor including
  // the main page, which made page content (e.g. extraction results)
  // "disappear" when the assistant was opened.
  useEffect(() => {
    const el = listRef.current
    if (el) el.scrollTop = el.scrollHeight
  }, [messages, open])

  const send = useCallback(async (overrideText) => {
    // overrideText lets soft-coded quick-action chips send a preset prompt
    // (events passed by onClick are objects — never treat them as text).
    const question = (typeof overrideText === 'string' ? overrideText : input).trim()
    if (!question || busy) return
    if (needsKey) { setShowKeyForm(true); toast.warn('Add your AI key to chat (or ask an admin to configure one).'); return }

    const userMsg = { role: 'user', content: question, ts: Date.now() }
    setMessages(prev => [...prev, userMsg].slice(-CHAT_CFG.maxHistory))
    setInput('')
    setBusy(true)
    try {
      const history = messages
        .filter(m => m.role === 'user' || m.role === 'assistant')
        .map(m => ({ role: m.role, content: m.content }))
      const res = await askRadAIChat({
        question,
        context: context || {},
        history,
        provider,
        apiKey: useManagedKey ? '' : apiKey,   // managed key resolves server-side unless the user opted into their own
      })
      const { text: answerText, actions } = parseActions(res.answer)
      const assistantMsg = {
        role: 'assistant',
        content: answerText || '(no answer)',
        ts: Date.now(),
        usage: res.token_usage,
        ...(actions.length ? { actions } : {}),
      }
      setMessages(prev => [...prev, assistantMsg].slice(-CHAT_CFG.maxHistory))
      // Archive the conversation to the project's S3 data lake (fire-and-forget)
      if (CHAT_CFG.archiveEnabled) {
        archiveRadAIChat({
          sessionId: sessionIdRef.current,
          messages: [...messages, userMsg, assistantMsg],
          context,
        })
      }
    } catch (err) {
      const msg = err?.response?.data?.error || 'The assistant could not answer. Check your AI key.'
      // Auth failure (401): the credential in use was rejected. If the
      // platform's managed key failed, push the user to their own BYOK key;
      // if their own key failed, say so and reopen the form for replacement.
      const authFailed = /401|authentication|credential/i.test(msg)
      let display = msg
      if (authFailed) {
        display = useManagedKey
          ? "⚠️ The platform's managed AI key was rejected (401). You can chat immediately by adding your own Claude/OpenAI key — opening the key settings."
          : '⚠️ Your AI key was rejected (401 authentication). Please check it and enter a valid key — opening the key settings.'
        setKeyView(apiKey ? 'status' : 'entry')
        setShowKeyForm(true)
      }
      setMessages(prev => [...prev, { role: 'assistant', content: display.startsWith('⚠️') ? display : `⚠️ ${display}`, ts: Date.now(), error: true }])
    } finally {
      setBusy(false)
    }
  }, [input, busy, needsKey, messages, context, provider, apiKey, useManagedKey])

  const saveKey = useCallback(() => {
    writeSS(CHAT_CFG.ssProvider, provider)
    writeSS(CHAT_CFG.ssApiKey, apiKey.trim())
    // Saving a key while a managed key exists means the user wants THEIR key.
    setUseOwnKey(true)
    writeSS(CHAT_CFG.ssUseOwnKey, '1')
    setKeyView('status')
    setShowKeyForm(false)
    toast.success('AI key saved for this session')
  }, [provider, apiKey])

  const clearKey = useCallback(() => {
    writeSS(CHAT_CFG.ssApiKey, '')
    writeSS(CHAT_CFG.ssUseOwnKey, '')
    setApiKey('')
    setUseOwnKey(false)
    toast.info('AI key removed')
  }, [])

  const switchToManaged = useCallback(() => {
    setUseOwnKey(false)
    writeSS(CHAT_CFG.ssUseOwnKey, '')
    setKeyView('status')
    setShowKeyForm(false)
    toast.info("Using the platform's managed key")
  }, [])

  // Apply/reject a proposed row edit. The actual mutation runs in the active
  // page's registered handler (chatContext.store) — the widget never touches
  // page data directly.
  const applyAction = useCallback(async (msgTs, actionIdx, accept) => {
    const patch = (patchObj) => setMessages(prev => prev.map(m => {
      if (m.ts !== msgTs || !Array.isArray(m.actions)) return m
      return { ...m, actions: m.actions.map((a, i) => (i === actionIdx ? { ...a, ...patchObj } : a)) }
    }))
    if (!accept) { patch({ status: 'rejected' }); return }
    const handler = getChatActionHandler()
    if (!handler) {
      patch({ status: 'failed', detail: 'this page does not support edits' })
      return
    }
    const msg = messages.find(m => m.ts === msgTs)
    const action = msg?.actions?.[actionIdx]
    if (!action) { patch({ status: 'failed', detail: 'action no longer available' }); return }
    try {
      const result = await handler({ op: action.op, match: action.match, set: action.set })
      if (result?.ok) {
        patch({ status: 'applied', detail: result.message || '' })
        toast.success(result?.message || 'Change applied')
      } else {
        patch({ status: 'failed', detail: result?.message || 'no matching row' })
        toast.warn(result?.message || 'Could not apply the change')
      }
    } catch (e) {
      patch({ status: 'failed', detail: String(e?.message || e).slice(0, 120) })
      toast.error('Failed to apply the change')
    }
  }, [messages])

  // 📎 Chat file upload — handed to the active page's registered handler
  // (soft-coded: page profiles declare `upload`, pages register via
  // registerChatUploadHandler). The widget never processes the file itself.
  const fileInputRef = useRef(null)
  const [uploadBusy, setUploadBusy] = useState(false)
  const handleChatFile = useCallback(async (file) => {
    if (!file) return
    const handler = getChatUploadHandler()
    if (!handler) {
      toast.warn('This page does not accept files from the assistant')
      return
    }
    setUploadBusy(true)
    setMessages(prev => [...prev, { role: 'user', content: `📎 ${file.name}`, ts: Date.now() }].slice(-CHAT_CFG.maxHistory))
    try {
      const res = await handler(file)
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: res?.ok
          ? `📎 ${res.message || `Received "${file.name}"`}`
          : `⚠️ ${res?.message || `Could not use "${file.name}" on this page`}`,
        ts: Date.now(), error: !(res?.ok),
      }].slice(-CHAT_CFG.maxHistory))
      if (res?.ok) toast.success(res.message || 'File received')
      else toast.warn(res?.message || 'File not accepted')
    } catch (e) {
      setMessages(prev => [...prev, { role: 'assistant', content: `⚠️ Upload failed: ${String(e?.message || e).slice(0, 120)}`, ts: Date.now(), error: true }].slice(-CHAT_CFG.maxHistory))
    } finally {
      setUploadBusy(false)
      if (fileInputRef.current) fileInputRef.current.value = ''
    }
  }, [])

  if (!CHAT_CFG.enabled) return null

  // Key panel mode: entry form / managed-key status / custom-key status.
  // Driven by keyView (UI state), NOT by apiKey — otherwise the form unmounts
  // on the first typed character.
  const keyPanelMode = (keyView === 'entry' || (!apiKey && !useManagedKey)) ? 'entry'
    : (useManagedKey && !useOwnKey) ? 'managed'
    : 'active'

  const ctxSummary = context && (context.rows?.length || context.document?.name)
    ? `${context.page || 'This page'} · ${context.row_count ?? context.rows?.length ?? 0} rows${context.document?.name ? ` · ${context.document.name}` : ''}`
    : null

  return createPortal(
    <>
      {/* Floating bubble */}
      {!open && (
        <button
          onClick={() => setOpen(true)}
          aria-label="Open RADAI assistant"
          title={CHAT_CFG.title}
          style={{
            position: 'fixed', bottom: 24, right: 24, zIndex: 9998,
            width: 56, height: 56, borderRadius: '50%', border: 'none', cursor: 'pointer',
            background: `linear-gradient(135deg, ${CHAT_CFG.accentFrom}, ${CHAT_CFG.accentTo})`,
            boxShadow: '0 8px 24px rgba(59,130,246,0.45)',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
            transition: 'transform 0.2s ease, box-shadow 0.2s ease',
          }}
          onMouseEnter={e => { e.currentTarget.style.transform = 'scale(1.08)' }}
          onMouseLeave={e => { e.currentTarget.style.transform = 'scale(1)' }}
        >
          <MessageSquare size={24} color="#fff" />
        </button>
      )}

      {/* Chat panel */}
      {open && (
        <div
          role="dialog"
          aria-label={CHAT_CFG.title}
          style={{
            position: 'fixed', bottom: 24, right: 24, zIndex: 9999,
            width: 'min(420px, 92vw)', height: 'min(620px, 84vh)',
            background: '#fff', borderRadius: 18, overflow: 'hidden',
            display: 'flex', flexDirection: 'column',
            border: '1px solid #e2e8f0',
            boxShadow: '0 20px 60px rgba(0,0,0,0.28)',
          }}
        >
          {/* Header */}
          <div style={{
            padding: '12px 16px', color: '#fff', flexShrink: 0,
            background: `linear-gradient(135deg, ${CHAT_CFG.accentFrom}, ${CHAT_CFG.accentTo})`,
            display: 'flex', alignItems: 'center', gap: 10,
          }}>
            <div style={{
              width: 34, height: 34, borderRadius: 10, background: 'rgba(255,255,255,0.18)',
              display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0,
            }}>
              <Sparkles size={18} color="#fff" />
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <div style={{ fontSize: 14, fontWeight: 800, lineHeight: 1.1 }}>{CHAT_CFG.title}</div>
              <div style={{ fontSize: 11, opacity: 0.9 }}>{CHAT_CFG.subtitle}</div>
            </div>
            <button onClick={() => {
                if (!showKeyForm) setKeyView((!apiKey && !useManagedKey) ? 'entry' : 'status')
                setShowKeyForm(v => !v)
              }} title="AI key settings" aria-label="AI key settings"
              style={{ background: 'rgba(255,255,255,0.16)', border: 'none', borderRadius: 8, padding: 6, cursor: 'pointer', color: '#fff' }}>
              <KeyRound size={16} />
            </button>
            <button onClick={() => setMessages([{ role: 'assistant', content: CHAT_CFG.welcomeMessage, ts: Date.now() }])}
              title="Clear chat" aria-label="Clear chat"
              style={{ background: 'rgba(255,255,255,0.16)', border: 'none', borderRadius: 8, padding: 6, cursor: 'pointer', color: '#fff' }}>
              <Trash2 size={16} />
            </button>
            <button onClick={() => setOpen(false)} aria-label="Close assistant"
              style={{ background: 'rgba(255,255,255,0.16)', border: 'none', borderRadius: 8, padding: 6, cursor: 'pointer', color: '#fff' }}>
              <Minimize2 size={16} />
            </button>
          </div>

          {/* Context banner */}
          {ctxSummary && (
            <div style={{
              padding: '7px 14px', fontSize: 11, color: '#1d4ed8', flexShrink: 0,
              background: 'rgba(59,130,246,0.06)', borderBottom: '1px solid rgba(59,130,246,0.15)',
              display: 'flex', alignItems: 'center', gap: 6,
            }}>
              <Database size={12} />
              <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                Context: {ctxSummary}
              </span>
            </div>
          )}

          {/* Key form (BYOK fallback) */}
          {showKeyForm && (
            <div style={{ padding: '12px 14px', background: '#f8fafc', borderBottom: '1px solid #e2e8f0', flexShrink: 0 }}>
              {keyPanelMode === 'managed' ? (
                <>
                  <div style={{ fontSize: 12, color: '#15803d', display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                    <KeyRound size={13} /> Using the platform&apos;s managed {provider === 'claude' ? 'Claude' : 'OpenAI'} key.
                  </div>
                  <div style={{ display: 'flex', gap: 6 }}>
                    <button onClick={() => { setUseOwnKey(true); setKeyView('entry') }}
                      style={{
                        flex: 1, padding: '7px 0', fontSize: 12, fontWeight: 700, cursor: 'pointer',
                        borderRadius: 8, border: `1px solid ${CHAT_CFG.accentFrom}`,
                        background: '#fff', color: CHAT_CFG.accentFrom,
                      }}>
                      Use my own key instead
                    </button>
                    <button onClick={() => setShowKeyForm(false)}
                      style={{ padding: '7px 12px', fontSize: 12, cursor: 'pointer', borderRadius: 8, border: '1px solid #e2e8f0', background: '#fff', color: '#64748b' }}>
                      Close
                    </button>
                  </div>
                </>
              ) : keyPanelMode === 'active' ? (
                // A custom BYOK key is already active — show status + actions
                // instead of the bare entry form (key stays hidden).
                <>
                  <div style={{ fontSize: 12, color: '#15803d', display: 'flex', alignItems: 'center', gap: 6, marginBottom: 8 }}>
                    <KeyRound size={13} /> Using your {provider === 'claude' ? 'Claude' : 'OpenAI'} key — this session only.
                  </div>
                  <div style={{ display: 'flex', gap: 6 }}>
                    <button onClick={() => { setApiKey(''); setKeyView('entry') }}
                      style={{
                        flex: 1, padding: '7px 0', fontSize: 12, fontWeight: 700, cursor: 'pointer',
                        borderRadius: 8, border: 'none', color: '#fff',
                        background: `linear-gradient(135deg, ${CHAT_CFG.accentFrom}, ${CHAT_CFG.accentTo})`,
                      }}>
                      Change key
                    </button>
                    <button onClick={clearKey}
                      style={{ padding: '7px 12px', fontSize: 12, cursor: 'pointer', borderRadius: 8, border: '1px solid #fecaca', background: '#fff', color: '#dc2626' }}>
                      Remove
                    </button>
                    {hasManagedKey ? (
                      <button onClick={switchToManaged}
                        style={{ padding: '7px 12px', fontSize: 12, cursor: 'pointer', borderRadius: 8, border: '1px solid #bbf7d0', background: '#f0fdf4', color: '#15803d' }}>
                        Use platform key
                      </button>
                    ) : (
                      <button onClick={() => setShowKeyForm(false)}
                        style={{ padding: '7px 12px', fontSize: 12, cursor: 'pointer', borderRadius: 8, border: '1px solid #e2e8f0', background: '#fff', color: '#64748b' }}>
                        Close
                      </button>
                    )}
                  </div>
                </>
              ) : (
                <>
                  <div style={{ fontSize: 12, fontWeight: 700, color: '#0f172a', marginBottom: 8 }}>
                    Bring Your Own Key (this session only)
                  </div>
                  <div style={{ display: 'flex', gap: 6, marginBottom: 8 }}>
                    {CHAT_CFG.providers.map(p => (
                      <button key={p.id} onClick={() => setProvider(p.id)}
                        style={{
                          flex: 1, padding: '6px 0', fontSize: 12, fontWeight: 600, cursor: 'pointer',
                          borderRadius: 8, border: `1px solid ${provider === p.id ? CHAT_CFG.accentFrom : '#e2e8f0'}`,
                          background: provider === p.id ? 'rgba(59,130,246,0.08)' : '#fff',
                          color: provider === p.id ? CHAT_CFG.accentFrom : '#64748b',
                        }}>
                        {p.label}
                      </button>
                    ))}
                  </div>
                  <input
                    type="password"
                    value={apiKey}
                    onChange={e => setApiKey(e.target.value)}
                    placeholder={`${provider === 'claude' ? 'Claude' : 'OpenAI'} API key`}
                    style={{
                      width: '100%', padding: '8px 10px', fontSize: 12, borderRadius: 8,
                      border: '1px solid #e2e8f0', outline: 'none', boxSizing: 'border-box',
                    }}
                  />
                  <div style={{ display: 'flex', gap: 6, marginTop: 8 }}>
                    <button onClick={saveKey} disabled={!apiKey.trim()}
                      style={{
                        flex: 1, padding: '7px 0', fontSize: 12, fontWeight: 700, cursor: 'pointer',
                        borderRadius: 8, border: 'none', color: '#fff',
                        background: `linear-gradient(135deg, ${CHAT_CFG.accentFrom}, ${CHAT_CFG.accentTo})`,
                        opacity: apiKey.trim() ? 1 : 0.5,
                      }}>
                      Save key
                    </button>
                    <button onClick={() => { setApiKey(readSS(CHAT_CFG.ssApiKey)); setKeyView('status'); setShowKeyForm(false) }}
                      style={{ padding: '7px 12px', fontSize: 12, cursor: 'pointer', borderRadius: 8, border: '1px solid #e2e8f0', background: '#fff', color: '#64748b' }}>
                      Cancel
                    </button>
                    {hasManagedKey && (
                      <button onClick={switchToManaged}
                        style={{ padding: '7px 12px', fontSize: 12, cursor: 'pointer', borderRadius: 8, border: '1px solid #bbf7d0', background: '#f0fdf4', color: '#15803d' }}>
                        Use platform key
                      </button>
                    )}
                  </div>
                </>
              )}
            </div>
          )}

          {/* Messages */}
          <div ref={listRef} style={{ flex: 1, overflowY: 'auto', padding: '14px 14px 8px', display: 'flex', flexDirection: 'column', gap: 10 }}>
            {messages.map((m, i) => (
              <div key={m.ts + '-' + i} style={{
                display: 'flex', gap: 8, alignItems: 'flex-start',
                flexDirection: m.role === 'user' ? 'row-reverse' : 'row',
              }}>
                <div style={{
                  width: 26, height: 26, borderRadius: '50%', flexShrink: 0,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  background: m.role === 'user'
                    ? 'linear-gradient(135deg,#10b981,#059669)'
                    : `linear-gradient(135deg, ${CHAT_CFG.accentFrom}, ${CHAT_CFG.accentTo})`,
                }}>
                  {m.role === 'user' ? <UserIcon size={13} color="#fff" /> : <Bot size={13} color="#fff" />}
                </div>
                <div style={{
                  maxWidth: '80%', padding: '9px 12px', borderRadius: 12, fontSize: 13, lineHeight: 1.5,
                  whiteSpace: 'pre-wrap', wordBreak: 'break-word',
                  background: m.role === 'user'
                    ? 'linear-gradient(135deg,#10b981,#059669)'
                    : m.error ? '#fef2f2' : '#f1f5f9',
                  color: m.role === 'user' ? '#fff' : m.error ? '#b91c1c' : '#0f172a',
                  border: m.role === 'user' ? 'none' : `1px solid ${m.error ? '#fca5a5' : '#e2e8f0'}`,
                }}>
                  {m.content}
                  {m.usage && (
                    <div style={{ marginTop: 6, fontSize: 10, opacity: 0.6, borderTop: '1px solid rgba(0,0,0,0.06)', paddingTop: 4 }}>
                      {m.usage.total_tokens != null ? `${m.usage.total_tokens} tokens` : ''}
                      {m.usage.estimated_cost_usd != null ? ` · ~$${m.usage.estimated_cost_usd}` : ''}
                    </div>
                  )}
                  {/* Proposed row edits (assistant edit control) — Apply/Reject */}
                  {Array.isArray(m.actions) && m.actions.map((a, ai) => (
                    <div key={ai} style={{
                      marginTop: 8, padding: '8px 10px', borderRadius: 10, fontSize: 12,
                      background: a.status === 'applied' ? '#f0fdf4' : a.status === 'rejected' ? '#fafafa' : '#fffbeb',
                      border: `1px solid ${a.status === 'applied' ? '#bbf7d0' : a.status === 'rejected' ? '#e2e8f0' : '#fde68a'}`,
                    }}>
                      <div style={{ fontWeight: 600, color: '#0f172a', marginBottom: a.status === 'pending' ? 6 : 0 }}>
                        ✏️ {describeAction(a)}
                      </div>
                      {a.status === 'pending' ? (
                        <div style={{ display: 'flex', gap: 6 }}>
                          <button onClick={() => applyAction(m.ts, ai, true)}
                            style={{
                              flex: 1, padding: '5px 0', fontSize: 11, fontWeight: 700, cursor: 'pointer',
                              borderRadius: 7, border: 'none', color: '#fff',
                              background: 'linear-gradient(135deg,#10b981,#059669)',
                            }}>
                            Apply
                          </button>
                          <button onClick={() => applyAction(m.ts, ai, false)}
                            style={{ padding: '5px 10px', fontSize: 11, cursor: 'pointer', borderRadius: 7, border: '1px solid #e2e8f0', background: '#fff', color: '#64748b' }}>
                            Reject
                          </button>
                        </div>
                      ) : (
                        <div style={{ fontSize: 11, marginTop: 4, color: a.status === 'applied' ? '#15803d' : a.status === 'failed' ? '#b91c1c' : '#64748b' }}>
                          {a.status === 'applied' ? `✅ Applied${a.detail ? ` — ${a.detail}` : ''}`
                            : a.status === 'failed' ? `⚠️ Failed${a.detail ? ` — ${a.detail}` : ''}`
                            : 'Rejected'}
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            ))}
            {busy && (
              <div style={{ display: 'flex', gap: 8, alignItems: 'center', color: '#64748b', fontSize: 12 }}>
                <Loader2 size={14} style={{ animation: 'spin 1s linear infinite' }} /> Thinking…
              </div>
            )}
            <div ref={endRef} />
          </div>

          {/* Input */}
          <div style={{ padding: '10px 12px', borderTop: '1px solid #e2e8f0', flexShrink: 0, background: '#fff' }}>
            {/* Quick actions — soft-coded per page profile (verify/recommend) */}
            {Array.isArray(context?.quick_actions) && context.quick_actions.length > 0 && (
              <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 8 }}>
                {context.quick_actions.map(qa => (
                  <button key={qa.id} onClick={() => send(qa.prompt)} disabled={busy}
                    title={qa.label}
                    style={{
                      padding: '5px 10px', fontSize: 11, fontWeight: 600, cursor: 'pointer',
                      borderRadius: 999, border: '1px solid rgba(59,130,246,0.35)',
                      background: 'rgba(59,130,246,0.06)', color: '#1d4ed8',
                      opacity: busy ? 0.5 : 1,
                    }}>
                    {qa.label}
                  </button>
                ))}
              </div>
            )}
            <div style={{ display: 'flex', gap: 8, alignItems: 'flex-end' }}>
              {/* 📎 upload (soft-coded per page profile `upload`) */}
              {context?.upload?.enabled && (
                <>
                  <input
                    ref={fileInputRef}
                    type="file"
                    accept={context.upload.accept || ''}
                    style={{ display: 'none' }}
                    onChange={e => handleChatFile(e.target.files?.[0])}
                  />
                  <button
                    onClick={() => fileInputRef.current?.click()}
                    disabled={uploadBusy || busy}
                    aria-label="Upload file"
                    title={`Upload ${context.upload.note || 'file'} to this page`}
                    style={{
                      width: 40, height: 40, borderRadius: 10, cursor: 'pointer', flexShrink: 0,
                      border: '1px solid #e2e8f0', background: '#f8fafc',
                      display: 'flex', alignItems: 'center', justifyContent: 'center',
                      opacity: (uploadBusy || busy) ? 0.5 : 1,
                    }}>
                    {uploadBusy
                      ? <Loader2 size={16} color="#64748b" style={{ animation: 'spin 1s linear infinite' }} />
                      : <Paperclip size={16} color="#475569" />}
                  </button>
                </>
              )}
              <textarea
                value={input}
                onChange={e => setInput(e.target.value)}
                onKeyDown={e => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); send() } }}
                placeholder={CHAT_CFG.placeholder}
                rows={1}
                style={{
                  flex: 1, resize: 'none', padding: '9px 12px', fontSize: 13, borderRadius: 10,
                  border: '1px solid #e2e8f0', outline: 'none', fontFamily: 'inherit',
                  maxHeight: 90, boxSizing: 'border-box',
                }}
              />
              <button onClick={send} disabled={busy || !input.trim()} aria-label="Send message"
                style={{
                  width: 40, height: 40, borderRadius: 10, border: 'none', cursor: 'pointer', flexShrink: 0,
                  background: `linear-gradient(135deg, ${CHAT_CFG.accentFrom}, ${CHAT_CFG.accentTo})`,
                  display: 'flex', alignItems: 'center', justifyContent: 'center',
                  opacity: (busy || !input.trim()) ? 0.5 : 1,
                }}>
                {busy ? <Loader2 size={16} color="#fff" style={{ animation: 'spin 1s linear infinite' }} /> : <Send size={16} color="#fff" />}
              </button>
            </div>
            <div style={{ fontSize: 10, color: '#94a3b8', marginTop: 5 }}>
              Enter to send · Shift+Enter for a new line
              {needsKey && <span style={{ color: '#b45309' }}> · add an AI key (⚙ icon) to chat</span>}
            </div>
          </div>
        </div>
      )}
      <style>{`@keyframes spin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }`}</style>
    </>,
    document.body
  )
}

export default RadAIChatWidget

import React, { useState } from 'react'
import { DOCUMENTATION_CONFIG } from '../../config/documentation.config'

/**
 * Documentation Component
 * Comprehensive documentation and help center
 * Configuration: src/config/documentation.config.js
 */

const Documentation = ({ isModal = false, onClose }) => {
  const [selectedCategory, setSelectedCategory] = useState(null)
  const [selectedArticle, setSelectedArticle] = useState(null)
  const [searchQuery, setSearchQuery] = useState('')

  const handleCategoryClick = (categoryId) => {
    setSelectedCategory(categoryId)
    setSelectedArticle(null)
  }

  const handleArticleClick = (article) => {
    setSelectedArticle(article)
  }

  const handleBack = () => {
    if (selectedArticle) {
      setSelectedArticle(null)
    } else if (selectedCategory) {
      setSelectedCategory(null)
    }
  }

  const renderArticleContent = (content) => {
    return content.split('\n').map((line, index) => {
      // Heading 1
      if (line.startsWith('# ')) {
        return <h1 key={index} className="text-3xl font-bold text-gray-900 mb-4 mt-6">{line.substring(2)}</h1>
      }
      // Heading 2
      if (line.startsWith('## ')) {
        return <h2 key={index} className="text-2xl font-bold text-gray-900 mb-3 mt-5">{line.substring(3)}</h2>
      }
      // Heading 3
      if (line.startsWith('### ')) {
        return <h3 key={index} className="text-xl font-semibold text-gray-800 mb-2 mt-4">{line.substring(4)}</h3>
      }
      // List item
      if (line.startsWith('- ')) {
        return <li key={index} className="ml-6 text-gray-700 mb-2">{line.substring(2)}</li>
      }
      // Numbered list
      if (/^\d+\./.test(line)) {
        return <li key={index} className="ml-6 text-gray-700 mb-2">{line.substring(line.indexOf('.') + 2)}</li>
      }
      // Bold text
      if (line.startsWith('**') && line.endsWith('**')) {
        return <p key={index} className="font-bold text-gray-900 mb-2">{line.substring(2, line.length - 2)}</p>
      }
      // Empty line
      if (line.trim() === '') {
        return <div key={index} className="h-2"></div>
      }
      // Regular paragraph
      return <p key={index} className="text-gray-700 mb-3 leading-relaxed">{line}</p>
    })
  }

  const getCategoryColor = (category) => {
    const cat = DOCUMENTATION_CONFIG.categories.find(c => c.id === category)
    return cat ? cat.gradient : 'from-gray-500 to-gray-600'
  }

  return (
    <div className={`${isModal ? 'fixed inset-0 z-50 flex items-center justify-center bg-black bg-opacity-50 p-4' : 'w-full'}`}>
      <div className={`${isModal ? 'bg-white rounded-3xl shadow-2xl max-w-7xl w-full max-h-[90vh] overflow-hidden flex flex-col' : 'w-full'}`}>
        {/* Header */}
        <div className="bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 text-white p-8 relative overflow-hidden flex-shrink-0">
          {/* Decorative elements */}
          <div className="absolute top-0 right-0 w-64 h-64 bg-white opacity-5 rounded-full -mr-32 -mt-32"></div>
          <div className="absolute bottom-0 left-0 w-48 h-48 bg-white opacity-5 rounded-full -ml-24 -mb-24"></div>
          
          <div className="relative z-10">
            <div className="flex items-center justify-between mb-4">
              <div className="flex items-center gap-4">
                {(selectedCategory || selectedArticle) && (
                  <button
                    onClick={handleBack}
                    className="w-10 h-10 bg-white bg-opacity-20 rounded-xl flex items-center justify-center hover:bg-opacity-30 transition-all"
                  >
                    <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 19l-7-7 7-7" />
                    </svg>
                  </button>
                )}
                <div className="flex items-center gap-3">
                  <div className="w-16 h-16 bg-white bg-opacity-20 rounded-2xl flex items-center justify-center backdrop-blur-sm">
                    <span className="text-4xl">📚</span>
                  </div>
                  <div>
                    <h2 className="text-3xl font-bold">{DOCUMENTATION_CONFIG.title}</h2>
                    <p className="text-blue-100 mt-1">{DOCUMENTATION_CONFIG.subtitle}</p>
                  </div>
                </div>
              </div>
              {isModal && (
                <button
                  onClick={onClose}
                  className="w-10 h-10 bg-white bg-opacity-20 rounded-xl flex items-center justify-center hover:bg-opacity-30 transition-all"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              )}
            </div>

            {/* Search Bar */}
            {!selectedArticle && (
              <div className="relative">
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder={DOCUMENTATION_CONFIG.searchPlaceholder}
                  className="w-full px-6 py-4 rounded-xl bg-white bg-opacity-20 backdrop-blur-sm text-white placeholder-blue-200 focus:outline-none focus:ring-2 focus:ring-white focus:ring-opacity-50"
                />
                <svg className="absolute right-4 top-1/2 transform -translate-y-1/2 w-6 h-6 text-blue-200" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
            )}
          </div>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto p-8">
          {/* Home View - Categories */}
          {!selectedCategory && !selectedArticle && (
            <div>
              {/* Categories Grid */}
              <div className="mb-8">
                <h3 className="text-2xl font-bold text-gray-900 mb-6 flex items-center gap-3">
                  <span className="w-1 h-8 bg-gradient-to-b from-blue-600 to-indigo-600 rounded-full"></span>
                  Browse by Category
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                  {DOCUMENTATION_CONFIG.categories.map((category) => (
                    <button
                      key={category.id}
                      onClick={() => handleCategoryClick(category.id)}
                      className="group bg-white rounded-2xl p-6 shadow-lg hover:shadow-2xl transition-all duration-300 border-2 border-gray-100 hover:border-transparent text-left relative overflow-hidden"
                    >
                      <div className={`absolute inset-0 bg-gradient-to-br ${category.gradient} opacity-0 group-hover:opacity-100 transition-opacity duration-300`}></div>
                      <div className="relative z-10">
                        <div className="text-5xl mb-4">{category.icon}</div>
                        <h4 className="text-xl font-bold text-gray-900 group-hover:text-white transition-colors mb-2">
                          {category.name}
                        </h4>
                        <p className="text-sm text-gray-600 group-hover:text-white group-hover:text-opacity-90 transition-colors">
                          {category.description}
                        </p>
                        <div className="mt-4 flex items-center gap-2 text-blue-600 group-hover:text-white transition-colors">
                          <span className="text-sm font-medium">Explore</span>
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                          </svg>
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* Quick Links */}
              <div className="mb-8">
                <h3 className="text-2xl font-bold text-gray-900 mb-6 flex items-center gap-3">
                  <span className="w-1 h-8 bg-gradient-to-b from-purple-600 to-pink-600 rounded-full"></span>
                  Quick Links
                </h3>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
                  {DOCUMENTATION_CONFIG.quickLinks.map((link) => (
                    <a
                      key={link.id}
                      href={link.url}
                      className="group bg-gradient-to-br from-gray-50 to-gray-100 rounded-xl p-4 hover:shadow-lg transition-all border border-gray-200"
                    >
                      <div className="text-3xl mb-2">{link.icon}</div>
                      <h5 className="font-bold text-gray-900 mb-1">{link.title}</h5>
                      <p className="text-xs text-gray-600">{link.description}</p>
                    </a>
                  ))}
                </div>
              </div>

              {/* Popular Topics */}
              <div className="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-2xl p-6 border border-blue-100">
                <h3 className="text-xl font-bold text-gray-900 mb-4 flex items-center gap-2">
                  <span>🔥</span>
                  Popular Topics
                </h3>
