                <span className="relative flex h-1.5 w-1.5 mr-1.5">
                  <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-300 opacity-75" />
                  <span className="relative inline-flex rounded-full h-1.5 w-1.5 bg-emerald-300" />
                </span>
                <span className="tabular-nums">{liveCount}</span>
                <span className="ml-1 opacity-80">{LIVE_PULSE.label}</span>
              </span>
            )}
          </div>
          <div>Secure Connection</div>
        </div>
      </div>

      {/* Animated Wave Footer (soft-coded) */}
      {WAVE_FOOTER.enabled && (
        <div className="absolute bottom-0 left-0 right-0 pointer-events-none z-0 opacity-40">
          <svg viewBox="0 0 1440 120" className="w-full h-16" preserveAspectRatio="none">
            <defs>
              <linearGradient id="loginWaveGrad" x1="0" y1="0" x2="1" y2="0">
                {WAVE_FOOTER.colors.map((c, i) => (
                  <stop key={i} offset={`${(i / (WAVE_FOOTER.colors.length - 1)) * 100}%`} stopColor={c} />
                ))}
              </linearGradient>
            </defs>
            <path fill="url(#loginWaveGrad)" fillOpacity="0.55">
              <animate attributeName="d" dur="9s" repeatCount="indefinite"
                values="M0,60 C240,100 480,20 720,60 C960,100 1200,20 1440,60 L1440,120 L0,120 Z;
                        M0,60 C240,20 480,100 720,60 C960,20 1200,100 1440,60 L1440,120 L0,120 Z;
                        M0,60 C240,100 480,20 720,60 C960,100 1200,20 1440,60 L1440,120 L0,120 Z" />
            </path>
          </svg>
        </div>
      )}
      
      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: rgba(255, 255, 255, 0.1);
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: linear-gradient(to bottom, #73BDC8, #617AAD);
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: linear-gradient(to bottom, #7FCAB5, #73BDC8);
        }
        @keyframes login-float-up {
          0%   { transform: translate3d(0, 0, 0) rotate(0deg); opacity: 0; }
          10%  { opacity: ${FLOATING_KEYWORDS.opacity}; }
          90%  { opacity: ${FLOATING_KEYWORDS.opacity}; }
          100% { transform: translate3d(20px, -120vh, 0) rotate(2deg); opacity: 0; }
        }
        @keyframes login-logo-pulse {
          0%   { transform: scale(1);   opacity: 0.7; }
          100% { transform: scale(2.4); opacity: 0;   }
        }
      `}</style>
    </div>
  )
}

export default LoginBranding

import { forwardRef, useEffect, useId, useLayoutEffect, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import {
  ArrowLeftIcon, ArrowPathIcon, ArrowRightIcon, BellSlashIcon, ChartBarIcon,
  CheckCircleIcon, ClipboardDocumentListIcon, ClockIcon, Cog6ToothIcon,
  DevicePhoneMobileIcon, DocumentTextIcon, EllipsisHorizontalIcon,
  ExclamationTriangleIcon, InformationCircleIcon, MagnifyingGlassIcon,
  ShieldCheckIcon, SpeakerWaveIcon, SparklesIcon, TrashIcon, UserGroupIcon, XMarkIcon,
} from '@heroicons/react/24/outline'
import { canDecideOffboardingNotification } from '../../utils/approvalCapabilities'
import { formatDistanceToNow } from '../../utils/dateFormatter'
import { resolveNotificationTarget } from '../../utils/notificationNavigation'
import './NotificationDropdown.css'

const FILTERS = [
  { id: 'all', label: 'All' }, { id: 'unread', label: 'Unread' },
  { id: 'approvals', label: 'Approvals' }, { id: 'system', label: 'System' },
]

const CATEGORY_STYLE = {
  SYSTEM: { label: 'System', Icon: Cog6ToothIcon, tone: 'slate' },
  PROJECT: { label: 'Projects', Icon: ChartBarIcon, tone: 'violet' },
  QHSE: { label: 'QHSE', Icon: ShieldCheckIcon, tone: 'emerald' },
  DOCUMENT: { label: 'Documents', Icon: DocumentTextIcon, tone: 'blue' },
  USER: { label: 'People', Icon: UserGroupIcon, tone: 'violet' },
  ADMIN: { label: 'Administration', Icon: Cog6ToothIcon, tone: 'slate' },
  AI: { label: 'AI', Icon: SparklesIcon, tone: 'violet' },
  APPROVAL: { label: 'Approvals', Icon: ClockIcon, tone: 'amber' },
  ALERT: { label: 'Alerts', Icon: ExclamationTriangleIcon, tone: 'rose' },
  INFO: { label: 'Information', Icon: InformationCircleIcon, tone: 'blue' },
}

const categoryName = (notification) => String(
  notification.category_name || notification.category?.name || notification.category_detail?.name
  || (typeof notification.category === 'string' ? notification.category : '')
).toUpperCase()

const categoryStyle = (notification) => {
  const category = categoryName(notification)
  if (category === 'APPROVAL' && (
    notification.metadata?.decision_status === 'approved' || /\bapproved\b/i.test(notification.title)
  )) return { label: 'Approvals', Icon: CheckCircleIcon, tone: 'emerald' }
  return CATEGORY_STYLE[category] || CATEGORY_STYLE.INFO
}

// Native disclosure buttons support Tab / Enter without imposing menu-role keyboard rules.
function NotificationActions({ notification, busy, onMarkAsRead, onDelete }) {
  const [open, setOpen] = useState(false)
  const [opensUp, setOpensUp] = useState(false)
  const containerRef = useRef(null)
  const triggerRef = useRef(null)
  const actionsRef = useRef(null)
  const actionsId = useId()

  useLayoutEffect(() => {
    if (!open) return
    const button = triggerRef.current.getBoundingClientRect()
    const actions = actionsRef.current.getBoundingClientRect()
    const list = containerRef.current.closest('.notification-drawer__body').getBoundingClientRect()
    setOpensUp(button.bottom + actions.height + 4 > list.bottom && button.top - actions.height - 4 >= list.top)
  }, [open])

  useEffect(() => {
    if (!open) return undefined
    const closeOutside = (event) => {
      if (!containerRef.current?.contains(event.target)) setOpen(false)
    }
    document.addEventListener('pointerdown', closeOutside)
    return () => document.removeEventListener('pointerdown', closeOutside)
  }, [open])

  const runAction = (handler) => {
    setOpen(false)
    triggerRef.current?.focus()
    handler(notification.id)
  }

  return (
    <div className="notification-drawer__actions" ref={containerRef}
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) setOpen(false)
      }}
      onKeyDown={(event) => {
        if (event.key === 'Escape' && open) {
          event.stopPropagation()
          setOpen(false)
          triggerRef.current?.focus()
        }
      }}
    >
      <button ref={triggerRef} type="button" className="notification-drawer__icon-button"
        aria-label={`Actions for ${notification.title}`} aria-expanded={open}
        aria-controls={actionsId} disabled={busy} onClick={() => setOpen((value) => !value)}
      >
        {busy ? <ArrowPathIcon aria-hidden="true" className="notification-drawer__spin" /> : <EllipsisHorizontalIcon aria-hidden="true" />}
      </button>
      {open && (
        <div ref={actionsRef} id={actionsId} className={`notification-drawer__action-list${opensUp ? ' notification-drawer__action-list--above' : ''}`}>
          {!notification.is_read && (
            <button type="button" onClick={() => runAction(onMarkAsRead)}>
              <CheckCircleIcon aria-hidden="true" /> Mark as read
            </button>
          )}
          <button type="button" className="notification-drawer__delete" onClick={() => runAction(onDelete)}>
            <TrashIcon aria-hidden="true" /> Delete notification
          </button>
        </div>
      )}
    </div>
  )
}

const NotificationDropdown = forwardRef(({
  notifications = [], loading = false, unreadCount = 0,
  onMarkAsRead, onMarkAllAsRead, onDelete, onRefresh,
  onOffboardingDecision, decisionLoadingId, decisionMessage,
  soundEnabled, onToggleSound, pushState, onTogglePush,
  onClose, onNavigate, busyIds = [], bulkBusy = false, errorMessage = '', hasMore = false,
}, ref) => {
  const [filter, setFilter] = useState('all')
  const [query, setQuery] = useState('')
  const [searchOpen, setSearchOpen] = useState(false)
  const [preferencesOpen, setPreferencesOpen] = useState(false)
  const searchRef = useRef(null)
  const searchToggleRef = useRef(null)
  const preferencesRef = useRef(null)
  const preferencesToggleRef = useRef(null)

  useEffect(() => {
    if (searchOpen && !preferencesOpen) searchRef.current?.focus()
  }, [searchOpen, preferencesOpen])
  useEffect(() => {
    if (preferencesOpen) preferencesRef.current?.focus()
  }, [preferencesOpen])

  const searchTerm = query.trim().toLocaleLowerCase()
  const visibleNotifications = notifications.filter((notification) => {
    const category = categoryName(notification)
    if (filter === 'unread' && notification.is_read) return false
    if (filter === 'approvals' && category !== 'APPROVAL') return false
    if (filter === 'system' && category !== 'SYSTEM') return false
    return !searchTerm || [notification.title, notification.message, categoryStyle(notification).label]
      .some((value) => String(value || '').toLocaleLowerCase().includes(searchTerm))
  })
  const today = new Date().toDateString()
  const groups = [
    { label: 'Today', items: visibleNotifications.filter((item) => new Date(item.created_at).toDateString() === today) },
    { label: 'Earlier', items: visibleNotifications.filter((item) => new Date(item.created_at).toDateString() !== today) },
  ].filter((group) => group.items.length)
  const recentUnreadCount = notifications.filter((notification) => !notification.is_read).length
  const limitedList = hasMore || unreadCount > recentUnreadCount
  const pushDisabled = pushState?.busy || pushState?.supported === false
    || (!pushState?.enabled && (pushState?.available === false || pushState?.permission === 'denied'))
  const pushDescription = pushState?.supported === false
    ? 'Browser notifications are not supported on this device.'
    : pushState?.permission === 'denied'
      ? 'Allow notifications in your browser settings to enable this.'
      : pushState?.available === false
        ? 'Browser notifications are not configured for this workspace.'
        : 'Receive updates on this device when RADAI is in the background.'

  return (
    <section id="notification-drawer" ref={ref} className="notification-drawer" role="dialog" aria-modal="true"
      aria-labelledby="notification-drawer-title" tabIndex={-1}
    >
      <header className="notification-drawer__header">
        <div className="notification-drawer__heading">
          <h2 id="notification-drawer-title">Notifications</h2>
          <span className="notification-drawer__count">{unreadCount} unread</span>
        </div>
        <div className="notification-drawer__header-actions">
          <button type="button" className="notification-drawer__text-button notification-drawer__mark-all"
            disabled={unreadCount === 0 || bulkBusy || busyIds.length > 0} onClick={onMarkAllAsRead} aria-busy={bulkBusy}
          >{bulkBusy ? 'Marking all read…' : 'Mark all read'}</button>
          <button ref={preferencesToggleRef} type="button" className="notification-drawer__icon-button"
            aria-label="Notification preferences" aria-expanded={preferencesOpen} aria-controls="notification-drawer-preferences"
            onClick={() => setPreferencesOpen((value) => !value)}
          ><Cog6ToothIcon aria-hidden="true" /></button>
          <button type="button" className="notification-drawer__icon-button" aria-label="Close notifications" onClick={onClose}>
            <XMarkIcon aria-hidden="true" />
          </button>
        </div>
      </header>

      {!preferencesOpen && (
        <div className="notification-drawer__filters">
          <div className="notification-drawer__filter-buttons" role="group" aria-label="Filter notifications">
            {FILTERS.map((item) => (
              <button key={item.id} type="button" aria-pressed={filter === item.id} onClick={() => setFilter(item.id)}>
                {item.label}
                {item.id === 'unread' && unreadCount > 0 && <span className="notification-drawer__filter-count">{unreadCount}</span>}
              </button>
            ))}
          </div>
          <button ref={searchToggleRef} type="button" className="notification-drawer__icon-button"
            aria-label="Search notifications" aria-expanded={searchOpen} aria-controls="notification-drawer-search"
            onClick={() => { setSearchOpen((value) => !value); setQuery('') }}
          ><MagnifyingGlassIcon aria-hidden="true" /></button>
        </div>
      )}
      {!preferencesOpen && searchOpen && (
        <div className="notification-drawer__search" id="notification-drawer-search">
          <MagnifyingGlassIcon aria-hidden="true" />
          <input ref={searchRef} type="search" aria-label="Search notifications" placeholder="Search recent notifications"
            value={query} onChange={(event) => setQuery(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Escape') {
                event.stopPropagation()
                setQuery(''); setSearchOpen(false); searchToggleRef.current?.focus()
              }
            }}
          />
        </div>
      )}
      {errorMessage && <div className="notification-drawer__notice notification-drawer__notice--error" role="alert">{errorMessage}</div>}
      {decisionMessage && <div className="notification-drawer__notice" role="status">{decisionMessage}</div>}
      {pushState?.error && <div className="notification-drawer__notice notification-drawer__notice--error" role="alert">{pushState.error}</div>}

      <div className="notification-drawer__body">
        {preferencesOpen ? (
          <section id="notification-drawer-preferences" className="notification-drawer__preferences" aria-labelledby="notification-preferences-title">
            <button type="button" className="notification-drawer__text-button notification-drawer__back"
              onClick={() => { setPreferencesOpen(false); preferencesToggleRef.current?.focus() }}
            ><ArrowLeftIcon aria-hidden="true" /> Back to notifications</button>
            <h3 ref={preferencesRef} tabIndex={-1} id="notification-preferences-title">Notification preferences</h3>
            <p className="notification-drawer__settings-intro">Choose how this browser alerts you to new updates.</p>
            <div className="notification-drawer__setting">
              <SpeakerWaveIcon aria-hidden="true" />
              <div><strong id="notification-sound-label">Notification sounds</strong><p>Play a sound when a new notification arrives.</p></div>
              <button type="button" className="notification-drawer__switch" role="switch"
                aria-checked={Boolean(soundEnabled)} aria-labelledby="notification-sound-label" onClick={onToggleSound}
              ><span /></button>
            </div>
            <div className="notification-drawer__setting">
              <DevicePhoneMobileIcon aria-hidden="true" />
              <div><strong id="notification-push-label">Browser push notifications</strong><p id="notification-push-description">{pushDescription}</p></div>
              <button type="button" className="notification-drawer__switch" role="switch"
                aria-checked={Boolean(pushState?.enabled)} aria-labelledby="notification-push-label"
                aria-describedby="notification-push-description" aria-busy={Boolean(pushState?.busy)}
                disabled={pushDisabled} onClick={onTogglePush}
              ><span /></button>
            </div>
          </section>
        ) : (
          <>
            <div className="notification-drawer__scope">
              <span>{limitedList ? 'Latest notifications · View the notification center for all.' : 'Your recent updates'}</span>
              <button type="button" className="notification-drawer__icon-button" aria-label="Refresh notifications" disabled={loading} onClick={onRefresh}>
                <ArrowPathIcon aria-hidden="true" className={loading ? 'notification-drawer__spin' : ''} />
              </button>
            </div>
            {loading && notifications.length === 0 ? (
              <div className="notification-drawer__empty" role="status">
                <ArrowPathIcon aria-hidden="true" className="notification-drawer__spin" /><h3>Loading notifications…</h3>
              </div>
            ) : visibleNotifications.length === 0 ? (
              <div className="notification-drawer__empty" role="status">
                <BellSlashIcon aria-hidden="true" />
                <h3>{notifications.length === 0 ? (errorMessage ? 'Notifications unavailable' : 'No notifications yet') : 'No matching notifications'}</h3>
                <p>{notifications.length === 0 && errorMessage ? 'Refresh to try loading your notifications again.'
                  : searchTerm || filter !== 'all' ? 'Try another filter or search your notification center.' : 'New updates will appear here.'}</p>
              </div>
            ) : (
              <div className="notification-drawer__groups" aria-busy={loading}>
                {groups.map((group) => (
                  <section key={group.label} aria-label={group.label}>
                    <h3 className="notification-drawer__group-title">{group.label}</h3>
                    <ul className="notification-drawer__list">
                      {group.items.map((notification) => {
                        const { label, Icon, tone } = categoryStyle(notification)
                        const actionTarget = resolveNotificationTarget(notification)
                        const busy = bulkBusy || busyIds.some((id) => String(id) === String(notification.id))
                        const decisionBusy = busy || decisionLoadingId === notification.id
                        return (
                          <li key={notification.id} aria-label={notification.title} data-notification-id={notification.id}
                            className={`notification-drawer__item${notification.is_read ? '' : ' notification-drawer__item--unread'}`} aria-busy={busy}
                          >
                            <div className={`notification-drawer__category notification-drawer__category--${tone}`}><Icon aria-hidden="true" /></div>
                            <div className="notification-drawer__content">
                              <h4>{notification.title}</h4>
                              <p className="notification-drawer__message">{notification.message}</p>
                              <p className="notification-drawer__metadata">
                                <span>{label}</span><span aria-hidden="true">·</span>
                                <time dateTime={notification.created_at}>{formatDistanceToNow(notification.created_at)}</time>
                                {['HIGH', 'URGENT'].includes(notification.priority?.toUpperCase()) && (
                                  <span className="notification-drawer__priority">{notification.priority.toUpperCase() === 'URGENT' ? 'Urgent' : 'High priority'}</span>
                                )}
                              </p>
                              {notification.metadata?.action_type === 'offboarding_project_manager_decision' && (
                                canDecideOffboardingNotification(notification) ? (
                                  <div className="notification-drawer__decisions">
                                    <button type="button" disabled={decisionBusy} onClick={() => onOffboardingDecision(notification, 'approved')}>
                                      <CheckCircleIcon aria-hidden="true" /> Approve
                                    </button>
                                    <button type="button" className="notification-drawer__reject" disabled={decisionBusy} onClick={() => onOffboardingDecision(notification, 'rejected')}>
                                      <XMarkIcon aria-hidden="true" /> Reject
                                    </button>
                                  </div>
                                ) : (
                                  <p className="notification-drawer__decision-status">
                                    {notification.metadata?.decision_status === 'pending' ? 'View the exit request for its current approval status.'
                                      : `Exit process ${notification.metadata?.decision_status || 'updated'}`}
                                  </p>
                                )
                              )}
                              {actionTarget && (
                                <Link to={actionTarget.href} reloadDocument={actionTarget.isExternal} className="notification-drawer__record-link"
                                  onClick={() => {
                                    if (!notification.is_read && !busy) onMarkAsRead(notification.id)
                                    onNavigate?.(notification)
                                  }}
                                >
                                  {actionTarget.isRecordPreview ? 'Preview' : notification.action_label || 'View details'}<ArrowRightIcon aria-hidden="true" />
                                </Link>
                              )}
                              {busy && <span className="notification-drawer__row-status" role="status">Updating notification…</span>}
                            </div>
                            <div className="notification-drawer__row-actions">
                              {!notification.is_read && <span className="notification-drawer__unread-dot"><span className="notification-drawer__sr-only">Unread</span></span>}
                              <NotificationActions notification={notification} busy={decisionBusy} onMarkAsRead={onMarkAsRead} onDelete={onDelete} />
                            </div>
                          </li>
                        )
                      })}
                    </ul>
                  </section>
                ))}
              </div>
            )}
          </>
        )}
      </div>

      <footer className="notification-drawer__footer">
        <Link to="/notifications" onClick={() => onNavigate?.()}>
          <ClipboardDocumentListIcon aria-hidden="true" /> View notification center <ArrowRightIcon aria-hidden="true" />
        </Link>
        <button type="button" onClick={() => setPreferencesOpen(true)}>
          <Cog6ToothIcon aria-hidden="true" /> Notification preferences
        </button>
      </footer>
    </section>
  )
})

NotificationDropdown.displayName = 'NotificationDropdown'

export default NotificationDropdown

/**
 * AnnotationEngine.js
 * Advanced AI-driven annotation and documentation system for P&ID diagrams
 * Implements industry-standard documentation practices
 * 
 * Features:
 * - Smart annotation placement avoiding overlaps
 * - Process data callouts (flow, temperature, pressure)
 * - Equipment notes and specifications
 * - Safety warnings and alerts
 * - Revision clouds and tracking
 * - Design notes and legends
 * - Auto-generated documentation
 * - Soft-coded configuration
 */

export class AnnotationEngine {
  constructor(canvasWidth, canvasHeight, options = {}) {
    this.width = canvasWidth
    this.height = canvasHeight
    this.gridSize = options.gridSize || 25
    this.margins = options.margins || { top: 50, right: 50, bottom: 50, left: 50 }
    
    // Annotation types
    this.annotationTypes = {
      NOTE: 'note',
      PROCESS_DATA: 'process_data',
      EQUIPMENT_TAG: 'equipment_tag',
      SAFETY: 'safety',
      DESIGN_BASIS: 'design_basis',
      REVISION: 'revision',
      CALLOUT: 'callout',
      DIMENSION: 'dimension',
      LEGEND: 'legend'
    }
    
    // Annotation styles
    this.styles = {
      note: {
        backgroundColor: '#fef3c7',
        borderColor: '#f59e0b',
        textColor: '#92400e',
        icon: '📝'
      },
      process_data: {
        backgroundColor: '#dbeafe',
        borderColor: '#3b82f6',
        textColor: '#1e40af',
        icon: '📊'
      },
      equipment_tag: {
        backgroundColor: '#e0e7ff',
        borderColor: '#6366f1',
        textColor: '#3730a3',
        icon: '🏷️'
      },
      safety: {
        backgroundColor: '#fee2e2',
        borderColor: '#ef4444',
        textColor: '#991b1b',
        icon: '⚠️'
      },
      design_basis: {
        backgroundColor: '#d1fae5',
        borderColor: '#10b981',
        textColor: '#065f46',
        icon: '📐'
      },
      revision: {
        backgroundColor: '#f3e8ff',
        borderColor: '#a855f7',
        textColor: '#6b21a8',
        icon: '🔄'
      }
    }
    
    // Process data templates
    this.processDataTemplates = {
      flow: { unit: 'm³/h', symbol: 'F', color: '#3b82f6' },
      temperature: { unit: '°C', symbol: 'T', color: '#ef4444' },
      pressure: { unit: 'bar', symbol: 'P', color: '#10b981' },
      level: { unit: '%', symbol: 'L', color: '#f59e0b' },
      density: { unit: 'kg/m³', symbol: 'ρ', color: '#8b5cf6' },
      viscosity: { unit: 'cP', symbol: 'μ', color: '#ec4899' }
    }
    
    // Safety classifications
    this.safetyLevels = {
      CRITICAL: { color: '#dc2626', priority: 1, label: 'CRITICAL' },
      HIGH: { color: '#ea580c', priority: 2, label: 'HIGH' },
      MEDIUM: { color: '#f59e0b', priority: 3, label: 'MEDIUM' },
      LOW: { color: '#84cc16', priority: 4, label: 'LOW' }
    }
    
    // Placed annotations tracking
    this.placedAnnotations = []
  }

  /**
   * Auto-generate annotations based on P&ID data
   */
  generateAnnotations(pidData, equipmentPositions, instrumentPositions, pipeRoutes, options = {}) {
    const annotations = []
    const includeProcessData = options.includeProcessData !== false
    const includeEquipmentNotes = options.includeEquipmentNotes !== false
    const includeSafetyNotes = options.includeSafetyNotes !== false
    const includeDesignBasis = options.includeDesignBasis !== false
    
    // Generate process data annotations for pipes
    if (includeProcessData && pipeRoutes.length > 0) {
      pipeRoutes.forEach(route => {
        const processAnnotations = this.generateProcessDataAnnotations(route)
        annotations.push(...processAnnotations)
      })
    }
    
    // Generate equipment notes
    if (includeEquipmentNotes && equipmentPositions.length > 0) {
      equipmentPositions.forEach(equipment => {
        const equipNotes = this.generateEquipmentAnnotations(equipment)
        annotations.push(...equipNotes)
      })
    }
    
    // Generate safety annotations
    if (includeSafetyNotes) {
      const safetyAnnotations = this.generateSafetyAnnotations(equipmentPositions, pidData)
      annotations.push(...safetyAnnotations)
    }
    
    // Generate design basis annotations
    if (includeDesignBasis && pidData) {
      const designAnnotations = this.generateDesignBasisAnnotations(pidData)
      annotations.push(...designAnnotations)
    }
    
    // Place annotations intelligently
    const placedAnnotations = this.placeAnnotations(annotations, equipmentPositions, pipeRoutes)
    
    return placedAnnotations
  }

  /**
   * Generate process data annotations for pipes
   */
  generateProcessDataAnnotations(route) {
    const annotations = []
    const midPoint = route.waypoints[Math.floor(route.waypoints.length / 2)]
    
    // Flow rate annotation
    if (route.flow_rate || route.design_flow) {
      annotations.push({
        type: this.annotationTypes.PROCESS_DATA,
        subtype: 'flow',
        text: `${route.flow_rate || route.design_flow} ${this.processDataTemplates.flow.unit}`,
        symbol: this.processDataTemplates.flow.symbol,
        x: midPoint.x + 40,
        y: midPoint.y - 30,
        width: 100,
        height: 40,
        associatedElement: route.id,
        priority: 2
      })
    }
    
    // Temperature annotation
    if (route.temperature || route.design_temperature) {
      annotations.push({
        type: this.annotationTypes.PROCESS_DATA,
        subtype: 'temperature',
        text: `${route.temperature || route.design_temperature} ${this.processDataTemplates.temperature.unit}`,
        symbol: this.processDataTemplates.temperature.symbol,
        x: midPoint.x + 40,
        y: midPoint.y,
        width: 100,
        height: 40,
        associatedElement: route.id,
        priority: 2
      })
    }
    
    // Pressure annotation
    if (route.pressure || route.design_pressure) {
      annotations.push({
        type: this.annotationTypes.PROCESS_DATA,
        subtype: 'pressure',
        text: `${route.pressure || route.design_pressure} ${this.processDataTemplates.pressure.unit}`,
        symbol: this.processDataTemplates.pressure.symbol,
        x: midPoint.x + 40,
        y: midPoint.y + 30,
        width: 100,
        height: 40,
        associatedElement: route.id,
        priority: 2
      })
    }
    
    return annotations
  }

  /**
   * Generate equipment annotations
   */
  generateEquipmentAnnotations(equipment) {
    const annotations = []
    
    // Equipment tag annotation
    if (equipment.tag_number) {
      annotations.push({
        type: this.annotationTypes.EQUIPMENT_TAG,
        text: equipment.tag_number,
        description: equipment.description || equipment.equipment_type,
        x: equipment.x,
        y: equipment.y - 80,
        width: 150,
        height: 50,
        associatedElement: equipment.tag_number,
        priority: 1
      })
    }
    
    // Equipment specifications
    if (equipment.specifications || equipment.capacity || equipment.power) {
      const specs = []
      if (equipment.capacity) specs.push(`Capacity: ${equipment.capacity}`)
      if (equipment.power) specs.push(`Power: ${equipment.power}`)
      if (equipment.design_pressure) specs.push(`Design P: ${equipment.design_pressure} bar`)
      if (equipment.design_temperature) specs.push(`Design T: ${equipment.design_temperature}°C`)
      
      if (specs.length > 0) {
        annotations.push({
          type: this.annotationTypes.NOTE,
          text: specs.join('\n'),
          x: equipment.x + 80,
          y: equipment.y,
          width: 180,
          height: 20 + specs.length * 15,
          associatedElement: equipment.tag_number,
          priority: 3
        })
      }
    }
    
    return annotations
  }

  /**
   * Generate safety annotations
   */
  generateSafetyAnnotations(equipmentPositions, pidData) {
    const annotations = []
    
    // Check for pressure vessels
    equipmentPositions.forEach(equipment => {
      const eqType = (equipment.equipment_type || '').toLowerCase()
      
      if (['vessel', 'column', 'reactor', 'drum'].some(t => eqType.includes(t))) {
        const pressure = equipment.design_pressure || 0
        
        if (pressure > 10) {
          annotations.push({
            type: this.annotationTypes.SAFETY,
            text: 'HIGH PRESSURE VESSEL',
            detail: `Design: ${pressure} bar\nRequires PSV`,
            x: equipment.x + 100,
            y: equipment.y - 50,
            width: 200,
            height: 60,
            safetyLevel: pressure > 40 ? 'CRITICAL' : 'HIGH',
            associatedElement: equipment.tag_number,
            priority: 1
          })
        }
      }
      
      // Check for flammable/toxic fluids
      if (equipment.fluid) {
        const fluid = equipment.fluid.toLowerCase()
        if (['hydrogen', 'methane', 'propane', 'butane', 'gasoline'].some(f => fluid.includes(f))) {
          annotations.push({
            type: this.annotationTypes.SAFETY,
            text: 'FLAMMABLE FLUID',
            detail: `${equipment.fluid}\nFire protection required`,
            x: equipment.x - 120,
            y: equipment.y,
            width: 200,
            height: 60,
            safetyLevel: 'HIGH',
            associatedElement: equipment.tag_number,
            priority: 1
          })
        }
      }
    })
    
    return annotations
  }

  /**
   * Generate design basis annotations
   */
  generateDesignBasisAnnotations(pidData) {
    const annotations = []
    
    // Design conditions
    if (pidData.design_temperature || pidData.design_pressure) {
      annotations.push({
        type: this.annotationTypes.DESIGN_BASIS,
        text: 'DESIGN CONDITIONS',
        detail: [
          pidData.design_temperature ? `Temperature: ${pidData.design_temperature}°C` : null,
          pidData.design_pressure ? `Pressure: ${pidData.design_pressure} bar` : null,
          pidData.design_flow ? `Flow: ${pidData.design_flow} m³/h` : null
        ].filter(Boolean).join('\n'),
        x: this.margins.left + 20,
        y: this.margins.top + 20,
        width: 250,
        height: 80,
        fixed: true,
        priority: 3
      })
    }
    
    // Process description
    if (pidData.process_description || pidData.pid_description) {
      annotations.push({
        type: this.annotationTypes.NOTE,
        text: 'PROCESS DESCRIPTION',
        detail: pidData.process_description || pidData.pid_description,
        x: this.margins.left + 20,
        y: this.margins.top + 120,
        width: 300,
        height: 100,
        fixed: true,
        priority: 3
      })
    }
    
    return annotations
  }

  /**
   * Intelligently place annotations avoiding overlaps
   */
  placeAnnotations(annotations, equipmentPositions, pipeRoutes) {
    this.placedAnnotations = []
    
    // Sort by priority (lower number = higher priority)
    const sortedAnnotations = [...annotations].sort((a, b) => 
      (a.priority || 5) - (b.priority || 5)
    )
    
    sortedAnnotations.forEach(annotation => {
      if (annotation.fixed) {
        // Fixed position annotations (like legends)
        this.placedAnnotations.push(annotation)
      } else {
        // Find best position avoiding overlaps
        const bestPosition = this.findBestPosition(annotation, equipmentPositions, pipeRoutes)
        this.placedAnnotations.push({
          ...annotation,
          x: bestPosition.x,
          y: bestPosition.y
        })
      }
    })
    
    return this.placedAnnotations
  }

  /**
   * Find best position for annotation
   */
  findBestPosition(annotation, equipmentPositions, pipeRoutes) {
    const originalX = annotation.x
    const originalY = annotation.y
    
    // Try original position first
    if (!this.hasOverlap({ ...annotation, x: originalX, y: originalY })) {
      return { x: originalX, y: originalY }
    }
    
    // Try positions around original
    const offsets = [
      { dx: 0, dy: -50 },   // Above
      { dx: 0, dy: 50 },    // Below
      { dx: 50, dy: 0 },    // Right
      { dx: -50, dy: 0 },   // Left
      { dx: 50, dy: -50 },  // Top-right
      { dx: 50, dy: 50 },   // Bottom-right
      { dx: -50, dy: -50 }, // Top-left
      { dx: -50, dy: 50 }   // Bottom-left
    ]
    
    for (const offset of offsets) {
      const testX = originalX + offset.dx
      const testY = originalY + offset.dy
      
      if (!this.hasOverlap({ ...annotation, x: testX, y: testY })) {
        return { x: testX, y: testY }
      }
    }
    
    // If all positions overlap, return original with slight offset
    return { x: originalX + 60, y: originalY }
  }

  /**
   * Check if annotation overlaps with existing elements
   */
  hasOverlap(annotation) {
    // Check against other placed annotations
    return this.placedAnnotations.some(placed => {
      return this.rectanglesOverlap(
        annotation.x, annotation.y, annotation.width, annotation.height,
        placed.x, placed.y, placed.width, placed.height
      )
    })
  }

  /**
   * Check if two rectangles overlap
   */
  rectanglesOverlap(x1, y1, w1, h1, x2, y2, w2, h2) {
    return !(x1 + w1 < x2 || x2 + w2 < x1 || y1 + h1 < y2 || y2 + h2 < y1)
  }

  /**
   * Generate revision cloud around area
   */
  generateRevisionCloud(centerX, centerY, radius, revisionNumber, description) {
    return {
      type: this.annotationTypes.REVISION,
      x: centerX - radius,
      y: centerY - radius,
      width: radius * 2,
      height: radius * 2,
      cloudRadius: radius,
      revisionNumber,
      description,
      date: new Date().toLocaleDateString(),
      priority: 1
    }
  }

  /**
   * Generate notes legend
   */
  generateNotesLegend(notes) {
    return {
      type: this.annotationTypes.LEGEND,
      text: 'NOTES',
      items: notes.map((note, index) => ({
        number: index + 1,
        text: note
      })),
      x: this.margins.left + 20,
      y: this.height - this.margins.bottom - 200,
      width: 400,
      height: Math.min(200, 40 + notes.length * 20),
      fixed: true,
      priority: 4
    }
  }

  /**
   * Generate process data table
   */
  generateProcessDataTable(processData) {
    return {
      type: this.annotationTypes.LEGEND,
      text: 'PROCESS DATA SUMMARY',
      tableHeaders: ['Parameter', 'Normal', 'Design', 'Unit'],
      tableData: processData,
      x: this.width - this.margins.right - 450,
      y: this.margins.top + 20,
      width: 430,
      height: Math.min(300, 60 + processData.length * 25),
      fixed: true,
      priority: 4
    }
  }

  /**
   * Add custom annotation
   */
  addAnnotation(type, text, x, y, options = {}) {
    const annotation = {
      type,
      text,
      x,
      y,
      width: options.width || 150,
      height: options.height || 60,
      detail: options.detail || '',
      priority: options.priority || 3,
      ...options
    }
    
    this.placedAnnotations.push(annotation)
    return annotation
  }

  /**
   * Generate automatic callouts for equipment
   */
  generateCallouts(equipmentPositions, style = 'leader') {
    const callouts = []
    
    equipmentPositions.forEach((equipment, index) => {
      if (!equipment.tag_number) return
      
      const angle = (index * Math.PI / 4) + Math.PI / 6
      const distance = 100
      
      callouts.push({
        type: this.annotationTypes.CALLOUT,
        text: equipment.tag_number,
        description: equipment.description || equipment.equipment_type,
        fromX: equipment.x,
        fromY: equipment.y,
        toX: equipment.x + Math.cos(angle) * distance,
        toY: equipment.y + Math.sin(angle) * distance,
        width: 140,
        height: 50,
        style,
        priority: 2
      })
    })
    
    return callouts
  }

  /**
   * Generate dimensioning annotations
   */
  generateDimensions(element1, element2, type = 'horizontal') {
    const dx = Math.abs(element2.x - element1.x)
    const dy = Math.abs(element2.y - element1.y)
    
    return {
      type: this.annotationTypes.DIMENSION,
      fromX: element1.x,
      fromY: element1.y,
      toX: element2.x,
      toY: element2.y,
      distance: type === 'horizontal' ? dx : dy,
      unit: 'mm',
      dimensionType: type,
      priority: 4
    }
  }

  /**
   * Get annotation style
   */
  getStyle(type) {
    return this.styles[type] || this.styles.note
  }

  /**
   * Export annotations as data
   */
  exportAnnotations() {
    return {
      annotations: this.placedAnnotations,
      metadata: {
        totalAnnotations: this.placedAnnotations.length,
        byType: this.getAnnotationCountByType(),
        generated: new Date().toISOString()
      }
    }
  }

  /**
   * Get count by type
   */
  getAnnotationCountByType() {
    const counts = {}
    this.placedAnnotations.forEach(annotation => {
      counts[annotation.type] = (counts[annotation.type] || 0) + 1
    })
    return counts
  }

  /**
   * Clear all annotations
   */
  clearAnnotations() {
    this.placedAnnotations = []
  }

  /**
   * Filter annotations by type
   */
  filterByType(type) {
    return this.placedAnnotations.filter(a => a.type === type)
  }
}

/**
 * Equipment Placement Engine
 * Advanced AI-driven equipment placement for P&ID diagrams
 * Uses process flow analysis, industry standards, and optimization algorithms
 * 
 * Features:
 * - Smart auto-placement based on process sequence
 * - Equipment type-based grouping
 * - Elevation-aware positioning
 * - Collision detection
 * - Flow optimization
 * - Industry standard spacing
 */

export class EquipmentPlacementEngine {
  constructor(canvasWidth, canvasHeight, config = {}) {
    this.canvasWidth = canvasWidth
    this.canvasHeight = canvasHeight
    this.config = {
      minSpacing: config.minSpacing || 150,
      gridSize: config.gridSize || 50,
      margins: config.margins || { top: 100, right: 100, bottom: 100, left: 100 },
      equipmentSizes: config.equipmentSizes || {
        pump: { width: 60, height: 60 },
        tank: { width: 80, height: 100 },
        vessel: { width: 80, height: 100 },
        column: { width: 60, height: 150 },
        reactor: { width: 100, height: 120 },
        heat_exchanger: { width: 80, height: 60 },
        compressor: { width: 70, height: 70 },
        separator: { width: 90, height: 90 },
        default: { width: 70, height: 70 }
      },
      elevationLevels: config.elevationLevels || {
        overhead: 0.2,    // 20% from top
        high: 0.35,       // 35% from top
        medium: 0.5,      // 50% from top (middle)
        low: 0.65,        // 65% from top
        ground: 0.85      // 85% from top
      }
    }
  }

  /**
   * Main placement function - analyzes equipment and generates optimal positions
   * @param {Array} equipmentList - List of equipment from P&ID data
   * @param {Object} options - Placement options
   * @returns {Array} - Equipment with calculated positions
   */
  placeEquipment(equipmentList, options = {}) {
    const {
      flowDirection = 'left-to-right', // 'left-to-right', 'top-to-bottom', 'auto'
      layoutStyle = 'process-sequence', // 'process-sequence', 'equipment-type', 'elevation', 'grid'
      autoOptimize = true,
      respectElevation = true
    } = options

    // Step 1: Analyze equipment and build process graph
    const analysis = this.analyzeEquipment(equipmentList)
    
    // Step 2: Determine optimal flow direction if auto
    const optimalDirection = flowDirection === 'auto' 
      ? this.determineOptimalFlowDirection(analysis)
      : flowDirection

    // Step 3: Apply layout strategy
    let positions = []
    switch (layoutStyle) {
      case 'process-sequence':
        positions = this.layoutByProcessSequence(equipmentList, analysis, optimalDirection)
        break
      case 'equipment-type':
        positions = this.layoutByEquipmentType(equipmentList, optimalDirection)
        break
      case 'elevation':
        positions = this.layoutByElevation(equipmentList, analysis)
        break
      case 'grid':
        positions = this.layoutInGrid(equipmentList)
        break
      default:
        positions = this.layoutByProcessSequence(equipmentList, analysis, optimalDirection)
    }

    // Step 4: Apply elevation adjustments if enabled
    if (respectElevation) {
      positions = this.applyElevationAdjustments(positions, analysis)
    }

    // Step 5: Optimize positions to avoid collisions
    if (autoOptimize) {
      positions = this.optimizePositions(positions)
    }

    // Step 6: Snap to grid
    positions = this.snapToGrid(positions)

    return positions
  }

  /**
   * Analyze equipment to understand process flow and relationships
   */
  analyzeEquipment(equipmentList) {
    const analysis = {
      majorEquipment: [],
      rotatingEquipment: [],
      heatExchangers: [],
      vessels: [],
      processSequence: [],
      elevationRequirements: {}
    }

    equipmentList.forEach((equipment, index) => {
      const type = (equipment.equipment_type || equipment.type || '').toLowerCase()
      const tag = equipment.tag || `EQUIP-${index + 1}`

      // Categorize by type
      if (type.includes('column') || type.includes('tower') || type.includes('reactor')) {
        analysis.majorEquipment.push({ ...equipment, index, category: 'major' })
      } else if (type.includes('pump') || type.includes('compressor')) {
        analysis.rotatingEquipment.push({ ...equipment, index, category: 'rotating' })
      } else if (type.includes('exchanger') || type.includes('cooler') || type.includes('heater')) {
        analysis.heatExchangers.push({ ...equipment, index, category: 'heat_transfer' })
      } else if (type.includes('tank') || type.includes('vessel') || type.includes('drum') || type.includes('separator')) {
        analysis.vessels.push({ ...equipment, index, category: 'vessel' })
      }

      // Determine elevation requirements
      analysis.elevationRequirements[tag] = this.determineElevation(equipment)

      // Build process sequence (simplified - in real scenario would analyze connections)
      analysis.processSequence.push({ ...equipment, index, sequenceOrder: index })
    })

    return analysis
  }

  /**
   * Determine optimal flow direction based on equipment types
   */
  determineOptimalFlowDirection(analysis) {
    // If we have tall equipment (columns), prefer left-to-right
    if (analysis.majorEquipment.length > 2) {
      return 'left-to-right'
    }
    
    // If mostly horizontal equipment, prefer top-to-bottom
    if (analysis.rotatingEquipment.length > analysis.majorEquipment.length) {
      return 'top-to-bottom'
    }

    // Default to industry standard
    return 'left-to-right'
  }

  /**
   * Layout equipment by process sequence (most common in industry)
   */
  layoutByProcessSequence(equipmentList, analysis, flowDirection) {
    const positions = []
    const { margins } = this.config
    
    if (flowDirection === 'left-to-right') {
      // Calculate available width and spacing
      const availableWidth = this.canvasWidth - margins.left - margins.right
      const equipmentCount = equipmentList.length
      const spacing = Math.max(
        this.config.minSpacing,
        availableWidth / Math.max(equipmentCount - 1, 1)
      )

      equipmentList.forEach((equipment, index) => {
        const type = (equipment.equipment_type || equipment.type || 'default').toLowerCase()
        const size = this.config.equipmentSizes[type] || this.config.equipmentSizes.default

        positions.push({
          ...equipment,
          x: margins.left + index * spacing,
          y: this.canvasHeight / 2, // Center vertically (will adjust by elevation later)
          width: size.width,
          height: size.height,
          index,
          sequenceOrder: index
        })
      })
    } else if (flowDirection === 'top-to-bottom') {
      // Calculate available height and spacing
      const availableHeight = this.canvasHeight - margins.top - margins.bottom
      const equipmentCount = equipmentList.length
      const spacing = Math.max(
        this.config.minSpacing,
        availableHeight / Math.max(equipmentCount - 1, 1)
      )

      equipmentList.forEach((equipment, index) => {
        const type = (equipment.equipment_type || equipment.type || 'default').toLowerCase()
        const size = this.config.equipmentSizes[type] || this.config.equipmentSizes.default

        positions.push({
          ...equipment,
          x: this.canvasWidth / 2, // Center horizontally
          y: margins.top + index * spacing,
          width: size.width,
          height: size.height,
          index,
          sequenceOrder: index
        })
      })
    }

    return positions
  }

  /**
   * Layout equipment grouped by type
   */
  layoutByEquipmentType(equipmentList, flowDirection) {
    const positions = []
    const groups = {}

    // Group equipment by type
    equipmentList.forEach((equipment, index) => {
      const type = (equipment.equipment_type || equipment.type || 'default').toLowerCase()
      const category = this.getEquipmentCategory(type)
      
      if (!groups[category]) {
        groups[category] = []
      }
      groups[category].push({ ...equipment, index })
    })

    // Place each group
    const groupKeys = Object.keys(groups)
    const { margins } = this.config

    if (flowDirection === 'left-to-right') {
      const groupSpacing = (this.canvasWidth - margins.left - margins.right) / groupKeys.length
      
      groupKeys.forEach((category, groupIndex) => {
        const groupEquipment = groups[category]
        const groupX = margins.left + groupIndex * groupSpacing
        const verticalSpacing = 120

        groupEquipment.forEach((equipment, eqIndex) => {
          const type = (equipment.equipment_type || equipment.type || 'default').toLowerCase()
          const size = this.config.equipmentSizes[type] || this.config.equipmentSizes.default

          positions.push({
            ...equipment,
            x: groupX,
            y: margins.top + eqIndex * verticalSpacing,
            width: size.width,
            height: size.height,
            category
          })
        })
      })
    } else {
      const groupSpacing = (this.canvasHeight - margins.top - margins.bottom) / groupKeys.length
      
      groupKeys.forEach((category, groupIndex) => {
        const groupEquipment = groups[category]
        const groupY = margins.top + groupIndex * groupSpacing
        const horizontalSpacing = 120

        groupEquipment.forEach((equipment, eqIndex) => {
          const type = (equipment.equipment_type || equipment.type || 'default').toLowerCase()
          const size = this.config.equipmentSizes[type] || this.config.equipmentSizes.default

          positions.push({
            ...equipment,
            x: margins.left + eqIndex * horizontalSpacing,
            y: groupY,
            width: size.width,
            height: size.height,
            category
          })
        })
      })
    }

    return positions
  }

  /**
   * Layout equipment by elevation (critical for gravity-driven processes)
   */
  layoutByElevation(equipmentList, analysis) {
    const positions = []
    const { margins, elevationLevels } = this.config

    equipmentList.forEach((equipment, index) => {
      const tag = equipment.tag || `EQUIP-${index + 1}`
      const elevationLevel = analysis.elevationRequirements[tag] || 'medium'
      const type = (equipment.equipment_type || equipment.type || 'default').toLowerCase()
      const size = this.config.equipmentSizes[type] || this.config.equipmentSizes.default

      // Calculate Y position based on elevation
      const y = margins.top + (this.canvasHeight - margins.top - margins.bottom) * elevationLevels[elevationLevel]

      // Distribute horizontally
      const horizontalSpacing = (this.canvasWidth - margins.left - margins.right) / Math.max(equipmentList.length, 1)

      positions.push({
        ...equipment,
        x: margins.left + index * horizontalSpacing,
        y: y,
        width: size.width,
        height: size.height,
        index,
        elevation: elevationLevel
      })
    })

    return positions
  }

  /**
   * Layout equipment in a grid pattern
   */
  layoutInGrid(equipmentList) {
    const positions = []
    const { margins } = this.config
    
    const cols = Math.ceil(Math.sqrt(equipmentList.length))
    const rows = Math.ceil(equipmentList.length / cols)
    
    const cellWidth = (this.canvasWidth - margins.left - margins.right) / cols
    const cellHeight = (this.canvasHeight - margins.top - margins.bottom) / rows

    equipmentList.forEach((equipment, index) => {
      const row = Math.floor(index / cols)
      const col = index % cols
      const type = (equipment.equipment_type || equipment.type || 'default').toLowerCase()
      const size = this.config.equipmentSizes[type] || this.config.equipmentSizes.default

      positions.push({
        ...equipment,
        x: margins.left + col * cellWidth + cellWidth / 2,
        y: margins.top + row * cellHeight + cellHeight / 2,
        width: size.width,
        height: size.height,
        index,
        gridPos: { row, col }
      })
    })

    return positions
  }

  /**
   * Apply elevation adjustments based on equipment type and process requirements
   */
  applyElevationAdjustments(positions, analysis) {
    return positions.map(pos => {
      const tag = pos.tag || `EQUIP-${pos.index + 1}`
      const elevationLevel = analysis.elevationRequirements[tag] || 'medium'
      const type = (pos.equipment_type || pos.type || '').toLowerCase()

      // Adjust Y position based on elevation while maintaining general layout
      let elevationOffset = 0
      
      switch (elevationLevel) {
        case 'overhead':
          elevationOffset = -150
          break
        case 'high':
          elevationOffset = -75
          break
        case 'medium':
          elevationOffset = 0
          break
        case 'low':
          elevationOffset = 75
          break
        case 'ground':
          elevationOffset = 150
          break
      }

      return {
        ...pos,
        y: pos.y + elevationOffset,
        elevation: elevationLevel
      }
    })
  }

  /**
   * Optimize positions to avoid collisions and maintain minimum spacing
   */
  optimizePositions(positions) {
    const optimized = [...positions]
    const maxIterations = 50
    let iteration = 0

    while (iteration < maxIterations) {
      let hasCollision = false

      for (let i = 0; i < optimized.length; i++) {
        for (let j = i + 1; j < optimized.length; j++) {
          const eq1 = optimized[i]
          const eq2 = optimized[j]

          if (this.checkCollision(eq1, eq2)) {
            hasCollision = true
            // Adjust positions to resolve collision
            this.resolveCollision(eq1, eq2)
          }
        }
      }

      if (!hasCollision) break
      iteration++
    }

    return optimized
  }

  /**
   * Check if two equipment items collide
   */
  checkCollision(eq1, eq2) {
    const margin = this.config.minSpacing / 2
    return (
      Math.abs(eq1.x - eq2.x) < (eq1.width + eq2.width) / 2 + margin &&
      Math.abs(eq1.y - eq2.y) < (eq1.height + eq2.height) / 2 + margin
    )
  }

  /**
   * Resolve collision by adjusting positions
   */
  resolveCollision(eq1, eq2) {
    const dx = eq2.x - eq1.x
    const dy = eq2.y - eq1.y
    const distance = Math.sqrt(dx * dx + dy * dy)
    
    if (distance === 0) return

    const minDistance = this.config.minSpacing
    const overlap = minDistance - distance
    
    const moveX = (dx / distance) * overlap / 2
    const moveY = (dy / distance) * overlap / 2

    eq1.x -= moveX
    eq1.y -= moveY
    eq2.x += moveX
    eq2.y += moveY
  }

  /**
   * Snap positions to grid
   */
  snapToGrid(positions) {
    return positions.map(pos => ({
      ...pos,
      x: Math.round(pos.x / this.config.gridSize) * this.config.gridSize,
      y: Math.round(pos.y / this.config.gridSize) * this.config.gridSize
    }))
  }

  /**
   * Determine elevation requirement for equipment
   */
  determineElevation(equipment) {
    const type = (equipment.equipment_type || equipment.type || '').toLowerCase()
    const description = (equipment.description || equipment.service || '').toLowerCase()

    // Overhead equipment
    if (type.includes('condenser') || description.includes('overhead') || 
        type.includes('reflux drum') || description.includes('top product')) {
      return 'overhead'
    }

    // High elevation
    if (type.includes('column') || type.includes('tower') || type.includes('accumulator')) {
      return 'high'
    }

    // Low elevation
    if (type.includes('reboiler') || description.includes('bottom') ||
        description.includes('sump') || type.includes('bottom receiver')) {
      return 'low'
    }

    // Ground level
    if (type.includes('pump') || description.includes('pump')) {
      return 'ground'
    }

    // Default to medium
    return 'medium'
  }

  /**
   * Get equipment category for grouping
   */
  getEquipmentCategory(type) {
    if (type.includes('column') || type.includes('tower') || type.includes('reactor')) {
      return 'major'
    } else if (type.includes('pump') || type.includes('compressor')) {
      return 'rotating'
    } else if (type.includes('exchanger') || type.includes('cooler') || type.includes('heater')) {
      return 'heat_transfer'
    } else if (type.includes('tank') || type.includes('vessel') || type.includes('drum')) {
      return 'vessel'
    }
    return 'other'
  }

  /**
   * Re-arrange specific equipment maintaining relationships
   */
  reArrange(positions, equipmentIndex, newX, newY) {
    const updated = [...positions]
    if (equipmentIndex >= 0 && equipmentIndex < updated.length) {
      updated[equipmentIndex] = {
        ...updated[equipmentIndex],
        x: newX,
        y: newY
      }
    }
    return this.optimizePositions(updated)
  }
}

// Export singleton instance
export default EquipmentPlacementEngine

/**
 * InstrumentationEngine.js
 * Advanced AI-driven instrumentation placement and control loop management
 * Implements ISA-5.1 standards for P&ID instrumentation
 * 
 * Features:
 * - Auto instrument detection and categorization
 * - Smart instrument placement (field, panel, DCS)
 * - Control loop visualization and identification
 * - Signal line routing with different styles
 * - ISA-5.1 compliant symbols and nomenclature
 * - Soft-coded configuration
 */

export class InstrumentationEngine {
  constructor(canvasWidth, canvasHeight, options = {}) {
    this.width = canvasWidth
    this.height = canvasHeight
    this.gridSize = options.gridSize || 25
    this.instrumentSize = options.instrumentSize || 40
    this.panelHeight = options.panelHeight || 100
    this.margins = options.margins || { top: 50, right: 50, bottom: 50, left: 50 }
    
    // ISA-5.1 Instrument categories
    this.instrumentCategories = {
      // Measured variables (first letter)
      measured: {
        'A': 'Analysis',
        'B': 'Burner/Combustion',
        'C': 'Conductivity',
        'D': 'Density',
        'E': 'Voltage',
        'F': 'Flow',
        'G': 'Gauging',
        'H': 'Hand',
        'I': 'Current',
        'J': 'Power',
        'K': 'Time',
        'L': 'Level',
        'M': 'Moisture',
        'N': 'User defined',
        'O': 'User defined',
        'P': 'Pressure',
        'Q': 'Quantity',
        'R': 'Radiation',
        'S': 'Speed',
        'T': 'Temperature',
        'U': 'Multivariable',
        'V': 'Vibration',
        'W': 'Weight',
        'X': 'Unclassified',
        'Y': 'Event',
        'Z': 'Position'
      },
      // Function (subsequent letters)
      functions: {
        'A': 'Alarm',
        'C': 'Controller',
        'E': 'Element (Sensor)',
        'G': 'Glass/Gauge',
        'I': 'Indicator',
        'K': 'Control Station',
        'L': 'Light',
        'O': 'Orifice',
        'R': 'Recorder',
        'S': 'Switch',
        'T': 'Transmitter',
        'V': 'Valve',
        'W': 'Well',
        'X': 'Unclassified',
        'Y': 'Relay/Compute',
        'Z': 'Driver/Actuator'
      }
    }
    
    // Instrument mounting locations
    this.mountingLocations = {
      field: 'FIELD_MOUNTED',
      panel: 'PANEL_MOUNTED',
      dcs: 'DCS_MOUNTED',
      shared: 'SHARED_DISPLAY'
    }
    
    // Signal line styles
    this.signalLineStyles = {
      pneumatic: 'dashed',
      electric: 'solid',
      hydraulic: 'dashdot',
      capillary: 'dotted',
      wireless: 'dashdotdot',
      software: 'dotted'
    }
  }

  /**
   * Place instruments on P&ID based on equipment and control strategy
   */
  placeInstruments(equipmentPositions, instrumentData, options = {}) {
    const strategy = options.placementStrategy || 'auto'
    const showControlLoops = options.showControlLoops !== false
    const groupByLoop = options.groupByLoop !== false
    
    const placedInstruments = []
    const controlLoops = []
    
    // Parse and categorize instruments
    const categorizedInstruments = this.categorizeInstruments(instrumentData)
    
    // Identify control loops
    if (showControlLoops) {
      const loops = this.identifyControlLoops(categorizedInstruments)
      controlLoops.push(...loops)
    }
    
    // Place instruments based on strategy
    switch (strategy) {
      case 'auto':
        return this.placeInstrumentsAuto(equipmentPositions, categorizedInstruments, controlLoops)
      case 'by-equipment':
        return this.placeByEquipment(equipmentPositions, categorizedInstruments)
      case 'by-function':
        return this.placeByFunction(equipmentPositions, categorizedInstruments)
      case 'by-loop':
        return this.placeByControlLoop(equipmentPositions, categorizedInstruments, controlLoops)
      default:
        return this.placeInstrumentsAuto(equipmentPositions, categorizedInstruments, controlLoops)
    }
  }

  /**
   * Categorize instruments based on ISA-5.1 tag nomenclature
   */
  categorizeInstruments(instrumentData) {
    return instrumentData.map(instrument => {
      const tag = instrument.tag_number || instrument.tag || ''
      const analysis = this.analyzeInstrumentTag(tag)
      
      return {
        ...instrument,
        ...analysis,
        mountingLocation: this.determineMountingLocation(instrument, analysis),
        signalType: this.determineSignalType(instrument, analysis),
        connectionPoint: this.determineConnectionPoint(instrument, analysis)
      }
    })
  }

  /**
   * Analyze instrument tag based on ISA-5.1 standard
   */
  analyzeInstrumentTag(tag) {
    // Format: XXX-YYY where XXX is function letters, YYY is loop number
    const match = tag.match(/^([A-Z]+)-?(\d+)?([A-Z])?$/)
    
    if (!match) {
      return {
        measuredVariable: 'X',
        functions: ['I'],
        loopNumber: '000',
        suffix: '',
        isValid: false
      }
    }
    
    const [, letters, loopNum, suffix] = match
    const measuredVariable = letters[0] || 'X'
    const functions = letters.slice(1).split('') || ['I']
    
    return {
      measuredVariable,
      functions,
      loopNumber: loopNum || '000',
      suffix: suffix || '',
      isValid: true,
      description: this.getInstrumentDescription(measuredVariable, functions)
    }
  }

  /**
   * Get human-readable instrument description
   */
  getInstrumentDescription(measuredVariable, functions) {
    const variable = this.instrumentCategories.measured[measuredVariable] || 'Unknown'
    const functionDesc = functions.map(f => this.instrumentCategories.functions[f] || '').join(' ')
    return `${variable} ${functionDesc}`.trim()
  }

  /**
   * Determine mounting location based on instrument type
   */
  determineMountingLocation(instrument, analysis) {
    const { functions } = analysis
    
    // Transmitters and elements are usually field mounted
    if (functions.includes('T') || functions.includes('E')) {
      return this.mountingLocations.field
    }
    
    // Controllers and indicators are usually panel/DCS mounted
    if (functions.includes('C') || functions.includes('R')) {
      return this.mountingLocations.dcs
    }
    
    // Indicators can be local or panel
    if (functions.includes('I')) {
      return instrument.is_local ? this.mountingLocations.field : this.mountingLocations.panel
    }
    
    // Default to field mounted
    return this.mountingLocations.field
  }

  /**
   * Determine signal type
   */
  determineSignalType(instrument, analysis) {
    const type = (instrument.signal_type || '').toLowerCase()
    
    if (type.includes('pneumatic') || type.includes('air')) return 'pneumatic'
    if (type.includes('wireless') || type.includes('radio')) return 'wireless'
    if (type.includes('hart') || type.includes('fieldbus') || type.includes('profibus')) return 'electric'
    
    // Default to electric for modern instruments
    return 'electric'
  }

  /**
   * Determine which equipment this instrument connects to
   */
  determineConnectionPoint(instrument, analysis) {
    // Check if instrument has explicit equipment reference
    if (instrument.equipment_tag || instrument.associated_equipment) {
      return instrument.equipment_tag || instrument.associated_equipment
    }
    
    // Try to infer from tag number or description
    const desc = (instrument.description || '').toLowerCase()
    const tag = instrument.tag_number || ''
    
    // Look for equipment references in description
    const equipmentTypes = ['pump', 'vessel', 'tank', 'column', 'exchanger', 'reactor', 'drum']
    for (const eqType of equipmentTypes) {
      if (desc.includes(eqType)) {
        return eqType
      }
    }
    
    return null
  }

  /**
   * Identify control loops from instruments
   */
  identifyControlLoops(instruments) {
    const loops = new Map()
    
    instruments.forEach(instrument => {
      const loopId = instrument.loopNumber
      
      if (!loops.has(loopId)) {
        loops.set(loopId, {
          loopId,
          instruments: [],
          measuredVariable: instrument.measuredVariable,
          hasController: false,
          hasTransmitter: false,
          hasValve: false,
          hasIndicator: false
        })
      }
      
      const loop = loops.get(loopId)
      loop.instruments.push(instrument)
      
      // Track loop components
      if (instrument.functions.includes('C')) loop.hasController = true
      if (instrument.functions.includes('T')) loop.hasTransmitter = true
      if (instrument.functions.includes('V')) loop.hasValve = true
      if (instrument.functions.includes('I')) loop.hasIndicator = true
    })
    
    return Array.from(loops.values())
  }

  /**
   * Auto placement - intelligent positioning based on instrument type
   */
  placeInstrumentsAuto(equipmentPositions, instruments, controlLoops) {
    const positioned = []
    const panelInstruments = []
    const fieldInstruments = []
    const dcsInstruments = []
    
    // Separate by mounting location
    instruments.forEach(instrument => {
      switch (instrument.mountingLocation) {
        case this.mountingLocations.field:
          fieldInstruments.push(instrument)
          break
        case this.mountingLocations.panel:
          panelInstruments.push(instrument)
          break
        case this.mountingLocations.dcs:
          dcsInstruments.push(instrument)
          break
        default:
          fieldInstruments.push(instrument)
      }
    })
    
    // Place field instruments near their equipment
    fieldInstruments.forEach((instrument, index) => {
      const equipment = this.findEquipmentForInstrument(instrument, equipmentPositions)
      
      if (equipment) {
        // Place around equipment
        const angle = (index * Math.PI / 4) + Math.PI / 8
        const distance = 80
        
        positioned.push({
          ...instrument,
          x: equipment.x + Math.cos(angle) * distance,
          y: equipment.y + Math.sin(angle) * distance,
          connectedEquipment: equipment
        })
      } else {
        // Place in grid if no equipment found
        const col = index % 5
        const row = Math.floor(index / 5)
        positioned.push({
          ...instrument,
          x: this.margins.left + col * 100,
          y: this.height - this.margins.bottom - this.panelHeight - 100 - row * 80
        })
      }
    })
    
    // Place panel instruments in bottom panel area
    panelInstruments.forEach((instrument, index) => {
      positioned.push({
        ...instrument,
        x: this.margins.left + (index * 100) + 50,
        y: this.height - this.margins.bottom - 50,
        isPanel: true
      })
    })
    
    // Place DCS instruments in top area
    dcsInstruments.forEach((instrument, index) => {
      positioned.push({
        ...instrument,
        x: this.margins.left + (index * 100) + 50,
        y: this.margins.top + 30,
        isDCS: true
      })
    })
    
    return positioned
  }

  /**
   * Place instruments grouped by equipment
   */
  placeByEquipment(equipmentPositions, instruments) {
    const positioned = []
    
    equipmentPositions.forEach((equipment, eqIndex) => {
      const instrumentsForEquipment = instruments.filter(inst => 
        this.isInstrumentForEquipment(inst, equipment)
      )
      
      instrumentsForEquipment.forEach((instrument, instIndex) => {
        const angle = (instIndex * Math.PI / 3) + Math.PI / 6
        const distance = 70 + (instIndex * 10)
        
        positioned.push({
          ...instrument,
          x: equipment.x + Math.cos(angle) * distance,
          y: equipment.y + Math.sin(angle) * distance,
          connectedEquipment: equipment
        })
      })
    })
    
    return positioned
  }

  /**
   * Place instruments grouped by function
   */
  placeByFunction(equipmentPositions, instruments) {
    const positioned = []
    const functionGroups = new Map()
    
    // Group by primary function
    instruments.forEach(instrument => {
      const primaryFunction = instrument.functions[0] || 'I'
      if (!functionGroups.has(primaryFunction)) {
        functionGroups.set(primaryFunction, [])
      }
      functionGroups.get(primaryFunction).push(instrument)
    })
    
    let groupIndex = 0
    functionGroups.forEach((group, functionType) => {
      const baseY = this.margins.top + 100 + (groupIndex * 150)
      
      group.forEach((instrument, index) => {
        positioned.push({
          ...instrument,
          x: this.margins.left + (index * 100) + 50,
          y: baseY,
          functionGroup: functionType
        })
      })
      
      groupIndex++
    })
    
    return positioned
  }

  /**
   * Place instruments grouped by control loop
   */
  placeByControlLoop(equipmentPositions, instruments, controlLoops) {
    const positioned = []
    
    controlLoops.forEach((loop, loopIndex) => {
      const baseX = this.margins.left + (loopIndex % 4) * 300
      const baseY = this.margins.top + 100 + Math.floor(loopIndex / 4) * 200
      
      loop.instruments.forEach((instrument, instIndex) => {
        positioned.push({
          ...instrument,
          x: baseX + (instIndex * 80),
          y: baseY,
          loopId: loop.loopId,
          loopSequence: instIndex
        })
      })
    })
    
    return positioned
  }

  /**
   * Route signal lines from instruments to equipment
   */
  routeSignalLines(instrumentPositions, equipmentPositions, options = {}) {
    const routes = []
    
    instrumentPositions.forEach(instrument => {
      // Find connected equipment
      const equipment = instrument.connectedEquipment || 
                       this.findEquipmentForInstrument(instrument, equipmentPositions)
      
      if (!equipment) return
      
      // Create signal line route
      const route = {
        id: `signal_${instrument.tag_number}`,
        from: { x: instrument.x, y: instrument.y },
        to: { x: equipment.x, y: equipment.y },
        signalType: instrument.signalType,
        lineStyle: this.signalLineStyles[instrument.signalType] || 'solid',
        instrument: instrument,
        equipment: equipment
      }
      
      // Add waypoint for cleaner routing
      if (Math.abs(equipment.x - instrument.x) > 100 && 
          Math.abs(equipment.y - instrument.y) > 100) {
        route.waypoints = [
          route.from,
          { x: instrument.x, y: equipment.y },
          route.to
        ]
      } else {
        route.waypoints = [route.from, route.to]
      }
      
      routes.push(route)
    })
    
    return routes
  }

  /**
   * Find equipment that this instrument should connect to
   */
  findEquipmentForInstrument(instrument, equipmentPositions) {
    // Try exact match on connection point
    if (instrument.connectionPoint) {
      const exact = equipmentPositions.find(eq => 
        (eq.tag_number || '').toLowerCase().includes(instrument.connectionPoint.toLowerCase())
      )
      if (exact) return exact
    }
    
    // Try to match by type
    const measuredVar = instrument.measuredVariable
    
    if (measuredVar === 'F') { // Flow - look for pumps or pipes
      return equipmentPositions.find(eq => 
        (eq.equipment_type || '').toLowerCase().includes('pump')
      )
    }
    
    if (measuredVar === 'L') { // Level - look for tanks/vessels
      return equipmentPositions.find(eq => 
        ['tank', 'vessel', 'drum'].some(type => 
          (eq.equipment_type || '').toLowerCase().includes(type)
        )
      )
    }
    
    if (measuredVar === 'P') { // Pressure - look for vessels
      return equipmentPositions.find(eq => 
        ['vessel', 'column', 'reactor'].some(type => 
          (eq.equipment_type || '').toLowerCase().includes(type)
        )
      )
    }
    
    if (measuredVar === 'T') { // Temperature - look for exchangers/reactors
      return equipmentPositions.find(eq => 
        ['exchanger', 'reactor', 'furnace'].some(type => 
          (eq.equipment_type || '').toLowerCase().includes(type)
        )
      )
    }
    
    // Default to closest equipment
    if (equipmentPositions.length > 0) {
      return equipmentPositions.reduce((closest, eq) => {
        const distCurrent = this.distance(instrument, eq)
        const distClosest = this.distance(instrument, closest)
        return distCurrent < distClosest ? eq : closest
      })
    }
    
    return null
  }

  /**
   * Check if instrument is for specific equipment
   */
  isInstrumentForEquipment(instrument, equipment) {
    const eqTag = (equipment.tag_number || '').toLowerCase()
    const instConnection = (instrument.connectionPoint || '').toLowerCase()
    const instDesc = (instrument.description || '').toLowerCase()
    
    return instConnection.includes(eqTag) || 
           instDesc.includes(eqTag) ||
           eqTag.includes(instConnection)
  }

  /**
   * Generate ISA-5.1 compliant instrument symbols
   */
  getInstrumentSymbol(instrument) {
    // Safely extract properties with defaults
    const mountingLocation = instrument?.mountingLocation || instrument?.mounting_location || 'field'
    const functions = instrument?.functions || instrument?.function || []
    const measuredVariable = instrument?.measuredVariable || instrument?.measured_variable || instrument?.variable || 'X'
    
    // Ensure functions is an array
    const functionsArray = Array.isArray(functions) ? functions : [functions].filter(Boolean)
    
    // Determine circle type based on mounting
    let circleType = 'field' // Solid circle
    if (mountingLocation === this.mountingLocations.panel || mountingLocation === 'panel') {
      circleType = 'panel' // Circle mounted on line
    } else if (mountingLocation === this.mountingLocations.dcs || mountingLocation === 'dcs' || mountingLocation === 'computer') {
      circleType = 'dcs' // Square or hexagon
    }
    
    // Determine if balloon should be shown
    const showBalloon = functionsArray.includes('C') || functionsArray.includes('I') || functionsArray.includes('R')
    
    return {
      circleType,
      showBalloon,
      letters: `${measuredVariable}${functionsArray.join('')}`,
      loopNumber: instrument?.loopNumber || instrument?.loop_number || '001'
    }
  }

  /**
   * Calculate distance between two points
   */
  distance(a, b) {
    const dx = (b.x || 0) - (a.x || 0)
    const dy = (b.y || 0) - (a.y || 0)
    return Math.sqrt(dx * dx + dy * dy)
  }

  /**
   * Auto-generate instruments based on equipment
   */
  autoGenerateInstruments(equipmentList) {
    const instruments = []
    let loopCounter = 100
    
    equipmentList.forEach((equipment, index) => {
      const eqType = (equipment.equipment_type || '').toLowerCase()
      
      // Pumps get flow and pressure instruments
      if (eqType.includes('pump')) {
        instruments.push({
          tag_number: `FT-${loopCounter}`,
          description: `${equipment.tag_number || 'PUMP'} Flow Transmitter`,
          equipment_tag: equipment.tag_number,
          signal_type: 'electric'
        })
        loopCounter++
        
        instruments.push({
          tag_number: `PT-${loopCounter}`,
          description: `${equipment.tag_number || 'PUMP'} Discharge Pressure`,
          equipment_tag: equipment.tag_number,
          signal_type: 'electric'
        })
        loopCounter++
      }
      
      // Vessels get level and pressure
      if (['tank', 'vessel', 'drum'].some(t => eqType.includes(t))) {
        instruments.push({
          tag_number: `LT-${loopCounter}`,
          description: `${equipment.tag_number || 'VESSEL'} Level Transmitter`,
          equipment_tag: equipment.tag_number,
          signal_type: 'electric'
        })
        loopCounter++
        
        instruments.push({
          tag_number: `PT-${loopCounter}`,
          description: `${equipment.tag_number || 'VESSEL'} Pressure`,
          equipment_tag: equipment.tag_number,
          signal_type: 'electric'
        })
        loopCounter++
      }
      
      // Heat exchangers get temperature
      if (eqType.includes('exchanger') || eqType.includes('heater') || eqType.includes('cooler')) {
        instruments.push({
          tag_number: `TT-${loopCounter}`,
          description: `${equipment.tag_number || 'EXCHANGER'} Outlet Temperature`,
          equipment_tag: equipment.tag_number,
          signal_type: 'electric'
        })
        loopCounter++
      }
    })
    
    return instruments
  }
}

