/**
 * useAIChampionTracker — client-side telemetry for the AI Champion leaderboard
 * ===========================================================================
 *
 * Fires `analyticsService.trackActivity` on every authenticated route change so
 * the AI Champion dashboard at /admin/ai-champion receives LIVE engagement
 * data. The backend middleware ALSO captures every API request, so this hook
 * primarily provides richer client-side context (route, dwell time) and
 * captures pure-frontend page views that don't hit the API.
 *
 * All thresholds and the URL→application/feature mapping are SOFT-CODED below
 * so admins can rebalance without touching component code.
 *
 * Failure semantics: NEVER throws. Tracking errors are logged at debug level.
 */
import { useEffect, useRef } from 'react';
import { useLocation } from 'react-router-dom';
import { useSelector } from 'react-redux';
import analyticsService from '../services/analyticsService';

// ---------------------------------------------------------------------------
// Soft-coded configuration
// ---------------------------------------------------------------------------

// Telemetry transport tuning. The route-view track is fire-and-forget, so we
// cap its request timeout aggressively — otherwise this background POST can
// queue behind a long synchronous extraction (e.g. ADNOC P&ID instrument
// index) and hang for the global 120 s default, surfacing a noisy
// `ECONNABORTED` error in DevTools. Tweak via env without code changes:
//   VITE_TRACKER_TIMEOUT_MS — axios timeout for telemetry POST (default 10s)
const TRACKER_TIMEOUT_MS = Number(import.meta.env?.VITE_TRACKER_TIMEOUT_MS ?? 10000);

// ---------------------------------------------------------------------------
// Soft-coded configuration
// ---------------------------------------------------------------------------

// Skip tracking for these route prefixes (auth pages, error pages, public pages)
const EXCLUDE_PREFIXES = [
  '/login',
  '/register',
  '/setup-password',
  '/change-password',
  '/request-password-reset',
  '/terms',
  '/privacy',
  '/about',
  '/solutions',
  '/enquiry',
  '/contact-support',
  '/documentation',
];

// Min dwell-time (ms) before we consider a page "viewed" — avoids spam from
// brief redirects.
const MIN_DWELL_MS = 750;

// Throttle: don't fire more than one event per route per this window
const THROTTLE_WINDOW_MS = 2000;

// Route segment → application code mapping. Order matters: first hit wins.
const APPLICATION_MAP = [
  // [substring, application, module]
  ['/admin/ai-champion',         'ai-champion',         'admin'],
  ['/admin/predictive',          'predictive-insights', 'admin'],
  ['/admin/advanced-analytics',  'advanced-analytics',  'admin'],
  ['/admin',                     'admin-dashboard',     'admin'],
  ['/users',                     'user-management',     'admin'],
  ['/dashboard',                 'dashboard',           'platform'],
  ['/engineering/process/pid',   'pid-verification',    'process'],
  ['/engineering/process/pfd',   'pfd-quality',         'process'],
  ['/engineering/process/equipment', 'equipment-list',  'process'],
  ['/engineering/process/line',  'line-list',           'process'],
  ['/engineering/process',       'process-datasheet',   'process'],
  ['/engineering/electrical',    'electrical',          'electrical'],
  ['/engineering/instrument',    'instrument',          'instrument'],
  ['/engineering/mechanical',    'mechanical',          'mechanical'],
  ['/engineering/piping',        'piping',              'piping'],
  ['/engineering/civil',         'civil',               'civil'],
  ['/engineering/digitization',  'digitization',        'digitization'],
  ['/qhse',                      'qhse',                'qhse'],
  ['/crs',                       'crs',                 'documents'],
  ['/finance',                   'finance',             'finance'],
  ['/procurement',               'procurement',         'procurement'],
  ['/sales',                     'sales',               'sales'],
  ['/wrench',                    'wrench-integration',  'integrations'],
  ['/designiq',                  'designiq',            'designiq'],
  ['/notifications',             'notifications',       'platform'],
  ['/profile',                   'profile',             'platform'],
];

// Stable per-tab session id so the backend can correlate events
const SESSION_KEY = 'radai_ai_champion_session';

const getSessionId = () => {
  try {
    let sid = sessionStorage.getItem(SESSION_KEY);
    if (!sid) {
      sid = `s_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 10)}`;
      sessionStorage.setItem(SESSION_KEY, sid);
    }
    return sid;
  } catch {
    return '';
  }
};

const resolveAppFeature = (pathname) => {
  for (const [needle, app, module] of APPLICATION_MAP) {
    if (pathname.startsWith(needle)) {
      const tail = pathname.slice(needle.length).replace(/^\/+/, '');
      const feature = (tail.split('/')[0] || 'index').slice(0, 64);
      return { application: app, module, feature };
    }
  }
  // Fallback: use first path segment as the application code
  const segs = pathname.split('/').filter(Boolean);
  return {
    application: segs[0] || 'platform',
    module: 'platform',
    feature: segs[1] || 'index',
  };
};

const isExcluded = (pathname) =>
  EXCLUDE_PREFIXES.some((p) => pathname.startsWith(p));

// ---------------------------------------------------------------------------
// Hook
// ---------------------------------------------------------------------------
const useAIChampionTracker = () => {
  const location = useLocation();
  const { isAuthenticated } = useSelector((s) => s.auth || {});
  const lastTrackRef = useRef({ path: '', at: 0 });
  const dwellStartRef = useRef({ path: '', at: 0 });

  useEffect(() => {
    if (!isAuthenticated) return undefined;

    const pathname = location.pathname || '/';
    if (isExcluded(pathname)) return undefined;

    // Throttle identical-path events
    const now = Date.now();
    if (
      lastTrackRef.current.path === pathname &&
      now - lastTrackRef.current.at < THROTTLE_WINDOW_MS
    ) {
      return undefined;
    }

    // Record dwell on the previous route, if any
    const prev = dwellStartRef.current;
    dwellStartRef.current = { path: pathname, at: now };

    // Schedule the track — only fires if the user stays on the page
    const controller = new AbortController();
    const timer = setTimeout(() => {
      const { application, module, feature } = resolveAppFeature(pathname);
      const dwellMs = prev.path && prev.at ? now - prev.at : 0;

      const payload = {
        application,
        module,
        feature,
        action_type: 'view',
        session_id: getSessionId(),
        duration_ms: Math.max(0, dwellMs),
        success: true,
        metadata: {
          source: 'frontend-route',
          path: pathname,
          referrer: prev.path || '',
        },
      };

      // Fire-and-forget telemetry. We pass an aggressive soft-coded
      // timeout so this background POST can never block the UI for the
      // 120 s global default, even when a worker is busy with a long
      // synchronous extraction. Errors are silenced — the global axios
      // interceptor also treats `/rbac/ai-champion/track/` as a silent
      // endpoint to avoid noisy `[API Error]` logs / toasts.
      analyticsService.trackActivity(payload, {
        timeout: TRACKER_TIMEOUT_MS,
        signal: controller.signal,
      }).then(() => {
        lastTrackRef.current = { path: pathname, at: now };
      }).catch((err) => {
        if (process.env.NODE_ENV !== 'production') {
          // eslint-disable-next-line no-console
          console.debug('[AIChampionTracker] track failed:', err?.message);
        }
      });
    }, MIN_DWELL_MS);

    return () => {
      clearTimeout(timer);
      controller.abort();
    };
  }, [location.pathname, isAuthenticated]);
};

export default useAIChampionTracker;

import { useState, useEffect, useRef, useCallback } from 'react';
import { ACTIVITY_CONFIG } from '../config/activity.config';

const WS_BASE_URL = import.meta.env.VITE_WS_URL || 'ws://localhost:8000';

/**
 * Custom hook for real-time activity stream
 * Manages WebSocket connection and activity data
 */
export const useActivityStream = () => {
  const [activities, setActivities] = useState([]);
  const [activeUsers, setActiveUsers] = useState([]);
  const [statistics, setStatistics] = useState({
    total_last_hour: 0,
    total_last_24h: 0,
    by_category: {},
    by_severity: {},
    success_rate: 100,
    average_duration: 0,
  });
  const [connectionStatus, setConnectionStatus] = useState('disconnected');
  const [error, setError] = useState(null);
  
  const wsRef = useRef(null);
  const reconnectTimeoutRef = useRef(null);
  const reconnectAttemptsRef = useRef(0);
  const pingIntervalRef = useRef(null);

  /**
   * Send message to WebSocket
   */
  const sendMessage = useCallback((data) => {
    if (wsRef.current?.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify(data));
    }
  }, []);

  /**
   * Request filtered activities
   */
  const requestActivities = useCallback((filters = {}) => {
    sendMessage({
      type: 'get_activities',
      category: filters.category || 'all',
      limit: filters.limit || ACTIVITY_CONFIG.display.defaultLimit,
    });
  }, [sendMessage]);

  /**
   * Request activity statistics
   */
  const requestStatistics = useCallback(() => {
    sendMessage({ type: 'get_statistics' });
  }, [sendMessage]);

  /**
   * Request active users
   */
  const requestActiveUsers = useCallback(() => {
    sendMessage({ type: 'get_active_users' });
  }, [sendMessage]);

  /**
   * Handle incoming WebSocket messages
   */
  const handleMessage = useCallback((event) => {
    try {
      const data = JSON.parse(event.data);
      
      switch (data.type) {
        case 'initial_data':
          setActivities(data.activities || []);
          setActiveUsers(data.active_users || []);
          break;
          
        case 'new_activity':
          setActivities(prev => {
            const newActivities = [data.activity, ...prev];
            // Keep only recent activities to prevent memory issues
            return newActivities.slice(0, ACTIVITY_CONFIG.display.defaultLimit);
          });
          break;
          
        case 'activity_update':
          setActivities(prev => 
            prev.map(activity => 
              activity.id === data.activity.id ? data.activity : activity
            )
          );
          break;
          
        case 'activities':
          setActivities(data.activities || []);
          break;
          
        case 'active_users':
          setActiveUsers(data.users || []);
          break;
          
        case 'statistics':
          setStatistics(data.stats || {});
          break;
          
        case 'periodic_update':
          if (data.new_activities?.length > 0) {
            setActivities(prev => {
              const newActivities = [...data.new_activities, ...prev];
              return newActivities.slice(0, ACTIVITY_CONFIG.display.defaultLimit);
            });
          }
          if (data.active_users) {
            setActiveUsers(data.active_users);
          }
          if (data.statistics) {
            setStatistics(data.statistics);
          }
          break;
          
        case 'pong':
          // Keep-alive response
          break;
          
        case 'error':
          console.error('Activity stream error:', data.message);
          setError(data.message);
          break;
          
        default:
          console.log('Unknown message type:', data.type);
      }
    } catch (err) {
      console.error('Error parsing WebSocket message:', err);
    }
  }, []);

  /**
   * Start ping interval for keep-alive
   */
  const startPingInterval = useCallback(() => {
    if (pingIntervalRef.current) {
      clearInterval(pingIntervalRef.current);
    }
    
    pingIntervalRef.current = setInterval(() => {
      if (wsRef.current?.readyState === WebSocket.OPEN) {
        wsRef.current.send(JSON.stringify({ type: 'ping' }));
      }
    }, ACTIVITY_CONFIG.websocket.pingInterval);
  }, []);

  /**
   * Connect to WebSocket
   */
  const connect = useCallback(() => {
    try {
      setConnectionStatus('connecting');
      setError(null);
      
      const ws = new WebSocket(`${WS_BASE_URL}/ws/activity/`);
      
      ws.onopen = () => {
        console.log('Activity stream connected');
        setConnectionStatus('connected');
        reconnectAttemptsRef.current = 0;
        startPingInterval();
        
        // Request initial data
        requestStatistics();
        requestActiveUsers();
      };
      
      ws.onmessage = handleMessage;
      
      ws.onerror = (error) => {
        console.error('WebSocket error:', error);
        setError('Connection error');
        setConnectionStatus('error');
      };
      
      ws.onclose = (event) => {
        console.log('Activity stream disconnected:', event.code, event.reason);
        setConnectionStatus('disconnected');
        
        // Clear ping interval
        if (pingIntervalRef.current) {
          clearInterval(pingIntervalRef.current);
          pingIntervalRef.current = null;
        }
        
        // Attempt to reconnect
        if (reconnectAttemptsRef.current < ACTIVITY_CONFIG.websocket.maxReconnectAttempts) {
          reconnectAttemptsRef.current += 1;
          console.log(`Reconnecting... Attempt ${reconnectAttemptsRef.current}`);
          
          reconnectTimeoutRef.current = setTimeout(() => {
            connect();
          }, ACTIVITY_CONFIG.websocket.reconnectDelay);
        } else {
          setError('Max reconnection attempts reached');
        }
      };
      
      wsRef.current = ws;
    } catch (err) {
      console.error('Error creating WebSocket:', err);
      setError(err.message);
      setConnectionStatus('error');
    }
  }, [handleMessage, startPingInterval, requestStatistics, requestActiveUsers]);

  /**
   * Disconnect from WebSocket
   */
  const disconnect = useCallback(() => {
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
      reconnectTimeoutRef.current = null;
    }
    
    if (pingIntervalRef.current) {
      clearInterval(pingIntervalRef.current);
      pingIntervalRef.current = null;
    }
    
    setConnectionStatus('disconnected');
  }, []);

  /**
   * Initialize connection on mount
   */
  useEffect(() => {
    connect();
    
    return () => {
      disconnect();
    };
  }, []);

  /**
   * Get filtered activities
   */
  const getFilteredActivities = useCallback((filters = {}) => {
    let filtered = [...activities];
    
    // Filter by category
    if (filters.category && filters.category !== 'all') {
      filtered = filtered.filter(a => a.category === filters.category);
    }
    
    // Filter by severity
    if (filters.severity && filters.severity !== 'all') {
      filtered = filtered.filter(a => a.severity === filters.severity);
    }
    
    // Filter by time range
    if (filters.minutes) {
      const cutoffTime = new Date(Date.now() - filters.minutes * 60 * 1000);
      filtered = filtered.filter(a => new Date(a.timestamp) >= cutoffTime);
    }
    
    // Filter by search term
    if (filters.search) {
      const search = filters.search.toLowerCase();
      filtered = filtered.filter(a => 
        a.description?.toLowerCase().includes(search) ||
        a.user_name?.toLowerCase().includes(search) ||
        a.user_email?.toLowerCase().includes(search)
      );
    }
    
    return filtered;
  }, [activities]);

  return {
    // Data
    activities,
    activeUsers,
    statistics,
    
    // State
    connectionStatus,
    isConnected: connectionStatus === 'connected',
    error,
    
    // Actions
    requestActivities,
    requestStatistics,
    requestActiveUsers,
    getFilteredActivities,
    reconnect: connect,
    disconnect,
  };
};

/**
 * Custom React Hook for Field Recommendations
 * Provides easy integration of recommendations into forms
 */

import { useState, useEffect, useCallback } from 'react';
import RecommendationsService from '../services/recommendations.service';

/**
 * Hook for managing field recommendations
 * @param {Object} formData - Current form state
 * @param {Object} options - Hook options
 * @returns {Object} Recommendations state and helpers
 */
export const useFieldRecommendations = (formData = {}, options = {}) => {
  const {
    autoFetch = true,
    context = {},
    onRecommendationsLoaded = null
  } = options;

  const [recommendations, setRecommendations] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  /**
   * Fetch recommendations from API
   */
  const fetchRecommendations = useCallback(async (forceRefresh = false) => {
    setLoading(true);
    setError(null);

    try {
      // Build context from form data if not provided
      const fetchContext = {
        ...context,
        project_no: context.project_no || formData.project_no,
        tag_prefix: context.tag_prefix || (formData.tag_no ? formData.tag_no.substring(0, 3) : null)
      };

      const data = await RecommendationsService.getRecommendations(fetchContext, forceRefresh);
      setRecommendations(data);

      if (onRecommendationsLoaded) {
        onRecommendationsLoaded(data);
      }

      console.log('✅ Recommendations loaded in hook:', data.context);
    } catch (err) {
      setError(err.message);
      console.error('❌ Hook: Failed to fetch recommendations:', err);
    } finally {
      setLoading(false);
    }
  }, [formData.project_no, formData.tag_no, context, onRecommendationsLoaded]);

  /**
   * Auto-fetch on mount if enabled
   */
  useEffect(() => {
    if (autoFetch) {
      fetchRecommendations();
    }
  }, []); // Only run on mount

  /**
   * Get suggestions for a specific field
   */
  const getSuggestionsForField = useCallback((fieldName) => {
    if (!recommendations) return [];
    return RecommendationsService.getTextFieldSuggestions(fieldName, recommendations);
  }, [recommendations]);

  /**
   * Get numeric suggestion for a field
   */
  const getNumericSuggestion = useCallback((fieldName) => {
    if (!recommendations) return null;
    return RecommendationsService.getNumericFieldSuggestion(fieldName, recommendations);
  }, [recommendations]);

  /**
   * Apply suggestion to a field
   */
  const applySuggestion = useCallback((fieldName, value, setFieldValue) => {
    console.log(`💡 Applying suggestion for ${fieldName}:`, value);
    setFieldValue(fieldName, value);
  }, []);

  /**
   * Auto-fill multiple fields with suggestions
   */
  const autoFillForm = useCallback((fieldsToFill, setFormData) => {
    if (!recommendations) {
      console.warn('⚠️ No recommendations available for auto-fill');
      return;
    }

    const updates = RecommendationsService.autoFillFields(
      formData,
      fieldsToFill,
      recommendations
    );

    if (Object.keys(updates).length > 0) {
      console.log('🎯 Auto-filling fields:', Object.keys(updates));
      setFormData(prevData => ({
        ...prevData,
        ...updates
      }));
    } else {
      console.log('ℹ️ No fields to auto-fill (all have values or no suggestions)');
    }
  }, [formData, recommendations]);

  /**
   * Get smart motor efficiency suggestion
   */
  const getMotorEfficiencySuggestion = useCallback((motorClassification) => {
    if (!recommendations || !motorClassification) return null;
    return RecommendationsService.suggestMotorEfficiency(motorClassification, recommendations);
  }, [recommendations]);

  /**
   * Check if recommendations are ready
   */
  const isReady = !loading && recommendations !== null && !error;

  /**
   * Get recommendation statistics
   */
  const stats = recommendations?.context || null;

  return {
    // State
    recommendations,
    loading,
    error,
    isReady,
    stats,
    
    // Methods
    fetchRecommendations,
    getSuggestionsForField,
    getNumericSuggestion,
    applySuggestion,
    autoFillForm,
    getMotorEfficiencySuggestion,
    
    // Utilities
    clearCache: RecommendationsService.clearCache
  };
};

export default useFieldRecommendations;

/**
 * Real-time Detection Hook
 * WebSocket integration for live ML detection updates
 */
import { useState, useEffect, useCallback, useRef } from 'react';
import { API_BASE_URL } from '../config/api.config';

const WS_BASE_URL = API_BASE_URL.replace('http', 'ws').replace('https', 'wss');

export const useRealTimeDetection = (options = {}) => {
  const {
    autoConnect = false,
    reconnectInterval = 5000,
    onAlert = null,
    onAnomaly = null,
    onMetrics = null
  } = options;

  const [isConnected, setIsConnected] = useState(false);
  const [alerts, setAlerts] = useState([]);
  const [metrics, setMetrics] = useState(null);
  const [lastUpdate, setLastUpdate] = useState(null);
  const [error, setError] = useState(null);

  const wsRef = useRef(null);
  const reconnectTimeoutRef = useRef(null);

  const connect = useCallback(() => {
    try {
      const ws = new WebSocket(`${WS_BASE_URL}/ws/detection/`);

      ws.onopen = () => {
        console.log('🟢 Real-time detection WebSocket connected');
        setIsConnected(true);
        setError(null);
      };

      ws.onmessage = (event) => {
        try {
          const data = JSON.parse(event.data);
          handleMessage(data);
        } catch (err) {
          console.error('Failed to parse WebSocket message:', err);
        }
      };

      ws.onerror = (err) => {
        console.error('❌ WebSocket error:', err);
        setError('WebSocket connection error');
      };

      ws.onclose = () => {
        console.log('🔴 WebSocket disconnected');
        setIsConnected(false);

        // Auto-reconnect
        if (autoConnect) {
          reconnectTimeoutRef.current = setTimeout(() => {
            console.log('🔄 Attempting to reconnect...');
            connect();
          }, reconnectInterval);
        }
      };

      wsRef.current = ws;
    } catch (err) {
      console.error('Failed to create WebSocket:', err);
      setError('Failed to establish connection');
    }
  }, [autoConnect, reconnectInterval]);

  const handleMessage = (data) => {
    setLastUpdate(new Date().toISOString());

    switch (data.type) {
      case 'connection_established':
        console.log('✅ Connection established:', data.message);
        break;

      case 'new_alert':
        console.log('🚨 New alert:', data.alert);
        setAlerts((prev) => [data.alert, ...prev].slice(0, 50)); // Keep last 50
        if (onAlert) onAlert(data.alert);
        break;

      case 'alerts_update':
        setAlerts(data.alerts);
        break;

      case 'periodic_update':
        if (data.alerts) {
          setAlerts(data.alerts);
        }
        if (data.metrics) {
          setMetrics(data.metrics);
          if (onMetrics) onMetrics(data.metrics);
        }
        break;

      case 'metrics_update':
        setMetrics(data.metrics);
        if (onMetrics) onMetrics(data.metrics);
        break;

      case 'anomaly_detected':
        console.log('⚠️ Anomaly detected:', data.anomaly);
        if (onAnomaly) onAnomaly(data.anomaly);
        break;

      case 'alert_broadcast':
        console.log('📢 Alert broadcast:', data.alert);
        setAlerts((prev) => {
          const exists = prev.find((a) => a.id === data.alert.id);
          if (exists) {
            return prev.map((a) => (a.id === data.alert.id ? data.alert : a));
          }
          return [data.alert, ...prev].slice(0, 50);
        });
        if (onAlert) onAlert(data.alert);
        break;

      case 'error':
        console.error('❌ Server error:', data.message);
        setError(data.message);
        break;

      default:
        console.log('📨 Unknown message type:', data.type);
    }
  };

  const disconnect = useCallback(() => {
    if (reconnectTimeoutRef.current) {
      clearTimeout(reconnectTimeoutRef.current);
    }
    if (wsRef.current) {
      wsRef.current.close();
      wsRef.current = null;
    }
    setIsConnected(false);
  }, []);

  const requestAlerts = useCallback(() => {
    if (wsRef.current && isConnected) {
      wsRef.current.send(JSON.stringify({ type: 'request_alerts' }));
    }
  }, [isConnected]);

  const requestMetrics = useCallback(() => {
    if (wsRef.current && isConnected) {
      wsRef.current.send(JSON.stringify({ type: 'request_metrics' }));
    }
  }, [isConnected]);

  const acknowledgeAlert = useCallback((alertId) => {
    if (wsRef.current && isConnected) {
      wsRef.current.send(JSON.stringify({
        type: 'acknowledge_alert',
        alert_id: alertId
      }));
    }
  }, [isConnected]);

  // Auto-connect on mount
  useEffect(() => {
    if (autoConnect) {
      connect();
    }

    return () => {
      disconnect();
    };
  }, [autoConnect, connect, disconnect]);

  return {
    isConnected,
    alerts,
    metrics,
    lastUpdate,
    error,
    connect,
    disconnect,
    requestAlerts,
    requestMetrics,
    acknowledgeAlert
  };
};


/**
 * System Metrics Hook
 * Real-time system performance metrics
 */
export const useSystemMetrics = (options = {}) => {
  const { autoConnect = false } = options;

  const [isConnected, setIsConnected] = useState(false);
  const [metrics, setMetrics] = useState(null);
  const [history, setHistory] = useState([]);

  const wsRef = useRef(null);

  useEffect(() => {
    if (!autoConnect) return;

    const ws = new WebSocket(`${WS_BASE_URL}/ws/metrics/`);

    ws.onopen = () => {
      console.log('🟢 System metrics WebSocket connected');
      setIsConnected(true);
    };

    ws.onmessage = (event) => {
      try {
        const data = JSON.parse(event.data);
        if (data.type === 'metrics_update') {
          setMetrics(data.metrics);
          setHistory((prev) => [...prev, data.metrics].slice(-100)); // Keep last 100
        }
      } catch (err) {
        console.error('Failed to parse metrics:', err);
      }
    };

    ws.onclose = () => {
      console.log('🔴 Metrics WebSocket disconnected');
      setIsConnected(false);
    };

    wsRef.current = ws;

    return () => {
      if (wsRef.current) {
        wsRef.current.close();
      }
    };
  }, [autoConnect]);

  return {
    isConnected,
    metrics,
    history
  };
};

