};

// ---------------------------------------------------------------------------
// HonoraryEditorModal — soft-coded add/edit form.
// Field list is driven by EDITOR_FIELDS so adding a new attribute is a
// single line change.
// ---------------------------------------------------------------------------
const EDITOR_FIELDS = [
  { key: 'name',    label: 'Full name *',  type: 'text',     placeholder: 'e.g. Tanzeem Agra' },
  { key: 'email',   label: 'Email *',      type: 'email',    placeholder: 'user@company.com' },
  { key: 'title',   label: 'Title / Role', type: 'text',     placeholder: 'e.g. Lead Developer' },
  { key: 'since',   label: 'Contributing since', type: 'date' },
  { key: 'avatar',  label: 'Avatar URL',   type: 'url',      placeholder: 'https://…' },
  { key: 'tagline', label: 'Tagline',      type: 'text',     placeholder: 'One-line motto' },
];

const HonoraryEditorModal = ({ mode, draft, onCancel, onSave }) => {
  const [form, setForm] = useState(draft || {});

  useEffect(() => {
    setForm(draft || {});
  }, [draft]);

  const update = (key, value) => setForm((f) => ({ ...f, [key]: value }));

  const achievementsText = Array.isArray(form.achievements)
    ? form.achievements.join('\n')
    : (form.achievements || '');

  const linksText = Array.isArray(form.links)
    ? form.links.map((l) => `${l.label} | ${l.href}`).join('\n')
    : '';

  const handleSubmit = (e) => {
    e.preventDefault();
    const links = linksText
      .split('\n')
      .map((line) => {
        const [label, href] = line.split('|').map((s) => (s || '').trim());
        return label && href ? { label, href } : null;
      })
      .filter(Boolean);
    onSave({
      ...form,
      achievements: achievementsText.split('\n').map((a) => a.trim()).filter(Boolean),
      links,
    });
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-900/50 backdrop-blur-sm p-4">
      <form
        onSubmit={handleSubmit}
        className="bg-white rounded-2xl shadow-2xl w-full max-w-2xl max-h-[90vh] overflow-y-auto"
      >
        <div className="px-5 py-4 border-b border-slate-200 flex items-center gap-2">
          <SparklesIcon className="w-5 h-5 text-purple-600" />
          <h3 className="font-semibold text-slate-800">
            {mode === 'edit' ? 'Edit Honorary Member' : 'Add Honorary Member'}
          </h3>
          <button
            type="button"
            onClick={onCancel}
            className="ml-auto p-1 rounded-md text-slate-500 hover:bg-slate-100"
          >
            <XMarkIcon className="w-5 h-5" />
          </button>
        </div>
        <div className="p-5 grid grid-cols-1 md:grid-cols-2 gap-4">
          {EDITOR_FIELDS.map((f) => (
            <label key={f.key} className="text-xs font-medium text-slate-600 block">
              {f.label}
              <input
                type={f.type}
                placeholder={f.placeholder || ''}
                value={form[f.key] || ''}
                onChange={(e) => update(f.key, e.target.value)}
                className="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 focus:border-purple-400 focus:ring-2 focus:ring-purple-100 text-sm text-slate-800"
              />
            </label>
          ))}

          <label className="text-xs font-medium text-slate-600 block">
            Tier
            <select
              value={form.tier || HOF_TIER_OPTIONS[0].id}
              onChange={(e) => update('tier', e.target.value)}
              className="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 focus:border-purple-400 focus:ring-2 focus:ring-purple-100 text-sm text-slate-800"
            >
              {HOF_TIER_OPTIONS.map((t) => (
                <option key={t.id} value={t.id}>{t.label}</option>
              ))}
            </select>
          </label>

          <label className="text-xs font-medium text-slate-600 block md:col-span-2">
            Achievements (one per line)
            <textarea
              rows={4}
              value={achievementsText}
              onChange={(e) => update('achievements', e.target.value)}
              placeholder={'e.g. Founded the platform\nDesigned the RBAC system'}
              className="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 focus:border-purple-400 focus:ring-2 focus:ring-purple-100 text-sm text-slate-800"
            />
          </label>

          <label className="text-xs font-medium text-slate-600 block md:col-span-2">
            Links (one per line — format: <code>Label | https://url</code>)
            <textarea
              rows={2}
              defaultValue={linksText}
              onChange={(e) => update('_linksRaw', e.target.value)}
              placeholder={'LinkedIn | https://linkedin.com/in/user'}
              className="mt-1 w-full px-3 py-2 rounded-lg border border-slate-200 focus:border-purple-400 focus:ring-2 focus:ring-purple-100 text-sm text-slate-800"
              onBlur={(e) => {
                const links = e.target.value
                  .split('\n')
                  .map((line) => {
                    const [label, href] = line.split('|').map((s) => (s || '').trim());
                    return label && href ? { label, href } : null;
                  })
                  .filter(Boolean);
                update('links', links);
              }}
            />
          </label>
        </div>
        <div className="px-5 py-3 border-t border-slate-200 flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={onCancel}
            className="px-3 py-1.5 rounded-lg text-sm font-medium bg-white border border-slate-200 text-slate-700 hover:bg-slate-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            className="px-3 py-1.5 rounded-lg text-sm font-semibold bg-purple-600 text-white hover:bg-purple-700 flex items-center gap-1"
          >
            <CheckBadgeIcon className="w-4 h-4" />
            {mode === 'edit' ? 'Save Changes' : 'Add Member'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default AIChampion;

import React, { useEffect, useState } from 'react';
import { BadgeCheck, Clock3, Timer, MessageSquare } from 'lucide-react';
import analyticsService from '../../services/analyticsService';
import './AIWorkflowMeasurements.css';

const defaults = { module: 'planning_package', title: '', task_reference: '', evidence_url: '', comparison: '', baseline_minutes: '', ai_minutes: '', review_minutes: '', rework_minutes: '', measurement: 'measured', contribution_type: 'task', hourly_rate: '', value_currency: '', workflow: null };
const fields = [['title', 'Task title'], ['task_reference', 'Unique task / job reference'], ['evidence_url', 'Evidence link (HTTPS)'], ['baseline_minutes', 'Comparable manual baseline (minutes)'], ['ai_minutes', 'AI-assisted work (minutes)'], ['review_minutes', 'Review time (minutes)'], ['rework_minutes', 'Rework time (minutes)']];

export default function AIOutcomes({ initialWorkflow = null }) {
  const [data, setData] = useState(null);
  const [page, setPage] = useState(1);
  const [revision, setRevision] = useState(0);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [form, setForm] = useState(() => initialWorkflow ? { ...defaults, workflow: initialWorkflow.id, module: initialWorkflow.module, task_reference: `${initialWorkflow.source_type}:${initialWorkflow.source_id}`, title: `${initialWorkflow.module} outcome` } : null);
  const [selected, setSelected] = useState(null);
  const [reason, setReason] = useState('');
  const [confirmed, setConfirmed] = useState(false);
  useEffect(() => {
    const controller = new AbortController(); let active = true;
    setData(null); setError('');
    analyticsService.getAIOutcomes(page, { signal: controller.signal }).then(value => { if (active) setData(value); })
      .catch(() => { if (active) setError('Unable to load outcome evidence. Retry.'); });
    return () => { active = false; controller.abort(); };
  }, [page, revision]);
  const save = async decision => {
    setBusy(true); setError('');
    try {
      if (decision) await analyticsService.reviewAIOutcome({ id: selected.id, decision, reason, comparable_quality_confirmed: confirmed });
      else await analyticsService.submitAIOutcome({ ...form, hourly_rate: form.hourly_rate === '' ? null : form.hourly_rate });
      setForm(null); setSelected(null); setReason(''); setConfirmed(false); setRevision(v => v + 1);
    } catch (e) { setError(e?.response?.data ? JSON.stringify(e.response.data) : 'Could not save evidence. Try again.'); }
    finally { setBusy(false); }
  };
  return <div className="ai-outcomes">
    <div className="ad-panel-heading"><div><h2>Productivity evidence</h2><p>Pilots: Planning packages and P&amp;ID analysis. All-time reviewed observations in your administrative scope.</p></div><button onClick={() => { setForm({ ...defaults }); setSelected(null); }} disabled={busy || !data}>Record outcome</button><button disabled={busy} onClick={() => setRevision(v => v + 1)}>Refresh evidence</button></div>
    {error && <div role="alert" className="ad-info">{error}</div>}
    {!data && !error && <p role="status">Loading outcome evidence…</p>}
    {data && <><div className="ad-kpis">{[['Approved observations', data.totals.approved, BadgeCheck, 'green'], ['Awaiting review', data.totals.pending, Clock3, data.totals.pending ? 'amber' : 'slate'], ['Measured hours freed', data.totals.measured_minutes_saved == null ? 'Not measured' : (data.totals.measured_minutes_saved / 60).toFixed(2), Timer, data.totals.measured_minutes_saved == null ? 'slate' : 'green'], ['Self-reported hours freed', data.totals.self_reported_minutes_saved == null ? 'Not reported' : (data.totals.self_reported_minutes_saved / 60).toFixed(2), MessageSquare, 'slate']].map(([label, value, Icon, tone]) => <div className="ad-kpi" data-tone={tone} key={label}><span className="ad-kpi-icon"><Icon /></span><span><span className="ad-kpi-label">{label}</span><strong>{value}</strong></span></div>)}</div>
      <p>Time freed = manual baseline − AI-assisted work − review − rework. Negative savings remain visible. Hours freed are not cash savings; approval does not convert self-reported estimates into measured results.</p>
      {data.estimated_values?.length > 0 && <section className="ad-panel ao-form"><h2>Estimated capacity value</h2>{data.estimated_values.map(v => <p key={`${v.currency}-${v.measurement}`}>{v.currency} {v.estimated_capacity_value} ? {v.measurement.replace('_', '-')} time ? supplied hourly rate</p>)}<p>Estimated capacity value is not realized revenue, cash savings or ROI. Currencies and measurement sources remain separate.</p></section>}<section className="ad-panel"><div className="ad-table-scroll"><table><thead><tr><th>Task</th><th>Module</th><th>Evidence type</th><th>Net minutes</th><th>Status</th><th>Action</th></tr></thead><tbody>{data.results.map(row => <tr key={row.id}><td>{row.title}</td><td>{row.module}</td><td>{row.measurement.replace('_', '-')}</td><td>{row.saved_minutes}</td><td>{row.status}</td><td><button onClick={() => { setSelected(row); setForm(null); setReason(''); setConfirmed(false); }}>{row.can_review ? 'Review evidence' : 'View details'}</button></td></tr>)}{!data.results.length && <tr><td colSpan="6">No outcome evidence recorded yet.</td></tr>}</tbody></table></div><div className="ad-panel-heading"><button disabled={page === 1 || busy} onClick={() => setPage(v => v - 1)}>Previous</button><span>Page {page} · {data.count} observations</span><button disabled={page * 10 >= data.count || busy} onClick={() => setPage(v => v + 1)}>Next</button></div></section>
      {form && <form className="ad-panel ao-form" onSubmit={e => { e.preventDefault(); save(); }}><h2>Record comparable task evidence</h2>{form.workflow && <p>Linked server workflow: {form.workflow}. Task reference and module are fixed to its persisted output.</p>}<label>AI module<select disabled={!!form.workflow} value={form.module} onChange={e => setForm({ ...form, module: e.target.value })}>{data.modules.map(m => <option key={m.code} value={m.code}>{m.name}</option>)}</select></label>{fields.map(([key, label]) => <label key={key}>{label}<input required maxLength={key === 'evidence_url' ? 1000 : 200} readOnly={key === 'task_reference' && !!form.workflow} type={key.endsWith('minutes') ? 'number' : key === 'evidence_url' ? 'url' : 'text'} min={key === 'baseline_minutes' ? 1 : 0} max={525600} step={1} value={form[key]} onChange={e => setForm({ ...form, [key]: e.target.value })} /></label>)}<label>Contribution evidence<select value={form.contribution_type} onChange={e => setForm({ ...form, contribution_type: e.target.value })}><option value="task">Comparable task outcome</option><option value="workflow_integration" disabled={!form.workflow}>Workflow integration (reviewed maturity 4)</option><option value="automation_creator" disabled={!form.workflow}>Automation creator (reviewed maturity 5)</option></select></label><label>Optional hourly rate for estimated capacity value<input type="number" min="0" max="99999999.99" step="0.01" value={form.hourly_rate} onChange={e => setForm({ ...form, hourly_rate: e.target.value })} /></label><label>Rate currency<select value={form.value_currency} onChange={e => setForm({ ...form, value_currency: e.target.value })}><option value="">No value estimate</option>{['USD','AED','EUR','GBP','SEK'].map(c => <option key={c}>{c}</option>)}</select></label><label>Measurement source<select value={form.measurement} onChange={e => setForm({ ...form, measurement: e.target.value })}><option value="measured">Measured task timings</option><option value="self_reported">Self-reported estimate</option></select></label><label>Explain baseline source, comparable scope and accepted output quality<textarea required minLength={20} maxLength={4000} value={form.comparison} onChange={e => setForm({ ...form, comparison: e.target.value })} /></label><div><button type="button" disabled={busy} onClick={() => setForm(null)}>Cancel</button><button disabled={busy}>Submit for independent review</button></div></form>}
      {selected && <section className="ad-panel ao-form"><h2>{selected.title}</h2><p>{selected.task_reference} · Submitted by {selected.submitted_by}</p><p>{selected.comparison}</p><p>Contribution: {selected.contribution_type || 'task'} ? Workflow: {selected.workflow || 'Not linked'}</p><a href={selected.evidence_url} target="_blank" rel="noopener noreferrer">Open supporting evidence</a><p>Manual: {selected.baseline_minutes} min · AI work: {selected.ai_minutes} min · Review: {selected.review_minutes} min · Rework: {selected.rework_minutes} min</p>{selected.review_reason && <p>Review decision: {selected.review_reason}</p>}{selected.can_review && <><label>Review reason<textarea minLength={10} maxLength={2000} value={reason} onChange={e => setReason(e.target.value)} /></label><label><input type="checkbox" checked={confirmed} onChange={e => setConfirmed(e.target.checked)} /> I checked comparable task scope, baseline evidence, accepted output quality and any integration or automation claim.</label><div><button disabled={busy || reason.trim().length < 10} onClick={() => save('rejected')}>Reject evidence</button><button disabled={busy || reason.trim().length < 10 || !confirmed} onClick={() => save('approved')}>Approve evidence</button></div></>}<button disabled={busy} onClick={() => setSelected(null)}>Close details</button></section>}
    </>}
  </div>;
}

import React, { useEffect, useState } from 'react';
import { Workflow, Users, Clock3, Activity, RefreshCw, Download } from 'lucide-react';
import analyticsService from '../../services/analyticsService';
import './AIWorkflowMeasurements.css';

const moduleName = code => ({ planning_package: 'Planning packages', pid_analysis: 'P&ID analysis', pfd_to_pid: 'PFD to P&ID', designiq: 'DesignIQ', crs_documents: 'CRS documents', pfd_quality: 'PFD Quality' }[code] || code);
const sourceName = type => ({ 'planning_intelligence.PlanningGeneration': 'Planning generation', 'planning_intelligence.DocumentIntelligenceRun': 'Document intelligence run', 'planning_intelligence.PlanningJob': 'Planning job', 'pid_analysis.PIDAnalysisReport': 'P&ID report' }[type] || type);

export default function AIWorkflowMeasurements({ onRecordOutcome }) {
  const [data, setData] = useState(null);
  const [days, setDays] = useState(30);
  const [module, setModule] = useState('');
  const [status, setStatus] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [revision, setRevision] = useState(0);
  const [error, setError] = useState('');
  useEffect(() => {
    const controller = new AbortController(); let active = true;
    setData(null); setError('');
    const timer = setTimeout(() => analyticsService.getAIMeasurements({ days, module, status, search, page }, { signal: controller.signal })
      .then(value => { if (active) setData(value); })
      .catch(() => { if (active) setError('Could not load workflow measurements. Retry the request.'); }), 200);
    return () => { active = false; clearTimeout(timer); controller.abort(); };
  }, [days, module, status, search, page, revision]);
  const exportPage = () => {
    const cell = value => { const s = String(value ?? ''); return `"${(/^[=+@\-\t\r]/.test(s) ? `'${s}` : s).replaceAll('"', '""')}"`; };
    const records = [['Workflow', 'Employee', 'Module', 'Status', 'Started UTC', 'SDK calls', 'Source type', 'Source ID'], ...data.results.map(r => [r.id, r.user, r.module, r.status, r.started_at, r.sdk_calls, r.source_type, r.source_id])];
    const url = URL.createObjectURL(new Blob(['\ufeff', records.map(r => r.map(cell).join(',')).join('\r\n')], { type: 'text/csv' }));
    const link = document.createElement('a'); link.href = url; link.download = `ai-workflows-page-${page}.csv`; link.click(); setTimeout(() => URL.revokeObjectURL(url), 1000);
  };
  const change = setter => e => { setter(e.target.value); setPage(1); };
  return <div className="aw-measurements">
    <div className="aw-toolbar"><div><h2>Workflow measurements</h2><p>Server-observed workflow activity; productivity pilots: Planning packages and P&amp;ID analysis</p></div><label>Period<select aria-label="Workflow reporting period" value={days} onChange={change(setDays)}>{[7, 30, 90, 365].map(n => <option key={n} value={n}>Last {n} days</option>)}</select></label><button onClick={() => setRevision(v => v + 1)}><RefreshCw /> Refresh measurements</button></div>
    {error && <p role="alert">{error}</p>}{!data && !error && <p role="status">Loading workflow measurements…</p>}
    {data && <><div className="ad-kpis">{[
      ['AI workflows', data.totals.ai_workflows, `${data.totals.completed_ai_workflows} completed outputs`, Workflow, 'blue'],
      ['Active employees', data.totals.active_users, 'Employees with observed SDK calls', Users, 'blue'],
      ['Derived AI sessions', data.totals.derived_sessions, '30-minute inactivity boundary', Clock3, 'indigo'],
      ['Provider SDK calls', data.totals.sdk_calls, `${data.totals.successful_sdk_calls} returned successfully`, Activity, 'blue'],
    ].map(([label, value, hint, Icon, tone]) => <div className="ad-kpi" data-tone={tone} key={label}><span className="ad-kpi-icon"><Icon /></span><span><span className="ad-kpi-label">{label}</span><strong>{value}</strong><small>{hint}</small></span></div>)}</div>
      <div className="ad-info"><div><strong>{data.snapshot_stale ? 'Workforce snapshot needs attention' : 'Workforce snapshot available'}</strong><p>Last capture: {data.latest_snapshot ? new Date(data.latest_snapshot).toLocaleString() : 'Not captured'}. Fresh snapshots: {data.snapshot_fresh_organizations ?? 0} of {data.snapshot_organizations ?? 0} organizations. Freshness limit: 36 hours. No historical workforce data is backfilled.</p></div></div>
      <section className="ad-panel"><div className="ad-panel-heading"><h2>Integration coverage</h2><span>Coverage is shown per adapter; no workforce coverage percentage is assumed.</span></div><div className="ad-table-scroll"><table><thead><tr><th>AI module</th><th>Adapter status</th><th>Observed calls</th><th>Uncosted calls</th><th>Last request</th><th>Output reconciliation</th></tr></thead><tbody>{data.coverage.map(r => <tr key={r.module}><td><details><summary>{r.name}</summary><p>{r.boundary}</p><ul>{r.paths.map(p => <li key={p}>{p}</li>)}</ul></details></td><td>{r.status}</td><td>{r.sdk_calls}</td><td>{r.pricing_missing}</td><td>{r.last_request ? new Date(r.last_request).toLocaleString() : 'No observations'}</td><td>{r.reconciliation?.status || 'Not checked'}{r.reconciliation?.unlinked_outputs > 0 && <small>{r.reconciliation.unlinked_outputs} persisted outputs have no workflow reference</small>}</td></tr>)}</tbody></table></div></section>
      <section className="ad-panel"><div className="aw-toolbar"><h2>Workflow register</h2><input aria-label="Search workflows" placeholder="Employee or source reference" value={search} onChange={change(setSearch)} /><select aria-label="Workflow module" value={module} onChange={change(setModule)}><option value="">All modules</option>{data.coverage.map(row => <option key={row.module} value={row.module}>{row.name}</option>)}</select><select aria-label="Workflow status" value={status} onChange={change(setStatus)}><option value="">All statuses</option>{['running', 'completed', 'returned', 'failed', 'no_result'].map(s => <option key={s}>{s}</option>)}</select><button onClick={exportPage}><Download /> Export this page</button></div>
        <div className="ad-table-scroll"><table><thead><tr><th>Employee / workflow</th><th>Module</th><th>Status</th><th>SDK calls</th><th>Result reference</th><th>Action</th></tr></thead><tbody>{data.results.map(r => <tr key={r.id}><td>{r.user}<small>{r.id}</small></td><td>{moduleName(r.module)}</td><td>{r.status === 'no_result' ? 'No output' : r.status === 'returned' ? 'Response returned' : r.status}</td><td>{r.sdk_calls}</td><td>{sourceName(r.source_type) || 'No persisted output'}<small>{r.source_id}</small></td><td>{r.can_record_outcome && <button onClick={() => onRecordOutcome(r)}>Record outcome</button>}{r.outcome_recorded && <span>Evidence recorded</span>}</td></tr>)}{!data.results.length && <tr><td colSpan="6">No server workflow measurements match this period and these filters. Historical requests are not converted into workflows.</td></tr>}</tbody></table></div>
        <div className="aw-toolbar"><span>{data.count} workflows · Page {page} of {Math.max(1, Math.ceil(data.count / 10))}</span><button disabled={page === 1} onClick={() => setPage(v => v - 1)}>Previous workflows</button><button disabled={page * 10 >= data.count} onClick={() => setPage(v => v + 1)}>Next workflows</button></div>
      </section>
      <section className="ad-panel aw-method"><h2>Measurement rules</h2>{data.totals.stalled_workflows > 0 && <p role="status">{data.totals.stalled_workflows} workflows have been running for more than six hours. Check the worker before treating these as completed or failed.</p>}<p>{data.totals.sessions_per_eligible_employee_per_week ?? 'Not available'} derived sessions per eligible employee per week ({data.totals.eligible_employees ?? 0} employees in the reporting cohort).</p><p>{data.totals.sessions_per_active_employee_per_week ?? 'Not available'} derived sessions per active employee per week. User prompts: not measured — generated model messages are not employee prompts.</p>{Object.entries(data.methodology).filter(([k]) => k !== 'version').map(([k, text]) => <details key={k}><summary>{k[0].toUpperCase() + k.slice(1)}</summary><p>{text}</p></details>)}</section>
    </>}
  </div>;
}

/**
 * Admin — Access Requests — /admin/access-requests
 *
 * Lists all module access requests submitted by users.
 * Admins can approve or deny each pending request with an optional note.
 * Status tabs allow quick filtering.
 */

import React, { useEffect, useState, useCallback } from 'react';
import rbacService from '../../services/rbac.service';

// ── Soft-coded constants ─────────────────────────────────────────────────────
const TABS = [
  { key: 'pending',  label: 'Pending'  },
  { key: 'approved', label: 'Approved' },
  { key: 'denied',   label: 'Denied'   },
  { key: '',         label: 'All'      },
];

const STATUS_COLORS = {
  pending:  'bg-yellow-100 text-yellow-800',
  approved: 'bg-green-100  text-green-800',
  denied:   'bg-red-100    text-red-800',
};

const STATUS_LABELS = {
  pending:  'Pending Review',
  approved: 'Approved',
  denied:   'Denied',
};
// ─────────────────────────────────────────────────────────────────────────────

function Badge({ status }) {
  return (
    <span
      className={`inline-block text-xs font-semibold px-2 py-0.5 rounded-full ${
        STATUS_COLORS[status] || 'bg-gray-100 text-gray-700'
      }`}
    >
      {STATUS_LABELS[status] || status}
    </span>
  );
}

function ActionModal({ request, action, onClose, onConfirm }) {
  const [note, setNote]     = useState('');
  const [busy, setBusy]     = useState(false);

  async function handleConfirm() {
    setBusy(true);
    await onConfirm(request.id, note);
    setBusy(false);
  }

  const isApprove = action === 'approve';
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40">
      <div className="bg-white rounded-xl shadow-2xl w-full max-w-md p-6">
        <h2 className={`text-lg font-bold mb-1 ${isApprove ? 'text-green-700' : 'text-red-700'}`}>
          {isApprove ? 'Approve Request' : 'Deny Request'}
        </h2>
        <p className="text-sm text-gray-600 mb-1">
          User: <strong>{request.user_name || request.user_email}</strong>
        </p>
        <p className="text-sm text-gray-600 mb-4">
          Module: <strong>{request.module_name}</strong>
        </p>
        <label className="block text-sm font-medium text-gray-700 mb-1">
          Admin note <span className="text-gray-400">(optional)</span>
        </label>
        <textarea
          className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm resize-none focus:ring-2 focus:ring-blue-500 focus:outline-none"
          rows={3}
          placeholder={isApprove ? 'Any message for the user…' : 'Reason for denial…'}
          value={note}
          onChange={(e) => setNote(e.target.value)}
        />
        <div className="flex gap-3 mt-5 justify-end">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm rounded-lg border border-gray-300 text-gray-600 hover:bg-gray-50"
          >
            Cancel
          </button>
          <button
            onClick={handleConfirm}
            disabled={busy}
            className={`px-4 py-2 text-sm rounded-lg text-white disabled:opacity-60 ${
              isApprove
                ? 'bg-green-600 hover:bg-green-700'
                : 'bg-red-600 hover:bg-red-700'
            }`}
          >
            {busy ? 'Processing…' : isApprove ? 'Approve' : 'Deny'}
          </button>
        </div>
      </div>
    </div>
  );
}

export default function AccessRequests() {
  const [tab,        setTab]        = useState('pending');
  const [requests,   setRequests]   = useState([]);
  const [loading,    setLoading]    = useState(true);
  const [error,      setError]      = useState('');
  const [successMsg, setSuccessMsg] = useState('');
  const [modal,      setModal]      = useState(null); // { request, action }

  const load = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const params = tab ? { status: tab } : {};
      const res = await rbacService.getAccessRequests(params);
      setRequests(res?.data?.results ?? res?.data ?? []);
    } catch {
      setError('Failed to load access requests.');
    } finally {
      setLoading(false);
    }
  }, [tab]);

  useEffect(() => { load(); }, [load]);

  // ── Count pending for badge ──────────────────────────────────────────────
  const pendingCount = requests.filter((r) => r.status === 'pending').length;

  // ── Approve / Deny handlers ──────────────────────────────────────────────
  async function handleAction(id, note) {
    setError('');
    setSuccessMsg('');
    try {
      if (modal.action === 'approve') {
        await rbacService.approveAccessRequest(id, note);
        setSuccessMsg('Request approved. The user now has access to the module.');
      } else {
        await rbacService.denyAccessRequest(id, note);
        setSuccessMsg('Request denied.');
      }
      setModal(null);
      load();
    } catch (err) {
      const detail =
        err?.response?.data?.detail ||
        (typeof err?.response?.data === 'string' ? err.response.data : null) ||
        'Action failed.';
      setError(detail);
      setModal(null);
    }
  }

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-5xl mx-auto">

        {/* Header */}
        <div className="mb-6 flex items-center justify-between">
          <div>
            <h1 className="text-2xl font-bold text-gray-800">Access Requests</h1>
            <p className="text-sm text-gray-500 mt-1">
              Review and manage module access requests from users.
            </p>
          </div>
          {tab !== 'pending' && pendingCount > 0 && (
            <span className="text-xs bg-yellow-100 text-yellow-800 font-semibold px-3 py-1 rounded-full">
              {pendingCount} pending
            </span>
          )}
        </div>

        {/* Flash messages */}
        {successMsg && (
          <div className="mb-4 p-3 bg-green-50 border border-green-200 rounded-lg text-green-700 text-sm">
            {successMsg}
          </div>
        )}
        {error && (
          <div className="mb-4 p-3 bg-red-50 border border-red-200 rounded-lg text-red-700 text-sm">
            {error}
          </div>
        )}

        {/* Status tabs */}
        <div className="flex border-b border-gray-200 mb-6">
          {TABS.map(({ key, label }) => (
            <button
              key={key}
              onClick={() => setTab(key)}
              className={`px-5 py-2.5 text-sm font-medium border-b-2 transition-colors ${
                tab === key
                  ? 'border-blue-600 text-blue-600'
                  : 'border-transparent text-gray-500 hover:text-gray-700'
              }`}
            >
              {label}
              {key === 'pending' && pendingCount > 0 && tab !== 'pending' && (
                <span className="ml-1.5 bg-yellow-400 text-white text-xs rounded-full px-1.5 py-0.5">
                  {pendingCount}
                </span>
              )}
            </button>
          ))}
        </div>

        {/* Content */}
        {loading ? (
          <div className="flex items-center justify-center h-40 text-gray-400 text-sm">
            Loading…
          </div>
        ) : requests.length === 0 ? (
          <div className="text-center text-gray-500 text-sm mt-12">
            No {tab || ''} access requests found.
          </div>
        ) : (
          <div className="space-y-3">
            {requests.map((req) => (
              <div
                key={req.id}
                className="bg-white border border-gray-200 rounded-xl p-4 shadow-sm"
              >
                <div className="flex flex-col sm:flex-row sm:items-start sm:justify-between gap-3">
                  {/* Left: user + module info */}
                  <div className="flex-1">
                    <div className="flex items-center gap-2 mb-1">
                      <p className="font-semibold text-gray-800 text-sm">
                        {req.user_name || req.user_email}
                      </p>
                      <Badge status={req.status} />
                    </div>
                    <p className="text-xs text-gray-500">{req.user_email}</p>
                    <p className="text-sm text-gray-700 mt-1">
                      Module:{' '}
                      <span className="font-medium">{req.module_name}</span>{' '}
                      <span className="text-xs text-gray-400">({req.module_code})</span>
                    </p>
                    {req.reason && (
                      <p className="text-xs text-gray-500 mt-1 italic">
                        Reason: "{req.reason}"
                      </p>
                    )}
                    {req.admin_note && (
                      <p className="text-xs text-blue-600 mt-1">
                        Admin note: {req.admin_note}
                      </p>
                    )}
                    <p className="text-xs text-gray-400 mt-2">
                      Submitted {new Date(req.created_at).toLocaleString()}
                      {req.reviewed_at && (
                        <> · Reviewed {new Date(req.reviewed_at).toLocaleString()}</>
                      )}
                      {req.reviewed_by_email && (
                        <> by {req.reviewed_by_email}</>
                      )}
                    </p>
                  </div>

                  {/* Right: action buttons (pending only) */}
                  {req.status === 'pending' && (
                    <div className="flex gap-2 shrink-0">
                      <button
                        onClick={() => setModal({ request: req, action: 'approve' })}
                        className="px-3 py-1.5 text-xs font-medium rounded-lg bg-green-600 text-white hover:bg-green-700"
                      >
                        Approve
                      </button>
                      <button
                        onClick={() => setModal({ request: req, action: 'deny' })}
                        className="px-3 py-1.5 text-xs font-medium rounded-lg bg-red-600 text-white hover:bg-red-700"
                      >
                        Deny
                      </button>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        )}
      </div>

      {/* Action modal */}
      {modal && (
        <ActionModal
          request={modal.request}
          action={modal.action}
          onClose={() => setModal(null)}
          onConfirm={handleAction}
        />
      )}
    </div>
  );
}

/**
 * Activity Reports — Admin dashboard for user engagement analytics
 * ==============================================================
 *
 * SuperAdmin (tanzeem.agra@rejlers.ae) can view:
 * - Summary: aggregate platform metrics
 * - By User: per-user activity ranking
 * - By Feature: feature adoption heatmap
 * - Daily: activity trend by day
 * - Export: CSV download in all formats
 *
 * All time windows, metrics, and UI configs are soft-coded.
 */
import React, { useEffect, useMemo, useState, useCallback } from 'react';
import { useSelector } from 'react-redux';
import { useNavigate } from 'react-router-dom';
import {
  ChartBarIcon,
  ArrowDownTrayIcon,
  ArrowPathIcon,
  CalendarDaysIcon,
  UserGroupIcon,
  SparklesIcon,
  ClockIcon,
} from '@heroicons/react/24/outline';
import analyticsService from '../../services/analyticsService';
import { isUserAdmin } from '../../utils/rbac.utils';

// ---------------------------------------------------------------------------
// Soft-coded UI config
// ---------------------------------------------------------------------------
const REPORT_TYPES = [
  { id: 'summary', label: 'Summary', icon: ChartBarIcon, description: 'Aggregate platform metrics' },
  { id: 'by-user', label: 'By User', icon: UserGroupIcon, description: 'Per-user activity ranking' },
  { id: 'by-feature', label: 'By Feature', icon: SparklesIcon, description: 'Feature adoption' },
  { id: 'daily', label: 'Daily', icon: CalendarDaysIcon, description: 'Daily trend' },
];

const TIME_WINDOWS = [
  { id: 'today', label: 'Today' },
  { id: 'week', label: 'This Week' },
  { id: 'month', label: 'This Month' },
  { id: 'quarter', label: 'This Quarter' },
  { id: 'ytd', label: 'Year to Date' },
];

const REFRESH_INTERVAL_MS = 300_000;  // 5 min
const REPORT_LIMIT = 100;

// Metric color coding (USD / actions / pct)
const metricColor = (key, value) => {
  if (key.includes('cost') && value >= 100) return 'text-rose-600 font-semibold';
  if (key.includes('cost') && value > 0) return 'text-amber-600';
  if (key.includes('rate') && value < 80) return 'text-orange-600';
  if (key.includes('rate')) return 'text-emerald-600';
  return 'text-slate-700';
};

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------
const ActivityReports = () => {
  const navigate = useNavigate();
  const authUser = useSelector((s) => s.auth?.user);
  const rbacRoles = useSelector((s) => s.rbac?.userRoles || []);

  const [reportType, setReportType] = useState('summary');
  const [window, setWindow] = useState('month');
  const [report, setReport] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [limit, setLimit] = useState(50);

  const isAdmin = useMemo(() => {
    if (isUserAdmin && isUserAdmin(authUser)) return true;
    const adminRoles = ['super_admin', 'admin'];
    return Array.isArray(rbacRoles) && rbacRoles.some((r) => adminRoles.includes(r?.role_code || r?.code || r));
  }, [authUser, rbacRoles]);

  const load = useCallback(async (silent = false) => {
    if (!silent) setLoading(true);
    setError(null);
    try {
      let data;
      switch (reportType) {
        case 'by-user':
          data = await analyticsService.getActivityByUser(window, limit);
          break;
        case 'by-feature':
          data = await analyticsService.getActivityByFeature(window);
          break;
        case 'daily':
          data = await analyticsService.getActivityDaily(window);
          break;
        case 'summary':
        default:
          data = await analyticsService.getActivitySummary(window);
      }
      setReport(data);
      setLastUpdated(new Date());
    } catch (err) {
      setError(err?.message || 'Failed to load report');
    } finally {
      setLoading(false);
    }
  }, [reportType, window, limit]);

  useEffect(() => {
    if (!isAdmin) return;
    load(false);
    const id = setInterval(() => load(true), REFRESH_INTERVAL_MS);
    return () => clearInterval(id);
  }, [isAdmin, load]);

  const handleExport = async () => {
    try {
      const format = reportType === 'summary' ? 'user' : reportType.replace('by-', '');
      const blob = await analyticsService.exportActivityReportCSV(window, format);
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `activity-report-${format}-${window}.csv`;
      document.body.appendChild(a);
      a.click();
      a.remove();
      URL.revokeObjectURL(url);
    } catch (err) {
      setError('Export failed: ' + (err?.message || 'unknown'));
    }
  };

  // Guard
  if (!isAdmin) {
    return (
      <div className="min-h-[60vh] flex items-center justify-center p-6">
        <div className="bg-white rounded-2xl shadow-lg p-8 text-center max-w-md">
          <ChartBarIcon className="w-12 h-12 mx-auto text-slate-400 mb-3" />
          <h2 className="text-xl font-bold text-slate-800 mb-2">Admin Access Required</h2>
          <p className="text-slate-600 mb-4">Activity reports are restricted to administrators.</p>
          <button
            onClick={() => navigate('/dashboard')}
            className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
          >
            Back to Dashboard
          </button>
        </div>
      </div>
    );
  }

  const currentType = REPORT_TYPES.find((t) => t.id === reportType) || REPORT_TYPES[0];
  const CurrentIcon = currentType.icon;

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-white to-blue-50 p-4 md:p-8">
      <div className="max-w-7xl mx-auto space-y-6">

        {/* Header */}
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div>
            <div className="flex items-center gap-3 mb-1">
              <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-blue-400 to-indigo-600 flex items-center justify-center shadow-lg">
                <ChartBarIcon className="w-6 h-6 text-white" />
              </div>
              <h1 className="text-2xl md:text-3xl font-bold bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent">
                Activity Reports
              </h1>
            </div>
            <p className="text-slate-600 text-sm">
              Comprehensive user engagement analytics · Weekly & monthly breakdowns
            </p>
          </div>
          <div className="flex items-center gap-2 flex-wrap">
            {TIME_WINDOWS.map((w) => (
              <button
                key={w.id}
                onClick={() => setWindow(w.id)}
                className={`px-3 py-1.5 rounded-lg text-sm font-medium border transition ${
                  window === w.id
                    ? 'bg-slate-900 text-white border-slate-900'
                    : 'bg-white text-slate-700 border-slate-200 hover:border-slate-400'
                }`}
              >
                {w.label}
              </button>
            ))}
          </div>
        </div>

        {error && (
          <div className="bg-rose-50 border border-rose-200 text-rose-700 px-4 py-3 rounded-xl text-sm">
            {error}
          </div>
        )}

        {/* Report Type Selector */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          {REPORT_TYPES.map((type) => {
            const Icon = type.icon;
            return (
              <button
                key={type.id}
                onClick={() => setReportType(type.id)}
                className={`p-4 rounded-xl border-2 transition flex flex-col items-start gap-2 ${
                  reportType === type.id
                    ? 'border-blue-500 bg-blue-50 shadow-md'
                    : 'border-slate-200 bg-white hover:border-slate-300'
                }`}
              >
                <Icon className={`w-6 h-6 ${reportType === type.id ? 'text-blue-600' : 'text-slate-400'}`} />
                <div className="text-left">
                  <div className="font-semibold text-slate-900 text-sm">{type.label}</div>
                  <div className="text-xs text-slate-500">{type.description}</div>
                </div>
              </button>
            );
          })}
        </div>

        {/* Controls */}
        <div className="flex items-center gap-2 flex-wrap bg-white rounded-lg p-4 shadow-sm border border-slate-200">
          {reportType === 'by-user' && (
            <div className="flex items-center gap-2">
              <label className="text-sm font-medium text-slate-700">Limit:</label>
              <input
                type="number"
                min="1"
                max="500"
                value={limit}
                onChange={(e) => setLimit(Math.max(1, Math.min(500, parseInt(e.target.value) || 50)))}
                className="w-16 px-2 py-1 border border-slate-300 rounded text-sm"
              />
            </div>
          )}
          <div className="flex-1"></div>
          <button
            onClick={() => load(true)}
            disabled={loading}
            className="px-3 py-2 rounded-lg text-sm font-medium bg-white border border-slate-200 hover:border-slate-400 flex items-center gap-1.5 disabled:opacity-50"
          >
            <ArrowPathIcon className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            {loading ? 'Loading...' : 'Refresh'}
          </button>
          <button
            onClick={handleExport}
            className="px-3 py-2 rounded-lg text-sm font-medium bg-blue-600 text-white hover:bg-blue-700 flex items-center gap-1.5"
          >
            <ArrowDownTrayIcon className="w-4 h-4" />
            Export CSV
          </button>
        </div>

        {/* Report Content */}
        {loading && !report && (
          <div className="flex items-center justify-center p-12">
            <div className="text-center">
              <ArrowPathIcon className="w-8 h-8 animate-spin text-blue-600 mx-auto mb-2" />
              <p className="text-slate-600">Loading report...</p>
            </div>
          </div>
        )}

        {report && !loading && (
          <>
            {/* Summary Report */}
            {reportType === 'summary' && (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {report.metrics && (
                  <div className="bg-white rounded-xl border border-slate-200 p-6 shadow-sm">
                    <h3 className="font-semibold text-slate-900 mb-4">Platform Metrics</h3>
                    <div className="space-y-3">
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">Total Actions</span>
                        <span className="font-semibold text-slate-900">{report.metrics.total_actions?.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">AI Requests</span>
                        <span className="font-semibold text-slate-900">{report.metrics.total_ai_requests?.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">AI Cost</span>
                        <span className={`font-semibold ${metricColor('cost', report.metrics.total_ai_cost_usd)}`}>
                          ${report.metrics.total_ai_cost_usd?.toFixed(2)}
                        </span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">Features Used</span>
                        <span className="font-semibold text-slate-900">{report.metrics.distinct_features}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">Session Time</span>
                        <span className="font-semibold text-slate-900">{report.metrics.session_minutes?.toLocaleString()} min</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">Success Rate</span>
                        <span className={`font-semibold ${metricColor('rate', report.metrics.success_rate_pct)}`}>
                          {report.metrics.success_rate_pct?.toFixed(1)}%
                        </span>
                      </div>
                    </div>
                  </div>
                )}
                {report.cohort && (
                  <div className="bg-white rounded-xl border border-slate-200 p-6 shadow-sm">
                    <h3 className="font-semibold text-slate-900 mb-4">Cohort Stats</h3>
                    <div className="space-y-3">
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">Active Users</span>
                        <span className="font-semibold text-slate-900">{report.cohort.active_users?.toLocaleString()}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">Avg Actions/User</span>
                        <span className="font-semibold text-slate-900">{report.cohort.avg_actions_per_user?.toFixed(1)}</span>
                      </div>
                      <div className="flex justify-between items-center">
                        <span className="text-sm text-slate-600">AI Adoption Rate</span>
                        <span className="font-semibold text-emerald-600">{report.cohort.ai_adoption_rate_pct?.toFixed(1)}%</span>
                      </div>
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* User Report Table */}
            {reportType === 'by-user' && report.results && (
              <div className="bg-white rounded-xl border border-slate-200 shadow-sm overflow-hidden">
                <div className="overflow-x-auto">
                  <table className="w-full">
                    <thead className="bg-slate-50 border-b border-slate-200">
                      <tr>
                        <th className="px-4 py-2 text-left text-xs font-semibold text-slate-600">#</th>
                        <th className="px-4 py-2 text-left text-xs font-semibold text-slate-600">User</th>
                        <th className="px-4 py-2 text-right text-xs font-semibold text-slate-600">Actions</th>
                        <th className="px-4 py-2 text-right text-xs font-semibold text-slate-600">AI Requests</th>
                        <th className="px-4 py-2 text-right text-xs font-semibold text-slate-600">AI Cost</th>
                        <th className="px-4 py-2 text-right text-xs font-semibold text-slate-600">Features</th>
                        <th className="px-4 py-2 text-right text-xs font-semibold text-slate-600">Success %</th>
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-200">
                      {report.results.slice(0, limit).map((row) => (
                        <tr key={row.user.id} className="hover:bg-slate-50">
                          <td className="px-4 py-2 text-sm font-semibold text-slate-700">{row.rank}</td>
                          <td className="px-4 py-2 text-sm">
                            <div className="font-medium text-slate-900">{row.user.name}</div>
                            <div className="text-xs text-slate-500">{row.user.email}</div>
                          </td>
                          <td className="px-4 py-2 text-sm text-right text-slate-900 font-medium">
                            {row.metrics.total_actions?.toLocaleString()}
                          </td>
