/**
 * CRS Revision Chain Detail Page
 * Shows complete chain history, all revisions, comments, and AI insights
 */

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import {
  Box, Card, CardContent, Typography, Grid, CircularProgress, Alert,
  Chip, Table, TableBody, TableCell, TableContainer, TableHead, TableRow,
  Paper, Divider, Button, IconButton, Tooltip
} from '@mui/material';
import {
  ArrowBack as BackIcon,
  Download as DownloadIcon,
  CloudDownload as CloudDownloadIcon,
  Description as DocIcon,
  TrendingUp as InsightIcon
} from '@mui/icons-material';

const CONFIG = {
  API_BASE_URL: import.meta.env.VITE_API_URL || '/api/v1',
  TOKEN_KEYS: ['radai_access_token', 'access_token', 'access']
};

const CRSChainDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [chainData, setChainData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  const getAuthHeaders = () => {
    for (const key of CONFIG.TOKEN_KEYS) {
      const token = localStorage.getItem(key);
      if (token) return { 'Authorization': `Bearer ${token}` };
    }
    return {};
  };

  useEffect(() => {
    fetchChainDetail();
  }, [id]);

  const fetchChainDetail = async () => {
    try {
      setLoading(true);
      const response = await fetch(
        `${CONFIG.API_BASE_URL}/crs/revision-chains/${id}/`,
        { headers: getAuthHeaders() }
      );

      if (!response.ok) {
        throw new Error(`Failed to fetch chain: ${response.status}`);
      }

      const data = await response.json();
      setChainData(data);
      setError(null);
    } catch (err) {
      setError(err.message);
      console.error('[CRS Detail] Error:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadExcel = () => {
    // Simple HTML-to-Excel export
    const html = generateExportHTML();
    const blob = new Blob([html], { type: 'application/vnd.ms-excel;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `CRS_Chain_${chainData.chain_id}_${new Date().toISOString().split('T')[0]}.xls`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);
  };

  const generateExportHTML = () => {
    return `
      <html>
      <head>
        <meta charset="UTF-8">
        <style>
          table { border-collapse: collapse; width: 100%; }
          th, td { border: 1px solid black; padding: 8px; text-align: left; }
          th { background-color: #4CAF50; color: white; font-weight: bold; }
        </style>
      </head>
      <body>
        <h2>CRS Revision Chain: ${chainData?.chain_id}</h2>
        <table>
          <tr><th>Document Title</th><td>${chainData?.document_title || 'N/A'}</td></tr>
          <tr><th>Document Number</th><td>${chainData?.document_number || 'N/A'}</td></tr>
          <tr><th>Project Name</th><td>${chainData?.project_name || 'N/A'}</td></tr>
          <tr><th>Contractor</th><td>${chainData?.contractor_name || 'N/A'}</td></tr>
          <tr><th>Total Revisions</th><td>${chainData?.revisions?.length || 0}</td></tr>
        </table>
        <h3>Revisions</h3>
        <table>
          <tr>
            <th>Revision Number</th>
            <th>Status</th>
            <th>File Name</th>
            <th>Uploaded At</th>
          </tr>
          ${(chainData?.revisions || []).map(rev => `
            <tr>
              <td>${rev.revision_number}</td>
              <td>${rev.status}</td>
              <td>${rev.original_file_name || 'N/A'}</td>
              <td>${new Date(rev.created_at).toLocaleString()}</td>
            </tr>
          `).join('')}
        </table>
      </body>
      </html>
    `;
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: '60vh' }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="error" sx={{ mb: 2 }}>
          {error}
        </Alert>
        <Button startIcon={<BackIcon />} onClick={() => navigate('/crs/documents')}>
          Back to CRS Documents
        </Button>
      </Box>
    );
  }

  if (!chainData) {
    return (
      <Box sx={{ p: 3 }}>
        <Alert severity="warning">Chain not found</Alert>
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', alignItems: 'center', mb: 3 }}>
        <IconButton onClick={() => navigate('/crs/documents')} sx={{ mr: 2 }}>
          <BackIcon />
        </IconButton>
        <Box sx={{ flexGrow: 1 }}>
          <Typography variant="h4" gutterBottom>
            {chainData.chain_id}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {chainData.document_title}
          </Typography>
        </Box>
        <Button
          variant="contained"
          color="success"
          startIcon={<DownloadIcon />}
          onClick={handleDownloadExcel}
        >
          Export Excel
        </Button>
      </Box>

      {/* Chain Information */}
      <Card sx={{ mb: 3 }}>
        <CardContent>
          <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
            <DocIcon sx={{ mr: 1 }} />
            Chain Information
          </Typography>
          <Divider sx={{ mb: 2 }} />
          <Grid container spacing={2}>
            <Grid item xs={12} md={6}>
              <Typography variant="body2" color="text.secondary">Chain ID</Typography>
              <Typography variant="body1" gutterBottom><strong>{chainData.chain_id}</strong></Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="body2" color="text.secondary">Document Number</Typography>
              <Typography variant="body1" gutterBottom>{chainData.document_number || 'N/A'}</Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="body2" color="text.secondary">Document Title</Typography>
              <Typography variant="body1" gutterBottom>{chainData.document_title || 'N/A'}</Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="body2" color="text.secondary">Project Name</Typography>
              <Typography variant="body1" gutterBottom>{chainData.project_name || 'N/A'}</Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="body2" color="text.secondary">Contractor</Typography>
              <Typography variant="body1" gutterBottom>{chainData.contractor_name || 'N/A'}</Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="body2" color="text.secondary">Department</Typography>
              <Typography variant="body1" gutterBottom>{chainData.department || 'N/A'}</Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="body2" color="text.secondary">Max Allowed Revisions</Typography>
              <Typography variant="body1" gutterBottom>{chainData.max_allowed_revisions}</Typography>
            </Grid>
            <Grid item xs={12} md={6}>
              <Typography variant="body2" color="text.secondary">Status</Typography>
              <Chip
                label={chainData.is_finalized ? 'Finalized' : 'Active'}
                color={chainData.is_finalized ? 'success' : 'primary'}
                size="small"
              />
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Revisions History */}
      <Card>
        <CardContent>
          <Typography variant="h6" gutterBottom>
            Revision History ({chainData.revisions?.length || 0} revisions)
          </Typography>
          <Divider sx={{ mb: 2 }} />
          
          {chainData.revisions && chainData.revisions.length > 0 ? (
            <TableContainer component={Paper} variant="outlined">
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell><strong>Revision #</strong></TableCell>
                    <TableCell><strong>Status</strong></TableCell>
                    <TableCell><strong>File Name</strong></TableCell>
                    <TableCell><strong>Uploaded At</strong></TableCell>
                    <TableCell><strong>Uploaded By</strong></TableCell>
                    <TableCell align="center"><strong>Download</strong></TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {chainData.revisions.map((revision) => (
                    <TableRow key={revision.id}>
                      <TableCell>
                        <Chip label={`Rev ${revision.revision_number}`} color="primary" size="small" />
                      </TableCell>
                      <TableCell>
                        <Chip
                          label={revision.status}
                          color={revision.status === 'completed' ? 'success' : 'warning'}
                          size="small"
                        />
                      </TableCell>
                      <TableCell>{revision.original_file_name || 'N/A'}</TableCell>
                      <TableCell>{new Date(revision.created_at).toLocaleString()}</TableCell>
                      <TableCell>{revision.uploaded_by_username || 'N/A'}</TableCell>
                      <TableCell align="center">
                        {revision.excel_download_url ? (
                          <Tooltip title="Download from S3 (instant)">
                            <IconButton
                              size="small"
                              color="success"
                              onClick={() => window.open(revision.excel_download_url, '_blank')}
                            >
                              <CloudDownloadIcon fontSize="small" />
                            </IconButton>
                          </Tooltip>
                        ) : (
                          <Tooltip title="Excel not available">
                            <span>
                              <IconButton size="small" disabled>
                                <DownloadIcon fontSize="small" />
                              </IconButton>
                            </span>
                          </Tooltip>
                        )}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>
          ) : (
            <Alert severity="info">No revisions found for this chain</Alert>
          )}
        </CardContent>
      </Card>

      {/* AI Insights (if available) */}
      {chainData.ai_insights && chainData.ai_insights.length > 0 && (
        <Card sx={{ mt: 3 }}>
          <CardContent>
            <Typography variant="h6" gutterBottom sx={{ display: 'flex', alignItems: 'center' }}>
              <InsightIcon sx={{ mr: 1 }} />
              AI Insights
            </Typography>
            <Divider sx={{ mb: 2 }} />
            {chainData.ai_insights.map((insight, idx) => (
              <Alert key={idx} severity="info" sx={{ mb: 1 }}>
                {insight.insight_text}
              </Alert>
            ))}
          </CardContent>
        </Card>
      )}
    </Box>
  );
};

export default CRSChainDetail;

import { radaiAlert, radaiPrompt } from '../services/radaiDialog'
/**
 * CRS Documents Page - Comment Resolution Sheet
 * Professional PDF comment extraction and Google Sheets integration
 */

import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import * as XLSX from 'xlsx';
import crsService from '../services/crsService';
import { API_BASE_URL } from '../config/api.config';
import { STORAGE_KEYS } from '../config/app.config';
import { withDashboardControls } from '../hoc/withPageControls';
import { PageControlButtons } from '../components/PageControlButtons';

const CRSDocuments = ({ pageControls, refetch }) => {
  const [documents, setDocuments] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState(null);
  const [statistics, setStatistics] = useState(null);
  
  // Filters
  const [statusFilter, setStatusFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  
  // Form states - NEW: Upload-based workflow
  const [uploadFile, setUploadFile] = useState(null);
  const [fileMetadata, setFileMetadata] = useState({
    project_name: '',
    document_number: '',
    revision: '',
    contractor: '',
    department: '',
    project_type: '', // NEW: ADNOC Onshore/Offshore
    template_key: '', // NEW: Selected S3 template
  });
  
  // NEW: Template management states
  const [projectTypes, setProjectTypes] = useState([]);
  const [availableTemplates, setAvailableTemplates] = useState([]);
  const [loadingTemplates, setLoadingTemplates] = useState(false);
  
  // Department options - loaded from API config
  const [departmentOptions, setDepartmentOptions] = useState([
    // Default fallback options
    { id: 'process_control_hse', name: 'Process Control and HSE', code: 'PCH' },
    { id: 'ict', name: 'I&CT', code: 'ICT' },
    { id: 'structure_civil', name: 'Structure and Civil', code: 'SC' },
  ]);
  const [processing, setProcessing] = useState(false);
  const [uploadResult, setUploadResult] = useState(null);
  const [pdfFile, setPdfFile] = useState(null); // For old upload modal

  useEffect(() => {
    loadData();
    loadConfig(); // Load configuration including departments
    loadProjectTypes(); // Load project types from backend
  }, []);

  // NEW: Load project types from backend
  const loadProjectTypes = async () => {
    try {
      const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
      const response = await fetch(
        `${API_BASE_URL}/crs/templates/`,
        {
          headers: {
            'Authorization': `Bearer ${token}`
          }
        }
      );
      
      if (response.ok) {
        const data = await response.json();
        if (data.project_types) {
          setProjectTypes(data.project_types);
        }
      }
    } catch (error) {
      console.error('Error loading project types:', error);
    }
  };

  // NEW: Load templates when project type changes
  const handleProjectTypeChange = async (projectType) => {
    setFileMetadata({ ...fileMetadata, project_type: projectType, template_key: '' });
    setAvailableTemplates([]);
    
    if (!projectType) return;
    
    try {
      setLoadingTemplates(true);
      const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
      const response = await fetch(
        `${API_BASE_URL}/crs/templates/?project_type=${projectType}`,
        {
          headers: {
            'Authorization': `Bearer ${token}`
          }
        }
      );
      
      if (response.ok) {
        const data = await response.json();
        if (data.templates) {
          setAvailableTemplates(data.templates);
        }
      }
    } catch (error) {
      console.error('Error loading templates:', error);
    } finally {
      setLoadingTemplates(false);
    }
  };

  // Load soft-coded configuration from backend
  const loadConfig = async () => {
    try {
      const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
      const response = await fetch(
        `${API_BASE_URL}/crs/documents/config/`,
        {
          headers: {
            'Authorization': `Bearer ${token}`
          }
        }
      );
      
      if (response.ok) {
        const data = await response.json();
        if (data.config?.departments) {
          setDepartmentOptions(data.config.departments);
        }
      }
    } catch (error) {
      console.log('Using default department options');
    }
  };

  const loadData = async () => {
    try {
      setLoading(true);
      const [docsResponse, statsResponse] = await Promise.all([
        crsService.fetchCRSDocuments(),
        crsService.getCRSStatistics()
      ]);
      
      setDocuments(Array.isArray(docsResponse) ? docsResponse : docsResponse.results || []);
      setStatistics(statsResponse);
    } catch (error) {
      console.error('Error loading CRS data:', error);
      await radaiAlert('Failed to load documents. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // NEW: State for preview mode
  const [previewData, setPreviewData] = useState(null);
  const [showPreviewModal, setShowPreviewModal] = useState(false);
  const [downloadingFormat, setDownloadingFormat] = useState(null);

  const handleUploadAndProcess = async (e) => {
    e.preventDefault();
    if (!uploadFile) {
      await radaiAlert('Please select a file to upload');
      return;
    }
    
    setProcessing(true);
    setUploadResult(null);
    
    try {
      const formData = new FormData();
      formData.append('file', uploadFile);
      formData.append('project_name', fileMetadata.project_name);
      formData.append('document_number', fileMetadata.document_number);
      formData.append('revision', fileMetadata.revision);
      formData.append('contractor', fileMetadata.contractor);
      formData.append('department', fileMetadata.department);
      formData.append('preview', 'true'); // Request preview mode first
      
      const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
      
      // Call unified upload endpoint in preview mode
      const response = await fetch(
        `${API_BASE_URL}/crs/documents/upload-and-process/`,
        {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${token}`
          },
          body: formData
        }
      );
      
      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Upload failed');
      }
      
      // Preview mode returns JSON with comments data
      const data = await response.json();
      
      if (data.preview && data.comments) {
        // Smart filtering: Remove comments with "Not Provided" or empty reviewers (client-side fallback)
        const notProvidedPatterns = ['not provided', 'not_provided', 'unknown', 'n/a', 'na', ''];
        const filteredComments = data.comments.filter(comment => {
          const reviewer = (comment.reviewer_name || '').toLowerCase().trim();
          return !notProvidedPatterns.includes(reviewer) && reviewer.length > 0;
        });
        
        // Recalculate statistics based on filtered comments
        const adjustedStatistics = {
          ...data.statistics,
          total: filteredComments.length,
          filtered_count: data.comments.length - filteredComments.length
        };
        
        // Store preview data and show preview modal
        setPreviewData({
          ...data,
          comments: filteredComments, // Use filtered comments
          statistics: adjustedStatistics, // Use adjusted statistics
          file: uploadFile,
          fileMetadata: { ...fileMetadata }
        });
        setShowCreateModal(false);
        setShowPreviewModal(true);
        setUploadResult({
          success: true,
          message: `Extracted ${filteredComments.length} comments${adjustedStatistics.filtered_count > 0 ? ` (filtered ${adjustedStatistics.filtered_count} without reviewer attribution)` : ''}. Review below and choose download format.`
        });
      } else {
        // Fallback for non-preview response
        setUploadResult({
          success: true,
          message: data.message || 'File processed successfully',
          data: data
        });
      }
      
    } catch (error) {
      console.error('Error:', error);
      setUploadResult({
        success: false,
        message: error.message || 'Failed to process file'
      });
    } finally {
      setProcessing(false);
    }
  };

  // NEW: Generate and download Excel directly from preview data
  const handleDownload = async (format) => {
    if (!previewData || !previewData.comments || previewData.comments.length === 0) {
      await radaiAlert('No comment data available for download');
      return;
    }

    setDownloadingFormat(format);

    try {
      const docNumber = previewData.fileMetadata?.document_number || 'Document';
      const timestamp = new Date().toISOString().split('T')[0];

      if (format === 'xlsx') {
        // Create Excel workbook using xlsx library
        const wb = XLSX.utils.book_new();
        
        // Define headers matching CRS template
        const headers = ['Page', 'Reviewer', 'Comment', 'Type', 'Discipline', 'Drawing Ref', 'Status'];
        
        // Map comment data to Excel rows
        const wsData = [
          headers,
          ...previewData.comments.map(comment => [
            comment.page_number || 'N/A',
            comment.reviewer_name || 'N/A',
            comment.comment_text || '',
            (comment.type || 'General').toUpperCase() === 'HOLD' ? 'HOLD' : 'General',
            comment.discipline || 'N/A',
            comment.drawing_reference || 'N/A',
            comment.status || 'Open'
          ])
        ];
        
        // Create worksheet with data
        const ws = XLSX.utils.aoa_to_sheet(wsData);
        
        // Set column widths for readability
        ws['!cols'] = [
          {wch: 8},  // Page
          {wch: 20}, // Reviewer
          {wch: 50}, // Comment
          {wch: 12}, // Type
          {wch: 15}, // Discipline
          {wch: 20}, // Drawing Ref
          {wch: 10}  // Status
        ];
        
        // Add worksheet to workbook
        XLSX.utils.book_append_sheet(wb, ws, 'CRS Comments');
        
        // Generate Excel file and download
        XLSX.writeFile(wb, `CRS_${docNumber}_${timestamp}.xlsx`);
        
      } else if (format === 'csv') {
        // Create CSV data
        const headers = ['Page', 'Reviewer', 'Comment', 'Type', 'Discipline', 'Drawing Ref', 'Status'];
        const rows = previewData.comments.map(comment => [
          comment.page_number || 'N/A',
          comment.reviewer_name || 'N/A',
          `"${(comment.comment_text || '').replace(/"/g, '""')}"`, // Escape quotes
          (comment.type || 'General').toUpperCase() === 'HOLD' ? 'HOLD' : 'General',
          comment.discipline || 'N/A',
          comment.drawing_reference || 'N/A',
          comment.status || 'Open'
        ]);
        
        const csvContent = [headers, ...rows].map(row => row.join(',')).join('\n');
        const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CRS_${docNumber}_${timestamp}.csv`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
        
      } else if (format === 'json') {
        // Create JSON data
        const jsonData = {
          metadata: previewData.fileMetadata || {},
          statistics: previewData.statistics || {},
          comments: previewData.comments,
          exported_at: new Date().toISOString()
        };
        
        const blob = new Blob([JSON.stringify(jsonData, null, 2)], { type: 'application/json' });
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CRS_${docNumber}_${timestamp}.json`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
        
      } else if (format === 'pdf' || format === 'docx') {
        // Call backend API to generate PDF or DOCX from the preview data
        const formData = new FormData();
        formData.append('file', previewData.file);
        formData.append('project_name', previewData.fileMetadata.project_name);
        formData.append('document_number', previewData.fileMetadata.document_number);
        formData.append('revision', previewData.fileMetadata.revision);
        formData.append('contractor', previewData.fileMetadata.contractor);
        formData.append('department', previewData.fileMetadata.department);
        formData.append('format', format); // Specify PDF or DOCX format
        
        const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
        
        const response = await fetch(
          `${API_BASE_URL}/crs/documents/upload-and-process/`,
          {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${token}`
            },
            body: formData
          }
        );
        
        if (!response.ok) {
          const error = await response.json();
          throw new Error(error.error || `${format.toUpperCase()} generation failed`);
        }
        
        // Backend returns the file as binary
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CRS_${docNumber}_${timestamp}.${format}`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(url);
      }
      
    } catch (error) {
      console.error('Error generating download:', error);
      await radaiAlert('Failed to generate download: ' + error.message);
    } finally {
      setDownloadingFormat(null);
    }
  };  // NEW: Close preview and reset
  const handleClosePreview = () => {
    setShowPreviewModal(false);
    setPreviewData(null);
    setUploadFile(null);
    setFileMetadata({
      project_name: '',
      document_number: '',
      revision: '',
      contractor: '',
      department: '',
    });
    setUploadResult(null);
    loadData();
  };

  const handleFileSelect = async (e) => {
    const file = e.target.files[0];
    if (file) {
      const validTypes = [
        'application/pdf',
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        'application/vnd.ms-excel'
      ];
      
      if (validTypes.includes(file.type)) {
        setUploadFile(file);
        setUploadResult(null);
      } else {
        await radaiAlert('Please select a valid PDF or Excel file');
        e.target.value = '';
      }
    }
  };

  const handleUploadPDF = async (e) => {
    e.preventDefault();
    if (!pdfFile || !selectedDocument) return;
    
    setProcessing(true);
    
    try {
      // Upload PDF
      await crsService.uploadPDFDocument(selectedDocument.id, pdfFile);
      
      // Extract comments automatically
      const extractResult = await crsService.extractPDFComments(selectedDocument.id, {
        autoCreate: true,
        debug: false
      });
      
      await radaiAlert(`✅ PDF uploaded and processed!\n\nExtracted ${extractResult.data.total_comments} comments:\n- 🔴 Red comments: ${extractResult.data.red_comments}\n- 🟡 Yellow boxes: ${extractResult.data.yellow_boxes}\n- 📌 Other: ${extractResult.data.other_annotations}`);
      
      setShowUploadModal(false);
      setPdfFile(null);
      setSelectedDocument(null);
      loadData();
    } catch (error) {
      console.error('Error uploading PDF:', error);
      await radaiAlert('Failed to upload PDF. Please try again.');
    } finally {
      setProcessing(false);
    }
  };

  const handleExportToSheets = async (document) => {
    if (!document.google_sheet_id) {
      const sheetId = (await radaiPrompt('Enter Google Sheet ID:'));
      if (!sheetId) return;
      
      try {
        setProcessing(true);
        await crsService.exportToGoogleSheets(document.id, { sheetId });
        await radaiAlert('✅ Exported to Google Sheets successfully!');
        loadData();
      } catch (error) {
        console.error('Error exporting:', error);
        await radaiAlert('Failed to export. Please ensure Google Sheets API is configured.');
      } finally {
        setProcessing(false);
      }
    } else {
      try {
        setProcessing(true);
        await crsService.exportToGoogleSheets(document.id);
        await radaiAlert('✅ Exported to Google Sheets successfully!');
        loadData();
      } catch (error) {
        console.error('Error exporting:', error);
        await radaiAlert('Failed to export. Please try again.');
      } finally {
        setProcessing(false);
      }
    }
  };

  const filteredDocuments = documents.filter(doc => {
    const matchesStatus = statusFilter === 'all' || doc.status === statusFilter;
    const matchesSearch = !searchQuery || 
      doc.document_name.toLowerCase().includes(searchQuery.toLowerCase()) ||
      (doc.document_number && doc.document_number.toLowerCase().includes(searchQuery.toLowerCase())) ||
      (doc.project_name && doc.project_name.toLowerCase().includes(searchQuery.toLowerCase()));
    
    return matchesStatus && matchesSearch;
  });

  const getStatusColor = (status) => {
    const colors = {
      'pending': 'bg-gray-100 text-gray-800',
      'in_review': 'bg-blue-100 text-blue-800',
      'processing': 'bg-yellow-100 text-yellow-800',
      'completed': 'bg-green-100 text-green-800',
      'archived': 'bg-purple-100 text-purple-800',
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  const getStatusLabel = (status) => {
    const labels = {
      'pending': 'Pending',
      'in_review': 'In Review',
      'processing': 'Processing',
      'completed': 'Completed',
      'archived': 'Archived',
    };
    return labels[status] || status;
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-6 sm:py-8 px-4 sm:px-6">
      {/* Header */}
      <div className="mb-6 sm:mb-8 flex flex-col sm:flex-row justify-between items-start gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold text-gray-900 mb-2">
            📋 CRS Documents - Comment Resolution Sheet
          </h1>
          <p className="text-sm sm:text-base text-gray-600">
            Professional PDF comment extraction and Google Sheets integration
          </p>
        </div>
        <div className="flex items-center gap-3">
          <PageControlButtons controls={pageControls} />
          <Link
            to="/crs/documents/history"
            className="inline-flex items-center px-4 sm:px-5 py-2 sm:py-2.5 text-xs sm:text-sm md:text-base bg-indigo-100 text-indigo-700 rounded-lg hover:bg-indigo-200 transition-colors whitespace-nowrap"
          >
            📚 View History
          </Link>
        </div>
      </div>

      {/* Statistics Cards */}
      {statistics && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 bg-blue-500 rounded-md p-3">
                <svg className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">Total Documents</dt>
                  <dd className="text-3xl font-semibold text-gray-900">{statistics.total_documents}</dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 bg-green-500 rounded-md p-3">
                <svg className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
                </svg>
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">Total Comments</dt>
                  <dd className="text-3xl font-semibold text-gray-900">{statistics.total_comments}</dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 bg-yellow-500 rounded-md p-3">
                <svg className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">Open Comments</dt>
                  <dd className="text-3xl font-semibold text-gray-900">{statistics.comments_by_status?.open || 0}</dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 bg-purple-500 rounded-md p-3">
                <svg className="h-6 w-6 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">Resolved</dt>
                  <dd className="text-3xl font-semibold text-gray-900">{statistics.comments_by_status?.resolved || 0}</dd>
                </dl>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Filters and Actions */}
      <div className="bg-white rounded-lg shadow mb-6 p-4">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div className="flex flex-col md:flex-row gap-4 flex-1">
            {/* Search */}
            <div className="flex-1">
              <input
                type="text"
                placeholder="🔍 Search documents..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
              />
            </div>

            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent"
            >
              <option value="all">All Status</option>
              <option value="pending">Pending</option>
              <option value="in_review">In Review</option>
              <option value="processing">Processing</option>
              <option value="completed">Completed</option>
              <option value="archived">Archived</option>
            </select>
          </div>

          {/* Upload & Process Button */}
          <button
            onClick={() => setShowCreateModal(true)}
            className="px-6 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-xl hover:shadow-lg transition-all font-semibold flex items-center gap-2"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
            </svg>
            📤 Upload & Process CRS
          </button>
        </div>
      </div>

      {/* Documents Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredDocuments.map(doc => (
          <div key={doc.id} className="bg-white rounded-lg shadow hover:shadow-lg transition-shadow">
            <div className="p-6">
              {/* Header */}
              <div className="flex items-start justify-between mb-4">
                <div className="flex-1">
                  <h3 className="text-lg font-semibold text-gray-900 mb-1">
                    {doc.document_name}
                  </h3>
                  {doc.document_number && (
                    <p className="text-sm text-gray-500">Doc #: {doc.document_number}</p>
                  )}
                </div>
                <span className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(doc.status)}`}>
                  {getStatusLabel(doc.status)}
                </span>
              </div>

              {/* Project Info */}
              {doc.project_name && (
                <div className="mb-4">
                  <p className="text-sm text-gray-600">
                    <span className="font-medium">Project:</span> {doc.project_name}
                  </p>
                  {doc.contractor_name && (
                    <p className="text-sm text-gray-600">
                      <span className="font-medium">Contractor:</span> {doc.contractor_name}
                    </p>
                  )}
                </div>
              )}

              {/* Progress Bar */}
              <div className="mb-4">
                <div className="flex items-center justify-between text-sm text-gray-600 mb-1">
                  <span>Progress</span>
                  <span className="font-medium">{doc.completion_percentage}%</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div
                    className="bg-indigo-600 h-2 rounded-full transition-all duration-300"
                    style={{ width: `${doc.completion_percentage}%` }}
                  ></div>
                </div>
              </div>

              {/* Stats */}
              <div className="grid grid-cols-3 gap-2 mb-4 text-center">
                <div className="bg-gray-50 rounded p-2">
                  <p className="text-2xl font-bold text-gray-900">{doc.total_comments}</p>
                  <p className="text-xs text-gray-500">Total</p>
                </div>
                <div className="bg-yellow-50 rounded p-2">
                  <p className="text-2xl font-bold text-yellow-600">{doc.pending_comments}</p>
                  <p className="text-xs text-gray-500">Pending</p>
                </div>
                <div className="bg-green-50 rounded p-2">
                  <p className="text-2xl font-bold text-green-600">{doc.resolved_comments}</p>
                  <p className="text-xs text-gray-500">Resolved</p>
                </div>
              </div>

              {/* Actions */}
              <div className="flex flex-wrap gap-2">
                <Link
                  to={`/crs/documents/${doc.id}`}
                  className="flex-1 text-center px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 transition-colors text-sm font-medium"
                >
                  View Details
                </Link>
                
                {!doc.pdf_file && (
                  <button
                    onClick={() => {
                      setSelectedDocument(doc);
                      setShowUploadModal(true);
                    }}
                    className="px-4 py-2 bg-blue-100 text-blue-700 rounded-lg hover:bg-blue-200 transition-colors text-sm font-medium"
                  >
                    📤 Upload PDF
                  </button>
                )}
                
                {doc.total_comments > 0 && (
                  <button
                    onClick={() => handleExportToSheets(doc)}
                    disabled={processing}
                    className="px-4 py-2 bg-green-100 text-green-700 rounded-lg hover:bg-green-200 transition-colors text-sm font-medium disabled:opacity-50"
                  >
                    📊 Export
                  </button>
                )}
              </div>

              {/* Google Sheet Link */}
              {doc.google_sheet_url && (
                <div className="mt-3 pt-3 border-t border-gray-200">
                  <a
                    href={doc.google_sheet_url}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="text-sm text-indigo-600 hover:text-indigo-800 flex items-center gap-1"
                  >
                    <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
                    </svg>
                    Open in Google Sheets
                  </a>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Empty State */}
      {filteredDocuments.length === 0 && (
        <div className="bg-white rounded-lg shadow p-12 text-center">
          <svg className="mx-auto h-12 w-12 text-gray-400" fill="none" viewBox="0 0 24 24" stroke="currentColor">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
          </svg>
          <h3 className="mt-2 text-sm font-medium text-gray-900">No documents found</h3>
          <p className="mt-1 text-sm text-gray-500">Get started by uploading and processing a CRS file.</p>
          <div className="mt-6">
            <button
              onClick={() => setShowCreateModal(true)}
              className="inline-flex items-center gap-2 px-6 py-3 shadow-lg text-sm font-semibold rounded-xl text-white bg-gradient-to-r from-indigo-600 to-purple-600 hover:shadow-xl transition-all"
            >
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
              </svg>
              📤 Upload & Process CRS
            </button>
          </div>
        </div>
      )}

      {/* Upload & Process Modal - NEW WORKFLOW */}
      {showCreateModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-2xl max-w-3xl w-full max-h-[90vh] overflow-y-auto shadow-2xl">
            {/* Header */}
            <div className="bg-gradient-to-r from-indigo-600 to-purple-600 p-6 rounded-t-2xl">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-bold text-white mb-2">
                    📋 Upload Comment Resolution Sheet
                  </h2>
                  <p className="text-indigo-100 text-sm">
                    Upload PDF or Excel file - Get standardized CRS template instantly
                  </p>
                </div>
                <button
                  onClick={() => {
                    setShowCreateModal(false);
                    setUploadFile(null);
                    setUploadResult(null);
                  }}
                  className="text-white hover:bg-white/20 rounded-lg p-2 transition-colors"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            <form onSubmit={handleUploadAndProcess} className="p-6">
              {/* File Upload Section */}
              <div className="mb-6">
                <label className="block text-sm font-semibold text-gray-700 mb-3">
                  📄 Select File (PDF or Excel) *
                </label>
                <div className="relative border-2 border-dashed border-gray-300 rounded-xl p-8 text-center hover:border-indigo-500 transition-all bg-gray-50">
                  <input
                    type="file"
                    accept=".pdf,.xlsx,.xls"
                    onChange={handleFileSelect}
                    required
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                  />
                  
                  {!uploadFile ? (
                    <div>
                      <svg className="mx-auto h-12 w-12 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                      </svg>
                      <p className="mt-2 text-sm text-gray-600">
                        <span className="font-semibold text-indigo-600">Click to upload</span> or drag and drop
                      </p>
                      <p className="mt-1 text-xs text-gray-500">
                        PDF, Excel (.xlsx, .xls) up to 50MB
                      </p>
                    </div>
                  ) : (
                    <div className="flex items-center justify-center gap-3">
                      <div className="w-12 h-12 bg-green-100 rounded-xl flex items-center justify-center">
                        {uploadFile.type.includes('pdf') ? (
                          <svg className="w-6 h-6 text-red-600" fill="currentColor" viewBox="0 0 20 20">
                            <path d="M4 4a2 2 0 012-2h4.586A2 2 0 0112 2.586L15.414 6A2 2 0 0116 7.414V16a2 2 0 01-2 2H6a2 2 0 01-2-2V4z" />
                          </svg>
                        ) : (
                          <svg className="w-6 h-6 text-green-600" fill="currentColor" viewBox="0 0 20 20">
                            <path d="M9 2a2 2 0 00-2 2v8a2 2 0 002 2h6a2 2 0 002-2V6.414A2 2 0 0016.414 5L14 2.586A2 2 0 0012.586 2H9z" />
                          </svg>
                        )}
                      </div>
                      <div className="text-left">
                        <p className="font-semibold text-gray-900">{uploadFile.name}</p>
                        <p className="text-sm text-gray-500">
                          {(uploadFile.size / 1024 / 1024).toFixed(2)} MB
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          setUploadFile(null);
                        }}
                        className="ml-4 text-red-600 hover:text-red-800"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                      </button>
                    </div>
                  )}
                </div>
                
                <div className="mt-3 p-3 bg-blue-50 rounded-lg border border-blue-200">
                  <div className="flex items-start gap-2">
                    <svg className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                      <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                    </svg>
                    <div className="text-xs text-blue-900">
                      <p className="font-semibold mb-1">What happens next?</p>
                      <ul className="list-disc list-inside space-y-0.5">
                        <li>System extracts all comments from your file</li>
                        <li>Data is validated and cleaned automatically</li>
                        <li>Standardized CRS template (CRS template.xlsx) is populated</li>
                        <li>Ready-to-use Excel file downloads instantly</li>
                      </ul>
                    </div>
                  </div>
                </div>
              </div>

              {/* Metadata Section */}
              <div className="space-y-4 mb-6">
                <h3 className="text-lg font-semibold text-gray-900 flex items-center gap-2">
                  <svg className="w-5 h-5 text-indigo-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                  Document Information
                </h3>

                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Project Name
                    </label>
                    <input
                      type="text"
                      value={fileMetadata.project_name}
                      onChange={(e) => setFileMetadata({...fileMetadata, project_name: e.target.value})}
                      className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900"
                      placeholder="e.g., Plant Expansion Phase 2"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Document Number
                    </label>
                    <input
                      type="text"
                      value={fileMetadata.document_number}
                      onChange={(e) => setFileMetadata({...fileMetadata, document_number: e.target.value})}
                      className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900"
                      placeholder="e.g., DOC-12345"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Revision
                    </label>
                    <input
                      type="text"
                      value={fileMetadata.revision}
                      onChange={(e) => setFileMetadata({...fileMetadata, revision: e.target.value})}
                      className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900"
                      placeholder="e.g., R1"
                    />
                  </div>

                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      Contractor
                    </label>
                    <input
                      type="text"
                      value={fileMetadata.contractor}
                      onChange={(e) => setFileMetadata({...fileMetadata, contractor: e.target.value})}
                      className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900"
                      placeholder="e.g., XYZ Engineering"
                    />
                  </div>
                </div>

                {/* Department Selection */}
                <div className="mt-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Department
                  </label>
                  <select
                    value={fileMetadata.department}
                    onChange={(e) => setFileMetadata({...fileMetadata, department: e.target.value})}
                    className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900 bg-white"
                  >
                    <option value="">Select Department...</option>
                    {departmentOptions.map((dept) => (
                      <option key={dept.id} value={dept.id}>
                        {dept.name}
                      </option>
                    ))}
                  </select>
                </div>

                {/* NEW: Project Type Selection */}
                <div className="mt-4">
                  <label className="block text-sm font-medium text-gray-700 mb-1">
                    Project Type <span className="text-red-500">*</span>
                  </label>
                  <select
                    value={fileMetadata.project_type}
                    onChange={(e) => handleProjectTypeChange(e.target.value)}
                    className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900 bg-white"
                    required
                  >
                    <option value="">Select Project Type...</option>
                    {projectTypes.map((type) => (
                      <option key={type.code} value={type.code}>
                        {type.icon} {type.label}
                      </option>
                    ))}
                  </select>
                </div>

                {/* NEW: Template Selection */}
                {fileMetadata.project_type && (
                  <div className="mt-4">
                    <label className="block text-sm font-medium text-gray-700 mb-1">
                      CRS Template
                    </label>
                    {loadingTemplates ? (
                      <div className="w-full px-4 py-2.5 border border-gray-300 rounded-lg bg-gray-50 text-gray-500 flex items-center gap-2">
                        <div className="animate-spin rounded-full h-4 w-4 border-2 border-indigo-500 border-t-transparent"></div>
                        Loading templates...
                      </div>
                    ) : availableTemplates.length > 0 ? (
                      <select
                        value={fileMetadata.template_key}
                        onChange={(e) => setFileMetadata({...fileMetadata, template_key: e.target.value})}
                        className="w-full px-4 py-2.5 border border-gray-300 rounded-lg focus:ring-2 focus:ring-indigo-500 focus:border-transparent text-gray-900 bg-white"
                      >
                        <option value="">Use Default Template</option>
                        {availableTemplates.map((template) => (
                          <option key={template.key} value={template.key}>
                            📄 {template.filename} ({(template.size / 1024).toFixed(1)} KB)
                          </option>
                        ))}
                      </select>
                    ) : (
                      <div className="w-full px-4 py-2.5 border border-yellow-300 rounded-lg bg-yellow-50 text-yellow-700 text-sm">
                        ⚠️ No custom templates found. Default template will be used.
                      </div>
                    )}
                  </div>
                )}
              </div>

              {/* Result Message */}
              {uploadResult && (
                <div className={`mb-6 p-4 rounded-xl border-2 ${
                  uploadResult.success 
                    ? 'bg-green-50 border-green-200' 
                    : 'bg-red-50 border-red-200'
                }`}>
                  <div className="flex items-start gap-3">
                    <div className={`w-6 h-6 rounded-full flex items-center justify-center flex-shrink-0 ${
                      uploadResult.success ? 'bg-green-500' : 'bg-red-500'
                    }`}>
                      {uploadResult.success ? (
                        <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                        </svg>
                      ) : (
                        <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                      )}
                    </div>
                    <div>
                      <p className={`font-semibold ${uploadResult.success ? 'text-green-900' : 'text-red-900'}`}>
                        {uploadResult.success ? '✅ Success!' : '❌ Error'}
                      </p>
                      <p className={`text-sm mt-1 ${uploadResult.success ? 'text-green-700' : 'text-red-700'}`}>
                        {uploadResult.message}
                      </p>
                    </div>
                  </div>
                </div>
              )}

              {/* Action Buttons */}
              <div className="flex gap-3">
                <button
                  type="button"
                  onClick={() => {
                    setShowCreateModal(false);
                    setUploadFile(null);
                    setUploadResult(null);
                  }}
                  className="flex-1 px-6 py-3 border-2 border-gray-300 text-gray-700 rounded-xl hover:bg-gray-50 transition-colors font-semibold"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={!uploadFile || processing}
                  className={`flex-1 px-6 py-3 rounded-xl font-semibold transition-all flex items-center justify-center gap-2 ${
                    !uploadFile || processing
                      ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                      : 'bg-gradient-to-r from-indigo-600 to-purple-600 text-white hover:shadow-lg hover:scale-105'
                  }`}
                >
                  {processing ? (
                    <>
                      <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                      Processing...
                    </>
                  ) : (
                    <>
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12" />
                      </svg>
                      Upload & Process
                    </>
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Preview Modal - Shows extracted comments before download */}
      {showPreviewModal && previewData && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-2xl max-w-6xl w-full max-h-[90vh] overflow-hidden shadow-2xl flex flex-col">
            {/* Header */}
            <div className="bg-gradient-to-r from-green-600 to-emerald-600 p-6">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-bold text-white mb-2">
                    ✅ Comment Extraction Complete
                  </h2>
                  <p className="text-green-100 text-sm">
                    {previewData.statistics?.total || previewData.comments?.length || 0} comments extracted • Review and download in your preferred format
                  </p>
                </div>
                <button
                  onClick={handleClosePreview}
                  className="text-white hover:bg-white/20 rounded-lg p-2 transition-colors"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            {/* Statistics Summary */}
            <div className="p-4 bg-gray-50 border-b border-gray-200">
              <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                <div className="bg-white rounded-lg p-3 text-center shadow-sm">
                  <p className="text-3xl font-bold text-indigo-600">{previewData.statistics?.total || previewData.comments?.length || 0}</p>
                  <p className="text-sm text-gray-500">Total Comments</p>
                </div>
                {previewData.statistics?.by_type && Object.keys(previewData.statistics.by_type).length > 0 && (
                  <div className="bg-white rounded-lg p-3 shadow-sm">
                    <p className="text-sm font-semibold text-gray-700 mb-1">By Type</p>
                    <div className="text-xs text-gray-600">
                      {Object.entries(previewData.statistics.by_type).slice(0, 3).map(([type, count]) => (
                        <span key={type} className="inline-block bg-blue-100 text-blue-800 px-2 py-0.5 rounded mr-1 mb-1">
                          {type}: {count}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
                {previewData.statistics?.by_discipline && Object.keys(previewData.statistics.by_discipline).length > 0 && (
                  <div className="bg-white rounded-lg p-3 shadow-sm">
                    <p className="text-sm font-semibold text-gray-700 mb-1">By Discipline</p>
                    <div className="text-xs text-gray-600">
                      {Object.entries(previewData.statistics.by_discipline).slice(0, 3).map(([disc, count]) => (
                        <span key={disc} className="inline-block bg-purple-100 text-purple-800 px-2 py-0.5 rounded mr-1 mb-1">
                          {disc}: {count}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
                {previewData.statistics?.by_reviewer && Object.keys(previewData.statistics.by_reviewer).length > 0 && (
                  <div className="bg-white rounded-lg p-3 shadow-sm">
                    <p className="text-sm font-semibold text-gray-700 mb-1">By Reviewer</p>
                    <div className="text-xs text-gray-600">
                      {Object.entries(previewData.statistics.by_reviewer).slice(0, 3).map(([reviewer, count]) => (
                        <span key={reviewer} className="inline-block bg-green-100 text-green-800 px-2 py-0.5 rounded mr-1 mb-1">
                          {reviewer}: {count}
                        </span>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* Comments Table */}
            <div className="flex-1 overflow-auto p-4">
              <div className="bg-white rounded-lg border border-gray-200 overflow-hidden">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-50 sticky top-0">
                    <tr>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-16">#</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-24">Page</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-28">Type</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Comment</th>
                      <th className="px-4 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider w-32">Reviewer</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    {previewData.comments && previewData.comments.map((comment, index) => (
                      <tr key={index} className="hover:bg-gray-50">
                        <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-900">{index + 1}</td>
                        <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">{comment.page_number || comment.page || '-'}</td>
                        <td className="px-4 py-3 whitespace-nowrap">
                          <span className={`inline-flex px-2 py-1 text-xs font-medium rounded-full ${
                            (comment.comment_type || comment.type) === 'HOLD' ? 'bg-red-100 text-red-800' :
                            (comment.comment_type || comment.type) === 'ADEQUACY' ? 'bg-yellow-100 text-yellow-800' :
                            (comment.comment_type || comment.type) === 'RECOMMENDATION' ? 'bg-blue-100 text-blue-800' :
                            (comment.comment_type || comment.type) === 'CLARIFICATION' ? 'bg-purple-100 text-purple-800' :
                            'bg-gray-100 text-gray-800'
                          }`}>
                            {comment.comment_type || comment.type || 'GENERAL'}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-sm text-gray-900 max-w-md">
                          <div className="truncate" title={comment.comment_text || comment.content}>
                            {comment.comment_text || comment.content || comment.text || '-'}
                          </div>
                        </td>
                        <td className="px-4 py-3 whitespace-nowrap text-sm text-gray-600">{comment.reviewer_name || comment.reviewer || comment.author || '-'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                
                {(!previewData.comments || previewData.comments.length === 0) && (
                  <div className="p-8 text-center text-gray-500">
                    <p>No comments found in the document.</p>
                  </div>
                )}
              </div>
            </div>

            {/* Download Actions */}
            <div className="p-4 bg-gray-50 border-t border-gray-200">
              <div className="flex flex-col md:flex-row items-center justify-between gap-4">
                <p className="text-sm text-gray-600">
                  Choose your preferred download format:
                </p>
                <div className="flex flex-wrap gap-3">
                  {/* Excel Download */}
                  <button
                    onClick={() => handleDownload('xlsx')}
                    disabled={downloadingFormat !== null}
                    className={`px-6 py-3 rounded-xl font-semibold flex items-center gap-2 transition-all ${
                      downloadingFormat === 'xlsx' 
                        ? 'bg-green-400 text-white cursor-wait'
                        : 'bg-green-600 text-white hover:bg-green-700 hover:shadow-lg'
                    }`}
                  >
                    {downloadingFormat === 'xlsx' ? (
                      <>
                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                        Downloading...
                      </>
                    ) : (
                      <>
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                          <path d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" />
                        </svg>
                        📊 Excel (.xlsx)
                      </>
                    )}
                  </button>

                  {/* CSV Download */}
                  <button
                    onClick={() => handleDownload('csv')}
                    disabled={downloadingFormat !== null}
                    className={`px-6 py-3 rounded-xl font-semibold flex items-center gap-2 transition-all ${
                      downloadingFormat === 'csv' 
                        ? 'bg-blue-400 text-white cursor-wait'
                        : 'bg-blue-600 text-white hover:bg-blue-700 hover:shadow-lg'
                    }`}
                  >
                    {downloadingFormat === 'csv' ? (
                      <>
                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                        Downloading...
                      </>
                    ) : (
                      <>
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                          <path d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" />
                        </svg>
                        📄 CSV
                      </>
                    )}
                  </button>

                  {/* JSON Download */}
                  <button
                    onClick={() => handleDownload('json')}
                    disabled={downloadingFormat !== null}
                    className={`px-6 py-3 rounded-xl font-semibold flex items-center gap-2 transition-all ${
                      downloadingFormat === 'json' 
                        ? 'bg-purple-400 text-white cursor-wait'
                        : 'bg-purple-600 text-white hover:bg-purple-700 hover:shadow-lg'
                    }`}
                  >
                    {downloadingFormat === 'json' ? (
                      <>
                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                        Downloading...
                      </>
                    ) : (
                      <>
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                          <path d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" />
                        </svg>
                        🔧 JSON
                      </>
                    )}
                  </button>

                  {/* PDF Download */}
                  <button
                    onClick={() => handleDownload('pdf')}
                    disabled={downloadingFormat !== null}
                    className={`px-6 py-3 rounded-xl font-semibold flex items-center gap-2 transition-all ${
                      downloadingFormat === 'pdf' 
                        ? 'bg-red-400 text-white cursor-wait'
                        : 'bg-red-600 text-white hover:bg-red-700 hover:shadow-lg'
                    }`}
                  >
                    {downloadingFormat === 'pdf' ? (
                      <>
                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                        Downloading...
                      </>
                    ) : (
                      <>
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                          <path d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" />
                        </svg>
                        📕 PDF
                      </>
                    )}
                  </button>

                  {/* DOCX Download */}
                  <button
                    onClick={() => handleDownload('docx')}
                    disabled={downloadingFormat !== null}
                    className={`px-6 py-3 rounded-xl font-semibold flex items-center gap-2 transition-all ${
                      downloadingFormat === 'docx' 
                        ? 'bg-indigo-400 text-white cursor-wait'
                        : 'bg-indigo-600 text-white hover:bg-indigo-700 hover:shadow-lg'
                    }`}
                  >
                    {downloadingFormat === 'docx' ? (
                      <>
                        <div className="animate-spin rounded-full h-5 w-5 border-2 border-white border-t-transparent"></div>
                        Downloading...
                      </>
                    ) : (
                      <>
                        <svg className="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                          <path d="M3 17a1 1 0 011-1h12a1 1 0 110 2H4a1 1 0 01-1-1zm3.293-7.707a1 1 0 011.414 0L9 10.586V3a1 1 0 112 0v7.586l1.293-1.293a1 1 0 111.414 1.414l-3 3a1 1 0 01-1.414 0l-3-3a1 1 0 010-1.414z" />
                        </svg>
                        📝 Word
                      </>
                    )}
                  </button>

                  {/* Cancel/Close */}
                  <button
                    onClick={handleClosePreview}
                    className="px-6 py-3 border-2 border-gray-300 text-gray-700 rounded-xl hover:bg-gray-100 transition-colors font-semibold"
                  >
                    Close
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Old Upload PDF Modal - Keep for backward compatibility */}
      {showUploadModal && selectedDocument && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-lg max-w-md w-full p-6">
            <h3 className="text-xl font-bold text-gray-900 mb-4">Upload PDF for {selectedDocument.document_name}</h3>
            <form onSubmit={handleUploadPDF}>
              <div className="mb-4">
                <label className="block text-sm font-medium text-gray-700 mb-2">
                  Select PDF File
                </label>
                <input
                  type="file"
                  accept=".pdf"
                  onChange={(e) => setPdfFile(e.target.files[0])}
                  required
                  className="w-full"
                />
              </div>
              <div className="flex gap-3">
                <button
                  type="button"
                  onClick={() => {
                    setShowUploadModal(false);
                    setSelectedDocument(null);
                    setPdfFile(null);
                  }}
                  className="flex-1 px-4 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={processing}
                  className="flex-1 px-4 py-2 bg-indigo-600 text-white rounded-lg hover:bg-indigo-700 disabled:opacity-50"
                >
                  {processing ? 'Uploading...' : 'Upload'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

// Wrapper component to provide refetch functionality
const CRSDocumentsWithRefresh = (props) => {
  const [refreshTrigger, setRefreshTrigger] = useState(0);
  
  const refetch = useCallback(() => {
    setRefreshTrigger(prev => prev + 1);
  }, []);
  
  return <CRSDocuments {...props} refetch={refetch} key={refreshTrigger} />;
};

export default withDashboardControls(CRSDocumentsWithRefresh, {
  autoRefreshInterval: 30000, // 30 seconds
  storageKey: 'crsDocumentsPageControls',
});

/**
 * CRS Documents History Page
 * Displays user's upload and export history from S3 storage
 * 
 * Features:
 * - View all uploaded files
 * - View all exported files
 * - Activity timeline
 * - Download files from history
 * - User storage profile stats
 */

import React, { useState, useEffect, useCallback } from 'react';
import { useSelector } from 'react-redux';
import axios from 'axios';
import { STORAGE_KEYS } from '../config/app.config';
import { API_BASE_URL } from '../config/api.config';

const CRSDocumentsHistory = () => {
  const { user } = useSelector((state) => state.auth);
  
  // State
  const [activeTab, setActiveTab] = useState('overview');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  // Data states
  const [profile, setProfile] = useState(null);
  const [uploads, setUploads] = useState([]);
  const [exports, setExports] = useState([]);
  const [activities, setActivities] = useState([]);
  
  // Fetch history overview
  const fetchHistoryOverview = useCallback(async () => {
    const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
    if (!token) return;
    
    setLoading(true);
    setError(null);
    
    try {
      const response = await axios.get(
        `${API_BASE_URL}/crs/documents/history/`,
        {
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        }
      );
      
      if (response.data.success) {
        setProfile(response.data.data.profile);
        setUploads(response.data.data.recent_uploads || []);
        setExports(response.data.data.recent_exports || []);
        setActivities(response.data.data.recent_activity || []);
      }
    } catch (err) {
      console.error('Error fetching history:', err);
      setError(err.response?.data?.error || 'Failed to load history');
    } finally {
      setLoading(false);
    }
  }, []);
  
  // Fetch all uploads
  const fetchAllUploads = useCallback(async () => {
    const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
    if (!token) return;
    
    try {
      const response = await axios.get(
        `${API_BASE_URL}/crs/documents/history/uploads/?limit=100`,
        {
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        }
      );
      
      if (response.data.success) {
        setUploads(response.data.uploads || []);
      }
    } catch (err) {
      console.error('Error fetching uploads:', err);
    }
  }, []);
  
  // Fetch all exports
  const fetchAllExports = useCallback(async () => {
    const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
    if (!token) return;
    
    try {
      const response = await axios.get(
        `${API_BASE_URL}/crs/documents/history/exports/?limit=100`,
        {
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        }
      );
      
      if (response.data.success) {
        setExports(response.data.exports || []);
      }
    } catch (err) {
      console.error('Error fetching exports:', err);
    }
  }, []);
  
  // Fetch all activities
  const fetchAllActivities = useCallback(async () => {
    const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
    if (!token) return;
    
    try {
      const response = await axios.get(
        `${API_BASE_URL}/crs/documents/history/activity/?days=30`,
        {
          headers: {
            'Authorization': `Bearer ${token}`,
          },
        }
      );
      
      if (response.data.success) {
        setActivities(response.data.activities || []);
      }
    } catch (err) {
      console.error('Error fetching activities:', err);
    }
  }, []);
  
  // Download file from history
  const downloadFromHistory = async (s3Key, filename) => {
    const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
    if (!token) return;
    
    try {
      const response = await axios.get(
        `${API_BASE_URL}/crs/documents/history/download/?key=${encodeURIComponent(s3Key)}`,
        {
          headers: {
            'Authorization': `Bearer ${token}`,
          },
          responseType: 'blob',
        }
      );
      
      // Create download link
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', filename);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Error downloading file:', err);
      setError('Failed to download file');
    }
  };
  
  // Load data on mount and tab change
  useEffect(() => {
    if (activeTab === 'overview') {
      fetchHistoryOverview();
    } else if (activeTab === 'uploads') {
      fetchAllUploads();
    } else if (activeTab === 'exports') {
      fetchAllExports();
    } else if (activeTab === 'activity') {
      fetchAllActivities();
    }
  }, [activeTab, fetchHistoryOverview, fetchAllUploads, fetchAllExports, fetchAllActivities]);
  
  // Format file size
  const formatFileSize = (bytes) => {
    if (!bytes) return '0 B';
    const k = 1024;
    const sizes = ['B', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  };
  
  // Format date
  const formatDate = (dateString) => {
    if (!dateString) return '-';
    return new Date(dateString).toLocaleString();
  };
  
  // Get format icon
  const getFormatIcon = (format) => {
    const icons = {
      'xlsx': '📊',
      'csv': '📄',
      'json': '🔧',
      'pdf': '📕',
      'docx': '📝',
    };
    return icons[format] || '📁';
  };
  
  // Get action icon
  const getActionIcon = (action) => {
    const icons = {
      'upload': '⬆️',
      'export': '⬇️',
      'download': '💾',
      'view': '👁️',
    };
    return icons[action] || '📋';
  };

  // Tab button component
  const TabButton = ({ id, label, icon }) => (
    <button
      onClick={() => setActiveTab(id)}
      className={`px-4 py-2 font-medium text-sm rounded-t-lg flex items-center gap-2 ${
        activeTab === id
          ? 'bg-white text-indigo-600 border-t border-l border-r border-gray-200'
          : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
      }`}
    >
      <span>{icon}</span>
      {label}
    </button>
  );

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-8">
          <h1 className="text-3xl font-bold text-gray-900">📚 Document History</h1>
          <p className="mt-2 text-gray-600">
            View your uploaded documents and exported files
          </p>
        </div>
        
        {/* Error message */}
        {error && (
          <div className="mb-4 bg-red-50 border border-red-200 text-red-700 px-4 py-3 rounded-lg">
            {error}
            <button 
              onClick={() => setError(null)}
              className="float-right text-red-500 hover:text-red-700"
            >
              ✕
            </button>
          </div>
        )}
        
        {/* Profile Stats Card */}
        {profile && (
          <div className="bg-white rounded-lg shadow-md p-6 mb-6">
            <div className="flex items-center justify-between">
              <div>
                <h2 className="text-xl font-semibold text-gray-900">
                  👤 {profile.username || user?.username || 'User'}
                </h2>
                <p className="text-gray-500 text-sm">
                  Member since: {formatDate(profile.created_at)}
                </p>
              </div>
              <div className="flex gap-8">
                <div className="text-center">
                  <div className="text-3xl font-bold text-indigo-600">
                    {profile.total_uploads || 0}
                  </div>
                  <div className="text-sm text-gray-500">Uploads</div>
                </div>
                <div className="text-center">
                  <div className="text-3xl font-bold text-green-600">
                    {profile.total_exports || 0}
                  </div>
                  <div className="text-sm text-gray-500">Exports</div>
                </div>
              </div>
            </div>
          </div>
        )}
        
        {/* Tab Navigation */}
        <div className="flex gap-2 mb-0">
          <TabButton id="overview" label="Overview" icon="📊" />
          <TabButton id="uploads" label="Uploads" icon="⬆️" />
          <TabButton id="exports" label="Exports" icon="⬇️" />
          <TabButton id="activity" label="Activity" icon="📋" />
        </div>
        
        {/* Tab Content */}
        <div className="bg-white rounded-b-lg rounded-tr-lg shadow-md p-6 border border-gray-200">
          {loading ? (
            <div className="flex items-center justify-center py-12">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
              <span className="ml-3 text-gray-500">Loading...</span>
            </div>
          ) : (
            <>
              {/* Overview Tab */}
              {activeTab === 'overview' && (
                <div className="space-y-6">
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                    {/* Recent Uploads */}
                    <div>
                      <h3 className="text-lg font-semibold text-gray-900 mb-4">
                        ⬆️ Recent Uploads
                      </h3>
                      {uploads.length > 0 ? (
                        <ul className="space-y-2">
                          {uploads.slice(0, 5).map((file, idx) => (
                            <li 
                              key={idx}
                              className="flex items-center justify-between p-3 bg-gray-50 rounded-lg"
                            >
                              <div className="flex items-center gap-2">
                                <span>📄</span>
                                <div>
                                  <div className="font-medium text-sm truncate max-w-[200px]">
                                    {file.filename}
                                  </div>
                                  <div className="text-xs text-gray-500">
                                    {formatFileSize(file.size)}
                                  </div>
                                </div>
                              </div>
                              <button
                                onClick={() => downloadFromHistory(file.s3_key, file.filename)}
                                className="text-indigo-600 hover:text-indigo-800 text-sm"
                              >
                                Download
                              </button>
                            </li>
                          ))}
                        </ul>
                      ) : (
                        <p className="text-gray-500 text-sm">No uploads yet</p>
                      )}
                    </div>
                    
                    {/* Recent Exports */}
                    <div>
                      <h3 className="text-lg font-semibold text-gray-900 mb-4">
                        ⬇️ Recent Exports
                      </h3>
                      {exports.length > 0 ? (
                        <ul className="space-y-2">
                          {exports.slice(0, 5).map((file, idx) => (
                            <li 
                              key={idx}
                              className="flex items-center justify-between p-3 bg-gray-50 rounded-lg"
                            >
                              <div className="flex items-center gap-2">
                                <span>{getFormatIcon(file.format)}</span>
                                <div>
                                  <div className="font-medium text-sm truncate max-w-[200px]">
                                    {file.filename}
                                  </div>
                                  <div className="text-xs text-gray-500">
                                    {formatFileSize(file.size)} • {file.format?.toUpperCase()}
                                  </div>
                                </div>
                              </div>
                              <button
                                onClick={() => downloadFromHistory(file.s3_key, file.filename)}
                                className="text-indigo-600 hover:text-indigo-800 text-sm"
                              >
                                Download
                              </button>
                            </li>
                          ))}
                        </ul>
                      ) : (
                        <p className="text-gray-500 text-sm">No exports yet</p>
                      )}
                    </div>
                  </div>
                  
                  {/* Recent Activity */}
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">
                      📋 Recent Activity
                    </h3>
                    {activities.length > 0 ? (
                      <div className="space-y-2">
                        {activities.slice(0, 10).map((activity, idx) => (
                          <div 
                            key={idx}
                            className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg"
                          >
                            <span className="text-xl">{getActionIcon(activity.action)}</span>
                            <div className="flex-1">
                              <div className="font-medium text-sm">
                                {activity.action === 'upload' && 'Uploaded file'}
                                {activity.action === 'export' && 'Exported document'}
                                {activity.action === 'download' && 'Downloaded file'}
                              </div>
                              <div className="text-xs text-gray-500">
                                {activity.details?.filename || activity.details?.s3_key?.split('/').pop()}
                              </div>
                            </div>
                            <div className="text-xs text-gray-400">
                              {formatDate(activity.timestamp)}
                            </div>
                          </div>
                        ))}
                      </div>
                    ) : (
                      <p className="text-gray-500 text-sm">No activity yet</p>
                    )}
                  </div>
                </div>
              )}
              
              {/* Uploads Tab */}
              {activeTab === 'uploads' && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">
                    All Uploaded Files
                  </h3>
                  {uploads.length > 0 ? (
                    <div className="overflow-x-auto">
                      <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                          <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                              File
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                              Size
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                              Date
                            </th>
                            <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                              Action
                            </th>
                          </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                          {uploads.map((file, idx) => (
                            <tr key={idx} className="hover:bg-gray-50">
                              <td className="px-6 py-4 whitespace-nowrap">
                                <div className="flex items-center">
                                  <span className="mr-2">📄</span>
                                  <span className="text-sm font-medium text-gray-900 truncate max-w-[300px]">
                                    {file.filename}
                                  </span>
                                </div>
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                {formatFileSize(file.size)}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                {formatDate(file.last_modified)}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                <button
                                  onClick={() => downloadFromHistory(file.s3_key, file.filename)}
                                  className="text-indigo-600 hover:text-indigo-900"
                                >
                                  Download
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  ) : (
                    <div className="text-center py-12 text-gray-500">
                      <span className="text-4xl mb-4 block">📂</span>
                      <p>No uploaded files yet</p>
                      <p className="text-sm mt-2">
                        Upload a PDF document to get started
                      </p>
                    </div>
                  )}
                </div>
              )}
              
              {/* Exports Tab */}
              {activeTab === 'exports' && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">
                    All Exported Files
                  </h3>
                  {exports.length > 0 ? (
                    <div className="overflow-x-auto">
                      <table className="min-w-full divide-y divide-gray-200">
                        <thead className="bg-gray-50">
                          <tr>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                              File
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                              Format
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                              Size
                            </th>
                            <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                              Date
                            </th>
                            <th className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">
                              Action
                            </th>
                          </tr>
                        </thead>
                        <tbody className="bg-white divide-y divide-gray-200">
                          {exports.map((file, idx) => (
                            <tr key={idx} className="hover:bg-gray-50">
                              <td className="px-6 py-4 whitespace-nowrap">
                                <div className="flex items-center">
                                  <span className="mr-2">{getFormatIcon(file.format)}</span>
                                  <span className="text-sm font-medium text-gray-900 truncate max-w-[300px]">
                                    {file.filename}
                                  </span>
                                </div>
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap">
                                <span className={`px-2 py-1 text-xs font-medium rounded ${
                                  file.format === 'xlsx' ? 'bg-green-100 text-green-800' :
                                  file.format === 'pdf' ? 'bg-red-100 text-red-800' :
                                  file.format === 'docx' ? 'bg-blue-100 text-blue-800' :
                                  file.format === 'csv' ? 'bg-yellow-100 text-yellow-800' :
                                  'bg-gray-100 text-gray-800'
                                }`}>
                                  {file.format?.toUpperCase()}
                                </span>
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                {formatFileSize(file.size)}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                                {formatDate(file.last_modified)}
                              </td>
                              <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                                <button
                                  onClick={() => downloadFromHistory(file.s3_key, file.filename)}
                                  className="text-indigo-600 hover:text-indigo-900"
                                >
                                  Download
                                </button>
                              </td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  ) : (
                    <div className="text-center py-12 text-gray-500">
                      <span className="text-4xl mb-4 block">📤</span>
                      <p>No exported files yet</p>
                      <p className="text-sm mt-2">
                        Process a document and export it to see it here
                      </p>
                    </div>
                  )}
                </div>
              )}
              
              {/* Activity Tab */}
              {activeTab === 'activity' && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">
                    Activity Timeline (Last 30 Days)
                  </h3>
                  {activities.length > 0 ? (
                    <div className="space-y-4">
                      {activities.map((activity, idx) => (
                        <div 
                          key={idx}
                          className="flex items-start gap-4 p-4 bg-gray-50 rounded-lg border-l-4 border-indigo-400"
                        >
                          <div className="text-2xl">{getActionIcon(activity.action)}</div>
                          <div className="flex-1">
                            <div className="flex items-center justify-between">
                              <span className="font-medium text-gray-900 capitalize">
                                {activity.action}
                              </span>
                              <span className="text-sm text-gray-500">
                                {formatDate(activity.timestamp)}
                              </span>
                            </div>
                            <div className="text-sm text-gray-600 mt-1">
                              {activity.details?.filename || activity.details?.s3_key?.split('/').pop() || 'Unknown file'}
                            </div>
                            {activity.details?.format && (
                              <span className="inline-block mt-2 px-2 py-1 text-xs font-medium bg-gray-200 text-gray-700 rounded">
                                {activity.details.format.toUpperCase()}
                              </span>
                            )}
                            {activity.details?.size && (
                              <span className="inline-block mt-2 ml-2 px-2 py-1 text-xs font-medium bg-gray-200 text-gray-700 rounded">
                                {formatFileSize(activity.details.size)}
                              </span>
                            )}
                          </div>
                        </div>
                      ))}
                    </div>
                  ) : (
                    <div className="text-center py-12 text-gray-500">
                      <span className="text-4xl mb-4 block">📋</span>
                      <p>No activity recorded yet</p>
                      <p className="text-sm mt-2">
                        Your actions will be tracked here
                      </p>
                    </div>
                  )}
                </div>
              )}
            </>
          )}
        </div>
        
        {/* Back to Documents Link */}
        <div className="mt-6 text-center">
          <a 
            href="/crs/documents"
            className="inline-flex items-center text-indigo-600 hover:text-indigo-800"
          >
            ← Back to CRS Documents
          </a>
        </div>
      </div>
    </div>
  );
};

export default CRSDocumentsHistory;

/**
 * CRS Multi-Revision Workflow
 * Create chain → Upload Rev 1 → Upload Rev 2 → Upload Rev 3...
 */

import React, { useState } from 'react';
import { 
  Box, 
  Button, 
  Card, 
  CardContent, 
  TextField, 
  Typography, 
  Grid, 
  Alert,
  Paper,
  Stepper,
  Step,
  StepLabel,
  CircularProgress,
  Divider,
  List,
  ListItem,
  ListItemText,
  Chip
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  CheckCircle as CheckIcon,
  Download as DownloadIcon,
  Add as AddIcon,
  NavigateNext as NextIcon
} from '@mui/icons-material';

// Soft-coded configuration
const CONFIG = {
  API_BASE_URL: import.meta.env.VITE_API_URL || '/api/v1',
  TOKEN_KEYS: ['radai_access_token', 'access_token', 'access'],
  MAX_REVISIONS: 10,
  MIN_REVISIONS: 1,
  ACCEPTED_FILE_TYPE: '.pdf'
};

const CRSMultiRevisionWorkflow = () => {
  // Step tracking
  const [currentStep, setCurrentStep] = useState(0); // 0=create chain, 1=upload revisions, 2=complete
  
  // Chain details form
  const [chainForm, setChainForm] = useState({
    chain_id: '',
    document_title: '',
    document_number: '',
    project_name: '',
    contractor_name: '',
    department: '',
    notes: '',
    max_allowed_revisions: 5
  });
  
  // Created chain and revisions
  const [createdChain, setCreatedChain] = useState(null);
  const [currentRevisionNumber, setCurrentRevisionNumber] = useState(1);
  const [uploadedRevisions, setUploadedRevisions] = useState([]);
  const [lastRevisionId, setLastRevisionId] = useState(null);
  
  // UI states
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);

  // Get auth token
  const getAuthHeaders = () => {
    let token = null;
    for (const key of CONFIG.TOKEN_KEYS) {
      token = localStorage.getItem(key);
      if (token) break;
    }
    if (!token) {
      console.warn('[CRS] No token found');
      return {};
    }
    return { 'Authorization': `Bearer ${token}` };
  };

  // STEP 1: Create Chain
  const handleCreateChain = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`${CONFIG.API_BASE_URL}/crs/revision-chains/`, {
        method: 'POST',
        headers: {
          ...getAuthHeaders(),
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(chainForm)
      });

      if (response.ok) {
        const data = await response.json();
        console.log('[CRS] Chain created - Full response:', JSON.stringify(data, null, 2));
        console.log('[CRS] Chain ID field:', data.id);
        console.log('[CRS] Chain PK field:', data.pk);
        console.log('[CRS] All keys:', Object.keys(data));
        setCreatedChain(data);
        setCurrentStep(1);
        setSuccess(`Chain created: ${data.chain_id || data.id}`);
      } else {
        const errData = await response.json().catch(() => ({}));
        console.error('[CRS] Chain creation failed:', response.status, errData);
        setError(`Failed to create chain: ${errData.detail || errData.chain_id?.[0] || response.statusText}`);
      }
    } catch (err) {
      setError(`Error: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // STEP 2: Upload Revision
  const handleUploadRevision = async (file) => {
    if (!file) return;
    
    setLoading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('revision_label', `Rev ${currentRevisionNumber}`);
      
      if (lastRevisionId) {
        formData.append('parent_revision_id', lastRevisionId);
      }

      console.log('[CRS] Uploading to chain:', createdChain.id);
      console.log('[CRS] URL:', `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/upload_and_add_revision/`);
      
      const response = await fetch(
        `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/upload_and_add_revision/`,
        {
          method: 'POST',
          headers: getAuthHeaders(),
          body: formData
        }
      );

      if (response.ok) {
        const result = await response.json();
        console.log('[CRS] Upload success - Full response:', JSON.stringify(result, null, 2));
        const data = result.data || result; // Handle both response structures
        console.log('[CRS] Extraction summary:', data.extraction_summary);
        const newRevision = {
          number: currentRevisionNumber,
          label: `Rev ${currentRevisionNumber}`,
          fileName: file.name,
          comments: data.extraction_summary?.total_comments || 0,
          redComments: data.extraction_summary?.red_comments || 0,
          yellowComments: data.extraction_summary?.yellow_comments || 0,
          data: data
        };
        
        setUploadedRevisions([...uploadedRevisions, newRevision]);
        setLastRevisionId(data.revision?.id || null);
        setSuccess(`Rev ${currentRevisionNumber} uploaded! ${newRevision.comments} comments extracted.`);
        
        // Move to next revision or complete
        if (currentRevisionNumber >= chainForm.max_allowed_revisions) {
          setCurrentStep(2);
        } else {
          setCurrentRevisionNumber(currentRevisionNumber + 1);
        }
      } else {
        const errData = await response.json().catch(() => ({}));
        console.error('[CRS] Upload failed:', response.status, errData);
        const errorMsg = errData.details || errData.error || errData.detail || response.statusText;
        setError(`Failed to upload revision: ${errorMsg}`);
      }
    } catch (err) {
      setError(`Error: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Download Excel
  const handleDownloadExcel = async () => {
    if (!createdChain) {
      setError('No chain created yet');
      return;
    }
    
    console.log('[CRS] Downloading Excel for chain:', createdChain.id);
    setLoading(true);
    setError(null);
    
    try {
      // Use simple HTML-to-Excel export endpoint
      const url = `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/export_simple/`;
      console.log('[CRS] Excel download URL:', url);
      
      const response = await fetch(url, { 
        headers: getAuthHeaders(),
        method: 'GET'
      });
      
      console.log('[CRS] Excel response status:', response.status);
      
      if (response.ok) {
        const blob = await response.blob();
        console.log('[CRS] Excel blob size:', blob.size);
        
        const downloadUrl = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = downloadUrl;
        a.download = `CRS_${createdChain.chain_id}_Export.xls`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(downloadUrl);
        
        setSuccess('Excel downloaded successfully!');
      } else {
        const errorText = await response.text();
        console.error('[CRS] Excel download failed:', errorText);
        setError(`Failed to download Excel: ${response.statusText}`);
      }
    } catch (err) {
      console.error('[CRS] Excel download error:', err);
      setError('Failed to download Excel: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  // Reset and start over
  const handleReset = () => {
    setCurrentStep(0);
    setCreatedChain(null);
    setCurrentRevisionNumber(1);
    setUploadedRevisions([]);
    setLastRevisionId(null);
    setError(null);
    setSuccess(null);
    setChainForm({
      chain_id: '',
      document_title: '',
      document_number: '',
      project_name: '',
      contractor_name: '',
      department: '',
      notes: '',
      max_allowed_revisions: 5
    });
  };

  return (
    <Box sx={{ p: 3, maxWidth: 1200, mx: 'auto' }}>
      {/* Header */}
      <Typography variant="h4" gutterBottom fontWeight="bold">
        📄 CRS Multi-Revision Workflow
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        Create a new revision chain and upload CRS sheets one by one
      </Typography>

      {/* Stepper */}
      <Stepper activeStep={currentStep} sx={{ mb: 4 }}>
        <Step>
          <StepLabel>Create Chain</StepLabel>
        </Step>
        <Step>
          <StepLabel>Upload Revisions</StepLabel>
        </Step>
        <Step>
          <StepLabel>Complete</StepLabel>
        </Step>
      </Stepper>

      {/* Alerts */}
      {error && <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess(null)}>{success}</Alert>}

      {/* STEP 0: Create Chain Form */}
      {currentStep === 0 && (
        <Paper sx={{ p: 4 }}>
          <Typography variant="h5" gutterBottom>
            Step 1: Create New Revision Chain
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
            Enter project details and specify how many revisions you want to upload
          </Typography>

          <form onSubmit={handleCreateChain}>
            <Grid container spacing={3}>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Chain ID *"
                  fullWidth
                  required
                  value={chainForm.chain_id}
                  onChange={(e) => setChainForm({...chainForm, chain_id: e.target.value})}
                  placeholder="e.g., CHAIN-001"
                  helperText="Unique identifier for this chain"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Document Title *"
                  fullWidth
                  required
                  value={chainForm.document_title}
                  onChange={(e) => setChainForm({...chainForm, document_title: e.target.value})}
                  placeholder="e.g., Main Building Structural Drawings"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Document Number *"
                  fullWidth
                  required
                  value={chainForm.document_number}
                  onChange={(e) => setChainForm({...chainForm, document_number: e.target.value})}
                  placeholder="e.g., STR-001"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Project Name *"
                  fullWidth
                  required
                  value={chainForm.project_name}
                  onChange={(e) => setChainForm({...chainForm, project_name: e.target.value})}
                  placeholder="e.g., Downtown Tower Project"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Contractor Name"
                  fullWidth
                  value={chainForm.contractor_name}
                  onChange={(e) => setChainForm({...chainForm, contractor_name: e.target.value})}
                  placeholder="e.g., ABC Construction"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Department"
                  fullWidth
                  value={chainForm.department}
                  onChange={(e) => setChainForm({...chainForm, department: e.target.value})}
                  placeholder="e.g., Engineering"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Number of Revisions *"
                  type="number"
                  fullWidth
                  required
                  value={chainForm.max_allowed_revisions}
                  onChange={(e) => setChainForm({
                    ...chainForm, 
                    max_allowed_revisions: Math.min(CONFIG.MAX_REVISIONS, Math.max(CONFIG.MIN_REVISIONS, parseInt(e.target.value) || 1))
                  })}
                  InputProps={{
                    inputProps: { 
                      min: CONFIG.MIN_REVISIONS, 
                      max: CONFIG.MAX_REVISIONS 
                    }
                  }}
                  helperText={`How many CRS sheets will you upload? (${CONFIG.MIN_REVISIONS}-${CONFIG.MAX_REVISIONS})`}
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Notes"
                  fullWidth
                  multiline
                  rows={3}
                  value={chainForm.notes}
                  onChange={(e) => setChainForm({...chainForm, notes: e.target.value})}
                  placeholder="Optional notes about this document chain"
                />
              </Grid>
            </Grid>

            <Box sx={{ mt: 4, display: 'flex', justifyContent: 'flex-end' }}>
              <Button
                type="submit"
                variant="contained"
                size="large"
                disabled={loading}
                startIcon={loading ? <CircularProgress size={20} /> : <AddIcon />}
                sx={{ minWidth: 200 }}
              >
                {loading ? 'Creating...' : 'Create Chain & Start Upload'}
              </Button>
            </Box>
          </form>
        </Paper>
      )}

      {/* STEP 1: Upload Revisions */}
      {currentStep === 1 && createdChain && (
        <Box>
          {/* Chain Info */}
          <Paper sx={{ p: 3, mb: 3, bgcolor: 'primary.light' }}>
            <Typography variant="h6" gutterBottom>
              📋 Chain: {createdChain.document_title}
            </Typography>
            <Grid container spacing={2}>
              <Grid item>
                <Chip label={`Doc #: ${createdChain.document_number}`} />
              </Grid>
              <Grid item>
                <Chip label={`Project: ${createdChain.project_name}`} />
              </Grid>
              <Grid item>
                <Chip label={`Total Revisions: ${chainForm.max_allowed_revisions}`} color="primary" />
              </Grid>
            </Grid>
          </Paper>

          {/* Upload Current Revision */}
          <Paper sx={{ p: 4, mb: 3 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 3 }}>
              <Typography variant="h5">
                Upload Revision {currentRevisionNumber} of {chainForm.max_allowed_revisions}
              </Typography>
              <Chip 
                label={`Rev ${currentRevisionNumber}`} 
                color="primary" 
                size="large"
                sx={{ fontSize: '1.1rem', py: 3 }}
              />
            </Box>

            <Box sx={{ textAlign: 'center', py: 4 }}>
              <Button
                variant="contained"
                component="label"
                size="large"
                disabled={loading}
                startIcon={loading ? <CircularProgress size={24} /> : <UploadIcon />}
                sx={{ 
                  py: 3, 
                  px: 6, 
                  fontSize: '1.2rem',
                  minWidth: 300
                }}
              >
                {loading ? 'Uploading...' : `📤 Upload CRS Sheet ${currentRevisionNumber}`}
                <input
                  type="file"
                  hidden
                  accept={CONFIG.ACCEPTED_FILE_TYPE}
                  onChange={(e) => {
                    if (e.target.files[0]) {
                      handleUploadRevision(e.target.files[0]);
                    }
                  }}
                  disabled={loading}
                />
              </Button>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
                PDF files only • Comments will be automatically extracted
              </Typography>
            </Box>
          </Paper>

          {/* Uploaded Revisions List */}
          {uploadedRevisions.length > 0 && (
            <Paper sx={{ p: 3 }}>
              <Typography variant="h6" gutterBottom>
                ✅ Uploaded Revisions ({uploadedRevisions.length})
              </Typography>
              <List>
                {uploadedRevisions.map((rev, idx) => (
                  <React.Fragment key={idx}>
                    <ListItem>
                      <CheckIcon color="success" sx={{ mr: 2, fontSize: 32 }} />
                      <ListItemText
                        primary={
                          <Typography variant="h6">
                            {rev.label}: {rev.fileName}
                          </Typography>
                        }
                        secondary={
                          <Box sx={{ mt: 1 }}>
                            <Chip label={`${rev.comments} Total Comments`} size="small" sx={{ mr: 1 }} />
                            <Chip label={`${rev.redComments} Red`} size="small" color="error" sx={{ mr: 1 }} />
                            <Chip label={`${rev.yellowComments} Yellow`} size="small" color="warning" />
                          </Box>
                        }
                      />
                    </ListItem>
                    {idx < uploadedRevisions.length - 1 && <Divider />}
                  </React.Fragment>
                ))}
              </List>
              
              {/* Download Excel Button - Available after first upload */}
              <Box sx={{ mt: 3, pt: 3, borderTop: '1px solid #ddd', textAlign: 'center' }}>
                <Button
                  variant="contained"
                  color="success"
                  size="large"
                  onClick={handleDownloadExcel}
                  startIcon={<DownloadIcon />}
                  sx={{ minWidth: 250, py: 1.5 }}
                >
                  📥 Download Excel Report
                </Button>
                <Typography variant="caption" display="block" color="text.secondary" sx={{ mt: 1 }}>
                  Contains all uploaded revisions and extracted comments
                </Typography>
              </Box>
            </Paper>
          )}
        </Box>
      )}

      {/* STEP 2: Complete */}
      {currentStep === 2 && (
        <Paper sx={{ p: 4, textAlign: 'center' }}>
          <CheckIcon sx={{ fontSize: 80, color: 'success.main', mb: 2 }} />
          <Typography variant="h4" gutterBottom>
            🎉 All Revisions Uploaded!
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 4 }}>
            Successfully uploaded {uploadedRevisions.length} revisions for {createdChain?.document_title}
          </Typography>

          <Grid container spacing={2} sx={{ mb: 4 }}>
            {uploadedRevisions.map((rev, idx) => (
              <Grid item xs={12} md={6} key={idx}>
                <Card variant="outlined">
                  <CardContent>
                    <Typography variant="h6">{rev.label}</Typography>
                    <Typography variant="body2" color="text.secondary" noWrap>
                      {rev.fileName}
                    </Typography>
                    <Box sx={{ mt: 1 }}>
                      <Chip label={`${rev.comments} Comments`} size="small" color="primary" />
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>

          <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center' }}>
            <Button
              variant="contained"
              size="large"
              onClick={handleDownloadExcel}
              startIcon={<DownloadIcon />}
              sx={{ minWidth: 200 }}
            >
              Download Excel Report
            </Button>
            <Button
              variant="outlined"
              size="large"
              onClick={handleReset}
              sx={{ minWidth: 200 }}
            >
              Create Another Chain
            </Button>
          </Box>
        </Paper>
      )}
    </Box>
  );
};

export default CRSMultiRevisionWorkflow;

import { radaiConfirm } from '../services/radaiDialog'
/**
 * CRS Multi-Revision Workflow - SMART VERSION
 * With Preview Table & HTML-to-Excel Export
 */

import React, { useState } from 'react';
import { 
  Box, Button, Card, CardContent, TextField, Typography, Grid, Alert,
  Paper, Stepper, Step, StepLabel, CircularProgress, Divider,
  List, ListItem, ListItemText, Chip, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, IconButton, Tooltip, Select, MenuItem, FormControl
} from '@mui/material';
import {
  CloudUpload as UploadIcon, CheckCircle as CheckIcon,
  Download as DownloadIcon, Visibility as PreviewIcon,
  TableChart as TableIcon, CloudDownload as CloudDownloadIcon
} from '@mui/icons-material';
import { withDashboardControls } from '../hoc/withPageControls';
import { PageControlButtons } from '../components/PageControlButtons';

// Smart configuration
const CONFIG = {
  API_BASE_URL: import.meta.env.VITE_API_URL || '/api/v1',
  TOKEN_KEYS: ['radai_access_token', 'access_token', 'access'],
  MAX_FILE_SIZE_MB: 50,
  ACCEPTED_FILE_TYPE: '.pdf'
};

const CRSMultiRevisionSmart = ({ pageControls }) => {
  // Step tracking
  const [currentStep, setCurrentStep] = useState(0);
  
  // Chain details
  const [chainForm, setChainForm] = useState({
    chain_id: '', document_title: '', document_number: '',
    project_name: '', contractor_name: '', department: '',
    notes: '', max_allowed_revisions: 10  // Flexible: user can set max, finish early
  });
  
  // Created chain and revisions
  const [createdChain, setCreatedChain] = useState(null);
  const [currentRevisionNumber, setCurrentRevisionNumber] = useState(1);
  const [uploadedRevisions, setUploadedRevisions] = useState([]);
  const [allComments, setAllComments] = useState([]); // For preview table
  
  // UI states
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);
  const [showPreview, setShowPreview] = useState(false);
  const [hasOpenComments, setHasOpenComments] = useState(false); // Track if previous revisions have open comments

  // Smart auto-generation of unique chain_id
  const generateUniqueChainId = () => {
    const timestamp = Date.now();
    const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
    const prefix = chainForm.project_name ? 
      chainForm.project_name.substring(0, 3).toUpperCase().replace(/[^A-Z]/g, '') || 'CRS' : 
      'CRS';
    return `${prefix}-${timestamp}-${random}`;
  };

  const handleAutoGenerateChainId = () => {
    const newChainId = generateUniqueChainId();
    setChainForm({...chainForm, chain_id: newChainId});
    setSuccess(`Auto-generated Chain ID: ${newChainId}`);
    setTimeout(() => setSuccess(null), 3000);
  };

  // Smart auth helper
  const getAuthHeaders = () => {
    for (const key of CONFIG.TOKEN_KEYS) {
      const token = localStorage.getItem(key);
      if (token) return { 'Authorization': `Bearer ${token}` };
    }
    console.warn('[CRS] No auth token found');
    return {};
  };

  // Create Chain with smart error handling
  const handleCreateChain = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    // Client-side validation for required fields
    const requiredFields = {
      'Chain ID': chainForm.chain_id,
      'Document Title': chainForm.document_title,
      'Document Number': chainForm.document_number,
      'Project Name': chainForm.project_name
    };

    const missingFields = Object.entries(requiredFields)
      .filter(([_, value]) => !value || value.trim() === '')
      .map(([name, _]) => name);

    if (missingFields.length > 0) {
      setError(`Required fields missing: ${missingFields.join(', ')}`);
      setLoading(false);
      return;
    }

    try {
      console.log('[CRS] Submitting chain data:', chainForm);
      
      const response = await fetch(`${CONFIG.API_BASE_URL}/crs/revision-chains/`, {
        method: 'POST',
        headers: { ...getAuthHeaders(), 'Content-Type': 'application/json' },
        body: JSON.stringify(chainForm)
      });

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        console.error('[CRS] Server error response:', JSON.stringify(errorData, null, 2));
        console.error('[CRS] Error data keys:', Object.keys(errorData));
        console.error('[CRS] Full error object:', errorData);
        
        // Smart error message extraction - handle all possible formats
        let errorMsg = `Failed: ${response.status}`;
        
        // Check for 'detail' field
        if (errorData.detail && typeof errorData.detail === 'string') {
          errorMsg = errorData.detail;
        }
        
        // Check for 'errors' object (DRF serializer errors)
        if (errorData.errors && typeof errorData.errors === 'object') {
          const fieldErrors = Object.entries(errorData.errors)
            .map(([field, errors]) => {
              const errorText = Array.isArray(errors) ? errors.join(', ') : String(errors);
              return `${field}: ${errorText}`;
            })
            .join(' | ');
          if (fieldErrors) errorMsg = fieldErrors;
        }
        
        // Check for direct field errors (DRF default format)
        else if (errorData && typeof errorData === 'object' && !errorData.detail && !errorData.errors) {
          // DRF returns errors like: {chain_id: ['error msg'], project_name: ['error msg']}
          const directErrors = Object.entries(errorData)
            .filter(([key]) => key !== 'non_field_errors')
            .map(([field, errors]) => {
              const errorText = Array.isArray(errors) ? errors.join(', ') : String(errors);
              return `${field}: ${errorText}`;
            });
          
          if (directErrors.length > 0) {
            errorMsg = directErrors.join(' | ');
          }
          
          // Check for non_field_errors
          if (errorData.non_field_errors) {
            const nfeText = Array.isArray(errorData.non_field_errors) 
              ? errorData.non_field_errors.join(', ') 
              : String(errorData.non_field_errors);
            errorMsg = nfeText;
          }
        }
        
        // Final fallback: stringify the entire error object
        if (errorMsg === `Failed: ${response.status}` && Object.keys(errorData).length > 0) {
          errorMsg = JSON.stringify(errorData);
        }
        
        console.error('[CRS] Final error message:', errorMsg);
        throw new Error(errorMsg);
      }

      const data = await response.json();
      setCreatedChain(data);
      setSuccess(`Chain "${data.chain_id}" created successfully!`);
      setCurrentStep(1);
      setError(null);
    } catch (err) {
      let errorMessage = err.message || 'Failed to create chain';
      
      // Smart handling for duplicate chain_id
      if (errorMessage.includes('already exists') || errorMessage.includes('chain_id')) {
        errorMessage += ' - Click "Auto-Generate ID" button to create a unique Chain ID.';
      }
      
      setError(errorMessage);
      console.error('[CRS] Create chain error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Smart Status Change Handler with Dropdown
  const handleStatusChange = async (commentId, newStatus, revisionLabel, commentText) => {
    if (!createdChain?.id) {
      setError('❌ No revision chain found');
      return;
    }

    setLoading(true);
    try {
      const response = await fetch(
        `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/close_comment/`,
        {
          method: 'POST',
          headers: {
            ...getAuthHeaders(),
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({ comment_id: commentId, status: newStatus })
        }
      );

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Failed to update comment status');
      }

      // Smart state update: Update the comment status in local state
      setUploadedRevisions(prevRevisions => 
        prevRevisions.map(rev => {
          if (rev.comments && rev.comments.length > 0) {
            return {
              ...rev,
              comments: rev.comments.map(comment => 
                (comment.id === commentId || comment.comment_id === commentId)
                  ? { ...comment, status: newStatus }
                  : comment
              )
            };
          }
          // Also check nested data structure
          if (rev.data?.comments && rev.data.comments.length > 0) {
            return {
              ...rev,
              data: {
                ...rev.data,
                comments: rev.data.comments.map(comment =>
                  (comment.id === commentId || comment.comment_id === commentId)
                    ? { ...comment, status: newStatus }
                    : comment
                )
              }
            };
          }
          return rev;
        })
      );

      setSuccess(`✅ Status updated to "${newStatus}" successfully!`);
      setTimeout(() => setSuccess(''), 3000);
      
      // Force re-check of open comments after status change
      console.log('[CRS] Status updated, checking for remaining open comments...');
      
    } catch (err) {
      setError(`❌ Failed to update status: ${err.message}`);
      console.error('[CRS] Status change error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Smart Close Comment Handler (for Action button)
  const handleCloseComment = async (commentId, revisionLabel, commentText) => {
    const confirmClose = (await radaiConfirm(
      `🔒 Close this comment?\n\nRevision: ${revisionLabel}\nComment: ${commentText?.substring(0, 100)}${commentText?.length > 100 ? '...' : ''}\n\nThis action will mark the comment as CLOSED.`
    ));

    if (!confirmClose) return;

    await handleStatusChange(commentId, 'closed', revisionLabel, commentText);
  };

  // Check if there are open comments from previous revisions
  const checkForOpenComments = () => {
    console.log('[CRS] Checking for open comments...');
    console.log('[CRS] Current uploadedRevisions:', uploadedRevisions);
    console.log('[CRS] Current revision number:', currentRevisionNumber);
    
    if (uploadedRevisions.length === 0) {
      console.log('[CRS] No revisions uploaded yet');
      return false;
    }
    
    // For REV 2 upload, check REV 1. For REV 3, check REV 1 & 2, etc.
    // We check ALL previous revisions (not just the latest)
    const previousRevisions = uploadedRevisions;
    
    console.log(`[CRS] Checking ${previousRevisions.length} previous revision(s)`);
    
    // Check each revision for open comments
    for (const rev of previousRevisions) {
      const comments = rev.comments || rev.data?.comments || [];
      console.log(`[CRS] ${rev.label}: ${comments.length} total comments`);
      
      const openComments = comments.filter(comment => {
        const status = (comment.status || 'open').toLowerCase();
        const isOpen = status === 'open';
        if (isOpen) {
          console.log(`[CRS]   - OPEN: "${(comment.comment_text || comment.text || '').substring(0, 50)}..."`);
        }
        return isOpen;
      });
      
      if (openComments.length > 0) {
        console.log(`[CRS] ❌ FOUND ${openComments.length} open comment(s) in ${rev.label}`);
        return true;
      }
    }
    
    console.log('[CRS] ✅ All comments are closed');
    return false;
  };

  // Upload Revision with smart file validation
  const handleUploadRevision = async (e) => {
    const file = e.target.files[0];
    if (!file) return;

    // ⚠️ CRITICAL: Client-side validation FIRST - check local state
    if (uploadedRevisions.length > 0) {
      const hasOpenComments = checkForOpenComments();
      if (hasOpenComments) {
        setError('⚠️ BLOCKED: You have open comments from previous revisions! Please close all comments before uploading the next revision.');
        e.target.value = ''; // Reset file input
        console.error('[CRS] ❌ Upload blocked - open comments detected in frontend state');
        return; // BLOCK IMMEDIATELY
      }
    }

    // Smart validation
    if (!file.name.toLowerCase().endsWith('.pdf')) {
      setError('Only PDF files are accepted');
      return;
    }

    const fileSizeMB = file.size / (1024 * 1024);
    if (fileSizeMB > CONFIG.MAX_FILE_SIZE_MB) {
      setError(`File too large (${fileSizeMB.toFixed(1)} MB). Max: ${CONFIG.MAX_FILE_SIZE_MB} MB`);
      return;
    }

    // ⚠️ CRITICAL VALIDATION: Double-check with backend API
    if (uploadedRevisions.length > 0) {
      setLoading(true);
      setError(null);
      
      try {
        const checkResponse = await fetch(
          `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/check_previous_comments_status/`,
          { headers: getAuthHeaders() }
        );

        if (!checkResponse.ok) {
          throw new Error(`Failed to verify comment status: ${checkResponse.status}`);
        }

        const checkData = await checkResponse.json();
        
        // BLOCK upload if any comments are still open
        if (!checkData.all_closed && checkData.open_count > 0) {
          setError(`⚠️ Cannot upload next revision! You must close all ${checkData.open_count} open comment(s) from previous revisions first. Use the "Close" action in the comments table below.`);
          setLoading(false);
          e.target.value = ''; // Reset file input to allow retry
          return;
        }
        
        // All comments closed - proceed with upload
        console.log(`[CRS] ✅ All previous comments closed, proceeding with REV ${currentRevisionNumber} upload`);
        
      } catch (err) {
        console.error('[CRS] Comment status check failed:', err);
        setError(`⚠️ Could not verify comment status: ${err.message}. Please ensure all previous comments are closed before uploading.`);
        setLoading(false);
        e.target.value = ''; // Reset file input
        return; // BLOCK upload on validation error
      }
    } else {
      // First revision - no validation needed
      setLoading(true);
      setError(null);
    }

    try {
      const formData = new FormData();
      formData.append('file', file);  // Backend expects 'file', not 'pdf_file'
      formData.append('revision_label', `Rev ${currentRevisionNumber}`);
      formData.append('notes', `Revision ${currentRevisionNumber} upload`);

      const response = await fetch(
        `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/upload_and_add_revision/`,
        {
          method: 'POST',
          headers: getAuthHeaders(),
          body: formData
        }
      );

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}));
        throw new Error(errorData.error || `Upload failed: ${response.status}`);
      }

      const data = await response.json();
      
      // Smart comment extraction from response
      let extractedComments = [];
      
      // Try multiple paths to find comments in the response
      if (data.data?.comments) {
        extractedComments = data.data.comments;
      } else if (data.comments) {
        extractedComments = data.comments;
      } else if (data.data?.document_details?.comments) {
        extractedComments = data.data.document_details.comments;
      }
      
      // Ensure all comments have a status field (default to 'open')
      extractedComments = extractedComments.map(comment => ({
        ...comment,
        status: comment.status || 'open' // CRITICAL: Default to 'open'
      }));
      
      console.log(`[CRS] Extracted ${extractedComments.length} comments with status:`, 
        extractedComments.map(c => ({ id: c.id, status: c.status })));
      
      // Store revision with extracted comments
      const revisionData = {
        number: currentRevisionNumber,
        label: `Rev ${currentRevisionNumber}`,
        fileName: file.name,
        data: data.data,
        uploadedAt: new Date().toISOString(),
        comments: extractedComments, // Store comments directly
        totalComments: data.data?.extraction_summary?.total_comments || extractedComments.length || 0
      };

      setUploadedRevisions(prev => [...prev, revisionData]);
      
      // Add comments to global comments list
      if (extractedComments.length > 0) {
        setAllComments(prev => [...prev, ...extractedComments.map(c => ({
          ...c,
          revision: revisionData.label,
          revision_label: revisionData.label,
          revisionNumber: currentRevisionNumber
        }))]);
      }

      setSuccess(`Revision ${currentRevisionNumber} uploaded successfully! (${revisionData.totalComments} comments found)`);
      setCurrentRevisionNumber(prev => prev + 1);
      setError(null);

      // Auto-show preview after first upload
      if (currentRevisionNumber === 1) {
        setShowPreview(true);
      }
    } catch (err) {
      setError(err.message || 'Upload failed');
      console.error('[CRS] Upload error:', err);
    } finally {
      setLoading(false);
      e.target.value = ''; // Reset file input
    }
  };

  // Smart HTML-to-Excel export - ALL revisions combined
  const handleDownloadExcel = async () => {
    try {
      setLoading(true);
      
      // Fetch all chain data
      const response = await fetch(
        `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/`,
        { headers: getAuthHeaders() }
      );

      if (!response.ok) throw new Error('Failed to fetch chain data');
      
      const chainData = await response.json();

      // Build smart HTML table
      const html = generateSmartHTML(chainData, uploadedRevisions);

      // Convert to Excel-compatible format
      const blob = new Blob([html], { 
        type: 'application/vnd.ms-excel;charset=utf-8' 
      });
      
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `CRS_${chainData.chain_id}_ALL_REVISIONS_${new Date().toISOString().split('T')[0]}.xls`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setSuccess('Combined Excel file downloaded successfully!');
    } catch (err) {
      setError(`Download failed: ${err.message}`);
      console.error('[CRS] Excel download error:', err);
    } finally {
      setLoading(false);
    }
  };

  // S3 Excel Download Handler - Try S3 first, fallback to on-the-fly generation
  const handleDownloadFromS3 = async (revisionIndex) => {
    try {
      const revision = uploadedRevisions[revisionIndex];
      
      if (!revision || !revision.data || !revision.data.revision) {
        throw new Error('Revision data not found');
      }

      const revisionData = revision.data.revision;
      
      // Check if S3 presigned URL exists
      if (revisionData.excel_download_url) {
        console.log(`✅ Downloading from S3: ${revision.label}`);
        
        // Download from S3 using presigned URL
        const link = document.createElement('a');
        link.href = revisionData.excel_download_url;
        link.download = `CRS_${createdChain.chain_id}_${revision.label}_${new Date().toISOString().split('T')[0]}.xls`;
        link.target = '_blank';
        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);
        
        setSuccess(`✅ Downloaded ${revision.label} from S3`);
        return;
      } else {
        // Fallback: Generate on-the-fly (existing logic)
        console.warn('⚠️ No S3 URL available, generating excel on-the-fly');
        handleDownloadSingleRevision(revisionIndex);
      }
    } catch (error) {
      console.error('❌ Error downloading from S3:', error);
      // Fallback to existing on-the-fly generation
      setError('S3 download failed, generating excel...');
      setTimeout(() => handleDownloadSingleRevision(revisionIndex), 1000);
    }
  };

  // Smart individual revision download - soft-coded for any revision
  const handleDownloadSingleRevision = async (revisionIndex) => {
    try {
      setLoading(true);
      const revision = uploadedRevisions[revisionIndex];
      
      if (!revision) {
        throw new Error('Revision not found');
      }

      // Fetch chain data for context
      const response = await fetch(
        `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/`,
        { headers: getAuthHeaders() }
      );

      if (!response.ok) throw new Error('Failed to fetch chain data');
      
      const chainData = await response.json();

      // Build HTML for single revision
      const html = generateSingleRevisionHTML(chainData, revision);

      // Convert to Excel
      const blob = new Blob([html], { 
        type: 'application/vnd.ms-excel;charset=utf-8' 
      });
      
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = `CRS_${chainData.chain_id}_${revision.label}_${new Date().toISOString().split('T')[0]}.xls`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      setSuccess(`${revision.label} Excel downloaded successfully!`);
    } catch (err) {
      setError(`Download failed: ${err.message}`);
      console.error('[CRS] Single revision download error:', err);
    } finally {
      setLoading(false);
    }
  };

  // Generate smart HTML for Excel export - ALL revisions
  const generateSmartHTML = (chainData, revisions) => {
    return `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel">
      <head>
        <meta charset="UTF-8">
        <style>
          table { border-collapse: collapse; width: 100%; margin-bottom: 20px; }
          th, td { border: 1px solid black; padding: 8px; text-align: left; }
          th { background-color: #4CAF50; color: white; font-weight: bold; }
          .section-header { background-color: #2196F3; color: white; font-weight: bold; font-size: 14px; }
          .revision-header { background-color: #FF9800; color: white; font-weight: bold; font-size: 13px; }
          .status-open { background-color: #FFEBEE; color: #C62828; font-weight: bold; }
          .status-closed { background-color: #E8F5E9; color: #2E7D32; font-weight: bold; }
          .rev-separator { height: 20px; background-color: #F5F5F5; }
        </style>
      </head>
      <body>
        <h2>CRS Multi-Revision Comparison Report</h2>
        <p><i>Generated on: ${new Date().toLocaleString()}</i></p>
        
        <!-- Chain Information -->
        <table>
          <tr class="section-header"><th colspan="2">Chain Information</th></tr>
          <tr><td><b>Chain ID</b></td><td>${chainData.chain_id || 'N/A'}</td></tr>
          <tr><td><b>Document Title</b></td><td>${chainData.document_title || 'N/A'}</td></tr>
          <tr><td><b>Document Number</b></td><td>${chainData.document_number || 'N/A'}</td></tr>
          <tr><td><b>Project Name</b></td><td>${chainData.project_name || 'N/A'}</td></tr>
          <tr><td><b>Contractor</b></td><td>${chainData.contractor_name || 'N/A'}</td></tr>
          <tr><td><b>Department</b></td><td>${chainData.department || 'N/A'}</td></tr>
          <tr><td><b>Total Revisions</b></td><td>${revisions.length}</td></tr>
        </table>
        <br/>
        
        <!-- Revisions Summary -->
        <table>
          <tr class="section-header"><th colspan="6">Revisions Summary</th></tr>
          <tr>
            <th>Revision</th>
            <th>File Name</th>
            <th>Total Comments</th>
            <th>Open Comments</th>
            <th>Closed Comments</th>
            <th>Uploaded At</th>
          </tr>
          ${revisions.map(rev => {
            const comments = rev.comments || rev.data?.comments || [];
            const openCount = comments.filter(c => (c.status || 'open').toLowerCase() === 'open').length;
            const closedCount = comments.filter(c => (c.status || 'open').toLowerCase() === 'closed').length;
            return `
            <tr>
              <td><b>${rev.label}</b></td>
              <td>${rev.fileName}</td>
              <td>${comments.length}</td>
              <td class="status-open">${openCount}</td>
              <td class="status-closed">${closedCount}</td>
              <td>${new Date(rev.uploadedAt).toLocaleString()}</td>
            </tr>
          `}).join('')}
        </table>
        <br/>
        
        <!-- Comments by Revision (Separated) -->
        ${revisions.map((rev, revIdx) => {
          const comments = rev.comments || rev.data?.comments || [];
          const openCount = comments.filter(c => (c.status || 'open').toLowerCase() === 'open').length;
          const closedCount = comments.filter(c => (c.status || 'open').toLowerCase() === 'closed').length;
          
          return `
          ${revIdx > 0 ? '<br/><br/>' : ''}
          <table>
            <tr class="revision-header">
              <th colspan="8">
                📄 ${rev.label} - ${comments.length} Comment${comments.length !== 1 ? 's' : ''} 
                (🔴 ${openCount} Open | ✅ ${closedCount} Closed)
              </th>
            </tr>
            <tr>
              <th>Page</th>
              <th>Reviewer</th>
              <th>Comment</th>
              <th>Type</th>
              <th>Discipline</th>
              <th>Drawing Ref</th>
              <th>Status</th>
              <th>Serial #</th>
            </tr>
            ${comments.length > 0 ? comments.map((comment, idx) => {
              const status = (comment.status || 'open').toLowerCase();
              const statusClass = status === 'open' ? 'status-open' : 'status-closed';
              return `
              <tr>
                <td>${comment.page_number || 'N/A'}</td>
                <td>${comment.reviewer_name || 'Not Provided'}</td>
                <td>${comment.comment_text || comment.text || 'N/A'}</td>
                <td>${comment.comment_type || comment.type || 'GENERAL'}</td>
                <td>${comment.discipline || 'Not Provided'}</td>
                <td>${comment.drawing_ref || 'N/A'}</td>
                <td class="${statusClass}">${status.toUpperCase()}</td>
                <td>${comment.serial_number || idx + 1}</td>
              </tr>
            `}).join('') : `
              <tr><td colspan="8" style="text-align: center; font-style: italic;">No comments found for ${rev.label}</td></tr>
            `}
          </table>
        `}).join('')}
        
        <br/><br/>
        <p style="font-size: 12px; color: #666;">
          <b>Legend:</b><br/>
          🔴 Open = Comment requires action<br/>
          ✅ Closed = Comment resolved<br/>
          <br/>
          <i>This report contains ${revisions.length} revision${revisions.length !== 1 ? 's' : ''} with detailed comment tracking.</i>
        </p>
      </body>
      </html>
    `;
  };

  // Generate HTML for SINGLE revision - soft-coded
  const generateSingleRevisionHTML = (chainData, revision) => {
    const comments = revision.comments || revision.data?.comments || revision.data?.document_details?.recent_activities || [];
    const openCount = comments.filter(c => (c.status || 'open').toLowerCase() === 'open').length;
    const closedCount = comments.filter(c => (c.status || 'open').toLowerCase() === 'closed').length;
    
    return `
      <html xmlns:o="urn:schemas-microsoft-com:office:office" xmlns:x="urn:schemas-microsoft-com:office:excel">
      <head>
        <meta charset="UTF-8">
        <style>
          table { border-collapse: collapse; width: 100%; margin-bottom: 15px; }
          th, td { border: 1px solid black; padding: 8px; text-align: left; }
          th { background-color: #4CAF50; color: white; font-weight: bold; }
          .section-header { background-color: #2196F3; color: white; font-weight: bold; }
          .status-open { background-color: #FFEBEE; color: #C62828; font-weight: bold; }
          .status-closed { background-color: #E8F5E9; color: #2E7D32; font-weight: bold; }
        </style>
      </head>
      <body>
        <h2>CRS Report - ${revision.label}</h2>
        <p><i>Generated on: ${new Date().toLocaleString()}</i></p>
        
        <!-- Chain Context -->
        <table>
          <tr class="section-header"><th colspan="2">Document Information</th></tr>
          <tr><td><b>Chain ID</b></td><td>${chainData.chain_id || 'N/A'}</td></tr>
          <tr><td><b>Document Title</b></td><td>${chainData.document_title || 'N/A'}</td></tr>
          <tr><td><b>Document Number</b></td><td>${chainData.document_number || 'N/A'}</td></tr>
          <tr><td><b>Project Name</b></td><td>${chainData.project_name || 'N/A'}</td></tr>
          <tr><td><b>Contractor</b></td><td>${chainData.contractor_name || 'N/A'}</td></tr>
          <tr><td><b>Department</b></td><td>${chainData.department || 'N/A'}</td></tr>
        </table>
        <br/>
        
        <!-- Revision Details -->
        <table>
          <tr class="section-header"><th colspan="2">Revision Details - ${revision.label}</th></tr>
          <tr><td><b>File Name</b></td><td>${revision.fileName}</td></tr>
          <tr><td><b>Uploaded At</b></td><td>${new Date(revision.uploadedAt).toLocaleString()}</td></tr>
          <tr><td><b>Total Comments</b></td><td>${comments.length}</td></tr>
          <tr><td><b>Open Comments</b></td><td class="status-open">${openCount}</td></tr>
          <tr><td><b>Closed Comments</b></td><td class="status-closed">${closedCount}</td></tr>
        </table>
        <br/>
        
        <!-- Comments for this revision -->
        <table>
          <tr class="section-header"><th colspan="8">Comments - ${revision.label} (${comments.length} Total)</th></tr>
          <tr>
            <th>Page</th>
            <th>Reviewer</th>
            <th>Comment</th>
            <th>Type</th>
            <th>Discipline</th>
            <th>Drawing Ref</th>
            <th>Status</th>
            <th>Serial #</th>
          </tr>
          ${comments.length > 0 ? comments.map((comment, idx) => {
            const status = (comment.status || 'open').toLowerCase();
            const statusClass = status === 'open' ? 'status-open' : 'status-closed';
            return `
            <tr>
              <td>${comment.page_number || 'N/A'}</td>
              <td>${comment.reviewer_name || 'Not Provided'}</td>
              <td>${comment.comment_text || comment.text || 'N/A'}</td>
              <td>${comment.comment_type || comment.type || 'GENERAL'}</td>
              <td>${comment.discipline || 'Not Provided'}</td>
              <td>${comment.drawing_ref || 'N/A'}</td>
              <td class="${statusClass}">${status.toUpperCase()}</td>
              <td>${comment.serial_number || idx + 1}</td>
            </tr>
          `}).join('') : '<tr><td colspan="8" style="text-align: center; font-style: italic;">No comments found for this revision</td></tr>'}
        </table>
        
        <br/>
        <p style="font-size: 12px; color: #666;">
          <b>Legend:</b><br/>
          🔴 Open = Comment requires action<br/>
          ✅ Closed = Comment resolved<br/>
        </p>
      </body>
      </html>
    `;
  };

  // Smart preview table component
  const PreviewTable = () => {
    if (!showPreview || uploadedRevisions.length === 0) return null;

    return (
      <Card sx={{ mt: 3, mb: 3 }}>
        <CardContent>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <TableIcon sx={{ mr: 1, color: 'primary.main' }} />
            <Typography variant="h6">Preview: All Revisions & Comments</Typography>
            <Box sx={{ flexGrow: 1 }} />
            <Button
              variant="contained"
              color="success"
              startIcon={<DownloadIcon />}
              onClick={handleDownloadExcel}
              disabled={loading}
              sx={{ mr: 1 }}
            >
              Download All (Combined)
            </Button>
          </Box>

          <Divider sx={{ mb: 2 }} />

          {/* Chain Info */}
          <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
            Chain Information
          </Typography>
          <TableContainer component={Paper} sx={{ mb: 3, maxHeight: 200 }}>
            <Table size="small">
              <TableBody>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold', width: '30%' }}>Chain ID</TableCell>
                  <TableCell>{createdChain?.chain_id}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold' }}>Document Title</TableCell>
                  <TableCell>{createdChain?.document_title}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold' }}>Project</TableCell>
                  <TableCell>{createdChain?.project_name}</TableCell>
                </TableRow>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold' }}>Total Revisions</TableCell>
                  <TableCell>{uploadedRevisions.length}</TableCell>
                </TableRow>
              </TableBody>
            </Table>
          </TableContainer>

          {/* Revisions Summary with Individual Downloads */}
          <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
            Revisions Summary
          </Typography>
          <TableContainer component={Paper} sx={{ mb: 3, maxHeight: 300 }}>
            <Table size="small" stickyHeader>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#2196F3', color: 'white' }}>Revision</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#2196F3', color: 'white' }}>File Name</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#2196F3', color: 'white' }}>Comments</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#2196F3', color: 'white' }}>Status</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#2196F3', color: 'white' }} align="center">Download</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {uploadedRevisions.map((rev, idx) => (
                  <TableRow key={idx}>
                    <TableCell>{rev.label}</TableCell>
                    <TableCell>{rev.fileName}</TableCell>
                    <TableCell>
                      <Chip 
                        label={rev.data?.extraction_summary?.total_comments || 0}
                        color="primary"
                        size="small"
                      />
                    </TableCell>
                    <TableCell>
                      <Chip 
                        label={rev.data?.revision?.status || 'N/A'}
                        color="success"
                        size="small"
                      />
                    </TableCell>
                    <TableCell align="center">
                      <Tooltip title={rev.data?.revision?.excel_download_url ? "Download from S3 (instant)" : "Generate Excel"}>
                        <IconButton
                          color={rev.data?.revision?.excel_download_url ? "success" : "primary"}
                          size="small"
                          onClick={() => handleDownloadFromS3(idx)}
                          disabled={loading}
                        >
                          {rev.data?.revision?.excel_download_url ? 
                            <CloudDownloadIcon fontSize="small" /> : 
                            <DownloadIcon fontSize="small" />
                          }
                        </IconButton>
                      </Tooltip>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>

          {/* Comments Detail (if available) */}
          <Typography variant="subtitle1" gutterBottom sx={{ fontWeight: 'bold' }}>
            All Comments Across Revisions
          </Typography>
          <TableContainer component={Paper} sx={{ maxHeight: 400 }}>
            <Table size="small" stickyHeader>
              <TableHead>
                <TableRow>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white' }}>Revision</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white' }}>Page</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white' }}>Reviewer</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white', minWidth: 300 }}>Comment</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white' }}>Type</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white' }}>Discipline</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white' }}>Drawing Ref</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white' }}>Status</TableCell>
                  <TableCell sx={{ fontWeight: 'bold', bgcolor: '#4CAF50', color: 'white' }}>Action</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {uploadedRevisions.map((rev, revIdx) => {
                  // Smart comment extraction: try multiple paths
                  const comments = rev.comments || rev.data?.comments || rev.data?.document_details?.recent_activities || [];
                  
                  console.log(`[CRS Debug] Revision ${revIdx}:`, {
                    label: rev.label,
                    number: rev.number,
                    commentsCount: comments.length,
                    comments: comments
                  });
                  
                  // Create array to hold all rows for this revision
                  const revisionRows = [];
                  
                  // Add revision header separator row (only if not first revision)
                  if (revIdx > 0) {
                    revisionRows.push(
                      <TableRow key={`separator-${rev.number}`}>
                        <TableCell colSpan={9} sx={{ 
                          bgcolor: '#E0E0E0', 
                          height: '8px', 
                          padding: 0,
                          borderTop: '2px solid #9E9E9E'
                        }} />
                      </TableRow>
                    );
                  }
                  
                  // Add revision section header
                  revisionRows.push(
                    <TableRow key={`header-${rev.number}`}>
                      <TableCell colSpan={9} sx={{ 
                        bgcolor: '#2196F3',
                        color: 'white',
                        fontWeight: 'bold',
                        fontSize: '1rem',
                        py: 1.5
                      }}>
                        📄 {rev.label || `Revision ${rev.number}`} - {comments.length} Comment{comments.length !== 1 ? 's' : ''}
                      </TableCell>
                    </TableRow>
                  );
                  
                  if (comments.length > 0) {
                    comments.forEach((comment, idx) => {
                      const commentId = comment.id || comment.comment_id;
                      const commentStatus = comment.status || 'open';
                      const isOpen = commentStatus.toLowerCase() === 'open';
                      
                      console.log(`[CRS Debug] Comment ${idx}:`, {
                        commentId,
                        commentStatus,
                        isOpen,
                        hasId: !!commentId,
                        comment
                      });
                      
                      revisionRows.push(
                        <TableRow key={`${rev.number}-comment-${idx}`} sx={{
                          bgcolor: isOpen ? '#FFF3E0' : 'inherit',
                          '&:hover': { bgcolor: isOpen ? '#FFE0B2' : '#F5F5F5' }
                        }}>
                          <TableCell>
                            <Chip 
                              label={rev.label || `Rev ${rev.number}`}
                              size="small"
                              color={isOpen ? 'warning' : 'success'}
                              variant="outlined"
                            />
                          </TableCell>
                          <TableCell>{comment.page_number || 'N/A'}</TableCell>
                          <TableCell>{comment.reviewer_name || 'Not Provided'}</TableCell>
                          <TableCell sx={{ wordBreak: 'break-word' }}>{comment.comment_text || comment.text || 'N/A'}</TableCell>
                          <TableCell>
                            <Chip 
                              label={comment.comment_type || comment.type || 'General'}
                              size="small"
                              color={comment.comment_type?.includes('RED') || comment.type?.includes('RED') ? 'error' : 'warning'}
                            />
                          </TableCell>
                          <TableCell>{comment.discipline || 'Not Provided'}</TableCell>
                          <TableCell>{comment.drawing_ref || 'N/A'}</TableCell>
                          <TableCell>
                            <FormControl size="small" fullWidth>
                              <Select
                                value={commentStatus.toLowerCase()}
                                onChange={(e) => {
                                  console.log('[CRS] Status change:', { commentId, newStatus: e.target.value });
                                  handleStatusChange(
                                    commentId, 
                                    e.target.value, 
                                    rev.label || `Rev ${rev.number}`, 
                                    comment.comment_text || comment.text
                                  );
                                }}
                                disabled={loading || !commentId}
                                sx={{
                                  minWidth: 120,
                                  bgcolor: commentStatus.toLowerCase() === 'open' ? '#FFEBEE' : 
                                           commentStatus.toLowerCase() === 'closed' ? '#E8F5E9' :
                                           commentStatus.toLowerCase() === 'in_progress' ? '#FFF3E0' :
                                           commentStatus.toLowerCase() === 'resolved' ? '#E3F2FD' : '#F3E5F5',
                                  fontWeight: 'bold',
                                  fontSize: '0.875rem'
                                }}
                              >
                                <MenuItem value="open">🔴 Open</MenuItem>
                                <MenuItem value="in_progress">🟡 In Progress</MenuItem>
                                <MenuItem value="resolved">🟢 Resolved</MenuItem>
                                <MenuItem value="closed">✅ Closed</MenuItem>
                                <MenuItem value="rejected">❌ Rejected</MenuItem>
                              </Select>
                            </FormControl>
                          </TableCell>
                          <TableCell>
                            {commentId ? (
                              <Button
                                size="small"
                                variant="contained"
                                color="success"
                                onClick={() => {
                                  console.log('[CRS] Close button clicked:', { commentId, revLabel: rev.label, comment });
                                  handleCloseComment(commentId, rev.label || `Rev ${rev.number}`, comment.comment_text || comment.text);
                                }}
                                disabled={loading || commentStatus.toLowerCase() === 'closed'}
                                sx={{ minWidth: 80 }}
                              >
                                {commentStatus.toLowerCase() === 'closed' ? '✓ Closed' : 'Close'}
                              </Button>
                            ) : (
                              <Typography variant="caption" color="text.secondary">
                                No ID
                              </Typography>
                            )}
                          </TableCell>
                        </TableRow>
                      );
                    });
                  } else {
                    // No comments for this revision
                    revisionRows.push(
                      <TableRow key={`${rev.number}-empty`}>
                        <TableCell colSpan={9} align="center" sx={{ 
                          fontStyle: 'italic', 
                          color: 'text.secondary',
                          py: 2,
                          bgcolor: '#FAFAFA'
                        }}>
                          No comments found for {rev.label}
                        </TableCell>
                      </TableRow>
                    );
                  }
                  
                  return revisionRows;
                })}
                {uploadedRevisions.length === 0 && (
                  <TableRow>
                    <TableCell colSpan={9} align="center" sx={{ fontStyle: 'italic', color: 'text.secondary' }}>
                      No revisions uploaded yet
                    </TableCell>
                  </TableRow>
                )}
              </TableBody>
            </Table>
          </TableContainer>
        </CardContent>
      </Card>
    );
  };

  return (
    <Box sx={{ pt: 6, px: 4, pb: 4, minHeight: "100vh" }}>
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 2 }}>
        <Typography variant="h4">
          CRS Multi-Revision Workflow (Smart Version)
        </Typography>
        <PageControlButtons controls={pageControls} />
      </Box>

      {/* Stepper */}
      <Stepper activeStep={currentStep} sx={{ mb: 4 }}>
        <Step><StepLabel>Create Chain</StepLabel></Step>
        <Step><StepLabel>Upload Revisions</StepLabel></Step>
        <Step><StepLabel>Complete</StepLabel></Step>
      </Stepper>

      {/* Error/Success Messages */}
      {error && <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess(null)}>{success}</Alert>}

      {/* STEP 0: Create Chain */}
      {currentStep === 0 && (
        <Card>
          <CardContent>
            <Typography variant="h6" gutterBottom>Step 1: Create Revision Chain</Typography>
            <form onSubmit={handleCreateChain}>
              <Grid container spacing={2}>
                <Grid item xs={12} md={6}>
                  <Box sx={{ display: 'flex', gap: 1, alignItems: 'flex-start' }}>
                    <TextField
                      fullWidth
                      label="Chain ID *"
                      value={chainForm.chain_id}
                      onChange={(e) => setChainForm({...chainForm, chain_id: e.target.value})}
                      required
                      helperText="Unique identifier for this revision chain"
                    />
                    <Button
                      variant="outlined"
                      onClick={handleAutoGenerateChainId}
                      sx={{ mt: 0.5, minWidth: '120px', whiteSpace: 'nowrap' }}
                      disabled={loading}
                    >
                      Auto-Generate
                    </Button>
                  </Box>
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Document Title *"
                    value={chainForm.document_title}
                    onChange={(e) => setChainForm({...chainForm, document_title: e.target.value})}
                    required
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Document Number *"
                    value={chainForm.document_number}
                    onChange={(e) => setChainForm({...chainForm, document_number: e.target.value})}
                    required
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Project Name *"
                    value={chainForm.project_name}
                    onChange={(e) => setChainForm({...chainForm, project_name: e.target.value})}
                    required
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Contractor Name"
                    value={chainForm.contractor_name}
                    onChange={(e) => setChainForm({...chainForm, contractor_name: e.target.value})}
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    label="Department"
                    value={chainForm.department}
                    onChange={(e) => setChainForm({...chainForm, department: e.target.value})}
                  />
                </Grid>
                <Grid item xs={12} md={6}>
                  <TextField
                    fullWidth
                    type="number"
                    label="Maximum Revisions *"
                    value={chainForm.max_allowed_revisions}
                    onChange={(e) => setChainForm({...chainForm, max_allowed_revisions: parseInt(e.target.value) || 10})}
                    inputProps={{ min: 1, max: 50 }}
                    helperText="You can finish early, this is just the maximum"
                    required
                  />
                </Grid>
                <Grid item xs={12}>
                  <TextField
                    fullWidth
                    multiline
                    rows={2}
                    label="Notes"
                    value={chainForm.notes}
                    onChange={(e) => setChainForm({...chainForm, notes: e.target.value})}
                  />
                </Grid>
                <Grid item xs={12}>
                  <Button
                    type="submit"
                    variant="contained"
                    color="primary"
                    size="large"
                    disabled={loading}
                    fullWidth
                  >
                    {loading ? <CircularProgress size={24} /> : 'Create Chain'}
                  </Button>
                </Grid>
              </Grid>
            </form>
          </CardContent>
        </Card>
      )}

      {/* STEP 1: Upload Revisions */}
      {currentStep === 1 && (
        <Box>
          <Card sx={{ mb: 3 }}>
            <CardContent>
              <Typography variant="h6" gutterBottom>
                Chain: {createdChain?.chain_id} - Upload Revisions
              </Typography>

              {/* Debug Info: Show open comment count */}
              {uploadedRevisions.length > 0 && (() => {
                const allComments = uploadedRevisions.flatMap(r => r.comments || []);
                const openCount = allComments.filter(c => (c.status || 'open').toLowerCase() === 'open').length;
                const closedCount = allComments.filter(c => (c.status || 'open').toLowerCase() === 'closed').length;
                return (
                  <Alert severity="info" sx={{ mb: 2 }}>
                    <strong>📊 Comment Status:</strong> {openCount} Open | {closedCount} Closed | {allComments.length} Total
                  </Alert>
                );
              })()}

              {/* Warning: Open Comments from Previous Revisions */}
              {uploadedRevisions.length > 0 && (() => {
                const hasOpen = checkForOpenComments();
                console.log('[CRS] Upload button check:', { 
                  uploadedRevisionsCount: uploadedRevisions.length,
                  currentRevisionNumber,
                  hasOpenComments: hasOpen 
                });
                return hasOpen;
              })() && (
                <Alert severity="warning" sx={{ mb: 2 }}>
                  <strong>⚠️ Cannot Upload Next Revision!</strong>
                  <br />
                  You have open comments from previous revisions. 
                  Please close all comments before uploading <strong>Rev {currentRevisionNumber}</strong>.
                  <br />
                  <Typography variant="caption" sx={{ mt: 1, display: 'block' }}>
                    💡 Scroll down to the "All Comments Across Revisions" table and change the "Status" dropdown from "Open" to "Closed" for each comment.
                  </Typography>
                </Alert>
              )}
              
              <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap', mb: 3 }}>
                {Array.from({ length: createdChain?.max_allowed_revisions || 5 }).map((_, idx) => {
                  const isNextRevision = idx === currentRevisionNumber - 1;
                  const hasOpenPrevComments = isNextRevision && uploadedRevisions.length > 0 && checkForOpenComments();
                  
                  return (
                    <Button
                      key={idx}
                      variant={idx < currentRevisionNumber - 1 ? "outlined" : idx === currentRevisionNumber - 1 ? "contained" : "text"}
                      color={idx < currentRevisionNumber - 1 ? "success" : "primary"}
                      startIcon={idx < currentRevisionNumber - 1 ? <CheckIcon /> : <UploadIcon />}
                      component="label"
                      disabled={idx !== currentRevisionNumber - 1 || loading || hasOpenPrevComments}
                      sx={{ minWidth: 150 }}
                      title={hasOpenPrevComments ? "Close all previous comments before uploading this revision" : ""}
                    >
                      Rev {idx + 1} {idx < currentRevisionNumber - 1 ? "✓" : ""}
                      <input
                        type="file"
                        accept={CONFIG.ACCEPTED_FILE_TYPE}
                        hidden
                        onChange={handleUploadRevision}
                        disabled={idx !== currentRevisionNumber - 1 || hasOpenPrevComments}
                      />
                    </Button>
                  );
                })}
              </Box>

              {loading && (
                <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                  <CircularProgress size={24} />
                  <Typography>Processing PDF and extracting comments...</Typography>
                </Box>
              )}

              {uploadedRevisions.length > 0 && (
                <Box sx={{ mt: 3 }}>
                  <Typography variant="subtitle1" gutterBottom>Uploaded Revisions:</Typography>
                  <List>
                    {uploadedRevisions.map((rev, idx) => (
                      <ListItem key={idx}>
                        <ListItemText
                          primary={`${rev.label}: ${rev.fileName}`}
                          secondary={`${rev.data?.extraction_summary?.total_comments || 0} comments extracted`}
                        />
                        <Chip label={rev.data?.revision?.status || 'Submitted'} color="success" />
                      </ListItem>
                    ))}
                  </List>
                </Box>
              )}

              <Divider sx={{ my: 3 }} />

              <Box sx={{ display: 'flex', gap: 2, flexWrap: 'wrap' }}>
                <Button
                  variant="outlined"
                  onClick={() => setShowPreview(!showPreview)}
                  startIcon={<PreviewIcon />}
                  disabled={uploadedRevisions.length === 0}
                >
                  {showPreview ? 'Hide' : 'Show'} Preview
                </Button>
                <Button
                  variant="contained"
                  color="success"
                  startIcon={<DownloadIcon />}
                  onClick={handleDownloadExcel}
                  disabled={uploadedRevisions.length === 0 || loading}
                >
                  Download Excel
                </Button>
                <Box sx={{ flexGrow: 1 }} />
                <Button
                  variant="outlined"
                  color="warning"
                  startIcon={<CheckIcon />}
                  onClick={() => setCurrentStep(2)}
                  disabled={uploadedRevisions.length === 0}
                >
                  Finish Early ({uploadedRevisions.length} of {createdChain?.max_allowed_revisions})
                </Button>
                <Button
                  variant="contained"
                  onClick={() => setCurrentStep(2)}
                  disabled={uploadedRevisions.length === 0}
                >
                  Complete All Revisions
                </Button>
              </Box>
            </CardContent>
          </Card>

          {/* SMART PREVIEW TABLE */}
          <PreviewTable />
        </Box>
      )}

      {/* STEP 2: Complete */}
      {currentStep === 2 && (
        <Card>
          <CardContent>
            <Box sx={{ textAlign: 'center', py: 4 }}>
              <CheckIcon sx={{ fontSize: 80, color: 'success.main', mb: 2 }} />
              <Typography variant="h5" gutterBottom>
                Multi-Revision Workflow Complete!
              </Typography>
              <Typography variant="body1" color="text.secondary" gutterBottom>
                Chain: {createdChain?.chain_id} | Revisions: {uploadedRevisions.length}
              </Typography>
              <Box sx={{ mt: 4, display: 'flex', gap: 2, justifyContent: 'center' }}>
                <Button
                  variant="contained"
                  color="success"
                  startIcon={<DownloadIcon />}
                  onClick={handleDownloadExcel}
                  disabled={loading}
                >
                  Download Excel Report
                </Button>
                <Button
                  variant="outlined"
                  onClick={() => {
                    setCurrentStep(0);
                    setCreatedChain(null);
                    setUploadedRevisions([]);
                    setCurrentRevisionNumber(1);
                    setShowPreview(false);
                  }}
                >
                  Start New Chain
                </Button>
              </Box>
            </Box>
          </CardContent>
        </Card>
      )}
    </Box>
  );
};

export default withDashboardControls(CRSMultiRevisionSmart);

import { radaiAlert } from '../services/radaiDialog'
/**
 * CRS Multi-Revision Management Component
 * Allows creating chains and uploading multiple revisions with automatic extraction
 */

import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Button, 
  Card, 
  CardContent, 
  TextField, 
  Typography, 
  Grid, 
  Dialog, 
  DialogTitle, 
  DialogContent, 
  DialogActions,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Paper,
  Chip,
  IconButton,
  Alert,
  CircularProgress,
  Tabs,
  Tab,
  Accordion,
  AccordionSummary,
  AccordionDetails,
  List,
  ListItem,
  ListItemText,
  Divider,
  Tooltip
} from '@mui/material';
import {
  Add as AddIcon,
  UploadFile as UploadIcon,
  Download as DownloadIcon,
  Visibility as ViewIcon,
  ExpandMore as ExpandMoreIcon,
  Description as DescriptionIcon,
  Timeline as TimelineIcon,
  Link as LinkIcon
} from '@mui/icons-material';

const API_BASE_URL = 'http://localhost:8000/api/v1';

const CRSMultiRevision = () => {
  const [chains, setChains] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showCreateDialog, setShowCreateDialog] = useState(false);
  const [showUploadDialog, setShowUploadDialog] = useState(false);
  const [selectedChain, setSelectedChain] = useState(null);
  const [tabValue, setTabValue] = useState(0);

  // Form states
  const [chainForm, setChainForm] = useState({
    document_title: '',
    document_number: '',
    project_name: '',
    description: ''
  });

  const [uploadForm, setUploadForm] = useState({
    file: null,
    files: [],  // Multiple files for batch upload
    revision_label: '',
    parent_revision_id: '',
    notes: '',
    project_name: '',
    document_number: '',
    contractor: '',
    department: '',
    auto_sequence: false,  // Enable auto-sequencing
    target_revision_count: 1  // How many revisions to upload
  });

  const [uploadResult, setUploadResult] = useState(null);
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState(null);
  const [batchProgress, setBatchProgress] = useState(null);  // Track batch upload progress

  useEffect(() => {
    loadChains();
  }, []);

  const getAuthHeaders = () => {
    // Try multiple token storage keys (soft coding)
    const token = localStorage.getItem('radai_access_token') || 
                  localStorage.getItem('access_token') || 
                  localStorage.getItem('access');
    
    if (!token) {
      console.warn('No authentication token found');
    }
    
    return {
      'Authorization': `Bearer ${token}`
    };
  };

  const loadChains = async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_BASE_URL}/crs/revision-chains/`, {
        headers: getAuthHeaders()
      });
      
      if (response.ok) {
        const data = await response.json();
        setChains(Array.isArray(data) ? data : data.results || []);
      }
    } catch (error) {
      console.error('Error loading chains:', error);
      setError('Failed to load revision chains');
    } finally {
      setLoading(false);
    }
  };

  const handleCreateChain = async (e) => {
    e.preventDefault();
    setProcessing(true);
    setError(null);

    try {
      const response = await fetch(`${API_BASE_URL}/crs/revision-chains/`, {
        method: 'POST',
        headers: {
          ...getAuthHeaders(),
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(chainForm)
      });

      if (response.ok) {
        const data = await response.json();
        setChains([data, ...chains]);
        setShowCreateDialog(false);
        setChainForm({
          document_title: '',
          document_number: '',
          project_name: '',
          description: ''
        });
        await radaiAlert('Revision chain created successfully!');
      } else {
        const error = await response.json();
        setError(error.detail || 'Failed to create chain');
      }
    } catch (error) {
      console.error('Error creating chain:', error);
      setError('Failed to create chain');
    } finally {
      setProcessing(false);
    }
  };

  const handleUploadRevision = async (e) => {
    e.preventDefault();
    
    // Validation for batch vs single upload
    if (uploadForm.auto_sequence) {
      if (!uploadForm.files || uploadForm.files.length === 0) {
        setError('Please select PDF files for batch upload');
        return;
      }
      // Check if all slots have files
      const missingFiles = uploadForm.files.filter(f => !f).length;
      if (missingFiles > 0) {
        setError(`Please upload files for all ${uploadForm.target_revision_count} revisions. ${missingFiles} file(s) missing.`);
        return;
      }
      await handleBatchUpload();
      return;
    }
    
    // Single upload validation
    if (!uploadForm.file) {
      setError('Please select a PDF file');
      return;
    }

    if (!uploadForm.revision_label) {
      setError('Please enter a revision label');
      return;
    }

    // Single upload
    setProcessing(true);
    setError(null);
    setUploadResult(null);
    
    try {
      await uploadSingleRevision(uploadForm.file, uploadForm.revision_label, uploadForm.parent_revision_id);
    } catch (error) {
      setError(error.message);
    } finally {
      setProcessing(false);
    }
  };

  // Smart batch upload: automatically creates sequential revisions
  const handleBatchUpload = async () => {
    setProcessing(true);
    setError(null);
    setUploadResult(null);

    // Validate files
    if (!uploadForm.files || uploadForm.files.length === 0) {
      setError('Please select PDF files for each revision');
      setProcessing(false);
      return;
    }

    const actualCount = uploadForm.files.length;
    setBatchProgress({ current: 0, total: actualCount, results: [] });

    try {
      let lastRevisionId = uploadForm.parent_revision_id || null;
      const results = [];

      for (let i = 0; i < actualCount; i++) {
        const revisionNumber = i + 1;
        const file = uploadForm.files[i];
        
        // Generate smart revision label (Rev 1, Rev 2, etc.)
        const revisionLabel = uploadForm.revision_label 
          ? `${uploadForm.revision_label} ${revisionNumber}` 
          : `Rev ${revisionNumber}`;

        setBatchProgress({ 
          current: revisionNumber, 
          total: actualCount, 
          results,
          currentLabel: revisionLabel,
          currentFile: file.name
        });

        try {
          const result = await uploadSingleRevision(
            file, 
            revisionLabel, 
            lastRevisionId,
            `Batch upload ${revisionNumber}/${actualCount} - File: ${file.name}`
          );

          if (result && result.revision) {
            lastRevisionId = result.revision.id;  // Link next revision to this one
            results.push({ success: true, label: revisionLabel, fileName: file.name, data: result });
          } else {
            results.push({ success: false, label: revisionLabel, fileName: file.name, error: 'No revision data returned' });
          }
        } catch (err) {
          results.push({ success: false, label: revisionLabel, fileName: file.name, error: err.message });
        }
      }

      setBatchProgress({ ...batchProgress, results, completed: true });
      setUploadResult({ 
        batch: true, 
        results, 
        message: `Successfully uploaded ${results.filter(r => r.success).length}/${actualCount} revisions` 
      });

      // Refresh chain data
      await loadChainDetails(selectedChain.id);

      // Reset form
      setUploadForm({
        ...uploadForm,
        files: [],
        file: null,
        auto_sequence: false
      });

      // Reset file input
      const fileInput = document.getElementById('upload-file-input');
      if (fileInput) fileInput.value = '';

    } catch (error) {
      console.error('Batch upload error:', error);
      setError('Batch upload failed: ' + error.message);
    } finally {
      setProcessing(false);
    }
  };

  // Single revision upload helper
  const uploadSingleRevision = async (file, revisionLabel, parentRevisionId = null, additionalNotes = '') => {
    const formData = new FormData();
    formData.append('file', file);
    formData.append('revision_label', revisionLabel);
    
    if (parentRevisionId) {
      formData.append('parent_revision_id', parentRevisionId);
    }
    
    const notes = [uploadForm.notes, additionalNotes].filter(Boolean).join('; ');
    if (notes) {
      formData.append('notes', notes);
    }
    if (uploadForm.project_name) {
      formData.append('project_name', uploadForm.project_name);
    }
    if (uploadForm.document_number) {
      formData.append('document_number', uploadForm.document_number);
    }
    if (uploadForm.contractor) {
      formData.append('contractor', uploadForm.contractor);
    }
    if (uploadForm.department) {
      formData.append('department', uploadForm.department);
    }

    const response = await fetch(
      `${API_BASE_URL}/crs/revision-chains/${selectedChain.id}/upload_and_add_revision/`,
      {
        method: 'POST',
        headers: getAuthHeaders(),
        body: formData
      }
    );

    if (!response.ok) {
      const error = await response.json();
      throw new Error(error.error || error.detail || 'Upload failed');
    }

    const data = await response.json();
    
    // If single upload (not batch), show result and reset form
    if (!uploadForm.auto_sequence || uploadForm.target_revision_count === 1) {
      setUploadResult(data);
      
      // Refresh chain data
      await loadChainDetails(selectedChain.id);
      
      // Reset form
      setUploadForm({
        file: null,
        revision_label: '',
        parent_revision_id: '',
        notes: '',
        project_name: uploadForm.project_name,
        document_number: uploadForm.document_number,
        contractor: '',
        department: '',
        auto_sequence: false,
        target_revision_count: 1
      });
      
      // Reset file input
      const fileInput = document.getElementById('upload-file-input');
      if (fileInput) fileInput.value = '';
    }

    return data;
  };

  const loadChainDetails = async (chainId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/crs/revision-chains/${chainId}/`, {
        headers: getAuthHeaders()
      });
      
      if (response.ok) {
        const data = await response.json();
        setSelectedChain(data);
        
        // Update in chains list
        setChains(chains.map(c => c.id === chainId ? data : c));
      }
    } catch (error) {
      console.error('Error loading chain details:', error);
    }
  };

  const handleDownloadExcel = async (chainId) => {
    try {
      const response = await fetch(
        `${API_BASE_URL}/crs/revision-chains/${chainId}/export_excel/`,
        {
          headers: getAuthHeaders()
        }
      );

      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CRS_Chain_${chainId}_Export.xlsx`;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
      }
    } catch (error) {
      console.error('Error downloading Excel:', error);
      setError('Failed to download Excel');
    }
  };

  const openUploadDialog = (chain) => {
    setSelectedChain(chain);
    setUploadForm({
      ...uploadForm,
      project_name: chain.project_name,
      document_number: chain.document_number
    });
    setShowUploadDialog(true);
    setUploadResult(null);
    setError(null);
  };

  const getStatusColor = (status) => {
    const colors = {
      'active': 'success',
      'completed': 'info',
      'on_hold': 'warning',
      'cancelled': 'error'
    };
    return colors[status] || 'default';
  };

  const getRiskColor = (risk) => {
    const colors = {
      'low': 'success',
      'medium': 'warning',
      'high': 'error',
      'critical': 'error'
    };
    return colors[risk] || 'default';
  };

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h4">
          CRS Multi-Revision Management
        </Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => setShowCreateDialog(true)}
        >
          Create Revision Chain
        </Button>
      </Box>

      {/* Error Alert */}
      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {/* Tabs */}
      <Tabs value={tabValue} onChange={(e, newValue) => setTabValue(newValue)} sx={{ mb: 2 }}>
        <Tab label="Revision Chains" />
        <Tab label="Statistics" />
      </Tabs>

      {/* Tab Panels */}
      {tabValue === 0 && (
        <Grid container spacing={3}>
          {loading ? (
            <Box sx={{ display: 'flex', justifyContent: 'center', width: '100%', p: 5 }}>
              <CircularProgress />
            </Box>
          ) : chains.length === 0 ? (
            <Grid item xs={12}>
              <Card>
                <CardContent sx={{ textAlign: 'center', py: 5 }}>
                  <DescriptionIcon sx={{ fontSize: 60, color: 'text.secondary', mb: 2 }} />
                  <Typography variant="h6" color="text.secondary">
                    No Revision Chains Yet
                  </Typography>
                  <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                    Create your first revision chain to start tracking document revisions
                  </Typography>
                  <Button
                    variant="contained"
                    startIcon={<AddIcon />}
                    onClick={() => setShowCreateDialog(true)}
                    sx={{ mt: 2 }}
                  >
                    Create Chain
                  </Button>
                </CardContent>
              </Card>
            </Grid>
          ) : (
            chains.map((chain) => (
              <Grid item xs={12} md={6} lg={4} key={chain.id}>
                <Card>
                  <CardContent>
                    <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
                      <Typography variant="h6" noWrap>
                        {chain.document_title}
                      </Typography>
                      <Chip 
                        label={chain.status} 
                        color={getStatusColor(chain.status)} 
                        size="small" 
                      />
                    </Box>
                    
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                      <strong>Document #:</strong> {chain.document_number}
                    </Typography>
                    <Typography variant="body2" color="text.secondary" gutterBottom>
                      <strong>Project:</strong> {chain.project_name}
                    </Typography>
                    
                    <Divider sx={{ my: 2 }} />
                    
                    <Grid container spacing={2}>
                      <Grid item xs={6}>
                        <Typography variant="caption" color="text.secondary">
                          Revisions
                        </Typography>
                        <Typography variant="h6">
                          {chain.total_revisions}
                        </Typography>
                      </Grid>
                      <Grid item xs={6}>
                        <Typography variant="caption" color="text.secondary">
                          Total Comments
                        </Typography>
                        <Typography variant="h6">
                          {chain.total_comments_across_revisions || 0}
                        </Typography>
                      </Grid>
                      {chain.risk_level && (
                        <Grid item xs={12}>
                          <Chip 
                            label={`Risk: ${chain.risk_level}`} 
                            color={getRiskColor(chain.risk_level)} 
                            size="small"
                            sx={{ mt: 1 }}
                          />
                        </Grid>
                      )}
                    </Grid>
                    
                    <Box sx={{ mt: 2, display: 'flex', gap: 1 }}>
                      <Button
                        variant="contained"
                        startIcon={<UploadIcon />}
                        onClick={() => openUploadDialog(chain)}
                        fullWidth
                      >
                        Upload Revision
                      </Button>
                      <Tooltip title="Download Excel">
                        <IconButton
                          color="primary"
                          onClick={() => handleDownloadExcel(chain.id)}
                        >
                          <DownloadIcon />
                        </IconButton>
                      </Tooltip>
                    </Box>
                    
                    {/* Revisions List */}
                    {chain.revisions && chain.revisions.length > 0 && (
                      <Accordion sx={{ mt: 2 }}>
                        <AccordionSummary expandIcon={<ExpandMoreIcon />}>
                          <Typography variant="body2">
                            View Revisions ({chain.revisions.length})
                          </Typography>
                        </AccordionSummary>
                        <AccordionDetails>
                          <List dense>
                            {chain.revisions.map((rev) => (
                              <ListItem key={rev.id}>
                                <ListItemText
                                  primary={rev.revision_label}
                                  secondary={`${rev.total_comments} comments • ${rev.status}`}
                                />
                              </ListItem>
                            ))}
                          </List>
                        </AccordionDetails>
                      </Accordion>
                    )}
                  </CardContent>
                </Card>
              </Grid>
            ))
          )}
        </Grid>
      )}

      {tabValue === 1 && (
        <Card>
          <CardContent>
            <Typography variant="h6">Statistics Coming Soon</Typography>
            <Typography variant="body2" color="text.secondary">
              Dashboard statistics will be available here
            </Typography>
          </CardContent>
        </Card>
      )}

      {/* Create Chain Dialog */}
      <Dialog 
        open={showCreateDialog} 
        onClose={() => !processing && setShowCreateDialog(false)}
        maxWidth="sm"
        fullWidth
      >
        <DialogTitle>Create Revision Chain</DialogTitle>
        <form onSubmit={handleCreateChain}>
          <DialogContent>
            <TextField
              label="Document Title"
              fullWidth
              required
              value={chainForm.document_title}
              onChange={(e) => setChainForm({...chainForm, document_title: e.target.value})}
              sx={{ mb: 2 }}
            />
            <TextField
              label="Document Number"
              fullWidth
              required
              value={chainForm.document_number}
              onChange={(e) => setChainForm({...chainForm, document_number: e.target.value})}
              sx={{ mb: 2 }}
            />
            <TextField
              label="Project Name"
              fullWidth
              required
              value={chainForm.project_name}
              onChange={(e) => setChainForm({...chainForm, project_name: e.target.value})}
              sx={{ mb: 2 }}
            />
            <TextField
              label="Description"
              fullWidth
              multiline
              rows={3}
              value={chainForm.description}
              onChange={(e) => setChainForm({...chainForm, description: e.target.value})}
            />
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setShowCreateDialog(false)} disabled={processing}>
              Cancel
            </Button>
            <Button 
              type="submit" 
              variant="contained" 
              disabled={processing}
              startIcon={processing && <CircularProgress size={20} />}
            >
              {processing ? 'Creating...' : 'Create Chain'}
            </Button>
          </DialogActions>
        </form>
      </Dialog>

      {/* Upload Revision Dialog */}
      <Dialog 
        open={showUploadDialog} 
        onClose={() => !processing && setShowUploadDialog(false)}
        maxWidth="md"
        fullWidth
      >
        <DialogTitle>
          Upload Revision to {selectedChain?.document_title}
        </DialogTitle>
        <form onSubmit={handleUploadRevision}>
          <DialogContent>
            {uploadResult && (
              <Alert severity="success" sx={{ mb: 2 }}>
                <Typography variant="subtitle2" gutterBottom>
                  {uploadResult.message}
                </Typography>
                <Typography variant="body2">
                  • Total Comments: {uploadResult.data.extraction_summary.total_comments}
                </Typography>
                <Typography variant="body2">
                  • Red Comments: {uploadResult.data.extraction_summary.red_comments}
                </Typography>
                <Typography variant="body2">
                  • Yellow Boxes: {uploadResult.data.extraction_summary.yellow_boxes}
                </Typography>
                <Typography variant="body2">
                  • Pages: {uploadResult.data.extraction_summary.pages_with_comments}
                </Typography>
              </Alert>
            )}

            <Grid container spacing={2}>
              {/* Single vs Batch Upload Toggle */}
              <Grid item xs={12}>
                <TextField
                  label="Upload Mode"
                  fullWidth
                  select
                  value={uploadForm.auto_sequence ? 'batch' : 'single'}
                  onChange={(e) => {
                    const isBatch = e.target.value === 'batch';
                    setUploadForm({
                      ...uploadForm, 
                      auto_sequence: isBatch,
                      files: isBatch ? [] : uploadForm.files,
                      file: isBatch ? null : uploadForm.file,
                      target_revision_count: isBatch ? 3 : 1
                    });
                  }}
                  SelectProps={{ native: true }}
                  helperText="Choose single or multiple revision upload"
                >
                  <option value="single">Single Revision Upload</option>
                  <option value="batch">Multiple Revisions (Batch)</option>
                </TextField>
              </Grid>

              {/* Single File Upload */}
              {!uploadForm.auto_sequence && (
                <Grid item xs={12}>
                  <Button
                    variant="outlined"
                    component="label"
                    fullWidth
                    startIcon={<UploadIcon />}
                  >
                    {uploadForm.file ? uploadForm.file.name : 'Select PDF File *'}
                    <input
                      type="file"
                      hidden
                      accept=".pdf"
                      onChange={(e) => {
                        const file = e.target.files[0];
                        setUploadForm({...uploadForm, file});
                      }}
                    />
                  </Button>
                </Grid>
              )}

              {/* Batch Upload - Individual File Pickers */}
              {uploadForm.auto_sequence && (
                <>
                  <Grid item xs={12}>
                    <TextField
                      label="Number of Revisions to Upload"
                      fullWidth
                      type="number"
                      value={uploadForm.target_revision_count}
                      onChange={(e) => {
                        const count = parseInt(e.target.value) || 1;
                        const newFiles = [...uploadForm.files];
                        // Adjust array size
                        while (newFiles.length < count) newFiles.push(null);
                        while (newFiles.length > count) newFiles.pop();
                        setUploadForm({...uploadForm, target_revision_count: count, files: newFiles});
                      }}
                      inputProps={{ min: 1, max: 10 }}
                      helperText="How many revisions do you want to create?"
                    />
                  </Grid>

                  {Array.from({ length: uploadForm.target_revision_count }).map((_, idx) => (
                    <Grid item xs={12} key={idx}>
                      <Paper sx={{ p: 2, bgcolor: 'background.default' }}>
                        <Typography variant="subtitle2" gutterBottom>
                          Revision {idx + 1} (Rev {idx + 1})
                        </Typography>
                        <Button
                          variant="outlined"
                          component="label"
                          fullWidth
                          startIcon={<UploadIcon />}
                          color={uploadForm.files[idx] ? "success" : "primary"}
                        >
                          {uploadForm.files[idx] 
                            ? `✓ ${uploadForm.files[idx].name}` 
                            : `Upload CRS Sheet ${idx + 1} *`}
                          <input
                            type="file"
                            hidden
                            accept=".pdf"
                            onChange={(e) => {
                              const file = e.target.files[0];
                              if (file) {
                                const newFiles = [...uploadForm.files];
                                newFiles[idx] = file;
                                setUploadForm({...uploadForm, files: newFiles});
                              }
                            }}
                          />
                        </Button>
                      </Paper>
                    </Grid>
                  ))}

                  <Grid item xs={12}>
                    <Alert severity="info">
                      <Typography variant="body2">
                        <strong>Batch Upload:</strong> Upload {uploadForm.target_revision_count} different PDF files. 
                        Each file will create a separate revision with its own comments extracted.
                      </Typography>
                    </Alert>
                  </Grid>
                </>
              )}

              <Grid item xs={12} md={6}>
                <TextField
                  label="Revision Label *"
                  fullWidth
                  required
                  value={uploadForm.revision_label}
                  onChange={(e) => setUploadForm({...uploadForm, revision_label: e.target.value})}
                  placeholder="e.g., Rev 0, Rev 1, Rev A"
                  helperText="Enter revision identifier"
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  label="Parent Revision ID"
                  fullWidth
                  type="number"
                  value={uploadForm.parent_revision_id}
                  onChange={(e) => setUploadForm({...uploadForm, parent_revision_id: e.target.value})}
                  helperText="Leave empty for first revision"
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  label="Project Name"
                  fullWidth
                  value={uploadForm.project_name}
                  onChange={(e) => setUploadForm({...uploadForm, project_name: e.target.value})}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  label="Document Number"
                  fullWidth
                  value={uploadForm.document_number}
                  onChange={(e) => setUploadForm({...uploadForm, document_number: e.target.value})}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  label="Contractor"
                  fullWidth
                  value={uploadForm.contractor}
                  onChange={(e) => setUploadForm({...uploadForm, contractor: e.target.value})}
                />
              </Grid>

              <Grid item xs={12} md={6}>
                <TextField
                  label="Department"
                  fullWidth
                  value={uploadForm.department}
                  onChange={(e) => setUploadForm({...uploadForm, department: e.target.value})}
                />
              </Grid>

              <Grid item xs={12}>
                <TextField
                  label="Notes"
                  fullWidth
                  multiline
                  rows={3}
                  value={uploadForm.notes}
                  onChange={(e) => setUploadForm({...uploadForm, notes: e.target.value})}
                  placeholder="Enter any notes about this revision..."
                />
              </Grid>
            </Grid>

            <Alert severity="info" sx={{ mt: 2 }}>
              <Typography variant="body2">
                <strong>What happens next:</strong>
              </Typography>
              <Typography variant="body2">
                • PDF will be uploaded and processed automatically
              </Typography>
              <Typography variant="body2">
                • Red text and yellow box comments will be extracted
              </Typography>
              <Typography variant="body2">
                • Comments will be linked to previous revision (if specified)
              </Typography>
              <Typography variant="body2">
                • You'll receive an immediate extraction summary
              </Typography>
            </Alert>
          </DialogContent>
          <DialogActions>
            <Button onClick={() => setShowUploadDialog(false)} disabled={processing}>
              {uploadResult ? 'Close' : 'Cancel'}
            </Button>
            {!uploadResult && (
              <Button 
                type="submit" 
                variant="contained" 
                disabled={processing || !uploadForm.file || !uploadForm.revision_label}
                startIcon={processing && <CircularProgress size={20} />}
              >
                {processing ? 'Uploading & Extracting...' : 'Upload & Extract'}
              </Button>
            )}
          </DialogActions>
        </form>
      </Dialog>
    </Box>
  );
};

export default CRSMultiRevision;

/**
 * CRS Multi-Revision Upload - SIMPLIFIED
 * Large, obvious upload buttons for each revision
 */

import React, { useState, useEffect } from 'react';
import { 
  Box, 
  Button, 
  Card, 
  CardContent, 
  TextField, 
  Typography, 
  Grid, 
  Alert,
  Paper,
  Chip,
  CircularProgress,
  Stack,
  Divider
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  CheckCircle as CheckIcon,
  Download as DownloadIcon,
  Refresh as RefreshIcon
} from '@mui/icons-material';

const CRSMultiRevisionSimple = () => {
  const [chains, setChains] = useState([]);
  const [selectedChain, setSelectedChain] = useState(null);
  const [revisionCount, setRevisionCount] = useState(3);
  const [files, setFiles] = useState({});
  const [loading, setLoading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);

  const API_BASE = '/api/v1';

  // Get auth token
  const getToken = () => {
    return localStorage.getItem('radai_access_token') || 
           localStorage.getItem('access_token') || 
           localStorage.getItem('access');
  };

  const getHeaders = () => ({
    'Authorization': `Bearer ${getToken()}`
  });

  // Load chains on mount
  useEffect(() => {
    loadChains();
  }, []);

  const loadChains = async () => {
    try {
      setLoading(true);
      const response = await fetch(`${API_BASE}/crs/revision-chains/`, {
        headers: getHeaders()
      });
      if (response.ok) {
        const data = await response.json();
        setChains(Array.isArray(data) ? data : data.results || []);
      }
    } catch (err) {
      console.error('Error loading chains:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleFileSelect = (revNumber, file) => {
    setFiles({...files, [revNumber]: file});
    setError(null);
  };

  const handleUpload = async () => {
    if (!selectedChain) {
      setError('Please select a chain first');
      return;
    }

    const fileCount = Object.keys(files).length;
    if (fileCount === 0) {
      setError('Please upload at least one file');
      return;
    }

    setUploading(true);
    setError(null);
    setSuccess(null);

    try {
      let successCount = 0;
      let lastRevisionId = null;

      // Upload each file in sequence
      for (let i = 1; i <= revisionCount; i++) {
        const file = files[i];
        if (!file) continue;

        const formData = new FormData();
        formData.append('file', file);
        formData.append('revision_label', `Rev ${i}`);
        if (lastRevisionId) {
          formData.append('parent_revision_id', lastRevisionId);
        }

        const response = await fetch(
          `${API_BASE}/crs/revision-chains/${selectedChain.id}/upload_and_add_revision/`,
          {
            method: 'POST',
            headers: getHeaders(),
            body: formData
          }
        );

        if (response.ok) {
          const data = await response.json();
          lastRevisionId = data.revision.id;
          successCount++;
        } else {
          console.error(`Failed to upload Rev ${i}`);
        }
      }

      setSuccess(`Successfully uploaded ${successCount} of ${fileCount} revisions!`);
      setFiles({});
      loadChains();
    } catch (err) {
      setError('Upload failed: ' + err.message);
    } finally {
      setUploading(false);
    }
  };

  const handleDownloadExcel = async () => {
    if (!selectedChain) return;
    
    try {
      const response = await fetch(
        `${API_BASE}/crs/revision-chains/${selectedChain.id}/export_excel/`,
        { headers: getHeaders() }
      );
      
      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `CRS_Chain_${selectedChain.chain_id}_Export.xlsx`;
        a.click();
      }
    } catch (err) {
      setError('Failed to download Excel: ' + err.message);
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" gutterBottom>
        📄 CRS Multi-Revision Upload
      </Typography>
      <Typography variant="body2" color="text.secondary" gutterBottom sx={{ mb: 3 }}>
        Upload multiple PDF revisions with individual upload buttons
      </Typography>

      {error && <Alert severity="error" sx={{ mb: 2 }}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }}>{success}</Alert>}

      {/* STEP 1: SELECT CHAIN */}
      <Paper sx={{ p: 3, mb: 3 }}>
        <Typography variant="h6" gutterBottom>
          Step 1: Select Document Chain
        </Typography>
        
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', p: 3 }}>
            <CircularProgress />
          </Box>
        ) : (
          <Grid container spacing={2}>
            {chains.map(chain => (
              <Grid item xs={12} md={6} lg={4} key={chain.id}>
                <Card 
                  sx={{ 
                    cursor: 'pointer',
                    border: selectedChain?.id === chain.id ? '2px solid' : '1px solid',
                    borderColor: selectedChain?.id === chain.id ? 'primary.main' : 'divider',
                    '&:hover': { boxShadow: 3 }
                  }}
                  onClick={() => setSelectedChain(chain)}
                >
                  <CardContent>
                    <Typography variant="h6" noWrap>
                      {chain.document_title || chain.chain_id}
                    </Typography>
                    <Typography variant="body2" color="text.secondary">
                      {chain.document_number || 'No number'}
                    </Typography>
                    <Box sx={{ mt: 1 }}>
                      <Chip label={`${chain.total_revisions || 0} Revisions`} size="small" />
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>
        )}
      </Paper>

      {/* STEP 2: UPLOAD FILES */}
      {selectedChain && (
        <Paper sx={{ p: 3, mb: 3 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <Typography variant="h6" sx={{ flexGrow: 1 }}>
              Step 2: Upload Revision Files
            </Typography>
            <TextField
              type="number"
              label="Number of Revisions"
              value={revisionCount}
              onChange={(e) => setRevisionCount(Math.min(10, Math.max(1, parseInt(e.target.value) || 1)))}
              size="small"
              sx={{ width: 150 }}
              InputProps={{ inputProps: { min: 1, max: 10 } }}
            />
          </Box>

          <Alert severity="info" sx={{ mb: 3 }}>
            Selected: <strong>{selectedChain.document_title || selectedChain.chain_id}</strong>
          </Alert>

          {/* LARGE UPLOAD BUTTONS */}
          <Grid container spacing={3}>
            {Array.from({ length: revisionCount }, (_, i) => i + 1).map(revNum => (
              <Grid item xs={12} md={6} lg={4} key={revNum}>
                <Paper 
                  elevation={files[revNum] ? 0 : 1}
                  sx={{ 
                    p: 3, 
                    textAlign: 'center',
                    bgcolor: files[revNum] ? 'success.light' : 'background.paper',
                    border: files[revNum] ? '2px solid' : '1px dashed',
                    borderColor: files[revNum] ? 'success.main' : 'divider',
                    minHeight: 180
                  }}
                >
                  <Typography variant="h5" gutterBottom fontWeight="bold">
                    Revision {revNum}
                  </Typography>
                  <Typography variant="body2" color="text.secondary" gutterBottom>
                    Rev {revNum}
                  </Typography>

                  {files[revNum] ? (
                    <>
                      <CheckIcon sx={{ fontSize: 48, color: 'success.main', my: 2 }} />
                      <Typography variant="body2" noWrap>
                        {files[revNum].name}
                      </Typography>
                      <Typography variant="caption" color="text.secondary">
                        {(files[revNum].size / 1024 / 1024).toFixed(2)} MB
                      </Typography>
                      <Button
                        size="small"
                        onClick={() => handleFileSelect(revNum, null)}
                        sx={{ mt: 1 }}
                      >
                        Remove
                      </Button>
                    </>
                  ) : (
                    <>
                      <Button
                        variant="contained"
                        component="label"
                        size="large"
                        startIcon={<UploadIcon />}
                        sx={{ mt: 2, mb: 1 }}
                        fullWidth
                      >
                        Upload CRS Sheet {revNum}
                        <input
                          type="file"
                          hidden
                          accept=".pdf"
                          onChange={(e) => {
                            if (e.target.files[0]) {
                              handleFileSelect(revNum, e.target.files[0]);
                            }
                          }}
                        />
                      </Button>
                      <Typography variant="caption" color="text.secondary">
                        PDF files only
                      </Typography>
                    </>
                  )}
                </Paper>
              </Grid>
            ))}
          </Grid>

          {/* UPLOAD ALL BUTTON */}
          <Box sx={{ mt: 4, display: 'flex', gap: 2, justifyContent: 'center' }}>
            <Button
              variant="outlined"
              size="large"
              onClick={() => {
                setFiles({});
                setError(null);
                setSuccess(null);
              }}
              startIcon={<RefreshIcon />}
            >
              Clear All
            </Button>
            <Button
              variant="contained"
              size="large"
              onClick={handleUpload}
              disabled={uploading || Object.keys(files).length === 0}
              startIcon={uploading ? <CircularProgress size={20} /> : <UploadIcon />}
              sx={{ minWidth: 200 }}
            >
              {uploading ? 'Uploading...' : `Upload ${Object.keys(files).length} Files`}
            </Button>
            <Button
              variant="contained"
              color="success"
              size="large"
              onClick={handleDownloadExcel}
              startIcon={<DownloadIcon />}
            >
              Download Excel
            </Button>
          </Box>
        </Paper>
      )}

      {/* No Chain Selected Message */}
      {!selectedChain && !loading && chains.length > 0 && (
        <Alert severity="info">
          👆 Please select a document chain above to start uploading revisions
        </Alert>
      )}
    </Box>
  );
};

export default CRSMultiRevisionSimple;

/**
 * CRS Multi-Revision Workflow
 * Create chain → Upload Rev 1 → Upload Rev 2 → Upload Rev 3...
 */

import React, { useState } from 'react';
import { 
  Box, 
  Button, 
  Card, 
  CardContent, 
  TextField, 
  Typography, 
  Grid, 
  Alert,
  Paper,
  Stepper,
  Step,
  StepLabel,
  CircularProgress,
  Divider,
  List,
  ListItem,
  ListItemText,
  Chip
} from '@mui/material';
import {
  CloudUpload as UploadIcon,
  CheckCircle as CheckIcon,
  Download as DownloadIcon,
  Add as AddIcon,
  NavigateNext as NextIcon
} from '@mui/icons-material';

// Soft-coded configuration
const CONFIG = {
  API_BASE_URL: import.meta.env.VITE_API_URL || '/api/v1',
  TOKEN_KEYS: ['radai_access_token', 'access_token', 'access'],
  MAX_REVISIONS: 10,
  MIN_REVISIONS: 1,
  ACCEPTED_FILE_TYPE: '.pdf'
};

const CRSMultiRevisionWorkflow = () => {
  // Step tracking
  const [currentStep, setCurrentStep] = useState(0); // 0=create chain, 1=upload revisions, 2=complete
  
  // Chain details form
  const [chainForm, setChainForm] = useState({
    chain_id: '',
    document_title: '',
    document_number: '',
    project_name: '',
    contractor_name: '',
    department: '',
    notes: '',
    max_allowed_revisions: 5
  });
  
  // Created chain and revisions
  const [createdChain, setCreatedChain] = useState(null);
  const [currentRevisionNumber, setCurrentRevisionNumber] = useState(1);
  const [uploadedRevisions, setUploadedRevisions] = useState([]);
  const [lastRevisionId, setLastRevisionId] = useState(null);
  
  // UI states
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState(null);

  // Get auth token
  const getAuthHeaders = () => {
    let token = null;
    for (const key of CONFIG.TOKEN_KEYS) {
      token = localStorage.getItem(key);
      if (token) break;
    }
    if (!token) {
      console.warn('[CRS] No token found');
      return {};
    }
    return { 'Authorization': `Bearer ${token}` };
  };

  // STEP 1: Create Chain
  const handleCreateChain = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`${CONFIG.API_BASE_URL}/crs/revision-chains/`, {
        method: 'POST',
        headers: {
          ...getAuthHeaders(),
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(chainForm)
      });

      if (response.ok) {
        const data = await response.json();
        console.log('[CRS] Chain created - Full response:', JSON.stringify(data, null, 2));
        console.log('[CRS] Chain ID field:', data.id);
        console.log('[CRS] Chain PK field:', data.pk);
        console.log('[CRS] All keys:', Object.keys(data));
        setCreatedChain(data);
        setCurrentStep(1);
        setSuccess(`Chain created: ${data.chain_id || data.id}`);
      } else {
        const errData = await response.json().catch(() => ({}));
        console.error('[CRS] Chain creation failed:', response.status, errData);
        setError(`Failed to create chain: ${errData.detail || errData.chain_id?.[0] || response.statusText}`);
      }
    } catch (err) {
      setError(`Error: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // STEP 2: Upload Revision
  const handleUploadRevision = async (file) => {
    if (!file) return;
    
    setLoading(true);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('file', file);
      formData.append('revision_label', `Rev ${currentRevisionNumber}`);
      
      if (lastRevisionId) {
        formData.append('parent_revision_id', lastRevisionId);
      }

      console.log('[CRS] Uploading to chain:', createdChain.id);
      console.log('[CRS] URL:', `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/upload_and_add_revision/`);
      
      const response = await fetch(
        `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/upload_and_add_revision/`,
        {
          method: 'POST',
          headers: getAuthHeaders(),
          body: formData
        }
      );

      if (response.ok) {
        const result = await response.json();
        console.log('[CRS] Upload success - Full response:', JSON.stringify(result, null, 2));
        const data = result.data || result; // Handle both response structures
        console.log('[CRS] Extraction summary:', data.extraction_summary);
        const newRevision = {
          number: currentRevisionNumber,
          label: `Rev ${currentRevisionNumber}`,
          fileName: file.name,
          comments: data.extraction_summary?.total_comments || 0,
          redComments: data.extraction_summary?.red_comments || 0,
          yellowComments: data.extraction_summary?.yellow_comments || 0,
          data: data
        };
        
        setUploadedRevisions([...uploadedRevisions, newRevision]);
        setLastRevisionId(data.revision?.id || null);
        setSuccess(`Rev ${currentRevisionNumber} uploaded! ${newRevision.comments} comments extracted.`);
        
        // Move to next revision or complete
        if (currentRevisionNumber >= chainForm.max_allowed_revisions) {
          setCurrentStep(2);
        } else {
          setCurrentRevisionNumber(currentRevisionNumber + 1);
        }
      } else {
        const errData = await response.json().catch(() => ({}));
        console.error('[CRS] Upload failed:', response.status, errData);
        const errorMsg = errData.details || errData.error || errData.detail || response.statusText;
        setError(`Failed to upload revision: ${errorMsg}`);
      }
    } catch (err) {
      setError(`Error: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  // Download Excel
  const handleDownloadExcel = async () => {
    if (!createdChain) {
      setError('No chain created yet');
      return;
    }
    
    console.log('[CRS] Downloading Excel for chain:', createdChain.id);
    setLoading(true);
    setError(null);
    
    try {
      // Use simple HTML-to-Excel export endpoint
      const url = `${CONFIG.API_BASE_URL}/crs/revision-chains/${createdChain.id}/export_simple/`;
      console.log('[CRS] Excel download URL:', url);
      
      const response = await fetch(url, { 
        headers: getAuthHeaders(),
        method: 'GET'
      });
      
      console.log('[CRS] Excel response status:', response.status);
      
      if (response.ok) {
        const blob = await response.blob();
        console.log('[CRS] Excel blob size:', blob.size);
        
        const downloadUrl = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = downloadUrl;
        a.download = `CRS_${createdChain.chain_id}_Export.xls`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        window.URL.revokeObjectURL(downloadUrl);
        
        setSuccess('Excel downloaded successfully!');
      } else {
        const errorText = await response.text();
        console.error('[CRS] Excel download failed:', errorText);
        setError(`Failed to download Excel: ${response.statusText}`);
      }
    } catch (err) {
      console.error('[CRS] Excel download error:', err);
      setError('Failed to download Excel: ' + err.message);
    } finally {
      setLoading(false);
    }
  };

  // Reset and start over
  const handleReset = () => {
    setCurrentStep(0);
    setCreatedChain(null);
    setCurrentRevisionNumber(1);
    setUploadedRevisions([]);
    setLastRevisionId(null);
    setError(null);
    setSuccess(null);
    setChainForm({
      chain_id: '',
      document_title: '',
      document_number: '',
      project_name: '',
      contractor_name: '',
      department: '',
      notes: '',
      max_allowed_revisions: 5
    });
  };

  return (
    <Box sx={{ p: 3, maxWidth: 1200, mx: 'auto' }}>
      {/* Header */}
      <Typography variant="h4" gutterBottom fontWeight="bold">
        📄 CRS Multi-Revision Workflow
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
        Create a new revision chain and upload CRS sheets one by one
      </Typography>

      {/* Stepper */}
      <Stepper activeStep={currentStep} sx={{ mb: 4 }}>
        <Step>
          <StepLabel>Create Chain</StepLabel>
        </Step>
        <Step>
          <StepLabel>Upload Revisions</StepLabel>
        </Step>
        <Step>
          <StepLabel>Complete</StepLabel>
        </Step>
      </Stepper>

      {/* Alerts */}
      {error && <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>{error}</Alert>}
      {success && <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess(null)}>{success}</Alert>}

      {/* STEP 0: Create Chain Form */}
      {currentStep === 0 && (
        <Paper sx={{ p: 4 }}>
          <Typography variant="h5" gutterBottom>
            Step 1: Create New Revision Chain
          </Typography>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 3 }}>
            Enter project details and specify how many revisions you want to upload
          </Typography>

          <form onSubmit={handleCreateChain}>
            <Grid container spacing={3}>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Chain ID *"
                  fullWidth
                  required
                  value={chainForm.chain_id}
                  onChange={(e) => setChainForm({...chainForm, chain_id: e.target.value})}
                  placeholder="e.g., CHAIN-001"
                  helperText="Unique identifier for this chain"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Document Title *"
                  fullWidth
                  required
                  value={chainForm.document_title}
                  onChange={(e) => setChainForm({...chainForm, document_title: e.target.value})}
                  placeholder="e.g., Main Building Structural Drawings"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Document Number *"
                  fullWidth
                  required
                  value={chainForm.document_number}
                  onChange={(e) => setChainForm({...chainForm, document_number: e.target.value})}
                  placeholder="e.g., STR-001"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Project Name *"
                  fullWidth
                  required
                  value={chainForm.project_name}
                  onChange={(e) => setChainForm({...chainForm, project_name: e.target.value})}
                  placeholder="e.g., Downtown Tower Project"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Contractor Name"
                  fullWidth
                  value={chainForm.contractor_name}
                  onChange={(e) => setChainForm({...chainForm, contractor_name: e.target.value})}
                  placeholder="e.g., ABC Construction"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Department"
                  fullWidth
                  value={chainForm.department}
                  onChange={(e) => setChainForm({...chainForm, department: e.target.value})}
                  placeholder="e.g., Engineering"
                />
              </Grid>
              <Grid item xs={12} md={6}>
                <TextField
                  label="Number of Revisions *"
                  type="number"
                  fullWidth
                  required
                  value={chainForm.max_allowed_revisions}
                  onChange={(e) => setChainForm({
                    ...chainForm, 
                    max_allowed_revisions: Math.min(CONFIG.MAX_REVISIONS, Math.max(CONFIG.MIN_REVISIONS, parseInt(e.target.value) || 1))
                  })}
                  InputProps={{
                    inputProps: { 
                      min: CONFIG.MIN_REVISIONS, 
                      max: CONFIG.MAX_REVISIONS 
                    }
                  }}
                  helperText={`How many CRS sheets will you upload? (${CONFIG.MIN_REVISIONS}-${CONFIG.MAX_REVISIONS})`}
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  label="Notes"
                  fullWidth
                  multiline
                  rows={3}
                  value={chainForm.notes}
                  onChange={(e) => setChainForm({...chainForm, notes: e.target.value})}
                  placeholder="Optional notes about this document chain"
                />
              </Grid>
            </Grid>

            <Box sx={{ mt: 4, display: 'flex', justifyContent: 'flex-end' }}>
              <Button
                type="submit"
                variant="contained"
                size="large"
                disabled={loading}
                startIcon={loading ? <CircularProgress size={20} /> : <AddIcon />}
                sx={{ minWidth: 200 }}
              >
                {loading ? 'Creating...' : 'Create Chain & Start Upload'}
              </Button>
            </Box>
          </form>
        </Paper>
      )}

      {/* STEP 1: Upload Revisions */}
      {currentStep === 1 && createdChain && (
        <Box>
          {/* Chain Info */}
          <Paper sx={{ p: 3, mb: 3, bgcolor: 'primary.light' }}>
            <Typography variant="h6" gutterBottom>
              📋 Chain: {createdChain.document_title}
            </Typography>
            <Grid container spacing={2}>
              <Grid item>
                <Chip label={`Doc #: ${createdChain.document_number}`} />
              </Grid>
              <Grid item>
                <Chip label={`Project: ${createdChain.project_name}`} />
              </Grid>
              <Grid item>
                <Chip label={`Total Revisions: ${chainForm.max_allowed_revisions}`} color="primary" />
              </Grid>
            </Grid>
          </Paper>

          {/* Upload Current Revision */}
          <Paper sx={{ p: 4, mb: 3 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', mb: 3 }}>
              <Typography variant="h5">
                Upload Revision {currentRevisionNumber} of {chainForm.max_allowed_revisions}
              </Typography>
              <Chip 
                label={`Rev ${currentRevisionNumber}`} 
                color="primary" 
                size="large"
                sx={{ fontSize: '1.1rem', py: 3 }}
              />
            </Box>

            <Box sx={{ textAlign: 'center', py: 4 }}>
              <Button
                variant="contained"
                component="label"
                size="large"
                disabled={loading}
                startIcon={loading ? <CircularProgress size={24} /> : <UploadIcon />}
                sx={{ 
                  py: 3, 
                  px: 6, 
                  fontSize: '1.2rem',
                  minWidth: 300
                }}
              >
                {loading ? 'Uploading...' : `📤 Upload CRS Sheet ${currentRevisionNumber}`}
                <input
                  type="file"
                  hidden
                  accept={CONFIG.ACCEPTED_FILE_TYPE}
                  onChange={(e) => {
                    if (e.target.files[0]) {
                      handleUploadRevision(e.target.files[0]);
                    }
                  }}
                  disabled={loading}
                />
              </Button>
              <Typography variant="body2" color="text.secondary" sx={{ mt: 2 }}>
                PDF files only • Comments will be automatically extracted
              </Typography>
            </Box>
          </Paper>

          {/* Uploaded Revisions List */}
          {uploadedRevisions.length > 0 && (
            <Paper sx={{ p: 3 }}>
              <Typography variant="h6" gutterBottom>
                ✅ Uploaded Revisions ({uploadedRevisions.length})
              </Typography>
              <List>
                {uploadedRevisions.map((rev, idx) => (
                  <React.Fragment key={idx}>
                    <ListItem>
                      <CheckIcon color="success" sx={{ mr: 2, fontSize: 32 }} />
                      <ListItemText
                        primary={
                          <Typography variant="h6">
                            {rev.label}: {rev.fileName}
                          </Typography>
                        }
                        secondary={
                          <Box sx={{ mt: 1 }}>
                            <Chip label={`${rev.comments} Total Comments`} size="small" sx={{ mr: 1 }} />
                            <Chip label={`${rev.redComments} Red`} size="small" color="error" sx={{ mr: 1 }} />
                            <Chip label={`${rev.yellowComments} Yellow`} size="small" color="warning" />
                          </Box>
                        }
                      />
                    </ListItem>
                    {idx < uploadedRevisions.length - 1 && <Divider />}
                  </React.Fragment>
                ))}
              </List>
              
              {/* Download Excel Button - Available after first upload */}
              <Box sx={{ mt: 3, pt: 3, borderTop: '1px solid #ddd', textAlign: 'center' }}>
                <Button
                  variant="contained"
                  color="success"
                  size="large"
                  onClick={handleDownloadExcel}
                  startIcon={<DownloadIcon />}
                  sx={{ minWidth: 250, py: 1.5 }}
                >
                  📥 Download Excel Report
                </Button>
                <Typography variant="caption" display="block" color="text.secondary" sx={{ mt: 1 }}>
                  Contains all uploaded revisions and extracted comments
                </Typography>
              </Box>
            </Paper>
          )}
        </Box>
      )}

      {/* STEP 2: Complete */}
      {currentStep === 2 && (
        <Paper sx={{ p: 4, textAlign: 'center' }}>
          <CheckIcon sx={{ fontSize: 80, color: 'success.main', mb: 2 }} />
          <Typography variant="h4" gutterBottom>
            🎉 All Revisions Uploaded!
          </Typography>
          <Typography variant="body1" color="text.secondary" sx={{ mb: 4 }}>
            Successfully uploaded {uploadedRevisions.length} revisions for {createdChain?.document_title}
          </Typography>

          <Grid container spacing={2} sx={{ mb: 4 }}>
            {uploadedRevisions.map((rev, idx) => (
              <Grid item xs={12} md={6} key={idx}>
                <Card variant="outlined">
                  <CardContent>
                    <Typography variant="h6">{rev.label}</Typography>
                    <Typography variant="body2" color="text.secondary" noWrap>
                      {rev.fileName}
                    </Typography>
                    <Box sx={{ mt: 1 }}>
                      <Chip label={`${rev.comments} Comments`} size="small" color="primary" />
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            ))}
          </Grid>

          <Box sx={{ display: 'flex', gap: 2, justifyContent: 'center' }}>
            <Button
              variant="contained"
              size="large"
              onClick={handleDownloadExcel}
              startIcon={<DownloadIcon />}
              sx={{ minWidth: 200 }}
            >
              Download Excel Report
            </Button>
            <Button
              variant="outlined"
              size="large"
              onClick={handleReset}
              sx={{ minWidth: 200 }}
            >
              Create Another Chain
            </Button>
          </Box>
        </Paper>
      )}
    </Box>
  );
};

export default CRSMultiRevisionWorkflow;

/**
 * CRS Multiple Revision - AI-Powered Revision Chain Management
 * Tracks document revisions, links comments across revisions, provides AI insights
 * Feature 2.2: CRS Multiple Revision (Classic Version - Redesigned)
 */

import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import { API_BASE_URL } from '../config/api.config';
import { STORAGE_KEYS } from '../config/app.config';
import { withDashboardControls } from '../hoc/withPageControls';
import { PageControlButtons } from '../components/PageControlButtons';

const CRSMultipleRevision = ({ pageControls, refetch }) => {
  // State Management
  const [chains, setChains] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [statistics, setStatistics] = useState(null);
  
  // Filter States
  const [statusFilter, setStatusFilter] = useState('all');
  const [riskFilter, setRiskFilter] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');

  // Load data function
  const loadData = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const token = localStorage.getItem(STORAGE_KEYS.ACCESS_TOKEN);
      
      if (!token) {
        setError('Authentication required. Please log in.');
        setLoading(false);
        return;
      }

      // Build query parameters
      const params = new URLSearchParams();
      if (statusFilter && statusFilter !== 'all') params.append('status', statusFilter);
      if (riskFilter && riskFilter !== 'all') params.append('risk_level', riskFilter);
      if (searchQuery) params.append('search', searchQuery);

      // Fetch chains and statistics
      const [chainsRes, statsRes] = await Promise.all([
        fetch(`${API_BASE_URL}/crs/revision-chains/?${params}`, {
          headers: { 'Authorization': `Bearer ${token}` }
        }),
        fetch(`${API_BASE_URL}/crs/revision-chains/dashboard_summary/`, {
          headers: { 'Authorization': `Bearer ${token}` }
        })
      ]);

      if (chainsRes.ok) {
        const chainsData = await chainsRes.json();
        setChains(Array.isArray(chainsData) ? chainsData : chainsData.results || []);
      } else {
        const errorData = await chainsRes.json().catch(() => ({}));
        console.error('Error loading chains:', chainsRes.status, errorData);
        
        // Extract meaningful error message
        let errorMsg = `Failed to load chains (${chainsRes.status})`;
        if (errorData.detail) errorMsg = errorData.detail;
        else if (errorData.errors) errorMsg = JSON.stringify(errorData.errors);
        
        setError(errorMsg);
      }

      if (statsRes.ok) {
        const statsData = await statsRes.json();
        setStatistics(statsData);
      } else {
        console.error('Error loading statistics:', statsRes.status);
        // Don't show error for stats failure, it's not critical
      }
    } catch (error) {
      console.error('Error loading data:', error);
      setError(error.message || 'Failed to load data. Please try again.');
    } finally {
      setLoading(false);
    }
  }, [statusFilter, riskFilter, searchQuery]);

  // Initial load
  useEffect(() => {
    loadData();
  }, [loadData]);

  // Auto-refresh integration
  useEffect(() => {
    if (refetch) {
      loadData();
    }
  }, [refetch, loadData]);

  // Helper functions
  const getRiskLevelColor = (riskLevel) => {
    const colors = {
      'low': 'bg-green-100 text-green-800 border border-green-200',
      'medium': 'bg-yellow-100 text-yellow-800 border border-yellow-200',
      'high': 'bg-orange-100 text-orange-800 border border-orange-200',
      'critical': 'bg-red-100 text-red-800 border border-red-200'
    };
    return colors[riskLevel] || 'bg-gray-100 text-gray-800 border border-gray-200';
  };

  const getStatusColor = (status) => {
    const colors = {
      'active': 'bg-blue-100 text-blue-800 border border-blue-200',
      'on_hold': 'bg-yellow-100 text-yellow-800 border border-yellow-200',
      'approved': 'bg-green-100 text-green-800 border border-green-200',
      'rejected': 'bg-red-100 text-red-800 border border-red-200'
    };
    return colors[status] || 'bg-gray-100 text-gray-800 border border-gray-200';
  };

  // Loading State
  if (loading && !chains.length) {
    return (
      <div className="flex justify-center items-center min-h-screen bg-gradient-to-br from-gray-50 to-blue-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-blue-500 mx-auto mb-4"></div>
          <p className="text-gray-600 font-semibold">Loading revision chains...</p>
        </div>
      </div>
    );
  }

  // Error State
  if (error) {
    return (
      <div className="flex justify-center items-center min-h-screen bg-gradient-to-br from-gray-50 to-blue-50">
        <div className="bg-white rounded-2xl shadow-xl p-8 max-w-md text-center">
          <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <svg className="w-8 h-8 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
            </svg>
          </div>
          <h3 className="text-xl font-bold text-gray-900 mb-2">Error Loading Data</h3>
          <p className="text-gray-600 mb-6">{error}</p>
          <button
            onClick={loadData}
            className="px-6 py-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-colors font-semibold"
          >
            Try Again
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-blue-50/30 to-indigo-50/30 pb-8">
      {/* Main Container */}
      <div className="max-w-[1920px] mx-auto px-3 sm:px-4 lg:px-6 py-4 lg:py-6 mt-20 sm:mt-16 lg:mt-6">
        
        {/* Page Header */}
        <div className="bg-white rounded-2xl shadow-lg border border-gray-100 p-4 sm:p-5 mb-6">
          {/* Title Row */}
          <div className="flex items-center gap-3 mb-4">
            <div className="flex-shrink-0 p-2 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-xl shadow-lg">
              <svg className="w-6 h-6 sm:w-7 sm:h-7 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
            </div>
            <div className="flex-1 min-w-0">
              <h1 className="text-base sm:text-lg lg:text-xl font-bold text-gray-900 leading-tight break-words">
                CRS Multi-Revision Workflow
              </h1>
              <p className="text-xs text-gray-600 leading-tight mt-0.5">
                AI-powered revision chain management system
              </p>
            </div>
          </div>

          {/* Action Buttons Row - Separate Row */}
          <div className="flex flex-wrap items-center gap-2">
            <PageControlButtons controls={pageControls} />
            <button
              onClick={loadData}
              title="Refresh Data"
              className="flex items-center gap-1.5 px-3 py-2 bg-white border-2 border-gray-300 text-gray-700 rounded-xl hover:border-blue-500 hover:text-blue-600 transition-all font-semibold shadow-sm hover:shadow-md text-sm"
            >
              <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
              </svg>
              <span className="hidden sm:inline">Refresh</span>
            </button>
          </div>
        </div>

        {/* Statistics Cards */}
        {statistics && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
            {/* Total Chains */}
            <div className="bg-white rounded-xl shadow-md hover:shadow-xl transition-shadow p-5 border border-gray-100">
              <div className="flex items-center justify-between mb-3">
                <div className="p-2 bg-blue-100 rounded-lg">
                  <svg className="w-6 h-6 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                </div>
              </div>
              <p className="text-sm font-semibold text-gray-600 mb-1">Total Chains</p>
              <p className="text-3xl font-bold text-gray-900">{statistics.total_chains || 0}</p>
            </div>

            {/* Critical Chains */}
            <div className="bg-white rounded-xl shadow-md hover:shadow-xl transition-shadow p-5 border border-gray-100">
              <div className="flex items-center justify-between mb-3">
                <div className="p-2 bg-red-100 rounded-lg">
                  <svg className="w-6 h-6 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                  </svg>
                </div>
                {(statistics.critical_chains?.length || 0) > 0 && (
                  <span className="px-2 py-1 bg-red-100 text-red-700 rounded-full text-xs font-bold">ALERT</span>
                )}
              </div>
              <p className="text-sm font-semibold text-gray-600 mb-1">Critical Chains</p>
              <p className="text-3xl font-bold text-red-600">{statistics.critical_chains?.length || 0}</p>
            </div>

            {/* Near Rejection */}
            <div className="bg-white rounded-xl shadow-md hover:shadow-xl transition-shadow p-5 border border-gray-100">
              <div className="flex items-center justify-between mb-3">
                <div className="p-2 bg-yellow-100 rounded-lg">
                  <svg className="w-6 h-6 text-yellow-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
                  </svg>
                </div>
                {(statistics.near_rejection?.length || 0) > 0 && (
                  <span className="px-2 py-1 bg-yellow-100 text-yellow-700 rounded-full text-xs font-bold">WARNING</span>
                )}
              </div>
              <p className="text-sm font-semibold text-gray-600 mb-1">Near Rejection</p>
              <p className="text-3xl font-bold text-yellow-600">{statistics.near_rejection?.length || 0}</p>
            </div>

            {/* Active Chains */}
            <div className="bg-white rounded-xl shadow-md hover:shadow-xl transition-shadow p-5 border border-gray-100">
              <div className="flex items-center justify-between mb-3">
                <div className="p-2 bg-green-100 rounded-lg">
                  <svg className="w-6 h-6 text-green-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                  </svg>
                </div>
              </div>
              <p className="text-sm font-semibold text-gray-600 mb-1">Active Chains</p>
              <p className="text-3xl font-bold text-green-600">{statistics.by_status?.['Active'] || 0}</p>
            </div>
          </div>
        )}

        {/* Filters Section */}
        <div className="bg-white rounded-xl shadow-md border border-gray-100 p-4 sm:p-5 mb-6">
          <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2">
            <svg className="w-5 h-5 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M3 4a1 1 0 011-1h16a1 1 0 011 1v2.586a1 1 0 01-.293.707l-6.414 6.414a1 1 0 00-.293.707V17l-4 4v-6.586a1 1 0 00-.293-.707L3.293 7.293A1 1 0 013 6.586V4z" />
            </svg>
            Filter & Search
          </h3>
          
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Search Input */}
            <div className="lg:col-span-2">
              <input
                type="text"
                placeholder="Search by chain ID, project, document..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full px-4 py-2.5 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all"
              />
            </div>

            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2.5 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all bg-white"
            >
              <option value="all">All Status</option>
              <option value="active">Active</option>
              <option value="on_hold">On Hold</option>
              <option value="approved">Approved</option>
              <option value="rejected">Rejected</option>
            </select>

            {/* Risk Filter */}
            <select
              value={riskFilter}
              onChange={(e) => setRiskFilter(e.target.value)}
              className="px-4 py-2.5 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition-all bg-white"
            >
              <option value="all">All Risk Levels</option>
              <option value="low">Low Risk</option>
              <option value="medium">Medium Risk</option>
              <option value="high">High Risk</option>
              <option value="critical">Critical Risk</option>
            </select>
          </div>
        </div>

        {/* Chains Table/List */}
        <div className="bg-white rounded-xl shadow-lg overflow-hidden border border-gray-100">
          {chains.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16 px-4">
              <div className="p-6 bg-blue-50 rounded-full mb-4">
                <svg className="w-16 h-16 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={1.5} d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                </svg>
              </div>
              <h3 className="text-xl font-bold text-gray-900 mb-2">No Revision Chains Found</h3>
              <p className="text-gray-600 text-center">No chains match your current filters. Try adjusting your search criteria.</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full">
                <thead className="bg-gray-50 border-b border-gray-200">
                  <tr>
                    <th className="px-4 sm:px-6 py-4 text-left text-xs font-bold text-gray-600 uppercase tracking-wider">
                      Chain Info
                    </th>
                    <th className="px-4 sm:px-6 py-4 text-left text-xs font-bold text-gray-600 uppercase tracking-wider">
                      Project / Document
                    </th>
                    <th className="px-4 sm:px-6 py-4 text-left text-xs font-bold text-gray-600 uppercase tracking-wider">
                      Progress
                    </th>
                    <th className="px-4 sm:px-6 py-4 text-left text-xs font-bold text-gray-600 uppercase tracking-wider">
                      Risk / Status
                    </th>
                    <th className="px-4 sm:px-6 py-4 text-right text-xs font-bold text-gray-600 uppercase tracking-wider">
                      Actions
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {chains.map((chain) => (
                    <tr key={chain.id} className="hover:bg-blue-50/50 transition-colors">
                      {/* Chain Info */}
                      <td className="px-4 sm:px-6 py-4 whitespace-nowrap">
                        <div className="flex items-center gap-3">
                          <div className="flex-shrink-0 w-12 h-12 bg-gradient-to-br from-blue-500 to-indigo-600 rounded-lg flex items-center justify-center shadow-md">
                            <span className="text-white font-bold text-lg">{chain.current_revision_number || 0}</span>
                          </div>
                          <div>
                            <p className="text-sm font-bold text-gray-900">{chain.chain_id}</p>
                            <p className="text-xs text-gray-500">{chain.document_number}</p>
                          </div>
                        </div>
                      </td>

                      {/* Project / Document */}
                      <td className="px-4 sm:px-6 py-4">
                        <div className="max-w-xs">
                          <p className="text-sm font-semibold text-gray-900">{chain.project_name}</p>
                          <p className="text-sm text-gray-600 truncate">{chain.document_title}</p>
                          {chain.contractor_name && (
                            <p className="text-xs text-gray-500 mt-1">👤 {chain.contractor_name}</p>
                          )}
                        </div>
                      </td>

                      {/* Progress */}
                      <td className="px-4 sm:px-6 py-4 whitespace-nowrap">
                        <div>
                          <div className="flex items-center gap-2 mb-2">
                            <span className="text-2xl font-bold text-blue-600">{chain.current_revision_number || 0}</span>
                            <span className="text-gray-400">/</span>
                            <span className="text-lg text-gray-600">{chain.max_allowed_revisions || 5}</span>
                          </div>
                          <div className="w-full bg-gray-200 rounded-full h-2">
                            <div
                              className={`h-full rounded-full transition-all ${
                                (chain.risk_percentage || 0) >= 80 ? 'bg-red-500' :
                                (chain.risk_percentage || 0) >= 60 ? 'bg-yellow-500' :
                                'bg-green-500'
                              }`}
                              style={{ width: `${chain.risk_percentage || 0}%` }}
                            />
                          </div>
                          <p className="text-xs text-gray-600 mt-1">{chain.risk_percentage || 0}% Complete</p>
                        </div>
                      </td>

                      {/* Risk / Status */}
                      <td className="px-4 sm:px-6 py-4 whitespace-nowrap">
                        <div className="flex flex-col gap-2">
                          <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-bold ${getRiskLevelColor(chain.risk_level)}`}>
                            {chain.risk_level === 'low' && '🟢'}
                            {chain.risk_level === 'medium' && '🟡'}
                            {chain.risk_level === 'high' && '🟠'}
                            {chain.risk_level === 'critical' && '🔴'}
                            {' '}{chain.risk_level?.toUpperCase() || 'UNKNOWN'}
                          </span>
                          <span className={`inline-flex items-center px-3 py-1 rounded-full text-xs font-bold ${getStatusColor(chain.status)}`}>
                            {chain.status?.replace('_', ' ').toUpperCase() || 'UNKNOWN'}
                          </span>
                        </div>
                      </td>

                      {/* Actions */}
                      <td className="px-4 sm:px-6 py-4 whitespace-nowrap text-right">
                        <Link
                          to={`/crs/chain/${chain.id}`}
                          className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm font-semibold shadow-sm hover:shadow-md"
                        >
                          <span>View Details</span>
                          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
                          </svg>
                        </Link>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

