              <span className="text-purple-500 text-sm font-semibold">
                {CONSULTING_SERVICE_INFO.moduleCode} v{CONSULTING_SERVICE_INFO.version}
              </span>
            </div>
            <h1 className={`text-5xl md:text-6xl font-bold mb-6 ${
