        {results && !isProcessing && items.length === 0 && (
          <div style={{
            background: 'rgba(240,253,244,0.9)', border: '1px solid rgba(5,150,105,0.2)',
            borderRadius: '12px', padding: '16px 20px', marginTop: '16px',
            color: '#065f46', fontSize: '0.88rem', fontWeight: 500,
