          }}>
            RECOMMENDED FOR YOU
          </span>
        </div>
        {Body}
      </div>
    </div>
  );
};

export default NonTeffMetadataPage;

import { radaiAlert, radaiConfirm } from '../../../services/radaiDialog'
/**
 * Non-TEFF Projects
 * Route:  /engineering/digitization/non-teff-metadata/projects
 *
 * Lightweight, RBAC-aware project organiser for the Non-TEFF Metadata
 * Generator. Mirrors the visual language of NonTeffMetadataPage (emerald /
 * teal) but stays self-contained — no business-logic dependency on the
 * extraction page.
 *
 * All API endpoint paths and visual tokens are soft-coded in PROJECT_PAGE_CFG.
 */

import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  FolderPlusIcon,
  FolderIcon,
  ArrowLeftIcon,
  MagnifyingGlassIcon,
  PencilSquareIcon,
  TrashIcon,
  XMarkIcon,
  CheckIcon,
  ArrowRightIcon,
  ChartBarIcon,
} from '@heroicons/react/24/outline';
import apiClient from '../../../services/api.service';

// ---------------------------------------------------------------------------
// Soft-coded configuration
// ---------------------------------------------------------------------------
const PROJECT_PAGE_CFG = {
  api: {
    list:   '/non-teff/projects/',
    detail: (id) => `/non-teff/projects/${id}/`,
    items:  (id) => `/non-teff/projects/${id}/items/`,
  },
  routes: {
    metadataPage: '/engineering/digitization/non-teff-metadata',
  },
  statuses: [
    { value: 'active',    label: 'Active',    color: '#059669', bg: 'rgba(5,150,105,0.10)' },
    { value: 'on_hold',   label: 'On hold',   color: '#b45309', bg: 'rgba(180,83,9,0.10)' },
    { value: 'completed', label: 'Completed', color: '#1d4ed8', bg: 'rgba(29,78,216,0.10)' },
    { value: 'archived',  label: 'Archived',  color: '#6b7280', bg: 'rgba(107,114,128,0.10)' },
  ],
  theme: {
    accent:        '#059669',
    accentSoft:    'rgba(5,150,105,0.08)',
    accentBorder:  'rgba(5,150,105,0.22)',
    cardBg:        '#ffffff',
    pageBg:        '#f8fafc',
    text:          '#0f172a',
    muted:         '#64748b',
  },
};

const statusMeta = (value) =>
  PROJECT_PAGE_CFG.statuses.find((s) => s.value === value) || PROJECT_PAGE_CFG.statuses[0];

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------
const NonTeffProjectsPage = () => {
  const navigate = useNavigate();
  const T = PROJECT_PAGE_CFG.theme;

  const [projects, setProjects] = useState([]);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState('');
  const [query, setQuery]       = useState('');
  const [statusFilter, setStatusFilter] = useState('');
  const [showCreate, setShowCreate] = useState(false);
  const [editing, setEditing]   = useState(null);   // project being edited
  const [busy, setBusy]         = useState(false);

  const loadProjects = useCallback(async () => {
    setLoading(true);
    try {
      const params = {};
      if (query)        params.q       = query;
      if (statusFilter) params.status  = statusFilter;
      const res = await apiClient.get(PROJECT_PAGE_CFG.api.list, { params });
      setProjects(res.data.items || []);
      setError('');
    } catch (err) {
      setError(err?.response?.data?.error || 'Could not load projects.');
    } finally {
      setLoading(false);
    }
  }, [query, statusFilter]);

  useEffect(() => { loadProjects(); }, [loadProjects]);

  const visibleProjects = useMemo(() => projects, [projects]);

  // -------------------------------------------------------------------------
  // Mutations
  // -------------------------------------------------------------------------
  const handleCreate = async (payload) => {
    setBusy(true);
    try {
      await apiClient.post(PROJECT_PAGE_CFG.api.list, payload);
      setShowCreate(false);
      await loadProjects();
    } catch (err) {
      await radaiAlert(err?.response?.data?.error || 'Could not create project.');
    } finally {
      setBusy(false);
    }
  };

  const handleUpdate = async (id, payload) => {
    setBusy(true);
    try {
      await apiClient.patch(PROJECT_PAGE_CFG.api.detail(id), payload);
      setEditing(null);
      await loadProjects();
    } catch (err) {
      await radaiAlert(err?.response?.data?.error || 'Could not update project.');
    } finally {
      setBusy(false);
    }
  };

  const handleDelete = async (p) => {
    if (!(await radaiConfirm(
      `Delete project "${p.name}"?\nAssociated extractions stay in the system but become unassigned.`
    ))) return;
    setBusy(true);
    try {
      await apiClient.delete(PROJECT_PAGE_CFG.api.detail(p.project_id));
      await loadProjects();
    } catch (err) {
      await radaiAlert(err?.response?.data?.error || 'Could not delete project.');
    } finally {
      setBusy(false);
    }
  };

  const handleOpen = (p) => {
    // Persist the active project so the extraction page can pick it up.
    try {
      localStorage.setItem('nonTeffActiveProject', JSON.stringify({
        project_id: p.project_id, name: p.name, plant: p.plant,
      }));
    } catch (_) { /* ignore */ }
    navigate(PROJECT_PAGE_CFG.routes.metadataPage);
  };

  // -------------------------------------------------------------------------
  // Render
  // -------------------------------------------------------------------------
  return (
    <div style={{ minHeight: '100vh', background: T.pageBg, padding: '24px 32px' }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 20 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 14 }}>
          <button
            onClick={() => navigate(PROJECT_PAGE_CFG.routes.metadataPage)}
            style={{
              display: 'inline-flex', alignItems: 'center', gap: 6,
              background: 'transparent', border: `1px solid ${T.accentBorder}`,
              color: T.accent, padding: '8px 12px', borderRadius: 8,
              fontSize: 13, fontWeight: 600, cursor: 'pointer',
            }}
          >
            <ArrowLeftIcon width={16} /> Back to Extractor
          </button>
          <div>
            <h1 style={{ margin: 0, fontSize: 22, fontWeight: 700, color: T.text, display: 'flex', alignItems: 'center', gap: 8 }}>
              <FolderIcon width={26} style={{ color: T.accent }} />
              Non-TEFF Projects
            </h1>
            <p style={{ margin: '4px 0 0', fontSize: 13, color: T.muted }}>
              Organise extractions by engineering project. Role-based — you see what you create; admins see all.
            </p>
          </div>
        </div>
        <button
          onClick={() => setShowCreate(true)}
          style={{
            display: 'inline-flex', alignItems: 'center', gap: 8,
            background: `linear-gradient(135deg, ${T.accent}, #0891b2)`,
            color: '#fff', border: 'none', padding: '10px 18px',
            borderRadius: 10, fontSize: 14, fontWeight: 600, cursor: 'pointer',
            boxShadow: '0 4px 14px rgba(5,150,105,0.30)',
          }}
        >
          <FolderPlusIcon width={18} /> New Project
        </button>
      </div>

      {/* Filters */}
      <div style={{
        display: 'flex', gap: 12, alignItems: 'center', marginBottom: 16,
        background: T.cardBg, padding: 12, borderRadius: 10,
        border: `1px solid ${T.accentBorder}`,
      }}>
        <div style={{ flex: 1, display: 'flex', alignItems: 'center', gap: 8,
                      background: T.accentSoft, borderRadius: 8, padding: '8px 12px' }}>
          <MagnifyingGlassIcon width={16} style={{ color: T.accent }} />
          <input
            type="text"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search by name, code, client, or plant…"
            style={{
              flex: 1, border: 'none', background: 'transparent',
              fontSize: 13, color: T.text, outline: 'none',
            }}
          />
        </div>
        <select
          value={statusFilter}
          onChange={(e) => setStatusFilter(e.target.value)}
          style={{
            padding: '8px 12px', borderRadius: 8, fontSize: 13,
            border: `1px solid ${T.accentBorder}`, background: '#fff',
            color: T.text, cursor: 'pointer',
          }}
        >
          <option value="">All statuses</option>
          {PROJECT_PAGE_CFG.statuses.map((s) => (
            <option key={s.value} value={s.value}>{s.label}</option>
          ))}
        </select>
      </div>

      {/* Status / Errors */}
      {error && (
        <div style={{ background: '#fee2e2', color: '#991b1b', padding: 12,
                      borderRadius: 8, marginBottom: 12, fontSize: 13 }}>
          {error}
        </div>
      )}

      {loading ? (
        <div style={{ padding: 60, textAlign: 'center', color: T.muted }}>Loading projects…</div>
      ) : visibleProjects.length === 0 ? (
        <EmptyState onCreate={() => setShowCreate(true)} theme={T} />
      ) : (
        <div style={{
          display: 'grid', gap: 14,
          gridTemplateColumns: 'repeat(auto-fill, minmax(320px, 1fr))',
        }}>
          {visibleProjects.map((p) => (
            <ProjectCard
              key={p.project_id}
              project={p}
              theme={T}
              onOpen={() => handleOpen(p)}
              onEdit={() => setEditing(p)}
              onDelete={() => handleDelete(p)}
            />
          ))}
        </div>
      )}

      {/* Create / Edit modal */}
      {(showCreate || editing) && (
        <ProjectFormModal
          theme={T}
          initial={editing}
          busy={busy}
          onClose={() => { setShowCreate(false); setEditing(null); }}
          onSubmit={(payload) =>
            editing ? handleUpdate(editing.project_id, payload) : handleCreate(payload)
          }
        />
      )}
    </div>
  );
};

