  const uploadAccessMode = apiConfig?.pipe_class_conversation_dataset?.upload_access_mode || 'admin_only';
  const uploadAccessLabel = uploadAccessMode === 'authenticated' ? 'All logged-in users' : 'Admin only';

  const load = useCallback(async () => {
    if (tableDef.infoOnly) return;
    setLoading(true);
    setError(null);
    try {
      const data = await tableDef.fetch(valveStandardsAPI, filters);
      setRows(Array.isArray(data) ? data : data?.results || []);
    } catch (e) {
      setError(e?.response?.data?.error || e.message || 'Failed to load data');
      setRows([]);
    } finally {
      setLoading(false);
    }
  }, [tableDef, filters]);

  useEffect(() => {
    setActiveTable(browseConfig[0].id);
  }, [browseConfig]);

  useEffect(() => {
    setFilters({});
    setRows([]);
    setSearch('');
    setUploadFile(null);
    setUploadMode('replace');
    setUploadDryRun(true);
    setUploadResult(null);
    setUploadCategory(VALVE_UPLOAD_CATEGORIES[0].value);
  }, [activeTable]);

  const handleUpload = async () => {
    if (!uploadFile || uploading) return;
    setUploading(true);
    setUploadResult(null);
    try {
      const data = await selectedUploadCategory.upload(valveStandardsAPI, uploadFile, {
        mode: uploadMode,
        dryRun: uploadDryRun,
      });
      setUploadResult({ ok: true, data });
      if (!uploadDryRun) {
        await load();
      }
    } catch (err) {
      setUploadResult({
        ok: false,
        error: err?.response?.data?.error || err?.response?.data?.detail || err?.message || 'Upload failed',
      });
    } finally {
      setUploading(false);
    }
  };

  const handleAddCustomTab = () => {
    const label = newTabLabel.trim();
    const endpointPath = newTabPath.trim();
    const columnsRaw = newTabColumns.trim();

    if (!label || !endpointPath || !columnsRaw) {
      setUploadResult({ ok: false, error: 'Tab name, endpoint path, and columns are required.' });
      return;
    }

    const columnKeys = columnsRaw.split(',').map((v) => v.trim()).filter(Boolean);
    if (columnKeys.length === 0) {
      setUploadResult({ ok: false, error: 'Please provide at least one column key.' });
      return;
    }

    const customId = `custom_${label.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '')}_${Date.now()}`;
    const customTab = {
      id: customId,
      label,
      icon: TableCellsIcon,
      custom: true,
      endpointPath,
      fetch: (api, filters) => api.fetchCustomRows(endpointPath, filters),
      filters: [],
      columns: columnKeys.map((key) => ({ key, label: key.replace(/_/g, ' ').replace(/\b\w/g, (m) => m.toUpperCase()) })),
    };

    const existing = JSON.parse(localStorage.getItem(CUSTOM_TABS_STORAGE_KEY) || '{}');
    const current = Array.isArray(existing?.[standard.id]) ? existing[standard.id] : [];
    const next = { ...existing, [standard.id]: [...current, customTab] };
    localStorage.setItem(CUSTOM_TABS_STORAGE_KEY, JSON.stringify(next));

    window.dispatchEvent(new Event('valve-standards-custom-tabs-updated'));

    setNewTabLabel('');
    setNewTabPath('');
    setNewTabColumns('');
    setShowAddTabForm(false);
    setUploadResult({ ok: true, data: { message: `Added new tab: ${label}` } });
  };

  useEffect(() => {
    load();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeTable, JSON.stringify(filters)]);

  const optionsFor = (key) => {
    if (!apiConfig) return [];
    if (key === 'group_no') return apiConfig.group_nos || [];
    if (key === 'class_number') return apiConfig.class_numbers || [];
    if (key === 'family') return (apiConfig.families || []).map((f) => f.value);
    if (key === 'class_section') return (apiConfig.class_sections || []).map((f) => f.value);
    if (key === 'unit') return (apiConfig.units || apiConfig.length_units || []).map((f) => f.value);
    if (key === 'temp_unit') return (apiConfig.temp_units || []).map((f) => f.value);
    if (key === 'category') return apiConfig.categories || [];
    if (key === 'spec_no') return apiConfig.spec_nos || [];
    if (key === 'source_sheet') return apiConfig.source_sheets || [];
    if (key === 'record_type') return apiConfig.record_types || [];
    return [];
  };

  // SOFT-CODED: free-text search filters whatever rows are already loaded —
  // no extra API calls, works identically across every table's column set.
  const visibleRows = useMemo(() => {
    if (!search.trim()) return rows;
    const q = search.trim().toLowerCase();
    return rows.filter((row) =>
      tableDef.columns.some((c) => {
        const v = c.render ? c.render(row) : row[c.key];
        return v !== null && v !== undefined && String(v).toLowerCase().includes(q);
      })
    );
  }, [rows, search, tableDef.columns]);

  return (
    <div className="grid grid-cols-1 xl:grid-cols-[280px_minmax(0,1fr)] gap-4">
      <aside className="bg-white rounded-xl border border-slate-200 shadow-sm p-3 h-fit xl:sticky xl:top-6">
        <div className="px-2 py-1 mb-2">
          <h3 className="text-xs uppercase tracking-wider font-semibold text-slate-500">Database Navigator</h3>
          <p className="text-[11px] text-slate-400 mt-0.5">Select a reference table</p>
        </div>
        <div className="space-y-1.5">
          <button
            onClick={() => setShowAddTabForm((v) => !v)}
            className="w-full flex items-center justify-center gap-2 px-3 py-2 rounded-lg text-sm font-semibold border border-dashed border-slate-300 text-slate-600 hover:bg-slate-50"
          >
            <PlusIcon className="w-4 h-4" /> Add Tab
          </button>
          {showAddTabForm && (
            <div className="rounded-lg border border-slate-200 bg-slate-50 p-2.5 space-y-2">
              <input
                value={newTabLabel}
                onChange={(e) => setNewTabLabel(e.target.value)}
                placeholder="Tab name (e.g., Gasket Specs)"
                className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-xs"
              />
              <input
                value={newTabPath}
                onChange={(e) => setNewTabPath(e.target.value)}
                placeholder="API path (e.g., /b16-5/gasket-specs/)"
                className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-xs"
              />
              <input
                value={newTabColumns}
                onChange={(e) => setNewTabColumns(e.target.value)}
                placeholder="Columns (comma-separated keys)"
                className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-xs"
              />
              <button
                onClick={handleAddCustomTab}
                className="w-full px-2 py-1.5 rounded-md bg-blue-600 text-white text-xs font-semibold hover:bg-blue-700"
              >
                Save Tab
              </button>
            </div>
          )}
          {browseConfig.map((t) => (
            <button
              key={t.id}
              onClick={() => setActiveTable(t.id)}
              className={`w-full flex items-center justify-between gap-2 px-3 py-2.5 rounded-lg text-sm font-medium transition-all duration-200 ${
                activeTable === t.id
                  ? `bg-gradient-to-r ${standard.accent} text-white shadow-md`
                  : 'bg-white text-slate-600 border border-slate-200 hover:bg-slate-50 hover:border-slate-300'
              }`}
            >
              <span className="flex items-center gap-2 min-w-0">
                <t.icon className="w-4 h-4 flex-shrink-0" />
                <span className="truncate">{t.label}</span>
              </span>
              <span className={`text-[11px] px-2 py-0.5 rounded-full ${activeTable === t.id ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'}`}>
                {(t.columns || []).length}
              </span>
            </button>
          ))}
        </div>
      </aside>

      <section className="min-w-0">
        {hasUploadCapability && (
          <div className="mb-4 bg-white p-4 rounded-lg border border-slate-200">
            <div className="flex items-center gap-2 mb-3">
              <CloudArrowUpIcon className="w-5 h-5 text-blue-600" />
              <h4 className="text-sm font-semibold text-slate-800">Valve Standards Reference Upload</h4>
              <span className="text-[11px] px-2 py-0.5 rounded-full bg-amber-100 text-amber-700 font-semibold">{uploadAccessLabel}</span>
            </div>
            <p className="text-xs text-slate-500 mb-3">
              Upload new category data in Excel format and update the reference database. Use Dry Run first.
            </p>
            <div className="grid grid-cols-1 md:grid-cols-5 gap-3 items-end">
              <div>
                <label className="text-xs font-medium text-slate-500 mb-1 block">Data Category</label>
                <select
                  value={uploadCategory}
                  onChange={(e) => {
                    const nextValue = e.target.value;
                    setUploadCategory(nextValue);
                    const nextCategory = VALVE_UPLOAD_CATEGORIES.find((c) => c.value === nextValue);
                    if (!nextCategory) return;
                    if (nextCategory.tableId && browseConfig.some((t) => t.id === nextCategory.tableId)) {
                      setActiveTable(nextCategory.tableId);
                    }
                  }}
                  className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
                >
                  {VALVE_UPLOAD_CATEGORIES.map((cat) => (
                    <option key={cat.value} value={cat.value}>{cat.label}</option>
                  ))}
                </select>
              </div>
              <div className="md:col-span-2">
                <label className="text-xs font-medium text-slate-500 mb-1 block">Excel File (.xlsx)</label>
                <input
                  type="file"
                  accept=".xlsx"
                  onChange={(e) => setUploadFile(e.target.files?.[0] || null)}
                  className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
                />
              </div>
              <div>
                <label className="text-xs font-medium text-slate-500 mb-1 block">Mode</label>
                <select
                  value={uploadMode}
                  onChange={(e) => setUploadMode(e.target.value)}
                  className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
                >
                  <option value="replace">Replace existing</option>
                  <option value="append">Append to existing</option>
                </select>
              </div>
              <div className="flex items-center gap-2">
                <input
                  id="uploadDryRun"
                  type="checkbox"
                  checked={uploadDryRun}
                  onChange={(e) => setUploadDryRun(e.target.checked)}
                  className="rounded border-slate-300"
                />
                <label htmlFor="uploadDryRun" className="text-sm text-slate-700">Dry run</label>
              </div>
            </div>
            <div className="mt-3 flex items-center gap-2">
              <button
                onClick={handleUpload}
                disabled={!uploadFile || uploading}
                className="px-4 py-2 rounded-lg bg-blue-600 text-white text-sm font-semibold hover:bg-blue-700 disabled:opacity-50"
              >
                {uploading ? 'Uploading...' : uploadDryRun ? 'Validate Workbook' : 'Update Database'}
              </button>
              {uploadFile && <span className="text-xs text-slate-500 truncate max-w-[280px]">{uploadFile.name}</span>}
            </div>
            {uploadResult && (
              <div className={`mt-3 rounded-lg border p-3 text-sm ${uploadResult.ok ? 'bg-emerald-50 border-emerald-200 text-emerald-800' : 'bg-rose-50 border-rose-200 text-rose-800'}`}>
                {uploadResult.ok ? (
                  <div>
                    <div className="font-semibold mb-1">{uploadResult.data.message || 'Upload completed.'}</div>
                    {uploadResult.data.summary && (
                      <div className="text-xs leading-5">
                        total_rows: {uploadResult.data.summary.total_rows} | index_entry: {uploadResult.data.summary.index_entry} | sheet_row: {uploadResult.data.summary.sheet_row} | branch_row: {uploadResult.data.summary.branch_row}
                      </div>
                    )}
                  </div>
                ) : (
                  <div className="font-semibold">{uploadResult.error}</div>
                )}
              </div>
            )}
          </div>
        )}

        {tableDef.infoOnly && (
          <div className="bg-white rounded-lg border border-slate-200 p-6 flex items-start gap-4 animate-[fade-in_0.25s_ease-out]">
            <InformationCircleIcon className="w-8 h-8 text-blue-500 flex-shrink-0" />
            <div>
              <h4 className="font-semibold text-slate-800 mb-2">{tableDef.infoTitle}</h4>
              <p className="text-slate-600 text-sm leading-relaxed mb-2">{tableDef.infoBody}</p>
              {tableDef.infoNote && (
                <p className="text-slate-500 text-xs leading-relaxed italic">{tableDef.infoNote}</p>
              )}
            </div>
          </div>
        )}

        {!tableDef.infoOnly && (
          <div className="flex flex-wrap items-end gap-3 mb-4 bg-white p-4 rounded-lg border border-slate-200">
            {tableDef.filters.map((f) => (
              <div key={f.key} className="flex flex-col">
                <label className="text-xs font-medium text-slate-500 mb-1">
                  {f.label}{f.required ? ' *' : ''}
                </label>
                {f.inputType === 'text' ? (
                  <input
                    type="text"
                    className="border border-slate-300 rounded-md px-2 py-1.5 text-sm min-w-[180px] focus:ring-2 focus:ring-offset-0 focus:outline-none transition-shadow"
                    value={filters[f.key] || ''}
                    placeholder={f.placeholder || 'Type to filter'}
                    onChange={(e) => setFilters((prev) => ({ ...prev, [f.key]: e.target.value || undefined }))}
                  />
                ) : (
                  <select
                    className="border border-slate-300 rounded-md px-2 py-1.5 text-sm min-w-[140px] focus:ring-2 focus:ring-offset-0 focus:outline-none transition-shadow"
                    value={filters[f.key] || ''}
                    onChange={(e) => setFilters((prev) => ({ ...prev, [f.key]: e.target.value || undefined }))}
                  >
                    <option value="">All</option>
                    {optionsFor(f.key).map((opt) => (
                      <option key={opt} value={opt}>{opt}</option>
                    ))}
                  </select>
                )}
              </div>
            ))}
            <div className="flex flex-col flex-1 min-w-[220px]">
              <label className="text-xs font-medium text-slate-500 mb-1">Quick Search</label>
              <div className="relative">
                <MagnifyingGlassIcon className="w-4 h-4 text-slate-400 absolute left-2.5 top-1/2 -translate-y-1/2" />
                <input
                  type="text"
                  value={search}
                  onChange={(e) => setSearch(e.target.value)}
                  placeholder="Filter loaded rows..."
                  className="w-full border border-slate-300 rounded-md pl-8 pr-8 py-1.5 text-sm focus:ring-2 focus:ring-offset-0 focus:outline-none transition-shadow"
                />
                {search && (
                  <button onClick={() => setSearch('')} className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600">
                    <XMarkIcon className="w-4 h-4" />
                  </button>
                )}
              </div>
            </div>
          </div>
        )}

        {!tableDef.infoOnly && loading && (
          <div className="bg-white rounded-lg border border-slate-200 p-4 space-y-2">
            {Array.from({ length: 8 }).map((_, i) => (
              <div key={i} className="h-8 rounded-md bg-gradient-to-r from-slate-100 via-slate-50 to-slate-100 bg-[length:200%_100%] animate-[shimmer-bg_1.4s_ease-in-out_infinite]" />
            ))}
          </div>
        )}

        {!tableDef.infoOnly && !loading && error && (
          <div className="flex items-center gap-2 text-rose-700 bg-rose-50 border border-rose-200 rounded-lg p-4">
            <ExclamationTriangleIcon className="w-5 h-5 flex-shrink-0" /> {error}
          </div>
        )}

        {!tableDef.infoOnly && !loading && !error && visibleRows.length === 0 && (
          <div className="text-center text-slate-500 py-10 bg-white rounded-lg border border-dashed border-slate-300">
            <TableCellsIcon className="w-8 h-8 mx-auto text-slate-300 mb-2" />
            {rows.length === 0 ? (tableDef.emptyHint || 'No rows found.') : 'No rows match your search.'}
          </div>
        )}

        {!tableDef.infoOnly && !loading && !error && visibleRows.length > 0 && useCompactCards && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-3 animate-[fade-in_0.25s_ease-out]">
            {visibleRows.map((row, i) => (
              <div key={row.id ?? i} className="bg-white rounded-xl border border-slate-200 px-4 py-3 shadow-sm hover:shadow-md hover:border-slate-300 transition-all">
                <div className="flex items-center justify-between gap-2 mb-2">
                  <span className="text-[11px] font-semibold uppercase tracking-wide text-slate-400">Group</span>
                  <span className={`inline-flex items-center px-2 py-0.5 rounded-full text-[11px] font-semibold ${standard.text} bg-slate-100`}>
                    {row.group_no}
                  </span>
                </div>
                <div className="text-sm font-medium text-slate-700 leading-tight">
                  {row.family_name || '—'}
                </div>
              </div>
            ))}
            <div className="col-span-full px-1 py-1 text-xs text-slate-400 flex items-center justify-between">
              <span>{visibleRows.length.toLocaleString()} group(s){search ? ` (of ${rows.length.toLocaleString()})` : ''}</span>
              {tableDef.filters.length > 0 && Object.keys(filters).length > 0 && (
                <button onClick={() => setFilters({})} className="text-slate-400 hover:text-slate-600 underline">
                  Reset filters
                </button>
              )}
            </div>
          </div>
        )}

        {!tableDef.infoOnly && !loading && !error && visibleRows.length > 0 && !useCompactCards && (
          <div className="bg-white rounded-lg border border-slate-200 overflow-auto max-h-[520px] shadow-sm animate-[fade-in_0.25s_ease-out]">
            <table className="min-w-full text-sm">
              <thead className={`bg-gradient-to-r ${standard.accentSoft} sticky top-0 z-10`}>
                <tr>
                  {tableDef.columns.map((c) => (
                    <th key={c.key} className="text-left px-4 py-2.5 font-semibold text-slate-700 whitespace-nowrap">
                      {c.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {visibleRows.map((row, i) => (
                  <tr key={row.id ?? i} className={`hover:bg-blue-50/60 transition-colors ${i % 2 === 1 ? 'bg-slate-50/60' : ''}`}>
                    {tableDef.columns.map((c) => {
                      const value = c.render ? c.render(row) : row[c.key];
                      return (
                        <td
                          key={c.key}
                          className={`px-4 py-2 text-slate-700 whitespace-nowrap ${isNumericValue(value) ? 'text-right tabular-nums font-mono text-[13px]' : ''}`}
                        >
                          {value ?? <span className="text-slate-300">—</span>}
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
            <div className="px-4 py-2 text-xs text-slate-400 border-t border-slate-100 flex items-center justify-between">
              <span>{visibleRows.length.toLocaleString()} row(s){search ? ` (of ${rows.length.toLocaleString()})` : ''}</span>
              {tableDef.filters.length > 0 && Object.keys(filters).length > 0 && (
                <button onClick={() => setFilters({})} className="text-slate-400 hover:text-slate-600 underline">
                  Reset filters
                </button>
              )}
            </div>
          </div>
        )}
      </section>
    </div>
  );
};

// ─── Validate panel ───────────────────────────────────────────────────────────
const ValidatePanel = ({ config: apiConfig }) => {
  const [form, setForm] = useState({
    group_no: '', class_number: '', class_section: 'A',
    temp_value: '', temp_unit: 'C', target_pressure: '',
  });
  const [result, setResult] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const setField = (key, value) => setForm((prev) => ({ ...prev, [key]: value }));

  const canSubmit = form.group_no && form.class_number && form.class_section && form.temp_value !== '';

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError(null);
    setResult(null);
    try {
      const payload = { ...form };
      if (payload.target_pressure === '') delete payload.target_pressure;
      const data = await valveStandardsAPI.validate(payload);
      setResult(data);
    } catch (e2) {
      setError(e2?.response?.data?.error || e2.message || 'Validation failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
      <form onSubmit={handleSubmit} className="bg-white rounded-lg border border-slate-200 p-6 space-y-4">
        <h3 className="font-semibold text-slate-800 flex items-center gap-2">
          <CalculatorIcon className="w-5 h-5 text-blue-600" /> Rating Lookup
        </h3>
        <p className="text-xs text-slate-500">
          Two-point linear interpolation between tabulated temperatures (ASME B16.34 para 2.1(f)).
          Footnote exceptions (e.g. flanged-end temperature cutoffs) are not applied automatically —
          check the bracketing rows below.
        </p>

        <div className="grid grid-cols-2 gap-3">
          <div>
            <label className="text-xs font-medium text-slate-500 mb-1 block">Group No. *</label>
            <select className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
              value={form.group_no} onChange={(e) => setField('group_no', e.target.value)}>
              <option value="">Select...</option>
              {(apiConfig?.group_nos || []).map((g) => <option key={g} value={g}>{g}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-medium text-slate-500 mb-1 block">Class *</label>
            <select className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
              value={form.class_number} onChange={(e) => setField('class_number', e.target.value)}>
              <option value="">Select...</option>
              {(apiConfig?.class_numbers || []).map((c) => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-medium text-slate-500 mb-1 block">Class Section *</label>
            <select className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
              value={form.class_section} onChange={(e) => setField('class_section', e.target.value)}>
              {(apiConfig?.class_sections || []).map((s) => <option key={s.value} value={s.value}>{s.label}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-medium text-slate-500 mb-1 block">Temp. Unit</label>
            <select className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
              value={form.temp_unit} onChange={(e) => setField('temp_unit', e.target.value)}>
              {(apiConfig?.temp_units || []).map((u) => <option key={u.value} value={u.value}>{u.label}</option>)}
            </select>
          </div>
          <div>
            <label className="text-xs font-medium text-slate-500 mb-1 block">Temperature *</label>
            <input type="number" step="any" className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
              value={form.temp_value} onChange={(e) => setField('temp_value', e.target.value)} placeholder="e.g. 100" />
          </div>
          <div>
            <label className="text-xs font-medium text-slate-500 mb-1 block">Target Pressure (optional)</label>
            <input type="number" step="any" className="w-full border border-slate-300 rounded-md px-2 py-1.5 text-sm"
              value={form.target_pressure} onChange={(e) => setField('target_pressure', e.target.value)} placeholder="pass/fail check" />
          </div>
        </div>

        <button type="submit" disabled={!canSubmit || loading}
          className="w-full flex items-center justify-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-medium disabled:opacity-50 hover:bg-blue-700 transition-colors">
          {loading ? <ArrowPathIcon className="w-4 h-4 animate-spin" /> : <CalculatorIcon className="w-4 h-4" />}
          Look Up Rating
        </button>
      </form>

      <div className="bg-white rounded-lg border border-slate-200 p-6">
        <h3 className="font-semibold text-slate-800 mb-4">Result</h3>
        {error && (
          <div className="flex items-center gap-2 text-rose-700 bg-rose-50 border border-rose-200 rounded-lg p-4">
            <ExclamationTriangleIcon className="w-5 h-5 flex-shrink-0" /> {error}
          </div>
        )}
        {!error && !result && <p className="text-sm text-slate-400">Run a lookup to see the interpolated rating.</p>}
        {result && (
          <div className="space-y-4">
            <div className="flex items-center justify-between bg-blue-50 rounded-lg p-4">
              <div>
                <div className="text-xs text-slate-500">Interpolated Pressure</div>
                <div className="text-2xl font-bold text-blue-700">
                  {result.interpolated_pressure} {result.pressure_unit}
                </div>
              </div>
              {'pass' in result && (
                <span className={`flex items-center gap-1 px-3 py-1 rounded-full text-sm font-semibold ${
                  result.pass ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'
                }`}>
                  {result.pass ? <CheckCircleIcon className="w-4 h-4" /> : <XCircleIcon className="w-4 h-4" />}
                  {result.pass ? 'PASS' : 'FAIL'} vs {result.target_pressure} {result.pressure_unit}
                </span>
              )}
            </div>
            <div>
              <div className="text-xs font-medium text-slate-500 mb-2">Bracketing tabulated rows</div>
              <table className="w-full text-sm border border-slate-200 rounded-lg overflow-hidden">
                <thead className="bg-slate-50">
                  <tr>
                    <th className="text-left px-3 py-1.5">Temp</th>
                    <th className="text-left px-3 py-1.5">Pressure</th>
                  </tr>
                </thead>
                <tbody>
                  {result.bracketing_rows.map((r, i) => (
                    <tr key={i} className="border-t border-slate-100">
                      <td className="px-3 py-1.5">{r.temp_label} °{r.temp_unit}</td>
                      <td className="px-3 py-1.5">{r.pressure} {r.pressure_unit}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

// SOFT-CODED: local keyframe not covered by the global stylesheet (index.css
// already defines 'fade-in' and a translateX 'shimmer' with different shape).
const VALVE_KEYFRAMES = `
@keyframes shimmer-bg {
  0% { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}
`;

const ValveStandardsPage = () => {
  const navigate = useNavigate();
  const [standardId, setStandardId] = useState(STANDARDS[0].id);
  const [tab, setTab] = useState(TABS.BROWSE);
  const [apiConfig, setApiConfig] = useState(null);
  const [customTabsByStandard, setCustomTabsByStandard] = useState({});

  const standard = useMemo(() => STANDARDS.find((s) => s.id === standardId), [standardId]);
  const effectiveBrowseConfig = useMemo(() => {
    const customTabs = Array.isArray(customTabsByStandard?.[standard.id]) ? customTabsByStandard[standard.id] : [];
    return [...standard.browseConfig, ...customTabs];
  }, [standard, customTabsByStandard]);
  const quickStats = useMemo(() => getQuickStats(apiConfig, effectiveBrowseConfig), [apiConfig, effectiveBrowseConfig]);

  useEffect(() => {
    const loadTabs = () => {
      try {
        setCustomTabsByStandard(JSON.parse(localStorage.getItem(CUSTOM_TABS_STORAGE_KEY) || '{}'));
      } catch {
        setCustomTabsByStandard({});
      }
    };
    loadTabs();
    window.addEventListener('valve-standards-custom-tabs-updated', loadTabs);
    return () => window.removeEventListener('valve-standards-custom-tabs-updated', loadTabs);
  }, []);

  useEffect(() => {
    setApiConfig(null);
    standard.getConfig(valveStandardsAPI).then(setApiConfig).catch(() => setApiConfig(null));
    if (!standard.hasValidate) setTab(TABS.BROWSE);
  }, [standard]);

  return (
    <div className={`min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-cyan-50 ${VALVE_LAYOUT.pagePadding}`}>
      <style>{VALVE_KEYFRAMES}</style>
      <div className={`${VALVE_LAYOUT.canvasWidth} mx-auto mb-6`}>
        <div className="flex items-center gap-3 mb-4">
          <div className={`p-3 bg-gradient-to-br ${standard.accent} rounded-xl shadow-lg transition-all duration-300`}>
            <BookOpenIcon className="w-8 h-8 text-white" />
          </div>
          <div>
            <h1 className={`text-3xl font-bold bg-gradient-to-r ${standard.accent} bg-clip-text text-transparent transition-all duration-300`}>
              Valve Standards Reference
            </h1>
            <p className="text-slate-600 mt-1">
              {standard.fullName} — browse reference data extracted from the standard
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2 text-sm text-slate-600 mb-6">
          <span className="cursor-pointer hover:text-blue-600" onClick={() => navigate('/dashboard')}>Dashboard</span>
          <span>/</span>
          <span className="cursor-pointer hover:text-blue-600" onClick={() => navigate('/engineering/digitization/smart-plant-3d')}>
            Smart Plant 3D
          </span>
          <span>/</span>
          <span className="text-blue-600 font-medium">Valve Standards Reference</span>
        </div>

        {/* Standard selector — card grid, soft-coded from STANDARDS[].icon/accent/tagline */}
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3 mb-6">
          {STANDARDS.map((s) => {
            const active = standardId === s.id;
            return (
              <button
                key={s.id}
                onClick={() => setStandardId(s.id)}
                className={`text-left p-4 rounded-xl border transition-all duration-200 relative overflow-hidden group ${
                  active
                    ? `border-transparent ring-2 ${s.ring} bg-white shadow-lg scale-[1.01]`
                    : 'border-slate-200 bg-white/70 hover:bg-white hover:shadow-md'
                }`}
              >
                <div className={`absolute inset-0 bg-gradient-to-br ${s.accentSoft} opacity-0 group-hover:opacity-60 transition-opacity ${active ? '!opacity-70' : ''}`} />
                <div className="relative flex items-start gap-3">
                  <div className={`p-2 rounded-lg bg-gradient-to-br ${s.accent} shadow-sm flex-shrink-0`}>
                    <s.icon className="w-5 h-5 text-white" />
                  </div>
                  <div className="min-w-0">
                    <div className="flex items-center gap-2">
                      <span className={`font-bold text-sm ${active ? s.text : 'text-slate-800'}`}>{s.label}</span>
                      {s.hasValidate && (
                        <span className="px-1.5 py-0.5 rounded-full text-[10px] font-semibold bg-emerald-100 text-emerald-700">
                          Validator
                        </span>
                      )}
                    </div>
                    <p className="text-xs text-slate-500 mt-1 leading-snug line-clamp-2">{s.tagline}</p>
                  </div>
                </div>
              </button>
            );
          })}
        </div>

        {/* Quick stats — real numbers from the active standard's /config/ endpoint */}
        {quickStats.length > 0 && (
          <div className="flex flex-wrap gap-3 mb-6">
            {quickStats.map((stat) => (
              <div key={stat.label} className="flex items-center gap-2 bg-white border border-slate-200 rounded-lg px-4 py-2 shadow-sm">
                <ChartBarIcon className={`w-4 h-4 ${standard.text}`} />
                <span className="text-lg font-bold text-slate-800">{stat.value.toLocaleString()}</span>
                <span className="text-xs text-slate-500">{stat.label}</span>
              </div>
            ))}
          </div>
        )}

        <div className="flex gap-2 mb-6">
          {[
            { id: TABS.BROWSE, label: 'Browse', icon: TableCellsIcon },
            ...(standard.hasValidate ? [{ id: TABS.VALIDATE, label: 'Validate', icon: CalculatorIcon }] : []),
          ].map((t) => (
            <button key={t.id} onClick={() => setTab(t.id)}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-lg font-medium transition-colors ${
                tab === t.id ? `bg-white shadow-md ${standard.text} border ${standard.border}` : 'text-slate-500 hover:text-slate-700'
              }`}>
              <t.icon className="w-4 h-4" /> {t.label}
            </button>
          ))}
        </div>
      </div>

      <div className={`${VALVE_LAYOUT.canvasWidth} mx-auto`} key={`${standardId}-${tab}`}>
        {tab === TABS.BROWSE
          ? <BrowsePanel config={apiConfig} browseConfig={effectiveBrowseConfig} standard={standard} onRequestStandardChange={setStandardId} />
          : <ValidatePanel config={apiConfig} />}
      </div>
    </div>
  );
};

export default ValveStandardsPage;

/**
 * Spec Customization — Component Matching Workbook Manager
 * 
 * Manages Match.xlsx, SPEC.xlsx, and CAT.xlsx uploads for isometric software integration.
 * Displays active workbook set, upload form, and matching rules table.
 */
import React, { useCallback, useEffect, useState } from 'react';
import {
  CloudArrowUpIcon,
  CheckCircleIcon,
  XCircleIcon,
  DocumentTextIcon,
  TableCellsIcon,
  Cog6ToothIcon,
  ArrowPathIcon,
  SparklesIcon,
  ExclamationTriangleIcon,
} from '@heroicons/react/24/outline';
import apiClient from '../../../../services/api.service';

// ─── Soft-coded configuration ──────────────────────────────────────────────
const WORKBOOK_MANAGER_CONFIG = {
  endpoints: {
    upload: '/spec-customization/matching/upload/',
    sets: '/spec-customization/matching/sets/',
    rules: (setId) => `/spec-customization/matching/sets/${setId}/rules/`,
    parse: (setId) => `/spec-customization/matching/sets/${setId}/parse/`,
  },
  fileTypes: {
    match: { label: 'Match.xlsx', description: 'PDF → Excel name mapping', icon: '🔗' },
    spec: { label: 'SPEC.xlsx', description: 'Specification rules (25 sheets)', icon: '📋' },
    cat: { label: 'CAT.xlsx', description: 'Component catalog (23 sheets)', icon: '📦' },
  },
  maxFileSize: 50 * 1024 * 1024, // 50MB
};

// ───────────────────────────────────────────────────────────────────────────
// Main Component
// ───────────────────────────────────────────────────────────────────────────
const ComponentMatchingWorkbookManager = ({ projectId }) => {
  const [workbookSets, setWorkbookSets] = useState([]);
  const [activeSet, setActiveSet] = useState(null);
  const [rules, setRules] = useState([]);
  const [loading, setLoading] = useState(true);
  const [uploadingFiles, setUploadingFiles] = useState(false);
  const [error, setError] = useState('');

  // File upload state
  const [matchFile, setMatchFile] = useState(null);
  const [specFile, setSpecFile] = useState(null);
  const [catFile, setCatFile] = useState(null);
  const [versionLabel, setVersionLabel] = useState('');

  // Load workbook sets for project
  const loadWorkbookSets = useCallback(async () => {
    if (!projectId) return;
    
    setLoading(true);
    setError('');
    try {
      const res = await apiClient.get(WORKBOOK_MANAGER_CONFIG.endpoints.sets, {
        params: { project_id: projectId },
      });
      const sets = res.data?.items || [];
      setWorkbookSets(sets);
      
      // Find active set
      const active = sets.find((s) => s.is_active);
      setActiveSet(active || null);
      
      // Load rules for active set
      if (active?.is_parsed) {
        loadRules(active.id);
      }
    } catch (err) {
      setError(err?.response?.data?.error || 'Failed to load workbook sets');
    } finally {
      setLoading(false);
    }
  }, [projectId]);

  // Load matching rules
  const loadRules = async (setId) => {
    try {
      const res = await apiClient.get(WORKBOOK_MANAGER_CONFIG.endpoints.rules(setId));
      setRules(res.data?.items || []);
    } catch (err) {
      console.error('Failed to load rules:', err);
    }
  };

  useEffect(() => {
    loadWorkbookSets();
  }, [loadWorkbookSets]);

  // Handle file upload
  const handleUpload = async (e) => {
    e.preventDefault();
    
    if (!matchFile || !specFile || !catFile) {
      setError('All three files (Match, SPEC, CAT) are required');
      return;
    }

    setUploadingFiles(true);
    setError('');

    const formData = new FormData();
    formData.append('project_id', projectId);
    formData.append('match_file', matchFile);
    formData.append('spec_file', specFile);
    formData.append('cat_file', catFile);
    formData.append('version_label', versionLabel || `Upload ${workbookSets.length + 1}`);
    formData.append('auto_parse', 'true');

    try {
      const res = await apiClient.post(
        WORKBOOK_MANAGER_CONFIG.endpoints.upload,
        formData,
        {
          headers: { 'Content-Type': 'multipart/form-data' },
        }
      );

      const newSet = res.data?.workbook_set;
      if (newSet) {
        setWorkbookSets([newSet, ...workbookSets.filter((s) => !s.is_active)]);
        setActiveSet(newSet);
        
        if (newSet.is_parsed) {
          loadRules(newSet.id);
        }
      }

      // Reset form
      setMatchFile(null);
      setSpecFile(null);
      setCatFile(null);
      setVersionLabel('');
    } catch (err) {
      setError(err?.response?.data?.error || 'Upload failed');
    } finally {
      setUploadingFiles(false);
    }
  };

  // Re-parse Match.xlsx
  const handleReparse = async () => {
    if (!activeSet) return;

    setLoading(true);
    try {
      const res = await apiClient.post(WORKBOOK_MANAGER_CONFIG.endpoints.parse(activeSet.id));
      
      if (res.data?.success) {
        // Reload sets and rules
        await loadWorkbookSets();
      } else {
        setError(res.data?.error || 'Parsing failed');
      }
    } catch (err) {
      setError(err?.response?.data?.error || 'Failed to parse workbook');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-2 rounded-lg bg-gradient-to-br from-violet-500 to-purple-600 text-white shadow-sm">
            <TableCellsIcon className="w-5 h-5" />
          </div>
          <div>
            <h3 className="text-lg font-bold text-gray-900 dark:text-white">Component Matching Workbooks</h3>
            <p className="text-xs text-gray-600 dark:text-gray-400">
              Upload Match, SPEC, and CAT workbooks for isometric software integration
            </p>
          </div>
        </div>
        {activeSet && (
          <button
            onClick={handleReparse}
            disabled={loading}
            className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-semibold text-violet-700 dark:text-violet-300 border border-violet-200 dark:border-violet-800/50 hover:bg-violet-50 dark:hover:bg-violet-900/20 rounded-lg disabled:opacity-50"
          >
            <ArrowPathIcon className={`w-3.5 h-3.5 ${loading ? 'animate-spin' : ''}`} />
            Re-parse
          </button>
        )}
      </div>

      {/* Error */}
      {error && (
        <div className="flex items-start gap-2 p-3 rounded-lg border border-rose-200 bg-rose-50 dark:bg-rose-900/20 text-rose-800 dark:text-rose-200 text-sm">
          <ExclamationTriangleIcon className="w-4 h-4 mt-0.5 shrink-0" />
          <div className="flex-1">{error}</div>
          <button onClick={() => setError('')} className="text-xs font-semibold underline">Dismiss</button>
        </div>
      )}

      {/* Active Set Status */}
      {activeSet && (
        <div className="rounded-xl border border-violet-200 dark:border-violet-800/40 bg-gradient-to-r from-violet-50 via-purple-50 to-fuchsia-50 dark:from-violet-900/20 dark:via-purple-900/15 dark:to-fuchsia-900/20 p-4">
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-start gap-3 flex-1">
              <div className="p-2 rounded-lg bg-gradient-to-br from-violet-500 to-purple-600 text-white shadow-sm">
                <CheckCircleIcon className="w-5 h-5" />
              </div>
              <div className="min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="text-[11px] font-semibold uppercase tracking-wide text-violet-700 dark:text-violet-300">Active workbook set</span>
                  <span className="text-sm font-bold text-gray-900 dark:text-white">{activeSet.version_label}</span>
                </div>
                <div className="mt-1 flex items-center gap-3 text-xs text-gray-600 dark:text-gray-400">
                  <span>🔗 {activeSet.match_file_name}</span>
                  <span>📋 {activeSet.spec_file_name}</span>
                  <span>📦 {activeSet.cat_file_name}</span>
                </div>
                <div className="mt-2 flex items-center gap-3 text-xs">
                  <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded ${
                    activeSet.is_parsed
                      ? 'bg-emerald-100 dark:bg-emerald-900/30 text-emerald-700 dark:text-emerald-300'
                      : 'bg-amber-100 dark:bg-amber-900/30 text-amber-700 dark:text-amber-300'
                  }`}>
                    {activeSet.is_parsed ? <CheckCircleIcon className="w-3.5 h-3.5" /> : <XCircleIcon className="w-3.5 h-3.5" />}
                    {activeSet.is_parsed ? `${activeSet.rules_count} rules` : 'Not parsed'}
                  </span>
                  <span className="text-gray-500">
                    SPEC: {activeSet.spec_sheets_count} sheets · CAT: {activeSet.cat_sheets_count} sheets
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Upload Form */}
      <div className="rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 p-6">
        <div className="flex items-center gap-2 mb-4">
          <CloudArrowUpIcon className="w-5 h-5 text-violet-600" />
          <h4 className="text-sm font-bold text-gray-900 dark:text-white">Upload New Workbook Set</h4>
        </div>

        <form onSubmit={handleUpload} className="space-y-4">
          {/* Version Label */}
          <div>
            <label className="block text-xs font-semibold text-gray-700 dark:text-gray-200 mb-1.5">
              Version Label (optional)
            </label>
            <input
              type="text"
              value={versionLabel}
              onChange={(e) => setVersionLabel(e.target.value)}
              placeholder="e.g., Rev A, Initial, 2024-Q1"
              className="w-full px-3 py-2 text-sm border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-900 text-gray-900 dark:text-white focus:ring-2 focus:ring-violet-500 focus:border-transparent"
            />
          </div>

          {/* File Inputs */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            {Object.entries(WORKBOOK_MANAGER_CONFIG.fileTypes).map(([key, config]) => {
              const file = key === 'match' ? matchFile : key === 'spec' ? specFile : catFile;
              const setFile = key === 'match' ? setMatchFile : key === 'spec' ? setSpecFile : setCatFile;

              return (
                <div key={key}>
                  <label className="block text-xs font-semibold text-gray-700 dark:text-gray-200 mb-1.5">
                    {config.icon} {config.label} *
                  </label>
                  <div className="relative">
                    <input
                      type="file"
                      accept=".xlsx,.xls"
                      onChange={(e) => setFile(e.target.files?.[0] || null)}
                      className="hidden"
                      id={`file-${key}`}
                    />
                    <label
                      htmlFor={`file-${key}`}
                      className="flex items-center justify-center gap-2 w-full px-3 py-2.5 text-sm border-2 border-dashed border-gray-300 dark:border-gray-600 rounded-lg hover:border-violet-400 dark:hover:border-violet-600 bg-gray-50 dark:bg-gray-900 cursor-pointer transition-colors"
                    >
                      {file ? (
                        <>
                          <CheckCircleIcon className="w-4 h-4 text-emerald-600" />
                          <span className="text-xs font-medium text-gray-900 dark:text-white truncate max-w-[120px]">
                            {file.name}
                          </span>
                        </>
                      ) : (
                        <>
                          <CloudArrowUpIcon className="w-4 h-4 text-gray-400" />
                          <span className="text-xs text-gray-500">Choose file</span>
                        </>
                      )}
                    </label>
                  </div>
                  <p className="mt-1 text-[10px] text-gray-500">{config.description}</p>
                </div>
              );
            })}
          </div>

          {/* Submit */}
          <div className="flex items-center justify-end gap-3 pt-2">
            <button
              type="submit"
              disabled={uploadingFiles || !matchFile || !specFile || !catFile}
              className="inline-flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white bg-gradient-to-r from-violet-600 to-purple-600 hover:from-violet-700 hover:to-purple-700 rounded-lg shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {uploadingFiles ? (
                <>
                  <ArrowPathIcon className="w-4 h-4 animate-spin" />
                  Uploading...
                </>
              ) : (
                <>
                  <CloudArrowUpIcon className="w-4 h-4" />
                  Upload Workbooks
                </>
              )}
            </button>
          </div>
        </form>
      </div>

      {/* Matching Rules Table */}
      {activeSet?.is_parsed && rules.length > 0 && (
        <div className="rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 overflow-hidden">
          <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-700 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <SparklesIcon className="w-4 h-4 text-violet-600" />
              <h4 className="text-sm font-bold text-gray-900 dark:text-white">Matching Rules</h4>
              <span className="text-xs text-gray-500">({rules.length} rules)</span>
            </div>
          </div>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="bg-gray-50 dark:bg-gray-900 border-b border-gray-200 dark:border-gray-700">
                <tr>
                  <th className="px-4 py-2 text-left text-xs font-semibold text-gray-700 dark:text-gray-200">PDF Component Name</th>
                  <th className="px-4 py-2 text-left text-xs font-semibold text-gray-700 dark:text-gray-200">Catalog Name</th>
                  <th className="px-4 py-2 text-left text-xs font-semibold text-gray-700 dark:text-gray-200">CAT Sheet</th>
                  <th className="px-4 py-2 text-left text-xs font-semibold text-gray-700 dark:text-gray-200">Row #</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-100 dark:divide-gray-700">
                {rules.map((rule) => (
                  <tr key={rule.id} className="hover:bg-gray-50 dark:hover:bg-gray-900/50">
                    <td className="px-4 py-2.5 text-gray-900 dark:text-white font-medium">{rule.pdf_component_name}</td>
                    <td className="px-4 py-2.5 text-gray-700 dark:text-gray-300">{rule.catalog_component_name}</td>
                    <td className="px-4 py-2.5">
                      <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded bg-violet-100 dark:bg-violet-900/30 text-violet-700 dark:text-violet-300 text-xs font-medium">
                        📦 {rule.cat_sheet_name}
                      </span>
                    </td>
                    <td className="px-4 py-2.5 text-xs text-gray-500">Row {rule.row_number}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {/* Empty State */}
      {!loading && !activeSet && (
        <div className="py-12 text-center">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-gradient-to-br from-violet-500 to-purple-600 text-white shadow-lg mb-4">
            <TableCellsIcon className="w-8 h-8" />
