};

const PaperSpecExtractor = ({ projectId = null, projectByok = null, jobId = null } = {}) => {
  const [file, setFile]                     = useState(null);
  const [uploading, setUploading]           = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [uploadError, setUploadError]       = useState('');
  // Live upload telemetry â€” soft-coded UX (speed/ETA/route/tip rotation).
  const [uploadSpeedBps, setUploadSpeedBps] = useState(0);
  const [uploadEtaSec, setUploadEtaSec]     = useState(null);
  const [uploadRoute, setUploadRoute]       = useState(null);    // 'presigned' | 'legacy' | null
  const [tipIndex, setTipIndex]             = useState(0);
  const [procTipIndex, setProcTipIndex]     = useState(0);
  const uploadStartRef                      = useRef(0);
  const lastTickRef                         = useRef({ t: 0, loaded: 0 });

  // BYOK (Server AI configuration) â€” optional user-supplied fields for attribution and custom AI usage.
  const [documentName, setDocumentName]     = useState('');
  const [engineerName, setEngineerName]     = useState('');
  const [aiProvider, setAiProvider]         = useState(() => {
    try {
      return sessionStorage.getItem('radai_spec_ai_provider') || '';
    } catch (_) { return ''; }
  });
  const [aiModel, setAiModel]               = useState(() => {
    try {
      return sessionStorage.getItem('radai_spec_ai_model') || '';
    } catch (_) { return ''; }
  });
  const [userApiKey, setUserApiKey]         = useState(() => {
    try {
      const provider = sessionStorage.getItem('radai_spec_ai_provider') || '';
      if (provider === 'openai') {
        return null || '';
      } else if (provider === 'claude') {
        return null || '';
      }
      return '';
    } catch (_) { return ''; }
  });
  const [showApiKey, setShowApiKey]         = useState(false);

  // Soft-coded AI provider & model options from backend config (BYOK)
  const [byokConfig, setByokConfig]         = useState({
    enabled: true,
    supported_providers: ['openai', 'claude'],
    openai_models: [
      {id: 'gpt-4o', label: 'GPT-4o (Latest)', description: 'Most capable', recommended: true},
      {id: 'gpt-4o-mini', label: 'GPT-4o Mini', description: 'Faster, cost-effective'},
    ],
    claude_models: [
      {id: 'claude-3-5-sonnet-20241022', label: 'Claude 3.5 Sonnet', description: 'Best balance', recommended: true},
      {id: 'claude-3-5-haiku-20241022', label: 'Claude 3.5 Haiku', description: 'Fastest'},
      {id: 'claude-3-opus-20240229', label: 'Claude 3 Opus', description: 'Highest quality'},
    ],
    provider_labels: {
      openai: 'Your OpenAI API Key',
      claude: 'Your Claude API Key (Anthropic)',
    },
    api_key_patterns: {
      openai: /^sk-[A-Za-z0-9_-]{18,}$/,
      claude: /^sk-ant-[A-Za-z0-9_-]{20,}$/,
    },
  });

  const [job, setJob]                       = useState(null);
  const [document, setDocument]             = useState(null);
  const [classes, setClasses]               = useState([]);
  const [expandedClassId, setExpandedClassId] = useState(null);
  const [classDetailCache, setClassDetailCache] = useState({});
  const [asmeValidationCache, setAsmeValidationCache] = useState({});
  const [config, setConfig]                 = useState(null);
  const [isDragging, setIsDragging]         = useState(false);
  const [classSearch, setClassSearch]       = useState('');
  const [ratingFilter, setRatingFilter]     = useState(null);
  const [classPage, setClassPage]           = useState(1);
  const [classPageSize, setClassPageSize]   = useState(CLASS_LIST_PAGINATION_CONFIG.pageSize);
  // Top-level view tab inside the results section.
  // 'classes'  â†’ original piping-class cards
  // 'canvas'   â†’ editable SPEC/CAT workbook canvas (cross-check + edit)
  const [activeView, setActiveView]         = useState('classes');
  const pollRef = useRef(null);

  // Fetch backend config once for displaying caps to the user.
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const c = await specCustomizationAPI.getConfig();
        if (!cancelled) {
          setConfig(c);
          // Update BYOK config from backend if available
          if (c.byok) {
            const newByokConfig = {
              enabled: c.byok.enabled,
              openai_models: c.byok.openai_models || [],
              claude_models: c.byok.claude_models || [],
              provider_labels: c.byok.provider_labels || {},
              api_key_patterns: {
                openai: /^sk-[A-Za-z0-9_-]{18,}$/,
                claude: /^sk-ant-[A-Za-z0-9_-]{20,}$/,
              },
            };
            setByokConfig(newByokConfig);
          }
        }
      } catch (e) { /* ignore */ }
    })();
    return () => { cancelled = true; };
  }, []);

  // Resume/view existing job if jobId prop provided (history table click).
  useEffect(() => {
    if (!jobId) return;
    let cancelled = false;
    (async () => {
      try {
        const jobData = await specCustomizationAPI.getJob(jobId);
        if (cancelled) return;
        setJob(jobData);
        setDocument(jobData.document || null);
        // If completed, load classes immediately
        if (['completed', 'failed', 'cancelled'].includes(jobData.status)) {
          const classList = await specCustomizationAPI.getJobClasses(jobId);
          if (!cancelled) setClasses(classList);
        }
      } catch (err) {
        console.error('[SpecExtractor] Failed to load job:', err);
      }
    })();
    return () => { cancelled = true; };
  }, [jobId]);

  // Project-level BYOK defaults: when a project has BYOK configured, preselect
  // its provider/model in the UI so uploads align to that project automatically.
  useEffect(() => {
    if (!projectByok?.enabled || !projectByok?.provider) return;
    const provider = String(projectByok.provider || '').trim();
    const model = String(projectByok.model || '').trim();
    if (!provider) return;

    setAiProvider(provider);
    if (model) setAiModel(model);

    try {
      sessionStorage.setItem('radai_spec_ai_provider', provider);
      if (model) sessionStorage.setItem('radai_spec_ai_model', model);
    } catch (_) { /* ignore */ }
  }, [projectByok?.enabled, projectByok?.provider, projectByok?.model]);

  const isTerminal = useMemo(() => {
    if (!job) return false;
    return ['completed', 'failed', 'cancelled'].includes(job.status);
  }, [job]);

  // â”€â”€ Polling â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  useEffect(() => {
    if (!job || isTerminal) {
      if (pollRef.current) { clearInterval(pollRef.current); pollRef.current = null; }
      return undefined;
    }
    pollRef.current = setInterval(async () => {
      try {
        const updated = await specCustomizationAPI.getJob(job.id);
        setJob(updated);
        if (['completed', 'failed', 'cancelled'].includes(updated.status)) {
          const list = await specCustomizationAPI.getJobClasses(updated.id);
          setClasses(list);
        }
      } catch (e) {
        // swallow transient polling errors
      }
    }, PANEL_CONFIG.pollIntervalMs);
    return () => { if (pollRef.current) clearInterval(pollRef.current); };
  }, [job, isTerminal]);

  // On completion, fetch final class list (extra safety net).
  useEffect(() => {
    if (job && job.status === 'completed' && classes.length === 0) {
      specCustomizationAPI.getJobClasses(job.id).then(setClasses).catch(() => {});
    }
  }, [job, classes.length]);

  // Rotate the AI tip cards while the upload is in flight. Cycles soft-coded
  // `UPLOAD_UX_CONFIG.tips` every `tipRotateMs` until the upload completes.
  useEffect(() => {
    if (!uploading) return undefined;
    const id = setInterval(() => {
      setTipIndex((i) => (i + 1) % UPLOAD_UX_CONFIG.tips.length);
    }, UPLOAD_UX_CONFIG.tipRotateMs);
    return () => clearInterval(id);
  }, [uploading]);

  // Rotate AI-processing tips while a job is running (post-upload).
  useEffect(() => {
    const running = job && !['completed', 'failed', 'cancelled'].includes(job.status);
    if (!running) return undefined;
    const id = setInterval(() => {
      setProcTipIndex((i) => (i + 1) % PROCESSING_UX_CONFIG.tips.length);
    }, PROCESSING_UX_CONFIG.tipRotateMs);
    return () => clearInterval(id);
  }, [job]);

  // Build the effective accept list â€” prefer server config if present.
  const acceptedExts = useMemo(() => {
    return config?.accepted_extensions || SPEC_API_CONFIG.acceptedExts;
  }, [config]);
  const acceptAttr = useMemo(
    () => config?.accept_attribute || acceptedExts.map((e) => `.${e}`).join(','),
    [acceptedExts, config]
  );

  const fileFormat = useMemo(() => (file ? detectFormat(file.name) : null), [file]);

  const validateFile = useCallback((f) => {
    if (!f) return 'No file selected.';
    const { ext } = detectFormat(f.name);
    if (!ext) return 'File has no extension; cannot detect format.';
    if (!acceptedExts.includes(ext)) {
      return `\u201C.${ext}\u201D is not supported. Accepted: ${acceptedExts.join(', ')}.`;
    }
    const maxBytes = PANEL_CONFIG.maxFileSizeMB * 1024 * 1024;
    if (f.size > maxBytes) {
      return `File exceeds ${PANEL_CONFIG.maxFileSizeMB} MB limit.`;
    }
    return '';
  }, [acceptedExts]);

  // â”€â”€ Handlers â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const handleFilePick = (e) => {
    const f = e.target.files?.[0];
    setUploadError('');
    if (!f) return;
    const err = validateFile(f);
    if (err) { setUploadError(err); return; }
    setFile(f);
  };

  const handleDragOver = (e) => {
    e.preventDefault(); e.stopPropagation();
    if (!isDragging) setIsDragging(true);
  };
  const handleDragLeave = (e) => {
    e.preventDefault(); e.stopPropagation();
    setIsDragging(false);
  };
  const handleDrop = (e) => {
    e.preventDefault(); e.stopPropagation();
    setIsDragging(false);
    const f = e.dataTransfer?.files?.[0];
    if (!f) return;
    setUploadError('');
    const err = validateFile(f);
    if (err) { setUploadError(err); return; }
    setFile(f);
  };

  const handleUpload = useCallback(async () => {
    if (!file) return;
    setUploading(true);
    // Soft-coded global busy flag â€” pollers (NotificationBell, etc.) skip
    // their ticks while this is true so the backend worker stays free.
    if (typeof window !== 'undefined') window.__RADAI_HEAVY_OP = true;
    setUploadError('');
    setUploadProgress(0);
    setUploadSpeedBps(0);
    setUploadEtaSec(null);
    setUploadRoute(null);
    setTipIndex(0);
    uploadStartRef.current = Date.now();
    lastTickRef.current    = { t: uploadStartRef.current, loaded: 0 };
    setClasses([]);
    setExpandedClassId(null);
    try {
      // Mirror the dispatcher's decision so the UI can show the actual route
      // â€” purely cosmetic; the service layer remains the source of truth.
      const willPresign =
        SPEC_API_CONFIG.presignedUpload?.enabled &&
        file.size >= (SPEC_API_CONFIG.presignedUpload?.minSizeBytes || 0);
      setUploadRoute(willPresign ? 'presigned' : 'legacy');

      const resp = await specCustomizationAPI.upload({
        file,
        projectId,
        title: documentName.trim(),                    // BYOK: document name
        engineerName: engineerName.trim(),             // BYOK: engineer attribution
        userApiKey: userApiKey.trim(),                 // BYOK: user's API key (OpenAI or Claude)
        userAiProvider: aiProvider.trim(),             // BYOK: AI provider ("openai" or "claude")
        userAiModel: aiModel.trim(),                   // BYOK: AI model ID
        onUploadProgress: (evt) => {
          if (!evt.total) return;
          const pct = Math.round((evt.loaded / evt.total) * 100);
          setUploadProgress(pct);

          // Smoothed instantaneous speed (EMA) + ETA.
          const now = Date.now();
          const dt  = (now - lastTickRef.current.t) / 1000;
          if (dt > 0.15) {
            const inst    = (evt.loaded - lastTickRef.current.loaded) / dt;
            const smooth  = UPLOAD_UX_CONFIG.speedSmoothing;
            setUploadSpeedBps((prev) =>
              prev > 0 ? prev * (1 - smooth) + inst * smooth : inst);
            const remaining = Math.max(0, evt.total - evt.loaded);
            setUploadEtaSec(inst > 0 ? Math.round(remaining / inst) : null);
            lastTickRef.current = { t: now, loaded: evt.loaded };
          }
        },
      });
      setDocument(resp.document);
      setJob(resp.job);
      if (resp.deduped) {
        // Already completed â€” load classes immediately.
        const list = await specCustomizationAPI.getJobClasses(resp.job.id);
        setClasses(list);
      }
    } catch (e) {
      setUploadError(e?.response?.data?.error || e?.message || 'Upload failed');
    } finally {
      setUploading(false);
      if (typeof window !== 'undefined') window.__RADAI_HEAVY_OP = false;
    }
  }, [file]);

  const handleCancel = async () => {
    if (!job) return;
    try {
      await specCustomizationAPI.cancelJob(job.id);
      const refreshed = await specCustomizationAPI.getJob(job.id);
      setJob(refreshed);
    } catch (e) { /* ignore */ }
  };

  const handleReset = () => {
    setFile(null);
    setUploadProgress(0);
    setUploadError('');
    setJob(null);
    setDocument(null);
    setClasses([]);
    setExpandedClassId(null);
    setClassDetailCache({});
    setAsmeValidationCache({});
  };

  const handleExpandClass = async (cls) => {
    if (expandedClassId === cls.id) { setExpandedClassId(null); return; }
    setExpandedClassId(cls.id);
    if (!classDetailCache[cls.id]) {
      try {
        const detail = await specCustomizationAPI.getClass(cls.id);
        setClassDetailCache((m) => ({ ...m, [cls.id]: detail }));
      } catch (e) { /* ignore */ }
    }
    // Advisory ASME validation alongside the detail fetch (soft-coded toggle).
    if (ASME_VALIDATION_UI.enabled && (!asmeValidationCache[cls.id] || asmeValidationCache[cls.id].status === 'error')) {
      setAsmeValidationCache((m) => ({ ...m, [cls.id]: null }));
      try {
        const v = await specCustomizationAPI.getClassAsmeValidation(cls.id);
        setAsmeValidationCache((m) => ({ ...m, [cls.id]: v }));
      } catch (e) {
        setAsmeValidationCache((m) => ({ ...m, [cls.id]: { status: 'error', label: ASME_VALIDATION_UI.unavailableText } }));
      }
    }
  };

  const handleExportXlsx = async () => {
    if (!job) return;
    try {
      const blob = await specCustomizationAPI.exportJob(job.id, 'xlsx');
      downloadBlob(blob, `paper_spec_${job.id}.xlsx`);
    } catch (e) { /* ignore */ }
  };

  const handleExportJson = async () => {
    if (!job) return;
    try {
      const data = await specCustomizationAPI.exportJob(job.id, 'json');
      const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
      downloadBlob(blob, `paper_spec_${job.id}.json`);
    } catch (e) { /* ignore */ }
  };

  const handleExportSmartplantSpec = async () => {
    if (!job) return;
    try {
      const blob = await specCustomizationAPI.exportSmartplantSpec(job.id);
      downloadBlob(blob, `spec_customisation_${job.id}_SPEC.xlsx`);
    } catch (e) { /* ignore */ }
  };

  const handleExportSmartplantCat = async () => {
    if (!job) return;
    try {
      const blob = await specCustomizationAPI.exportSmartplantCat(job.id);
      downloadBlob(blob, `spec_customisation_${job.id}_CAT.xlsx`);
    } catch (e) { /* ignore */ }
  };

  // â”€â”€ Derived UI bits â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const statusMeta = job ? (STATUS_META[job.status] || STATUS_META.queued) : null;
  const progressPct = job?.progress_percent ?? 0;
  const livePhase   = job?.current_phase || job?.live_progress?.status || '';
  const partialCount = job?.live_progress?.classes_found ?? classes.length;

  // â”€â”€ Class aggregates (soft-coded; powers the stats strip) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
  const classAggregates = useMemo(() => {
    if (!classes.length) {
      return { totalClasses: 0, totalComponents: 0, uniqueMaterials: 0,
               uniqueRatings: 0, avgConfidence: null, ratingCounts: [] };
    }
    const materials = new Set();
    const ratings   = new Map();   // rating â†’ count
    let totalComponents = 0;
    let confSum = 0;
    let confN   = 0;
    classes.forEach((c) => {
      if (c.material_grade) materials.add(c.material_grade);
      if (c.pressure_rating) {
        ratings.set(c.pressure_rating, (ratings.get(c.pressure_rating) || 0) + 1);
      }
      totalComponents += (c.components_count || 0);
      if (typeof c.confidence_score === 'number') {
        confSum += c.confidence_score;
        confN   += 1;
      }
    });
    return {
      totalClasses:    classes.length,
      totalComponents,
      uniqueMaterials: materials.size,
      uniqueRatings:   ratings.size,
      avgConfidence:   confN ? confSum / confN : null,
      ratingCounts:    [...ratings.entries()].sort((a, b) => b[1] - a[1]),
    };
  }, [classes]);

  // Filtered class list â€” search text + active rating chip.
  const filteredClasses = useMemo(() => {
    const q = classSearch.trim().toLowerCase();
    if (!q && !ratingFilter) return classes;
    return classes.filter((c) => {
      if (ratingFilter && c.pressure_rating !== ratingFilter) return false;
      if (!q) return true;
      const blob = [
        c.class_code, c.class_full_code, c.material_grade,
        c.pressure_rating, c.flange_facing,
      ].filter(Boolean).join(' ').toLowerCase();
      return blob.includes(q);
    });
  }, [classes, classSearch, ratingFilter]);

  // New jobs and filters start at the first page; fewer results clamp the page below.
  useEffect(() => {
    setClassPage(1);
  }, [classSearch, ratingFilter, classPageSize, job?.id]);

  // Client-side pagination over the filtered classes (soft-coded config).
  const pagedClasses = useMemo(() => {
    if (!CLASS_LIST_PAGINATION_CONFIG.enabled) return filteredClasses;
    const start = (classPage - 1) * classPageSize;
    return filteredClasses.slice(start, start + classPageSize);
  }, [filteredClasses, classPage, classPageSize]);

  const classPageCount = CLASS_LIST_PAGINATION_CONFIG.enabled
    ? Math.max(1, Math.ceil(filteredClasses.length / classPageSize))
    : 1;

  useEffect(() => {
    setClassPage((page) => Math.min(page, classPageCount));
  }, [classPageCount]);

  // Look up the full colour band for a class's confidence score.
  const confidenceBandFor = useCallback((score) => {
    if (typeof score !== 'number') {
      return { className: 'bg-slate-300', stroke: 'stroke-slate-300', label: 'N/A', text: 'text-slate-500', bg: 'bg-slate-50' };
    }
    const band = CLASS_SUMMARY_CONFIG.confidenceBands.find((b) => score >= b.min);
    return band || { className: 'bg-slate-300', stroke: 'stroke-slate-300', label: 'N/A', text: 'text-slate-500', bg: 'bg-slate-50' };
  }, []);

  return (
    <div className="bg-white dark:bg-gray-800 rounded-lg shadow-sm border border-slate-200 dark:border-slate-700 overflow-hidden">
      {/* Header strip */}
      <div className="bg-slate-50 dark:bg-slate-900/40 border-b border-slate-200 dark:border-slate-700 px-4 py-3 flex items-center justify-between">
        <div className="flex items-center gap-3">
          <div className="p-1.5 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-md">
            <SparklesIcon className="w-5 h-5 text-blue-600 dark:text-blue-300" />
          </div>
          <div>
            <h2 className="text-sm font-semibold text-slate-900 dark:text-white">{PANEL_CONFIG.title}</h2>
            <p className="text-slate-500 dark:text-slate-400 text-xs">AI-powered Piping Spec extraction</p>
          </div>
        </div>
        {config && (
          <div className="hidden md:flex items-center gap-2 text-slate-500 dark:text-slate-400 text-xs bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 px-2.5 py-1.5 rounded-md">
            <Cog6ToothIcon className="w-4 h-4" />
            <span>chunk={config.chunk_size_pages}p | AI cap={config.max_ai_pages_per_job}p</span>
          </div>
        )}
      </div>

      <div className="p-4 space-y-4">
        <p className="text-sm text-slate-600 dark:text-slate-300 leading-relaxed">
          {PANEL_CONFIG.subtitle}
        </p>
        <ul className="grid sm:grid-cols-2 gap-x-6 gap-y-1 text-xs text-slate-600 dark:text-slate-400 list-disc pl-5">
          {PANEL_CONFIG.helperPoints.map((p) => <li key={p}>{p}</li>)}
        </ul>

        {/* â”€â”€ AI Document Assist (Wrench) â€” soft-coded, optional â”€â”€â”€â”€â”€â”€â”€ */}
        {SPEC_AI_ASSIST_CONFIG.enabled && !job && (
          <WrenchAiDocAssist
            title={SPEC_AI_ASSIST_CONFIG.title}
            subtitleTag={SPEC_AI_ASSIST_CONFIG.subtitleTag}
            subtitle={SPEC_AI_ASSIST_CONFIG.subtitle}
            defaultHint={SPEC_AI_ASSIST_CONFIG.defaultHint}
            hintPlaceholder={SPEC_AI_ASSIST_CONFIG.hintPlaceholder}
            topN={SPEC_AI_ASSIST_CONFIG.topN}
            acceptedExts={SPEC_AI_ASSIST_CONFIG.acceptedExts}
            projectName=""
            onFileSelected={(f) => {
              // Reuse the same validator the manual drop-zone uses so
              // size / extension errors surface identically.
              const err = validateFile(f);
              if (err) { setUploadError(err); return; }
              setUploadError('');
              setFile(f);
            }}
            onError={(msg) => setUploadError(msg)}
          />
        )}

        {/* â”€â”€ Upload zone â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
        {!job && (
          <div
            onDragOver={handleDragOver}
            onDragEnter={handleDragOver}
            onDragLeave={handleDragLeave}
            onDrop={handleDrop}
            className={`relative group border-2 border-dashed rounded-xl p-8 transition-all duration-300 ${
              isDragging
                ? 'border-blue-500 bg-blue-100/70 dark:bg-blue-900/30 scale-[1.01] shadow-lg shadow-blue-300/40'
                : 'border-blue-300 dark:border-blue-700 bg-blue-50/40 dark:bg-blue-900/10 hover:border-blue-400 hover:bg-blue-50/70'
            }`}
          >
            <div className="flex flex-col items-center text-center gap-3">
              {(() => {
                const Icon = fileFormat?.group ? (GROUP_ICONS[fileFormat.group] || CloudArrowUpIcon) : CloudArrowUpIcon;
                return <Icon className="w-12 h-12 text-blue-500" />;
              })()}
              <div>
                <p className="font-semibold text-slate-800 dark:text-slate-100">
                  {file ? file.name : 'Drop a Paper Spec here, or click to browse'}
                </p>
                <p className="text-xs text-slate-500 dark:text-slate-400 mt-1">
                  {file
                    ? fmtBytes(file.size)
                    : `Max ${PANEL_CONFIG.maxFileSizeMB} MB | ${acceptedExts.length} formats supported`}
                </p>
                {file && fileFormat?.meta && (
                  <div className="mt-2 inline-flex items-center gap-2 text-xs">
                    <span className={`px-2 py-0.5 rounded font-semibold ${fileFormat.meta.badge}`}>
                      {fileFormat.meta.label} Â· .{fileFormat.ext}
                    </span>
                    <span className="text-slate-500">{fileFormat.meta.hint}</span>
                  </div>
                )}
              </div>
              <input
                id="paper-spec-file"
                type="file"
                accept={acceptAttr}
                onChange={handleFilePick}
                className="hidden"
              />

              {/* BYOK (Server AI configuration) â€” optional attribution & custom API key fields */}
              {file && (
                <div className="mt-4 p-4 border border-slate-200 dark:border-slate-700 rounded-xl bg-slate-50 dark:bg-slate-900/50 space-y-3">
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                      Document Name <span className="text-slate-400 font-normal">(optional â€” helps identify this spec in history)</span>
                    </label>
                    <input
                      type="text"
                      value={documentName}
                      onChange={(e) => setDocumentName(e.target.value)}
                      placeholder="e.g. Q4 2026 Piping Spec Rev A"
                      className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm bg-white dark:bg-slate-800 dark:text-white"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1">
                      Spec Engineer <span className="text-slate-400 font-normal">(optional â€” for attribution)</span>
                    </label>
                    <input
                      type="text"
                      value={engineerName}
                      onChange={(e) => setEngineerName(e.target.value)}
                      placeholder="e.g. John Smith, Lead Piping Engineer"
                      className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent text-sm bg-white dark:bg-slate-800 dark:text-white"
                    />
                  </div>
                  
                  {/* BYOK: AI Provider & Model Selection */}
                  {byokConfig.enabled && (
                    <div className="space-y-3 p-4 bg-gradient-to-br from-purple-50 to-blue-50 dark:from-slate-900/20 dark:to-blue-900/20 rounded-lg border border-purple-200 dark:border-purple-800">
                      <div className="flex items-center gap-2 text-sm font-semibold text-purple-900 dark:text-purple-200">
                        <SparklesIcon className="w-4 h-4" />
                        <span>AI provider configuration</span>
                        <span className="text-xs font-normal text-purple-600 dark:text-purple-400">(Optional provider preference)</span>
                      </div>

                      {projectByok?.enabled && projectByok?.keyConfigured && (
                        <div className="text-xs rounded-md bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-200 dark:border-emerald-800 px-2.5 py-2 text-emerald-700 dark:text-emerald-300">
                          Project preference: {projectByok.provider || 'provider'} / {projectByok.model || 'default model'}. Credentials are resolved securely on the server.
                        </div>
                      )}
                      
                      {/* AI Provider Selection */}
                      <div>
                        <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">
                          AI Provider
                        </label>
                        <div className="grid grid-cols-2 gap-2">
                          <button
                            type="button"
                            onClick={() => {
                              setAiProvider('openai');
                              setAiModel('gpt-4o');
                              setUserApiKey('');
                              try {
                                sessionStorage.setItem('radai_spec_ai_provider', 'openai');
                                sessionStorage.setItem('radai_spec_ai_model', 'gpt-4o');
                                sessionStorage.removeItem('radai_spec_user_openai_key');
                                sessionStorage.removeItem('radai_spec_user_claude_key');
                              } catch (_) { /* Session storage is optional. */ }
                            }}
                            className={`px-4 py-3 rounded-lg border-2 transition-all text-left ${
                              aiProvider === 'openai'
                                ? 'border-emerald-500 bg-emerald-50 dark:bg-emerald-900/30'
                                : 'border-slate-200 dark:border-slate-700 hover:border-slate-300'
                            }`}
                          >
                            <div className="font-semibold text-sm text-slate-900 dark:text-white">OpenAI</div>
                            <div className="text-xs text-slate-600 dark:text-slate-400">GPT-4o models</div>
                          </button>
                          <button
                            type="button"
                            onClick={() => {
                              setAiProvider('claude');
                              setAiModel('claude-3-5-sonnet-20241022');
                              setUserApiKey('');
                              try {
                                sessionStorage.setItem('radai_spec_ai_provider', 'claude');
                                sessionStorage.setItem('radai_spec_ai_model', 'claude-3-5-sonnet-20241022');
                                sessionStorage.removeItem('radai_spec_user_openai_key');
                                sessionStorage.removeItem('radai_spec_user_claude_key');
                              } catch (_) { /* Session storage is optional. */ }
                            }}
                            className={`px-4 py-3 rounded-lg border-2 transition-all text-left ${
                              aiProvider === 'claude'
                                ? 'border-orange-500 bg-orange-50 dark:bg-orange-900/30'
                                : 'border-slate-200 dark:border-slate-700 hover:border-slate-300'
                            }`}
                          >
                            <div className="font-semibold text-sm text-slate-900 dark:text-white">Claude</div>
                            <div className="text-xs text-slate-600 dark:text-slate-400">Anthropic models</div>
                          </button>
                        </div>
                      </div>

                      {/* Model Selection */}
                      {aiProvider && (
                        <div>
                          <label className="block text-sm font-medium text-slate-700 dark:text-slate-300 mb-1.5">
                            Model Selection
                          </label>
                          <select
                            value={aiModel}
                            onChange={(e) => {
                              setAiModel(e.target.value);
                              try {
                                sessionStorage.setItem('radai_spec_ai_model', e.target.value);
                              } catch (_) { /* Session storage is optional. */ }
                            }}
                            className="w-full px-3 py-2 border border-slate-300 dark:border-slate-600 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-transparent text-sm bg-white dark:bg-slate-800 dark:text-white"
                          >
                            {(aiProvider === 'openai' ? byokConfig.openai_models : byokConfig.claude_models).map((model) => (
                              <option key={model.id} value={model.id}>
                                {model.label} {model.recommended ? 'â­' : ''} - {model.description}
                              </option>
                            ))}
                          </select>
                        </div>
                      )}

                      {/* API Key Input */}
                      {aiProvider && (
                        <PlatformAIStatus provider={aiProvider || "openai"} />
                      )}

                      {!aiProvider && (
                        <p className="text-xs text-slate-600 dark:text-slate-400 italic">
                          ðŸ‘† Select a supported provider above, or retain the server default. Credentials are managed by your administrator.
                        </p>
                      )}
                    </div>
                  )}
                </div>
              )}

              <div className="flex gap-2 flex-wrap justify-center">
                <label
                  htmlFor="paper-spec-file"
                  className="px-4 py-2 bg-white border border-blue-300 text-blue-700 rounded-lg text-sm font-medium hover:bg-blue-50 cursor-pointer"
                >
                  Choose File
                </label>
                {file && (
                  <button
                    onClick={() => { setFile(null); setUploadError(''); }}
                    className="px-3 py-2 bg-white border border-slate-300 text-slate-600 rounded-lg text-sm font-medium hover:bg-slate-50"
                  >
                    Clear
                  </button>
                )}
                <button
                  onClick={handleUpload}
                  disabled={!file || uploading}
                  className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white rounded-md text-sm font-semibold transition-colors disabled:opacity-50 disabled:cursor-not-allowed inline-flex items-center gap-1.5"
                >
                  <SparklesIcon className={`w-4 h-4 ${uploading ? 'animate-spin' : 'group-hover:animate-pulse'}`} />
                  {uploading ? 'Uploading...' : 'Extract with AI'}
                </button>
              </div>

              {/* Supported-format chips */}
              <div className="flex flex-wrap gap-1.5 justify-center pt-1">
                {Object.entries(SPEC_API_CONFIG.formatGroups).map(([key, g]) => (
                  <span
                    key={key}
                    className={`px-2 py-0.5 text-[10px] font-semibold rounded ${g.badge}`}
                    title={g.hint}
                  >
                    {g.label}
                  </span>
                ))}
              </div>

              {uploading && (
                <UploadConsole
                  file={file}
                  progress={uploadProgress}
                  speedBps={uploadSpeedBps}
                  etaSec={uploadEtaSec}
                  route={uploadRoute}
                  tipIndex={tipIndex}
                />
              )}
              {uploadError && (
                <p className="text-rose-600 text-sm flex items-center gap-1">
                  <ExclamationTriangleIcon className="w-4 h-4" /> {uploadError}
                </p>
              )}
            </div>
          </div>
        )}

        {/* â”€â”€ Job status â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
        {job && (
          <div className="border border-slate-200 dark:border-slate-700 rounded-xl p-5 bg-slate-50/60 dark:bg-slate-900/30">
            <div className="flex items-start justify-between gap-3 flex-wrap">
              <div className="flex items-center gap-3 min-w-0">
                <div className={`px-2.5 py-1 text-xs font-semibold rounded-md border ${statusMeta.color}`}>
                  {statusMeta.label}
                </div>
                <div className="min-w-0">
                  <p className="text-sm font-semibold text-slate-800 dark:text-slate-100 truncate">
                    {document?.original_filename || 'Document'}
                  </p>
                  <p className="text-xs text-slate-500 dark:text-slate-400">
                    {document?.total_pages || 0} pages | {fmtBytes(document?.file_size_bytes)}
                  </p>
                </div>
              </div>
              <div className="flex gap-2">
                {isTerminal && job.status === 'completed' && (
                  <>
                    <button
                      onClick={handleExportSmartplantSpec}
                      title="SmartPlant 3D â€” Piping Spec Rules workbook (25 sheets)"
                      className="px-3 py-1.5 text-xs font-semibold bg-indigo-50 text-indigo-700 border border-indigo-200 rounded-lg hover:bg-indigo-100 inline-flex items-center gap-1"
                    >
                      <DocumentArrowDownIcon className="w-4 h-4" /> SPEC.xlsx
                    </button>
                    <button
                      onClick={handleExportSmartplantCat}
                      title="SmartPlant 3D â€” Component Catalog workbook (23 sheets)"
                      className="px-3 py-1.5 text-xs font-semibold bg-blue-50 text-blue-700 border border-blue-200 rounded-lg hover:bg-blue-100 inline-flex items-center gap-1"
                    >
                      <DocumentArrowDownIcon className="w-4 h-4" /> CAT.xlsx
                    </button>
                    <button
                      onClick={handleExportXlsx}
                      className="px-3 py-1.5 text-xs font-semibold bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg hover:bg-emerald-100 inline-flex items-center gap-1"
                    >
                      <DocumentArrowDownIcon className="w-4 h-4" /> XLSX
                    </button>
                    <button
                      onClick={handleExportJson}
                      className="px-3 py-1.5 text-xs font-semibold bg-sky-50 text-sky-700 border border-sky-200 rounded-lg hover:bg-sky-100 inline-flex items-center gap-1"
                    >
                      <DocumentArrowDownIcon className="w-4 h-4" /> JSON
                    </button>
                  </>
                )}
                {!isTerminal && (
                  <button
                    onClick={handleCancel}
                    className="px-3 py-1.5 text-xs font-semibold bg-rose-50 text-rose-700 border border-rose-200 rounded-lg hover:bg-rose-100 inline-flex items-center gap-1"
                  >
                    <XMarkIcon className="w-4 h-4" /> Cancel
                  </button>
                )}
                {isTerminal && (
                  <button
                    onClick={handleReset}
                    className="px-3 py-1.5 text-xs font-semibold bg-slate-50 text-slate-700 border border-slate-200 rounded-lg hover:bg-slate-100 inline-flex items-center gap-1"
                  >
                    <ArrowPathIcon className="w-4 h-4" /> New
                  </button>
                )}
              </div>
            </div>

            {/* Progress bar */}
            <div className="mt-4">
              <div className="flex items-center justify-between text-xs text-slate-600 dark:text-slate-400 mb-1">
                <span>{livePhase || (isTerminal ? statusMeta.label : 'Starting...')}</span>
                <span>{progressPct}%</span>
              </div>
              <div className="w-full bg-slate-200 dark:bg-slate-700 rounded-full h-2 overflow-hidden">
                <div
                  className={`h-full transition-all ${
                    job.status === 'failed'    ? 'bg-rose-500' :
                    job.status === 'cancelled' ? 'bg-amber-500' :
                    job.status === 'completed' ? 'bg-emerald-500' :
                    'bg-gradient-to-r from-blue-500 to-rose-500 animate-pulse'
                  }`}
                  style={{ width: `${progressPct}%` }}
                />
              </div>
              <div className="mt-2 grid grid-cols-3 gap-2 text-xs text-slate-500">
                <div>Chunks: {job.chunks_done}/{job.chunks_total}</div>
                <div>Pages: {job.pages_processed}</div>
                <div>Classes: {partialCount}</div>
              </div>
            </div>

            {/* Animated AI-processing insights (hidden when job is finished). */}
            {job && !isTerminal && (
              <ProcessingConsole
                job={job}
                partialCount={partialCount}
                tipIndex={procTipIndex}
              />
            )}

            {job.error_message && (
              <div className="mt-3 p-2 bg-rose-50 border border-rose-200 rounded text-xs text-rose-700">
                {job.error_message}
              </div>
            )}
          </div>
        )}

        {/* â”€â”€ Extracted classes / Workbook Canvas â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
        {job?.status === 'completed' && (
          <div className="space-y-4">
            {/* â”€â”€ View tabs (Piping Classes â‡„ Workbook Canvas) â”€â”€â”€â”€â”€â”€ */}
            <div className="flex flex-wrap items-center gap-2">
              {[
                { key: 'classes', label: 'Piping Classes',  hint: 'Extracted spec cards' },
                { key: 'canvas',  label: 'Workbook Canvas', hint: 'Cross-check & edit SPEC / CAT data' },
              ].map((tab) => (
                <button
                  key={tab.key}
                  onClick={() => setActiveView(tab.key)}
                  className={`px-3.5 py-1.5 text-xs font-semibold rounded-full border transition ${
                    activeView === tab.key
                      ? 'bg-gradient-to-r from-blue-500 to-rose-500 text-white border-transparent shadow'
                      : 'bg-white dark:bg-slate-800 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-700 hover:border-blue-300 hover:text-blue-600'
                  }`}
                  title={tab.hint}
                >
                  {tab.label}
                </button>
              ))}
              {activeView === 'canvas' && (
                <span className="text-[11px] text-slate-500 dark:text-slate-400 italic">
                  Cell changes autosave and are included in the downloaded workbook.
                </span>
              )}
            </div>

            {activeView === 'canvas' ? (
              <WorkbookCanvas job={job} />
            ) : classes.length === 0 ? (
            <div className="rounded-xl border border-dashed border-amber-300 bg-amber-50/60 dark:bg-amber-900/10 dark:border-amber-700 px-6 py-10 text-center space-y-3">
              <div className="inline-flex items-center justify-center w-12 h-12 rounded-full bg-amber-100 dark:bg-amber-900/40 mb-1">
                <ExclamationTriangleIcon className="w-6 h-6 text-amber-500" />
              </div>
              <p className="text-base font-semibold text-slate-800 dark:text-slate-100">
                {CLASS_SUMMARY_CONFIG.emptyJobTitle}
              </p>
              <p className="text-sm text-slate-600 dark:text-slate-300 max-w-xl mx-auto leading-relaxed">
                {CLASS_SUMMARY_CONFIG.emptyJobMessage}
              </p>
            </div>
            ) : (
            <>
            {/* â”€â”€ 1. AI Insight Banner â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            <div className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 p-5 shadow-xl">
              {/* Animated glow blobs */}
              <div className="absolute -top-16 -left-16 w-64 h-64 bg-blue-500/20 rounded-full blur-3xl animate-pulse" />
              <div className="absolute -bottom-16 -right-16 w-64 h-64 bg-violet-500/20 rounded-full blur-3xl animate-pulse"
                   style={{ animationDelay: '1.5s' }} />
              {/* Grid pattern overlay */}
              <div
                className="absolute inset-0 opacity-10"
                style={{
                  backgroundImage: 'linear-gradient(rgba(255,255,255,0.4) 1px, transparent 1px), linear-gradient(90deg, rgba(255,255,255,0.4) 1px, transparent 1px)',
                  backgroundSize: '24px 24px',
                }}
              />
              <div className="relative">
                <div className="flex items-center gap-2 mb-2">
                  <span className="relative flex h-2 w-2">
                    <span className="absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75 animate-ping" />
                    <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-400" />
                  </span>
                  <span className="text-[10px] font-bold uppercase tracking-[0.25em] text-blue-300">
                    {CLASS_SUMMARY_CONFIG.aiBanner.eyebrow}
                  </span>
                </div>
                <h3 className="text-xl font-bold text-white mb-1 flex items-center gap-2">
                  <SparklesIcon className="w-5 h-5 text-blue-300" />
                  {CLASS_SUMMARY_CONFIG.aiBanner.title}
                </h3>
                <p className="text-sm text-slate-200 leading-relaxed max-w-3xl">
                  {CLASS_SUMMARY_CONFIG.aiBanner.insight(classAggregates).map((tok, i) => (
                    <span key={i} className={tok.tone ? CLASS_SUMMARY_CONFIG.highlightTones[tok.tone] : ''}>
                      {tok.text}
                    </span>
                  ))}
                </p>
              </div>
            </div>

            {/* â”€â”€ 2. KPI Card Strip (soft-coded) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-3">
              {CLASS_SUMMARY_CONFIG.stats.map((stat) => {
                const Icon  = stat.icon;
                const raw   = stat.compute(classAggregates);
                const value = stat.format(raw);
                const pct   = stat.barPct ? stat.barPct(classAggregates) : 0;
                return (
                  <div
                    key={stat.key}
                    className={`group relative overflow-hidden rounded-2xl p-4 bg-gradient-to-br ${stat.tone} text-white shadow-lg ${stat.glow} ring-1 ${stat.ring} transition-all duration-300 hover:scale-[1.03] hover:shadow-2xl`}
                  >
                    {/* Decorative giant icon */}
                    <Icon className="absolute -right-3 -bottom-3 w-20 h-20 opacity-10 group-hover:opacity-20 transition" />
                    {/* Diagonal sheen */}
                    <div className="absolute inset-0 bg-gradient-to-tr from-white/0 via-white/10 to-white/0 opacity-0 group-hover:opacity-100 transition-opacity" />
                    <div className="relative">
                      <div className="flex items-start justify-between">
                        <div className="p-1.5 bg-white/20 backdrop-blur-sm rounded-lg ring-1 ring-white/30">
                          <Icon className="w-4 h-4" />
                        </div>
                        {stat.pulse && (
                          <span className="px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wider bg-white/25 backdrop-blur-sm rounded-full animate-pulse">
                            AI
                          </span>
                        )}
                      </div>
                      <p className="mt-3 text-3xl font-extrabold leading-none tracking-tight tabular-nums">
                        {value}
                      </p>
                      <p className="mt-1.5 text-[11px] font-semibold uppercase tracking-wider opacity-95">
                        {stat.label}
                      </p>
                      <p className="text-[10px] opacity-75">{stat.sublabel}</p>
                      {/* Activity bar */}
                      <div className="mt-3 h-1 bg-black/20 rounded-full overflow-hidden">
                        <div
                          className="h-full bg-white/70 rounded-full transition-all duration-700"
                          style={{ width: `${Math.max(4, pct)}%` }}
                        />
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>

            {/* â”€â”€ 3. Filter / search bar â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            <div className="bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl p-3 space-y-2">
              <div className="flex items-center gap-2">
                <div className="relative flex-1">
                  <MagnifyingGlassIcon className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
                  <input
                    type="text"
                    value={classSearch}
                    onChange={(e) => setClassSearch(e.target.value)}
                    placeholder="Search by class code, material grade, rating, flange facingâ€¦"
                    className="w-full pl-9 pr-3 py-2 text-sm bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-300 focus:border-blue-400"
                  />
                </div>
                <span className="text-xs text-slate-500 dark:text-slate-400 whitespace-nowrap">
                  Showing <strong className="text-slate-700 dark:text-slate-200">{filteredClasses.length}</strong>
                  {' '}of {classes.length}
                </span>
              </div>

              {classAggregates.ratingCounts.length > 0 && (
                <div className="flex items-center gap-1.5 flex-wrap">
                  <span className="text-[10px] font-semibold uppercase tracking-wider text-slate-500 dark:text-slate-400 mr-1">
                    Rating:
                  </span>
                  <button
                    onClick={() => setRatingFilter(null)}
                    className={`px-2 py-0.5 text-[11px] font-semibold rounded-full border transition ${
                      !ratingFilter
                        ? 'bg-blue-600 text-white border-blue-600'
                        : 'bg-slate-100 dark:bg-slate-900 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-700 hover:bg-blue-50'
                    }`}
                  >
                    All
                  </button>
                  {classAggregates.ratingCounts
                    .slice(0, CLASS_SUMMARY_CONFIG.maxRatingChips)
                    .map(([rating, count]) => (
                      <button
                        key={rating}
                        onClick={() => setRatingFilter(ratingFilter === rating ? null : rating)}
                        className={`px-2 py-0.5 text-[11px] font-semibold rounded-full border transition ${
                          ratingFilter === rating
                            ? 'bg-blue-600 text-white border-blue-600'
                            : 'bg-slate-100 dark:bg-slate-900 text-slate-600 dark:text-slate-300 border-slate-200 dark:border-slate-700 hover:bg-blue-50'
                        }`}
                      >
                        {rating} <span className="opacity-70">Â· {count}</span>
                      </button>
                    ))}
                </div>
              )}
            </div>

            {/* â”€â”€ 4. Class cards â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€ */}
            {filteredClasses.length === 0 ? (
              <div className="border border-dashed border-slate-300 rounded-xl px-4 py-8 text-sm text-slate-500 dark:text-slate-400 text-center">
                {CLASS_SUMMARY_CONFIG.emptyFilterMessage}
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
                {pagedClasses.map((cls) => {
                  const expanded = expandedClassId === cls.id;
                  const detail = classDetailCache[cls.id];
                  const band   = confidenceBandFor(cls.confidence_score);
                  const score  = typeof cls.confidence_score === 'number' ? cls.confidence_score : null;
                  return (
                    <div
                      key={cls.id}
                      className={`group relative overflow-hidden rounded-xl border bg-white dark:bg-slate-800 transition-all duration-300 hover:shadow-lg ${
                        expanded
                          ? 'md:col-span-2 border-blue-300 shadow-lg ring-1 ring-blue-200'
                          : 'border-slate-200 dark:border-slate-700 hover:-translate-y-0.5'
                      }`}
                    >
                      {/* Left confidence rail */}
                      <span className={`absolute left-0 top-0 bottom-0 w-1.5 ${band.className}`} />
                      <button
                        onClick={() => handleExpandClass(cls)}
                        className="w-full text-left pl-5 pr-4 py-3"
                      >
                        <div className="flex items-start gap-3">
                          {/* Class code monogram */}
                          <div className="flex-shrink-0 w-12 h-12 rounded-lg bg-gradient-to-br from-blue-500 to-rose-600 text-white font-mono font-extrabold flex items-center justify-center shadow-md text-base">
                            {cls.class_code}
                          </div>

                          <div className="flex-1 min-w-0">
                            <div className="flex items-center justify-between gap-2">
                              <p className="text-sm font-semibold text-slate-800 dark:text-slate-100 truncate">
                                {cls.class_full_code || cls.material_grade || 'â€”'}
                              </p>
                              {score !== null && (
                                <div className="flex items-center gap-1 flex-shrink-0">
                                  {/* Mini radial confidence */}
                                  <svg className="w-7 h-7 -rotate-90" viewBox="0 0 32 32">
                                    <circle cx="16" cy="16" r="13" fill="none"
                                      className="stroke-slate-200 dark:stroke-slate-700" strokeWidth="3" />
                                    <circle cx="16" cy="16" r="13" fill="none"
                                      className={band.stroke}
                                      strokeWidth="3" strokeLinecap="round"
                                      strokeDasharray={`${2 * Math.PI * 13}`}
                                      strokeDashoffset={`${2 * Math.PI * 13 * (1 - score)}`} />
                                  </svg>
                                  <span className={`text-[11px] font-bold ${band.text}`}>
                                    {Math.round(score * 100)}%
                                  </span>
                                </div>
                              )}
                            </div>

                            {/* Meta chips */}
                            <div className="mt-1.5 flex flex-wrap items-center gap-1">
                              {cls.material_grade && (
                                <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-sky-50 text-sky-700 border border-sky-200 rounded">
                                  {cls.material_grade}
                                </span>
                              )}
                              {cls.pressure_rating && (
                                <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-amber-50 text-amber-800 border border-amber-200 rounded">
                                  {cls.pressure_rating}
                                </span>
                              )}
                              {cls.flange_facing && (
                                <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-violet-50 text-violet-700 border border-violet-200 rounded">
                                  {cls.flange_facing}
                                </span>
                              )}
                              {cls.source_pages?.length === 2 && (
                                <span className="px-1.5 py-0.5 text-[10px] font-semibold bg-slate-50 text-slate-600 border border-slate-200 rounded">
                                  p.{cls.source_pages[0]}â€“{cls.source_pages[1]}
                                </span>
                              )}
                              {/* ASME validation badge (advisory, soft-coded) */}
                              {ASME_VALIDATION_UI.enabled && asmeValidationCache[cls.id] && (() => {
                                const v = asmeValidationCache[cls.id];
                                const tone = ASME_VALIDATION_UI.statusTones[v.status] || ASME_VALIDATION_UI.statusTones.skipped;
                                return (
                                  <span
                                    className={`px-1.5 py-0.5 text-[10px] font-bold border rounded inline-flex items-center gap-1 ${tone.badge}`}
                                    title={v.label}
                                  >
                                    <ShieldCheckIcon className="w-3 h-3" />
                                    {ASME_VALIDATION_UI.badgePrefix} {v.status === 'pass' ? '✓' : v.status === 'fail' ? '✗' : '—'}
                                  </span>
                                );
                              })()}
                              <span className={`px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wider rounded ${band.bg} ${band.text}`}>
                                {band.label}
                              </span>
                            </div>

                            {/* Footer: components count + engine + expand hint */}
                            <div className="mt-2 flex items-center justify-between">
                              <div className="flex items-center gap-3 text-[11px] text-slate-500 dark:text-slate-400">
                                <span className="inline-flex items-center gap-1">
                                  <TableCellsIcon className="w-3.5 h-3.5" />
                                  <strong className="text-slate-700 dark:text-slate-200">{cls.components_count}</strong>
                                  rows
                                </span>
                                <span className="inline-flex items-center gap-1">
                                  <SparklesIcon className="w-3.5 h-3.5 text-blue-500" />
                                  {cls.extraction_engine || 'AI'}
                                </span>
                              </div>
                              <span className="text-[10px] font-semibold text-blue-600 dark:text-blue-300 group-hover:translate-x-0.5 transition-transform inline-flex items-center gap-0.5">
                                {expanded ? 'Collapse' : 'Open detail'}
                                {expanded ? <ChevronDownIcon className="w-3 h-3" /> : <ChevronRightIcon className="w-3 h-3" />}
                              </span>
                            </div>
                          </div>
                        </div>
                      </button>

                      {/* Expanded detail */}
                      {expanded && (
                        <div className="border-t border-blue-200 bg-gradient-to-b from-blue-50/40 to-white dark:from-slate-900/40 dark:to-slate-800 px-4 py-3">
                          {!detail ? (
                            <div className="flex items-center gap-2 text-xs text-slate-500 italic">
                              <ArrowPathIcon className="w-3.5 h-3.5 animate-spin" />
                              Loading detailâ€¦
                            </div>
                          ) : (
                            <ClassDetailPanel cls={detail} asme={asmeValidationCache[cls.id]} />
                          )}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            )}

            {/* ─── 5. Class-list pagination controls (soft-coded) ─── */}
            {CLASS_LIST_PAGINATION_CONFIG.enabled && filteredClasses.length > 0 && (
              <div className="flex flex-wrap items-center justify-between gap-2 border border-slate-200 dark:border-slate-700 rounded-xl px-3 py-2 bg-white dark:bg-slate-800">
                <div className="flex items-center gap-2">
                  <button
                    onClick={() => setClassPage((p) => Math.max(1, p - 1))}
                    disabled={classPage <= 1}
                    className="px-2.5 py-1 text-xs font-semibold rounded-md border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-blue-50 disabled:opacity-40 disabled:cursor-not-allowed"
                  >
                    {CLASS_LIST_PAGINATION_CONFIG.labels.previous}
                  </button>
                  <button
                    onClick={() => setClassPage((p) => Math.min(classPageCount, p + 1))}
                    disabled={classPage >= classPageCount}
                    className="px-2.5 py-1 text-xs font-semibold rounded-md border border-slate-200 dark:border-slate-700 text-slate-600 dark:text-slate-300 hover:bg-blue-50 disabled:opacity-40 disabled:cursor-not-allowed"
                  >
                    {CLASS_LIST_PAGINATION_CONFIG.labels.next}
                  </button>
                  <span className="text-xs text-slate-500 dark:text-slate-400">
                    {CLASS_LIST_PAGINATION_CONFIG.labels.pagePrefix}{' '}
                    <strong className="text-slate-700 dark:text-slate-200">{classPage}</strong>
                    {' '}/ {classPageCount}
                  </span>
                </div>
                <label className="flex items-center gap-1.5 text-xs text-slate-500 dark:text-slate-400">
                  Per page
                  <select
                    value={classPageSize}
                    onChange={(e) => setClassPageSize(Number(e.target.value))}
                    className="px-1.5 py-1 text-xs bg-slate-50 dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-300"
                  >
                    {CLASS_LIST_PAGINATION_CONFIG.pageSizeOptions.map((n) => (
                      <option key={n} value={n}>{n}</option>
                    ))}
                  </select>
                </label>
              </div>
            )}
            </>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

// â”€â”€â”€ Subcomponent: per-class detail (soft-coded sections) â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€â”€
const SectionHeader = ({ icon: Icon, title, accent, count }) => (
  <div className="flex items-center gap-2 mb-2">
    <span className={`inline-flex items-center justify-center w-6 h-6 rounded-md bg-gradient-to-br ${accent} text-white shadow-sm`}>
      <Icon className="w-3.5 h-3.5" />
    </span>
    <h4 className="text-xs font-bold uppercase tracking-[0.15em] text-slate-700 dark:text-slate-200">
      {title}
    </h4>
    {typeof count === 'number' && (
      <span className="px-1.5 py-0.5 text-[10px] font-bold bg-slate-100 dark:bg-slate-700 text-slate-600 dark:text-slate-300 rounded-full">
        {count}
      </span>
    )}
    <div className={`flex-1 h-px bg-gradient-to-r ${accent} opacity-30`} />
  </div>
);

const ClassDetailPanel = ({ cls, asme }) => {
  if (!cls) return null;
  const sections = DETAIL_CONFIG.sections.filter((s) => s.visible(cls));

  if (sections.length === 0) {
    return (
      <p className="text-xs text-slate-500 italic">No additional detail captured for this class.</p>
    );
  }

  const renderBody = (key) => {
    if (key === 'services') {
      return (
        <div className="flex flex-wrap gap-1">
          {(cls.service_list || []).map((s, i) => (
            <span
              key={`${s}-${i}`}
              className="px-2 py-1 text-xs font-medium bg-gradient-to-r from-blue-50 to-slate-50 text-blue-700 border border-blue-200 rounded-full shadow-sm"
            >
              {s}
            </span>
          ))}
        </div>
      );
    }
    if (key === 'pt') {
      const rows = cls.pt_rating_table || [];
      return (
        <div className="overflow-x-auto rounded-lg border border-slate-200 dark:border-slate-700">
          <table className="text-xs w-full">
            <thead>
              <tr className="bg-gradient-to-r from-emerald-50 to-teal-50 dark:from-slate-700 dark:to-slate-700">
                <th className="px-3 py-2 text-left font-bold text-emerald-800 dark:text-emerald-200">Pressure (bar-g)</th>
                <th className="px-3 py-2 text-left font-bold text-emerald-800 dark:text-emerald-200">Temperature (Â°C)</th>
