  TEMPLATE_COLUMNS, 
  SECTION_COLORS,
  FIELD_INPUT_CONFIG,
  getEmptyTemplateData 
} from '../../../config/electricalChecklistTemplate.config';

// SOFT-CODED: Page Configuration
const PAGE_CONFIG = {
  title: 'Electrical Checklist Projects',
  subtitle: 'Professional project-based checklist management with AWS S3 storage',
  backRoute: '/engineering/electrical',
  backText: 'Back to Electrical Engineering',
  showProjectSelector: true,
  enableQuickUpload: true
};

// SOFT-CODED: number of decimal places shown for the OpenAI Vision API cost
// (backend computes the exact value from real token usage; kept to 4 places
// since per-job cost is typically well under $1).
const CHECKLIST_COST_DECIMAL_PLACES = 4;

const formatChecklistCost = (costUsd) => {
  const cost = Number(costUsd) || 0;
  if (cost <= 0) return 'Free (OCR)';
  return `$${cost.toFixed(CHECKLIST_COST_DECIMAL_PLACES)}`;
};

const ElectricalCheckList = () => {
  const navigate = useNavigate();
  const fileInputRef = useRef(null);

  // Project state
  const [projects, setProjects] = useState([]);
  const [selectedProject, setSelectedProject] = useState(null);
  const [showCreateProject, setShowCreateProject] = useState(false);
  const [loadingProjects, setLoadingProjects] = useState(true);
  const [newProjectData, setNewProjectData] = useState({
    project_name: '',
    description: '',
    location: '',
    client_name: '',
    template_id: 'ups_battery_standard',
    settings: {
      extract_signatures: true,
      require_approval: false,
      auto_generate_excel: true,
      s3_storage: true
    },
    tags: []
  });

  // Upload state management
  const [selectedFiles, setSelectedFiles] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [extractionStage, setExtractionStage] = useState('');
  const [extractionResult, setExtractionResult] = useState(null);
  const [error, setError] = useState(null);
  const [jobId, setJobId] = useState(null);

  // Checklist history — previously extracted/saved checklists for the
  // selected project so an inspection engineer can revisit and download them.
  const [projectChecklists, setProjectChecklists] = useState([]);
  const [loadingChecklists, setLoadingChecklists] = useState(false);
  const [viewingHistoryJobId, setViewingHistoryJobId] = useState(null);

  // BYOK — user-supplied OpenAI API key (optional). Never sent anywhere except
  // to our own /extract-handwriting/ endpoint; never persisted server-side.
  const platformAI = useAIProviderStatus('openai');
  const [userApiKey, setUserApiKey] = useState(() => {
    try {
      const cfg = EXTRACTION_CONFIG.handwriting;
      if (cfg?.allowUserApiKey && cfg?.apiKeyStorage === 'session') {
        return null || '';
      }
    } catch (_) { /* ignore */ }
    return '';
  });
  const [showApiKey, setShowApiKey] = useState(false);
  const [engineerName, setEngineerName] = useState('');
  // Optional label so an inspection engineer can tell checklists apart in
  // project history (e.g. "Q1 Site Visit"). Backend falls back to an
  // auto-generated name (Checklist #<id> — <date>) when left blank.
  const [checklistName, setChecklistName] = useState('');

  // Soft-coded extraction mode (Fast / Balanced / Deep / Vision-Only).
  // Persisted per-browser via localStorage so user's preference sticks.
  const [extractionMode, setExtractionMode] = useState(() => {
    try {
      const cfg = EXTRACTION_CONFIG.handwriting || {};
      const stored = localStorage.getItem(cfg.modeStorageKey);
      const validIds = (cfg.modes || []).map(m => m.id);
      if (stored && validIds.includes(stored)) return stored;
      return cfg.defaultMode || 'balanced';
    } catch (_) {
      return 'balanced';
    }
  });

  // Checklist data state
  const [checklistData, setChecklistData] = useState({});
  const [viewMode, setViewMode] = useState('summary'); // 'summary' or 'detailed'
  const [expandedSections, setExpandedSections] = useState({});
  const [saving, setSaving] = useState(false);

  // Initialize checklist data on mount
  useEffect(() => {
    try {
      setChecklistData(getEmptyTemplateData());
    } catch (error) {
      console.error('Error initializing checklist data:', error);
      setChecklistData({});
    }
  }, []);

  // Load projects on mount
  useEffect(() => {
    fetchProjects();
  }, []);

  // Expand first section when switching to detailed view
  useEffect(() => {
    if (viewMode === 'detailed' && TEMPLATE_SECTIONS.length > 0) {
      // Expand first section by default if none are expanded
      if (Object.keys(expandedSections).length === 0) {
        setExpandedSections({ [TEMPLATE_SECTIONS[0].id]: true });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [viewMode]);

  // Fetch the checklist history (previously extracted/saved jobs) for a project.
  // Soft-coded: reuses PROJECT_ENDPOINTS.checklists (already routes to the
  // existing GET /projects/{id}/checklists/ backend action — no new endpoint).
  const fetchProjectChecklists = async (projectId) => {
    if (!projectId) return;
    try {
      setLoadingChecklists(true);
      const response = await apiClient.get(`${PROJECT_ENDPOINTS.checklists}${projectId}/checklists/`);
      if (response.data.success) {
        setProjectChecklists(response.data.checklists || []);
      }
    } catch (err) {
      console.error('Error loading checklist history:', err);
    } finally {
      setLoadingChecklists(false);
    }
  };

  // Load project history whenever a project is opened.
  useEffect(() => {
    if (selectedProject?.id) {
      fetchProjectChecklists(selectedProject.id);
    } else {
      setProjectChecklists([]);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedProject?.id]);

  // Open a previously extracted/saved checklist from history into the detail view.
  const handleViewHistoryChecklist = async (job) => {
    try {
      setError(null);
      setViewingHistoryJobId(job.id);
      const response = await apiClient.get(`${EXTRACTION_CONFIG.endpoints.result}${job.id}/result/`);

      if (!response.data.success) {
        throw new Error(response.data.message || 'Failed to load checklist');
      }

      const result = response.data.result || {};
      const summary = result.summary || {};

      setJobId(job.id);
      setExtractionResult({
        fields_extracted:   summary.fields_extracted   ?? job.fields_extracted   ?? 0,
        sections_completed: summary.sections_completed ?? 0,
        signatures_found:   summary.signatures_found   ?? job.signatures_found   ?? 0,
        confidence_score:   summary.confidence_score   ?? job.confidence_score   ?? 0,
        checklist_data:     result.checklist_data || {},
        sources:            result.sources,
        key_source:         result.key_source,
        key_status:         result.key_status,
        summary,
      });
      setChecklistData(prev => ({ ...prev, ...(result.checklist_data || {}) }));
      setChecklistName(result.checklist_name || job.checklist_name || '');
      setViewMode('detailed');
    } catch (err) {
      console.error('Error opening historical checklist:', err);
      setError(err.response?.data?.message || err.message || 'Failed to load checklist history');
    } finally {
      setViewingHistoryJobId(null);
    }
  };

  // Download Excel for a specific historical job without first opening it.
  const handleDownloadHistoryExcel = async (job) => {
    await handleDownloadExcel(job.id);
  };

  // Fetch user's projects
  const fetchProjects = async () => {
    try {
      setLoadingProjects(true);
      const response = await apiClient.get(PROJECT_ENDPOINTS.list);
      
      if (response.data.success) {
        setProjects(response.data.projects);
        
        // Auto-select first project if available
        if (response.data.projects.length > 0 && !selectedProject) {
          setSelectedProject(response.data.projects[0]);
        }
      }
    } catch (err) {
      console.error('Error loading projects:', err);
      setError('Failed to load projects');
    } finally {
      setLoadingProjects(false);
    }
  };

  // Create new project
  const handleCreateProject = async () => {
    const trimmedName = newProjectData.project_name.trim();
    if (!trimmedName) {
      setError('Project name is required');
      return;
    }
    if (trimmedName.length < PROJECT_NAME_MIN_LENGTH) {
      setError(`Project name must be at least ${PROJECT_NAME_MIN_LENGTH} characters long`);
      return;
    }
    if (trimmedName.length > PROJECT_NAME_MAX_LENGTH) {
      setError(`Project name cannot exceed ${PROJECT_NAME_MAX_LENGTH} characters`);
      return;
    }

    try {
      const response = await apiClient.post(PROJECT_ENDPOINTS.create, { ...newProjectData, project_name: trimmedName });
      
      if (response.data.success) {
        setProjects(prev => [response.data.project, ...prev]);
        setSelectedProject(response.data.project);
        setShowCreateProject(false);
        setNewProjectData({
          project_name: '',
          description: '',
          location: '',
          client_name: '',
          template_id: 'ups_battery_standard',
          settings: {
            extract_signatures: true,
            require_approval: false,
            auto_generate_excel: true,
            s3_storage: true
          },
          tags: []
        });
        setError(null);
      }
    } catch (err) {
      console.error('Error creating project:', err);
      const fieldErrors = err.response?.data?.errors;
      const firstFieldError = fieldErrors && Object.values(fieldErrors)[0]?.[0];
      setError(firstFieldError || err.response?.data?.message || 'Failed to create project');
    }
  };

  // Drag and drop handlers
  const handleDragOver = (e) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    
    const files = Array.from(e.dataTransfer.files).filter(file => 
      file.type === 'application/pdf'
    );
    
    if (files.length === 0) {
      setError('Please upload PDF files only');
      return;
    }
    
    if (files.length > EXTRACTION_CONFIG.upload.maxFiles) {
      setError(`Maximum ${EXTRACTION_CONFIG.upload.maxFiles} files allowed`);
      return;
    }
    
    setSelectedFiles(files);
    setError(null);
    setExtractionResult(null);
  };

  const handleFileSelect = (e) => {
    const files = Array.from(e.target.files).filter(file => 
      file.type === 'application/pdf'
    );
    
    if (files.length > 0) {
      setSelectedFiles(files);
      setError(null);
      setExtractionResult(null);
    }
  };

  const handleRemoveFile = (index) => {
    setSelectedFiles(prev => prev.filter((_, i) => i !== index));
  };

  // AI Extraction handler
  const handleExtract = async () => {
    if (selectedFiles.length === 0) {
      setError('Please select at least one PDF file');
      return;
    }

    if (!selectedProject) {
      setError('Please select a project first');
      return;
    }

    setUploading(true);
    setUploadProgress(0);
    setError(null);
    setExtractionStage(UI_CONFIG.extractionStages[0]);

    // Soft-coded: use handwriting pipeline (synchronous) when enabled, else legacy async endpoint.
    const hwCfg = EXTRACTION_CONFIG.handwriting || {};
    const useHandwriting = hwCfg.enabled === true;

    try {
      const formData = new FormData();
      selectedFiles.forEach((file, index) => {
        formData.append(`file_${index}`, file);
      });
      formData.append('template_id', CHECKLIST_TEMPLATE.id);
      formData.append('extract_signatures', EXTRACTION_CONFIG.ocr.extractSignatures);
      formData.append('project_id', selectedProject.id);
      if (checklistName?.trim()) {
        formData.append('checklist_name', checklistName.trim());
      }

      if (useHandwriting) {
        if (engineerName?.trim()) {
          formData.append('engineer_name', engineerName.trim());
        }
        // Soft-coded extraction mode (fast / balanced / deep / vision_only).
        if (extractionMode) {
          formData.append('extraction_mode', extractionMode);
          try { localStorage.setItem(hwCfg.modeStorageKey, extractionMode); } catch (_) {}
        }
        // BYOK — only sent if user provided a key AND config allows it.
        if (hwCfg.allowUserApiKey && userApiKey?.trim()) {
          formData.append('openai_api_key', userApiKey.trim());
          if (hwCfg.apiKeyStorage === 'session') {
            try { undefined; } catch (_) {}
          }
        }
      }

      setExtractionStage(UI_CONFIG.extractionStages[1]);
      setUploadProgress(20);

      const endpoint = useHandwriting
        ? EXTRACTION_CONFIG.endpoints.uploadHandwriting
        : EXTRACTION_CONFIG.endpoints.upload;

      const response = await apiClient.post(endpoint, formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
        onUploadProgress: (progressEvent) => {
          const progress = Math.round((progressEvent.loaded * 100) / progressEvent.total);
          setUploadProgress(Math.min(progress, 90));
        },
      });

      if (!response.data.success) {
        throw new Error(response.data.message || 'Extraction failed');
      }

      setJobId(response.data.job_id);

      // Handwriting endpoint is synchronous — result is in the response body.
      if (useHandwriting && response.data.checklist_data) {
        setUploadProgress(100);
        setExtractionStage(UI_CONFIG.extractionStages[UI_CONFIG.extractionStages.length - 1]);

        const summary = response.data.summary || {};
        setExtractionResult({
          fields_extracted:   summary.fields_extracted   || 0,
          sections_completed: summary.sections_completed || 0,
          signatures_found:   summary.signatures_found   || 0,
          confidence_score:   summary.confidence_score   || 0,
          checklist_data:     response.data.checklist_data,
          sources:            response.data.sources,
          key_source:         response.data.key_source,
          key_status:         response.data.key_status,
          summary,
        });

        // Auto-populate the 6-column detailed template with extracted values.
        setChecklistData(prev => ({ ...prev, ...response.data.checklist_data }));
        setViewMode('detailed');

        setUploading(false);
        setExtractionStage('');

        if (selectedProject) {
          fetchProjects();
          fetchProjectChecklists(selectedProject.id);
        }
      } else {
        // Legacy async path — poll for status.
        pollExtractionStatus(response.data.job_id);
      }

    } catch (err) {
      console.error('Extraction error:', err);
      setError(err.response?.data?.message || err.message || 'Failed to extract checklist data');
      setUploading(false);
      setExtractionStage('');
    }
  };

  // Poll extraction status
  const pollExtractionStatus = async (jobId) => {
    let attempts = 0;
    const maxAttempts = EXTRACTION_CONFIG.polling.maxAttempts;

    const poll = setInterval(async () => {
      attempts++;
      
      if (attempts > maxAttempts) {
        clearInterval(poll);
        setError('Extraction timeout - please try again');
        setUploading(false);
        setExtractionStage('');
        return;
      }

      try {
        const response = await apiClient.get(`${EXTRACTION_CONFIG.endpoints.status}${jobId}/status/`);
        
        if (response.data.status === 'completed') {
          clearInterval(poll);
          setExtractionStage(UI_CONFIG.extractionStages[5]);
          setUploadProgress(100);
          setExtractionResult(response.data.result);
          setUploading(false);
          setExtractionStage('');
          
          // Refresh project statistics
          if (selectedProject) {
            fetchProjects();
          }
        } else if (response.data.status === 'failed') {
          clearInterval(poll);
          setError(response.data.error || 'Extraction failed');
          setUploading(false);
          setExtractionStage('');
        } else {
          // Update stage based on progress
          const stageIndex = Math.min(
            Math.floor((response.data.progress / 100) * UI_CONFIG.extractionStages.length),
            UI_CONFIG.extractionStages.length - 1
          );
          setExtractionStage(UI_CONFIG.extractionStages[stageIndex]);
          setUploadProgress(response.data.progress);
        }
      } catch (err) {
        console.error('Polling error:', err);
        clearInterval(poll);
        setError('Failed to check extraction status');
        setUploading(false);
        setExtractionStage('');
      }
    }, EXTRACTION_CONFIG.polling.intervalMs);
  };

  // Download Excel
  // SOFT-CODED: the backend may respond in two shapes depending on whether S3
  // storage is enabled for the project:
  //  1) Binary .xlsx bytes (S3 disabled / upload failed → direct FileResponse)
  //  2) JSON { success, download_url, ... } (S3 enabled → presigned URL)
  // We detect which one we got from the blob's content-type and handle both,
  // instead of assuming the raw response body is always the spreadsheet.
  //
  // Accepts an optional `targetJobId` so the checklist history list can
  // trigger a download for any past job without first "opening" it into the
  // detail view. Falls back to the currently open job's id (existing usage).
  const handleDownloadExcel = async (targetJobId) => {
    const downloadJobId = targetJobId || jobId;
    if (!downloadJobId) return;

    try {
      const response = await apiClient.get(
        `${EXTRACTION_CONFIG.endpoints.download}${downloadJobId}/download-excel/`,
        { responseType: 'blob' }
      );

      const blob = response.data;
      const contentType = (blob?.type || response.headers?.['content-type'] || '').toLowerCase();

      if (contentType.includes('application/json')) {
        // Backend returned a presigned S3 URL as JSON, not the file itself.
        const text = await blob.text();
        let payload;
        try {
          payload = JSON.parse(text);
        } catch (parseErr) {
          throw new Error('Server returned an unexpected response while preparing the Excel file');
        }

        if (!payload.success || !payload.download_url) {
          throw new Error(payload.error || payload.message || 'Failed to prepare Excel file');
        }

        const link = document.createElement('a');
        link.href = payload.download_url;
        link.setAttribute('download', `checklist_${downloadJobId}.xlsx`);
        link.rel = 'noopener noreferrer';
        document.body.appendChild(link);
        link.click();
        link.remove();
        return;
      }

      // Raw binary .xlsx — download directly.
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `checklist_${downloadJobId}.xlsx`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Download error:', err);
      setError(err.message || 'Failed to download Excel file');
    }
  };

  // Reset form
  const handleReset = () => {
    setSelectedFiles([]);
    setExtractionResult(null);
    setError(null);
    setJobId(null);
    setUploadProgress(0);
    setExtractionStage('');
    setViewMode('summary');
    setChecklistData(getEmptyTemplateData());
    setChecklistName('');
  };

  // Update checklist field value
  const updateFieldValue = (fieldId, column, value) => {
    setChecklistData(prev => ({
      ...prev,
      [fieldId]: {
        ...prev[fieldId],
        [column]: value
      }
    }));
  };

  // Toggle section expansion
  const toggleSection = (sectionId) => {
    setExpandedSections(prev => ({
      ...prev,
      [sectionId]: !prev[sectionId]
    }));
  };

  // Expand all sections
  const expandAllSections = () => {
    const allExpanded = {};
    TEMPLATE_SECTIONS.forEach(section => {
      allExpanded[section.id] = true;
    });
    setExpandedSections(allExpanded);
  };

  // Collapse all sections
  const collapseAllSections = () => {
    setExpandedSections({});
  };

  // Save checklist data
  const handleSaveChecklist = async () => {
    if (!selectedProject) {
      await radaiAlert('Please select a project first');
      return;
    }
    if (!jobId) {
      await radaiAlert('No extraction job to save yet — please extract data first');
      return;
    }

    try {
      setSaving(true);

      // NOTE: PROJECT_ENDPOINTS.detail is a base path string (not a function) —
      // append the project id + action, matching the pattern used across this file.
      const response = await apiClient.post(
        `${PROJECT_ENDPOINTS.detail}${selectedProject.id}/save-checklist/`,
        {
          checklist_data: checklistData,
          job_id: jobId,
          checklist_name: checklistName?.trim() || undefined
        }
      );

      if (response.data.success) {
        await radaiAlert('Checklist saved successfully!');
        if (selectedProject) fetchProjectChecklists(selectedProject.id);
      } else {
        await radaiAlert(response.data.message || 'Failed to save checklist');
      }
    } catch (err) {
      console.error('Save error:', err);
      await radaiAlert(err.response?.data?.message || 'Failed to save checklist');
    } finally {
      setSaving(false);
    }
  };

  // Render field input based on type
  const renderFieldInput = (field, fieldId, column, value) => {
    if (!TEMPLATE_COLUMNS.find(col => col.key === column)?.editable) {
      // Non-editable column (field_name)
      return <span className="font-medium text-gray-900">{value}</span>;
    }

    const inputConfig = FIELD_INPUT_CONFIG[field.type] || FIELD_INPUT_CONFIG.text;
    const inputProps = inputConfig.props || {};
    
    if (inputConfig.component === 'select' && field.options) {
      return (
        <select
          value={value || ''}
          onChange={(e) => updateFieldValue(fieldId, column, e.target.value)}
          {...inputProps}
        >
          <option value="">Select...</option>
          {field.options.map(option => (
            <option key={option} value={option}>{option}</option>
          ))}
        </select>
      );
    } else if (inputConfig.component === 'textarea') {
      return (
        <textarea
          value={value || ''}
          onChange={(e) => updateFieldValue(fieldId, column, e.target.value)}
          {...inputProps}
        />
      );
    } else {
      return (
        <input
          value={value || ''}
          onChange={(e) => updateFieldValue(fieldId, column, e.target.value)}
          {...inputProps}
        />
      );
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 via-yellow-50 to-blue-50 p-6">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <button
            onClick={() => navigate(PAGE_CONFIG.backRoute)}
            className="flex items-center gap-2 text-gray-600 hover:text-gray-900 mb-4 transition-colors"
          >
            <ArrowLeftIcon className="h-5 w-5" />
            {PAGE_CONFIG.backText}
          </button>

          <div className="flex items-center gap-4 mb-2">
            <div className="p-3 bg-gradient-to-br from-yellow-500 to-orange-500 rounded-xl shadow-lg">
              <DocumentCheckIcon className="h-8 w-8 text-white" />
            </div>
            <div>
              <h1 className="text-4xl font-bold text-gray-900">
                {PAGE_CONFIG.title}
              </h1>
              <p className="text-lg text-gray-600 mt-1">
                {PAGE_CONFIG.subtitle}
              </p>
            </div>
          </div>

          {/* Info Banner */}
          <div className="mt-4 bg-blue-50 border border-blue-200 rounded-xl p-4">
            <div className="flex items-start gap-3">
              <SparklesIcon className="h-5 w-5 text-blue-600 flex-shrink-0 mt-0.5" />
              <div className="flex-1">
                <h3 className="font-semibold text-blue-900 mb-1">AI-Powered Extraction</h3>
                <p className="text-sm text-blue-800">
                  Upload inspection checklist PDFs and let AI extract all field data automatically.
                  Template: <span className="font-semibold">{CHECKLIST_TEMPLATE.name}</span>
                </p>
                <div className="mt-2 flex gap-2 flex-wrap">
                  <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded-md text-xs font-medium">
                    {CHECKLIST_TEMPLATE.sections.length} Sections
                  </span>
                  <span className="px-2 py-1 bg-purple-100 text-purple-700 rounded-md text-xs font-medium">
                    Signature Detection
                  </span>
                  <span className="px-2 py-1 bg-green-100 text-green-700 rounded-md text-xs font-medium">
                    Excel Export
                  </span>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Create Project Modal */}
        {showCreateProject && (
          <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
            <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[90vh] overflow-y-auto">
              <div className="p-6 border-b border-gray-200">
                <div className="flex items-center justify-between">
                  <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-3">
                    <FolderPlusIcon className="h-7 w-7 text-yellow-500" />
                    Create New Checklist Project
                  </h2>
                  <button
                    onClick={() => setShowCreateProject(false)}
                    className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                  >
                    <XCircleIcon className="h-6 w-6 text-gray-500" />
                  </button>
                </div>
              </div>

              <div className="p-6 space-y-6">
                {/* Project Name */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Project Name <span className="text-red-500">*</span>
                  </label>
                  <input
                    type="text"
                    value={newProjectData.project_name}
                    onChange={(e) => setNewProjectData({ ...newProjectData, project_name: e.target.value })}
                    placeholder="e.g., Al-Ruwais UPS Inspection Q3 2026"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
                  />
                </div>

                {/* Description */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Description
                  </label>
                  <textarea
                    value={newProjectData.description}
                    onChange={(e) => setNewProjectData({ ...newProjectData, description: e.target.value })}
                    placeholder="Describe the project scope and objectives..."
                    rows={3}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
                  />
                </div>

                {/* Location & Client */}
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                      Location
                    </label>
                    <input
                      type="text"
                      value={newProjectData.location}
                      onChange={(e) => setNewProjectData({ ...newProjectData, location: e.target.value })}
                      placeholder="e.g., Abu Dhabi, UAE"
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 mb-2">
                      Client Name
                    </label>
                    <input
                      type="text"
                      value={newProjectData.client_name}
                      onChange={(e) => setNewProjectData({ ...newProjectData, client_name: e.target.value })}
                      placeholder="e.g., ADNOC"
                      className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
                    />
                  </div>
                </div>

                {/* Template Selection */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Project Template
                  </label>
                  <select
                    value={newProjectData.template_id}
                    onChange={(e) => setNewProjectData({ ...newProjectData, template_id: e.target.value })}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
                  >
                    {PROJECT_TEMPLATES.map((template) => (
                      <option key={template.id} value={template.id}>
                        {template.name}
                      </option>
                    ))}
                  </select>
                  <p className="mt-2 text-sm text-gray-500">
                    {PROJECT_TEMPLATES.find(t => t.id === newProjectData.template_id)?.description}
                  </p>
                </div>

                {/* Settings */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-3">
                    Project Settings
                  </label>
                  <div className="space-y-3">
                    <label className="flex items-center gap-3">
                      <input
                        type="checkbox"
                        checked={newProjectData.settings.extract_signatures}
                        onChange={(e) => setNewProjectData({
                          ...newProjectData,
                          settings: { ...newProjectData.settings, extract_signatures: e.target.checked }
                        })}
                        className="w-5 h-5 text-yellow-500 rounded focus:ring-yellow-500"
                      />
                      <span className="text-sm text-gray-700">Extract signatures from checklists</span>
                    </label>
                    <label className="flex items-center gap-3">
                      <input
                        type="checkbox"
                        checked={newProjectData.settings.require_approval}
                        onChange={(e) => setNewProjectData({
                          ...newProjectData,
                          settings: { ...newProjectData.settings, require_approval: e.target.checked }
                        })}
                        className="w-5 h-5 text-yellow-500 rounded focus:ring-yellow-500"
                      />
                      <span className="text-sm text-gray-700">Require approval for extracted data</span>
                    </label>
                    <label className="flex items-center gap-3">
                      <input
                        type="checkbox"
                        checked={newProjectData.settings.auto_generate_excel}
                        onChange={(e) => setNewProjectData({
                          ...newProjectData,
                          settings: { ...newProjectData.settings, auto_generate_excel: e.target.checked }
                        })}
                        className="w-5 h-5 text-yellow-500 rounded focus:ring-yellow-500"
                      />
                      <span className="text-sm text-gray-700">Auto-generate Excel reports</span>
                    </label>
                  </div>
                </div>

                {/* Tags */}
                <div>
                  <label className="block text-sm font-semibold text-gray-700 mb-2">
                    Tags (comma separated)
                  </label>
                  <input
                    type="text"
                    placeholder="e.g., UPS, Battery, Inspection"
                    onChange={(e) => {
                      const tags = e.target.value.split(',').map(t => t.trim()).filter(t => t);
                      setNewProjectData({ ...newProjectData, tags });
                    }}
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
                  />
                </div>

                {/* Error Message */}
                {error && (
                  <div className="p-4 bg-red-50 border border-red-200 rounded-lg">
                    <div className="flex items-center gap-2 text-red-800">
                      <XCircleIcon className="h-5 w-5" />
                      <span className="font-medium">{error}</span>
                    </div>
                  </div>
                )}
              </div>

              <div className="p-6 border-t border-gray-200 flex gap-4">
                <button
                  onClick={() => setShowCreateProject(false)}
                  className="flex-1 px-6 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-all font-semibold"
                >
                  Cancel
                </button>
                <button
                  onClick={handleCreateProject}
                  className="flex-1 px-6 py-3 bg-gradient-to-r from-yellow-500 to-orange-500 text-white rounded-lg hover:shadow-lg transition-all font-semibold"
                >
                  Create Project
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Project Management Section */}
        {!selectedProject ? (
          <div className="bg-white rounded-2xl shadow-lg border border-gray-200 p-8">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-gray-900 flex items-center gap-3">
                <FolderOpenIcon className="h-8 w-8 text-yellow-500" />
                My Checklist Projects
              </h2>
              <button
                onClick={() => setShowCreateProject(true)}
                className="flex items-center gap-2 px-4 py-2 bg-gradient-to-r from-yellow-500 to-orange-500 text-white rounded-lg hover:shadow-lg transition-all font-semibold"
              >
                <FolderPlusIcon className="h-5 w-5" />
                Create New Project
              </button>
            </div>

            {loadingProjects ? (
              <div className="text-center py-12">
                <ArrowPathIcon className="h-12 w-12 text-yellow-500 animate-spin mx-auto mb-4" />
                <p className="text-gray-600">Loading projects...</p>
              </div>
            ) : projects.length === 0 ? (
              <div className="text-center py-12">
                <FolderOpenIcon className="h-16 w-16 text-gray-300 mx-auto mb-4" />
                <h3 className="text-xl font-semibold text-gray-700 mb-2">No Projects Yet</h3>
                <p className="text-gray-500 mb-6">Create your first checklist project to get started</p>
                <button
                  onClick={() => setShowCreateProject(true)}
                  className="inline-flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-yellow-500 to-orange-500 text-white rounded-lg hover:shadow-lg transition-all font-semibold"
                >
                  <PlusCircleIcon className="h-5 w-5" />
                  Create First Project
                </button>
              </div>
            ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {projects.map((project) => (
                  <div
                    key={project.id}
                    className="border border-gray-200 rounded-xl p-6 hover:shadow-lg transition-all cursor-pointer bg-gradient-to-br from-white to-gray-50"
                    onClick={() => setSelectedProject(project)}
                  >
                    <div className="flex items-start justify-between mb-4">
                      <div className="p-3 bg-yellow-100 rounded-lg">
                        <FolderOpenIcon className="h-6 w-6 text-yellow-600" />
                      </div>
                      <span className={`px-3 py-1 rounded-full text-xs font-semibold ${
                        project.status === 'active' ? 'bg-green-100 text-green-700' :
                        project.status === 'on_hold' ? 'bg-yellow-100 text-yellow-700' :
                        project.status === 'completed' ? 'bg-blue-100 text-blue-700' :
                        'bg-gray-100 text-gray-700'
                      }`}>
                        {project.status}
                      </span>
                    </div>
                    
                    <h3 className="text-lg font-bold text-gray-900 mb-2">{project.project_name}</h3>
                    <p className="text-sm text-gray-600 mb-4 line-clamp-2">{project.description || 'No description'}</p>
                    
                    <div className="space-y-2 mb-4">
                      {project.location && (
                        <div className="flex items-center gap-2 text-sm text-gray-600">
                          <span className="font-medium">Location:</span>
                          <span>{project.location}</span>
                        </div>
                      )}
                      {project.client_name && (
                        <div className="flex items-center gap-2 text-sm text-gray-600">
                          <span className="font-medium">Client:</span>
                          <span>{project.client_name}</span>
                        </div>
                      )}
                    </div>

                    <div className="grid grid-cols-2 gap-4 pt-4 border-t border-gray-200">
                      <div>
                        <div className="text-2xl font-bold text-yellow-600">{project.total_checklists || 0}</div>
                        <div className="text-xs text-gray-500">Checklists</div>
                      </div>
                      <div>
                        <div className="text-2xl font-bold text-blue-600">{project.total_fields_extracted || 0}</div>
                        <div className="text-xs text-gray-500">Fields</div>
                      </div>
                    </div>

                    {project.tags && project.tags.length > 0 && (
                      <div className="mt-4 flex flex-wrap gap-2">
                        {project.tags.slice(0, 3).map((tag, idx) => (
                          <span key={idx} className="px-2 py-1 bg-gray-100 text-gray-600 rounded text-xs">
                            {tag}
                          </span>
                        ))}
                      </div>
                    )}
                  </div>
                ))}
              </div>
            )}
          </div>
        ) : (
          <>
            {/* Project Header */}
            <div className="bg-white rounded-2xl shadow-lg border border-gray-200 p-6 mb-6">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-4">
                  <button
                    onClick={() => setSelectedProject(null)}
                    className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                  >
                    <ArrowLeftIcon className="h-5 w-5 text-gray-600" />
                  </button>
                  <div className="p-3 bg-yellow-100 rounded-lg">
                    <FolderOpenIcon className="h-6 w-6 text-yellow-600" />
                  </div>
                  <div>
                    <h2 className="text-2xl font-bold text-gray-900">{selectedProject.project_name}</h2>
                    <p className="text-sm text-gray-600">{selectedProject.project_code}</p>
                  </div>
                </div>
                
                <div className="flex items-center gap-4">
                  <div className="text-right">
                    <div className="text-sm text-gray-500">Total Checklists</div>
                    <div className="text-2xl font-bold text-yellow-600">{selectedProject.total_checklists || 0}</div>
                  </div>
                  <div className="text-right">
                    <div className="text-sm text-gray-500">Fields Extracted</div>
                    <div className="text-2xl font-bold text-blue-600">{selectedProject.total_fields_extracted || 0}</div>
                  </div>
                  {selectedProject.total_signatures_found > 0 && (
                    <div className="text-right">
                      <div className="text-sm text-gray-500">Signatures</div>
                      <div className="text-2xl font-bold text-purple-600">{selectedProject.total_signatures_found}</div>
                    </div>
                  )}
                </div>
              </div>
            </div>

            {/* Checklist History — previously extracted/saved checklists for this
                project. Lets an inspection engineer revisit or download past
                records instead of only being able to start a brand new upload. */}
            {!extractionResult && (
              <div className="bg-white rounded-2xl shadow-lg border border-gray-200 p-6 mb-6">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-bold text-gray-900 flex items-center gap-2">
                    <DocumentTextIcon className="h-5 w-5 text-yellow-500" />
                    Checklist History
                  </h3>
                  <button
                    onClick={() => fetchProjectChecklists(selectedProject.id)}
                    className="text-sm text-yellow-700 hover:text-yellow-900 flex items-center gap-1"
                    disabled={loadingChecklists}
                  >
                    <ArrowPathIcon className={`h-4 w-4 ${loadingChecklists ? 'animate-spin' : ''}`} />
                    Refresh
                  </button>
                </div>

                {loadingChecklists ? (
                  <div className="text-center py-8 text-gray-500 text-sm">Loading history...</div>
                ) : projectChecklists.length === 0 ? (
                  <div className="text-center py-8 text-gray-400 text-sm">
                    No checklists extracted yet for this project. Upload a PDF below to get started.
                  </div>
                ) : (
                  <div className="overflow-x-auto">
                    <table className="w-full text-sm">
                      <thead>
                        <tr className="text-left text-gray-500 border-b border-gray-200">
                          <th className="py-2 pr-4 font-medium">Name</th>
                          <th className="py-2 pr-4 font-medium">Date</th>
                          <th className="py-2 pr-4 font-medium">Engineer</th>
                          <th className="py-2 pr-4 font-medium">Status</th>
                          <th className="py-2 pr-4 font-medium">Fields</th>
                          <th className="py-2 pr-4 font-medium">Confidence</th>
                          <th className="py-2 pr-4 font-medium">Cost</th>
                          <th className="py-2 pr-4 font-medium text-right">Actions</th>
                        </tr>
                      </thead>
                      <tbody>
                        {projectChecklists.map((job) => (
                          <tr key={job.id} className="border-b border-gray-100 hover:bg-gray-50">
                            <td className="py-3 pr-4 font-medium text-gray-900 max-w-[220px] truncate" title={job.checklist_name}>
                              {job.checklist_name || `Checklist #${job.id}`}
                            </td>
                            <td className="py-3 pr-4 whitespace-nowrap">
                              {job.created_at ? new Date(job.created_at).toLocaleString() : '-'}
                            </td>
                            <td className="py-3 pr-4">{job.user_name || '-'}</td>
                            <td className="py-3 pr-4">
                              <span className={`px-2 py-1 rounded-full text-xs font-semibold ${
                                job.status === 'completed' ? 'bg-green-100 text-green-700' :
                                job.status === 'failed'    ? 'bg-red-100 text-red-700' :
                                'bg-gray-100 text-gray-700'
                              }`}>
                                {job.status}
                              </span>
                            </td>
                            <td className="py-3 pr-4">{job.fields_extracted ?? 0}</td>
                            <td className="py-3 pr-4">{job.confidence_score ? `${job.confidence_score}%` : '-'}</td>
                            <td className="py-3 pr-4 whitespace-nowrap" title="Exact OpenAI Vision API cost for this checklist (based on real token usage)">
                              {formatChecklistCost(job.cost_usd)}
                            </td>
                            <td className="py-3 pr-4 text-right">
                              {job.status === 'completed' ? (
                                <div className="flex items-center gap-2 justify-end">
                                  <button
                                    onClick={() => handleViewHistoryChecklist(job)}
                                    disabled={viewingHistoryJobId === job.id}
                                    className="px-3 py-1.5 bg-yellow-500 text-white rounded-lg hover:bg-yellow-600 transition-all font-medium text-xs disabled:opacity-50"
                                  >
                                    {viewingHistoryJobId === job.id ? 'Opening...' : 'View'}
                                  </button>
                                  <button
                                    onClick={() => handleDownloadHistoryExcel(job)}
                                    className="px-3 py-1.5 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-all font-medium text-xs"
                                  >
                                    Download
                                  </button>
                                </div>
                              ) : (
                                <span className="text-xs text-gray-400">{job.status}</span>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            )}

            {/* Main Content */}
            <div className="bg-white rounded-2xl shadow-lg border border-gray-200 p-8">
              {!extractionResult ? (
                <>
                  {/* Upload Area */}
                  <div
                    className={`border-3 border-dashed rounded-2xl p-12 text-center transition-all ${
                      selectedFiles.length > 0
                        ? 'border-green-500 bg-green-50'
                        : 'border-yellow-300 bg-yellow-50/30 hover:border-yellow-500 hover:bg-yellow-50'
                    }`}
                    onDragOver={handleDragOver}
                    onDrop={handleDrop}
                  >
                <input
                  ref={fileInputRef}
                  type="file"
                  accept={EXTRACTION_CONFIG.upload.acceptedFormats}
                  multiple
                  onChange={handleFileSelect}
                  className="hidden"
                  disabled={uploading}
                />

                {selectedFiles.length === 0 ? (
                  <button
                    onClick={() => fileInputRef.current?.click()}
                    disabled={uploading}
                    className="w-full"
                  >
                    <CloudArrowUpIcon className="w-20 h-20 text-yellow-400 mx-auto mb-4" />
                    <h3 className="text-2xl font-semibold text-gray-900 mb-2">
                      {UI_CONFIG.uploadArea.title}
                    </h3>
                    <p className="text-gray-600 mb-2">
                      {UI_CONFIG.uploadArea.subtitle}
                    </p>
                    <p className="text-sm text-gray-500">
                      {UI_CONFIG.uploadArea.helperText}
                    </p>
                  </button>
                ) : (
                  <div className="space-y-3">
                    <div className="flex items-center justify-center mb-4">
                      <CheckCircleIcon className="h-16 w-16 text-green-600" />
                    </div>
                    {selectedFiles.map((file, index) => (
                      <div
                        key={index}
                        className="flex items-center justify-between p-3 bg-white rounded-lg border border-green-200"
                      >
                        <div className="flex items-center gap-3">
                          <DocumentTextIcon className="h-6 w-6 text-green-600" />
                          <div className="text-left">
                            <p className="font-semibold text-gray-900">{file.name}</p>
                            <p className="text-sm text-gray-500">
                              {(file.size / 1024 / 1024).toFixed(2)} MB
                            </p>
                          </div>
                        </div>
                        {!uploading && (
                          <button
                            onClick={() => handleRemoveFile(index)}
                            className="text-red-600 hover:text-red-800"
                          >
                            <XCircleIcon className="h-6 w-6" />
                          </button>
                        )}
                      </div>
                    ))}
                  </div>
                )}
                  </div>

              {/* Error Message */}
              {error && (
                <div className="mt-6 p-4 bg-red-50 border border-red-200 rounded-lg">
                  <div className="flex items-center gap-2 text-red-800">
                    <XCircleIcon className="h-5 w-5" />
                    <span className="font-medium">{error}</span>
                  </div>
                </div>
              )}

              {/* Upload Progress */}
              {uploading && (
                <div className="mt-6">
                  <div className="flex items-center justify-between mb-2">
                    <span className="text-sm font-medium text-gray-700">{extractionStage}</span>
                    <span className="text-sm font-medium text-yellow-600">{uploadProgress}%</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-3 overflow-hidden">
                    <div
                      className="bg-gradient-to-r from-yellow-500 to-orange-500 h-full transition-all duration-300 rounded-full"
                      style={{ width: `${uploadProgress}%` }}
                    />
                  </div>
                </div>
              )}

              {/* Action Buttons */}
              {selectedFiles.length > 0 && !uploading && (
                <>
                  {/* Extraction mode selector (soft-coded from EXTRACTION_CONFIG.handwriting.modes) */}
                  {EXTRACTION_CONFIG.handwriting?.enabled && EXTRACTION_CONFIG.handwriting?.modes?.length > 0 && (
                    <div className="mt-6 p-4 border border-gray-200 rounded-xl bg-gradient-to-br from-white to-gray-50">
                      <div className="flex items-center justify-between mb-3">
                        <label className="block text-sm font-semibold text-gray-800">
                          Extraction Accuracy Mode
                        </label>
                        <span className="text-xs text-gray-500">
                          Selected: <span className="font-medium text-gray-800">{extractionMode}</span>
                        </span>
                      </div>
                      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
                        {EXTRACTION_CONFIG.handwriting.modes.map((mode) => {
                          const isSelected = extractionMode === mode.id;
                          const isDisabled = mode.requiresApiKey && !platformAI.canUseAI;
                          return (
                            <button
                              key={mode.id}
                              type="button"
                              disabled={isDisabled}
                              onClick={() => setExtractionMode(mode.id)}
                              className={[
                                'text-left p-3 rounded-lg border-2 transition-all',
                                isSelected
                                  ? 'border-yellow-500 bg-yellow-50 shadow-md ring-2 ring-yellow-200'
                                  : 'border-gray-200 bg-white hover:border-gray-300 hover:shadow-sm',
                                isDisabled ? 'opacity-50 cursor-not-allowed' : 'cursor-pointer',
                              ].join(' ')}
                            >
                              <div className="flex items-start justify-between mb-1">
                                <span className={`text-sm font-semibold ${isSelected ? 'text-yellow-900' : 'text-gray-900'}`}>
                                  {mode.label}
                                </span>
                                {mode.recommended && (
                                  <span className="text-[10px] px-1.5 py-0.5 bg-green-100 text-green-700 rounded uppercase font-bold">
                                    Rec
                                  </span>
                                )}
                              </div>
                              <p className="text-[11px] text-gray-500 mb-2">{mode.tagline}</p>
                              <p className="text-xs text-gray-600 leading-snug mb-2">{mode.description}</p>
                              <div className="flex items-center justify-between text-[10px]">
                                <span className="font-mono text-gray-500">{mode.cost}</span>
                                <span className="text-gray-500">{mode.accuracy}</span>
                              </div>
                              {isDisabled && (
                                <p className="mt-2 text-[10px] text-red-500 italic">
                                  Provide an OpenAI key below to enable
                                </p>
                              )}
                            </button>
                          );
                        })}
                      </div>
                    </div>
                  )}

                  {/* Inspector attribution and server-managed AI. */}
                  <PlatformAIStatus provider="openai" />
                  <div className="mt-4 p-4 border border-gray-200 rounded-xl bg-gray-50 space-y-3">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Checklist Name <span className="text-gray-400 font-normal">(optional — helps tell checklists apart in history)</span>
                      </label>
                      <input
                        type="text"
                        value={checklistName}
                        onChange={(e) => setChecklistName(e.target.value)}
                        placeholder="e.g. Q1 Site Visit — Substation A"
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent text-sm"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Inspection Engineer <span className="text-gray-400 font-normal">(optional \u2014 for attribution)</span>
                      </label>
                      <input
                        type="text"
                        value={engineerName}
                        onChange={(e) => setEngineerName(e.target.value)}
                        placeholder="e.g. Habil, Shayad Abdul Razaq"
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent text-sm"
                      />
                    </div>


                  </div>

                  <div className="mt-4 flex gap-4">
                    <button
                      onClick={handleExtract}
                      className="flex-1 flex items-center justify-center gap-2 px-6 py-4 bg-gradient-to-r from-yellow-500 to-orange-500 text-white rounded-xl hover:shadow-lg transition-all font-semibold text-lg"
                    >
                      <SparklesIcon className="h-6 w-6" />
                      Extract Data with AI
                    </button>
                    <button
                      onClick={handleReset}
                      className="px-6 py-4 bg-gray-100 text-gray-700 rounded-xl hover:bg-gray-200 transition-all font-semibold"
                    >
                      Reset
                    </button>
                  </div>
                </>
              )}
            </>
          ) : (
            /* Extraction Results */
            <div className="space-y-6">
              {/* BYOK key rejected warning (surfaced from backend key_status) */}
              {extractionResult.key_status?.user_rejected && (
                <div className="p-4 bg-amber-50 border border-amber-300 rounded-xl flex items-start gap-3">
                  <ExclamationTriangleIcon className="h-6 w-6 text-amber-600 flex-shrink-0 mt-0.5" />
                  <div className="text-sm">
                    <p className="font-semibold text-amber-900">Your OpenAI API key was not used</p>
                    <p className="text-amber-800 mt-1">
                      {extractionResult.key_status.reason || 'The key you provided was invalid.'}
                      {' '}Extraction ran with the platform key instead. To use your own key, paste a valid one that starts with <code className="font-mono bg-white px-1 rounded">sk-</code>.
                    </p>
                  </div>
                </div>
              )}

              {/* Success Banner with View Toggle */}
              <div className="flex items-center justify-between p-6 bg-green-50 rounded-xl border border-green-200">
                <div className="flex items-center gap-4">
                  <CheckCircleIcon className="h-12 w-12 text-green-600" />
                  <div>
                    <h3 className="text-xl font-bold text-green-900">Extraction Complete!</h3>
                    <p className="text-green-700">
                      Successfully extracted {extractionResult.fields_extracted} fields from {selectedFiles.length} file(s)
                    </p>
                    <input
                      type="text"
                      value={checklistName}
                      onChange={(e) => setChecklistName(e.target.value)}
                      placeholder={`Checklist #${jobId} — name it to find it later`}
                      title="Checklist name — shown in the project's Checklist History"
                      className="mt-2 w-72 max-w-full px-2 py-1 text-sm bg-white/70 border border-green-300 rounded-lg focus:ring-2 focus:ring-green-500 focus:border-transparent"
                    />
                  </div>
                </div>
                <div className="flex items-center gap-3">
                  <div className="flex bg-white rounded-lg p-1 border border-gray-200">
                    <button
                      onClick={() => setViewMode('summary')}
                      className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        viewMode === 'summary'
                          ? 'bg-green-600 text-white'
                          : 'text-gray-700 hover:bg-gray-100'
                      }`}
                    >
                      Summary
                    </button>
                    <button
                      onClick={() => setViewMode('detailed')}
                      className={`px-4 py-2 rounded-md text-sm font-medium transition-all ${
                        viewMode === 'detailed'
                          ? 'bg-green-600 text-white'
                          : 'text-gray-700 hover:bg-gray-100'
                      }`}
                    >
                      Detailed View
                    </button>
                  </div>
                  <button
                    onClick={() => handleDownloadExcel()}
                    className="flex items-center gap-2 px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-all font-semibold"
                  >
                    <ArrowDownTrayIcon className="h-5 w-5" />
                    Download Excel
                  </button>
                </div>
              </div>

              {viewMode === 'summary' ? (
                /* Summary View */
                <>
                  {/* Extracted Data Summary */}
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                    <div className="p-6 bg-blue-50 rounded-xl border border-blue-200">
                      <div className="text-3xl font-bold text-blue-900 mb-1">
                        {extractionResult.sections_completed}
                      </div>
                      <div className="text-sm text-blue-700">Sections Completed</div>
                    </div>
                    <div className="p-6 bg-purple-50 rounded-xl border border-purple-200">
                      <div className="text-3xl font-bold text-purple-900 mb-1">
                        {extractionResult.signatures_found || 0}
                      </div>
                      <div className="text-sm text-purple-700">Signatures Detected</div>
                    </div>
                    <div className="p-6 bg-yellow-50 rounded-xl border border-yellow-200">
                      <div className="text-3xl font-bold text-yellow-900 mb-1">
                        {extractionResult.confidence_score}%
                      </div>
                      <div className="text-sm text-yellow-700">Average Confidence</div>
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex gap-4">
                    <button
                      onClick={handleReset}
                      className="flex items-center gap-2 px-6 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-all font-semibold"
                    >
                      <ArrowPathIcon className="h-5 w-5" />
                      Extract Another Checklist
                    </button>
                  </div>
                </>
              ) : (
                /* Detailed Checklist View - 6 Column Table */
                <>
                  {/* Toolbar */}
                  <div className="flex items-center justify-between p-4 bg-gray-50 rounded-lg border border-gray-200">
                    <div className="flex items-center gap-3">
                      <button
                        onClick={expandAllSections}
                        className="px-3 py-2 text-sm font-medium text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                      >
                        Expand All
                      </button>
                      <button
                        onClick={collapseAllSections}
                        className="px-3 py-2 text-sm font-medium text-blue-600 hover:bg-blue-50 rounded-lg transition-all"
                      >
                        Collapse All
                      </button>
                    </div>
                    <div className="flex items-center gap-3">
                      <button
                        onClick={handleSaveChecklist}
                        disabled={saving}
                        className="flex items-center gap-2 px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-all font-semibold disabled:opacity-50"
                      >
                        {saving ? 'Saving...' : 'Save Changes'}
                      </button>
                      <button
                        onClick={handleReset}
                        className="flex items-center gap-2 px-6 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-all font-semibold"
                      >
                        <ArrowPathIcon className="h-5 w-5" />
                        Reset
                      </button>
                    </div>
                  </div>

                  {/* Checklist Sections */}
                  <div className="space-y-4">
                    {TEMPLATE_SECTIONS && TEMPLATE_SECTIONS.length > 0 ? (
                      TEMPLATE_SECTIONS.map((section) => {
                        const sectionColors = SECTION_COLORS[section.color] || SECTION_COLORS.blue;
                        const isExpanded = expandedSections[section.id];

                      return (
                        <div key={section.id} className={`rounded-xl border-2 ${sectionColors.border} overflow-hidden`}>
                          {/* Section Header */}
                          <button
                            onClick={() => toggleSection(section.id)}
                            className={`w-full p-4 ${sectionColors.bg} flex items-center justify-between hover:opacity-90 transition-all`}
                          >
                            <div className="flex items-center gap-3">
                              <span className={`px-3 py-1 ${sectionColors.badge} rounded-lg font-bold`}>
                                {section.number}
                              </span>
                              <div className="text-left">
                                <h3 className={`text-lg font-bold ${sectionColors.text}`}>
                                  {section.title}
                                  {section.subtitle && <span className="ml-2 text-sm font-normal">{section.subtitle}</span>}
                                </h3>
                                <p className="text-sm text-gray-600">{section.description}</p>
                              </div>
                            </div>
                            <svg
                              className={`w-6 h-6 ${sectionColors.icon} transform transition-transform ${isExpanded ? 'rotate-180' : ''}`}
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                            </svg>
                          </button>

                          {/* Section Content - Table */}
                          {isExpanded && (
                            <div className="bg-white">
                              {/* Table Header */}
                              <div className="grid grid-cols-6 gap-2 p-4 bg-gray-50 border-b border-gray-200 font-semibold text-sm text-gray-700">
                                {TEMPLATE_COLUMNS.map((col) => (
                                  <div key={col.key} className="px-2">
                                    {col.label}
                                    {col.description && (
                                      <p className="text-xs text-gray-500 font-normal mt-1">{col.description}</p>
                                    )}
                                  </div>
                                ))}
                              </div>

                              {/* Table Rows */}
                              <div className="divide-y divide-gray-200">
                                {section.fields.map((field) => {
                                  const fieldData = checklistData[field.id] || {};
                                  
                                  return (
                                    <div key={field.id} className="grid grid-cols-6 gap-2 p-4 hover:bg-gray-50 transition-colors">
                                      {TEMPLATE_COLUMNS.map((col) => (
                                        <div key={`${field.id}-${col.key}`} className="px-2">
                                          {col.key === 'field_name' 
                                            ? renderFieldInput(field, field.id, col.key, field.name)
                                            : renderFieldInput(field, field.id, col.key, fieldData[col.key] || '')
                                          }
                                        </div>
                                      ))}
                                    </div>
                                  );
                                })}
                              </div>
                            </div>
                          )}
                        </div>
                      );
                    })
                    ) : (
                      <div className="p-8 text-center text-gray-500">
                        <p>No template sections available. Please check the configuration.</p>
                      </div>
                    )}
                  </div>
                </>
              )}
            </div>
          )}
        </div>
        </>
      )}
    </div>
  </div>
  );
};

export default ElectricalCheckList;

import { radaiConfirm, radaiAlert } from '../../../services/radaiDialog'
import React, { useState, useEffect } from 'react';
import { useNavigate, useParams, useSearchParams } from 'react-router-dom';
import apiClient from '../../../services/api.service';
import {
  ArrowLeftIcon,
  CheckIcon,
  XMarkIcon,
  DocumentTextIcon,
  SparklesIcon,
  CloudArrowUpIcon
} from '@heroicons/react/24/outline';
import QualityCheckerReport from '../../../components/Electrical/QualityCheckerReport';
import FileUploadSection from '../../../components/Electrical/FileUploadSection';

const API_BASE_URL = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000';

const ElectricalDatasheetFormPage = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const [searchParams] = useSearchParams();
  const equipmentTypeParam = searchParams.get('type');

  const [loading, setLoading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState(null);
  const [equipmentType, setEquipmentType] = useState(null);
  const [configuration, setConfiguration] = useState(null);
  const [formData, setFormData] = useState({});
  const [showQualityChecker, setShowQualityChecker] = useState(false);
  const [uploadedFiles, setUploadedFiles] = useState([]);
  const [showFileUpload, setShowFileUpload] = useState(false);
  const [basicInfo, setBasicInfo] = useState({
    tag_number: '',
    service_description: '',
    location: '',
    project_name: '',
    project_number: ''
  });

  useEffect(() => {
    if (id) {
      // Edit mode - load existing datasheet
      loadDatasheet(id);
    } else if (equipmentTypeParam) {
      // Create mode - load equipment type configuration
      loadEquipmentTypeConfiguration(equipmentTypeParam);
    }
  }, [id, equipmentTypeParam]);

  const loadDatasheet = async (datasheetId) => {
    try {
      setLoading(true);
      const response = await apiClient.get(`/electrical-datasheet/datasheets/${datasheetId}/`);
      
      const datasheet = response.data;
      setBasicInfo({
        tag_number: datasheet.tag_number,
        service_description: datasheet.service_description,
        location: datasheet.location,
        project_name: datasheet.project_name || '',
        project_number: datasheet.project_number || ''
      });
      setFormData(datasheet.form_data || {});
      
      // Load attached files
      if (datasheet.form_data?.attached_files) {
        setUploadedFiles(datasheet.form_data.attached_files);
      }
      
      // Load equipment type configuration
      await loadEquipmentTypeConfiguration(datasheet.equipment_type);
    } catch (err) {
      console.error('Error loading datasheet:', err);
      setError('Failed to load datasheet');
    } finally {
      setLoading(false);
    }
  };

  const loadEquipmentTypeConfiguration = async (typeId) => {
    try {
      setLoading(true);
      
      // Load equipment type details
      const typeResponse = await apiClient.get(`/electrical-datasheet/equipment-types/${typeId}/`);
      setEquipmentType(typeResponse.data);
      
      // Load configuration
      const configResponse = await apiClient.get(`/electrical-datasheet/equipment-types/${typeId}/configuration/`);
      setConfiguration(configResponse.data);
    } catch (err) {
      console.error('Error loading configuration:', err);
      setError('Failed to load equipment configuration');
    } finally {
      setLoading(false);
    }
  };

  const handleBasicInfoChange = (field, value) => {
    setBasicInfo(prev => ({ ...prev, [field]: value }));
  };

  const handleFieldChange = (fieldId, value) => {
    setFormData(prev => ({ ...prev, [fieldId]: value }));
  };

  const handleFileUpload = async (file) => {
    try {
      if (!id) {
        throw new Error('Please save the datasheet first before uploading files');
      }

      const formData = new FormData();
      formData.append('file', file);
      formData.append('file_type', 'datasheet');

      const response = await apiClient.post(
        `/electrical-datasheet/datasheets/${id}/attach_file/`,
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
          },
        }
      );

      // Reload datasheet to get updated file list
      await loadDatasheet(id);
      
      return response.data;
    } catch (error) {
      console.error('File upload error:', error);
      throw error;
    }
  };

  const handleFileRemove = async (file, index) => {
    if ((await radaiConfirm('Are you sure you want to remove this file?'))) {
      try {
        const updatedFiles = uploadedFiles.filter((_, i) => i !== index);
        
        // Update form_data with new file list
        const updatedFormData = { ...formData, attached_files: updatedFiles };
        
        await apiClient.patch(`/electrical-datasheet/datasheets/${id}/`, {
          form_data: updatedFormData
        });
        
        setUploadedFiles(updatedFiles);
        setFormData(updatedFormData);
      } catch (error) {
        console.error('Error removing file:', error);
        await radaiAlert('Failed to remove file');
      }
    }
  };

  const handleFileDownload = async (file, index) => {
    try {
      const response = await apiClient.get(
        `/electrical-datasheet/datasheets/${id}/download_file/?file_index=${index}`
      );
      
      if (response.data.download_url) {
        window.open(response.data.download_url, '_blank');
      } else {
        await radaiAlert('Download URL not available');
      }
    } catch (error) {
      console.error('Error downloading file:', error);
      await radaiAlert('Failed to download file');
    }
  };

  const handleSubmit = async (submitStatus = 'draft') => {
    try {
      setSaving(true);
      setError(null);
      
      const payload = {
        equipment_type: equipmentType.id,
        ...basicInfo,
        form_data: formData,
        status: submitStatus
      };

      let response;
      if (id) {
        // Update existing
        response = await apiClient.put(`/electrical-datasheet/datasheets/${id}/`, payload);
      } else {
        // Create new
        response = await apiClient.post('/electrical-datasheet/datasheets/', payload);
      }

      // Navigate back to list
      navigate('/engineering/electrical/datasheet');
    } catch (err) {
      console.error('Error saving datasheet:', err);
      if (err.response?.data) {
        const errors = err.response.data;
        const errorMessages = Object.entries(errors).map(([key, value]) => {
          if (Array.isArray(value)) {
            return `${key}: ${value.join(', ')}`;
          }
          return `${key}: ${value}`;
        }).join('\n');
        setError(errorMessages || 'Failed to save datasheet');
      } else {
        setError('Failed to save datasheet. Please check all required fields.');
      }
    } finally {
      setSaving(false);
    }
  };

  const renderField = (field) => {
    const value = formData[field.id] || '';
    const commonProps = {
      id: field.id,
      value: value,
      onChange: (e) => handleFieldChange(field.id, e.target.value),
      className: "mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-yellow-500 focus:ring-yellow-500 sm:text-sm",
      placeholder: field.placeholder || '',
      required: field.required || false
    };

    switch (field.type) {
      case 'text':
        return <input type="text" {...commonProps} />;
      
      case 'number':
        return (
          <div className="flex items-center">
            <input
              type="number"
              {...commonProps}
              step={field.step || 'any'}
              min={field.min}
              max={field.max}
            />
            {field.unit && (
              <span className="ml-2 text-sm text-gray-500">{field.unit}</span>
            )}
          </div>
        );
      
      case 'textarea':
        return (
          <textarea
            {...commonProps}
            rows={3}
          />
        );
      
      case 'select':
        return (
          <select {...commonProps}>
            <option value="">Select {field.label}</option>
            {field.options?.map((option) => (
              <option key={option.value} value={option.value}>
                {option.label}
              </option>
            ))}
          </select>
        );
      
      case 'multi_select':
        const selectedValues = Array.isArray(value) ? value : [];
        return (
          <div className="space-y-2">
            {field.options?.map((option) => (
              <label key={option.value} className="flex items-center">
                <input
                  type="checkbox"
                  checked={selectedValues.includes(option.value)}
                  onChange={(e) => {
                    const newValues = e.target.checked
                      ? [...selectedValues, option.value]
                      : selectedValues.filter(v => v !== option.value);
                    handleFieldChange(field.id, newValues);
                  }}
                  className="rounded border-gray-300 text-yellow-600 focus:ring-yellow-500"
                />
                <span className="ml-2 text-sm text-gray-700">{option.label}</span>
              </label>
            ))}
          </div>
        );
      
      default:
        return <input type="text" {...commonProps} />;
    }
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-yellow-600 mx-auto"></div>
          <p className="mt-4 text-gray-500">Loading...</p>
        </div>
      </div>
    );
  }

  if (!equipmentType || !configuration) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <p className="text-red-600">{error || 'Equipment configuration not found'}</p>
          <button
            onClick={() => navigate('/engineering/electrical/datasheet')}
            className="mt-4 text-yellow-600 hover:text-yellow-700"
          >
            Go Back
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-6">
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header */}
        <div className="mb-6">
          <button
            onClick={() => navigate('/engineering/electrical/datasheet')}
            className="flex items-center text-sm text-gray-500 hover:text-gray-700"
          >
            <ArrowLeftIcon className="w-4 h-4 mr-2" />
            Back to Datasheets
          </button>
          <h1 className="mt-4 text-2xl font-bold text-gray-900">
            {id ? 'Edit' : 'Create'} {equipmentType.name} Datasheet
          </h1>
          <p className="mt-1 text-sm text-gray-500">{configuration.description}</p>
        </div>

        {/* Error Display */}
        {error && (
          <div className="mb-6 bg-red-50 border border-red-200 rounded-md p-4">
            <div className="flex">
              <XMarkIcon className="w-5 h-5 text-red-400" />
              <div className="ml-3">
                <h3 className="text-sm font-medium text-red-800">Error</h3>
                <div className="mt-2 text-sm text-red-700 whitespace-pre-line">{error}</div>
              </div>
            </div>
          </div>
        )}

        {/* Form */}
        <div className="bg-white shadow rounded-lg">
          {/* Basic Information */}
          <div className="px-6 py-4 border-b border-gray-200">
            <h2 className="text-lg font-medium text-gray-900">Basic Information</h2>
          </div>
          <div className="px-6 py-4 space-y-4">
            <div>
              <label htmlFor="tag_number" className="block text-sm font-medium text-gray-700">
                Tag Number <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                id="tag_number"
                value={basicInfo.tag_number}
                onChange={(e) => handleBasicInfoChange('tag_number', e.target.value)}
                required
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-yellow-500 focus:ring-yellow-500 sm:text-sm"
              />
            </div>
            
            <div>
              <label htmlFor="service_description" className="block text-sm font-medium text-gray-700">
                Service Description <span className="text-red-500">*</span>
              </label>
              <textarea
                id="service_description"
                value={basicInfo.service_description}
                onChange={(e) => handleBasicInfoChange('service_description', e.target.value)}
                required
                rows={2}
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-yellow-500 focus:ring-yellow-500 sm:text-sm"
              />
            </div>

            <div>
              <label htmlFor="location" className="block text-sm font-medium text-gray-700">
                Location/Area <span className="text-red-500">*</span>
              </label>
              <input
                type="text"
                id="location"
                value={basicInfo.location}
                onChange={(e) => handleBasicInfoChange('location', e.target.value)}
                required
                className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-yellow-500 focus:ring-yellow-500 sm:text-sm"
              />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <label htmlFor="project_name" className="block text-sm font-medium text-gray-700">
                  Project Name
                </label>
                <input
                  type="text"
                  id="project_name"
                  value={basicInfo.project_name}
                  onChange={(e) => handleBasicInfoChange('project_name', e.target.value)}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-yellow-500 focus:ring-yellow-500 sm:text-sm"
                />
              </div>

              <div>
                <label htmlFor="project_number" className="block text-sm font-medium text-gray-700">
                  Project Number
                </label>
                <input
                  type="text"
                  id="project_number"
                  value={basicInfo.project_number}
                  onChange={(e) => handleBasicInfoChange('project_number', e.target.value)}
                  className="mt-1 block w-full rounded-md border-gray-300 shadow-sm focus:border-yellow-500 focus:ring-yellow-500 sm:text-sm"
                />
              </div>
            </div>
          </div>

          {/* Dynamic Sections from Configuration */}
          {configuration.sections?.map((section) => (
            <div key={section.id} className="border-t border-gray-200">
              <div className="px-6 py-4 bg-gray-50">
                <h2 className="text-lg font-medium text-gray-900">{section.name}</h2>
              </div>
              <div className="px-6 py-4 space-y-4">
                {section.fields?.map((field) => (
                  <div key={field.id}>
                    <label htmlFor={field.id} className="block text-sm font-medium text-gray-700">
                      {field.label}
                      {field.required && <span className="text-red-500 ml-1">*</span>}
                    </label>
                    {renderField(field)}
                  </div>
                ))}
              </div>
            </div>
          ))}

          {/* File Upload Section */}
          {id && (
            <div className="border-t border-gray-200">
              <div 
                className="px-6 py-4 bg-gray-50 flex items-center justify-between cursor-pointer hover:bg-gray-100"
                onClick={() => setShowFileUpload(!showFileUpload)}
              >
                <div className="flex items-center">
                  <CloudArrowUpIcon className="w-5 h-5 text-purple-600 mr-2" />
                  <h2 className="text-lg font-medium text-gray-900">
                    Datasheet Files & ADNOC Validation
                  </h2>
                  {uploadedFiles.length > 0 && (
                    <span className="ml-3 px-2 py-1 text-xs font-medium bg-purple-100 text-purple-700 rounded-full">
                      {uploadedFiles.length} file{uploadedFiles.length !== 1 ? 's' : ''}
                    </span>
                  )}
                </div>
                <div className="text-gray-400">
                  {showFileUpload ? '▼' : '▶'}
                </div>
              </div>
              
              {showFileUpload && (
                <div className="px-6 py-4">
                  <FileUploadSection
                    onFileUpload={handleFileUpload}
                    existingFiles={uploadedFiles}
                    onFileRemove={handleFileRemove}
                    onFileDownload={handleFileDownload}
                    acceptedTypes=".pdf,.xlsx,.xls"
                    maxSize={10 * 1024 * 1024}
                    showADNOCValidation={true}
                  />
                </div>
              )}
            </div>
          )}

          {!id && (
            <div className="border-t border-gray-200 px-6 py-4 bg-purple-50">
              <div className="flex items-start space-x-3">
                <CloudArrowUpIcon className="w-5 h-5 text-purple-600 flex-shrink-0 mt-0.5" />
                <div>
                  <h3 className="text-sm font-medium text-purple-900">File Upload Available After Save</h3>
                  <p className="text-xs text-purple-700 mt-1">
                    Save this datasheet first to enable file upload and ADNOC standards validation.
                  </p>
                </div>
              </div>
            </div>
          )}

          {/* Action Buttons */}
          <div className="px-6 py-4 bg-gray-50 border-t border-gray-200 flex justify-between items-center">
            <div>
              {id && (
                <button
                  type="button"
                  onClick={() => setShowQualityChecker(true)}
                  className="inline-flex items-center px-4 py-2 border border-purple-300 rounded-md shadow-sm text-sm font-medium text-purple-700 bg-white hover:bg-purple-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-purple-500"
                >
                  <SparklesIcon className="w-5 h-5 mr-2" />
                  AI Quality Check
                </button>
              )}
            </div>
            <div className="flex space-x-3">
              <button
                type="button"
                onClick={() => navigate('/engineering/electrical/datasheet')}
                className="px-4 py-2 border border-gray-300 rounded-md shadow-sm text-sm font-medium text-gray-700 bg-white hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-yellow-500"
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={() => handleSubmit('draft')}
                disabled={saving}
                className="px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-gray-600 hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-gray-500 disabled:opacity-50"
              >
                {saving ? 'Saving...' : 'Save as Draft'}
              </button>
              <button
                type="button"
                onClick={() => handleSubmit('under_review')}
                disabled={saving}
                className="inline-flex items-center px-4 py-2 border border-transparent rounded-md shadow-sm text-sm font-medium text-white bg-yellow-600 hover:bg-yellow-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-yellow-500 disabled:opacity-50"
              >
                <CheckIcon className="w-5 h-5 mr-2" />
                {saving ? 'Submitting...' : 'Submit for Review'}
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* Quality Checker Modal */}
      {showQualityChecker && id && (
        <QualityCheckerReport
          datasheetId={id}
          onClose={() => setShowQualityChecker(false)}
        />
      )}
    </div>
  );
};

export default ElectricalDatasheetFormPage;

import React, { useState, useEffect } from 'react';
import apiClient from '../../../services/api.service';
import {
  CloudArrowUpIcon,
  DocumentTextIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowPathIcon,
  BoltIcon,
  SparklesIcon,
  ExclamationTriangleIcon,
  ArrowDownTrayIcon
} from '@heroicons/react/24/outline';

const ElectricalDatasheetPage = () => {
  const [equipmentTypes, setEquipmentTypes] = useState([]);
  const [selectedType, setSelectedType] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [validationResult, setValidationResult] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    fetchEquipmentTypes();
  }, []);

  const fetchEquipmentTypes = async () => {
    try {
      const response = await apiClient.get('/electrical-datasheet/equipment-types/');
      const data = response.data?.results || response.data || [];
      setEquipmentTypes(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error('Error fetching equipment types:', err);
    }
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileInput = (e) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  const handleFile = (file) => {
    // Validate file type
    const allowedTypes = ['application/pdf', 'image/png', 'image/jpeg', 'image/jpg'];
    if (!allowedTypes.includes(file.type)) {
      setError('Please upload PDF or image files only (PDF, PNG, JPG, JPEG)');
      return;
    }

    // Validate file size (max 10MB)
    if (file.size > 10 * 1024 * 1024) {
      setError('File size must be less than 10MB');
      return;
    }

    setSelectedFile(file);
    setError(null);
    setValidationResult(null);
  };

  const handleUpload = async () => {
    if (!selectedFile || !selectedType) {
      setError('Please select equipment type and file');
      return;
    }

    setUploading(true);
    setUploadProgress(0);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('file', selectedFile);
      formData.append('equipment_type_id', selectedType);

      setUploadProgress(30);

      const response = await apiClient.post(
        '/electrical-datasheet/datasheets/validate_diagram/',
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
          },
        }
      );

      setUploadProgress(100);
      setValidationResult(response.data);
    } catch (err) {
      console.error('Upload error:', err);
      setError(err.response?.data?.error || 'Upload failed. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  const resetUpload = () => {
    setSelectedFile(null);
    setSelectedType('');
    setValidationResult(null);
    setError(null);
    setUploadProgress(0);
  };

  const handleExportToExcel = async () => {
    try {
      const response = await apiClient.post(
        '/electrical-datasheet/datasheets/export-validation/',
        validationResult,
        {
          responseType: 'blob',
        }
      );

      // Create download link
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `electrical_validation_${new Date().toISOString().slice(0, 10)}.xlsx`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Export error:', err);
      setError('Failed to export to Excel. Please try again.');
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-blue-50">
      {/* Header */}
      <div className="bg-white shadow">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
          <div className="flex items-center">
            <BoltIcon className="w-10 h-10 text-yellow-600 mr-4" />
            <div>
              <h1 className="text-3xl font-bold text-gray-900">Electrical Diagram Validation</h1>
              <p className="text-sm text-gray-600 mt-1 flex items-center">
                <SparklesIcon className="w-4 h-4 mr-1" />
                AI-Powered ADNOC Standards Verification
              </p>
            </div>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        {!validationResult ? (
          <>
            {/* Equipment Type Selection */}
            <div className="bg-white rounded-lg shadow-lg p-8 mb-6">
              <h2 className="text-xl font-semibold text-gray-900 mb-4">Select Equipment Type</h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {equipmentTypes.map((type) => (
                  <button
                    key={type.id}
                    onClick={() => setSelectedType(type.id)}
                    className={`p-6 border-2 rounded-lg transition-all ${
                      selectedType === type.id
                        ? 'border-yellow-600 bg-yellow-50 shadow-md'
                        : 'border-gray-200 hover:border-yellow-400 hover:shadow-sm'
                    }`}
                  >
                    <div className="flex items-center">
                      <div className="text-4xl mr-4">{type.icon}</div>
                      <div className="text-left">
                        <p className="font-semibold text-gray-900">{type.name}</p>
                        <p className="text-sm text-gray-600 mt-1">{type.description}</p>
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            </div>

            {/* Upload Area */}
            <div className="bg-white rounded-lg shadow-lg p-8">
              <h2 className="text-xl font-semibold text-gray-900 mb-4">Upload Diagram</h2>
              
              <div
                onDragEnter={handleDrag}
                onDragLeave={handleDrag}
                onDragOver={handleDrag}
                onDrop={handleDrop}
                className={`relative border-2 border-dashed rounded-lg p-12 text-center transition-all ${
                  dragActive
                    ? 'border-yellow-600 bg-yellow-50'
                    : 'border-gray-300 hover:border-gray-400'
                }`}
              >
                <input
                  type="file"
                  accept=".pdf,.png,.jpg,.jpeg"
                  onChange={handleFileInput}
                  className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                />
                
                {selectedFile ? (
                  <div className="space-y-4">
                    <CheckCircleIcon className="w-16 h-16 text-green-600 mx-auto" />
                    <div>
                      <p className="text-lg font-medium text-gray-900">{selectedFile.name}</p>
                      <p className="text-sm text-gray-500 mt-1">
                        {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
                      </p>
                    </div>
                    <button
                      onClick={(e) => {
                        e.preventDefault();
                        setSelectedFile(null);
                      }}
                      className="text-sm text-red-600 hover:text-red-800"
                    >
                      Remove file
                    </button>
                  </div>
                ) : (
                  <div className="space-y-4">
                    <CloudArrowUpIcon className="w-16 h-16 text-gray-400 mx-auto" />
                    <div>
                      <p className="text-lg font-medium text-gray-900">
                        Drag and drop your diagram here
                      </p>
                      <p className="text-sm text-gray-500 mt-1">or click to browse</p>
                    </div>
                    <p className="text-xs text-gray-400">
                      Supports PDF, PNG, JPG, JPEG (Max 10MB)
                    </p>
                  </div>
                )}
              </div>

              {/* Error Message */}
              {error && (
                <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-lg flex items-start">
                  <ExclamationTriangleIcon className="w-5 h-5 text-red-600 mr-2 flex-shrink-0 mt-0.5" />
                  <p className="text-sm text-red-800">{error}</p>
                </div>
              )}

              {/* Upload Button */}
              <div className="mt-6">
                <button
                  onClick={handleUpload}
                  disabled={!selectedFile || !selectedType || uploading}
                  className={`w-full py-4 px-6 rounded-lg font-semibold text-white transition-all ${
                    !selectedFile || !selectedType || uploading
                      ? 'bg-gray-300 cursor-not-allowed'
                      : 'bg-gradient-to-r from-yellow-600 to-orange-600 hover:from-yellow-700 hover:to-orange-700 shadow-lg hover:shadow-xl'
                  }`}
                >
                  {uploading ? (
                    <span className="flex items-center justify-center">
                      <ArrowPathIcon className="w-5 h-5 mr-2 animate-spin" />
                      Validating... {uploadProgress}%
                    </span>
                  ) : (
                    <span className="flex items-center justify-center">
                      <SparklesIcon className="w-5 h-5 mr-2" />
                      Validate with AI
                    </span>
                  )}
                </button>
              </div>

              {/* Info Banner */}
              <div className="mt-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
                <div className="flex">
                  <DocumentTextIcon className="w-5 h-5 text-blue-600 mr-2 flex-shrink-0" />
                  <div className="text-sm text-blue-800">
                    <p className="font-semibold mb-1">AI-Powered Validation</p>
                    <p>Your diagram will be automatically validated against ADNOC standards using OpenAI GPT-4. The system will check:</p>
                    <ul className="list-disc list-inside mt-2 space-y-1">
                      <li>Technical specifications compliance</li>
                      <li>Safety standards adherence</li>
                      <li>Design parameters verification</li>
                      <li>Documentation completeness</li>
                    </ul>
                  </div>
                </div>
              </div>
            </div>
          </>
        ) : (
          /* Validation Results */
          <div className="bg-white rounded-lg shadow-lg p-8">
            <div className="flex items-center justify-between mb-6">
              <h2 className="text-2xl font-bold text-gray-900">Validation Results</h2>
              <div className="flex space-x-3">
                <button
                  onClick={handleExportToExcel}
                  className="px-4 py-2 text-sm font-medium text-white bg-green-600 hover:bg-green-700 rounded-lg flex items-center shadow-md transition-all"
                >
                  <ArrowDownTrayIcon className="w-5 h-5 mr-2" />
                  Export to Excel
                </button>
                <button
                  onClick={resetUpload}
                  className="px-4 py-2 text-sm font-medium text-gray-700 bg-gray-100 hover:bg-gray-200 rounded-lg"
                >
                  Upload New Diagram
                </button>
              </div>
            </div>

            {/* Validation Score */}
            <div className="mb-6 p-6 bg-gradient-to-r from-green-50 to-blue-50 rounded-lg border border-green-200">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-600">Compliance Score</p>
                  <p className="text-4xl font-bold text-green-600 mt-2">
                    {validationResult.compliance_score}%
                  </p>
                </div>
                {validationResult.compliance_score >= 80 ? (
                  <CheckCircleIcon className="w-16 h-16 text-green-600" />
                ) : validationResult.compliance_score >= 60 ? (
                  <ExclamationTriangleIcon className="w-16 h-16 text-yellow-600" />
                ) : (
                  <XCircleIcon className="w-16 h-16 text-red-600" />
                )}
              </div>
            </div>

            {/* Validation Details */}
            <div className="space-y-6">
              {/* Extracted Data Section */}
              {validationResult.extracted_data && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-3">Extracted Data</h3>
                  <div className="bg-blue-50 border border-blue-200 rounded-lg p-4">
                    <div className="grid grid-cols-2 gap-4">
                      {Object.entries(validationResult.extracted_data).map(([key, value]) => (
                        <div key={key} className="flex justify-between items-center">
                          <span className="text-sm font-medium text-gray-700 capitalize">{key.replace('_', ' ')}:</span>
                          <span className={`text-sm ${value === 'NOT FOUND' ? 'text-red-600 font-semibold' : 'text-gray-900'}`}>
                            {typeof value === 'object' ? JSON.stringify(value) : value}
                          </span>
                        </div>
                      ))}
                    </div>
                  </div>
                </div>
              )}

              {/* Missing Data with Intelligent Defaults */}
              {validationResult.missing_data && validationResult.missing_data.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-3">Missing Parameters & AI Recommendations</h3>
                  <div className="space-y-3">
                    {validationResult.missing_data.map((item, index) => (
                      <div
                        key={index}
                        className={`p-4 rounded-lg border ${
                          item.criticality === 'HIGH'
                            ? 'bg-red-50 border-red-300'
                            : item.criticality === 'MEDIUM'
                            ? 'bg-yellow-50 border-yellow-300'
                            : 'bg-gray-50 border-gray-300'
                        }`}
                      >
                        <div className="flex items-start">
                          <ExclamationTriangleIcon 
                            className={`w-5 h-5 mr-3 flex-shrink-0 mt-0.5 ${
                              item.criticality === 'HIGH'
                                ? 'text-red-600'
                                : item.criticality === 'MEDIUM'
                                ? 'text-yellow-600'
                                : 'text-gray-600'
                            }`}
                          />
                          <div className="flex-1">
                            <div className="flex items-center justify-between mb-2">
                              <p className="font-medium text-gray-900">{item.parameter}</p>
                              <span className={`px-2 py-1 text-xs font-semibold rounded ${
                                item.criticality === 'HIGH'
                                  ? 'bg-red-100 text-red-800'
                                  : item.criticality === 'MEDIUM'
                                  ? 'bg-yellow-100 text-yellow-800'
                                  : 'bg-gray-100 text-gray-800'
                              }`}>
                                {item.criticality}
                              </span>
                            </div>
                            <div className="bg-white rounded px-3 py-2 mb-2">
                              <p className="text-sm text-gray-600">
                                <span className="font-semibold text-green-700">AI Suggested Default: </span>
                                {item.suggested_default}
                              </p>
                            </div>
                            <p className="text-xs text-gray-600 italic">
                              💡 Reasoning: {item.reasoning}
                            </p>
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Validation Results */}
              <div>
                <h3 className="text-lg font-semibold text-gray-900 mb-3">ADNOC Standards Validation</h3>
                {validationResult.validation_results && (
                  <div className="space-y-3">
                    {validationResult.validation_results.map((result, index) => (
                      <div
                        key={index}
                        className={`p-4 rounded-lg border ${
                          result.passed
                            ? 'bg-green-50 border-green-200'
                            : 'bg-red-50 border-red-200'
                        }`}
                      >
                        <div className="flex items-start">
                          {result.passed ? (
                            <CheckCircleIcon className="w-5 h-5 text-green-600 mr-3 flex-shrink-0 mt-0.5" />
                          ) : (
                            <XCircleIcon className="w-5 h-5 text-red-600 mr-3 flex-shrink-0 mt-0.5" />
                          )}
                          <div className="flex-1">
                            <p className="font-medium text-gray-900">{result.parameter}</p>
                            {result.expected && (
                              <p className="text-xs text-gray-500 mt-1">
                                Expected: {result.expected} | Found: {result.found || 'MISSING'}
                              </p>
                            )}
                            <p className="text-sm text-gray-600 mt-1">{result.message}</p>
                            {result.recommendation && (
                              <p className="text-sm text-blue-600 mt-2">
                                💡 {result.recommendation}
                              </p>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
              )}

              {/* AI Analysis */}
              {validationResult.ai_analysis && (
                <div className="mt-6 p-6 bg-purple-50 border border-purple-200 rounded-lg">
                  <h4 className="font-semibold text-purple-900 mb-3 flex items-center">
                    <SparklesIcon className="w-5 h-5 mr-2" />
                    AI Analysis
                  </h4>
                  <p className="text-sm text-purple-800 whitespace-pre-line">
                    {validationResult.ai_analysis}
                  </p>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default ElectricalDatasheetPage;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import apiClient from '../../../services/api.service';
import {
  CloudArrowUpIcon,
  DocumentTextIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowPathIcon,
  BoltIcon,
  SparklesIcon,
  ExclamationTriangleIcon,
  ArrowDownTrayIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  PlusIcon
} from '@heroicons/react/24/outline';

const ElectricalDatasheetPage = () => {
  const [datasheets, setDatasheets] = useState([]);
  const [equipmentTypes, setEquipmentTypes] = useState([]);
  const [loading, setLoading] = useState(true);
  const [statistics, setStatistics] = useState(null);
  
  // Filters
  const [searchQuery, setSearchQuery] = useState('');
  const [statusFilter, setStatusFilter] = useState('all');
  const [equipmentFilter, setEquipmentFilter] = useState('all');
  
  // Modal states
  const [showUploadModal, setShowUploadModal] = useState(false);
  const [showResultModal, setShowResultModal] = useState(false);
  const [selectedType, setSelectedType] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);
  const [dragActive, setDragActive] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [validationResult, setValidationResult] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    loadData();
  }, []);

  const loadData = async () => {
    try {
      setLoading(true);
      const [datasheetsRes, typesRes, statsRes] = await Promise.all([
        apiClient.get('/electrical-datasheet/datasheets/'),
        apiClient.get('/electrical-datasheet/equipment-types/'),
        apiClient.get('/electrical-datasheet/datasheets/statistics/')
      ]);
      
      setDatasheets(datasheetsRes.data?.results || datasheetsRes.data || []);
      setEquipmentTypes(typesRes.data?.results || typesRes.data || []);
      setStatistics(statsRes.data || null);
    } catch (err) {
      console.error('Error loading data:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleDrag = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (e.type === "dragenter" || e.type === "dragover") {
      setDragActive(true);
    } else if (e.type === "dragleave") {
      setDragActive(false);
    }
  };

  const handleDrop = (e) => {
    e.preventDefault();
    e.stopPropagation();
    setDragActive(false);
    
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      handleFile(e.dataTransfer.files[0]);
    }
  };

  const handleFileInput = (e) => {
    if (e.target.files && e.target.files[0]) {
      handleFile(e.target.files[0]);
    }
  };

  const handleFile = (file) => {
    const allowedTypes = ['application/pdf', 'image/png', 'image/jpeg', 'image/jpg'];
    if (!allowedTypes.includes(file.type)) {
      setError('Please upload PDF or image files only (PDF, PNG, JPG, JPEG)');
      return;
    }

    if (file.size > 10 * 1024 * 1024) {
      setError('File size must be less than 10MB');
      return;
    }

    setSelectedFile(file);
    setError(null);
  };

  const handleUploadAndValidate = async (e) => {
    e.preventDefault();
    
    if (!selectedFile || !selectedType) {
      setError('Please select equipment type and file');
      return;
    }

    setUploading(true);
    setUploadProgress(0);
    setError(null);

    try {
      const formData = new FormData();
      formData.append('file', selectedFile);
      formData.append('equipment_type_id', selectedType);

      setUploadProgress(30);

      const response = await apiClient.post(
        '/electrical-datasheet/datasheets/validate_diagram/',
        formData,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
          },
        }
      );

      setUploadProgress(100);
      setValidationResult(response.data);
      setShowUploadModal(false);
      setShowResultModal(true);
      loadData(); // Refresh data
    } catch (err) {
      console.error('Upload error:', err);
      setError(err.response?.data?.error || 'Upload failed. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  const handleExportToExcel = async () => {
    try {
      const response = await apiClient.post(
        '/electrical-datasheet/datasheets/export-validation/',
        validationResult,
        {
          responseType: 'blob',
        }
      );

      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `electrical_validation_${new Date().toISOString().slice(0, 10)}.xlsx`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Export error:', err);
      setError('Failed to export to Excel. Please try again.');
    }
  };

  const resetUpload = () => {
    setShowUploadModal(false);
    setShowResultModal(false);
    setSelectedFile(null);
    setSelectedType('');
    setValidationResult(null);
    setError(null);
    setUploadProgress(0);
  };

  const filteredDatasheets = datasheets.filter(sheet => {
    const matchesSearch = !searchQuery || 
      sheet.equipment_name?.toLowerCase().includes(searchQuery.toLowerCase()) ||
      sheet.tag_number?.toLowerCase().includes(searchQuery.toLowerCase());
    
    const matchesStatus = statusFilter === 'all' || sheet.status === statusFilter;
    const matchesEquipment = equipmentFilter === 'all' || sheet.equipment_type === parseInt(equipmentFilter);
    
    return matchesSearch && matchesStatus && matchesEquipment;
  });

  const getStatusColor = (status) => {
    const colors = {
      'draft': 'bg-gray-100 text-gray-800',
      'validated': 'bg-blue-100 text-blue-800',
      'in_review': 'bg-yellow-100 text-yellow-800',
      'approved': 'bg-green-100 text-green-800',
      'rejected': 'bg-red-100 text-red-800',
    };
    return colors[status] || 'bg-gray-100 text-gray-800';
  };

  const getComplianceColor = (score) => {
    if (score >= 90) return 'text-green-600 bg-green-50';
    if (score >= 70) return 'text-yellow-600 bg-yellow-50';
    return 'text-red-600 bg-red-50';
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen bg-gray-50">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-4 border-yellow-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading datasheets...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50 py-6 sm:py-8 px-4 sm:px-6">
      {/* Header */}
      <div className="mb-6 sm:mb-8 flex flex-col sm:flex-row justify-between items-start gap-4">
        <div>
          <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold text-gray-900 mb-2 flex items-center gap-3">
            <BoltIcon className="w-10 h-10 text-yellow-600" />
            Electrical Datasheets
          </h1>
          <p className="text-sm sm:text-base text-gray-600">
            AI-Powered ADNOC Standards Verification & Validation
          </p>
        </div>
        <button
          onClick={() => setShowUploadModal(true)}
          className="px-6 py-3 bg-gradient-to-r from-yellow-600 to-orange-600 text-white rounded-xl hover:shadow-lg transition-all font-semibold flex items-center gap-2"
        >
          <CloudArrowUpIcon className="w-5 h-5" />
          Upload & Validate
        </button>
      </div>

      {/* Statistics Cards */}
      {statistics && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-6 mb-8">
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 bg-blue-500 rounded-md p-3">
                <DocumentTextIcon className="h-6 w-6 text-white" />
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">Total Datasheets</dt>
                  <dd className="text-3xl font-semibold text-gray-900">{statistics.total || datasheets.length}</dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 bg-green-500 rounded-md p-3">
                <CheckCircleIcon className="h-6 w-6 text-white" />
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">Approved</dt>
                  <dd className="text-3xl font-semibold text-gray-900">{statistics.approved || 0}</dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 bg-yellow-500 rounded-md p-3">
                <ExclamationTriangleIcon className="h-6 w-6 text-white" />
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">In Review</dt>
                  <dd className="text-3xl font-semibold text-gray-900">{statistics.in_review || 0}</dd>
                </dl>
              </div>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center">
              <div className="flex-shrink-0 bg-purple-500 rounded-md p-3">
                <SparklesIcon className="h-6 w-6 text-white" />
              </div>
              <div className="ml-5 w-0 flex-1">
                <dl>
                  <dt className="text-sm font-medium text-gray-500 truncate">Avg Compliance</dt>
                  <dd className="text-3xl font-semibold text-gray-900">{statistics.avg_compliance || 0}%</dd>
                </dl>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Filters */}
      <div className="bg-white rounded-lg shadow mb-6 p-4">
        <div className="flex flex-col md:flex-row md:items-center md:justify-between gap-4">
          <div className="flex flex-col md:flex-row gap-4 flex-1">
            {/* Search */}
            <div className="flex-1 relative">
              <MagnifyingGlassIcon className="w-5 h-5 absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400" />
              <input
                type="text"
                placeholder="Search datasheets..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
              />
            </div>

            {/* Equipment Type Filter */}
            <select
              value={equipmentFilter}
              onChange={(e) => setEquipmentFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
            >
              <option value="all">All Equipment</option>
              {equipmentTypes.map(type => (
                <option key={type.id} value={type.id}>{type.name}</option>
              ))}
            </select>

            {/* Status Filter */}
            <select
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-yellow-500 focus:border-transparent"
            >
              <option value="all">All Status</option>
              <option value="draft">Draft</option>
              <option value="validated">Validated</option>
              <option value="in_review">In Review</option>
              <option value="approved">Approved</option>
              <option value="rejected">Rejected</option>
            </select>
          </div>
        </div>
      </div>

      {/* Datasheets Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {filteredDatasheets.map(sheet => (
          <div key={sheet.id} className="bg-white rounded-lg shadow hover:shadow-lg transition-shadow">
            <div className="p-6">
              {/* Header */}
              <div className="flex items-start justify-between mb-4">
                <div className="flex-1">
                  <h3 className="text-lg font-semibold text-gray-900 mb-1">
                    {sheet.equipment_name || 'Unnamed Equipment'}
                  </h3>
                  {sheet.tag_number && (
                    <p className="text-sm text-gray-500">Tag: {sheet.tag_number}</p>
                  )}
                  {sheet.equipment_type_name && (
                    <p className="text-xs text-gray-400 mt-1">Type: {sheet.equipment_type_name}</p>
                  )}
                </div>
                <span className={`px-3 py-1 rounded-full text-xs font-medium ${getStatusColor(sheet.status)}`}>
                  {sheet.status?.replace('_', ' ').toUpperCase()}
                </span>
              </div>

              {/* Compliance Score */}
              {sheet.compliance_score !== undefined && (
                <div className="mb-4">
                  <div className="flex items-center justify-between text-sm text-gray-600 mb-1">
                    <span>ADNOC Compliance</span>
                    <span className={`font-bold ${getComplianceColor(sheet.compliance_score).split(' ')[0]}`}>
                      {sheet.compliance_score}%
                    </span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-2">
                    <div
                      className={`h-2 rounded-full transition-all duration-300 ${
                        sheet.compliance_score >= 90 ? 'bg-green-600' :
                        sheet.compliance_score >= 70 ? 'bg-yellow-600' : 'bg-red-600'
                      }`}
                      style={{ width: `${sheet.compliance_score}%` }}
                    ></div>
                  </div>
                </div>
              )}

              {/* Specifications */}
              <div className="mb-4 space-y-2">
                {sheet.voltage && (
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Voltage:</span>
                    <span className="font-medium text-gray-900">{sheet.voltage}</span>
                  </div>
                )}
                {sheet.current && (
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Current:</span>
                    <span className="font-medium text-gray-900">{sheet.current}</span>
                  </div>
                )}
                {sheet.power && (
                  <div className="flex justify-between text-sm">
                    <span className="text-gray-500">Power:</span>
                    <span className="font-medium text-gray-900">{sheet.power}</span>
                  </div>
                )}
              </div>

              {/* Actions */}
              <div className="flex flex-wrap gap-2">
                <Link
                  to={`/engineering/electrical/datasheet/${sheet.id}`}
                  className="flex-1 text-center px-4 py-2 bg-yellow-600 text-white rounded-lg hover:bg-yellow-700 transition-colors text-sm font-medium"
                >
                  View Details
                </Link>
                
                {sheet.has_validation && (
                  <button
                    onClick={() => {
                      setValidationResult(sheet.validation_data);
                      setShowResultModal(true);
                    }}
                    className="px-4 py-2 bg-green-100 text-green-700 rounded-lg hover:bg-green-200 transition-colors text-sm font-medium"
                  >
                    📊 Results
                  </button>
                )}
              </div>

              {/* Timestamps */}
              {sheet.created_at && (
                <div className="mt-3 pt-3 border-t border-gray-200">
                  <p className="text-xs text-gray-500">
                    Created: {new Date(sheet.created_at).toLocaleDateString()}
                  </p>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Empty State */}
      {filteredDatasheets.length === 0 && (
        <div className="bg-white rounded-lg shadow p-12 text-center">
          <BoltIcon className="mx-auto h-12 w-12 text-gray-400" />
          <h3 className="mt-2 text-sm font-medium text-gray-900">No datasheets found</h3>
          <p className="mt-1 text-sm text-gray-500">Get started by uploading and validating an electrical diagram.</p>
          <div className="mt-6">
            <button
              onClick={() => setShowUploadModal(true)}
              className="inline-flex items-center gap-2 px-6 py-3 shadow-lg text-sm font-semibold rounded-xl text-white bg-gradient-to-r from-yellow-600 to-orange-600 hover:shadow-xl transition-all"
            >
              <CloudArrowUpIcon className="w-5 h-5" />
              Upload & Validate
            </button>
          </div>
        </div>
      )}

      {/* Upload & Validate Modal */}
      {showUploadModal && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50">
          <div className="bg-white rounded-2xl max-w-3xl w-full max-h-[90vh] overflow-y-auto shadow-2xl">
            {/* Header */}
            <div className="bg-gradient-to-r from-yellow-600 to-orange-600 p-6 rounded-t-2xl">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-bold text-white mb-2 flex items-center gap-2">
                    <SparklesIcon className="w-7 h-7" />
                    AI-Powered Diagram Validation
                  </h2>
                  <p className="text-yellow-100 text-sm">
                    Upload electrical diagram for instant ADNOC standards verification
                  </p>
                </div>
                <button
                  onClick={resetUpload}
                  className="text-white hover:bg-white/20 rounded-lg p-2 transition-colors"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            <form onSubmit={handleUploadAndValidate} className="p-6">
              {/* Equipment Type Selection */}
              <div className="mb-6">
                <label className="block text-sm font-semibold text-gray-700 mb-3">
                  ⚡ Select Equipment Type *
                </label>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {equipmentTypes.map((type) => (
                    <button
                      key={type.id}
                      type="button"
                      onClick={() => setSelectedType(type.id)}
                      className={`p-4 border-2 rounded-lg transition-all text-left ${
                        selectedType === type.id
                          ? 'border-yellow-600 bg-yellow-50 shadow-md'
                          : 'border-gray-200 hover:border-yellow-400 hover:shadow-sm'
                      }`}
                    >
                      <div className="flex items-center">
                        <div className="text-3xl mr-3">{type.icon || '⚡'}</div>
                        <div>
                          <p className="font-semibold text-gray-900">{type.name}</p>
                          <p className="text-xs text-gray-600 mt-1">{type.description}</p>
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>

              {/* File Upload Section */}
              <div className="mb-6">
                <label className="block text-sm font-semibold text-gray-700 mb-3">
                  📄 Upload Diagram (PDF or Image) *
                </label>
                <div
                  onDragEnter={handleDrag}
                  onDragLeave={handleDrag}
                  onDragOver={handleDrag}
                  onDrop={handleDrop}
                  className={`relative border-2 border-dashed rounded-xl p-8 text-center transition-all ${
                    dragActive
                      ? 'border-yellow-600 bg-yellow-50'
                      : 'border-gray-300 hover:border-yellow-500 bg-gray-50'
                  }`}
                >
                  <input
                    type="file"
                    accept=".pdf,.png,.jpg,.jpeg"
                    onChange={handleFileInput}
                    required
                    className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
                  />
                  
                  {!selectedFile ? (
                    <div>
                      <CloudArrowUpIcon className="mx-auto h-12 w-12 text-gray-400" />
                      <p className="mt-2 text-sm text-gray-600">
                        <span className="font-semibold text-yellow-600">Click to upload</span> or drag and drop
                      </p>
                      <p className="mt-1 text-xs text-gray-500">
                        PDF, PNG, JPG, JPEG up to 10MB
                      </p>
                    </div>
                  ) : (
                    <div className="flex items-center justify-center gap-3">
                      <div className="w-12 h-12 bg-green-100 rounded-xl flex items-center justify-center">
                        <DocumentTextIcon className="w-6 h-6 text-green-600" />
                      </div>
                      <div className="text-left">
                        <p className="font-semibold text-gray-900">{selectedFile.name}</p>
                        <p className="text-sm text-gray-500">
                          {(selectedFile.size / 1024 / 1024).toFixed(2)} MB
                        </p>
                      </div>
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          setSelectedFile(null);
                        }}
                        className="ml-4 text-red-600 hover:text-red-800"
                      >
                        <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                        </svg>
                      </button>
                    </div>
                  )}
                </div>
                
                {/* Info Banner */}
                <div className="mt-3 p-3 bg-blue-50 rounded-lg border border-blue-200">
                  <div className="flex items-start gap-2">
                    <SparklesIcon className="w-5 h-5 text-blue-600 flex-shrink-0 mt-0.5" />
                    <div className="text-xs text-blue-900">
                      <p className="font-semibold mb-1">AI Validation Process:</p>
                      <ul className="list-disc list-inside space-y-0.5">
                        <li>Extract all technical specifications automatically</li>
                        <li>Validate against ADNOC-AGES standards</li>
                        <li>Identify missing critical parameters</li>
                        <li>Provide intelligent recommendations</li>
                        <li>Generate comprehensive Excel report</li>
                      </ul>
                    </div>
                  </div>
                </div>
              </div>

              {/* Error Message */}
              {error && (
                <div className="mb-6 p-4 rounded-xl bg-red-50 border-2 border-red-200">
                  <div className="flex items-start gap-3">
                    <XCircleIcon className="w-6 h-6 text-red-600 flex-shrink-0" />
                    <p className="text-sm text-red-700">{error}</p>
                  </div>
                </div>
              )}

              {/* Action Buttons */}
              <div className="flex gap-3">
                <button
                  type="button"
                  onClick={resetUpload}
                  className="flex-1 px-6 py-3 border-2 border-gray-300 text-gray-700 rounded-xl hover:bg-gray-50 transition-colors font-semibold"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={!selectedFile || !selectedType || uploading}
                  className={`flex-1 px-6 py-3 rounded-xl font-semibold transition-all flex items-center justify-center gap-2 ${
                    !selectedFile || !selectedType || uploading
                      ? 'bg-gray-300 text-gray-500 cursor-not-allowed'
                      : 'bg-gradient-to-r from-yellow-600 to-orange-600 text-white hover:shadow-lg hover:scale-105'
                  }`}
                >
                  {uploading ? (
                    <>
                      <ArrowPathIcon className="w-5 h-5 animate-spin" />
                      Validating... {uploadProgress}%
                    </>
                  ) : (
                    <>
                      <SparklesIcon className="w-5 h-5" />
                      Validate with AI
                    </>
                  )}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Validation Results Modal */}
      {showResultModal && validationResult && (
        <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center p-4 z-50 overflow-y-auto">
          <div className="bg-white rounded-2xl max-w-5xl w-full max-h-[90vh] overflow-hidden shadow-2xl flex flex-col my-8">
            {/* Header */}
            <div className="bg-gradient-to-r from-green-600 to-emerald-600 p-6">
              <div className="flex items-center justify-between">
                <div>
                  <h2 className="text-2xl font-bold text-white mb-2">
                    ✅ Validation Complete
                  </h2>
                  <p className="text-green-100 text-sm">
                    {validationResult.equipment_type} • ADNOC Standards Analysis
                  </p>
                </div>
                <button
                  onClick={resetUpload}
                  className="text-white hover:bg-white/20 rounded-lg p-2 transition-colors"
                >
                  <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                  </svg>
                </button>
              </div>
            </div>

            {/* Compliance Score Banner */}
            <div className="p-6 bg-gradient-to-r from-green-50 to-blue-50 border-b border-green-200">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-medium text-gray-600">Overall Compliance Score</p>
                  <p className="text-5xl font-bold text-green-600 mt-2">
                    {validationResult.compliance_score}%
                  </p>
                </div>
                <div className="flex flex-col gap-2">
                  <button
                    onClick={handleExportToExcel}
                    className="px-6 py-3 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-all font-semibold flex items-center gap-2 shadow-md"
                  >
                    <ArrowDownTrayIcon className="w-5 h-5" />
                    Export to Excel
                  </button>
                </div>
              </div>
            </div>

            {/* Content */}
            <div className="flex-1 overflow-y-auto p-6 space-y-6">
              {/* Extracted Data */}
              {validationResult.extracted_data && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-3 flex items-center gap-2">
                    <CheckCircleIcon className="w-6 h-6 text-blue-600" />
                    Extracted Parameters
                  </h3>
                  <div className="bg-white border border-gray-200 rounded-lg p-4">
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                      {Object.entries(validationResult.extracted_data).map(([key, value]) => {
                        if (key === 'additional_specs') return null;
                        return (
                          <div key={key} className="p-3 bg-gray-50 rounded-lg">
                            <p className="text-xs text-gray-500 font-medium uppercase">{key.replace('_', ' ')}</p>
                            <p className={`text-lg font-semibold mt-1 ${value === 'NOT FOUND' ? 'text-red-600' : 'text-gray-900'}`}>
                              {value === 'NOT FOUND' ? 'Not Found' : value}
                            </p>
                          </div>
                        );
                      })}
                    </div>
                  </div>
                </div>
              )}

              {/* Missing Parameters */}
              {validationResult.missing_data && validationResult.missing_data.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-3 flex items-center gap-2">
                    <ExclamationTriangleIcon className="w-6 h-6 text-yellow-600" />
                    Missing Parameters & Recommendations
                  </h3>
                  <div className="space-y-3">
                    {validationResult.missing_data.map((item, index) => (
                      <div key={index} className="bg-white border border-gray-200 rounded-lg p-4">
                        <div className="flex items-start justify-between mb-2">
                          <p className="font-semibold text-gray-900">{item.parameter}</p>
                          <span className={`px-2 py-1 rounded text-xs font-bold ${
                            item.criticality === 'HIGH' ? 'bg-red-100 text-red-700' :
                            item.criticality === 'MEDIUM' ? 'bg-yellow-100 text-yellow-700' :
                            'bg-gray-100 text-gray-700'
                          }`}>
                            {item.criticality}
                          </span>
                        </div>
                        <p className="text-sm text-gray-600 mb-2">
                          <span className="font-medium">Suggested:</span> {item.suggested_default}
                        </p>
                        <p className="text-xs text-gray-500">{item.reasoning}</p>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* Validation Results */}
              {validationResult.validation_results && validationResult.validation_results.length > 0 && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-3 flex items-center gap-2">
                    <DocumentTextIcon className="w-6 h-6 text-purple-600" />
                    ADNOC Standards Validation
                  </h3>
                  <div className="space-y-2">
                    {validationResult.validation_results.map((item, index) => (
                      <div key={index} className={`p-4 rounded-lg border ${
                        item.passed ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'
                      }`}>
                        <div className="flex items-start justify-between">
                          <div className="flex-1">
                            <p className="font-semibold text-gray-900">{item.parameter}</p>
                            <div className="mt-2 text-sm">
                              <p className="text-gray-600">
                                <span className="font-medium">Expected:</span> {item.expected}
                              </p>
                              <p className="text-gray-600">
                                <span className="font-medium">Found:</span> {item.found}
                              </p>
                              {item.recommendation && (
                                <p className="text-gray-700 mt-1">
                                  <span className="font-medium">→</span> {item.recommendation}
                                </p>
                              )}
                            </div>
                          </div>
                          {item.passed ? (
                            <CheckCircleIcon className="w-6 h-6 text-green-600 flex-shrink-0" />
                          ) : (
                            <XCircleIcon className="w-6 h-6 text-red-600 flex-shrink-0" />
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {/* AI Analysis */}
              {validationResult.ai_analysis && (
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-3 flex items-center gap-2">
                    <SparklesIcon className="w-6 h-6 text-indigo-600" />
                    Comprehensive Analysis
                  </h3>
                  <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                    <pre className="whitespace-pre-wrap text-sm text-gray-700 font-mono">
                      {validationResult.ai_analysis}
                    </pre>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default ElectricalDatasheetPage;

import { radaiAlert } from '../../../services/radaiDialog'
import React, { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  MagnifyingGlassIcon,
  FunnelIcon,
  ChevronDownIcon,
  ChevronUpIcon,
  RocketLaunchIcon,
  CheckCircleIcon
} from '@heroicons/react/24/outline';
import {
  ELECTRICAL_DOCUMENTS,
  DOCUMENT_CATEGORIES,
  CATEGORY_DISPLAY_NAMES,
  CATEGORY_DESCRIPTIONS,
  getDocumentsByCategory,
  getCategoryStats,
  DOCUMENT_STATUS,
  ELECTRICAL_DOCUMENTS_FEATURE_ENABLED // SOFT-CODED: Feature flag for content visibility
} from '../../../config/electricalDocuments.config';

/**
 * Electrical Documents Hub - Smart Unified Interface
 * Configuration-driven approach handling all 27 electrical initiatives
 */
const ElectricalDocumentsHub = () => {
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [statusFilter, setStatusFilter] = useState('all');
  const [expandedCategories, setExpandedCategories] = useState({
    [DOCUMENT_CATEGORIES.DATASHEETS]: true,
    [DOCUMENT_CATEGORIES.CALCULATIONS]: true,
    [DOCUMENT_CATEGORIES.DIAGRAMS]: true,
    [DOCUMENT_CATEGORIES.LOAD_LISTS]: true,
    [DOCUMENT_CATEGORIES.STUDIES]: true,
    [DOCUMENT_CATEGORIES.SCHEDULES]: true
  });

  // SOFT-CODED: Return "Coming Soon" page when feature is disabled
  if (!ELECTRICAL_DOCUMENTS_FEATURE_ENABLED) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-yellow-50 via-orange-50 to-amber-50 flex items-center justify-center p-4">
        <div className="max-w-2xl w-full">
          {/* Coming Soon Card */}
          <div className="bg-white rounded-2xl shadow-2xl p-8 md:p-12 border-4 border-yellow-400">
            {/* Icon */}
            <div className="flex justify-center mb-6">
              <div className="w-24 h-24 bg-gradient-to-br from-yellow-400 to-orange-500 rounded-full flex items-center justify-center shadow-lg">
                <RocketLaunchIcon className="h-14 w-14 text-white" />
              </div>
            </div>

            {/* Coming Soon Badge */}
            <div className="flex justify-center mb-4">
              <span className="inline-flex items-center px-6 py-2 rounded-full text-sm font-bold bg-gradient-to-r from-yellow-400 to-orange-500 text-white shadow-lg">
                🚀 COMING SOON
              </span>
            </div>

            {/* Title */}
            <h1 className="text-4xl md:text-5xl font-bold text-center text-gray-900 mb-4">
              Electrical Engineering Documents
            </h1>

            {/* Subtitle */}
            <p className="text-xl text-center text-gray-600 mb-8">
              Comprehensive suite of electrical engineering initiatives
            </p>

            {/* Description */}
            <div className="bg-gradient-to-r from-yellow-50 to-orange-50 rounded-lg p-6 mb-8 border border-yellow-200">
              <p className="text-center text-gray-700 leading-relaxed">
                We're working on something amazing! This module will include <span className="font-semibold text-yellow-700">27 electrical engineering initiatives</span> covering technical datasheets, calculations, diagrams, layouts, and schedules - everything you need in one unified platform.
              </p>
            </div>

            {/* Features Grid */}
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4 mb-8">
              <div className="text-center p-4 bg-yellow-50 rounded-lg border border-yellow-200">
                <div className="text-2xl font-bold text-yellow-600">11+</div>
                <div className="text-sm text-gray-600">Datasheets</div>
              </div>
              <div className="text-center p-4 bg-orange-50 rounded-lg border border-orange-200">
                <div className="text-2xl font-bold text-orange-600">7+</div>
                <div className="text-sm text-gray-600">Diagrams</div>
              </div>
              <div className="text-center p-4 bg-amber-50 rounded-lg border border-amber-200">
                <div className="text-2xl font-bold text-amber-600">9+</div>
                <div className="text-sm text-gray-600">Tools</div>
              </div>
            </div>

            {/* Footer Message */}
            <div className="text-center">
              <p className="text-gray-500 text-sm">
                Stay tuned for updates! This feature is under active development.
              </p>
            </div>
          </div>

          {/* Bottom Note */}
          <div className="text-center mt-6">
            <p className="text-gray-600 text-sm">
              Questions? Contact your system administrator for more information.
            </p>
          </div>
        </div>
      </div>
    );
  }

  // Debug log to verify component is rendering
  console.log('[ElectricalDocumentsHub] Component rendered');
  console.log('[ElectricalDocumentsHub] Total documents:', ELECTRICAL_DOCUMENTS.length);
  console.log('[ElectricalDocumentsHub] Categories:', Object.keys(DOCUMENT_CATEGORIES));

  const categoryStats = useMemo(() => getCategoryStats(), []);

  // Filter documents based on search, category, and status
  const filteredDocuments = useMemo(() => {
    return ELECTRICAL_DOCUMENTS.filter(doc => {
      // Search filter
      const matchesSearch = searchQuery === '' || 
        doc.name.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.fullName.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.description.toLowerCase().includes(searchQuery.toLowerCase()) ||
        doc.code.toLowerCase().includes(searchQuery.toLowerCase());

      // Category filter
      const matchesCategory = selectedCategory === 'all' || doc.category === selectedCategory;

      // Status filter
      const matchesStatus = statusFilter === 'all' || doc.status === statusFilter;

      return matchesSearch && matchesCategory && matchesStatus;
    });
  }, [searchQuery, selectedCategory, statusFilter]);

  // Group filtered documents by category
  const groupedDocuments = useMemo(() => {
    const grouped = {};
    Object.values(DOCUMENT_CATEGORIES).forEach(category => {
      grouped[category] = filteredDocuments.filter(doc => doc.category === category);
    });
    return grouped;
  }, [filteredDocuments]);

  const toggleCategory = (category) => {
    setExpandedCategories(prev => ({
      ...prev,
      [category]: !prev[category]
    }));
  };

  const handleDocumentClick = async (doc) => {
    if (doc.status === DOCUMENT_STATUS.ACTIVE) {
      // SOFT-CODED: Use route from config if available, fallback to upload page
      const targetRoute = doc.route || '/engineering/electrical/datasheet/upload';
      navigate(targetRoute);
    } else {
      // Show coming soon message
      await radaiAlert(`${doc.name} is ${doc.status === DOCUMENT_STATUS.COMING_SOON ? 'coming soon' : 'in development'}!`);
