  );

  const refresh = (q = search) =>
    setProjects(listIoListProjects({ search: q }));

  useEffect(() => {
    refresh();
  }, []); // eslint-disable-line react-hooks/exhaustive-deps

  const onSearch = (e) => {
    const v = e.target.value;
    setSearch(v);
    refresh(v);
  };

  const resetForm = () =>
    setForm(
      Object.fromEntries(
        IO_LIST_PROJECT_FIELDS.map((f) => [f.key, f.defaultValue || ""]),
      ),
    );

  const submitCreate = (e) => {
    e.preventDefault();
    try {
      const required = IO_LIST_PROJECT_FIELDS.filter((f) => f.required);
      for (const f of required) {
        if (!String(form[f.key] || "").trim()) {
          toast.warn(`${f.label} is required.`);
          return;
        }
      }
      if (editing) {
        updateIoListProject(editing.id, form);
        toast.success("Project updated.");
      } else {
        createIoListProject(form);
        toast.success("Project created.");
      }
      setShowCreate(false);
      setEditing(null);
      resetForm();
      refresh();
    } catch (err) {
      toast.error(err?.message || "Failed to save project.");
    }
  };

  const openEdit = (p) => {
    setEditing(p);
    setForm(
      Object.fromEntries(
        IO_LIST_PROJECT_FIELDS.map((f) => [
          f.key,
          p[f.key] ?? f.defaultValue ?? "",
        ]),
      ),
    );
    setShowCreate(true);
  };

  const doDelete = () => {
    if (!confirmDelete) return;
    deleteIoListProject(confirmDelete.id);
    setConfirmDelete(null);
    toast.success("Project deleted.");
    refresh();
  };

  return (
    <section
      className={`${LAYOUT_CONFIG.contentMaxW} ${LAYOUT_CONFIG.cardGapY}`}
