          <button
            type="button"
            onClick={() => {
              setEditing(null);
              resetForm();
              setShowCreate(true);
            }}
            className="inline-flex items-center gap-1.5 px-3 py-2 rounded-lg bg-white/15 hover:bg-white/25 text-white text-xs font-semibold backdrop-blur transition"
          >
            <FolderPlusIcon className="h-4 w-4" />
