                        Open
                      </button>
                      <button
                        type="button"
                        title="Edit"
                        onClick={() => openEdit(p)}
                        className="p-1.5 rounded-lg border border-gray-200 text-gray-600 hover:bg-gray-50"
                      >
                        <PencilSquareIcon className="h-4 w-4" />
                      </button>
                      <button
