                    <Fragment key={i}>
                    <tr
                      key={i}
                      className="border-t border-gray-100 hover:bg-purple-50/40 transition-colors"
                      style={{ animation: `itFadeUp .3s ease-out both`, animationDelay: `${Math.min(i, 30) * 12}ms` }}
                    >
                      <Td>{_str(it.row)}</Td>
