                            title="Re-validate this Excel file (line/column count, structural checks)"

                          >

                            <ArrowPathIcon className={`w-4 h-4 mr-1 ${rowActionId === output.id && rowActionType === 'recheck' ? 'animate-spin' : ''}`} />

