                <div className="mt-2 text-sm text-gray-600">

                  Example: {lineNumberFormat.components

                    .filter(c => c.enabled)

                    .sort((a, b) => a.order - b.order)

                    .map(c => c.example)

                    .join(lineNumberFormat.separator) || 'Configure components below'}

