        <div style={{ minHeight: 0, display: 'flex', flexDirection: 'column' }}>{wfCfg && <WorkflowDiagram cfg={wfCfg} />}</div>
        {docsPanel}
      </div>
    );
  }

  // ── Stacked fallback ──
  return (
    <div style={{ marginTop: '8px' }}>
      {wfCfg && <WorkflowDiagram cfg={wfCfg} />}
      {docsPanel}
    </div>
  );
};

