                  </label>
                  <select
                    id="hmb-case-preview"
                    value={casePreviewName}
                    onChange={(e) => {
                      setCasePreviewName(e.target.value);
                      setCasePreviewResolvedName('');
                    }}
                    style={{
                      fontSize: 11,
                      border: '1px solid #cbd5e1',
                      borderRadius: 7,
                      padding: '0 8px',
                      background: '#fff',
                      minWidth: 170,
                      height: 32,
                      boxSizing: 'border-box',
                    }}
                  >
                    <option value="">Latest imported case</option>
                    {casePreviewOptions.map((name) => (
                      <option key={name} value={name}>{name}</option>
                    ))}
                  </select>
                  <button
                    onClick={loadCasePreview}
                    style={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: 5,
                      fontSize: 11,
                      fontWeight: 700,
                      border: '1px solid #cbd5e1',
                      background: '#fff',
                      color: '#0f172a',
                      borderRadius: 7,
                      padding: '0 8px',
                      height: 32,
                      boxSizing: 'border-box',
                      cursor: 'pointer',
                    }}
                  >
                    <RefreshCw width={12} /> Refresh
                  </button>
                  <button
                    onClick={exportTemplateCanvasExcel}
                    disabled={templateCanvasModel.rows.length === 0}
                    style={{
                      display: 'inline-flex',
                      alignItems: 'center',
                      gap: 5,
                      fontSize: 11,
                      fontWeight: 700,
                      border: '1px solid #2563eb',
                      background: templateCanvasModel.rows.length === 0 ? '#e2e8f0' : '#2563eb',
                      color: templateCanvasModel.rows.length === 0 ? '#64748b' : '#ffffff',
                      borderRadius: 7,
                      padding: '0 10px',
                      height: 32,
                      boxSizing: 'border-box',
                      cursor: templateCanvasModel.rows.length === 0 ? 'not-allowed' : 'pointer',
                    }}
