                  <section aria-label="Source value details" style={{ padding: 12, borderBottom: '1px solid #b9d7d0', background: '#f8fafc', fontSize: 12, overflowWrap: 'anywhere' }}>
                    <button type="button" aria-label="Close source details" title="Close source details" onClick={() => setInspectedValue(null)}
                      style={{ float: 'right', width: 28, height: 28, border: '1px solid #cbd5e1', background: '#fff', borderRadius: 4 }}><X width={15} /></button>
                    <strong>{inspectedValue.caseName} · {inspectedValue.property} · {inspectedValue.unit}</strong>
                    <div style={{ marginTop: 6 }}>Value: {inspectedValue.value === '' || inspectedValue.value == null ? 'Missing' : inspectedValue.value}</div>
                    <div>Source: {inspectedValue.source.filename || 'Not recorded'} · {inspectedValue.source.sheet || '-'} · {inspectedValue.source.cell || '-'}</div>
                    <div>Original: {inspectedValue.source.value ?? 'Not recorded'} {inspectedValue.source.unit || ''}</div>
                    <div>Status: {inspectedValue.source.status || 'Missing source value'}</div>
                  </section>
                )}
                {comparisonData?.conflicts?.length > 0 && (
                  <div style={{ padding: '9px 12px', background: '#fffbeb', color: '#92400e', fontSize: 11 }}>
                    {comparisonData.conflicts.length} conflicting duplicate value(s) were detected. The first value is shown; review source mappings before export.
                  </div>
                )}
                {!comparisonBusy && comparisonData?.case_names?.length > 0 && (
                  <div style={{ padding: '8px 12px', borderBottom: '1px solid #d9e5e2', background: '#f8fcfb', display: 'flex', gap: 6, flexWrap: 'wrap' }}>
                    {comparisonData.case_names.map((caseName) => {
                      const hasData = comparisonData.rows?.some((row) => row.values?.[caseName] !== '' && row.values?.[caseName] != null);
                      return (
                        <span key={caseName} style={{ border: `1px solid ${hasData ? '#93c5fd' : '#d4d4d8'}`, borderRadius: 999, padding: '3px 7px', background: hasData ? '#dbeafe' : '#f4f4f5', color: hasData ? '#1d4ed8' : '#71717a', fontSize: 10, fontWeight: 700 }}>
                          {caseName}: {hasData ? 'Imported' : 'Not imported'}
                        </span>
                      );
                    })}
                  </div>
                )}
                {comparisonBusy && (
                  <div style={{ padding: 12, color: '#496b66', fontSize: 12 }}>Loading multi-case values...</div>
                )}
                {!comparisonBusy && comparisonData?.rows?.length > 0 && (
                  <div style={{ maxHeight: 520, overflow: 'auto', background: '#fff' }}>
                    <table style={{ borderCollapse: 'separate', borderSpacing: 0, minWidth: '100%', tableLayout: 'fixed', fontSize: 11 }}>
                      <thead>
                        <tr>
                          {['Phase', 'Property', 'Unit', ...(comparisonData.case_names || [])].map((heading, index) => (
                            <th key={heading} style={{ position: 'sticky', top: 0, zIndex: index < 3 ? 3 : 2, minWidth: index === 1 ? 190 : index < 3 ? 95 : 118, padding: '8px 7px', borderRight: '1px solid #bfd4cf', borderBottom: '1px solid #93c5fd', background: index < 3 ? '#dceee9' : '#edf7f4', color: '#1e3a8a', textAlign: index === 1 ? 'left' : 'center', fontWeight: 800 }}>
                              {heading}
                            </th>
                          ))}
                        </tr>
                      </thead>
                      <tbody>
                        {comparisonData.rows.map((row) => (
                          <tr key={`${row.section_key}-${row.row_index}`}>
                            <td style={{ padding: '6px 7px', borderRight: '1px solid #d9e5e2', borderBottom: '1px solid #e5ecea', background: '#f4faf8', fontWeight: 700, color: '#315b54' }}>{row.section}</td>
                            <td style={{ padding: '6px 7px', borderRight: '1px solid #d9e5e2', borderBottom: '1px solid #e5ecea', color: '#172b27' }}>{row.property}</td>
                            <td style={{ padding: '6px 7px', borderRight: '1px solid #d9e5e2', borderBottom: '1px solid #e5ecea', textAlign: 'center', color: '#496b66' }}>{row.unit || '-'}</td>
                            {(comparisonData.case_names || []).map((caseName) => (
                              <td key={caseName} style={{ padding: '6px 7px', borderRight: '1px solid #e5ecea', borderBottom: '1px solid #e5ecea', textAlign: 'right', color: row.values?.[caseName] === '' ? '#a8b7b3' : '#172b27', fontVariantNumeric: 'tabular-nums' }}>
                                <button type="button" title="Inspect source value" aria-label={`Inspect ${caseName} ${row.section} ${row.property} ${row.unit}`}
                                  onClick={() => setInspectedValue({ caseName, property: row.property, unit: row.unit, value: row.values?.[caseName], source: row.sources?.[caseName] || {} })}
                                  style={{ font: 'inherit', color: 'inherit', border: 0, background: 'transparent', padding: 0, cursor: 'pointer', textAlign: 'right', width: '100%' }}>
                                  {row.values?.[caseName] === '' || row.values?.[caseName] == null ? '\u2013' : formatStreamValue(row.values[caseName])}
                                </button>
                              </td>
                            ))}
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                )}
              </div>
            </div>

            <div style={{ padding: 16, display: showTemplateManager ? 'block' : 'none', borderTop: '1px solid #e2e8f0', background: '#fcfdff' }}>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, alignItems: 'center' }}>
              <input
                type="text"
                value={templateName}
                onChange={(e) => setTemplateName(e.target.value)}
                placeholder="Template name (optional)"
                style={{
                  fontSize: 13,
                  border: `1px solid ${T.accentBorder}`,
                  borderRadius: 8,
                  padding: '8px 10px',
                  minWidth: 220,
                }}
              />
              <input
                type="file"
                accept=".xlsx,.xlsm"
                onChange={(e) => {
                  setMasterTemplateFile(e.target.files?.[0] || null);
                  setTemplateError('');
                  setTemplateNotice('');
                }}
                style={{ fontSize: 13 }}
              />
              <button
                onClick={handleAnalyzeTemplate}
                disabled={templateBusy || !masterTemplateFile}
                style={{
                  display: 'inline-flex', alignItems: 'center', gap: 8,
                  background: `linear-gradient(135deg, ${T.accent}, ${T.accentAlt})`,
                  color: '#fff', border: 'none', padding: '8px 14px', borderRadius: 8,
                  fontSize: 13, fontWeight: 600, cursor: templateBusy || !masterTemplateFile ? 'not-allowed' : 'pointer',
                  opacity: templateBusy || !masterTemplateFile ? 0.6 : 1,
                }}
              >
                {templateBusy ? 'Analyzing...' : 'Analyze Template'}
              </button>
              {masterTemplateFile && (
                <span style={{ fontSize: 12, color: T.muted }}>
                  {masterTemplateFile.name}
                </span>
              )}
            </div>

            {templateError && (
              <div style={{
