                      <span key={`${f.name}-${f.size}`} style={{
                        border: `1px solid ${T.accentBorder}`,
                        borderRadius: 999,
                        padding: '4px 8px',
                        fontSize: 11,
                        background: T.accentSoft,
                        color: T.text,
                        maxWidth: 320,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                        display: 'inline-flex',
                        alignItems: 'center',
