                        <div key={file.file_id || file.filename} style={{ border: `1px solid ${file.requires_mapping ? '#fbbf24' : '#bbd8d1'}`, borderRadius: 7, padding: 10, background: file.requires_mapping ? '#fffbeb' : '#f8fcfb' }}>
