            ) : (
              <div style={{ overflow: 'auto', maxHeight: 420 }}>
                <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: 12 }}>
                  <thead style={{ background: THEME_BG_SOFT, position: 'sticky', top: 0 }}>
                    <tr>
