                  color: activeIndex === TOC.length - 1 ? THEME.faint : '#fff',
                  border: 'none',
                  fontSize: 12, fontWeight: 700,
                  cursor: activeIndex === TOC.length - 1 ? 'not-allowed' : 'pointer',
                  boxShadow: activeIndex === TOC.length - 1 ? 'none' : '0 4px 10px rgba(124,58,237,0.25)',
