//   HIDDEN_RULE_IDS         : rule_ids to hide globally (table, overlay, exports)
//   EVIDENCE_NOISE_PATTERNS : RegExp[] — finding.evidence fullmatching ANY drops
// Add new rule_ids/patterns here as new noise classes are observed.
