  const _writeWrenchProjectsToLS = useCallback((payload) => {
    try {
      localStorage.setItem(_WRENCH_PROJECTS_LS_KEY, JSON.stringify({
        ts:       Date.now(),
        projects: payload?.projects || [],
        // backend-provided counters (purely informational on the UI)
        total:              payload?.total || 0,
        transmittal_count:  payload?.transmittal_count || 0,
        fetched_at_server:  payload?.fetched_at || null,
      }))
    } catch { /* localStorage may be full or disabled — silently ignore */ }
  }, [])

  const _readWrenchProjectsFromLS = useCallback(() => {
    try {
      const raw = localStorage.getItem(_WRENCH_PROJECTS_LS_KEY)
      if (!raw) return null
      const parsed = JSON.parse(raw)
      if (!parsed?.ts || !Array.isArray(parsed?.projects)) return null
      if (Date.now() - parsed.ts > _WRENCH_PROJECTS_LS_TTL_MS) return null  // hard-expired
      return parsed
    } catch { return null }
  }, [])

  const loadWrenchProjects = useCallback(async ({ force = false } = {}) => {
    // ── Step A: instant hydrate from localStorage (only when not forcing) ──
    let hadLocalSnapshot = false
    if (!force && !wrenchProjectsLoaded) {
      const snap = _readWrenchProjectsFromLS()
      if (snap && snap.projects.length) {
        setWrenchProjects(snap.projects)
        setWrenchProjectsFetchedAt(snap.ts)
        setWrenchProjectsLoaded(true)
        hadLocalSnapshot = true
        // If the snapshot is still "fresh" enough, skip the background call entirely.
        if (Date.now() - snap.ts < _WRENCH_PROJECTS_FRESH_MS) return
      }
    }

    // ── Step B: prevent double-fire ─────────────────────────────────────
    if (wrenchProjectsLoading || wrenchProjectsSyncing) return

    // Foreground spinner only when we have nothing to show yet.
    if (hadLocalSnapshot || wrenchProjectsLoaded) setWrenchProjectsSyncing(true)
    else                                          setWrenchProjectsLoading(true)
    setWrenchProjectsError('')

    try {
      const res = await axios.get(`${API_BASE_URL}/wrench/sync/projects/`, {
        params:  force ? { refresh: 1 } : {},
        headers: authHeader(),
        timeout: 120000,
      })
      const data = res.data || {}
      const projects = Array.isArray(data.projects) ? data.projects : []
      setWrenchProjects(projects)
      setWrenchProjectsLoaded(true)
      setWrenchProjectsFetchedAt(Date.now())
      _writeWrenchProjectsToLS(data)
    } catch (err) {
      // If we already have a local snapshot we keep it visible — just surface a soft hint.
      const detail = err?.response?.data?.detail || err?.message || 'Failed to load Wrench projects.'
      setWrenchProjectsError(detail)
    } finally {
      setWrenchProjectsLoading(false)
      setWrenchProjectsSyncing(false)
    }
  }, [
    wrenchProjectsLoading, wrenchProjectsSyncing, wrenchProjectsLoaded,
    _readWrenchProjectsFromLS, _writeWrenchProjectsToLS,
  ])

  // Trigger first load when the AI Assist panel is opened.
  useEffect(() => {
    if (aiAssistEnabled && !wrenchProjectsLoaded && !wrenchProjectsLoading) {
      loadWrenchProjects()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [aiAssistEnabled])

  // ── AI Document Assist (Wrench) — fetch ranked P&ID candidates ────────────
  const runAiAssist = useCallback(async () => {
    if (!aiAssistEnabled) return
    const orderNo     = (aiAssistOrderNo || '').trim()
    const projectName = (selectedProject?.project_name || '').trim()
    if (!orderNo && !projectName) {
      setAiAssistError('Select a Project Number or open a RAD AI project first.')
      return
    }
    setAiAssistLoading(true)
    setAiAssistError('')
    setAiAssistResult(null)
    try {
      const res = await axios.get(`${API_BASE_URL}/wrench/sync/pid-recommendations/`, {
        params: {
          ...(orderNo     ? { order_no:     orderNo }     : {}),
          ...(projectName ? { project_name: projectName } : {}),
          ...(aiAssistHint ? { drawing_hint: aiAssistHint } : {}),
          top: _AI_ASSIST_DEFAULT_TOP,
        },
        headers: authHeader(),
        timeout: 60000,
      })
      setAiAssistResult(res.data)
      if (!orderNo && res.data?.order_no) setAiAssistOrderNo(res.data.order_no)
    } catch (err) {
      setAiAssistError(err?.response?.data?.detail || err?.message || 'AI assist failed.')
    } finally {
      setAiAssistLoading(false)
    }
  }, [aiAssistEnabled, aiAssistOrderNo, aiAssistHint, selectedProject])

  // Fetch a recommended document via the existing Wrench download proxy and
  // load it as the P&ID file (so the user can click "Run P&ID Verification").
  const useRecommendedDoc = useCallback(async (rec) => {
    if (!rec?.download_url) return
    setAiAssistFetchingDoc(rec.doc_no)
    setAiAssistError('')
    try {
      const downloadPath = rec.download_url.startsWith('http')
        ? rec.download_url
        : `${API_BASE_URL.replace(/\/api\/v1$/, '')}${rec.download_url}`
      const res = await axios.get(downloadPath, {
        headers: authHeader(),
        responseType: 'blob',
        timeout: 120000,
      })
      // Handle JSON redirect response (Wrench returns { download_url })
      const ctype = res.headers?.['content-type'] || ''
      if (ctype.includes('application/json')) {
        const txt  = await res.data.text()
        const json = JSON.parse(txt)
        if (json?.download_url) {
          window.open(json.download_url, '_blank', 'noopener,noreferrer')
          flash('info', `Opening Wrench document ${rec.doc_no} in a new tab — please save and upload it manually.`)
          return
        }
        throw new Error(json?.detail || 'Wrench did not return file bytes.')
      }
      // Build a File from the blob and feed it into the upload state
      const fileName = `${rec.doc_no || 'wrench-document'}.${rec.file_ext || 'pdf'}`
      const fileObj  = new File([res.data], fileName, { type: res.data.type || 'application/pdf' })
      setFile(fileObj)
      setError('')
      flash('success', `Loaded "${fileName}" from Wrench — ready to verify.`)
    } catch (err) {
      setAiAssistError(err?.response?.data?.detail || err?.message || 'Failed to download document from Wrench.')
    } finally {
      setAiAssistFetchingDoc(null)
    }
  }, [])

  const handleDrop = useCallback((e) => {
    e.preventDefault(); setDragOver(false);
    const f = e.dataTransfer.files[0];
    if (f) { setFile(f); setError(''); }  }, []);

  const handleUpload = async () => {
    if (!file) { setError('Please select a P&ID file first.'); return; }
    
    // SOFT-CODED: Validation for AI Vision mode requiring API key
    if (extractionMode === MODE_VISION && !centralAI.canUseAI) {
      setError('Ask your administrator to configure the selected AI provider.');
      return;
    }
    
    setError(''); setUploading(true); setResults(null); setDocStatus(null); setDocumentId(null);

    const fd = new FormData();
    fd.append('file', file);
    if (selectedProject) fd.append('project_id', selectedProject.project_id);
    
    // ══════════════════════════════════════════════════════════════════════
    // SOFT-CODED: Extraction Mode & BYOK (Bring Your Own Key)
    // ══════════════════════════════════════════════════════════════════════
    // Maps frontend extraction modes to backend analysis modes:
    //   MODE_OCR    → 'standard'          (Traditional OCR, no AI)
    //   MODE_VISION → 'enhanced_openai'   (OpenAI GPT-4o Vision)
    //            or → 'deep_claude'        (Claude Sonnet 4.5 Vision)
    // 
    // Backend expects:
    //   - analysis_mode: 'standard' | 'enhanced_openai' | 'deep_claude' | 'hybrid'
    //   - openai_api_key: User's OpenAI key (for enhanced_openai mode)
    //   - claude_api_key: User's Claude key (for deep_claude mode)
    // ══════════════════════════════════════════════════════════════════════
    
    // BUG FIX: this used to gate sending the API key on
    // `extractionMode === MODE_VISION` alone — a SEPARATE toggle from the
    // API key field itself, defaulting to MODE_OCR. A real, confirmed
    // symptom: a user pastes and successfully tests a valid key, clicks
    // "Start AI Analysis" without also clicking the separate Vision-mode
    // toggle, extractionMode is still MODE_OCR, the key is silently never
    // attached, the request goes out as analysis_mode='standard' (OCR-
    // only), and — since Tesseract isn't installed — it fails with
    // "Please install Tesseract OR add a Claude API key", even though a
    // perfectly valid key was right there in the form the whole time.
    // Now: a present, non-empty key is used whenever it exists, regardless
    // of which mode toggle is selected — "I typed a working key" is a
    // clearer signal of intent than a separate, easy-to-miss toggle click.
    // extractionMode still governs the true OCR-only case: no key entered.
    if (extractionMode === MODE_VISION) {
      if (visionProvider === 'openai') {
        fd.append('analysis_mode', 'enhanced_openai');
        if (visionApiKey.trim()) fd.append('openai_api_key', visionApiKey.trim());
      } else if (visionProvider === 'claude') {
        fd.append('analysis_mode', 'deep_claude');
        if (visionApiKey.trim()) fd.append('claude_api_key', visionApiKey.trim());
      }
    } else {
      // No key provided — standard OCR mode, no AI enhancement.
      fd.append('analysis_mode', 'standard');
    }

    // ══════════════════════════════════════════════════════════════════════

    try {
      // BUG FIX: 120000ms (2 min) was too short for a real analysis run.
      // Confirmed live (2026-09-08): a genuinely successful upload took
      // 140s end-to-end in local dev (Celery EAGER mode blocks the HTTP
      // response until the whole pipeline — Vision extraction, thinking,
      // comparison engine, Excel/PDF export — finishes synchronously), so
      // axios aborted the request as a timeout right as the backend was
      // about to succeed. The frontend then showed the generic "Upload
      // failed. Please try again." (no err.response on a client-side
      // timeout) even though the analysis itself had completed. 40 minutes
      // matches the backend Celery task's own hard time_limit (see
      // TASK_CONFIG/soft_time_limit in tasks.py) plus headroom — large,
      // dense P&IDs with thinking enabled can legitimately need it.
      const res = await axios.post(`${API_PREFIX}/upload-pid/`, fd, {
        headers: { ...authHeader(), 'Content-Type': 'multipart/form-data' },
        timeout: 2400000,
      });
      const { document_id, status: s } = res.data;
      setDocumentId(document_id);
      setDocStatus(s);

      // FIX: Always refresh history after successful upload to ensure UI reflects latest state
      // This fixes the issue where cached/immediate completions don't update the history
      if (selectedProject) {
        await fetchHistory(selectedProject.project_id);
      }
      
      if (s === 'completed') {
        await fetchResults(document_id);
      } else {
        startPolling(document_id);
      }
    } catch (err) {
      setError(err?.response?.data?.error || 'Upload failed. Please try again.');
    } finally {
      setUploading(false);
    }
  };

  // ── Symbol recognition (BYOK Vision) — separate, best-effort feature ──────
  // Sends the already-uploaded P&ID (by documentId) + the project's Legend
  // Sheet to Vision so the model can compare them and guess which legend
  // symbols appear on the drawing. Does not touch line/equipment/instrument
  // extraction.
  const handleIdentifySymbols = async () => {
    if (!documentId) { setSymbolsError('Upload and analyze a P&ID first.'); return; }
    if (!centralAI.canUseAI) { setSymbolsError('Ask your administrator to configure the selected AI provider.'); return; }

    setSymbolsError(''); setIdentifyingSymbols(true); setSymbolsResult(null);
    const fd = new FormData();
    fd.append('pid_document_id', documentId);
    fd.append('provider', visionProvider);
    if (visionProvider === 'claude') fd.append('model', visionClaudeModel);
    if (visionApiKey.trim()) fd.append('api_key', visionApiKey.trim());
    fd.append('thorough', thoroughScan ? 'true' : 'false');

    try {
      const res = await axios.post(`${API_BASE_URL}/pid-checker-v2/identify-symbols/`, fd, {
        headers: { ...authHeader(), 'Content-Type': 'multipart/form-data' },
        timeout: thoroughScan ? 300000 : 120000,
      });
      setSymbolsResult(res.data);
    } catch (err) {
      setSymbolsError(err?.response?.data?.error || 'Symbol identification failed. Please try again.');
    } finally {
      setIdentifyingSymbols(false);
    }
  };

  const startPolling = (docId) => {
    // ── Soft-coded poll watchdog (prevents the page from hanging indefinitely) ──
    // Tune these constants to change behaviour without touching core logic below.
    //   POLL_INTERVAL_MS         : delay between status checks (ms)
    //   POLL_MAX_DURATION_MS     : hard ceiling — give up after this much time (ms)
    //   POLL_MAX_CONSECUTIVE_ERR : abort after N consecutive failed polls (network/auth)
    //   POLL_REQUEST_TIMEOUT_MS  : per-request timeout for /status/ calls (ms)
    const POLL_INTERVAL_MS         = 3000;
    // Matches PIDVerificationV2.jsx's already-tuned value (was 15 min here,
    // causing this page specifically to give up on deep_claude / multi-page
    // analyses that legitimately need the full backend budget — V2 raised
    // this for exactly that reason but V1 was never updated to match, see
    // PIDVerificationV2.jsx's startPolling for the original reasoning).
    const POLL_MAX_DURATION_MS     = 40 * 60 * 1000;
    const POLL_MAX_CONSECUTIVE_ERR = 5;
    const POLL_REQUEST_TIMEOUT_MS  = 15000;

    setPolling(true);
    setElapsedSec(0);
    let consecutiveErrors = 0;
    const pollStartTs = Date.now();

    const stopAll = () => {
      if (pollRef.current)  { clearInterval(pollRef.current);  pollRef.current  = null; }
      if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null; }
      setPolling(false);
    };

    // Start the elapsed-time ticker (1 s resolution, purely cosmetic)
    timerRef.current = setInterval(() => {
      setElapsedSec(s => s + 1);
    }, 1000);
    pollRef.current = setInterval(async () => {
      // Hard ceiling — bail out so the UI never appears to hang for hours
      if (Date.now() - pollStartTs > POLL_MAX_DURATION_MS) {
        stopAll();
        setError(`Processing is taking longer than ${Math.floor(POLL_MAX_DURATION_MS / 60000)} minutes. The job may still be running on the server — check the History panel later.`);
        return;
      }
      try {
        const res = await axios.get(`${API_PREFIX}/status/${docId}/`, { headers: authHeader(), timeout: POLL_REQUEST_TIMEOUT_MS });
        consecutiveErrors = 0;  // reset error streak on any successful response
        const s = res.data.status;
        setDocStatus(s);
        // Keep the History row's badge/Re-check-button gating in sync on
        // every tick, not just at the end — see recheckDocument's
        // postmortem comment for why a stale row status is what let a
        // still-processing document's Re-check get clicked again (409).
        updateHistoryStatus(docId, s);
        if (s === 'completed') {
          stopAll();
          await fetchResults(docId);
          if (selectedProject) fetchHistory(selectedProject.project_id);
        } else if (s === 'failed') {
          stopAll();
          setError(res.data.error_message || 'Processing failed.');
        }
      } catch (err) {
        consecutiveErrors += 1;
        // Surface auth failures immediately — no point polling with an expired token
        if (err?.response?.status === 401 || err?.response?.status === 403) {
          stopAll();
          setError('Your session expired during processing. Please log in again and check History.');
          return;
        }
        if (consecutiveErrors >= POLL_MAX_CONSECUTIVE_ERR) {
          stopAll();
          setError('Lost connection to the server while checking status. Please refresh and check History.');
        }
      }
    }, POLL_INTERVAL_MS);
  };

  const fetchResults = async (docId) => {
    try {
      const res = await axios.get(`${API_PREFIX}/results/${docId}/`, { headers: authHeader(), timeout: 30000 });
      setResults(res.data);
      if (res.data.drawings?.length > 0) setActiveDrawing(res.data.drawings[0].drawing_id);
    } catch (e) {
      setError('Failed to load results.');
    }
  };

  const resetUpload = () => {
    clearInterval(pollRef.current);
    clearInterval(timerRef.current);
    setFile(null); setDocumentId(null); setDocStatus(null);
    setError(''); setPolling(false); setActiveDrawing(null);
    setElapsedSec(0);
    setOverrides({}); setOverridesSaved(false);
    setComparison(null);
  };

  // recheckDocument — re-run the full P&ID quality check on an already-uploaded
  // document without re-uploading the file.  Reuses the existing status-polling loop.
  //
  // docId    : document_id (UUID string) of the document to re-check
  // fileName : display name used in flash messages only
  // 2026-08-28 postmortem: recheckDocument only disabled its button for the
  // ~1s round-trip of the POST /reprocess/ call itself (recheckingDocId
  // resets in `finally`, right after that response lands) — NOT for the
  // up-to-30-minute duration the actual re-check runs on the server. The
  // History list's status badge for this row was also never updated after
  // firing a re-check (no fetchHistory() call, and the poll loop below only
  // ever updated the single currently-viewed document's docStatus, never
  // the matching row in `history`). So for the entire real processing
  // window, the row kept showing its OLD 'completed'/'failed' badge with a
  // fully clickable Re-check button — an impatient click during that window
  // hit reprocess_document while the document was still genuinely
  // 'processing' server-side, and the backend correctly (by design) 409'd.
  // Keeping the History row's status in sync — both right after firing and
  // on every subsequent poll tick — closes that window.
  const updateHistoryStatus = (docId, newStatus) => {
    setHistory(prev => prev.map(h => h.document_id === docId ? { ...h, status: newStatus } : h));
  };

  const recheckDocument = async (docId, fileName) => {
    if (recheckingDocId) return;          // prevent double-click
    setRecheckingDocId(docId);
    try {
      // 0. Same analysis_mode/BYOK-key mapping handleUpload() uses — this
      //    used to be an empty POST body, so the backend always ran with
      //    no BYOK context at all: claude_api_key was always None, and the
      //    Anthropic SDK silently fell back to its own (unset) environment
      //    variable instead of the user's key on screen, producing a 401
      //    on every Re-check in AI Vision mode. See _parse_byok_context()
      //    in views.py for the backend half of this fix.
      // BUG FIX: same fix as handleUpload() above — gating on
      // `extractionMode === MODE_VISION` alone let a present, tested,
      // valid key get silently dropped whenever the separate mode toggle
      // was still on MODE_OCR, producing the exact same "Please install
      // Tesseract OR add a Claude API key" failure on Re-check as on a
      // fresh upload. A present key is used regardless of that toggle.
      const reprocessBody = {};
      if (extractionMode === MODE_VISION) {
        if (visionProvider === 'openai') {
          reprocessBody.analysis_mode = 'enhanced_openai';
          if (visionApiKey.trim()) reprocessBody.openai_api_key = visionApiKey.trim();
        } else if (visionProvider === 'claude') {
          reprocessBody.analysis_mode = 'deep_claude';
          if (visionApiKey.trim()) reprocessBody.claude_api_key = visionApiKey.trim();
        }
      } else {
        reprocessBody.analysis_mode = 'standard';
      }

      // 1. Tell the backend to reset and re-queue. reprocess_document()
      //    ALWAYS runs a fresh pipeline now (see its BUG FIX comment in
      //    views.py) — it never serves a stale cached result here instead,
      //    so there's nothing to branch on in the response; it always
      //    proceeds to polling below.
      // BUG FIX: 20000ms (20s) was even more undersized than handleUpload()'s
      // old 120000ms — in local dev (Celery EAGER mode), this POST blocks for
      // the entire pipeline duration too, not just an enqueue round-trip.
      // Matches handleUpload()'s 40-minute timeout for the same reason.
      await axios.post(
        `${API_PREFIX}/reprocess/${docId}/`,
        reprocessBody,
        { headers: authHeader(), timeout: 2400000 },
      );

      flash('success', `Fresh analysis started for "${fileName}".`);

      // 2. Load this document as the active one so the user sees live progress
      setResults(null);
      setDocumentId(docId);
      setDocStatus('uploaded');
      setActiveDrawing(null);
      setOverrides({});
      setOverridesSaved(false);
      setComparison(null);
      // Reflect the new non-terminal status in the History row immediately —
      // see postmortem above — so its Re-check button hides/disables right
      // away instead of staying clickable for the whole processing window.
      updateHistoryStatus(docId, 'uploaded');

      // 3. Start the same polling loop used after a fresh upload
      startPolling(docId);
    } catch (e) {
      if (e?.response?.status === 409) {
        // Not a real failure — the document is already being (re)processed,
        // most likely from an earlier click during this same run. Say so
        // plainly instead of the generic "failed, try again" (which reads
        // as an error and invites yet another click/409 loop).
        flash('info', e?.response?.data?.error || 'Already processing — please wait for it to finish before re-checking again.');
      } else {
        const msg = e?.response?.data?.error || 'Re-check failed — please try again.';
        flash('error', msg);
      }
    } finally {
      setRecheckingDocId(null);
    }
  };

  // viewPreviousResults — backs the "Re-check (use cache)" button. Loads a
  // document's already-saved findings straight from the DB/S3 cache (see
  // results_cache.py's module docstring) via the existing /results/
  // endpoint. No pipeline run, no polling, no reprocess call, no API key
  // used — this is the instant companion to "Re-check (run fresh)"
  // (recheckDocument, below), which always ignores the cache and re-runs.
  const viewPreviousResults = async (docId, fileName) => {
    if (viewingPreviousId || recheckingDocId) return;
    setViewingPreviousId(docId);
    try {
      setResults(null);
      setDocumentId(docId);
      setDocStatus('completed');
      setActiveDrawing(null);
      setOverrides({});
      setOverridesSaved(false);
      setComparison(null);
      setError('');
      await fetchResults(docId);
      flash('success', `Loaded previous results for "${fileName}".`);
    } catch (e) {
      flash('error', 'Failed to load previous results.');
    } finally {
      setViewingPreviousId(null);
    }
  };

  const handleOverrideChange = (findingId, field, value) => {
    setOverrides(prev => ({ ...prev, [findingId]: { ...prev[findingId], [field]: value } }));
    setOverridesSaved(false);
  };

  const handleSaveOverrides = async () => {
    setSavingOverrides(true);
    const count = Object.keys(overrides).length;
    try {
      await Promise.all(
        Object.entries(overrides).map(([id, changes]) =>
          axios.patch(`${API_PREFIX}/findings/${id}/`, changes, { headers: authHeader() })
        )
      );
      setOverridesSaved(true);
      setOverrides({});
      await fetchResults(documentId);
      flash('success', `${count} finding${count !== 1 ? 's' : ''} updated — exports will reflect your review`);
    } catch (e) {
      flash('error', 'Failed to save overrides');
    } finally {
      setSavingOverrides(false);
    }
  };

  const downloadExcel = async () => {
    if (downloadingXlsx) return;
    setDownloadingXlsx(true);
    try {
      const res = await axios.get(`${API_PREFIX}/export/excel/${documentId}/`, {
        headers: { ...authHeader() },
        responseType: 'blob',
        timeout: 120000,
      });
      const url = URL.createObjectURL(res.data);
      const a   = document.createElement('a');
      const safeName = (results?.file_name || documentId).replace(/\.[^.]+$/, '').replace(/\s+/g, '_');
      a.href     = url;
      a.download = `pidv_findings_${safeName}.xlsx`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      flash('error', 'Excel export failed — ' + (e.response?.data?.error || e.message));
    } finally {
      setDownloadingXlsx(false);
    }
  };

  const downloadPDF = async () => {
    if (downloadingPdf) return;
    setDownloadingPdf(true);
    try {
      const res = await axios.get(`${API_PREFIX}/export/pdf/${documentId}/`, {
        headers: { ...authHeader() },
        responseType: 'blob',
        timeout: 120000,
      });
      const url = URL.createObjectURL(res.data);
      const a   = document.createElement('a');
      const safeName = (results?.file_name || documentId).replace(/\.[^.]+$/, '').replace(/\s+/g, '_');
      a.href     = url;
      a.download = `pidv_report_${safeName}.pdf`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
    } catch (e) {
      flash('error', 'PDF export failed — ' + (e.response?.data?.error || e.message));
    } finally {
      setDownloadingPdf(false);
    }
  };

  // ── Helpers ───────────────────────────────────────────────────────────────
  const flash = (type, text) => {
    setMessage({ type, text });
    setTimeout(() => setMessage({ type:'', text:'' }), 3500);
  };

  const activeDrawingData = results?.drawings?.find(d => d.drawing_id === activeDrawing);
  const extractionSummary = activeDrawingData?.metadata?.extraction_summary || null;

  // ── Performance: memoize expensive per-drawing computations ──────────────────────────────
  // These re-run ONLY when activeDrawingData changes (drawing selection), NOT on every render.
  // Without this, the Lines panel rebuilt tagFindingsMap O(findings×tags) and _routeSort for
  // every line tag on every keystroke / hover / scroll event.

  // tagFindingsMap: each line tag text → array of its related QC findings
  const tagFindingsMap = useMemo(() => {
    const lts      = activeDrawingData?.metadata?.line_tags || [];
    const findings = (activeDrawingData?.issues || []).filter(
      f => _LINE_FINDING_CATS.has(f.category) || (f.rule_id || '').startsWith('LSZ')
    );
    const map = new Map();
    for (const f of findings) {
      const ev = (f.evidence || f.issue || '').toLowerCase();
      for (const lt of lts) {
        if (lt.text && ev.includes(lt.text.toLowerCase())) {
          if (!map.has(lt.text)) map.set(lt.text, []);
          map.get(lt.text).push(f);
        }
      }
    }
    return map;
  }, [activeDrawingData]); // eslint-disable-line react-hooks/exhaustive-deps

  // layoutItemsBase: direction-aware route items for Drawing Layout sub-tab
  const layoutItemsBase = useMemo(() => {
    const lts = activeDrawingData?.metadata?.line_tags || [];
    return lts.reduce((acc, lt) => {
      const text = lt.text || lt.tag || lt.label || '';
      if (!text) return acc;
      const occs = (lt.occurrences || []).filter(o => o.x_pct != null && o.y_pct != null);
      if (occs.length === 0) return acc;
      const parts = text.match(/^(\d+(?:\.\d+)?)"?[-_]([A-Za-z0-9]+)[-_](\d+)/);
      const fluidCode = parts ? parts[2].toUpperCase() : (lt.fluid_code || '').toUpperCase();
      const fc      = _lfcGlobal(fluidCode);
      const sorted  = _routeSort(occs);
      const start   = sorted[0], end = sorted[sorted.length - 1], middle = sorted.slice(1, -1);
      const fds     = tagFindingsMap.get(text) || [];
      const hasIssue = fds.length > 0;
      const maxSev   = fds.length
        ? fds.reduce((b, f) => (_SEV_RANK[f.severity] || 0) > (_SEV_RANK[b] || 0) ? f.severity : b, fds[0].severity)
        : null;
      const dirs = [...new Set(occs.map(o => (o.direction || '').toUpperCase().charAt(0)).filter(Boolean))];
      const routeType = dirs.length > 1 ? 'HV' : (dirs[0] || 'H');
      acc.push({ text, fluidCode, fc, start, end, middle, sorted, hasIssue, maxSev,
                 multi_angle: !!lt.multi_angle, routeType });
      return acc;
    }, []);
  }, [activeDrawingData, tagFindingsMap]); // eslint-disable-line react-hooks/exhaustive-deps

  // Override-aware helpers — use local draft until saved
  const getVal = (f, field) => overrides[f.id]?.[field] ?? f[field];
  const pendingCount = Object.keys(overrides).length;
  const allIssues    = results?.drawings?.flatMap(d => d.issues ?? []) ?? [];
  const totalIssues   = results?.total_issues ?? allIssues.length;
  const criticalCount = allIssues.filter(f => getVal(f, 'severity') === 'critical').length;
  const majorCount    = allIssues.filter(f => getVal(f, 'severity') === 'major').length;

  // Soft-coded overlay helpers (frontend only): infer confidence and pseudo-position from evidence.
  const bandRank = { low: 1, medium: 2, high: 3 };

  const detectConfidenceBand = (finding) => {
    const txt = `${finding.issue_observed || ''}`;
    const explicit = txt.match(/confidence:\s*(high|medium|low)/i)?.[1]?.toLowerCase();
    if (explicit) return explicit;

    const sev = getVal(finding, 'severity');
    if (sev === 'critical' || sev === 'major') return 'high';
    if (sev === 'minor') return 'medium';
    return 'low';
  };

  const inferEvidenceKey = (finding) => {
    if (finding.evidence?.trim()) return finding.evidence.trim();
    const quoted = (finding.issue_observed || '').match(/'([^']+)'/)?.[1];
    if (quoted) return quoted;
    return `${finding.rule_id}-${finding.sl_no}`;
  };

  const stableUnit = (str, salt) => {
    let h = 2166136261 ^ salt;
    for (let i = 0; i < str.length; i += 1) {
      h ^= str.charCodeAt(i);
      h = Math.imul(h, 16777619);
    }
    const n = (h >>> 0) % 10000;
    return n / 10000;
  };

  const buildOverlayNodes = (issues = []) => {
    // v5: accurate overlay positioning with smart occurrence selection.
    // ── Soft-coded calibration constants ────────────────────────────────────
    // Shift ALL anchored markers by these amounts (% of image dimensions).
    // Set to 0 to disable. Positive = shift right / down.
    // Tune these if a run of real-position markers is consistently offset in one
    // direction across the whole drawing (systematic canvas origin mismatch).
    const OVERLAY_CALIB_X_PCT = 0;
    const OVERLAY_CALIB_Y_PCT = 0;

    // Drawing content area bounds (% of page).  Positions outside this band are
    // likely in the title block / border — exclude them when picking the best
    // occurrence from an NPS size's 'all' array.
    // Typical P&ID (landscape A1): title block occupies right ~12% & bottom ~12%.
    const AREA_X_MIN = 1;
    const AREA_X_MAX = 96;
    const AREA_Y_MIN = 1;
    const AREA_Y_MAX = 87;

    // Drawing main-content centroid — used as the reference point when selecting
    // the single best occurrence from a tag's 'all' occurrences array. Biased
    // slightly above & left of page centre as instrument fields cluster there.
    const CONTENT_CX = 50;
    const CONTENT_CY = 40;
    // ────────────────────────────────────────────────────────────────────────

    const realPositions = activeDrawingData?.metadata?.tag_positions || {};

    // Normalize curly/smart quotes → straight ASCII " for consistent key lookup.
    const normKey = (k) =>
      (k || '').replace(/[\u201c\u201d\u2018\u2019]/g, '"').trim();

    // Extract all NPS pipe-size keys from an evidence string.
    // Handles both straight (") and smart (" ") quote characters.
    // e.g. 'SUCTION KOD 6" 4"-BD-4860-033842-X-N ...' -> ['6"', '4"']
    const extractNpsKeys = (str) => {
      const keys = [];
      // Original proven regex: \b ensures we match NPS sizes as standalone
      // tokens (avoids false matches inside longer numbers).
      // Character class: straight quote, two smart-quote Unicode variants.
      const re = /\b(\d+(?:\.\d+)?)\s*["\u201c\u201d\u2033]/g;
      let m;
      while ((m = re.exec(str)) !== null) {
        keys.push(m[1] + '"');        // normalise to straight quote (matches backend key format)
      }
      return [...new Set(keys)];
    };

    // Soft-coded: regex that matches ISA 5.1-style instrument / equipment tag IDs.
    // Covers: PI-3610-16, FV-001, LT-42A, TIC-101, PSV-1234A, FE-3610-16-01, etc.
    // Add new patterns here to extend instrument tag resolution without changing render logic.
    const INSTR_TAG_RE = /\b([A-Z]{1,4}[A-Z]?)\s*[-–]\s*(\d{2,6}(?:[A-Z]?(?:[-–]\d{1,4})?)?)\b/g;

    const extractInstrTags = (str) => {
      const tags = [];
      const re = new RegExp(INSTR_TAG_RE.source, 'g');
      let m;
      while ((m = re.exec(str)) !== null) {
        const canonical = `${m[1]}-${m[2]}`; // e.g. "PI-3610-16"
        tags.push(canonical);
        tags.push(m[0].trim()); // raw match (might have spaces around dash)
        // Some backends store without sub-suffix: PI-3610
        const short = `${m[1]}-${m[2].split(/[-–]/)[0]}`;
        if (short !== canonical) tags.push(short);
      }
      return [...new Set(tags)];
    };

    // Pick the single best {x_pct, y_pct} from a position-entry (may have 'all').
    // Strategy: filter to main drawing area first, then pick the occurrence
    // whose Euclidean distance to the content centroid is smallest.
    // For position entries WITHOUT an 'all' array (direct tag hits), the entry
    // itself is returned unchanged — those are already single, precise points.
    const pickBestOcc = (pos) => {
      if (!pos) return null;
      if (!pos.all || pos.all.length === 0) {
        // Direct tag position (no 'all' array) — use as-is
        return (pos.x_pct != null && pos.y_pct != null) ? pos : null;
      }
      // Filter to drawing content area (excludes title block corners)
      const inArea = pos.all.filter(o =>
        o.x_pct >= AREA_X_MIN && o.x_pct <= AREA_X_MAX &&
        o.y_pct >= AREA_Y_MIN && o.y_pct <= AREA_Y_MAX
      );
      const pool = inArea.length > 0 ? inArea : pos.all;
      // Pick the occurrence nearest the drawing content centroid
      let best = pool[0];
      let bestDist = Infinity;
      for (const o of pool) {
        const dx = o.x_pct - CONTENT_CX;
        const dy = o.y_pct - CONTENT_CY;
        const d  = dx * dx + dy * dy;
        if (d < bestDist) { bestDist = d; best = o; }
      }
      return { x_pct: best.x_pct, y_pct: best.y_pct };
    };

    // Prefer H-direction occurrence for line_tags (horizontal labels are the
    // primary pipeline designation text — more precisely rendered than rotated V).
    const pickBestLineTagOcc = (lt) => {
      const occs = (lt.occurrences || []).filter(o => o.x_pct != null && o.y_pct != null);
      if (occs.length === 0) return null;
      const hOcc = occs.find(o => o.direction === 'H');
      const candidate = hOcc ?? occs[0];
      return { x_pct: candidate.x_pct, y_pct: candidate.y_pct };
    };

    // Apply soft-coded calibration offset and clamp to visible canvas.
    const applyCalib = (xp, yp) => ({
      left: Math.min(AREA_X_MAX, Math.max(AREA_X_MIN, xp + OVERLAY_CALIB_X_PCT)),
      top:  Math.min(AREA_Y_MAX, Math.max(AREA_Y_MIN, yp + OVERLAY_CALIB_Y_PCT)),
    });

    // Resolve the best real position for a finding.
    // Priority 1 : exact normalised key match
    // Priority 2 : NPS size keys extracted from evidence (e.g. "8\"", "3\"")
    // Priority 3 : instrument / equipment tag IDs extracted from evidence (e.g. "PI-3610-16")
    // Priority 4 : line_tags fuzzy match (exact → sep-normalised → partial)
    // Priority 5 : red_annotations text match
    // Fallback    : null → deterministic hash-based heuristic position
    const resolveReal = (nk, rawKey) => {
      // P1: exact match on normalised key or original raw key
      //     pickBestOcc selects the nearest-to-centroid occurrence from the
      //     'all' array so the marker lands on an actual text element, not
      //     the arithmetic average of all occurrences.
      const r1 = pickBestOcc(realPositions[nk] ?? realPositions[rawKey] ?? null);
      if (r1) return { ...r1, tier: 'P1' };

      // P2: NPS size keys — try both the normalised key and original raw string
      //     so that smart-quote variants don't slip through normalisation
      for (const src of [nk, rawKey]) {
        for (const nps of extractNpsKeys(src)) {
          const r2 = pickBestOcc(realPositions[nps] ?? realPositions[normKey(nps)] ?? null);
          if (r2) return { ...r2, tier: 'P2' };
        }
      }

      // P3: instrument / equipment tag IDs extracted from evidence text
      for (const src of [nk, rawKey]) {
        for (const tag of extractInstrTags(src)) {
          const r3 = pickBestOcc(realPositions[tag] ?? realPositions[normKey(tag)] ?? null);
          if (r3) return { ...r3, tier: 'P3' };
        }
      }

      // P4: line_tags text match — resolves LN-001, LN-002, LSZ-010 findings
      // whose evidence is a pipeline designation like '4"-BD-4860-033842-X-N'.
      // Split by " · " to handle multi-tag evidence strings (LSZ-010).
      const lineTagsArr = activeDrawingData?.metadata?.line_tags || [];
      if (lineTagsArr.length > 0) {
        const candidates = [...new Set(
          [nk, normKey(rawKey)]
            .flatMap(s => s.split(/\s*[·\u00b7]\s*/).map(p => p.trim()))
            .filter(Boolean)
        )];

        // P4-exact: strict normalised key match
        for (const cand of candidates) {
          for (const lt of lineTagsArr) {
            const ltText = normKey(lt.text || '');
            if (!ltText) continue;
            if (ltText === cand || cand === ltText) {
              const occ = pickBestLineTagOcc(lt);
              if (occ) return { ...occ, tier: 'P4' };
            }
          }
        }

        // P4-norm: separator-normalised comparison — handles OCR reading '_' for '-'
        // or extra spaces introduced when joining splits across font runs.
        const normSep = (s) => s.replace(/[\s_]+/g, '-').replace(/-{2,}/g, '-').toUpperCase();
        for (const cand of candidates) {
          const nc = normSep(cand);
          if (nc.length < 8) continue;
          for (const lt of lineTagsArr) {
            const nltText = normSep(normKey(lt.text || ''));
            if (!nltText) continue;
            if (nltText === nc) {
              const occ = pickBestLineTagOcc(lt);
              if (occ) return { ...occ, tier: 'P4' };
            }
          }
        }

        // P4-partial: substring match for fragment evidence (min 8 chars to avoid noise).
        for (const cand of candidates) {
          if (cand.length < 8) continue;
          for (const lt of lineTagsArr) {
            const ltText = normKey(lt.text || '');
            if (!ltText || ltText.length < 8) continue;
            if (ltText.includes(cand) || cand.includes(ltText)) {
              const occ = pickBestLineTagOcc(lt);
              if (occ) return { ...occ, tier: 'P4' };
            }
          }
        }
      }

      // P5: red_annotations text match — resolves RED-001 findings and any
      // annotation-based findings (ANN-001, VLV-002/003) whose evidence text
      // appears as a red span on the drawing with a known bounding-box position.
      const redAnnsArr = activeDrawingData?.metadata?.red_annotations || [];
      if (redAnnsArr.length > 0) {
        const evNk = normKey(rawKey);
        for (const ra of redAnnsArr) {
          const raNk = normKey(ra.text || '');
          if (!raNk) continue;
          if (evNk.includes(raNk) || raNk.includes(evNk)) {
            if (ra.x_pct != null && ra.y_pct != null) {
              return { x_pct: ra.x_pct, y_pct: ra.y_pct, tier: 'P5' };
            }
          }
        }
      }

      return null;
    };

    // Group findings by normalised evidence key; keep highest-severity band.
    const grouped = new Map();
    for (const f of issues) {
      const rawKey = inferEvidenceKey(f);
      const nk = normKey(rawKey);
      const band = detectConfidenceBand(f);
      const cur = grouped.get(nk);
      if (!cur || bandRank[band] > bandRank[cur.band]) {
        grouped.set(nk, { finding: f, band, key: nk, rawKey });
      }
    }

    // BUG FIX (2026-09-08): FH (Fallback Hash) markers are a deterministic
    // pseudo-position — a hash of the finding's identity, not derived from
    // the drawing at all — meant as "a few uncertain dots among mostly-real
    // ones." Root cause of a real, confirmed, reproducible symptom: any
    // document with NO tag_positions data whatsoever (e.g. a scanned/
    // image-only PDF processed without Tesseract, real key confirmed live)
    // has literally zero real positions for every single finding, so 100%
    // of markers fell into the FH branch — the whole canvas covered in
    // hash-scattered dots with no relationship to the actual drawing,
    // which reads as broken/misleading rather than "a few unsure ones."
    // Fix: only fabricate an FH position when at least one OTHER finding on
    // THIS drawing resolved a real (or engineer-corrected) position — i.e.
    // only when "mostly real, a few uncertain" is actually true. When zero
    // real positions exist anywhere on the drawing, skip FH entirely and
    // return no nodes — findings are never lost (they still render in the
    // Findings table below, via anchoringFailedEntirely's fallback), just
    // not spatially misplaced on an image where the position is fabricated
    // for literally every marker. Applies generically to any document that
    // hits this condition, not one specific file.
    const groupEntries = [...grouped];
    let anyRealPosition = false;
    for (const [nk, x] of groupEntries) {
      const corrKey = `${activeDrawing || 'drawing'}:${x.finding.id}`;
      if (calibCorrections[corrKey] || resolveReal(nk, x.rawKey)) {
        anyRealPosition = true;
        break;
      }
    }

    const nodes = [];
    for (const [nk, x] of groupEntries) {
      const real = resolveReal(nk, x.rawKey);

      // Apply any stored engineer correction for this finding — always wins over
      // extracted / heuristic positions. Keyed 'drawingId:findingId'.
      const corrKey = `${activeDrawing || 'drawing'}:${x.finding.id}`;
      const storedCorr = calibCorrections[corrKey];
      if (storedCorr) {
        nodes.push({ ...x, left: storedCorr.correctedLeft, top: storedCorr.correctedTop, anchored: true, tier: 'CX' });
        continue;
      }

      // One marker per unique finding group — use primary coord (x_pct/y_pct).
      // real.all contains every OCR occurrence; pickBestOcc already selected the
      // best single point so we read x_pct/y_pct directly here.
      if (real) {
        const xp = real.x_pct ?? real.all?.[0]?.x_pct;
        const yp = real.y_pct ?? real.all?.[0]?.y_pct;
        const pos = applyCalib(xp, yp);
        nodes.push({ ...x, ...pos, anchored: true, tier: real.tier || 'P?' });
      } else if (anyRealPosition) {
        // Deterministic pseudo-position from FNV-1a hash (dashed marker) —
        // only shown when at least one other finding on this drawing has a
        // real position (see anyRealPosition's own comment above).
        const seed = `${activeDrawing || 'drawing'}:${nk}`;
        nodes.push({
          ...x,
          left: 8  + (stableUnit(seed, 11) * 84),
          top:  10 + (stableUnit(seed, 29) * 78),
          anchored: false,
          tier: 'FH',
        });
      }
      // else: no real position for this finding AND none anywhere on this
      // drawing — skip entirely rather than fabricate one (see above).
    }
    return nodes;
  };

  const overlayNodes = buildOverlayNodes(
    (activeDrawingData?.issues || []).filter(f =>
      !isFindingNoisy(f) &&
      !HIDDEN_CATEGORIES.has(f.category) &&
      !HIDDEN_SEVERITIES.has((f.severity || '').toLowerCase())
    )
  );
  const visibleOverlayNodes = overlayNodes.filter(n => showUncertainHighlights || n.band !== 'low');

  // ── Anchored-findings filter ──────────────────────────────────────────────
  // Inline evidence-key normalizer — mirrors normKey defined inside buildOverlayNodes.
  // Strips smart/curly quotes so keys from different sources compare equal.
  const _normEvKey = (k) => (k || '').replace(/[\u201c\u201d\u2018\u2019]/g, '"').trim();
  // Build the set of normalized evidence keys for findings that have a REAL
  // drawing position (tier in FINDINGS_ANCHORED_TIERS, i.e. P1–P5 or CX).
  // This set is consumed by the Findings table IIFE below to restrict the list
  // to findings actually visible as markers on the canvas.
  const anchoredEvidenceKeys = FINDINGS_TABLE_ANCHORED_ONLY
    ? new Set(
        overlayNodes
          .filter(n => FINDINGS_ANCHORED_TIERS.has(n.tier))
          .map(n => _normEvKey(inferEvidenceKey(n.finding)))
      )
    : null;

  // Auto-record per-drawing resolution tier statistics to localStorage.
  // Accumulates across all P&IDs tested and can be exported for model training.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  useEffect(() => {
    if (!activeDrawing || overlayNodes.length === 0) return;
    try {
      const tc = {};
      for (const n of overlayNodes) { const t = n.tier || 'FH'; tc[t] = (tc[t] || 0) + 1; }
      const rawStats = localStorage.getItem(CALIB_STATS_KEY);
      const allStats = rawStats ? JSON.parse(rawStats) : {};
      allStats[activeDrawing] = {
        drawingId: activeDrawing, timestamp: new Date().toISOString(),
        totalFindings: overlayNodes.length, tierCounts: tc,
        anchoredCount: overlayNodes.filter(n => n.anchored).length,
        correctedCount: overlayNodes.filter(n => n.tier === 'CX').length,
      };
      localStorage.setItem(CALIB_STATS_KEY, JSON.stringify(allStats));
    } catch { /* non-fatal */ }
  }, [activeDrawing]); // re-records whenever drawing changes

  const jumpToFinding = (findingId) => {
    setFocusedFindingId(findingId);
    const el = document.getElementById(`finding-row-${findingId}`);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }
  };

  // ─────────────────────────────────────────────────────────────────────────
  // Flash banner
  // ─────────────────────────────────────────────────────────────────────────
  const FlashBanner = () => message.text ? (
    <div className={`mb-5 p-4 rounded-xl border flex items-center gap-3 ${
      message.type === 'success' ? 'bg-emerald-50 border-emerald-200 text-emerald-700'
      : message.type === 'error' ? 'bg-red-50 border-red-200 text-red-700'
      : 'bg-blue-50 border-blue-200 text-blue-700'
    }`}>
      {message.type === 'success' ? <CheckCircle className="w-4 h-4 flex-shrink-0" /> : <AlertTriangle className="w-4 h-4 flex-shrink-0" />}
      <span className="text-sm">{message.text}</span>
    </div>
  ) : null;

  // ─────────────────────────────────────────────────────────────────────────
  // VIEW 1 — Project selection
  // ─────────────────────────────────────────────────────────────────────────
  if (!selectedProject) {
    return (
      <DarkBg>
        <style>{`
          /* Responsive workflow split-screen */
          @media (max-width: ${SPLIT_SCREEN_MIN_WIDTH - 1}px) {
            .workflow-split-container {
              display: block !important;
              grid-template-columns: 1fr !important;
            }
          }
        `}</style>
        <div className="w-full px-2 sm:px-4 lg:px-6 py-10">

          {/* ═══ SMART REDESIGNED HEADER ═══ */}
          <div className="mb-12" style={{ 
            animation: `${ANIMATION_CARD_ENTRANCE} ${ANIMATION_ENTRANCE_DURATION} ease-out both`,
            ...(HEADER_SHOW_GRADIENT_BG && {
              background: `linear-gradient(135deg, ${HEADER_GRADIENT_FROM} 0%, ${HEADER_GRADIENT_TO} 100%)`,
              borderRadius: CARD_BORDER_RADIUS,
              padding: '32px',
              border: `1px solid ${CARD_BORDER_COLOR}`
            })
          }}>
            <div className="flex items-start justify-between gap-6 flex-wrap">
              {/* Left: Icon + Title + Description */}
              <div className="flex items-start gap-5 flex-1">
                {/* Icon */}
                <div style={{ 
                  width: `${HEADER_ICON_SIZE}px`,
                  height: `${HEADER_ICON_SIZE}px`,
                  borderRadius: '14px',
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexShrink: 0,
                  background: HEADER_ICON_BG_STYLE === 'gradient' 
                    ? 'linear-gradient(135deg, #3b82f6 0%, #6366f1 100%)'
                    : HEADER_ICON_BG_STYLE === 'solid' 
                    ? COLOR_PRIMARY 
                    : 'transparent',
                  border: HEADER_ICON_BG_STYLE === 'outline' ? `2px solid ${COLOR_PRIMARY}` : 'none',
                  boxShadow: HEADER_ICON_BG_STYLE !== 'outline' ? '0 4px 14px rgba(59,130,246,0.3)' : 'none'
                }}>
                  <Shield className="text-white" style={{ width: `${HEADER_ICON_SIZE * 0.55}px`, height: `${HEADER_ICON_SIZE * 0.55}px` }} />
                </div>

                {/* Title & Description */}
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2 flex-wrap">
                    <h1 style={{ 
                      fontSize: HEADING_MAIN_SIZE,
                      fontWeight: HEADING_MAIN_WEIGHT,
                      color: COLOR_TEXT_PRIMARY,
                      lineHeight: 1.2,
                      margin: 0
                    }}>
                      P&ID Verification
                    </h1>
                    {HEADER_SHOW_STATUS_BADGE && (
                      <span style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '6px',
                        padding: '4px 12px',
                        borderRadius: '20px',
                        fontSize: '0.75rem',
                        fontWeight: 600,
                        background: `${HEADER_BADGE_COLOR}15`,
                        color: HEADER_BADGE_COLOR,
                        border: `1px solid ${HEADER_BADGE_COLOR}30`
                      }}>
                        <CheckCircle style={{ width: '14px', height: '14px' }} />
                        {HEADER_BADGE_TEXT}
                      </span>
                    )}
                  </div>
                  <p style={{ 
                    fontSize: HEADING_SUB_SIZE,
                    color: HEADING_SUB_COLOR,
                    margin: 0,
                    maxWidth: '680px',
                    lineHeight: 1.6
