                          e.stopPropagation();
                          console.log('Zoom out clicked, current:', workflowZoom);
                          setWorkflowZoom(Math.max(50, workflowZoom - 10));
                        }}
                        disabled={workflowZoom <= 50}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          width: '32px',
                          height: '32px',
                          borderRadius: '8px',
                          border: '1px solid rgba(148,163,184,0.2)',
                          background: workflowZoom <= 50 ? 'rgba(148,163,184,0.05)' : 'rgba(59,130,246,0.08)',
                          color: workflowZoom <= 50 ? '#94a3b8' : COLOR_PRIMARY,
                          cursor: workflowZoom <= 50 ? 'not-allowed' : 'pointer',
                          transition: 'all 200ms ease',
                          fontSize: '18px',
                          fontWeight: 600,
                          opacity: workflowZoom <= 50 ? 0.5 : 1
                        }}
                        title="Zoom Out (Min 50%)"
                      >
                        −
                      </button>
                      
                      {/* Zoom Level Display */}
                      <div style={{
                        padding: '6px 12px',
                        borderRadius: '8px',
                        background: 'rgba(59,130,246,0.1)',
                        border: '1px solid rgba(59,130,246,0.2)',
                        fontSize: '13px',
                        fontWeight: 600,
                        color: COLOR_PRIMARY,
                        minWidth: '60px',
                        textAlign: 'center'
                      }}>
                        {workflowZoom}%
                      </div>
                      
                      {/* Zoom In */}
                      <button
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          console.log('Zoom in clicked, current:', workflowZoom);
                          setWorkflowZoom(Math.min(200, workflowZoom + 10));
                        }}
                        disabled={workflowZoom >= 200}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          width: '32px',
                          height: '32px',
                          borderRadius: '8px',
                          border: '1px solid rgba(148,163,184,0.2)',
                          background: workflowZoom >= 200 ? 'rgba(148,163,184,0.05)' : 'rgba(59,130,246,0.08)',
                          color: workflowZoom >= 200 ? '#94a3b8' : COLOR_PRIMARY,
                          cursor: workflowZoom >= 200 ? 'not-allowed' : 'pointer',
                          transition: 'all 200ms ease',
                          fontSize: '18px',
                          fontWeight: 600,
                          opacity: workflowZoom >= 200 ? 0.5 : 1
                        }}
                        title="Zoom In (Max 200%)"
                      >
                        +
                      </button>
                      
                      {/* Reset Zoom */}
                      {workflowZoom !== 100 && (
                        <button
                          onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            console.log('Reset zoom clicked');
                            setWorkflowZoom(100);
                          }}
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '4px',
                            padding: '6px 10px',
                            borderRadius: '8px',
                            border: '1px solid rgba(148,163,184,0.2)',
                            background: 'rgba(99,102,241,0.08)',
                            color: '#6366f1',
                            cursor: 'pointer',
                            transition: 'all 200ms ease',
                            fontSize: '11px',
                            fontWeight: 600
                          }}
                          title="Reset to 100%"
                        >
                          <Minimize2 style={{ width: '14px', height: '14px' }} />
                          Reset
                        </button>
                      )}
                      
                      {/* Fullscreen */}
                      <button
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          console.log('Fullscreen clicked');
                          setWorkflowFullscreen(true);
                        }}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '4px',
                          padding: '6px 10px',
                          borderRadius: '8px',
                          border: '1px solid rgba(16,185,129,0.2)',
                          background: 'rgba(16,185,129,0.08)',
                          color: COLOR_SUCCESS,
                          cursor: 'pointer',
                          transition: 'all 200ms ease',
                          fontSize: '11px',
                          fontWeight: 600
                        }}
                        title="View Fullscreen"
                      >
                        <Maximize2 style={{ width: '14px', height: '14px' }} />
                        Fullscreen
                      </button>
                    </div>
                  </div>
                  
                  {/* P&ID Verification Workflow Diagram - Interactive Image */}
                  <div style={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '100%',
                    maxWidth: '100%',
                    overflow: 'auto'
                  }}>
                    
                    {/* Workflow Image Container */}
                    <div style={{
                      width: workflowCompact ? '90%' : '95%',
                      maxWidth: '1400px',
                      margin: '0 auto',
                      borderRadius: '12px',
                      overflow: workflowZoom === 100 ? 'hidden' : 'auto',
                      boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
                      background: 'white',
                      border: '2px solid rgba(59,130,246,0.2)',
                      position: 'relative',
                      transition: 'all 300ms ease'
                    }}>
                      {/* Loading State */}
                      {!workflowImageLoaded && !workflowImageError && (
                        <div style={{
                          position: 'absolute',
                          top: 0,
                          left: 0,
                          right: 0,
                          bottom: 0,
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          background: 'linear-gradient(135deg, rgba(59,130,246,0.05) 0%, rgba(99,102,241,0.05) 100%)',
                          zIndex: 10
                        }}>
                          <div style={{ textAlign: 'center' }}>
                            <Loader style={{ width: '32px', height: '32px', color: COLOR_PRIMARY, animation: 'spin 1s linear infinite' }} />
                            <p style={{ marginTop: '12px', fontSize: '13px', color: COLOR_TEXT_SECONDARY }}>Loading workflow diagram...</p>
                          </div>
                        </div>
                      )}
                      
                      {/* Error State */}
                      {workflowImageError && (
                        <div style={{
                          padding: '40px 20px',
                          textAlign: 'center',
                          background: 'linear-gradient(135deg, rgba(239,68,68,0.05) 0%, rgba(220,38,38,0.05) 100%)'
                        }}>
                          <AlertTriangle style={{ width: '48px', height: '48px', color: COLOR_ERROR, margin: '0 auto' }} />
                          <h3 style={{ marginTop: '16px', fontSize: '16px', color: COLOR_ERROR, fontWeight: 600 }}>Failed to Load Workflow Diagram</h3>
                          <p style={{ marginTop: '8px', fontSize: '13px', color: COLOR_TEXT_SECONDARY }}>Please refresh the page or contact support.</p>
                        </div>
                      )}
                      
                      {/* Actual Image */}
                      <img 
                        src={WORKFLOW_DIAGRAM_IMAGE_PATH} 
                        alt="P&ID Verification Workflow - 3 Stage Process: Upload Documents, AI Analysis, Quality Report"
                        onLoad={() => { setWorkflowImageLoaded(true); setWorkflowImageError(false); }}
                        onError={() => { setWorkflowImageError(true); setWorkflowImageLoaded(false); }}
                        style={{
                          width: `${workflowZoom}%`,
                          height: 'auto',
                          display: 'block',
                          margin: '0 auto',
                          transition: 'transform 300ms ease',
                          cursor: workflowZoom < 200 ? 'zoom-in' : 'default',
                          minHeight: '200px'
                        }}
                        onClick={() => {
                          if (workflowZoom < 200) {
                            setWorkflowZoom(Math.min(200, workflowZoom + 25));
                          }
                        }}
                      />
                    </div>

                    {/* Workflow Caption */}
                    <div style={{
                      marginTop: '16px',
                      textAlign: 'center',
                      maxWidth: '900px',
                      padding: '12px 20px',
                      background: 'rgba(59,130,246,0.05)',
                      borderRadius: '10px',
                      border: '1px solid rgba(59,130,246,0.1)'
                    }}>
                      <p style={{
                        fontSize: '13px',
                        color: COLOR_TEXT_SECONDARY,
                        margin: 0,
                        lineHeight: 1.6
                      }}>
                        <span style={{ color: COLOR_PRIMARY, fontWeight: 700 }}>✓ 3-Stage AI Process:</span> <span style={{ fontWeight: 500 }}>Stage 1</span> Upload P&ID drawings & legends (PDF/DWG/PNG) → <span style={{ fontWeight: 500 }}>Stage 2</span> AI Analysis with 20+ verification rules (OCR, Vision, ML) → <span style={{ fontWeight: 500 }}>Stage 3</span> Interactive quality report with export capabilities
                      </p>
                      <div style={{ marginTop: '8px', fontSize: '11px', color: '#6366f1', fontStyle: 'italic' }}>
                        💡 Tip: Click image to zoom in • Use controls above for zoom/fullscreen
                      </div>
                    </div>

                  </div>

                  {/* Workflow Features Bar - Key Capabilities */}
                  {!workflowCompact && (
                    <div style={{
                      marginTop: '24px',
                      paddingTop: '20px',
                      borderTop: `1px solid ${WORKFLOW_BORDER_COLOR}`,
                      display: 'flex',
                      justifyContent: 'center',
                      gap: '16px',
                      flexWrap: 'wrap'
                    }}>
                      {[
                        { icon: Tag, label: 'Tag Validation', color: '#3b82f6', desc: 'Equipment & instrument tags' },
                        { icon: Network, label: 'Connectivity', color: '#8b5cf6', desc: 'Line continuity checks' },
                        { icon: Ruler, label: 'Line Sizing', color: '#f59e0b', desc: 'Diameter consistency' },
                        { icon: Shield, label: 'Compliance', color: '#10b981', desc: 'Industry standards' }
                      ].map((feature, i) => (
                        <div 
                          key={i} 
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '8px',
                            padding: '10px 16px',
                            borderRadius: '10px',
                            background: 'rgba(148,163,184,0.05)',
                            border: '1px solid rgba(148,163,184,0.15)',
                            fontSize: '12px',
                            fontWeight: 500,
                            color: COLOR_TEXT_SECONDARY,
                            cursor: 'help',
                            transition: 'all 200ms ease',
                            position: 'relative'
                          }}
                          title={feature.desc}
                          onMouseEnter={(e) => {
                            e.currentTarget.style.background = 'rgba(148,163,184,0.1)';
                            e.currentTarget.style.borderColor = feature.color;
                            e.currentTarget.style.transform = 'translateY(-2px)';
                          }}
                          onMouseLeave={(e) => {
                            e.currentTarget.style.background = 'rgba(148,163,184,0.05)';
                            e.currentTarget.style.borderColor = 'rgba(148,163,184,0.15)';
                            e.currentTarget.style.transform = 'translateY(0)';
                          }}
                        >
                          <feature.icon style={{ width: '16px', height: '16px', color: feature.color }} />
                          {feature.label}
                        </div>
                      ))}
                    </div>
                  )}

                </div>
              )}
            </div>

            {/* ─── RIGHT COLUMN: Documentation Area (Split-Screen Mode Only) ─── */}
            {WORKFLOW_SPLIT_SCREEN && (
              <div style={{
                background: WORKFLOW_BG_COLOR,
                border: `1px solid ${WORKFLOW_BORDER_COLOR}`,
                borderRadius: WORKFLOW_BORDER_RADIUS,
                boxShadow: WORKFLOW_SHADOW,
                overflow: 'hidden',
                display: 'flex',
                flexDirection: 'column',
                maxHeight: '600px'
              }}>
                {/* Header */}
                <div style={{
                  padding: '20px 24px',
                  borderBottom: `1px solid ${WORKFLOW_BORDER_COLOR}`,
                  background: 'linear-gradient(135deg, rgba(99,102,241,0.03) 0%, rgba(59,130,246,0.06) 100%)'
                }}>
                  <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    gap: '12px',
                    marginBottom: '12px'
                  }}>
                    <BookOpen style={{ width: '24px', height: '24px', color: COLOR_PRIMARY }} />
                    <div style={{ flex: 1 }}>
                      <h3 style={{
                        fontSize: '1.1rem',
                        fontWeight: 700,
                        color: COLOR_TEXT_PRIMARY,
                        margin: 0,
                        lineHeight: 1
                      }}>
                        Smart Documentation
                      </h3>
                      <p style={{
                        fontSize: '0.75rem',
                        color: COLOR_TEXT_SECONDARY,
                        margin: '4px 0 0',
                        lineHeight: 1
                      }}>
                        {projects.length === 0 
                          ? 'Get started with your first P&ID verification' 
                          : `${projects.length} project${projects.length === 1 ? '' : 's'} • AI-powered quality analysis`
                        }
                      </p>
                    </div>
                    {/* Collapse Workflow Button */}
                    <button
                      onClick={() => setDocPanelCollapsed(!docPanelCollapsed)}
                      style={{
                        padding: '8px 14px',
                        fontSize: '0.75rem',
                        borderRadius: '8px',
                        border: `1px solid ${docPanelCollapsed ? 'rgba(16,185,129,0.3)' : 'rgba(100,116,139,0.3)'}`,
                        background: docPanelCollapsed ? 'rgba(16,185,129,0.08)' : 'rgba(148,163,184,0.06)',
                        color: docPanelCollapsed ? COLOR_SUCCESS : COLOR_TEXT_SECONDARY,
                        cursor: 'pointer',
                        display: 'flex',
                        alignItems: 'center',
                        gap: '6px',
                        fontWeight: 500,
                        transition: 'all 200ms ease',
                        whiteSpace: 'nowrap'
                      }}
                      onMouseEnter={e => {
                        e.currentTarget.style.background = docPanelCollapsed ? 'rgba(16,185,129,0.15)' : 'rgba(148,163,184,0.12)';
                      }}
