                        which always ignores the cache and re-runs the pipeline. */}
                    {d.status === 'completed' && (
                      <button
                        onClick={() => viewPreviousResults(d.document_id, d.file_name)}
                        disabled={viewingPreviousId === d.document_id || recheckingDocId === d.document_id}
