      setBuildingLegend(false);
    }
  };

  const handleClearProjectLegend = async () => {
    if (!selectedProject?.project_id) return;
    setClearingLegend(true);
    try {
      await axios.delete(
        `${API_PREFIX}/projects/${selectedProject.project_id}/legend/build/`,
