            animation: `${ANIMATION_CARD_ENTRANCE} ${ANIMATION_ENTRANCE_DURATION} ease-out both`,
            ...(HEADER_SHOW_GRADIENT_BG && {
              background: `linear-gradient(135deg, ${HEADER_GRADIENT_FROM} 0%, ${HEADER_GRADIENT_TO} 100%)`,
