                {/* Title & Description */}
                <div className="flex-1">
                  <div className="flex items-center gap-3 mb-2 flex-wrap">
                    <h1 style={{ 
                      fontSize: HEADING_MAIN_SIZE,
                      fontWeight: HEADING_MAIN_WEIGHT,
                      color: COLOR_TEXT_PRIMARY,
                      lineHeight: 1.2,
                      margin: 0
                    }}>
                      P&ID Verification {SHOW_VERSION_BADGE && <span style={{ fontSize: '0.85em', color: '#6366f1' }}>V2</span>}
                    </h1>
                    {HEADER_SHOW_STATUS_BADGE && (
                      <span style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '6px',
                        padding: '4px 12px',
                        borderRadius: '20px',
                        fontSize: '0.75rem',
                        fontWeight: 600,
                        background: `${HEADER_BADGE_COLOR}15`,
                        color: HEADER_BADGE_COLOR,
                        border: `1px solid ${HEADER_BADGE_COLOR}30`
                      }}>
                        <CheckCircle style={{ width: '14px', height: '14px' }} />
                        {HEADER_BADGE_TEXT}
                      </span>
                    )}
                    {SHOW_VERSION_BADGE && (
                      <span style={{
                        display: 'inline-flex',
                        alignItems: 'center',
                        gap: '6px',
                        padding: '4px 12px',
                        borderRadius: '20px',
                        fontSize: '0.75rem',
                        fontWeight: 600,
                        background: '#ede9fe',
                        color: '#6366f1',
                        border: '1px solid #c7d2fe'
                      }}>
                        <Sparkles style={{ width: '14px', height: '14px' }} />
                        {V2_BETA_MODE ? 'Beta' : 'Version 2'}
                      </span>
                    )}
                    {/* "Go to V1" — carries the currently selected project's
                        name across via ?fromProject=<name> (V1/V2 are
                        separate apps with their own project rows, no shared
                        ID, so name is the only practical link) — see the
                        mount effect near fetchProjects() in V1's
                        PIDVerification.jsx that reads this back. */}
                    <button
                      type="button"
                      onClick={() => navigate(`/engineering/process/pid-verification-v1${selectedProject?.project_name ? `?fromProject=${encodeURIComponent(selectedProject.project_name)}` : ''}`)}
