                      <GitBranch style={{ width: '14px', height: '14px' }} />
                      Go to V1
                    </button>
                  </div>
                  <p style={{ 
                    fontSize: HEADING_SUB_SIZE,
                    color: HEADING_SUB_COLOR,
                    margin: 0,
                    maxWidth: '680px',
                    lineHeight: 1.6
