                    e.currentTarget.style.background = 'white';
                    e.currentTarget.style.color = '#6366f1';
                    e.currentTarget.style.transform = 'translateY(0)';
                    e.currentTarget.style.boxShadow = '0 2px 8px rgba(99,102,241,0.15)';
                  }}
