                  {/* Zoom Controls Bar */}
                  <div style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    marginBottom: '16px',
                    padding: '12px 16px',
                    background: 'linear-gradient(135deg, rgba(59,130,246,0.05) 0%, rgba(99,102,241,0.05) 100%)',
                    borderRadius: '10px',
                    border: '1px solid rgba(59,130,246,0.15)'
                  }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      <div style={{
                        width: '6px',
                        height: '6px',
                        borderRadius: '50%',
                        background: workflowImageLoaded ? COLOR_SUCCESS : (workflowImageError ? COLOR_ERROR : COLOR_WARNING),
                        boxShadow: `0 0 8px ${workflowImageLoaded ? COLOR_SUCCESS : (workflowImageError ? COLOR_ERROR : COLOR_WARNING)}`
                      }} />
                      <span style={{ fontSize: '12px', color: COLOR_TEXT_SECONDARY, fontWeight: 500 }}>
                        {workflowImageError ? 'Failed to load diagram' : (workflowImageLoaded ? 'Workflow Diagram' : 'Loading...')}
                      </span>
                    </div>
                    
                    {/* Always show controls */}
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
                      {/* Zoom Out */}
                      <button
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          console.log('Zoom out clicked, current:', workflowZoom);
                          setWorkflowZoom(Math.max(50, workflowZoom - 10));
                        }}
                        disabled={workflowZoom <= 50}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          width: '32px',
                          height: '32px',
                          borderRadius: '8px',
                          border: '1px solid rgba(148,163,184,0.2)',
                          background: workflowZoom <= 50 ? 'rgba(148,163,184,0.05)' : 'rgba(59,130,246,0.08)',
                          color: workflowZoom <= 50 ? '#94a3b8' : COLOR_PRIMARY,
                          cursor: workflowZoom <= 50 ? 'not-allowed' : 'pointer',
                          transition: 'all 200ms ease',
                          fontSize: '18px',
                          fontWeight: 600,
                          opacity: workflowZoom <= 50 ? 0.5 : 1
                        }}
                        title="Zoom Out (Min 50%)"
                      >
                        −
                      </button>
                      
                      {/* Zoom Level Display */}
                      <div style={{
                        padding: '6px 12px',
                        borderRadius: '8px',
                        background: 'rgba(59,130,246,0.1)',
                        border: '1px solid rgba(59,130,246,0.2)',
                        fontSize: '13px',
                        fontWeight: 600,
                        color: COLOR_PRIMARY,
                        minWidth: '60px',
                        textAlign: 'center'
                      }}>
                        {workflowZoom}%
                      </div>
                      
                      {/* Zoom In */}
                      <button
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          console.log('Zoom in clicked, current:', workflowZoom);
                          setWorkflowZoom(Math.min(200, workflowZoom + 10));
                        }}
                        disabled={workflowZoom >= 200}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          width: '32px',
                          height: '32px',
                          borderRadius: '8px',
                          border: '1px solid rgba(148,163,184,0.2)',
                          background: workflowZoom >= 200 ? 'rgba(148,163,184,0.05)' : 'rgba(59,130,246,0.08)',
                          color: workflowZoom >= 200 ? '#94a3b8' : COLOR_PRIMARY,
                          cursor: workflowZoom >= 200 ? 'not-allowed' : 'pointer',
                          transition: 'all 200ms ease',
                          fontSize: '18px',
                          fontWeight: 600,
                          opacity: workflowZoom >= 200 ? 0.5 : 1
                        }}
                        title="Zoom In (Max 200%)"
                      >
                        +
                      </button>
                      
                      {/* Reset Zoom */}
                      {workflowZoom !== 100 && (
                        <button
                          onClick={(e) => {
                            e.preventDefault();
                            e.stopPropagation();
                            console.log('Reset zoom clicked');
                            setWorkflowZoom(100);
                          }}
                          style={{
                            display: 'flex',
                            alignItems: 'center',
                            gap: '4px',
                            padding: '6px 10px',
                            borderRadius: '8px',
                            border: '1px solid rgba(148,163,184,0.2)',
                            background: 'rgba(99,102,241,0.08)',
                            color: '#6366f1',
                            cursor: 'pointer',
                            transition: 'all 200ms ease',
                            fontSize: '11px',
                            fontWeight: 600
                          }}
                          title="Reset to 100%"
                        >
                          <Minimize2 style={{ width: '14px', height: '14px' }} />
                          Reset
                        </button>
                      )}
                      
                      {/* Fullscreen */}
                      <button
                        onClick={(e) => {
                          e.preventDefault();
                          e.stopPropagation();
                          console.log('Fullscreen clicked');
                          setWorkflowFullscreen(true);
                        }}
                        style={{
                          display: 'flex',
                          alignItems: 'center',
                          gap: '4px',
                          padding: '6px 10px',
                          borderRadius: '8px',
                          border: '1px solid rgba(16,185,129,0.2)',
                          background: 'rgba(16,185,129,0.08)',
                          color: COLOR_SUCCESS,
                          cursor: 'pointer',
                          transition: 'all 200ms ease',
                          fontSize: '11px',
                          fontWeight: 600
                        }}
                        title="View Fullscreen"
                      >
                        <Maximize2 style={{ width: '14px', height: '14px' }} />
                        Fullscreen
                      </button>
                    </div>
                  </div>
                  
                  {/* P&ID Verification Workflow Diagram - Interactive Image */}
                  <div style={{
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                    justifyContent: 'center',
                    width: '100%',
                    maxWidth: '100%',
                    overflow: 'auto'
                  }}>
                    
                    {/* Workflow Image Container */}
                    <div style={{
                      width: workflowCompact ? '90%' : '95%',
                      maxWidth: '1400px',
                      margin: '0 auto',
                      borderRadius: '12px',
                      overflow: workflowZoom === 100 ? 'hidden' : 'auto',
                      boxShadow: '0 8px 32px rgba(0,0,0,0.15)',
                      background: 'white',
                      border: '2px solid rgba(59,130,246,0.2)',
