                          <p style={{ marginTop: '8px', fontSize: '13px', color: COLOR_TEXT_SECONDARY }}>Please refresh the page or contact support.</p>
                        </div>
                      )}
                      
                      {/* Actual Image */}
                      <img 
                        src="/assets/images/PID_Workflow.png" 
