                          </div>
                          {/* Rows — soft-coded from COMPARE_METRICS */}
                          {COMPARE_METRICS.map((m, idx) => {
                            const b = bef[m.key] ?? 0;
                            const a = aft[m.key] ?? 0;
                            const d = dlt[m.key] ?? (a - b);
