                        border: isActive ? `1.5px solid ${tab.accent}` : '1.5px solid #e2e8f0',
                        boxShadow: isActive
                          ? `0 4px 16px ${tab.glow || 'rgba(0,0,0,0.15)'}, 0 1px 4px rgba(0,0,0,0.08)`
