                        transform: isDragging
                          ? `scale(${isActive ? 1.02 : 1})`
                          : isActive
                            ? `scale(1.02) translateY(${translateY}px)`
                            : `scale(1) translateY(${translateY}px)`,
                        opacity: isDragging ? 0.22 : 1,
                        willChange: draggingId ? 'transform' : 'auto',
                        cursor: 'pointer',
                        userSelect: 'none',
                      }}
