import { useState, useEffect } from 'react'
import { X, Loader2 } from 'lucide-react'
import { toast } from 'react-toastify'

import { addLegendLookupEntry, editLegendLookupEntry, listLookupSections, LEGEND_SECTIONS } from '../../../../services/pidCheckerV2API'

/**
 * Shared by P&ID Verification V1 and V2 (both talk to the same
 * pid_checker_v2 legend backend) — two entry points:
 *   - "+ Add to Legend" quick-add on an unrecognised Legend Check
 *     finding (section/value pre-filled and locked, just needs a
 *     description).
 *   - Manage Legends' own lookup-table row editor (Add Row / Edit),
 *     nothing pre-filled/locked for a new row, section+value locked
 *     for an edit of an existing one.
 * add/edit are the same backend write (upsert) — `mode` only changes
 * the modal's title/button copy and which field(s) start locked.
 */
const AddToLegendModal = ({
  isOpen, onClose, onSaved,
  initialSection = '', initialCode = '', initialDescription = '',
  mode = 'add', lockSection = false, lockCode = false,
}) => {
  const [section, setSection] = useState(initialSection)
  const [code, setCode] = useState(initialCode)
  const [description, setDescription] = useState(initialDescription)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState('')

  // BUG FIX: some legend sections are format/regex-only and have no
  // lookup field at all. Offering them in this dropdown let a user pick
  // one and then fail on save with "no lookup table to add to" no matter
  // what they typed. Fetch which of the user's active legends actually
  // have a lookup table and restrict the dropdown to just those,
  // defaulting to the first one when nothing was explicitly locked in.
  const [lookupSections, setLookupSections] = useState(null) // null = still loading

  // BUG FIX (the real one — the fix above only ever changed what VALUE
  // gets passed as initialSection; this fixes the modal actually USING
  // it). This component never unmounts between opens — Manage Legends
  // keeps ONE instance alive and toggles it via `isOpen`/`return null` —
  // so `useState(initialSection)` above only runs on the very FIRST open
  // this page load ever sees, then never again. Confirmed live: click
  // "+ Add Row" once on ANY tab (locks in whatever that tab's section
  // was), then click it again on a DIFFERENT tab — the modal kept
  // showing the FIRST tab's section every time, because section only
  // ever re-synced when `!lockSection` (line below) — and the Manage
  // Legends "+ Add Row" flow always passes lockSection=true. Re-sync
  // every field fresh on every open, unconditionally.
  useEffect(() => {
    if (!isOpen) return
    setSection(initialSection)
    setCode(initialCode)
    setDescription(initialDescription)
    setError('')
  }, [isOpen, initialSection, initialCode, initialDescription])

  useEffect(() => {
    if (!isOpen) return
    let cancelled = false
    listLookupSections().then((secs) => {
      if (cancelled) return
      setLookupSections(secs)
      if (!lockSection) {
        setSection((prev) => (prev && secs.includes(prev)) ? prev : (secs[0] || ''))
      }
    }).catch(() => { if (!cancelled) setLookupSections([]) })
    return () => { cancelled = true }
  }, [isOpen]) // eslint-disable-line react-hooks/exhaustive-deps

  if (!isOpen) return null

  const availableSections = (lookupSections === null || lockSection)
    ? LEGEND_SECTIONS
    : LEGEND_SECTIONS.filter((s) => lookupSections.includes(s.id))

  const handleSave = async (e) => {
    e.preventDefault()
    if (!section || !code.trim() || !description.trim()) {
      setError('Section, value, and description are all required.')
      return
    }
    setSaving(true); setError('')
    try {
      const call = mode === 'edit' ? editLegendLookupEntry : addLegendLookupEntry
      const payload = { section, code: code.trim(), description: description.trim() }
      const result = await call(payload)
      toast.success(`"${payload.code}" saved to the legend.`)
      onSaved?.(result, payload)
      onClose()
    } catch (err) {
      setError(err.response?.data?.error || err.message || 'Failed to save.')
    } finally {
      setSaving(false)
    }
  }

  return (
    <div
      className="fixed inset-0 z-[70] flex items-center justify-center bg-black/40 px-4"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-xl shadow-xl w-full max-w-sm"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="px-5 py-4 border-b border-slate-200 flex items-center justify-between">
          <h3 className="text-sm font-semibold text-slate-900">
            {mode === 'edit' ? 'Edit Legend Entry' : 'Add to Legend'}
          </h3>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <X className="w-4 h-4" />
          </button>
        </div>
        <form onSubmit={handleSave} className="p-5 space-y-3">
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Section</label>
            <select
              value={section}
              onChange={(e) => setSection(e.target.value)}
              disabled={lockSection || lookupSections === null}
              required
              className="w-full text-sm border border-slate-300 rounded-lg px-3 py-2 bg-white disabled:bg-slate-50 disabled:text-slate-500 outline-none focus:ring-2 focus:ring-purple-200 focus:border-purple-400"
            >
              <option value="">
                {lookupSections === null ? 'Loading tabs…' : 'Select a tab…'}
              </option>
              {availableSections.map((s) => (
                <option key={s.id} value={s.id}>{s.label}</option>
              ))}
            </select>
            {lookupSections !== null && lookupSections.length === 0 && (
              <p className="text-xs text-amber-600 mt-1">
                No legend tab has a lookup table to add codes to yet.
              </p>
            )}
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Value</label>
            <input
              value={code}
              onChange={(e) => setCode(e.target.value)}
              disabled={lockCode}
              required
              className="w-full text-sm border border-slate-300 rounded-lg px-3 py-2 disabled:bg-slate-50 disabled:text-slate-500 outline-none focus:ring-2 focus:ring-purple-200 focus:border-purple-400"
            />
          </div>
          <div>
            <label className="block text-xs font-semibold text-slate-700 mb-1">Description</label>
            <input
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              placeholder="e.g. DIGITAL INPUT"
              required
              autoFocus
              className="w-full text-sm border border-slate-300 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-purple-200 focus:border-purple-400"
            />
          </div>
          {error && <p className="text-xs text-red-600">{error}</p>}
          <div className="flex justify-end gap-2 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="text-sm px-3 py-1.5 rounded-lg text-slate-600 hover:bg-slate-100"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={saving}
              className="text-sm px-4 py-1.5 rounded-lg bg-purple-600 text-white hover:bg-purple-700 disabled:opacity-50 flex items-center gap-1.5"
            >
              {saving && <Loader2 className="w-3.5 h-3.5 animate-spin" />} Save
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}

export default AddToLegendModal

import useAIProviderStatus from '../../../../hooks/useAIProviderStatus'
import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { toast } from 'react-toastify'
import {
  GitCompare, Loader2, Sparkles, Download,
  CheckCircle2, AlertTriangle, XCircle, PlusCircle, ChevronDown, ChevronRight,
} from 'lucide-react'

import { crossCheck } from '../../../../services/pidCheckerV2API'
import LineListHistoryPopover from './LineListHistoryPopover'
import { downloadCrossCheckExcel } from './crossCheckExcelExport'

// ─── Soft-coded theme (matches parent) ─────────────────────────────
const THEME_PRIMARY = '#7c3aed'
const THEME_ACCENT = '#ec4899'
const THEME_TEXT = '#0f172a'
const THEME_MUTED = '#64748b'
const THEME_BORDER = '#e2e8f0'
const THEME_BG_SOFT = '#f8fafc'
const THEME_GRADIENT = `linear-gradient(135deg, ${THEME_PRIMARY} 0%, ${THEME_ACCENT} 100%)`

// Backend finding kinds (mirror line_list_cross_check.py)
const K_MATCH        = 'match'
const K_MISSING      = 'missing_on_pid'
const K_EXTRA        = 'extra_on_pid'
const K_MISMATCH     = 'mismatch'

const KIND_META = {
  [K_MATCH]:    { label: 'Match',            colour: '#047857', bg: '#ecfdf5', border: '#a7f3d0', Icon: CheckCircle2 },
  [K_MISSING]:  { label: 'Missing on P&ID',  colour: '#b91c1c', bg: '#fef2f2', border: '#fecaca', Icon: XCircle },
  [K_EXTRA]:    { label: 'Extra on P&ID',    colour: '#b45309', bg: '#fffbeb', border: '#fcd34d', Icon: PlusCircle },
  [K_MISMATCH]: { label: 'Mismatch',         colour: '#b91c1c', bg: '#fef2f2', border: '#fecaca', Icon: AlertTriangle },
}

const FILTERS = [
  { id: 'all', label: 'All' },
  { id: K_MISSING,  label: 'Missing on P&ID' },
  { id: K_EXTRA,    label: 'Extra on P&ID' },
  { id: K_MISMATCH, label: 'Mismatch' },
  { id: K_MATCH,    label: 'Match' },
]

/**
 * CrossCheckPanel
 *
 * Compares extracted P&ID tags against the active master Line List and,
 * optionally, asks the configured AI provider to correlate MISSING vs
 * EXTRA entries (typos / renumbering).
 *
 * Props:
 *   tags            — array of tag dicts from the extraction result
 *   activeLineList  — the currently-active Line List or null
 *   provider        — BYOK provider id (openai|claude) or null
 *   apiKey          — BYOK api key or null
 *   onLineListChange — called after activate / delete inside the popover
 *   projectId        — active project's UUID, scopes the history popover to it
 */
export default function CrossCheckPanel({ tags, activeLineList, provider, apiKey, onLineListChange, onResultChange, projectId }) {
  const [loading, setLoading] = useState(false)
  const [result, setResult] = useState(null)
  const [useAi, setUseAi] = useState(true)
  const [filter, setFilter] = useState('all')
  const [expanded, setExpanded] = useState(null)

  const centralAI = useAIProviderStatus(provider)
  const canAi = centralAI.canUseAI
  const hasTags = Array.isArray(tags) && tags.length > 0
  const disabled = loading || !hasTags || !activeLineList

  const onRun = useCallback(async () => {
    if (!hasTags) { toast.warn('No P&ID tags to cross-check'); return }
    if (!activeLineList) { toast.warn('Upload and activate a Line List first'); return }
    setLoading(true)
    try {
      const data = await crossCheck({
        tags,
        lineListId: activeLineList.line_list_id,
        projectId,
        useAi: useAi && canAi,
        provider,
        apiKey,
      })
      setResult(data)
      const s = data.summary || {}
      toast.success(
        `Cross-check: ${s.match || 0} match · ${s.missing_on_pid || 0} missing · `
        + `${s.extra_on_pid || 0} extra · ${s.mismatch || 0} mismatch`
      )
    } catch (err) {
      toast.error(err?.response?.data?.error || err.message || 'Cross-check failed')
    } finally {
      setLoading(false)
    }
  }, [tags, activeLineList, useAi, canAi, provider, apiKey, hasTags, projectId])

  // Bubble the latest cross-check result up so the parent can build a combined workbook
  useEffect(() => { if (typeof onResultChange === 'function') onResultChange(result) }, [result, onResultChange])

  const findings = result?.findings || []
  const filtered = useMemo(() => {
    if (filter === 'all') return findings
    return findings.filter(f => f.kind === filter)
  }, [findings, filter])

  const s = result?.summary || {}

  return (
    <div style={{
      background: '#fff', border: `1px solid ${THEME_BORDER}`, borderRadius: 12,
      padding: 20, marginTop: 20,
    }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14, flexWrap: 'wrap' }}>
        <div style={{
          width: 32, height: 32, borderRadius: 8,
          background: THEME_GRADIENT, display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <GitCompare size={16} color="#fff" />
        </div>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: 15, fontWeight: 600, color: THEME_TEXT }}>
            Cross-check vs Master Line List
          </div>
          <div style={{ fontSize: 12, color: THEME_MUTED }}>
            {activeLineList
              ? `Comparing against: ${activeLineList.title || activeLineList.filename} · ${activeLineList.total_rows} lines`
              : 'No active Line List — upload one above.'}
          </div>
        </div>

        <label
          title={canAi ? '' : 'Ask your administrator to configure the selected AI provider'}
          style={{
            marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6,
            fontSize: 12, color: canAi ? THEME_TEXT : THEME_MUTED,
            cursor: canAi ? 'pointer' : 'not-allowed', userSelect: 'none',
          }}
        >
          <input
            type="checkbox" checked={useAi && canAi} disabled={!canAi}
            onChange={(e) => setUseAi(e.target.checked)}
          />
          <Sparkles size={12} color={THEME_PRIMARY} /> AI-assisted correlation
        </label>

        <LineListHistoryPopover
          activeLineList={activeLineList}
          onChange={onLineListChange}
          projectId={projectId}
        />

        <button
          type="button" onClick={onRun} disabled={disabled}
          style={{
            display: 'flex', alignItems: 'center', gap: 6,
            padding: '8px 14px', borderRadius: 8,
            border: 'none', color: '#fff',
            background: disabled ? '#cbd5e1' : THEME_GRADIENT,
            fontSize: 12, fontWeight: 600,
            cursor: disabled ? 'not-allowed' : 'pointer',
          }}
        >
          {loading
            ? <><Loader2 size={12} style={{ animation: 'spin 1s linear infinite' }} /> Comparing…</>
            : <><GitCompare size={12} /> Run cross-check</>}
        </button>

        {result && (
          <button
            type="button"
            onClick={() => downloadCrossCheckExcel(result, 'line_list', {
              contextTitle: activeLineList
                ? (activeLineList.title || activeLineList.filename)
                : '',
            })}
            title="Download this cross-check as an Excel workbook"
            style={{
              display: 'flex', alignItems: 'center', gap: 6,
              padding: '8px 12px', borderRadius: 8,
              border: `1px solid ${THEME_BORDER}`,
              background: '#fff', color: THEME_TEXT,
              fontSize: 12, fontWeight: 600, cursor: 'pointer',
            }}
          >
            <Download size={12} /> Excel
          </button>
        )}
      </div>

      {/* Summary pills */}
      {result && (
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 14 }}>
          <SummaryPill label="P&ID tags"     value={s.pid_total ?? 0} />
          <SummaryPill label="Line List"     value={s.line_list_total ?? 0} />
          <SummaryPill label="Match"         value={s.match ?? 0}         tone="ok" />
          <SummaryPill label="Missing on P&ID" value={s.missing_on_pid ?? 0} tone="err" />
          <SummaryPill label="Extra on P&ID"   value={s.extra_on_pid ?? 0}   tone="warn" />
          <SummaryPill label="Mismatch"      value={s.mismatch ?? 0}      tone="err" />
          <SummaryPill label="Coverage"      value={`${s.coverage_pct ?? 0}%`} tone={
            (s.coverage_pct ?? 0) >= 95 ? 'ok' : (s.coverage_pct ?? 0) >= 75 ? 'warn' : 'err'
          } />
          {result.ai_used && (
            <span style={{
              padding: '4px 10px', borderRadius: 999, fontSize: 11, fontWeight: 600,
              color: '#fff', background: THEME_GRADIENT,
              display: 'inline-flex', alignItems: 'center', gap: 4,
            }}>
              <Sparkles size={11} /> AI enrichment applied
            </span>
          )}
        </div>
      )}

      {/* Filter tabs */}
      {result && (
        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 10 }}>
          {FILTERS.map(f => (
            <button
              key={f.id} type="button" onClick={() => setFilter(f.id)}
              style={{
                padding: '5px 10px', borderRadius: 999, fontSize: 12,
                border: `1px solid ${filter === f.id ? THEME_PRIMARY : THEME_BORDER}`,
                background: filter === f.id ? '#faf5ff' : '#fff',
                color: filter === f.id ? THEME_PRIMARY : THEME_TEXT,
                fontWeight: filter === f.id ? 600 : 500, cursor: 'pointer',
              }}
            >
              {f.label}
            </button>
          ))}
        </div>
      )}

      {/* Findings */}
      {result && (
        filtered.length === 0
          ? (
            <div style={{ padding: 14, textAlign: 'center', color: THEME_MUTED, fontSize: 13 }}>
              No findings in this category.
            </div>
          )
          : (
            <div style={{ display: 'grid', gap: 6 }}>
              {filtered.map((f, idx) => {
                const meta = KIND_META[f.kind] || KIND_META[K_MISMATCH]
                const key = `${f.kind}::${f.tag || f.expected_tag || idx}`
                const isOpen = expanded === key
                return (
                  <div key={key} style={{
                    borderRadius: 10, border: `1px solid ${meta.border}`, background: meta.bg,
                  }}>
                    <button
                      type="button" onClick={() => setExpanded(isOpen ? null : key)}
                      style={{
                        width: '100%', textAlign: 'left',
                        display: 'flex', alignItems: 'center', gap: 10,
                        padding: '10px 12px', border: 'none', background: 'transparent',
                        cursor: 'pointer',
                      }}
                    >
                      <meta.Icon size={14} color={meta.colour} />
                      <span style={{
                        fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
                        fontSize: 13, fontWeight: 600, color: THEME_TEXT,
                      }}>
                        {f.tag || f.expected_tag || '(no tag)'}
                      </span>
                      <span style={{
                        padding: '2px 8px', borderRadius: 999, fontSize: 11,
                        background: '#fff', color: meta.colour,
                        border: `1px solid ${meta.border}`,
                      }}>
                        {meta.label}
                      </span>
                      <span style={{ marginLeft: 'auto', color: THEME_MUTED, fontSize: 12 }}>
                        {f.message || ''}
                      </span>
                      {isOpen ? <ChevronDown size={14} color={THEME_MUTED} /> : <ChevronRight size={14} color={THEME_MUTED} />}
                    </button>

                    {isOpen && (
                      <div style={{
                        padding: '4px 14px 12px 40px', fontSize: 12, color: THEME_TEXT,
                        display: 'grid', gap: 4,
                      }}>
                        {f.details && Object.entries(f.details).map(([k, v]) => (
                          <div key={k}>
                            <span style={{ color: THEME_MUTED }}>{k}:</span>{' '}
                            <span>{typeof v === 'object' ? JSON.stringify(v) : String(v)}</span>
                          </div>
                        ))}
                        {f.ai_suggested_match && (
                          <div style={{
                            marginTop: 6, padding: '6px 10px', borderRadius: 8,
                            background: '#faf5ff', border: `1px solid ${THEME_PRIMARY}`,
                            display: 'flex', alignItems: 'center', gap: 6,
                          }}>
                            <Sparkles size={12} color={THEME_PRIMARY} />
                            <span style={{ color: THEME_PRIMARY, fontWeight: 600 }}>
                              AI suggests → {f.ai_suggested_match}
                            </span>
                            {typeof f.ai_confidence === 'number' && (
                              <span style={{ color: THEME_MUTED }}>
                                ({Math.round(f.ai_confidence * 100)}% confidence)
                              </span>
                            )}
                            {f.ai_reason && (
                              <span style={{ color: THEME_MUTED, marginLeft: 4 }}>— {f.ai_reason}</span>
                            )}
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          )
      )}

      {!result && (
        <div style={{ padding: 14, textAlign: 'center', color: THEME_MUTED, fontSize: 13 }}>
          {activeLineList
            ? 'Click "Run cross-check" to compare the extracted tags against the master Line List.'
            : 'Upload a master Line List (Excel) above to enable this cross-check.'}
        </div>
      )}
    </div>
  )
}

function SummaryPill({ label, value, tone = 'neutral' }) {
  const TONE = {
    neutral: { bg: '#f1f5f9', fg: '#0f172a', border: '#e2e8f0' },
    ok:      { bg: '#ecfdf5', fg: '#047857', border: '#a7f3d0' },
    warn:    { bg: '#fffbeb', fg: '#b45309', border: '#fcd34d' },
    err:     { bg: '#fef2f2', fg: '#b91c1c', border: '#fecaca' },
  }[tone] || {}
  return (
    <span style={{
      padding: '5px 10px', borderRadius: 999, fontSize: 12, fontWeight: 600,
      background: TONE.bg, color: TONE.fg, border: `1px solid ${TONE.border}`,
      display: 'inline-flex', alignItems: 'center', gap: 6,
    }}>
      <span style={{ opacity: 0.75 }}>{label}</span>
      <span>{value}</span>
    </span>
  )
}

import useAIProviderStatus from '../../../../hooks/useAIProviderStatus'
import React, { useCallback, useEffect, useMemo, useState } from 'react'
import { toast } from 'react-toastify'
import {
  GitCompare, Loader2, Sparkles, Wand2, Download,
  CheckCircle2, XCircle, PlusCircle, ChevronDown, ChevronRight, Boxes,
} from 'lucide-react'

import {
  equipmentCrossCheck, filterEquipmentTags, extractEquipmentTagsFromPid,
} from '../../../../services/pidCheckerV2API'
import EquipmentListHistoryPopover from './EquipmentListHistoryPopover'
import { downloadCrossCheckExcel } from './crossCheckExcelExport'

// ─── Soft-coded theme ─────────────────────────────────────────────
const THEME_PRIMARY = '#7c3aed'
const THEME_ACCENT = '#ec4899'
const THEME_TEXT = '#0f172a'
const THEME_MUTED = '#64748b'
const THEME_BORDER = '#e2e8f0'
const THEME_BG_SOFT = '#f8fafc'
const THEME_GRADIENT = `linear-gradient(135deg, ${THEME_PRIMARY} 0%, ${THEME_ACCENT} 100%)`

// Backend finding kinds (mirror equipment_cross_check.py)
const K_MATCH   = 'match'
const K_MISSING = 'missing_on_pid'
const K_EXTRA   = 'extra_on_pid'
// Pseudo-filter: matches with attribute mismatches
const K_ATTR_DIFF = 'attribute_mismatch'

const KIND_META = {
  [K_MATCH]:   { label: 'Match',           colour: '#047857', bg: '#ecfdf5', border: '#a7f3d0', Icon: CheckCircle2 },
  [K_MISSING]: { label: 'Missing on P&ID', colour: '#b91c1c', bg: '#fef2f2', border: '#fecaca', Icon: XCircle },
  [K_EXTRA]:   { label: 'Extra on P&ID',   colour: '#b45309', bg: '#fffbeb', border: '#fcd34d', Icon: PlusCircle },
}

// Overall per-tag attribute severity (mirror equipment_cross_check.py)
const SEV_OK       = 'ok'
const SEV_MINOR    = 'minor'
const SEV_CRITICAL = 'critical'

const SEVERITY_META = {
  [SEV_OK]:       { label: 'All attrs OK',   colour: '#047857', bg: '#ecfdf5', border: '#a7f3d0' },
  [SEV_MINOR]:    { label: 'Minor diffs',    colour: '#b45309', bg: '#fffbeb', border: '#fcd34d' },
  [SEV_CRITICAL]: { label: 'Critical diffs', colour: '#b91c1c', bg: '#fef2f2', border: '#fecaca' },
}

// Per-cell attribute status (mirror equipment_cross_check.py)
const ATTR_STATUS_META = {
  match:         { label: 'Match',         colour: '#047857', bg: '#ecfdf5' },
  mismatch:      { label: 'Mismatch',      colour: '#b91c1c', bg: '#fef2f2' },
  missing_pid:   { label: 'Missing (P&ID)',   colour: '#b45309', bg: '#fffbeb' },
  missing_excel: { label: 'Missing (Excel)',  colour: '#b45309', bg: '#fffbeb' },
  both_empty:    { label: '—',             colour: '#94a3b8', bg: '#f8fafc' },
}

const FILTERS = [
  { id: 'all', label: 'All' },
  { id: K_MISSING, label: 'Missing on P&ID' },
  { id: K_EXTRA,   label: 'Extra on P&ID' },
  { id: K_MATCH,   label: 'Match' },
  { id: K_ATTR_DIFF, label: 'Attribute diffs' },
]

/**
 * EquipmentCrossCheckPanel
 *
 * Compares equipment tags detected on the P&ID against the active master
 * Equipment List.  The equipment tags are extracted from the base
 * `tags` list by pattern-matching (V-###-XX, P-###, etc.); the user may
 * also add tags manually via a text field.
 *
 * Props:
 *   tags                 — line-tag dicts from the extraction result (source for pattern-detected equipment tags)
 *   pdfFile              — the raw PDF file the user uploaded, enabling on-demand Vision extraction of equipment tags
 *   activeEquipmentList  — active EL or null
 *   provider, apiKey     — BYOK
 *   onEquipmentListChange — refetch trigger after activate/delete
 */
export default function EquipmentCrossCheckPanel({
  tags, pdfFile, activeEquipmentList, provider, apiKey, onEquipmentListChange, onResultChange, projectId,
}) {
  const [loading, setLoading] = useState(false)
  const [extracting, setExtracting] = useState(false)
  const [visionExtracted, setVisionExtracted] = useState([]) // [{tag, kind, description}]
  const [result, setResult] = useState(null)
  const [useAi, setUseAi] = useState(true)
  const [filter, setFilter] = useState('all')
  const [expanded, setExpanded] = useState(null)
  const [manualInput, setManualInput] = useState('')

  const centralAI = useAIProviderStatus(provider)
  const canAi = centralAI.canUseAI

  // Auto-detect equipment tags from the extracted result set
  const detectedTags = useMemo(() => {
    if (!Array.isArray(tags)) return []
    const tokens = tags.map(t => t?.tag).filter(Boolean)
    return filterEquipmentTags(tokens)
  }, [tags])

  const manualTags = useMemo(() => {
    if (!manualInput.trim()) return []
    const raw = manualInput.split(/[,\s;\n]+/).map(s => s.trim().toUpperCase()).filter(Boolean)
    return Array.from(new Set(raw))
  }, [manualInput])

  // Union of all three sources: line-tag pattern hits, on-demand Vision, manual input
  const finalTags = useMemo(() => {
    const set = new Set([
      ...detectedTags,
      ...visionExtracted.map(v => v.tag).filter(Boolean),
      ...manualTags,
    ])
    return Array.from(set)
  }, [detectedTags, visionExtracted, manualTags])

  // Per-tag attribute dictionary sourced from Vision extraction only.
  // Backend triggers the deep attribute cross-check whenever this object
  // is non-empty (and BYOK creds are set).
  const attributesByTag = useMemo(() => {
    const map = {}
    for (const v of visionExtracted) {
      if (!v?.tag || !v?.attributes || typeof v.attributes !== 'object') continue
      // Skip if every value is empty — no point sending
      const anyValue = Object.values(v.attributes).some(x => x && String(x).trim())
      if (!anyValue) continue
      map[v.tag] = v.attributes
    }
    return map
  }, [visionExtracted])

  const hasAttributes = Object.keys(attributesByTag).length > 0
  const hasTags = finalTags.length > 0
  const disabled = loading || !activeEquipmentList
  const canExtract = Boolean(pdfFile && canAi) && !extracting && !loading

  const onExtractFromPid = useCallback(async () => {
    if (!pdfFile) { toast.warn('Upload a P&ID PDF on the left first'); return }
    if (!canAi)   { toast.warn('Ask your administrator to configure the selected AI provider'); return }
    setExtracting(true)
    try {
      const data = await extractEquipmentTagsFromPid(pdfFile, { provider, apiKey })
      const list = Array.isArray(data?.tags) ? data.tags : []
      setVisionExtracted(list)
      toast.success(`Vision extracted ${list.length} equipment tag(s) from the P&ID`)
    } catch (err) {
      toast.error(err?.response?.data?.error || err.message || 'Vision extraction failed')
    } finally {
      setExtracting(false)
    }
  }, [pdfFile, canAi, provider, apiKey])

  const onRun = useCallback(async () => {
    if (!activeEquipmentList) { toast.warn('Upload and activate an Equipment List first'); return }
    if (hasAttributes && !canAi) {
      toast.warn('AI is unavailable — running tag-only comparison')
    }
    setLoading(true)
    try {
      const data = await equipmentCrossCheck({
        equipmentTags: finalTags,
        equipmentListId: activeEquipmentList.equipment_list_id,
        projectId,
        useAi: useAi && canAi,
        provider,
        apiKey,
        equipmentAttributes: canAi ? attributesByTag : undefined,
      })
      setResult(data)
      const s = data.summary || {}
      const attrNote = (s.attribute_mismatches || 0)
        ? ` · ${s.attribute_mismatches} attr diff(s)${s.attribute_critical ? ` (${s.attribute_critical} critical)` : ''}`
        : ''
      toast.success(
        `Cross-check: ${s.match || 0} match · ${s.missing_on_pid || 0} missing · `
        + `${s.extra_on_pid || 0} extra${attrNote}`
      )
    } catch (err) {
      toast.error(err?.response?.data?.error || err.message || 'Cross-check failed')
    } finally {
      setLoading(false)
    }
  }, [finalTags, activeEquipmentList, useAi, canAi, provider, apiKey, attributesByTag, hasAttributes, projectId])

  // Reset stale result when the active list changes
  useEffect(() => { setResult(null); setExpanded(null) }, [activeEquipmentList?.equipment_list_id])

  // Clear vision extraction when the PDF is swapped out
  useEffect(() => { setVisionExtracted([]) }, [pdfFile])

  // Bubble the latest cross-check result up so the parent can build a combined workbook
  useEffect(() => { if (typeof onResultChange === 'function') onResultChange(result) }, [result, onResultChange])

  const findings = result?.findings || []
  const filtered = useMemo(() => {
    if (filter === 'all') return findings
    if (filter === K_ATTR_DIFF) {
      return findings.filter(f => f.kind === K_MATCH
        && (f.severity === SEV_MINOR || f.severity === SEV_CRITICAL))
    }
    return findings.filter(f => f.kind === filter)
  }, [findings, filter])

  const s = result?.summary || {}

  return (
    <div style={{
      background: '#fff', border: `1px solid ${THEME_BORDER}`, borderRadius: 12,
      padding: 20,
    }}>
      {/* Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 14, flexWrap: 'wrap' }}>
        <div style={{
          width: 32, height: 32, borderRadius: 8,
          background: THEME_GRADIENT, display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <Boxes size={16} color="#fff" />
        </div>
        <div style={{ minWidth: 0 }}>
          <div style={{ fontSize: 15, fontWeight: 600, color: THEME_TEXT }}>
            Cross-check vs Master Equipment List
          </div>
          <div style={{ fontSize: 12, color: THEME_MUTED }}>
            {activeEquipmentList
              ? `Comparing against: ${activeEquipmentList.title || activeEquipmentList.filename} · ${activeEquipmentList.total_rows} items`
              : 'No active Equipment List — upload one on the left.'}
          </div>
        </div>

        <label
          title={canAi ? '' : 'Ask your administrator to configure the selected AI provider'}
          style={{
            marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6,
            fontSize: 12, color: canAi ? THEME_TEXT : THEME_MUTED,
            cursor: canAi ? 'pointer' : 'not-allowed', userSelect: 'none',
          }}
        >
          <input
            type="checkbox" checked={useAi && canAi} disabled={!canAi}
            onChange={(e) => setUseAi(e.target.checked)}
          />
          <Sparkles size={12} color={THEME_PRIMARY} /> AI-assisted correlation
        </label>

        <EquipmentListHistoryPopover
          activeEquipmentList={activeEquipmentList}
          onChange={onEquipmentListChange}
          projectId={projectId}
        />

        <button
          type="button" onClick={onRun} disabled={disabled}
          style={{
            display: 'flex', alignItems: 'center', gap: 6,
            padding: '8px 14px', borderRadius: 8,
            border: 'none', color: '#fff',
            background: disabled ? '#cbd5e1' : THEME_GRADIENT,
            fontSize: 12, fontWeight: 600,
            cursor: disabled ? 'not-allowed' : 'pointer',
          }}
        >
          {loading
            ? <><Loader2 size={12} style={{ animation: 'spin 1s linear infinite' }} /> Comparing…</>
            : <><GitCompare size={12} /> Run cross-check</>}
        </button>

        {result && (
          <button
            type="button"
            onClick={() => downloadCrossCheckExcel(result, 'equipment_list', {
              contextTitle: activeEquipmentList
                ? (activeEquipmentList.title || activeEquipmentList.filename)
                : '',
            })}
            title="Download this cross-check as an Excel workbook"
            style={{
              display: 'flex', alignItems: 'center', gap: 6,
              padding: '8px 12px', borderRadius: 8,
              border: `1px solid ${THEME_BORDER}`,
              background: '#fff', color: THEME_TEXT,
              fontSize: 12, fontWeight: 600, cursor: 'pointer',
            }}
          >
            <Download size={12} /> Excel
          </button>
        )}
      </div>

      {/* Detected + manual equipment tag inputs */}
      <div style={{
        marginBottom: 14, padding: 12, borderRadius: 10,
        border: `1px solid ${THEME_BORDER}`, background: THEME_BG_SOFT,
      }}>
        {/* Vision extraction — the accurate path */}
        <div style={{
          display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap',
          padding: '8px 10px', marginBottom: 10, borderRadius: 8,
          border: `1px solid ${visionExtracted.length ? '#a7f3d0' : THEME_BORDER}`,
          background: visionExtracted.length ? '#ecfdf5' : '#fff',
        }}>
          <Wand2 size={14} color={visionExtracted.length ? '#047857' : THEME_PRIMARY} />
          <div style={{ fontSize: 12, color: THEME_TEXT, minWidth: 0 }}>
            <b>Vision extraction:</b>{' '}
            {visionExtracted.length
              ? <span style={{ color: '#047857' }}>{visionExtracted.length} equipment tag(s) detected on the P&amp;ID</span>
              : <span style={{ color: THEME_MUTED }}>Run a targeted AI pass to pull equipment tags directly from the drawing.</span>}
          </div>
          <button
            type="button" onClick={onExtractFromPid} disabled={!canExtract}
            title={
              !pdfFile ? 'Upload a P&ID PDF on the left first'
                : !canAi ? 'Ask your administrator to configure the selected AI provider'
                : 'Run AI Vision extraction'
            }
            style={{
              marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6,
              padding: '6px 12px', borderRadius: 8,
              border: 'none', color: '#fff',
              background: canExtract ? THEME_GRADIENT : '#cbd5e1',
              fontSize: 12, fontWeight: 600,
              cursor: canExtract ? 'pointer' : 'not-allowed',
            }}
          >
            {extracting
              ? <><Loader2 size={12} style={{ animation: 'spin 1s linear infinite' }} /> Extracting…</>
              : <><Wand2 size={12} /> {visionExtracted.length ? 'Re-extract' : 'Extract from P&ID'}</>}
          </button>
        </div>

        {visionExtracted.length > 0 && (
          <div style={{
            marginBottom: 10, padding: 8, borderRadius: 8,
            background: '#fff', border: `1px solid ${THEME_BORDER}`,
            fontSize: 11, color: THEME_TEXT, maxHeight: 120, overflow: 'auto',
          }}>
            <div style={{ color: THEME_MUTED, marginBottom: 4, fontSize: 10, letterSpacing: 0.3, textTransform: 'uppercase' }}>
              AI-extracted equipment
            </div>
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 6 }}>
              {visionExtracted.map(v => (
                <span key={v.tag} title={v.description || v.kind || ''}
                  style={{
                    padding: '2px 8px', borderRadius: 999, fontSize: 11,
                    background: '#f5f3ff', color: THEME_PRIMARY,
                    border: `1px solid #e9d5ff`,
                    fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
                  }}>
                  {v.tag}{v.kind && v.kind !== 'other' ? ` · ${v.kind}` : ''}
                </span>
              ))}
            </div>
          </div>
        )}

        <div style={{ fontSize: 12, color: THEME_MUTED, marginBottom: 6 }}>
          <b style={{ color: THEME_TEXT }}>{detectedTags.length}</b> extra equipment-shaped tag(s) auto-detected from line extraction
          {detectedTags.length > 0 && (
            <span style={{ marginLeft: 8, color: THEME_TEXT, fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace' }}>
              {detectedTags.slice(0, 8).join(', ')}{detectedTags.length > 8 ? ` … +${detectedTags.length - 8}` : ''}
            </span>
          )}
        </div>
        <div style={{ fontSize: 11, color: THEME_MUTED, marginBottom: 6 }}>
          Add extra equipment tags manually (comma / space / newline separated):
        </div>
        <input
          type="text" value={manualInput} onChange={(e) => setManualInput(e.target.value)}
          placeholder="e.g. V-803-TF, P-101A, E-2001"
          style={{
            width: '100%', padding: '8px 10px', borderRadius: 8,
            border: `1px solid ${THEME_BORDER}`, background: '#fff',
            fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace', fontSize: 12,
            color: THEME_TEXT, outline: 'none',
          }}
        />
        <div style={{ marginTop: 6, fontSize: 11, color: THEME_MUTED }}>
          Total tags to compare: <b style={{ color: THEME_TEXT }}>{finalTags.length}</b>
          {!hasTags && ' — enter at least one tag to compare.'}
        </div>
      </div>

      {/* Summary pills */}
      {result && (
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 14 }}>
          <SummaryPill label="P&ID tags"       value={s.pid_total ?? 0} />
          <SummaryPill label="Equipment List"  value={s.equipment_list_total ?? 0} />
          <SummaryPill label="Match"           value={s.match ?? 0}          tone="ok" />
          <SummaryPill label="Missing on P&ID" value={s.missing_on_pid ?? 0} tone="err" />
          <SummaryPill label="Extra on P&ID"   value={s.extra_on_pid ?? 0}   tone="warn" />
          <SummaryPill label="Coverage"        value={`${s.coverage_pct ?? 0}%`} tone={
            (s.coverage_pct ?? 0) >= 95 ? 'ok' : (s.coverage_pct ?? 0) >= 75 ? 'warn' : 'err'
          } />
          {(s.attribute_mismatches ?? 0) > 0 && (
            <SummaryPill label="Attr diffs" value={s.attribute_mismatches ?? 0}
              tone={(s.attribute_critical ?? 0) > 0 ? 'err' : 'warn'} />
          )}
          {(s.attribute_critical ?? 0) > 0 && (
            <SummaryPill label="Critical" value={s.attribute_critical} tone="err" />
          )}
          {result.ai_attributes_used && (
            <span style={{
              padding: '4px 10px', borderRadius: 999, fontSize: 11, fontWeight: 600,
              color: '#fff', background: THEME_GRADIENT,
              display: 'inline-flex', alignItems: 'center', gap: 4,
            }}>
              <Sparkles size={11} /> AI attribute judge
            </span>
          )}
          {result.ai_used && (
            <span style={{
              padding: '4px 10px', borderRadius: 999, fontSize: 11, fontWeight: 600,
              color: '#fff', background: THEME_GRADIENT,
              display: 'inline-flex', alignItems: 'center', gap: 4,
            }}>
              <Sparkles size={11} /> AI enrichment applied
            </span>
          )}
        </div>
      )}

      {/* Filter tabs */}
      {result && (
        <div style={{ display: 'flex', gap: 6, flexWrap: 'wrap', marginBottom: 10 }}>
          {FILTERS.map(f => (
            <button
              key={f.id} type="button" onClick={() => setFilter(f.id)}
              style={{
                padding: '5px 10px', borderRadius: 999, fontSize: 12,
                border: `1px solid ${filter === f.id ? THEME_PRIMARY : THEME_BORDER}`,
                background: filter === f.id ? '#faf5ff' : '#fff',
                color: filter === f.id ? THEME_PRIMARY : THEME_TEXT,
                fontWeight: filter === f.id ? 600 : 500, cursor: 'pointer',
              }}
            >
              {f.label}
            </button>
          ))}
        </div>
      )}

      {/* Findings */}
      {result && (
        filtered.length === 0
          ? (
            <div style={{ padding: 14, textAlign: 'center', color: THEME_MUTED, fontSize: 13 }}>
              No findings in this category.
            </div>
          )
          : (
            <div style={{ display: 'grid', gap: 6 }}>
              {filtered.map((f, idx) => {
                const meta = KIND_META[f.kind] || KIND_META[K_MATCH]
                const key = `${f.kind}::${f.tag || idx}`
                const isOpen = expanded === key
                return (
                  <div key={key} style={{
                    borderRadius: 10, border: `1px solid ${meta.border}`, background: meta.bg,
                  }}>
                    <button
                      type="button" onClick={() => setExpanded(isOpen ? null : key)}
                      style={{
                        width: '100%', textAlign: 'left',
                        display: 'flex', alignItems: 'center', gap: 10,
                        padding: '10px 12px', border: 'none', background: 'transparent',
                        cursor: 'pointer',
                      }}
                    >
                      <meta.Icon size={14} color={meta.colour} />
                      <span style={{
                        fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace',
                        fontSize: 13, fontWeight: 600, color: THEME_TEXT,
                      }}>
                        {f.tag || '(no tag)'}
                      </span>
                      <span style={{
                        padding: '2px 8px', borderRadius: 999, fontSize: 11,
                        background: '#fff', color: meta.colour,
                        border: `1px solid ${meta.border}`,
                      }}>
                        {meta.label}
                      </span>
                      {f.kind === K_MATCH && f.severity && SEVERITY_META[f.severity] && (
                        <span title={SEVERITY_META[f.severity].label} style={{
                          padding: '2px 8px', borderRadius: 999, fontSize: 11, fontWeight: 600,
                          background: SEVERITY_META[f.severity].bg,
                          color: SEVERITY_META[f.severity].colour,
                          border: `1px solid ${SEVERITY_META[f.severity].border}`,
                          display: 'inline-flex', alignItems: 'center', gap: 4,
                        }}>
                          <span style={{
                            width: 6, height: 6, borderRadius: '50%',
                            background: SEVERITY_META[f.severity].colour, display: 'inline-block',
                          }} />
                          {SEVERITY_META[f.severity].label}
                        </span>
                      )}
                      {f.description && (
                        <span style={{ color: THEME_MUTED, fontSize: 12 }}>
                          {f.description}
                        </span>
                      )}
                      <span style={{ marginLeft: 'auto' }}>
                        {isOpen ? <ChevronDown size={14} color={THEME_MUTED} /> : <ChevronRight size={14} color={THEME_MUTED} />}
                      </span>
                    </button>

                    {isOpen && (
                      <div style={{
                        padding: '4px 14px 12px 40px', fontSize: 12, color: THEME_TEXT,
                        display: 'grid', gap: 4,
                      }}>
                        {f.message && (
                          <div style={{ color: THEME_MUTED }}>{f.message}</div>
                        )}
                        {f.description && (
                          <div><span style={{ color: THEME_MUTED }}>Description:</span> {f.description}</div>
                        )}
                        {f.pid_no && (
                          <div><span style={{ color: THEME_MUTED }}>P&amp;ID:</span> {f.pid_no}</div>
                        )}
                        {f.moc && (
                          <div><span style={{ color: THEME_MUTED }}>MOC:</span> {f.moc}</div>
                        )}
                        {f.phase && (
                          <div><span style={{ color: THEME_MUTED }}>Phase:</span> {f.phase}</div>
                        )}
                        {f.equipment_list_row && (
                          <div><span style={{ color: THEME_MUTED }}>Excel row:</span> {f.equipment_list_row}</div>
                        )}
                        {f.ai_suggested_match && (
                          <div style={{
                            marginTop: 6, padding: '6px 10px', borderRadius: 8,
                            background: '#faf5ff', border: `1px solid ${THEME_PRIMARY}`,
                            display: 'flex', alignItems: 'center', gap: 6, flexWrap: 'wrap',
                          }}>
                            <Sparkles size={12} color={THEME_PRIMARY} />
                            <span style={{ color: THEME_PRIMARY, fontWeight: 600 }}>
                              AI suggests → {f.ai_suggested_match}
                            </span>
                            {f.ai_confidence && (
                              <span style={{ color: THEME_MUTED }}>({f.ai_confidence})</span>
                            )}
                            {f.ai_reason && (
                              <span style={{ color: THEME_MUTED, marginLeft: 4 }}>— {f.ai_reason}</span>
                            )}
                          </div>
                        )}
                        {Array.isArray(f.attributes) && f.attributes.length > 0 && (
                          <AttributeGrid attributes={f.attributes} />
                        )}
                      </div>
                    )}
                  </div>
                )
              })}
            </div>
          )
      )}

      {!result && (
        <div style={{ padding: 14, textAlign: 'center', color: THEME_MUTED, fontSize: 13 }}>
          {activeEquipmentList
            ? 'Click "Run cross-check" to compare the equipment tags against the master Equipment List.'
            : 'Upload a master Equipment List (Excel) on the left to enable this cross-check.'}
        </div>
      )}
    </div>
  )
}

function SummaryPill({ label, value, tone = 'neutral' }) {
  const TONE = {
    neutral: { bg: '#f1f5f9', fg: '#0f172a', border: '#e2e8f0' },
    ok:      { bg: '#ecfdf5', fg: '#047857', border: '#a7f3d0' },
    warn:    { bg: '#fffbeb', fg: '#b45309', border: '#fcd34d' },
    err:     { bg: '#fef2f2', fg: '#b91c1c', border: '#fecaca' },
  }[tone] || {}
  return (
    <span style={{
      padding: '5px 10px', borderRadius: 999, fontSize: 12, fontWeight: 600,
      background: TONE.bg, color: TONE.fg, border: `1px solid ${TONE.border}`,
      display: 'inline-flex', alignItems: 'center', gap: 6,
    }}>
      <span style={{ opacity: 0.75 }}>{label}</span>
      <span>{value}</span>
    </span>
  )
}

function AttributeGrid({ attributes }) {
  return (
    <div style={{
      marginTop: 8, borderRadius: 8, border: '1px solid #e2e8f0',
      background: '#fff', overflow: 'hidden',
    }}>
      <div style={{
        display: 'grid',
        gridTemplateColumns: '1.4fr 1.2fr 1.2fr 0.9fr',
        fontSize: 11, fontWeight: 600, color: '#64748b',
        background: '#f8fafc', padding: '6px 10px',
        borderBottom: '1px solid #e2e8f0',
        textTransform: 'uppercase', letterSpacing: 0.3,
      }}>
        <span>Attribute</span>
        <span>P&amp;ID Value</span>
        <span>Equipment List</span>
        <span>Status</span>
      </div>
      {attributes.map((a, i) => {
        const meta = ATTR_STATUS_META[a.status] || ATTR_STATUS_META.both_empty
        return (
          <div key={`${a.key}-${i}`} style={{
            display: 'grid',
            gridTemplateColumns: '1.4fr 1.2fr 1.2fr 0.9fr',
            fontSize: 12, padding: '6px 10px',
            borderTop: i === 0 ? 'none' : '1px solid #f1f5f9',
            alignItems: 'center',
            background: a.status === 'mismatch' ? '#fef2f2'
              : a.status === 'missing_pid' || a.status === 'missing_excel' ? '#fffbeb'
              : '#fff',
          }}>
            <span style={{ color: '#0f172a', fontWeight: 500 }}>{a.label || a.key}</span>
            <span style={{ color: '#0f172a', fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace' }}>
              {a.pid_value || <span style={{ color: '#94a3b8' }}>—</span>}
            </span>
            <span style={{ color: '#0f172a', fontFamily: 'ui-monospace, SFMono-Regular, Menlo, monospace' }}>
              {a.excel_value || <span style={{ color: '#94a3b8' }}>—</span>}
            </span>
            <span>
              <span title={a.note || ''} style={{
                padding: '2px 8px', borderRadius: 999, fontSize: 11, fontWeight: 600,
                background: meta.bg, color: meta.colour,
                border: `1px solid ${meta.colour}22`,
              }}>
                {meta.label}
              </span>
              {a.note && (
                <div style={{ marginTop: 3, color: '#64748b', fontSize: 11 }}>{a.note}</div>
              )}
            </span>
          </div>
        )
      })}
    </div>
  )
}

import React, { useRef, useState } from 'react'
import { toast } from 'react-toastify'
import { Boxes, Upload, Loader2, CheckCircle2 } from 'lucide-react'

import { uploadEquipmentList } from '../../../../services/pidCheckerV2API'

// ─── Soft-coded theme (matches parent) ─────────────────────────────
const THEME_PRIMARY = '#7c3aed'
const THEME_ACCENT  = '#ec4899'
const THEME_TEXT    = '#0f172a'
const THEME_MUTED   = '#64748b'
const THEME_BORDER  = '#e2e8f0'
const THEME_BG_SOFT = '#f8fafc'
const THEME_GRADIENT = `linear-gradient(135deg, ${THEME_PRIMARY} 0%, ${THEME_ACCENT} 100%)`
const ACCEPTED = '.xlsx,.xlsm'
const MAX_MB = 15

/**
 * Compact Excel Equipment List picker — auto-uploads and calls back.
 *
 * Props:
 *   activeEquipmentList  — currently-active EL summary (or null)
 *   onUploaded(data)     — called with the API response when parse succeeds
 *   disabled             — parent-controlled (e.g. during PDF extraction)
 *   projectId            — active project's UUID, sent with the upload
 *                          request but NOT used to scope it — the Master
 *                          Equipment List is deliberately global (one per
 *                          user account, not per project); see
 *                          PIDCheckerV2.jsx's top-of-file comment for the
 *                          full trace.
 */
export default function EquipmentListDropzone({ activeEquipmentList, onUploaded, disabled, projectId }) {
  const fileRef = useRef(null)
  const [uploading, setUploading] = useState(false)
  const [pct, setPct] = useState(0)

  const onPick = async (e) => {
    const f = e.target.files?.[0]
    if (!f) return
    if (f.size > MAX_MB * 1024 * 1024) {
      toast.error(`File exceeds ${MAX_MB} MB`)
      if (fileRef.current) fileRef.current.value = ''
      return
    }
    setUploading(true); setPct(0)
    try {
      const data = await uploadEquipmentList(f, { onProgress: setPct, projectId })
      toast.success(`Uploaded — ${data.total_rows} equipment items parsed`)
      onUploaded?.(data)
    } catch (err) {
      toast.error(err?.response?.data?.error || err.message || 'Upload failed')
    } finally {
      setUploading(false); setPct(0)
      if (fileRef.current) fileRef.current.value = ''
    }
  }

  const isActive = Boolean(activeEquipmentList)

  return (
    <div style={{
      padding: 14, borderRadius: 10,
      border: `1px dashed ${isActive ? '#bfdbfe' : THEME_BORDER}`,
      background: isActive ? '#eff6ff' : THEME_BG_SOFT,
      display: 'flex', flexDirection: 'column', gap: 10,
      minHeight: 128,
    }}>
      <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
        <div style={{
          width: 28, height: 28, borderRadius: 6,
          background: THEME_GRADIENT, display: 'flex', alignItems: 'center', justifyContent: 'center',
        }}>
          <Boxes size={14} color="#fff" />
        </div>
        <div style={{ fontSize: 13, fontWeight: 600, color: THEME_TEXT }}>
          Master Equipment List (Excel)
        </div>
        {isActive && (
          <span style={{
            marginLeft: 'auto', display: 'inline-flex', alignItems: 'center', gap: 4,
            padding: '2px 8px', borderRadius: 999, fontSize: 11,
            background: '#dbeafe', color: '#1e40af', border: '1px solid #bfdbfe',
          }}>
            <CheckCircle2 size={11} /> {activeEquipmentList.total_rows} items
          </span>
        )}
      </div>

      <button
        type="button"
        onClick={() => fileRef.current?.click()}
        disabled={disabled || uploading}
        style={{
          display: 'flex', alignItems: 'center', justifyContent: 'center', gap: 6,
          padding: '8px 12px', borderRadius: 8,
          border: `1px solid ${THEME_BORDER}`, background: '#fff', color: THEME_TEXT,
          fontSize: 12, fontWeight: 500,
          cursor: (disabled || uploading) ? 'not-allowed' : 'pointer',
        }}
      >
        {uploading
          ? <><Loader2 size={12} style={{ animation: 'spin 1s linear infinite' }} /> Parsing… {pct}%</>
          : <><Upload size={12} /> {isActive ? 'Replace Excel' : 'Choose Excel (.xlsx)'}</>}
      </button>
      <input
        ref={fileRef} type="file" accept={ACCEPTED}
        onChange={onPick} style={{ display: 'none' }}
      />

      <div style={{ fontSize: 11, color: THEME_MUTED, lineHeight: 1.4, minHeight: 32 }}>
        {isActive
          ? <>Active: <b style={{ color: THEME_TEXT }}>{activeEquipmentList.title || activeEquipmentList.filename}</b></>
          : <>Optional — enables cross-check between P&amp;ID equipment tags and the master equipment list.</>}
      </div>
    </div>
  )
}

import { radaiConfirm } from '../../../../services/radaiDialog'
import React, { useCallback, useEffect, useRef, useState } from 'react'
import { toast } from 'react-toastify'
import {
  Boxes, Loader2, RefreshCw, Trash2, CheckCircle2, X, Layers,
} from 'lucide-react'

import {
  listEquipmentLists, activateEquipmentList, deleteEquipmentList,
} from '../../../../services/pidCheckerV2API'

// ─── Soft-coded theme ──────────────────────────────────────────────
const THEME_PRIMARY = '#7c3aed'
const THEME_TEXT    = '#0f172a'
const THEME_MUTED   = '#64748b'
const THEME_BORDER  = '#e2e8f0'
const THEME_BG_SOFT = '#f8fafc'

/**
 * Compact history popover for uploaded Equipment Lists.
 * Dropdown-style, click-outside closes.
 *
 * Props:
 *   activeEquipmentList  — currently-active EL (or null)
 *   onChange()           — called after activate / delete / refresh
 *   projectId            — active project's UUID, scopes the listed history to it
 */
export default function EquipmentListHistoryPopover({ activeEquipmentList, onChange, projectId }) {
  const [open, setOpen] = useState(false)
  const [history, setHistory] = useState([])
  const [loading, setLoading] = useState(false)
  const wrapperRef = useRef(null)

  const refresh = useCallback(async () => {
    setLoading(true)
    try {
      const rows = await listEquipmentLists(projectId)
      setHistory(Array.isArray(rows) ? rows : (rows?.results || []))
    } catch (err) {
      console.warn('[EquipmentListHistoryPopover] refresh failed', err)
    } finally {
      setLoading(false)
    }
  }, [projectId])

  useEffect(() => { if (open) refresh() }, [open, refresh])

  useEffect(() => {
    if (!open) return
    const handler = (e) => {
      if (wrapperRef.current && !wrapperRef.current.contains(e.target)) setOpen(false)
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [open])

  const onActivate = async (id) => {
    try {
      await activateEquipmentList(id)
      await refresh()
      onChange?.()
    } catch (err) {
      toast.error(err?.response?.data?.error || err.message || 'Activate failed')
    }
  }

  const onDelete = async (id) => {
    if (!(await radaiConfirm('Delete this uploaded Equipment List?'))) return
    try {
      await deleteEquipmentList(id)
      await refresh()
      onChange?.()
    } catch (err) {
      toast.error(err?.response?.data?.error || err.message || 'Delete failed')
    }
  }

  return (
    <div ref={wrapperRef} style={{ position: 'relative' }}>
      <button
        type="button" onClick={() => setOpen(v => !v)}
        style={{
          display: 'flex', alignItems: 'center', gap: 6,
          padding: '6px 10px', borderRadius: 8,
          border: `1px solid ${THEME_BORDER}`, background: '#fff', color: THEME_TEXT,
          fontSize: 12, cursor: 'pointer',
        }}
      >
        <Layers size={12} /> Manage equipment lists
      </button>

      {open && (
        <div style={{
          position: 'absolute', top: '100%', right: 0, marginTop: 6,
          width: 380, maxHeight: 380, overflow: 'auto',
          background: '#fff', borderRadius: 10,
          border: `1px solid ${THEME_BORDER}`,
          boxShadow: '0 12px 32px rgba(15,23,42,0.12)',
          zIndex: 50,
        }}>
          <div style={{
            display: 'flex', alignItems: 'center', gap: 8,
            padding: '10px 12px', borderBottom: `1px solid ${THEME_BORDER}`,
          }}>
            <div style={{ fontSize: 13, fontWeight: 600, color: THEME_TEXT }}>
              Uploaded equipment lists
            </div>
            <span style={{
              padding: '2px 8px', borderRadius: 999, fontSize: 11,
              background: THEME_BG_SOFT, color: THEME_MUTED,
            }}>
              {history.length}
            </span>
            <button
              type="button" onClick={refresh} disabled={loading} title="Refresh"
              style={{
                marginLeft: 'auto', display: 'flex', alignItems: 'center',
                padding: 6, borderRadius: 6,
                border: `1px solid ${THEME_BORDER}`, background: '#fff', color: THEME_TEXT,
                cursor: loading ? 'wait' : 'pointer',
              }}
            >
              {loading
                ? <Loader2 size={12} style={{ animation: 'spin 1s linear infinite' }} />
                : <RefreshCw size={12} />}
            </button>
            <button
              type="button" onClick={() => setOpen(false)} title="Close"
              style={{
                display: 'flex', alignItems: 'center',
                padding: 6, borderRadius: 6,
                border: `1px solid ${THEME_BORDER}`, background: '#fff', color: THEME_MUTED,
                cursor: 'pointer',
              }}
            >
              <X size={12} />
            </button>
          </div>

          <div style={{ padding: 8 }}>
            {history.length === 0 && !loading && (
              <div style={{ padding: 12, textAlign: 'center', color: THEME_MUTED, fontSize: 12 }}>
                No equipment lists uploaded yet.
              </div>
            )}
            <div style={{ display: 'grid', gap: 6 }}>
              {history.map((h) => {
                const active = h.is_active
                const when = h.created_at ? new Date(h.created_at).toLocaleString() : ''
                return (
                  <div key={h.equipment_list_id} style={{
                    display: 'flex', alignItems: 'center', gap: 8,
                    padding: '8px 10px', borderRadius: 8,
                    border: `1px solid ${active ? '#bfdbfe' : THEME_BORDER}`,
                    background: active ? '#eff6ff' : '#fff',
                  }}>
                    <Boxes size={12} color={active ? '#1e40af' : THEME_MUTED} />
                    <div style={{ minWidth: 0, flex: 1 }}>
                      <div style={{
                        fontSize: 12, fontWeight: 500, color: THEME_TEXT,
                        overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap',
                      }}>
                        {h.title || h.filename}
                      </div>
                      <div style={{ fontSize: 10, color: THEME_MUTED, marginTop: 2 }}>
                        {when} · {h.total_rows} items
                      </div>
                    </div>
                    {active
                      ? <span style={{
                          display: 'inline-flex', alignItems: 'center', gap: 3,
                          padding: '2px 6px', borderRadius: 999, fontSize: 10,
                          color: '#1e40af', background: '#fff', border: '1px solid #bfdbfe',
                        }}>
                          <CheckCircle2 size={10} /> active
                        </span>
                      : <button
                          type="button" onClick={() => onActivate(h.equipment_list_id)}
                          style={{
                            padding: '4px 8px', borderRadius: 6,
                            border: `1px solid ${THEME_BORDER}`, background: '#fff', color: THEME_PRIMARY,
                            fontSize: 11, fontWeight: 600, cursor: 'pointer',
                          }}
                        >
                          Activate
                        </button>}
                    <button
                      type="button" onClick={() => onDelete(h.equipment_list_id)}
                      title="Delete"
                      style={{
                        display: 'flex', alignItems: 'center',
                        padding: 4, borderRadius: 6,
                        border: `1px solid ${THEME_BORDER}`, background: '#fff', color: '#b91c1c',
                        cursor: 'pointer',
                      }}
                    >
                      <Trash2 size={10} />
                    </button>
                  </div>
                )
              })}
            </div>
          </div>
        </div>
      )}
    </div>
  )
}

