          ].map(([Icon, label, value]) => <div key={label}><dt><Icon aria-hidden="true" />{label}</dt><dd className={value === 'Not selected' || value === 'Generated after name validation' ? 'is-muted' : ''}>{value}</dd></div>)}</dl></section>
