                  <span className={`text-[11px] px-2 py-0.5 rounded-full border font-medium ${v.check_out_time ? statusClass('APPROVED') : statusClass('ACTIVE')}`}>{v.status_label || (v.check_out_time ? 'Completed' : 'Active')}</span>
