// -- Quick Log Form (wide two-column layout)
const TASK_PLACEHOLDERS = [
  'Reviewed P&ID drawings for Train 2',
  'Attended client coordination meeting',
  'Completed instrument datasheet rev B',
  'Prepared progress report for PMC',
  'Performed quality check on deliverables',
  'Coordinated with procurement team',
]

const LOG_ACTIVITY_DAY_NAMES = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday']

function ActivityWizard({ initial, onSave, onClose, submitting, alreadyLoggedHours = 0 }) {
  const cfg      = DAILY_TRACKER_COPY
  const today    = new Date().toISOString().slice(0, 10)
  const yesterday = (() => { const d = new Date(); d.setDate(d.getDate() - 1); return d.toISOString().slice(0, 10) })()

  const [form, setForm] = useState({
    log_date:          initial?.log_date         ?? today,
    task_title:        initial?.task_title        ?? '',
    notes:             initial?.notes             ?? '',
    hours_spent:       initial?.hours_spent != null ? String(parseFloat(initial.hours_spent)) : '1',
    project_category:  initial?.project_category  ?? '',
    priority:          initial?.priority          ?? 'medium',
    status:            initial?.status            ?? 'in_progress',
    submitted_to_role: initial?.submitted_to_role ?? 'reporting_manager',
  })
  const [customHours, setCustomHours] = useState('')
  const [phIndex,     setPhIndex]     = useState(0)
  const set = (k, v) => setForm(p => ({ ...p, [k]: v }))

  useEffect(() => {
    const t = setInterval(() => setPhIndex(i => (i + 1) % TASK_PLACEHOLDERS.length), 3500)
    return () => clearInterval(t)
  }, [])

  useEffect(() => {
    const h = e => { if (e.key === 'Escape') onClose() }
    window.addEventListener('keydown', h)
    return () => window.removeEventListener('keydown', h)
  }, [onClose])

  async function handleSubmit(e) {
    e.preventDefault()
    const h = parseFloat(form.hours_spent)
    if (!form.task_title.trim() || isNaN(h) || h <= 0) return
    if (h > cfg.maxHoursWarning && !(await radaiConfirm(`${h}h seems high. Continue?`))) return
    onSave({ ...form, hours_spent: h.toFixed(2) })
  }

  const selectedH   = parseFloat(form.hours_spent) || 0
  const remaining   = Math.max(0, 8 - alreadyLoggedHours)
  const canSubmit   = form.task_title.trim().length > 0 && selectedH > 0
  const isToday     = form.log_date === today
  const isYesterday = form.log_date === yesterday
  const todayPct    = Math.min(100, Math.round((alreadyLoggedHours / 8) * 100))
  const afterPct    = Math.min(100, Math.round(((alreadyLoggedHours + selectedH) / 8) * 100))
  const dateObj     = new Date(form.log_date + 'T12:00:00')
  const dayLabel    = LOG_ACTIVITY_DAY_NAMES[dateObj.getDay()]
  const monthLabel  = dateObj.toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm px-3 py-4"
      onClick={onClose}
    >
      <div
        className="w-full max-w-2xl bg-white rounded-2xl shadow-2xl overflow-hidden flex flex-col max-h-[90vh]"
        onClick={e => e.stopPropagation()}
      >
        {/* HEADER */}
        <div className="bg-gradient-to-r from-indigo-600 via-purple-600 to-violet-700 px-6 py-4 flex-shrink-0">
          <div className="flex items-start justify-between">
            <div>
              <h2 className="text-white font-bold text-lg leading-tight">
                {initial ? 'Edit Activity' : 'Log Activity'}
              </h2>
              <p className="text-white/70 text-xs mt-0.5">
                {dayLabel}, {monthLabel}
                {isToday && !initial && remaining > 0 ? ` \u00b7 ${remaining.toFixed(1)}h remaining` : ''}
                {isToday && !initial && remaining === 0 ? ' \u00b7 Day fully logged' : ''}
              </p>
            </div>
            <button onClick={onClose} className="text-white/70 hover:text-white transition-colors mt-0.5">
              <HeroIcons.XMarkIcon className="h-5 w-5" />
            </button>
          </div>
          {isToday && !initial && (
            <div className="mt-3">
              <div className="flex justify-between text-[10px] text-white/60 mb-1">
                <span>Today&apos;s logged hours</span>
                <span>{alreadyLoggedHours.toFixed(1)}h{selectedH > 0 ? ` + ${selectedH}h this entry` : ''} / 8h</span>
              </div>
              <div className="h-1.5 bg-white/20 rounded-full overflow-hidden relative">
                <div className="absolute inset-y-0 left-0 bg-white/40 rounded-full transition-all duration-300" style={{ width: `${afterPct}%` }} />
                <div className="absolute inset-y-0 left-0 bg-white rounded-full transition-all duration-300" style={{ width: `${todayPct}%` }} />
              </div>
            </div>
          )}
        </div>

        {/* BODY */}
        <form onSubmit={handleSubmit} className="flex-1 overflow-y-auto">
          <div className="grid grid-cols-1 md:grid-cols-[3fr_2fr] divide-y md:divide-y-0 md:divide-x divide-slate-100">

            {/* LEFT COL \u2014 main content */}
            <div className="p-5 space-y-4">

              {/* Task title */}
              <div>
                <div className="flex items-center justify-between mb-1.5">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">What did you work on? *</label>
                  <span className={`text-[10px] tabular-nums ${form.task_title.length > 180 ? 'text-red-400 font-bold' : 'text-slate-300'}`}>
                    {form.task_title.length}/200
                  </span>
                </div>
                <textarea
                  autoFocus
                  rows={4}
                  maxLength={200}
                  value={form.task_title}
                  onChange={e => set('task_title', e.target.value)}
                  placeholder={TASK_PLACEHOLDERS[phIndex]}
                  className="w-full text-sm text-slate-800 bg-slate-50 border border-slate-200 rounded-xl px-3.5 py-2.5 resize-none focus:outline-none focus:ring-2 focus:ring-indigo-400 focus:bg-white transition-all placeholder:text-slate-300 leading-relaxed"
                />
              </div>

              {/* Notes \u2014 always visible */}
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide block mb-1.5">
                  Notes / Context
                </label>
                <textarea
                  rows={3}
                  value={form.notes}
                  onChange={e => set('notes', e.target.value)}
                  placeholder="Blockers, decisions, links, next steps..."
                  className="w-full text-xs text-slate-600 bg-slate-50 border border-slate-200 rounded-xl px-3.5 py-2.5 resize-none focus:outline-none focus:ring-2 focus:ring-indigo-300 focus:bg-white transition-all placeholder:text-slate-300 leading-relaxed"
                />
              </div>

              {/* Send for approval to */}
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide block mb-2">
                  Send for Approval to
                </label>
                <div className="grid grid-cols-2 gap-2">
                  {DAILY_TRACKER_SUBMIT_TO_OPTIONS.map(opt => {
                    const active = form.submitted_to_role === opt.id
                    return (
                      <button
                        key={opt.id}
                        type="button"
                        onClick={() => set('submitted_to_role', opt.id)}
                        className={`flex flex-col items-start gap-1 px-3 py-2.5 rounded-xl border text-left transition-all ${
                          active ? opt.activeTailwind + ' shadow-md ring-2 ring-offset-1 ring-current/20' : opt.chipTailwind + ' hover:shadow-sm'
                        }`}
                      >
                        <div className="flex items-center gap-1.5">
                          {active
                            ? <HeroIcons.CheckCircleIcon className="h-3.5 w-3.5 flex-shrink-0" />
                            : <HeroIcons.UserCircleIcon className="h-3.5 w-3.5 flex-shrink-0 opacity-60" />
                          }
                          <span className="text-xs font-bold leading-tight">{opt.label}</span>
                        </div>
                        <span className={`text-[10px] leading-snug ${active ? 'text-white/80' : 'opacity-60'}`}>
                          {opt.description}
                        </span>
                      </button>
                    )
                  })}
                </div>
              </div>

              {/* Date */}
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide block mb-1.5">Date</label>
                <div className="flex items-center gap-2">
                  <button type="button" onClick={() => set('log_date', today)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all ${
                      isToday
                        ? 'bg-indigo-600 text-white border-indigo-600 shadow-sm'
                        : 'bg-white text-slate-500 border-slate-200 hover:border-indigo-300 hover:text-indigo-600'
                    }`}>Today</button>
                  <button type="button" onClick={() => set('log_date', yesterday)}
                    className={`px-3 py-1.5 rounded-lg text-xs font-semibold border transition-all ${
                      isYesterday
                        ? 'bg-indigo-600 text-white border-indigo-600 shadow-sm'
                        : 'bg-white text-slate-500 border-slate-200 hover:border-indigo-300 hover:text-indigo-600'
                    }`}>Yesterday</button>
                  <input
                    type="date"
                    value={form.log_date}
                    max={today}
                    onChange={e => set('log_date', e.target.value)}
                    className={`border rounded-lg px-2.5 py-1.5 text-xs focus:outline-none focus:ring-2 focus:ring-indigo-300 transition-all ${
                      !isToday && !isYesterday
                        ? 'border-indigo-300 bg-indigo-50 text-indigo-700 font-semibold'
                        : 'border-slate-200 bg-white text-slate-500'
                    }`}
                  />
                </div>
              </div>
            </div>

            {/* RIGHT COL \u2014 quick selectors */}
            <div className="p-5 space-y-5">

              {/* Hours */}
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide">Hours Spent *</label>
                  {selectedH > 0 && (
                    <span className="text-[10px] text-indigo-600 font-semibold bg-indigo-50 px-2 py-0.5 rounded-full">
                      {Math.round((selectedH / 8) * 100)}% of workday
                    </span>
                  )}
                </div>
                <div className="grid grid-cols-4 gap-1.5 mb-2">
                  {cfg.quickHours.map(h => (
                    <button
                      key={h}
                      type="button"
                      onClick={() => { set('hours_spent', String(h)); setCustomHours('') }}
                      className={`py-2 rounded-xl text-xs font-bold border transition-all ${
                        selectedH === h && !customHours
                          ? 'bg-indigo-600 text-white border-indigo-600 shadow-md scale-105'
                          : 'bg-slate-50 text-slate-600 border-slate-200 hover:border-indigo-300 hover:bg-indigo-50 hover:text-indigo-600'
                      }`}
                    >{h}h</button>
                  ))}
                </div>
                <div className="flex items-center gap-2">
                  <input
                    type="number"
                    min="0.25" max="24" step="0.25"
                    value={customHours}
                    onChange={e => { setCustomHours(e.target.value); if (e.target.value) set('hours_spent', e.target.value) }}
                    placeholder="Custom hours (e.g. 2.5)"
                    className="flex-1 border border-slate-200 rounded-lg px-2.5 py-1.5 text-xs text-slate-700 bg-slate-50 focus:outline-none focus:ring-2 focus:ring-indigo-300 focus:bg-white transition-all"
                  />
                </div>
              </div>

              <div className="h-px bg-slate-100" />

              {/* Priority */}
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide block mb-2">Priority</label>
                <div className="grid grid-cols-2 gap-1.5">
                  {DAILY_TRACKER_PRIORITIES.map(p => (
                    <button key={p.id} type="button" onClick={() => set('priority', p.id)}
                      className={`py-1.5 rounded-lg text-xs font-semibold border text-center transition-all ${
                        form.priority === p.id ? p.tailwind + ' shadow-sm' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'
                      }`}>
                      {p.icon} {p.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Status */}
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide block mb-2">Status</label>
                <div className="grid grid-cols-2 gap-1.5">
                  {DAILY_TRACKER_STATUSES.map(s => (
                    <button key={s.id} type="button" onClick={() => set('status', s.id)}
                      className={`py-1.5 rounded-lg text-xs font-semibold border text-center transition-all ${
                        form.status === s.id ? s.tailwind + ' shadow-sm' : 'bg-white text-slate-400 border-slate-100 hover:border-slate-300'
                      }`}>
                      {s.icon} {s.label}
                    </button>
                  ))}
                </div>
              </div>

              {/* Category */}
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-wide block mb-2">Category</label>
                <div className="flex flex-wrap gap-1.5">
                  {DAILY_TRACKER_PROJECT_CATEGORIES.map(c => (
                    <button
                      key={c}
                      type="button"
                      onClick={() => set('project_category', form.project_category === c ? '' : c)}
                      className={`px-2 py-1 rounded-full text-[11px] font-medium border transition-all ${
                        form.project_category === c
                          ? 'bg-violet-600 text-white border-violet-600 shadow-sm'
                          : 'bg-white text-slate-500 border-slate-200 hover:border-violet-300 hover:text-violet-600'
                      }`}
                    >{c}</button>
                  ))}
                </div>
              </div>
            </div>
          </div>

          {/* FOOTER */}
          <div className="px-5 py-3.5 bg-slate-50 border-t border-slate-100 flex items-center gap-3 flex-shrink-0">
            <div className="flex-1 flex items-center gap-1.5 flex-wrap min-w-0">
              {selectedH > 0 && (
                <span className="inline-flex items-center gap-1 bg-indigo-100 text-indigo-700 rounded-full px-2.5 py-0.5 text-[11px] font-semibold">
                  <HeroIcons.ClockIcon className="h-3 w-3" />{selectedH}h
                </span>
              )}
              {form.priority && (() => {
                const p = DAILY_TRACKER_PRIORITIES.find(x => x.id === form.priority)
                return p ? (
                  <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-[11px] font-semibold border ${p.tailwind}`}>{p.icon} {p.label}</span>
                ) : null
              })()}
              {form.status && (() => {
                const s = DAILY_TRACKER_STATUSES.find(x => x.id === form.status)
                return s ? (
                  <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-[11px] font-semibold border ${s.tailwind}`}>{s.icon} {s.label}</span>
                ) : null
              })()}
              {form.project_category && (
                <span className="inline-flex items-center gap-1 bg-violet-100 text-violet-700 rounded-full px-2.5 py-0.5 text-[11px] font-semibold">
                  <HeroIcons.FolderIcon className="h-3 w-3" />{form.project_category}
                </span>
              )}
              {form.submitted_to_role && (() => {
                const opt = DAILY_TRACKER_SUBMIT_TO_OPTIONS.find(o => o.id === form.submitted_to_role)
                return opt ? (
                  <span className={`inline-flex items-center gap-1 rounded-full px-2.5 py-0.5 text-[11px] font-semibold border ${opt.chipTailwind}`}>
                    <HeroIcons.PaperAirplaneIcon className="h-3 w-3" />{opt.label}
                  </span>
                ) : null
              })()}
            </div>
            <button
              type="submit"
              disabled={!canSubmit || submitting}
              className="flex-shrink-0 px-6 py-2.5 rounded-xl font-bold text-sm text-white bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700 shadow-md transition-all disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {submitting ? 'Saving...' : initial ? 'Update Activity' : `Log ${selectedH > 0 ? selectedH + 'h' : 'Activity'}`}
            </button>
          </div>
        </form>
      </div>
    </div>
  )
}
// -- Reject note mini-modal ----------------------------------------------------
function RejectModal({ onConfirm, onClose }) {
  const cfg = DAILY_TRACKER_COPY
  const [note, setNote] = useState('')
  return (
    <div className="fixed inset-0 z-[60] flex items-center justify-center bg-black/50 backdrop-blur-sm"
      onClick={onClose}>
      <div className="bg-white rounded-2xl shadow-2xl p-6 w-full max-w-sm mx-4" onClick={e => e.stopPropagation()}>
        <div className="flex items-center gap-2 mb-3">
          <div className="h-9 w-9 rounded-full bg-red-100 flex items-center justify-center">
            <HeroIcons.XCircleIcon className="h-5 w-5 text-red-600" />
          </div>
          <h3 className="font-semibold text-slate-800">Reject Activity</h3>
        </div>
        <textarea
          autoFocus
          rows={3}
          value={note}
          onChange={e => setNote(e.target.value)}
          placeholder={cfg.rejectNotePlaceholder}
          className="w-full border border-slate-200 rounded-xl px-3 py-2.5 text-sm resize-none focus:outline-none focus:ring-2 focus:ring-red-300 bg-slate-50 mb-4"
        />
        <div className="flex gap-2">
          <button onClick={onClose}
            className="flex-1 py-2 border border-slate-200 rounded-xl text-sm text-slate-600 hover:bg-slate-50">
            Cancel
          </button>
          <button
            onClick={() => note.trim() && onConfirm(note)}
            disabled={!note.trim()}
            className="flex-1 py-2 bg-red-500 hover:bg-red-600 text-white rounded-xl text-sm font-semibold disabled:opacity-40">
            Reject
          </button>
        </div>
      </div>
    </div>
  )
}

// -- Main Daily Tracker tab ----------------------------------------------------
function DailyTrackerTab({ currentUser }) {
  const cfg     = DAILY_TRACKER_COPY
  const isStaff = currentUser?.is_staff || currentUser?.is_superuser || false

  const [logs,            setLogs]            = useState([])
  const [summary,         setSummary]         = useState([])
  const [loading,         setLoading]         = useState(true)
  const [submitting,      setSubmitting]      = useState(false)
  const [exportLoading,   setExportLoading]   = useState(false)
  const [selectedDate,    setSelectedDate]    = useState(new Date().toISOString().slice(0, 10))
  const [wizardOpen,      setWizardOpen]      = useState(false)
  const [editingLog,      setEditingLog]      = useState(null)
  const [showTeam,        setShowTeam]        = useState(false)
  const [teamLogs,        setTeamLogs]        = useState([])
  const [teamLoading,     setTeamLoading]     = useState(false)
  const [approvalQueue,   setApprovalQueue]   = useState([])
  const [queueLoading,    setQueueLoading]    = useState(false)
  const [rejectTarget,    setRejectTarget]    = useState(null)  // log id pending rejection
  const [toast,           setToast]           = useState(null)

  function showToast(msg, type = 'success') {
    setToast({ msg, type })
    setTimeout(() => setToast(null), 3500)
  }

  // -- Data loading ----------------------------------------------------------
  const loadLogs = useCallback(async () => {
    setLoading(true)
    try {
      const from14w = (() => { const d = new Date(); d.setDate(d.getDate() - 97); return d.toISOString().slice(0,10) })()
      const [logsRes, sumRes] = await Promise.all([
        payrollService.getDailyLogs({ date: selectedDate }),
        payrollService.getDailyLogSummary({ from: from14w }),
      ])
      setLogs(Array.isArray(logsRes) ? logsRes : logsRes.results ?? [])
      setSummary(Array.isArray(sumRes) ? sumRes : [])
    } catch {
      showToast('Failed to load logs.', 'error')
    } finally {
      setLoading(false)
    }
  }, [selectedDate])

  useEffect(() => { loadLogs() }, [loadLogs])

  const loadApprovalQueue = useCallback(async () => {
    if (!isStaff) return
    setQueueLoading(true)
    try {
      const res = await payrollService.getDailyApprovalQueue()
      setApprovalQueue(Array.isArray(res) ? res : res.results ?? [])
    } catch {
      setApprovalQueue([])
    } finally {
      setQueueLoading(false)
    }
  }, [isStaff])

  useEffect(() => { loadApprovalQueue() }, [loadApprovalQueue])

  const loadTeam = useCallback(async () => {
    if (!isStaff) return
    setTeamLoading(true)
    try {
      const res = await payrollService.getTeamDailyLogs({ date: selectedDate })
      setTeamLogs(Array.isArray(res) ? res : res.results ?? [])
    } catch { setTeamLogs([]) }
    finally { setTeamLoading(false) }
  }, [isStaff, selectedDate])

  useEffect(() => { if (showTeam) loadTeam() }, [showTeam, loadTeam])

  // -- Derived KPIs ----------------------------------------------------------
  const todayLogs    = logs
  const hoursToday   = todayLogs.reduce((a, l) => a + parseFloat(l.hours_spent || 0), 0)
  const tasksDone    = todayLogs.filter(l => l.status === 'done').length
  const blocked      = todayLogs.filter(l => l.status === 'blocked').length
  const pendingCount = todayLogs.filter(l => l.approval_status === 'pending').length

  const weekStart = (() => {
    const d = new Date(); const dow = (d.getDay() + 6) % 7
    d.setDate(d.getDate() - dow); return d.toISOString().slice(0, 10)
  })()
  const hoursWeek = summary.filter(r => r.date >= weekStart)
    .reduce((a, r) => a + (r.total_hours || 0), 0)

  const weekDays = ['Mon','Tue','Wed','Thu','Fri','Sat','Sun']
  const weekChartData = weekDays.map((day, i) => {
    const d = new Date(weekStart); d.setDate(d.getDate() + i)
    const iso = d.toISOString().slice(0, 10)
    const row = summary.find(r => r.date === iso)
    return { day, hours: row ? parseFloat(row.total_hours.toFixed(1)) : 0 }
  })

  // -- CRUD handlers ---------------------------------------------------------
  async function handleSave(data) {
    setSubmitting(true)
    try {
      if (editingLog) {
        const updated = await payrollService.updateDailyLog(editingLog.id, data)
        setLogs(p => p.map(l => l.id === updated.id ? updated : l))
        showToast('Activity updated.')
      } else {
        const created = await payrollService.createDailyLog(data)
        if (data.log_date === selectedDate) setLogs(p => [created, ...p])
        showToast('Activity submitted \u2014 pending manager approval.')
      }
      setWizardOpen(false)
      setEditingLog(null)
      const from14w = (() => { const d = new Date(); d.setDate(d.getDate() - 97); return d.toISOString().slice(0,10) })()
      const sumRes = await payrollService.getDailyLogSummary({ from: from14w })
      setSummary(Array.isArray(sumRes) ? sumRes : [])
    } catch {
      showToast('Save failed.', 'error')
    } finally {
      setSubmitting(false)
    }
  }

  async function handleDelete(id) {
    if (!(await radaiConfirm('Delete this activity log?'))) return
    try {
      await payrollService.deleteDailyLog(id)
      setLogs(p => p.filter(l => l.id !== id))
      showToast('Activity deleted.')
    } catch { showToast('Delete failed.', 'error') }
  }

  async function handleApprove(id) {
    try {
      const updated = await payrollService.approveDailyLog(id)
      setLogs(p => p.map(l => l.id === id ? updated : l))
      setApprovalQueue(p => p.filter(l => l.id !== id))
      showToast(cfg.approveSuccess)
    } catch { showToast('Approval failed.', 'error') }
  }

  async function handleReject(id, note) {
    try {
      const updated = await payrollService.rejectDailyLog(id, note)
      setLogs(p => p.map(l => l.id === id ? updated : l))
      setApprovalQueue(p => p.filter(l => l.id !== id))
      setRejectTarget(null)
      showToast(cfg.rejectSuccess)
    } catch { showToast('Rejection failed.', 'error') }
  }

  async function handleExport() {
    setExportLoading(true)
    try {
      const res = await payrollService.exportDailyLogsToS3()
      showToast(`${cfg.exportSuccess} (${res.count} records)`)
    } catch { showToast(cfg.exportError, 'error') }
    finally { setExportLoading(false) }
  }

  // -- Render ----------------------------------------------------------------
  if (loading) return <EmployeeTabLoading message="Loading your daily activities…" />

  return (
    <div className="space-y-5">

      {/* Toast */}
      {toast && (
        <div className={`fixed top-4 right-4 z-[60] px-4 py-3 rounded-xl shadow-lg text-sm font-medium transition-all ${
          toast.type === 'error'
            ? 'bg-red-50 text-red-700 border border-red-200'
            : 'bg-emerald-50 text-emerald-700 border border-emerald-200'
        }`}>
          {toast.msg}
        </div>
      )}

      {/* Header */}
      <div className="flex flex-wrap items-center justify-between gap-3">
        <div className="flex items-center gap-3">
          <HeroIcons.ClipboardDocumentListIcon className="h-5 w-5 text-indigo-600" />
          <h2 className="text-lg font-semibold text-slate-800">{cfg.tabLabel}</h2>
          <input
            type="date"
            value={selectedDate}
            max={new Date().toISOString().slice(0,10)}
            onChange={e => setSelectedDate(e.target.value)}
            className="border border-slate-200 rounded-lg px-3 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-indigo-400"
          />
        </div>
        <div className="flex items-center gap-2">
          {isStaff && (
            <button onClick={() => setShowTeam(p => !p)}
              className={`px-4 py-2 rounded-lg text-sm font-medium border transition-colors ${
                showTeam ? 'bg-indigo-50 text-indigo-700 border-indigo-200' : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
              }`}>
              <HeroIcons.UserGroupIcon className="h-4 w-4 inline mr-1" />Team
            </button>
          )}
          <button onClick={handleExport} disabled={exportLoading}
            className="px-4 py-2 rounded-lg text-sm font-medium bg-white text-slate-600 border border-slate-200 hover:bg-slate-50 disabled:opacity-50">
            <HeroIcons.CloudArrowUpIcon className="h-4 w-4 inline mr-1" />
            {exportLoading ? 'Exporting\u2026' : cfg.exportButton}
          </button>
          <button onClick={() => { setEditingLog(null); setWizardOpen(true) }}
            className="px-4 py-2 rounded-lg text-sm font-semibold bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700 text-white shadow-sm transition-all">
            <HeroIcons.PlusIcon className="h-4 w-4 inline mr-1" />{cfg.addButton}
          </button>
        </div>
      </div>

      {/* KPI tiles */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
        {[
          { label: 'Hours Today',     value: hoursToday.toFixed(1), sub: `${pendingCount} pending approval`,  icon: 'ClockIcon',            color: 'text-indigo-600',  bg: 'bg-indigo-50'  },
          { label: 'Tasks Done',      value: tasksDone,             sub: 'approved + non-approved',           icon: 'CheckCircleIcon',      color: 'text-emerald-600', bg: 'bg-emerald-50' },
          { label: 'Blocked',         value: blocked,               sub: 'need attention',                    icon: 'ExclamationCircleIcon', color: 'text-red-500',    bg: 'bg-red-50'     },
          { label: 'Hours This Week', value: hoursWeek.toFixed(1),  sub: 'Mon\u2013today',                         icon: 'CalendarDaysIcon',     color: 'text-purple-600', bg: 'bg-purple-50'  },
        ].map(tile => {
          const Icon = HeroIcons[tile.icon]
          return (
            <ProfileMetricCard key={tile.label} icon={Icon && <Icon />} label={tile.label} value={tile.value} sub={tile.sub}
              tone={({ 'bg-indigo-50': 'blue', 'bg-emerald-50': 'green', 'bg-red-50': 'rose', 'bg-purple-50': 'purple' })[tile.bg]} />
          )
        })}
      </div>

      {/* Charts */}
      <div className="grid grid-cols-1 xl:grid-cols-2 gap-5">
        <div className="bg-white rounded-2xl border border-slate-100 p-5 shadow-sm overflow-x-auto">
          <ActivityHeatmap summary={summary} />
        </div>
        <div className="bg-white rounded-2xl border border-slate-100 p-5 shadow-sm">
          <p className="text-xs font-medium text-slate-500 mb-3">{cfg.weeklyChartTitle}</p>
          <ResponsiveContainer width="100%" height={140}>
            <BarChart data={weekChartData} margin={{ top: 0, right: 10, left: -20, bottom: 0 }}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="day" tick={{ fontSize: 11, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fontSize: 11, fill: '#94a3b8' }} axisLine={false} tickLine={false} />
              <Tooltip contentStyle={{ fontSize: 12, borderRadius: 8, border: '1px solid #e2e8f0' }}
                formatter={v => [`${v} hrs`, 'Hours']} />
              <Bar dataKey="hours" fill="#6366f1" radius={[4, 4, 0, 0]} />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Approval Queue \u2014 managers/staff only */}
      {isStaff && (
        <div className="bg-white rounded-2xl border border-amber-100 shadow-sm overflow-hidden">
          <div className="px-5 py-4 border-b border-amber-50 flex items-center justify-between bg-amber-50/50">
            <div className="flex items-center gap-2">
              <HeroIcons.ClipboardDocumentCheckIcon className="h-4 w-4 text-amber-600" />
              <p className="font-semibold text-slate-700 text-sm">{cfg.approvalQueueTitle}</p>
              {approvalQueue.length > 0 && (
                <span className="px-2 py-0.5 bg-amber-500 text-white rounded-full text-[11px] font-bold">
                  {approvalQueue.length}
                </span>
              )}
            </div>
            <button onClick={loadApprovalQueue}
              className="text-slate-400 hover:text-indigo-600 transition-colors">
              <HeroIcons.ArrowPathIcon className="h-4 w-4" />
            </button>
          </div>

          {queueLoading ? (
            <div className="p-6 text-center text-slate-400 text-sm">Loading{ELLIPSIS_DISPLAY}</div>
          ) : approvalQueue.length === 0 ? (
            <div className="p-6 text-center text-slate-400 text-sm">
              <HeroIcons.CheckBadgeIcon className="h-8 w-8 mx-auto mb-2 text-emerald-300" />
              {cfg.approvalQueueEmpty}
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead>
                  <tr className="bg-amber-50/40 text-[11px] text-slate-500 uppercase tracking-wide">
                    <th className="px-4 py-2 text-left">Employee</th>
                    <th className="px-4 py-2 text-left">Task</th>
                    <th className="px-4 py-2 text-center">Date</th>
                    <th className="px-4 py-2 text-center">Hrs</th>
                    <th className="px-4 py-2 text-left">Category</th>
                    <th className="px-4 py-2 text-center">Sent to</th>
                    <th className="px-4 py-2 text-center">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-amber-50">
                  {approvalQueue.slice(0, cfg.teamPageSize).map(log => {
                    const routeOpt = DAILY_TRACKER_SUBMIT_TO_OPTIONS.find(o => o.id === log.submitted_to_role)
                    return (
                    <tr key={log.id} className="hover:bg-amber-50/30 transition-colors">
                      <td className="px-4 py-3 font-medium text-slate-700 whitespace-nowrap">{log.user_full_name}</td>
                      <td className="px-4 py-3 text-slate-800 max-w-[200px] truncate">{log.task_title}</td>
                      <td className="px-4 py-3 text-center text-slate-500 text-xs whitespace-nowrap">{log.log_date}</td>
                      <td className="px-4 py-3 text-center font-mono font-semibold text-slate-700">
                        {parseFloat(log.hours_spent).toFixed(1)}
                      </td>
                      <td className="px-4 py-3 text-slate-500 text-xs">{log.project_category || 'u2014'}</td>
                      <td className="px-4 py-3 text-center">
                        {routeOpt ? (
                          <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-[10px] font-semibold border ${routeOpt.chipTailwind}`}>
                            {routeOpt.label}
                          </span>
                        ) : (
                          <span className="text-slate-300 text-xs">&#x2014;</span>
                        )}
                      </td>
                      <td className="px-4 py-3">
                        <div className="flex items-center justify-center gap-2">
                          <button
                            onClick={() => handleApprove(log.id)}
                            className="flex items-center gap-1 px-3 py-1.5 bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg text-xs font-semibold hover:bg-emerald-100 transition-colors"
                          >
                            <HeroIcons.CheckIcon className="h-3 w-3" /> {cfg.approveButton}
                          </button>
                          <button
                            onClick={() => setRejectTarget(log.id)}
                            className="flex items-center gap-1 px-3 py-1.5 bg-red-50 text-red-600 border border-red-200 rounded-lg text-xs font-semibold hover:bg-red-100 transition-colors"
                          >
                            <HeroIcons.XMarkIcon className="h-3 w-3" /> {cfg.rejectButton}
                          </button>
                        </div>
                      </td>
                    </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Personal log list */}
      {!showTeam && (
        <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
          <div className="px-5 py-4 border-b border-slate-50 flex items-center justify-between">
            <p className="font-semibold text-slate-700 text-sm">Activity Log {EMPTY_DISPLAY} {selectedDate}</p>
            <span className="text-xs text-slate-400">{todayLogs.length} {todayLogs.length === 1 ? 'entry' : 'entries'}</span>
          </div>

          {loading ? (
            <div className="p-8 text-center text-slate-400 text-sm">Loading{ELLIPSIS_DISPLAY}</div>
          ) : todayLogs.length === 0 ? (
            <div className="p-8 text-center space-y-2">
              <HeroIcons.ClipboardDocumentListIcon className="h-10 w-10 mx-auto text-slate-200" />
              <p className="text-slate-400 text-sm">{cfg.emptyLogs}</p>
            </div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead>
                  <tr className="bg-slate-50 text-[11px] text-slate-500 uppercase tracking-wide">
                    <th className="px-4 py-2 text-left">Task</th>
                    <th className="px-4 py-2 text-left">Category</th>
                    <th className="px-4 py-2 text-center">Hrs</th>
                    <th className="px-4 py-2 text-center">Priority</th>
                    <th className="px-4 py-2 text-center">Status</th>
                    <th className="px-4 py-2 text-center">Approval</th>
                    <th className="px-4 py-2 text-center">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {todayLogs.map(log => {
                    const pc = priorityConfig(log.priority)
                    const sc = statusConfig(log.status)
                    const ac = approvalConfig(log.approval_status)
                    return (
                      <tr key={log.id} className={`transition-colors hover:brightness-95 ${ac.rowBg}`}>
                        <td className="px-4 py-3 font-medium text-slate-800 max-w-[180px] truncate">{log.task_title}</td>
                        <td className="px-4 py-3 text-slate-500 text-xs">{log.project_category || EMPTY_DISPLAY}</td>
                        <td className="px-4 py-3 text-center font-mono font-semibold text-slate-700">
                          {parseFloat(log.hours_spent).toFixed(1)}
                        </td>
                        <td className="px-4 py-3 text-center">
                          <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs border font-medium ${pc.tailwind}`}>
                            {pc.icon} {pc.label}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-center">
                          <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs border font-medium ${sc.tailwind}`}>
                            {sc.icon} {sc.label}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-center">
                          <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs border font-medium ${ac.tailwind}`}>
                            {ac.icon} {ac.label}
                          </span>
                          {log.approval_note && (
                            <p className="text-[10px] text-slate-400 mt-0.5 max-w-[120px] truncate">{log.approval_note}</p>
                          )}
                        </td>
                        <td className="px-4 py-3 text-center">
                          <div className="flex items-center justify-center gap-2">
                            {/* Only allow editing pending/rejected logs */}
                            {log.approval_status !== 'approved' && (
                              <button onClick={() => { setEditingLog(log); setWizardOpen(true) }}
                                className="text-slate-400 hover:text-indigo-600 transition-colors" title="Edit">
                                <HeroIcons.PencilSquareIcon className="h-4 w-4" />
                              </button>
                            )}
                            {/* Manager approve/reject inline for logs they're viewing */}
                            {isStaff && log.approval_status === 'pending' && (
                              <>
                                <button onClick={() => handleApprove(log.id)}
                                  className="text-emerald-400 hover:text-emerald-600 transition-colors" title="Approve">
                                  <HeroIcons.CheckBadgeIcon className="h-4 w-4" />
                                </button>
                                <button onClick={() => setRejectTarget(log.id)}
                                  className="text-red-400 hover:text-red-600 transition-colors" title="Reject">
                                  <HeroIcons.XCircleIcon className="h-4 w-4" />
                                </button>
                              </>
                            )}
                            {log.approval_status !== 'approved' && (
                              <button onClick={() => handleDelete(log.id)}
                                className="text-slate-400 hover:text-red-500 transition-colors" title="Delete">
                                <HeroIcons.TrashIcon className="h-4 w-4" />
                              </button>
                            )}
                          </div>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Team view */}
      {showTeam && isStaff && (
        <div className="bg-white rounded-2xl border border-slate-100 shadow-sm overflow-hidden">
          <div className="px-5 py-4 border-b border-slate-50">
            <p className="font-semibold text-slate-700 text-sm">{cfg.teamViewTitle} {EMPTY_DISPLAY} {selectedDate}</p>
          </div>
          {teamLoading ? (
            <div className="p-8 text-center text-slate-400 text-sm">Loading{ELLIPSIS_DISPLAY}</div>
          ) : teamLogs.length === 0 ? (
            <div className="p-8 text-center text-slate-400 text-sm">No team logs for this date.</div>
          ) : (
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead>
                  <tr className="bg-slate-50 text-[11px] text-slate-500 uppercase tracking-wide">
                    <th className="px-4 py-2 text-left">Employee</th>
                    <th className="px-4 py-2 text-left">Task</th>
                    <th className="px-4 py-2 text-left">Category</th>
                    <th className="px-4 py-2 text-center">Hrs</th>
                    <th className="px-4 py-2 text-center">Priority</th>
                    <th className="px-4 py-2 text-center">Status</th>
                    <th className="px-4 py-2 text-center">Approval</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-50">
                  {teamLogs.slice(0, cfg.teamPageSize).map(log => {
                    const pc = priorityConfig(log.priority)
                    const sc = statusConfig(log.status)
                    const ac = approvalConfig(log.approval_status)
                    return (
                      <tr key={log.id} className={`hover:brightness-95 transition-colors ${ac.rowBg}`}>
                        <td className="px-4 py-3 font-medium text-slate-700">{log.user_full_name}</td>
                        <td className="px-4 py-3 text-slate-800 max-w-[180px] truncate">{log.task_title}</td>
                        <td className="px-4 py-3 text-slate-500 text-xs">{log.project_category || EMPTY_DISPLAY}</td>
                        <td className="px-4 py-3 text-center font-mono font-semibold text-slate-700">
                          {parseFloat(log.hours_spent).toFixed(1)}
                        </td>
                        <td className="px-4 py-3 text-center">
                          <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs border font-medium ${pc.tailwind}`}>
                            {pc.icon} {pc.label}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-center">
                          <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs border font-medium ${sc.tailwind}`}>
                            {sc.icon} {sc.label}
                          </span>
                        </td>
                        <td className="px-4 py-3 text-center">
                          <div className="flex items-center justify-center gap-1.5">
                            <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs border font-medium ${ac.tailwind}`}>
                              {ac.icon} {ac.label}
                            </span>
                            {log.approval_status === 'pending' && (
                              <>
                                <button onClick={() => handleApprove(log.id)}
                                  className="text-emerald-400 hover:text-emerald-600" title="Approve">
                                  <HeroIcons.CheckBadgeIcon className="h-4 w-4" />
                                </button>
                                <button onClick={() => setRejectTarget(log.id)}
                                  className="text-red-400 hover:text-red-600" title="Reject">
                                  <HeroIcons.XCircleIcon className="h-4 w-4" />
                                </button>
                              </>
                            )}
                          </div>
                        </td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          )}
        </div>
      )}

      {/* Wizard form */}
      {wizardOpen && (
        <ActivityWizard
          initial={editingLog}
          onSave={handleSave}
          onClose={() => { setWizardOpen(false); setEditingLog(null) }}
          submitting={submitting}
          alreadyLoggedHours={hoursToday}
        />
      )}

      {/* Reject modal */}
      {rejectTarget && (
        <RejectModal
          onConfirm={note => handleReject(rejectTarget, note)}
          onClose={() => setRejectTarget(null)}
        />
      )}
    </div>
  )
}

// -----------------------------------------------------------------------------
// MAIN COMPONENT
// -----------------------------------------------------------------------------

export default function EmployeeSelfService() {
  const dispatch = useDispatch()
  const { user: authUser } = useSelector((s) => s.auth) || {}
  const { currentUser }    = useSelector((s) => s.rbac) || {}
  const authProfile = currentUser || authUser

  const [profileParams] = useSearchParams()
  const [activeTab, setActiveTabState] = useState(() => {
    const requestedTab = new URLSearchParams(window.location.search).get('tab')
    return requestedTab === 'timesheet' ? 'attendance' : requestedTab === 'overtime' ? 'requests' : ESS_TABS.some((tab) => tab.id === requestedTab) ? requestedTab : 'overview'
  })
  const setActiveTab = tab => setActiveTabState(tab === 'timesheet' ? 'attendance' : tab)
  useEffect(() => {
    const tab = profileParams.get('tab')
    if (tab === 'timesheet') setActiveTab('attendance')
    else if (tab === 'overtime') setActiveTab('requests')
    else if (ESS_TABS.some(item => item.id === tab)) setActiveTab(tab)
  }, [profileParams])
  const [salaryVisible, setSalaryVisible] = useState(false)
  const [uploadingPhoto, setUploadingPhoto] = useState(false)
  const [photoUploadState, setPhotoUploadState] = useState(null)
  const { photo: authenticatedPhotoUrl } = useCurrentProfilePhoto()

  // -- Data state --------------------------------------------------------------
  const [profile,      setProfile]      = useState(null)
  const [monthlyTs,    setMonthlyTs]    = useState(null)
  const [todayTs,      setTodayTs]      = useState(null)
  const [liveAttendance, setLiveAttendance] = useState(null)
  const [userHistory,  setUserHistory]  = useState(null)
  const [leaveRecord,  setLeaveRecord]  = useState(null)
  const [leaveAvailable, setLeaveAvailable] = useState(false)
  const [profileDocuments, setProfileDocuments] = useState(null)
  const [organizationEmployees, setOrganizationEmployees] = useState(undefined)
  const [downloadingOverview, setDownloadingOverview] = useState(false)
  const [overviewError, setOverviewError] = useState('')
  const [leaveTypes,   setLeaveTypes]   = useState([])
  const [leaveRequests,setLeaveRequests]= useState([])
  const [salaryInfo,   setSalaryInfo]   = useState(null)
  const [slips,        setSlips]        = useState([])
  const [notifications,setNotifications]= useState([])

  // -- Loading / error state ---------------------------------------------------
  const [loadingProfile,  setLoadingProfile]  = useState(true)
  const [loadingTs,       setLoadingTs]       = useState(true)
  const [loadingLeave,    setLoadingLeave]    = useState(true)
  const [leaveRevision, setLeaveRevision] = useState(0)
  useEffect(() => {
    const refresh = () => setLeaveRevision(value => value + 1)
    window.addEventListener('leave-approval-updated', refresh)
    window.addEventListener('focus', refresh)
    return () => {
      window.removeEventListener('leave-approval-updated', refresh)
      window.removeEventListener('focus', refresh)
    }
  }, [])
  const [loadingPayroll,  setLoadingPayroll]  = useState(true)
  const [loadingNotifications, setLoadingNotifications] = useState(true)

  // -- Leave form state --------------------------------------------------------
  const [submitting,    setSubmitting]    = useState(false)
  const [submitResult,  setSubmitResult]  = useState(null)

  // -- Load profile ------------------------------------------------------------
  useEffect(() => {
    setLoadingProfile(true)
    rbacService.getCurrentUser()
      .then(r => setProfile(r?.data || r))
      .catch(() => setProfile(authProfile))
      .finally(() => setLoadingProfile(false))
  }, [])

  const handleProfilePhotoUpload = useCallback(async (file) => {
    const supportedTypes = ['image/jpeg', 'image/png', 'image/webp']
    if (!supportedTypes.includes(file.type)) {
      setPhotoUploadState({ type: 'error', message: 'Choose a JPEG, PNG or WebP image.' })
      return
    }
    if (file.size > 5 * 1024 * 1024) {
      setPhotoUploadState({ type: 'error', message: 'The image must be 5 MB or smaller.' })
      return
    }

    setUploadingPhoto(true)
    setPhotoUploadState(null)
    const formData = new FormData()
    formData.append('photo', file)

    try {
      const response = await apiClient.post('/users/employees/my-profile-photo/', formData, {
        headers: { 'Content-Type': 'multipart/form-data' },
      })
      const photoUrl = response?.data?.photo_url
      if (!photoUrl) throw new Error('The server did not return the uploaded photo.')

      setProfile((current) => ({ ...current, profile_photo: photoUrl }))
      dispatch(updateUser({ profile_photo: photoUrl }))
      window.dispatchEvent(new Event('radai:profile-photo-changed'))
      setPhotoUploadState({ type: 'success', message: 'Profile picture updated successfully.' })
    } catch (error) {
      const message = error?.response?.data?.error
        || error?.response?.data?.detail
        || error?.message
        || 'The profile picture could not be uploaded.'
      setPhotoUploadState({ type: 'error', message })
    } finally {
      setUploadingPhoto(false)
    }
  }, [dispatch])

  useEffect(() => {
    let active = true
    apiClient.get('/rbac/users/reporting-managers/')
      .then(response => { if (active) setOrganizationEmployees(response.data?.results || []) })
      .catch(() => { if (active) setOrganizationEmployees(null) })
    apiClient.get('/rbac/profile-documents/my_documents/')
      .then(response => { if (active) setProfileDocuments(Array.isArray(response.data) ? response.data : response.data?.results || []) })
      .catch(() => { if (active) setProfileDocuments(null) })
    return () => { active = false }
  }, [])

  const downloadOverviewPayslip = async slip => {
    if (!slip?.id) return
    setDownloadingOverview(true)
    setOverviewError('')
    try {
      const blob = await payrollEngineService.downloadPayslipXlsx(slip.id)
      const url = URL.createObjectURL(blob)
      const anchor = document.createElement('a')
      anchor.href = url
      anchor.download = `payslip-${slip.run_cycle || slip.id}.xlsx`
      document.body.appendChild(anchor)
      anchor.click()
      anchor.remove()
      window.setTimeout(() => URL.revokeObjectURL(url), 1000)
    } catch { setOverviewError('Payslip download failed. Open Pay & benefits to try again.') }
    finally { setDownloadingOverview(false) }
  }

  // -- Load timesheet data for current user ------------------------------------
  useEffect(() => {
    setLoadingTs(true)
    // Use new self-service endpoints that automatically filter by logged-in user
    const now = new Date()
    const employeeCode = profile?.employee_id || profile?.engineer_profile?.employee_code

    Promise.all([
      timesheetSvc.fetchMyMonthlyAttendance(now.getFullYear(), now.getMonth() + 1).catch(() => null),
      timesheetSvc.fetchMyDailyAttendance(todayStr()).catch(() => null),
      employeeCode
        ? timesheetSvc.fetchUserHistory({ code: employeeCode, limit: 60 }).catch(() => null)
        : Promise.resolve(null),
    ]).then(([monthly, daily, history]) => {
      // New self-service endpoints return { data: {...}, employee_code, email }
      // where data is the user's record directly, not an array to filter
      if (monthly?.data) {
        setMonthlyTs(monthly.data)
      } else if (monthly && !monthly.configured) {
        setMonthlyTs(null)
      } else {
        setMonthlyTs(null)
      }

      // Same for daily
      if (daily?.data) {
        setTodayTs(daily.data)
      } else if (daily && !daily.configured) {
        setTodayTs(null)
      } else {
        setTodayTs(null)
      }

      setUserHistory(history)
    }).finally(() => setLoadingTs(false))
  }, [profile])

  // Live presence is authoritative for the latest IN/OUT punch and also
  // carries the current authenticated RADAI activity heartbeat.
  useEffect(() => {
    let cancelled = false
    const refreshPresence = () => {
      timesheetSvc.fetchMyLiveAttendance()
        .then((response) => {
          if (!cancelled) setLiveAttendance(response)
        })
        .catch(() => {
          // Retain the last known state during a temporary biometric outage.
        })
    }

    refreshPresence()
    const timer = window.setInterval(refreshPresence, 60 * 1000)
    return () => {
      cancelled = true
      window.clearInterval(timer)
    }
  }, [])

  // -- Load leave data ---------------------------------------------------------
  useEffect(() => {
    setLoadingLeave(true)

    // employee.id from backend = Django User.id (not UserProfile.id)
    // employee_id on UserProfile = biometric employee code
    const userId = profile?.user?.id // Django User UUID — matches LeaveRequest.employee FK

    Promise.all([
      payrollService.getLeaveTypes().catch(() => []),
      // mine=true forces scoping to the current user's own requests even when
      // they hold an HR/Admin role (which otherwise gets unrestricted visibility
      // for the Leave Management / Approval Tracker views).
      payrollService.getLeaveRequests({ mine: true, year: new Date().getFullYear(), page_size: 50 }).catch(() => null),
      // 2026-08-31: this call had no `mine: true` (unlike its sibling right
      // above) — the comment below claimed the backend "auto-scopes... no
      // need to pass employee_code", but it never actually did that for an
      // HR/Admin-role user (the same "unrestricted visibility unless told
      // otherwise" behavior mine:true exists to override on the request
      // above). An HR Manager/admin viewing their OWN profile got the
      // unfiltered list back and picked up an arbitrary employee's balance
      // instead of their own — confirmed live for a super_admin account.
      // mine=true forces self-scoping regardless of role, same as above.
      payrollService.getLeaveRecords({ mine: true, year: new Date().getFullYear(), page_size: 5 }).catch(() => ({ results: [] })),
    ]).then(([types, reqRes, recRes]) => {
      setLeaveAvailable(reqRes !== null)
      // Filter leave types to only show enabled types from ESS_LEAVE_TYPE_CONFIG.
      // To enable/disable a type, change `enabled` in hrLeave.config.js — no code change needed.
      const enabledCategories = Object.keys(LEAVE_TYPE_CONFIG).filter(
        key => LEAVE_TYPE_CONFIG[key].enabled !== false
      )
      const apiTypes = Array.isArray(types) ? types : types?.results || []
      const filteredTypes = apiTypes.filter(t => {
        const category = (t.category || t.code || '').toLowerCase()
        return enabledCategories.includes(category)
      })
      setLeaveTypes(filteredTypes)

      const reqs = Array.isArray(reqRes) ? reqRes : reqRes?.results || []
      // Backend scopes leave requests to the current user. As a safety net, also
      // filter client-side using the correct User UUID (not the UserProfile UUID).
      setLeaveRequests(
        userId
          ? reqs.filter(r => r.employee === userId)
          : reqs
      )

      const recs = Array.isArray(recRes) ? recRes : recRes?.results || []
      setLeaveRecord(recs.length > 0 ? recs[0] : null)
    }).finally(() => setLoadingLeave(false))
  }, [profile, leaveRevision])

  // -- Load payroll data -------------------------------------------------------
  useEffect(() => {
    setLoadingPayroll(true)
    const userId  = profile?.user?.id   // Django User UUID for SalarySlip FK lookups
    const empCode = profile?.employee_id // biometric code for EmployeeSalaryInfo lookup

    Promise.all([
      // Real payslips live in payroll_engine.Payslip (finance.SalarySlip is
      // always empty — that model is unused). employee_no filters by the
      // PayrollEmployee's biometric/HR code, matching UserProfile.employee_id.
      empCode
        ? payrollEngineService.listPayslips({ employee_no: empCode, page_size: 12 }).catch(() => ({ results: [] }))
        : Promise.resolve({ results: [] }),
      empCode
        ? payrollEngineService.listEmployees({ search: empCode, is_active: true, page_size: 10 }).catch(() => ({ results: [] }))
        : Promise.resolve({ results: [] }),
      // EmployeeSalaryInfo: filter by user UUID (added in backend fix)
      userId
        ? payrollService.getEmployeeSalaryInfo({ employee: userId }).catch(() => null)
        : Promise.resolve(null),
    ]).then(([slipRes, employeeRes, info]) => {
      const rawSlips = Array.isArray(slipRes) ? slipRes : slipRes?.results || []
      // Normalise payroll_engine field names to what PayrollSnapshot already
      // reads (gross_salary/net_salary/month/year), and sort most-recent-run
      // first — run_cycle is 'YYYY-MM' so string sort works — since the
      // backend's default ordering here is alphabetical by employee name.
      const slipList = [...rawSlips]
        .sort((a, b) => String(b.run_cycle).localeCompare(String(a.run_cycle)))
        .map(s => {
          const [year, month] = String(s.run_cycle || '').split('-').map(Number)
          return {
            ...s,
            year,
            month,
            gross_salary: s.gross_earnings,
            net_salary:   s.net_payable,
          }
        })
      setSlips(slipList)
      const employees = Array.isArray(employeeRes) ? employeeRes : employeeRes?.results || []
      const payrollEmployee = employees.find(e => String(e.employee_no) === String(empCode)) || null
      const infoList = Array.isArray(info) ? info : info?.results || [info]
      const legacyInfo = infoList.find(Boolean) || null
      setSalaryInfo(payrollEmployee || legacyInfo ? {
        ...(legacyInfo || {}),
        ...(payrollEmployee || {}),
        basic_salary: payrollEmployee?.basic ?? legacyInfo?.basic_salary,
      } : null)
    }).finally(() => setLoadingPayroll(false))
  }, [profile])

  // -- Load current user's notifications --------------------------------------
  useEffect(() => {
    setLoadingNotifications(true)
    notificationService.getNotifications({ page_size: 100 })
      .then(data => setNotifications(Array.isArray(data) ? data : data?.results || []))
      .catch(() => setNotifications([]))
      .finally(() => setLoadingNotifications(false))
  }, [])

  const handleMarkNotificationRead = useCallback(async (id) => {
    setNotifications(items => items.map(n => n.id === id ? { ...n, is_read: true } : n))
    try {
      await notificationService.markAsRead(id)
    } catch {
      setNotifications(items => items.map(n => n.id === id ? { ...n, is_read: false } : n))
    }
  }, [])

  const handleMarkAllNotificationsRead = useCallback(async () => {
    const previous = notifications
    setNotifications(items => items.map(n => ({ ...n, is_read: true })))
    try {
      await notificationService.markAllAsRead()
    } catch {
      setNotifications(previous)
    }
  }, [notifications])

  // -- Derived: AI insights ----------------------------------------------------
  const insights = useMemo(() => generateInsights({
    leaveRecord,
    monthlyTs,
    today: todayTs,
    slips,
    salaryVisible,
  }), [leaveRecord, monthlyTs, todayTs, slips, salaryVisible])

  // -- Leave request submit ----------------------------------------------------
  const handleLeaveSubmit = useCallback(async (form) => {
    setSubmitting(true)
    setSubmitResult(null)
    try {
      // Use Django User UUID — matches the LeaveRequest.employee FK
      const userId  = profile?.user?.id
      const empCode = profile?.employee_id
      const empName = profile
        ? [profile.user?.first_name, profile.user?.last_name].filter(Boolean).join(' ') || profile.user?.username
        : null
      
      // SOFT-CODED: Handle file upload with FormData if attachment is present
      let response
      if (form.attachment) {
        const formData = new FormData()
        formData.append('leave_type', form.leave_type)
        formData.append('start_date', form.start_date)
        formData.append('end_date', form.end_date)
        formData.append('half_day', form.half_day ? 'true' : 'false')
        formData.append('reason', form.reason || '')
        formData.append('contact_number', form.contact_number || '')
        formData.append('substitute_name', form.substitute_name || '')
        formData.append('attachment', form.attachment)
        if (userId) formData.append('employee', userId)
        if (empCode) formData.append('employee_code', empCode)
        if (empName) formData.append('employee_name', empName)
        
        response = await payrollService.createLeaveRequest(formData, true) // true = multipart
      } else {
        // Regular JSON submission without attachment
        const payload = {
          ...form,
          // Backend perform_create also sets these — we send them for non-staff HR fallback
          ...(userId   ? { employee: userId }             : {}),
          ...(empCode  ? { employee_code: empCode }       : {}),
          ...(empName  ? { employee_name: empName }       : {}),
        }
        response = await payrollService.createLeaveRequest(payload)
      }
      
      window.dispatchEvent(new Event('leave-approval-updated'))
      setSubmitResult({ success: true, message: `Leave request submitted. Awaiting ${response?.line_manager_name || 'line manager'} approval, followed by HR.` })
      // Reload requests — mine=true scopes to current user even for HR/Admin roles
      const reqRes = await payrollService.getLeaveRequests({ mine: true, page_size: 50 }).catch(() => ({ results: [] }))
      const reqs   = Array.isArray(reqRes) ? reqRes : reqRes?.results || []
      setLeaveRequests(userId ? reqs.filter(r => r.employee === userId) : reqs)
    } catch (err) {
      const msg = err?.response?.data?.detail ||
                  err?.response?.data?.non_field_errors?.[0] ||
                  Object.values(err?.response?.data || {}).flat().join(' ') ||
                  'Failed to submit leave request. Please try again.'
      setSubmitResult({ error: msg })
    } finally {
      setSubmitting(false)
    }
  }, [profile])

  // -- Tab notification badges -------------------------------------------------
  const pendingLeave   = leaveRequests.filter(r => ['PENDING', 'RM_APPROVED'].includes(r.status?.toUpperCase())).length
  const unreadNotifs   = notifications.filter(n => !n.is_read).length

  // Days Taken — live sum from approved requests. Matches LeaveBalanceSection's
  // calculation on the Leave tab exactly (same leaveRequests state, same
  // field/sum logic) so both tabs always agree, instead of the Overview card
  // reading the static leaveRecord.total_taken snapshot.
  const totalDaysTaken = leaveRequests
    .filter(r => r.status?.toUpperCase() === 'APPROVED')
    .reduce((sum, r) => sum + Number(r.days_requested || r.duration_days || r.days || 0), 0)

  const tabBadges = {
    leave:         pendingLeave > 0 ? pendingLeave : null,
    notifications: unreadNotifs > 0 ? unreadNotifs : null,
  }

  // -- Section renders ---------------------------------------------------------
  const renderSection = () => {
    // Check if profile is incomplete (missing employee_id or has placeholder/marker)
    const empId = profile?.employee_id
    const employeeIdentifier = currentUser?.email || authProfile?.email || profile?.user_email || profile?.email || empId
    const invalidMarkers = ['DELETED', 'TEST_ACCOUNT', 'EXTERNAL']
    const needsConfig = !empId || empId === '' || empId.includes('@') || empId.startsWith('EMP') || invalidMarkers.includes(empId)

    const loadingByTab = {
      overview: loadingProfile || loadingTs || loadingLeave || loadingPayroll,
      leave: loadingProfile || loadingLeave,
      attendance: loadingProfile,
      payroll: loadingProfile || loadingPayroll,
      twin: loadingProfile || loadingTs || loadingLeave || loadingPayroll,
      notifications: loadingNotifications,
    }
    const loadingMessageByTab = {
      overview: 'Loading your employee overview…',
      leave: 'Loading your leave information…',
      attendance: 'Loading your attendance…',
      payroll: 'Loading your payroll information…',
      twin: 'Loading your employee insights…',
      notifications: 'Loading your notifications…',
    }

    if (loadingByTab[activeTab]) {
      return <EmployeeTabLoading message={loadingMessageByTab[activeTab]} />
    }
    
    switch (activeTab) {
      case 'overview':
        return <ProfileOverviewWorkspace
          profile={profile} organizationEmployees={organizationEmployees} todayData={todayTs} monthlyTs={monthlyTs}
          leaveRecord={leaveRecord}
          leaveRequests={leaveRequests} leaveAvailable={leaveAvailable}
          slips={slips} documents={profileDocuments} onNavigate={setActiveTab}
          onDownloadPayslip={downloadOverviewPayslip} downloading={downloadingOverview}
          downloadError={overviewError}
        />

      case 'documents':
        return <div className="rounded-xl border border-slate-200 bg-white p-5"><DocumentUploadSection /></div>

      case 'career':
        return <Profile embedded />

      case 'signature':
        return <div className="space-y-5"><MySignaturePanel /><MyDigitalStampPanel /></div>

      case 'leave':
        return (
          <div className="space-y-5">
            {/* Profile Configuration Alert */}
            {needsConfig && (
              <div className="bg-amber-50 border border-amber-200 rounded-lg p-4">
                <div className="flex items-start gap-3">
                  <Icon name="ExclamationTriangleIcon" className="w-5 h-5 text-amber-600 flex-shrink-0 mt-0.5" />
                  <div className="flex-1">
                    <div className="font-semibold text-amber-900 text-sm mb-1">
                      Employee ID Required
                    </div>
                    <div className="text-amber-700 text-sm">
                      To view leave records, please contact HR to configure your employee ID. Current value: <code className="bg-amber-100 px-1 rounded">{empId || 'Not Set'}</code>
                    </div>
                  </div>
                </div>
              </div>
            )}
            
            <ProfileLeaveSummary
              typeConfig={LEAVE_TYPE_CONFIG}
              leaveRecord={leaveRecord}
              requests={leaveRequests}
              loading={loadingLeave}
            />
            <div className="grid grid-cols-1 items-start gap-4 xl:grid-cols-[minmax(320px,0.85fr)_minmax(0,1.65fr)]">
              <LeaveRequestForm
                leaveTypes={leaveTypes}
                leaveRecord={leaveRecord}
                requests={leaveRequests}
                onSubmit={handleLeaveSubmit}
                submitting={submitting}
                submitResult={submitResult}
              />
              <ProfileLeaveRequests requests={leaveRequests} loading={loadingLeave} />
            </div>
          </div>
        )

      case 'attendance':
      case 'timesheet':
        return <ProfileTimesheetTables profile={profile} />

      case 'payroll':
        return (
          <PayrollSnapshot
            salaryInfo={salaryInfo}
            slips={slips}
            loading={loadingPayroll}
            salaryVisible={salaryVisible}
            onToggleSalary={() => setSalaryVisible((visible) => !visible)}
          />
        )

      case 'workspace':
        return <UnifiedHRWorkspacePanel />

      case 'requests':
        return <EmployeeServiceRequestsPanel employeeIdentifier={employeeIdentifier} />

      case 'performance':
        return <EmployeeTalentPerformancePanel employee={{ id: employeeIdentifier }} profileWorkspace />

      case 'schedule':
        return <EmployeeWorkforceSchedulePanel employee={{ id: employeeIdentifier }} />

      case 'team':
        return <TeamCalendar />

      case 'daily_tracker':
        return <DailyTrackerTab currentUser={currentUser || authProfile} />

      case 'twin':
        return (
          <DigitalTwin
            monthlyTs={monthlyTs}
            leaveRecord={leaveRecord}
            slips={slips}
            requests={leaveRequests}
            loading={loadingTs || loadingLeave || loadingPayroll}
          />
        )

      case 'notifications':
        return (
          <NotificationsCenter
            notifications={notifications}
            loading={loadingNotifications}
            onMarkRead={handleMarkNotificationRead}
            onMarkAllRead={handleMarkAllNotificationsRead}
          />
        )

      case 'site_visits':
        return <SiteVisitsPanel />

      case 'assistant':
        return <HRAssistantPanel />

      default:
        return null
    }
  }

  return (
    <div className="epw-page">
      <div className="epw-container">
        {/* -- Profile Header -- */}
        <EmployeeProfileHeader
          profile={profile}
          leaveRecord={leaveRecord}
          monthlyTs={monthlyTs}
          salaryInfo={salaryInfo}
          loading={loadingProfile}
          activeTab={activeTab}
          onTabChange={setActiveTab}
          tabBadges={tabBadges}
          salaryVisible={salaryVisible}
          onToggleSalary={() => setSalaryVisible((visible) => !visible)}
          uploadingPhoto={uploadingPhoto}
          photoUploadState={photoUploadState}
          onPhotoUpload={handleProfilePhotoUpload}
          todayData={todayTs}
          liveAttendance={liveAttendance}
          authenticatedPhotoUrl={authenticatedPhotoUrl}
        />

        {/* -- Active Section -- */}
        <div className={`epw-active-section${activeTab === 'overview' ? '' : ' epw-tab-content'}`} data-profile-tab={activeTab}>
          {renderSection()}
        </div>

        {/* -- Footer -- */}
        <div className="epw-footer">
          Your personal workspace · Only your own employee records are shown.
        </div>
      </div>
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import * as Icons from '@heroicons/react/24/outline'
import apiClient from '../../services/api.service'
import { CASE_STAGES, CASE_STATUSES, caseActivity, caseDate, caseError, caseProgress, isPastCaseDate, validCaseDate } from './onboardingCaseData'
import { getOnboardingInitials } from './onboardingDashboardData'
import './FullOnboardingOverview.css'

const API = '/onboarding/onboarding'
const BRANCHES = { RAD: 'Rejlers Abu Dhabi', RIN: 'Rejlers India' }

export default function FullOnboardingOverview({ employee = {}, recordId, focusItChecklist = false, focusedChecklistStage, onClose }) {
  const [record, setRecord] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [loadAttempt, setLoadAttempt] = useState(0)
  const [selected, setSelected] = useState(CASE_STAGES.some(stage => stage.id === focusedChecklistStage) ? focusedChecklistStage : focusItChecklist ? 'it_provisioning' : null)
  const [busy, setBusy] = useState('')
  const [actionError, setActionError] = useState('')
  const [notice, setNotice] = useState('')
  const [editor, setEditor] = useState(null)
  const [editValue, setEditValue] = useState('')
  const [editError, setEditError] = useState('')
  const [owners, setOwners] = useState([])
  const [ownerState, setOwnerState] = useState('idle')
  const [ownerAttempt, setOwnerAttempt] = useState(0)
  const dialogRef = useRef(null)
  const tasksRef = useRef(null)
  const mutationLock = useRef(false)
  const progress = caseProgress(record)
  const active = progress.stages.find(stage => stage.id === selected) || progress.stages[progress.currentIndex]
  const currentStage = progress.stages[progress.currentIndex]
  const activeIndex = progress.stages.indexOf(active)
  const closed = ['completed', 'cancelled'].includes(record?.status)
  const permission = record?.checklist_stage_permissions?.[active.id]
  const canManage = !closed && Boolean(permission?.can_manage)
  const canStart = !closed && Boolean(permission?.can_start)
  const canEditCase = !closed && Boolean(record?.checklist_stage_permissions?.pre_hire?.can_manage)
  const ownerLabel = permission?.owner_label || active.owner
  const accessReason = permission?.disabled_reason || (closed ? 'This workflow is closed. Its checklist is read-only.' : 'HR Edit permission is required to manage this stage.')
  const name = record?.employee_name || `${employee.first_name || ''} ${employee.last_name || ''}`.trim() || 'Employee'
  const activity = caseActivity(record)
  const pastJoining = !closed && isPastCaseDate(record?.joining_date)
  const unassigned = !record?.assigned_to && !record?.assigned_to_name
  const caseWarnings = !closed ? [unassigned && 'Case owner is unassigned', (!record?.joining_date || pastJoining) && 'Joining date requires review', !record?.reporting_manager && 'Reporting manager is not recorded'].filter(Boolean) : []

  useEffect(() => {
    if (!recordId && !employee.user_id) {
      setRecord(null); setLoading(false); setError('No employee or onboarding case was selected.')
      return undefined
    }
    let activeRequest = true
    setLoading(true); setError('')
    const request = recordId ? apiClient.get(`${API}/${recordId}/`) : apiClient.get(`${API}/`, { params: { user_id: employee.user_id } }).then(response => {
      const records = Array.isArray(response.data) ? response.data : response.data.results || []
      return records.length ? apiClient.get(`${API}/${records[0].id}/`) : { data: null }
    })
    request.then(response => { if (activeRequest) setRecord(response.data) })
      .catch(() => { if (activeRequest) setError('Unable to load the onboarding overview. Please try again.') })
      .finally(() => { if (activeRequest) setLoading(false) })
    return () => { activeRequest = false }
  }, [recordId, employee.user_id, loadAttempt])

  useEffect(() => {
    if (editor && dialogRef.current && !dialogRef.current.open) dialogRef.current.showModal()
  }, [editor])

  useEffect(() => {
    if (editor?.type !== 'owner') return undefined
    let live = true
    setOwnerState('loading')
    apiClient.get(`${API}/owner_options/`).then(response => {
      if (!live) return
      setOwners(Array.isArray(response.data) ? response.data : response.data.results || [])
      setOwnerState('ready')
    }).catch(() => { if (live) setOwnerState('error') })
    return () => { live = false }
  }, [editor?.type, ownerAttempt])

  const openEditor = (type, item) => {
    setEditError('')
    setEditValue(type === 'owner' ? String(record.assigned_to || '') : type === 'date' ? record.joining_date || '' : item?.description || '')
    setEditor({ type, item })
  }
  const closeEditor = () => {
    if (busy) return
    dialogRef.current?.close()
    setEditor(null)
  }
  const refresh = async () => {
    const response = await apiClient.get(`${API}/${record.id}/`)
    setRecord(response.data)
    return response.data
  }
  const mutate = async (key, operation, message) => {
    if (mutationLock.current) return false
    mutationLock.current = true; setBusy(key); setActionError(''); setNotice('')
    try {
      await operation()
      await refresh()
      setNotice(message)
      return true
    } catch (failure) {
      setActionError(caseError(failure, 'The change could not be saved. Refresh the case and try again.'))
      return false
    } finally { mutationLock.current = false; setBusy('') }
  }
  const startStage = () => {
    if (!canStart) return
    return mutate('start', () => apiClient.post(`${API}/${record.id}/start-checklist-stage/`, { stage: active.id }), `${active.title} checklist started.`)
  }
  const toggleTask = item => {
    if (!canManage) return
    return mutate(`task-${item.id}`, () => apiClient.patch(`/onboarding/checklist/${item.id}/`, { completed: !item.completed }), `${item.task_name}: ${item.completed ? 'marked as pending' : 'completed'}.`)
  }
  const saveEditor = async event => {
    event.preventDefault()
    if (mutationLock.current) return
    if (editor.type === 'owner' && !owners.some(owner => String(owner.user_id) === editValue)) { setEditError('Select an active case owner.'); return }
    if (editor.type === 'date' && !validCaseDate(editValue)) { setEditError('Enter a valid joining date.'); return }
    mutationLock.current = true; setBusy('editor'); setEditError(''); setNotice('')
    try {
      if (editor.type === 'task') await apiClient.patch(`/onboarding/checklist/${editor.item.id}/`, { description: editValue })
      else await apiClient.patch(`${API}/${record.id}/`, editor.type === 'owner' ? { assigned_to: editValue } : { joining_date: editValue })
      await refresh()
      setNotice(editor.type === 'owner' ? 'Case owner assigned.' : editor.type === 'date' ? 'Joining date updated.' : 'Task notes saved.')
      dialogRef.current?.close(); setEditor(null)
    } catch (failure) { setEditError(caseError(failure, 'The change could not be saved. Please try again.')) }
    finally { mutationLock.current = false; setBusy('') }
  }
  const printSummary = () => {
    const printWindow = window.open('', '_blank', 'width=1100,height=800')
    if (!printWindow) { setActionError('Allow pop-ups to open the print summary.'); return }
    const escape = value => String(value ?? '—').replace(/[&<>"']/g, char => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char])
    const rows = progress.stages.map(stage => `<h2>${escape(stage.title)}</h2><table><thead><tr><th>Task</th><th>Due</th><th>Status</th><th>Notes / evidence</th></tr></thead><tbody>${stage.items.length ? stage.items.map(item => `<tr><td>${escape(item.task_name)}</td><td>${escape(caseDate(item.due_date))}</td><td>${item.completed ? 'Completed' : 'Pending'}${item.completed_by_name ? `<br>${escape(item.completed_by_name)}` : ''}</td><td>${escape(item.description || '—')}</td></tr>`).join('') : '<tr><td colspan="4">Checklist has not started</td></tr>'}</tbody></table>`).join('')
    printWindow.document.write(`<!doctype html><html lang="en"><head><meta charset="utf-8"><title>${escape(name)} — Onboarding summary</title><style>@page{size:A4;margin:16mm}body{font:12px Arial,sans-serif;color:#14284b}header{border-bottom:2px solid #14284b;padding-bottom:12px}h1{font-size:25px}h2{font-size:16px;margin-top:25px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #d7e0ed;padding:8px;text-align:left;vertical-align:top;white-space:pre-wrap}th{background:#f0f5fa}tr{break-inside:avoid}footer{margin-top:24px;color:#596c89;font-size:10px}</style></head><body><header><strong>REJLERS · CONFIDENTIAL HR DOCUMENT</strong><h1>${escape(name)}</h1><p>Full Onboarding Overview · Case ONB-${escape(record.id)}</p><p>${escape(CASE_STATUSES[record.status] || record.status)} · ${progress.percent}% readiness</p></header><p>Joining date: ${escape(caseDate(record.joining_date))}<br>Case owner: ${escape(record.assigned_to_name || 'Unassigned')}<br>Work email: ${escape(record.employee_email)}<br>Employee ID: ${escape(record.employee_id)}<br>Position: ${escape(record.position)}<br>Department: ${escape(record.department)}<br>Reporting manager: ${escape(record.reporting_manager || 'Not assigned')}</p>${rows}<h2>Activity</h2>${activity.map(event => `<p>${escape(caseDate(event.date))} · ${escape(event.title)} · ${escape(event.detail)}</p>`).join('')}<footer>Printed ${escape(caseDate(new Date().toISOString()))} · Rejlers Abu Dhabi</footer></body></html>`)
    printWindow.document.close()
    printWindow.addEventListener('afterprint', () => printWindow.close(), { once: true })
    printWindow.setTimeout(() => { printWindow.focus(); printWindow.print() }, 300)
  }
  const back = () => { if (!busy) onClose() }

  return <div className="onboarding-case" aria-label="Full Onboarding Overview">
    <nav className="onboarding-case-breadcrumb" aria-label="Breadcrumb"><a href="/hr">HR</a><span>/</span><button type="button" onClick={back} disabled={Boolean(busy)} aria-label="Back to onboarding">Onboarding</button><span>/</span><span aria-current="page">{name}</span></nav>
    {loading ? <div className="onboarding-case-state" role="status"><Icons.ArrowPathIcon className="animate-spin" aria-hidden="true" />Loading onboarding overview…</div> : error ? <div className="onboarding-case-state" role="alert"><p>{error}</p><button className="onboarding-case-button" onClick={() => setLoadAttempt(value => value + 1)}>Retry overview</button></div> : !record ? <div className="onboarding-case-state"><p>No onboarding workflow was found for this employee.</p><button className="onboarding-case-button" onClick={back}>Back to onboarding</button></div> : <>
      <header className="onboarding-case-header"><div className="onboarding-case-person"><span className="onboarding-case-avatar">{record.photo_url ? <img src={record.photo_url} alt="" /> : getOnboardingInitials(name)}</span><div><div className="onboarding-case-title"><h1>{name}</h1><span className={`onboarding-case-badge ${record.status === 'completed' ? 'is-green' : record.status === 'cancelled' ? 'is-gray' : 'is-blue'}`}>{CASE_STATUSES[record.status] || record.status}</span></div><p>{record.position || employee.job_title_uae || 'Position not set'}<span> · </span>{record.department || employee.division || 'Department not set'}</p></div></div><div className="onboarding-case-id"><span>Case ID</span><strong>ONB-{record.id}</strong></div><div className="onboarding-case-header-actions"><button type="button" className="onboarding-case-button" onClick={printSummary}><Icons.PrinterIcon aria-hidden="true" />Print summary</button><button type="button" className="onboarding-case-button is-icon" aria-label="Refresh overview" disabled={Boolean(busy)} onClick={() => setLoadAttempt(value => value + 1)}><Icons.ArrowPathIcon aria-hidden="true" /></button>{canEditCase && <button type="button" className="onboarding-case-button is-primary" disabled={Boolean(busy)} onClick={() => openEditor('owner')}><Icons.UserPlusIcon aria-hidden="true" />{unassigned ? 'Assign owner' : 'Change owner'}</button>}</div></header>
      <section className="onboarding-case-metrics" aria-label="Case summary"><div><Icons.CalendarDaysIcon className="is-violet" aria-hidden="true" /><div><span>Joining date</span><strong>{caseDate(record.joining_date)}{pastJoining && <b className="onboarding-case-badge is-red">Past date</b>}</strong></div></div><div><Icons.ChartBarIcon aria-hidden="true" /><div><span>Overall readiness</span><strong title="Completion across all four checklist stages">{progress.percent}%</strong></div></div><div><Icons.DocumentCheckIcon className="is-blue" aria-hidden="true" /><div><span>Current stage</span><strong>{record.status === 'completed' ? 'Complete' : currentStage.short}</strong></div></div><div><Icons.UserCircleIcon className="is-amber" aria-hidden="true" /><div><span>Case owner</span><strong>{unassigned ? <b className="onboarding-case-badge is-amber">Unassigned</b> : record.assigned_to_name || 'Assigned'}</strong></div></div></section>
      {caseWarnings.length > 0 && <section className="onboarding-case-attention"><Icons.ExclamationCircleIcon aria-hidden="true" /><div><h2>Onboarding needs attention</h2><p>{unassigned && pastJoining ? 'Assign a case owner and review the joining date while completing the onboarding tasks.' : caseWarnings.join('. ') + '.'}</p></div><div>{canEditCase && unassigned && <button type="button" className="onboarding-case-button is-primary" onClick={() => openEditor('owner')} disabled={Boolean(busy)}><Icons.UserPlusIcon aria-hidden="true" />Assign owner</button>}{canEditCase && <button type="button" className="onboarding-case-button" onClick={() => openEditor('date')} disabled={Boolean(busy)}><Icons.CalendarDaysIcon aria-hidden="true" />Review joining date</button>}</div></section>}
      {actionError && <div className="onboarding-case-message is-error" role="alert">{actionError}<button type="button" onClick={() => { setActionError(''); setLoadAttempt(value => value + 1) }}>Refresh case</button></div>}
      {notice && <p className="onboarding-case-message" role="status"><Icons.CheckCircleIcon aria-hidden="true" />{notice}</p>}
      <nav className="onboarding-case-stages" aria-label="Onboarding stages">{progress.stages.map((stage, index) => {
        const stagePermission = record.checklist_stage_permissions?.[stage.id]
        return <button type="button" key={stage.id} aria-label={stage.short} aria-current={stage.id === active.id ? 'step' : undefined} disabled={Boolean(busy)} onClick={() => { setSelected(stage.id); setActionError('') }} className={stage.complete ? 'is-complete' : ''}><span className="onboarding-case-step-number">{stage.complete ? <Icons.CheckIcon aria-hidden="true" /> : index + 1}</span><div><strong>{stage.short}</strong><small>Owner: {stagePermission?.owner_label || stage.owner}</small></div>{!stage.complete && !stagePermission?.can_manage && !stagePermission?.can_start && <Icons.LockClosedIcon className="onboarding-case-step-lock" aria-hidden="true" />}</button>
      })}</nav>
      <div className="onboarding-case-columns">
        <section className="onboarding-case-panel onboarding-case-tasks" ref={tasksRef} tabIndex={-1} aria-labelledby="onboarding-case-stage-title">
          <header className="onboarding-case-task-heading"><Icons.DocumentCheckIcon aria-hidden="true" /><div><h2 id="onboarding-case-stage-title">{active.title}</h2><p>{active.description}</p></div><dl><div><dt>Owner</dt><dd>{ownerLabel}</dd></div><div><dt>Completed</dt><dd>{active.done} of {active.items.length}</dd></div><div><dt>Due</dt><dd>{caseDate(record.target_completion_date || record.joining_date)}</dd></div></dl><span className={`onboarding-case-access ${canManage ? 'is-editable' : ''}`}>{canManage ? <Icons.PencilSquareIcon aria-hidden="true" /> : <Icons.EyeIcon aria-hidden="true" />}{canManage ? 'HR can edit this stage' : closed ? 'View only — case closed' : `View only — ${ownerLabel} owns this stage`}</span></header>
          {!canManage && <p className="onboarding-case-access-reason"><Icons.LockClosedIcon aria-hidden="true" />{accessReason}</p>}
          {active.items.length ? <div className="onboarding-case-table-scroll"><table className="onboarding-case-table"><thead><tr><th scope="col">#</th><th scope="col">Task</th><th scope="col">Owner</th><th scope="col">Due</th><th scope="col">Status</th><th scope="col">Evidence / Action</th></tr></thead><tbody>{active.items.map((item, index) => <tr key={item.id}><td>{index + 1}</td><td><span>{item.task_name}</span></td><td>{ownerLabel}</td><td><span className={!item.completed && isPastCaseDate(item.due_date) ? 'onboarding-case-overdue' : ''}>{!item.completed && isPastCaseDate(item.due_date) && <Icons.CalendarDaysIcon aria-hidden="true" />}{item.due_date ? !item.completed && isPastCaseDate(item.due_date) ? 'Overdue' : caseDate(item.due_date) : 'Not set'}</span></td><td><button type="button" className={`onboarding-case-task-status ${item.completed ? 'is-complete' : ''}`} aria-label={`Mark ${item.task_name} as ${item.completed ? 'pending' : 'completed'}`} disabled={!canManage || Boolean(busy)} onClick={() => toggleTask(item)} title={canManage ? `Mark as ${item.completed ? 'pending' : 'completed'}` : accessReason}>{item.completed ? <Icons.CheckCircleIcon aria-hidden="true" /> : <i />}{busy === `task-${item.id}` ? 'Saving…' : item.completed ? 'Completed' : 'Not started'}</button></td><td><button type="button" className="onboarding-case-link" disabled={Boolean(busy)} onClick={() => openEditor('task', item)}><Icons.ArrowTopRightOnSquareIcon aria-hidden="true" />{item.completed ? 'View evidence' : 'View requirement'}</button></td></tr>)}</tbody></table></div> : <div className="onboarding-case-empty"><Icons.ClipboardDocumentListIcon aria-hidden="true" /><h3>{active.title} has not started</h3><p>{canStart ? 'Start the checklist to create this stage’s standard tasks.' : accessReason}</p><button type="button" className="onboarding-case-button is-primary" onClick={startStage} disabled={!canStart || Boolean(busy)}>{busy === 'start' ? 'Starting…' : canStart ? 'Start Checklist' : canEditCase ? 'Stage locked' : 'View Only'}</button></div>}
          {active.items.length > 0 && <footer className="onboarding-case-task-footer"><Icons.InformationCircleIcon aria-hidden="true" /><p>{closed ? 'This case is closed. Completed tasks and evidence remain available for review.' : 'Review the requirements and record completion for every task. The next stage unlocks when this checklist is complete.'}</p><div>{closed ? <span className={`onboarding-case-badge ${record.status === 'completed' ? 'is-green' : 'is-gray'}`}>{CASE_STATUSES[record.status]}</span> : activeIndex < 3 ? <button type="button" className="onboarding-case-button is-primary" disabled={!active.complete || Boolean(busy)} onClick={() => setSelected(progress.stages[activeIndex + 1].id)}>Continue to {progress.stages[activeIndex + 1].short}<Icons.ArrowRightIcon aria-hidden="true" /></button> : <button type="button" className="onboarding-case-button is-primary" disabled={!progress.allComplete || !canManage || Boolean(busy)} onClick={() => mutate('complete', () => apiClient.post(`${API}/${record.id}/mark_completed/`, {}), 'Onboarding completed.')}>Complete onboarding</button>}<small>{closed ? `${progress.percent}% readiness recorded` : active.items.length - active.done ? `${active.items.length - active.done} required tasks remain` : 'All stage tasks complete'}</small></div></footer>}
        </section>
        <aside className="onboarding-case-aside">
          <section className="onboarding-case-panel onboarding-case-readiness"><h2><Icons.ChartBarIcon aria-hidden="true" />Case readiness</h2><div className={`onboarding-case-readiness-status ${record.status === 'completed' ? 'is-complete' : record.status === 'cancelled' ? 'is-cancelled' : caseWarnings.length || active.items.some(item => !item.completed && isPastCaseDate(item.due_date)) ? 'is-attention' : ''}`}><Icons.ExclamationCircleIcon aria-hidden="true" />{record.status === 'completed' ? 'Completed' : record.status === 'cancelled' ? 'Cancelled' : caseWarnings.length ? 'Needs attention' : 'In progress'}</div><ul><li><Icons.ListBulletIcon aria-hidden="true" /><span>{active.items.length ? `${active.items.length - active.done} ${active.short.toLowerCase()} tasks incomplete` : `${active.short} checklist not started`}</span></li>{caseWarnings.map(warning => <li key={warning}><Icons.ExclamationCircleIcon aria-hidden="true" /><span>{warning}</span></li>)}{activeIndex < 3 && !active.complete && <li><Icons.LockClosedIcon aria-hidden="true" /><span>Complete this checklist to unlock {progress.stages[activeIndex + 1].short.toLowerCase()}</span></li>}</ul><button type="button" className="onboarding-case-button onboarding-case-review-button" onClick={() => { tasksRef.current?.scrollIntoView({ behavior: 'smooth', block: 'center' }); tasksRef.current?.focus({ preventScroll: true }) }}>Review tasks<Icons.ArrowRightIcon aria-hidden="true" /></button></section>
          <section className="onboarding-case-panel onboarding-case-activity"><header><h2><Icons.ClockIcon aria-hidden="true" />Activity</h2><button type="button" className="onboarding-case-button" onClick={() => openEditor('history')}>View full history</button></header><ol>{activity.slice(0, 3).map(event => <li key={event.id}><strong>{event.title}</strong><span>{caseDate(event.date)}{event.detail && ` · ${event.detail}`}</span></li>)}</ol>{!activity.length && <p className="onboarding-case-muted">No recorded activity yet.</p>}</section>
        </aside>
      </div>
      <details className="onboarding-case-panel onboarding-case-employee" open><summary><Icons.UserIcon aria-hidden="true" /><h2>Employee details</h2><Icons.ChevronDownIcon aria-hidden="true" /></summary><dl>{[['Work email', record.employee_email || employee.email], ['Employee ID', record.employee_id || employee.employee_number], ['Branch', BRANCHES[record.branch] || record.branch], ['Position', record.position], ['Department', record.department], ['Reporting manager', record.reporting_manager || 'Not assigned']].map(([label, value]) => <div key={label}><dt>{label}</dt><dd>{value || 'Not set'}</dd></div>)}</dl><div className="onboarding-case-employee-actions">{record.user && <a className="onboarding-case-link" href={`/hr/employees?employee=${encodeURIComponent(record.user)}`}><Icons.ArrowTopRightOnSquareIcon aria-hidden="true" />Open employee record</a>}{canEditCase && <button type="button" className="onboarding-case-link" disabled={Boolean(busy)} onClick={() => openEditor('date')}>Review joining date</button>}</div></details>
      {editor && <dialog ref={dialogRef} className="onboarding-case-dialog" aria-labelledby="onboarding-case-dialog-title" onCancel={event => { event.preventDefault(); closeEditor() }} onClose={() => setEditor(null)}><header><h2 id="onboarding-case-dialog-title">{editor.type === 'owner' ? 'Assign case owner' : editor.type === 'date' ? 'Review joining date' : editor.type === 'task' ? editor.item.task_name : 'Activity history'}</h2><button type="button" className="onboarding-case-button is-icon" aria-label="Close dialog" onClick={closeEditor} disabled={Boolean(busy)}><Icons.XMarkIcon aria-hidden="true" /></button></header>
        {editor.type === 'history' ? <ol className="onboarding-case-history-list">{activity.map(event => <li key={event.id}><strong>{event.title}</strong><p>{event.detail}</p><small>{caseDate(event.date)}</small></li>)}</ol> : <form onSubmit={saveEditor}>
          {editor.type === 'owner' && <><p>Select the employee responsible for coordinating this onboarding case.</p><label htmlFor="onboarding-case-owner">Case owner</label><select id="onboarding-case-owner" name="assigned_to" value={editValue} onChange={event => setEditValue(event.target.value)} disabled={ownerState !== 'ready' || Boolean(busy)} required><option value="">{ownerState === 'loading' ? 'Loading owners…' : 'Select case owner'}</option>{owners.map(owner => <option value={owner.user_id} key={owner.user_id}>{`${owner.first_name || ''} ${owner.last_name || ''}`.trim()} · {owner.email || owner.employee_number}</option>)}</select>{ownerState === 'error' && <p className="onboarding-case-message is-error" role="alert">Case owners could not be loaded.<button type="button" onClick={() => setOwnerAttempt(value => value + 1)}>Retry owners</button></p>}</>}
          {editor.type === 'date' && <><p>Update the joining date on this case and the employee record. Existing task deadlines and the target completion date stay as recorded.</p><label htmlFor="onboarding-case-date">Joining date</label><input id="onboarding-case-date" name="joining_date" type="date" value={editValue} onChange={event => setEditValue(event.target.value)} required disabled={Boolean(busy)} /></>}
          {editor.type === 'task' && <><p>{active.title} · Owner: {ownerLabel} · Due {caseDate(editor.item.due_date)}</p><label htmlFor="onboarding-case-description">Requirement / evidence notes</label><textarea id="onboarding-case-description" name="description" rows="6" value={editValue} onChange={event => setEditValue(event.target.value)} readOnly={!canManage} disabled={Boolean(busy)} /><p className="onboarding-case-muted">Record the requirement, reference or completion evidence here. Task completion is recorded separately in the checklist.</p>{editor.item.completed && <p>Completed {caseDate(editor.item.completed_date)}{editor.item.completed_by_name && ` by ${editor.item.completed_by_name}`}.</p>}</>}
          {editError && <p className="onboarding-case-message is-error" role="alert">{editError}</p>}
          <footer><button type="button" className="onboarding-case-button" disabled={Boolean(busy)} onClick={closeEditor}>Cancel</button>{(editor.type !== 'task' || canManage) && <button type="submit" className="onboarding-case-button is-primary" disabled={Boolean(busy) || (editor.type === 'owner' && ownerState !== 'ready')}>{busy === 'editor' ? 'Saving…' : editor.type === 'owner' ? 'Save owner' : editor.type === 'date' ? 'Save joining date' : 'Save notes'}</button>}</footer>
        </form>}
      </dialog>}
    </>}
  </div>
}

/**
 * HR · Consolidated Command Center (`/hr`)
 * ----------------------------------------
 * The HR Vice President's single-pane real-time dashboard.
 *
 * Data sources (all existing — NO core logic was modified):
 *   • timesheetService.fetchLive()    → live IN/OUT summary + roster
 *   • timesheetService.fetchDaily()   → today's per-user hours
 *   • timesheetService.fetchMonthly() → month-to-date rollup
 *   • rbacService.getUsers()          → workforce master directory
 *
 * Every label, KPI, polling interval, colour, section and link is read from
 * `frontend/src/config/hrDashboard.config.js`. The component is intentionally
 * a thin renderer over that config so HR can re-tune the dashboard without
 * any JSX edits.
 */
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useSelector } from "react-redux";
import * as HeroIcons from "@heroicons/react/24/outline";

import hrCoreService from "../../services/hrCore.service";
import hrFoundationService from "../../services/hrFoundation.service";
import timesheetService from "../../services/timesheet.service";
import payrollService from "../../services/payroll.service";
import apiClient from "../../services/api.service";
import HRCommandCenterView from "./HRCommandCenterView";
import {
  fmtCurrency,
  PAYROLL_WORKFLOW_STAGES,
} from "../../config/hrPayroll.config";

import {
  HR_DASHBOARD_POLL_MS,
  HR_DASHBOARD_COPY,
  HR_DASHBOARD_KPIS,
  HR_DASHBOARD_PAYROLL_KPIS,
  HR_DASHBOARD_SECTIONS,
  HR_DASHBOARD_QUICK_LINKS,
  HR_DASHBOARD_PENDING_TYPES,
  HR_DASHBOARD_KPI_REPORTS,
  HR_DASHBOARD_LEAVE_REPORT,
  buildTotalPending,
  buildDepartmentBreakdown,
  buildDisciplineBreakdown,
  buildTodayPunctuality,
  buildMonthRollup,
  buildRecentJoiners,
  buildLiveFeed,
  buildStatusDistribution,
  formatPunchTime,
  getGreeting,
  formatLeaveRecord,
} from "../../config/hrDashboard.config";

import {
  fullName,
  initials,
  normalizeEmployee,
  getEmail,
  formatDate,
} from "../../config/hrEmployees.config";

// ─────────────────────────────────────────────────────────────────────────────
// Tiny helpers — kept local so the page stays self-contained.
// ─────────────────────────────────────────────────────────────────────────────
const Icon = ({ name, className = "w-5 h-5" }) => {
  const C = HeroIcons[name] || HeroIcons.QuestionMarkCircleIcon;
  return <C className={className} aria-hidden="true" />;
};

const formatTime = (d) =>
  d
    ? new Date(d).toLocaleTimeString([], {
        hour: "2-digit",
        minute: "2-digit",
        second: "2-digit",
      })
    : "—";

const workforceErrorMessage = (error) => {
  if (error?.code === "ECONNABORTED" || /timeout/i.test(error?.message || "")) {
    return "The workforce directory timed out. Automatic retries also received no response.";
  }
  if (error?.response?.status === 401 || error?.response?.status === 403) {
    return "Permission denied. HR Management access is required to view workforce analytics.";
  }
  if ((error?.response?.status || 0) >= 500) {
    return "The workforce service returned a server error. Please retry or contact support if it continues.";
  }
  if (!error?.response) {
    return "The workforce service could not be reached. Check the network or backend connection and retry.";
  }
  return error?.response?.data?.detail || HR_DASHBOARD_COPY.workforceError;
};

const retryDelay = (milliseconds) =>
  new Promise((resolve) => window.setTimeout(resolve, milliseconds));

const isRetryableWorkforceError = (error) => {
  const status = error?.response?.status;
  return (
    error?.code === "ECONNABORTED" ||
    !error?.response ||
    status === 408 ||
    status === 429 ||
    status >= 500
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Badge palette for KPI report modal cells (status codes → Tailwind classes)
// ─────────────────────────────────────────────────────────────────────────────
const STATUS_BADGE_STYLES = {
  active: "bg-emerald-100 text-emerald-700 border-emerald-200",
  pending: "bg-amber-100   text-amber-700   border-amber-200",
  initiated: "bg-blue-100    text-blue-700    border-blue-200",
  "in progress": "bg-violet-100 text-violet-700 border-violet-200",
  "awaiting first login": "bg-amber-100 text-amber-700 border-amber-200",
  inactive: "bg-slate-100   text-slate-600   border-slate-200",
  suspended: "bg-red-100     text-red-700     border-red-200",
  on_leave: "bg-blue-100    text-blue-700    border-blue-200",
};

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: KPI drill-down report modal (full-screen overlay)
// ─────────────────────────────────────────────────────────────────────────────
const KpiReportModal = ({ reportId, ctx, onClose }) => {
  const [search, setSearch] = useState("");
  const config = HR_DASHBOARD_KPI_REPORTS[reportId];
  const navigate = useNavigate();

  // Close on Escape
  useEffect(() => {
    const handler = (e) => {
      if (e.key === "Escape") onClose();
    };
    document.addEventListener("keydown", handler);
    return () => document.removeEventListener("keydown", handler);
  }, [onClose]);

  if (!config) return null;

  const allRows = config.getRows(ctx);
  const filteredRows = search.trim()
    ? allRows.filter((r) => config.searchFn(r).includes(search.toLowerCase()))
    : allRows;

  const renderCell = (col, row) => {
    const val = col.render(row);
    if (col.typeBadge) {
      const type = String(val);
      const typeConfig =
        type === "Onboarding"
          ? {
              icon: "UserPlusIcon",
              classes: "bg-emerald-50 text-emerald-700 border-emerald-200",
            }
          : type === "Offboarding"
            ? {
                icon: "UserMinusIcon",
                classes: "bg-rose-50 text-rose-700 border-rose-200",
              }
            : {
                icon: "KeyIcon",
                classes: "bg-amber-50 text-amber-700 border-amber-200",
              };
      return (
        <span
          className={`inline-flex items-center gap-1.5 px-2 py-1 rounded-md text-[11px] font-bold border ${typeConfig.classes}`}
        >
          <Icon name={typeConfig.icon} className="w-3.5 h-3.5" />
          {type}
        </span>
      );
    }
    if (col.actionLink) {
      return (
        <span className="inline-flex items-center gap-1 text-xs font-bold text-blue-600">
          {val}
          <Icon name="ArrowRightIcon" className="w-3.5 h-3.5" />
        </span>
      );
    }
    if (col.statusBadge) {
      const style =
        STATUS_BADGE_STYLES[String(val).toLowerCase()] ||
        "bg-slate-100 text-slate-600 border-slate-200";
      return (
        <span
          className={`inline-flex items-center px-2 py-0.5 rounded-md text-[11px] font-semibold border capitalize ${style}`}
        >
          {val}
        </span>
      );
    }
    if (col.mfaBadge) {
      const enabled = String(val) === "Enabled";
      return (
        <span
          className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-semibold border ${
            enabled
              ? "bg-emerald-100 text-emerald-700 border-emerald-200"
              : "bg-rose-100 text-rose-700 border-rose-200"
          }`}
        >
          {enabled ? "✓ Enabled" : "✗ Disabled"}
        </span>
      );
    }
    if (col.lateBadge) {
      return (
        <span className="inline-flex items-center px-2 py-0.5 rounded-md text-[11px] font-semibold border bg-amber-100 text-amber-700 border-amber-200">
          ⏰ Late
        </span>
      );
    }
    if (col.attendanceBadge) {
      const isLate = String(val) === "Late";
      return (
        <span
          className={`inline-flex items-center px-2 py-0.5 rounded-md text-[11px] font-semibold border ${
            isLate
              ? "bg-amber-100 text-amber-700 border-amber-200"
              : "bg-emerald-100 text-emerald-700 border-emerald-200"
          }`}
        >
          {isLate ? "⏰ Late" : "✓ On Time"}
        </span>
      );
    }
    if (col.mono) {
      return <span className="font-mono text-xs text-slate-500">{val}</span>;
    }
    return val;
  };

  const openLifecycleRequest = (row) => {
    if (reportId !== "pending_onboarding") return;
    if (row.request_type === "Onboarding") {
      navigate(
        `/hr/onboarding?tab=onboarding&user_id=${row.user_id}&record_id=${row.request_id}&action=it-checklist`,
      );
    } else if (row.request_type === "Offboarding") {
      navigate(`/hr/onboarding?tab=offboarding&record_id=${row.request_id}`);
    } else {
      navigate(`/hr/employees?user_id=${row.user_id}`);
    }
    onClose();
  };

  return (
    <div
      className="fixed inset-0 z-50 flex items-start justify-center p-4 sm:p-8 bg-black/50 backdrop-blur-sm overflow-y-auto"
      onClick={(e) => {
        if (e.target === e.currentTarget) onClose();
      }}
    >
      <div className="relative bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-5xl my-auto">
        {/* ── Gradient header ── */}
        <div
          className={`bg-gradient-to-r ${config.accentGradient} rounded-t-2xl p-5 text-white`}
        >
          <div className="flex items-start justify-between gap-4">
            <div className="flex items-center gap-3">
              <div className="w-11 h-11 rounded-xl bg-white/20 flex items-center justify-center flex-shrink-0">
                <Icon name={config.icon} className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-xl font-bold">{config.title}</h2>
                <p className="text-sm text-white/80 mt-0.5 max-w-xl">
                  {config.description}
                </p>
              </div>
            </div>
            <button
              type="button"
              onClick={onClose}
              className="w-9 h-9 rounded-xl bg-white/20 hover:bg-white/30 flex items-center justify-center flex-shrink-0 transition-colors"
              title="Close (Esc)"
            >
              <Icon name="XMarkIcon" className="w-5 h-5" />
            </button>
          </div>
          {/* Summary stats bar */}
          <div className="mt-4 flex items-center gap-4 flex-wrap text-sm text-white/90">
            <span className="inline-flex items-center gap-1.5">
              <Icon name="TableCellsIcon" className="w-4 h-4 opacity-80" />
              <strong>{allRows.length}</strong> total records
            </span>
            {search.trim() && (
              <span className="inline-flex items-center gap-1.5">
                <Icon name="FunnelIcon" className="w-4 h-4 opacity-80" />
                <strong>{filteredRows.length}</strong> matching filter
              </span>
            )}
          </div>
        </div>

        {/* ── Search bar ── */}
        <div className="flex items-center gap-3 px-5 py-3 border-b border-slate-100 bg-slate-50/60">
          <div className="relative flex-1">
            <Icon
              name="MagnifyingGlassIcon"
              className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2 pointer-events-none"
            />
            <input
              type="text"
              placeholder="Search by name, email, department…"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="w-full pl-9 pr-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 bg-white"
              autoFocus
            />
            {search && (
              <button
                type="button"
                onClick={() => setSearch("")}
                className="absolute right-2.5 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-600"
              >
                <Icon name="XMarkIcon" className="w-3.5 h-3.5" />
              </button>
            )}
          </div>
          <button
            type="button"
            onClick={onClose}
            className="px-3 py-2 rounded-lg text-xs font-semibold bg-white border border-slate-200 text-slate-600 hover:bg-slate-100 transition-colors whitespace-nowrap"
          >
            ← Close Report
          </button>
        </div>

        {/* ── Data table ── */}
        <div
          className="overflow-x-auto"
          style={{ maxHeight: "60vh", overflowY: "auto" }}
        >
          {filteredRows.length === 0 ? (
            <div className="text-sm text-slate-500 italic py-14 text-center">
              {search.trim()
                ? "No records match your search."
                : config.emptyMsg}
            </div>
          ) : (
            <table className="w-full text-sm">
              <thead className="sticky top-0 bg-white border-b border-slate-200 shadow-sm z-10">
                <tr>
                  <th className="text-left px-4 py-3 text-xs font-semibold text-slate-400 uppercase tracking-wide w-10">
                    #
                  </th>
                  {config.columns.map((col) => (
                    <th
                      key={col.key}
                      className="text-left px-4 py-3 text-xs font-semibold text-slate-500 uppercase tracking-wide"
                    >
                      {col.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {filteredRows.map((row, idx) => (
                  <tr
                    key={row.id || row.user?.id || row.employee_code || idx}
                    onClick={() => openLifecycleRequest(row)}
                    onKeyDown={(event) => {
                      if (
                        reportId === "pending_onboarding" &&
                        (event.key === "Enter" || event.key === " ")
                      ) {
                        event.preventDefault();
                        openLifecycleRequest(row);
                      }
                    }}
                    role={
                      reportId === "pending_onboarding" ? "button" : undefined
                    }
                    tabIndex={reportId === "pending_onboarding" ? 0 : undefined}
                    className={`transition-colors ${
                      reportId === "pending_onboarding"
                        ? `cursor-pointer focus:outline-none focus:bg-blue-50 ${
                            row.request_type === "Onboarding"
                              ? "border-l-4 border-l-emerald-400 hover:bg-emerald-50/60"
                              : row.request_type === "Offboarding"
                                ? "border-l-4 border-l-rose-400 hover:bg-rose-50/60"
                                : "border-l-4 border-l-amber-400 hover:bg-amber-50/60"
                          }`
                        : "hover:bg-slate-50/80"
                    }`}
                    title={
                      reportId === "pending_onboarding"
                        ? `Open ${row.request_type} workflow`
                        : undefined
                    }
                  >
                    <td className="px-4 py-2.5 text-xs text-slate-400 font-mono">
                      {idx + 1}
                    </td>
                    {config.columns.map((col) => (
                      <td
                        key={col.key}
                        className="px-4 py-2.5 text-slate-800 max-w-xs truncate"
                      >
                        {renderCell(col, row)}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>

        {/* ── Footer ── */}
        <div className="px-5 py-3 border-t border-slate-100 rounded-b-2xl bg-slate-50/40 flex items-center justify-between gap-2 text-xs text-slate-400">
          <span>
            Live data — auto-refresh every{" "}
            {Math.round(HR_DASHBOARD_POLL_MS / 1000)}s
          </span>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-500 hover:text-slate-800 font-medium transition-colors"
          >
            Close ✕
          </button>
        </div>
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: top KPI tile — clickable, opens drill-down report
// ─────────────────────────────────────────────────────────────────────────────
const KpiTile = ({ kpi, value, onClick }) => (
  <button
    type="button"
    onClick={onClick}
    className="group w-full rounded-lg border border-l-[3px] border-slate-200 border-l-blue-600 bg-white p-3 text-left shadow-[0_1px_2px_rgba(15,23,42,0.04)] transition hover:border-slate-300 hover:shadow-md focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 focus-visible:ring-offset-2 motion-reduce:transition-none"
    title={`Click to view ${kpi.label} report`}
  >
    <div className="flex items-start justify-between">
      <div className="grid h-8 w-8 place-items-center rounded-md bg-blue-50 text-blue-700">
        <Icon name={kpi.icon} className="w-4 h-4" />
      </div>
      <span className="max-w-[65%] text-right text-[9px] font-medium uppercase tracking-wide text-slate-400">
        {kpi.sub}
      </span>
    </div>
    <div className="mt-2 text-2xl font-bold leading-tight tabular-nums text-slate-950">
      {value === null || value === undefined ? "—" : value}
    </div>
    <div className="mt-1 text-xs font-semibold text-slate-800">{kpi.label}</div>
    {/* Click hint — appears on hover */}
    <div className="absolute bottom-2.5 right-3 flex items-center gap-1 text-[9px] font-semibold uppercase tracking-wide text-slate-400 opacity-0 transition-opacity group-hover:opacity-100 motion-reduce:transition-none">
      <Icon name="ArrowTopRightOnSquareIcon" className="w-3 h-3" />
      View report
    </div>
  </button>
);

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: payroll / pending KPI tile (compact secondary strip)
// ─────────────────────────────────────────────────────────────────────────────
const PayrollKpiTile = ({ kpi, value, onClick }) => {
  const isUrgent = kpi.urgent && value > 0;
  return (
    <button
      type="button"
      onClick={onClick}
      className={`relative w-full overflow-hidden rounded-lg border p-3 text-left shadow-[0_1px_2px_rgba(15,23,42,0.04)] transition hover:border-slate-300 hover:shadow-md focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 focus-visible:ring-offset-2 motion-reduce:transition-none
        ${
          isUrgent
            ? "border-rose-200 bg-rose-50 text-rose-800"
            : "border-slate-200 bg-white text-slate-800"
        }`}
    >
      <div className="flex items-center justify-between mb-2">
        <Icon
          name={kpi.icon}
          className={`w-4 h-4 ${isUrgent ? "text-rose-600" : "text-slate-500"}`}
        />
        {isUrgent && (
          <span className="w-2 h-2 rounded-full bg-rose-500 animate-pulse" />
        )}
      </div>
      <div
        className={`text-xl font-bold tabular-nums ${isUrgent ? "text-rose-800" : "text-slate-900"}`}
      >
        {value === null || value === undefined ? "—" : value}
      </div>
      <div
        className={`text-xs mt-0.5 font-medium ${isUrgent ? "text-rose-700" : "text-slate-500"}`}
      >
        {kpi.label}
      </div>
    </button>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: section card wrapper
// ─────────────────────────────────────────────────────────────────────────────
const Section = ({ title, hint, icon, children, action }) => (
  <section className="rounded-lg border border-slate-200 bg-white shadow-[0_1px_2px_rgba(15,23,42,0.04)]">
    <header className="flex items-start justify-between gap-3 border-b border-slate-200 px-4 py-3">
      <div className="flex items-start gap-3 min-w-0">
        {icon && (
          <div className="w-8 h-8 rounded-md bg-blue-50 text-blue-700 flex items-center justify-center flex-shrink-0">
            <Icon name={icon} className="w-4 h-4" />
          </div>
        )}
        <div className="min-w-0">
          <h2 className="text-sm font-semibold text-slate-950 truncate">
            {title}
          </h2>
          {hint && <p className="text-xs text-slate-500 mt-0.5">{hint}</p>}
        </div>
      </div>
      {action && <div className="flex-shrink-0">{action}</div>}
    </header>
    <div className="p-4">{children}</div>
  </section>
);

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: horizontal bar chart (no chart library — pure tailwind)
// ─────────────────────────────────────────────────────────────────────────────
const BarChart = ({ items, emptyMessage }) => {
  if (!items || items.length === 0) {
    return (
      <div className="text-sm text-slate-500 italic py-6 text-center">
        {emptyMessage}
      </div>
    );
  }
  const max = Math.max(...items.map((i) => i.count), 1);
  return (
    <div className="space-y-2">
      {items.map((item) => {
        const pct = Math.max(2, Math.round((item.count / max) * 100));
        return (
          <div
            key={item.label}
            className="grid grid-cols-12 gap-2 items-center text-sm"
          >
            <div
              className="col-span-5 truncate text-slate-700"
              title={item.label}
            >
              {item.label}
            </div>
            <div className="col-span-6">
              <div className="h-2.5 bg-slate-100 rounded-full overflow-hidden">
                <div
                  className={`h-full bg-gradient-to-r ${item.accent || "from-blue-400 to-blue-600"} rounded-full transition-all`}
                  style={{ width: `${pct}%` }}
                />
              </div>
            </div>
            <div className="col-span-1 text-right font-semibold text-slate-900">
              {item.count}
            </div>
          </div>
        );
      })}
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: status distribution stack bar
// ─────────────────────────────────────────────────────────────────────────────
const StatusStack = ({ items, total }) => {
  if (!items || items.length === 0 || total === 0) {
    return <div className="text-sm text-slate-500 italic">No status data</div>;
  }
  return (
    <div className="space-y-3">
      <div className="flex h-3 w-full rounded-full overflow-hidden bg-slate-100">
        {items.map((s) => {
          const pct = Math.max(0.5, (s.count / total) * 100);
          return (
            <div
              key={s.code}
              className={s.bar}
              style={{ width: `${pct}%` }}
              title={`${s.label}: ${s.count}`}
            />
          );
        })}
      </div>
      <div className="flex flex-wrap gap-x-4 gap-y-1 text-xs">
        {items.map((s) => (
          <div key={s.code} className="flex items-center gap-1.5">
            <span className={`w-2.5 h-2.5 rounded-sm ${s.bar}`} />
            <span className={`font-medium ${s.text}`}>{s.label}</span>
            <span className="text-slate-500">({s.count})</span>
          </div>
        ))}
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: live activity feed row
// ─────────────────────────────────────────────────────────────────────────────
const LiveFeedRow = ({ row }) => {
  const t = formatPunchTime(row);
  const type = (row.punch_type || "").toString().toUpperCase();
  const isIn = type === "IN" || type === "1";
  const name =
    row.radai_full_name || row.name || row.employee_name || row.employee_code;
  const dept = row.radai_department || row.department || "";
  return (
    <div className="flex items-center gap-3 py-2.5 border-b border-slate-100 last:border-b-0">
      <div
        className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-semibold flex-shrink-0 ${
          isIn
            ? "bg-emerald-100 text-emerald-700"
            : "bg-slate-200 text-slate-700"
        }`}
      >
        {(name || "?").toString().slice(0, 2).toUpperCase()}
      </div>
      <div className="flex-1 min-w-0">
        <div className="text-sm font-medium text-slate-900 truncate">
          {name}
        </div>
        <div className="text-xs text-slate-500 truncate">
          {dept || row.employee_code}
        </div>
      </div>
      <div className="text-right flex-shrink-0">
        <div
          className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-semibold ${
            isIn
              ? "bg-emerald-50 text-emerald-700 border border-emerald-200"
              : "bg-slate-100 text-slate-600 border border-slate-200"
          }`}
        >
          <Icon
            name={
              isIn ? "ArrowRightOnRectangleIcon" : "ArrowLeftOnRectangleIcon"
            }
            className="w-3 h-3"
          />
          {isIn ? "IN" : "OUT"}
        </div>
        <div
          className={`text-[11px] mt-0.5 ${t.stale ? "text-slate-400" : "text-slate-500"}`}
        >
          {t.time}
          {t.minutesAgo !== null && t.minutesAgo < 999 && (
            <span className="ml-1 text-slate-400">· {t.minutesAgo}m ago</span>
          )}
        </div>
      </div>
    </div>
  );
};

const LeaveRecordRow = ({ record }) => {
  const name = record.employee_name || record.employee?.name || "Employee";
  const leaveType = record.leave_type_detail?.name || record.leave_type || "Leave";
  const status = (record.status || "PENDING").toUpperCase();
  const statusColors = HR_DASHBOARD_LEAVE_REPORT.statusColors[status]
    || HR_DASHBOARD_LEAVE_REPORT.statusColors.PENDING;
  const statusLabel = status.replaceAll("_", " ");
  const rowInitials = name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
  const dateLabel = record.start_date
    ? `${formatDate(record.start_date)}${record.end_date && record.end_date !== record.start_date ? ` – ${formatDate(record.end_date)}` : ""}`
    : "Date unavailable";

  return (
    <div className="flex items-center gap-3 border-b border-slate-100 py-2.5 last:border-b-0">
      <div className="flex h-9 w-9 flex-shrink-0 items-center justify-center rounded-full bg-blue-100 text-xs font-semibold text-blue-700">
        {rowInitials || "?"}
      </div>
      <div className="min-w-0 flex-1">
        <div className="truncate text-sm font-medium text-slate-900">{name}</div>
        <div className="truncate text-xs text-slate-500">{leaveType}</div>
      </div>
      <div className="flex-shrink-0 text-right">
        <div className={`inline-flex rounded-md border px-2 py-0.5 text-[11px] font-semibold ${statusColors.bg} ${statusColors.text} ${statusColors.border}`}>
          {statusLabel}
        </div>
        <div className="mt-0.5 max-w-40 truncate text-[11px] text-slate-400">{dateLabel}</div>
      </div>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: recent joiner card
// ─────────────────────────────────────────────────────────────────────────────
const JoinerCard = ({ emp }) => (
  <Link
    to="/hr/employees"
    className="flex items-center gap-3 p-3 rounded-xl border border-slate-200 hover:border-purple-300 hover:bg-purple-50/40 transition-colors"
  >
    <div className="w-10 h-10 rounded-full bg-gradient-to-br from-purple-500 to-fuchsia-600 text-white flex items-center justify-center text-sm font-semibold flex-shrink-0">
      {initials(emp)}
    </div>
    <div className="flex-1 min-w-0">
      <div className="text-sm font-semibold text-slate-900 truncate">
        {fullName(emp)}
      </div>
      <div className="text-xs text-slate-500 truncate">
        {getEmail(emp) || emp.department || "—"}
      </div>
    </div>
    <div className="text-[11px] text-slate-500 flex-shrink-0">
      {formatDate(emp.created_at)}
    </div>
  </Link>
);

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: quick link tile
// ─────────────────────────────────────────────────────────────────────────────
const QuickLink = ({ link }) => (
  <Link
    to={link.to}
    className={`flex items-start gap-3 p-4 rounded-xl border transition-colors ${link.tone}`}
  >
    <div className="w-10 h-10 rounded-lg bg-white/80 flex items-center justify-center flex-shrink-0 shadow-sm">
      <Icon name={link.icon} className="w-5 h-5" />
    </div>
    <div className="min-w-0">
      <div className="text-sm font-semibold">{link.label}</div>
      <div className="text-xs opacity-80 mt-0.5">{link.description}</div>
    </div>
  </Link>
);

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: pending action card (one per category)
// ─────────────────────────────────────────────────────────────────────────────
const PendingActionCard = ({ type, pending, navigate }) => {
  const count = type.getCount(pending);
  const items = type.getItems(pending);
  const hasItems = count > 0;
  return (
    <div
      className={`rounded-xl border p-4 flex flex-col gap-3 transition-all ${hasItems ? `${type.bg} ${type.border}` : "bg-white border-slate-200"}`}
    >
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <div
            className={`w-8 h-8 rounded-lg flex items-center justify-center ${hasItems ? "bg-white/70" : "bg-slate-100"}`}
          >
            <Icon
              name={type.icon}
              className={`w-4 h-4 ${hasItems ? type.text : "text-slate-400"}`}
            />
          </div>
          <span
            className={`text-sm font-semibold ${hasItems ? type.text : "text-slate-500"}`}
          >
            {type.label}
          </span>
        </div>
        <span
          className={`inline-flex items-center gap-1 px-2.5 py-1 rounded-full text-xs font-bold border ${hasItems ? type.badge : "bg-slate-100 text-slate-400 border-slate-200"}`}
        >
          {count}
        </span>
      </div>
      {/* Item list (top 3) */}
      {hasItems ? (
        <div className="space-y-2">
          {items.map((r, i) => (
            <div key={r.id || i} className="flex items-start gap-2 text-sm">
              <span
                className={`mt-1 w-1.5 h-1.5 rounded-full flex-shrink-0 ${type.dot}`}
              />
              <div className="min-w-0">
                <div className={`font-medium truncate ${type.text}`}>
                  {type.getRowLabel(r)}
                </div>
                <div className="text-xs text-slate-500 truncate">
                  {type.getRowSub(r)}
                </div>
              </div>
            </div>
          ))}
          {count > items.length && (
            <div className={`text-xs ${type.text} opacity-70`}>
              + {count - items.length} more
            </div>
          )}
        </div>
      ) : (
        <p className="text-xs text-slate-400">{type.zeroMsg}</p>
      )}
      {/* CTA */}
      <button
        type="button"
        onClick={() => navigate(type.route)}
        className={`mt-auto text-xs font-semibold py-1.5 px-3 rounded-lg border transition-colors
          ${
            hasItems
              ? "bg-white/80 border-white/50 hover:bg-white " + type.text
              : "bg-slate-50 border-slate-200 text-slate-400 hover:bg-slate-100 hover:text-slate-600"
          }`}
      >
        {type.actionLabel} →
      </button>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: notification dropdown (bell click)
// ─────────────────────────────────────────────────────────────────────────────
const NotifDropdown = ({ pending, total, navigate, onClose }) => (
  <div className="absolute right-0 top-full mt-2 w-80 bg-white rounded-2xl border border-slate-200 shadow-xl z-50 overflow-hidden">
    <div className="flex items-center justify-between px-4 py-3 border-b border-slate-100">
      <div className="flex items-center gap-2">
        <Icon name="BellIcon" className="w-4 h-4 text-slate-600" />
        <span className="text-sm font-semibold text-slate-800">
          {HR_DASHBOARD_COPY.notifTitle}
        </span>
      </div>
      {total > 0 && (
        <span className="px-2 py-0.5 rounded-full bg-rose-500 text-white text-[11px] font-bold">
          {total}
        </span>
      )}
      <button
        onClick={onClose}
        className="ml-auto text-slate-400 hover:text-slate-700"
      >
        <Icon name="XMarkIcon" className="w-4 h-4" />
      </button>
    </div>
    <div className="max-h-96 overflow-y-auto divide-y divide-slate-100">
      {total === 0 ? (
        <div className="flex flex-col items-center justify-center py-8 gap-2 text-slate-400">
          <Icon name="CheckCircleIcon" className="w-8 h-8 text-emerald-400" />
          <span className="text-sm">{HR_DASHBOARD_COPY.notifClear}</span>
        </div>
      ) : (
        HR_DASHBOARD_PENDING_TYPES.map((type) => {
          const count = type.getCount(pending);
          if (count === 0) return null;
          return (
            <button
              key={type.id}
              type="button"
              onClick={() => {
                navigate(type.route);
                onClose();
              }}
              className={`w-full flex items-center gap-3 px-4 py-3 hover:${type.bg} transition-colors text-left`}
            >
              <div
                className={`w-8 h-8 rounded-lg ${type.bg} ${type.border} border flex items-center justify-center flex-shrink-0`}
              >
                <Icon name={type.icon} className={`w-4 h-4 ${type.text}`} />
              </div>
              <div className="flex-1 min-w-0">
                <div className={`text-sm font-medium ${type.text}`}>
                  {type.label}
                </div>
                <div className="text-xs text-slate-500">
                  {count} {count === 1 ? type.singularMsg : type.pluralMsg}
                </div>
              </div>
              <span
                className={`px-2 py-0.5 rounded-full text-xs font-bold border ${type.badge}`}
              >
                {count}
              </span>
            </button>
          );
        })
      )}
    </div>
    <div className="px-4 py-3 border-t border-slate-100">
      <button
        type="button"
        onClick={() => {
          navigate("/hr/payroll");
          onClose();
        }}
        className="w-full text-center text-xs font-semibold text-blue-600 hover:text-blue-800"
      >
        Open Payroll & Salary →
      </button>
    </div>
  </div>
);

// ─────────────────────────────────────────────────────────────────────────────
// Approval Pipeline Widget — compact tracker embedded in the HR Dashboard.
// Gated by isSuperAdmin; clicking "Full Tracker" navigates to /hr/payroll.
// ─────────────────────────────────────────────────────────────────────────────
const PIPELINE_STAGE_KPIS = [
  {
    key: "draft",
    label: "Draft",
    cls: "bg-slate-100  text-slate-700  border-slate-200",
  },
  {
    key: "frozen",
    label: "Frozen",
    cls: "bg-blue-100   text-blue-700   border-blue-200",
  },
  {
    key: "hr_approved",
    label: "HR Approved",
    cls: "bg-violet-100 text-violet-700 border-violet-200",
  },
  {
    key: "finance_review",
    label: "In Finance",
    cls: "bg-amber-100  text-amber-700  border-amber-200",
  },
  {
    key: "finance_approved",
    label: "Fin. Approved",
    cls: "bg-emerald-100 text-emerald-700 border-emerald-200",
  },
  {
    key: "released",
    label: "Released",
    cls: "bg-green-100  text-green-700  border-green-200",
  },
];

function ApprovalPipelineWidget({ data, onViewAll }) {
  const { summary = {}, results = [] } = data;
  const active = [...results]
    .filter((r) => r.workflow_stage !== "released")
    .sort((a, b) => {
      const rank = { overdue: 0, warning: 1, ok: 2 };
      return (
        (rank[a.current_sla_status] ?? 2) - (rank[b.current_sla_status] ?? 2)
      );
    })
    .slice(0, 5);
  const overdueCount = summary.overdue_count ?? 0;
  const warningCount = summary.warning_count ?? 0;

  return (
    <div className="bg-white rounded-xl border border-slate-200 p-5 shadow-sm">
      {/* Header */}
      <div className="flex items-center justify-between mb-4 flex-wrap gap-2">
        <div className="flex items-center gap-2 flex-wrap">
          <div className="w-7 h-7 rounded-lg bg-blue-50 border border-blue-100 flex items-center justify-center">
            <HeroIcons.ClipboardDocumentListIcon className="w-4 h-4 text-blue-600" />
          </div>
          <div>
            <h3 className="text-sm font-semibold text-slate-700">
              Payroll Approval Pipeline
            </h3>
            <p className="text-[10px] text-slate-400">
              {summary.total ?? 0} master payroll file
              {(summary.total ?? 0) !== 1 ? "s" : ""}
            </p>
          </div>
          {overdueCount > 0 && (
            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-rose-100 text-rose-700 border border-rose-200">
              <HeroIcons.ExclamationCircleIcon className="w-3.5 h-3.5" />
              {overdueCount} overdue
            </span>
          )}
          {warningCount > 0 && overdueCount === 0 && (
            <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-medium bg-amber-100 text-amber-700 border border-amber-200">
              <HeroIcons.ExclamationTriangleIcon className="w-3.5 h-3.5" />
              {warningCount} at risk
            </span>
          )}
        </div>
        <button
          type="button"
          onClick={onViewAll}
          className="flex items-center gap-1 text-xs text-blue-600 hover:text-blue-800 hover:underline transition-colors"
        >
          Full Tracker
          <HeroIcons.ArrowTopRightOnSquareIcon className="w-3.5 h-3.5" />
        </button>
      </div>

      {/* Stage KPI mini-bar */}
      <div className="grid grid-cols-6 gap-2 mb-4">
        {PIPELINE_STAGE_KPIS.map(({ key, label, cls }) => (
          <div
            key={key}
            className={`rounded-lg border px-2 py-2 text-center ${cls}`}
          >
            <div className="text-lg font-bold leading-tight">
              {summary.by_stage?.[key] ?? 0}
            </div>
            <div className="text-[10px] font-medium opacity-70 leading-tight mt-0.5 truncate">
              {label}
            </div>
          </div>
        ))}
      </div>

      {/* Active files list */}
      {active.length > 0 ? (
        <div className="space-y-1.5">
          <p className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider mb-2">
            Active Files
          </p>
          {active.map((row) => {
            const stageDef = PAYROLL_WORKFLOW_STAGES.find(
              (s) => s.key === row.workflow_stage,
            );
            const StagIcon = stageDef
              ? HeroIcons[stageDef.icon] || HeroIcons.DocumentTextIcon
              : HeroIcons.DocumentTextIcon;
            const isOverdue = row.current_sla_status === "overdue";
            const isWarning = row.current_sla_status === "warning";
            return (
              <div
                key={row.id}
                className={`flex items-center justify-between px-3 py-2 rounded-lg border ${
                  isOverdue
                    ? "bg-rose-50/60 border-rose-200"
                    : isWarning
                      ? "bg-amber-50/60 border-amber-200"
                      : "bg-slate-50 border-slate-100"
                }`}
              >
                <div className="flex items-center gap-2.5 min-w-0">
                  {stageDef && (
                    <div
                      className={`w-6 h-6 rounded-full flex-shrink-0 flex items-center justify-center ${stageDef.activeBg} border ${stageDef.activeBorder}`}
                    >
                      <StagIcon className={`w-3 h-3 ${stageDef.activeText}`} />
                    </div>
                  )}
                  <div className="min-w-0">
                    <p className="text-xs font-semibold text-slate-700 leading-tight">
                      {row.period}
                    </p>
                    <p className="text-[10px] text-slate-400">
                      {row.total_rows} employees
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2 flex-shrink-0">
                  {stageDef && (
                    <span
                      className={`hidden sm:inline-flex text-[10px] font-medium px-2 py-0.5 rounded-full border ${stageDef.activeBg} ${stageDef.activeText} ${stageDef.activeBorder}`}
                    >
                      {stageDef.label}
                    </span>
                  )}
                  {row.days_in_current_stage != null && (
                    <span
                      className={`text-[10px] font-medium ${
                        isOverdue
                          ? "text-rose-600"
                          : isWarning
                            ? "text-amber-600"
                            : "text-slate-400"
                      }`}
                    >
                      {row.days_in_current_stage}d
                      {row.current_sla_days ? `/${row.current_sla_days}d` : ""}
                    </span>
                  )}
                  {row.pending_role && (
                    <span className="hidden md:inline-flex items-center gap-0.5 text-[10px] text-slate-400">
                      <HeroIcons.UserIcon className="w-3 h-3" />
                      {row.pending_role}
                    </span>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      ) : summary.total > 0 ? (
        <p className="text-xs text-emerald-600 text-center py-3 flex items-center justify-center gap-1.5">
          <HeroIcons.CheckCircleIcon className="w-4 h-4" />
          All payroll files have been released.
        </p>
      ) : (
        <p className="text-xs text-slate-400 text-center py-4">
          No master payroll files yet.
        </p>
      )}
    </div>
  );
}

