              <div className="grid grid-cols-2 gap-3 text-sm">
                <div className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2">
                  <span className="text-slate-600">On-time rate</span>
                  <span className="font-semibold text-slate-900">{punctuality.onTimePct}</span>
                </div>
                <div className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2">
                  <span className="text-slate-600">Full-day rate</span>
                  <span className="font-semibold text-slate-900">{punctuality.fullPct}</span>
                </div>
              </div>
            </div>
          )}
        </Section>
      )}

      {HR_DASHBOARD_SECTIONS.monthRollup && (
        <Section
          title={HR_DASHBOARD_COPY.sectionMonth}
          hint={HR_DASHBOARD_COPY.sectionMonthHint}
          icon="CalendarIcon"
        >
          {monthRollup.employees === 0 ? (
            <div className="py-6 text-center text-sm italic text-slate-500">{HR_DASHBOARD_COPY.emptyMonthly}</div>
          ) : (
            <div className="grid grid-cols-2 gap-3 text-sm">
              <div className="rounded-xl border border-slate-100 bg-slate-50 p-3">
                <div className="text-2xl font-bold text-slate-900">{monthRollup.totalHours.toLocaleString()}</div>
                <div className="mt-0.5 text-[11px] uppercase tracking-wider text-slate-500">Total hours</div>
              </div>
              <div className="rounded-xl border border-slate-100 bg-slate-50 p-3">
                <div className="text-2xl font-bold text-slate-900">{monthRollup.avgHoursPerEmployee}</div>
                <div className="mt-0.5 text-[11px] uppercase tracking-wider text-slate-500">Avg hrs / emp</div>
              </div>
              <div className="rounded-xl border border-blue-100 bg-blue-50 p-3">
                <div className="text-2xl font-bold text-blue-700">{monthRollup.totalFull.toLocaleString()}</div>
                <div className="mt-0.5 text-[11px] uppercase tracking-wider text-blue-600">Full days</div>
              </div>
              <div className="rounded-xl border border-amber-100 bg-amber-50 p-3">
                <div className="text-2xl font-bold text-amber-700">{monthRollup.totalLate.toLocaleString()}</div>
                <div className="mt-0.5 text-[11px] uppercase tracking-wider text-amber-600">Late arrivals</div>
              </div>
            </div>
          )}
        </Section>
      )}

      {HR_DASHBOARD_SECTIONS.leaveRecordsConsolidated && (
        <Section
          title={HR_DASHBOARD_LEAVE_REPORT.title}
          hint={HR_DASHBOARD_LEAVE_REPORT.subtitle}
          icon="ClipboardDocumentListIcon"
          action={
            <button
              type="button"
              onClick={onOpenLeaveRecords}
              className="text-xs font-semibold text-blue-600 hover:text-blue-700 hover:underline focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-600"
            >
              View records
            </button>
          }
        >
          {loadingLeaveRecords ? (
            <div className="flex items-center justify-center gap-2 py-10 text-sm text-slate-500">
              <Icon name="ArrowPathIcon" className="h-4 w-4 animate-spin" />
              Loading leave records...
            </div>
          ) : leaveRecords.length === 0 ? (
            <div className="py-6 text-center text-sm italic text-slate-500">
              No leave records found.
            </div>
          ) : (
            <div className="-my-2 divide-y divide-slate-100">
              {leaveRecords.slice(0, 8).map((record, index) => (
                <LeaveRecordRow key={record.id || index} record={record} />
              ))}
            </div>
          )}
        </Section>
      )}
    </div>
  );
}

export default function HRDashboard() {
  const currentUser = useSelector((state) => state.auth?.user);
  const navigate = useNavigate();
  const notifRef = useRef(null);
  const workforceRequestRef = useRef(false);
  const lifecycleRequestRef = useRef(false);
  const timesheetRequestRef = useRef(false);
  const payrollRequestRef = useRef(false);
  const performanceRequestRef = useRef(false);

  const [workforce, setWorkforce] = useState([]);
  const [live, setLive] = useState(null);
  const [daily, setDaily] = useState(null);
  const [monthly, setMonthly] = useState(null);
  const [performanceReviews, setPerformanceReviews] = useState([]);
  const [lifecycleRequests, setLifecycleRequests] = useState([]);

  // KPI drill-down report — id of the tile that was clicked (null = closed)
  const [reportKpiId, setReportKpiId] = useState(null);

  // Payroll / leave / salary pending data (from 4.2 + 4.3)
  const [pending, setPending] = useState({
    pendingLeave: [],
    pendingLeaveCount: 0,
    pendingOvertime: [],
    pendingOvertimeCount: 0,
    pendingAlerts: [],
    pendingAlertsCount: 0,
    pendingSalary: [],
    pendingSalaryCount: 0,
    pendingSlips: [],
    pendingSlipsCount: 0,
    payrollSummary: null,
  });
  const [notifOpen, setNotifOpen] = useState(false);
  const [loadingPayroll, setLoadingPayroll] = useState(false);

  // ═══════════════════════════════════════════════════════════════════════════
  // SOFT-CODED: Consolidated Leave Records State (for HR Manager dashboard)
  // ═══════════════════════════════════════════════════════════════════════════
  const [allLeaveRecords, setAllLeaveRecords] = useState([]);
  const [filteredLeaveRecords, setFilteredLeaveRecords] = useState([]);
  const [loadingLeaveRecords, setLoadingLeaveRecords] = useState(false);
  const [leaveStatusFilter, setLeaveStatusFilter] = useState("ALL");
  const [leaveTypeFilter, setLeaveTypeFilter] = useState("ALL");
  const [leaveSearchQuery, setLeaveSearchQuery] = useState("");
  const [leaveCurrentPage, setLeaveCurrentPage] = useState(1);
  const [leavePageSize, setLeavePageSize] = useState(25);

  const [loadingWorkforce, setLoadingWorkforce] = useState(true);
  const [loadingLive, setLoadingLive] = useState(true);
  const [workforceError, setWorkforceError] = useState(null);
  const [timesheetError, setTimesheetError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);
  const [autoRefresh, setAutoRefresh] = useState(true);
  const [now, setNow] = useState(new Date());

  // Approval Tracker widget (super-admin only, non-blocking)
  const [trackerData, setTrackerData] = useState(null);
  const userData = currentUser?.user || currentUser;
  const isSuperAdmin = !!(
    userData?.is_staff ||
    userData?.is_superuser ||
    currentUser?.roles?.some(
      (r) => r.code === "super_admin" || r.name === "Super Administrator",
    )
  );

  // Close notif dropdown when clicking outside
  useEffect(() => {
    if (!notifOpen) return;
    const handler = (e) => {
      if (notifRef.current && !notifRef.current.contains(e.target))
        setNotifOpen(false);
    };
    document.addEventListener("mousedown", handler);
    return () => document.removeEventListener("mousedown", handler);
  }, [notifOpen]);

  // ── Fetch workforce (one-time on mount; doesn't need to poll every 30s)
  const loadWorkforce = useCallback(async () => {
    if (workforceRequestRef.current) return;
    workforceRequestRef.current = true;
    setLoadingWorkforce(true);
    setWorkforceError(null);
    try {
      let finalError = null;
      for (let attempt = 0; attempt < 3; attempt += 1) {
        try {
          const resp = await hrCoreService.getWorkforceSummary();
          const raw = Array.isArray(resp?.results)
            ? resp.results
            : Array.isArray(resp)
              ? resp
              : [];
          setWorkforce(raw.map(normalizeEmployee));
          finalError = null;
          break;
        } catch (err) {
          finalError = err;
          if (attempt < 2 && isRetryableWorkforceError(err)) {
            await retryDelay(attempt === 0 ? 1500 : 4000);
          } else {
            break;
          }
        }
      }
      if (finalError) throw finalError;
    } catch (err) {
      console.warn("[HRDashboard] workforce summary load failed", err);
      setWorkforceError(err);
    } finally {
      setLoadingWorkforce(false);
      workforceRequestRef.current = false;
    }
  }, []);

  // Active Onboarding | Offboarding requests shown in Pending Onboarding.
  const loadLifecycleRequests = useCallback(async () => {
    if (lifecycleRequestRef.current) return;
    lifecycleRequestRef.current = true;
    try {
      const response = await apiClient.get(
        "/onboarding/onboarding/command-center-pending/",
      );
      setLifecycleRequests(Array.isArray(response.data) ? response.data : []);
    } catch (err) {
      console.warn("[HRDashboard] lifecycle requests load failed", err);
      setLifecycleRequests([]);
    } finally {
      lifecycleRequestRef.current = false;
    }
  }, []);

  // ── Fetch live + today + month rollup (polled)
  const loadTimesheets = useCallback(async () => {
    if (timesheetRequestRef.current) return;
    timesheetRequestRef.current = true;
    setLoadingLive(true);
    setTimesheetError(null);
    try {
      const [liveResp, dailyResp, monthlyResp] = await Promise.allSettled([
        timesheetService.fetchLive(),
        timesheetService.fetchDaily(),
        timesheetService.fetchMonthly(),
      ]);
      if (liveResp.status === "fulfilled") setLive(liveResp.value);
      if (dailyResp.status === "fulfilled") setDaily(dailyResp.value);
      if (monthlyResp.status === "fulfilled") setMonthly(monthlyResp.value);
      const anyOk =
        liveResp.status === "fulfilled" ||
        dailyResp.status === "fulfilled" ||
        monthlyResp.status === "fulfilled";
      if (!anyOk)
        setTimesheetError(
          liveResp.reason || new Error("Timesheet unavailable"),
        );
      setLastUpdated(new Date());
    } catch (err) {
      console.warn("[HRDashboard] timesheet load failed", err);
      setTimesheetError(err);
    } finally {
      setLoadingLive(false);
      timesheetRequestRef.current = false;
    }
  }, []);

  const loadPerformanceReviews = useCallback(async () => {
    if (performanceRequestRef.current) return;
    performanceRequestRef.current = true;
    try {
      const [submitted, acknowledged] = await Promise.all([
        hrFoundationService.getReviews({ status: "submitted", page_size: 500 }),
        hrFoundationService.getReviews({ status: "acknowledged", page_size: 500 }),
      ]);
      setPerformanceReviews([...submitted, ...acknowledged]);
    } catch (error) {
      console.warn("[HRDashboard] performance reviews load failed", error);
      setPerformanceReviews([]);
    } finally {
      performanceRequestRef.current = false;
    }
  }, []);

  // ── Fetch pending actions from 4.2 Payroll + 4.3 Leave/Salary (polled)
  const loadPayrollData = useCallback(async () => {
    if (
      !HR_DASHBOARD_SECTIONS.pendingActions &&
      !HR_DASHBOARD_SECTIONS.payrollSnapshot
    )
      return;
    if (payrollRequestRef.current) return;
    payrollRequestRef.current = true;
    setLoadingPayroll(true);
    try {
      const [leaveRes, alertsRes, salaryRes, slipsRes, summaryRes, overtimeRes] =
        await Promise.allSettled([
          payrollService.getLeaveRequests({ status__in: "PENDING,RM_APPROVED", page_size: 10 }),
          payrollService.getAuditAlerts({ status: "open", page_size: 10 }),
          payrollService.getPendingSalaryStructures(),
          payrollService.getSalarySlips({
            status: "pending_approval",
            page_size: 10,
          }),
          payrollService.getDashboardSummary(),
          hrCoreService.getOvertimeRequests({ status: "pending" }),
        ]);

      const leaveList =
        leaveRes.status === "fulfilled"
          ? (leaveRes.value?.results ?? leaveRes.value ?? [])
          : [];
      const alertsList =
        alertsRes.status === "fulfilled"
          ? (alertsRes.value?.results ?? alertsRes.value ?? [])
          : [];
      const salaryList =
        salaryRes.status === "fulfilled"
          ? (salaryRes.value?.results ?? Array.isArray(salaryRes.value))
            ? salaryRes.value
            : []
          : [];
      const slipsList =
        slipsRes.status === "fulfilled"
          ? (slipsRes.value?.results ?? slipsRes.value ?? [])
          : [];
      const summary =
        summaryRes.status === "fulfilled" ? summaryRes.value : null;

      const overtimeList = overtimeRes.status === "fulfilled" ? (overtimeRes.value?.results ?? []) : [];
      setPending({
        pendingOvertime: overtimeList,
        pendingOvertimeCount: overtimeRes.status === "fulfilled" ? (overtimeRes.value?.count ?? overtimeList.length) : 0,
        pendingLeave: Array.isArray(leaveList) ? leaveList : [],
        pendingLeaveCount:
          leaveRes.status === "fulfilled"
            ? (leaveRes.value?.count ?? leaveList.length)
            : 0,
        pendingAlerts: Array.isArray(alertsList) ? alertsList : [],
        pendingAlertsCount:
          alertsRes.status === "fulfilled"
            ? (alertsRes.value?.count ?? alertsList.length)
            : 0,
        pendingSalary: Array.isArray(salaryList) ? salaryList : [],
        pendingSalaryCount: Array.isArray(salaryList) ? salaryList.length : 0,
        pendingSlips: Array.isArray(slipsList) ? slipsList : [],
        pendingSlipsCount:
          slipsRes.status === "fulfilled"
            ? (slipsRes.value?.count ?? slipsList.length)
            : 0,
        payrollSummary: summary,
      });
    } catch (err) {
      console.warn("[HRDashboard] payroll data load failed", err);
    } finally {
      setLoadingPayroll(false);
      payrollRequestRef.current = false;
    }
  }, []);

  // ═══════════════════════════════════════════════════════════════════════════
  // SOFT-CODED: Load consolidated leave records for HR Manager dashboard
  // ═══════════════════════════════════════════════════════════════════════════
  const loadAllLeaveRecords = useCallback(async () => {
    if (!HR_DASHBOARD_SECTIONS.leaveRecordsConsolidated) return;
    setLoadingLeaveRecords(true);
    try {
      // Fetch ALL leave records (not just pending) with large page size
      const response = await payrollService.getLeaveRequests({
        page_size: 500,
      });
      const records = Array.isArray(response?.results)
        ? response.results
        : Array.isArray(response)
          ? response
          : [];
      setAllLeaveRecords(records);
    } catch (err) {
      console.warn("[HRDashboard] leave records load failed", err);
      setAllLeaveRecords([]);
    } finally {
      setLoadingLeaveRecords(false);
    }
  }, []);

  // ═══════════════════════════════════════════════════════════════════════════
  // SOFT-CODED: Filter leave records based on status, type, and search query
  // ═══════════════════════════════════════════════════════════════════════════
  useEffect(() => {
    let filtered = [...allLeaveRecords];

    // Filter by status
    if (leaveStatusFilter !== "ALL") {
      filtered = filtered.filter(
        (record) => record.status === leaveStatusFilter,
      );
    }

    // Filter by leave type
    if (leaveTypeFilter !== "ALL") {
      filtered = filtered.filter(
        (record) =>
          (
            record.leave_type_detail?.code ||
            record.leave_type ||
            ""
          ).toLowerCase() === leaveTypeFilter.toLowerCase(),
      );
    }

    // Filter by search query (employee name, reason)
    if (leaveSearchQuery.trim()) {
      const query = leaveSearchQuery.toLowerCase();
      filtered = filtered.filter(
        (record) =>
          (record.employee_name || "").toLowerCase().includes(query) ||
          (record.reason || "").toLowerCase().includes(query),
      );
    }

    setFilteredLeaveRecords(filtered);
    setLeaveCurrentPage(1); // Reset to first page when filters change
  }, [allLeaveRecords, leaveStatusFilter, leaveTypeFilter, leaveSearchQuery]);

  // ── Initial mount
  useEffect(() => {
    loadWorkforce();
    loadLifecycleRequests();
    loadTimesheets();
    loadPerformanceReviews();
    loadPayrollData();
    loadAllLeaveRecords(); // Load consolidated leave records
  }, [
    loadWorkforce,
    loadLifecycleRequests,
    loadTimesheets,
    loadPerformanceReviews,
    loadPayrollData,
    loadAllLeaveRecords,
  ]);

  // ── Auto-refresh timer
  useEffect(() => {
    if (!autoRefresh) return undefined;
    const id = setInterval(() => {
      loadTimesheets();
      loadPayrollData();
      loadLifecycleRequests();
    }, HR_DASHBOARD_POLL_MS);
    return () => clearInterval(id);
  }, [autoRefresh, loadTimesheets, loadPayrollData, loadLifecycleRequests]);

  // ── Live clock for the header
  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(id);
  }, []);

  // ── Approval tracker (DISABLED - feature not implemented yet)
  // useEffect(() => {
  //   if (!isSuperAdmin) return
  //   payrollService.getApprovalTracker()
  //     .then(data => setTrackerData(data))
  //     .catch(() => { /* non-fatal — widget stays hidden */ })
  // }, [isSuperAdmin])

  // ── Derived data (memoised so re-renders stay cheap)
  const ctx = useMemo(
    () => ({ workforce, live, daily, monthly, lifecycleRequests }),
    [workforce, live, daily, monthly, lifecycleRequests],
  );
  const liveFeed = useMemo(() => buildLiveFeed(live), [live]);
  const deptBars = useMemo(
    () => buildDepartmentBreakdown(workforce),
    [workforce],
  );
  const disciplineBars = useMemo(
    () =>
      buildDisciplineBreakdown(workforce)
        .slice(0, 8)
        .map((d) => ({
          label: d.label,
          count: d.count,
          accent: "from-rose-400 to-pink-600",
        })),
    [workforce],
  );
  const statusDist = useMemo(
    () => buildStatusDistribution(workforce),
    [workforce],
  );
  const punctuality = useMemo(
    () => buildTodayPunctuality(daily?.rows),
    [daily],
  );
  const monthRollup = useMemo(() => buildMonthRollup(monthly?.rows), [monthly]);
  const joiners = useMemo(() => buildRecentJoiners(workforce), [workforce]);

  // Derived pending counts (update with each `pending` state change)
  const totalPending = useMemo(() => buildTotalPending(pending), [pending]);
  const payrollKpiValues = useMemo(
    () =>
      HR_DASHBOARD_PAYROLL_KPIS.map((kpi) =>
        kpi.compute({
          pendingLeaveCount: pending.pendingLeaveCount,
          pendingAlertsCount: pending.pendingAlertsCount,
          pendingSalaryCount: pending.pendingSalaryCount,
          pendingSlipsCount: pending.pendingSlipsCount,
          payrollSummary: pending.payrollSummary,
        }),
      ),
    [pending],
  );

  const greeting = getGreeting();
  const userFirstName =
    currentUser?.first_name ||
    (currentUser?.full_name ? currentUser.full_name.split(/\s+/)[0] : "") ||
    "there";

  if (HR_DASHBOARD_SECTIONS.commandCenterLayout) {
    return (
      <>
        <HRCommandCenterView
          workforce={workforce}
          live={live}
          daily={daily}
          monthly={monthly}
          performanceReviews={performanceReviews}
          lifecycleRequests={lifecycleRequests}
          pending={pending}
          joiners={joiners}
          punctuality={punctuality}
          monthRollup={monthRollup}
          totalPending={totalPending}
          autoRefresh={autoRefresh}
          setAutoRefresh={setAutoRefresh}
          now={now}
          loading={loadingWorkforce || loadingLive || loadingPayroll}
          workforceError={workforceError}
          timesheetError={timesheetError}
          lastUpdated={lastUpdated}
          onRetryWorkforce={loadWorkforce}
          onRefresh={() => {
            loadWorkforce();
            loadTimesheets();
            loadPerformanceReviews();
            loadPayrollData();
            loadLifecycleRequests();
          }}
          onOpenReport={setReportKpiId}
          navigate={navigate}
        />
        {reportKpiId && (
          <KpiReportModal
            reportId={reportKpiId}
            ctx={ctx}
            onClose={() => setReportKpiId(null)}
          />
        )}
      </>
    );
  }

  return (
    <div className="min-h-full w-full bg-[#f5f6f8] px-3 py-2 sm:px-4 lg:px-5 xl:px-6">
      <div className="space-y-4">
        {/* ── Header ───────────────────────────────────────────────────── */}
        <header className="flex flex-col gap-3 rounded-lg border border-slate-200 bg-white px-4 py-3 shadow-[0_1px_2px_rgba(15,23,42,0.04)] lg:flex-row lg:items-center lg:justify-between">
          <div>
            <div className="flex items-center gap-3 mb-1">
              <div className="w-10 h-10 rounded-lg bg-[#0f6cbd] text-white flex items-center justify-center shadow-sm">
                <Icon name="IdentificationIcon" className="w-5 h-5" />
              </div>
              <div>
                <div className="mb-0.5 text-[10px] font-semibold uppercase tracking-[0.14em] text-blue-700">
                  Human Resources / Overview
                </div>
                <h1 className="text-xl font-bold text-slate-950 tracking-tight sm:text-2xl">
                  {HR_DASHBOARD_COPY.pageTitle}
                </h1>
                <p className="max-w-3xl text-xs text-slate-500 sm:text-sm">
                  {greeting},{" "}
                  <span className="font-semibold">{userFirstName}</span>.{" "}
                  {HR_DASHBOARD_COPY.pageSubtitle}
                </p>
              </div>
            </div>
          </div>

          <div className="flex items-center gap-2 flex-wrap">
            <div className="hidden px-3 py-1.5 rounded-md bg-slate-50 border border-slate-200 text-xs text-slate-600 font-mono sm:block">
              {formatTime(now)}
            </div>

            {/* ── Notification Bell ─────────────────────────────────── */}
            {HR_DASHBOARD_SECTIONS.pendingActions && (
              <div ref={notifRef} className="relative">
                <button
                  type="button"
                  onClick={() => setNotifOpen((v) => !v)}
                  className="relative flex h-8 w-8 items-center justify-center rounded-md border border-slate-300 bg-white text-slate-600 transition-colors hover:bg-slate-50 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-600"
                  title="Pending actions"
                >
                  <Icon name="BellIcon" className="w-4 h-4" />
                  {totalPending > 0 && (
                    <span className="absolute -top-1.5 -right-1.5 min-w-[18px] h-[18px] flex items-center justify-center rounded-full bg-rose-500 text-[10px] font-bold text-white px-1 shadow">
                      {totalPending > 99 ? "99+" : totalPending}
                    </span>
                  )}
                </button>
                {notifOpen && (
                  <NotifDropdown
                    pending={pending}
                    total={totalPending}
                    navigate={navigate}
                    onClose={() => setNotifOpen(false)}
                  />
                )}
              </div>
            )}

            <button
              type="button"
              onClick={() => setAutoRefresh((v) => !v)}
              className={`h-8 rounded-md border px-3 text-xs font-semibold transition-colors focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 ${
                autoRefresh
                  ? "bg-emerald-50 text-emerald-700 border-emerald-200 hover:bg-emerald-100"
                  : "bg-slate-50 text-slate-600 border-slate-200 hover:bg-slate-100"
              }`}
              title={`Polling every ${Math.round(HR_DASHBOARD_POLL_MS / 1000)}s`}
            >
              <span
                className={`inline-block w-2 h-2 rounded-full mr-1.5 ${
                  autoRefresh ? "bg-emerald-500 animate-pulse" : "bg-slate-400"
                }`}
              />
              {autoRefresh
                ? HR_DASHBOARD_COPY.autoRefreshOn
                : HR_DASHBOARD_COPY.autoRefreshOff}
            </button>
            <button
              type="button"
              onClick={() => {
                loadTimesheets();
                loadPayrollData();
                loadLifecycleRequests();
              }}
              disabled={loadingLive || loadingPayroll}
              className="h-8 rounded-md border border-slate-300 bg-white px-3 text-xs font-semibold text-slate-700 hover:bg-slate-50 focus:outline-none focus-visible:ring-2 focus-visible:ring-blue-600 disabled:opacity-60"
            >
              <Icon
                name="ArrowPathIcon"
                className={`w-3.5 h-3.5 inline mr-1 ${loadingLive || loadingPayroll ? "animate-spin" : ""}`}
              />
              {loadingLive || loadingPayroll
                ? HR_DASHBOARD_COPY.refreshing
                : HR_DASHBOARD_COPY.manualRefresh}
            </button>
            {lastUpdated && (
              <div className="hidden text-[10px] text-slate-500 ml-1 xl:block">
                {HR_DASHBOARD_COPY.lastUpdated}: {formatTime(lastUpdated)}
              </div>
            )}
          </div>
        </header>

        {/* ── Error banners ────────────────────────────────────────────── */}
        {(workforceError || timesheetError) && (
          <div className="space-y-2">
            {workforceError && (
              <div className="flex items-center gap-2 bg-amber-50 border border-amber-200 text-amber-900 rounded-lg p-3 text-sm" role="alert">
                <Icon
                  name="ExclamationTriangleIcon"
                  className="w-5 h-5 flex-shrink-0"
                />
                <span className="flex-1">{workforceErrorMessage(workforceError)}</span>
                <button
                  type="button"
                  onClick={loadWorkforce}
                  disabled={loadingWorkforce}
                  className="inline-flex h-8 shrink-0 items-center gap-1.5 rounded-md border border-amber-300 bg-white px-3 text-xs font-semibold text-amber-900 hover:bg-amber-100 focus:outline-none focus-visible:ring-2 focus-visible:ring-amber-600 disabled:cursor-wait disabled:opacity-60"
                >
                  <Icon
                    name="ArrowPathIcon"
                    className={`h-3.5 w-3.5 ${loadingWorkforce ? "animate-spin" : ""}`}
                  />
                  {loadingWorkforce ? "Retrying…" : "Retry"}
                </button>
              </div>
            )}
            {timesheetError && (
              <div className="flex items-start gap-2 bg-blue-50 border border-blue-200 text-blue-800 rounded-lg p-3 text-sm">
                <Icon
                  name="InformationCircleIcon"
                  className="w-5 h-5 flex-shrink-0"
                />
                <span>{HR_DASHBOARD_COPY.timesheetUnavailable}</span>
              </div>
            )}
          </div>
        )}

        {/* ── KPI tile strip ───────────────────────────────────────────── */}
        <div className="grid grid-cols-2 gap-2 sm:grid-cols-4 xl:grid-cols-8">
          {HR_DASHBOARD_KPIS.map((kpi) => (
            <KpiTile
              key={kpi.id}
              kpi={kpi}
              value={kpi.compute(ctx)}
              onClick={() => setReportKpiId(kpi.id)}
            />
          ))}
        </div>

        {HR_DASHBOARD_SECTIONS.attendanceAtTop && (
          <AttendanceOverviewPanels
            liveFeed={liveFeed}
            punctuality={punctuality}
            monthRollup={monthRollup}
            leaveRecords={allLeaveRecords}
            loadingLeaveRecords={loadingLeaveRecords}
            onOpenLeaveRecords={() => navigate("/hr/leave")}
          />
        )}

        {/* ── KPI drill-down report modal ──────────────────────────────── */}
        {reportKpiId && (
          <KpiReportModal
            reportId={reportKpiId}
            ctx={ctx}
            onClose={() => setReportKpiId(null)}
          />
        )}

        {/* ── Payroll Snapshot KPI strip (secondary row) ───────────────── */}
        {HR_DASHBOARD_SECTIONS.payrollSnapshot && (
          <div>
            <div className="flex items-center justify-between mb-2 px-1">
              <span className="text-xs font-semibold text-slate-500 uppercase tracking-wide">
                {HR_DASHBOARD_COPY.sectionPayrollSnapshot}
              </span>
              {loadingPayroll && (
                <Icon
                  name="ArrowPathIcon"
                  className="w-3.5 h-3.5 text-slate-400 animate-spin"
                />
              )}
            </div>
            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
              {HR_DASHBOARD_PAYROLL_KPIS.map((kpi, idx) => (
                <PayrollKpiTile
                  key={kpi.id}
                  kpi={kpi}
                  value={payrollKpiValues[idx]}
                  onClick={() => navigate("/hr/payroll")}
                />
              ))}
            </div>
          </div>
        )}

        {/* ── Approval Pipeline Tracker (DISABLED - feature not implemented yet) ─────────────── */}
        {/* {isSuperAdmin && trackerData && (
          <ApprovalPipelineWidget
            data={trackerData}
            onViewAll={() => navigate('/hr/payroll')}
          />
        )} */}

        {/* ── Pending Actions inbox ────────────────────────────────────── */}
        {HR_DASHBOARD_SECTIONS.pendingActionsPanel && (
          <div>
            <div className="flex items-center justify-between mb-3">
              <div>
                <h2 className="text-base font-bold text-slate-900">
                  {HR_DASHBOARD_COPY.sectionPending}
                </h2>
                <p className="text-xs text-slate-500">
                  {HR_DASHBOARD_COPY.sectionPendingHint}
                </p>
              </div>
              {totalPending === 0 && (
                <div className="flex items-center gap-1.5 text-emerald-600 text-xs font-semibold bg-emerald-50 border border-emerald-200 px-3 py-1.5 rounded-lg">
                  <Icon name="CheckCircleIcon" className="w-4 h-4" />
                  {HR_DASHBOARD_COPY.emptyPending}
                </div>
              )}
            </div>
            <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
              {HR_DASHBOARD_PENDING_TYPES.map((type) => (
                <PendingActionCard
                  key={type.id}
                  type={type}
                  pending={pending}
                  navigate={navigate}
                />
              ))}
            </div>
          </div>
        )}

        {/* ═══════════════════════════════════════════════════════════════════ */}
        {/* SOFT-CODED: Consolidated Leave Records Report (HR Manager Dashboard) */}
        {/* ═══════════════════════════════════════════════════════════════════ */}
        {HR_DASHBOARD_SECTIONS.leaveRecordsDetailPanel && (
          <div className="bg-white rounded-2xl border border-slate-200 shadow-sm p-6">
            {/* Header */}
            <div
              className={`bg-gradient-to-r ${HR_DASHBOARD_LEAVE_REPORT.accentGradient} rounded-xl p-5 mb-6 text-white`}
            >
              <div className="flex items-center gap-3 mb-3">
                <div className="w-11 h-11 rounded-xl bg-white/20 flex items-center justify-center">
                  <Icon
                    name={HR_DASHBOARD_LEAVE_REPORT.icon}
                    className="w-6 h-6"
                  />
                </div>
                <div>
                  <h2 className="text-xl font-bold">
                    {HR_DASHBOARD_LEAVE_REPORT.title}
                  </h2>
                  <p className="text-sm text-white/80">
                    {HR_DASHBOARD_LEAVE_REPORT.subtitle}
                  </p>
                </div>
              </div>

              {/* Quick Stats */}
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                {HR_DASHBOARD_LEAVE_REPORT.quickStats.map((stat) => {
                  const count =
                    stat.key === "total"
                      ? filteredLeaveRecords.length
                      : stat.key === "pending"
                        ? filteredLeaveRecords.filter(
                            (r) => r.status === "PENDING",
                          ).length
                        : stat.key === "approved"
                          ? filteredLeaveRecords.filter(
                              (r) => r.status === "APPROVED",
                            ).length
                          : stat.key === "rejected"
                            ? filteredLeaveRecords.filter((r) =>
                                ["REJECTED", "RM_REJECTED"].includes(r.status),
                              ).length
                            : 0;
                  return (
                    <div key={stat.key} className="bg-white/10 rounded-lg p-3">
                      <div className="flex items-center gap-2 mb-1">
                        <Icon name={stat.icon} className="w-4 h-4" />
                        <span className="text-xs text-white/70">
                          {stat.label}
                        </span>
                      </div>
                      <div className="text-2xl font-bold">{count}</div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Filters */}
            <div className="flex flex-wrap items-center gap-3 mb-4">
              {/* Search */}
              <div className="relative flex-1 min-w-[200px]">
                <Icon
                  name="MagnifyingGlassIcon"
                  className="w-4 h-4 text-slate-400 absolute left-3 top-1/2 -translate-y-1/2"
                />
                <input
                  type="text"
                  placeholder="Search by employee or reason..."
                  value={leaveSearchQuery}
                  onChange={(e) => setLeaveSearchQuery(e.target.value)}
                  className="w-full pl-9 pr-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
                />
              </div>

              {/* Status Filter */}
              <select
                value={leaveStatusFilter}
                onChange={(e) => setLeaveStatusFilter(e.target.value)}
                className="px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
              >
                {HR_DASHBOARD_LEAVE_REPORT.statusFilters.map((f) => (
                  <option key={f.value} value={f.value}>
                    {f.label}
                  </option>
                ))}
              </select>

              {/* Type Filter */}
              <select
                value={leaveTypeFilter}
                onChange={(e) => setLeaveTypeFilter(e.target.value)}
                className="px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
              >
                {HR_DASHBOARD_LEAVE_REPORT.leaveTypeFilters.map((f) => (
                  <option key={f.value} value={f.value}>
                    {f.label}
                  </option>
                ))}
              </select>

              {/* Page Size */}
              <select
                value={leavePageSize}
                onChange={(e) => setLeavePageSize(Number(e.target.value))}
                className="px-3 py-2 rounded-lg border border-slate-200 text-sm focus:outline-none focus:ring-2 focus:ring-amber-500"
              >
                {HR_DASHBOARD_LEAVE_REPORT.pageSizeOptions.map((size) => (
                  <option key={size} value={size}>
                    {size} per page
                  </option>
                ))}
              </select>
            </div>

            {/* Table */}
            {loadingLeaveRecords ? (
              <div className="text-center py-12 text-slate-500">
                Loading leave records...
              </div>
            ) : filteredLeaveRecords.length === 0 ? (
              <div className="text-center py-12 text-slate-500">
                <Icon
                  name="InboxIcon"
                  className="w-12 h-12 mx-auto mb-2 text-slate-300"
                />
                <p>No leave records found matching your filters</p>
              </div>
            ) : (
              <>
                <div className="overflow-x-auto">
                  <table className="w-full text-sm">
                    <thead>
                      <tr className="border-b border-slate-200">
                        {HR_DASHBOARD_LEAVE_REPORT.columns.map((col) => (
                          <th
                            key={col.key}
                            className={`${col.width} px-3 py-3 text-left text-xs font-semibold text-slate-600 uppercase tracking-wider`}
                          >
                            {col.label}
                          </th>
                        ))}
                      </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-100">
                      {filteredLeaveRecords
                        .slice(
                          (leaveCurrentPage - 1) * leavePageSize,
                          leaveCurrentPage * leavePageSize,
                        )
                        .map((record, idx) => (
                          <tr
                            key={record.id || idx}
                            className="hover:bg-slate-50"
                          >
                            {HR_DASHBOARD_LEAVE_REPORT.columns.map((col) => {
                              const value = record[col.key];
                              if (col.type === "status-badge") {
                                const colors =
                                  HR_DASHBOARD_LEAVE_REPORT.statusColors[
                                    value
                                  ] ||
                                  HR_DASHBOARD_LEAVE_REPORT.statusColors
                                    .PENDING;
                                return (
                                  <td key={col.key} className="px-3 py-3">
                                    <span
                                      className={`inline-flex items-center px-2 py-0.5 rounded-md text-xs font-semibold border ${colors.bg} ${colors.text} ${colors.border}`}
                                    >
                                      {value || "Unknown"}
                                    </span>
                                  </td>
                                );
                              } else if (col.type === "badge") {
                                const leaveTypeKey = (
                                  record.leave_type_detail?.code ||
                                  value ||
                                  "other"
                                ).toLowerCase();
                                const colors =
                                  HR_DASHBOARD_LEAVE_REPORT.leaveTypeColors[
                                    leaveTypeKey
                                  ] ||
                                  HR_DASHBOARD_LEAVE_REPORT.leaveTypeColors
                                    .other;
                                return (
                                  <td key={col.key} className="px-3 py-3">
                                    <span
                                      className={`inline-flex items-center px-2 py-0.5 rounded-md text-xs font-semibold ${colors.bg} ${colors.text}`}
                                    >
                                      {record.leave_type_detail?.name ||
                                        value ||
                                        "Unknown"}
                                    </span>
                                  </td>
                                );
                              } else if (col.type === "date") {
                                return (
                                  <td
                                    key={col.key}
                                    className="px-3 py-3 text-slate-600"
                                  >
                                    {value ? formatDate(value) : "—"}
                                  </td>
                                );
                              } else if (col.type === "datetime") {
                                return (
                                  <td
                                    key={col.key}
                                    className="px-3 py-3 text-slate-600 text-xs"
                                  >
                                    {value
                                      ? new Date(value).toLocaleString()
                                      : "—"}
                                  </td>
                                );
                              } else if (col.type === "number") {
                                return (
                                  <td
                                    key={col.key}
                                    className="px-3 py-3 text-slate-900 font-semibold"
                                  >
                                    {value ?? "—"}
                                  </td>
                                );
                              } else {
                                return (
                                  <td
                                    key={col.key}
                                    className="px-3 py-3 text-slate-600"
                                  >
                                    {value || "—"}
                                  </td>
                                );
                              }
                            })}
                          </tr>
                        ))}
                    </tbody>
                  </table>
                </div>

                {/* Pagination */}
                {filteredLeaveRecords.length > leavePageSize && (
                  <div className="flex items-center justify-between mt-4 pt-4 border-t border-slate-200">
                    <div className="text-sm text-slate-500">
                      Showing {(leaveCurrentPage - 1) * leavePageSize + 1} to{" "}
                      {Math.min(
                        leaveCurrentPage * leavePageSize,
                        filteredLeaveRecords.length,
                      )}{" "}
                      of {filteredLeaveRecords.length} records
                    </div>
                    <div className="flex items-center gap-2">
                      <button
                        onClick={() =>
                          setLeaveCurrentPage((p) => Math.max(1, p - 1))
                        }
                        disabled={leaveCurrentPage === 1}
                        className="px-3 py-1.5 rounded-lg border border-slate-200 text-sm font-medium text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        Previous
                      </button>
                      <span className="text-sm text-slate-600">
                        Page {leaveCurrentPage} of{" "}
                        {Math.ceil(filteredLeaveRecords.length / leavePageSize)}
                      </span>
                      <button
                        onClick={() =>
                          setLeaveCurrentPage((p) =>
                            Math.min(
                              Math.ceil(
                                filteredLeaveRecords.length / leavePageSize,
                              ),
                              p + 1,
                            ),
                          )
                        }
                        disabled={
                          leaveCurrentPage >=
                          Math.ceil(filteredLeaveRecords.length / leavePageSize)
                        }
                        className="px-3 py-1.5 rounded-lg border border-slate-200 text-sm font-medium text-slate-600 hover:bg-slate-50 disabled:opacity-50 disabled:cursor-not-allowed"
                      >
                        Next
                      </button>
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* ── Main grid ────────────────────────────────────────────────── */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
          {/* Live activity feed (spans 1 col, tall) */}
          {!HR_DASHBOARD_SECTIONS.attendanceAtTop && HR_DASHBOARD_SECTIONS.liveFeed && (
            <div className="lg:row-span-2">
              <Section
                title={HR_DASHBOARD_COPY.sectionLive}
                hint={HR_DASHBOARD_COPY.sectionLiveHint}
                icon="SignalIcon"
                action={
                  <span className="inline-flex items-center gap-1 px-2 py-0.5 rounded-md bg-emerald-100 text-emerald-700 text-[10px] font-bold tracking-wider">
                    <span className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-pulse" />
                    {HR_DASHBOARD_COPY.liveBadge}
                  </span>
                }
              >
                {liveFeed.length === 0 ? (
                  <div className="text-sm text-slate-500 italic py-6 text-center">
                    {HR_DASHBOARD_COPY.emptyLive}
                  </div>
                ) : (
                  <div className="divide-y divide-slate-100 -my-2">
                    {liveFeed.map((row, i) => (
                      <LiveFeedRow
                        key={`${row.employee_code || i}-${row.punch_time || i}`}
                        row={row}
                      />
                    ))}
                  </div>
                )}
              </Section>
            </div>
          )}

          {/* Today punctuality */}
          {!HR_DASHBOARD_SECTIONS.attendanceAtTop && HR_DASHBOARD_SECTIONS.todayPunctuality && (
            <Section
              title={HR_DASHBOARD_COPY.sectionToday}
              hint={HR_DASHBOARD_COPY.sectionTodayHint}
              icon="ClockIcon"
            >
              {punctuality.total === 0 ? (
                <div className="text-sm text-slate-500 italic py-6 text-center">
                  {HR_DASHBOARD_COPY.emptyDaily}
                </div>
              ) : (
                <div className="space-y-4">
                  <div className="grid grid-cols-3 gap-3 text-center">
                    <div className="rounded-xl bg-emerald-50 border border-emerald-100 p-3">
                      <div className="text-2xl font-bold text-emerald-700">
                        {punctuality.onTime}
                      </div>
                      <div className="text-[11px] text-emerald-600 uppercase tracking-wider mt-0.5">
                        On time
                      </div>
                    </div>
                    <div className="rounded-xl bg-amber-50 border border-amber-100 p-3">
                      <div className="text-2xl font-bold text-amber-700">
                        {punctuality.late}
                      </div>
                      <div className="text-[11px] text-amber-600 uppercase tracking-wider mt-0.5">
                        Late
                      </div>
                    </div>
                    <div className="rounded-xl bg-blue-50 border border-blue-100 p-3">
                      <div className="text-2xl font-bold text-blue-700">
                        {punctuality.full}
                      </div>
                      <div className="text-[11px] text-blue-600 uppercase tracking-wider mt-0.5">
                        Full day
                      </div>
                    </div>
                  </div>
                  <div className="grid grid-cols-2 gap-3 text-sm">
                    <div className="flex items-center justify-between bg-slate-50 rounded-lg px-3 py-2">
                      <span className="text-slate-600">On-time rate</span>
                      <span className="font-semibold text-slate-900">
                        {punctuality.onTimePct}
                      </span>
                    </div>
                    <div className="flex items-center justify-between bg-slate-50 rounded-lg px-3 py-2">
                      <span className="text-slate-600">Full-day rate</span>
                      <span className="font-semibold text-slate-900">
                        {punctuality.fullPct}
                      </span>
                    </div>
                  </div>
                </div>
              )}
            </Section>
          )}

          {/* Month-to-date */}
          {!HR_DASHBOARD_SECTIONS.attendanceAtTop && HR_DASHBOARD_SECTIONS.monthRollup && (
            <Section
              title={HR_DASHBOARD_COPY.sectionMonth}
              hint={HR_DASHBOARD_COPY.sectionMonthHint}
              icon="CalendarIcon"
            >
