        {/* ── Footer note ─────────────────────────────────────────────── */}
        <div className="text-center text-[11px] text-slate-400 py-2">
          Data sources: Employee Master · biometric timesheet · activity feed —
          auto-refresh every {Math.round(HR_DASHBOARD_POLL_MS / 1000)} seconds
        </div>
      </div>
    </div>
  );
}

