            </div>
            {!embedded && (
              <div className="hidden flex-wrap gap-1.5 px-1 text-[10px] font-medium text-slate-500 sm:flex">
                {[
                  "Employee ID",
                  "Name",
                  "Email",
                  "Department",
                  "Manager",
                  "Location",
                  "Role",
