        {viewMode === "timesheet" && (
          <div className="flex min-h-[38px] flex-1 items-center text-sm text-slate-600">
            Browse attendance using the Time Sheet controls below.
          </div>
        )}

        <div className="flex flex-wrap items-center gap-2">
          {viewMode !== "timesheet" && (
            <button
              type="button"
              onClick={() => setFiltersOpen((o) => !o)}
              className={`relative inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md border ${anim("transition")} ${
                filtersOpen || activeFilterCount > 0
                  ? "bg-blue-50 border-blue-200 text-blue-700"
