const EmployeeQuickActions = ({ emp, onAction, compact = false }) => {
  const [open, setOpen] = useState(false);
  const [menuPosition, setMenuPosition] = useState(null);
  const buttonRef = useRef(null);
  const menuRef = useRef(null);

  const positionMenu = useCallback(() => {
    if (!buttonRef.current) return;

    const trigger = buttonRef.current.getBoundingClientRect();
    const menuWidth = 208;
    const menuHeight = menuRef.current?.offsetHeight || 176;
    const viewportPadding = 8;
    const gap = 6;
    const roomBelow = window.innerHeight - trigger.bottom;
    const openUpward = roomBelow < menuHeight + gap;

    setMenuPosition({
      left: Math.min(
        Math.max(viewportPadding, trigger.right - menuWidth),
        window.innerWidth - menuWidth - viewportPadding,
      ),
      top: openUpward
        ? Math.max(viewportPadding, trigger.top - menuHeight - gap)
        : trigger.bottom + gap,
    });
  }, []);

  useEffect(() => {
    if (!open) {
      setMenuPosition(null);
      return undefined;
    }

    positionMenu();
    const frame = window.requestAnimationFrame(positionMenu);
    const closeOnOutsideClick = (event) => {
      if (
        !buttonRef.current?.contains(event.target) &&
        !menuRef.current?.contains(event.target)
      ) {
        setOpen(false);
      }
    };
    const closeOnEscape = (event) => {
      if (event.key === "Escape") setOpen(false);
    };

    document.addEventListener("mousedown", closeOnOutsideClick);
    document.addEventListener("keydown", closeOnEscape);
    window.addEventListener("resize", positionMenu);
    window.addEventListener("scroll", positionMenu, true);

    return () => {
      window.cancelAnimationFrame(frame);
      document.removeEventListener("mousedown", closeOnOutsideClick);
      document.removeEventListener("keydown", closeOnEscape);
      window.removeEventListener("resize", positionMenu);
      window.removeEventListener("scroll", positionMenu, true);
    };
  }, [open, positionMenu]);

  const menu = open && menuPosition && (
    <div
      ref={menuRef}
      className="fixed z-[1000] grid w-52 grid-cols-2 gap-1 rounded-xl border border-slate-200 bg-white p-2 text-left shadow-2xl"
      style={{ left: menuPosition.left, top: menuPosition.top }}
      role="menu"
      aria-label={`Actions for ${fullName(emp)}`}
      onClick={(event) => event.stopPropagation()}
    >
      {EMPLOYEE_QUICK_ACTIONS.map((action) => (
        <button
          key={action.id}
          type="button"
          role="menuitem"
          onClick={() => {
            setOpen(false);
            onAction(emp, action.id);
          }}
          className={`flex items-center gap-2 rounded-lg px-2.5 py-2 text-xs font-semibold ${action.danger ? "text-rose-700 hover:bg-rose-50" : "text-slate-700 hover:bg-blue-50 hover:text-blue-700"}`}
        >
          <Icon name={action.icon} className="h-4 w-4" /> {action.label}
        </button>
      ))}
    </div>
  );

  return (
    <div className="relative" onClick={(event) => event.stopPropagation()}>
      <button
        ref={buttonRef}
        type="button"
        onClick={() => setOpen((value) => !value)}
        className="inline-flex items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-2.5 py-1.5 text-xs font-semibold text-slate-700 shadow-sm hover:border-blue-300 hover:text-blue-700"
        aria-expanded={open}
        aria-label={`Quick actions for ${fullName(emp)}`}
      >
        <HeroIcons.BoltIcon className="h-4 w-4" />
        {!compact && <span>Quick actions</span>}
        <HeroIcons.ChevronDownIcon className="h-3 w-3" />
      </button>
      {menu && createPortal(menu, document.body)}
    </div>
  );
};

const probationSummary = (employee) => {
  const joinedValue = employee?.join_date || employee?.created_at;
  if (!joinedValue) return null;
  const joined = new Date(`${String(joinedValue).slice(0, 10)}T00:00:00Z`);
  if (Number.isNaN(joined.getTime())) return null;
  let probationEnd;
  if (employee?.probation_end_date) {
    probationEnd = new Date(`${String(employee.probation_end_date).slice(0, 10)}T00:00:00Z`);
  } else {
    const targetMonth = joined.getUTCMonth() + 6;
    const targetYear = joined.getUTCFullYear() + Math.floor(targetMonth / 12);
    const normalizedMonth = targetMonth % 12;
    const lastDay = new Date(Date.UTC(targetYear, normalizedMonth + 1, 0)).getUTCDate();
    probationEnd = new Date(Date.UTC(targetYear, normalizedMonth, Math.min(joined.getUTCDate(), lastDay)));
  }
  const now = new Date();
  const today = new Date(Date.UTC(now.getFullYear(), now.getMonth(), now.getDate()));
  if (today < joined) return { label: 'Probation not started', tone: 'bg-slate-100 text-slate-600', end: probationEnd };
  const daysLeft = Math.ceil((probationEnd - today) / 86400000);
  if (daysLeft <= 0) return { label: 'Probation completed', tone: 'bg-emerald-100 text-emerald-700', end: probationEnd };
  const remaining = daysLeft > 45 ? `${Math.ceil(daysLeft / 30.4375)} months left` : `${daysLeft} days left`;
  return { label: `In probation period · ${remaining}`, tone: 'bg-amber-100 text-amber-700', end: probationEnd };
};

