const CEO_TITLE_RE = /\b(ceo|chief executive(?: officer)?|managing director)\b/i;

const empDisplayTitle = (emp) =>
  emp.job_title || emp.position || emp.designation || emp.title || "";

const countSubtree = (node) =>
