      return (
        <span className={`inline-flex items-center px-2 py-1 rounded-full text-xs font-medium border ${statusCfg.color}`}>
          {statusCfg.label}
        </span>
      )
    },
  },
  {
    id: 'progress',
    label: 'Progress',
    field: 'progress_percentage',
