  )
}

import React, { useEffect, useRef, useState } from 'react'
import { Navigate, useSearchParams } from 'react-router-dom'
import { ClockIcon, PlusIcon, XMarkIcon } from '@heroicons/react/24/outline'
import service from '../../services/hrCore.service'
import { radaiConfirm } from '../../services/radaiDialog'

const errorText = (error) => {
  const data = error?.response?.data
  return typeof data === 'string' ? data : data ? Object.values(data).flat().join(' ') : error.message || 'Please try again.'
}
const statusText = (item) => item.status === 'pending' ? (item.stage_code === 'manager_review' ? 'Awaiting manager' : 'Awaiting HR / Finance') : item.status.charAt(0).toUpperCase() + item.status.slice(1)
const formatAED = value => `AED ${Number(value).toLocaleString('en-AE', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`
const fieldClass = 'w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm focus:border-indigo-400 focus:outline-none focus:ring-2 focus:ring-indigo-100'

function RequestDialog({ employees, onClose, onCreated }) {
  const dialog = useRef(null)
  const lock = useRef(false)
  const [form, setForm] = useState({ employee: employees.find(e => e.is_self)?.id || employees[0]?.id || '', reason: '', compensation_type: 'cash' })
  const [selectedDays, setSelectedDays] = useState({})
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  useEffect(() => { const el = dialog.current; const prior = document.activeElement; el.showModal(); return () => { el.close(); prior?.focus() } }, [])
  const submit = async (event) => {
    event.preventDefault()
    if (lock.current) return
    lock.current = true; setBusy(true); setError('')
    try { const result = await service.createOvertimeDays({ ...form, days: Object.entries(selectedDays).map(([work_date, requested_hours]) => ({ work_date, requested_hours })) }); onCreated(result.results[0]) }
    catch (failure) { setError(errorText(failure)); lock.current = false; setBusy(false) }
  }
  const [days, setDays] = useState([])
  const [daysLoading, setDaysLoading] = useState(false)
  useEffect(() => {
    let active = true
    setDays([]); setDaysLoading(true); setError('')
    setSelectedDays({})
    service.getOvertimeDays(form.employee).then(data => { if (active) setDays(data.days || []) })
      .catch(failure => { if (active) setError(errorText(failure)) })
      .finally(() => { if (active) setDaysLoading(false) })
    return () => { active = false }
  }, [form.employee])

  const change = (key) => (event) => setForm(old => ({ ...old, [key]: event.target.value }))
  return <dialog ref={dialog} aria-labelledby="ot-create-title" onCancel={(e) => { e.preventDefault(); if (!busy) onClose() }} className="m-auto w-[calc(100%-2rem)] max-w-lg rounded-2xl border border-slate-200 bg-white p-0 shadow-xl backdrop:bg-slate-900/40">
    <form onSubmit={submit}>
      <header className="flex items-center justify-between border-b border-slate-200 bg-indigo-50/50 px-5 py-4"><h2 id="ot-create-title" className="text-base font-semibold">Request overtime</h2><button type="button" disabled={busy} onClick={onClose} aria-label="Close overtime request"><XMarkIcon className="h-5 w-5" /></button></header>
      <div className="space-y-4 p-5">
        <label className="block text-sm">Employee<select autoFocus required value={form.employee} onChange={change('employee')} className={fieldClass}>{employees.map(e => <option key={e.id} value={e.id}>{e.name} ({e.code})</option>)}</select></label>
        <fieldset disabled={busy || daysLoading} className="space-y-2">
          <legend className="mb-2 text-sm">Recorded OT days</legend>
          <div className="max-h-60 space-y-2 overflow-y-auto rounded-lg border border-slate-200 p-3">
            {daysLoading ? <p className="text-sm text-slate-500">Loading timesheet...</p> : !days.length ? <p className="text-sm text-slate-500">No available OT days</p> : days.map(day => <div key={day.date} className="flex items-center justify-between gap-3">
              <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={day.date in selectedDays} disabled={!(day.date in selectedDays) && Object.keys(selectedDays).length >= 31} onChange={e => setSelectedDays(old => { const next = { ...old }; if (e.target.checked) next[day.date] = String(Math.min(24, Number(day.overtime_hours))); else delete next[day.date]; return next })} />{day.date} / {Number(day.overtime_hours)} OT hours</label>
              {day.date in selectedDays && <input aria-label={`Hours for ${day.date}`} required type="number" min="0.01" max={Math.min(24, Number(day.overtime_hours))} step="0.01" value={selectedDays[day.date]} onChange={e => setSelectedDays(old => ({ ...old, [day.date]: e.target.value }))} className="w-24 rounded-lg border border-slate-300 px-2 py-1 text-sm" />}
            </div>)}
          </div>
          {!!Object.keys(selectedDays).length && <p className="text-sm text-indigo-700">{Object.keys(selectedDays).length} days / {Object.values(selectedDays).reduce((sum, hours) => sum + Number(hours), 0).toFixed(2)} hours</p>}
        </fieldset>
        <label className="block text-sm">Type<select value={form.compensation_type} onChange={change('compensation_type')} className={fieldClass}><option value="cash">Encashment</option><option value="day_off">Off day</option></select></label><label className="block text-sm">Reason<textarea required rows={3} value={form.reason} onChange={change('reason')} className={fieldClass} /></label>
        {error && <p role="alert" className="text-sm text-rose-700">{error}</p>}
      </div>
      <footer className="flex justify-end gap-2 border-t border-slate-200 px-5 py-4"><button type="button" disabled={busy} onClick={onClose} className="rounded-lg border border-slate-300 px-4 py-2 text-sm">Cancel</button><button disabled={busy || daysLoading || !Object.keys(selectedDays).length} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-medium text-white disabled:opacity-50">{busy ? 'Submitting...' : 'Submit request'}</button></footer>
    </form>
  </dialog>
}

function BenefitDialog({ item, onClose, onApplied }) {
  const dialog = useRef(null)
  const lock = useRef(false)
  const [type, setType] = useState(item.compensation_type || '')
  const [period, setPeriod] = useState(new Date().toISOString().slice(0, 7))
  const [multiplier, setMultiplier] = useState('1.25')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  useEffect(() => { const el = dialog.current; const prior = document.activeElement; el.showModal(); return () => { el.close(); prior?.focus() } }, [])
  const submit = async event => {
    event.preventDefault()
    if (lock.current) return
    lock.current = true; setBusy(true); setError('')
    try {
      const [year, month] = period.split('-').map(Number)
      onApplied(await service.applyOvertimeBenefit(item.id, { type, year, month, multiplier }))
    } catch (failure) { setError(errorText(failure)) }
    finally { lock.current = false; setBusy(false) }
  }
  return <dialog ref={dialog} onCancel={event => { event.preventDefault(); if (!busy) onClose() }} aria-labelledby="ot-benefit-title" className="m-auto w-[calc(100%-2rem)] max-w-md rounded-2xl border border-slate-200 bg-white p-0 shadow-xl backdrop:bg-slate-900/40">
    <form onSubmit={submit}>
      <header className="border-b border-slate-200 bg-indigo-50/40 p-5"><h2 id="ot-benefit-title" className="font-semibold">Apply approved OT</h2><p className="mt-1 text-sm">{item.employee_name} / {Number(item.approved_hours)} hours</p></header>
      <div className="space-y-4 p-5">
        <label className="block text-sm">Type<select required disabled={!!item.compensation_type} value={type} onChange={e => setType(e.target.value)} className={fieldClass}><option value="">Select type</option><option value="cash">Encashment</option><option value="day_off">Off day</option></select></label>
        <label className="block text-sm">{type === 'day_off' ? 'Credit period' : 'Payroll month'}<input required type="month" min={type === 'cash' ? new Date().toISOString().slice(0, 7) : '2000-01'} max="2100-12" value={period} onChange={e => setPeriod(e.target.value)} className={fieldClass} /></label>
        {type === 'cash' && <label className="block text-sm">OT multiplier<select value={multiplier} onChange={e => setMultiplier(e.target.value)} className={fieldClass}><option value="1.25">1.25x</option><option value="1.50">1.50x</option></select></label>}
        {type === 'day_off' && <p className="text-sm text-indigo-700">{Number(item.approved_hours) / 8} days added to annual leave</p>}
        {error && <p role="alert" className="text-sm text-rose-700">{error}</p>}
      </div>
      <footer className="flex justify-end gap-2 border-t border-slate-200 p-4"><button type="button" disabled={busy} onClick={onClose} className="rounded-lg border px-4 py-2 text-sm">Cancel</button><button disabled={busy || !type} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm text-white disabled:opacity-40">{busy ? 'Applying...' : type === 'day_off' ? 'Add to annual leave' : 'Apply to monthly run'}</button></footer>
    </form>
  </dialog>
}

export default function OvertimeManagement({ reviewOnly = false }) {
  const [params] = useSearchParams()
  const [employees, setEmployees] = useState([])
  const [rows, setRows] = useState([])
  const [count, setCount] = useState(0)
  const [page, setPage] = useState(1)
  const [search, setSearch] = useState('')
  const [status, setStatus] = useState(() => params.get('ot_status') === 'pending' ? 'pending' : '')
  const [selected, setSelected] = useState(null)
  const [applying, setApplying] = useState(null)
  const [creating, setCreating] = useState(false)
  const [revision, setRevision] = useState(0)
  const [loading, setLoading] = useState(true)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [note, setNote] = useState('')
  const lock = useRef(false)
  useEffect(() => { if (reviewOnly) return; let active = true; service.getOvertimeEmployees().then(data => { if (active) setEmployees(data.employees || []) }).catch(e => { if (active) setError(errorText(e)) }); return () => { active = false } }, [reviewOnly])
  useEffect(() => {
    let active = true
    setLoading(true)
    const timer = setTimeout(() => service.getOvertimeRequests({ page, search, scope: reviewOnly ? undefined : 'mine', status: status || undefined }).then(data => {
      if (!active) return
      setRows(data.results || []); setCount(data.count || 0)
      if (!params.get('request')) setSelected(old => old || data.results?.[0] || null)
    }).catch(e => { if (active) setError(errorText(e)) }).finally(() => { if (active) setLoading(false) }), 250)
    return () => { active = false; clearTimeout(timer) }
  }, [page, search, status, revision, reviewOnly])
  useEffect(() => {
    const id = params.get('request'); let active = true
    if (id) service.getOvertimeRequest(id, { scope: reviewOnly ? undefined : 'mine' }).then(data => { if (active) setSelected(data) }).catch(e => { if (active) setError(errorText(e)) })
    return () => { active = false }
  }, [params, reviewOnly])
  const review = async (action) => {
    if (!reviewOnly || lock.current) return
    if (action === 'reject' && !note.trim()) { setError('Enter a rejection reason.'); return }
    lock.current = true; setBusy(true); setError('')
    try {
      if (!(await radaiConfirm(`${action === 'approve' ? 'Approve' : action === 'reject' ? 'Reject' : 'Cancel'} overtime for ${selected.employee_name}?`))) return
      const updated = await service.reviewOvertimeRequest(selected.id, action, note)
      setSelected(updated); setNote(''); setRevision(v => v + 1)
    } catch (failure) { setError(errorText(failure)) }
    finally { lock.current = false; setBusy(false) }
  }
  const pages = Math.max(1, Math.ceil(count / 10))
  return <div className="space-y-4 text-slate-900">
    <div className={reviewOnly ? "hidden" : "flex items-center justify-between gap-3"}><h2 className="flex items-center gap-2 text-lg font-semibold"><ClockIcon className="h-5 w-5 text-indigo-600" />Overtime</h2>{!reviewOnly && <button disabled={!employees.length} onClick={() => setCreating(true)} className="inline-flex items-center gap-2 rounded-lg bg-indigo-600 px-3 py-2 text-sm font-medium text-white disabled:opacity-40"><PlusIcon className="h-4 w-4" />Request OT</button>}</div>
    {error && <p role="alert" className="rounded-lg bg-rose-50 p-3 text-sm text-rose-700">{error}</p>}
    <div className="grid min-w-0 items-start gap-5 xl:grid-cols-2">
      <section className="min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white">
        <div className="flex flex-wrap items-center gap-3 border-b border-slate-200 p-5"><h2 className="text-base font-semibold">{reviewOnly ? 'All OT requests' : 'My OT requests'}</h2><input aria-label="Search overtime requests" placeholder="Search name or employee ID" value={search} onChange={e => { setSearch(e.target.value); setPage(1) }} className={`${fieldClass} min-w-0 flex-1`} /><select aria-label="Overtime status" value={status} onChange={e => { setStatus(e.target.value); setPage(1) }} className="rounded-lg border border-slate-300 px-3 py-2 text-sm"><option value="">All requests</option><option value="pending">Awaiting approval</option><option value="approved">Approved</option><option value="rejected">Rejected</option><option value="cancelled">Cancelled</option></select></div>
        <table className="w-full table-fixed text-left text-sm"><thead className="bg-slate-50 text-sm text-slate-500"><tr>{['Date', 'EmpID', 'Name', 'Requested hours', 'Type', reviewOnly ? 'Action' : 'Status'].map(title => <th key={title} className="p-3 font-medium">{title}</th>)}</tr></thead><tbody>{rows.map(row => <tr key={row.id} className={`border-t border-slate-100 ${selected?.id === row.id ? 'bg-indigo-50' : ''}`}><td className="break-words p-3">{row.work_date}{row.day_entries?.length > 1 && <span className="block text-xs text-slate-500">{row.day_entries.length} days</span>}</td><td className="break-words p-3">{row.employee_code}</td><td className="break-words p-3"><button onClick={() => { setSelected(row); setNote(''); setError('') }} className="text-left font-medium text-indigo-600">{row.employee_name}</button></td><td className="p-3">{Number(row.requested_hours)}</td><td className="break-words p-3">{row.compensation_type === 'cash' ? 'Encashment' : row.compensation_type === 'day_off' ? 'Off day' : 'Not selected'}</td><td className="break-words p-3">{row.application ? <span className="text-emerald-700">{row.application.method === 'cash' ? <>Applied to payroll<span className="block font-medium">{formatAED(row.application.amount)}</span></> : 'Added to annual leave'}</span> : reviewOnly && row.can_apply ? <button onClick={() => setApplying(row)} className="text-left font-medium text-indigo-600">{row.compensation_type === 'day_off' ? 'Add to annual leave' : 'Apply'}</button> : <span className="text-slate-500">{statusText(row)}</span>}</td></tr>)}</tbody></table>
        {loading ? <p className="p-5 text-sm text-slate-500">Loading...</p> : !rows.length && <p className="p-5 text-sm text-slate-500">No overtime requests.</p>}
        <footer className="flex items-center justify-between gap-2 border-t border-slate-200 p-3 text-xs text-slate-500"><span>{count} requests</span><div className="flex items-center gap-2"><button disabled={page <= 1 || loading} onClick={() => setPage(p => p - 1)} className="rounded-lg border px-2 py-1.5 disabled:opacity-40">Previous</button><span>{page} / {pages}</span><button disabled={page >= pages || loading} onClick={() => setPage(p => p + 1)} className="rounded-lg border px-2 py-1.5 disabled:opacity-40">Next</button></div></footer>
      </section>
      {selected && <section className="min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white"><header className="flex items-center gap-3 border-b border-slate-200 bg-indigo-50/30 p-5"><ClockIcon className="h-6 w-6 text-indigo-600" /><h2 className="text-base font-semibold">OT request</h2></header><div className="p-6">
        <div className="flex justify-between gap-3"><div><h3 className="text-base font-semibold">{selected.employee_name}</h3><p className="text-sm text-slate-500">{selected.employee_code}</p></div><button aria-label="Close overtime details" onClick={() => setSelected(null)} disabled={busy}><XMarkIcon className="h-5 w-5" /></button></div>
        <div className="my-5 grid grid-cols-2 gap-3 rounded-xl border border-indigo-100 bg-indigo-50/40 p-4 text-sm"><span>{selected.work_date}</span><span>{Number(selected.requested_hours)} hours</span><span className="col-span-2 text-indigo-700">{statusText(selected)}</span></div>
        {selected.application && <p className="mb-4 rounded-lg bg-emerald-50 p-3 text-sm text-emerald-700">{selected.application.method === 'cash' ? `Payroll ${selected.application.year}-${String(selected.application.month).padStart(2, '0')}: ${formatAED(selected.application.amount)}` : `${Number(selected.application.days)} days added to annual leave (${selected.application.year})`}</p>}
        {!!selected.day_entries?.length && <table className="mb-5 w-full text-left text-sm"><thead><tr className="border-b border-slate-200 text-slate-500"><th className="py-2 font-medium">Date</th><th className="py-2 text-right font-medium">Hours</th></tr></thead><tbody>{selected.day_entries.map(day => <tr key={day.work_date} className="border-b border-slate-100"><td className="py-2">{day.work_date}</td><td className="py-2 text-right">{Number(day.requested_hours)}</td></tr>)}</tbody></table>}
        <h3 className="mb-3 text-sm font-semibold">Request details</h3><p className="whitespace-pre-wrap break-words text-sm">{selected.reason}</p>
        <p className="mt-3 text-xs text-slate-500">Requested by {selected.requested_by_name}</p>
        <h3 className="mt-6 border-t border-slate-100 pt-5 text-sm font-semibold">Approval progress</h3><ol className="my-4 space-y-3">{(selected.history || []).map((event, i) => <li key={i} className="text-sm"><span className="capitalize">{event.action}</span> / {event.actor}<span className="block text-xs text-slate-500">{new Date(event.at).toLocaleString()}</span>{event.note && <p className="whitespace-pre-wrap">{event.note}</p>}</li>)}</ol>
        {reviewOnly && selected.can_review && <label className="block text-sm">Note<textarea rows={2} value={note} onChange={e => setNote(e.target.value)} className={fieldClass} /></label>}
        <div className="mt-3 flex gap-2">{reviewOnly && selected.can_review && <><button disabled={busy} onClick={() => review('approve')} className="rounded-lg bg-indigo-600 px-4 py-2 text-sm text-white disabled:opacity-50">Approve</button><button disabled={busy} onClick={() => review('reject')} className="rounded-lg border border-rose-200 px-4 py-2 text-sm text-rose-700 disabled:opacity-50">Reject</button></>}{reviewOnly && selected.can_cancel && <button disabled={busy} onClick={() => review('cancel')} className="rounded-lg border border-slate-300 px-4 py-2 text-sm disabled:opacity-50">Cancel request</button>}</div>
      </div></section>}
    </div>
    {applying && <BenefitDialog item={applying} onClose={() => setApplying(null)} onApplied={item => { setApplying(null); setSelected(item); setRevision(v => v + 1) }} />}
    {creating && <RequestDialog employees={employees} onClose={() => setCreating(false)} onCreated={item => { setCreating(false); setSelected(item); setPage(1); setRevision(v => v + 1) }} />}
  </div>
}

export function OvertimeReviewPage() {
  const [params] = useSearchParams()
  const next = new URLSearchParams(params)
  next.set('view', 'encashment')
  return <Navigate replace to={`/hr/leave?${next}`} />
}

/**
 * Payroll Intelligence Platform — Main Shell
 * Route: /hr/payroll
 *
 * Tab container for all 6 payroll modules.
 * Hoists shared state (activeRunId, selectedEmployee) and passes down as props.
 * 
 * Notification Integration:
 *   When user clicks a workflow notification, they're navigated here with ?run=<id>
 *   The component auto-switches to the "engine" tab and selects that payroll run.
 */
import './payroll/radaiPayroll.css'
import { useState, useEffect, useCallback } from 'react'
import { useSelector } from 'react-redux'
import { Navigate, useSearchParams } from 'react-router-dom'
import * as HeroIcons from '@heroicons/react/24/outline'
import {
  PAYROLL_TABS,
  PAYROLL_DEFAULT_TAB,
} from '../../config/hrPayroll.config'

// Lazy-import modules (all exist in the payroll/ subfolder)
import PayrollDashboard      from './payroll/PayrollDashboard'
import AttendanceDashboard   from './payroll/AttendanceDashboard'
import LeaveDashboard        from './payroll/LeaveDashboard'
import ApprovalTracker       from './payroll/ApprovalTracker'

const TAB_COMPONENTS = {
  dashboard:  PayrollDashboard,
  attendance: AttendanceDashboard,
  leave:      LeaveDashboard,
  engine:     PayrollDashboard,
  salary:     PayrollDashboard,
  tracker:    ApprovalTracker,
}

export default function Payroll({ module = 'payroll' }) {
  const [searchParams, setSearchParams] = useSearchParams()
  const [activeTab,    setActiveTab]    = useState(module === 'payroll' ? PAYROLL_DEFAULT_TAB : module)
  const [activeRunId,  setActiveRunId]  = useState(null)

  // ── Notification deep-link handling ────────────────────────────────────────
  // When user clicks a workflow notification, auto-switch to engine tab and select the run
  useEffect(() => {
    if (module !== 'payroll') { setActiveTab(module); setActiveRunId(null); return }
    const runIdFromUrl = searchParams.get('run')
    const tabFromUrl = searchParams.get('tab')
    if (runIdFromUrl) {
      setActiveRunId(runIdFromUrl)
      setActiveTab('salary')
      console.log(`[Payroll] Notification deep-link detected: run=${runIdFromUrl}, switching to Salary Management`)
    } else {
      // `engine` was the former top-level route. Keep bookmarks and
      // notifications working while presenting one canonical workspace.
      const canonicalTab = tabFromUrl === 'engine' ? 'salary' : tabFromUrl
      if (canonicalTab && PAYROLL_TABS.some((tab) => tab.id === canonicalTab)) {
        setActiveTab(canonicalTab)
        if (tabFromUrl === 'engine') {
          const next = new URLSearchParams(searchParams)
          next.set('tab', 'salary')
          setSearchParams(next, { replace: true })
        }
      }
    }
  }, [searchParams, setSearchParams, module])

  const selectTab = useCallback((tabId) => {
    const canonicalTab = tabId === 'engine' ? 'salary' : tabId
    setActiveTab(canonicalTab)
    if (canonicalTab !== 'salary') setActiveRunId(null)
    const next = new URLSearchParams(searchParams)
    next.set('tab', canonicalTab)
    if (canonicalTab !== 'salary') next.delete('run')
    setSearchParams(next, { replace: true })
  }, [searchParams, setSearchParams])

  // ── Role-based tab visibility ────────────────────────────────────────────
  const rbacUser   = useSelector(s => s.rbac?.currentUser)
  const authUser   = useSelector(s => s.auth?.user)
  const isHRManager = (
    authUser?.is_staff ||
    authUser?.is_superuser ||
    rbacUser?.roles?.some(r =>
      r.code?.startsWith('hr') || ['admin', 'superadmin', 'super_admin'].includes(r.code)
    )
  ) ?? false
  // Approval Tracker is restricted to super-admins and platform admins
  const isSuperAdmin = (
    authUser?.is_superuser ||
    rbacUser?.roles?.some(r => ['admin', 'superadmin', 'super_admin'].includes(r.code))
  ) ?? false
  const visibleTabs = PAYROLL_TABS.filter(tab =>
    tab.id !== 'salary' && (!tab.hrOnly || isHRManager) && (!tab.adminOnly || isSuperAdmin)
  )

  const [headerActions, setHeaderActions] = useState(null)
  const effectiveTab = module === 'payroll' ? activeTab : module
  const ActiveModule = TAB_COMPONENTS[effectiveTab]
  const title = module === 'attendance' ? 'Attendance Management' : module === 'leave' ? 'Leave Management' : 'Payroll Management'
  const ModuleIcon = module === 'attendance' ? HeroIcons.ClipboardDocumentCheckIcon : module === 'leave' ? HeroIcons.CalendarDaysIcon : HeroIcons.BanknotesIcon
  const legacyTab = searchParams.get('tab')?.replace(/,$/, '')
  if (module === 'payroll' && ['attendance', 'leave'].includes(legacyTab)) {
    const remaining = new URLSearchParams(searchParams)
    remaining.delete('tab')
    return <Navigate to={{ pathname: `/hr/${legacyTab}`, search: remaining.toString() }} replace />
  }

  return (
    <div className={`min-h-screen bg-slate-50 ${module === 'attendance' ? 'attendance-page' : ''}`}>
      {module === 'attendance' && <h1 className="sr-only">Attendance Management</h1>}
      {/* Page Header */}
      {module !== 'attendance' && <div className="border-b border-slate-200 bg-white">
        <div className="px-4 py-5 sm:px-6 lg:px-8">
          <div className="flex flex-wrap items-center justify-between gap-4">
            <div>
              <h1 className="flex items-center gap-3 text-xl font-semibold tracking-tight text-slate-900">
                <span className="rounded-lg border border-indigo-100 bg-indigo-50 p-2"><ModuleIcon className="h-5 w-5 text-indigo-600" /></span>
                {title}
              </h1>
            </div>
            {module === 'leave' && <div ref={setHeaderActions} />}

          </div>

          {/* Tab Navigation */}
          {module === 'payroll' && visibleTabs.length > 1 && <div className="mt-4 flex flex-wrap gap-1 rounded-lg bg-slate-50 p-1">
            {visibleTabs.map((tab) => {
              const Icon = HeroIcons[tab.icon] || HeroIcons.ChartBarIcon
              const isActive = activeTab === tab.id
              return (
                <button
                  key={tab.id}
                  type="button"
                  onClick={() => selectTab(tab.id)}
                  title={tab.description}
                  className={`flex min-w-0 items-center gap-2 rounded-lg border px-3 py-2 text-sm font-medium transition-all ${
                    isActive
                      ? 'border-indigo-200 bg-white text-indigo-700 shadow-sm'
                      : 'border-transparent bg-transparent text-slate-600 hover:bg-white hover:text-indigo-700'
                  }`}
                >
                  <span className={`flex h-5 w-5 shrink-0 items-center justify-center ${isActive ? 'text-indigo-600' : 'text-slate-400'}`}><Icon className="h-4 w-4" /></span>
                  <span className="truncate">{tab.label}</span>
                </button>
              )
            })}
          </div>}
        </div>
      </div>}

      {/* Module Content */}
      <div className={`px-4 py-5 sm:px-6 lg:px-8 ${effectiveTab !== 'dashboard' ? 'radai-payroll-module' : ''} ${module === 'attendance' ? 'attendance-page-content' : ''}`}>
        {ActiveModule ? (
          <ActiveModule
            headerActions={headerActions}
            activeRunId={activeRunId}
            initialTab={activeTab === 'salary' && !activeRunId ? 'employees' : undefined}
            onSelectRun={(run) => {
              const id = typeof run === 'string' ? run : run?.id
              setActiveRunId(id)
            }}
            onSwitchTab={selectTab}
          />
        ) : (
          <div className="bg-white rounded-xl border border-slate-200 p-14 text-center text-slate-400">
            <HeroIcons.CpuChipIcon className="w-12 h-12 mx-auto mb-2 opacity-30" />
            <p>Module not found</p>
          </div>
        )}
      </div>
    </div>
  )
}

import { radaiConfirm } from '../../services/radaiDialog'
/**
 * Site Visit Tracking Page
 * GPS-based attendance for off-site engineers
 * Phase 1 MVP: Request + GPS Check-In/Out
 */

import React, { useState, useEffect } from 'react';
import {
  MapPinIcon,
  ClockIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowPathIcon,
  PlusIcon,
  CameraIcon,
} from '@heroicons/react/24/outline';
import siteVisitService from '../../services/siteVisit.service';

const SiteVisits = () => {
  const [activeTab, setActiveTab] = useState('check-in'); // check-in, requests, history
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  // State for sites
  const [sites, setSites] = useState([]);
  const [selectedSite, setSelectedSite] = useState(null);

  // State for GPS
  const [gpsPosition, setGpsPosition] = useState(null);
  const [gpsLoading, setGpsLoading] = useState(false);
  const [gpsError, setGpsError] = useState('');

  // State for check-ins
  const [activeCheckIn, setActiveCheckIn] = useState(null);
  const [checkInHistory, setCheckInHistory] = useState([]);

  // State for requests
  const [requests, setRequests] = useState([]);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [requestForm, setRequestForm] = useState({
    site_id: '',
    start_date: '',
    end_date: '',
    purpose: '',
  });

  // ═══════════════════════════════════════════════════════════════════════════
  // INITIALIZATION
  // ═══════════════════════════════════════════════════════════════════════════

  useEffect(() => {
    loadSites();
    loadActiveCheckIn();
  }, []);

  useEffect(() => {
    if (activeTab === 'requests') {
      loadRequests();
    } else if (activeTab === 'history') {
      loadCheckInHistory();
    }
  }, [activeTab]);

  const loadSites = async () => {
    try {
      const data = await siteVisitService.getSites(true);
      setSites(data);
    } catch (err) {
      console.error('Failed to load sites:', err);
    }
  };

  const loadActiveCheckIn = async () => {
    try {
      const data = await siteVisitService.getActiveSiteVisits();
      if (data && data.length > 0) {
        setActiveCheckIn(data[0]); // Get the first active check-in
      }
    } catch (err) {
      console.error('Failed to load active check-in:', err);
    }
  };

  const loadRequests = async () => {
    try {
      setLoading(true);
      const data = await siteVisitService.getMyRequests();
      setRequests(data);
    } catch (err) {
      setError('Failed to load requests');
    } finally {
      setLoading(false);
    }
  };

  const loadCheckInHistory = async () => {
    try {
      setLoading(true);
      const data = await siteVisitService.getMyCheckIns();
      setCheckInHistory(data);
    } catch (err) {
      setError('Failed to load check-in history');
    } finally {
      setLoading(false);
    }
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // GPS FUNCTIONALITY
  // ═══════════════════════════════════════════════════════════════════════════

  const getCurrentGPS = async () => {
    setGpsLoading(true);
    setGpsError('');
    
    try {
      const position = await siteVisitService.getCurrentPosition();
      setGpsPosition(position);
      return position;
    } catch (err) {
      setGpsError(err.message);
      return null;
    } finally {
      setGpsLoading(false);
    }
  };

  const calculateSiteDistance = (site) => {
    if (!gpsPosition || !site.latitude || !site.longitude) {
      return null;
    }
    
    const distance = siteVisitService.calculateDistance(
      gpsPosition.latitude,
      gpsPosition.longitude,
      parseFloat(site.latitude),
      parseFloat(site.longitude)
    );
    
    return Math.round(distance); // meters
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // CHECK-IN / CHECK-OUT
  // ═══════════════════════════════════════════════════════════════════════════

  const handleCheckIn = async () => {
    if (!selectedSite) {
      setError('Please select a site');
      return;
    }

    setLoading(true);
    setError('');
    setSuccess('');

    try {
      // Get fresh GPS position
      const position = await getCurrentGPS();
      if (!position) {
        setError('Unable to get GPS location');
        setLoading(false);
        return;
      }

      // Validate accuracy
      if (position.accuracy > 50) {
        const proceed = (await radaiConfirm(
          `GPS accuracy is ${Math.round(position.accuracy)}m (threshold: 50m). Continue anyway?`
        ));
        if (!proceed) {
          setLoading(false);
          return;
        }
      }

      // Check distance from site
      const distance = calculateSiteDistance(selectedSite);
      if (distance && distance > selectedSite.geofence_radius) {
        const proceed = (await radaiConfirm(
          `You are ${distance}m from the site (geofence: ${selectedSite.geofence_radius}m). Continue anyway?`
        ));
        if (!proceed) {
          setLoading(false);
          return;
        }
      }

      // Submit check-in
      const checkInData = {
        site_id: selectedSite.id,
        latitude: position.latitude,
        longitude: position.longitude,
        accuracy: position.accuracy,
        method: 'GPS',
      };

      const result = await siteVisitService.checkIn(checkInData);
      setActiveCheckIn(result);
      setSuccess(`✓ Checked in to ${selectedSite.name} at ${new Date().toLocaleTimeString()}`);
      setSelectedSite(null);
    } catch (err) {
      setError(err.response?.data?.error || 'Check-in failed');
    } finally {
      setLoading(false);
    }
  };

  const handleCheckOut = async () => {
    if (!activeCheckIn) return;

    setLoading(true);
    setError('');
    setSuccess('');

    try {
      // Get fresh GPS position
      const position = await getCurrentGPS();
      if (!position) {
        setError('Unable to get GPS location');
        setLoading(false);
        return;
      }

      // Submit check-out
      const checkOutData = {
        latitude: position.latitude,
        longitude: position.longitude,
        accuracy: position.accuracy,
        method: 'GPS',
      };

      const result = await siteVisitService.checkOut(activeCheckIn.id, checkOutData);
      setSuccess(
        `✓ Checked out. Duration: ${result.duration_hours}h at ${new Date().toLocaleTimeString()}`
      );
      setActiveCheckIn(null);
    } catch (err) {
      setError(err.response?.data?.error || 'Check-out failed');
    } finally {
      setLoading(false);
    }
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // SITE VISIT REQUEST
  // ═══════════════════════════════════════════════════════════════════════════

  const handleSubmitRequest = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setSuccess('');

    try {
      await siteVisitService.submitRequest(requestForm);
      setSuccess('Site visit request submitted for approval');
      setShowRequestForm(false);
      setRequestForm({ site_id: '', start_date: '', end_date: '', purpose: '' });
      loadRequests();
    } catch (err) {
      setError(err.response?.data?.error || 'Failed to submit request');
    } finally {
      setLoading(false);
    }
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // RENDER HELPERS
  // ═══════════════════════════════════════════════════════════════════════════

  const getStatusBadge = (status) => {
    const colors = {
      PENDING: 'bg-yellow-100 text-yellow-800',
      APPROVED: 'bg-green-100 text-green-800',
      REJECTED: 'bg-red-100 text-red-800',
      CANCELLED: 'bg-gray-100 text-gray-800',
    };
    return (
      <span className={`px-2 py-1 text-xs font-semibold rounded-full ${colors[status]}`}>
        {status}
      </span>
    );
  };

  const formatDuration = (hours) => {
    if (!hours) return 'N/A';
    const h = Math.floor(hours);
    const m = Math.round((hours - h) * 60);
    return `${h}h ${m}m`;
  };

  // ═══════════════════════════════════════════════════════════════════════════
  // RENDER
  // ═══════════════════════════════════════════════════════════════════════════

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="mb-6">
          <h1 className="text-3xl font-bold text-gray-900">Site Visit Tracking</h1>
          <p className="text-gray-600 mt-1">GPS-based attendance for off-site work</p>
        </div>

        {/* Alerts */}
        {error && (
          <div className="mb-4 p-4 bg-red-50 border border-red-200 rounded-lg flex items-center gap-2">
            <XCircleIcon className="w-5 h-5 text-red-600" />
            <span className="text-red-800">{error}</span>
          </div>
        )}
        {success && (
          <div className="mb-4 p-4 bg-green-50 border border-green-200 rounded-lg flex items-center gap-2">
            <CheckCircleIcon className="w-5 h-5 text-green-600" />
            <span className="text-green-800">{success}</span>
          </div>
        )}

        {/* Active Check-In Banner */}
        {activeCheckIn && (
          <div className="mb-6 p-4 bg-blue-50 border border-blue-200 rounded-lg">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-3">
                <MapPinIcon className="w-6 h-6 text-blue-600" />
                <div>
                  <p className="font-semibold text-blue-900">
                    Currently on-site: {activeCheckIn.site_name}
                  </p>
                  <p className="text-sm text-blue-700">
                    Checked in at {new Date(activeCheckIn.check_in_time).toLocaleTimeString()}
                  </p>
                </div>
              </div>
              <button
                onClick={handleCheckOut}
                disabled={loading}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50 disabled:cursor-not-allowed"
              >
                {loading ? 'Processing...' : 'Check Out'}
              </button>
            </div>
          </div>
        )}

        {/* Tabs */}
        <div className="mb-6 border-b border-gray-200">
          <nav className="-mb-px flex gap-6">
            {[
              { key: 'check-in', label: 'Check-In / Out' },
              { key: 'requests', label: 'My Requests' },
              { key: 'history', label: 'History' },
            ].map((tab) => (
              <button
                key={tab.key}
                onClick={() => setActiveTab(tab.key)}
                className={`pb-4 px-1 border-b-2 font-medium text-sm ${
                  activeTab === tab.key
                    ? 'border-blue-500 text-blue-600'
                    : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                }`}
              >
                {tab.label}
              </button>
            ))}
          </nav>
        </div>

        {/* Tab Content */}
        <div className="bg-white rounded-lg shadow-sm p-6">
          {/* ═══ CHECK-IN TAB ═══ */}
          {activeTab === 'check-in' && !activeCheckIn && (
            <div>
              <div className="mb-6">
                <h2 className="text-xl font-semibold mb-4">Check In to a Site</h2>
                
                {/* GPS Status */}
                <div className="mb-4 p-4 bg-gray-50 rounded-lg">
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="font-medium text-gray-700">GPS Location</p>
                      {gpsPosition ? (
                        <p className="text-sm text-green-600">
                          ✓ Position acquired (±{Math.round(gpsPosition.accuracy)}m accuracy)
                        </p>
                      ) : (
                        <p className="text-sm text-gray-500">Click to get current location</p>
                      )}
                      {gpsError && <p className="text-sm text-red-600">{gpsError}</p>}
                    </div>
                    <button
                      onClick={getCurrentGPS}
                      disabled={gpsLoading}
                      className="flex items-center gap-2 px-4 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 disabled:opacity-50"
                    >
                      <ArrowPathIcon className={`w-5 h-5 ${gpsLoading ? 'animate-spin' : ''}`} />
                      {gpsLoading ? 'Locating...' : 'Get GPS'}
                    </button>
                  </div>
                </div>

                {/* Site Selection */}
                <div className="space-y-3">
                  <label className="block text-sm font-medium text-gray-700">Select Site</label>
                  {sites.length === 0 ? (
                    <p className="text-gray-500">No active sites available</p>
                  ) : (
                    <div className="grid grid-cols-1 gap-3">
                      {sites.map((site) => {
                        const distance = calculateSiteDistance(site);
                        const withinGeofence = distance && distance <= site.geofence_radius;
                        
                        return (
                          <div
                            key={site.id}
                            onClick={() => setSelectedSite(site)}
                            className={`p-4 border-2 rounded-lg cursor-pointer transition ${
                              selectedSite?.id === site.id
                                ? 'border-blue-500 bg-blue-50'
                                : withinGeofence
                                ? 'border-green-300 hover:border-green-400'
                                : 'border-gray-200 hover:border-gray-300'
                            }`}
                          >
                            <div className="flex items-center justify-between">
                              <div>
                                <p className="font-semibold text-gray-900">{site.name}</p>
                                <p className="text-sm text-gray-600">{site.client_name}</p>
                                <p className="text-xs text-gray-500 mt-1">
                                  {site.city}, {site.country}
                                </p>
                              </div>
                              <div className="text-right">
                                {distance !== null && (
                                  <div className="space-y-1">
                                    <p
                                      className={`text-sm font-medium ${
                                        withinGeofence ? 'text-green-600' : 'text-orange-600'
                                      }`}
                                    >
                                      {distance}m away
                                    </p>
                                    {withinGeofence && (
                                      <p className="text-xs text-green-600">✓ Within geofence</p>
                                    )}
                                  </div>
                                )}
                              </div>
                            </div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </div>

                {/* Check-In Button */}
                <button
                  onClick={handleCheckIn}
                  disabled={!selectedSite || loading}
                  className="mt-6 w-full px-6 py-3 bg-green-600 text-white font-semibold rounded-lg hover:bg-green-700 disabled:opacity-50 disabled:cursor-not-allowed"
                >
                  {loading ? 'Processing...' : 'Check In'}
                </button>
              </div>
            </div>
          )}

          {activeTab === 'check-in' && activeCheckIn && (
            <div className="text-center py-12">
              <MapPinIcon className="w-16 h-16 text-blue-600 mx-auto mb-4" />
              <h3 className="text-xl font-semibold text-gray-900 mb-2">
                You are on-site at {activeCheckIn.site_name}
              </h3>
              <p className="text-gray-600">
                Checked in at {new Date(activeCheckIn.check_in_time).toLocaleString()}
              </p>
              <button
                onClick={handleCheckOut}
                className="mt-6 px-8 py-3 bg-blue-600 text-white font-semibold rounded-lg hover:bg-blue-700"
              >
                Check Out Now
              </button>
            </div>
          )}

          {/* ═══ REQUESTS TAB ═══ */}
          {activeTab === 'requests' && (
            <div>
              <div className="flex items-center justify-between mb-6">
                <h2 className="text-xl font-semibold">Site Visit Requests</h2>
                <button
                  onClick={() => setShowRequestForm(!showRequestForm)}
                  className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"
                >
                  <PlusIcon className="w-5 h-5" />
                  New Request
                </button>
              </div>

              {/* Request Form */}
              {showRequestForm && (
                <form onSubmit={handleSubmitRequest} className="mb-6 p-4 bg-gray-50 rounded-lg">
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Site *
                      </label>
                      <select
                        required
                        value={requestForm.site_id}
                        onChange={(e) =>
                          setRequestForm({ ...requestForm, site_id: e.target.value })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      >
                        <option value="">Select a site</option>
                        {sites.map((site) => (
                          <option key={site.id} value={site.id}>
                            {site.name} ({site.client_name})
                          </option>
                        ))}
                      </select>
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Start Date *
                      </label>
                      <input
                        type="date"
                        required
                        value={requestForm.start_date}
                        onChange={(e) =>
                          setRequestForm({ ...requestForm, start_date: e.target.value })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        End Date *
                      </label>
                      <input
                        type="date"
                        required
                        value={requestForm.end_date}
                        onChange={(e) =>
                          setRequestForm({ ...requestForm, end_date: e.target.value })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      />
                    </div>
                    <div>
                      <label className="block text-sm font-medium text-gray-700 mb-1">
                        Purpose *
                      </label>
                      <input
                        type="text"
                        required
                        placeholder="e.g., Installation work"
                        value={requestForm.purpose}
                        onChange={(e) =>
                          setRequestForm({ ...requestForm, purpose: e.target.value })
                        }
                        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
                      />
                    </div>
                  </div>
                  <div className="flex gap-3 mt-4">
                    <button
                      type="submit"
                      disabled={loading}
                      className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
                    >
                      Submit Request
                    </button>
                    <button
                      type="button"
                      onClick={() => setShowRequestForm(false)}
                      className="px-6 py-2 bg-gray-300 text-gray-700 rounded-lg hover:bg-gray-400"
                    >
                      Cancel
                    </button>
                  </div>
                </form>
              )}

              {/* Requests List */}
              {loading ? (
                <div className="text-center py-8">
                  <ArrowPathIcon className="w-8 h-8 text-gray-400 animate-spin mx-auto" />
                  <p className="text-gray-500 mt-2">Loading...</p>
                </div>
              ) : requests.length === 0 ? (
                <p className="text-center text-gray-500 py-8">No requests found</p>
              ) : (
                <div className="space-y-3">
                  {requests.map((req) => (
                    <div key={req.id} className="p-4 border border-gray-200 rounded-lg">
                      <div className="flex items-center justify-between mb-2">
                        <p className="font-semibold text-gray-900">{req.site_name}</p>
                        {getStatusBadge(req.status)}
                      </div>
                      <p className="text-sm text-gray-600">
                        {req.start_date} to {req.end_date}
                      </p>
                      <p className="text-sm text-gray-700 mt-1">{req.purpose}</p>
                      {req.reviewer_note && (
                        <p className="text-sm text-gray-500 mt-2 italic">
                          Note: {req.reviewer_note}
                        </p>
                      )}
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* ═══ HISTORY TAB ═══ */}
          {activeTab === 'history' && (
            <div>
              <h2 className="text-xl font-semibold mb-6">Check-In History</h2>
              {loading ? (
                <div className="text-center py-8">
                  <ArrowPathIcon className="w-8 h-8 text-gray-400 animate-spin mx-auto" />
                  <p className="text-gray-500 mt-2">Loading...</p>
                </div>
              ) : checkInHistory.length === 0 ? (
                <p className="text-center text-gray-500 py-8">No check-in history</p>
              ) : (
                <div className="space-y-3">
                  {checkInHistory.map((record) => (
                    <div key={record.id} className="p-4 border border-gray-200 rounded-lg">
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center gap-2">
                          <MapPinIcon className="w-5 h-5 text-blue-600" />
                          <p className="font-semibold text-gray-900">{record.site_name}</p>
                        </div>
                        {record.check_out_time ? (
                          <span className="text-sm text-green-600 font-medium">
                            ✓ Completed
                          </span>
                        ) : (
                          <span className="text-sm text-blue-600 font-medium">
                            ◉ Active
                          </span>
                        )}
                      </div>
                      <div className="grid grid-cols-2 gap-4 text-sm text-gray-600">
                        <div>
                          <p>
                            <span className="font-medium">Check-in:</span>{' '}
                            {new Date(record.check_in_time).toLocaleString()}
                          </p>
                          {record.geofence_valid && (
                            <p className="text-green-600 text-xs">✓ Within geofence</p>
                          )}
                        </div>
                        <div>
                          {record.check_out_time ? (
                            <>
                              <p>
                                <span className="font-medium">Check-out:</span>{' '}
                                {new Date(record.check_out_time).toLocaleString()}
                              </p>
                              <p className="text-xs text-gray-500">
                                Duration: {formatDuration(record.duration_hours)}
                              </p>
                            </>
                          ) : (
                            <p className="text-gray-500">Not checked out yet</p>
                          )}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default SiteVisits;

/**
 * HR · Time Sheet Analytics (`/hr/employees → Time Sheet`)
 * --------------------------------------------------------
 * Real-time attendance dashboard powered by the on-premise SQL Server
 * biometric database (`backend/apps/timesheet/*`).
 *
 * Five tabs:
 *   • Live     — auto-refreshing IN/OUT roster + late-today counter
 *   • Daily    — per-user hours for a chosen date
 *   • Monthly  — month rollup with full/half-day + late stats
 *   • Reports  — Excel + PDF downloads
 *   • Setup    — discovery wizard (databases → tables → columns → env vars)
 *
 * Every label, endpoint, polling interval and column comes from
 * `frontend/src/config/timesheet.config.js`. No magic values live here.
 */
import { useCallback, useEffect, useMemo, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import timesheetService from '../../services/timesheet.service'
import {
  TIMESHEET_TABS,
  TIMESHEET_DEFAULT_TAB,
  TIMESHEET_POLL_MS,
  TIMESHEET_TABLE_PAGE_SIZES,
  TIMESHEET_TABLE_DEFAULT_PAGE_SIZE,
  TIMESHEET_STATUS_TONES,
  TIMESHEET_LIVE_COLUMNS,
  TIMESHEET_DAILY_COLUMNS,
  TIMESHEET_MONTHLY_COLUMNS,
  TIMESHEET_ENV_VARS,
  TIMESHEET_COPY,
  PUNCH_TYPE_LABELS,
} from '../../config/timesheet.config'

// ─────────────────────────────────────────────────────────────────────────────
// Helpers
// ─────────────────────────────────────────────────────────────────────────────
const Icon = ({ name, className = 'w-5 h-5' }) => {
  const C = HeroIcons[name] || HeroIcons.QuestionMarkCircleIcon
  return <C className={className} aria-hidden="true" />
}

const fmtError = (err) => {
  if (!err) return null
  if (typeof err === 'string') return err
  if (err.response?.data?.error) return err.response.data.error
  if (err.response?.data?.detail) return err.response.data.detail
  return err.message || 'Unknown error'
}

const todayISO = () => new Date().toISOString().slice(0, 10)
const now = () => new Date().getFullYear()
const thisMonth = () => new Date().getMonth() + 1

// ─────────────────────────────────────────────────────────────────────────────
// Soft-coded row search — fields checked when filtering timesheet rows by text.
// Add/remove field names here to change what the search covers without
// touching any tab component.
// ─────────────────────────────────────────────────────────────────────────────
const ROW_SEARCH_FIELDS = [
  'radai_full_name', 'name', 'employee_name', 'employee_code',
  'radai_email', 'employee_email', 'email',
  'department', 'radai_department',
]

/** Return true when `row` matches the trimmed lowercase query `q`. */
const rowMatchesQuery = (row, q) => {
  if (!q) return true
  return ROW_SEARCH_FIELDS.some(f => {
    const v = (row[f] ?? '').toString().toLowerCase()
    return v && v.includes(q)
  })
}

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: RowSearchBar — inline search for timesheet data tables.
// Used by Live, Daily and Monthly tabs.
// ─────────────────────────────────────────────────────────────────────────────
const RowSearchBar = ({ value, onChange, totalCount, matchCount }) => (
  <div className="flex items-center gap-3">
    <div className="relative flex-1 max-w-sm">
      <HeroIcons.MagnifyingGlassIcon className="w-4 h-4 absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
      <input
        type="text"
        value={value}
        onChange={(e) => onChange(e.target.value)}
        placeholder="Search name, code, email, dept…"
        autoComplete="off"
        className="w-full pl-9 pr-8 py-1.5 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
      />
      {value && (
        <button
          type="button"
          onClick={() => onChange('')}
          className="absolute right-2 top-1/2 -translate-y-1/2 text-slate-400 hover:text-slate-700"
          aria-label="Clear search"
        >
          <HeroIcons.XMarkIcon className="w-4 h-4" />
        </button>
      )}
    </div>
    {value && (
      <span className="text-xs text-slate-500">
        {matchCount} of {totalCount} rows
      </span>
    )}
  </div>
)

// ─────────────────────────────────────────────────────────────────────────────
// Live-tab filter predicates (soft-coded)
// Backend stamps `is_in` (bool) and `is_late` (bool) on every live row.
// `null` value means "show all rows" (no filter applied).
// ─────────────────────────────────────────────────────────────────────────────
const LIVE_FILTER_FNS = {
  in:      (r) => r.is_in === true,
  out:     (r) => r.is_in === false,
  no_punch: (r) => r.is_in !== true && r.is_in !== false,
  late:    (r) => r.is_late === true,
  total:   null,
  matched: (r) => Boolean(r.radai_user_id),
}

const LIVE_FILTER_LABELS = {
  in:      'Currently IN',
  out:     'Currently OUT',
  no_punch: 'No Biometric Punch',
  late:    'Late Today',
  total:   'All Seen Today',
  matched: 'Matched to RAD AI',
}

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: KPI cards (Live tab)
// ─────────────────────────────────────────────────────────────────────────────
const LiveKpis = ({ summary, asOf, activeFilter, onFilterChange }) => {
  const tiles = [
    { id: 'in',      label: 'Currently IN',      value: summary?.currently_in    ?? 0, accent: 'from-emerald-500 to-teal-600',   icon: 'ArrowRightOnRectangleIcon' },
    { id: 'out',     label: 'Currently OUT',     value: summary?.currently_out   ?? 0, accent: 'from-slate-500 to-slate-700',    icon: 'ArrowLeftOnRectangleIcon' },
    { id: 'no_punch', label: 'No Punch',          value: summary?.no_punch         ?? 0, accent: 'from-slate-400 to-slate-600',    icon: 'QuestionMarkCircleIcon' },
    { id: 'late',    label: 'Late Today',        value: summary?.late_today      ?? 0, accent: 'from-amber-500 to-orange-600',   icon: 'ClockIcon' },
    { id: 'total',   label: 'Seen Today',        value: summary?.total_seen_today ?? 0, accent: 'from-blue-500 to-indigo-600',    icon: 'UsersIcon' },
    { id: 'matched', label: 'Matched to RAD AI', value: summary?.matched_to_radai ?? 0, accent: 'from-purple-500 to-fuchsia-600', icon: 'LinkIcon' },
  ]
  return (
    <div className="space-y-1">
      <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-6 gap-3">
        {tiles.map(t => {
          const isActive = activeFilter === t.id
          return (
            <button
              key={t.id}
              type="button"
              onClick={() => onFilterChange(isActive ? null : t.id)}
              title={isActive ? `Clear "${t.label}" filter` : `Filter by ${t.label}`}
              className={[
                'relative overflow-hidden rounded-xl bg-gradient-to-br text-white p-4 shadow-md text-left w-full',
                t.accent,
                'transition-all duration-150',
                isActive
                  ? 'ring-4 ring-white/60 scale-[1.04] shadow-xl'
                  : 'hover:scale-[1.02] hover:shadow-lg',
                activeFilter && !isActive ? 'opacity-40' : 'opacity-100',
              ].join(' ')}
            >
              <div className="flex items-start justify-between gap-1">
                <Icon name={t.icon} className="w-6 h-6 opacity-80 flex-shrink-0" />
                <span className="text-[10px] uppercase tracking-wider opacity-80 text-right leading-tight">{t.label}</span>
              </div>
              <div className="mt-2 text-3xl font-bold leading-tight">{t.value}</div>
              {isActive && (
                <div className="absolute bottom-1.5 right-2 text-[9px] font-semibold uppercase tracking-widest opacity-90 flex items-center gap-0.5">
                  <HeroIcons.FunnelIcon className="w-3 h-3" /> active
                </div>
              )}
            </button>
          )
        })}
      </div>
      {asOf && (
        <div className="text-xs text-slate-500 text-right">
          Updated {new Date(asOf).toLocaleTimeString()} · auto-refresh every {Math.round(TIMESHEET_POLL_MS / 1000)}s
        </div>
      )}
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: Generic data table
// ─────────────────────────────────────────────────────────────────────────────
const DataTable = ({ rows, columns, emptyMessage, resetKey }) => {
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(TIMESHEET_TABLE_DEFAULT_PAGE_SIZE)
  const rowCount = rows?.length || 0
  const totalPages = Math.max(1, Math.ceil(rowCount / pageSize))
  const safePage = Math.min(page, totalPages)
  const firstRow = (safePage - 1) * pageSize
  const visibleRows = rows?.slice(firstRow, firstRow + pageSize) || []

  useEffect(() => {
    setPage(1)
  }, [resetKey, pageSize])

  useEffect(() => {
    setPage(current => Math.min(current, totalPages))
  }, [totalPages])

  if (!rows || rows.length === 0) {
    return (
      <div className="bg-white border border-slate-200 rounded-xl p-10 text-center">
        <HeroIcons.InboxIcon className="w-10 h-10 text-slate-300 mx-auto mb-2" />
        <div className="text-sm text-slate-600">{emptyMessage || 'No data for this period.'}</div>
      </div>
    )
  }
  return (
    <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
      <div className="overflow-x-auto">
        <table className="min-w-full text-sm">
          <thead className="bg-slate-50 border-b border-slate-200">
            <tr>
              {columns.map(c => (
                <th key={c.id} className="text-left px-3 py-2 font-semibold text-slate-700 uppercase text-[11px] tracking-wider">
                  {c.label}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {visibleRows.map((r, i) => (
              <tr key={r.employee_code || r.radai_user_id || firstRow + i} className="hover:bg-slate-50">
                {columns.map(c => {
                  const v = c.accessor(r)
                  // Soft-coded cell renderer dispatch — `cellType` on the
                  // column declares the renderer (kept in the config as a
                  // string so timesheet.config.js stays JSX-free).
                  if (c.cellType === 'email') {
                    const e = (v || '').toString().trim()
                    return (
                      <td key={c.id} className="px-3 py-2 text-slate-800 whitespace-nowrap">
                        {e && e.includes('@')
                          ? <a href={`mailto:${e}`} className="text-blue-700 hover:underline" title={e}>{e}</a>
                          : <span className="text-slate-400">—</span>}
                      </td>
                    )
                  }
                  // Soft-coded punch-type badge — labels come from PUNCH_TYPE_LABELS
                  // in timesheet.config.js so display text never needs a code change.
                  if (c.cellType === 'punch_type') {
                    const isIn  = v === PUNCH_TYPE_LABELS.in
                    const isOut = v === PUNCH_TYPE_LABELS.out
                    return (
                      <td key={c.id} className="px-3 py-2 whitespace-nowrap">
                        <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold ${
                          isIn  ? 'bg-emerald-100 text-emerald-700' :
                          isOut ? 'bg-rose-100 text-rose-700' :
                                  'bg-slate-100 text-slate-500'
                        }`}>
                          {isIn  && <span className="w-1.5 h-1.5 rounded-full bg-emerald-500" />}
                          {isOut && <span className="w-1.5 h-1.5 rounded-full bg-rose-500" />}
                          {v}
                        </span>
                      </td>
                    )
                  }
                  return (
                    <td key={c.id} className="px-3 py-2 text-slate-800 whitespace-nowrap">
                      {v}
                    </td>
                  )
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      <div className="flex flex-col gap-3 border-t border-slate-200 bg-slate-50 px-3 py-3 sm:flex-row sm:items-center sm:justify-between">
        <div className="text-xs text-slate-600">
          Showing <span className="font-semibold text-slate-800">{firstRow + 1}</span>
          {' – '}
          <span className="font-semibold text-slate-800">{Math.min(firstRow + pageSize, rowCount)}</span>
          {' of '}
          <span className="font-semibold text-slate-800">{rowCount}</span> rows
        </div>
        <div className="flex flex-wrap items-center gap-2">
          <label className="flex items-center gap-2 text-xs text-slate-600">
            Rows per page
            <select
              value={pageSize}
              onChange={(e) => setPageSize(Number(e.target.value))}
              className="rounded-md border border-slate-300 bg-white px-2 py-1 text-xs text-slate-700 focus:border-blue-500 focus:ring-2 focus:ring-blue-500"
            >
              {TIMESHEET_TABLE_PAGE_SIZES.map(size => <option key={size} value={size}>{size}</option>)}
            </select>
          </label>
          <button
            type="button"
            onClick={() => setPage(current => Math.max(1, current - 1))}
            disabled={safePage === 1}
            className="inline-flex items-center gap-1 rounded-md border border-slate-300 bg-white px-2.5 py-1 text-xs font-medium text-slate-700 hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-40"
          >
            <HeroIcons.ChevronLeftIcon className="h-3.5 w-3.5" /> Previous
          </button>
          <span className="min-w-[5.5rem] text-center text-xs text-slate-600">
            Page <span className="font-semibold text-slate-800">{safePage}</span> of {totalPages}
          </span>
          <button
            type="button"
            onClick={() => setPage(current => Math.min(totalPages, current + 1))}
            disabled={safePage === totalPages}
            className="inline-flex items-center gap-1 rounded-md border border-slate-300 bg-white px-2.5 py-1 text-xs font-medium text-slate-700 hover:bg-slate-100 disabled:cursor-not-allowed disabled:opacity-40"
          >
            Next <HeroIcons.ChevronRightIcon className="h-3.5 w-3.5" />
          </button>
        </div>
      </div>
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Sub-component: Health banner (shown when not configured / driver missing / connection failed)
// ─────────────────────────────────────────────────────────────────────────────
const HealthBanner = ({ health, onOpenSetup }) => {
  if (!health) return null
  const { driver, config, ping } = health
  // Soft-coded backend mode. Falls back to legacy behaviour if the backend
  // doesn't yet return `data_source` (older deployments).
  const dataSource = (health.data_source || config?.data_source || 'sqlserver').toLowerCase()

  let title, subtitle, tone = TIMESHEET_STATUS_TONES.unconfigured

  // ── Mirror mode (production / Railway): no SQL Server reachability concept.
  // Decide based on the local Postgres mirror table.
  if (dataSource === 'mirror') {
    if (ping?.ok) return null  // Healthy mirror with events → no banner.
    if (ping?.error) {
      title = TIMESHEET_COPY.mirrorErrorTitle
      subtitle = `${TIMESHEET_COPY.mirrorErrorSubtitle}\n${ping.error}`
    } else {
      title = TIMESHEET_COPY.mirrorEmptyTitle
      subtitle = TIMESHEET_COPY.mirrorEmptySubtitle
    }
  // ── SQL Server (direct LAN) mode: original behaviour.
  } else if (!driver?.driver_in_use) {
    title = TIMESHEET_COPY.driverMissingTitle
    subtitle = TIMESHEET_COPY.driverMissingSubtitle
  } else if (!config?.configured) {
    title = TIMESHEET_COPY.notConfiguredTitle
    subtitle = TIMESHEET_COPY.notConfiguredSubtitle
  } else if (ping && ping.ok === false) {
    title = TIMESHEET_COPY.connectionFailedTitle
    subtitle = `${TIMESHEET_COPY.connectionFailedSubtitle}\nDriver error: ${ping.error || 'unknown'}`
  } else {
    return null
  }

  return (
    <div className={`border rounded-xl p-4 flex items-start gap-3 ${tone}`}>
      <HeroIcons.ExclamationTriangleIcon className="w-6 h-6 flex-shrink-0 mt-0.5" />
      <div className="flex-1">
        <div className="font-semibold">{title}</div>
        <div className="text-sm mt-1 whitespace-pre-line opacity-90">{subtitle}</div>
      </div>
      <button
        type="button"
        onClick={onOpenSetup}
        className="px-3 py-1.5 bg-white text-rose-700 border border-rose-200 rounded-md text-xs font-semibold hover:bg-rose-50"
      >
        Open Setup
      </button>
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Tab: Live
// ─────────────────────────────────────────────────────────────────────────────
const LiveTab = ({ refreshTick, onManualRefresh }) => {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [activeFilter, setActiveFilter] = useState(null)
  const [rowSearch, setRowSearch] = useState('')
  const [isRefreshing, setIsRefreshing] = useState(false)

  useEffect(() => {
    let cancelled = false
    setLoading(true)
    // Soft-coded: add cache-busting timestamp to force fresh data
    const cacheBuster = Date.now()
    
    // Log fetch attempt for debugging production issues
    if (window.location.hostname !== 'localhost') {
      console.log(`[Timesheet] 📡 Fetching live attendance data (tick: ${refreshTick}, cache: ${cacheBuster})`)
    }
    
    timesheetService.fetchLive(cacheBuster)
      .then(d => { 
        if (!cancelled) { 
          setData(d); 
          setError(null);
          if (window.location.hostname !== 'localhost') {
            console.log(`[Timesheet] ✅ Live data loaded: ${d?.rows?.length || 0} rows, summary:`, d?.summary)
          }
        } 
      })
      .catch(e => { 
        if (!cancelled) {
          const errMsg = fmtError(e);
          setError(errMsg);
          if (window.location.hostname !== 'localhost') {
            console.error(`[Timesheet] ❌ Failed to fetch live data:`, errMsg, e)
          }
        }
      })
      .finally(() => { if (!cancelled) setLoading(false) })
    return () => { cancelled = true }
  }, [refreshTick])

  // Manual refresh handler - bypasses cache
  const handleManualRefresh = useCallback(() => {
    setIsRefreshing(true)
    onManualRefresh()
    // Reset refreshing state after animation
    setTimeout(() => setIsRefreshing(false), 1000)
  }, [onManualRefresh])

  const allRows = data?.rows || []
  const filterFn = activeFilter ? LIVE_FILTER_FNS[activeFilter] : null
  const q = rowSearch.trim().toLowerCase()
  const filteredRows = allRows
    .filter(r => filterFn ? filterFn(r) : true)
    .filter(r => rowMatchesQuery(r, q))

  if (loading && !data) {
    return <div className="text-center text-slate-500 py-10">Loading live status…</div>
  }
  if (error) {
    return <div className="bg-rose-50 border border-rose-200 text-rose-800 p-4 rounded-lg">{error}</div>
  }
  if (data?.configured === false) {
    return null  // The HealthBanner above already explains; no extra noise here.
  }

  // Soft-coded: when the rolling window returns 0 rows (e.g. sync agent
  // hasn't run yet today, or timezone boundary mismatch), show a helpful
  // diagnostic banner instead of a silent empty table.
  const windowFrom = data?.window_from
  const fmtWindowFrom = windowFrom
    ? new Date(windowFrom).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' })
    : null

  return (
    <div className="space-y-4">
      {/* ── Soft-coded window label + Refresh button ── */}
      <div className="flex items-center justify-between gap-3">
        <div className="flex items-center gap-2 text-xs text-slate-500 bg-slate-50 border border-slate-200 rounded-lg px-3 py-1.5">
          <HeroIcons.ClockIcon className="w-3.5 h-3.5 text-slate-400" />
          {fmtWindowFrom && (
            <>
              {TIMESHEET_COPY.liveWindowPrefix}{' '}
              <span className="font-semibold text-slate-700">{fmtWindowFrom}</span>
              {data?.lookback_hours && (
                <span className="ml-1 text-slate-400">({data.lookback_hours} h window)</span>
              )}
            </>
          )}
          {!fmtWindowFrom && <span className="text-slate-400">Loading...</span>}
        </div>
        
        {/* Soft-coded: Manual refresh button - bypasses cache and triggers sync */}
        <button
          type="button"
          onClick={handleManualRefresh}
          disabled={isRefreshing || loading}
          className={`px-3 py-1.5 rounded-md text-xs font-medium flex items-center gap-1.5 transition ${
            isRefreshing || loading
              ? 'bg-slate-100 text-slate-400 cursor-not-allowed'
              : 'bg-blue-600 text-white hover:bg-blue-700 active:bg-blue-800'
          }`}
          title="Fetch latest punch data from server (bypasses cache)"
        >
          <HeroIcons.ArrowPathIcon className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
          {isRefreshing ? 'Refreshing...' : 'Refresh Data'}
        </button>
      </div>
      
      <LiveKpis
        summary={data?.summary}
        asOf={data?.as_of}
        activeFilter={activeFilter}
        onFilterChange={setActiveFilter}
      />
      <RowSearchBar
        value={rowSearch}
        onChange={setRowSearch}
        totalCount={allRows.filter(r => filterFn ? filterFn(r) : true).length}
        matchCount={filteredRows.length}
      />
      {activeFilter && (
        <div className="flex items-center justify-between bg-blue-50 border border-blue-200 rounded-lg px-4 py-2">
          <div className="text-sm text-blue-800 font-medium flex items-center gap-2">
            <HeroIcons.FunnelIcon className="w-4 h-4" />
            Showing{' '}
            <span className="font-bold">{filteredRows.length}</span>
            {' '}of{' '}
            <span className="font-bold">{allRows.length}</span>
            {' '}employees — Filter: <span className="font-bold">{LIVE_FILTER_LABELS[activeFilter]}</span>
          </div>
          <button
            type="button"
            onClick={() => setActiveFilter(null)}
            className="text-xs text-blue-700 hover:text-blue-900 font-semibold flex items-center gap-1"
          >
            <HeroIcons.XMarkIcon className="w-4 h-4" />
            Clear filter
          </button>
        </div>
      )}

      {/* ── Soft-coded stale sync diagnostic banner (when DB has data but it's too old) ── */}
      {data?.sync_stale && (
        <div className="bg-rose-50 border border-rose-200 rounded-xl p-4 flex items-start gap-3">
          <HeroIcons.ExclamationTriangleIcon className="w-5 h-5 text-rose-500 flex-shrink-0 mt-0.5" />
          <div className="flex-1">
            <div className="text-sm font-semibold text-rose-800">{TIMESHEET_COPY.liveStaleSyncTitle}</div>
            <div className="text-xs text-rose-700 mt-1">{TIMESHEET_COPY.liveStaleSyncSubtitle}</div>
            <div className="mt-2 space-y-1">
              {data.mirror_latest_event && (
                <div className="text-xs text-rose-600 flex items-center gap-1">
                  <HeroIcons.ClockIcon className="w-3 h-3" />
                  {TIMESHEET_COPY.liveStaleSyncLastEvent}{' '}
                  <span className="font-semibold">
                    {new Date(data.mirror_latest_event).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' })}
                  </span>
                </div>
              )}
              {data.sync_age_days && (
                <div className="text-xs text-rose-600 flex items-center gap-1">
                  <HeroIcons.ExclamationCircleIcon className="w-3 h-3" />
                  {TIMESHEET_COPY.liveStaleSyncAge}{' '}
                  <span className="font-semibold">
                    {data.sync_age_days < 1 
                      ? `${data.sync_age_hours} hours ago`
                      : `${data.sync_age_days} days ago`}
                  </span>
                </div>
              )}
            </div>
            <div className="mt-3 text-xs font-semibold text-rose-800 bg-rose-100 border border-rose-300 rounded px-3 py-2">
              🔧 {TIMESHEET_COPY.liveStaleSyncAction}
            </div>
          </div>
        </div>
      )}

      {/* ── Soft-coded no-data diagnostic banner (shown only when 0 rows + no filter + no stale data) ── */}
      {allRows.length === 0 && !activeFilter && !q && !data?.sync_stale && (
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 flex items-start gap-3">
          <HeroIcons.ExclamationTriangleIcon className="w-5 h-5 text-amber-500 flex-shrink-0 mt-0.5" />
          <div>
            <div className="text-sm font-semibold text-amber-800">{TIMESHEET_COPY.liveNoDataTitle}</div>
            <div className="text-xs text-amber-700 mt-1">{TIMESHEET_COPY.liveNoDataSubtitle}</div>
            {fmtWindowFrom && (
              <div className="text-xs text-amber-600 mt-1.5 flex items-center gap-1">
                <HeroIcons.ClockIcon className="w-3 h-3" />
                Window checked: {fmtWindowFrom} →{' '}
                {data?.as_of ? new Date(data.as_of).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' }) : TIMESHEET_COPY.liveSyncUnknown}
              </div>
            )}
          </div>
        </div>
      )}

      <DataTable
        rows={filteredRows}
        columns={TIMESHEET_LIVE_COLUMNS}
        resetKey={`${activeFilter || 'all'}:${q}`}
        emptyMessage={
          q              ? `No rows match "${rowSearch}".` :
          activeFilter   ? `No employees match "${LIVE_FILTER_LABELS[activeFilter]}".` :
          /* else */       TIMESHEET_COPY.liveNoDataTitle
        }
      />
    </div>
  )
}

