const NOW          = new Date()
const TODAY_STR    = `${NOW.getFullYear()}-${String(NOW.getMonth() + 1).padStart(2, '0')}-${String(NOW.getDate()).padStart(2, '0')}`

export default function AttendanceDashboard() {
  // ── UI state ────────────────────────────────────────────────────────────────
  const [view,         setView]         = useState(ATTENDANCE_DEFAULT_VIEW)
  const [selectedDate, setSelectedDate] = useState(TODAY_STR)
  const [dailyInitialSearch, setDailyInitialSearch] = useState('')
  const [matrixSelection, setMatrixSelection] = useState({})

  // ── Data state ──────────────────────────────────────────────────────────────
  const [dailyData,   setDailyData]   = useState([])

  const [loadingDaily,   setLoadingDaily]   = useState(false)
  const [dailyError, setDailyError] = useState('')
  const [dailySource, setDailySource] = useState('')
  const [dailyLoadedDate, setDailyLoadedDate] = useState('')
  const [dailyRefresh, setDailyRefresh] = useState(0)

  // ── Daily data ──────────────────────────────────────────────────────────────
  useEffect(() => {
    if (view !== 'daily') return
    let active = true
    setLoadingDaily(true)
    setDailyData([])
    setDailyError('')
    setDailySource('')
    setDailyLoadedDate('')
    ts.fetchDaily(selectedDate)
      .then(d => {
        if (!active) return
        if (d?.configured === false) {
          setDailyError(typeof d.message === 'string' && d.message ? d.message : 'The attendance source is not configured or is unavailable.')
          return
        }
        const rows = d?.rows || (Array.isArray(d) ? d : null)
        if (!Array.isArray(rows)) throw new Error('Invalid daily attendance response')
        setDailyData(rows.filter(filterEmployeeRow))
        const source = d?.attendance_source || (d?.variant === 'manual' || d?.hours_mode === 'manual' ? 'manual_upload' : '')
        setDailySource(({ manual_upload: 'Manual upload source', biometric: 'Biometric source', hybrid: 'Biometric + uploaded hours' })[source] || 'Attendance records')
        setDailyLoadedDate(selectedDate)
      })
      .catch(failure => {
        if (!active) return
        setDailyError(failure?.response?.status === 403 ? 'You do not have permission to view daily attendance.'
          : failure?.response?.status === 401 ? 'Your session has expired. Sign in again to load attendance.'
            : 'Daily attendance could not be loaded. Please try again.')
      })
      .finally(() => { if (active) setLoadingDaily(false) })
    return () => { active = false }
  }, [selectedDate, view, dailyRefresh])

  const renderDaily = () => (
    <DailyAttendanceTab rows={dailyData} date={selectedDate} today={TODAY_STR}
      loading={loadingDaily || (!dailyError && dailyLoadedDate !== selectedDate)}
      error={dailyError} source={dailySource} onDateChange={setSelectedDate}
      onRefresh={() => setDailyRefresh(value => value + 1)} Pagination={TablePagination} initialSearch={dailyInitialSearch} />
  )

  // MAIN RENDER
  // ────────────────────────────────────────────────────────────────────────────
  return (
    <div className="attendance-workspace">
      <nav className="att-tabs" aria-label="Attendance views">
        {ATTENDANCE_VIEWS.map(item => <button key={item.id} type="button" className="att-tab" aria-pressed={view === item.id} title={item.description} onClick={() => { setDailyInitialSearch(''); setMatrixSelection({}); setView(item.id) }}>{item.label}</button>)}
      </nav>

      {/* Render active view */}
      {view === 'overview' && <AttendanceOverviewTab date={selectedDate} today={TODAY_STR} onDateChange={setSelectedDate}
        onOpenDaily={(date, search = '') => { setSelectedDate(date); setDailyInitialSearch(search); setView('daily') }}
        onOpenMatrix={(date, search = '') => { setMatrixSelection({ initialDate: date, initialSearch: search }); setView('summary') }} /> }
      {view === 'summary'  && <SummaryTab {...matrixSelection} />}
      {view === 'daily'    && renderDaily()}
      {view === 'yearly'   && <YearlyAttendanceTab Pagination={TablePagination} />}
      {view === 'reports'  && <ReportsTab todayStr={TODAY_STR} />}
    </div>
  )
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import * as Icons from '@heroicons/react/24/outline'
import { CartesianGrid, Line, LineChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import ts from '../../../services/timesheet.service'
import payrollService from '../../../services/payroll.service'
import { ATT_STANDARD_DAILY_HOURS, empDept, empName, filterEmployeeRow } from '../../../config/hrAttendance.config'
import { BRANCHES } from '../../../config/hrLeave.config'
import { buildOverviewDay, overviewDateKeys, overviewNumber } from './overviewAttendanceModel'

const EMPTY = { state: 'loading', data: null }
const dateObject = value => new Date(`${value}T12:00:00`)
const dateKey = value => `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, '0')}-${String(value.getDate()).padStart(2, '0')}`
const dateLabel = value => dateObject(value).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })
const format = value => value == null ? '—' : value.toLocaleString('en-US', { maximumFractionDigits: 1 })
const hours = value => value == null ? '—' : `${format(value)}h`
const timestamp = value => value && !Number.isNaN(new Date(value).getTime()) ? new Date(value).toLocaleString('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—'
const errorMessage = error => error?.response?.status === 403 ? 'Access denied.' : error?.response?.status === 401 ? 'Session expired. Sign in again.' : 'Could not be loaded.'
const sourceLabel = data => ({ manual_upload: 'Manual upload', manual: 'Manual upload', biometric: 'Biometric records', hybrid: 'Biometric + uploaded hours', mirror: 'Biometric mirror', sqlserver: 'Biometric records' })[data?.attendance_source || data?.variant || data?.hours_mode] || 'Attendance records'

// Keyed reads clear obsolete values immediately and ignore late responses.
function useOverviewRead(key, loader) {
  const [result, setResult] = useState({ key: null, ...EMPTY })
  useEffect(() => {
    let active = true
    setResult({ key, ...EMPTY })
    Promise.resolve().then(loader).then(data => {
      if (active) setResult({ key, state: 'loaded', data })
    }).catch(error => {
      if (active) setResult({ key, state: 'error', error: errorMessage(error), data: null })
    })
    return () => { active = false }
  }, [key, loader])
  return result.key === key ? result : EMPTY
}

async function loadHolidays(year) {
  const rows = []
  let count
  for (let page = 1; page <= 1000; page++) {
    const response = await payrollService.getPublicHolidays(year, { active_only: 'true', page })
    if (page === 1 && Array.isArray(response)) return response
    if (!Array.isArray(response?.results) || !Number.isSafeInteger(response.count) || response.count < 0) throw new Error('Incomplete holidays')
    if (page === 1) count = response.count
    if (response.count !== count) throw new Error('Changed holidays')
    rows.push(...response.results)
    if (rows.length > count) throw new Error('Incomplete holidays')
    if (response.next === null) {
      if (rows.length !== count) throw new Error('Incomplete holidays')
      return rows
    }
    if (typeof response.next !== 'string' || !response.results.length || Number(new URL(response.next, 'https://attendance.invalid').searchParams.get('page')) !== page + 1) throw new Error('Incomplete holidays')
  }
  throw new Error('Incomplete holidays')
}

function PanelState({ resource, label, onRetry, empty }) {
  if (resource.state === 'loading') return <p className="att-overview-empty" role="status">Loading {label.toLowerCase()}…</p>
  if (resource.state === 'error') return <div className="att-overview-empty att-overview-error" role="alert">{label}: {resource.error} <button type="button" className="att-overview-link" onClick={onRetry}>Retry {label.toLowerCase()}</button></div>
  return empty ? <p className="att-overview-empty">{empty}</p> : null
}

export default function AttendanceOverviewTab({ date, today, onDateChange, onOpenDaily, onOpenMatrix }) {
  const [branch, setBranch] = useState('all')
  const [department, setDepartment] = useState('all')
  const [search, setSearch] = useState('')
  const [refresh, setRefresh] = useState(0)
  const [attentionExpanded, setAttentionExpanded] = useState(false)
  const [exportBusy, setExportBusy] = useState(false)
  const [exportError, setExportError] = useState('')
  const [week, setWeek] = useState({ key: '', days: {} })
  const year = Number(date.slice(0, 4)), month = Number(date.slice(5, 7))
  const weekKey = `${date}:${refresh}`
  const dates = useMemo(() => overviewDateKeys(date), [date])
  const branchYearsKey = [...new Set(dates.map(day => day.slice(0, 4)))].join(',')
  const retry = () => setRefresh(value => value + 1)

  useEffect(() => {
    let active = true
    setWeek({ key: weekKey, days: {} })
    dates.forEach(day => {
      ts.fetchDaily(day).then(response => {
        const rows = Array.isArray(response) ? response : response?.rows
        if (response?.configured === false || !Array.isArray(rows)) throw new Error('Attendance unavailable')
        if (active) setWeek(previous => ({ key: weekKey, days: { ...previous.days, [day]: { state: 'loaded', data: rows.filter(filterEmployeeRow), source: sourceLabel(response) } } }))
      }).catch(error => {
        if (active) setWeek(previous => ({ key: weekKey, days: { ...previous.days, [day]: { state: 'error', data: null, error: errorMessage(error) } } }))
      })
    })
    return () => { active = false }
  }, [dates, weekKey])

  const leave = useOverviewRead(`${year}:${month}:${refresh}`, useCallback(async () => {
    const response = await payrollService.getLeaveCalendar(year, month)
    if (!response?.calendar || typeof response.calendar !== 'object' || Array.isArray(response.calendar)) throw new Error('Invalid calendar')
    return response.calendar
  }, [year, month]))
  const corrections = useOverviewRead(`${year}:${month}:${refresh}`, useCallback(async () => {
    const rows = await payrollService.getAttendanceOverrides(year, month)
    if (!Array.isArray(rows)) throw new Error('Invalid corrections')
    return [...rows].sort((a, b) => (Date.parse(b.created_at) || 0) - (Date.parse(a.created_at) || 0))
  }, [year, month]))
  const holidays = useOverviewRead(`${year}:${refresh}`, useCallback(() => loadHolidays(year), [year]))
  const approvals = useOverviewRead(String(refresh), useCallback(async () => {
    const response = await payrollService.getPendingLeaveApprovals()
    if (!Array.isArray(response?.results) || !Number.isSafeInteger(response.count) || response.count !== response.results.length) throw new Error('Invalid approval queue')
    return response
  }, []))
  const health = useOverviewRead(String(refresh), useCallback(async () => {
    const response = await ts.fetchHealth()
    if (typeof response?.ping?.ok !== 'boolean') throw new Error('Invalid health')
    return response
  }, []))
  const branchState = useOverviewRead(`${branchYearsKey}:${branch}:${refresh}`, useCallback(async () => {
    if (branch === 'all') return {}
    const entries = await Promise.all(branchYearsKey.split(',').map(async branchYear => {
      const response = await payrollService.getBranchEmployeeCodes(branch, Number(branchYear))
      if (!Array.isArray(response?.codes)) throw new Error('Invalid branch')
      return [branchYear, response.codes.map(String)]
    }))
    return Object.fromEntries(entries)
  }, [branch, branchYearsKey]))

  const current = week.key === weekKey ? week.days[date] || EMPTY : EMPTY
  const branchReady = branch === 'all' || branchState.state === 'loaded'
  const ready = current.state === 'loaded' && branchReady
  const codes = useMemo(() => Object.fromEntries(Object.entries(branchState.data || {}).map(([key, values]) => [key, new Set(values)])), [branchState.data])
  const filterBranch = (row, rowYear = year) => branch === 'all' || Boolean(codes[rowYear]?.has(String(row.employee_code || '')))
  const filterRow = (row, rowYear = year) => filterBranch(row, rowYear) && (department === 'all' || empDept(row) === department) && (!search.trim() || [empName(row), row.employee_code, empDept(row)].some(value => String(value || '').toLowerCase().includes(search.trim().toLowerCase())))
  const rows = ready ? current.data.filter(row => filterRow(row)) : []
  const totals = buildOverviewDay(rows)
  const departments = [...new Set((current.data || []).filter(row => filterBranch(row)).map(empDept))].sort()
  if (department !== 'all' && !departments.includes(department)) departments.push(department)
  const trend = dates.map(day => {
    const resource = week.key === weekKey ? week.days[day] || EMPTY : EMPTY
    return { date: day, label: dateObject(day).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' }), records: branchReady && resource.state === 'loaded' ? resource.data.filter(row => filterRow(row, Number(day.slice(0, 4)))).length : null, state: resource.state }
  })
  const approvedLeave = leave.state === 'loaded' ? Object.values(leave.data).filter(days => Boolean(days?.[date])).length : null
  const selectedHolidays = holidays.state === 'loaded' ? holidays.data.filter(item => item.date === date && item.is_active !== false) : []
  const recent = corrections.state === 'loaded' ? corrections.data.slice(0, 5) : []
  const attention = attentionExpanded ? totals.attention : totals.attention.slice(0, 5)
  const metric = value => ready ? format(value) : '—'
  const stepDate = delta => {
    const next = dateObject(date)
    next.setDate(next.getDate() + delta)
    changeDate(dateKey(next))
  }
  const changeDate = value => {
    if (value <= today && overviewDateKeys(value).length) {
      onDateChange(value)
      setAttentionExpanded(false)
      setExportError('')
    }
  }
  const exportDay = async () => {
    setExportError('')
    setExportBusy(true)
    try { await ts.downloadDailyExcel(date) }
    catch { setExportError('The daily report could not be exported. Please try again.') }
    finally { setExportBusy(false) }
  }
  const sourceHealth = health.data?.data_source
  const sourceValue = health.state === 'loaded' ? health.data.ping.ok ? ({ manual: 'Upload storage available', mirror: 'Mirror records available', sqlserver: 'Connection available' })[sourceHealth] || 'Available' : 'Unavailable / no records' : health.state === 'loading' ? 'Loading…' : 'Unavailable'
  const dataStatus = resource => resource.state === 'loaded' ? 'Loaded' : resource.state === 'loading' ? 'Loading…' : 'Unavailable'

  return <section className="att-overview" aria-label="Attendance overview">
    <div className="att-filter-panel att-overview-toolbar">
      <div className="att-date-navigation">
        <button type="button" className="att-button" aria-label="Previous overview day" disabled={exportBusy} onClick={() => stepDate(-1)}><Icons.ChevronLeftIcon /></button>
        <label className="att-date-picker"><Icons.CalendarDaysIcon /><span>{date === today ? 'Today · ' : ''}{dateLabel(date)}</span><input type="date" aria-label="Overview date" value={date} max={today} disabled={exportBusy} onChange={event => changeDate(event.target.value)} /></label>
        <button type="button" className="att-button" aria-label="Next overview day" disabled={date >= today || exportBusy} onClick={() => stepDate(1)}><Icons.ChevronRightIcon /></button>
        {date !== today && <button type="button" className="att-overview-link" disabled={exportBusy} onClick={() => changeDate(today)}>Today</button>}
      </div>
      <label className="att-field"><span>Branch</span><select aria-label="Branch" value={branch} onChange={event => setBranch(event.target.value)}><option value="all">All branches</option>{BRANCHES.map(item => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label>
      <label className="att-field"><span>Department</span><select aria-label="Department" value={department} onChange={event => setDepartment(event.target.value)}><option value="all">All departments</option>{departments.map(item => <option key={item}>{item}</option>)}</select></label>
      <label className="att-field att-search"><span>Search attendance</span><span className="att-search-box"><Icons.MagnifyingGlassIcon /><input aria-label="Employee search" placeholder="Employee name or ID" value={search} onChange={event => setSearch(event.target.value)} /></span></label>
      <div className="att-overview-tools">
        <button type="button" className="att-button" title="Excel · all permitted records for the selected date" disabled={exportBusy} onClick={exportDay}><Icons.ArrowDownTrayIcon />{exportBusy ? 'Exporting…' : 'Export daily hours'}</button>
        <button type="button" className="att-button att-sync" aria-label="Refresh overview" onClick={retry}><Icons.ArrowPathIcon />Refresh</button>
        <Link className="att-button" to="/hr/leave"><Icons.CalendarDaysIcon />Leave management</Link>
      </div>
    </div>
    {exportError && <div className="att-overview-alert" role="alert">{exportError} <button type="button" className="att-overview-link" disabled={exportBusy} onClick={exportDay}>Retry export</button></div>}
    {branch !== 'all' && branchState.state !== 'loaded' && <PanelState resource={branchState} label="Branch attendance" onRetry={retry} />}
    {current.state !== 'loaded' && <PanelState resource={current} label="Daily attendance" onRetry={retry} />}

    <dl className="att-summary att-overview-summary" aria-label="Overview attendance summary">
      {[
        ['Attendance records', metric(totals.records), Icons.UsersIcon, 'neutral', 'Filtered records'],
        ['Check-ins', metric(totals.checkIns), Icons.UserIcon, 'good', 'Recorded first punch'],
        ['Approved leave', format(approvedLeave), Icons.CalendarDaysIcon, 'blue', 'All permitted employees'],
        ['Late records', metric(totals.late), Icons.ClockIcon, 'warn', 'Source late flag'],
        ['Attention items', metric(totals.attention.length), Icons.ExclamationTriangleIcon, 'warn', 'Filtered records'],
        ['Pending leave', approvals.state === 'loaded' ? format(approvals.data.count) : '—', Icons.ClockIcon, 'warn', 'For your review · all dates'],
      ].map(([label, value, Icon, tone, note]) => <div key={label} className="att-summary-item" data-tone={tone}><Icon /><div><dt>{label}</dt><dd>{value}</dd><small>{note}</small></div></div>)}
    </dl>

    <div className="att-overview-grid">
      <div className="att-overview-main">
        <section className="att-overview-card" aria-label="Requires attention">
          <header><div><h2>Requires attention</h2><p>Open shifts, late arrivals and recorded overtime</p></div><button type="button" className="att-overview-link" disabled={!ready || !totals.attention.length} onClick={() => setAttentionExpanded(value => !value)}>{attentionExpanded ? 'Show less' : `View all (${ready ? totals.attention.length : '—'})`}<Icons.ChevronRightIcon /></button></header>
          {!ready ? <p className="att-overview-empty">Attendance details are unavailable until the selected records load.</p> : !attention.length ? <p className="att-overview-empty">{rows.length ? 'No attention items in the returned records.' : 'No attendance records match this date and filters.'}</p> : <div className="att-overview-table-scroll"><table className="att-overview-table att-overview-attention"><thead><tr><th>Type</th><th>Issue</th><th>Employee</th><th>Department</th><th>Details</th><th>Action</th></tr></thead><tbody>{attention.map(item => <tr key={item.key}><td><span className="att-overview-tone" data-tone={item.tone === 'warning' ? 'warn' : 'blue'}>{item.tone === 'warning' ? <Icons.ExclamationTriangleIcon /> : <Icons.InformationCircleIcon />}{item.tone === 'warning' ? 'Warning' : 'Info'}</span></td><td>{item.issue}</td><td>{empName(item.row)}</td><td>{empDept(item.row)}</td><td>{item.detail}</td><td><button type="button" className="att-overview-review" aria-label={`Review ${empName(item.row)}`} onClick={() => onOpenDaily(date, String(item.row.employee_code || empName(item.row)))}>Review</button></td></tr>)}</tbody></table></div>}
        </section>

        <section className="att-overview-card" aria-label="Attendance by department">
          <header><h2>Attendance by department</h2><button type="button" className="att-overview-link" onClick={() => onOpenDaily(date)}>Open daily register<Icons.ChevronRightIcon /></button></header>
          {ready && totals.departments.length ? <div className="att-overview-table-scroll"><table className="att-overview-table att-overview-departments"><thead><tr><th>Department</th><th>Records</th><th>Check-ins</th><th>Open shifts</th><th>Regular hours</th><th>Check-in share</th></tr></thead><tbody>{totals.departments.map(item => <tr key={item.dept}><td>{item.dept}</td><td>{format(item.records)}</td><td>{format(item.checkIns)}</td><td>{format(item.openShifts)}</td><td>{hours(item.regularHours)}</td><td><span className="att-overview-bar"><span><i style={{ width: `${item.checkInShare || 0}%` }} /></span><b>{format(item.checkInShare)}%</b></span></td></tr>)}</tbody></table></div> : <p className="att-overview-empty">{ready ? 'No department records for this selection.' : 'Department figures unavailable.'}</p>}
          <p className="att-overview-footnote">Share of returned records with a check-in. Records can include multiple sessions per employee.</p>
        </section>

        <section className="att-overview-card" aria-label="Seven-day attendance trend">
          <header><h2>7-day attendance trend</h2><span className="att-overview-chart-key"><i />Attendance records</span></header>
          <div className="att-overview-trend"><div className="att-overview-chart" role="img" aria-label={trend.map(point => `${point.label}: ${point.records == null ? 'unavailable' : `${point.records} records`}`).join('; ')}>
            <ResponsiveContainer width="100%" height={180}><LineChart data={trend} margin={{ top: 10, right: 12, bottom: 4, left: -22 }}><CartesianGrid stroke="#e9eff7" strokeDasharray="3 3" /><XAxis dataKey="label" tick={{ fontSize: 10, fill: '#526c92' }} axisLine={{ stroke: '#c7d5e7' }} tickLine={false} /><YAxis allowDecimals={false} tick={{ fontSize: 10, fill: '#526c92' }} axisLine={false} tickLine={false} /><Tooltip formatter={value => [format(value), 'Records']} /><Line type="linear" dataKey="records" stroke="#1765ff" strokeWidth={2} dot={{ r: 3, fill: '#1765ff', stroke: 'white', strokeWidth: 1 }} connectNulls={false} isAnimationActive={false} /></LineChart></ResponsiveContainer>
          </div><aside><span>Selected day</span><strong>{metric(totals.records)}</strong><span>Days loaded</span><b>{trend.filter(point => point.state === 'loaded').length} of 7</b><p><Icons.InformationCircleIcon />Recorded counts; a scheduled workforce denominator is not available.</p></aside></div>
          {trend.some(point => point.state === 'error') && <div className="att-overview-footnote" role="alert">Unavailable days: {trend.filter(point => point.state === 'error').map(point => point.label).join(', ')}. <button className="att-overview-link" type="button" onClick={retry}>Retry trend</button></div>}
        </section>
      </div>

      <div className="att-overview-side">
        <section className="att-overview-card" aria-label="Daily summary">
          <header><h2>Daily summary</h2><button type="button" className="att-overview-link" onClick={() => onOpenMatrix(date)}>Open monthly matrix</button></header>
          <dl className="att-overview-facts">
            <div><dt><Icons.ClockIcon />Configured standard day</dt><dd>{hours(ATT_STANDARD_DAILY_HOURS)}</dd></div>
            <div><dt><Icons.PlayIcon />Source regular hours</dt><dd>{ready ? hours(totals.regularHours) : '—'}</dd></div>
            <div><dt><Icons.ChartBarIcon />Recorded OT · unapproved</dt><dd>{ready ? hours(totals.overtimeHours) : '—'}</dd></div>
            <div><dt><Icons.CalendarDaysIcon />Expected hours / variance</dt><dd className="att-overview-muted">Not available</dd></div>
            <div><dt><Icons.CalendarDaysIcon />Public holidays · all regions</dt><dd>{holidays.state === 'loaded' ? selectedHolidays.length ? selectedHolidays.map(item => `${item.name}${item.region ? ` (${item.region})` : ''}`).join(', ') : 'None listed' : '—'}</dd></div>
          </dl><p className="att-overview-footnote">{current.state === 'loaded' ? current.source : 'Source unavailable'} · {dateLabel(date)}. Source hours exclude HR corrections; open-shift hours may change.</p>
          {holidays.state === 'error' && <PanelState resource={holidays} label="Public holidays" onRetry={retry} />}
        </section>

        <section className="att-overview-card" aria-label="Data health">
          <header><h2>Data health</h2><button type="button" className="att-overview-link" onClick={retry}>Refresh status</button></header>
          <dl className="att-overview-facts">
            {[[health, 'Attendance source', sourceValue], [current, 'Selected-day records', dataStatus(current)], [leave, 'Approved leave calendar', dataStatus(leave)], [corrections, 'HR corrections', dataStatus(corrections)]].map(([resource, label, value]) => <div key={label}><dt>{resource.state === 'error' || (label === 'Attendance source' && resource.data?.ping?.ok === false) ? <Icons.ExclamationTriangleIcon className="att-overview-warn" /> : resource.state === 'loaded' ? <Icons.CheckCircleIcon className="att-overview-good" /> : <Icons.ClockIcon />}{label}</dt><dd>{value}</dd></div>)}
          </dl>
          {health.state === 'loaded' && (health.data.ping.latest_upload || health.data.ping.latest_event) && <p className="att-overview-footnote">{health.data.ping.latest_upload ? 'Latest upload' : 'Latest recorded event'}: {timestamp(health.data.ping.latest_upload || health.data.ping.latest_event)}. This is not a sync heartbeat.</p>}
          {health.state === 'error' && <PanelState resource={health} label="Source health" onRetry={retry} />}
          {leave.state === 'error' && <PanelState resource={leave} label="Approved leave" onRetry={retry} />}
        </section>

        <section className="att-overview-card" aria-label="Pending leave approvals">
          <header><h2>Pending leave approvals{approvals.state === 'loaded' ? ` (${approvals.data.count})` : ''}</h2><Link className="att-overview-link" to="/hr/leave-requests">View all</Link></header>
          <PanelState resource={approvals} label="Leave approvals" onRetry={retry} empty={approvals.state === 'loaded' && !approvals.data.count ? 'No leave requests are waiting for your review.' : ''} />
          {approvals.state === 'loaded' && approvals.data.count > 0 && <div className="att-overview-table-scroll"><table className="att-overview-table att-overview-approvals"><thead className="sr-only"><tr><th>Leave type</th><th>Employee</th><th>Starts</th><th>Action</th></tr></thead><tbody>{approvals.data.results.slice(0, 3).map(item => <tr key={item.id}><td><span className="att-overview-inline"><Icons.ClockIcon />{item.leave_type_detail?.name || 'Leave request'}</span></td><td>{item.employee_name || item.employee_code}</td><td>{item.start_date ? dateLabel(item.start_date) : '—'}</td><td><Link className="att-overview-link" to={`/hr/leave-requests/${encodeURIComponent(item.id)}`}>Review</Link></td></tr>)}</tbody></table></div>}
          <p className="att-overview-footnote">Your current review queue · all dates and departments.</p>
        </section>

        <section className="att-overview-card" aria-label="Recent corrections">
          <header><h2>Recent corrections</h2><button type="button" className="att-overview-link" onClick={() => onOpenMatrix(date)}>Open matrix</button></header>
          <PanelState resource={corrections} label="HR corrections" onRetry={retry} empty={corrections.state === 'loaded' && !recent.length ? 'No active corrections for this month.' : ''} />
          {recent.length > 0 && <div className="att-overview-table-scroll"><table className="att-overview-table att-overview-corrections"><thead><tr><th>Employee</th><th>Original</th><th>Corrected</th><th>Recorded by</th><th>Created</th></tr></thead><tbody>{recent.map(item => <tr key={item.id}><td><button type="button" className="att-overview-link" onClick={() => onOpenMatrix(item.date, item.employee_code)}>{item.employee_name || item.employee_code}</button><small>{item.date ? dateLabel(item.date) : '—'}</small></td><td>{hours(overviewNumber(item.original_hours))}</td><td>{hours(overviewNumber(item.override_hours))}</td><td>{item.created_by_name || '—'}</td><td>{timestamp(item.created_at)}</td></tr>)}</tbody></table></div>}
          <p className="att-overview-footnote">Active corrections for {dateObject(date).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' })} · all permitted employees. These are recorded changes.</p>
        </section>
      </div>
    </div>
    <p className="att-overview-scope">Filters apply to attendance records, department figures and trend. Leave and corrections retain their stated scope. Excel includes all permitted records for the selected date.</p>
  </section>
}

import { useEffect, useMemo, useRef, useState } from 'react'
import { useSelector } from 'react-redux'
import * as Icons from '@heroicons/react/24/outline'
import ts from '../../../services/timesheet.service'
import {
  ATTENDANCE_DAILY_COLS, ATTENDANCE_STATUS, OPEN_SHIFT_INDICATOR,
  canEditAttendance, classifyDay, empDept, empName,
} from '../../../config/hrAttendance.config'

const STATUS = [
  { id: 'present', label: 'Present', Icon: Icons.UserIcon },
  { id: 'late', label: 'Late', Icon: Icons.ClockIcon },
  { id: 'half_day', label: 'Half day', Icon: Icons.ClockIcon },
  { id: 'absent', label: 'Absent', Icon: Icons.UserMinusIcon },
  { id: 'in_progress', label: 'In progress', Icon: Icons.ClockIcon },
]
const dateObject = value => new Date(`${value}T12:00:00`)
const dateKey = value => `${value.getFullYear()}-${String(value.getMonth() + 1).padStart(2, '0')}-${String(value.getDate()).padStart(2, '0')}`
const sortValue = (row, column) => {
  if (column.id === 'in' || column.id === 'out') return row[column.id === 'in' ? 'first_in' : 'last_out'] || null
  if (column.cellType === 'hours_worked') return row.open_shift ? null : Number(column.accessor(row))
  if (column.id === 'status') return ATTENDANCE_STATUS[classifyDay(row)]?.label || ''
  return column.accessor(row)
}

export default function DailyAttendanceTab({ rows, date, today, loading, error, source, onDateChange, onRefresh, Pagination, initialSearch = '' }) {
  const [department, setDepartment] = useState('all')
  const [search, setSearch] = useState(initialSearch)
  const [status, setStatus] = useState('all')
  const [density, setDensity] = useState('comfortable')
  const [hiddenColumns, setHiddenColumns] = useState([])
  const [sort, setSort] = useState({ key: 'in', direction: 'asc' })
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(25)
  const [exporting, setExporting] = useState(false)
  const [exportError, setExportError] = useState('')
  const [uploading, setUploading] = useState(false)
  const [uploadError, setUploadError] = useState('')
  const [uploadMessage, setUploadMessage] = useState('')
  const [uploadSelection, setUploadSelection] = useState(null)
  const fileRef = useRef(null)
  const authUser = useSelector(state => state.auth?.user)
  const profile = useSelector(state => state.rbac?.currentUser)
  const canUpload = canEditAttendance(profile, authUser)
  const ready = !loading && !error
  const periodBusy = uploading || exporting
  const progressAvailable = rows.every(row => typeof row.open_shift === 'boolean')
  const departments = useMemo(() => [...new Set(rows.map(empDept))].sort(), [rows])
  const visibleColumns = ATTENDANCE_DAILY_COLS.filter(column => !hiddenColumns.includes(column.id))
  const counts = useMemo(() => {
    const result = { all: rows.length, present: 0, late: 0, half_day: 0, absent: 0, in_progress: 0 }
    for (const row of rows) {
      result[classifyDay(row)]++
      if (row.open_shift) result.in_progress++
    }
    return result
  }, [rows])
  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase()
    const selected = rows.filter(row =>
      (department === 'all' || empDept(row) === department) &&
      (status === 'all' || (status === 'in_progress' ? row.open_shift : classifyDay(row) === status)) &&
      (!query || [empName(row), empDept(row), row.employee_code, row.employee_id, row.radai_email, row.email]
        .some(value => String(value || '').toLowerCase().includes(query)))
    )
    const column = ATTENDANCE_DAILY_COLS.find(item => item.id === sort.key)
    return selected.sort((a, b) => {
      const left = sortValue(a, column), right = sortValue(b, column)
      if (left == null) return right == null ? 0 : 1
      if (right == null) return -1
      const comparison = typeof left === 'number' && typeof right === 'number'
        ? left - right : String(left).localeCompare(String(right), undefined, { numeric: true })
      return sort.direction === 'asc' ? comparison : -comparison
    })
  }, [rows, department, search, status, sort])
  const safePage = Math.min(page, Math.max(1, Math.ceil(filtered.length / pageSize)))
  const paged = filtered.slice((safePage - 1) * pageSize, safePage * pageSize)

  useEffect(() => { setPage(1) }, [date, department, search, status, pageSize, sort])
  useEffect(() => { setExportError('') }, [date])
  useEffect(() => {
    if (ready && !progressAvailable && status === 'in_progress') setStatus('all')
  }, [ready, progressAvailable, status])

  const changeDate = value => {
    if (value && /^\d{4}-\d{2}-\d{2}$/.test(value) && value <= today && !Number.isNaN(dateObject(value).getTime())) onDateChange(value)
  }
  const stepDate = amount => {
    const next = dateObject(date)
    next.setDate(next.getDate() + amount)
    changeDate(dateKey(next))
  }
  const exportDay = async () => {
    setExportError('')
    setExporting(true)
    try { await ts.downloadDailyExcel(date) }
    catch { setExportError('The daily report could not be exported. Please try again.') }
    finally { setExporting(false) }
  }
  const uploadHours = async (selection = uploadSelection) => {
    if (!selection?.file || !canUpload) return
    setUploading(true)
    setUploadError('')
    setUploadMessage('')
    try {
      const { file, year, month } = selection
      const result = await ts.uploadDailyAttendance(file, year, month)
      if (fileRef.current) fileRef.current.value = ''
      setUploadSelection(null)
      setUploadMessage(`Imported ${(result.created || 0) + (result.updated || 0)} daily entries for ${year}-${String(month).padStart(2, '0')}${result.skipped ? ` · ${result.skipped} skipped` : ''}.`)
      onRefresh()
    } catch (failure) {
      const data = failure?.response?.data
      setUploadError(data?.detail || data?.errors?.[0]?.error || 'Attendance upload failed. Please retry.')
    } finally { setUploading(false) }
  }
  const selectUpload = event => {
    const file = event.target.files?.[0]
    if (!file) return
    const [year, month] = date.split('-').map(Number)
    const selection = { file, year, month }
    setUploadSelection(selection)
    uploadHours(selection)
  }
  const countLabel = key => ready && (key !== 'in_progress' || progressAvailable) ? counts[key].toLocaleString() : '—'
  const hasFilters = department !== 'all' || search || status !== 'all'
  const summaryItems = [{ id: 'all', label: 'Attendance records', Icon: Icons.UserGroupIcon }, ...STATUS]

  return (
    <section className="att-daily" data-density={density} aria-label="Daily attendance">
      <div className="att-filter-panel att-daily-toolbar" aria-label="Daily attendance filters">
        <div className="att-date-navigation">
          <button type="button" className="att-button" aria-label="Previous day" disabled={periodBusy} onClick={() => stepDate(-1)}><Icons.ChevronLeftIcon aria-hidden="true" /></button>
          <label className="att-date-picker">
            <Icons.CalendarDaysIcon aria-hidden="true" />
            <span>{date === today ? 'Today · ' : ''}{dateObject(date).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' })}</span>
            <input type="date" aria-label="Attendance date" value={date} max={today} disabled={periodBusy} onChange={event => changeDate(event.target.value)} />
          </label>
          <button type="button" className="att-button" aria-label="Next day" disabled={date >= today || periodBusy} onClick={() => stepDate(1)}><Icons.ChevronRightIcon aria-hidden="true" /></button>
          {date !== today && <button type="button" className="att-button" disabled={periodBusy} onClick={() => changeDate(today)}>Today</button>}
        </div>
        <label className="att-field att-daily-department"><span>Department</span>
          <select aria-label="Department" value={department} onChange={event => setDepartment(event.target.value)}>
            <option value="all">All departments</option>
            {department !== 'all' && !departments.includes(department) && <option value={department}>{department}</option>}
            {departments.map(item => <option key={item} value={item}>{item}</option>)}
          </select>
        </label>
        <label className="att-field att-search"><span className="sr-only">Search employees</span>
          <div className="att-search-box"><Icons.MagnifyingGlassIcon aria-hidden="true" /><input aria-label="Search employees" value={search} placeholder="Employee name or ID" onChange={event => setSearch(event.target.value)} /></div>
        </label>
        <div className="att-daily-tools">
          <details className="att-columns" onKeyDown={event => { if (event.key === 'Escape') { event.currentTarget.open = false; event.currentTarget.querySelector('summary')?.focus() } }}>
            <summary className="att-button"><Icons.ViewColumnsIcon aria-hidden="true" />Columns<Icons.ChevronDownIcon aria-hidden="true" /></summary>
            <div className="att-columns-panel">
              {ATTENDANCE_DAILY_COLS.filter(column => column.id !== 'name').map(column => <label key={column.id}>
                <input type="checkbox" checked={!hiddenColumns.includes(column.id)} onChange={event => setHiddenColumns(previous => event.target.checked ? previous.filter(id => id !== column.id) : [...previous, column.id])} />{column.label}
              </label>)}
            </div>
          </details>
          <label className="att-density"><span className="sr-only">Density</span><select aria-label="Density" value={density} onChange={event => setDensity(event.target.value)}><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label>
          <button type="button" className="att-button" disabled={exporting || !ready} title="Export all attendance records for the selected date" onClick={exportDay}><Icons.ArrowDownTrayIcon aria-hidden="true" />{exporting ? 'Exporting…' : 'Export'}</button>
          <button type="button" className="att-button" aria-label="Refresh daily attendance" disabled={loading || uploading} onClick={onRefresh}><Icons.ArrowPathIcon aria-hidden="true" /></button>
          {canUpload && <label className="att-button att-upload"><Icons.ArrowUpTrayIcon aria-hidden="true" />{uploading ? 'Importing…' : 'Upload daily hours'}
            <input ref={fileRef} className="att-file-input" type="file" aria-label="Upload daily hours" accept=".xlsx,.csv" disabled={uploading} onChange={selectUpload} />
          </label>}
        </div>
      </div>

      {exportError && <div className="att-daily-error" role="alert">{exportError}<button type="button" className="att-button" disabled={exporting} onClick={exportDay}>Retry export</button></div>}
      {uploadError && <div className="att-daily-error" role="alert"><span>{uploadError}{uploadSelection && ` Upload period: ${uploadSelection.year}-${String(uploadSelection.month).padStart(2, '0')}.`}</span><button type="button" className="att-button" disabled={uploading} onClick={() => uploadHours()}>Retry upload</button></div>}
      {uploadMessage && <p className="att-daily-notice" role="status">{uploadMessage}</p>}

      <dl className="att-summary att-daily-summary" aria-label="Daily attendance summary" title="Counts cover all returned attendance records for the selected date. In progress can also be included in a daily status.">
        {summaryItems.map(({ id, label, Icon }) => <div className="att-summary-item" data-status={id} key={id} title={id === 'in_progress' && !progressAvailable ? 'Open-shift information is unavailable for this source.' : undefined}>
          <Icon aria-hidden="true" /><div><dt>{label}</dt><dd>{countLabel(id)}</dd></div>
        </div>)}
      </dl>

      <div className="att-status-filters" role="group" aria-label="Filter daily status">
        {summaryItems.map(({ id, label, Icon }) => <button type="button" key={id} className="att-status-filter" data-status={id} aria-pressed={status === id} disabled={id === 'in_progress' && !progressAvailable} onClick={() => setStatus(id)}>
          <Icon aria-hidden="true" />{id === 'all' ? 'All' : label} ({countLabel(id)})
        </button>)}
      </div>

      <div className="att-daily-panel" aria-busy={loading}>
        <div className="att-daily-table-heading">
          <span>{ready ? `${filtered.length.toLocaleString()} attendance records` : 'Attendance records'} · {date}</span>
          {ready && <span className="att-daily-source"><Icons.CircleStackIcon aria-hidden="true" />{source || 'Attendance records'}</span>}
        </div>
        {loading ? <div className="att-daily-empty" role="status"><Icons.ArrowPathIcon className="animate-spin" aria-hidden="true" />Loading daily attendance…</div>
          : error ? <div className="att-daily-empty att-daily-load-error" role="alert"><Icons.ExclamationTriangleIcon aria-hidden="true" /><p>{error}</p><button type="button" className="att-button" onClick={onRefresh}>Retry</button></div>
            : !filtered.length ? <div className="att-daily-empty" role="status"><Icons.CalendarDaysIcon aria-hidden="true" /><p>{hasFilters ? 'No attendance records match these filters.' : 'No attendance records for the selected date.'}</p>{hasFilters && <button type="button" className="att-button" onClick={() => { setSearch(''); setDepartment('all'); setStatus('all') }}>Clear filters</button>}</div>
              : <>
                <div className="att-table-scroll" role="region" aria-label="Daily attendance table" tabIndex={0}>
                  <table className="att-daily-table">
                    <caption className="sr-only">Attendance records for {date}</caption>
                    <thead><tr>{visibleColumns.map(column => <th key={column.id} scope="col" aria-sort={sort.key === column.id ? (sort.direction === 'asc' ? 'ascending' : 'descending') : 'none'}>
                      <button type="button" aria-label={`Sort by ${column.label}`} onClick={() => setSort(previous => ({ key: column.id, direction: previous.key === column.id && previous.direction === 'asc' ? 'desc' : 'asc' }))}>{column.label}<Icons.ChevronUpDownIcon aria-hidden="true" /></button>
                    </th>)}</tr></thead>
                    <tbody>{paged.map((row, index) => <tr key={`${row.employee_code || row.radai_user_id || 'record'}:${row.first_in || ''}:${index}`}>
                      {visibleColumns.map(column => {
                        const value = column.accessor(row)
                        if (column.cellType === 'att_status') {
                          const { Icon = Icons.UserIcon } = STATUS.find(item => item.id === value) || {}
                          return <td key={column.id}><span className="att-daily-status" data-status={value}><Icon aria-hidden="true" />{ATTENDANCE_STATUS[value]?.label || value}</span></td>
                        }
                        if (column.cellType === 'hours_worked') return <td key={column.id} className="att-daily-hours">
                          {row.open_shift ? <span className="att-in-progress" title={OPEN_SHIFT_INDICATOR.tooltip}><Icons.ClockIcon aria-hidden="true" />{OPEN_SHIFT_INDICATOR.label}{OPEN_SHIFT_INDICATOR.maxCreditedH > 0 && Number(value) > 0 ? ` (${Number(value).toFixed(1)}h)` : ''}</span>
                            : Number(value) > 0 ? `${Number(value).toFixed(1)}h` : '—'}
                        </td>
                        return <td key={column.id} title={String(value)}>{value}</td>
                      })}
                    </tr>)}</tbody>
                  </table>
                </div>
                <Pagination total={filtered.length} page={safePage} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={setPageSize} itemLabel="records" />
              </>}
      </div>
    </section>
  )
}

import { radaiConfirm } from '../../../services/radaiDialog'
/**
 * Leave Dashboard — HR Leave Management
 * ======================================
 * Displays leave data imported from "Summary Leave Calculation-RAD-Updated.xlsx"
 * Source: /api/v1/payroll/leave-records/
 *
 * Views:  Overview  ·  Employee Detail  ·  Reports
 * All config (thresholds, colours, columns) → hrLeave.config.js
 */
import { useCallback, useEffect, useMemo, useState } from 'react'
import { useSearchParams } from 'react-router-dom'
import OvertimeManagement from '../OvertimeManagement'
import { createPortal } from 'react-dom'
import { useSelector } from 'react-redux'
import * as HeroIcons from '@heroicons/react/24/outline'
import {
  BarChart, Bar, LineChart, Line, PieChart, Pie, Cell,
  XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer,
} from 'recharts'
import payrollService from '../../../services/payroll.service'
import { BRANCHES, getBranch, LEAVE_YEAR, DEFAULT_ANNUAL_ENTITLEMENT, LEAVE_ENCASHMENT_WORKING_DAYS } from '../../../config/hrLeave.config'

// ─────────────────────────────────────────────────────────────────────────────
// CONFIG — all soft-coded constants
// ─────────────────────────────────────────────────────────────────────────────
const YEAR = LEAVE_YEAR
const ANNUAL_ENTITLEMENT = DEFAULT_ANNUAL_ENTITLEMENT

const BALANCE_TIERS = [
  { label: 'Surplus (> 5)',   min: 5,   max: Infinity, color: '#10b981', bg: 'bg-emerald-50',  text: 'text-emerald-700',  border: 'border-emerald-200' },
  { label: 'Low (0 – 5)',     min: 0,   max: 5,        color: '#f59e0b', bg: 'bg-amber-50',    text: 'text-amber-700',    border: 'border-amber-200' },
  { label: 'Negative',        min: -Infinity, max: 0,  color: '#ef4444', bg: 'bg-rose-50',     text: 'text-rose-700',     border: 'border-rose-200' },
]

const balanceTier = (balance) => {
  const b = Number(balance)
  return BALANCE_TIERS.find(t => b > t.min || (b >= t.min && t.min === t.max)) ||
         BALANCE_TIERS.find(t => b >= t.min && b < t.max) ||
         (b >= 5 ? BALANCE_TIERS[0] : b >= 0 ? BALANCE_TIERS[1] : BALANCE_TIERS[2])
}

const MONTH_LABELS = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec']

const LIST_COLS = [
  { id: 'name',    label: 'Employee',    accessor: r => r.employee_name },
  { id: 'code',    label: 'Code',        accessor: r => r.employee_code || '—' },
  { id: 'dept',    label: 'Department',  accessor: r => r.department || '—' },
  { id: 'title',   label: 'Title',       accessor: r => r.job_title   || '—' },
  { id: 'joining', label: 'Joined',      accessor: r => r.joining_date ? r.joining_date.slice(0, 10) : '—' },
  { id: 'earned',  label: 'Earned',      accessor: r => Number(r.total_earned).toFixed(2),  cellType: 'number' },
  { id: 'taken',   label: 'Taken',       accessor: r => Number(r.total_taken).toFixed(2),   cellType: 'taken' },
  { id: 'encashed',label: 'Encashed',    accessor: r => Number(r.total_encashed).toFixed(2), cellType: 'number' },
  { id: 'balance', label: 'Balance',     accessor: r => Number(r.leave_balance).toFixed(2), cellType: 'balance' },
]

const PAGE_SIZE_OPTIONS = [25, 50, 100, 'All']
const ALL_DEPTS = 'all'

// ─────────────────────────────────────────────────────────────────────────────
// Sub-components
// ─────────────────────────────────────────────────────────────────────────────
const Spinner = () => (
  <svg className="animate-spin w-4 h-4 text-blue-500" fill="none" viewBox="0 0 24 24">
    <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
    <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8v8z" />
  </svg>
)

const BalanceBadge = ({ value }) => {
  const tier = balanceTier(value)
  return (
    <span className={`inline-flex px-2 py-0.5 rounded-full text-xs font-semibold border ${tier.bg} ${tier.text} ${tier.border}`}>
      {Number(value).toFixed(1)} d
    </span>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Main Component
// ─────────────────────────────────────────────────────────────────────────────
const VIEWS = [
  { id: 'overview',    label: 'Overview',   icon: 'ChartBarSquareIcon' },
  { id: 'list',        label: 'Employees',  icon: 'TableCellsIcon' },
  { id: 'detail',      label: 'Detail',     icon: 'UserCircleIcon' },
  { id: 'requests',    label: 'Requests',   icon: 'ClipboardDocumentListIcon' },
  { id: 'encashment',  label: 'Encashment', icon: 'BanknotesIcon' },
]

export default function LeaveDashboard({ headerActions = null }) {
  const [params] = useSearchParams()
  const [view,        setView]        = useState(() => params.get('view') === 'encashment' ? 'encashment' : 'overview')
  useEffect(() => { if (params.get('view') === 'encashment') setView('encashment') }, [params])
  const [records,     setRecords]     = useState([])    // full unfiltered list for counts
  const [loading,     setLoading]     = useState(false)
  const [branch,      setBranch]      = useState(null)  // null = All | 'RAD' | 'RIN'
  const [search,      setSearch]      = useState('')
  const [deptFilter,  setDeptFilter]  = useState(ALL_DEPTS)
  const [selected,    setSelected]    = useState(null)  // full record with monthly breakdown
  const [detailLoading, setDetailLoading] = useState(false)
  const [pageSize,    setPageSize]    = useState(50)
  const [page,        setPage]        = useState(1)
  const [sortCol,     setSortCol]     = useState('name')
  const [sortAsc,     setSortAsc]     = useState(true)
  const [cfEditing,   setCfEditing]   = useState(false)  // carry-forward inline edit mode
  const [cfValue,     setCfValue]     = useState('')
  const [cfSaving,    setCfSaving]    = useState(false)
  const [cfMsg,       setCfMsg]       = useState(null)   // { type: 'ok'|'err', text }

  // ── Requests view state ────────────────────────────────────────────────────
  // 'rm_pending'  → PENDING requests (awaiting Reporting Manager)
  // 'hr_pending'  → RM_APPROVED requests (awaiting HR final approval)
  // 'new'         → Submit new request form
  // 'history'     → Resolved requests
  const [reqTab,       setReqTab]       = useState('rm_pending')
  const [leaveTypes,   setLeaveTypes]   = useState([])
  const [requests,     setRequests]     = useState([])
  const [reqLoading,   setReqLoading]   = useState(false)
  const [reqNote,      setReqNote]      = useState('')       // reviewer note for approve/reject
  const [formState,    setFormState]    = useState({
    employee_name: '', employee_code: '', department: '',
    leave_type: '', start_date: '', end_date: '', reason: '',
  })
  const [formBusy,     setFormBusy]     = useState(false)
  const [formMsg,      setFormMsg]      = useState(null)     // { type: 'ok'|'err', text }
  const [reviewBusy,   setReviewBusy]   = useState(null)     // UUID being reviewed

  // ── Encashment view state ──────────────────────────────────────────────────
  const today        = new Date()
  const [encYear,    setEncYear]    = useState(today.getFullYear())
  const [encMonth,   setEncMonth]   = useState(today.getMonth() + 1)
  const [encStatus,  setEncStatus]  = useState(null)   // LeaveEncashmentRun | null | 'not_run'
  const [encPreview, setEncPreview] = useState(null)   // preview rows array
  const [encLoading, setEncLoading] = useState(false)
  const [encRunning, setEncRunning] = useState(false)
  const [encMsg,     setEncMsg]     = useState(null)   // { type: 'ok'|'err', text }
  const [encConfirm, setEncConfirm] = useState(false)  // show confirm modal

  // ── Fetch all records ──────────────────────────────────────────────────────
  const loadRecords = useCallback(() => {
    setLoading(true)
    const params = { year: YEAR, page_size: 500 }
    if (branch) params.branch = branch
    return payrollService.getLeaveRecords(params)
      .then(d => setRecords(Array.isArray(d) ? d : (d?.results ?? [])))
      .catch(() => setRecords([]))
      .finally(() => setLoading(false))
  }, [branch])

  useEffect(() => { loadRecords() }, [loadRecords])

  // ── Departments list ───────────────────────────────────────────────────────
  const departments = useMemo(() =>
    [...new Set(records.map(r => r.department).filter(Boolean))].sort(),
    [records]
  )

  // ── Filtered + sorted list ─────────────────────────────────────────────────
  const filtered = useMemo(() => {
    let d = records
    if (deptFilter !== ALL_DEPTS) d = d.filter(r => r.department === deptFilter)
    if (search.trim()) {
      const s = search.toLowerCase()
      d = d.filter(r =>
        r.employee_name?.toLowerCase().includes(s) ||
        r.employee_code?.toLowerCase().includes(s) ||
        r.job_title?.toLowerCase().includes(s)
      )
    }
    return [...d].sort((a, b) => {
      let av = LIST_COLS.find(c => c.id === sortCol)?.accessor(a) ?? ''
      let bv = LIST_COLS.find(c => c.id === sortCol)?.accessor(b) ?? ''
      const cmp = String(av).localeCompare(String(bv), undefined, { numeric: true })
      return sortAsc ? cmp : -cmp
    })
  }, [records, deptFilter, search, sortCol, sortAsc])

  const totalPages = pageSize === 'All' ? 1 : Math.ceil(filtered.length / pageSize)
  const paginated  = pageSize === 'All' ? filtered : filtered.slice((page - 1) * pageSize, page * pageSize)

  // ── Sort toggle ────────────────────────────────────────────────────────────
  const toggleSort = (id) => {
    if (sortCol === id) setSortAsc(a => !a)
    else { setSortCol(id); setSortAsc(true) }
  }

  // ── Load detail ────────────────────────────────────────────────────────────
  const loadDetail = useCallback((rec, { preserveCfMsg = false } = {}) => {
    setDetailLoading(true)
    setView('detail')
    if (!preserveCfMsg) { setCfEditing(false); setCfMsg(null) }
    payrollService.getLeaveRecord(rec.id)
      .then(d => setSelected(d))
      .catch(() => setSelected(rec))
      .finally(() => setDetailLoading(false))
  }, [])

  // ── Edit carry forward (HR/Admin only) ─────────────────────────────────────
  const startEditCarryforward = () => {
    setCfValue(String(selected?.carryforward ?? 0))
    setCfMsg(null)
    setCfEditing(true)
  }

  const cancelEditCarryforward = () => {
    setCfEditing(false)
    setCfMsg(null)
  }

  const saveCarryforward = async () => {
    const parsed = Number(cfValue)
    if (Number.isNaN(parsed)) {
      setCfMsg({ type: 'err', text: 'Enter a valid number.' })
      return
    }
    setCfSaving(true)
    setCfMsg(null)
    try {
      await payrollService.updateLeaveRecordCarryforward(selected.id, parsed)
      setCfEditing(false)
      setCfMsg({ type: 'ok', text: 'Carry forward updated.' })
      loadDetail(selected, { preserveCfMsg: true })
      // Refresh the records list too — Avg Balance KPI, dept chart, and the
      // Employees-tab list all derive from it via useMemo, so this is the
      // one call needed to bring every other Leave Balance view up to date.
      loadRecords()
    } catch (e) {
      const msg = e?.response?.data?.error || e?.response?.data?.detail || e?.message || 'Failed to update carry forward.'
      setCfMsg({ type: 'err', text: msg })
    } finally {
      setCfSaving(false)
    }
  }

  // ── Load leave types (once) ────────────────────────────────────────────────
  useEffect(() => {
    payrollService.getLeaveTypes()
      .then(d => setLeaveTypes(Array.isArray(d) ? d : (d?.results ?? [])))
      .catch(() => {})
  }, [])

  // ── Role checks ───────────────────────────────────────────────────────────
  const rbacUser    = useSelector(s => s.rbac?.currentUser)
  const authUser    = useSelector(s => s.auth?.user)
  // authUser is the raw UserProfileSerializer payload — is_staff/is_superuser
  // live on the nested `user` object (UserSerializer), not at the top level.
  const isHRManager = (
    authUser?.user?.is_staff ||
    authUser?.user?.is_superuser ||
    rbacUser?.roles?.some(r =>
      r.code?.startsWith('hr') || ['admin', 'superadmin', 'super_admin'].includes(r.code)
    )
  ) ?? false
  // Reporting Manager: any staff user can action Stage-1
  const isManager = authUser?.user?.is_staff || authUser?.user?.is_superuser ||
    rbacUser?.roles?.some(r => (r.level ?? 0) >= 3 || r.code?.includes('manager') || r.code?.includes('senior'))

  // ── Load requests whenever requests tab is active ──────────────────────────
  useEffect(() => {
    if (view !== 'requests') return
    setReqLoading(true)
    let params = {}
    if      (reqTab === 'rm_pending')  params = { status: 'PENDING' }
    else if (reqTab === 'hr_pending')  params = { status: 'RM_APPROVED' }
    // Multi-status filters must use `status__in` — the backend only splits
    // on commas for that param name; plain `status` does an exact match
    // against the whole string, so a comma-joined list here always matched
    // zero rows.
    else if (reqTab === 'history')     params = { status__in: 'APPROVED,REJECTED,CANCELLED,RM_REJECTED' }
    // 'new' tab: no fetch needed
    if (reqTab !== 'new') {
      payrollService.getLeaveRequests(params)
        .then(d => setRequests(Array.isArray(d) ? d : (d?.results ?? [])))
        .catch(() => setRequests([]))
        .finally(() => setReqLoading(false))
    } else {
      setReqLoading(false)
    }
  }, [view, reqTab])

  // ── Working days preview for the new-request form ─────────────────────────
  const formWorkDays = useMemo(() => {
    if (!formState.start_date || !formState.end_date) return null
    const s = new Date(formState.start_date)
    const e = new Date(formState.end_date)
    if (e < s) return null
    let d = 0; let c = new Date(s)
    while (c <= e) { if (c.getDay() !== 0 && c.getDay() !== 6) d++; c = new Date(c.getFullYear(), c.getMonth(), c.getDate() + 1) }
    return d
  }, [formState.start_date, formState.end_date])

  // ── Submit new leave request ───────────────────────────────────────────────
  const submitRequest = async () => {
    if (!formState.employee_name || !formState.leave_type || !formState.start_date || !formState.end_date) {
      setFormMsg({ type: 'err', text: 'Please fill in all required fields.' })
      return
    }
    setFormBusy(true)
    setFormMsg(null)
    try {
      await payrollService.createLeaveRequest({
        employee_name: formState.employee_name,
        employee_code: formState.employee_code || undefined,
        department:    formState.department    || undefined,
        leave_type:    Number(formState.leave_type),
        start_date:    formState.start_date,
        end_date:      formState.end_date,
        reason:        formState.reason,
      })
      setFormMsg({ type: 'ok', text: 'Leave request submitted successfully.' })
      setFormState({ employee_name: '', employee_code: '', department: '', leave_type: '', start_date: '', end_date: '', reason: '' })
    } catch {
      setFormMsg({ type: 'err', text: 'Failed to submit request. Please try again.' })
    } finally {
      setFormBusy(false)
    }
  }

  // ── Approve / Reject helper ────────────────────────────────────────────────
  const reviewRequest = async (id, action) => {
    setReviewBusy(id)
    try {
      if (action === 'rm_approve') await payrollService.rmApproveLeaveRequest(id, reqNote)
      else if (action === 'rm_reject') await payrollService.rmRejectLeaveRequest(id, reqNote)
      else if (action === 'approve')   await payrollService.approveLeaveRequest(id, reqNote)
      else                             await payrollService.rejectLeaveRequest(id, reqNote)
      setRequests(prev => prev.filter(r => r.id !== id))
    } catch (e) {
      const msg = e?.response?.data?.error || e?.message || 'Action failed'
      setFormMsg({ type: 'err', text: msg })
    }
    finally { setReviewBusy(null); setReqNote('') }
  }

  const cancelRequest = async (id) => {
    setReviewBusy(id)
    try {
      await payrollService.cancelLeaveRequest(id)
      setRequests(prev => prev.filter(r => r.id !== id))
    } catch {
      // The list remains unchanged when cancellation fails.
    }
    finally { setReviewBusy(null) }
  }

  // ── Initialize Current Month Leave ─────────────────────────────────────────
  const [initBusy, setInitBusy] = useState(false)
  const [initMsg, setInitMsg] = useState(null)  // { type: 'ok'|'err', text }
  
  const initializeCurrentMonthLeave = async () => {
    if (!(await radaiConfirm(
      `Initialize current month leave balance to 1.83 days for all employees?\n\n` +
      `This will set the earned value for ${new Date().toLocaleString('default', { month: 'long' })} ${YEAR} ` +
      `to the standard monthly accrual (1.83 days = 22 days/year ÷ 12 months).`
    ))) return
    
    setInitBusy(true)
    setInitMsg(null)
    try {
      const result = await payrollService.initializeCurrentMonthLeave({ 
        year: YEAR,
        month: new Date().getMonth() + 1,  // current month
        branch: branch || undefined,
      })
      setInitMsg({ 
        type: 'ok', 
        text: `✅ Initialized ${result.records_created} new records, updated ${result.records_updated} existing records. Monthly accrual: ${result.monthly_accrual.toFixed(2)} days.` 
      })
      // Reload records to show updated balances
      setTimeout(() => {
        const params = { year: YEAR, page_size: 500 }
        if (branch) params.branch = branch
        payrollService.getLeaveRecords(params)
          .then(d => setRecords(Array.isArray(d) ? d : (d?.results ?? [])))
          .catch(() => {})
      }, 500)
    } catch (e) {
      const msg = e?.response?.data?.error || e?.message || 'Initialization failed'
      setInitMsg({ type: 'err', text: `❌ ${msg}` })
    } finally {
      setInitBusy(false)
    }
  }

  // ─────────────────────────────────────────────────────────────────────────
  // KPI computations
  // ─────────────────────────────────────────────────────────────────────────
  const kpis = useMemo(() => {
    const total     = records.length
    const negative  = records.filter(r => Number(r.leave_balance) < 0).length
    const low       = records.filter(r => Number(r.leave_balance) >= 0 && Number(r.leave_balance) < 5).length
    const surplus   = records.filter(r => Number(r.leave_balance) >= 5).length
    const totalTaken  = records.reduce((s, r) => s + Number(r.total_taken  || 0), 0)
    const totalEncash = records.reduce((s, r) => s + Number(r.total_encashed || 0), 0)
    const avgBalance  = total > 0
      ? (records.reduce((s, r) => s + Number(r.leave_balance || 0), 0) / total).toFixed(2)
      : 0
    return { total, negative, low, surplus, totalTaken, totalEncash, avgBalance }
  }, [records])

  // ─────────────────────────────────────────────────────────────────────────
  // Chart data
  // ─────────────────────────────────────────────────────────────────────────
  const deptChart = useMemo(() => {
    const map = {}
    records.forEach(r => {
      const d = r.department || 'Unassigned'
      if (!map[d]) map[d] = { dept: d.slice(0, 15), taken: 0, encashed: 0, balance: 0, count: 0 }
      map[d].taken    += Number(r.total_taken    || 0)
      map[d].encashed += Number(r.total_encashed || 0)
      map[d].balance  += Number(r.leave_balance  || 0)
      map[d].count++
    })
    return Object.values(map).sort((a, b) => b.count - a.count).slice(0, 12)
  }, [records])

  const balanceDist = useMemo(() => [
    { name: 'Surplus ≥5d',  value: kpis.surplus,  fill: '#10b981' },
    { name: 'Low 0–5d',     value: kpis.low,       fill: '#f59e0b' },
    { name: 'Negative',     value: kpis.negative,  fill: '#ef4444' },
  ].filter(d => d.value > 0), [kpis])

  const topNegative = useMemo(() =>
    [...records]
      .filter(r => Number(r.leave_balance) < 0)
      .sort((a, b) => Number(a.leave_balance) - Number(b.leave_balance))
      .slice(0, 10),
    [records]
  )

  // ─────────────────────────────────────────────────────────────────────────
  // OVERVIEW VIEW
  // ─────────────────────────────────────────────────────────────────────────
  const renderOverview = () => (
    <div className="space-y-5">
      {/* KPI Row */}
      <div className="grid grid-cols-2 sm:grid-cols-3 xl:grid-cols-6 gap-3">
        {[
          { label: 'Total Employees', value: kpis.total,      icon: 'UsersIcon',         bg: 'bg-blue-50',    text: 'text-blue-700' },
          { label: 'Surplus Balance', value: kpis.surplus,    icon: 'CheckCircleIcon',   bg: 'bg-emerald-50', text: 'text-emerald-700' },
          { label: 'Low Balance',     value: kpis.low,        icon: 'ExclamationCircleIcon', bg: 'bg-amber-50', text: 'text-amber-700' },
          { label: 'Negative Balance',value: kpis.negative,   icon: 'XCircleIcon',       bg: 'bg-rose-50',    text: 'text-rose-700' },
          { label: 'Total Days Taken',value: kpis.totalTaken.toFixed(0), icon: 'CalendarDaysIcon', bg: 'bg-purple-50', text: 'text-purple-700' },
          { label: 'Avg Balance',     value: `${kpis.avgBalance}d`, icon: 'ScaleIcon',   bg: 'bg-slate-50',   text: 'text-slate-700' },
        ].map(k => {
          const Icon = HeroIcons[k.icon] || HeroIcons.ChartBarIcon
          return (
            <div key={k.label} className={`${k.bg} rounded-xl p-4 border border-slate-200 bg-gradient-to-br to-white`}>
              <div className="flex items-center justify-between mb-2">
                <span className="text-xs font-medium text-slate-600">{k.label}</span>
                <Icon className={`w-4 h-4 ${k.text}`} />
              </div>
              <div className={`text-2xl font-semibold tabular-nums ${k.text}`}>{loading ? '…' : k.value}</div>
            </div>
          )
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Dept bar chart */}
        <div className="bg-white rounded-xl border border-slate-200 p-4">
          <h3 className="text-sm font-semibold text-slate-700 mb-3 flex items-center gap-2">
            <HeroIcons.BuildingOfficeIcon className="w-4 h-4 text-slate-400" />
            Leave Taken + Encashed by Department
          </h3>
          {deptChart.length > 0 ? (
            <ResponsiveContainer width="100%" height={220}>
              <BarChart data={deptChart} margin={{ top: 5, right: 20, bottom: 30, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                <XAxis dataKey="dept" tick={{ fontSize: 10 }} angle={-30} textAnchor="end" interval={0} />
                <YAxis tick={{ fontSize: 11 }} />
                <Tooltip />
                <Legend iconSize={10} wrapperStyle={{ fontSize: 11 }} />
                <Bar dataKey="taken"    name="Days Taken"    fill="#3b82f6" radius={[3,3,0,0]} />
                <Bar dataKey="encashed" name="Days Encashed" fill="#8b5cf6" radius={[3,3,0,0]} />
              </BarChart>
            </ResponsiveContainer>
          ) : <div className="h-32 flex items-center justify-center text-slate-400 text-sm">{loading ? <Spinner /> : 'No data'}</div>}
        </div>

        {/* Balance distribution pie */}
        <div className="bg-white rounded-xl border border-slate-200 p-4">
          <h3 className="text-sm font-semibold text-slate-700 mb-3 flex items-center gap-2">
            <HeroIcons.ChartPieIcon className="w-4 h-4 text-slate-400" />
            Leave Balance Distribution
          </h3>
          {balanceDist.length > 0 ? (
            <ResponsiveContainer width="100%" height={220}>
              <PieChart>
                <Pie data={balanceDist} cx="50%" cy="50%" innerRadius={55} outerRadius={85}
                  paddingAngle={3} dataKey="value" nameKey="name" label={({ name, value }) => `${value}`}>
                  {balanceDist.map((e, i) => <Cell key={i} fill={e.fill} />)}
                </Pie>
                <Tooltip formatter={(v, n) => [`${v} employees`, n]} />
                <Legend iconSize={10} wrapperStyle={{ fontSize: 11 }} />
              </PieChart>
            </ResponsiveContainer>
          ) : <div className="h-32 flex items-center justify-center text-slate-400 text-sm">{loading ? <Spinner /> : 'No data'}</div>}
        </div>
      </div>

      {/* Negative balance alert */}
      {topNegative.length > 0 && (
        <div className="bg-rose-50 border border-rose-200 rounded-xl p-4">
          <h3 className="text-sm font-semibold text-rose-800 mb-2 flex items-center gap-1.5">
            <HeroIcons.ExclamationTriangleIcon className="w-4 h-4" />
            Employees with Negative Leave Balance ({topNegative.length})
          </h3>
          <div className="flex flex-wrap gap-2">
            {topNegative.map((r, i) => (
              <button key={i} type="button" onClick={() => loadDetail(r)}
                className="bg-white text-rose-700 text-xs px-3 py-1.5 rounded-full border border-rose-200 hover:bg-rose-100 transition flex items-center gap-1.5">
                <span>{r.employee_name}</span>
                <span className="font-bold">{Number(r.leave_balance).toFixed(1)}d</span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  )

  // ─────────────────────────────────────────────────────────────────────────
  // LIST VIEW
  // ─────────────────────────────────────────────────────────────────────────
  const renderList = () => (
    <div className="space-y-3">
      {/* Controls */}
      <div className="bg-white rounded-xl border border-slate-200 p-4 flex flex-wrap gap-3 items-end">
        <div className="flex-1 min-w-48">
          <label className="block text-xs text-slate-500 mb-1">Search employee</label>
          <div className="relative">
            <HeroIcons.MagnifyingGlassIcon className="w-4 h-4 absolute left-2.5 top-2.5 text-slate-400" />
            <input value={search} onChange={e => { setSearch(e.target.value); setPage(1) }}
              placeholder="Name, code, or title…"
              className="w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" />
          </div>
        </div>
        <div className="min-w-44">
          <label className="block text-xs text-slate-500 mb-1">Department</label>
          <select value={deptFilter} onChange={e => { setDeptFilter(e.target.value); setPage(1) }}
            className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500">
            <option value={ALL_DEPTS}>All Departments</option>
            {departments.map(d => <option key={d} value={d}>{d}</option>)}
          </select>
        </div>
        <div>
          <label className="block text-xs text-slate-500 mb-1">Rows</label>
          <select value={pageSize} onChange={e => { setPageSize(e.target.value === 'All' ? 'All' : Number(e.target.value)); setPage(1) }}
            className="px-3 py-2 border border-slate-300 rounded-lg text-sm">
            {PAGE_SIZE_OPTIONS.map(o => <option key={o} value={o}>{o}</option>)}
          </select>
        </div>
        <div className="ml-auto text-xs text-slate-500 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2">
          <span className="font-semibold">{filtered.length}</span> of {records.length} employees
        </div>
      </div>

      {/* Table */}
      {loading ? (
        <div className="flex items-center justify-center h-32 gap-2 text-slate-400 text-sm"><Spinner /> Loading…</div>
      ) : (
        <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
          <div className="overflow-x-auto">
            <table className="min-w-full text-sm">
              <thead className="bg-slate-50">
                <tr>
                  {LIST_COLS.map(c => (
                    <th key={c.id} onClick={() => toggleSort(c.id)}
                      className="text-left px-3 py-2.5 text-xs font-semibold text-slate-600 uppercase tracking-wider whitespace-nowrap cursor-pointer hover:bg-slate-100 transition select-none">
                      <div className="flex items-center gap-1">
                        {c.label}
                        {sortCol === c.id && (
                          sortAsc
                            ? <HeroIcons.ChevronUpIcon className="w-3 h-3" />
                            : <HeroIcons.ChevronDownIcon className="w-3 h-3" />
                        )}
                      </div>
                    </th>
                  ))}                    <th className="text-left px-3 py-2.5 text-xs font-semibold text-slate-600 uppercase tracking-wider">Branch</th>                  <th className="text-left px-3 py-2.5 text-xs font-semibold text-slate-600 uppercase tracking-wider"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {paginated.length === 0 ? (
                  <tr><td colSpan={LIST_COLS.length + 2} className="text-center py-10 text-slate-400 text-sm">No records found</td></tr>
                ) : paginated.map((r) => {
                  const balance   = Number(r.leave_balance)
                  const branchMeta = getBranch(r.branch)
                  return (
                    <tr key={r.id} className={`hover:bg-slate-50 transition-colors ${balance < 0 ? 'bg-rose-50/30' : ''}`}>
                      {LIST_COLS.map(c => {
                        const v = c.accessor(r)
                        if (c.cellType === 'balance') {
                          return <td key={c.id} className="px-3 py-2.5"><BalanceBadge value={r.leave_balance} /></td>
                        }
                        if (c.cellType === 'taken') {
                          return <td key={c.id} className={`px-3 py-2.5 font-medium ${Number(r.total_taken) > 0 ? 'text-blue-700' : 'text-slate-400'}`}>{v}</td>
                        }
                        return <td key={c.id} className="px-3 py-2.5 text-slate-700 whitespace-nowrap">{v}</td>
                      })}
                      {/* Branch badge */}
                      <td className="px-3 py-2.5">
                        {branchMeta ? (
                          <span className={`inline-flex px-2 py-0.5 rounded-full text-[10px] font-bold border ${branchMeta.badgeBg} ${branchMeta.badgeText} ${branchMeta.badgeBorder}`}>
                            {branchMeta.label}
                          </span>
                        ) : (
                          <span className="text-slate-300 text-xs">{r.branch || '—'}</span>
                        )}
                      </td>
                      <td className="px-3 py-2.5">
                        <button type="button" onClick={() => loadDetail(r)}
                          className="text-xs text-blue-600 hover:underline flex items-center gap-1">
                          Detail <HeroIcons.ArrowRightIcon className="w-3 h-3" />
                        </button>
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>

          {/* Pagination */}
          {pageSize !== 'All' && totalPages > 1 && (
            <div className="px-4 py-3 border-t border-slate-100 flex items-center justify-between">
              <span className="text-xs text-slate-500">
                Page {page} of {totalPages}
              </span>
              <div className="flex gap-1">
                <button onClick={() => setPage(p => Math.max(1, p - 1))} disabled={page === 1}
                  className="px-2.5 py-1 text-xs rounded border border-slate-300 disabled:opacity-40 hover:bg-slate-50">← Prev</button>
                <button onClick={() => setPage(p => Math.min(totalPages, p + 1))} disabled={page === totalPages}
                  className="px-2.5 py-1 text-xs rounded border border-slate-300 disabled:opacity-40 hover:bg-slate-50">Next →</button>
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  )

  // ─────────────────────────────────────────────────────────────────────────
  // DETAIL VIEW
  // ─────────────────────────────────────────────────────────────────────────
  const renderDetail = () => {
    if (!selected && !detailLoading) return (
      <div className="bg-white rounded-xl border border-slate-200 p-10 text-center text-slate-400 text-sm">
        <HeroIcons.UserCircleIcon className="w-10 h-10 mx-auto mb-2 opacity-30" />
        Select an employee from the Employees tab
      </div>
    )
    if (detailLoading) return (
      <div className="flex items-center justify-center h-32 gap-2 text-slate-400 text-sm"><Spinner /> Loading…</div>
    )

    const monthly = selected?.monthly_breakdown ?? []
    const chartData = monthly.map(m => ({
      month:   MONTH_LABELS[(m.month || 1) - 1],
      earned:  Number(m.earned   || 0),
      taken:   Number(m.taken    || 0),
      encashed:Number(m.encashed || 0),
      balance: Number(m.balance  || 0),
    }))
    const tier = balanceTier(selected.leave_balance)

    return (
      <div className="space-y-4">
        {/* Back button */}
        <button type="button" onClick={() => setView('list')}
          className="flex items-center gap-1.5 text-sm text-slate-600 hover:text-slate-900">
          <HeroIcons.ArrowLeftIcon className="w-4 h-4" /> Back to list
        </button>

        {/* Header card */}
        <div className="bg-white rounded-xl border border-slate-200 p-5">
          <div className="flex items-start justify-between flex-wrap gap-3">
            <div>
              <h2 className="text-lg font-bold text-slate-900">{selected.employee_name}</h2>
              <p className="text-sm text-slate-500 mt-0.5">{selected.job_title || '—'}</p>
              <div className="flex flex-wrap gap-2 mt-2 text-xs text-slate-600">
                {selected.employee_code && <span className="bg-slate-100 px-2 py-0.5 rounded">#{selected.employee_code}</span>}
                {selected.department    && <span className="bg-blue-50 text-blue-700 px-2 py-0.5 rounded border border-blue-200">{selected.department}</span>}
                {selected.joining_date  && <span className="bg-slate-100 px-2 py-0.5 rounded">Joined {selected.joining_date.slice(0, 10)}</span>}
              </div>
            </div>
            <div className="text-right">
              <div className="text-xs text-slate-500 mb-1">Leave Balance</div>
              <BalanceBadge value={selected.leave_balance} />
            </div>
          </div>

          {/* Stats row */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mt-4">
            {[
              { label: 'Annual Entitlement', value: `${Number(selected.annual_entitlement).toFixed(1)} d`, color: 'text-slate-700' },
              { label: 'Total Earned',       value: `${Number(selected.total_earned).toFixed(2)} d`,      color: 'text-emerald-700' },
              { label: 'Total Taken',        value: `${Number(selected.total_taken).toFixed(2)} d`,       color: 'text-blue-700' },
              { label: 'Total Encashed',     value: `${Number(selected.total_encashed).toFixed(2)} d`,    color: 'text-purple-700' },
            ].map(s => (
              <div key={s.label} className="bg-slate-50 rounded-lg p-3 border border-slate-200">
                <div className="text-xs text-slate-500">{s.label}</div>
                <div className={`text-lg font-bold ${s.color} mt-0.5`}>{s.value}</div>
              </div>
            ))}
          </div>

          {/* Carry forward row */}
          <div className="mt-3 bg-slate-50 rounded-lg p-3 border border-slate-200 flex items-center justify-between flex-wrap gap-2">
            <div className="text-xs text-slate-500">Carry Forward</div>
            {cfEditing ? (
              <div className="flex items-center gap-2">
                <input
                  type="number" step="0.01" value={cfValue}
                  onChange={e => setCfValue(e.target.value)}
                  className="w-24 px-2 py-1 text-sm border border-slate-300 rounded focus:outline-none focus:ring-1 focus:ring-indigo-400"
                  autoFocus
                />
                <button type="button" onClick={saveCarryforward} disabled={cfSaving}
                  className="p-1.5 rounded bg-emerald-50 text-emerald-700 border border-emerald-200 hover:bg-emerald-100 disabled:opacity-50">
                  {cfSaving ? <Spinner /> : <HeroIcons.CheckIcon className="w-3.5 h-3.5" />}
                </button>
                <button type="button" onClick={cancelEditCarryforward} disabled={cfSaving}
                  className="p-1.5 rounded bg-slate-100 text-slate-600 border border-slate-200 hover:bg-slate-200 disabled:opacity-50">
                  <HeroIcons.XMarkIcon className="w-3.5 h-3.5" />
                </button>
              </div>
            ) : (
              <div className="flex items-center gap-2">
                <div className="text-lg font-bold text-slate-700">{Number(selected.carryforward || 0).toFixed(2)} d</div>
                {isHRManager && (
                  <button type="button" onClick={startEditCarryforward} title="Edit carry forward"
                    className="p-1 rounded text-slate-400 hover:text-blue-600 hover:bg-blue-50">
                    <HeroIcons.PencilSquareIcon className="w-4 h-4" />
                  </button>
                )}
              </div>
            )}
          </div>
          {cfMsg && (
            <div className={`mt-2 px-3 py-2 rounded-lg text-xs ${cfMsg.type === 'ok' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-rose-50 text-rose-700 border border-rose-200'}`}>
              {cfMsg.text}
            </div>
          )}
        </div>

        {/* Monthly chart */}
        {chartData.some(d => d.earned > 0 || d.taken > 0) && (
          <div className="bg-white rounded-xl border border-slate-200 p-4">
            <h3 className="text-sm font-semibold text-slate-700 mb-3">Monthly Leave Breakdown — {YEAR}</h3>
            <ResponsiveContainer width="100%" height={240}>
              <BarChart data={chartData} margin={{ top: 5, right: 20, bottom: 5, left: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                <XAxis dataKey="month" tick={{ fontSize: 11 }} />
                <YAxis tick={{ fontSize: 11 }} />
                <Tooltip />
                <Legend iconSize={10} wrapperStyle={{ fontSize: 11 }} />
                <Bar dataKey="earned"   name="Earned"   fill="#10b981" radius={[3,3,0,0]} />
                <Bar dataKey="taken"    name="Taken"    fill="#3b82f6" radius={[3,3,0,0]} />
                <Bar dataKey="encashed" name="Encashed" fill="#8b5cf6" radius={[3,3,0,0]} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        )}

        {/* Monthly table */}
        {monthly.length > 0 && (
          <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
            <div className="px-4 py-3 border-b border-slate-100 text-xs text-slate-500">Monthly breakdown</div>
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead className="bg-slate-50">
                  <tr>
                    {['Month','Earned','Taken','Encashed','Balance'].map(h => (
                      <th key={h} className="text-left px-3 py-2.5 text-xs font-semibold text-slate-600 uppercase tracking-wider">{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {monthly.map((m, i) => (
                    <tr key={i} className="hover:bg-slate-50">
                      <td className="px-3 py-2.5 font-medium text-slate-700">{m.month_label || MONTH_LABELS[(m.month || 1) - 1]}</td>
                      <td className="px-3 py-2.5 text-emerald-700">{Number(m.earned   || 0).toFixed(2)}</td>
                      <td className="px-3 py-2.5 text-blue-700">{Number(m.taken    || 0).toFixed(2)}</td>
                      <td className="px-3 py-2.5 text-purple-700">{Number(m.encashed || 0).toFixed(2)}</td>
                      <td className="px-3 py-2.5"><BalanceBadge value={m.balance} /></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>
    )
  }

  // ─────────────────────────────────────────────────────────────────────────
  // REQUESTS VIEW
  // ─────────────────────────────────────────────────────────────────────────
  const REQ_TABS = [
    { id: 'new',        label: 'New Request',            icon: 'PlusCircleIcon' },
    { id: 'rm_pending', label: 'Awaiting Manager',       icon: 'ClockIcon',      badge: requests.length },
    { id: 'hr_pending', label: 'Awaiting HR Approval',   icon: 'CheckBadgeIcon', badge: null },
    { id: 'history',    label: 'History',                icon: 'ArchiveBoxIcon' },
  ]

  const STATUS_STYLES = {
    PENDING:     'bg-amber-100 text-amber-800 border-amber-300',
    RM_APPROVED: 'bg-blue-100 text-blue-800 border-blue-300',
    RM_REJECTED: 'bg-orange-100 text-orange-800 border-orange-300',
    APPROVED:    'bg-emerald-100 text-emerald-800 border-emerald-300',
    REJECTED:    'bg-rose-100 text-rose-800 border-rose-300',
    CANCELLED:   'bg-slate-100 text-slate-600 border-slate-300',
  }

  // ─────────────────────────────────────────────────────────────────────────
  // Encashment view helpers
  // ─────────────────────────────────────────────────────────────────────────
  const MONTH_NAMES = ['January','February','March','April','May','June',
    'July','August','September','October','November','December']

  const [annualEncashmentOpen, setAnnualEncashmentOpen] = useState(false)

  const loadEncashmentStatus = (yr, mo) => {
    setEncLoading(true)
    setEncStatus(null)
    setEncPreview(null)
    payrollService.getLeaveEncashmentStatus({ year: yr, month: mo })
      .then(d => setEncStatus(d?.status === 'not_run' ? 'not_run' : d))
      .catch(() => setEncMsg({ type: 'err', text: 'Unable to load encashment status. Please try again.' }))
      .finally(() => setEncLoading(false))
  }

  const loadPreview = () => {
    setEncLoading(true)
    payrollService.previewLeaveEncashment({ year: encYear, month: encMonth })
      .then(d => setEncPreview(d?.preview || []))
      .catch(() => setEncMsg({ type: 'err', text: 'Failed to load preview.' }))
      .finally(() => setEncLoading(false))
  }

  const handleRunEncashment = async () => {
    setEncConfirm(false)
    setEncRunning(true)
    setEncMsg(null)
    try {
      const result = await payrollService.runLeaveEncashment({ year: encYear, month: encMonth })
      setEncPreview(result?.preview || [])
      setEncStatus({
        status: result?.missing_salaries?.length > 0 ? 'partial' : 'success',
        year: encYear, month: encMonth,
        records_processed: result?.records_processed,
        total_days_encashed: result?.total_days_encashed,
        total_pay: result?.total_pay,
        missing_salaries: result?.missing_salaries || [],
        executed_at: new Date().toISOString(),
        triggered_by: 'You',
      })
      setEncMsg({ type: 'ok', text: `Encashment completed. ${result?.records_processed} employees processed.` })
    } catch (e) {
      const msg = e?.response?.data?.error || 'Encashment run failed.'
      setEncMsg({ type: 'err', text: msg })
    } finally {
      setEncRunning(false)
    }
  }

  // Load status when encashment view becomes active or period changes
  useEffect(() => {
    if (view !== 'encashment' || !annualEncashmentOpen) return
    loadEncashmentStatus(encYear, encMonth)
  }, [view, encYear, encMonth, annualEncashmentOpen]) // eslint-disable-line react-hooks/exhaustive-deps

  const renderEncashment = () => {
    // Partial runs have already changed employee leave ledgers, so they are
    // completed periods too and cannot be posted a second time.
    const alreadyRun = encStatus && encStatus !== 'not_run' && ['success', 'partial'].includes(encStatus?.status)
    const periodLabel = `${MONTH_NAMES[encMonth - 1]} ${encYear}`

    return (
      <div className="space-y-4">
        {/* Period selector */}
        <div className="bg-white rounded-xl border border-slate-200 p-4 flex flex-wrap gap-4 items-end">
          <div>
            <label className="block text-xs font-medium text-slate-500 mb-1">Year</label>
            <select value={encYear} onChange={e => setEncYear(Number(e.target.value))}
              className="px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500">
              {[encYear - 1, encYear, encYear + 1].map(y => <option key={y} value={y}>{y}</option>)}
            </select>
          </div>
          <div>
            <label className="block text-xs font-medium text-slate-500 mb-1">Month</label>
            <select value={encMonth} onChange={e => setEncMonth(Number(e.target.value))}
              className="px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500">
              {MONTH_NAMES.map((m, i) => <option key={i + 1} value={i + 1}>{m}</option>)}
            </select>
          </div>
          <button type="button" onClick={loadPreview} disabled={encLoading}
            className="px-4 py-2 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-lg text-sm font-medium transition-colors disabled:opacity-50">
            {encLoading ? 'Loading…' : 'Preview'}
          </button>
        </div>

        {/* Status banner */}
        {encLoading && (
          <div className="text-sm text-slate-500 text-center py-6 animate-pulse">Loading encashment data…</div>
        )}
        {!encLoading && encStatus && encStatus !== 'not_run' && (
          <div className={`rounded-xl border p-4 flex flex-wrap gap-4 items-start ${
            encStatus.status === 'success' ? 'bg-emerald-50 border-emerald-200' :
            encStatus.status === 'partial' ? 'bg-amber-50 border-amber-200' :
            'bg-rose-50 border-rose-200'}`}>
            <HeroIcons.CheckCircleIcon className={`w-5 h-5 mt-0.5 shrink-0 ${
              encStatus.status === 'success' ? 'text-emerald-600' : 'text-amber-600'}`} />
            <div className="flex-1 text-sm">
              <div className="font-semibold text-slate-800 mb-1">
                Encashment {encStatus.status === 'success' ? 'completed' : 'completed with warnings'} — {periodLabel}
              </div>
              <div className="text-slate-600 grid grid-cols-2 sm:grid-cols-4 gap-3 mt-2">
                <div><div className="text-xs text-slate-400">Employees</div><div className="font-semibold">{encStatus.records_processed}</div></div>
                <div><div className="text-xs text-slate-400">Days Encashed</div><div className="font-semibold">{Number(encStatus.total_days_encashed).toFixed(2)}</div></div>
                <div><div className="text-xs text-slate-400">Total Pay (AED)</div><div className="font-semibold">{Number(encStatus.total_pay).toLocaleString('en-AE', { minimumFractionDigits: 2 })}</div></div>
                <div><div className="text-xs text-slate-400">Run by</div><div className="font-semibold">{encStatus.triggered_by}</div></div>
              </div>
              {encStatus.missing_salaries?.length > 0 && (
                <div className="mt-2 text-xs text-amber-700">
                  ⚠ {encStatus.missing_salaries.length} employee(s) had no salary on record — encashment pay set to 0:&nbsp;
                  {encStatus.missing_salaries.join(', ')}
                </div>
              )}
            </div>
          </div>
        )}
        {!encLoading && (encStatus === null || encStatus === 'not_run') && (
          <div className="bg-slate-50 border border-slate-200 rounded-xl p-4 text-sm text-slate-500 flex items-center gap-2">
            <HeroIcons.InformationCircleIcon className="w-4 h-4 text-slate-400 shrink-0" />
            No encashment run found for {periodLabel}.
          </div>
        )}

        {/* Feedback message */}
        {encMsg && (
          <div className={`rounded-xl border px-4 py-3 text-sm flex items-center gap-2 ${
            encMsg.type === 'ok' ? 'bg-emerald-50 border-emerald-200 text-emerald-700'
                                 : 'bg-rose-50 border-rose-200 text-rose-700'}`}>
            {encMsg.type === 'ok'
              ? <HeroIcons.CheckCircleIcon className="w-4 h-4 shrink-0" />
              : <HeroIcons.ExclamationCircleIcon className="w-4 h-4 shrink-0" />}
            {encMsg.text}
          </div>
        )}

        {/* Run button (HR-only, disabled if already run) */}
        {isHRManager && (
          <div className="flex items-center gap-3">
            <button type="button"
              disabled={alreadyRun || encRunning}
              onClick={() => setEncConfirm(true)}
              className={`flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-semibold transition-colors ${
                alreadyRun
                  ? 'bg-slate-100 text-slate-400 cursor-not-allowed'
                  : 'bg-indigo-700 hover:bg-indigo-800 text-white shadow-sm'
              }`}>
              <HeroIcons.BanknotesIcon className="w-4 h-4" />
              {encRunning ? 'Running…' : alreadyRun ? `Already run for ${periodLabel}` : `Run Encashment for ${periodLabel}`}
            </button>
            {alreadyRun && (
              <span className="text-xs text-slate-500">
                Completed on {encStatus?.executed_at ? new Date(encStatus.executed_at).toLocaleDateString() : '—'}
              </span>
            )}
          </div>
        )}

        {/* Confirm modal */}
        {encConfirm && (
          <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30">
            <div className="bg-white rounded-2xl shadow-2xl p-6 max-w-sm w-full mx-4">
              <h3 className="text-base font-semibold text-slate-800 mb-2 flex items-center gap-2">
                <HeroIcons.BanknotesIcon className="w-5 h-5 text-blue-600" />
                Confirm Encashment
              </h3>
              <p className="text-sm text-slate-600 mb-4">
                This will encash all unused leave balances for <strong>{periodLabel}</strong> using the
                formula: <code className="text-xs bg-slate-100 px-1 rounded">days × (salary ÷ {LEAVE_ENCASHMENT_WORKING_DAYS})</code>.
                This action cannot be undone.
              </p>
              <div className="flex gap-3 justify-end">
                <button type="button" onClick={() => setEncConfirm(false)}
                  className="px-4 py-2 text-sm text-slate-600 hover:text-slate-800 rounded-lg transition-colors">
                  Cancel
                </button>
                <button type="button" onClick={handleRunEncashment}
                  className="px-4 py-2 bg-indigo-700 hover:bg-indigo-800 text-white rounded-lg text-sm font-semibold transition-colors">
                  Yes, Run Encashment
                </button>
              </div>
            </div>
          </div>
        )}

        {/* Preview / Results table */}
        {encPreview && encPreview.length > 0 && (
          <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
            <div className="px-4 py-3 border-b border-slate-100 flex items-center justify-between">
              <h3 className="text-sm font-semibold text-slate-700">
                {encStatus && encStatus !== 'not_run' ? 'Encashment Results' : 'Preview'} — {periodLabel}
              </h3>
              <span className="text-xs text-slate-400">{encPreview.length} employees</span>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-xs">
                <thead className="bg-slate-50 text-slate-500 uppercase tracking-wide">
                  <tr>
                    <th className="px-3 py-2 text-left">Employee</th>
                    <th className="px-3 py-2 text-right">Earned</th>
                    <th className="px-3 py-2 text-right">Taken</th>
                    <th className="px-3 py-2 text-right">Days Encashed</th>
                    <th className="px-3 py-2 text-right">Monthly Salary</th>
                    <th className="px-3 py-2 text-right">Daily Rate</th>
                    <th className="px-3 py-2 text-right font-semibold text-slate-700">Pay (AED)</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {encPreview.map((row, i) => (
                    <tr key={row.employee_code || i} className="hover:bg-slate-50">
                      <td className="px-3 py-2.5">
                        <div className="font-medium text-slate-800">{row.employee_name}</div>
                        <div className="text-slate-400">{row.employee_code}</div>
                      </td>
                      <td className="px-3 py-2.5 text-right text-slate-600">{Number(row.earned).toFixed(2)}</td>
                      <td className="px-3 py-2.5 text-right text-slate-600">{Number(row.taken).toFixed(2)}</td>
                      <td className="px-3 py-2.5 text-right font-semibold text-blue-700">{Number(row.days_encashed).toFixed(2)}</td>
                      <td className="px-3 py-2.5 text-right text-slate-600">
                        {row.monthly_salary != null ? Number(row.monthly_salary).toLocaleString('en-AE', { minimumFractionDigits: 0 }) : <span className="text-amber-500">N/A</span>}
                      </td>
                      <td className="px-3 py-2.5 text-right text-slate-600">{Number(row.daily_rate).toFixed(2)}</td>
                      <td className="px-3 py-2.5 text-right font-bold text-emerald-700">
                        {Number(row.encashment_pay).toLocaleString('en-AE', { minimumFractionDigits: 2 })}
                      </td>
                    </tr>
                  ))}
                </tbody>
                <tfoot className="bg-slate-50 font-semibold text-slate-700">
                  <tr>
                    <td className="px-3 py-2.5" colSpan={3}>Totals</td>
                    <td className="px-3 py-2.5 text-right text-blue-700">
                      {encPreview.reduce((s, r) => s + Number(r.days_encashed), 0).toFixed(2)}
                    </td>
                    <td className="px-3 py-2.5" colSpan={2} />
                    <td className="px-3 py-2.5 text-right text-emerald-700">
                      {encPreview.reduce((s, r) => s + Number(r.encashment_pay), 0).toLocaleString('en-AE', { minimumFractionDigits: 2 })}
                    </td>
                  </tr>
                </tfoot>
              </table>
            </div>
          </div>
        )}
        {encPreview && encPreview.length === 0 && (
          <div className="text-sm text-slate-400 text-center py-8">
            No leave accrual records found for {periodLabel}. Run the monthly accrual first.
          </div>
        )}
      </div>
    )
  }

  const renderRequests = () => (
    <div className="space-y-4">
      {/* Sub-tabs */}
      <div className="bg-white rounded-xl border border-slate-200 px-4 py-2 flex gap-1 flex-wrap">
        {REQ_TABS.map(t => {
          const Icon = HeroIcons[t.icon] || HeroIcons.ClipboardDocumentListIcon
          return (
            <button key={t.id} type="button" onClick={() => setReqTab(t.id)}
              className={`flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${
                reqTab === t.id ? 'bg-indigo-50 text-indigo-700 ring-1 ring-inset ring-indigo-200' : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
              }`}>
              <Icon className="w-4 h-4" />{t.label}
            </button>
          )
        })}
      </div>
      {/* Stage guide banner */}
      {reqTab !== 'new' && reqTab !== 'history' && (
        <div className="flex items-start gap-2 px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-xs text-slate-600">
          <HeroIcons.InformationCircleIcon className="w-4 h-4 text-blue-500 mt-0.5 shrink-0" />
          <span>
            <strong>Two-stage leave approval (direct manager only):</strong>{' '}
            Employee submits → <strong className="text-amber-700">Direct Reporting Manager</strong> approves →{' '}
            <strong className="text-blue-700">HR Manager</strong> gives final approval.
            {reqTab === 'rm_pending' && ' ← Stage 1: You see only your direct reports.'}
            {reqTab === 'hr_pending' && ' ← Stage 2: HR final approval for all employees.'}
          </span>
        </div>
      )}

      {/* ── NEW REQUEST form ─────────────────────────────────────────────── */}
      {reqTab === 'new' && (
        <div className="bg-white rounded-xl border border-slate-200 p-5 max-w-2xl">
          <h3 className="text-sm font-semibold text-slate-700 mb-4 flex items-center gap-2">
            <HeroIcons.PlusCircleIcon className="w-4 h-4 text-blue-400" />
            Submit Leave Request
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            {/* Employee name with datalist */}
            <div className="sm:col-span-2">
              <label className="block text-xs font-medium text-slate-600 mb-1">Employee Name <span className="text-rose-500">*</span></label>
              <input
                list="leave-emp-list"
                value={formState.employee_name}
                onChange={e => {
                  const val = e.target.value
                  const match = records.find(r => r.employee_name === val)
                  setFormState(s => ({
                    ...s, employee_name: val,
                    employee_code: match?.employee_code ?? s.employee_code,
                    department:    match?.department    ?? s.department,
                  }))
                }}
                placeholder="Search or type employee name…"
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500"
              />
              <datalist id="leave-emp-list">
                {records.map(r => <option key={r.id} value={r.employee_name} />)}
              </datalist>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Employee Code</label>
              <input value={formState.employee_code}
                onChange={e => setFormState(s => ({ ...s, employee_code: e.target.value }))}
                placeholder="e.g. EMP-001"
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Department</label>
              <input value={formState.department}
                onChange={e => setFormState(s => ({ ...s, department: e.target.value }))}
                placeholder="e.g. Engineering"
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Leave Type <span className="text-rose-500">*</span></label>
              <select value={formState.leave_type}
                onChange={e => setFormState(s => ({ ...s, leave_type: e.target.value }))}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500">
                <option value="">— Select leave type —</option>
                {leaveTypes.map(lt => (
                  <option key={lt.id} value={lt.id}>{lt.code} — {lt.name}</option>
                ))}
              </select>
            </div>
            <div className="flex flex-col justify-end">
              {formWorkDays !== null && (
                <div className="text-xs bg-blue-50 border border-blue-200 text-blue-700 rounded-lg px-3 py-2">
                  <span className="font-bold">{formWorkDays}</span> working day{formWorkDays !== 1 ? 's' : ''} requested
                </div>
              )}
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Start Date <span className="text-rose-500">*</span></label>
              <input type="date" value={formState.start_date}
                onChange={e => setFormState(s => ({ ...s, start_date: e.target.value }))}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">End Date <span className="text-rose-500">*</span></label>
              <input type="date" value={formState.end_date} min={formState.start_date}
                onChange={e => setFormState(s => ({ ...s, end_date: e.target.value }))}
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-2 focus:ring-indigo-500" />
            </div>
            <div className="sm:col-span-2">
              <label className="block text-xs font-medium text-slate-600 mb-1">Reason</label>
              <textarea rows={3} value={formState.reason}
                onChange={e => setFormState(s => ({ ...s, reason: e.target.value }))}
                placeholder="Optional reason / notes…"
                className="w-full px-3 py-2 border border-slate-300 rounded-lg text-sm resize-none focus:ring-2 focus:ring-indigo-500" />
            </div>
          </div>
          {formMsg && (
            <div className={`mt-3 px-4 py-2.5 rounded-lg text-sm ${formMsg.type === 'ok' ? 'bg-emerald-50 text-emerald-700 border border-emerald-200' : 'bg-rose-50 text-rose-700 border border-rose-200'}`}>
              {formMsg.text}
            </div>
          )}
          <div className="mt-4 flex gap-2">
            <button type="button" onClick={submitRequest} disabled={formBusy}
              className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 disabled:opacity-60 transition">
              {formBusy ? <Spinner /> : <HeroIcons.PaperAirplaneIcon className="w-4 h-4" />}
              {formBusy ? 'Submitting…' : 'Submit Request'}
            </button>
            <button type="button" onClick={() => { setFormState({ employee_name: '', employee_code: '', department: '', leave_type: '', start_date: '', end_date: '', reason: '' }); setFormMsg(null) }}
              className="px-4 py-2 text-slate-600 rounded-lg text-sm hover:bg-slate-100 transition">
              Reset
            </button>
          </div>
        </div>
      )}

      {/* ── PENDING / HISTORY table ─────────────────────────────────────── */}
      {(reqTab === 'rm_pending' || reqTab === 'hr_pending' || reqTab === 'history') && (
        reqLoading ? (
          <div className="flex items-center justify-center h-28 gap-2 text-slate-400 text-sm"><Spinner /> Loading…</div>
        ) : (
          <div className="bg-white rounded-xl border border-slate-200 overflow-hidden">
            <div className="overflow-x-auto">
              <table className="min-w-full text-sm">
                <thead className="bg-slate-50">
                  <tr>
                    {['Employee','Code','Dept','Leave Type','From','To','Days','Reason','Status',
                      reqTab === 'rm_pending' ? 'RM Action'
                      : reqTab === 'hr_pending' ? 'HR Action'
                      : 'Reviewer',
                    ].map(h => (
                      <th key={h} className="text-left px-3 py-2.5 text-xs font-semibold text-slate-600 uppercase tracking-wider whitespace-nowrap">{h}</th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100">
                  {requests.length === 0 ? (
                    <tr><td colSpan={10} className="text-center py-10 text-slate-400 text-sm">
                      {reqTab === 'rm_pending' ? 'No requests awaiting manager approval'
                       : reqTab === 'hr_pending' ? 'No requests awaiting HR approval'
                       : 'No leave history'}
                    </td></tr>
                  ) : requests.map(r => {
                    const lt   = r.leave_type_detail
                    const isBusy = reviewBusy === r.id
                    return (
                      <tr key={r.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-3 py-2.5 font-medium text-slate-800 whitespace-nowrap">{r.employee_name}</td>
                        <td className="px-3 py-2.5 text-slate-500">{r.employee_code || '—'}</td>
                        <td className="px-3 py-2.5 text-slate-500 whitespace-nowrap">{r.department || '—'}</td>
                        <td className="px-3 py-2.5">
                          {lt ? (
                            <span className={`inline-flex items-center gap-1 px-2 py-0.5 rounded-full text-xs font-semibold border ${lt.badge_bg} ${lt.badge_text} ${lt.badge_border}`}>
                              {lt.code}
                            </span>
                          ) : <span className="text-slate-400">—</span>}
                        </td>
                        <td className="px-3 py-2.5 text-slate-600 whitespace-nowrap">{r.start_date}</td>
                        <td className="px-3 py-2.5 text-slate-600 whitespace-nowrap">{r.end_date}</td>
                        <td className="px-3 py-2.5 text-center font-semibold text-slate-700">{Number(r.days_requested).toFixed(0)}</td>
                        <td className="px-3 py-2.5 text-slate-500 max-w-xs truncate">{r.reason || '—'}</td>
                        <td className="px-3 py-2.5">
                          <span className={`inline-flex px-2 py-0.5 rounded-full text-xs font-semibold border ${STATUS_STYLES[r.status] || 'bg-slate-100 text-slate-600 border-slate-300'}`}>
                            {r.status_display || r.status}
                          </span>
                        </td>
                        {reqTab === 'rm_pending' ? (
                          <td className="px-3 py-2.5">
                            <div className="flex items-center gap-1.5">
                              {isManager && (
                                <>
                                  <button type="button" disabled={isBusy} onClick={() => reviewRequest(r.id, 'rm_approve')}
                                    className="inline-flex items-center gap-1 px-2.5 py-1 text-xs bg-emerald-50 text-emerald-700 border border-emerald-200 rounded-lg hover:bg-emerald-100 disabled:opacity-50 transition">
                                    {isBusy ? <Spinner /> : <HeroIcons.CheckIcon className="w-3.5 h-3.5" />}
                                    Approve
                                  </button>
                                  <button type="button" disabled={isBusy} onClick={() => reviewRequest(r.id, 'rm_reject')}
                                    className="inline-flex items-center gap-1 px-2.5 py-1 text-xs bg-rose-50 text-rose-700 border border-rose-200 rounded-lg hover:bg-rose-100 disabled:opacity-50 transition">
                                    <HeroIcons.XMarkIcon className="w-3.5 h-3.5" />
                                    Reject
                                  </button>
                                </>
                              )}
                              {!isManager && <span className="text-xs text-slate-400">Manager action</span>}
                            </div>
                          </td>
                        ) : reqTab === 'hr_pending' ? (
                          <td className="px-3 py-2.5">
                            <div className="flex flex-col gap-1">
                              <div className="text-xs text-slate-400 mb-0.5">
                                RM: <span className="font-medium text-slate-600">{r.rm_reviewed_by_name || '—'}</span>
                                {r.rm_reviewed_at && <span className="ml-1">({r.rm_reviewed_at.slice(0,10)})</span>}
                              </div>
                              {isHRManager ? (
                                <div className="flex items-center gap-1.5">
                                  <button type="button" disabled={isBusy} onClick={() => reviewRequest(r.id, 'approve')}
                                    className="inline-flex items-center gap-1 px-2.5 py-1 text-xs bg-blue-50 text-blue-700 border border-blue-200 rounded-lg hover:bg-blue-100 disabled:opacity-50 transition">
                                    {isBusy ? <Spinner /> : <HeroIcons.CheckBadgeIcon className="w-3.5 h-3.5" />}
                                    Final Approve
                                  </button>
                                  <button type="button" disabled={isBusy} onClick={() => reviewRequest(r.id, 'reject')}
                                    className="inline-flex items-center gap-1 px-2.5 py-1 text-xs bg-rose-50 text-rose-700 border border-rose-200 rounded-lg hover:bg-rose-100 disabled:opacity-50 transition">
                                    <HeroIcons.XMarkIcon className="w-3.5 h-3.5" />
                                    Reject
                                  </button>
                                </div>
                              ) : (
                                <span className="text-xs text-slate-400">HR Manager action</span>
                              )}
                            </div>
                          </td>
                        ) : (
                          <td className="px-3 py-2.5 text-slate-500 text-xs">
                            <div>{r.reviewed_by_name || r.rm_reviewed_by_name || '—'}</div>
                            {(r.reviewed_at || r.rm_reviewed_at) && (
                              <div className="text-slate-400">{(r.reviewed_at || r.rm_reviewed_at).slice(0, 10)}</div>
                            )}
                          </td>
                        )}
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            </div>
          </div>
        )
      )}
    </div>
  )

  // ─────────────────────────────────────────────────────────────────────────
  // MAIN RENDER
  // ─────────────────────────────────────────────────────────────────────────
  // Per-branch employee counts for the selector badges
  const branchCounts = useMemo(() => {
    const m = { ALL: records.length }
    BRANCHES.forEach(b => { m[b.id] = records.filter(r => r.branch === b.id).length })
    return m
  }, [records])

  const branchSelector = (
    <select aria-label="Branch" value={branch || ''} onChange={event => { setBranch(event.target.value || null); setPage(1) }}
      className="max-w-full rounded-lg border border-slate-200 bg-white px-3 py-2 text-sm text-slate-700 focus:border-indigo-400 focus:outline-none focus:ring-2 focus:ring-indigo-100">
      <option value="">All branches{loading ? '' : ` (${branchCounts.ALL})`}</option>
      {BRANCHES.map(item => <option key={item.id} value={item.id}>{item.label}{loading ? '' : ` (${branchCounts[item.id] ?? 0})`}</option>)}
    </select>
  )

  const activeBranchMeta  = branch ? getBranch(branch) : null
  const activeBranchLabel = activeBranchMeta ? activeBranchMeta.fullName : 'All Branches (RAD + RIN)'

  return (
    <div className="space-y-4">
      {headerActions ? createPortal(branchSelector, headerActions) : <div className="flex justify-end">{branchSelector}</div>}

      {/* View tabs */}
      <div className="bg-white rounded-xl border border-slate-200 px-4 py-2 flex gap-1 items-center flex-wrap">
        {VIEWS.map(v => {
          const Icon = HeroIcons[v.icon] || HeroIcons.TableCellsIcon
          const active = view === v.id
          return (
            <button key={v.id} type="button" onClick={() => setView(v.id)}
              className={`flex items-center gap-1.5 px-3.5 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-colors ${
                active ? 'bg-indigo-50 text-indigo-700 ring-1 ring-inset ring-indigo-200' : 'text-slate-600 hover:text-slate-900 hover:bg-slate-50'
              }`}>
              <Icon className="w-4 h-4" />
              {v.label}
            </button>
          )
        })}
        <div className="ml-auto flex items-center gap-2 text-xs text-slate-400 bg-slate-50 border border-slate-200 rounded-lg px-3 py-1.5">
          <span className="w-2 h-2 rounded-full bg-emerald-400 inline-block" />
          {records.length} employees · {YEAR} · {activeBranchLabel}
        </div>
      </div>

      {view === 'overview'   && renderOverview()}
      {view === 'list'       && renderList()}
      {view === 'detail'     && renderDetail()}
      {view === 'requests'   && renderRequests()}
      {view === 'encashment' && <div className="space-y-4"><OvertimeManagement reviewOnly /><details onToggle={event => setAnnualEncashmentOpen(event.currentTarget.open)} className="rounded-xl border border-slate-200 bg-white p-4"><summary className="cursor-pointer text-sm font-medium">Annual leave encashment</summary><div className="mt-4">{renderEncashment()}</div></details></div>}
    </div>
  )
}

