// KPI tile — now a clickable button that opens the drill-down modal
// ─────────────────────────────────────────────────────────────────────────────
const KPI_STYLE = {
  gross: 'border-indigo-200 from-indigo-50 text-indigo-700',
  net: 'border-emerald-200 from-emerald-50 text-emerald-700',
  pending: 'border-amber-200 from-amber-50 text-amber-700',
  ytd: 'border-violet-200 from-violet-50 text-violet-700',
  alerts: 'border-rose-200 from-rose-50 text-rose-700',
}
function KpiTile({ kpi, summary, onClick }) {
  const Icon = HeroIcons[kpi.icon] || HeroIcons.ChartBarIcon
  return <button type="button" onClick={onClick} className={`min-w-0 rounded-xl border bg-gradient-to-br to-white p-4 text-left transition-colors hover:border-indigo-400 focus-visible:outline-indigo-600 ${KPI_STYLE[kpi.id] || 'border-blue-200 from-blue-50 text-blue-700'}`}>
    <div className="flex items-center justify-between gap-2"><span className="text-xs font-medium">{kpi.label}</span><Icon className="h-4 w-4 shrink-0 opacity-70" /></div>
    <p className="mt-3 break-words text-xl font-semibold tracking-tight tabular-nums">{kpi.compute(summary)}<span className="ml-1 text-xs font-normal">{kpi.id === 'pending' ? ' requests' : kpi.suffix}</span></p>
    {kpi.sub && summary && <p className="mt-1 text-xs opacity-75">{kpi.sub(summary)}</p>}
  </button>
}
function LeaveTile({ icon, label, value, sub, textColor, onClick }) {
  const Icon = HeroIcons[icon] ?? HeroIcons.CalendarDaysIcon
  return <button type="button" onClick={onClick} className="min-w-0 rounded-lg border border-slate-200 bg-white p-4 text-left transition-colors hover:border-indigo-300 hover:bg-indigo-50/30 focus-visible:outline-indigo-600">
    <div className="flex items-start justify-between gap-2"><span className="text-xs text-slate-500">{label}</span><Icon className={`h-4 w-4 shrink-0 ${textColor}`} /></div>
    <p className={`mt-2 text-xl font-semibold tabular-nums ${textColor}`}>{value}</p><p className="mt-1 text-xs text-slate-500">{sub}</p>
  </button>
}

function RunEditModal({ run, onClose, onSaved }) {
  const [form, setForm] = useState({
    run_code:     run.run_code     || '',
    month:        run.month        || 1,
    year:         run.year         || new Date().getFullYear(),
    period_start: run.period_start || '',
    period_end:   run.period_end   || '',
  })
  const [busy, setBusy] = useState(false)
  const [msg,  setMsg]  = useState('')

  const isDraft = run.status === 'draft'

  // Close on Escape
  useEffect(() => {
    const h = (e) => { if (e.key === 'Escape') onClose() }
    document.addEventListener('keydown', h)
    return () => document.removeEventListener('keydown', h)
  }, [onClose])

  const handleSave = async () => {
    if (!form.run_code?.trim()) { setMsg('Error: Run Code is required.'); return }
    setBusy(true)
    setMsg('')
    try {
      const payload = {
        run_code:     form.run_code,
        month:        form.month,
        year:         form.year,
        ...(form.period_start ? { period_start: form.period_start } : {}),
        ...(form.period_end   ? { period_end:   form.period_end   } : {}),
      }
      await payrollService.updatePayrollRun(run.id, payload)
      setMsg(PAYROLL_RUN_COPY.successEdit)
      setTimeout(onSaved, 800)
    } catch (e) {
      const detail = e?.response?.data
      const errMsg = typeof detail === 'object'
        ? Object.entries(detail).map(([k, v]) => `${k}: ${Array.isArray(v) ? v.join(', ') : v}`).join(' | ')
        : (detail || e?.message || 'Update failed')
      setMsg('Error: ' + errMsg)
    } finally {
      setBusy(false)
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm"
      onClick={(e) => { if (e.target === e.currentTarget) onClose() }}
    >
      <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-lg">
        {/* Header */}
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 bg-slate-50 rounded-t-2xl">
          <div className="flex items-center gap-2">
            <HeroIcons.PencilSquareIcon className="w-5 h-5 text-blue-600" />
            <h3 className="text-base font-semibold text-slate-800">{PAYROLL_RUN_COPY.editTitle}</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600">
            <HeroIcons.XMarkIcon className="w-5 h-5" />
          </button>
        </div>

        {/* Body */}
        <div className="p-6 space-y-4">
          {!isDraft && (
            <div className="flex items-center gap-2 p-3 bg-amber-50 border border-amber-200 text-amber-700 rounded-lg text-sm">
              <HeroIcons.ExclamationTriangleIcon className="w-4 h-4 shrink-0" />
              {PAYROLL_RUN_COPY.errorNotDraft}
            </div>
          )}
          {msg && (
            <div className={`flex items-center gap-2 p-3 rounded-lg text-sm border ${
              msg.startsWith('Error')
                ? 'bg-rose-50 border-rose-200 text-rose-700'
                : 'bg-emerald-50 border-emerald-200 text-emerald-700'
            }`}>
              {msg.startsWith('Error')
                ? <HeroIcons.ExclamationCircleIcon className="w-4 h-4 shrink-0" />
                : <HeroIcons.CheckCircleIcon className="w-4 h-4 shrink-0" />
              }
              {msg}
            </div>
          )}

          {/* Run Code */}
          <div>
            <label className="block text-xs font-medium text-slate-600 mb-1">Run Code</label>
            <input
              type="text"
              value={form.run_code}
              onChange={e => setForm(f => ({ ...f, run_code: e.target.value }))}
              disabled={!isDraft}
              className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-300 disabled:bg-slate-50"
            />
          </div>

          {/* Month + Year */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Month</label>
              <select
                value={form.month}
                onChange={e => setForm(f => ({ ...f, month: parseInt(e.target.value, 10) }))}
                disabled={!isDraft}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-300 disabled:bg-slate-50"
              >
                {PAYROLL_RUN_MONTHS.map(m => (
                  <option key={m.value} value={m.value}>{m.label}</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Year</label>
              <input
                type="number"
                value={form.year}
                onChange={e => setForm(f => ({ ...f, year: parseInt(e.target.value, 10) }))}
                disabled={!isDraft}
                min={2020} max={2099} step={1}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-300 disabled:bg-slate-50"
              />
            </div>
          </div>

          {/* Period Start + End */}
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Period Start</label>
              <input
                type="date"
                value={form.period_start}
                onChange={e => setForm(f => ({ ...f, period_start: e.target.value }))}
                disabled={!isDraft}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-300 disabled:bg-slate-50"
              />
            </div>
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Period End</label>
              <input
                type="date"
                value={form.period_end}
                onChange={e => setForm(f => ({ ...f, period_end: e.target.value }))}
                disabled={!isDraft}
                className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-300 disabled:bg-slate-50"
              />
            </div>
          </div>

          <p className="text-xs text-slate-400">{PAYROLL_RUN_COPY.editNote}</p>
        </div>

        {/* Footer */}
        <div className="px-6 py-4 border-t border-slate-200 bg-slate-50 rounded-b-2xl flex justify-end gap-2">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 transition"
          >
            Cancel
          </button>
          <button
            onClick={handleSave}
            disabled={busy}
            className="px-4 py-2 text-sm font-medium text-white bg-blue-600 hover:bg-blue-700 disabled:bg-slate-200 disabled:text-slate-400 rounded-lg transition flex items-center gap-1.5"
          >
            {busy ? <Spinner /> : <HeroIcons.CheckIcon className="w-4 h-4" />}
            {PAYROLL_RUN_COPY.btnEdit}
          </button>
        </div>
      </div>
    </div>
  )
}

// ─────────────────────────────────────────────────────────────────────────────
// Delete Payroll Run confirmation modal
// ─────────────────────────────────────────────────────────────────────────────
function DeleteConfirmModal({ run, onClose, onDeleted }) {
  const [busy, setBusy] = useState(false)
  const [msg,  setMsg]  = useState('')

  const isDraft = run.status === 'draft'

  useEffect(() => {
    const h = (e) => { if (e.key === 'Escape') onClose() }
    document.addEventListener('keydown', h)
    return () => document.removeEventListener('keydown', h)
  }, [onClose])

  const handleDelete = async () => {
    setBusy(true)
    try {
      await payrollService.deletePayrollRun(run.id)
      setMsg(PAYROLL_RUN_COPY.successDelete)
      setTimeout(onDeleted, 600)
    } catch (e) {
      setMsg('Error: ' + (e?.response?.data?.detail || e?.message || 'Delete failed'))
    } finally {
      setBusy(false)
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-sm"
      onClick={(e) => { if (e.target === e.currentTarget) onClose() }}
    >
      <div className="bg-white rounded-2xl shadow-2xl border border-slate-200 w-full max-w-md">
        <div className="p-6 text-center">
          <div className="w-14 h-14 rounded-full bg-rose-100 flex items-center justify-center mx-auto mb-4">
            <HeroIcons.TrashIcon className="w-7 h-7 text-rose-600" />
          </div>
          <h3 className="text-base font-semibold text-slate-800 mb-2">{PAYROLL_RUN_COPY.deleteTitle}</h3>
          <p className="text-sm text-slate-500">{PAYROLL_RUN_COPY.deleteConfirm}</p>
          <p className="text-xs text-slate-400 mt-2">
            Run: <strong className="text-slate-700">{run.run_code}</strong>
            {' · '}{String(run.month).padStart(2, '0')}/{run.year}
          </p>
          {!isDraft && (
            <p className="text-xs text-amber-600 mt-2 font-medium">{PAYROLL_RUN_COPY.deleteNote}</p>
          )}
          {msg && (
            <p className={`text-xs mt-3 font-medium ${msg.startsWith('Error') ? 'text-rose-600' : 'text-emerald-600'}`}>
              {msg}
            </p>
          )}
        </div>
        <div className="px-6 pb-6 flex justify-center gap-3">
          <button
            onClick={onClose}
            className="px-4 py-2 text-sm font-medium text-slate-600 hover:text-slate-800 bg-white border border-slate-200 rounded-lg hover:bg-slate-50 transition"
          >
            Cancel
          </button>
          <button
            onClick={handleDelete}
            disabled={busy}
            className="px-4 py-2 text-sm font-medium text-white bg-rose-600 hover:bg-rose-700 disabled:bg-slate-200 disabled:text-slate-400 rounded-lg transition flex items-center gap-1.5"
          >
            {busy ? <Spinner /> : <HeroIcons.TrashIcon className="w-4 h-4" />}
            {PAYROLL_RUN_COPY.btnDelete}
          </button>
        </div>
      </div>
    </div>
  )
}

export default function PayrollDashboard({ onSelectRun, onSwitchTab, activeRunId, initialTab }) {
  const [summary,      setSummary]      = useState(null)
  const [loading,      setLoading]      = useState(true)
  const [error,        setError]        = useState(null)
  const [reportId,     setReportId]     = useState(null)
  const [trackerData,  setTrackerData]  = useState(null)   // approval pipeline widget

  // Role — used to gate the Approval Pipeline widget
  // authUser is the raw UserProfileSerializer payload — is_superuser lives on
  // the nested `user` object (UserSerializer), not at the top level.
  const rbacUser    = useSelector(s => s.rbac?.currentUser)
  const authUser    = useSelector(s => s.auth?.user)
  const isSuperAdmin = (
    authUser?.user?.is_superuser ||
    rbacUser?.roles?.some(r => r.code === 'super_admin' || r.code === 'admin')
  ) ?? false

  useEffect(() => {
    setLoading(true)
    Promise.all([
      payrollEngineService.getDashboardSummary().catch(() => null),
      payrollService.getDashboardSummary().catch(() => null),
    ]).then(async ([engineSummary, legacySummary]) => {
      // Payroll values come from Payroll Engine; leave intelligence still
      // comes from the HR/payroll summary until that API is consolidated.
      const s = engineSummary || legacySummary
        ? {
            ...(legacySummary || {}),
            ...(engineSummary || {}),
            current_year: engineSummary?.year ?? legacySummary?.current_year,
            current_month: engineSummary?.month ?? legacySummary?.current_month,
          }
        : null
      // The backend summary counts draft payslips across every PayrollRun
      // (all months), but the Pending Approvals modal only ever shows the
      // current month's run — recompute the card's count the same way so
      // both agree.
      if (s) {
        // Pending Approvals = draft payslips for the current run + leave
        // requests awaiting RM/HR action (backend-computed, always current).
        const leavePending = s.leave_pending_approvals ?? 0
        const run = await fetchCurrentMonthRun().catch(() => null)
        if (run) {
          const pendingResp = await payrollEngineService
            .listPayslips({ run: run.id, status: 'draft', page_size: 1 })
            .catch(() => null)
          s.pending_approvals = (pendingResp?.count ?? s.pending_approvals ?? 0) + leavePending
        } else {
          s.pending_approvals = leavePending
        }
      }
      setSummary(s)
    }).catch((e) => setError(e.message)).finally(() => setLoading(false))
  }, [])

  // Approval tracker — loaded separately; only for super-admins.
  // getApprovalTracker isn't implemented yet (no backend endpoint exists) —
  // guard the call so the widget just stays hidden instead of throwing.
  useEffect(() => {
    if (!isSuperAdmin) return
    if (typeof payrollService.getApprovalTracker !== 'function') return
    payrollService.getApprovalTracker().catch(() => null).then(d => {
      if (d) setTrackerData(d)
    })
  }, [isSuperAdmin])

  if (loading) return (
    <div className="flex items-center justify-center h-64">
      <Spinner />
      <span className="ml-3 text-slate-500 text-sm">Loading payroll data…</span>
    </div>
  )

  if (error) return (
    <div className="bg-rose-50 border border-rose-200 rounded-xl p-6 text-rose-700 text-sm">{error}</div>
  )

  return (
    <div className="space-y-5">
      {/* KPI Tiles */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 2xl:grid-cols-7 gap-3">
        {PAYROLL_KPIS.map((kpi) => (
          <KpiTile key={kpi.id} kpi={kpi} summary={summary} onClick={() => setReportId(kpi.id)} />
        ))}
      </div>

      <section className="radai-payroll-module min-w-0" aria-label="Payroll management workspace">
        <PayrollEngine activeRunId={activeRunId} initialTab={activeRunId ? undefined : initialTab || 'runs'} onSelectRun={onSelectRun} onSwitchTab={onSwitchTab} />
      </section>

      {/* Leave overview Panel — always shown when summary is loaded */}
      {summary && (
        <div className="bg-white rounded-xl border border-slate-200 p-5">
          <div className="flex items-center gap-2 mb-4">
            <HeroIcons.CalendarDaysIcon className="w-4 h-4 text-indigo-500" />
            <h3 className="text-sm font-semibold text-slate-700">
              Leave overview — {summary.current_year}
            </h3>
            <span className="ml-auto text-xs text-slate-400">
              {MONTH_NAMES[(summary.current_month ?? new Date().getMonth() + 1) - 1]} {summary.current_year ?? new Date().getFullYear()}
            </span>
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-5 gap-3">
            {/* Employees tracked */}
            <LeaveTile
              icon="UsersIcon" label="Employees Tracked"
              value={summary.leave_employees} sub="active this year"
              bg="bg-indigo-50" border="border-indigo-100" textColor="text-indigo-700" subColor="text-indigo-500"
              onClick={() => setReportId('leave_employees')}
            />
            {/* Leave taken YTD */}
            <LeaveTile
              icon="ArrowTrendingDownIcon" label="Leave Taken YTD"
              value={parseFloat(summary.leave_total_taken_ytd ?? 0).toFixed(1)} sub="days"
              bg="bg-amber-50" border="border-amber-100" textColor="text-amber-700" subColor="text-amber-500"
              onClick={() => setReportId('leave_taken_ytd')}
            />
            {/* Leave earned YTD */}
            <LeaveTile
              icon="ArrowTrendingUpIcon" label="Leave Earned YTD"
              value={parseFloat(summary.leave_total_earned_ytd ?? 0).toFixed(1)} sub="days"
              bg="bg-emerald-50" border="border-emerald-100" textColor="text-emerald-700" subColor="text-emerald-500"
              onClick={() => setReportId('leave_earned_ytd')}
            />
            {/* Avg balance */}
            <LeaveTile
              icon="ScaleIcon" label="Avg Leave Balance"
              value={parseFloat(summary.leave_avg_balance ?? 0).toFixed(1)} sub="days / employee"
              bg="bg-teal-50" border="border-teal-100" textColor="text-teal-700" subColor="text-teal-500"
              onClick={() => setReportId('leave_avg_balance')}
            />
            {/* Critical alerts */}
            <LeaveTile
              icon="ExclamationTriangleIcon" label="Critical Balance"
              value={summary.leave_critical_alerts ?? 0} sub="employees at ≤ 0 days"
              bg={(summary.leave_critical_alerts ?? 0) > 0 ? 'bg-rose-50' : 'bg-slate-50'}
              border={(summary.leave_critical_alerts ?? 0) > 0 ? 'border-rose-100' : 'border-slate-100'}
              textColor={(summary.leave_critical_alerts ?? 0) > 0 ? 'text-rose-700' : 'text-slate-400'}
              subColor={(summary.leave_critical_alerts ?? 0) > 0 ? 'text-rose-500' : 'text-slate-400'}
              onClick={() => setReportId('leave_critical')}
            />
          </div>
          {/* On leave this month sub-line */}
          {parseFloat(summary.leave_current_month_taken ?? 0) > 0 && (
            <div className="mt-3 pt-3 border-t border-slate-100 flex items-center gap-2 text-xs text-slate-500">
              <HeroIcons.CalendarIcon className="w-3.5 h-3.5 text-slate-400" />
              <span>
                <strong className="text-slate-700">
                  {parseFloat(summary.leave_current_month_taken).toFixed(1)} days
                </strong>{' '}
                taken in {MONTH_NAMES[(summary.current_month ?? 1) - 1]} across{' '}
                <strong className="text-slate-700">{summary.leave_employees_taken}</strong> employees YTD
              </span>
            </div>
          )}
        </div>
      )}

      {/* Approval Pipeline Widget — super-admin only, non-blocking */}
      {isSuperAdmin && trackerData && (
        <ApprovalPipelineWidget
          data={trackerData}
          onViewAll={() => onSwitchTab?.('tracker')}
        />
      )}

      {/* KPI drill-down report modal */}
      {reportId && (
        <KpiReportModal reportId={reportId} onClose={() => setReportId(null)} />
      )}

    </div>
  )
}

﻿/**
 * Payroll Engine — Monthly automation shell.
 *
 * Props (passed by parent Payroll.jsx):
 *   activeRunId   — UUID/PK of a run to deep-link into (from ?run= query)
 *   onSelectRun   — bubbles run selection back to parent (kept for URL sync)
 *   onSwitchTab   — bubbles top-level tab changes back to parent (unused here)
 *
 * Internal sub-tabs live in payroll/engine/. Selecting a run from the
 * 'runs' tab shows RunDetail in place; clicking "All runs" returns.
 */
import React, { useState, useEffect } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'

import {
  ENGINE_TABS, DEFAULT_ENGINE_TAB,
  CANVAS_MODES, DEFAULT_CANVAS_MODE,
  PAYROLL_ENGINE_CANVAS_STORAGE_KEY,
} from '../../../config/payrollEngine.config'

import RunsList         from './engine/RunsList'
import RunDetail        from './engine/RunDetail'
import EmployeesTable   from './engine/EmployeesTable'
import AdjustmentsList  from './engine/AdjustmentsList'
import ComparisonsHub   from './engine/ComparisonsHub'
import ExcelHub         from './engine/ExcelHub'

const TAB_ICONS = {
  runs:        'CalendarDaysIcon',
  employees:   'UsersIcon',
  adjustments: 'AdjustmentsHorizontalIcon',
  comparison:  'ArrowsRightLeftIcon',
  excel:       'TableCellsIcon',
}

const readStoredCanvas = () => {
  try {
    const stored = localStorage.getItem(PAYROLL_ENGINE_CANVAS_STORAGE_KEY)
    if (stored && CANVAS_MODES.some((m) => m.key === stored)) return stored
  } catch (_) { /* localStorage unavailable */ }
  return DEFAULT_CANVAS_MODE
}

export default function PayrollEngine({ activeRunId, initialTab, onSelectRun, onSwitchTab }) {
  const [tab, setTab] = useState(initialTab || DEFAULT_ENGINE_TAB)
  const [selectedRunId, setSelectedRunId] = useState(activeRunId || null)
  const [canvasModeKey] = useState(readStoredCanvas)
  const [employeeActionsTarget, setEmployeeActionsTarget] = useState(null)

  // Deep-link contract: parent supplies ?run=<id> → jump into detail view
  useEffect(() => {
    if (activeRunId) {
      setSelectedRunId(activeRunId)
      setTab('runs')
    }
  }, [activeRunId])

  useEffect(() => {
    if (initialTab && ENGINE_TABS.some((item) => item.key === initialTab)) {
      setTab(initialTab)
      setSelectedRunId(null)
    }
  }, [initialTab])

  // Persist canvas mode across reloads
  useEffect(() => {
    try { localStorage.setItem(PAYROLL_ENGINE_CANVAS_STORAGE_KEY, canvasModeKey) }
    catch (_) { /* ignore */ }
  }, [canvasModeKey])

  const handleSelectRun = (run) => {
    const id = typeof run === 'string' ? run : run?.id
    setSelectedRunId(id)
    onSelectRun?.(run)
  }

  const handleBackToList = () => {
    setSelectedRunId(null)
    onSelectRun?.(null)
  }

  return (
    <div className="w-full min-w-0 space-y-4">
      {/* Sub-tab navigation and actions */}
      <div className="bg-white border border-slate-200 rounded-xl p-2 flex flex-wrap items-center justify-between gap-2">
        <div className="flex flex-wrap gap-1">
          {ENGINE_TABS.map((t) => {
            const Icon = HeroIcons[TAB_ICONS[t.key]] || HeroIcons.RectangleStackIcon
            const isActive = tab === t.key
            return (
              <button
                key={t.key}
                type="button"
                onClick={() => {
                  setTab(t.key)
                  if (t.key !== 'runs') setSelectedRunId(null)
                }}
                title={t.description}
                className={`inline-flex items-center gap-1.5 px-3.5 py-2 text-sm font-medium rounded-lg border whitespace-nowrap ${
                  isActive
                    ? 'border-indigo-200 text-indigo-700 bg-indigo-50'
                    : 'border-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-50'
                }`}
              >
                <Icon className="w-4 h-4" />
                {t.label}
              </button>
            )
          })}
        </div>
        <div ref={setEmployeeActionsTarget} />
      </div>

      {/* Sub-tab content */}
      {tab === 'runs' && (
        selectedRunId
          ? <RunDetail
              runId={selectedRunId}
              onBack={handleBackToList}
              canvasModeKey={canvasModeKey}
            />
          : <RunsList onSelectRun={handleSelectRun} />
      )}
      {tab === 'employees'   && <EmployeesTable actionsTarget={employeeActionsTarget} />}
      {tab === 'adjustments' && <AdjustmentsList />}
      {tab === 'comparison'  && <ComparisonsHub />}
      {tab === 'excel'       && (
        <ExcelHub
          onAfterImport={(run) => {
            setTab('runs')
            handleSelectRun(run)
          }}
        />
      )}
    </div>
  )
}

import { useEffect, useMemo, useRef, useState } from 'react'
import * as Icons from '@heroicons/react/24/outline'
import { CartesianGrid, Line, LineChart, ReferenceLine, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts'
import ts from '../../../services/timesheet.service'
import payrollService from '../../../services/payroll.service'
import { BRANCHES } from '../../../config/hrLeave.config'
import { ATT_GOOD_RATE_PCT, ATT_WARN_RATE_PCT, ATT_STANDARD_MONTHLY_WORKING_DAYS, MONTH_SHORT, MONTH_FULL } from '../../../config/hrAttendance.config'
import { buildYearlyEmployees, summarizeYearlyEmployees } from './yearlyAttendanceModel'

const STATUS = {
  ready: { label: 'On target', Icon: Icons.CheckCircleIcon },
  review: { label: 'Below target', Icon: Icons.ExclamationTriangleIcon },
  incomplete: { label: 'Incomplete data', Icon: Icons.InformationCircleIcon },
}
const OPTIONAL_COLUMNS = [
  ['department', 'Department'], ['status', 'Status'], ['leave', 'Leave balance'],
  ['overtime', 'Recorded OT (Unapproved)'], ['year', 'Year'],
]
const number = value => (typeof value === 'number' || (typeof value === 'string' && value.trim() !== '')) && Number.isFinite(Number(value)) ? Number(value) : null
const format = value => value === null ? '—' : value.toLocaleString('en-US', { maximumFractionDigits: 1 })
const percent = value => value === null ? '—' : `${format(value)}%`
const tone = value => value === null ? 'unknown' : value >= ATT_GOOD_RATE_PCT ? 'good' : value >= ATT_WARN_RATE_PCT ? 'warn' : 'low'
const matchEmployee = (employee, query) => !query.trim() || [employee.name, employee.code, employee.dept].some(value => String(value).toLowerCase().includes(query.trim().toLowerCase()))

export default function YearlyAttendanceTab({ Pagination }) {
  const now = new Date()
  const currentYear = now.getFullYear(), currentMonth = now.getMonth() + 1
  const [year, setYear] = useState(currentYear)
  const [branch, setBranch] = useState('all')
  const [department, setDepartment] = useState('all')
  const [search, setSearch] = useState('')
  const [tableSearch, setTableSearch] = useState('')
  const [status, setStatus] = useState('all')
  const [density, setDensity] = useState('comfortable')
  const [hidden, setHidden] = useState([])
  const [descending, setDescending] = useState(false)
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(25)
  const [refresh, setRefresh] = useState(0)
  const [attendance, setAttendance] = useState({ year: null, busy: true, months: [] })
  const [leave, setLeave] = useState({ year: null, busy: true, balances: {}, error: false })
  const [branchState, setBranchState] = useState({ key: '', busy: false, codes: [], error: false })
  const [exportOpen, setExportOpen] = useState(false)
  const [exportBusy, setExportBusy] = useState(false)
  const [exportFormat, setExportFormat] = useState('excel')
  const [exportError, setExportError] = useState('')
  const exportRef = useRef(null)
  const retry = () => setRefresh(value => value + 1)

  useEffect(() => {
    let active = true
    setAttendance({ year, busy: true, months: [] })
    Promise.all(Array.from({ length: 12 }, async (_, index) => {
      try {
        const response = await ts.fetchMonthly(year, index + 1)
        const rows = Array.isArray(response) ? response : response?.rows
        if (response?.configured === false || !Array.isArray(rows)) throw new Error('Unavailable attendance source')
        return { state: 'loaded', rows }
      } catch { return { state: 'error', rows: [] } }
    })).then(months => { if (active) setAttendance({ year, busy: false, months }) })
    return () => { active = false }
  }, [year, refresh])

  useEffect(() => {
    let active = true
    setLeave({ year, busy: true, balances: {}, error: false })
    payrollService.getAnnualLeaveBalanceSummary(year, 12)
      .then(response => {
        if (!response?.balances || typeof response.balances !== 'object' || Array.isArray(response.balances)) throw new Error('Invalid annual leave response')
        if (active) setLeave({ year, busy: false, balances: response.balances, error: false })
      })
      .catch(() => { if (active) setLeave({ year, busy: false, balances: {}, error: true }) })
    return () => { active = false }
  }, [year, refresh])

  useEffect(() => {
    if (branch === 'all') return undefined
    let active = true
    const key = `${year}:${branch}`
    setBranchState({ key, busy: true, codes: [], error: false })
    payrollService.getBranchEmployeeCodes(branch, year)
      .then(response => {
        if (!Array.isArray(response?.codes)) throw new Error('Invalid branch mapping')
        if (active) setBranchState({ key, busy: false, codes: response.codes.map(String), error: false })
      })
      .catch(() => { if (active) setBranchState({ key, busy: false, codes: [], error: true }) })
    return () => { active = false }
  }, [year, branch, refresh])

  useEffect(() => { setPage(1) }, [year, branch, department, search, status, tableSearch, pageSize, descending])
  useEffect(() => { setExportError('') }, [year])
  useEffect(() => {
    if (!exportOpen) return undefined
    const close = event => { if (!exportRef.current?.contains(event.target)) setExportOpen(false) }
    document.addEventListener('mousedown', close)
    return () => document.removeEventListener('mousedown', close)
  }, [exportOpen])

  const busy = attendance.year !== year || attendance.busy
  const branchCurrent = branchState.key === `${year}:${branch}`
  const branchBusy = branch !== 'all' && (!branchCurrent || branchState.busy)
  const branchError = branch !== 'all' && branchCurrent && branchState.error
  const ready = !busy && !branchBusy && !branchError
  const relevantMonths = year < currentYear ? 12 : currentMonth
  const failedMonths = attendance.year === year ? attendance.months.flatMap((month, index) => index < relevantMonths && month.state === 'error' ? [MONTH_SHORT[index]] : []) : []
  const allFailed = !busy && failedMonths.length === relevantMonths
  const employees = useMemo(() => busy ? [] : buildYearlyEmployees(attendance.months, { year, currentYear, currentMonth }), [attendance, year, currentYear, currentMonth, busy])
  const branchEmployees = useMemo(() => {
    if (!ready) return []
    const codes = new Set(branchState.codes)
    return branch === 'all' ? employees : employees.filter(employee => codes.has(employee.code))
  }, [ready, employees, branch, branchState.codes])
  const departments = useMemo(() => [...new Set(branchEmployees.map(employee => employee.dept))].sort(), [branchEmployees])
  const filtered = useMemo(() => branchEmployees.filter(employee =>
    (department === 'all' || employee.dept === department) && (status === 'all' || employee.status === status) && matchEmployee(employee, search)
  ), [branchEmployees, department, status, search])
  const totals = useMemo(() => summarizeYearlyEmployees(filtered), [filtered])
  const overtimePartial = filtered.some(employee => employee.months.some(month => !month || month.overtime === null))
  const tableRows = useMemo(() => filtered.filter(employee => matchEmployee(employee, tableSearch)).sort((a, b) => (descending ? -1 : 1) * a.name.localeCompare(b.name)), [filtered, tableSearch, descending])
  const safePage = Math.min(page, Math.max(1, Math.ceil(tableRows.length / pageSize)))
  const paged = tableRows.slice((safePage - 1) * pageSize, safePage * pageSize)
  const leaveReady = leave.year === year && !leave.busy && !leave.error
  const takenValues = filtered.map(employee => employee.code ? number(leave.balances[employee.code]?.taken_ytd) : null)
  const taken = ready && leaveReady && takenValues.length && takenValues.every(value => value !== null) ? takenValues.reduce((sum, value) => sum + value, 0) : null
  const lastPoint = [...totals.trend].reverse().find(point => point.rate !== null)
  const show = id => !hidden.includes(id)
  const metric = value => ready && !allFailed ? format(value) : '—'
  const exportYear = async kind => {
    setExportFormat(kind)
    setExportError('')
    setExportBusy(true)
    try { await (kind === 'pdf' ? ts.downloadYearlyPdf(year) : ts.downloadYearlyExcel(year)) }
    catch { setExportError('The yearly report could not be exported. Please try again.') }
    finally { setExportBusy(false) }
  }

  return <section className="att-yearly" data-density={density} aria-label="Yearly attendance">
    <div className="att-filter-panel att-yearly-toolbar" aria-label="Yearly attendance filters">
      <label className="att-field"><span>Year</span><select aria-label="Year" value={year} disabled={exportBusy} onChange={event => setYear(Number(event.target.value))}>{[currentYear - 2, currentYear - 1, currentYear].map(value => <option key={value}>{value}</option>)}</select></label>
      <label className="att-field att-yearly-select"><span>Branch</span><select aria-label="Branch" value={branch} title="Branch mapping from the selected year's HR records" onChange={event => setBranch(event.target.value)}><option value="all">All branches</option>{BRANCHES.map(item => <option key={item.id} value={item.id}>{item.label}</option>)}</select></label>
      <label className="att-field att-yearly-select"><span>Department</span><select aria-label="Department" value={department} onChange={event => setDepartment(event.target.value)}><option value="all">All departments</option>{department !== 'all' && !departments.includes(department) && <option>{department}</option>}{departments.map(value => <option key={value}>{value}</option>)}</select></label>
      <label className="att-field att-search"><span className="sr-only">Search employees</span><div className="att-search-box"><Icons.MagnifyingGlassIcon aria-hidden="true" /><input aria-label="Search employees" placeholder="Employee name or ID" value={search} onChange={event => setSearch(event.target.value)} /></div></label>
      <label className="att-field"><span>Status</span><select aria-label="Status" value={status} onChange={event => setStatus(event.target.value)}><option value="all">All statuses</option>{Object.entries(STATUS).map(([id, item]) => <option key={id} value={id}>{item.label}</option>)}</select></label>
      <div className="att-yearly-tools">
        <details className="att-columns" onKeyDown={event => { if (event.key === 'Escape') { event.currentTarget.open = false; event.currentTarget.querySelector('summary')?.focus() } }}><summary className="att-button"><Icons.ViewColumnsIcon aria-hidden="true" />Columns</summary><div className="att-columns-panel">{OPTIONAL_COLUMNS.map(([id, label]) => <label key={id}><input type="checkbox" checked={show(id)} onChange={event => setHidden(previous => event.target.checked ? previous.filter(value => value !== id) : [...previous, id])} />{label}</label>)}</div></details>
        <label className="att-density"><span className="sr-only">Density</span><select aria-label="Density" value={density} onChange={event => setDensity(event.target.value)}><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></label>
        <div ref={exportRef} className="att-yearly-export" onKeyDown={event => { if (event.key === 'Escape') { setExportOpen(false); exportRef.current?.querySelector('button')?.focus() } }}>
          <button type="button" className="att-button" aria-expanded={exportOpen} onClick={() => setExportOpen(value => !value)}><Icons.ArrowUpTrayIcon aria-hidden="true" />Export</button>
          {exportOpen && <div className="att-yearly-export-panel" role="group" aria-label="Yearly export formats"><p>Monthly recorded hours · {year}<br />All employees permitted by the export.</p><button type="button" className="att-button" disabled={exportBusy} onClick={() => exportYear('excel')}>Excel · monthly hours</button><button type="button" className="att-button" disabled={exportBusy} onClick={() => exportYear('pdf')}>PDF · monthly hours</button></div>}
        </div>
        <button type="button" className="att-button" aria-label="Refresh yearly attendance" disabled={busy || branchBusy} onClick={retry}><Icons.ArrowPathIcon aria-hidden="true" /></button>
      </div>
    </div>

    {!busy && failedMonths.length > 0 && <div role="alert" className="att-yearly-message">Attendance unavailable for {failedMonths.join(', ')}. These months are excluded from recorded averages.<button type="button" className="att-button" onClick={retry}>Retry attendance</button></div>}
    {branchError && <div role="alert" className="att-yearly-message">Branch employees could not be loaded. The selected branch remains active.<button type="button" className="att-button" onClick={retry}>Retry branch</button></div>}
    {leave.year === year && leave.error && <div role="status" className="att-yearly-message">Annual leave figures could not be loaded.<button type="button" className="att-button" onClick={retry}>Retry leave</button></div>}
    {exportError && <div role="alert" className="att-yearly-message">{exportError}<button type="button" className="att-button" disabled={exportBusy} onClick={() => exportYear(exportFormat)}>Retry export</button></div>}

    <dl className="att-summary att-yearly-summary" aria-label="Yearly attendance summary">
      <div className="att-summary-item" title="Employees found in available monthly responses"><Icons.UserGroupIcon aria-hidden="true" /><div><dt>Employees</dt><dd>{metric(filtered.length)}</dd></div></div>
      <div className="att-summary-item" title="Mean of the monthly recorded rates. Missing months are excluded; import completeness is not certified."><Icons.CheckCircleIcon aria-hidden="true" /><div><dt>Average recorded rate</dt><dd>{ready && !allFailed ? percent(totals.averageRecordedRate) : '—'}</dd></div></div>
      <div className="att-summary-item" title="Only employees with all 12 recorded months can be assessed for the full year."><Icons.ExclamationTriangleIcon aria-hidden="true" /><div><dt>Below target (&lt; {ATT_GOOD_RATE_PCT}%)</dt><dd className="att-negative">{metric(totals.belowTarget)}</dd><small>Full-year records only</small></div></div>
      <div className="att-summary-item" title="Annual leave taken from HR imports for this year; not all leave types."><Icons.CalendarDaysIcon aria-hidden="true" /><div><dt>Annual leave taken</dt><dd>{taken === null ? '—' : `${format(taken)} days`}</dd></div></div>
      <div className="att-summary-item" title="Sum of available recorded overtime; this is not approved overtime."><Icons.ClockIcon aria-hidden="true" /><div><dt>Recorded OT (Unapproved)</dt><dd>{ready && !allFailed && totals.totalOvertime !== null ? `${format(totals.totalOvertime)} h` : '—'}</dd>{ready && overtimePartial && totals.totalOvertime !== null && <small>Partial · recorded months only</small>}</div></div>
    </dl>

    <section className="att-yearly-trend" aria-label="Yearly attendance trend" aria-busy={busy || branchBusy}>
      <div className="att-yearly-chart-area">
        <div className="att-yearly-chart-heading"><h2>{year} attendance trend</h2><p><Icons.InformationCircleIcon aria-hidden="true" />Recorded months only; missing months stay blank.</p></div>
        <div className="att-yearly-chart" role="img" aria-label={`${year} recorded attendance rates. ${totals.trend.map(point => `${point.month}: ${percent(point.rate)}`).join(', ')}. Configured target ${ATT_GOOD_RATE_PCT} percent.`}>
          <ResponsiveContainer width="100%" height="100%"><LineChart data={totals.trend} margin={{ top: 20, right: 20, bottom: 4, left: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="#e9eff7" /><XAxis dataKey="month" tick={{ fontSize: 10, fill: '#526b8f' }} interval={0} tickLine={false} /><YAxis domain={[0, 100]} ticks={[0, 25, 50, 75, 100]} width={42} tick={{ fontSize: 10, fill: '#526b8f' }} tickFormatter={value => `${value}%`} />
            <Tooltip formatter={value => [percent(value), 'Recorded attendance']} contentStyle={{ borderRadius: 8, borderColor: '#dce5f1', fontSize: 12 }} />
            <ReferenceLine y={ATT_GOOD_RATE_PCT} stroke="#889bb8" strokeDasharray="5 5" />
            <Line type="linear" dataKey="rate" connectNulls={false} stroke="#246bff" strokeWidth={2} dot={{ r: 3, fill: '#246bff' }} activeDot={{ r: 5 }} isAnimationActive={false} label={({ x, y, value }) => value == null ? null : <text x={x} y={y - 10} fill="#203552" textAnchor="middle" fontSize={10} fontWeight={600}>{value}%</text>} />
          </LineChart></ResponsiveContainer>
        </div>
        <div className="att-yearly-legend"><span><i />Recorded attendance rate</span><span><i />Configured target {ATT_GOOD_RATE_PCT}%</span></div>
      </div>
      <dl className="att-yearly-trend-stats">
        <div><dt>{lastPoint ? `Latest (${lastPoint.month} ${year})` : 'Latest recorded month'}</dt><dd data-tone={tone(lastPoint?.rate ?? null)}>{ready ? percent(lastPoint?.rate ?? null) : '—'}</dd></div>
        <div><dt>Configured target</dt><dd>{ATT_GOOD_RATE_PCT}%</dd></div>
        <div><dt>Full-year rate</dt><dd>{ready ? percent(totals.fullYearRate) : '—'}</dd></div>
        <div><dt>Months with records</dt><dd>{ready && !allFailed ? `${totals.monthsWithRecords} of 12` : '—'}</dd></div>
      </dl>
    </section>

    <section className="att-yearly-panel" aria-label="Employee yearly attendance" aria-busy={busy || branchBusy}>
      <div className="att-yearly-table-heading"><strong>{ready && !allFailed ? `${filtered.length} employees` : 'Employee attendance'}</strong><p><Icons.InformationCircleIcon aria-hidden="true" />Rate = present days ÷ {ATT_STANDARD_MONTHLY_WORKING_DAYS} configured workdays.<span className="att-yearly-rate-key">Green ≥{ATT_GOOD_RATE_PCT}%; amber ≥{ATT_WARN_RATE_PCT}%; red &lt;{ATT_WARN_RATE_PCT}%.</span></p><label className="att-yearly-table-search"><Icons.MagnifyingGlassIcon aria-hidden="true" /><input aria-label="Search in yearly table" placeholder="Search in table…" value={tableSearch} onChange={event => setTableSearch(event.target.value)} /></label></div>
      {busy || branchBusy ? <div className="att-yearly-empty" role="status"><Icons.ArrowPathIcon className="animate-spin" aria-hidden="true" />Loading yearly attendance…</div>
        : branchError || allFailed ? <div className="att-yearly-empty">Attendance is unavailable. Use Retry above to load this selection.</div>
          : tableRows.length === 0 ? <div className="att-yearly-empty" role="status"><Icons.CalendarDaysIcon aria-hidden="true" /><p>{employees.length ? 'No employees match the selected filters.' : 'No attendance records for the selected year.'}</p>{(branch !== 'all' || department !== 'all' || status !== 'all' || search || tableSearch) && <button type="button" className="att-button" onClick={() => { setBranch('all'); setDepartment('all'); setStatus('all'); setSearch(''); setTableSearch('') }}>Clear filters</button>}</div>
            : <>
              <div className="att-table-scroll" role="region" aria-label="Yearly attendance table" tabIndex={0}><table className="att-yearly-table"><caption className="sr-only">{year} recorded attendance by employee. Missing months are not zero attendance.</caption>
                <thead><tr><th scope="col" aria-sort={descending ? 'descending' : 'ascending'}><button type="button" aria-label="Sort by Employee" onClick={() => setDescending(value => !value)}>Employee<Icons.ArrowUpIcon aria-hidden="true" className={descending ? 'rotate-180' : ''} /></button></th>{show('department') && <th scope="col">Department</th>}{MONTH_SHORT.map(month => <th scope="col" key={month}>{month}</th>)}{show('status') && <th scope="col">Status</th>}{show('leave') && <th scope="col">Leave balance</th>}{show('overtime') && <th scope="col">Recorded OT<br /><small>(Unapproved)</small></th>}{show('year') && <th scope="col">Year</th>}</tr></thead>
                <tbody>{paged.map(employee => {
                  const statusInfo = STATUS[employee.status]
                  const balance = leaveReady && employee.code ? number(leave.balances[employee.code]?.balance) : null
                  return <tr key={employee.key}><td title={`${employee.name} · ${employee.code}`}>{employee.name}</td>{show('department') && <td title={employee.dept}>{employee.dept}</td>}{employee.months.map((month, index) => <td key={index}>
                    {month ? <span data-tone={tone(month.rate)} title={`${MONTH_FULL[index]}: ${month.present} recorded present days / ${ATT_STANDARD_MONTHLY_WORKING_DAYS} configured days`}>{percent(month.rate)}</span> : <span className="att-yearly-missing">—<small>{employee.monthStates[index] === 'unavailable' ? 'Unavailable' : employee.monthStates[index] === 'future' ? 'Upcoming' : 'No data'}</small></span>}
                  </td>)}{show('status') && <td><span className="att-yearly-status" data-status={employee.status} title="Attendance display threshold only; this does not indicate payroll or import approval."><statusInfo.Icon aria-hidden="true" />{statusInfo.label}</span></td>}{show('leave') && <td className="att-yearly-leave" title="Annual leave balance from HR records">{balance === null ? '—' : `${format(balance)} d`}</td>}{show('overtime') && <td className="att-yearly-overtime" title="Available recorded overtime; missing months are not included">{employee.totalOvertime === null ? '—' : `${format(employee.totalOvertime)} h`}{employee.totalOvertime !== null && employee.months.some(month => !month || month.overtime === null) && <small>Partial</small>}</td>}{show('year') && <td><span data-tone={tone(employee.fullYearRate)} title="A full-year rate requires records for all 12 months.">{percent(employee.fullYearRate)}</span></td>}</tr>
                })}</tbody>
              </table></div>
              <Pagination total={tableRows.length} page={safePage} pageSize={pageSize} onPageChange={setPage} onPageSizeChange={setPageSize} />
            </>}
    </section>
  </section>
}

/**
 * Schema-driven editor for a single PayrollAdjustment.
 *
 * Every field is generated from `ADJUSTMENT_EDIT_FIELDS` in
 * payrollEngine.config — add an entry there and a control appears here.
 *
 * Specials:
 *   • `type: 'employee'`   → searchable employee picker (uses /employees/).
 *   • `type: 'component'`  → dependent dropdown that switches between
 *                            `earning_components` and `deduction_components`
 *                            based on the value of the `kind` field.
 *
 * Backend write access is gated by `PayrollAdjustmentWritePermission`, so
 * this modal is also gated by `canEditPayrollAdjustment` on the parent.
 */
import React, { useEffect, useMemo, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService from '../../../../services/payrollEngine.service'
import {
  ADJUSTMENT_EDIT_FIELDS,
  ADJUSTMENT_KIND,
  PAYROLL_ENGINE_CURRENCY,
} from '../../../../config/payrollEngine.config'

const MONTHS = [
  { value: 1, label: 'Jan' }, { value: 2, label: 'Feb' }, { value: 3, label: 'Mar' },
  { value: 4, label: 'Apr' }, { value: 5, label: 'May' }, { value: 6, label: 'Jun' },
  { value: 7, label: 'Jul' }, { value: 8, label: 'Aug' }, { value: 9, label: 'Sep' },
  { value: 10, label: 'Oct' }, { value: 11, label: 'Nov' }, { value: 12, label: 'Dec' },
]

const toFormValue = (raw, type) => {
  if (raw === null || raw === undefined) return ''
  return raw
}

const toPayloadValue = (val, type) => {
  if (type === 'number') return val === '' || val === null ? null : val
  return val ?? ''
}

const FIELD_GROUPS_ORDER = (() => {
  const seen = new Set()
  const order = []
  for (const f of ADJUSTMENT_EDIT_FIELDS) {
    const g = f.group || 'General'
    if (!seen.has(g)) { seen.add(g); order.push(g) }
  }
  return order
})()

const today = new Date()
const DEFAULTS = {
  target_year: today.getFullYear(),
  target_month: today.getMonth() + 1,
  kind: ADJUSTMENT_KIND.EARNING,
  status: 'pending',
}

export default function AdjustmentModal({ open, adjustment, onClose, onSaved }) {
  const currentDate = new Date()
  const currentYear = currentDate.getFullYear()
  const currentMonth = currentDate.getMonth() + 1
  const isEdit = !!adjustment?.id
  const [form, setForm] = useState({})
  const [catalog, setCatalog] = useState(null)
  const [employees, setEmployees] = useState([])
  const [empSearch, setEmpSearch] = useState('')
  const [empSelected, setEmpSelected] = useState(false)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState(null)
  const [touched, setTouched] = useState(false)

  // Seed form whenever modal opens
  useEffect(() => {
    if (!open) return
    const seeded = {}
    for (const f of ADJUSTMENT_EDIT_FIELDS) {
      const raw = adjustment?.[f.key] ?? DEFAULTS[f.key]
      seeded[f.key] = toFormValue(raw, f.type)
    }
    setForm(seeded)
    setError(null)
    setTouched(false)
    setEmpSearch(adjustment?.employee_name || '')
    setEmpSelected(Boolean(adjustment?.employee))
  }, [open, adjustment])

  // Load /catalog/ once for select options
  useEffect(() => {
    if (!open || catalog) return
    payrollEngineService.getCatalog()
      .then(setCatalog)
      .catch(() => setCatalog({}))
  }, [open, catalog])

  // Load employees list for picker (cap at 500 — typical org)
  useEffect(() => {
    if (!open || employees.length > 0) return
    payrollEngineService.listEmployees({ page_size: 500 })
      .then((res) => {
        const list = Array.isArray(res) ? res : (res?.results || [])
        setEmployees(list)
      })
      .catch(() => setEmployees([]))
  }, [open, employees.length])

  const handleChange = (key, value) => {
    setForm((prev) => {
      const next = { ...prev, [key]: value }
      // When kind changes, clear the dependent component_code so the user
      // is forced to re-pick from the right list.
      if (key === 'target_year' && Number(value) === currentYear && Number(prev.target_month) < currentMonth) next.target_month = currentMonth
      if (key === 'kind' && value !== prev.kind) next.component_code = ''
      return next
    })
    setTouched(true)
  }

  const resolveOptions = (field) => {
    if (field.optionsFrom === 'months') return MONTHS.filter(month => Number(form.target_year) > currentYear || (Number(form.target_year) === currentYear && month.value >= currentMonth))
    if (field.optionsFrom && catalog?.[field.optionsFrom]) {
      return catalog[field.optionsFrom].map((o) => ({
        value: o.code ?? o.value ?? o,
        label: o.label ?? o.name ?? o.code ?? String(o),
      }))
    }
    return []
  }

  const resolveComponentOptions = () => {
    if (!catalog) return []
    const kind = form.kind
    const src = kind === ADJUSTMENT_KIND.DEDUCTION
      ? catalog.deduction_components
      : catalog.earning_components
    return (src || []).map((o) => ({
      value: o.code,
      label: o.label || o.code,
    }))
  }

  const filteredEmployees = useMemo(() => {
    const q = (empSearch || '').trim().toLowerCase()
    if (!q) return employees.slice(0, 50)
    return employees.filter((e) =>
      (e.full_name || '').toLowerCase().includes(q)
      || (e.employee_no || '').toLowerCase().includes(q)
    ).slice(0, 50)
  }, [empSearch, employees])

  const grouped = useMemo(() => {
    const byGroup = {}
    for (const f of ADJUSTMENT_EDIT_FIELDS) {
      // Hide edit-only fields when creating
      if (f.editOnly && !isEdit) continue
      const g = f.group || 'General'
      if (!byGroup[g]) byGroup[g] = []
      byGroup[g].push(f)
    }
    return byGroup
  }, [isEdit])

  const handleSubmit = async (e) => {
    e.preventDefault()
    for (const f of ADJUSTMENT_EDIT_FIELDS) {
      if (!f.required) continue
      if (f.editOnly && !isEdit) continue
      const v = form[f.key]
      if (v === '' || v === null || v === undefined) {
        setError(`${f.label} is required.`)
        return
      }
    }
    if (Number(form.target_year) < currentYear || (Number(form.target_year) === currentYear && Number(form.target_month) < currentMonth)) { setError('Select the current month or a future month.'); return }
    setSaving(true); setError(null)
    try {
      const payload = {}
      for (const f of ADJUSTMENT_EDIT_FIELDS) {
        if (f.editOnly && !isEdit) continue
        payload[f.key] = toPayloadValue(form[f.key], f.type)
      }
      const saved = isEdit
        ? await payrollEngineService.updateAdjustment(adjustment.id, payload)
        : await payrollEngineService.createAdjustment(payload)
      onSaved?.(saved)
    } catch (err) {
      const data = err?.response?.data
      const msg = data?.detail
        || data?.error
        || (typeof data === 'object'
              ? Object.entries(data).map(([k, v]) => `${k}: ${Array.isArray(v) ? v.join(', ') : v}`).join(' · ')
              : null)
        || err.message
      setError(msg)
    } finally {
      setSaving(false)
    }
  }

  const renderInput = (field) => {
    const id = `adj-edit-${field.key}`
    const value = form[field.key]
    const baseCls =
      'w-full text-sm border border-slate-300 rounded-md px-2.5 py-1.5 ' +
      'focus:outline-none focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 ' +
      'disabled:bg-slate-50 disabled:text-slate-500'

    if (field.type === 'employee') {
      const selected = employees.find((e) => String(e.id) === String(value))
      return (
        <div className="space-y-1">
          <input
            type="text"
            placeholder="Search by name or emp #…"
            value={empSearch}
            onChange={(e) => {
              setEmpSearch(e.target.value)
              setEmpSelected(false)
              // Search text is not a selection. Clear the previous employee so
              // validation and the submitted payload cannot use a stale ID.
              if (form[field.key]) handleChange(field.key, '')
            }}
            className={baseCls}
          />
          {!empSelected && (
          <select
            id={id}
            value={value ?? ''}
            onChange={(e) => {
              handleChange(field.key, e.target.value)
              const emp = employees.find((em) => String(em.id) === String(e.target.value))
              if (emp){
                 setEmpSearch(`${emp.employee_no} · ${emp.full_name}`)
                 setEmpSelected(true)
              }
            }}
            className={baseCls}
            size={Math.min(6, Math.max(3, filteredEmployees.length))}
          >
            <option value="" disabled>
              Select an employee from the results
            </option>
            {selected && !filteredEmployees.some((e) => String(e.id) === String(selected.id)) && (
              <option value={selected.id}>
                {selected.employee_no} · {selected.full_name}
              </option>
            )}
            {filteredEmployees.map((e) => (
              <option key={e.id} value={e.id}>
                {e.employee_no} · {e.full_name}
              </option>
            ))}
          </select>
          )}
        </div>
      )
    }

    if (field.type === 'component') {
      const options = resolveComponentOptions()
      return (
        <select
          id={id}
          value={value ?? ''}
          onChange={(e) => handleChange(field.key, e.target.value)}
          className={baseCls}
        >
          <option value="">— Select —</option>
          {options.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
      )
    }

    if (field.type === 'select') {
      const options = resolveOptions(field)
      return (
        <select
          id={id}
          value={value ?? ''}
          onChange={(e) => handleChange(field.key, e.target.value)}
          className={baseCls}
        >
          <option value="">— Select —</option>
          {options.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
      )
    }

    if (field.type === 'textarea') {
      return (
        <textarea
          id={id}
          rows={3}
          value={value ?? ''}
          onChange={(e) => handleChange(field.key, e.target.value)}
          className={baseCls}
        />
      )
    }

    return (
      <div className="relative">
        <input
          id={id}
          type={field.type || 'text'}
          step={field.type === 'number' ? (field.step || '0.01') : undefined}
          min={field.key === 'target_year' ? currentYear : undefined}
          maxLength={field.maxLength}
          value={value ?? ''}
          onChange={(e) => handleChange(field.key, e.target.value)}
          className={`${baseCls} ${field.currency ? 'pr-12' : ''}`}
        />
        {field.currency && (
          <span className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] font-medium text-slate-400 uppercase">
            {PAYROLL_ENGINE_CURRENCY}
          </span>
        )}
      </div>
    )
  }

  if (!open) return null

  return (
    <div
      className="fixed inset-0 z-50 bg-slate-900/40 backdrop-blur-sm flex items-center justify-center p-4"
      onClick={onClose}
    >
      <form
        onSubmit={handleSubmit}
        onClick={(e) => e.stopPropagation()}
        className="bg-white w-full max-w-3xl rounded-xl shadow-xl flex flex-col max-h-[90vh]"
      >
        <div className="px-5 py-3 border-b border-slate-200 flex items-center justify-between">
          <div>
            <h3 className="text-sm font-semibold text-slate-800 flex items-center gap-2">
              <HeroIcons.AdjustmentsHorizontalIcon className="w-4 h-4 text-indigo-600" />
              {isEdit ? 'Edit Adjustment' : 'New Adjustment'}
            </h3>
            <p className="text-xs text-slate-500 mt-0.5">
              {isEdit
                ? `${adjustment.employee_name || ''} · ${adjustment.label || ''}`
                : 'Queue an earning or deduction for an upcoming payroll run.'}
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-slate-700"
            aria-label="Close"
          >
            <HeroIcons.XMarkIcon className="w-5 h-5" />
          </button>
        </div>

        <div className="px-5 py-4 overflow-y-auto space-y-5">
          {FIELD_GROUPS_ORDER.map((group) => (
            grouped[group]?.length ? (
              <fieldset key={group} className="space-y-2">
                <legend className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">
                  {group}
                </legend>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-x-4 gap-y-3">
                  {grouped[group].map((field) => (
                    <div
                      key={field.key}
                      className={
                        field.type === 'textarea' || field.type === 'employee'
                          ? 'md:col-span-2'
                          : ''
                      }
                    >
                      <label
                        htmlFor={`adj-edit-${field.key}`}
                        className="block text-xs font-medium text-slate-600 mb-1"
                      >
                        {field.label}
                        {field.required && <span className="text-red-500 ml-0.5">*</span>}
                      </label>
                      {renderInput(field)}
                    </div>
                  ))}
                </div>
              </fieldset>
            ) : null
          ))}

          {error && (
            <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2">
              {error}
            </div>
          )}
        </div>

        <div className="px-5 py-3 border-t border-slate-200 flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={onClose}
            className="px-3 py-1.5 text-sm font-medium rounded-md border border-slate-300 hover:bg-slate-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={saving || (isEdit && !touched)}
            className="inline-flex items-center gap-1.5 px-4 py-1.5 text-sm font-medium rounded-md bg-indigo-600 text-white hover:bg-indigo-700 disabled:opacity-50"
          >
            {saving
              ? <HeroIcons.ArrowPathIcon className="w-4 h-4 animate-spin" />
              : <HeroIcons.CheckIcon className="w-4 h-4" />}
            {saving ? 'Saving…' : (isEdit ? 'Save Changes' : 'Create Adjustment')}
          </button>
        </div>
      </form>
    </div>
  )
}

import { radaiConfirm, radaiAlert } from '../../../../services/radaiDialog'
/**
 * Adjustments dashboard for the Payroll Engine.
 *
 * Features (soft-coded — all controlled from payrollEngine.config.js):
 *   • KPI summary tiles (counts + totals by status / kind)
 *   • Year / month / status / kind / search filters
 *   • Bulk-select with single-click cancel
 *   • Per-row Edit & Cancel actions, gated by RBAC
 *   • Create new adjustments via AdjustmentModal
 *
 * RBAC: editing/cancelling is gated by `canEditPayrollAdjustment` which
 * mirrors the backend `PayrollAdjustmentWritePermission`. Roles can be
 * tuned via the `PAYROLL_ADJUSTMENT_WRITE_ROLES` env var.
 */
import React, { useEffect, useMemo, useState } from 'react'
import { useSelector } from 'react-redux'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService from '../../../../services/payrollEngine.service'
import {
  formatCurrency,
  ADJUSTMENT_COLUMNS,
  MONTH_NAMES,
  ADJUSTMENT_STATUS,
  ADJUSTMENT_STATUS_META,
  ADJUSTMENT_KIND,
  ADJUSTMENT_KIND_META,
  ADJUSTMENT_KPIS,
  canEditPayrollAdjustment,
} from '../../../../config/payrollEngine.config'
import AdjustmentModal from './AdjustmentModal'

const today = new Date()
const YEAR_RANGE = [today.getFullYear() - 1, today.getFullYear(), today.getFullYear() + 1]

const Icon = ({ name, className }) => {
  const Cmp = HeroIcons[name] || HeroIcons.SparklesIcon
  return <Cmp className={className} />
}

const fmtAmount = (v) => formatCurrency(v ?? 0, { withSymbol: false })
const isEditable = (a) => a?.status === ADJUSTMENT_STATUS.PENDING

export default function AdjustmentsList() {
  const authUser = useSelector((s) => s.auth?.user)
  const rbacUser = useSelector((s) => s.rbac?.currentUser)
  const canEdit = useMemo(
    () => canEditPayrollAdjustment(authUser, rbacUser),
    [authUser, rbacUser],
  )

  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [filter, setFilter] = useState({
    year: today.getFullYear(),
    month: today.getMonth() + 1,
    status: '',
    kind: '',
    search: '',
  })
  const [selectedIds, setSelectedIds] = useState(new Set())
  const [modalOpen, setModalOpen] = useState(false)
  const [editing, setEditing] = useState(null)
  const [busyIds, setBusyIds] = useState(new Set())

  const load = async () => {
    setLoading(true); setError(null)
    try {
      const params = { ...filter }
      Object.keys(params).forEach((k) => { if (!params[k] && params[k] !== 0) delete params[k] })
      delete params.search // search is applied client-side; don't shrink the slice
      const data = await payrollEngineService.listAdjustments(params)
      const list = Array.isArray(data) ? data : (data?.results ?? [])
      setItems(list)
      setSelectedIds(new Set())
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { load() /* eslint-disable-next-line */ },
    [filter.year, filter.month, filter.status, filter.kind])

  // ── Derived summary (client-side over the loaded slice)
  const summary = useMemo(() => {
    const acc = {
      count: items.length,
      pending_total: 0,
      earning_total: 0,
      deduction_total: 0,
      applied_total: 0,
      cancelled_total: 0,
    }
    for (const a of items) {
      const amt = Number(a.amount) || 0
      if (a.status === ADJUSTMENT_STATUS.PENDING)   acc.pending_total += amt
      if (a.status === ADJUSTMENT_STATUS.APPLIED)   acc.applied_total += amt
      if (a.status === ADJUSTMENT_STATUS.CANCELLED) acc.cancelled_total += amt
      if (a.kind === ADJUSTMENT_KIND.EARNING && a.status !== ADJUSTMENT_STATUS.CANCELLED)   acc.earning_total += amt
      if (a.kind === ADJUSTMENT_KIND.DEDUCTION && a.status !== ADJUSTMENT_STATUS.CANCELLED) acc.deduction_total += amt
    }
    return acc
  }, [items])

  const visible = useMemo(() => {
    const q = (filter.search || '').trim().toLowerCase()
    if (!q) return items
    return items.filter((a) =>
      (a.employee_name || '').toLowerCase().includes(q)
      || (a.employee_no || '').toLowerCase().includes(q)
      || (a.label || '').toLowerCase().includes(q)
      || (a.description || '').toLowerCase().includes(q)
      || (a.component_code || '').toLowerCase().includes(q)
    )
  }, [items, filter.search])

  const selectableIds = useMemo(
    () => visible.filter(isEditable).map((a) => a.id),
    [visible],
  )
  const allSelected = selectableIds.length > 0 && selectableIds.every((id) => selectedIds.has(id))

  const toggleSelectAll = () => {
    if (allSelected) {
      setSelectedIds(new Set())
    } else {
      setSelectedIds(new Set(selectableIds))
    }
  }
  const toggleSelectOne = (id) => {
    const next = new Set(selectedIds)
    if (next.has(id)) next.delete(id); else next.add(id)
    setSelectedIds(next)
  }

  const markBusy = (id, on = true) => {
    setBusyIds((prev) => {
      const next = new Set(prev)
      if (on) next.add(id); else next.delete(id)
      return next
    })
  }

  // ── Actions ──────────────────────────────────────────────────────────────
  const openCreate = () => { setEditing(null); setModalOpen(true) }
  const openEdit = (a) => { setEditing(a); setModalOpen(true) }

  const handleSaved = (saved) => {
    setModalOpen(false)
    setEditing(null)
    setItems((prev) => {
      const idx = prev.findIndex((x) => x.id === saved.id)
      if (idx === -1) return [saved, ...prev]
      const next = prev.slice()
      next[idx] = saved
      return next
    })
  }

  const handleCancelOne = async (a) => {
    if (!isEditable(a)) return
    if (!(await radaiConfirm(`Cancel adjustment "${a.label}" for ${a.employee_name}?`))) return
    markBusy(a.id, true)
    try {
      const updated = await payrollEngineService.cancelAdjustment(a.id)
      setItems((prev) => prev.map((x) => (x.id === a.id ? updated : x)))
    } catch (e) {
      await radaiAlert(e?.response?.data?.error || e.message || 'Failed to cancel adjustment.')
    } finally {
      markBusy(a.id, false)
    }
  }

  const handleDelete = async (a) => {
    if (!(await radaiConfirm(`Permanently delete adjustment "${a.label}"? This cannot be undone.`))) return
    markBusy(a.id, true)
    try {
      await payrollEngineService.deleteAdjustment(a.id)
      setItems((prev) => prev.filter((x) => x.id !== a.id))
    } catch (e) {
      await radaiAlert(e?.response?.data?.error || e.message || 'Failed to delete adjustment.')
    } finally {
      markBusy(a.id, false)
    }
  }

  const handleBulkCancel = async () => {
    const ids = Array.from(selectedIds)
    if (ids.length === 0) return
    if (!(await radaiConfirm(`Cancel ${ids.length} adjustment${ids.length === 1 ? '' : 's'}?`))) return
    try {
      const res = await payrollEngineService.bulkCancelAdjustments(ids)
      await load()
      await radaiAlert(`Cancelled ${res.cancelled} of ${res.requested} adjustment${res.requested === 1 ? '' : 's'}.`)
    } catch (e) {
      await radaiAlert(e?.response?.data?.error || e.message || 'Bulk cancel failed.')
    }
  }

  // ── Render ───────────────────────────────────────────────────────────────
  return (
    <div className="space-y-4">
      {/* KPI tiles */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {ADJUSTMENT_KPIS.map((k) => {
          const raw = summary[k.id] ?? 0
          const value = k.format === 'currency' ? fmtAmount(raw) : raw.toLocaleString()
          return (
            <div
              key={k.id}
              className="bg-white border border-slate-200 rounded-xl px-4 py-3 flex items-center gap-3"
            >
              <div className={`p-2 rounded-lg ${k.bg}`}>
                <Icon name={k.icon} className={`w-5 h-5 ${k.color}`} />
              </div>
              <div className="min-w-0">
                <div className="text-[11px] text-slate-500 uppercase tracking-wide">{k.label}</div>
                <div className="text-base font-semibold text-slate-800 tabular-nums truncate">{value}</div>
              </div>
            </div>
          )
        })}
      </div>

      {/* Filter / action toolbar */}
      <div className="bg-white border border-slate-200 rounded-xl p-3 flex flex-wrap gap-2 items-center">
        <select
          value={filter.year}
          onChange={(e) => setFilter({ ...filter, year: Number(e.target.value) })}
          className="text-sm border border-slate-300 rounded-md px-2 py-1.5"
        >
          {YEAR_RANGE.map((y) => <option key={y} value={y}>{y}</option>)}
        </select>
        <select
          value={filter.month}
          onChange={(e) => setFilter({ ...filter, month: Number(e.target.value) })}
          className="text-sm border border-slate-300 rounded-md px-2 py-1.5"
        >
          {MONTH_NAMES.slice(1).map((n, i) => (
            <option key={i + 1} value={i + 1}>{n}</option>
          ))}
        </select>
        <select
          value={filter.status}
          onChange={(e) => setFilter({ ...filter, status: e.target.value })}
          className="text-sm border border-slate-300 rounded-md px-2 py-1.5"
        >
          <option value="">All statuses</option>
          {Object.values(ADJUSTMENT_STATUS).map((s) => (
            <option key={s} value={s}>{ADJUSTMENT_STATUS_META[s]?.label || s}</option>
          ))}
        </select>
        <select
          value={filter.kind}
          onChange={(e) => setFilter({ ...filter, kind: e.target.value })}
          className="text-sm border border-slate-300 rounded-md px-2 py-1.5"
        >
          <option value="">All kinds</option>
          {Object.values(ADJUSTMENT_KIND).map((k) => (
            <option key={k} value={k}>{ADJUSTMENT_KIND_META[k]?.label || k}</option>
          ))}
        </select>
        <div className="relative">
          <HeroIcons.MagnifyingGlassIcon className="w-4 h-4 text-slate-400 absolute left-2 top-1/2 -translate-y-1/2" />
          <input
            type="text"
            placeholder="Search employee / label / description…"
            value={filter.search}
            onChange={(e) => setFilter({ ...filter, search: e.target.value })}
            className="text-sm border border-slate-300 rounded-md pl-7 pr-2 py-1.5 w-64"
          />
        </div>

        <div className="ml-auto flex items-center gap-2">
          {canEdit && selectedIds.size > 0 && (
            <button
              type="button"
              onClick={handleBulkCancel}
              className="inline-flex items-center gap-1 text-xs px-2.5 py-1.5 rounded-md border border-rose-300 bg-rose-50 text-rose-700 hover:bg-rose-100"
            >
              <HeroIcons.NoSymbolIcon className="w-4 h-4" />
              Cancel {selectedIds.size} selected
            </button>
          )}
          <button
            type="button"
            onClick={load}
            className="inline-flex items-center gap-1 text-xs px-2.5 py-1.5 rounded-md border border-slate-300 hover:bg-slate-50"
            title="Refresh"
          >
            <HeroIcons.ArrowPathIcon className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
            Refresh
          </button>
          {canEdit && (
            <button
              type="button"
              onClick={openCreate}
              className="inline-flex items-center gap-1 text-xs px-3 py-1.5 rounded-md bg-indigo-600 text-white hover:bg-indigo-700"
            >
              <HeroIcons.PlusIcon className="w-4 h-4" />
              New Adjustment
            </button>
          )}
        </div>
      </div>

      {error && (
        <div className="bg-red-50 border border-red-200 rounded-md px-3 py-2 text-xs text-red-700">{error}</div>
      )}

      {/* Table */}
      <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
        {loading ? (
          <div className="p-8 text-center text-sm text-slate-400">Loading…</div>
        ) : visible.length === 0 ? (
          <div className="p-8 text-center text-sm text-slate-400">
            No adjustments for {MONTH_NAMES[filter.month]} {filter.year}.
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="min-w-full text-xs">
              <thead className="bg-slate-50 text-slate-500 uppercase">
                <tr>
                  {canEdit && (
                    <th className="px-3 py-2 w-8">
                      <input
                        type="checkbox"
                        checked={allSelected}
                        onChange={toggleSelectAll}
                        disabled={selectableIds.length === 0}
                      />
                    </th>
                  )}
                  {ADJUSTMENT_COLUMNS.map((c) => (
                    <th
                      key={c.key}
                      style={{ width: c.width }}
                      className={`px-3 py-2 font-medium ${c.align === 'right' ? 'text-right' : 'text-left'}`}
                    >
                      {c.label}
                    </th>
                  ))}
                  {canEdit && (
                    <th className="px-3 py-2 text-right font-medium">Actions</th>
                  )}
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {visible.map((a) => {
                  const editable = isEditable(a)
                  const busy = busyIds.has(a.id)
                  const kindMeta = ADJUSTMENT_KIND_META[a.kind]
                  const statusMeta = ADJUSTMENT_STATUS_META[a.status]
                  return (
                    <tr key={a.id} className={`hover:bg-slate-50 ${selectedIds.has(a.id) ? 'bg-indigo-50/40' : ''}`}>
                      {canEdit && (
                        <td className="px-3 py-2">
                          <input
                            type="checkbox"
                            checked={selectedIds.has(a.id)}
                            disabled={!editable}
                            onChange={() => toggleSelectOne(a.id)}
                            title={editable ? '' : 'Only pending adjustments can be selected.'}
                          />
                        </td>
                      )}
                      <td className="px-3 py-2 text-slate-700">{a.employee_name}</td>
                      <td className="px-3 py-2 font-mono text-slate-500">{a.employee_no}</td>
                      <td className="px-3 py-2">
                        <span className={`inline-block px-2 py-0.5 text-[10px] rounded-full border ${kindMeta?.badge || ''}`}>
                          {kindMeta?.sign || ''} {kindMeta?.label || a.kind}
                        </span>
                      </td>
                      <td className="px-3 py-2 text-slate-700">{a.label}</td>
                      <td className="px-3 py-2 text-slate-500 max-w-md truncate" title={a.description}>{a.description}</td>
                      <td className="px-3 py-2 text-right tabular-nums font-medium">{fmtAmount(a.amount)}</td>
                      <td className="px-3 py-2">
                        <span className={`inline-block px-2 py-0.5 text-[10px] rounded-full border ${statusMeta?.badge || ''}`}>
                          {statusMeta?.label || a.status}
                        </span>
                      </td>
                      {canEdit && (
                        <td className="px-3 py-2 text-right whitespace-nowrap">
                          {editable ? (
                            <div className="inline-flex items-center gap-1">
                              <button
                                type="button"
                                onClick={() => openEdit(a)}
                                disabled={busy}
                                className="inline-flex items-center gap-1 text-[11px] px-2 py-1 rounded-md border border-slate-300 hover:bg-slate-100 disabled:opacity-50"
                                title="Edit adjustment"
                              >
                                <HeroIcons.PencilSquareIcon className="w-3.5 h-3.5" />
                                Edit
                              </button>
                              <button
                                type="button"
                                onClick={() => handleCancelOne(a)}
                                disabled={busy}
                                className="inline-flex items-center gap-1 text-[11px] px-2 py-1 rounded-md border border-amber-300 bg-amber-50 text-amber-700 hover:bg-amber-100 disabled:opacity-50"
                                title="Cancel adjustment"
                              >
                                <HeroIcons.NoSymbolIcon className="w-3.5 h-3.5" />
                                Cancel
                              </button>
                              <button
                                type="button"
                                onClick={() => handleDelete(a)}
                                disabled={busy}
                                className="inline-flex items-center gap-1 text-[11px] px-2 py-1 rounded-md border border-rose-300 text-rose-600 hover:bg-rose-50 disabled:opacity-50"
                                title="Delete adjustment"
                              >
                                <HeroIcons.TrashIcon className="w-3.5 h-3.5" />
                              </button>
                            </div>
                          ) : (
                            <span className="text-[11px] text-slate-400 italic">
                              {a.status === ADJUSTMENT_STATUS.APPLIED ? 'Locked (applied)' : 'Cancelled'}
                            </span>
                          )}
                        </td>
                      )}
                    </tr>
                  )
                })}
              </tbody>
              <tfoot className="bg-slate-50">
                <tr>
                  <td
                    colSpan={(canEdit ? 1 : 0) + ADJUSTMENT_COLUMNS.length - 2}
                    className="px-3 py-2 text-right text-[11px] font-medium text-slate-500 uppercase"
                  >
                    Showing {visible.length} of {items.length}
                  </td>
                  <td className="px-3 py-2 text-right tabular-nums font-semibold text-slate-700">
                    {fmtAmount(visible.reduce((s, a) => s + (Number(a.amount) || 0), 0))}
                  </td>
                  <td colSpan={(canEdit ? 2 : 1)} />
                </tr>
              </tfoot>
            </table>
          </div>
        )}
      </div>

      <AdjustmentModal
        open={modalOpen}
        adjustment={editing}
        onClose={() => { setModalOpen(false); setEditing(null) }}
        onSaved={handleSaved}
      />
    </div>
  )
}

import { radaiConfirm } from '../../../../services/radaiDialog'
import React, { useMemo, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService from '../../../../services/payrollEngine.service'
import {
  formatCurrency,
  BULK_DEDUCTION_FIELDS,
  BULK_DEDUCTION_DEFAULT_PCT,
  BULK_DEDUCTION_MIN_PCT,
  BULK_DEDUCTION_MAX_PCT,
  BULK_DEDUCTION_COMPONENT_CODE,
} from '../../../../config/payrollEngine.config'

const toNumber = (v) => {
  const n = Number(v)
  return Number.isFinite(n) ? n : 0
}

export default function BulkDeductionModal({ run, payslips = [], onClose, onApplied }) {
  const [percentage, setPercentage] = useState(String(BULK_DEDUCTION_DEFAULT_PCT))
  const [fields, setFields] = useState(
    () => Object.fromEntries(BULK_DEDUCTION_FIELDS.map((f) => [f.key, f.defaultChecked]))
  )
  const [label, setLabel] = useState('')
  const [description, setDescription] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState(null)
  const [success, setSuccess] = useState(null)

  const selectedKeys = useMemo(
    () => BULK_DEDUCTION_FIELDS.filter((f) => fields[f.key]).map((f) => f.key),
    [fields]
  )

  // Live client-side preview — sums the selected components across all
  // payslips, then applies the percentage. The server is the source of truth;
  // this is just so HR can sanity-check before clicking Apply.
  const preview = useMemo(() => {
    const pct = toNumber(percentage)
    let base = 0
    let affected = 0
    let skipped = 0
    payslips.forEach((slip) => {
      const slipBase = selectedKeys.reduce((sum, k) => sum + toNumber(slip[k]), 0)
      if (slipBase > 0) {
        base += slipBase
        affected += 1
      } else {
        skipped += 1
      }
    })
    const deduction = (base * pct) / 100
    return { base, deduction, affected, skipped, pct }
  }, [payslips, selectedKeys, percentage])

  const existingBulkLines = useMemo(() => {
    let count = 0
    payslips.forEach((slip) => {
      (slip.line_items || []).forEach((li) => {
        if (li.component_code === BULK_DEDUCTION_COMPONENT_CODE) count += 1
      })
    })
    return count
  }, [payslips])

  const pctNumber = toNumber(percentage)
  const pctValid =
    pctNumber >= BULK_DEDUCTION_MIN_PCT && pctNumber <= BULK_DEDUCTION_MAX_PCT
  const fieldsValid = selectedKeys.length > 0
  const canApply = pctValid && fieldsValid && !busy

  const handleApply = async () => {
    setBusy(true); setError(null); setSuccess(null)
    try {
      const payload = {
        percentage: percentage,
        fields: selectedKeys,
        replace_existing: true,
      }
      if (label.trim()) payload.label = label.trim()
      if (description.trim()) payload.description = description.trim()
      const result = await payrollEngineService.applyBulkDeduction(run.id, payload)
      // Refresh the parent BEFORE closing so the table reliably reflects the
      // new DEDUCTIONS / NET PAYABLE values (avoids a render-race where the
      // modal unmounts before payslips state updates).
      await onApplied?.(result)
      setSuccess(result?.summary || null)
      // Brief pause so HR sees the confirmation before the modal disappears.
      setTimeout(() => { onClose?.() }, 1200)
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally { setBusy(false) }
  }

  const handleReverse = async () => {
    if (!(await radaiConfirm('Remove ALL bulk percentage-deduction line items from this run?'))) return
    setBusy(true); setError(null); setSuccess(null)
    try {
      const result = await payrollEngineService.reverseBulkDeduction(run.id)
      await onApplied?.(result)
      onClose?.()
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally { setBusy(false) }
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 p-4">
      <div className="w-full max-w-3xl rounded-2xl bg-white shadow-2xl">
        {/* Header */}
        <div className="flex items-start justify-between border-b border-slate-200 px-6 py-4">
          <div className="flex items-start gap-3">
            <div className="rounded-lg bg-violet-100 p-2">
              <HeroIcons.ReceiptPercentIcon className="h-6 w-6 text-violet-700" />
            </div>
            <div>
              <h2 className="text-lg font-semibold text-slate-900">
                Bulk Salary Deduction
              </h2>
              <p className="text-sm text-slate-500">
                Apply a percentage deduction across every payslip in{' '}
                <span className="font-medium text-slate-700">{run.cycle_code}</span>.
                Basic salary is protected and never reduced.
              </p>
            </div>
          </div>
          <button
            onClick={onClose}
            className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100 hover:text-slate-700"
          >
            <HeroIcons.XMarkIcon className="h-5 w-5" />
          </button>
        </div>

        <div className="space-y-5 px-6 py-5">
          {/* Percentage input */}
          <div>
            <label className="mb-1 block text-sm font-medium text-slate-700">
              Deduction Percentage
            </label>
            <div className="flex items-center gap-3">
              <div className="relative w-44">
                <input
                  type="number"
                  step="0.01"
                  min={BULK_DEDUCTION_MIN_PCT}
                  max={BULK_DEDUCTION_MAX_PCT}
                  value={percentage}
                  onChange={(e) => setPercentage(e.target.value)}
                  disabled={busy}
                  className={`w-full rounded-lg border px-3 py-2 pr-9 text-right text-base font-semibold tabular-nums focus:outline-none focus:ring-2 ${
                    pctValid
                      ? 'border-slate-300 focus:border-violet-500 focus:ring-violet-200'
                      : 'border-red-300 focus:border-red-500 focus:ring-red-200'
                  }`}
                />
                <span className="pointer-events-none absolute inset-y-0 right-3 flex items-center text-slate-500">
                  %
                </span>
              </div>
              <div className="flex gap-1">
                {[2.5, 5, 10, 15, 20].map((preset) => (
                  <button
                    key={preset}
                    type="button"
                    onClick={() => setPercentage(String(preset))}
                    disabled={busy}
                    className="rounded-md border border-slate-200 bg-slate-50 px-2 py-1 text-xs font-medium text-slate-600 hover:bg-violet-50 hover:text-violet-700"
                  >
                    {preset}%
                  </button>
                ))}
              </div>
            </div>
            {!pctValid && (
              <p className="mt-1 text-xs text-red-600">
                Enter a value between {BULK_DEDUCTION_MIN_PCT}% and {BULK_DEDUCTION_MAX_PCT}%.
              </p>
            )}
          </div>

          {/* Fields */}
          <div>
            <label className="mb-2 block text-sm font-medium text-slate-700">
              Deduct From
            </label>
            <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
              {BULK_DEDUCTION_FIELDS.map((f) => (
                <label
                  key={f.key}
                  className={`flex cursor-pointer items-center gap-2 rounded-lg border px-3 py-2 text-sm transition ${
                    fields[f.key]
                      ? 'border-violet-300 bg-violet-50 text-violet-900'
                      : 'border-slate-200 bg-white text-slate-600 hover:bg-slate-50'
                  }`}
                >
                  <input
                    type="checkbox"
                    checked={!!fields[f.key]}
                    onChange={(e) => setFields((prev) => ({ ...prev, [f.key]: e.target.checked }))}
                    disabled={busy}
                    className="h-4 w-4 rounded border-slate-300 text-violet-600 focus:ring-violet-500"
                  />
                  {f.label}
                </label>
              ))}
            </div>
            <div className="mt-2 flex items-center gap-1.5 rounded-md bg-amber-50 px-3 py-2 text-xs text-amber-800">
              <HeroIcons.LockClosedIcon className="h-4 w-4 flex-shrink-0" />
              <span><strong>Basic</strong> is protected and never deducted.</span>
            </div>
            {!fieldsValid && (
              <p className="mt-1 text-xs text-red-600">Select at least one field.</p>
            )}
          </div>

          {/* Optional label + description */}
          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700">
                Custom Label <span className="font-normal text-slate-400">(optional)</span>
              </label>
              <input
                type="text"
                value={label}
                onChange={(e) => setLabel(e.target.value)}
                disabled={busy}
                placeholder={`Bulk Salary Deduction (${pctNumber}%)`}
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:border-violet-500 focus:outline-none focus:ring-2 focus:ring-violet-200"
              />
            </div>
            <div>
              <label className="mb-1 block text-sm font-medium text-slate-700">
                Description <span className="font-normal text-slate-400">(optional)</span>
              </label>
              <input
                type="text"
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                disabled={busy}
                placeholder="e.g. Ramadan adjustment"
                className="w-full rounded-lg border border-slate-300 px-3 py-2 text-sm focus:border-violet-500 focus:outline-none focus:ring-2 focus:ring-violet-200"
              />
            </div>
          </div>

          {/* Live preview */}
          <div className="rounded-xl border border-violet-200 bg-gradient-to-br from-violet-50 to-white p-4">
            <div className="mb-3 flex items-center gap-2 text-sm font-semibold text-violet-900">
              <HeroIcons.CalculatorIcon className="h-4 w-4" />
              Live Preview
            </div>
            <div className="grid grid-cols-2 gap-x-4 gap-y-2 text-sm sm:grid-cols-4">
              <div>
                <div className="text-xs uppercase tracking-wide text-slate-500">Affected</div>
                <div className="font-semibold text-slate-900">{preview.affected}</div>
              </div>
              <div>
                <div className="text-xs uppercase tracking-wide text-slate-500">Skipped (zero base)</div>
                <div className="font-semibold text-slate-900">{preview.skipped}</div>
              </div>
              <div>
                <div className="text-xs uppercase tracking-wide text-slate-500">Combined Base</div>
                <div className="font-semibold text-slate-900 tabular-nums">
                  {formatCurrency(preview.base)}
                </div>
              </div>
              <div>
                <div className="text-xs uppercase tracking-wide text-violet-700">Total Deduction</div>
                <div className="text-lg font-bold text-violet-700 tabular-nums">
                  − {formatCurrency(preview.deduction)}
                </div>
              </div>
            </div>
          </div>

          {existingBulkLines > 0 && (
            <div className="flex items-start gap-2 rounded-lg border border-blue-200 bg-blue-50 px-3 py-2 text-xs text-blue-900">
              <HeroIcons.InformationCircleIcon className="h-4 w-4 flex-shrink-0" />
              <span>
                This run already has <strong>{existingBulkLines}</strong> previous bulk-deduction
                line item(s). Applying a new deduction will <strong>replace</strong> them.
              </span>
            </div>
          )}

          {error && (
            <div className="flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-800">
              <HeroIcons.ExclamationTriangleIcon className="h-4 w-4 flex-shrink-0" />
              <span>{error}</span>
            </div>
          )}

          {success && (
            <div className="flex items-start gap-2 rounded-lg border border-emerald-200 bg-emerald-50 px-3 py-2 text-sm text-emerald-900">
              <HeroIcons.CheckCircleIcon className="h-4 w-4 flex-shrink-0 text-emerald-600" />
              <span>
                Applied <strong>{success.percentage}%</strong> deduction to{' '}
                <strong>{success.employees_affected}</strong> payslip(s){' '}
                ({success.employees_skipped} skipped). Total deducted:{' '}
                <strong className="tabular-nums">{formatCurrency(success.total_deducted)}</strong>.
              </span>
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="flex items-center justify-between border-t border-slate-200 bg-slate-50 px-6 py-4">
          <button
            type="button"
            onClick={handleReverse}
            disabled={busy || existingBulkLines === 0}
            className="inline-flex items-center gap-1.5 rounded-lg border border-red-300 bg-white px-3 py-2 text-sm font-medium text-red-700 hover:bg-red-50 disabled:cursor-not-allowed disabled:opacity-50"
          >
            <HeroIcons.ArrowUturnLeftIcon className="h-4 w-4" />
            Reverse All Bulk Deductions
          </button>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={onClose}
              disabled={busy}
              className="rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-medium text-slate-700 hover:bg-slate-100"
            >
              Cancel
            </button>
            <button
              type="button"
              onClick={handleApply}
              disabled={!canApply}
              className="inline-flex items-center gap-1.5 rounded-lg bg-violet-600 px-4 py-2 text-sm font-semibold text-white shadow-sm hover:bg-violet-700 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {busy ? (
                <HeroIcons.ArrowPathIcon className="h-4 w-4 animate-spin" />
              ) : (
                <HeroIcons.ReceiptPercentIcon className="h-4 w-4" />
              )}
              Apply {pctNumber}% Deduction
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

import React, { useEffect, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService from '../../../../services/payrollEngine.service'
import {
  formatCurrency,
  CHANGE_LOG_ACTION_META,
  CHANGE_LOG_FIELD_LABELS,
} from '../../../../config/payrollEngine.config'

/**
 * ChangeHistoryModal — Display complete audit trail of line item changes
 * 
 * Shows chronological history of all creates/updates/deletes for OTHER EARNINGS
 * and DEDUCTIONS on a specific payslip.
 * 
 * Soft-coded: Uses CHANGE_LOG_ACTION_META and CHANGE_LOG_FIELD_LABELS for
 * extensibility without code changes.
 */
export default function ChangeHistoryModal({ payslipId, employeeName, onClose }) {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [filter, setFilter] = useState('all') // 'all' | 'created' | 'updated' | 'deleted'

  useEffect(() => {
    loadHistory()
  }, [payslipId])

  const loadHistory = async () => {
    setLoading(true)
    setError(null)
    try {
      const result = await payrollEngineService.getPayslipChangeHistory(payslipId)
      setData(result)
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setLoading(false)
    }
  }

  const filteredChanges = data?.changes?.filter(
    (ch) => filter === 'all' || ch.action === filter
  ) || []

  const formatDateTime = (iso) => {
    if (!iso) return '—'
    try {
      return new Date(iso).toLocaleString('en-AE', {
        year: 'numeric',
        month: 'short',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
      })
    } catch {
      return iso
    }
  }

  const renderFieldChange = (field, oldVal, newVal) => {
    const label = CHANGE_LOG_FIELD_LABELS[field] || field
    
    // Format amount as currency
    if (field === 'amount') {
      return (
        <div key={field} className="text-xs">
          <span className="font-medium text-slate-600">{label}:</span>{' '}
          {oldVal && <span className="text-rose-600 line-through">{formatCurrency(oldVal)}</span>}
          {oldVal && newVal && ' → '}
          {newVal && <span className="text-emerald-600 font-semibold">{formatCurrency(newVal)}</span>}
        </div>
      )
    }

    // Standard text field
    if (oldVal !== newVal) {
      return (
        <div key={field} className="text-xs">
          <span className="font-medium text-slate-600">{label}:</span>{' '}
          {oldVal && <span className="text-slate-400 line-through">{oldVal}</span>}
          {oldVal && newVal && ' → '}
          {newVal && <span className="font-semibold">{newVal}</span>}
        </div>
      )
    }

    return null
  }

  const renderChange = (change) => {
    const meta = CHANGE_LOG_ACTION_META[change.action] || {}
    const Icon = HeroIcons[meta.icon] || HeroIcons.InformationCircleIcon

    // Determine which fields changed
    const fields = [...new Set([
      ...Object.keys(change.old_values || {}),
      ...Object.keys(change.new_values || {})
    ])]

    return (
      <div
        key={change.id}
        className="border border-slate-200 rounded-lg p-4 bg-white hover:shadow-sm transition-shadow"
      >
        {/* Header: Action + Time + Actor */}
        <div className="flex items-start justify-between mb-3">
          <div className="flex items-center gap-2">
            <div className={`p-1.5 rounded-lg ${meta.badge || 'bg-slate-50'}`}>
              <Icon className={`w-4 h-4 ${meta.color || 'text-slate-500'}`} />
            </div>
            <div>
              <div className="flex items-center gap-2">
                <span className="text-sm font-semibold text-slate-800">
                  {meta.label || change.action}
                </span>
                <span
                  className={`text-[10px] px-2 py-0.5 rounded-full border font-medium ${meta.badge || 'bg-slate-50 text-slate-600 border-slate-300'}`}
                >
                  {change.action_label}
                </span>
              </div>
              <div className="text-xs text-slate-500 mt-0.5">
                {formatDateTime(change.at)}
              </div>
            </div>
          </div>
          <div className="text-right">
            <div className="text-xs font-medium text-slate-700">{change.actor_name || 'System'}</div>
            {change.actor_email && (
              <div className="text-[10px] text-slate-400">{change.actor_email}</div>
            )}
          </div>
        </div>

        {/* Body: Field changes */}
        <div className="space-y-1 pl-9">
          {change.action === 'created' && (
            <div className="space-y-1">
              <div className="text-xs">
                <span className="font-medium text-slate-600">Type:</span>{' '}
                <span className="font-semibold capitalize">{change.new_values.kind}</span>
              </div>
              <div className="text-xs">
                <span className="font-medium text-slate-600">Label:</span>{' '}
                <span className="font-semibold">{change.new_values.label}</span>
              </div>
              <div className="text-xs">
                <span className="font-medium text-slate-600">Amount:</span>{' '}
                <span className="font-semibold text-emerald-600">
                  {formatCurrency(change.new_values.amount)}
                </span>
              </div>
              {change.new_values.description && (
                <div className="text-xs">
                  <span className="font-medium text-slate-600">Description:</span>{' '}
                  {change.new_values.description}
                </div>
              )}
            </div>
          )}

          {change.action === 'updated' && (
            <div className="space-y-1">
              {fields.map((field) =>
                renderFieldChange(
                  field,
                  change.old_values?.[field],
                  change.new_values?.[field]
                )
              )}
            </div>
          )}

          {change.action === 'deleted' && (
            <div className="space-y-1 opacity-75">
              <div className="text-xs">
                <span className="font-medium text-slate-600">Type:</span>{' '}
                <span className="line-through capitalize">{change.old_values.kind}</span>
              </div>
              <div className="text-xs">
                <span className="font-medium text-slate-600">Label:</span>{' '}
                <span className="line-through">{change.old_values.label}</span>
              </div>
              <div className="text-xs">
                <span className="font-medium text-slate-600">Amount:</span>{' '}
                <span className="line-through text-rose-600">
                  {formatCurrency(change.old_values.amount)}
                </span>
              </div>
            </div>
          )}

          {change.note && (
            <div className="mt-2 text-xs text-slate-500 italic border-l-2 border-slate-200 pl-2">
              {change.note}
            </div>
          )}
        </div>
      </div>
    )
  }

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4 overflow-y-auto">
      <div className="bg-white rounded-2xl shadow-xl max-w-4xl w-full my-8">
        {/* Header */}
        <div className="p-5 border-b border-slate-200 flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold text-slate-800 flex items-center gap-2">
              <HeroIcons.ClockIcon className="w-5 h-5 text-blue-600" />
              Change History
            </h3>
            <p className="text-xs text-slate-500 mt-0.5">
              {employeeName || 'Employee'} · Run: {data?.run_cycle || '—'}
            </p>
          </div>
          <button
            onClick={onClose}
            className="p-1.5 hover:bg-slate-100 rounded-md"
          >
            <HeroIcons.XMarkIcon className="w-5 h-5 text-slate-500" />
          </button>
        </div>

        {/* Filters */}
        <div className="px-5 py-3 border-b border-slate-200 bg-slate-50">
          <div className="flex items-center gap-2">
            <span className="text-xs font-medium text-slate-600">Filter:</span>
            {['all', 'created', 'updated', 'deleted'].map((f) => {
              const meta = f === 'all' ? null : CHANGE_LOG_ACTION_META[f]
              const count =
                f === 'all'
                  ? data?.total_changes || 0
                  : data?.changes?.filter((ch) => ch.action === f).length || 0

              return (
                <button
                  key={f}
                  onClick={() => setFilter(f)}
                  className={`inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md border transition-all ${
                    filter === f
                      ? meta?.badge || 'bg-blue-50 text-blue-700 border-blue-300'
                      : 'bg-white text-slate-600 border-slate-300 hover:bg-slate-50'
                  }`}
                >
                  {f === 'all' ? 'All' : meta?.label || f}
                  <span className="text-[10px] px-1.5 py-0.5 rounded-full bg-white/50 font-semibold">
                    {count}
                  </span>
                </button>
              )
            })}
          </div>
        </div>

        {/* Content */}
        <div className="p-5 max-h-[60vh] overflow-y-auto">
          {loading && (
            <div className="flex items-center justify-center py-12">
              <div className="flex items-center gap-2 text-sm text-slate-500">
                <HeroIcons.ArrowPathIcon className="w-4 h-4 animate-spin" />
                Loading change history...
              </div>
            </div>
          )}

          {error && (
            <div className="text-sm text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2">
              {error}
            </div>
          )}

          {!loading && !error && filteredChanges.length === 0 && (
            <div className="text-center py-12">
              <HeroIcons.DocumentTextIcon className="w-12 h-12 text-slate-300 mx-auto mb-3" />
              <p className="text-sm font-medium text-slate-600">No changes found</p>
              <p className="text-xs text-slate-400 mt-1">
                {filter === 'all'
                  ? 'No line item changes recorded for this payslip yet.'
                  : `No ${filter} actions found.`}
              </p>
            </div>
          )}

          {!loading && !error && filteredChanges.length > 0 && (
            <div className="space-y-3">
              {filteredChanges.map(renderChange)}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-5 py-3 border-t border-slate-200 bg-slate-50 flex items-center justify-between rounded-b-2xl">
          <div className="text-xs text-slate-500">
            {filteredChanges.length > 0 && (
              <span>
                Showing <strong>{filteredChanges.length}</strong> of{' '}
                <strong>{data?.total_changes || 0}</strong> changes
              </span>
            )}
          </div>
          <button
            onClick={onClose}
            className="px-3 py-1.5 text-sm font-medium rounded-md border border-slate-300 hover:bg-slate-100"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  )
}

/**
 * ConsolidatedView — cross-source heatmap.
 *
 * When the run has 2+ comparisons (e.g. ValueFrame + Sympa), this view
 * pivots all of them into a single grid:
 *
 *   Employee | Source A: field1 field2 … | Source B: field1 field2 … | …
 *
 * Each cell shows the EXTERNAL value, colour-coded by variance severity
 * vs our payroll. "—" means that field wasn't in that file.
 *
 * Props:
 *   comparisons: array of comparison DETAIL objects (with .rows[])
 */
import React, { useMemo } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'

import {
  COMPARISON_SEVERITY_META,
  comparisonFieldMeta, formatComparisonValue,
} from '../../../../config/payrollEngine.config'

export default function ComparisonConsolidatedView({ comparisons }) {
  // Each comparison contributes (sourceLabel, profile, detectedFields, rowsByEmp)
  const sources = useMemo(() => (comparisons || []).map((cmp) => {
    const detected = (cmp.summary?.fields_detected || [])
      .filter((f) => f !== 'employee_no' && f !== 'full_name')
    const byEmp = {}
    for (const row of (cmp.rows || [])) {
      const key = row.payroll_employee_no || row.external_employee_no
      if (!key) continue
      byEmp[key] = row
    }
    return {
      id: cmp.id,
      label: cmp.source_label,
      profile: cmp.source_profile,
      detectedFields: detected,
      byEmp,
    }
  }), [comparisons])

  // Union of all employee keys + display names
  const employees = useMemo(() => {
    const map = new Map()
    for (const src of sources) {
      for (const [key, row] of Object.entries(src.byEmp)) {
        if (!map.has(key)) {
          map.set(key, {
            key,
            no:   row.payroll_employee_no || row.external_employee_no || key,
            name: row.payroll_employee_name || row.external_name || '—',
            // For "Our" column, prefer any source that has our_values populated
            ourValues: row.our_values || null,
            severityScore: 0,
          })
        }
        const meta = map.get(key)
        if (!meta.ourValues && row.our_values) meta.ourValues = row.our_values
        // Tally a rough severity score for sort
        for (const v of (row.variances || [])) {
          if (v.severity === 'critical')      meta.severityScore += 3
          else if (v.severity === 'warning')  meta.severityScore += 1
        }
      }
    }
    // Sort: highest severity first, then name
    return Array.from(map.values()).sort((a, b) => {
      if (b.severityScore !== a.severityScore) return b.severityScore - a.severityScore
      return (a.name || '').localeCompare(b.name || '')
    })
  }, [sources])

  if (!comparisons?.length) {
    return (
      <div className="bg-white border border-dashed border-slate-300 rounded-xl p-6 text-center text-sm text-slate-500">
        Upload at least two external files to see the consolidated cross-source view.
      </div>
    )
  }

  if (comparisons.length === 1) {
    return (
      <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 flex items-start gap-3">
        <HeroIcons.LightBulbIcon className="w-5 h-5 text-amber-600 mt-0.5 flex-shrink-0" />
        <div className="text-xs text-amber-800">
          The consolidated view is most useful when comparing <b>multiple sources</b> at once
          (e.g. ValueFrame for hours <i>and</i> Sympa for salaries). Upload a second file
          above to enable side-by-side reconciliation.
        </div>
      </div>
    )
  }

  return (
    <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
      <div className="px-4 py-2 border-b border-slate-200 flex items-center gap-2 bg-slate-50">
        <HeroIcons.TableCellsIcon className="w-4 h-4 text-indigo-600" />
        <h3 className="text-sm font-semibold text-slate-700">Cross-source matrix</h3>
        <span className="text-xs text-slate-500">
          · {employees.length} employees · {sources.length} sources
        </span>
        <div className="ml-auto flex items-center gap-3 text-[10px] text-slate-500">
          <LegendChip cls="bg-rose-50  border border-rose-200"  label="Critical" />
          <LegendChip cls="bg-amber-50 border border-amber-200" label="Warning" />
          <LegendChip cls="bg-sky-50   border border-sky-200"   label="Info" />
          <LegendChip cls="bg-emerald-50 border border-emerald-200" label="Match" />
        </div>
      </div>
      <div className="overflow-x-auto max-h-[60vh]">
        <table className="min-w-full text-[11px]">
          <thead className="bg-slate-50 text-slate-500 uppercase sticky top-0 z-10">
            <tr>
              <th rowSpan={2} className="px-3 py-2 text-left font-medium border-r border-slate-200">
                Employee
              </th>
              {sources.map((src) => (
                <th
                  key={src.id}
                  colSpan={Math.max(src.detectedFields.length, 1)}
                  className="px-3 py-2 text-center font-semibold border-l border-slate-200 text-indigo-700 bg-indigo-50/40"
                >
                  {src.label}
                </th>
              ))}
            </tr>
            <tr>
              {sources.map((src) => (
                src.detectedFields.length ? (
                  src.detectedFields.map((f) => (
                    <th
                      key={`${src.id}-${f}`}
                      className="px-2 py-1.5 text-right font-medium border-l border-slate-200 tabular-nums"
                    >
                      {comparisonFieldMeta(f).label}
                    </th>
                  ))
                ) : (
                  <th key={`${src.id}-empty`} className="px-2 py-1.5 border-l border-slate-200 text-slate-300">—</th>
                )
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {employees.map((emp) => (
              <tr key={emp.key} className="hover:bg-slate-50">
                <td className="px-3 py-1.5 border-r border-slate-200 align-top">
                  <div className="font-medium text-slate-800">{emp.name}</div>
                  <div className="text-[10px] text-slate-500">#{emp.no}</div>
                </td>
                {sources.map((src) => {
                  const row = src.byEmp[emp.key]
                  if (!row) {
                    return src.detectedFields.length
                      ? src.detectedFields.map((f) => (
                          <td key={`${src.id}-${f}-x`} className="px-2 py-1.5 border-l border-slate-200 text-center text-slate-300">
                            —
                          </td>
                        ))
                      : <td key={`${src.id}-empty-x`} className="px-2 py-1.5 border-l border-slate-200 text-slate-300">—</td>
                  }
                  const varMap = Object.fromEntries((row.variances || []).map((v) => [v.field, v]))
                  return src.detectedFields.map((f) => {
                    const v = varMap[f]
                    const extVal = row.external_values?.[f]
                    const display = formatComparisonValue(f, extVal)
                    let cellCls = ''
                    if (v) {
                      const sm = COMPARISON_SEVERITY_META[v.severity] || {}
                      cellCls = sm.cell || ''
                    } else if (extVal !== undefined && extVal !== null) {
                      cellCls = 'bg-emerald-50/60'
                    }
                    return (
                      <td
                        key={`${src.id}-${f}-${row.id}`}
                        className={`px-2 py-1.5 text-right tabular-nums border-l border-slate-200 ${cellCls}`}
                        title={v ? `Our: ${formatComparisonValue(f, v.our)} / Ext: ${formatComparisonValue(f, v.external)} / ${v.severity}` : `Ext: ${display}`}
                      >
                        {display}
                      </td>
                    )
                  })
                })}
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  )
}

function LegendChip({ cls, label }) {
  return (
    <span className="inline-flex items-center gap-1">
      <span className={`inline-block w-3 h-3 rounded ${cls}`} />
      {label}
    </span>
  )
}

/**
 * ComparisonDiffTable — per-row variance table with severity-coloured cells.
 * Pure presentation; consumes pre-loaded `rows` and the field list.
 */
import React from 'react'
import {
  COMPARISON_STATUS_META, COMPARISON_SEVERITY_META,
  comparisonFieldMeta, formatComparisonValue,
} from '../../../../config/payrollEngine.config'

const KIND_GLYPH = { money: '$', hours: 'h', days: 'd', identifier: '#' }

export default function ComparisonDiffTable({ rows, detectedFields, loading }) {
  if (loading) {
    return (
      <div className="bg-white border border-slate-200 rounded-xl p-6 text-center text-sm text-slate-500">
        Loading rows…
      </div>
    )
  }
  if (!rows.length) {
    return (
      <div className="bg-white border border-slate-200 rounded-xl p-6 text-center text-sm text-slate-500">
        No rows for the current filter.
      </div>
    )
  }
  return (
    <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
      <div className="overflow-x-auto">
        <table className="min-w-full text-xs">
          <thead className="bg-slate-50 text-slate-500 uppercase">
            <tr>
              <th className="px-3 py-2 text-left font-medium">Status</th>
              <th className="px-3 py-2 text-left font-medium">Employee</th>
              <th className="px-3 py-2 text-left font-medium">Match</th>
              {detectedFields.map((f) => {
                const meta = comparisonFieldMeta(f)
                return (
                  <th key={f} className="px-3 py-2 text-right font-medium tabular-nums">
                    <span className="text-slate-400 mr-1">
                      {KIND_GLYPH[meta.kind] || ''}
                    </span>
                    {meta.label}
                  </th>
                )
              })}
              <th className="px-3 py-2 text-left font-medium">Action</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {rows.map((row) => {
              const meta = COMPARISON_STATUS_META[row.status] || {}
              const varMap = Object.fromEntries((row.variances || []).map((v) => [v.field, v]))
              const recs = (row.variances || [])
                .filter((v) => v.recommendation)
                .map((v) => ({
                  field: comparisonFieldMeta(v.field).label,
                  text: v.recommendation,
                  sev: v.severity,
                }))
              return (
                <tr key={row.id} className={`hover:bg-slate-50 ${meta.rowFill || ''}`}>
                  <td className="px-3 py-2 align-top">
                    <span className={`inline-flex items-center px-1.5 py-0.5 rounded border text-[10px] font-medium ${meta.badge || ''}`}>
                      {meta.short || row.status}
                    </span>
                  </td>
                  <td className="px-3 py-2 align-top">
                    <div className="font-medium text-slate-800">
                      {row.payroll_employee_name || row.external_name || '—'}
                    </div>
                    <div className="text-[10px] text-slate-500">
                      {row.payroll_employee_no || row.external_employee_no || ''}
                    </div>
                  </td>
                  <td className="px-3 py-2 text-slate-500 text-[10px] align-top">
                    {row.matched_by || '—'}
                  </td>
                  {detectedFields.map((f) => {
                    const v = varMap[f]
                    const ourValue = formatComparisonValue(f, v?.our ?? null)
                    const extValue = formatComparisonValue(f, v?.external ?? null)
                    if (!v) {
                      return <td key={f} className="px-3 py-2 text-right text-slate-300 align-top">—</td>
                    }
                    const sev = COMPARISON_SEVERITY_META[v.severity] || {}
                    return (
                      <td
                        key={f}
                        className={`px-3 py-2 text-right tabular-nums align-top ${sev.cell || ''}`}
                        title={`Our: ${ourValue}\nExternal: ${extValue}\nDiff: ${v.diff ?? '—'} (${v.pct ?? 0}%)`}
                      >
                        <div className="text-slate-700">{ourValue}</div>
                        <div className="text-[10px] text-slate-500">ext {extValue}</div>
                      </td>
                    )
                  })}
                  <td className="px-3 py-2 text-slate-600 max-w-xs align-top">
                    {recs.length ? (
                      <ul className="space-y-0.5">
                        {recs.map((r, i) => {
                          const sm = COMPARISON_SEVERITY_META[r.sev] || {}
                          return (
                            <li key={i} className="flex items-start gap-1 text-[11px] leading-snug">
                              <span className={`inline-block w-1.5 h-1.5 rounded-full mt-1 flex-shrink-0 ${
                                r.sev === 'critical' ? 'bg-rose-500'
                                : r.sev === 'warning' ? 'bg-amber-500'
                                : 'bg-sky-400'
                              }`} />
                              <span><span className="font-medium">{r.field}:</span> {r.text}</span>
                            </li>
                          )
                        })}
                      </ul>
                    ) : <span className="text-slate-300">—</span>}
                  </td>
                </tr>
              )
            })}
          </tbody>
        </table>
      </div>
    </div>
  )
}

import { radaiConfirm } from '../../../../services/radaiDialog'
/**
 * ComparisonPanel — orchestrator for the Payroll Comparison feature.
 *
 *   1. Multi-file upload queue with per-file profile + status
 *   2. History strip listing every comparison run against the selected run
 *   3. Summary KPIs (matched / variance / external-only / payroll-only)
 *   4. Three view modes:
 *        - Diff Table        (current active comparison, with filters)
 *        - Recommendations   (plain-language action cards across all sources)
 *        - Consolidated      (cross-source matrix; needs 2+ uploads)
 *   5. XLSX download per comparison
 *
 * Used standalone in `ComparisonsHub` (global tab) and embedded inside
 * `RunDetail`. Soft-coded throughout via `payrollEngine.config.js`.
 */
import React, { useEffect, useMemo, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'

import payrollEngineService, { downloadBlob } from '../../../../services/payrollEngine.service'
import {
  COMPARISON_STATUS, COMPARISON_STATUS_META,
  COMPARISON_FIELDS, COMPARISON_PROFILE_FALLBACK,
  comparisonFieldMeta, formatNumber,
} from '../../../../config/payrollEngine.config'

import ComparisonDiffTable from './ComparisonDiffTable'
import ComparisonRecommendationsInbox from './ComparisonRecommendationsInbox'
import ComparisonConsolidatedView from './ComparisonConsolidatedView'

function formatDateTime(iso) {
  if (!iso) return '—'
  try {
    return new Date(iso).toLocaleString('en-AE', {
      year: 'numeric', month: 'short', day: '2-digit',
      hour: '2-digit', minute: '2-digit',
    })
  } catch { return iso }
}

const STATUS_TABS = [
  { key: '__all__',                          label: 'All' },
  { key: COMPARISON_STATUS.VARIANCE,         label: COMPARISON_STATUS_META[COMPARISON_STATUS.VARIANCE].label },
  { key: COMPARISON_STATUS.MATCH,            label: COMPARISON_STATUS_META[COMPARISON_STATUS.MATCH].label },
  { key: COMPARISON_STATUS.EXTERNAL_ONLY,    label: COMPARISON_STATUS_META[COMPARISON_STATUS.EXTERNAL_ONLY].label },
  { key: COMPARISON_STATUS.PAYROLL_ONLY,     label: COMPARISON_STATUS_META[COMPARISON_STATUS.PAYROLL_ONLY].label },
]

const VIEW_MODES = [
  { key: 'diff',         label: 'Diff Table',      icon: 'TableCellsIcon',
    hint: 'Row-by-row comparison for the selected upload' },
  { key: 'inbox',        label: 'Recommendations', icon: 'InboxStackIcon',
    hint: 'Plain-language actions grouped by severity & employee' },
  { key: 'consolidated', label: 'Consolidated',    icon: 'Squares2X2Icon',
    hint: 'Cross-source matrix — best with 2+ uploads' },
]

// Quick profile auto-detect from filename — pure UX hint, the backend
// still re-detects when source_profile='auto'.
function guessProfileFromFilename(name) {
  const n = (name || '').toLowerCase()
  if (n.includes('valueframe') || n.startsWith('vf'))     return 'valueframe'
  if (n.includes('sympa'))                                return 'sympa'
  return 'auto'
}

export default function ComparisonPanel({
  runId,
  runOptions = [],
  showRunPicker = false,
  defaultRunId = '',
}) {
  const [profiles, setProfiles] = useState(COMPARISON_PROFILE_FALLBACK)
  const [activeRunId, setActiveRunId] = useState(runId || defaultRunId || '')

  // History = all comparisons for the current run (summary cards)
  const [history, setHistory] = useState([])
  // Detailed comparisons (with rows) for inbox + consolidated view.
  // Keyed by comparison id.
  const [details, setDetails] = useState({})
  const [activeId, setActiveId] = useState(null)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)

  // Upload queue: each entry = { id, file, profile, label, status, progress, error }
  const [queue, setQueue] = useState([])
  const [uploading, setUploading] = useState(false)

  // View mode
  const [viewMode, setViewMode] = useState('diff')

  // Diff-mode filters
  const [statusFilter, setStatusFilter] = useState('__all__')
  const [search, setSearch] = useState('')
  const [filteredRows, setFilteredRows] = useState([])
  const [rowsLoading, setRowsLoading] = useState(false)

  // ── Effect: keep activeRunId in sync when parent prop changes
  useEffect(() => {
    if (runId && runId !== activeRunId) setActiveRunId(runId)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [runId])

  // ── Effect: load profile list once
  useEffect(() => {
    payrollEngineService.getComparisonProfiles()
      .then((data) => { if (Array.isArray(data) && data.length) setProfiles(data) })
      .catch(() => { /* keep fallback */ })
  }, [])

  // ── Effect: when active run changes, reload history + clear details
  useEffect(() => {
    if (!activeRunId) {
      setHistory([]); setDetails({}); setActiveId(null); setFilteredRows([])
      return
    }
    refreshHistoryAndDetails()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeRunId])

  // ── Effect: when filters / active comparison change, reload filtered rows
  useEffect(() => {
    if (!activeId) { setFilteredRows([]); return }
    reloadFilteredRows(activeId)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [activeId, statusFilter, search])

  const refreshHistoryAndDetails = async () => {
    setLoading(true); setError(null)
    try {
      const data = await payrollEngineService.listComparisons({ run: activeRunId })
      const list = Array.isArray(data) ? data : (data?.results ?? [])
      setHistory(list)
      if (!list.length) {
        setDetails({}); setActiveId(null); setFilteredRows([])
        return
      }
      const detailObjs = await Promise.all(
        list.map((c) => payrollEngineService.getComparison(c.id))
      )
      const map = {}
      for (const d of detailObjs) map[d.id] = d
      setDetails(map)
      setActiveId((cur) => (cur && map[cur]) ? cur : list[0].id)
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setLoading(false)
    }
  }

  const reloadFilteredRows = async (id) => {
    setRowsLoading(true)
    const params = {}
    if (statusFilter !== '__all__') params.status = statusFilter
    if (search.trim()) params.search = search.trim()
    try {
      const data = await payrollEngineService.listComparisonRows(id, params)
      const list = Array.isArray(data) ? data : (data?.results ?? [])
      setFilteredRows(list)
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setRowsLoading(false)
    }
  }

  // ── Upload queue ──────────────────────────────────────────────────
  const handleFilesPicked = (filesList) => {
    const files = Array.from(filesList || [])
    if (!files.length) return
    setQueue((q) => [
      ...q,
      ...files.map((f, i) => ({
        id: `${Date.now()}-${i}-${f.name}`,
        file: f,
        profile: guessProfileFromFilename(f.name),
        label: '',
        status: 'pending',     // pending | uploading | done | error
        error: null,
      })),
    ])
    // Reset the input so re-picking the same file works
    const input = document.getElementById('comparison-file-input')
    if (input) input.value = ''
  }

  const updateQueueEntry = (id, patch) =>
    setQueue((q) => q.map((e) => (e.id === id ? { ...e, ...patch } : e)))

  const removeQueueEntry = (id) =>
    setQueue((q) => q.filter((e) => e.id !== id))

  const runQueue = async () => {
    if (!activeRunId) { setError('Pick a payroll run first.'); return }
    const pending = queue.filter((q) => q.status === 'pending' || q.status === 'error')
    if (!pending.length) return
    setUploading(true); setError(null)
    for (const entry of pending) {
      updateQueueEntry(entry.id, { status: 'uploading', error: null })
      try {
        const detail = await payrollEngineService.uploadComparison({
          runId: activeRunId,
          file: entry.file,
          sourceLabel: entry.label,
          sourceProfile: entry.profile,
        })
        updateQueueEntry(entry.id, { status: 'done', resultId: detail.id })
      } catch (e) {
        updateQueueEntry(entry.id, {
          status: 'error',
          error: e?.response?.data?.error || e.message,
        })
      }
    }
    setUploading(false)
    await refreshHistoryAndDetails()
    // Clear successfully-uploaded entries
    setQueue((q) => q.filter((e) => e.status !== 'done'))
  }

  const clearQueue = () => setQueue([])

  // ── Per-comparison actions ────────────────────────────────────────
  const handleDelete = async (id) => {
    if (!(await radaiConfirm('Delete this comparison report?'))) return
    try {
      await payrollEngineService.deleteComparison(id)
      await refreshHistoryAndDetails()
      if (activeId === id) setActiveId(null)
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    }
  }

  const handleDownloadXlsx = async (id) => {
    const cmp = history.find((c) => c.id === id)
    if (!cmp) return
    try {
      const blob = await payrollEngineService.downloadComparisonXlsx(id)
      downloadBlob(blob, `comparison_${cmp.run_cycle_code}_${cmp.source_profile}_${id}.xlsx`)
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    }
  }

  // ── Derived ───────────────────────────────────────────────────────
  const activeDetail = activeId ? details[activeId] : null
  const detectedFields = useMemo(() => {
    const fields = activeDetail?.summary?.fields_detected || []
    return fields.filter((f) => f !== 'employee_no' && f !== 'full_name')
  }, [activeDetail])

  const allDetails = useMemo(() => Object.values(details), [details])

  const aggregateKpis = useMemo(() => {
    const agg = { matched: 0, variance: 0, external_only: 0, payroll_only: 0 }
    for (const d of allDetails) {
      const s = d.summary || {}
      agg.matched       += s.matched || 0
      agg.variance      += s.variance || 0
      agg.external_only += s.external_only || 0
      agg.payroll_only  += s.payroll_only || 0
    }
    return agg
  }, [allDetails])

  const hasMultiple = allDetails.length >= 2

  return (
    <div className="space-y-4">
      {/* ── Upload card ──────────────────────────────────────────── */}
      <div className="bg-white border border-slate-200 rounded-xl p-4">
        <div className="flex items-start justify-between flex-wrap gap-3">
          <div>
            <h3 className="text-sm font-semibold text-slate-700 flex items-center gap-2">
              <HeroIcons.ArrowsRightLeftIcon className="w-4 h-4 text-indigo-600" />
              Upload external file(s)
            </h3>
            <p className="text-xs text-slate-500 mt-1">
              Drop or pick <b>one or many</b> ValueFrame / Sympa / generic XLSX files.
              Each file becomes its own comparison; uploading two or more enables
              the Consolidated cross-source view.
            </p>
          </div>
        </div>

        {/* Run picker + file picker */}
        <div className="grid grid-cols-1 md:grid-cols-12 gap-3 mt-4">
          {showRunPicker && (
            <div className="md:col-span-4">
              <label className="block text-[11px] uppercase font-medium text-slate-500 mb-1">
                Payroll run
              </label>
              <select
                value={activeRunId}
                onChange={(e) => setActiveRunId(e.target.value)}
                className="w-full text-xs border border-slate-300 rounded-md px-2 py-2 bg-white"
              >
                <option value="">— select —</option>
                {runOptions.map((r) => (
                  <option key={r.id} value={r.id}>
                    {r.cycle_code} {r.status_label ? `(${r.status_label})` : ''}
                  </option>
                ))}
              </select>
            </div>
          )}
          <div className={showRunPicker ? 'md:col-span-8' : 'md:col-span-12'}>
            <label className="block text-[11px] uppercase font-medium text-slate-500 mb-1">
              Add file(s)
            </label>
            <div className="flex items-center gap-2">
              <label
                htmlFor="comparison-file-input"
                className="inline-flex items-center gap-1.5 px-3 py-2 text-xs font-medium rounded-md border border-indigo-300 bg-indigo-50 text-indigo-700 hover:bg-indigo-100 cursor-pointer"
              >
                <HeroIcons.DocumentPlusIcon className="w-4 h-4" />
                Pick files
              </label>
              <input
                id="comparison-file-input"
                type="file"
                multiple
                accept=".xlsx,.xls,.csv"
                onChange={(e) => handleFilesPicked(e.target.files)}
                className="hidden"
              />
              <span className="text-xs text-slate-500">
                {queue.length
                  ? `${queue.length} file${queue.length === 1 ? '' : 's'} queued`
                  : 'No files queued yet'}
              </span>
              <div className="ml-auto flex items-center gap-2">
                {queue.length > 0 && (
                  <button
                    type="button"
                    onClick={clearQueue}
                    disabled={uploading}
                    className="text-xs text-slate-500 underline disabled:opacity-50"
                  >
                    Clear
                  </button>
                )}
                <button
                  type="button"
                  onClick={runQueue}
                  disabled={uploading || !activeRunId || queue.every((q) => q.status === 'done')}
                  className="inline-flex items-center gap-1.5 px-3 py-2 text-xs font-medium rounded-md bg-indigo-600 text-white hover:bg-indigo-700 disabled:opacity-50"
                >
                  {uploading
                    ? <HeroIcons.ArrowPathIcon className="w-4 h-4 animate-spin" />
                    : <HeroIcons.ArrowUpTrayIcon className="w-4 h-4" />}
                  {uploading ? 'Comparing…' : `Run comparison${queue.length > 1 ? 's' : ''}`}
                </button>
              </div>
            </div>
          </div>
        </div>

        {/* Per-file queue */}
        {queue.length > 0 && (
          <div className="mt-3 border border-slate-200 rounded-md divide-y divide-slate-100">
            {queue.map((q) => (
              <QueueRow
                key={q.id}
                entry={q}
                profiles={profiles}
                onChange={(patch) => updateQueueEntry(q.id, patch)}
                onRemove={() => removeQueueEntry(q.id)}
                disabled={uploading}
              />
            ))}
          </div>
        )}

        {error && (
          <div className="mt-3 text-xs text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2">
            {error}
          </div>
        )}
      </div>

      {/* ── History strip ────────────────────────────────────────── */}
      {history.length > 0 && (
        <div className="bg-white border border-slate-200 rounded-xl p-3">
          <div className="text-[11px] uppercase font-medium text-slate-500 mb-2">
            Uploads for this run ({history.length})
          </div>
          <div className="flex flex-wrap gap-2">
            {history.map((h) => {
              const isActive = activeId === h.id
              const variances = h.summary?.variance || 0
              return (
                <div
                  key={h.id}
                  className={`flex items-center gap-2 px-2.5 py-1.5 text-xs rounded-md border ${
                    isActive
                      ? 'border-indigo-400 bg-indigo-50 text-indigo-700'
                      : 'border-slate-200 bg-slate-50 text-slate-700 hover:bg-white'
                  }`}
                >
                  <button
                    type="button"
                    onClick={() => setActiveId(h.id)}
                    className="flex items-center gap-1.5"
                  >
                    <HeroIcons.DocumentMagnifyingGlassIcon className="w-3.5 h-3.5" />
                    <span className="font-medium">{h.source_label || h.source_profile}</span>
                    <span className="text-slate-400">·</span>
                    <span className="text-slate-500">{formatDateTime(h.created_at)}</span>
                    {variances ? (
                      <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-amber-100 text-amber-700 border border-amber-200">
                        {variances} diff
                      </span>
                    ) : (
                      <span className="ml-1 px-1.5 py-0.5 rounded text-[10px] bg-emerald-100 text-emerald-700 border border-emerald-200">
                        clean
                      </span>
                    )}
                  </button>
                  <button
                    type="button"
                    onClick={() => handleDownloadXlsx(h.id)}
                    title="Download diff XLSX"
                    className="text-slate-400 hover:text-indigo-700"
                  >
                    <HeroIcons.ArrowDownTrayIcon className="w-3.5 h-3.5" />
                  </button>
                  <button
                    type="button"
                    onClick={() => handleDelete(h.id)}
                    title="Delete this comparison"
                    className="text-slate-400 hover:text-rose-600"
                  >
                    <HeroIcons.XMarkIcon className="w-3.5 h-3.5" />
                  </button>
                </div>
              )
            })}
          </div>
        </div>
      )}

      {/* ── Aggregate KPIs (across all sources) ─────────────────── */}
      {allDetails.length > 0 && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
          <KpiTile
            label={allDetails.length > 1 ? `Matched (all ${allDetails.length} sources)` : 'Matched'}
            value={formatNumber(aggregateKpis.matched, { decimals: 0 })}
            tone="emerald"
            icon="CheckCircleIcon"
          />
          <KpiTile
            label="Variances"
            value={formatNumber(aggregateKpis.variance, { decimals: 0 })}
            tone="amber"
            icon="ExclamationTriangleIcon"
          />
          <KpiTile
            label="External only"
            value={formatNumber(aggregateKpis.external_only, { decimals: 0 })}
            tone="sky"
            icon="UserPlusIcon"
          />
          <KpiTile
            label="Missing from external"
            value={formatNumber(aggregateKpis.payroll_only, { decimals: 0 })}
            tone="rose"
            icon="UserMinusIcon"
          />
        </div>
      )}

      {/* ── View-mode tabs + content ─────────────────────────────── */}
      {allDetails.length > 0 && (
        <div>
          <div className="bg-white border border-slate-200 rounded-xl px-2 pt-1.5 mb-3">
            <div className="flex gap-1 overflow-x-auto">
              {VIEW_MODES.map((m) => {
                const Icon = HeroIcons[m.icon] || HeroIcons.TableCellsIcon
                const isActive = viewMode === m.key
                const disabled = m.key === 'consolidated' && !hasMultiple
                return (
                  <button
                    key={m.key}
                    type="button"
                    onClick={() => !disabled && setViewMode(m.key)}
                    title={disabled ? 'Upload at least 2 files to enable' : m.hint}
                    disabled={disabled}
                    className={`inline-flex items-center gap-1.5 px-3.5 py-2 text-xs font-medium rounded-t-md border-b-2 whitespace-nowrap ${
                      disabled
                        ? 'border-transparent text-slate-300 cursor-not-allowed'
                        : isActive
                          ? 'border-indigo-600 text-indigo-700 bg-indigo-50/40'
                          : 'border-transparent text-slate-600 hover:text-slate-900 hover:bg-slate-50'
                    }`}
                  >
                    <Icon className="w-4 h-4" />
                    {m.label}
                  </button>
                )
              })}
            </div>
          </div>

          {viewMode === 'diff' && activeDetail && (
            <DiffView
              detail={activeDetail}
              detectedFields={detectedFields}
              statusFilter={statusFilter}
              setStatusFilter={setStatusFilter}
              search={search}
              setSearch={setSearch}
              rows={filteredRows}
              rowsLoading={rowsLoading}
            />
          )}

          {viewMode === 'inbox' && (
            <ComparisonRecommendationsInbox comparisons={allDetails} />
          )}

          {viewMode === 'consolidated' && (
            <ComparisonConsolidatedView comparisons={allDetails} />
          )}
        </div>
      )}

      {!allDetails.length && !loading && activeRunId && (
        <div className="text-center text-slate-500 text-sm py-8 border border-dashed border-slate-300 rounded-xl">
          No comparisons yet. Pick one or more external files above and click
          “Run comparisons” to get started.
        </div>
      )}
    </div>
  )
}

// ── Sub-components ──────────────────────────────────────────────────

function QueueRow({ entry, profiles, onChange, onRemove, disabled }) {
  const statusBadge = {
    pending:   { cls: 'bg-slate-100 text-slate-600',     label: 'Queued',     icon: HeroIcons.QueueListIcon },
    uploading: { cls: 'bg-indigo-100 text-indigo-700',   label: 'Comparing…', icon: HeroIcons.ArrowPathIcon, spin: true },
    done:      { cls: 'bg-emerald-100 text-emerald-700', label: 'Done',       icon: HeroIcons.CheckCircleIcon },
    error:     { cls: 'bg-rose-100 text-rose-700',       label: 'Failed',     icon: HeroIcons.XCircleIcon },
  }[entry.status] || {}
  const Icon = statusBadge.icon || HeroIcons.DocumentIcon

  return (
    <div className="px-3 py-2 flex items-center gap-2 flex-wrap text-xs bg-white">
      <HeroIcons.DocumentTextIcon className="w-4 h-4 text-slate-400 flex-shrink-0" />
      <div className="font-medium text-slate-800 min-w-0 truncate flex-1 md:flex-none md:w-64" title={entry.file.name}>
        {entry.file.name}
      </div>
      <span className="text-[10px] text-slate-400">
        {(entry.file.size / 1024).toFixed(0)} KB
      </span>
      <select
        value={entry.profile}
        onChange={(e) => onChange({ profile: e.target.value })}
        disabled={disabled || entry.status === 'uploading' || entry.status === 'done'}
        className="text-[11px] border border-slate-300 rounded px-1.5 py-1 bg-white"
        title="Source profile"
      >
        {profiles.map((p) => (
          <option key={p.code} value={p.code}>{p.label}</option>
        ))}
      </select>
      <input
        type="text"
        value={entry.label}
        onChange={(e) => onChange({ label: e.target.value })}
        placeholder="Label (optional)"
        disabled={disabled || entry.status === 'uploading' || entry.status === 'done'}
        className="text-[11px] border border-slate-300 rounded px-1.5 py-1 flex-1 min-w-[120px]"
      />
      <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[10px] font-medium ${statusBadge.cls}`}>
        <Icon className={`w-3 h-3 ${statusBadge.spin ? 'animate-spin' : ''}`} />
        {statusBadge.label}
      </span>
      {entry.error && (
        <span className="text-[10px] text-rose-600 max-w-xs truncate" title={entry.error}>
          {entry.error}
        </span>
      )}
      {entry.status !== 'uploading' && (
        <button
          type="button"
          onClick={onRemove}
          disabled={disabled}
          className="text-slate-400 hover:text-rose-600 disabled:opacity-50"
          title="Remove"
        >
          <HeroIcons.XMarkIcon className="w-3.5 h-3.5" />
        </button>
      )}
    </div>
  )
}

function KpiTile({ label, value, tone = 'slate', icon }) {
  const tones = {
    emerald: 'bg-emerald-50 border-emerald-200 text-emerald-800',
    amber:   'bg-amber-50 border-amber-200 text-amber-800',
    sky:     'bg-sky-50 border-sky-200 text-sky-800',
    rose:    'bg-rose-50 border-rose-200 text-rose-800',
    slate:   'bg-slate-50 border-slate-200 text-slate-800',
  }
  const Icon = icon ? (HeroIcons[icon] || HeroIcons.SparklesIcon) : null
  return (
    <div className={`border rounded-lg p-3 ${tones[tone] || tones.slate}`}>
      <div className="flex items-center gap-2">
        {Icon && <Icon className="w-4 h-4 opacity-70" />}
        <div className="text-[10px] uppercase font-medium opacity-70">{label}</div>
      </div>
      <div className="text-lg font-semibold tabular-nums mt-1">{value || 0}</div>
    </div>
  )
}

function DiffView({
  detail, detectedFields,
  statusFilter, setStatusFilter, search, setSearch,
  rows, rowsLoading,
}) {
  return (
    <div className="space-y-3">
      {/* Source header + per-field breakdown */}
      <div className="bg-white border border-slate-200 rounded-xl p-4">
        <div className="text-sm font-semibold text-slate-700">
          {detail.source_label}
          <span className="ml-2 text-xs font-normal text-slate-500">
            vs {detail.run_cycle_code} · uploaded {formatDateTime(detail.created_at)}
            {detail.uploaded_by_name ? ` by ${detail.uploaded_by_name}` : ''}
          </span>
        </div>
        {detectedFields.length > 0 && (
          <div className="mt-3">
            <div className="text-[11px] uppercase font-medium text-slate-500 mb-2">
              Variance by field (this source)
            </div>
            <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-6 gap-2">
              {detectedFields.map((f) => {
                const meta = comparisonFieldMeta(f)
                const st = detail.summary?.by_field?.[f] || {}
                const total = st.variances || 0
                const crit = st.critical || 0
                const warn = st.warning || 0
                return (
                  <div
                    key={f}
                    className={`border rounded-md px-2 py-1.5 text-xs ${
                      crit ? 'border-rose-200 bg-rose-50'
                      : warn ? 'border-amber-200 bg-amber-50'
                      : total ? 'border-sky-200 bg-sky-50'
                      : 'border-emerald-200 bg-emerald-50'
                    }`}
                  >
                    <div className="font-medium text-slate-700">{meta.label}</div>
                    <div className="flex items-center gap-1.5 mt-0.5 text-[11px]">
                      {total
                        ? (
                          <>
                            <span className="text-slate-600">{total} diff</span>
                            {crit ? <span className="text-rose-600 font-medium">·{crit}!</span> : null}
                            {warn ? <span className="text-amber-600 font-medium">·{warn}⚠</span> : null}
                          </>
                        )
                        : <span className="text-emerald-700 font-medium">all match ✓</span>
                      }
                    </div>
                  </div>
                )
              })}
            </div>
          </div>
        )}
      </div>

      {/* Filters */}
      <div className="bg-white border border-slate-200 rounded-xl p-3">
        <div className="flex items-center justify-between flex-wrap gap-2">
          <div className="flex flex-wrap gap-1">
            {STATUS_TABS.map((t) => {
              const isActive = statusFilter === t.key
              return (
                <button
                  key={t.key}
                  type="button"
                  onClick={() => setStatusFilter(t.key)}
                  className={`px-2.5 py-1 text-xs font-medium rounded-md border ${
                    isActive
                      ? 'border-indigo-400 bg-indigo-50 text-indigo-700'
                      : 'border-slate-200 bg-white text-slate-600 hover:bg-slate-50'
                  }`}
                >
                  {t.label}
                </button>
              )
            })}
          </div>
          <div className="relative">
            <HeroIcons.MagnifyingGlassIcon className="w-4 h-4 absolute left-2 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              type="text"
              placeholder="Search name / emp #"
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className="pl-7 pr-2 py-1.5 text-xs border border-slate-300 rounded-md w-64"
            />
          </div>
        </div>
      </div>

      <ComparisonDiffTable
        rows={rows}
        detectedFields={detectedFields}
        loading={rowsLoading}
      />
    </div>
  )
}

/**
 * RecommendationsInbox — plain-language action cards aggregated across one
 * or many comparisons for the same run. Groups by severity (Critical →
 * Warning → Info) and within each group, by employee.
 *
 * Props:
 *   comparisons: array of comparison DETAIL objects (with .rows[].variances[])
 *                Use ALL active comparisons for the run (multi-source aware).
 */
import React, { useMemo, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'

import {
  COMPARISON_SEVERITY_META,
  comparisonFieldMeta, formatComparisonValue,
} from '../../../../config/payrollEngine.config'

const SEVERITY_ORDER = ['critical', 'warning', 'info']
const SEVERITY_ICON = {
  critical: HeroIcons.ExclamationTriangleIcon,
  warning:  HeroIcons.ExclamationCircleIcon,
  info:     HeroIcons.InformationCircleIcon,
}
const SEVERITY_HEADER = {
  critical: 'bg-rose-50  border-rose-200  text-rose-800',
  warning:  'bg-amber-50 border-amber-200 text-amber-800',
  info:     'bg-sky-50   border-sky-200   text-sky-800',
}

export default function ComparisonRecommendationsInbox({ comparisons }) {
  const [hideInfo, setHideInfo] = useState(true)

  // Flatten all variances across all comparisons into actionable items.
  const items = useMemo(() => {
    const out = []
    for (const cmp of comparisons || []) {
      for (const row of (cmp.rows || [])) {
        for (const v of (row.variances || [])) {
          if (!v.recommendation) continue
          out.push({
            sev: v.severity,
            sourceLabel: cmp.source_label,
            sourceProfile: cmp.source_profile,
            employeeNo:  row.payroll_employee_no || row.external_employee_no || '—',
            employeeName: row.payroll_employee_name || row.external_name || '—',
            field: v.field,
            our: v.our,
            external: v.external,
            diff: v.diff,
            pct: v.pct,
            text: v.recommendation,
          })
        }
      }
    }
    return out
  }, [comparisons])

  const grouped = useMemo(() => {
    const g = { critical: [], warning: [], info: [] }
    for (const it of items) (g[it.sev] || g.info).push(it)
    return g
  }, [items])

  const totals = {
    critical: grouped.critical.length,
    warning:  grouped.warning.length,
    info:     grouped.info.length,
  }
  const totalAll = totals.critical + totals.warning + totals.info

  if (!totalAll) {
    return (
      <div className="bg-white border border-emerald-200 rounded-xl p-8 text-center">
        <HeroIcons.CheckBadgeIcon className="w-10 h-10 text-emerald-500 mx-auto mb-2" />
        <div className="text-sm font-medium text-emerald-700">
          All clear — no actionable variances detected.
        </div>
      </div>
    )
  }

  return (
    <div className="space-y-3">
      {/* Top counters */}
      <div className="grid grid-cols-3 gap-3">
        <CounterTile label="Critical" count={totals.critical} sev="critical" />
        <CounterTile label="Warning"  count={totals.warning}  sev="warning"  />
        <CounterTile label="Info"     count={totals.info}     sev="info"
                     trailing={
                       <button
                         type="button"
                         onClick={() => setHideInfo((v) => !v)}
                         className="text-[10px] underline text-sky-700"
                       >
                         {hideInfo ? 'show' : 'hide'}
                       </button>
                     } />
      </div>

      {SEVERITY_ORDER.map((sev) => {
        if (sev === 'info' && hideInfo) return null
        const list = grouped[sev]
        if (!list.length) return null
        const Icon = SEVERITY_ICON[sev]
        // Group by employee
        const byEmp = list.reduce((acc, it) => {
          const key = `${it.employeeNo}|${it.employeeName}`
          if (!acc[key]) acc[key] = { no: it.employeeNo, name: it.employeeName, items: [] }
          acc[key].items.push(it)
          return acc
        }, {})
        const empList = Object.values(byEmp)
        return (
          <div key={sev} className="bg-white border border-slate-200 rounded-xl overflow-hidden">
            <div className={`px-4 py-2 border-b flex items-center gap-2 ${SEVERITY_HEADER[sev]}`}>
              <Icon className="w-4 h-4" />
              <div className="text-sm font-semibold capitalize">{sev}</div>
              <div className="ml-auto text-xs">
                {list.length} item{list.length === 1 ? '' : 's'} across {empList.length} employee{empList.length === 1 ? '' : 's'}
              </div>
            </div>
            <div className="divide-y divide-slate-100">
              {empList.map((emp) => (
                <div key={emp.no + emp.name} className="px-4 py-3">
                  <div className="flex items-center gap-2 mb-1.5">
                    <HeroIcons.UserCircleIcon className="w-4 h-4 text-slate-400" />
                    <span className="text-sm font-medium text-slate-800">{emp.name}</span>
                    <span className="text-xs text-slate-500">#{emp.no}</span>
                  </div>
                  <ul className="space-y-1.5 pl-6">
                    {emp.items.map((it, i) => (
                      <RecommendationLine key={i} it={it} />
                    ))}
                  </ul>
                </div>
              ))}
            </div>
          </div>
        )
      })}
    </div>
  )
}

function CounterTile({ label, count, sev, trailing }) {
  const Icon = SEVERITY_ICON[sev]
  const meta = COMPARISON_SEVERITY_META[sev] || {}
  return (
    <div className={`border rounded-lg p-3 flex items-center gap-3 ${meta.cell || ''}`}>
      <Icon className={`w-6 h-6 ${
        sev === 'critical' ? 'text-rose-500'
        : sev === 'warning' ? 'text-amber-500'
        : 'text-sky-500'
      }`} />
      <div className="flex-1">
        <div className="text-[10px] uppercase font-medium text-slate-500">{label}</div>
        <div className="text-xl font-semibold tabular-nums text-slate-800">{count}</div>
      </div>
      {trailing}
    </div>
  )
}

function RecommendationLine({ it }) {
  const meta = comparisonFieldMeta(it.field)
  const our = formatComparisonValue(it.field, it.our)
  const ext = formatComparisonValue(it.field, it.external)
  return (
    <li className="text-xs leading-relaxed">
      <div className="flex flex-wrap items-baseline gap-x-2 gap-y-0.5">
        <span className="font-medium text-slate-700">{meta.label}</span>
        <span className="text-slate-400">·</span>
        <span className="text-slate-500">{it.sourceLabel}</span>
        <span className="text-slate-400">·</span>
        <span className="text-slate-600">
          Our <span className="font-mono">{our}</span> vs Ext <span className="font-mono">{ext}</span>
          {it.pct != null && (
            <span className={`ml-1 ${it.sev === 'critical' ? 'text-rose-600' : 'text-amber-600'} font-medium`}>
              ({it.pct >= 0 ? '+' : ''}{it.pct}%)
            </span>
          )}
        </span>
      </div>
      <div className="text-slate-700 mt-0.5">{it.text}</div>
    </li>
  )
}

/**
 * Schema-driven editor for a single PayrollEmployee. Every input is
 * generated from `EMPLOYEE_EDIT_FIELDS` in payrollEngine.config — add a
 * field there and it appears here automatically.
 *
 * Backend write permission is enforced by `PayrollEmployeeWritePermission`,
 * so this modal is also gated by `canEditPayrollEmployee` on the parent.
 */
import React, { useEffect, useMemo, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService from '../../../../services/payrollEngine.service'
import {
  EMPLOYEE_EDIT_FIELDS,
  PAYROLL_ENGINE_CURRENCY,
} from '../../../../config/payrollEngine.config'

const toFormValue = (raw, type) => {
  if (raw === null || raw === undefined) {
    if (type === 'checkbox') return false
    return ''
  }
  if (type === 'date' && typeof raw === 'string') return raw.slice(0, 10)
  return raw
}

const toPayloadValue = (val, type) => {
  if (type === 'checkbox') return !!val
  if (type === 'number') return val === '' || val === null ? null : val
  if (type === 'date') return val || null
  return val ?? ''
}

const FIELD_GROUPS_ORDER = (() => {
  const seen = new Set()
  const order = []
  for (const f of EMPLOYEE_EDIT_FIELDS) {
    const g = f.group || 'General'
    if (!seen.has(g)) { seen.add(g); order.push(g) }
  }
  return order
})()

export default function EmployeeEditModal({ employee, onClose, onSaved }) {
  const [form, setForm] = useState({})
  const [catalog, setCatalog] = useState(null)
  const [saving, setSaving] = useState(false)
  const [error, setError] = useState(null)
  const [touched, setTouched] = useState(false)

  // Seed the form from the row whenever the modal opens for a new employee
  useEffect(() => {
    if (!employee) return
    const seeded = {}
    for (const f of EMPLOYEE_EDIT_FIELDS) {
      seeded[f.key] = toFormValue(employee[f.key], f.type)
    }
    setForm(seeded)
    setError(null)
    setTouched(false)
  }, [employee])

  // Hydrate select options that read from /catalog/ (e.g. payment_modes)
  useEffect(() => {
    if (catalog) return
    const needsCatalog = EMPLOYEE_EDIT_FIELDS.some((f) => f.optionsFrom)
    if (!needsCatalog) return
    payrollEngineService.getCatalog()
      .then(setCatalog)
      .catch(() => setCatalog({}))
  }, [catalog])

  const resolveOptions = (field) => {
    if (Array.isArray(field.options)) return field.options
    if (field.optionsFrom && catalog?.[field.optionsFrom]) {
      return catalog[field.optionsFrom].map((o) => ({
        value: o.code ?? o.value ?? o,
        label: o.label ?? o.name ?? o.code ?? String(o),
      }))
    }
    return []
  }

  const grouped = useMemo(() => {
    const byGroup = {}
    for (const f of EMPLOYEE_EDIT_FIELDS) {
      const g = f.group || 'General'
      if (!byGroup[g]) byGroup[g] = []
      byGroup[g].push(f)
    }
    return byGroup
  }, [])

  const handleChange = (key, value) => {
    setForm((prev) => ({ ...prev, [key]: value }))
    setTouched(true)
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    if (!employee?.id) return
    // Validation — required fields
    for (const f of EMPLOYEE_EDIT_FIELDS) {
      if (f.required && !f.readOnly && !f.canonical) {
        const v = form[f.key]
        if (v === '' || v === null || v === undefined) {
          setError(`${f.label} is required.`)
          return
        }
      }
    }
    setSaving(true); setError(null)
    try {
      const payload = {}
      for (const f of EMPLOYEE_EDIT_FIELDS) {
        if (f.readOnly || f.canonical) continue
        payload[f.key] = toPayloadValue(form[f.key], f.type)
      }
      const updated = await payrollEngineService.updateEmployee(employee.id, payload)
      onSaved?.(updated)
    } catch (err) {
      const data = err?.response?.data
      const msg = data?.detail
        || data?.error
        || (typeof data === 'object'
              ? Object.entries(data).map(([k, v]) => `${k}: ${Array.isArray(v) ? v.join(', ') : v}`).join(' · ')
              : null)
        || err.message
      setError(msg)
    } finally {
      setSaving(false)
    }
  }

  const renderInput = (field) => {
    const id = `emp-edit-${field.key}`
    const value = form[field.key]
    const isReadOnly = field.readOnly || Boolean(field.canonical)
    const baseCls =
      'w-full text-sm border border-slate-300 rounded-md px-2.5 py-1.5 ' +
      'focus:outline-none focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 ' +
      'disabled:bg-slate-50 disabled:text-slate-500'

    if (field.type === 'checkbox') {
      return (
        <label className="inline-flex items-center gap-2 text-sm text-slate-700">
          <input
            id={id}
            type="checkbox"
            checked={!!value}
            disabled={isReadOnly}
            onChange={(e) => handleChange(field.key, e.target.checked)}
            className="rounded"
          />
          {field.label}
        </label>
      )
    }

    if (field.type === 'select') {
      const options = resolveOptions(field)
      return (
        <select
          id={id}
          value={value ?? ''}
          disabled={isReadOnly}
          onChange={(e) => handleChange(field.key, e.target.value)}
          className={baseCls}
        >
          <option value="">— Select —</option>
          {options.map((o) => (
            <option key={o.value} value={o.value}>{o.label}</option>
          ))}
        </select>
      )
    }

    // datalist = freeform input with dropdown suggestions from catalog.
    // Allows HR to type a new value OR pick from existing entries.
    if (field.type === 'datalist') {
      const listId = `${id}-list`
      const suggestions = field.optionsFrom && catalog?.[field.optionsFrom]
        ? catalog[field.optionsFrom]
        : []
      return (
        <>
          <input
            id={id}
            type="text"
            list={listId}
            value={value ?? ''}
            disabled={isReadOnly}
            onChange={(e) => handleChange(field.key, e.target.value)}
            className={baseCls}
            placeholder="Type or select…"
          />
          <datalist id={listId}>
            {suggestions.map((s) => (
              <option key={s} value={s} />
            ))}
          </datalist>
        </>
      )
    }

    if (field.type === 'textarea') {
      return (
        <textarea
          id={id}
          rows={3}
          value={value ?? ''}
          disabled={isReadOnly}
          onChange={(e) => handleChange(field.key, e.target.value)}
          className={baseCls}
        />
      )
    }

    return (
      <div className="relative">
        <input
          id={id}
          type={field.type || 'text'}
          step={field.type === 'number' ? (field.step || '0.01') : undefined}
          value={value ?? ''}
          readOnly={isReadOnly}
          disabled={isReadOnly}
          onChange={(e) => handleChange(field.key, e.target.value)}
          className={`${baseCls} ${field.currency ? 'pr-12' : ''}`}
        />
        {field.currency && (
          <span className="absolute right-2 top-1/2 -translate-y-1/2 text-[10px] font-medium text-slate-400 uppercase">
            {PAYROLL_ENGINE_CURRENCY}
          </span>
        )}
      </div>
    )
  }

  if (!employee) return null

  return (
    <div
      className="fixed inset-0 z-50 bg-slate-900/40 backdrop-blur-sm flex items-center justify-center p-4"
      onClick={onClose}
    >
      <form
        onSubmit={handleSubmit}
        onClick={(e) => e.stopPropagation()}
        className="bg-white w-full max-w-3xl rounded-xl shadow-xl flex flex-col max-h-[90vh]"
      >
        {/* Header */}
        <div className="px-5 py-3 border-b border-slate-200 flex items-center justify-between">
          <div>
            <h3 className="text-sm font-semibold text-slate-800 flex items-center gap-2">
              <HeroIcons.PencilSquareIcon className="w-4 h-4 text-indigo-600" />
              Edit Employee
            </h3>
            <p className="text-xs text-slate-500 mt-0.5">
              {employee.full_name} · {employee.employee_no}
            </p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="text-slate-400 hover:text-slate-700"
            aria-label="Close"
          >
            <HeroIcons.XMarkIcon className="w-5 h-5" />
          </button>
        </div>

        {/* Body */}
        <div className="px-5 py-4 overflow-y-auto space-y-5">
          <div className="rounded-lg border border-blue-200 bg-blue-50 px-3 py-2 text-xs text-blue-800">
            Name, employee number, department, designation and joining date come from the canonical employee profile. Edit them in HR Employee Profile; payroll controls only compensation, banking and payroll eligibility.
          </div>
          {FIELD_GROUPS_ORDER.map((group) => (
            <fieldset key={group} className="space-y-2">
              <legend className="text-[11px] font-semibold uppercase tracking-wider text-slate-500">
                {group}
              </legend>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-x-4 gap-y-3">
                {grouped[group].map((field) => (
                  <div key={field.key} className={field.type === 'textarea' ? 'md:col-span-2' : ''}>
                    {field.type !== 'checkbox' && (
                      <label
                        htmlFor={`emp-edit-${field.key}`}
                        className="block text-xs font-medium text-slate-600 mb-1"
                      >
                        {field.label}
                        {field.required && <span className="text-red-500 ml-0.5">*</span>}
                      </label>
                    )}
                    {renderInput(field)}
                  </div>
                ))}
              </div>
            </fieldset>
          ))}

          {error && (
            <div className="text-xs text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2">
              {error}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-5 py-3 border-t border-slate-200 flex items-center justify-end gap-2">
          <button
            type="button"
            onClick={onClose}
            className="px-3 py-1.5 text-sm font-medium rounded-md border border-slate-300 hover:bg-slate-50"
          >
            Cancel
          </button>
          <button
            type="submit"
            disabled={saving || !touched}
            className="inline-flex items-center gap-1.5 px-4 py-1.5 text-sm font-medium rounded-md bg-indigo-600 text-white hover:bg-indigo-700 disabled:opacity-50"
          >
            {saving
              ? <HeroIcons.ArrowPathIcon className="w-4 h-4 animate-spin" />
              : <HeroIcons.CheckIcon className="w-4 h-4" />}
            {saving ? 'Saving…' : 'Save Changes'}
          </button>
        </div>
      </form>
    </div>
  )
}

import { radaiConfirm } from '../../../../services/radaiDialog'
import { createPortal } from 'react-dom'
import React, { useEffect, useMemo, useRef, useState } from 'react'
import { Link } from 'react-router-dom'
import { useSelector } from 'react-redux'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService, { downloadBlob } from '../../../../services/payrollEngine.service'
import rbacService from '../../../../services/rbac.service'
import { formatCurrency, canEditPayrollEmployee } from '../../../../config/payrollEngine.config'
import EmployeeEditModal from './EmployeeEditModal'

const initials = (name = '') => name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]).join('').toUpperCase() || 'EP'
const money = (value) => formatCurrency(Number(value || 0))
const listFrom = (data) => Array.isArray(data) ? data : (data?.results ?? [])
const userListFrom = (response) => response?.data?.data?.results ?? response?.data?.results ?? response?.data?.data ?? response?.data ?? response?.results ?? []

function EmployeeAvatar({ name, src, className = 'h-10 w-10', textClassName = 'text-xs' }) {
  const [failed, setFailed] = useState(false)
  useEffect(() => { setFailed(false) }, [src])
  return <span className={`flex shrink-0 items-center justify-center overflow-hidden rounded-xl bg-gradient-to-br from-blue-600 to-indigo-700 font-bold text-white ${textClassName} ${className}`}>
    {src && !failed ? <img src={src} alt={`${name || 'Employee'} profile`} className="h-full w-full object-cover" loading="lazy" onError={() => setFailed(true)} /> : initials(name)}
  </span>
}

function AccountLinkModal({ employee, linkedEmployeesByUser, onClose, onLinked }) {
  const [query, setQuery] = useState(employee.employee_no || '')
  const [candidates, setCandidates] = useState([])
  const [loading, setLoading] = useState(false)
  const [savingId, setSavingId] = useState(null)
  const [error, setError] = useState('')

  useEffect(() => {
    const term = query.trim()
    if (!term) { setCandidates([]); return undefined }
    let cancelled = false
    const timer = window.setTimeout(() => {
      setLoading(true); setError('')
      rbacService.getUsers({ search: term, status: 'active', page_size: 20 })
        .then((response) => { if (!cancelled) setCandidates(userListFrom(response)) })
        .catch((requestError) => { if (!cancelled) setError(requestError?.response?.data?.detail || requestError?.message || 'RADAI accounts could not be searched.') })
        .finally(() => { if (!cancelled) setLoading(false) })
    }, 300)
    return () => { cancelled = true; window.clearTimeout(timer) }
  }, [query])

  const linkAccount = async (profile, knownOwner = null) => {
    const userId = profile.user?.id
    if (!userId) return
    let transfer = Boolean(knownOwner)
    if (knownOwner && !(await radaiConfirm(`This RADAI account is linked to payroll employee #${knownOwner.employee_no} (${knownOwner.full_name}). Move the account link to #${employee.employee_no} (${employee.full_name})? Salary and payslip records remain on their existing payroll rows.`))) return
    setSavingId(userId); setError('')
    try {
      let result
      try {
        result = await payrollEngineService.linkRadaiAccount(employee.id, userId, { transfer })
      } catch (requestError) {
        const conflict = requestError?.response?.data?.linked_employee
        if (requestError?.response?.status !== 409 || !conflict) throw requestError
        const confirmed = (await radaiConfirm(`This account is currently linked to #${conflict.employee_no} (${conflict.full_name}). Move the link to #${employee.employee_no} (${employee.full_name})?`))
        if (!confirmed) { setError(`Account remains linked to #${conflict.employee_no} (${conflict.full_name}).`); return }
        transfer = true
        result = await payrollEngineService.linkRadaiAccount(employee.id, userId, { transfer: true })
      }
      onLinked(result)
    } catch (requestError) {
      setError(requestError?.response?.data?.user?.[0] || requestError?.response?.data?.detail || requestError?.response?.data?.error || requestError?.message || 'The account could not be linked.')
    } finally { setSavingId(null) }
  }

  return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/45 p-4" role="dialog" aria-modal="true">
    <div className="w-full max-w-xl overflow-hidden rounded-2xl bg-white shadow-2xl">
      <div className="flex items-start justify-between border-b border-slate-200 px-5 py-4"><div><h3 className="text-base font-bold text-slate-950">Link RADAI account</h3><p className="mt-1 text-xs text-slate-500">Payroll employee #{employee.employee_no} · {employee.full_name}</p></div><button type="button" onClick={onClose} className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100 hover:text-slate-700"><HeroIcons.XMarkIcon className="h-5 w-5" /></button></div>
      <div className="p-5">
        <div className="rounded-xl border border-amber-200 bg-amber-50 p-3 text-xs text-amber-800"><strong>Verify carefully:</strong> linking connects payroll, salary and payslip history to the selected employee account. Search by employee number or company email for the safest match.</div>
        <div className="relative mt-4"><HeroIcons.MagnifyingGlassIcon className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Employee number, name or email" className="w-full rounded-xl border border-slate-300 py-3 pl-10 pr-3 text-sm outline-none focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100" /></div>
        {error && <div className="mt-3 rounded-lg border border-red-200 bg-red-50 p-3 text-xs text-red-700">{error}</div>}
        <div className="mt-4 max-h-80 overflow-y-auto rounded-xl border border-slate-200">
          {loading ? <div className="p-8 text-center text-sm text-slate-500"><HeroIcons.ArrowPathIcon className="mx-auto mb-2 h-5 w-5 animate-spin text-blue-600" />Searching employee accounts…</div> : candidates.length === 0 ? <div className="p-8 text-center text-sm text-slate-500">No active RADAI account matches this search.</div> : <div className="divide-y divide-slate-100">{candidates.map((profile) => {
            const userId = profile.user?.id
            const linkedOwner = linkedEmployeesByUser.get(String(userId))
            const candidateName = profile.full_name || `${profile.first_name || ''} ${profile.last_name || ''}`.trim() || profile.email
            return <div key={profile.id} className="flex items-center gap-3 px-4 py-3"><EmployeeAvatar name={candidateName} src={profile.profile_photo} /><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold text-slate-900">{candidateName}</p><p className="truncate text-xs text-slate-500">#{profile.employee_id || 'No employee ID'} · {profile.email}</p><p className="truncate text-[11px] text-slate-400">{profile.job_title || 'No job title'} · {profile.department || 'No department'}</p>{linkedOwner && <p className="mt-1 text-xs font-medium text-amber-700">Currently linked to payroll #{linkedOwner.employee_no} · {linkedOwner.full_name}</p>}</div><button type="button" onClick={() => linkAccount(profile, linkedOwner)} disabled={!userId || savingId === userId} className={`rounded-lg px-3 py-2 text-sm font-medium disabled:cursor-not-allowed disabled:bg-slate-200 disabled:text-slate-500 ${linkedOwner ? 'border border-amber-300 bg-amber-50 text-amber-800 hover:bg-amber-100' : 'bg-indigo-700 text-white hover:bg-indigo-800'}`}>{savingId === userId ? 'Saving…' : linkedOwner ? 'Move link here' : 'Link account'}</button></div>
          })}</div>}
        </div>
      </div>
    </div>
  </div>
}

function PayrollEmployeeDrawer({ employee, canEdit, onClose, onEdit, onLink }) {
  const detail = employee
  const [payslips, setPayslips] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')

  useEffect(() => {
    let cancelled = false
    setLoading(true); setError('')
    payrollEngineService.listPayslips({ employee: employee.id, page_size: 36 }).then((data) => {
      if (cancelled) return
      setPayslips(listFrom(data).sort((a, b) => String(b.run_cycle || '').localeCompare(String(a.run_cycle || ''))))
    }).catch((requestError) => {
      if (!cancelled) setError(requestError?.response?.data?.detail || requestError?.message || 'Payslip history could not be loaded.')
    }).finally(() => { if (!cancelled) setLoading(false) })
    return () => { cancelled = true }
  }, [employee.id])

  const latest = payslips[0]
  return (
    <div className="fixed inset-0 z-50 flex justify-end bg-slate-950/35 backdrop-blur-[1px]" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose() }}>
      <aside className="flex h-full w-full max-w-2xl flex-col bg-slate-50 shadow-2xl">
        <header className="bg-gradient-to-r from-slate-950 via-blue-950 to-blue-800 px-6 py-5 text-white">
          <div className="flex items-start justify-between gap-4">
            <div className="flex min-w-0 items-center gap-4">
              <EmployeeAvatar name={detail.full_name} src={detail.profile_photo} className="h-14 w-14 rounded-2xl ring-1 ring-white/20" textClassName="text-lg" />
              <div className="min-w-0">
                <div className="flex flex-wrap items-center gap-2"><h2 className="truncate text-xl font-bold">{detail.full_name}</h2><span className={`rounded-full px-2 py-0.5 text-[11px] font-bold ${detail.is_active ? 'bg-emerald-400/20 text-emerald-200' : 'bg-slate-400/20 text-slate-200'}`}>{detail.is_active ? 'Active' : 'Inactive'}</span></div>
                <p className="mt-1 text-sm text-blue-100">#{detail.employee_no} · {detail.designation || 'Designation not set'}</p>
                <p className="mt-0.5 text-xs text-blue-200">{detail.department || 'Department not set'}</p>
              </div>
            </div>
            <button type="button" onClick={onClose} className="rounded-lg p-2 text-blue-100 hover:bg-white/10 hover:text-white" aria-label="Close employee payroll"><HeroIcons.XMarkIcon className="h-5 w-5" /></button>
          </div>
          <div className="mt-5 flex flex-wrap gap-2">
            {detail.user ? <Link to={`/hr/employees?employee=${encodeURIComponent(detail.employee_no)}&tab=compensation`} className="inline-flex items-center gap-2 rounded-lg bg-white px-3 py-2 text-sm font-medium text-blue-800 hover:bg-blue-50"><HeroIcons.UserCircleIcon className="h-4 w-4" /> Open employee profile</Link> : <span className="inline-flex items-center gap-2 rounded-lg border border-amber-300/30 bg-amber-300/10 px-3 py-2 text-xs font-semibold text-amber-100"><HeroIcons.ExclamationTriangleIcon className="h-4 w-4" /> Payroll-only record</span>}
            {!detail.user && canEdit && <button type="button" onClick={() => onLink(detail)} className="inline-flex items-center gap-2 rounded-lg bg-white px-3 py-2 text-sm font-medium text-blue-800 hover:bg-blue-50"><HeroIcons.LinkIcon className="h-4 w-4" /> Link RADAI account</button>}
            {canEdit && <button type="button" onClick={() => onEdit(detail)} className="inline-flex items-center gap-2 rounded-lg border border-white/20 bg-white/10 px-3 py-2 text-sm font-medium text-white hover:bg-white/20"><HeroIcons.PencilSquareIcon className="h-4 w-4" /> Edit payroll profile</button>}
          </div>
        </header>

        <div className="flex-1 space-y-4 overflow-y-auto p-5 sm:p-6">
          {error && <div className="rounded-xl border border-red-200 bg-red-50 p-4 text-sm text-red-700">{error}</div>}
          {loading ? <div className="rounded-xl border border-slate-200 bg-white p-12 text-center text-sm text-slate-500"><HeroIcons.ArrowPathIcon className="mx-auto mb-3 h-6 w-6 animate-spin text-blue-600" />Loading employee payroll…</div> : <>
            <section className="grid grid-cols-2 gap-3 sm:grid-cols-4">
              {[['Basic', detail.basic], ['Allowances', Number(detail.housing || 0) + Number(detail.transport || 0) + Number(detail.home_leave || 0)], ['Default gross', detail.default_gross], ['Latest net', latest?.net_payable]].map(([label, value]) => <div key={label} className="rounded-xl border border-slate-200 bg-white p-3"><p className="text-[10px] font-bold uppercase tracking-wide text-slate-500">{label}</p><p className="mt-1 text-base font-bold text-slate-950">{money(value)}</p></div>)}
            </section>

            <section className="rounded-xl border border-slate-200 bg-white p-5">
              <div className="flex items-center gap-2 border-b border-slate-100 pb-3"><HeroIcons.IdentificationIcon className="h-5 w-5 text-blue-600" /><h3 className="text-sm font-bold text-slate-900">Payroll identity</h3></div>
              <dl className="mt-4 grid grid-cols-1 gap-x-6 gap-y-4 text-sm sm:grid-cols-2">
                <div><dt className="text-[10px] font-bold uppercase tracking-wide text-slate-400">Employee number</dt><dd className="mt-1 font-medium text-slate-800">{detail.employee_no}</dd></div>
                <div><dt className="text-[10px] font-bold uppercase tracking-wide text-slate-400">RADAI account</dt><dd className="mt-1"><span className={`inline-flex items-center gap-1.5 rounded-full px-2 py-1 text-[11px] font-bold ${detail.user ? 'bg-emerald-50 text-emerald-700 ring-1 ring-emerald-200' : 'bg-amber-50 text-amber-700 ring-1 ring-amber-200'}`}><span className={`h-1.5 w-1.5 rounded-full ${detail.user ? 'bg-emerald-500' : 'bg-amber-500'}`} />{detail.user ? 'Linked' : 'Not linked'}</span>{detail.user && <span className="ml-2 text-xs font-medium text-slate-600">{detail.employee_email || `User #${detail.user}`}</span>}</dd></div>
                {[['Grade', detail.grade || '—'], ['Discipline', detail.discipline || '—'], ['Joining date', detail.joining_date || '—'], ['Contracted hours', detail.hours || '—'], ['Bank', detail.bank_name || '—'], ['Payment mode', detail.default_payment_mode || '—']].map(([label, value]) => <div key={label}><dt className="text-[10px] font-bold uppercase tracking-wide text-slate-400">{label}</dt><dd className="mt-1 font-medium text-slate-800">{value}</dd></div>)}
              </dl>
            </section>

            <section className="rounded-xl border border-slate-200 bg-white">
              <div className="flex items-center justify-between border-b border-slate-100 px-5 py-4"><div><h3 className="text-sm font-bold text-slate-900">Payslip history</h3></div><span className="rounded-full bg-blue-50 px-2.5 py-1 text-sm font-medium text-blue-700">{payslips.length}</span></div>
              {payslips.length === 0 ? <div className="px-5 py-10 text-center text-sm text-slate-500">No payroll runs have generated a payslip for this employee yet.</div> : <div className="divide-y divide-slate-100">{payslips.slice(0, 12).map((slip) => <div key={slip.id} className="grid grid-cols-[1fr_auto] items-center gap-4 px-5 py-3 hover:bg-slate-50"><div><p className="text-sm font-bold text-slate-900">{slip.run_cycle}</p><p className="mt-0.5 text-xs text-slate-500">Gross {money(slip.gross_earnings)} · Deductions {money(slip.total_deductions)}</p></div><div className="text-right"><p className="text-sm font-bold text-emerald-700">{money(slip.net_payable)}</p><p className="mt-0.5 text-[10px] font-semibold uppercase text-slate-400">{slip.status}</p></div></div>)}</div>}
            </section>
          </>}
        </div>
      </aside>
    </div>
  )
}

export default function EmployeesTable({ actionsTarget }) {
  const [employees, setEmployees] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [search, setSearch] = useState('')
  const [showInactive, setShowInactive] = useState(false)
  const [uploading, setUploading] = useState(false)
  const [uploadSummary, setUploadSummary] = useState(null)
  const [editing, setEditing] = useState(null)
  const [selected, setSelected] = useState(null)
  const [linking, setLinking] = useState(null)
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(24)
  const fileInputRef = useRef(null)
  const authUser = useSelector((state) => state.auth?.user)
  const rbacUser = useSelector((state) => state.rbac?.currentUser)
  const canEdit = useMemo(() => canEditPayrollEmployee(authUser, rbacUser), [authUser, rbacUser])

  const load = async () => {
    setLoading(true); setError('')
    try {
      const data = await payrollEngineService.listEmployees({ is_active: showInactive ? undefined : 'true', page_size: 500 })
      setEmployees(listFrom(data))
    } catch (requestError) {
      setError(requestError?.response?.data?.error || requestError?.message || 'Payroll employees could not be loaded.')
    } finally { setLoading(false) }
  }
  useEffect(() => { load() /* eslint-disable-next-line react-hooks/exhaustive-deps */ }, [showInactive])

  const filtered = useMemo(() => {
    const query = search.trim().toLowerCase()
    if (!query) return employees
    return employees.filter((employee) => [employee.full_name, employee.employee_no, employee.department, employee.designation, employee.employee_email].some((value) => String(value || '').toLowerCase().includes(query)))
  }, [employees, search])

  const linkedEmployeesByUser = useMemo(() => new Map(employees.filter((employee) => employee.user).map((employee) => [String(employee.user), employee])), [employees])
  const totalPages = Math.max(1, Math.ceil(filtered.length / pageSize))
  const pageRows = useMemo(() => filtered.slice((page - 1) * pageSize, page * pageSize), [filtered, page, pageSize])
  useEffect(() => { setPage(1) }, [search, showInactive, pageSize])
  useEffect(() => { setPage((current) => Math.min(current, totalPages)) }, [totalPages])

  const handleUpload = async (event) => {
    const file = event.target.files?.[0]; if (!file) return
    setUploading(true); setError(''); setUploadSummary(null)
    try { setUploadSummary(await payrollEngineService.importEmployeesXlsx(file)); await load() }
    catch (requestError) { setError(requestError?.response?.data?.error || requestError?.message) }
    finally { setUploading(false); if (fileInputRef.current) fileInputRef.current.value = '' }
  }
  const handleDownload = async () => {
    try { downloadBlob(await payrollEngineService.exportEmployeesXlsx(), 'payroll_employees.xlsx') }
    catch (requestError) { setError(requestError?.response?.data?.error || requestError?.message) }
  }

  return <div className="space-y-4">
    <input ref={fileInputRef} type="file" accept=".xlsx" className="hidden" onChange={handleUpload} />
    {actionsTarget && createPortal(
      <details className="relative" onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget)) event.currentTarget.open = false
      }} onKeyDown={(event) => {
        if (event.key === 'Escape') {
          event.currentTarget.open = false
          event.currentTarget.querySelector('summary')?.focus()
        }
      }}>
        <summary className="flex cursor-pointer list-none items-center gap-2 rounded-lg border border-indigo-200 bg-white px-3 py-2 text-sm font-medium text-indigo-700 hover:bg-indigo-50 [&::-webkit-details-marker]:hidden">
          Import / Export <HeroIcons.ChevronDownIcon className="h-4 w-4" />
        </summary>
        <div className="absolute right-0 z-30 mt-2 w-44 rounded-xl border border-slate-200 bg-white p-1 shadow-lg">
          <button type="button" disabled={uploading} onClick={(event) => {
            event.currentTarget.closest('details').open = false
            fileInputRef.current?.click()
          }} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-sm text-slate-700 hover:bg-indigo-50 disabled:opacity-50">
            <HeroIcons.ArrowUpTrayIcon className="h-4 w-4" />{uploading ? 'Importing...' : 'Import XLSX'}
          </button>
          <button type="button" onClick={(event) => {
            event.currentTarget.closest('details').open = false
            handleDownload()
          }} className="flex w-full items-center gap-2 rounded-lg px-3 py-2 text-sm text-slate-700 hover:bg-indigo-50">
            <HeroIcons.ArrowDownTrayIcon className="h-4 w-4" />Export roster
          </button>
        </div>
      </details>, actionsTarget)}

    <section className="rounded-2xl border border-slate-200 bg-white shadow-sm">
      <div className="flex flex-wrap items-center gap-3 border-b border-slate-200 p-4"><div className="relative min-w-[240px] flex-1"><HeroIcons.MagnifyingGlassIcon className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Search employee, number, department, designation or email" className="w-full rounded-lg border border-slate-300 py-2.5 pl-9 pr-3 text-sm outline-none focus:border-indigo-400 focus:ring-2 focus:ring-indigo-100" /></div><label className="inline-flex items-center gap-2 rounded-lg border border-slate-200 px-3 py-2.5 text-xs font-semibold text-slate-600"><input type="checkbox" checked={showInactive} onChange={(event) => setShowInactive(event.target.checked)} className="rounded border-slate-300 text-blue-600" />Include inactive</label><label className="inline-flex items-center gap-2 text-xs font-semibold text-slate-500">Rows<select value={pageSize} onChange={(event) => setPageSize(Number(event.target.value))} className="rounded-lg border border-slate-200 bg-white px-2 py-2 text-xs text-slate-700"><option value={12}>12</option><option value={24}>24</option><option value={48}>48</option></select></label><span className="text-xs font-semibold text-slate-500">{filtered.length} records</span></div>
      {uploadSummary && <div className="m-4 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-xs font-medium text-emerald-800">Import complete: {uploadSummary.employees_created} created, {uploadSummary.employees_updated} updated.</div>}
      {error && <div className="m-4 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-xs text-red-700">{error}</div>}
      {loading ? <div className="p-14 text-center text-sm text-slate-500"><HeroIcons.ArrowPathIcon className="mx-auto mb-3 h-6 w-6 animate-spin text-blue-600" />Loading payroll employees…</div> : filtered.length === 0 ? <div className="p-14 text-center text-sm text-slate-500">No payroll employees match this search.</div> : <div className="divide-y divide-slate-100">{pageRows.map((employee) => <button key={employee.id} type="button" onClick={() => setSelected(employee)} className="grid w-full grid-cols-[auto_1fr_auto] items-center gap-3 px-4 py-3 text-left transition-colors hover:bg-blue-50/50 sm:px-5 lg:grid-cols-[auto_minmax(220px,1.4fr)_minmax(160px,1fr)_130px_130px_auto]">
        <EmployeeAvatar name={employee.full_name} src={employee.profile_photo} />
        <span className="min-w-0"><span className="flex items-center gap-2"><span className="truncate text-sm font-bold text-slate-900">{employee.full_name}</span>{employee.user ? <HeroIcons.LinkIcon className="h-3.5 w-3.5 shrink-0 text-violet-500" title="Linked to RADAI employee" /> : null}</span><span className="mt-0.5 block text-xs text-slate-500">#{employee.employee_no} · {employee.designation || 'No designation'}</span></span>
        <span className="hidden min-w-0 lg:block"><span className="block truncate text-sm font-medium text-slate-700">{employee.department || 'No department'}</span><span className="mt-0.5 block truncate text-xs text-slate-400">{employee.grade || employee.discipline || '—'}</span></span>
        <span className="hidden text-right lg:block"><span className="block text-[10px] font-bold uppercase text-slate-400">Basic</span><span className="text-sm font-semibold text-slate-700">{money(employee.basic)}</span></span>
        <span className="hidden text-right lg:block"><span className="block text-[10px] font-bold uppercase text-slate-400">Gross</span><span className="text-sm font-bold text-emerald-700">{money(employee.default_gross)}</span></span>
        <span className="flex items-center gap-2">{employee.is_active ? <span className="hidden rounded-full bg-emerald-50 px-2 py-1 text-[10px] font-bold text-emerald-700 sm:inline">Active</span> : <span className="hidden rounded-full bg-slate-100 px-2 py-1 text-[10px] font-bold text-slate-500 sm:inline">Inactive</span>}<HeroIcons.ChevronRightIcon className="h-4 w-4 text-slate-400" /></span>
      </button>)}</div>}
      {!loading && filtered.length > 0 && <div className="flex flex-wrap items-center justify-between gap-3 border-t border-slate-200 px-4 py-3 sm:px-5"><p className="text-xs text-slate-500">Showing {(page - 1) * pageSize + 1}–{Math.min(page * pageSize, filtered.length)} of {filtered.length}</p><div className="flex items-center gap-1"><button type="button" onClick={() => setPage((current) => Math.max(1, current - 1))} disabled={page === 1} className="rounded-lg border border-slate-200 p-2 text-slate-600 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40" aria-label="Previous employee page"><HeroIcons.ChevronLeftIcon className="h-4 w-4" /></button><span className="min-w-24 px-2 text-center text-sm font-medium text-slate-700">Page {page} of {totalPages}</span><button type="button" onClick={() => setPage((current) => Math.min(totalPages, current + 1))} disabled={page === totalPages} className="rounded-lg border border-slate-200 p-2 text-slate-600 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40" aria-label="Next employee page"><HeroIcons.ChevronRightIcon className="h-4 w-4" /></button></div></div>}
    </section>

    {selected && <PayrollEmployeeDrawer key={`${selected.id}:${selected.user || 'unlinked'}`} employee={selected} canEdit={canEdit} onClose={() => setSelected(null)} onEdit={(employee) => { setSelected(null); setEditing(employee) }} onLink={setLinking} />}
    {linking && <AccountLinkModal employee={linking} linkedEmployeesByUser={linkedEmployeesByUser} onClose={() => setLinking(null)} onLinked={(result) => { const replacements = new Map([result.employee, ...(result.unlinked_employees || [])].map((item) => [item.id, item])); setEmployees((previous) => previous.map((employee) => replacements.get(employee.id) || employee)); setSelected(result.employee); setLinking(null) }} />}
    {editing && <EmployeeEditModal employee={editing} onClose={() => setEditing(null)} onSaved={(updated) => { setEmployees((previous) => previous.map((employee) => employee.id === updated.id ? updated : employee)); setEditing(null) }} />}
  </div>
}

import React, { useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService from '../../../../services/payrollEngine.service'
import MonthYearPicker from './MonthYearPicker'

const today = new Date()

export default function ExcelHub({ onAfterImport }) {
  const [period, setPeriod] = useState({
    year: today.getFullYear(),
    month: today.getMonth() + 1,
  })
  const [file, setFile] = useState(null)
  const [busy, setBusy] = useState(false)
  const [result, setResult] = useState(null)
  const [error, setError] = useState(null)
  const fileInputRef = React.useRef(null)

  const handleImportFull = async () => {
    if (!file) { setError('Pick an Excel file first.'); return }
    setBusy(true); setError(null); setResult(null)
    try {
      const data = await payrollEngineService.importFullXlsx(file, period)
      setResult(data)
      onAfterImport?.(data.run)
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setBusy(false)
    }
  }

  return (
    <div className="space-y-4">
      <div className="bg-white border border-slate-200 rounded-xl p-5">
        <h3 className="text-sm font-semibold text-slate-700 mb-1 flex items-center gap-2">
          <HeroIcons.DocumentArrowUpIcon className="w-5 h-5 text-blue-600" />
          Full Payroll Import (Excel → Draft Run)
        </h3>
        <p className="text-xs text-slate-500 mb-4">
          Upload the monthly master Excel (same format as the source template) to
          create or overwrite the Draft PayrollRun for the chosen period in one shot.
        </p>

        <div className="flex flex-wrap items-end gap-3">
          <div>
            <label className="block text-xs font-medium text-slate-600 mb-1">Period</label>
            <MonthYearPicker year={period.year} month={period.month} onChange={setPeriod} />
          </div>

          <div className="flex-1 min-w-[260px]">
            <label className="block text-xs font-medium text-slate-600 mb-1">Excel file</label>
            <input
              ref={fileInputRef}
              type="file"
              accept=".xlsx"
              onChange={(e) => setFile(e.target.files?.[0] || null)}
              className="block w-full text-xs text-slate-600 file:mr-3 file:py-1.5 file:px-3 file:rounded-md file:border-0 file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
            />
            {file && (
              <p className="text-xs text-slate-500 mt-1">
                Selected: <span className="font-medium">{file.name}</span> ({Math.round(file.size / 1024)} KB)
              </p>
            )}
          </div>

          <button
            type="button"
            onClick={handleImportFull}
            disabled={!file || busy}
            className="inline-flex items-center gap-1.5 px-4 py-2 text-sm font-medium rounded-md bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50"
          >
            {busy
              ? <HeroIcons.ArrowPathIcon className="w-4 h-4 animate-spin" />
              : <HeroIcons.PlayCircleIcon className="w-4 h-4" />
            }
            {busy ? 'Importing…' : 'Import & Generate'}
          </button>
        </div>

        {error && (
          <div className="mt-3 text-xs text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2">{error}</div>
        )}

        {result && (
          <div className="mt-3 text-xs text-emerald-800 bg-emerald-50 border border-emerald-200 rounded-md px-3 py-2 space-y-0.5">
            <div className="font-semibold">Import successful</div>
            <div>Run: {result.run?.cycle_code} ({result.run?.employee_count} payslips · net {result.run?.total_net} AED)</div>
            <div>
              Employees: {result.import_summary?.employees_created} created /
              {' '}{result.import_summary?.employees_updated} updated /
              {' '}{result.import_summary?.adjustments_created} adjustments queued
            </div>
          </div>
        )}
      </div>

      <div className="bg-white border border-slate-200 rounded-xl p-5">
        <h3 className="text-sm font-semibold text-slate-700 mb-1 flex items-center gap-2">
          <HeroIcons.InformationCircleIcon className="w-5 h-5 text-slate-500" />
          Expected Excel Layout
        </h3>
        <ul className="text-xs text-slate-600 space-y-1 ml-4 list-disc">
          <li>Sheet #1 is the master roster with headers at row 4: Employee #, Name, IBAN, Bank, Department, Designation, Basic, Housing, Transport, Home Leave, Other Pay, Deductions, Payment Method.</li>
          <li>Data rows start at row 5; the row labelled <code className="bg-slate-100 px-1 rounded">TOTAL</code> ends the data block.</li>
          <li>"Other Pay" + "Other Pay Details" become free-form earning adjustments.</li>
          <li>"Salary Deduction" + "Salary Deduction Details" become free-form deductions.</li>
        </ul>
      </div>
    </div>
  )
}

/**
 * ExternalUploadPanel — Upload ValueFrame or Sympa XLSX to update payslip data.
 *
 * Displayed inside RunDetail (Draft runs only) before the Deductions/Comparison section.
 * Soft-coded file types come from EXTERNAL_UPLOAD_FILE_TYPES in payrollEngine.config.js.
 * Each upload immediately applies the data to the run's payslips and stores the file in S3.
 */
import React, { useCallback, useEffect, useRef, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService from '../../../../services/payrollEngine.service'
import { EXTERNAL_UPLOAD_FILE_TYPES } from '../../../../config/payrollEngine.config'

// Soft-coded color classes per file type (Tailwind JIT-safe)
const COLOR_MAP = {
  blue:   { card: 'border-blue-200 bg-blue-50',   btn: 'bg-blue-600 hover:bg-blue-700 text-white', badge: 'bg-blue-100 text-blue-700 border-blue-200' },
  violet: { card: 'border-violet-200 bg-violet-50', btn: 'bg-violet-600 hover:bg-violet-700 text-white', badge: 'bg-violet-100 text-violet-700 border-violet-200' },
}
const DEFAULT_COLOR = { card: 'border-slate-200 bg-slate-50', btn: 'bg-slate-700 hover:bg-slate-800 text-white', badge: 'bg-slate-100 text-slate-700 border-slate-200' }
const colors = (key) => COLOR_MAP[key] || DEFAULT_COLOR

const fmtDate = (iso) => {
  try { return new Date(iso).toLocaleString('en-AE', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' }) }
  catch { return iso }
}

export default function ExternalUploadPanel({ runId, runEditable, onUploaded, onClose }) {
  const [uploads, setUploads] = useState([])
  const [uploading, setUploading] = useState({})  // { fileType: true/false }
  const [results,   setResults]   = useState({})  // { fileType: result }
  const [errors,    setErrors]    = useState({})  // { fileType: errorMsg }
  const fileRefs = useRef({})

  const loadUploads = useCallback(async () => {
    try {
      const data = await payrollEngineService.listRunUploads(runId)
      setUploads(Array.isArray(data?.results) ? data.results : [])
    } catch { /* silent */ }
  }, [runId])

  useEffect(() => { loadUploads() }, [loadUploads])

  const handleUpload = async (ft) => {
    const file = fileRefs.current[ft.key]?.files?.[0]
    if (!file) {
      setErrors((e) => ({ ...e, [ft.key]: 'Please select a file first.' }))
      return
    }
    setUploading((u) => ({ ...u, [ft.key]: true }))
    setErrors((e) => ({ ...e, [ft.key]: null }))
    setResults((r) => ({ ...r, [ft.key]: null }))
    try {
      const result = await payrollEngineService.uploadExternalFile(runId, file, ft.key)
      setResults((r) => ({ ...r, [ft.key]: result }))
      // Reset file input
      if (fileRefs.current[ft.key]) fileRefs.current[ft.key].value = ''
      await loadUploads()
      onUploaded?.()
    } catch (e) {
      const msg = e?.response?.data?.error || e.message || 'Upload failed.'
      setErrors((er) => ({ ...er, [ft.key]: msg }))
    } finally {
      setUploading((u) => ({ ...u, [ft.key]: false }))
    }
  }

  return (
    <div className="bg-white border border-slate-200 rounded-xl p-4">
      <div className="flex items-center gap-2 mb-4">
        <HeroIcons.ArrowUpTrayIcon className="w-4 h-4 text-indigo-600" />
        <h3 className="text-sm font-semibold text-slate-700">Import External Files</h3>
        <span className="text-[10px] uppercase font-medium text-slate-400 ml-2">
          Updates payslip data · Draft only
        </span>
        {onClose && (
          <button
            type="button"
            onClick={onClose}
            className="ml-auto p-1 hover:bg-slate-100 rounded text-slate-400 hover:text-slate-600"
            title="Close"
          >
            <HeroIcons.XMarkIcon className="w-4 h-4" />
          </button>
        )}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {EXTERNAL_UPLOAD_FILE_TYPES.map((ft) => {
          const cl      = colors(ft.color)
          const busy    = !!uploading[ft.key]
          const result  = results[ft.key]
          const errMsg  = errors[ft.key]

          return (
            <div key={ft.key} className={`rounded-xl border p-4 ${cl.card}`}>
              {/* Header */}
              <div className="flex items-center justify-between mb-2">
                <div>
                  <div className="text-sm font-semibold text-slate-800">{ft.label}</div>
                  <div className="text-xs text-slate-500 mt-0.5">{ft.description}</div>
                </div>
                <div className="flex flex-wrap gap-1 justify-end">
                  {ft.fields_updated.map((f) => (
                    <span key={f} className={`inline-block px-1.5 py-0.5 rounded text-[10px] border font-medium ${cl.badge}`}>
                      {f.replace('_', ' ')}
                    </span>
                  ))}
                </div>
              </div>

              {/* File input + upload button */}
              {runEditable ? (
                <div className="flex items-center gap-2 mt-3">
                  <input
                    type="file"
                    accept={ft.accept}
                    ref={(el) => { fileRefs.current[ft.key] = el }}
                    disabled={busy}
                    className="flex-1 text-xs text-slate-600 file:mr-2 file:py-1 file:px-2 file:rounded file:border-0 file:text-xs file:font-medium file:bg-white file:text-slate-700 file:border file:border-slate-300 hover:file:bg-slate-50 disabled:opacity-50"
                  />
                  <button
                    type="button"
                    onClick={() => handleUpload(ft)}
                    disabled={busy}
                    className={`inline-flex items-center gap-1 px-3 py-1.5 text-xs font-medium rounded-md ${cl.btn} disabled:opacity-50`}
                  >
                    {busy
                      ? <HeroIcons.ArrowPathIcon className="w-3.5 h-3.5 animate-spin" />
                      : <HeroIcons.ArrowUpTrayIcon className="w-3.5 h-3.5" />}
                    {busy ? 'Uploading…' : 'Upload'}
                  </button>
                </div>
              ) : (
                <div className="mt-3 text-xs text-slate-400 italic">
                  Run is not in Draft — uploads disabled.
                </div>
              )}

              {/* Result summary */}
              {result && (
                <div className="mt-3 bg-emerald-50 border border-emerald-200 rounded-lg px-3 py-2 text-xs text-emerald-800">
                  <span className="font-semibold">✓ Applied</span>
                  {' · '}{result.rows_updated} updated · {result.rows_matched} matched
                  {result.unmatched?.length > 0 && (
                    <div className="mt-1 text-amber-700">
                      ⚠ {result.unmatched.length} unmatched: {result.unmatched.slice(0, 5).join(', ')}
                      {result.unmatched.length > 5 && ` +${result.unmatched.length - 5} more`}
                    </div>
                  )}
                </div>
              )}
              {errMsg && (
                <div className="mt-3 bg-rose-50 border border-rose-200 rounded-lg px-3 py-2 text-xs text-rose-700">
                  ✗ {errMsg}
                </div>
              )}
            </div>
          )
        })}
      </div>

      {/* Upload history */}
      {uploads.length > 0 && (
        <div className="mt-5">
          <h4 className="text-xs font-semibold text-slate-500 uppercase mb-2">Upload History</h4>
          <div className="space-y-1.5">
            {uploads.map((u) => {
              const ft = EXTERNAL_UPLOAD_FILE_TYPES.find((t) => t.key === u.file_type)
              const cl = colors(ft?.color)
              return (
                <div key={u.id} className="flex flex-wrap items-center gap-2 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-xs">
                  <span className={`px-2 py-0.5 rounded-full border font-medium ${cl.badge}`}>{u.file_type_label || u.file_type}</span>
                  <span className="text-slate-700 font-medium truncate max-w-xs">{u.original_filename}</span>
                  <span className="text-slate-400">·</span>
                  <span className="text-slate-600">{u.rows_updated} updated / {u.rows_matched} matched</span>
                  {u.unmatched?.length > 0 && (
                    <span className="text-amber-600">⚠ {u.unmatched.length} unmatched</span>
                  )}
                  <span className="text-slate-400 ml-auto">{fmtDate(u.uploaded_at)} · {u.uploaded_by_name}</span>
                  {u.s3_key && (
                    <span className="text-emerald-600" title={`S3: ${u.s3_key}`}>
                      <HeroIcons.CloudArrowUpIcon className="w-3.5 h-3.5 inline" />
                    </span>
                  )}
                </div>
              )
            })}
          </div>
        </div>
      )}
    </div>
  )
}

import React, { useEffect, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService from '../../../../services/payrollEngine.service'
import {
  CHANGE_LOG_ACTION,
  CHANGE_LOG_ACTION_META,
  CHANGE_LOG_FIELD_LABELS,
  INLINE_CHANGE_HISTORY,
  formatCurrency
} from '../../../../config/payrollEngine.config'

/**
 * InlineChangeHistory — Compact, embedded change log viewer
 * 
 * Displays change history for a specific kind (earning/deduction) within
 * the section itself, rather than in a separate modal. Shows compact
 * timeline of changes with expand/collapse functionality.
 * 
 * Props:
 * - payslipId: ID of the payslip to fetch changes for
 * - kind: 'earning' or 'deduction' (filters changes to this type only)
 */
export default function InlineChangeHistory({ payslipId, kind }) {
  const [changes, setChanges] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [displayLimit, setDisplayLimit] = useState(INLINE_CHANGE_HISTORY.DEFAULT_LIMIT)
  const [expanded, setExpanded] = useState(false)

  useEffect(() => {
    loadHistory()
  }, [payslipId, kind])

  const loadHistory = async () => {
    setLoading(true)
    setError(null)
    try {
      const response = await payrollEngineService.getPayslipChangeHistory(payslipId)
      
      // Backend returns: { payslip_id, employee_name, total_changes, changes: [...] }
      let data = []
      if (Array.isArray(response)) {
        // Direct array (legacy format)
        data = response
      } else if (response && Array.isArray(response.changes)) {
        // Object with changes property (current backend format)
        data = response.changes
      } else if (response && Array.isArray(response.results)) {
        // Paginated format
        data = response.results
      } else if (response && Array.isArray(response.data)) {
        // Generic data property
        data = response.data
      } else {
        console.warn('Unexpected response format from getPayslipChangeHistory:', response)
        data = []
      }
      
      // Filter by kind
      const filtered = data.filter(c => 
        c.new_values?.kind === kind || c.old_values?.kind === kind
      )
      setChanges(filtered)
    } catch (err) {
      setError(err?.response?.data?.error || err.message || 'Failed to load change history')
    } finally {
      setLoading(false)
    }
  }

  const formatDateTime = (isoString) => {
    if (!isoString) return '—'
    const date = new Date(isoString)
    return date.toLocaleString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    })
  }

  const getDisplayValue = (change, field) => {
    const values = change.new_values || change.old_values || {}
    const value = values[field]
    
    if (field === 'amount') {
      return formatCurrency(value, { withSymbol: false })
    }
    return value || '—'
  }

  const getActionMeta = (action) => {
    return CHANGE_LOG_ACTION_META[action] || {
      label: action,
      icon: 'QuestionMarkCircleIcon',
      badge: 'bg-slate-50 text-slate-700 border-slate-300',
      color: 'text-slate-600'
    }
  }

  if (loading) {
    return (
      <div className="flex items-center justify-center py-3 text-xs text-slate-400">
        <HeroIcons.ArrowPathIcon className="w-3.5 h-3.5 animate-spin mr-1.5" />
        Loading change history...
      </div>
    )
  }

  if (error) {
    return (
      <div className="text-xs text-rose-600 bg-rose-50 border border-rose-200 rounded-md px-2.5 py-2 flex items-start gap-1.5">
        <HeroIcons.ExclamationTriangleIcon className="w-3.5 h-3.5 flex-shrink-0 mt-0.5" />
        <span>{error}</span>
      </div>
    )
  }

  if (changes.length === 0) {
    return (
      <div className="text-xs text-slate-400 italic py-2 px-2.5 bg-slate-50/50 rounded-md border border-slate-100">
        {INLINE_CHANGE_HISTORY.EMPTY_MESSAGE}
      </div>
    )
  }

  const displayedChanges = expanded ? changes : changes.slice(0, displayLimit)
  const hasMore = changes.length > displayLimit && !expanded

  return (
    <div className="mt-2 border border-slate-200 rounded-lg overflow-hidden bg-slate-50/30">
      {/* Header */}
      <div className="px-2.5 py-1.5 bg-slate-100/50 border-b border-slate-200 flex items-center justify-between">
        <div className="flex items-center gap-1.5 text-[10px] uppercase font-semibold text-slate-600">
          <HeroIcons.ClockIcon className="w-3 h-3" />
          Change History
          <span className="inline-flex items-center justify-center min-w-[16px] h-4 px-1 rounded-full bg-slate-200 text-[9px] font-bold text-slate-700">
            {changes.length}
          </span>
        </div>
        {changes.length > 0 && (
          <button
            onClick={() => setExpanded(!expanded)}
            className="text-[10px] text-blue-600 hover:text-blue-700 font-medium flex items-center gap-0.5"
          >
            {expanded ? (
              <>
                <HeroIcons.ChevronUpIcon className="w-3 h-3" />
                Show Less
              </>
            ) : (
              <>
                <HeroIcons.ChevronDownIcon className="w-3 h-3" />
                Show All
              </>
            )}
          </button>
        )}
      </div>

      {/* Changes Table */}
      <div className="divide-y divide-slate-100">
        {displayedChanges.map((change) => {
          const meta = getActionMeta(change.action)
          const Icon = HeroIcons[meta.icon] || HeroIcons.QuestionMarkCircleIcon

          return (
            <div key={change.id} className="px-2.5 py-2 hover:bg-white/60 transition-colors">
              <div className="flex items-start gap-2">
                {/* Icon & Badge */}
                <div className="flex-shrink-0 mt-0.5">
                  <Icon className={`w-3.5 h-3.5 ${meta.color}`} />
                </div>

                {/* Content */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2 mb-1">
                    <span className={`inline-flex items-center px-1.5 py-0.5 rounded text-[9px] font-semibold border ${meta.badge}`}>
                      {meta.label}
                    </span>
                    <span className="text-[10px] font-medium text-slate-700 truncate">
                      {getDisplayValue(change, 'label')}
                    </span>
                    {change.action === CHANGE_LOG_ACTION.UPDATED && (
                      <span className="text-[10px] text-slate-500">
                        {formatCurrency(change.old_values?.amount || 0, { withSymbol: false })}
                        {' → '}
                        {formatCurrency(change.new_values?.amount || 0, { withSymbol: false })}
                      </span>
                    )}
                    {change.action === CHANGE_LOG_ACTION.CREATED && (
                      <span className="text-[10px] text-emerald-600 font-medium">
                        +{formatCurrency(change.new_values?.amount || 0, { withSymbol: false })}
                      </span>
                    )}
                    {change.action === CHANGE_LOG_ACTION.DELETED && (
                      <span className="text-[10px] text-rose-600 font-medium line-through">
                        {formatCurrency(change.old_values?.amount || 0, { withSymbol: false })}
                      </span>
                    )}
                  </div>

                  {/* Actor & Timestamp */}
                  {(INLINE_CHANGE_HISTORY.SHOW_ACTOR || INLINE_CHANGE_HISTORY.SHOW_TIMESTAMP) && (
                    <div className="flex items-center gap-2 text-[10px] text-slate-500">
                      {INLINE_CHANGE_HISTORY.SHOW_ACTOR && (
                        <span className="flex items-center gap-1">
                          <HeroIcons.UserIcon className="w-3 h-3" />
                          {change.actor_name || 'System'}
                        </span>
                      )}
                      {INLINE_CHANGE_HISTORY.SHOW_TIMESTAMP && (
                        <span className="flex items-center gap-1">
                          <HeroIcons.ClockIcon className="w-3 h-3" />
                          {formatDateTime(change.at)}
                        </span>
                      )}
                    </div>
                  )}

                  {/* Description (if changed) */}
                  {change.action === CHANGE_LOG_ACTION.UPDATED && 
                   change.old_values?.description !== change.new_values?.description && (
                    <div className="mt-1 text-[10px] text-slate-600">
                      <span className="line-through text-slate-400">{change.old_values?.description || 'No description'}</span>
                      {' → '}
                      <span>{change.new_values?.description || 'No description'}</span>
                    </div>
                  )}
                </div>
              </div>
            </div>
          )
        })}
      </div>

      {/* Load More Button */}
      {hasMore && (
        <div className="px-2.5 py-2 bg-slate-50 border-t border-slate-200">
          <button
            onClick={() => setDisplayLimit(prev => prev + INLINE_CHANGE_HISTORY.EXPAND_INCREMENT)}
            className="w-full text-[10px] text-blue-600 hover:text-blue-700 font-medium flex items-center justify-center gap-1"
          >
            <HeroIcons.ChevronDownIcon className="w-3 h-3" />
            Load {Math.min(INLINE_CHANGE_HISTORY.EXPAND_INCREMENT, changes.length - displayLimit)} More
          </button>
        </div>
      )}
    </div>
  )
}

import React from 'react'
import { MONTH_NAMES } from '../../../../config/payrollEngine.config'

const currentYear = new Date().getFullYear()
const YEAR_OPTIONS = Array.from({ length: 6 }, (_, i) => currentYear - 2 + i)

