import { radaiConfirm } from '../../../../services/radaiDialog'
import React, { useEffect, useState } from 'react'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService, { downloadBlob } from '../../../../services/payrollEngine.service'
import { formatCurrency, FIXED_EARNING_FIELDS, ATTENDANCE_LEAVE_FIELDS, PAYSLIP_EMPLOYEE_INFO_FIELDS } from '../../../../config/payrollEngine.config'
import InlineChangeHistory from './InlineChangeHistory'

export default function PayslipDetailModal({ slip: initialSlip, runEditable, onClose, onChanged }) {
  // Local mirror of the payslip so basic/housing/transport/home_leave/totals
  // re-render the moment a PATCH succeeds without waiting for the parent reload.
  const [slip, setSlip] = useState(initialSlip)
  const [items, setItems] = useState(initialSlip.line_items || [])
  const [editing, setEditing] = useState(null)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState(null)
  const [savingField, setSavingField] = useState(null)
  // Catalog for department/designation dropdowns
  const [catalog, setCatalog] = useState(null)
  // Refresh key to trigger change history reload
  const [refreshKey, setRefreshKey] = useState(0)

  useEffect(() => {
    payrollEngineService.getCatalog()
      .then(setCatalog)
      .catch(() => setCatalog({}))
  }, [])

  useEffect(() => {
    setSlip(initialSlip)
    setItems(initialSlip.line_items || [])
  }, [initialSlip])

  const refresh = async () => {
    try {
      const fresh = await payrollEngineService.getPayslip(slip.id)
      setSlip(fresh)
      setItems(fresh.line_items || [])
      setRefreshKey(prev => prev + 1)  // Trigger change history reload
      onChanged?.()
    } catch (e) { setError(e?.response?.data?.error || e.message) }
  }

  const handleDelete = async (id) => {
    if (!(await radaiConfirm('Delete this line item?'))) return
    setBusy(true); setError(null)
    try {
      await payrollEngineService.deleteLineItem(id)
      await refresh()
    } catch (e) { setError(e?.response?.data?.error || e.message) }
    finally { setBusy(false) }
  }

  const handleSave = async (item) => {
    setBusy(true); setError(null)
    try {
      if (item.id) {
        await payrollEngineService.updateLineItem(item.id, item)
      } else {
        await payrollEngineService.createLineItem({ ...item, payslip: slip.id })
      }
      setEditing(null)
      await refresh()
    } catch (e) { setError(e?.response?.data?.error || e.message) }
    finally { setBusy(false) }
  }

  const handleFixedEarningChange = async (field, rawValue) => {
    const value = rawValue === '' || rawValue == null ? 0 : Number(rawValue)
    if (Number.isNaN(value) || value < 0) {
      setError(`${field} must be a non-negative number.`)
      return
    }
    if (Number(slip[field] ?? 0) === value) return
    setSavingField(field); setError(null)
    try {
      const updated = await payrollEngineService.updatePayslip(slip.id, { [field]: value })
      setSlip(updated)
      setItems(updated.line_items || items)
      onChanged?.()
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
      await refresh()
    } finally {
      setSavingField(null)
    }
  }

  const handleDownload = async () => {
    try {
      const blob = await payrollEngineService.downloadPayslipXlsx(slip.id)
      downloadBlob(blob, `payslip_${slip.employee_no}_${slip.run_cycle}.xlsx`)
    } catch (e) { setError(e?.response?.data?.error || e.message) }
  }

  const earnings = items.filter(i => i.kind === 'earning')
  const deductions = items.filter(i => i.kind === 'deduction')

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 p-4 overflow-y-auto">
      <div className="bg-white rounded-2xl shadow-xl max-w-3xl w-full my-8">
        <div className="p-5 border-b border-slate-200 flex items-center justify-between">
          <div>
            <h3 className="text-lg font-semibold text-slate-800">{slip.snapshot_full_name}</h3>
            <p className="text-xs text-slate-500">
              Emp #{slip.employee_no} · {slip.snapshot_department} · {slip.run_cycle}
              {!runEditable && (
                <span className="ml-2 inline-block px-1.5 py-0.5 text-[10px] rounded-full bg-slate-100 text-slate-500 border border-slate-300">
                  Read-only — run is {slip.run_status}
                </span>
              )}
            </p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={handleDownload}
              className="inline-flex items-center gap-1 px-3 py-1.5 text-xs font-medium rounded-md border border-slate-300 hover:bg-slate-50"
            >
              <HeroIcons.ArrowDownTrayIcon className="w-4 h-4" /> Download
            </button>
            <button
              onClick={onClose}
              className="p-1.5 hover:bg-slate-100 rounded-md"
            >
              <HeroIcons.XMarkIcon className="w-5 h-5 text-slate-500" />
            </button>
          </div>
        </div>

        <div className="p-5">
          {/* Attendance & Leave — editable when run is Draft */}
          <div className="mb-5">
            <h4 className="text-xs font-semibold text-slate-500 uppercase mb-2 flex items-center gap-1.5">
              <HeroIcons.CalendarDaysIcon className="w-3.5 h-3.5" />
              Attendance &amp; Leave
            </h4>
            <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
              {ATTENDANCE_LEAVE_FIELDS.map(({ key, label, step }) => (
                <NumericTile
                  key={key}
                  fieldKey={key}
                  label={label}
                  step={step}
                  value={slip[key]}
                  editable={runEditable}
                  saving={savingField === key}
                  onCommit={(val) => handleFixedEarningChange(key, val)}
                />
              ))}
            </div>
          </div>

          {/* Employee Info — joining date, department, designation */}
          <div className="mb-5">
            <h4 className="text-xs font-semibold text-slate-500 uppercase mb-2 flex items-center gap-1.5">
              <HeroIcons.UserCircleIcon className="w-3.5 h-3.5" />
              Employee Info
              <span className="text-[9px] font-normal normal-case text-slate-400 ml-1">changes sync to Employees tab</span>
            </h4>
            <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
              {PAYSLIP_EMPLOYEE_INFO_FIELDS.map(({ key, label, type, optionsFrom }) => (
                <InfoTile
                  key={key}
                  fieldKey={key}
                  label={label}
                  fieldType={type}
                  suggestions={optionsFrom && catalog?.[optionsFrom] ? catalog[optionsFrom] : []}
                  value={slip[key]}
                  editable={runEditable}
                  saving={savingField === key}
                  onCommit={(val) => handleFixedEarningChange(key, val)}
                />
              ))}
            </div>
          </div>

          {/* Fixed earnings — inline editable when run is in Draft */}
          <div className="mb-1">
            <h4 className="text-xs font-semibold text-slate-500 uppercase mb-2 flex items-center gap-1.5">
              <HeroIcons.BanknotesIcon className="w-3.5 h-3.5" />
              Salary Components
            </h4>
          </div>
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-5">
            {FIXED_EARNING_FIELDS.map(({ key, label }) => (
              <FixedEarningTile
                key={key}
                fieldKey={key}
                label={label}
                value={slip[key]}
                editable={runEditable}
                saving={savingField === key}
                onCommit={(val) => handleFixedEarningChange(key, val)}
              />
            ))}
          </div>

          {/* Earnings */}
          <Section
            title="Other Earnings"
            items={earnings}
            kind="earning"
            payslipId={slip.id}
            refreshKey={refreshKey}
            editable={runEditable}
            onEdit={setEditing}
            onDelete={handleDelete}
            onAdd={() => setEditing({ kind: 'earning', label: '', description: '', amount: 0 })}
          />

          {/* Deductions */}
          <Section
            title="Deductions"
            items={deductions}
            kind="deduction"
            payslipId={slip.id}
            refreshKey={refreshKey}
            editable={runEditable}
            onEdit={setEditing}
            onDelete={handleDelete}
            onAdd={() => setEditing({ kind: 'deduction', label: '', description: '', amount: 0 })}
          />

          {/* Totals */}
          <div className="mt-5 grid grid-cols-3 gap-3">
            <div className="bg-slate-50 border border-slate-200 rounded-lg p-3">
              <div className="text-[10px] uppercase text-slate-500">Gross Earnings</div>
              <div className="text-base font-semibold tabular-nums">{formatCurrency(slip.gross_earnings)}</div>
            </div>
            <div className="bg-slate-50 border border-slate-200 rounded-lg p-3">
              <div className="text-[10px] uppercase text-slate-500">Total Deductions</div>
              <div className="text-base font-semibold tabular-nums">{formatCurrency(slip.total_deductions)}</div>
            </div>
            <div className="bg-emerald-50 border border-emerald-200 rounded-lg p-3">
              <div className="text-[10px] uppercase text-emerald-700">Net Payable</div>
              <div className="text-base font-semibold tabular-nums text-emerald-800">{formatCurrency(slip.net_payable)}</div>
            </div>
          </div>

          {error && (
            <div className="mt-3 text-xs text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2">
              {error}
            </div>
          )}
        </div>

        {editing && (
          <LineItemEditor
            item={editing}
            onSave={handleSave}
            onCancel={() => setEditing(null)}
            busy={busy}
          />
        )}
      </div>
    </div>
  )
}

/**
 * Inline-editable tile for a fixed earning column on the Payslip model.
 * Saves on blur or Enter; resets on Escape; shows a tiny spinner while busy.
 */
function FixedEarningTile({ fieldKey, label, value, editable, saving, onCommit }) {
  const initial = value == null ? '0' : String(value)
  const [draft, setDraft] = useState(initial)

  useEffect(() => { setDraft(initial) }, [initial])

  if (!editable) {
    return (
      <div className="bg-slate-50 border border-slate-200 rounded-lg p-2.5">
        <div className="text-[10px] uppercase text-slate-500">{label}</div>
        <div className="text-sm font-semibold tabular-nums">
          {formatCurrency(value, { withSymbol: false })}
        </div>
      </div>
    )
  }

  const commit = () => onCommit(draft)

  return (
    <div className="bg-white border border-slate-300 rounded-lg p-2.5 focus-within:border-indigo-400 focus-within:ring-1 focus-within:ring-indigo-200">
      <div className="flex items-center justify-between">
        <span className="text-[10px] uppercase text-slate-500">{label}</span>
        {saving && (
          <HeroIcons.ArrowPathIcon className="w-3 h-3 text-indigo-500 animate-spin" />
        )}
      </div>
      <input
        type="number"
        step="0.01"
        min="0"
        value={draft}
        disabled={saving}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={commit}
        onKeyDown={(e) => {
          if (e.key === 'Enter') { e.preventDefault(); e.currentTarget.blur() }
          if (e.key === 'Escape') { setDraft(initial); e.currentTarget.blur() }
        }}
        className="mt-0.5 w-full text-sm font-semibold tabular-nums bg-transparent border-0 p-0 focus:outline-none focus:ring-0"
      />
    </div>
  )
}

/**
 * Inline-editable tile for numeric (non-monetary) payslip fields:
 * hours, public_holiday_days, annual_leave_days, unpaid_leave_days.
 * Mirrors FixedEarningTile but displays plain numbers without currency formatting.
 * step controls keyboard ↑/↓ increment (e.g. '1' for whole days, '0.5' for half-days).
 */
function NumericTile({ fieldKey, label, step = '1', value, editable, saving, onCommit }) {
  const initial = value == null ? '0' : String(value)
  const [draft, setDraft] = useState(initial)

  useEffect(() => { setDraft(initial) }, [initial])

  const fmt = (v) => {
    const n = Number(v)
    return Number.isNaN(n) ? '0' : n % 1 === 0 ? String(n) : n.toFixed(2)
  }

  if (!editable) {
    return (
      <div className="bg-slate-50 border border-slate-200 rounded-lg p-2.5">
        <div className="text-[10px] uppercase text-slate-500">{label}</div>
        <div className="text-sm font-semibold tabular-nums">{fmt(value)}</div>
      </div>
    )
  }

  const commit = () => onCommit(draft)

  return (
    <div className="bg-white border border-indigo-200 rounded-lg p-2.5 focus-within:border-indigo-400 focus-within:ring-1 focus-within:ring-indigo-200">
      <div className="flex items-center justify-between">
        <span className="text-[10px] uppercase text-slate-500">{label}</span>
        {saving && <HeroIcons.ArrowPathIcon className="w-3 h-3 text-indigo-500 animate-spin" />}
      </div>
      <input
        type="number"
        step={step}
        min="0"
        value={draft}
        disabled={saving}
        onChange={(e) => setDraft(e.target.value)}
        onBlur={commit}
        onKeyDown={(e) => {
          if (e.key === 'Enter') { e.preventDefault(); e.currentTarget.blur() }
          if (e.key === 'Escape') { setDraft(initial); e.currentTarget.blur() }
        }}
        className="mt-0.5 w-full text-sm font-semibold tabular-nums bg-transparent border-0 p-0 focus:outline-none focus:ring-0"
      />
    </div>
  )
}

/**
 * Editable tile for snapshot employee-info fields (date, text, datalist).
 * Saves on blur/Enter; shows suggestions from catalog for datalist type.
 */
function InfoTile({ fieldKey, label, fieldType, suggestions = [], value, editable, saving, onCommit }) {
  const initial = value == null ? '' : String(value).slice(0, 10) // trim date if needed
  const [draft, setDraft] = useState(initial)
  const listId = `info-${fieldKey}-list`

  useEffect(() => { setDraft(value == null ? '' : String(value).slice(0, 10)) }, [value])

  if (!editable) {
    return (
      <div className="bg-slate-50 border border-slate-200 rounded-lg p-2.5">
        <div className="text-[10px] uppercase text-slate-500">{label}</div>
        <div className="text-sm font-medium text-slate-700 truncate">{value || '—'}</div>
      </div>
    )
  }

  const commit = () => { if (draft !== initial) onCommit(draft) }

  const inputCls = 'mt-0.5 w-full text-sm text-slate-800 bg-transparent border-0 p-0 focus:outline-none focus:ring-0'

  return (
    <div className="bg-white border border-violet-200 rounded-lg p-2.5 focus-within:border-violet-400 focus-within:ring-1 focus-within:ring-violet-200">
      <div className="flex items-center justify-between">
        <span className="text-[10px] uppercase text-slate-500">{label}</span>
        {saving && <HeroIcons.ArrowPathIcon className="w-3 h-3 text-violet-500 animate-spin" />}
      </div>
      {fieldType === 'date' ? (
        <input type="date" value={draft} disabled={saving}
          onChange={(e) => setDraft(e.target.value)} onBlur={commit}
          onKeyDown={(e) => { if (e.key === 'Enter') e.currentTarget.blur() }}
          className={inputCls} />
      ) : fieldType === 'datalist' ? (
        <>
          <input type="text" list={listId} value={draft} disabled={saving}
            placeholder="Type or select…"
            onChange={(e) => setDraft(e.target.value)} onBlur={commit}
            onKeyDown={(e) => { if (e.key === 'Enter') e.currentTarget.blur() }}
            className={inputCls} />
          <datalist id={listId}>
            {suggestions.map((s) => <option key={s} value={s} />)}
          </datalist>
        </>
      ) : (
        <input type="text" value={draft} disabled={saving}
          onChange={(e) => setDraft(e.target.value)} onBlur={commit}
          onKeyDown={(e) => { if (e.key === 'Enter') e.currentTarget.blur() }}
          className={inputCls} />
      )}
    </div>
  )
}

function Section({ title, items, kind, payslipId, refreshKey, editable, onEdit, onDelete, onAdd }) {
  return (
    <div className="mb-4">
      <div className="flex items-center justify-between mb-1.5">
        <h4 className="text-xs font-semibold text-slate-600 uppercase">{title}</h4>
        {editable && (
          <button
            type="button"
            onClick={onAdd}
            className="text-xs text-blue-600 hover:underline inline-flex items-center gap-1"
          >
            <HeroIcons.PlusCircleIcon className="w-3.5 h-3.5" /> Add
          </button>
        )}
      </div>
      {items.length === 0 ? (
        <p className="text-xs text-slate-400 italic">No {title.toLowerCase()}.</p>
      ) : (
        <table className="w-full text-xs">
          <tbody className="divide-y divide-slate-100">
            {items.map((it) => (
              <tr key={it.id} className="hover:bg-slate-50">
                <td className="px-2 py-1.5 w-40 font-medium">{it.label}</td>
                <td className="px-2 py-1.5 text-slate-500">{it.description || '—'}</td>
                <td className="px-2 py-1.5 text-right tabular-nums w-32">{formatCurrency(it.amount, { withSymbol: false })}</td>
                {editable && (
                  <td className="px-2 py-1.5 text-right w-20">
                    <button onClick={() => onEdit(it)} className="text-slate-400 hover:text-blue-600 mr-1">
                      <HeroIcons.PencilSquareIcon className="w-3.5 h-3.5 inline" />
                    </button>
                    <button onClick={() => onDelete(it.id)} className="text-slate-400 hover:text-red-600">
                      <HeroIcons.TrashIcon className="w-3.5 h-3.5 inline" />
                    </button>
                  </td>
                )}
              </tr>
            ))}
          </tbody>
        </table>
      )}
      
      {/* Inline Change History */}
      {payslipId && (
        <InlineChangeHistory key={refreshKey} payslipId={payslipId} kind={kind} />
      )}
    </div>
  )
}

function LineItemEditor({ item, onSave, onCancel, busy }) {
  const [form, setForm] = useState({
    kind: item.kind,
    component_code: item.component_code || (item.kind === 'earning' ? 'other_earning' : 'other_deduction'),
    label: item.label || '',
    description: item.description || '',
    amount: item.amount || '0',
    id: item.id,
  })
  return (
    <div className="border-t border-slate-200 p-5 bg-slate-50">
      <h4 className="text-sm font-semibold mb-2.5">
        {item.id ? 'Edit' : 'Add'} {item.kind === 'earning' ? 'Earning' : 'Deduction'}
      </h4>
      <div className="grid grid-cols-2 gap-3">
        <div>
          <label className="block text-xs text-slate-600 mb-1">Label</label>
          <input
            type="text"
            value={form.label}
            onChange={(e) => setForm({ ...form, label: e.target.value })}
            className="w-full text-sm border border-slate-300 rounded-md px-2 py-1.5"
          />
        </div>
        <div>
          <label className="block text-xs text-slate-600 mb-1">Amount (AED)</label>
          <input
            type="number"
            step="0.01"
            value={form.amount}
            onChange={(e) => setForm({ ...form, amount: e.target.value })}
            className="w-full text-sm border border-slate-300 rounded-md px-2 py-1.5 tabular-nums"
          />
        </div>
        <div className="col-span-2">
          <label className="block text-xs text-slate-600 mb-1">Description</label>
          <input
            type="text"
            value={form.description}
            onChange={(e) => setForm({ ...form, description: e.target.value })}
            className="w-full text-sm border border-slate-300 rounded-md px-2 py-1.5"
          />
        </div>
      </div>
      <div className="flex justify-end gap-2 mt-3">
        <button
          onClick={onCancel}
          disabled={busy}
          className="px-3 py-1.5 text-xs font-medium rounded-md border border-slate-300 hover:bg-slate-100"
        >
          Cancel
        </button>
        <button
          onClick={() => onSave(form)}
          disabled={busy}
          className="px-3 py-1.5 text-xs font-medium rounded-md bg-blue-600 text-white hover:bg-blue-700 disabled:opacity-50"
        >
          {busy ? 'Saving…' : 'Save'}
        </button>
      </div>
    </div>
  )
}

import { radaiConfirm, radaiAlert } from '../../../../services/radaiDialog'
import React, { useEffect, useState, useMemo, useRef } from 'react'
import { useSelector } from 'react-redux'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService, { downloadBlob } from '../../../../services/payrollEngine.service'
import {
  formatCurrency, formatNumber, getPayslipColumns, WORKFLOW_STATUS, STATUS_LABEL,
  canForcePayrollRun, getCanvasMode, TABLE_SIZE_CLASSES,
} from '../../../../config/payrollEngine.config'
import StatusBadge from './StatusBadge'
import PayslipDetailModal from './PayslipDetailModal'
import BulkDeductionModal from './BulkDeductionModal'
import PayrollApprovalDialog from './PayrollApprovalDialog'
import ComparisonPanel from './ComparisonPanel'
import ExternalUploadPanel from './ExternalUploadPanel'
import './payrollTable.css'
import { payrollApprovalTransitions } from '../../../../utils/approvalCapabilities'

function formatDateTime(iso) {
  if (!iso) return '—'
  try {
    return new Date(iso).toLocaleString('en-AE', {
      year: 'numeric', month: 'short', day: '2-digit',
      hour: '2-digit', minute: '2-digit',
    })
  } catch { return iso }
}

function formatDate(iso) {
  if (!iso) return '—'
  try {
    return new Date(iso).toLocaleDateString('en-AE', {
      year: 'numeric', month: 'short', day: '2-digit',
    })
  } catch { return iso }
}

const TONE_CLASS = {
  blue:  'bg-blue-600 hover:bg-blue-700 text-white',
  amber: 'bg-amber-600 hover:bg-amber-700 text-white',
  green: 'bg-emerald-600 hover:bg-emerald-700 text-white',
  gray:  'bg-slate-100 hover:bg-slate-200 text-slate-700',
}

export default function RunDetail({ runId, onBack, canvasModeKey }) {
  const payslipColumns = useMemo(() => getPayslipColumns(canvasModeKey), [canvasModeKey])
  const canvasMode = useMemo(() => getCanvasMode(canvasModeKey), [canvasModeKey])
  const tableSizeClasses = useMemo(() => TABLE_SIZE_CLASSES[canvasMode.tableSize] || TABLE_SIZE_CLASSES.normal, [canvasMode])
  const tableContainerRef = useRef(null)
  const [isScrolledToEnd, setIsScrolledToEnd] = useState(false)
  const authUser = useSelector((s) => s.auth?.user)
  const rbacUser = useSelector((s) => s.rbac?.currentUser)
  const canForce = useMemo(
    () => canForcePayrollRun(authUser, rbacUser),
    [authUser, rbacUser],
  )
  const [run, setRun] = useState(null)
  const [payslips, setPayslips] = useState([])
  const [workflowLog, setWorkflowLog] = useState([])
  const [loading, setLoading] = useState(true)
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState(null)
  const [search, setSearch] = useState('')
  const [selectedSlip, setSelectedSlip] = useState(null)
  const [bulkOpen, setBulkOpen] = useState(false)
  const [approvalAction, setApprovalAction] = useState(null)
  const [showUploadPanel, setShowUploadPanel] = useState(false)
  const [deletingSlipId, setDeletingSlipId] = useState(null)
  const [compliance, setCompliance] = useState(null)
  const [paymentBatch, setPaymentBatch] = useState(null)
  const [accountingExport, setAccountingExport] = useState(null)

  const load = async () => {
    if (!runId) return
    setLoading(true)
    setError(null)
    try {
      const [r, slips, log] = await Promise.all([
        payrollEngineService.getRun(runId),
        payrollEngineService.listPayslips({ run: runId }),
        payrollEngineService.getRunWorkflowLog(runId),
      ])
      setRun(r)
      setPayslips(Array.isArray(slips) ? slips : (slips?.results ?? []))
      setWorkflowLog(Array.isArray(log) ? log : (log?.results ?? []))
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setLoading(false)
    }
  }
  useEffect(() => { load() /* eslint-disable-next-line */ }, [runId])

  const filtered = useMemo(() => {
    if (!search.trim()) return payslips
    const q = search.toLowerCase()
    return payslips.filter((p) =>
      (p.snapshot_full_name || '').toLowerCase().includes(q) ||
      (p.employee_no || '').toLowerCase().includes(q) ||
      (p.snapshot_department || '').toLowerCase().includes(q)
    )
  }, [payslips, search])

  // Track horizontal scroll to show/hide fade overlay
  useEffect(() => {
    const container = tableContainerRef.current
    if (!container) return

    const handleScroll = () => {
      const { scrollLeft, scrollWidth, clientWidth } = container
      const scrolledToEnd = scrollLeft + clientWidth >= scrollWidth - 10
      setIsScrolledToEnd(scrolledToEnd)
    }

    container.addEventListener('scroll', handleScroll)
    handleScroll() // Initial check

    return () => container.removeEventListener('scroll', handleScroll)
  }, [payslips, canvasMode])

  const handleTransition = async (note) => {
    const current = await payrollEngineService.getRun(run.id)
    setRun(current)
    if (!payrollApprovalTransitions(current).some(action => action.fn === approvalAction?.fn)) {
      setApprovalAction(null)
      setError('This approval is no longer available to you at the current stage.')
      return
    }
    try {
      await payrollEngineService[approvalAction.fn](run.id, note)
      setApprovalAction(null)
    } finally {
      await load()
    }
  }

  const handleRevert = async () => {
    if (!(await radaiConfirm('Revert this run back to Draft?'))) return
    setBusy(true); setError(null)
    try {
      await payrollEngineService.revertRun(run.id, 'Reverted by user')
      await load()
    } catch (e) { setError(e?.response?.data?.error || e.message) }
    finally { setBusy(false) }
  }

  const handleDownloadMaster = async () => {
    try {
      const blob = await payrollEngineService.downloadRunMasterXlsx(run.id)
      downloadBlob(blob, `payroll_master_${run.cycle_code}.xlsx`)
    } catch (e) { setError(e?.response?.data?.error || e.message) }
  }

  const handleRefreshHours = async () => {
    const isDraft = run.status === WORKFLOW_STATUS.DRAFT
    const force = !isDraft
    const msg = isDraft
      ? `Pull live "Total" hours from the Time Sheet Summary for ${run.cycle_code}?\n\n`
        + 'Each payslip’s Hours column will be replaced with the biometric '
        + 'total (with HR overrides overlaid).'
      : `⚠️ FORCE-REFRESH HOURS on a ${run.status.toUpperCase()} run?\n\n`
        + `Run ${run.cycle_code} is already approved. Super-Admin override required.\n\n`
        + 'This rewrites each payslip’s Hours column with the live biometric total. '
        + 'Totals, gross and net are not recomputed (Hours is informational only).\n\n'
        + 'Proceed?'
    if (!(await radaiConfirm(msg))) return
    setBusy(true); setError(null)
    try {
      const result = await payrollEngineService.refreshRunHoursFromTimesheet(run.id, { force })
      await load()
      const missing = (result?.missing || []).length
      ;(await radaiAlert(
        `Hours refreshed from Time Sheet${result?.forced ? ' (FORCED)' : ''}.\n\n`
        + `Updated: ${result?.updated ?? 0}\n`
        + `Unchanged: ${result?.unchanged ?? 0}\n`
        + (missing ? `Missing biometric data: ${missing} employee(s)` : 'All employees matched.')
      ))
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally { setBusy(false) }
  }

  const handleDownloadPack = async () => {
    try {
      const blob = await payrollEngineService.downloadRunPayslipPack(run.id)
      downloadBlob(blob, `payroll_payslips_${run.cycle_code}.xlsx`)
    } catch (e) { setError(e?.response?.data?.error || e.message) }
  }

  const runCompliance = async () => {
    setBusy(true); setError(null)
    try { setCompliance(await payrollEngineService.runComplianceCheck(run.id)) }
    catch (e) { setError(e?.response?.data?.error || e.message) }
    finally { setBusy(false) }
  }

  const generatePayment = async (batchType) => {
    setBusy(true); setError(null)
    try { setPaymentBatch(await payrollEngineService.generatePaymentBatch(run.id, batchType)) }
    catch (e) { setError(e?.response?.data?.error || e.message) }
    finally { setBusy(false) }
  }

  const downloadPayment = async () => {
    try {
      const type = paymentBatch?.batch_type || 'wps'
      downloadBlob(await payrollEngineService.downloadPaymentFile(run.id, type), `${type}_${run.cycle_code}.csv`)
    } catch (e) { setError(e?.response?.data?.error || e.message) }
  }

  const generateJournal = async () => {
    setBusy(true); setError(null)
    try { setAccountingExport(await payrollEngineService.generateAccountingExport(run.id, 'generic')) }
    catch (e) { setError(e?.response?.data?.error || e.message) }
    finally { setBusy(false) }
  }

  const downloadJournal = async () => {
    try { downloadBlob(await payrollEngineService.downloadAccountingFile(run.id, accountingExport?.target_system || 'generic'), `payroll_journal_${run.cycle_code}.csv`) }
    catch (e) { setError(e?.response?.data?.error || e.message) }
  }

  const handleDeleteSlip = async (slip) => {
    const label = slip.snapshot_full_name || `payslip #${slip.id}`
    const msg = `Delete payslip for ${label}?\n\nUse this when an employee is terminated or no longer on payroll. This cannot be undone.`
    if (!(await radaiConfirm(msg))) return
    setDeletingSlipId(slip.id); setError(null)
    try {
      await payrollEngineService.deletePayslip(slip.id)
      // Optimistic removal so the row disappears immediately, then full reload
      setPayslips((prev) => prev.filter((s) => s.id !== slip.id))
      await load()
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setDeletingSlipId(null)
    }
  }

  if (loading) return <div className="p-8 text-center text-sm text-slate-400">Loading run…</div>
  if (!run) return (
    <div className="p-8 text-center text-sm text-slate-400">
      Run not found.
      <button onClick={onBack} className="ml-2 text-blue-600 hover:underline">Back to list</button>
    </div>
  )

  const availableTransitions = payrollApprovalTransitions(run)

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="bg-white border border-slate-200 rounded-xl p-4">
        <div className="flex items-start justify-between flex-wrap gap-3">
          <div>
            <button
              onClick={onBack}
              className="text-xs text-slate-500 hover:text-slate-800 inline-flex items-center gap-1 mb-2"
            >
              <HeroIcons.ChevronLeftIcon className="w-3.5 h-3.5" /> All runs
            </button>
            <h2 className="text-xl font-semibold text-slate-800 flex items-center gap-2">
              Payroll Run {run.cycle_code} <StatusBadge status={run.status} />
            </h2>
            <p className="text-xs text-slate-500 mt-1">
              {run.employee_count} payslips · generated {formatDateTime(run.generated_at)}
            </p>
          </div>
          <div className="flex flex-wrap gap-2">
        <IntegrationCard icon="ShieldCheckIcon" title="Payroll Compliance" subtitle="UAE identity, banking, net-pay and reconciliation controls">
          {compliance && <ResultBadge tone={compliance.status === 'failed' ? 'red' : compliance.status === 'warning' ? 'amber' : 'green'}>{compliance.status} · {compliance.error_count} errors · {compliance.warning_count} warnings</ResultBadge>}
          <button disabled={busy} onClick={runCompliance} className="mt-3 w-full rounded-md bg-blue-600 px-3 py-2 text-xs font-semibold text-white disabled:opacity-50">Run compliance check</button>
        </IntegrationCard>
        {['wps', 'bank'].map((type) => (
          <IntegrationCard key={type} icon={type === 'wps' ? 'CreditCardIcon' : 'BuildingLibraryIcon'} title={type === 'wps' ? 'WPS' : 'Banking'}>
            {paymentBatch?.batch_type === type && <ResultBadge tone={paymentBatch.validation_errors?.length ? 'red' : 'green'}>{paymentBatch.record_count} records / {paymentBatch.status}</ResultBadge>}
            <div className="mt-3 flex gap-2">
              <button disabled={busy} onClick={() => generatePayment(type)} className="flex-1 rounded-md bg-indigo-600 px-3 py-2 text-xs font-semibold text-white disabled:opacity-40">Generate</button>
              <button disabled={paymentBatch?.batch_type !== type || paymentBatch?.status === 'draft'} onClick={downloadPayment} className="flex-1 rounded-md border border-slate-300 px-3 py-2 text-xs font-semibold disabled:opacity-40">Export</button>
            </div>
          </IntegrationCard>
        ))}
        <IntegrationCard icon="CalculatorIcon" title="Accounting Journal" subtitle="Balanced payroll journal for Dynamics, SAP, Oracle or CSV">
          {accountingExport && <ResultBadge tone={accountingExport.total_debit === accountingExport.total_credit ? 'green' : 'red'}>{accountingExport.reference} · {accountingExport.status}</ResultBadge>}
          <div className="mt-3 grid grid-cols-2 gap-2"><button disabled={busy} onClick={generateJournal} className="rounded-md bg-emerald-600 px-2 py-2 text-xs font-semibold text-white">Generate</button><button disabled={!accountingExport} onClick={downloadJournal} className="rounded-md border border-slate-300 px-2 py-2 text-xs font-semibold disabled:opacity-40">Export CSV</button></div>
        </IntegrationCard>

            {run.status === WORKFLOW_STATUS.DRAFT && (
              <button
                onClick={() => setBulkOpen(true)}
                disabled={busy}
                title="Apply a percentage-based salary deduction across all employees in this run"
                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md bg-violet-600 hover:bg-violet-700 text-white disabled:opacity-50"
              >
                <HeroIcons.ReceiptPercentIcon className="w-4 h-4" />
                Deduction
              </button>
            )}
            {/* Quick upload buttons in header — trigger the ExternalUploadPanel below */}
            {run.status === WORKFLOW_STATUS.DRAFT && (
              <button
                onClick={() => setShowUploadPanel(true)}
                title="Import ValueFrame or Sympa XLSX to update hours & salary data"
                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md border border-blue-300 bg-blue-50 text-blue-700 hover:bg-blue-100"
              >
                <HeroIcons.ArrowUpTrayIcon className="w-4 h-4" />
                Import Files
              </button>
            )}
            {availableTransitions.map((b) => (
              <button
                key={b.status}
                disabled={busy}
                onClick={() => setApprovalAction(b)}
                className={`inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md ${TONE_CLASS[b.tone]} disabled:opacity-50`}
              >
                <HeroIcons.CheckCircleIcon className="w-4 h-4" />
                {b.label}
              </button>
            ))}
            {run.status !== WORKFLOW_STATUS.DRAFT && run.status !== WORKFLOW_STATUS.RELEASED && (
              <button
                onClick={handleRevert}
                disabled={busy}
                className={`inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md ${TONE_CLASS.gray} disabled:opacity-50`}
              >
                <HeroIcons.ArrowUturnLeftIcon className="w-4 h-4" />
                Revert to Draft
              </button>
            )}
            {run.status === WORKFLOW_STATUS.DRAFT && (
              <button
                onClick={handleRefreshHours}
                disabled={busy}
                title="Pull each payslip’s Hours column from the live Time Sheet Summary (biometric Total + HR overrides)"
                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md border border-sky-300 bg-sky-50 text-sky-700 hover:bg-sky-100 disabled:opacity-50"
              >
                <HeroIcons.ClockIcon className="w-4 h-4" />
                Refresh Hours
              </button>
            )}
            {run.status !== WORKFLOW_STATUS.DRAFT && canForce && (
              <button
                onClick={handleRefreshHours}
                disabled={busy}
                title="Super-Admin override — force-refresh Hours from the live Time Sheet on an approved run"
                className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md border border-amber-300 bg-amber-50 text-amber-700 hover:bg-amber-100 disabled:opacity-50"
              >
                <HeroIcons.ShieldExclamationIcon className="w-4 h-4" />
                Force Refresh Hours
              </button>
            )}
            <button
              onClick={handleDownloadMaster}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md border border-slate-300 hover:bg-slate-50"
            >
              <HeroIcons.ArrowDownTrayIcon className="w-4 h-4" />
              Master XLSX
            </button>
            <button
              onClick={handleDownloadPack}
              className="inline-flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium rounded-md border border-slate-300 hover:bg-slate-50"
            >
              <HeroIcons.DocumentDuplicateIcon className="w-4 h-4" />
              Payslip Pack
            </button>
          </div>
        </div>

        {error && (
          <div className="mt-3 text-xs text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2">
            {error}
          </div>
        )}
      </div>

      {/* Workflow log */}
      {workflowLog.length > 0 && (
        <div className="bg-white border border-slate-200 rounded-xl p-4">
          <h3 className="text-xs font-semibold text-slate-600 uppercase mb-2">Workflow Log</h3>
          <div className="space-y-1.5">
            {workflowLog.map((log) => (
              <div key={log.id} className="flex items-center gap-2 text-xs text-slate-600">
                <span className="text-slate-400 w-36">{formatDateTime(log.at)}</span>
                <StatusBadge status={log.from_status || WORKFLOW_STATUS.DRAFT} />
                <HeroIcons.ArrowRightIcon className="w-3 h-3 text-slate-400" />
                <StatusBadge status={log.to_status} />
                <span className="text-slate-500">by {log.actor_name || 'system'}</span>
                {log.note && <span className="italic text-slate-400">— {log.note}</span>}
              </div>
            ))}
          </div>
        </div>
      )}

      {/* External File Import — collapsible, shown right after KPI tiles */}
      {showUploadPanel && (
        <ExternalUploadPanel
          runId={run.id}
          runEditable={run.status === WORKFLOW_STATUS.DRAFT}
          onUploaded={() => { load(); }}
          onClose={() => setShowUploadPanel(false)}
        />
      )}

      {/* Payslip table */}
      <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
        <div className={`px-4 py-3 border-b border-slate-200 flex items-center justify-between flex-wrap gap-2 ${canvasMode.tableSize === 'ultra-compact' ? 'py-2' : ''}`}>
          <h3 className={`font-semibold text-slate-700 ${
            canvasMode.tableSize === 'ultra-compact' ? 'text-xs' : 'text-sm'
          }`}>
            Payslips ({filtered.length})
          </h3>
          <div className="flex items-center gap-2">
            <div className="relative">
              <HeroIcons.MagnifyingGlassIcon className="w-4 h-4 absolute left-2 top-1/2 -translate-y-1/2 text-slate-400" />
              <input
                type="text"
                placeholder="Search name / emp # / dept"
                value={search}
                onChange={(e) => setSearch(e.target.value)}
                className={`pl-7 pr-2 py-1.5 border border-slate-300 rounded-md ${
                  canvasMode.tableSize === 'ultra-compact' ? 'text-[10px] w-48' : 'text-xs w-64'
                }`}
              />
            </div>
          </div>
        </div>
        {/* Enhanced table container with smooth horizontal scroll and sticky columns */}
        <div
          ref={tableContainerRef}
          className={`payroll-table-container overflow-x-auto overflow-y-visible relative ${
            canvasMode.tableSize === 'ultra-compact' ? 'ultra-compact-table' : ''
          } ${isScrolledToEnd ? 'scrolled-to-end' : ''}`}
          style={{ maxHeight: 'calc(100vh - 320px)' }}
        >
          <div className="inline-block min-w-full align-middle">
            <div className="overflow-hidden">
              <table className={`${tableSizeClasses.minWidth} ${tableSizeClasses.text} border-collapse`}>
                <thead className="bg-slate-50 text-slate-500 uppercase sticky top-0 z-20 shadow-sm">
                  <tr>
                    {payslipColumns.map((c, idx) => (
                      <th
                        key={c.key}
                        style={{
                          width: c.width,
                          minWidth: c.width,
                          ...(idx === 0 ? { left: 0 } : {}),
                          ...(idx === 1 ? { left: payslipColumns[0]?.width || 90 } : {}),
                        }}
                        className={`${
                          tableSizeClasses.headerPadding
                        } font-medium border-b border-slate-200 ${
                          c.align === 'right' ? 'text-right' : c.align === 'center' ? 'text-center' : 'text-left'
                        } ${
                          // Make first two columns sticky for better navigation
                          idx === 0 || idx === 1
                            ? 'sticky bg-slate-50 z-10 shadow-[2px_0_4px_rgba(0,0,0,0.05)] payroll-sticky-col'
                            : ''
                        }`}
                        title={c.helpText || c.label}
                      >
                        {c.label}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 bg-white">
                  {filtered.map((p) => (
                    <tr
                      key={p.id}
                      className="hover:bg-slate-50 cursor-pointer transition-colors"
                      onClick={() => setSelectedSlip(p)}
                    >
                      {payslipColumns.map((c, idx) => {
                        if (c.action === 'edit') {
                          const editable = run.status === WORKFLOW_STATUS.DRAFT
                          return (
                            <td
                              key={c.key}
                              className={`${tableSizeClasses.cellPadding} text-center border-b border-slate-100`}
                              onClick={(e) => e.stopPropagation()}
                            >
                              <button
                                type="button"
                                onClick={() => setSelectedSlip(p)}
                                title={editable
                                  ? 'Edit salary, earnings & deductions'
                                  : `View payslip (read-only — run is ${run.status})`}
                                className={`inline-flex items-center gap-1 px-2 py-1 text-[11px] font-medium rounded-md border transition-colors ${
                                  editable
                                    ? 'border-indigo-200 bg-indigo-50 text-indigo-700 hover:bg-indigo-100'
                                    : 'border-slate-200 bg-slate-50 text-slate-600 hover:bg-slate-100'
                                }`}
                              >
                                {editable
                                  ? <HeroIcons.PencilSquareIcon className="w-3.5 h-3.5" />
                                  : <HeroIcons.EyeIcon className="w-3.5 h-3.5" />
                                }
                                {editable ? 'Edit' : 'View'}
                              </button>
                            </td>
                          )
                        }
                        if (c.action === 'delete') {
                          const editable = run.status === WORKFLOW_STATUS.DRAFT
                          const isDeleting = deletingSlipId === p.id
                          return (
                            <td
                              key={c.key}
                              className={`${tableSizeClasses.cellPadding} text-center border-b border-slate-100`}
                              onClick={(e) => e.stopPropagation()}
                            >
                              <button
                                type="button"
                                disabled={!editable || isDeleting}
                                onClick={() => handleDeleteSlip(p)}
                                title={editable
                                  ? `Delete payslip (e.g. terminated employee)`
                                  : `Deletion disabled — run is ${run.status}`}
                                className={`inline-flex items-center gap-1 px-2 py-1 text-[11px] font-medium rounded-md border transition-colors ${
                                  editable
                                    ? 'border-red-200 bg-red-50 text-red-700 hover:bg-red-100'
                                    : 'border-slate-200 bg-slate-50 text-slate-400 cursor-not-allowed'
                                } disabled:opacity-60`}
                              >
                                {isDeleting
                                  ? <HeroIcons.ArrowPathIcon className="w-3.5 h-3.5 animate-spin" />
                                  : <HeroIcons.TrashIcon className="w-3.5 h-3.5" />
                                }
                                Delete
                              </button>
                            </td>
                          )
                        }
                        const v = p[c.key]
                        let display
                        if (c.format === 'currency')      display = formatCurrency(v, { withSymbol: false })
                        else if (c.format === 'number')   display = formatNumber(v)
                        else if (c.format === 'date')     display = formatDate(v)
                        else if (c.format === 'datetime') display = formatDateTime(v)
                        else                              display = (v ?? '—')
                        
                        return (
                          <td
                            key={c.key}
                            title={c.key === 'snapshot_iban' && v ? v : c.helpText || undefined}
                            className={`${
                              tableSizeClasses.cellPadding
                            } border-b border-slate-100 ${
                              c.align === 'right' ? 'text-right tabular-nums' : c.align === 'center' ? 'text-center' : ''
                            } ${
                              c.key === 'snapshot_iban' ? 'font-mono text-slate-500' : ''
                            } ${
                              // Highlight new columns with subtle background
                              c.key === 'total_worked_days' || c.key === 'employee_category'
                                ? 'bg-indigo-50/30 new-column-highlight'
                                : ''
                            } ${
                              // Make first two columns sticky
                              idx === 0 || idx === 1
                                ? 'sticky bg-white z-10 shadow-[2px_0_4px_rgba(0,0,0,0.05)] payroll-sticky-col'
                                : ''
                            }`}
                            style={{
                              ...(idx === 0 ? { left: 0, minWidth: c.width, width: c.width } : {}),
                              ...(idx === 1 ? { left: payslipColumns[0]?.width || 90, minWidth: c.width, width: c.width } : {}),
                            }}
                          >
                            {display}
                          </td>
                        )
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      </div>

      {selectedSlip && (
        <PayslipDetailModal
          slip={selectedSlip}
          runEditable={run.status === WORKFLOW_STATUS.DRAFT}
          onClose={() => setSelectedSlip(null)}
          onChanged={async () => { await load() }}
        />
      )}

      {approvalAction && (
        <PayrollApprovalDialog
          action={approvalAction.label}
          cycle={run.cycle_code}
          onClose={() => setApprovalAction(null)}
          onConfirm={handleTransition}
        />
      )}
      {bulkOpen && (
        <BulkDeductionModal
          run={run}
          payslips={payslips}
          onClose={() => setBulkOpen(false)}
          onApplied={async () => { await load() }}
        />
      )}

      {/* External-file Comparison */}
      <div className="bg-white border border-slate-200 rounded-xl p-4">
        <div className="flex items-center gap-2 mb-3">
          <HeroIcons.ArrowsRightLeftIcon className="w-4 h-4 text-indigo-600" />
          <h3 className="text-sm font-semibold text-slate-700">
            Comparison vs external HR file
          </h3>
          <span className="text-[10px] uppercase font-medium text-slate-400 ml-2">
            ValueFrame · Sympa · Generic
          </span>
        </div>
        <ComparisonPanel runId={run.id} />
      </div>
    </div>
  )
}

function IntegrationCard({ icon, title, children }) {
  const Icon = HeroIcons[icon] || HeroIcons.Squares2X2Icon
  const tone = {
    ShieldCheckIcon: 'border-blue-200 bg-blue-50 text-blue-700 hover:bg-blue-100',
    CreditCardIcon: 'border-violet-200 bg-violet-50 text-violet-700 hover:bg-violet-100',
    BuildingLibraryIcon: 'border-sky-200 bg-sky-50 text-sky-700 hover:bg-sky-100',
    CalculatorIcon: 'border-emerald-200 bg-emerald-50 text-emerald-700 hover:bg-emerald-100',
  }[icon] || 'border-indigo-200 bg-indigo-50 text-indigo-700 hover:bg-indigo-100'
  return (
    <details className="relative" onBlur={(event) => {
      if (!event.currentTarget.contains(event.relatedTarget)) event.currentTarget.open = false
    }} onKeyDown={(event) => {
      if (event.key === 'Escape') {
        event.currentTarget.open = false
        event.currentTarget.querySelector('summary')?.focus()
      }
    }}>
      <summary title={title} aria-label={title} className={`flex h-8 w-8 cursor-pointer list-none items-center justify-center rounded-md border transition-colors focus-visible:outline-indigo-500 [&::-webkit-details-marker]:hidden ${tone}`}>
        <Icon className="h-4 w-4" aria-hidden="true" />
      </summary>
      <div className="absolute left-0 z-30 mt-2 w-60 rounded-xl border border-slate-200 bg-white p-3 shadow-lg">
        <h3 className="mb-2 text-sm font-semibold text-slate-900">{title}</h3>
        {children}
      </div>
    </details>
  )
}

function ResultBadge({ tone, children }) {
  const tones = { red: 'bg-rose-50 text-rose-700', amber: 'bg-amber-50 text-amber-700', green: 'bg-emerald-50 text-emerald-700' }
  return <div className={`rounded-lg px-3 py-2 text-xs font-medium ${tones[tone] || tones.green}`}>{children}</div>
}

import { radaiConfirm, radaiPrompt } from '../../../../services/radaiDialog'
import React, { useEffect, useMemo, useState, useRef } from 'react'
import { useSelector } from 'react-redux'
import * as HeroIcons from '@heroicons/react/24/outline'
import payrollEngineService, { downloadBlob } from '../../../../services/payrollEngine.service'
import {
  formatCurrency,
  formatNumber,
  RUN_COLUMNS,
  RUN_DELETABLE_STATUSES,
  canForcePayrollRun,
} from '../../../../config/payrollEngine.config'
import StatusBadge from './StatusBadge'
import MonthYearPicker from './MonthYearPicker'

const today = new Date()

function formatDateTime(iso) {
  if (!iso) return '—'
  try {
    return new Date(iso).toLocaleString('en-AE', {
      year: 'numeric', month: 'short', day: '2-digit',
      hour: '2-digit', minute: '2-digit',
    })
  } catch { return iso }
}

export default function RunsList({ onSelectRun }) {
  const authUser = useSelector((s) => s.auth?.user)
  const rbacUser = useSelector((s) => s.rbac?.currentUser)
  const canForce = useMemo(
    () => canForcePayrollRun(authUser, rbacUser),
    [authUser, rbacUser],
  )

  const [runs, setRuns] = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [generating, setGenerating] = useState(false)
  const [period, setPeriod] = useState({
    year: today.getFullYear(),
    month: today.getMonth() + 1,
  })
  const [overwrite, setOverwrite] = useState(false)
  // Soft-coded default: mirrors catalog.DEFAULT_WORKING_DAYS_PER_MONTH (22 UAE standard)
  const DEFAULT_WORKING_DAYS = 22
  const [workingDays, setWorkingDays] = useState(DEFAULT_WORKING_DAYS)
  // Generation mode: 'system' = from live data, 'import' = from uploaded Excel
  const [genMode, setGenMode] = useState('system')
  const [importFile, setImportFile] = useState(null)
  const importFileRef = React.useRef(null)
  const [deletingId, setDeletingId] = useState(null)
  const [revertingId, setRevertingId] = useState(null)
  const [page, setPage] = useState(1)
  const [pageSize, setPageSize] = useState(10)
  const totalPages = Math.max(1, Math.ceil(runs.length / pageSize))
  const pageRuns = useMemo(() => runs.slice((page - 1) * pageSize, page * pageSize), [runs, page, pageSize])

  useEffect(() => { setPage((current) => Math.min(current, totalPages)) }, [totalPages])
  useEffect(() => { setPage(1) }, [pageSize])

  const load = async () => {
    setLoading(true)
    setError(null)
    try {
      const data = await payrollEngineService.listRuns({ page_size: 500 })
      setRuns(Array.isArray(data) ? data : (data?.results ?? []))
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setLoading(false)
    }
  }

  useEffect(() => { load() }, [])

  const handleGenerate = async () => {
    setGenerating(true)
    setError(null)
    try {
      let run
      if (genMode === 'import') {
        if (!importFile) { setError('Select an Excel file to import.'); setGenerating(false); return }
        const data = await payrollEngineService.importFullXlsx(importFile, period)
        run = data.run
        if (importFileRef.current) importFileRef.current.value = ''
        setImportFile(null)
      } else {
        run = await payrollEngineService.generateRun({ ...period, overwrite, working_days: workingDays })
      }
      await load()
      onSelectRun?.(run)
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setGenerating(false)
    }
  }

  const handleDownload = async (run) => {
    try {
      const blob = await payrollEngineService.downloadRunMasterXlsx(run.id)
      downloadBlob(blob, `payroll_master_${run.cycle_code}.xlsx`)
    } catch (e) { setError(e?.response?.data?.error || e.message) }
  }

  const handleDelete = async (run, { force = false } = {}) => {
    const standardMsg = `Delete payroll run ${run.cycle_code}?\n\n` +
      `This permanently removes the run, all ${run.employee_count || 0} payslip(s) and ` +
      `their line items so you can rebuild from scratch. This cannot be undone.`
    const forceMsg =
      `⚠️  SUPER-ADMIN OVERRIDE\n\n` +
      `Run ${run.cycle_code} is currently "${run.status}" (approved/released).\n` +
      `Force-deleting will permanently destroy ${run.employee_count || 0} payslip(s) and ` +
      `all related line items, even though the run has already passed through approval.\n\n` +
      `A full audit row will be written to the workflow log.\n\n` +
      `Type OK in the next prompt to confirm.`
    if (!(await radaiConfirm(force ? forceMsg : standardMsg))) return
    if (force) {
      const typed = (await radaiPrompt('Type FORCE DELETE to confirm:', ''))
      if ((typed || '').trim().toUpperCase() !== 'FORCE DELETE') return
    }
    setDeletingId(run.id); setError(null)
    try {
      await payrollEngineService.deleteRun(run.id, { force })
      setRuns((prev) => prev.filter((r) => r.id !== run.id))
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setDeletingId(null)
    }
  }

  const handleForceRevert = async (run) => {
    const msg =
      `⚠️  SUPER-ADMIN OVERRIDE\n\n` +
      `Force-revert run ${run.cycle_code} (currently "${run.status}") back to Draft?\n\n` +
      `Approval/release timestamps will be cleared so the workflow restarts.\n` +
      `The change will be audit-logged. Continue?`
    if (!(await radaiConfirm(msg))) return
    setRevertingId(run.id); setError(null)
    try {
      const updated = await payrollEngineService.forceRevertRun(run.id)
      setRuns((prev) => prev.map((r) => (r.id === run.id ? updated : r)))
    } catch (e) {
      setError(e?.response?.data?.error || e.message)
    } finally {
      setRevertingId(null)
    }
  }

  return (
    <div className="space-y-4">
      {/* ── Generate Panel ── */}
      <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
        {/* Mode selector tabs */}
        <div className="flex border-b border-slate-200">
          {[
            { key: 'system', label: 'System Generate', icon: 'PlayCircleIcon',       desc: 'From live employee & timesheet data' },
            { key: 'import', label: 'Import from File', icon: 'DocumentArrowUpIcon', desc: 'From master payroll Excel upload' },
          ].map((m) => {
            const Icon = HeroIcons[m.icon]
            return (
              <button key={m.key} type="button"
                onClick={() => { setGenMode(m.key); setError(null) }}
                className={`flex-1 flex items-center gap-2 px-4 py-3 text-sm font-medium transition-colors ${
                  genMode === m.key
                    ? 'bg-blue-50 text-blue-700 border-b-2 border-blue-600'
                    : 'text-slate-600 hover:bg-slate-50'
                }`}>
                <Icon className="w-4 h-4" />
                <span>{m.label}</span>
                <span className="hidden sm:inline text-xs font-normal text-slate-400 ml-1">— {m.desc}</span>
              </button>
            )
          })}
        </div>

        {/* Controls */}
        <div className="p-4">
          <div className="flex items-end flex-wrap gap-4">
            <div>
              <label className="block text-xs font-medium text-slate-600 mb-1">Month / Year</label>
              <MonthYearPicker year={period.year} month={period.month} onChange={setPeriod} />
            </div>

            {genMode === 'system' && (
              <>
                {/* Working Days */}
                <div>
                  <label className="block text-xs font-medium text-slate-600 mb-1">
                    Working Days <span className="text-slate-400 font-normal">(this month)</span>
                  </label>
                  <input type="number" min={1} max={31} value={workingDays}
                    onChange={(e) => { const v = parseInt(e.target.value, 10); if (v >= 1 && v <= 31) setWorkingDays(v) }}
                    className="w-24 border border-slate-200 rounded-lg px-3 py-2 text-sm text-center font-semibold focus:outline-none focus:ring-2 focus:ring-blue-300"
                    title="Total working days for this month"
                  />
                </div>
                {/* Overwrite */}
                <label className="inline-flex items-center gap-2 text-xs text-slate-600">
                  <input type="checkbox" checked={overwrite} onChange={(e) => setOverwrite(e.target.checked)} className="rounded" />
                  Overwrite if Draft exists
                </label>
              </>
            )}

            {genMode === 'import' && (
              <div className="flex-1 min-w-56">
                <label className="block text-xs font-medium text-slate-600 mb-1">Master Payroll Excel</label>
                <input ref={importFileRef} type="file" accept=".xlsx,.xls"
                  onChange={(e) => setImportFile(e.target.files?.[0] || null)}
                  className="block w-full text-xs text-slate-600 file:mr-2 file:py-1.5 file:px-3 file:rounded file:border-0 file:text-xs file:font-medium file:bg-emerald-50 file:text-emerald-700 hover:file:bg-emerald-100" />
                {importFile && (
                  <p className="text-xs text-slate-400 mt-0.5">{importFile.name} ({Math.round(importFile.size / 1024)} KB)</p>
                )}
              </div>
            )}

            <button type="button" onClick={handleGenerate} disabled={generating}
              className={`ml-auto inline-flex items-center gap-1.5 px-4 py-2 text-sm font-medium rounded-md disabled:opacity-50 ${
                genMode === 'import'
                  ? 'bg-emerald-600 text-white hover:bg-emerald-700'
                  : 'bg-blue-600 text-white hover:bg-blue-700'
              }`}>
              {generating
                ? <HeroIcons.ArrowPathIcon className="w-4 h-4 animate-spin" />
                : genMode === 'import' ? <HeroIcons.DocumentArrowUpIcon className="w-4 h-4" /> : <HeroIcons.PlayCircleIcon className="w-4 h-4" />
              }
              {generating ? (genMode === 'import' ? 'Importing…' : 'Generating…') : (genMode === 'import' ? 'Import & Generate' : 'Generate Run')}
            </button>
          </div>

          {error && (
            <div className="mt-3 text-xs text-red-700 bg-red-50 border border-red-200 rounded-md px-3 py-2">{error}</div>
          )}
        </div>
      </div>

      <div className="bg-white border border-slate-200 rounded-xl overflow-hidden">
        <div className="px-4 py-3 border-b border-slate-200 flex items-center justify-between">
          <h3 className="text-sm font-semibold text-slate-700">Monthly Runs</h3>
          <div className="flex items-center gap-3">
            {canForce && (
              <span
                className="inline-flex items-center gap-1 text-[10px] font-medium uppercase tracking-wide px-2 py-1 rounded-full bg-amber-50 text-amber-700 border border-amber-200"
                title="You can force-edit, force-revert or force-delete approved or released runs. All actions are audit-logged."
              >
                <HeroIcons.ShieldCheckIcon className="w-3.5 h-3.5" />
                Super-Admin overrides enabled
              </span>
            )}
            <button
              type="button"
              onClick={load}
              className="text-xs text-slate-500 hover:text-slate-800 inline-flex items-center gap-1"
            >
              <HeroIcons.ArrowPathIcon className="w-3.5 h-3.5" /> Refresh
            </button>
          </div>
        </div>
        {loading ? (
          <div className="p-8 text-center text-sm text-slate-400">Loading…</div>
        ) : runs.length === 0 ? (
          <div className="p-8 text-center text-sm text-slate-400">
            No payroll runs yet. Generate one above.
          </div>
        ) : (
          <div className="overflow-x-auto"><table className="min-w-[1180px] w-full text-sm">
            <thead className="bg-slate-50 text-xs text-slate-500 uppercase">
              <tr>
                {RUN_COLUMNS.map((c) => (
                  <th
                    key={c.key}
                    style={{ width: c.width }}
                    className={`px-3 py-2 font-medium ${c.align === 'right' ? 'text-right' : 'text-left'}`}
                  >
                    {c.label}
                  </th>
                ))}
                <th className="px-3 py-2 text-right">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {pageRuns.map((r) => (
                <tr
                  key={r.id}
                  className="hover:bg-slate-50 cursor-pointer"
                  onClick={() => onSelectRun?.(r)}
                >
                  <td className="px-3 py-2 font-mono">{r.cycle_code}</td>
                  <td className="px-3 py-2">
                    <div className="flex items-center gap-1.5">
                      <StatusBadge status={r.status} />
                      {r.source_type === 'import' && (
                        <span className="inline-flex items-center gap-0.5 px-1.5 py-0.5 rounded text-[10px] font-semibold border bg-emerald-50 text-emerald-700 border-emerald-200" title="Generated from imported Excel file">
                          ↗ Import
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-3 py-2 text-right">{r.employee_count}</td>
                  <td className="px-3 py-2 text-right font-semibold text-indigo-700">
                    {r.working_days_in_month ?? 22}
                  </td>
                  <td className="px-3 py-2 text-right tabular-nums">{formatNumber(r.total_hours, { decimals: 2 })}</td>
                  <td className="px-3 py-2 text-right tabular-nums font-medium text-slate-700">{formatNumber(r.total_days, { decimals: 2 })}</td>
                  <td className="px-3 py-2 text-right">{formatCurrency(r.total_gross, { withSymbol: false })}</td>
                  <td className="px-3 py-2 text-right">{formatCurrency(r.total_deductions, { withSymbol: false })}</td>
                  <td className="px-3 py-2 text-right font-medium">{formatCurrency(r.total_net)}</td>
                  <td className="px-3 py-2 text-xs text-slate-500">{formatDateTime(r.generated_at)}</td>
                  <td className="px-3 py-2 text-right" onClick={(e) => e.stopPropagation()}>
                    <div className="inline-flex items-center gap-3 justify-end">
                      <button
                        type="button"
                        onClick={() => handleDownload(r)}
                        className="text-xs text-blue-600 hover:underline inline-flex items-center gap-1"
                      >
                        <HeroIcons.ArrowDownTrayIcon className="w-3.5 h-3.5" /> XLSX
                      </button>
                      {RUN_DELETABLE_STATUSES.includes(r.status) ? (
                        <button
                          type="button"
                          onClick={() => handleDelete(r)}
                          disabled={deletingId === r.id}
                          title="Delete this Draft run so you can rebuild it"
                          className="text-xs text-red-600 hover:underline inline-flex items-center gap-1 disabled:opacity-50"
                        >
                          {deletingId === r.id
                            ? <HeroIcons.ArrowPathIcon className="w-3.5 h-3.5 animate-spin" />
                            : <HeroIcons.TrashIcon className="w-3.5 h-3.5" />}
                          {deletingId === r.id ? 'Deleting…' : 'Delete'}
                        </button>
                      ) : canForce ? (
                        <>
                          <button
                            type="button"
                            onClick={() => handleForceRevert(r)}
                            disabled={revertingId === r.id}
                            title="Super-Admin override: revert this run back to Draft"
                            className="text-xs text-amber-700 hover:underline inline-flex items-center gap-1 disabled:opacity-50"
                          >
                            {revertingId === r.id
                              ? <HeroIcons.ArrowPathIcon className="w-3.5 h-3.5 animate-spin" />
                              : <HeroIcons.ArrowUturnLeftIcon className="w-3.5 h-3.5" />}
                            {revertingId === r.id ? 'Reverting…' : 'Force Revert'}
                          </button>
                          <button
                            type="button"
                            onClick={() => handleDelete(r, { force: true })}
                            disabled={deletingId === r.id}
                            title="Super-Admin override: force-delete an approved/released run"
                            className="text-xs text-red-700 hover:underline inline-flex items-center gap-1 disabled:opacity-50"
                          >
                            {deletingId === r.id
                              ? <HeroIcons.ArrowPathIcon className="w-3.5 h-3.5 animate-spin" />
                              : <HeroIcons.ShieldExclamationIcon className="w-3.5 h-3.5" />}
                            {deletingId === r.id ? 'Deleting…' : 'Force Delete'}
                          </button>
                        </>
                      ) : (
                        <span
                          title="Only Draft runs can be deleted — revert to Draft first"
                          className="text-xs text-slate-300 inline-flex items-center gap-1 cursor-not-allowed"
                        >
                          <HeroIcons.TrashIcon className="w-3.5 h-3.5" /> Delete
                        </span>
                      )}
                    </div>
                  </td>
                </tr>
              ))}
            </tbody>
          </table></div>
        )}
        {!loading && runs.length > 0 && <div className="flex flex-wrap items-center justify-between gap-3 border-t border-slate-200 px-4 py-3"><div className="flex items-center gap-3"><p className="text-xs text-slate-500">Showing {(page - 1) * pageSize + 1}–{Math.min(page * pageSize, runs.length)} of {runs.length} runs</p><label className="flex items-center gap-2 text-xs text-slate-500">Rows<select value={pageSize} onChange={(event) => setPageSize(Number(event.target.value))} className="rounded-md border border-slate-200 bg-white px-2 py-1.5 text-xs text-slate-700"><option value={5}>5</option><option value={10}>10</option><option value={20}>20</option></select></label></div><div className="flex items-center gap-1"><button type="button" onClick={() => setPage((current) => Math.max(1, current - 1))} disabled={page === 1} className="rounded-lg border border-slate-200 p-2 text-slate-600 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40" aria-label="Previous payroll runs page"><HeroIcons.ChevronLeftIcon className="h-4 w-4" /></button><span className="min-w-24 text-center text-xs font-semibold text-slate-700">Page {page} of {totalPages}</span><button type="button" onClick={() => setPage((current) => Math.min(totalPages, current + 1))} disabled={page === totalPages} className="rounded-lg border border-slate-200 p-2 text-slate-600 hover:bg-slate-50 disabled:cursor-not-allowed disabled:opacity-40" aria-label="Next payroll runs page"><HeroIcons.ChevronRightIcon className="h-4 w-4" /></button></div></div>}
      </div>
    </div>
  )
}

