          />
          {disciplines.length === 0 ? (
            <EmptyState icon="📊" message="No data yet — start using the platform to see stats." />
          ) : (
            <ResponsiveContainer width="100%" height={Math.max(240, disciplines.length * 36)}>
              <BarChart data={disciplines} layout="vertical" margin={{ top: 0, right: 24, bottom: 0, left: 8 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={false} />
                <XAxis type="number" tick={{ fontSize: 11 }} />
                <YAxis type="category" dataKey="discipline_label" width={155} tick={{ fontSize: 11 }} />
                <Tooltip formatter={(v, n) => [fmt(v), n === 'total_requests' ? 'Requests' : 'Users']} />
                <Legend formatter={v => v === 'total_requests' ? 'Requests' : 'Unique Users'} />
                <Bar dataKey="total_requests" name="total_requests" radius={[0, 4, 4, 0]}>
                  {disciplines.map((d, i) => <Cell key={i} fill={discColor(d.discipline_label)} />)}
                </Bar>
                <Bar dataKey="unique_users" name="unique_users" fill="#a5b4fc" radius={[0, 4, 4, 0]} />
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>

        {/* Discipline badge pills */}
        <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6">
          <SectionHeader icon="🏷️" title="Discipline Breakdown" subtitle="All modules accessed in period" />
          <div className="flex flex-wrap gap-2">
            {disciplines.length === 0
              ? <p className="text-gray-400 text-sm">No discipline data yet.</p>
              : disciplines.map(d => (
                  <div
                    key={d.discipline_key}
                    className="flex items-center gap-2 px-3 py-1.5 rounded-full text-white text-xs font-semibold shadow-sm"
                    style={{ backgroundColor: discColor(d.discipline_label) }}
                  >
                    <span>{d.discipline_label}</span>
                    <span className="bg-white/25 rounded-full px-1.5 py-0.5">{fmt(d.total_requests)}</span>
                    <span className="text-white/70">·</span>
                    <span className="text-white/80">{d.unique_users} users</span>
                  </div>
                ))
            }
          </div>
        </div>

        {/* Top Users */}
        <div className="bg-white rounded-2xl border border-gray-200 shadow-sm p-6">
          <SectionHeader icon="⭐" title="Top Users" subtitle={`Most active — ${CONFIG.timeRanges.find(r => r.key === range)?.label}`} />
          {topUsers.length === 0 ? (
            <EmptyState icon="👤" message="No user data for this period." />
          ) : (
            <div className="overflow-x-auto">
              <table className="w-full text-sm">
                <thead>
                  <tr className="text-left text-xs font-semibold text-gray-500 uppercase tracking-wide border-b border-gray-100">
                    <th className="pb-3 pr-4">#</th>
                    <th className="pb-3 pr-4">User</th>
                    <th className="pb-3 pr-4 text-right">Requests</th>
                    <th className="pb-3 pr-4 text-right">Disciplines</th>
                    <th className="pb-3 text-right">Avg Response</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {topUsers.map((u, i) => (
                    <tr key={u.user_email} className="hover:bg-gray-50 transition-colors">
                      <td className="py-3 pr-4">
                        <span className={`inline-flex w-6 h-6 items-center justify-center rounded-full text-xs font-bold ${
                          i === 0 ? 'bg-yellow-100 text-yellow-700' :
                          i === 1 ? 'bg-gray-100 text-gray-600'    :
                          i === 2 ? 'bg-orange-100 text-orange-700' : 'text-gray-400'
                        }`}>
                          {i < 3 ? ['🥇','🥈','🥉'][i] : i + 1}
                        </span>
                      </td>
                      <td className="py-3 pr-4">
                        <p className="font-semibold text-gray-900">{u.user_full_name || '—'}</p>
                        <p className="text-xs text-gray-400">{u.user_email}</p>
                      </td>
                      <td className="py-3 pr-4 text-right font-semibold text-indigo-700">{fmt(u.total_requests)}</td>
                      <td className="py-3 pr-4 text-right text-gray-600">{u.disciplines_used}</td>
                      <td className="py-3 text-right text-gray-500">{fmt(u.avg_response_ms)} ms</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>

        {/* All-users roster */}
        <AllUsersPanel
          allUsers={allUsers}
          userSearch={userSearch}
          setUserSearch={setUserSearch}
        />

        {/* Sessions */}
        <SessionsPanel sessions={sessions} />

        {/* DB Events */}
        <DbEventsPanel
          dbEvents={dbEvents}
          evtCategory={evtCategory}
          setEvtCategory={setEvtCategory}
        />
      </div>
    );
  }

  return null;
}

// ─────────────────────────────────────────────────────────────────────────────
// ⑦ ROOT COMPONENT
// ─────────────────────────────────────────────────────────────────────────────
export default function InternalSalesDashboard() {

  // ── Platform usage state ─────────────────────────────────────────────────
  const [range, setRange]             = useState('7d');
  const [overview, setOverview]       = useState(null);
  const [disciplines, setDisciplines] = useState([]);
  const [topUsers, setTopUsers]       = useState([]);
  const [trends, setTrends]           = useState([]);
  const [activeNow, setActiveNow]     = useState([]);
  const [allUsers, setAllUsers]       = useState([]);
  const [userSearch, setUserSearch]   = useState('');
  const [dbEvents, setDbEvents]       = useState({ events: [], total_in_period: 0, category_summary: [] });
  const [evtCategory, setEvtCategory] = useState('');
  const [sessions, setSessions]       = useState({ active_sessions: [], recent_sessions: [], active_count: 0 });
  const [usageLoading, setUsageLoading] = useState(true);
  const [usageError, setUsageError]   = useState(null);

  // ── CRM / pipeline state ─────────────────────────────────────────────────
  const [pipeline, setPipeline]             = useState(null);
  const [clients, setClients]               = useState({ top: [], atRisk: [] });
  const [aiInsights, setAiInsights]         = useState([]);
  const [activities, setActivities]         = useState([]);
  const [pipelineLoading, setPipelineLoading] = useState(false);
  const [pipelineError, setPipelineError]   = useState(null);
  const [pipelineLoaded, setPipelineLoaded] = useState(false); // lazy — load once

  // ── Utilisation Report state ─────────────────────────────────────────────
  const [reportData,    setReportData]    = useState(null);
  const [reportPeriod,  setReportPeriod]  = useState('monthly');
  const [reportAnchor,  setReportAnchor]  = useState(() => new Date().toISOString().slice(0, 7));
  const [reportLoading, setReportLoading] = useState(false);
  const [reportError,   setReportError]   = useState(null);

  // ── UI state ─────────────────────────────────────────────────────────────
  const [activeTab, setActiveTab]   = useState(CONFIG.defaultTab);
  const [lastRefresh, setLastRefresh] = useState(new Date());

  const mainTimer      = useRef(null);
  const activeNowTimer = useRef(null);
  const sessionsTimer  = useRef(null);

  // ── Fetch: platform usage (tied to range) ────────────────────────────────
  const fetchUsage = useCallback(async () => {
    try {
      setUsageError(null);
      const trendRange = range === '1d' ? '7d' : range;
      const [ov, disc, users, tr, allU, evts] = await Promise.all([
        internalSalesService.getOverview(range),
        internalSalesService.getDisciplines(range),
        internalSalesService.getTopUsers(range, CONFIG.topUsersLimit),
        internalSalesService.getTrends(trendRange),
        internalSalesService.getAllUsers(range),
        internalSalesService.getDbEvents(range, { limit: 100 }),
      ]);
      setOverview(ov);
      setDisciplines(disc);
      setTopUsers(users);
      setTrends(tr);
      setAllUsers(allU);
      setDbEvents(evts);
      setLastRefresh(new Date());
    } catch (e) {
      console.error('Usage fetch error:', e);
      setUsageError('Could not load analytics. Backend may still be starting up.');
    } finally {
      setUsageLoading(false);
    }
  }, [range]);

  const fetchActive = useCallback(async () => {
    try { setActiveNow(await internalSalesService.getActiveNow()); } catch (_) {}
  }, []);

  const fetchSessions = useCallback(async () => {
    try { setSessions(await internalSalesService.getSessions()); } catch (_) {}
  }, []);

  // ── Fetch: CRM data — lazy, loads once when pipeline tab is first visited ─
  const fetchPipeline = useCallback(async () => {
    if (pipelineLoaded) return;
    setPipelineLoading(true);
    setPipelineError(null);
    try {
      const [summary, topC, atRisk, insights, upcoming] = await Promise.allSettled([
        salesService.getPipelineSummary(),
        salesService.getTopClients({ limit: 20 }),
        salesService.getAtRiskClients(),
        salesService.getAIInsights(),
        salesService.getUpcomingActivities(7),
      ]);

      if (summary.status  === 'fulfilled') {
        // Adopt API-provided currency (soft-coded; defaults to AED).
        setSalesCurrency(summary.value?.currency, summary.value?.currency_locale);
        setPipeline(summary.value);
      }
      if (topC.status     === 'fulfilled') setClients(prev => ({ ...prev, top:    safeArr(topC.value)    }));
      if (atRisk.status   === 'fulfilled') setClients(prev => ({ ...prev, atRisk: safeArr(atRisk.value)  }));
      if (insights.status === 'fulfilled') setAiInsights(safeArr(insights.value?.insights ?? insights.value));
      if (upcoming.status === 'fulfilled') setActivities(safeArr(upcoming.value));

      if (summary.status === 'rejected') {
        // Don't mark loaded — allows auto-retry on next tab visit
        setPipelineError('Connecting to analytics engine… switching to this tab will retry automatically.');
        return;
      }

      setPipelineLoaded(true);
    } catch (e) {
      setPipelineError('Failed to load sales pipeline data.');
    } finally {
      setPipelineLoading(false);
    }
  }, [pipelineLoaded]);

  // ── Fetch: utilisation report (manual trigger) ───────────────────────────
  const fetchReport = useCallback(async () => {
    setReportLoading(true);
    setReportError(null);
    try {
      const data = await internalSalesService.getUtilisationReport({
        period: reportPeriod,
        anchor: reportAnchor,
      });
      setReportData(data);
    } catch (e) {
      console.error('Report fetch error:', e);
      setReportError('Could not load utilisation report. Please try again.');
    } finally {
      setReportLoading(false);
    }
  }, [reportPeriod, reportAnchor]);

  // ── Lifecycle — usage polling ─────────────────────────────────────────────
  useEffect(() => {
    setUsageLoading(true);
    fetchUsage();
    fetchActive();
    fetchSessions();

    clearInterval(mainTimer.current);
    clearInterval(activeNowTimer.current);
    clearInterval(sessionsTimer.current);

    mainTimer.current      = setInterval(fetchUsage,    CONFIG.refreshIntervalMs);
    activeNowTimer.current = setInterval(fetchActive,   CONFIG.activeNowRefreshMs);
    sessionsTimer.current  = setInterval(fetchSessions, CONFIG.sessionsRefreshMs);

    return () => {
      clearInterval(mainTimer.current);
      clearInterval(activeNowTimer.current);
      clearInterval(sessionsTimer.current);
    };
  }, [fetchUsage, fetchActive, fetchSessions]);

  // ── Lazy-load CRM when Sales Pipeline or Overview tab is first opened ────
  useEffect(() => {
    if (activeTab === 'pipeline' || activeTab === 'overview') fetchPipeline();
  }, [activeTab, fetchPipeline]);

  // ── Bundle state / actions for TabContent ───────────────────────────────
  const tabState = {
    range, overview, disciplines, topUsers, trends, activeNow,
    allUsers, userSearch, dbEvents, evtCategory, sessions,
    pipeline, clients, aiInsights, activities,
    pipelineLoading, pipelineError,
  };
  const onQuickAction = useCallback((action) => {
    // Soft-routed quick-action: jump to the relevant tab
    if (action?.tab) setActiveTab(action.tab);
  }, []);
  const tabActions = { setUserSearch, setEvtCategory, fetchPipeline, fetchUsage, onQuickAction };

  // ── Render ───────────────────────────────────────────────────────────────
  return (
    <div className="w-full min-h-full bg-gradient-to-br from-slate-50 via-indigo-50/20 to-purple-50/20">
      <div
        className={`mx-auto space-y-6 ${LAYOUT_CONFIG.paddingX} ${LAYOUT_CONFIG.paddingY}`}
        style={{ maxWidth: LAYOUT_CONFIG.maxWidth }}
      >

        {/* ── Hero banner (gradient, icon-based) ── */}
        <div className="relative bg-gradient-to-r from-indigo-600 via-purple-600 to-fuchsia-600 rounded-2xl shadow-lg overflow-hidden">
          {/* Decorative blur blobs */}
          <div className="absolute -top-12 -right-12 h-44 w-44 rounded-full bg-white/10 blur-3xl pointer-events-none" />
          <div className="absolute -bottom-16 left-1/3 h-56 w-56 rounded-full bg-fuchsia-400/20 blur-3xl pointer-events-none" />

          <div className="relative px-6 py-6">
            <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-5">

              {/* Logo + title */}
              <div className="flex items-center gap-4">
                <div className="h-14 w-14 rounded-2xl bg-white/15 backdrop-blur flex items-center justify-center ring-1 ring-white/20">
                  <ChartBarIcon className="h-7 w-7 text-white" />
                </div>
                <div>
                  <div className="flex items-center gap-2">
                    <h1 className="text-2xl sm:text-3xl font-black text-white leading-tight tracking-tight">
                      Sales Intelligence
                    </h1>
                    <span className="hidden sm:inline-flex items-center gap-1 px-2 py-0.5 rounded-full bg-white/15 backdrop-blur text-[10px] font-bold text-white ring-1 ring-white/20 uppercase tracking-wider">
                      <SparklesIcon className="h-3 w-3" /> AI · Live
                    </span>
                  </div>
                  <p className="text-sm text-white/80 mt-0.5">
                    Platform analytics · CRM pipeline · live user activity
                  </p>
                </div>
              </div>

              {/* Time range + live indicator */}
              <div className="flex items-center gap-3 flex-wrap">
                <div className="flex rounded-xl overflow-hidden bg-white/10 backdrop-blur ring-1 ring-white/20">
                  {CONFIG.timeRanges.map(({ key, label }) => (
                    <button
                      key={key}
                      onClick={() => setRange(key)}
                      className={`px-3.5 py-1.5 text-xs font-bold transition-all ${
                        range === key ? 'bg-white text-indigo-700 shadow-sm' : 'text-white/80 hover:bg-white/10'
                      }`}
                    >
                      {label}
                    </button>
                  ))}
                </div>
                <div className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-white/10 backdrop-blur ring-1 ring-white/20">
                  <span className="w-2 h-2 rounded-full bg-emerald-300 animate-pulse inline-block" />
                  <span className="text-[11px] font-bold text-white">LIVE</span>
                  <span className="text-[10px] text-white/70 ml-1 tabular-nums">{lastRefresh.toLocaleTimeString()}</span>
                </div>
              </div>
            </div>

            {/* Tab bar — segmented, glass */}
            <div className="flex gap-1 mt-5 p-1 rounded-xl bg-white/10 backdrop-blur ring-1 ring-white/20 w-fit">
              {CONFIG.tabs.map(({ key, label, icon }) => (
                <button
                  key={key}
                  onClick={() => setActiveTab(key)}
                  className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-sm font-bold transition-all select-none ${
                    activeTab === key
                      ? 'bg-white text-indigo-700 shadow-sm'
                      : 'text-white/85 hover:bg-white/10'
                  }`}
                >
                  <span>{icon}</span>
                  <span>{label}</span>
                </button>
              ))}
            </div>
          </div>
        </div>

        {/* ── Loading ── */}
        {usageLoading && <Spinner />}

        {/* ── Tab content — always rendered after initial load.
             usageError shows as a warning banner but does NOT hide tabs.
             The Sales Pipeline tab uses its own endpoints and stays functional
             even when the Usage/Analytics API is unreachable. ── */}
        {!usageLoading && (
          <>
            {usageError && (
              <ErrorBanner
                message={usageError}
                onRetry={fetchUsage}
              />
            )}
            <TabContent tab={activeTab} state={tabState} actions={tabActions} />
          </>
        )}

      </div>
    </div>
  );
}

import { useCallback, useEffect, useMemo, useState } from 'react'
import { useSelector } from 'react-redux'
import { useNavigate } from 'react-router-dom'
import {
  ArrowPathIcon, ArrowRightIcon, CheckCircleIcon, ChevronRightIcon, ClockIcon,
  DocumentTextIcon, ExclamationTriangleIcon, InboxIcon, MagnifyingGlassIcon,
  PaperClipIcon, PlusIcon, SparklesIcon, XMarkIcon,
} from '@heroicons/react/24/outline'
import apiService from '../services/api.service'

const TYPES = [
  ['general', 'General inquiry'], ['technical_support', 'Technical support'],
  ['complaint', 'Complaint'], ['suggestion', 'Suggestion'], ['partnership', 'Partnership'],
  ['legal', 'Legal'], ['hr', 'HR'], ['it_request', 'IT request'],
  ['finance_request', 'Finance request'], ['procurement', 'Procurement'],
  ['facility_request', 'Facility request'], ['other', 'Other'],
]
const EMPTY_FORM = { name: '', email: '', inquiry_type: 'general', subject: '', message: '', urgency: 'normal', phone: '', company: '' }
const CLOSED_STATUSES = ['resolved', 'closed', 'spam']
const RESPONSE_STATUSES = ['responded', 'resolved', 'closed']
const ATTENTION_STATUSES = ['waiting_user', 'pending_confirmation']
const STATUS_OPTIONS = [
  ['all', 'All statuses'], ['new', 'New'], ['assigned', 'Assigned'], ['in_progress', 'In progress'],
  ['waiting_user', 'Waiting for me'], ['responded', 'Responded'], ['pending_confirmation', 'Confirmation needed'],
  ['resolved', 'Resolved'], ['closed', 'Closed'], ['escalated', 'Escalated'], ['reopened', 'Reopened'],
]
const statusTone = {
  new: 'border-blue-200 bg-blue-50 text-blue-700', assigned: 'border-cyan-200 bg-cyan-50 text-cyan-700',
  in_progress: 'border-amber-200 bg-amber-50 text-amber-700', waiting_user: 'border-violet-200 bg-violet-50 text-violet-700',
  responded: 'border-indigo-200 bg-indigo-50 text-indigo-700', resolved: 'border-emerald-200 bg-emerald-50 text-emerald-700',
  escalated: 'border-red-200 bg-red-50 text-red-700', pending_confirmation: 'border-fuchsia-200 bg-fuchsia-50 text-fuchsia-700',
  reopened: 'border-orange-200 bg-orange-50 text-orange-700', closed: 'border-slate-200 bg-slate-100 text-slate-600',
  spam: 'border-slate-200 bg-slate-100 text-slate-600',
}
const priorityTone = { urgent: 'text-red-700', high: 'text-orange-700', normal: 'text-slate-600', low: 'text-slate-400' }
const titleCase = (value = '') => value.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase())
const dateText = (value) => value
  ? new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric', hour: '2-digit', minute: '2-digit' }).format(new Date(value))
  : '—'

export default function MyEnquiries () {
  const navigate = useNavigate()
  const auth = useSelector((state) => state.auth?.user)
  const user = useMemo(() => auth?.user || auth || {}, [auth])
  const [items, setItems] = useState([])
  const [loading, setLoading] = useState(true)
  const [loadError, setLoadError] = useState('')
  const [creating, setCreating] = useState(false)
  const [form, setForm] = useState(EMPTY_FORM)
  const [saving, setSaving] = useState(false)
  const [attachments, setAttachments] = useState([])
  const [submitError, setSubmitError] = useState('')
  const [query, setQuery] = useState('')
  const [statusFilter, setStatusFilter] = useState('all')

  const load = useCallback(async () => {
    setLoading(true)
    setLoadError('')
    try {
      const { data } = await apiService.get('/enquiry/mine/')
      setItems(data?.results || [])
    } catch (error) {
      setLoadError(error?.response?.data?.message || 'We could not load your requests. Please try again.')
    } finally { setLoading(false) }
  }, [])
  useEffect(() => { load() }, [load])

  useEffect(() => {
    const identity = user.user || user
    const fallbackName = identity.full_name || `${identity.first_name || ''} ${identity.last_name || ''}`.trim() || identity.username || ''
    setForm((current) => ({
      ...current,
      name: current.name || fallbackName,
      email: current.email || identity.email || '',
      phone: current.phone || user.phone || '',
      company: current.company || user.organization_name || user.organization?.name || '',
    }))
    apiService.get('/rbac/users/me/', { params: { view: 'profile' } }).then(({ data }) => {
      const profileIdentity = data?.user || data || {}
      const profileName = profileIdentity.full_name || `${profileIdentity.first_name || ''} ${profileIdentity.last_name || ''}`.trim() || profileIdentity.username || fallbackName
      setForm((current) => ({
        ...current,
        name: profileName || current.name,
        email: profileIdentity.email || data?.email || current.email,
        phone: data?.phone || current.phone,
        company: data?.organization_name || data?.organization?.name || current.company,
      }))
    }).catch(() => {})
  }, [user])

  const stats = useMemo(() => ({
    total: items.length,
    active: items.filter((row) => !CLOSED_STATUSES.includes(row.status)).length,
    attention: items.filter((row) => ATTENTION_STATUSES.includes(row.status)).length,
    completed: items.filter((row) => RESPONSE_STATUSES.includes(row.status)).length,
  }), [items])
  const filteredItems = useMemo(() => {
    const term = query.trim().toLowerCase()
    return items.filter((row) => {
      const matchesStatus = statusFilter === 'all' || row.status === statusFilter
      const content = [row.reference, row.subject, row.department, row.inquiry_type_label, row.status].join(' ').toLowerCase()
      return matchesStatus && (!term || content.includes(term))
    })
  }, [items, query, statusFilter])
  const open = (row) => navigate(`/my-enquiries/${row.id}`)

  const submit = async (event) => {
    event.preventDefault()
    setSaving(true)
    setSubmitError('')
    try {
      const payload = new FormData()
      Object.entries({ ...form, service: form.inquiry_type }).forEach(([key, value]) => payload.append(key, value || ''))
      attachments.forEach((file) => payload.append('attachments', file))
      await apiService.post('/enquiry/submit/', payload)
      setForm((current) => ({ ...EMPTY_FORM, name: current.name, email: current.email, phone: current.phone, company: current.company }))
      setAttachments([])
      setCreating(false)
      await load()
    } catch (error) {
      const fieldErrors = Object.values(error?.response?.data?.errors || {}).join(' ')
      setSubmitError(fieldErrors || error?.response?.data?.message || (error?.code === 'ECONNABORTED' ? 'The request timed out. Please try again.' : 'Could not submit the request.'))
    } finally { setSaving(false) }
  }
  const firstName = user.first_name || user.full_name?.split(' ')[0] || 'there'

  return (
    <main className="min-h-full w-full min-w-0 overflow-x-hidden bg-[#f6f8fc] px-4 py-5 font-sans sm:px-6 xl:px-8">
      <div className="mx-auto w-full max-w-[1600px]">
        <header className="relative overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_1px_2px_rgba(15,23,42,0.04),0_14px_38px_rgba(15,23,42,0.06)]">
          <div className="absolute inset-x-0 top-0 h-1 bg-gradient-to-r from-blue-600 via-indigo-500 to-cyan-400" />
          <div className="flex flex-col gap-6 px-5 py-6 sm:px-7 lg:flex-row lg:items-center lg:justify-between lg:px-8">
            <div className="min-w-0">
              <div className="flex items-center gap-2 text-xs font-semibold text-slate-400"><span>Service desk</span><ChevronRightIcon className="h-3.5 w-3.5" /><span className="text-slate-600">My requests</span></div>
              <div className="mt-4 flex items-start gap-4">
                <span className="grid h-11 w-11 shrink-0 place-content-center rounded-xl bg-blue-50 text-blue-600 ring-1 ring-blue-100"><InboxIcon className="h-6 w-6" /></span>
                <div className="min-w-0"><h1 className="text-2xl font-bold tracking-tight text-slate-950 sm:text-3xl">My Requests</h1><p className="mt-1 text-sm leading-6 text-slate-500">Welcome, {firstName}. Create, track and respond to every RADAI service request in one place.</p></div>
              </div>
            </div>
            <div className="flex shrink-0 items-center gap-2">
              <button type="button" onClick={load} disabled={loading} title="Refresh requests" aria-label="Refresh requests" className="grid h-10 w-10 place-content-center rounded-xl border border-slate-200 bg-white text-slate-600 shadow-sm transition hover:border-slate-300 hover:bg-slate-50 disabled:opacity-50"><ArrowPathIcon className={`h-5 w-5 ${loading ? 'animate-spin' : ''}`} /></button>
              <button type="button" onClick={() => setCreating(true)} className="inline-flex h-10 items-center gap-2 rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white shadow-[0_8px_18px_-8px_rgba(37,99,235,0.8)] transition hover:bg-blue-700 focus:outline-none focus:ring-4 focus:ring-blue-100"><PlusIcon className="h-4 w-4" />New request</button>
            </div>
          </div>
        </header>

        <section aria-label="Request summary" className="mt-5 grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <MetricCard label="All requests" value={stats.total} note="Lifetime total" icon={DocumentTextIcon} tone="blue" />
          <MetricCard label="Active" value={stats.active} note="Currently in progress" icon={ClockIcon} tone="amber" />
          <MetricCard label="Needs your attention" value={stats.attention} note="Reply or confirmation" icon={ExclamationTriangleIcon} tone="violet" />
          <MetricCard label="Responded / completed" value={stats.completed} note="Service response received" icon={CheckCircleIcon} tone="emerald" />
        </section>

        <section className="mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-[0_1px_2px_rgba(15,23,42,0.04)]">
          <div className="flex flex-col gap-4 border-b border-slate-200 px-5 py-5 lg:flex-row lg:items-end lg:justify-between">
            <div><div className="flex items-center gap-2"><SparklesIcon className="h-4 w-4 text-blue-600" /><h2 className="text-base font-bold text-slate-950">Request workspace</h2></div><p className="mt-1 text-xs text-slate-500">Review progress, open conversations and complete requested actions.</p></div>
            <div className="flex w-full flex-col gap-2 sm:flex-row lg:w-auto">
              <label className="relative block min-w-0 sm:w-80"><span className="sr-only">Search requests</span><MagnifyingGlassIcon className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search reference, subject or department" className="h-10 w-full rounded-xl border border-slate-300 bg-white pl-9 pr-3 text-sm text-slate-800 outline-none transition placeholder:text-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-100" /></label>
              <label><span className="sr-only">Filter by status</span><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} className="h-10 w-full rounded-xl border border-slate-300 bg-white px-3 text-sm font-medium text-slate-700 outline-none transition focus:border-blue-500 focus:ring-4 focus:ring-blue-100 sm:w-48">{STATUS_OPTIONS.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>
            </div>
          </div>
          <div className="flex items-center justify-between border-b border-slate-100 bg-slate-50/70 px-5 py-2.5 text-xs text-slate-500"><span>Showing <strong className="font-semibold text-slate-700">{filteredItems.length}</strong> of {items.length} requests</span>{(query || statusFilter !== 'all') && <button type="button" onClick={() => { setQuery(''); setStatusFilter('all') }} className="font-semibold text-blue-600 hover:text-blue-700">Clear filters</button>}</div>
          {loading ? <LoadingState /> : loadError ? <ErrorState message={loadError} retry={load} /> : filteredItems.length === 0 ? <EmptyState hasItems={items.length > 0} create={() => setCreating(true)} clear={() => { setQuery(''); setStatusFilter('all') }} /> : <RequestList rows={filteredItems} open={open} />}
        </section>
      </div>
      {creating && <CreateDialog form={form} setForm={setForm} attachments={attachments} setAttachments={setAttachments} error={submitError} saving={saving} close={() => { setCreating(false); setSubmitError('') }} submit={submit} />}
    </main>
  )
}

const toneMap = {
  blue: ['bg-blue-50 text-blue-600 ring-blue-100', 'text-blue-600'], amber: ['bg-amber-50 text-amber-600 ring-amber-100', 'text-amber-600'],
  violet: ['bg-violet-50 text-violet-600 ring-violet-100', 'text-violet-600'], emerald: ['bg-emerald-50 text-emerald-600 ring-emerald-100', 'text-emerald-600'],
}
const MetricCard = ({ label, value, note, icon: Icon, tone }) => <article className="group rounded-2xl border border-slate-200 bg-white p-5 shadow-[0_1px_2px_rgba(15,23,42,0.04)] transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold text-slate-500">{label}</p><p className="mt-2 text-3xl font-bold tracking-tight text-slate-950">{value}</p></div><span className={`grid h-10 w-10 place-content-center rounded-xl ring-1 ${toneMap[tone][0]}`}><Icon className="h-5 w-5" /></span></div><p className={`mt-3 text-[11px] font-medium ${toneMap[tone][1]}`}>{note}</p></article>

const RequestList = ({ rows, open }) => <><div className="hidden overflow-x-auto lg:block"><table className="w-full table-fixed text-left"><thead><tr className="border-b border-slate-200 bg-white text-[10px] font-bold uppercase tracking-[0.08em] text-slate-400"><th className="w-[13%] px-5 py-3">Reference</th><th className="w-[37%] px-4 py-3">Request</th><th className="w-[15%] px-4 py-3">Priority</th><th className="w-[17%] px-4 py-3">Status</th><th className="w-[15%] px-4 py-3">Updated</th><th className="w-[3%] px-3 py-3"><span className="sr-only">Open</span></th></tr></thead><tbody className="divide-y divide-slate-100">{rows.map((row) => <tr key={row.id} onClick={() => open(row)} className="group cursor-pointer transition hover:bg-blue-50/40"><td className="px-5 py-4 align-middle"><span className="font-mono text-xs font-semibold text-blue-600">{row.reference}</span></td><td className="px-4 py-4"><strong className="block truncate text-sm font-semibold text-slate-900 group-hover:text-blue-700">{row.subject}</strong><span className="mt-1 block truncate text-xs text-slate-500">{row.department || 'Routing pending'} · {row.inquiry_type_label || titleCase(row.inquiry_type)}</span></td><td className={`px-4 py-4 text-xs font-semibold ${priorityTone[row.urgency] || priorityTone.normal}`}>{titleCase(row.urgency || 'normal')}</td><td className="px-4 py-4"><StatusBadge status={row.status} /></td><td className="px-4 py-4 text-xs text-slate-500">{dateText(row.updated_at)}</td><td className="px-3 py-4"><ArrowRightIcon className="h-4 w-4 text-slate-300 transition group-hover:translate-x-0.5 group-hover:text-blue-600" /></td></tr>)}</tbody></table></div><div className="divide-y divide-slate-100 lg:hidden">{rows.map((row) => <button type="button" key={row.id} onClick={() => open(row)} className="block w-full p-4 text-left transition hover:bg-blue-50/40"><div className="flex items-start justify-between gap-3"><span className="font-mono text-xs font-semibold text-blue-600">{row.reference}</span><StatusBadge status={row.status} /></div><strong className="mt-2 block text-sm text-slate-900">{row.subject}</strong><span className="mt-1 block text-xs text-slate-500">{row.department || 'Routing pending'} · {row.inquiry_type_label || titleCase(row.inquiry_type)}</span><div className="mt-3 flex items-center justify-between text-xs"><span className={`font-semibold ${priorityTone[row.urgency] || priorityTone.normal}`}>{titleCase(row.urgency || 'normal')} priority</span><span className="text-slate-400">{dateText(row.updated_at)}</span></div></button>)}</div></>
const StatusBadge = ({ status }) => <span className={`inline-flex items-center gap-1.5 whitespace-nowrap rounded-full border px-2.5 py-1 text-[10px] font-bold ${statusTone[status] || 'border-slate-200 bg-slate-50 text-slate-600'}`}><span className="h-1.5 w-1.5 rounded-full bg-current opacity-70" />{titleCase(status)}</span>
const LoadingState = () => <div className="grid min-h-64 place-content-center text-center"><span className="mx-auto h-7 w-7 animate-spin rounded-full border-2 border-blue-100 border-t-blue-600" /><p className="mt-3 text-sm font-medium text-slate-500">Loading your requests…</p></div>
const ErrorState = ({ message, retry }) => <div className="grid min-h-64 place-content-center px-6 text-center"><span className="mx-auto grid h-11 w-11 place-content-center rounded-xl bg-red-50 text-red-600"><ExclamationTriangleIcon className="h-6 w-6" /></span><p className="mt-3 text-sm font-semibold text-slate-800">Could not load requests</p><p className="mt-1 max-w-md text-xs text-slate-500">{message}</p><button type="button" onClick={retry} className="mx-auto mt-4 rounded-lg border border-slate-300 px-3 py-2 text-xs font-semibold text-slate-700 hover:bg-slate-50">Try again</button></div>
const EmptyState = ({ hasItems, create, clear }) => <div className="grid min-h-72 place-content-center px-6 text-center"><span className="mx-auto grid h-12 w-12 place-content-center rounded-2xl bg-slate-100 text-slate-400"><InboxIcon className="h-6 w-6" /></span><p className="mt-4 text-sm font-semibold text-slate-900">{hasItems ? 'No matching requests' : 'No requests yet'}</p><p className="mt-1 text-xs text-slate-500">{hasItems ? 'Try changing your search or status filter.' : 'Create your first request and we will route it to the right team.'}</p><button type="button" onClick={hasItems ? clear : create} className="mx-auto mt-4 text-xs font-semibold text-blue-600 hover:text-blue-700">{hasItems ? 'Clear filters' : 'Create your first request'}</button></div>

const CreateDialog = ({ form, setForm, attachments, setAttachments, error, saving, close, submit }) => {
  const [fileError, setFileError] = useState('')
  const update = (field) => (event) => setForm((current) => ({ ...current, [field]: event.target.value }))
  const inputClass = 'mt-1.5 w-full rounded-xl border border-slate-300 bg-white px-3.5 py-2.5 text-sm text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-500 focus:ring-4 focus:ring-blue-100'
  const addFiles = (event) => {
    const selected = Array.from(event.target.files || [])
    setFileError('')
    if (attachments.length + selected.length > 5) { setFileError('You can attach up to 5 files.'); return }
    const invalid = selected.find((file) => file.size > 10 * 1024 * 1024)
    if (invalid) { setFileError(`${invalid.name} exceeds the 10 MB limit.`); return }
    setAttachments((current) => [...current, ...selected])
    event.target.value = ''
  }
  return <div className="fixed inset-0 z-[100] grid place-items-center overflow-y-auto bg-slate-950/55 p-4 backdrop-blur-sm"><form onSubmit={submit} role="dialog" aria-modal="true" aria-labelledby="create-request-title" className="my-auto w-full max-w-3xl overflow-hidden rounded-2xl border border-white/20 bg-white shadow-[0_30px_90px_-20px_rgba(15,23,42,0.55)]"><div className="h-1 bg-gradient-to-r from-blue-600 via-indigo-500 to-cyan-400"/><div className="flex items-start justify-between border-b border-slate-200 px-6 py-5"><div><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-blue-600">RADAI service desk</p><h2 id="create-request-title" className="mt-1 text-xl font-bold tracking-tight text-slate-950">Create a request</h2><p className="mt-1 text-sm text-slate-500">Your identity is filled from your employee profile.</p></div><button type="button" onClick={close} aria-label="Close dialog" className="grid h-9 w-9 place-content-center rounded-lg text-slate-400 transition hover:bg-slate-100 hover:text-slate-700"><XMarkIcon className="h-5 w-5"/></button></div><div className="max-h-[72vh] overflow-y-auto px-6 py-5"><div className="mb-5 rounded-xl border border-blue-100 bg-blue-50/60 p-4"><div className="mb-3 text-[10px] font-bold uppercase tracking-[0.12em] text-blue-700">Requester profile</div><div className="grid gap-4 sm:grid-cols-2"><DialogField label="Requester name"><input readOnly value={form.name} className={`${inputClass} cursor-default bg-white/70 text-slate-600`}/></DialogField><DialogField label="Email address"><input readOnly type="email" value={form.email} className={`${inputClass} cursor-default bg-white/70 text-slate-600`}/></DialogField><DialogField label="Phone number" required><input type="tel" required value={form.phone} onChange={update('phone')} placeholder="Add phone number" className={inputClass}/></DialogField><DialogField label="Company / organization"><input value={form.company} onChange={update('company')} placeholder="Company or organization" className={inputClass}/></DialogField></div></div><div className="grid gap-4 sm:grid-cols-2"><DialogField label="Request type"><select value={form.inquiry_type} onChange={update('inquiry_type')} className={inputClass}>{TYPES.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></DialogField><DialogField label="Priority"><select value={form.urgency} onChange={update('urgency')} className={inputClass}><option value="low">Low</option><option value="normal">Normal</option><option value="high">High</option><option value="urgent">Urgent</option></select></DialogField><div className="sm:col-span-2"><DialogField label="Subject" required><input required minLength="5" maxLength="200" value={form.subject} onChange={update('subject')} placeholder="A short summary of your request" className={inputClass}/></DialogField></div><div className="sm:col-span-2"><DialogField label="Request details" required hint={`${form.message.length}/1000`}><textarea required minLength="10" maxLength="1000" rows="5" value={form.message} onChange={update('message')} placeholder="Describe what happened, what you need and any relevant dates or references." className={`${inputClass} resize-none`}/></DialogField></div><div className="sm:col-span-2"><DialogField label="Attachments" hint="Optional · up to 5 files · 10 MB each"><label className="mt-1.5 flex cursor-pointer items-center justify-center gap-2 rounded-xl border border-dashed border-slate-300 bg-slate-50 px-4 py-4 text-sm font-semibold text-slate-600 transition hover:border-blue-400 hover:bg-blue-50"><PaperClipIcon className="h-5 w-5 text-blue-600"/>Attach image or document<input type="file" multiple accept="image/*,.pdf,.doc,.docx,.xls,.xlsx,.csv,.txt,.ppt,.pptx" onChange={addFiles} className="sr-only"/></label></DialogField>{attachments.length > 0 && <div className="mt-2 space-y-2">{attachments.map((file, index) => <div key={`${file.name}-${file.lastModified}`} className="flex items-center justify-between rounded-lg border border-slate-200 px-3 py-2 text-xs"><span className="min-w-0 truncate text-slate-600">{file.name} · {(file.size / 1024 / 1024).toFixed(2)} MB</span><button type="button" onClick={() => setAttachments((current) => current.filter((_, itemIndex) => itemIndex !== index))} className="ml-3 text-red-500 hover:text-red-700">Remove</button></div>)}</div>}{fileError && <p className="mt-2 text-xs font-semibold text-red-600">{fileError}</p>}</div>{error && <div role="alert" className="sm:col-span-2 rounded-xl border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-700">{error}</div>}</div></div><div className="flex flex-col-reverse gap-2 border-t border-slate-200 bg-slate-50 px-6 py-4 sm:flex-row sm:justify-end"><button type="button" onClick={close} className="rounded-xl border border-slate-300 bg-white px-4 py-2.5 text-sm font-semibold text-slate-700 transition hover:bg-slate-50">Cancel</button><button type="submit" disabled={saving || !form.name || !form.email} className="inline-flex min-w-36 items-center justify-center gap-2 rounded-xl bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-blue-700 disabled:cursor-not-allowed disabled:opacity-60">{saving ? <><span className="h-4 w-4 animate-spin rounded-full border-2 border-white/40 border-t-white"/>Submitting</> : <>Submit request <ArrowRightIcon className="h-4 w-4"/></>}</button></div></form></div>
}
const DialogField = ({ label, required = false, hint, children }) => <label className="block text-xs font-semibold text-slate-700"><span className="flex items-center justify-between"><span>{label}{required && <span className="ml-1 text-red-500">*</span>}</span>{hint && <span className="font-normal text-slate-400">{hint}</span>}</span>{children}</label>

import React, { useCallback, useEffect, useState } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { ArrowLeftIcon, CheckCircleIcon, PaperAirplaneIcon, PaperClipIcon, StarIcon, XMarkIcon } from '@heroicons/react/24/outline'
import apiService from '../services/api.service'

const date = (value) => value ? new Date(value).toLocaleString() : '—'
const label = (value = '') => value.replaceAll('_', ' ').replace(/\b\w/g, (letter) => letter.toUpperCase())

export default function MyEnquiryDetail () {
  const { id } = useParams()
  const navigate = useNavigate()
  const [ticket, setTicket] = useState(null)
  const [reply, setReply] = useState('')
  const [comment, setComment] = useState('')
  const [rating, setRating] = useState(5)
  const [recommend, setRecommend] = useState(true)
  const [saving, setSaving] = useState(false)
  const [feedbackOpen, setFeedbackOpen] = useState(false)

  const load = useCallback(async () => {
    const { data } = await apiService.get(`/enquiry/mine/${id}/`)
    const record = data?.enquiry
    setTicket(record)
    // `resolved` is included for tickets confirmed before the new close-first
    // workflow was deployed, so historical requests receive the same prompt.
    if (['resolved', 'closed'].includes(record?.status) && !record?.feedback) setFeedbackOpen(true)
  }, [id])
  useEffect(() => { load() }, [load])

  const sendReply = async () => {
    if (!reply.trim()) return
    setSaving(true)
    try { const { data } = await apiService.post(`/enquiry/mine/${id}/respond/`, { body: reply }); setTicket(data.enquiry); setReply('') } finally { setSaving(false) }
  }
  const confirm = async (accepted) => {
    setSaving(true)
    try { const { data } = await apiService.post(`/enquiry/mine/${id}/resolution/`, { accepted, comment }); setTicket(data.enquiry); setComment(''); if (accepted && data.enquiry?.status === 'closed' && !data.enquiry?.feedback) setFeedbackOpen(true) } finally { setSaving(false) }
  }
  const feedback = async () => {
    setSaving(true)
    try { const { data } = await apiService.post(`/enquiry/mine/${id}/feedback/`, { rating, comment, would_recommend: recommend }); setTicket(data.enquiry); setComment(''); setFeedbackOpen(false) } finally { setSaving(false) }
  }

  if (!ticket) return <div className="grid min-h-[60vh] place-content-center text-sm text-slate-500">Loading request…</div>
  return <main className="min-h-full w-full min-w-0 bg-[#f5f8fc] px-4 py-5 font-sans sm:px-6">
    <button onClick={() => navigate('/my-enquiries')} className="mb-3 inline-flex items-center gap-1 text-xs font-bold text-slate-500"><ArrowLeftIcon className="h-4 w-4"/>My Requests</button>
    <header className="rounded-2xl bg-gradient-to-r from-slate-950 via-blue-950 to-indigo-900 p-6 text-white shadow-lg"><div className="font-mono text-xs font-bold text-cyan-300">{ticket.reference}</div><div className="mt-1 flex flex-wrap items-start justify-between gap-3"><div><h1 className="text-2xl font-bold">{ticket.subject}</h1><p className="mt-1 text-xs text-slate-300">{ticket.department || 'Routing pending'} · Submitted {date(ticket.created_at)}</p></div><span className="rounded-full bg-white/15 px-3 py-1 text-xs font-bold ring-1 ring-white/20">{label(ticket.status)}</span></div></header>
    <div className="mt-4 grid items-start gap-4 xl:grid-cols-[minmax(0,1fr)_360px]">
      <section className="space-y-4">{ticket.attachments?.length > 0 && <Card title={`Attachments · ${ticket.attachments.length}`}><AttachmentList rows={ticket.attachments}/></Card>}<Card title="Conversation"><div className="space-y-3">{(ticket.messages || []).map((message) => <div key={message.id} className={`max-w-[88%] rounded-xl border p-4 text-sm ${message.sender_type === 'requester' ? 'ml-auto border-blue-200 bg-blue-50' : 'border-slate-200 bg-white'}`}><div className="mb-1 flex justify-between gap-2 text-[10px] font-bold uppercase text-slate-400"><span>{message.author?.name || label(message.sender_type)}</span><span>{date(message.created_at)}</span></div><p className="whitespace-pre-wrap leading-6">{message.body}</p></div>)}</div>{!['closed', 'spam', 'pending_confirmation'].includes(ticket.status) && <div className="mt-4 border-t pt-4"><textarea value={reply} onChange={(event) => setReply(event.target.value)} rows="4" placeholder="Add information or reply…" className="w-full rounded-lg border p-3 text-sm"/><div className="mt-2 text-right"><button onClick={sendReply} disabled={saving || !reply.trim()} className="inline-flex items-center gap-2 rounded-lg bg-blue-600 px-4 py-2 text-xs font-bold text-white disabled:opacity-50"><PaperAirplaneIcon className="h-4 w-4"/>Send reply</button></div></div>}</Card></section>
      <aside className="space-y-4">
        {ticket.status === 'pending_confirmation' && <Card title="Resolution approval"><p className="whitespace-pre-wrap text-sm leading-6 text-slate-700">{ticket.resolution_summary}</p><textarea value={comment} onChange={(event) => setComment(event.target.value)} rows="3" placeholder="Optional confirmation or reopening comment" className="mt-4 w-full rounded-lg border p-3 text-xs"/><div className="mt-3 grid grid-cols-2 gap-2"><button onClick={() => confirm(false)} disabled={saving} className="rounded-lg border border-red-200 px-3 py-2 text-xs font-bold text-red-600">Not resolved</button><button onClick={() => confirm(true)} disabled={saving} className="rounded-lg bg-emerald-600 px-3 py-2 text-xs font-bold text-white">Confirm resolved</button></div></Card>}
        {['resolved', 'closed'].includes(ticket.status) && !ticket.feedback && <Card title="After-service feedback"><div className="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-xs leading-5 text-emerald-800">This ticket is complete. Please tell us how the service went.</div><button onClick={() => setFeedbackOpen(true)} className="mt-3 w-full rounded-lg bg-blue-600 px-3 py-2.5 text-xs font-bold text-white">Give feedback</button></Card>}
        {ticket.feedback && <Card title="Your feedback"><div className="text-center text-2xl text-amber-500">{'★'.repeat(ticket.feedback.rating)}{'☆'.repeat(5-ticket.feedback.rating)}</div><p className="mt-2 text-center text-xs text-slate-600">{ticket.feedback.comment || 'Thank you for your rating.'}</p></Card>}
        <Card title="Ticket information"><Info k="Type" v={ticket.inquiry_type_label}/><Info k="Priority" v={label(ticket.urgency)}/><Info k="Representative" v={ticket.assigned_to?.name || 'Assignment pending'}/><Info k="Response due" v={date(ticket.due_at)}/><Info k="Escalation" v={ticket.escalation_level ? `Level ${ticket.escalation_level}` : 'None'}/></Card>
      </aside>
    </div>
    {feedbackOpen && !ticket.feedback && <FeedbackDialog rating={rating} setRating={setRating} comment={comment} setComment={setComment} recommend={recommend} setRecommend={setRecommend} saving={saving} submit={feedback} close={() => setFeedbackOpen(false)} />}
  </main>
}

const Card = ({ title, children }) => <article className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><h2 className="mb-4 text-[11px] font-bold uppercase tracking-wider text-slate-500">{title}</h2>{children}</article>
const AttachmentList = ({ rows }) => <div className="grid gap-2 sm:grid-cols-2">{rows.map((attachment) => <a key={attachment.id} href={attachment.url} target="_blank" rel="noreferrer" className="flex min-w-0 items-center gap-3 rounded-xl border border-slate-200 bg-slate-50 p-3 hover:border-blue-300 hover:bg-blue-50"><PaperClipIcon className="h-5 w-5 shrink-0 text-blue-600"/><span className="min-w-0"><strong className="block truncate text-xs text-slate-700">{attachment.name}</strong><span className="text-[10px] text-slate-400">{(attachment.size / 1024 / 1024).toFixed(2)} MB</span></span></a>)}</div>
const Info = ({ k, v }) => <div className="flex justify-between border-b border-slate-100 py-2 text-xs last:border-0"><span className="text-slate-400">{k}</span><strong className="text-right text-slate-700">{v}</strong></div>
const FeedbackDialog = ({ rating, setRating, comment, setComment, recommend, setRecommend, saving, submit, close }) => <div className="fixed inset-0 z-[120] grid place-items-center overflow-y-auto bg-slate-950/60 p-4 backdrop-blur-sm"><section role="dialog" aria-modal="true" aria-labelledby="feedback-title" className="w-full max-w-lg overflow-hidden rounded-2xl border border-white/20 bg-white shadow-2xl"><div className="h-1 bg-gradient-to-r from-emerald-500 via-cyan-500 to-blue-600"/><div className="relative px-6 pb-6 pt-7 text-center"><button type="button" onClick={close} aria-label="Close feedback prompt" className="absolute right-4 top-4 grid h-8 w-8 place-content-center rounded-lg text-slate-400 hover:bg-slate-100 hover:text-slate-700"><XMarkIcon className="h-4 w-4"/></button><span className="mx-auto grid h-12 w-12 place-content-center rounded-2xl bg-emerald-50 text-emerald-600 ring-1 ring-emerald-100"><CheckCircleIcon className="h-7 w-7"/></span><p className="mt-4 text-[10px] font-bold uppercase tracking-[0.16em] text-emerald-600">Ticket closed</p><h2 id="feedback-title" className="mt-1 text-2xl font-bold tracking-tight text-slate-950">How did we do?</h2><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-slate-500">Your feedback helps RADAI improve response quality and service performance.</p><div className="mt-5 flex justify-center gap-1">{[1, 2, 3, 4, 5].map((value) => <button type="button" key={value} onClick={() => setRating(value)} aria-label={`${value} star rating`}><StarIcon className={`h-9 w-9 transition hover:scale-110 ${value <= rating ? 'fill-amber-400 text-amber-400' : 'text-slate-300'}`}/></button>)}</div><div className="mt-1 text-xs font-semibold text-slate-500">{rating} of 5</div><textarea value={comment} onChange={(event) => setComment(event.target.value)} rows="4" placeholder="Tell us about your experience…" className="mt-5 w-full resize-none rounded-xl border border-slate-300 p-3 text-left text-sm outline-none focus:border-blue-500 focus:ring-4 focus:ring-blue-100"/><label className="mt-3 flex items-center gap-2 text-left text-xs text-slate-600"><input type="checkbox" checked={recommend} onChange={(event) => setRecommend(event.target.checked)} className="rounded border-slate-300"/>I would recommend RADAI support</label><button type="button" onClick={submit} disabled={saving} className="mt-5 inline-flex w-full items-center justify-center rounded-xl bg-blue-600 px-4 py-3 text-sm font-bold text-white transition hover:bg-blue-700 disabled:opacity-50">{saving ? 'Submitting feedback…' : 'Submit feedback'}</button><button type="button" onClick={close} className="mt-2 text-xs font-semibold text-slate-400 hover:text-slate-600">Remind me later</button></div></section></div>

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import apiClient from '../services/api.service';

/**
 * PFD Analysis Console - Phase 1
 * Display comprehensive PFD analysis before P&ID generation
 */
const PFDAnalysisConsole = () => {
  const { documentId } = useParams();
  const navigate = useNavigate();
  
  const [loading, setLoading] = useState(true);
  const [analyzing, setAnalyzing] = useState(false);
  const [analysis, setAnalysis] = useState(null);
  const [error, setError] = useState('');
  const [selectedModules, setSelectedModules] = useState([]);
  const [activeTab, setActiveTab] = useState('overview');

  useEffect(() => {
    loadAnalysis();
  }, [documentId]);

  const loadAnalysis = async () => {
    try {
      setLoading(true);
      // Try to get existing analysis first
      const response = await apiClient.get(`/pfd/documents/${documentId}/get_analysis/`);
      setAnalysis(response.data);
      // Pre-select all modules
      setSelectedModules(response.data.modules?.map(m => m.module_id) || []);
      setLoading(false);
    } catch (err) {
      if (err.response?.status === 404) {
        // No analysis exists, trigger it
        runAnalysis();
      } else {
        setError('Failed to load analysis');
        setLoading(false);
      }
    }
  };

  const runAnalysis = async () => {
    try {
      setAnalyzing(true);
      setError('');
      const response = await apiClient.post(`/pfd/documents/${documentId}/analyze/`);
      setAnalysis(response.data);
      setSelectedModules(response.data.modules?.map(m => m.module_id) || []);
      setAnalyzing(false);
    } catch (err) {
      setError(err.response?.data?.detail || 'Analysis failed');
      setAnalyzing(false);
    }
  };

  const toggleModuleSelection = (moduleId) => {
    setSelectedModules(prev => 
      prev.includes(moduleId) 
        ? prev.filter(id => id !== moduleId)
        : [...prev, moduleId]
    );
  };

  const proceedToPIDGeneration = () => {
    // Navigate to P&ID generation with selected modules
    navigate(`/pfd/convert/${documentId}`, {
      state: { 
        analysis,
        selectedModules 
      }
    });
  };

  if (loading || analyzing) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-purple-50 flex items-center justify-center">
        <div className="text-center">
          <div className="inline-block animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-purple-600 mb-4"></div>
          <h2 className="text-2xl font-bold text-gray-900 mb-2">
            {analyzing ? 'Analyzing PFD Document...' : 'Loading Analysis...'}
          </h2>
          <p className="text-gray-600">
            {analyzing ? 'AI is identifying modules, connectivity, and complexity' : 'Please wait'}
          </p>
        </div>
      </div>
    );
  }

  if (error && !analysis) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-purple-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-xl shadow-2xl p-8 max-w-md">
          <div className="text-red-500 text-center mb-4">
            <svg className="h-16 w-16 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <h2 className="text-2xl font-bold mb-2">Analysis Failed</h2>
            <p className="text-gray-600">{error}</p>
          </div>
          <button
            onClick={() => navigate('/dashboard')}
            className="w-full px-6 py-3 bg-purple-600 text-white rounded-lg hover:bg-purple-700"
          >
            Back to Dashboard
          </button>
        </div>
      </div>
    );
  }

  if (!analysis) return null;

  const complexity = analysis.complexity_analysis || {};
  const modules = analysis.modules || [];
  const connectivity = analysis.connectivity || {};

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-purple-50 py-6 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6">
          <button
            onClick={() => navigate('/dashboard')}
            className="flex items-center text-purple-600 hover:text-purple-800 mb-4"
          >
            <svg className="h-5 w-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
            Back to Dashboard
          </button>
          
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-4xl font-bold bg-gradient-to-r from-purple-600 to-pink-600 bg-clip-text text-transparent mb-2">
                PFD Analysis Console
              </h1>
              <p className="text-gray-600">Phase 1: Understanding your Process Flow Diagram</p>
              <p className="text-sm text-gray-500 mt-1">Document: {analysis.document_name}</p>
            </div>
            <div className="text-right">
              <div className="text-3xl font-bold text-purple-600">{analysis.module_count}</div>
              <div className="text-sm text-gray-600">Modules Identified</div>
            </div>
          </div>
        </div>

        {/* Key Metrics Cards */}
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4 mb-6">
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Total Modules</p>
                <p className="text-2xl font-bold text-purple-600">{analysis.module_count}</p>
              </div>
              <svg className="h-10 w-10 text-purple-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10" />
              </svg>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Complexity</p>
                <p className={`text-2xl font-bold ${
                  complexity.overall_complexity === 'High' ? 'text-red-600' :
                  complexity.overall_complexity === 'Medium' ? 'text-yellow-600' :
                  'text-green-600'
                }`}>
                  {complexity.overall_complexity || 'N/A'}
                </p>
              </div>
              <svg className="h-10 w-10 text-yellow-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Recommended P&IDs</p>
                <p className="text-2xl font-bold text-blue-600">{analysis.recommended_pids}</p>
              </div>
              <svg className="h-10 w-10 text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
              </svg>
            </div>
          </div>

          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center justify-between">
              <div>
                <p className="text-sm text-gray-600">Total Equipment</p>
                <p className="text-2xl font-bold text-green-600">{complexity.total_equipment_estimate || 'N/A'}</p>
              </div>
              <svg className="h-10 w-10 text-green-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6V4m0 2a2 2 0 100 4m0-4a2 2 0 110 4m-6 8a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4m6 6v10m6-2a2 2 0 100-4m0 4a2 2 0 110-4m0 4v2m0-6V4" />
              </svg>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="bg-white rounded-xl shadow-lg overflow-hidden mb-6">
          <div className="border-b border-gray-200">
            <nav className="flex -mb-px">
              {[
                { id: 'overview', label: 'Overview', icon: 'M4 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2V6zM14 6a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2V6zM4 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2H6a2 2 0 01-2-2v-2zM14 16a2 2 0 012-2h2a2 2 0 012 2v2a2 2 0 01-2 2h-2a2 2 0 01-2-2v-2z' },
                { id: 'modules', label: `Modules (${modules.length})`, icon: 'M19 11H5m14 0a2 2 0 012 2v6a2 2 0 01-2 2H5a2 2 0 01-2-2v-6a2 2 0 012-2m14 0V9a2 2 0 00-2-2M5 11V9a2 2 0 012-2m0 0V5a2 2 0 012-2h6a2 2 0 012 2v2M7 7h10' },
                { id: 'connectivity', label: 'Connectivity', icon: 'M13.828 10.172a4 4 0 00-5.656 0l-4 4a4 4 0 105.656 5.656l1.102-1.101m-.758-4.899a4 4 0 005.656 0l4-4a4 4 0 00-5.656-5.656l-1.1 1.1' },
                { id: 'recommendations', label: 'P&ID Strategy', icon: 'M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-3 7h3m-3 4h3m-6-4h.01M9 16h.01' }
              ].map(tab => (
                <button
                  key={tab.id}
                  onClick={() => setActiveTab(tab.id)}
                  className={`flex items-center px-6 py-4 text-sm font-medium border-b-2 transition-colors ${
                    activeTab === tab.id
                      ? 'border-purple-600 text-purple-600'
                      : 'border-transparent text-gray-500 hover:text-gray-700 hover:border-gray-300'
                  }`}
                >
                  <svg className="h-5 w-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={tab.icon} />
                  </svg>
                  {tab.label}
                </button>
              ))}
            </nav>
          </div>

          <div className="p-6">
            {/* Overview Tab */}
            {activeTab === 'overview' && (
              <div className="space-y-6">
                <div className="bg-gradient-to-r from-purple-50 to-pink-50 rounded-lg p-6">
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">Analysis Summary</h3>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4 text-sm">
                    <div>
                      <span className="text-gray-600">Document:</span>
                      <span className="ml-2 font-medium text-gray-900">{analysis.document_name}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Total Modules:</span>
                      <span className="ml-2 font-medium text-gray-900">{analysis.module_count}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Complexity Score:</span>
                      <span className="ml-2 font-medium text-gray-900">{complexity.complexity_score}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Total Connections:</span>
                      <span className="ml-2 font-medium text-gray-900">{complexity.total_connections || 0}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">Safety Critical Modules:</span>
                      <span className="ml-2 font-medium text-red-600">{complexity.safety_critical_modules?.length || 0}</span>
                    </div>
                    <div>
                      <span className="text-gray-600">High Complexity Modules:</span>
                      <span className="ml-2 font-medium text-yellow-600">{complexity.high_complexity_modules?.length || 0}</span>
                    </div>
                  </div>
                </div>

                {/* Process Flow Visualization */}
                {connectivity.main_process_flow && connectivity.main_process_flow.length > 0 && (
                  <div className="bg-white border-2 border-gray-200 rounded-lg p-6">
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">Main Process Flow</h3>
                    <div className="flex items-center space-x-2 overflow-x-auto pb-4">
                      {connectivity.main_process_flow.map((moduleId, idx) => {
                        const module = modules.find(m => m.module_id === moduleId);
                        return (
                          <React.Fragment key={moduleId}>
                            <div className="flex-shrink-0 bg-purple-100 border-2 border-purple-300 rounded-lg px-4 py-3 text-center min-w-[140px]">
                              <div className="text-xs text-purple-600 font-semibold">{moduleId}</div>
                              <div className="text-sm font-medium text-gray-900 mt-1">{module?.module_name || 'Unknown'}</div>
                            </div>
                            {idx < connectivity.main_process_flow.length - 1 && (
                              <svg className="h-6 w-6 text-purple-400 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5l7 7-7 7" />
                              </svg>
                            )}
                          </React.Fragment>
                        );
                      })}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Modules Tab */}
            {activeTab === 'modules' && (
              <div className="space-y-4">
                <div className="flex items-center justify-between mb-4">
                  <h3 className="text-lg font-semibold text-gray-900">Identified Modules</h3>
                  <button
                    onClick={() => {
                      if (selectedModules.length === modules.length) {
                        setSelectedModules([]);
                      } else {
                        setSelectedModules(modules.map(m => m.module_id));
                      }
                    }}
                    className="text-sm text-purple-600 hover:text-purple-800 font-medium"
                  >
                    {selectedModules.length === modules.length ? 'Deselect All' : 'Select All'}
                  </button>
                </div>
                
                <div className="grid grid-cols-1 gap-4">
                  {modules.map(module => (
                    <div
                      key={module.module_id}
                      className={`border-2 rounded-lg p-4 cursor-pointer transition-all ${
                        selectedModules.includes(module.module_id)
                          ? 'border-purple-500 bg-purple-50'
                          : 'border-gray-200 bg-white hover:border-gray-300'
                      }`}
                      onClick={() => toggleModuleSelection(module.module_id)}
                    >
                      <div className="flex items-start justify-between">
                        <div className="flex-1">
                          <div className="flex items-center space-x-3 mb-2">
                            <input
                              type="checkbox"
                              checked={selectedModules.includes(module.module_id)}
                              onChange={() => {}}
                              className="h-5 w-5 text-purple-600 rounded"
                            />
                            <span className="text-xs font-semibold text-purple-600 bg-purple-100 px-2 py-1 rounded">
                              {module.module_id}
                            </span>
                            <h4 className="text-lg font-semibold text-gray-900">{module.module_name}</h4>
                            <span className={`text-xs px-2 py-1 rounded ${
                              module.complexity_level === 'High' ? 'bg-red-100 text-red-700' :
                              module.complexity_level === 'Medium' ? 'bg-yellow-100 text-yellow-700' :
                              'bg-green-100 text-green-700'
                            }`}>
                              {module.complexity_level} Complexity
                            </span>
                            {module.safety_critical && (
                              <span className="text-xs bg-red-100 text-red-700 px-2 py-1 rounded">Safety Critical</span>
                            )}
                          </div>
                          
                          <div className="ml-8 space-y-2 text-sm">
                            <div>
                              <span className="text-gray-600">Type:</span>
                              <span className="ml-2 font-medium">{module.module_type}</span>
                            </div>
                            <div>
                              <span className="text-gray-600">Function:</span>
                              <span className="ml-2 text-gray-700">{module.primary_function}</span>
                            </div>
                            <div>
                              <span className="text-gray-600">Equipment Count:</span>
                              <span className="ml-2 font-medium">{module.estimated_equipment_count}</span>
                            </div>
                            <div>
                              <span className="text-gray-600">Key Equipment:</span>
                              <span className="ml-2 text-gray-700">{module.key_equipment?.join(', ')}</span>
                            </div>
                            {module.utilities_required && module.utilities_required.length > 0 && (
                              <div>
                                <span className="text-gray-600">Utilities:</span>
                                <span className="ml-2 text-gray-700">{module.utilities_required.join(', ')}</span>
                              </div>
                            )}
                          </div>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}

            {/* Connectivity Tab */}
            {activeTab === 'connectivity' && (
              <div className="space-y-6">
                <div>
                  <h3 className="text-lg font-semibold text-gray-900 mb-4">Module Connections</h3>
                  <div className="space-y-3">
                    {connectivity.connections && connectivity.connections.length > 0 ? (
                      connectivity.connections.map((conn, idx) => (
                        <div key={idx} className="flex items-center bg-gray-50 rounded-lg p-4">
                          <div className="flex-1 flex items-center space-x-4">
                            <div className="bg-purple-100 text-purple-700 font-semibold px-3 py-2 rounded text-sm">
                              {conn.from_module}
                            </div>
                            <svg className="h-6 w-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7l5 5m0 0l-5 5m5-5H6" />
                            </svg>
                            <div className="flex-1">
                              <div className="text-sm font-medium text-gray-900">{conn.stream_name}</div>
                              <div className="text-xs text-gray-500">{conn.stream_type}</div>
                            </div>
                            <svg className="h-6 w-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7l5 5m0 0l-5 5m5-5H6" />
                            </svg>
                            <div className="bg-blue-100 text-blue-700 font-semibold px-3 py-2 rounded text-sm">
                              {conn.to_module}
                            </div>
                            {conn.is_critical && (
                              <span className="bg-red-100 text-red-700 text-xs px-2 py-1 rounded">Critical</span>
                            )}
                          </div>
                        </div>
                      ))
                    ) : (
                      <div className="text-center text-gray-500 py-8">
                        No connections data available
                      </div>
                    )}
                  </div>
                </div>

                {connectivity.utility_connections && Object.keys(connectivity.utility_connections).length > 0 && (
                  <div>
                    <h3 className="text-lg font-semibold text-gray-900 mb-4">Utility Connections</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                      {Object.entries(connectivity.utility_connections).map(([utility, moduleIds]) => (
                        <div key={utility} className="bg-green-50 border border-green-200 rounded-lg p-4">
                          <div className="font-semibold text-green-800 mb-2 capitalize">{utility.replace('_', ' ')}</div>
                          <div className="flex flex-wrap gap-2">
                            {moduleIds.map(moduleId => (
                              <span key={moduleId} className="bg-green-100 text-green-700 text-xs px-2 py-1 rounded">
                                {moduleId}
                              </span>
                            ))}
                          </div>
                        </div>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}

            {/* Recommendations Tab */}
            {activeTab === 'recommendations' && (
              <div className="space-y-6">
                <div className="bg-gradient-to-r from-blue-50 to-purple-50 rounded-lg p-6">
                  <h3 className="text-lg font-semibold text-gray-900 mb-2">Recommended P&ID Strategy</h3>
                  <p className="text-gray-700 mb-4">
                    Strategy: <span className="font-semibold">{analysis.coverage_plan?.strategy}</span>
                  </p>
                  <p className="text-sm text-gray-600">
                    Based on the analysis, we recommend creating <span className="font-semibold text-purple-600">{analysis.recommended_pids} P&ID(s)</span> for optimal coverage and clarity.
                  </p>
                </div>

                <div className="space-y-4">
                  {analysis.coverage_plan?.plan?.map((pidPlan, idx) => (
                    <div key={idx} className="border-2 border-gray-200 rounded-lg p-6 bg-white">
                      <div className="flex items-start justify-between mb-4">
                        <div>
                          <h4 className="text-lg font-semibold text-gray-900">{pidPlan.pid_number}: {pidPlan.pid_title}</h4>
                          <p className="text-sm text-gray-600 mt-1">{pidPlan.rationale}</p>
                        </div>
                        <div className="text-right">
                          <div className="text-2xl font-bold text-purple-600">{pidPlan.estimated_equipment}</div>
                          <div className="text-xs text-gray-600">Equipment Items</div>
                        </div>
                      </div>
                      
                      <div>
                        <div className="text-sm text-gray-600 mb-2">Modules Covered:</div>
                        <div className="flex flex-wrap gap-2">
                          {pidPlan.modules_covered?.map(moduleId => {
                            const module = modules.find(m => m.module_id === moduleId);
                            return (
                              <div key={moduleId} className="bg-purple-100 text-purple-700 px-3 py-2 rounded text-sm">
                                <div className="font-semibold">{moduleId}</div>
                                <div className="text-xs">{module?.module_name}</div>
                              </div>
                            );
                          })}
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Action Buttons */}
        <div className="bg-white rounded-xl shadow-lg p-6">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="text-lg font-semibold text-gray-900 mb-1">Ready to Generate P&IDs?</h3>
              <p className="text-sm text-gray-600">
                {selectedModules.length} of {modules.length} modules selected for P&ID generation
              </p>
            </div>
            <div className="flex space-x-4">
              <button
                onClick={() => navigate('/dashboard')}
                className="px-6 py-3 border-2 border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium transition-colors"
              >
                Save & Exit
              </button>
              <button
                onClick={proceedToPIDGeneration}
                disabled={selectedModules.length === 0}
                className="px-8 py-3 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 disabled:from-gray-300 disabled:to-gray-400 disabled:cursor-not-allowed font-medium transition-all shadow-lg flex items-center space-x-2"
              >
                <span>Proceed to Phase 2: P&ID Generation</span>
                <svg className="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 7l5 5m0 0l-5 5m5-5H6" />
                </svg>
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PFDAnalysisConsole;

import React, { useState, useEffect, useRef } from 'react';
import { useSelector } from 'react-redux';
import { artifactDownloadFilename, conversionReviewLabel, hasConversionAction, isNewUnreviewedArtifact, pfdOperationError } from '../utils/pfdArtifactState';
import { useParams, useNavigate } from 'react-router-dom';
import apiClient from '../services/api.service';
import PIDEngineeringResults from '../components/PIDEngineeringResults';
import PID2DGenerator from '../components/pid/PID2DGenerator';
import PIDDesignCheck from '../components/pid/PIDDesignCheck';

/**
 * PFD Conversion Results & P&ID Generation Page
 * Shows stored output identity and explicitly requested P&ID generation.
 * Uses 3-Step Engineering Workflow Display Component
 * Includes P&ID Design Check for verification
 */
const PFDConvert = () => {
  const { documentId } = useParams();
  const navigate = useNavigate();

  const { user } = useSelector(state => state.auth);
  const [pfdDocument, setPfdDocument] = useState(null);
  const [pidConversion, setPidConversion] = useState(null);
  const [conversions, setConversions] = useState([]);
  const [historyReady, setHistoryReady] = useState(false);
  const [loading, setLoading] = useState(true);
  const [generating, setGenerating] = useState(false);
  const [downloading, setDownloading] = useState(false);
  const [canvasLoading, setCanvasLoading] = useState(false);
  const [error, setError] = useState('');
  const [notice, setNotice] = useState('');
  const [activeTab, setActiveTab] = useState('pfd');
  const [viewMode, setViewMode] = useState('specifications');
  const selectedId = useRef(null);
  const loadSequence = useRef(0);
  const canGenerate = user?.module_actions?.pfd_to_pid?.includes('create') === true;
  const canRegenerate = historyReady && hasConversionAction(pidConversion, 'regenerate') &&
    Boolean(pidConversion?.updated_at && pidConversion?.artifact?.sha256);
  const canDownload = hasConversionAction(pidConversion, 'download') && pidConversion?.artifact?.available === true;

  const selectConversion = conversion => {
    if (selectedId.current !== conversion?.id) sessionStorage.removeItem('canvasLoadData');
    selectedId.current = conversion?.id || null;
    setPidConversion(conversion || null);
  };

  // Opening or refreshing a result is read-only. Initial generation is explicit
  // and available only after a successful history read establishes absence.
  const loadPFDDocument = async () => {
    const sequence = ++loadSequence.current;
    setLoading(true);
    setHistoryReady(false);
    setError('');
    try {
      const documentResponse = await apiClient.get(`/pfd/documents/${documentId}/`);
      if (sequence !== loadSequence.current) return;
      setPfdDocument(documentResponse.data);
      const response = await apiClient.get(`/pfd/conversions/?pfd_document=${documentId}`);
      if (sequence !== loadSequence.current) return;
      const rows = Array.isArray(response.data) ? response.data : response.data?.results;
      if (!Array.isArray(rows) || rows.some(row => !row?.id)) throw new Error('Invalid output history');
      setConversions(rows);
      selectConversion(rows.find(row => row.id === selectedId.current) || rows[0] || null);
      setHistoryReady(true);
    } catch (err) {
      if (sequence === loadSequence.current) {
        setError(await pfdOperationError(err, 'Output history could not be loaded. Reload outputs before generating or regenerating. Previously displayed evidence has been preserved.'));
      }
    } finally {
      if (sequence === loadSequence.current) setLoading(false);
    }
  };

  useEffect(() => {
    sessionStorage.removeItem('canvasLoadData');
    setGenerating(false);
    setDownloading(false);
    setCanvasLoading(false);
    selectedId.current = null;
    setPidConversion(null);
    setPfdDocument(null);
    setConversions([]);
    setNotice('');
    void loadPFDDocument();
    return () => { loadSequence.current += 1; sessionStorage.removeItem('canvasLoadData'); };
  }, [documentId]);

  const recordNewConversion = conversion => {
    setConversions(previous => [conversion, ...previous.filter(row => row.id !== conversion.id)]);
    selectConversion(conversion);
    setActiveTab('pid');
  };

  const generatePID = async (intelligent = false) => {
    if (!historyReady || conversions.length || !canGenerate || !pfdDocument?.extracted_data || generating) return;
    const sequence = loadSequence.current;
    setGenerating(true);
    setError('');
    setNotice('');
    try {
      const drawingNumber = (pfdDocument.document_number || 'PFD-001').replace('PFD', 'P&ID');
      const response = await apiClient.post(intelligent ? '/pfd/conversions/intelligent-generate/' : '/pfd/conversions/generate/', {
        pfd_document_id: documentId,
        pid_drawing_number: drawingNumber + (intelligent ? '-INT' : ''),
        pid_title: (pfdDocument.document_title || 'Generated P&ID') + (intelligent ? ' (Intelligent)' : ''),
        pid_revision: pfdDocument.revision || 'A',
      }, { timeout: intelligent ? 360000 : 300000 });
      if (sequence !== loadSequence.current) return;
      if (!response.data?.id) throw new Error('Generation response has no output identity');
      recordNewConversion(response.data);
      setNotice('Generation returned an output. Review the recorded artifact and review state below.');
    } catch (err) {
      if (sequence !== loadSequence.current) return;
      setError(await pfdOperationError(err, 'Generation failed or its outcome could not be confirmed. Reload outputs before retrying.'));
      setHistoryReady(false);
    } finally {
      if (sequence === loadSequence.current) setGenerating(false);
    }
  };

  const regeneratePID = async () => {
    if (!canRegenerate || !pidConversion?.updated_at || !pidConversion?.artifact?.sha256 || generating) return;
    const original = pidConversion;
    const sequence = loadSequence.current;
    setGenerating(true);
    setError('');
    setNotice('');
    try {
      const response = await apiClient.post(`/pfd/conversions/${original.id}/regenerate/`, {
        expected_updated_at: original.updated_at,
        expected_artifact_sha256: original.artifact.sha256,
      }, { timeout: 300000 });
      if (sequence !== loadSequence.current || selectedId.current !== original.id) return;
      if (!isNewUnreviewedArtifact(original, response.data)) {
        setHistoryReady(false);
        setError('Regeneration did not confirm a distinct unreviewed artifact. The selected output is preserved. Reload outputs to check the result.');
        return;
      }
      recordNewConversion(response.data);
      setNotice('A new unreviewed output was created. The original output and its review evidence remain available in Output version.');
    } catch (err) {
      if (sequence !== loadSequence.current || selectedId.current !== original.id) return;
      setError(await pfdOperationError(err, 'Regeneration failed. The original output and its review evidence have been preserved.'));
      setHistoryReady(false);
    } finally {
      if (sequence === loadSequence.current) setGenerating(false);
    }
  };

  const downloadPIDSpec = () => {
    if (!pidConversion) return;

    const dataStr = JSON.stringify(pidConversion, null, 2);
    const dataBlob = new Blob([dataStr], { type: 'application/json' });
    const url = URL.createObjectURL(dataBlob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${pidConversion.pid_drawing_number || 'PID'}_${pidConversion.id}_specifications.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const downloadPIDDrawing = async () => {
    if (!canDownload || downloading) return;
    const output = pidConversion;
    const sequence = loadSequence.current;
    setDownloading(true);
    setError('');
    try {
      const response = await apiClient.get(`/pfd/conversions/${output.id}/download_drawing/`, { responseType: 'blob' });
      if (sequence !== loadSequence.current || selectedId.current !== output.id) return;
      const url = URL.createObjectURL(response.data);
      const link = document.createElement('a');
      link.href = url;
      link.download = artifactDownloadFilename(output, response.headers);
      link.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      if (sequence !== loadSequence.current || selectedId.current !== output.id) return;
      setError(await pfdOperationError(err, 'The stored drawing could not be downloaded. Download does not generate or replace an output.'));
    } finally {
      if (sequence === loadSequence.current) setDownloading(false);
    }
  };

  const loadToCanvas = async conversionId => {
    if (!conversionId || canvasLoading) return;
    const sequence = loadSequence.current;
    setCanvasLoading(true);
    setError('');
    setNotice('Loading this output into the canvas...');
    try {
      const response = await apiClient.get(`/pfd/conversions/${conversionId}/load-to-canvas/`);
      if (sequence !== loadSequence.current || selectedId.current !== conversionId) return;
      sessionStorage.setItem('canvasLoadData', JSON.stringify({ ...response.data, conversion_id: conversionId }));
      setViewMode('2d-diagram');
      setNotice('This output was loaded into the canvas. Canvas edits do not change the stored drawing or its review.');
    } catch (err) {
      if (sequence !== loadSequence.current || selectedId.current !== conversionId) return;
      setNotice('');
      setError(await pfdOperationError(err, 'This output could not be loaded into the canvas. The stored drawing and review are unchanged.'));
    } finally {
      if (sequence === loadSequence.current) setCanvasLoading(false);
    }
  };

  if (loading && !pfdDocument) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-purple-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-purple-600 mx-auto mb-4"></div>
          <p className="text-gray-600 text-lg">Loading PFD data...</p>
        </div>
      </div>
    );
  }

  if (error && !pfdDocument) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-purple-50 flex items-center justify-center px-4">
        <div className="bg-white rounded-xl shadow-xl p-8 max-w-md w-full">
          <div className="text-center">
            <svg className="h-16 w-16 text-red-500 mx-auto mb-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            </svg>
            <h2 className="text-2xl font-bold text-gray-900 mb-2">Error</h2>
            <p className="text-gray-600 mb-6">{error}</p>
            <button
              onClick={() => navigate('/pfd/upload')}
              className="px-6 py-3 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors"
            >
              Back to Upload
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-purple-50 py-6 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6">
          <button
            onClick={() => navigate('/dashboard')}
            className="flex items-center text-purple-600 hover:text-purple-800 mb-4"
          >
            <svg className="h-5 w-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
            Back to Dashboard
          </button>

          <div className="bg-white rounded-xl shadow-lg p-6">
            <div className="flex items-start justify-between">
              <div className="flex-1">
                <h1 className="text-3xl font-bold text-gray-900 mb-2">
                  {pfdDocument?.document_title || 'PFD Conversion'}
                </h1>
                <div className="flex flex-wrap gap-4 text-sm text-gray-600">
                  {pfdDocument?.document_number && (
                    <div className="flex items-center">
                      <svg className="h-4 w-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                      </svg>
                      <span>{pfdDocument.document_number}</span>
                    </div>
                  )}
                  {pfdDocument?.revision && (
                    <div className="flex items-center">
                      <svg className="h-4 w-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 7h.01M7 3h5c.512 0 1.024.195 1.414.586l7 7a2 2 0 010 2.828l-7 7a2 2 0 01-2.828 0l-7-7A1.994 1.994 0 013 12V7a4 4 0 014-4z" />
                      </svg>
                      <span>Rev {pfdDocument.revision}</span>
                    </div>
                  )}
                  {pfdDocument?.project_name && (
                    <div className="flex items-center">
                      <svg className="h-4 w-4 mr-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                      </svg>
                      <span>{pfdDocument.project_name}</span>
                    </div>
                  )}
                </div>
              </div>

              {/* Status Badge */}
              <div className={`px-4 py-2 rounded-full text-sm font-medium ${
                pfdDocument?.status === 'converted' ? 'bg-green-100 text-green-800' :
                pfdDocument?.status === 'processing' ? 'bg-yellow-100 text-yellow-800' :
                'bg-red-100 text-red-800'
              }`}>
                {pfdDocument?.status === 'converted' ? '✓ Extracted' :
                 pfdDocument?.status === 'processing' ? '⏳ Processing' :
                 '✗ Failed'}
              </div>
            </div>
          </div>
        </div>

        {notice && <div role="status" className="bg-blue-50 border border-blue-200 rounded-xl p-4 mb-6 text-blue-900">{notice}</div>}
        {generating && pidConversion && <div role="status" className="bg-blue-50 border border-blue-200 rounded-xl p-4 mb-6 text-blue-900">Creating a separate unreviewed output. The selected original is retained.</div>}

        {/* Error Banner */}
        {error && pfdDocument && (
          <div role="alert" className="bg-red-50 border-2 border-red-200 rounded-xl p-4 mb-6">
            <div className="flex items-start justify-between">
              <div className="flex">
                <svg className="h-5 w-5 text-red-400 mr-3 mt-0.5 flex-shrink-0" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
                <div className="flex-1">
                  <h4 className="text-red-800 font-medium">Output operation unavailable</h4>
                  <p className="text-red-700 text-sm mt-1">{error}</p>
                </div>
              </div>
              <button
                onClick={loadPFDDocument}
                disabled={loading || generating || downloading || canvasLoading}
                className="ml-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors text-sm font-medium flex-shrink-0"
              >                Reload outputs
              </button>
            </div>
          </div>
        )}

        {/* Tabs */}
        <div className="bg-white rounded-xl shadow-lg overflow-hidden">
          <div className="border-b border-gray-200">
            <nav className="flex relative z-10">
              <button
                onClick={() => setActiveTab('pfd')}
                className={`flex-1 py-4 px-6 text-center font-medium transition-colors cursor-pointer ${
                  activeTab === 'pfd'
                    ? 'border-b-2 border-purple-600 text-purple-600 bg-purple-50'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-50'
                }`}
                type="button"
              >
                <span className="flex items-center justify-center">
                  <svg className="h-5 w-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                  </svg>
                  Extracted PFD Data
                </span>
              </button>
              <button
                onClick={() => setActiveTab('pid')}
                className={`flex-1 py-4 px-6 text-center font-medium transition-colors cursor-pointer ${
                  activeTab === 'pid'
                    ? 'border-b-2 border-purple-600 text-purple-600 bg-purple-50'
                    : 'text-gray-600 hover:text-gray-900 hover:bg-gray-50'
                }`}
                type="button"
                style={{ pointerEvents: 'auto', position: 'relative', zIndex: 10 }}
              >
                <span className="flex items-center justify-center">
                  <svg className="h-5 w-5 mr-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M11 4a2 2 0 114 0v1a1 1 0 001 1h3a1 1 0 011 1v3a1 1 0 01-1 1h-1a2 2 0 100 4h1a1 1 0 011 1v3a1 1 0 01-1 1h-3a1 1 0 01-1-1v-1a2 2 0 10-4 0v1a1 1 0 01-1 1H7a1 1 0 01-1-1v-3a1 1 0 00-1-1H4a2 2 0 110-4h1a1 1 0 001-1V7a1 1 0 011-1h3a1 1 0 001-1V4z" />
                  </svg>
                  Generated P&ID
                  {generating && <span className="ml-2 animate-pulse">⏳</span>}
                </span>
              </button>
            </nav>
          </div>

          <div className="p-6">
            {/* PFD Data Tab */}
            {activeTab === 'pfd' && pfdDocument?.extracted_data && (
              <div className="space-y-6">
                {/* Check if data has 3-step structure */}
                {(pfdDocument.extracted_data.step1_core_extraction || 
                  pfdDocument.extracted_data.step2_pid_structure || 
                  pfdDocument.extracted_data.step3_detailed_engineering) ? (
                  <PIDEngineeringResults data={pfdDocument.extracted_data} />
                ) : (
                  <PFDDataView data={pfdDocument.extracted_data} />
                )}
              </div>
            )}

            {/* P&ID Tab */}
            {activeTab === 'pid' && (
              <div className="space-y-6">
                {generating && !pidConversion ? (
                  <div className="text-center py-12">
                    <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-purple-600 mx-auto mb-4"></div>
                    <h3 className="text-xl font-semibold text-gray-900 mb-2">Generating P&ID Specifications...</h3>
                    <p className="text-gray-600 mb-4">
                      AI is analyzing PFD data using 3-step engineering workflow and creating detailed P&ID specifications with instrumentation, piping, and safety systems
                    </p>
                    <div className="bg-blue-50 border border-blue-200 rounded-lg p-4 max-w-2xl mx-auto mt-6">
                      <p className="text-sm text-blue-800">
                        <strong>⏱️ This process may take 2-5 minutes</strong> as we make multiple AI calls to generate comprehensive P&ID specifications.
                      </p>
                      <p className="text-xs text-blue-600 mt-2">
                        Completion is confirmed only when an output is returned. If the request times out, reload outputs to check before retrying.
                      </p>
                    </div>
                  </div>
                ) : pidConversion ? (
                  <>
                    <section aria-label="Output identity and review" className="rounded-lg border border-gray-200 bg-gray-50 p-4 space-y-3">
                      <div className="flex flex-wrap items-end gap-3">
                        <div className="min-w-0 flex-1">
                          <label htmlFor="pfd-output-version" className="block text-sm font-medium text-gray-800 mb-1">Output version</label>
                          <select id="pfd-output-version" value={pidConversion.id} disabled={generating || loading || downloading || canvasLoading}
                            onChange={event => { selectConversion(conversions.find(row => row.id === event.target.value)); setNotice(''); setError(''); }}
                            className="w-full min-w-0 rounded-md border border-gray-300 bg-white p-2 text-sm">
                            {conversions.map(row => <option key={row.id} value={row.id}>{row.pid_drawing_number || 'P&ID'} - Rev {row.pid_revision || 'Unavailable'} - {row.id} - {conversionReviewLabel(row)}</option>)}
                          </select>
                        </div>
                        <button type="button" onClick={loadPFDDocument} disabled={loading || generating || downloading || canvasLoading} className="px-4 py-2 rounded-md border border-gray-300 bg-white text-sm text-gray-800 disabled:opacity-50">{loading ? 'Loading outputs...' : 'Reload outputs'}</button>
                      </div>
                      <dl className="text-sm space-y-1 break-words">
                        <div><dt className="inline font-medium">Output identity: </dt><dd className="inline">{pidConversion.artifact?.identity || pidConversion.id}</dd></div>
                        <div><dt className="inline font-medium">Drawing revision: </dt><dd className="inline">{pidConversion.pid_revision || 'Unavailable'}</dd></div>
                        <div><dt className="inline font-medium">Review state: </dt><dd className="inline">{conversionReviewLabel(pidConversion)}</dd></div>
