                    <span className="text-gray-400">→</span>
                    <span className="px-3 py-1 bg-green-100 text-green-800 rounded font-medium text-sm">
                      {conn.to_module}
                    </span>
                  </div>
                  <span className="text-xs text-gray-500">{conn.connection_type}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Utility Connections */}
        {Object.keys(utilityConnections).length > 0 && (
          <div className="bg-white p-6 rounded-lg border border-gray-200">
            <h4 className="font-semibold text-gray-900 mb-4 flex items-center">
              <span className="mr-2">⚡</span> Utility Connections
            </h4>
            <div className="grid md:grid-cols-2 gap-4">
              {Object.entries(utilityConnections).map(([utility, modules]) => (
                <div key={utility} className="p-4 bg-purple-50 rounded-lg">
                  <h5 className="font-medium text-purple-900 mb-2">{utility}</h5>
                  <div className="flex flex-wrap gap-2">
                    {modules.map((module, i) => (
                      <span key={i} className="px-2 py-1 bg-white text-purple-800 rounded text-xs">
                        {module}
                      </span>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Critical Paths */}
        {criticalPaths.length > 0 && (
          <div className="bg-orange-50 p-6 rounded-lg border border-orange-200">
            <h4 className="font-semibold text-orange-900 mb-4 flex items-center">
              <span className="mr-2">⚠️</span> Critical Process Paths
            </h4>
            <div className="space-y-3">
              {criticalPaths.map((path, idx) => (
                <div key={idx} className="bg-white p-4 rounded-lg">
                  <div className="font-medium text-gray-900 mb-2">{path.description}</div>
                  <div className="flex flex-wrap gap-2">
                    {path.modules && path.modules.map((module, i) => (
                      <span key={i} className="px-3 py-1 bg-orange-100 text-orange-800 rounded-full text-sm">
                        {module}
                      </span>
                    ))}
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Isolated Modules Warning */}
        {stage5.isolated_modules && stage5.isolated_modules.length > 0 && (
          <div className="bg-red-50 p-6 rounded-lg border border-red-200">
            <h4 className="font-semibold text-red-900 mb-2 flex items-center">
              <span className="mr-2">⚠️</span> Isolated Modules ({stage5.isolated_modules.length})
            </h4>
            <p className="text-red-700 text-sm mb-3">
              These modules have no identified connections and may require review
            </p>
            <div className="flex flex-wrap gap-2">
              {stage5.isolated_modules.map((module, i) => (
                <span key={i} className="px-3 py-1 bg-red-100 text-red-800 rounded font-medium text-sm">
                  {module}
                </span>
              ))}
            </div>
          </div>
        )}
      </div>
    );
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600">Loading analysis...</p>
        </div>
      </div>
    );
  }

  const hasAnalysis = analysis && (
    analysis.stage1_module_identification || 
    analysis.stage2_module_details || 
    analysis.stage3_pid_complexity || 
    analysis.stage4_module_coverage || 
    analysis.stage5_connectivity
  );

  return (
    <div className="container mx-auto px-4 py-8 max-w-7xl">
      {/* Header */}
      <div className="mb-8">
        <button
          onClick={() => navigate('/pfd/history')}
          className="text-blue-600 hover:text-blue-800 mb-4 flex items-center"
        >
          ← Back to History
        </button>
        
        <div className="bg-white p-6 rounded-lg shadow-md border border-gray-200">
          <h1 className="text-3xl font-bold text-gray-900 mb-2">
            5-Stage PFD Analysis
          </h1>
          {document && (
            <div className="flex items-center space-x-4 text-sm text-gray-600">
              <span>Document: <strong>{document.document_number}</strong></span>
              <span>•</span>
              <span>Project: <strong>{document.project_name}</strong></span>
              <span>•</span>
              <span className={`px-3 py-1 rounded-full ${
                document.status === 'analyzed' ? 'bg-green-100 text-green-800' :
                document.status === 'analyzing' ? 'bg-yellow-100 text-yellow-800' :
                'bg-gray-100 text-gray-800'
              }`}>
                {document.status}
              </span>
            </div>
          )}
        </div>
      </div>

      {error && (
        <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg text-red-800">
          {error}
        </div>
      )}

      {/* Analysis Controls */}
      {!hasAnalysis && (
        <div className="mb-8 bg-blue-50 p-8 rounded-lg border border-blue-200 text-center">
          <h3 className="text-xl font-semibold text-gray-900 mb-4">
            Start 5-Stage Analysis
          </h3>
          <p className="text-gray-700 mb-6">
            This will analyze the PFD document through 5 comprehensive stages using advanced AI models
          </p>
          <button
            onClick={startAnalysis}
            disabled={analyzing}
            className="px-8 py-3 bg-blue-600 text-white rounded-lg font-medium hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed transition-colors"
          >
            {analyzing ? (
              <span className="flex items-center">
                <svg className="animate-spin -ml-1 mr-3 h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                  <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                  <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                </svg>
                Analyzing...
              </span>
            ) : (
              '🚀 Start Analysis'
            )}
          </button>
        </div>
      )}

      {/* Analysis Results */}
      {hasAnalysis && (
        <>
          {/* Progress Bar */}
          {analysis.analysis_progress !== undefined && (
            <div className="mb-6 bg-white p-4 rounded-lg shadow">
              <div className="flex justify-between items-center mb-2">
                <span className="text-sm font-medium text-gray-700">
                  Analysis Progress: Stage {analysis.analysis_stage}/5
                </span>
                <span className="text-sm font-medium text-blue-600">
                  {analysis.analysis_progress}%
                </span>
              </div>
              <div className="w-full bg-gray-200 rounded-full h-3">
                <div
                  className="bg-blue-600 h-3 rounded-full transition-all duration-500"
                  style={{ width: `${analysis.analysis_progress}%` }}
                ></div>
              </div>
            </div>
          )}

          {/* Stage Navigation */}
          {renderStageNav()}

          {/* Stage Content */}
          <div className="min-h-screen">
            {activeStage === 1 && renderStage1()}
            {activeStage === 2 && renderStage2()}
            {activeStage === 3 && renderStage3()}
            {activeStage === 4 && renderStage4()}
            {activeStage === 5 && renderStage5()}
          </div>

          {/* Refresh Button */}
          <div className="mt-8 flex justify-center">
            <button
              onClick={fetchAnalysis}
              className="px-6 py-2 bg-gray-600 text-white rounded-lg hover:bg-gray-700 transition-colors"
            >
              🔄 Refresh Analysis
            </button>
          </div>
        </>
      )}
    </div>
  );
};

export default PFDFiveStageAnalysis;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient from '../services/api.service';
import UPLOAD_REQUIREMENTS, { areRequiredDocumentsUploaded, getUploadMode, validateFile as validateFileHelper } from '../config/uploadRequirements.config';

/**
 * PFD Upload Page
 * Upload Process Flow Diagrams for AI-powered conversion to P&ID
 * Philosophy document is now OPTIONAL (configurable in uploadRequirements.config.js)
 */
const PFDUpload = () => {
  const navigate = useNavigate();
  const [file, setFile] = useState(null);
  const [philosophyFile, setPhilosophyFile] = useState(null);
  const [formData, setFormData] = useState({
    document_title: '',
    document_number: '',
    revision: '',
    project_name: '',
    project_code: ''
  });
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState('');
  const [uploadMode, setUploadMode] = useState(null);

  const validateFile = (selectedFile, fileType = 'PFD') => {
    const validation = validateFileHelper(selectedFile);
    if (!validation.valid) {
      setError(`${fileType}: ${validation.error}`);
      return false;
    }
    return true;
  };

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile && validateFile(selectedFile, 'PFD')) {
      setFile(selectedFile);
      setError('');
      // Update upload mode
      updateUploadMode({ pfd: selectedFile, philosophy: philosophyFile });
    }
  };

  const handlePhilosophyFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile && validateFile(selectedFile, 'Philosophy')) {
      setPhilosophyFile(selectedFile);
      setError('');
      // Update upload mode
      updateUploadMode({ pfd: file, philosophy: selectedFile });
    }
  };

  const updateUploadMode = (docs) => {
    const mode = getUploadMode(docs);
    setUploadMode(mode);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Soft-coded validation using configuration
    const uploadedDocs = { pfd: file, philosophy: philosophyFile };
    
    if (!file) {
      setError(UPLOAD_REQUIREMENTS.messages.pfdRequired);
      return;
    }

    // Check if all REQUIRED documents are uploaded (philosophy is now optional)
    if (!areRequiredDocumentsUploaded(uploadedDocs)) {
      setError('Please upload all required documents');
      return;
    }

    setUploading(true);
    setProgress(10);

    try {
      const uploadData = new FormData();
      uploadData.append('file', file);
      
      // Only append philosophy file if uploaded (optional)
      if (philosophyFile) {
        uploadData.append('philosophy_file', philosophyFile);
      }
      
      // Add metadata if provided
      if (formData.document_title) uploadData.append('document_title', formData.document_title);
      if (formData.document_number) uploadData.append('document_number', formData.document_number);
      if (formData.revision) uploadData.append('revision', formData.revision);
      if (formData.project_name) uploadData.append('project_name', formData.project_name);
      if (formData.project_code) uploadData.append('project_code', formData.project_code);

      setProgress(30);

      const response = await apiClient.post('/pfd/documents/upload/', uploadData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        onUploadProgress: (progressEvent) => {
          const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
          setProgress(30 + (percentCompleted * 0.7)); // 30-100%
        },
      });

      setProgress(100);
      
      // Navigate to Phase 1: PFD Analysis Console
      setTimeout(() => {
        navigate(`/pfd/analyze/${response.data.id}`);
      }, 500);

    } catch (err) {
      console.error('Upload failed:', err);
      setError(err.response?.data?.error || err.response?.data?.detail || 'Upload failed. Please try again.');
      setUploading(false);
      setProgress(0);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 to-purple-50 px-3 py-6 sm:px-4 sm:py-8">
      <div className="w-full">
        <div className="mb-6 sm:mb-8">
          <div className="flex items-center justify-between mb-2">
            <h1 className="text-4xl font-bold bg-gradient-to-r from-purple-600 to-pink-600 bg-clip-text text-transparent">
              Upload PFD & Philosophy Documents
            </h1>
          </div>
          
          {/* RAG Information Banner */}
          <div className="bg-gradient-to-r from-green-50 to-teal-50 border-l-4 border-green-500 p-4 mb-6 rounded-r-lg shadow-sm">
            <div className="flex items-start">
              <svg className="h-6 w-6 text-green-600 mr-3 mt-0.5 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z" />
              </svg>
              <div className="flex-1">
                <h3 className="text-sm font-bold text-green-900 mb-1">
                  🤖 AI-Enhanced Analysis with RAG (Retrieval Augmented Generation)
                </h3>
                <p className="text-xs text-green-800 leading-relaxed">
                  Your PFD will be analyzed using intelligent context retrieval. The system automatically searches 
                  for similar reference PFDs from your S3 bucket (<span className="font-mono font-semibold">rejlers-engineering-data</span>) 
                  and uses them as context to provide more accurate analysis based on your organization's historical project data.
                </p>
              </div>
            </div>
          </div>
          
          {/* Upload Mode Notice - Dynamic based on uploaded files */}
          {uploadMode && (
              <div className={`border-l-4 p-4 mb-6 ${
                uploadMode.requiredDocs.includes('philosophy') 
                  ? 'bg-blue-50 border-blue-500' 
                  : 'bg-green-50 border-green-500'
              }`}>
                <div className="flex items-start">
                  <svg className={`h-5 w-5 mr-3 mt-0.5 ${
                    uploadMode.requiredDocs.includes('philosophy') ? 'text-blue-500' : 'text-green-500'
                  }`} fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                  </svg>
                  <div className="flex-1">
                    <p className={`text-sm font-semibold mb-2 ${
                      uploadMode.requiredDocs.includes('philosophy') ? 'text-blue-800' : 'text-green-800'
                    }`}>
                      {uploadMode.description}
                    </p>
                    <p className={`text-xs mb-2 ${
                      uploadMode.requiredDocs.includes('philosophy') ? 'text-blue-700' : 'text-green-700'
                    }`}>
                      Estimated processing: {uploadMode.processingTime}
                    </p>
                    <ul className={`text-xs space-y-1 ${
                      uploadMode.requiredDocs.includes('philosophy') ? 'text-blue-600' : 'text-green-600'
                    }`}>
                      {uploadMode.features.map((feature, idx) => (
                        <li key={idx}>• {feature}</li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            )}

            {!uploadMode && (
              <div className="bg-purple-50 border-l-4 border-purple-500 p-4 mb-6">
                <div className="flex items-center">
                  <svg className="h-5 w-5 text-purple-500 mr-2" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                  </svg>
                  <div>
                    <p className="text-sm font-semibold text-purple-800 mb-1">
                      PFD Document is required - Philosophy is optional
                    </p>
                    <p className="text-xs text-purple-700">
                      Upload philosophy document for enhanced P&ID with control logic integration
                    </p>
                  </div>
                </div>
              </div>
            )}
          
          <p className="text-gray-600">AI-powered conversion from PFD to detailed P&ID drawings with philosophy integration</p>
        </div>

        <div className="flex items-center my-8">
          <div className="flex-1 border-t-2 border-gray-300"></div>
          <span className="px-4 text-gray-500 font-medium">OR</span>
          <div className="flex-1 border-t-2 border-gray-300"></div>
        </div>

        {/* Main Upload Card */}
        <div className="bg-white rounded-xl shadow-2xl p-8 border-2 border-purple-100">
          <form onSubmit={handleSubmit} className="space-y-6">
            {/* Required Documents Notice */}
            <div className="bg-purple-50 border-l-4 border-purple-500 p-4 mb-6">
              <div className="flex items-center">
                <svg className="h-5 w-5 text-purple-500 mr-2" fill="currentColor" viewBox="0 0 20 20">
                  <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clipRule="evenodd" />
                </svg>
                <p className="text-sm font-medium text-purple-800">
                  Both PFD and Philosophy documents are required to start processing
                </p>
              </div>
            </div>

            {/* File Upload Areas - Side by side on larger screens */}
            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
              {/* PFD Document Upload */}
              <div>
                <label className="block text-lg font-semibold text-gray-900 mb-4">
                  PFD Document <span className="text-red-500">*</span>
                </label>
                
                <div className="border-4 border-dashed border-purple-200 rounded-xl p-6 text-center hover:border-purple-400 transition-colors">
                  <input
                    type="file"
                    id="pfd-file"
                    accept=".pdf,.jpg,.jpeg,.png"
                    onChange={handleFileChange}
                    className="hidden"
                    disabled={uploading}
                  />
                  
                  <label htmlFor="pfd-file" className="cursor-pointer">
                    {file ? (
                      <div className="flex flex-col items-center">
                        <svg className="h-12 w-12 text-purple-500 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                        <p className="text-sm font-medium text-gray-900 break-all">{file.name}</p>
                        <p className="text-xs text-gray-500 mt-2">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                        <button
                          type="button"
                          onClick={(e) => {
                            e.preventDefault();
                            setFile(null);
                          }}
                          className="mt-3 text-xs text-purple-600 hover:text-purple-800"
                        >
                          Change file
                        </button>
                      </div>
                    ) : (
                      <div className="flex flex-col items-center">
                        <svg className="h-12 w-12 text-gray-400 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                        </svg>
                        <p className="text-sm font-medium text-gray-900 mb-1">
                          Upload PFD
                        </p>
                        <p className="text-xs text-gray-500">
                          PDF, JPEG, PNG (max 10MB)
                        </p>
                      </div>
                    )}
                  </label>
                </div>
              </div>

              {/* Philosophy Document Upload */}
              <div>
                <label className="block text-lg font-semibold text-gray-900 mb-4">
                  Philosophy Document <span className="text-red-500">*</span>
                </label>
                
                <div className="border-4 border-dashed border-blue-200 rounded-xl p-6 text-center hover:border-blue-400 transition-colors">
                  <input
                    type="file"
                    id="philosophy-file"
                    accept=".pdf,.jpg,.jpeg,.png"
                    onChange={handlePhilosophyFileChange}
                    className="hidden"
                    disabled={uploading}
                  />
                  
                  <label htmlFor="philosophy-file" className="cursor-pointer">
                    {philosophyFile ? (
                      <div className="flex flex-col items-center">
                        <svg className="h-12 w-12 text-blue-500 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                        </svg>
                        <p className="text-sm font-medium text-gray-900 break-all">{philosophyFile.name}</p>
                        <p className="text-xs text-gray-500 mt-2">{(philosophyFile.size / 1024 / 1024).toFixed(2)} MB</p>
                        <button
                          type="button"
                          onClick={(e) => {
                            e.preventDefault();
                            setPhilosophyFile(null);
                          }}
                          className="mt-3 text-xs text-blue-600 hover:text-blue-800"
                        >
                          Change file
                        </button>
                      </div>
                    ) : (
                      <div className="flex flex-col items-center">
                        <svg className="h-12 w-12 text-gray-400 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                        </svg>
                        <p className="text-sm font-medium text-gray-900 mb-1">
                          Upload Philosophy
                        </p>
                        <p className="text-xs text-gray-500">
                          PDF, JPEG, PNG (max 10MB)
                        </p>
                      </div>
                    )}
                  </label>
                </div>
              </div>
            </div>

            {/* Document Metadata */}
            <div className="border-t pt-6">
              <h3 className="text-lg font-semibold text-gray-900 mb-4">Document Information (Optional)</h3>
              
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Document Title
                  </label>
                  <input
                    type="text"
                    value={formData.document_title}
                    onChange={(e) => setFormData({ ...formData, document_title: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                    placeholder="e.g., Crude Oil Processing Unit"
                    disabled={uploading}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Document Number
                  </label>
                  <input
                    type="text"
                    value={formData.document_number}
                    onChange={(e) => setFormData({ ...formData, document_number: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                    placeholder="e.g., PFD-001"
                    disabled={uploading}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Revision
                  </label>
                  <input
                    type="text"
                    value={formData.revision}
                    onChange={(e) => setFormData({ ...formData, revision: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                    placeholder="e.g., A, B, C"
                    disabled={uploading}
                  />
                </div>
                
                <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Project Name
                  </label>
                  <input
                    type="text"
                    value={formData.project_name}
                    onChange={(e) => setFormData({ ...formData, project_name: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                    placeholder="e.g., ADNOC Refinery Expansion"
                    disabled={uploading}
                  />
                </div>
                
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium text-gray-700 mb-2">
                    Project Code
                  </label>
                  <input
                    type="text"
                    value={formData.project_code}
                    onChange={(e) => setFormData({ ...formData, project_code: e.target.value })}
                    className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                    placeholder="e.g., ADNOC-REF-2024"
                    disabled={uploading}
                  />
                </div>
              </div>
            </div>

            {/* Error Message */}
            {error && (
              <div className="bg-red-50 border border-red-200 rounded-lg p-4">
                <div className="flex">
                  <svg className="h-5 w-5 text-red-400 mr-2" fill="currentColor" viewBox="0 0 20 20">
                    <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                  </svg>
                  <p className="text-sm text-red-800">{error}</p>
                </div>
              </div>
            )}

            {/* Progress Bar */}
            {uploading && (
              <div>
                <div className="flex justify-between text-sm text-gray-600 mb-2">
                  <span>Uploading and processing...</span>
                  <span>{progress}%</span>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-3">
                  <div 
                    className="bg-gradient-to-r from-purple-500 to-pink-500 h-3 rounded-full transition-all duration-300"
                    style={{ width: `${progress}%` }}
                  ></div>
                </div>
              </div>
            )}

            {/* Submit Button */}
            <div className="flex gap-4 pt-4">
              <button
                type="button"
                onClick={() => navigate('/dashboard')}
                className="flex-1 px-6 py-3 border-2 border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-medium transition-colors"
                disabled={uploading}
              >
                Cancel
              </button>
              <button
                type="submit"
                disabled={!file || uploading}
                className="flex-1 px-6 py-3 bg-gradient-to-r from-purple-600 to-pink-600 text-white rounded-lg hover:from-purple-700 hover:to-pink-700 disabled:from-gray-300 disabled:to-gray-400 disabled:cursor-not-allowed font-medium transition-all shadow-lg"
              >
                {uploading ? 'Processing...' : !file ? 'Upload PFD to Continue' : philosophyFile ? 'Upload & Process (PFD + Philosophy)' : 'Upload & Process (PFD Only)'}
              </button>
            </div>
          </form>
        </div>

        {/* Info Cards */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mt-8">
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center mb-3">
              <svg className="h-8 w-8 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
              <h3 className="font-semibold text-gray-900">AI Processing</h3>
            </div>
            <p className="text-sm text-gray-600">
              Advanced AI extracts process equipment, flows, and parameters from your PFD
            </p>
          </div>
          
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center mb-3">
              <svg className="h-8 w-8 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4" />
              </svg>
              <h3 className="font-semibold text-gray-900">Smart Conversion</h3>
            </div>
            <p className="text-sm text-gray-600">
              Automatically generates instrumentation, piping specs, and safety systems
            </p>
          </div>
          
          <div className="bg-white rounded-lg shadow p-6">
            <div className="flex items-center mb-3">
              <svg className="h-8 w-8 text-purple-500 mr-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
              </svg>
              <h3 className="font-semibold text-gray-900">Standards Compliant</h3>
            </div>
            <p className="text-sm text-gray-600">
              Ensures compliance with ADNOC DEP, API, and ISA standards
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PFDUpload;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient from '../services/api.service';

/**
 * ULTRA COMPLETE P&ID GENERATOR - Frontend Interface
 * Redesigned to showcase RAG + Advanced Graph Intelligence capabilities
 * Implements today's breakthrough: Intelligent P&ID generation with completeness levels
 */
const PFDUploadNew = () => {
  const navigate = useNavigate();
  
  // File uploads
  const [file, setFile] = useState(null);
  const [philosophyFile, setPhilosophyFile] = useState(null);
  
  // Intelligence level selection
  const [intelligenceLevel, setIntelligenceLevel] = useState('ultra');
  
  // Form data
  const [formData, setFormData] = useState({
    project_name: '',
    project_code: '',
    drawing_title: '',
    client: 'SARB Oil & Gas Division',
    contractor: 'Rejlers Engineering AB',
    // Engineering context — feed the AI precision enhancer for better P&ID accuracy
    fluid_service: '',
    operating_pressure: '',
    operating_temperature: '',
    applicable_standards: 'ISA 5.1, ADNOC DEP, API 520, API 521',
    design_basis: '',
  });
  
  // UI states
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState('');
  const [showAdvanced, setShowAdvanced] = useState(false);

  // Intelligence Level Configuration - Ultra Complete Only
  const intelligenceLevels = {
    ultra: {
      name: 'Ultra Complete P&ID (95%)',
      description: 'Industry-leading intelligent P&ID generation with RAG + Graph AI',
      icon: '🤖',
      color: 'green',
      features: [
        '✨ RAG Knowledge Base - Retrieves Oil & Gas standards',
        '🔍 Advanced Graph Analysis - Finds missing connections',
        '⚡ Auto-Generation - Drain/vent/bypass systems',
        '🌐 Utility Networks - Complete IA/N2/CW distribution',
        '🎛️ Control Loops - Full transmitter/controller/valve sets',
        '🛡️ Safety Systems - PSV/ESD/interlocks with SIL ratings',
        '📐 Strict Grid Alignment - 50mm professional snapping',
        '📊 Complete Process Unit - 81+ Elements',
        '🎯 95%+ Completeness - Professional CAD Quality'
      ],
      completeness: '95%+',
      processingTime: '5-7 minutes',
      highlight: true
    }
  };

  const currentLevel = intelligenceLevels[intelligenceLevel];

  const handleFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      if (selectedFile.size > 10 * 1024 * 1024) {
        setError('File size must be less than 10MB');
        return;
      }
      setFile(selectedFile);
      setError('');
    }
  };

  const handlePhilosophyFileChange = (e) => {
    const selectedFile = e.target.files[0];
    if (selectedFile) {
      setPhilosophyFile(selectedFile);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!file) {
      setError('Please upload a PFD document');
      return;
    }

    setUploading(true);
    setProgress(10);

    try {
      const uploadData = new FormData();
      uploadData.append('file', file);
      
      if (philosophyFile) {
        uploadData.append('philosophy_file', philosophyFile);
      }
      
      // Add intelligence level and project info
      uploadData.append('intelligence_level', intelligenceLevel);
      uploadData.append('project_name', formData.project_name);
      uploadData.append('project_code', formData.project_code);
      uploadData.append('drawing_title', formData.drawing_title);
      uploadData.append('client', formData.client);
      uploadData.append('contractor', formData.contractor);
      // Engineering context for AI precision enhancement
      uploadData.append('fluid_service', formData.fluid_service);
      uploadData.append('operating_pressure', formData.operating_pressure);
      uploadData.append('operating_temperature', formData.operating_temperature);
      uploadData.append('applicable_standards', formData.applicable_standards);
      uploadData.append('design_basis', formData.design_basis);

      setProgress(30);

      const response = await apiClient.post('/pfd/documents/upload/', uploadData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        onUploadProgress: (progressEvent) => {
          const percentCompleted = Math.round((progressEvent.loaded * 100) / progressEvent.total);
          setProgress(30 + (percentCompleted * 0.7));
        },
      });

      setProgress(100);
      
      setTimeout(() => {
        navigate(`/pfd/analyze/${response.data.id}`);
      }, 500);

    } catch (err) {
      console.error('Upload failed:', err);
      
      // Extract error information with fallbacks
      const errorData = err.response?.data || {};
      const errorMessage = errorData.message || errorData.error || 'Upload failed';
      const suggestions = errorData.suggestions || [];
      const technicalDetail = errorData.technical_detail || errorData.detail || '';
      
      // Build user-friendly error message
      let displayMessage = errorMessage;
      
      if (suggestions.length > 0) {
        displayMessage += '\n\nSuggestions:\n' + suggestions.map((s, i) => `${i + 1}. ${s}`).join('\n');
      }
      
      if (technicalDetail && technicalDetail.trim() !== '') {
        displayMessage += '\n\nTechnical Details: ' + technicalDetail;
      }
      
      setError(displayMessage);
      setUploading(false);
      setProgress(0);
    }
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-purple-50 to-teal-50 px-3 py-8 sm:px-4">
      <div className="w-full">
        {/* Header */}
        <div className="mb-8">
          <div className="text-center mb-6">
            <h1 className="text-5xl font-bold bg-gradient-to-r from-purple-600 via-pink-600 to-teal-600 bg-clip-text text-transparent mb-3">
              ULTRA COMPLETE P&ID GENERATOR
            </h1>
            <p className="text-xl text-gray-600">RAG Knowledge Base + Advanced Graph Intelligence</p>
          </div>

          {/* Achievement Banner */}
          <div className="bg-gradient-to-r from-green-500 to-teal-500 text-white rounded-xl p-6 shadow-2xl mb-8">
            <div className="flex items-center justify-center gap-3 mb-3">
              <svg className="h-8 w-8" fill="currentColor" viewBox="0 0 20 20">
                <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.8 2.034a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.8-2.034a1 1 0 00-1.175 0l-2.8 2.034c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
              </svg>
              <h2 className="text-2xl font-bold">Today's Breakthrough Achievement</h2>
            </div>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
              <div className="bg-white/20 rounded-lg p-3">
                <div className="font-bold mb-1">🎯 RAG Implementation</div>
                <div>Retrieved Oil & Gas engineering standards on-demand</div>
              </div>
              <div className="bg-white/20 rounded-lg p-3">
                <div className="font-bold mb-1">🔍 Graph Analysis</div>
                <div>Found 11+ missing connections automatically</div>
              </div>
              <div className="bg-white/20 rounded-lg p-3">
                <div className="font-bold mb-1">📈 Complexity Score</div>
                <div>From 153.0 → 382.8 (2.5X improvement!)</div>
              </div>
            </div>
          </div>
        </div>

        {/* Main Content - Two Column Layout */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
          {/* Left Column - Ultra Intelligence Display */}
          <div className="lg:col-span-1">
            <div className="bg-white rounded-xl shadow-lg p-6 sticky top-8">
              <h2 className="text-2xl font-bold text-gray-900 mb-4">Ultra Complete P&ID</h2>
              <p className="text-sm text-gray-600 mb-6">95%+ completeness with RAG + Graph AI</p>
              
              {/* Ultra Intelligence Card */}
              <div className="p-5 rounded-xl border-2 border-green-500 bg-green-50 shadow-lg ring-2 ring-green-400 ring-offset-2">
                <div className="flex items-start gap-3">
                  <div className="text-4xl">{currentLevel.icon}</div>
                  <div className="flex-1">
                    <div className="flex items-center justify-between mb-2">
                      <h3 className="font-bold text-gray-900">{currentLevel.name}</h3>
                      <span className="text-xs bg-green-500 text-white px-3 py-1 rounded-full font-bold">
                        ACTIVE
                      </span>
                    </div>
                    <p className="text-sm text-gray-700 mb-3">{currentLevel.description}</p>
                    <div className="flex items-center gap-4 text-sm">
                      <span className="text-green-600 font-semibold">
                        {currentLevel.completeness} Complete
                      </span>
                      <span className="text-gray-500">{currentLevel.processingTime}</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* Features Included */}
              <div className="mt-6 p-4 bg-gray-50 rounded-lg">
                <h3 className="font-semibold text-gray-900 mb-3">AI Features:</h3>
                <ul className="space-y-2 text-sm">
                  {currentLevel.features.map((feature, idx) => (
                    <li key={idx} className="flex items-start gap-2">
                      <svg className="h-5 w-5 text-green-500 flex-shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clipRule="evenodd" />
                      </svg>
                      <span className="text-gray-700">{feature}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>

          {/* Right Column - File Upload & Project Info */}
          <div className="lg:col-span-2">
            <form onSubmit={handleSubmit} className="space-y-6">
              {/* File Upload Section */}
              <div className="bg-white rounded-xl shadow-lg p-8">
                <h2 className="text-2xl font-bold text-gray-900 mb-6">Upload Documents</h2>
                
                {/* PFD Upload */}
                <div className="mb-6">
                  <label className="block text-lg font-semibold text-gray-900 mb-3">
                    PFD Document <span className="text-red-500">*</span>
                  </label>
                  <div className="border-4 border-dashed border-purple-200 rounded-xl p-8 text-center hover:border-purple-400 transition-colors">
                    <input
                      type="file"
                      id="pfd-file"
                      accept=".pdf,.jpg,.jpeg,.png"
                      onChange={handleFileChange}
                      className="hidden"
                      disabled={uploading}
                    />
                    
                    <label htmlFor="pfd-file" className="cursor-pointer">
                      {file ? (
                        <div className="flex flex-col items-center">
                          <svg className="h-16 w-16 text-purple-500 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                          </svg>
                          <p className="font-semibold text-gray-900 mb-1">{file.name}</p>
                          <p className="text-sm text-gray-500">{(file.size / 1024 / 1024).toFixed(2)} MB</p>
                          <button
                            type="button"
                            onClick={(e) => {
                              e.preventDefault();
                              setFile(null);
                            }}
                            className="mt-3 text-sm text-purple-600 hover:text-purple-800 font-medium"
                          >
                            Change file
                          </button>
                        </div>
                      ) : (
                        <div className="flex flex-col items-center">
                          <svg className="h-16 w-16 text-gray-400 mb-3" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12" />
                          </svg>
                          <p className="font-semibold text-gray-900 mb-1">Click to upload PFD</p>
                          <p className="text-sm text-gray-500">PDF, JPEG, PNG (max 10MB)</p>
                        </div>
                      )}
                    </label>
                  </div>
                </div>

                {/* Philosophy Upload (Optional) */}
                <div>
                  <label className="block text-lg font-semibold text-gray-900 mb-3">
                    Philosophy Document <span className="text-gray-400 text-sm">(Optional)</span>
                  </label>
                  <div className="border-2 border-dashed border-blue-200 rounded-xl p-6 text-center hover:border-blue-400 transition-colors">
                    <input
                      type="file"
                      id="philosophy-file"
                      accept=".pdf,.jpg,.jpeg,.png"
                      onChange={handlePhilosophyFileChange}
                      className="hidden"
                      disabled={uploading}
                    />
                    
                    <label htmlFor="philosophy-file" className="cursor-pointer">
                      {philosophyFile ? (
                        <div className="flex flex-col items-center">
                          <svg className="h-12 w-12 text-blue-500 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                          </svg>
                          <p className="text-sm font-medium text-gray-900">{philosophyFile.name}</p>
                          <button
                            type="button"
                            onClick={(e) => {
                              e.preventDefault();
                              setPhilosophyFile(null);
                            }}
                            className="mt-2 text-xs text-blue-600 hover:text-blue-800"
                          >
                            Remove
                          </button>
                        </div>
                      ) : (
                        <div className="flex flex-col items-center">
                          <svg className="h-12 w-12 text-gray-400 mb-2" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6.253v13m0-13C10.832 5.477 9.246 5 7.5 5S4.168 5.477 3 6.253v13C4.168 18.477 5.754 18 7.5 18s3.332.477 4.5 1.253m0-13C13.168 5.477 14.754 5 16.5 5c1.747 0 3.332.477 4.5 1.253v13C19.832 18.477 18.247 18 16.5 18c-1.746 0-3.332.477-4.5 1.253" />
                          </svg>
                          <p className="text-sm font-medium text-gray-600">Add philosophy for enhanced control logic</p>
                        </div>
                      )}
                    </label>
                  </div>
                </div>
              </div>

              {/* Project Information */}
              <div className="bg-white rounded-xl shadow-lg p-8">
                <div className="flex items-center justify-between mb-6">
                  <h2 className="text-2xl font-bold text-gray-900">Project Information</h2>
                  <button
                    type="button"
                    onClick={() => setShowAdvanced(!showAdvanced)}
                    className="text-purple-600 hover:text-purple-800 text-sm font-medium"
                  >
                    {showAdvanced ? 'Hide' : 'Show'} Advanced
                  </button>
                </div>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Project Name <span className="text-red-500">*</span>
                    </label>
                    <input
                      type="text"
                      value={formData.project_name}
                      onChange={(e) => setFormData({ ...formData, project_name: e.target.value })}
                      className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                      placeholder="e.g., SARB OIL & GAS PRODUCTION FACILITY"
                      disabled={uploading}
                    />
                  </div>
                  
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Project Code
                    </label>
                    <input
                      type="text"
                      value={formData.project_code}
                      onChange={(e) => setFormData({ ...formData, project_code: e.target.value })}
                      className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                      placeholder="e.g., P-16093"
                      disabled={uploading}
                    />
                  </div>

                  <div className="md:col-span-2">
                    <label className="block text-sm font-medium text-gray-700 mb-2">
                      Drawing Title
                    </label>
                    <input
                      type="text"
                      value={formData.drawing_title}
                      onChange={(e) => setFormData({ ...formData, drawing_title: e.target.value })}
                      className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                      placeholder="e.g., THREE-PHASE SEPARATOR UNIT - P&ID"
                      disabled={uploading}
                    />
                  </div>

                  {showAdvanced && (
                    <>
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Client
                        </label>
                        <input
                          type="text"
                          value={formData.client}
                          onChange={(e) => setFormData({ ...formData, client: e.target.value })}
                          className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                          disabled={uploading}
                        />
                      </div>
                      
                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Contractor
                        </label>
                        <input
                          type="text"
                          value={formData.contractor}
                          onChange={(e) => setFormData({ ...formData, contractor: e.target.value })}
                          className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                          disabled={uploading}
                        />
                      </div>

                      {/* Engineering Context — improves AI P&ID accuracy */}
                      <div className="md:col-span-2 pt-2 border-t border-gray-100">
                        <p className="text-xs font-semibold text-purple-700 uppercase tracking-wide mb-4">
                          Engineering Context — enhances AI instrument loop &amp; safety device accuracy
                        </p>
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Fluid Service
                        </label>
                        <input
                          type="text"
                          value={formData.fluid_service}
                          onChange={(e) => setFormData({ ...formData, fluid_service: e.target.value })}
                          className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                          placeholder="e.g. Hydrocarbon Gas / Crude Oil / Water"
                          disabled={uploading}
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Operating Pressure (barg)
                        </label>
                        <input
                          type="text"
                          value={formData.operating_pressure}
                          onChange={(e) => setFormData({ ...formData, operating_pressure: e.target.value })}
                          className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                          placeholder="e.g. 10.5"
                          disabled={uploading}
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Operating Temperature (°C)
                        </label>
                        <input
                          type="text"
                          value={formData.operating_temperature}
                          onChange={(e) => setFormData({ ...formData, operating_temperature: e.target.value })}
                          className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                          placeholder="e.g. 60"
                          disabled={uploading}
                        />
                      </div>

                      <div>
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Applicable Standards
                        </label>
                        <select
                          value={formData.applicable_standards}
                          onChange={(e) => setFormData({ ...formData, applicable_standards: e.target.value })}
                          className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900"
                          disabled={uploading}
                        >
                          <option value="ISA 5.1, ADNOC DEP, API 520, API 521">ISA 5.1 + ADNOC DEP + API 520/521 (default)</option>
                          <option value="ISA 5.1, API 520, API 521, ASME">ISA 5.1 + API 520/521 + ASME</option>
                          <option value="ISA 5.1, Shell DEP, API 520">ISA 5.1 + Shell DEP + API 520</option>
                          <option value="ISA 5.1, Aramco SAES, API 520">ISA 5.1 + Aramco SAES + API 520</option>
                          <option value="EN ISO 10628, ISA 5.1, PED">EN ISO 10628 + ISA 5.1 + PED (European)</option>
                        </select>
                      </div>

                      <div className="md:col-span-2">
                        <label className="block text-sm font-medium text-gray-700 mb-2">
                          Design Basis / Additional Notes
                        </label>
                        <textarea
                          value={formData.design_basis}
                          onChange={(e) => setFormData({ ...formData, design_basis: e.target.value })}
                          rows={3}
                          className="w-full px-4 py-3 border-2 border-gray-300 rounded-lg focus:ring-2 focus:ring-purple-500 focus:border-purple-500 text-gray-900 resize-none"
                          placeholder="e.g. Three-phase separation, fiscal metering required, ESD system per SIL 2, sour service H2S > 300 ppm"
                          disabled={uploading}
                        />
                      </div>
                    </>
                  )}
                </div>
              </div>

              {/* Error Message */}
              {error && (
                <div className="bg-red-50 border-2 border-red-200 rounded-lg p-4">
                  <div className="flex items-center">
                    <svg className="h-5 w-5 text-red-400 mr-2" fill="currentColor" viewBox="0 0 20 20">
                      <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                    </svg>
                    <p className="text-sm text-red-800 font-medium">{error}</p>
                  </div>
                </div>
              )}

              {/* Progress Bar */}
              {uploading && (
                <div className="bg-white rounded-lg p-6">
                  <div className="flex justify-between text-sm font-medium text-gray-700 mb-2">
                    <span>Processing with {currentLevel.name}...</span>
                    <span>{progress}%</span>
                  </div>
                  <div className="w-full bg-gray-200 rounded-full h-4 overflow-hidden">
                    <div 
                      className="bg-gradient-to-r from-purple-500 via-pink-500 to-teal-500 h-4 rounded-full transition-all duration-300 ease-out"
                      style={{ width: `${progress}%` }}
                    ></div>
                  </div>
                  <p className="text-xs text-gray-500 mt-2">Applying RAG knowledge retrieval and graph analysis...</p>
                </div>
              )}

              {/* Submit Button */}
              <div className="flex gap-4">
                <button
                  type="button"
                  onClick={() => navigate('/dashboard')}
                  className="flex-1 px-6 py-4 border-2 border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 font-semibold transition-colors"
                  disabled={uploading}
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  disabled={!file || uploading}
                  className="flex-1 px-6 py-4 bg-gradient-to-r from-purple-600 via-pink-600 to-teal-600 text-white rounded-lg hover:from-purple-700 hover:via-pink-700 hover:to-teal-700 disabled:from-gray-300 disabled:via-gray-400 disabled:to-gray-500 disabled:cursor-not-allowed font-bold text-lg transition-all shadow-lg hover:shadow-xl transform hover:scale-105 disabled:transform-none"
                >
                  {uploading ? 'Processing...' : `Generate ${currentLevel.name} →`}
                </button>
              </div>
            </form>
          </div>
        </div>

        {/* Technical Details Footer */}
        <div className="mt-12 grid grid-cols-1 md:grid-cols-4 gap-4">
          <div className="bg-white rounded-lg shadow p-6">
            <div className="text-3xl mb-2">📊</div>
            <h3 className="font-bold text-gray-900 mb-1">Graph Analysis</h3>
            <p className="text-sm text-gray-600">NetworkX algorithms find missing connections</p>
          </div>
          
          <div className="bg-white rounded-lg shadow p-6">
            <div className="text-3xl mb-2">🧠</div>
            <h3 className="font-bold text-gray-900 mb-1">RAG Knowledge</h3>
            <p className="text-sm text-gray-600">Retrieves ISA 5.1, API 520, ASME standards</p>
          </div>
          
          <div className="bg-white rounded-lg shadow p-6">
            <div className="text-3xl mb-2">📐</div>
            <h3 className="font-bold text-gray-900 mb-1">Strict Alignment</h3>
            <p className="text-sm text-gray-600">50mm grid snapping, professional layout</p>
          </div>
          
          <div className="bg-white rounded-lg shadow p-6">
            <div className="text-3xl mb-2">✅</div>
            <h3 className="font-bold text-gray-900 mb-1">Standards Compliant</h3>
            <p className="text-sm text-gray-600">ISO 10628, ISA 5.1, ADNOC DEP</p>
          </div>
        </div>
      </div>
    </div>
  );
};

