  velocity_estimate:  { icon: '💨', label: 'Velocity Estimate' },
  ref_list_mismatch:  { icon: '📋', label: 'Reference List Mismatch' },
  psv_discharge:      { icon: '⚠️', label: 'PSV Discharge Sizing' },
