              className="anim-fade-up inline-flex items-center px-3 py-1 rounded-full bg-white border border-gray-200 text-gray-600 text-xs font-medium shadow-sm"
              style={{animationDelay:`${200 + i * 80}ms`}}
            >
              {cap}
            </span>
          ))}
        </div>
      </div>

      {/* ── Cards Grid ──────────────────────────────────────────────────────── */}
