              <div className="flex-1">
                <h3 className="font-semibold text-gray-900 mb-1">AI-Powered Data Entry</h3>
                <p className="text-sm text-gray-600">
                  Upload existing pump calculation Excel file for automatic data extraction
                </p>
              </div>
              <label className="cursor-pointer">
                <input
                  type="file"
                  accept=".xlsx,.xls"
                  onChange={handleFileUpload}
                  className="hidden"
                />
                <div className="bg-blue-600 hover:bg-blue-700 text-white px-6 py-3 rounded-lg font-medium transition-colors">
                  {isProcessing ? 'Processing...' : 'Upload Excel File'}
                </div>
              </label>
            </div>
            {uploadedFile && (
              <div className="mt-4 flex items-center gap-2 text-sm text-green-600">
                <span className="font-medium">✓ Uploaded:</span>
                <span>{uploadedFile.name}</span>
              </div>
            )}
          </div>
        </div>

        {/* Form Sections */}
        <form onSubmit={(e) => handleSubmit(e, false)}>
          {/* 🎯 Recommendation Context Display */}
          {recommendationsReady && recommendationStats && (
            <RecommendationContext context={recommendationStats} />
          )}

          {/* ✨ Auto-Fill Button */}
          {recommendationsReady && (
            <div className="mb-6 flex items-center justify-between bg-gradient-to-r from-purple-50 to-pink-50 border-2 border-purple-200 rounded-lg p-4">
              <div>
                <h3 className="font-semibold text-gray-900 mb-1 flex items-center gap-2">
                  <SparklesIcon className="w-5 h-5 text-purple-600" />
                  Smart Auto-Fill Available
                </h3>
                <p className="text-sm text-gray-600">
                  Fill common fields with intelligent suggestions based on {recommendationStats.total_records_analyzed} recent records
                </p>
              </div>
              <AutoFillButton 
                onClick={handleAutoFill}
                loading={recommendationsLoading}
                disabled={!recommendationsReady}
                fieldsCount={8}
              />
            </div>
          )}

          {/* Status Messages */}
          {/* Success Modal with Actions */}
          {showSuccessModal && (
            <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
              <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full overflow-hidden animate-fade-in">
                {/* Modal Header */}
                <div className="bg-gradient-to-r from-green-500 to-emerald-600 px-8 py-6">
                  <div className="flex items-center gap-4">
                    <div className="bg-white rounded-full p-3">
                      <CheckCircleIcon className="w-10 h-10 text-green-600" />
                    </div>
                    <div className="text-white">
                      <h2 className="text-2xl font-bold mb-1">Calculation Submitted Successfully!</h2>
                      <p className="text-green-100">Your pump calculation data has been saved. Choose an action below:</p>
                    </div>
                  </div>
                </div>

                {/* Modal Body - Action Options */}
                <div className="p-8">
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-6">
                    {/* View Data Option */}
                    <button
                      onClick={() => {
                        window.open(`/engineering/process/datasheet/view/${savedPumpId}`, '_blank');
                      }}
                      className="group flex flex-col items-center justify-center p-6 border-2 border-blue-200 rounded-xl hover:border-blue-500 hover:bg-blue-50 transition-all cursor-pointer"
                    >
                      <div className="bg-blue-100 group-hover:bg-blue-200 rounded-full p-4 mb-3 transition-colors">
                        <svg className="w-8 h-8 text-blue-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M15 12a3 3 0 11-6 0 3 3 0 016 0z" />
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M2.458 12C3.732 7.943 7.523 5 12 5c4.478 0 8.268 2.943 9.542 7-1.274 4.057-5.064 7-9.542 7-4.477 0-8.268-2.943-9.542-7z" />
                        </svg>
                      </div>
                      <span className="font-semibold text-gray-800 group-hover:text-blue-600">View Data</span>
                      <span className="text-xs text-gray-500 mt-1 text-center">Preview in template format</span>
                    </button>

                    {/* Download Excel Option */}
                    <button
                      onClick={() => {
                        handleGenerateDatasheet();
                      }}
                      disabled={isGeneratingDatasheet}
                      className="group flex flex-col items-center justify-center p-6 border-2 border-emerald-200 rounded-xl hover:border-emerald-500 hover:bg-emerald-50 transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      <div className="bg-emerald-100 group-hover:bg-emerald-200 rounded-full p-4 mb-3 transition-colors">
                        <svg className="w-8 h-8 text-emerald-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 10v6m0 0l-3-3m3 3l3-3m2 8H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z" />
                        </svg>
                      </div>
                      <span className="font-semibold text-gray-800 group-hover:text-emerald-600">
                        {isGeneratingDatasheet ? 'Generating...' : 'Download Excel'}
                      </span>
                      <span className="text-xs text-gray-500 mt-1 text-center">Pump Data Sheet.xlsx</span>
                    </button>

                    {/* Download PDF Option */}
                    <button
                      onClick={() => {
                        handleGeneratePdf();
                      }}
                      disabled={isGeneratingPdf}
                      className="group flex flex-col items-center justify-center p-6 border-2 border-red-200 rounded-xl hover:border-red-500 hover:bg-red-50 transition-all cursor-pointer disabled:opacity-50 disabled:cursor-not-allowed"
                    >
                      <div className="bg-red-100 group-hover:bg-red-200 rounded-full p-4 mb-3 transition-colors">
                        <svg className="w-8 h-8 text-red-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                        </svg>
                      </div>
                      <span className="font-semibold text-gray-800 group-hover:text-red-600">
                        {isGeneratingPdf ? 'Generating...' : 'Download PDF'}
                      </span>
                      <span className="text-xs text-gray-500 mt-1 text-center">Pump Data Sheet.pdf</span>
                    </button>
                  </div>

                  {/* Saved Data Info */}
                  <div className="bg-gray-50 rounded-lg p-4 mb-6">
                    <div className="grid grid-cols-2 gap-4 text-sm">
                      <div>
                        <span className="text-gray-500">Document No:</span>
                        <span className="ml-2 font-medium text-gray-800">{formData.documentNo || 'N/A'}</span>
                      </div>
                      <div>
                        <span className="text-gray-500">Tag No:</span>
                        <span className="ml-2 font-medium text-gray-800">{formData.tagNo || 'N/A'}</span>
                      </div>
                      <div>
                        <span className="text-gray-500">Project No:</span>
                        <span className="ml-2 font-medium text-gray-800">{formData.projectNo || 'N/A'}</span>
                      </div>
                      <div>
                        <span className="text-gray-500">Pump ID:</span>
                        <span className="ml-2 font-mono text-xs text-gray-600">{savedPumpId}</span>
                      </div>
                    </div>
                  </div>

                  {/* Action Buttons */}
                  <div className="flex justify-between items-center">
                    <button
                      onClick={() => {
                        setShowSuccessModal(false);
                        // Optionally reset form
                      }}
                      className="text-gray-600 hover:text-gray-800 font-medium px-6 py-2 rounded-lg hover:bg-gray-100 transition-colors"
                    >
                      Continue Editing
                    </button>
                    <button
                      onClick={() => {
                        setShowSuccessModal(false);
                        setFormData({});
                        setSavedPumpId(null);
                        setSubmitStatus(null);
                      }}
                      className="bg-gradient-to-r from-blue-600 to-indigo-600 text-white font-medium px-6 py-3 rounded-lg hover:from-blue-700 hover:to-indigo-700 transition-all shadow-md"
                    >
                      Start New Calculation
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}
          
          {submitStatus === 'error' && (
            <div className="bg-red-50 border border-red-200 rounded-lg p-4 mb-6 flex items-center">
              <ExclamationTriangleIcon className="w-6 h-6 text-red-500 mr-3" />
              <div>
                <h3 className="text-red-800 font-medium">Error</h3>
                <p className="text-red-700">{errorMessage || 'Failed to save pump calculation data. Please try again.'}</p>
              </div>
            </div>
          )}
          
          {Object.keys(FORM_SECTIONS).map(sectionKey => renderSection(sectionKey))}

          {/* Submit Section */}
          <div className="bg-white rounded-xl shadow-md p-6">
            <div className="flex items-center justify-between">
              <div className="text-sm text-gray-600">
                <span className="font-medium text-red-500">*</span> Required fields
              </div>
              <div className="flex gap-4">
                <button
                  type="button"
                  onClick={(e) => handleSubmit(e, true)}
                  disabled={isSubmitting || isGeneratingDatasheet || isGeneratingPdf}
                  className={`px-6 py-3 border border-gray-300 rounded-lg font-medium transition-all ${
                    isSubmitting || isGeneratingDatasheet || isGeneratingPdf 
                      ? 'text-gray-400 bg-gray-100 cursor-not-allowed' 
                      : 'text-gray-700 hover:bg-gray-50'
                  }`}
                >
                  {isSubmitting ? 'Saving...' : 'Save Draft'}
                </button>
                <button
                  type="submit"
                  disabled={isSubmitting || isGeneratingDatasheet || isGeneratingPdf}
                  className={`px-8 py-3 rounded-lg font-medium transition-all shadow-lg flex items-center gap-2 ${
                    isSubmitting || isGeneratingDatasheet || isGeneratingPdf
                      ? 'bg-gray-400 text-white cursor-not-allowed'
                      : 'bg-gradient-to-r from-blue-600 to-indigo-600 text-white hover:from-blue-700 hover:to-indigo-700'
                  }`}
                >
                  {isSubmitting && (
                    <svg className="animate-spin h-5 w-5 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                      <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                      <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                    </svg>
                  )}
                  {isSubmitting ? 'Processing Data...' : 'Submit Calculation'}
                </button>
                
                {/* Excel Download Button */}
                <button
                  type="button"
                  onClick={() => handleGenerateDatasheet()}
                  disabled={isSubmitting || isGeneratingDatasheet || isGeneratingPdf}
                  className={`px-5 py-3 rounded-lg font-medium transition-all shadow-lg border-2 ${
                    isGeneratingDatasheet
                      ? 'bg-gray-400 text-white border-gray-400 cursor-not-allowed'
                      : datasheetStatus === 'success'
                        ? 'bg-green-600 text-white border-green-600 hover:bg-green-700'
                        : datasheetStatus === 'error'
                          ? 'bg-red-600 text-white border-red-600 hover:bg-red-700'
                          : 'bg-gradient-to-r from-emerald-600 to-teal-600 text-white border-emerald-600 hover:from-emerald-700 hover:to-teal-700'
                  } flex items-center gap-2`}
                >
                  <ArrowUpTrayIcon className="h-4 w-4" />
                  {isGeneratingDatasheet 
                    ? 'Generating...' 
                    : datasheetStatus === 'success'
                      ? 'Excel Ready!'
                      : datasheetStatus === 'error'
                        ? 'Failed'
                        : 'Excel'
                  }
                </button>

                {/* PDF Download Button */}
                <button
                  type="button"
                  onClick={() => handleGeneratePdf()}
                  disabled={isSubmitting || isGeneratingDatasheet || isGeneratingPdf}
                  className={`px-5 py-3 rounded-lg font-medium transition-all shadow-lg border-2 ${
                    isGeneratingPdf
                      ? 'bg-gray-400 text-white border-gray-400 cursor-not-allowed'
                      : pdfStatus === 'success'
                        ? 'bg-green-600 text-white border-green-600 hover:bg-green-700'
                        : pdfStatus === 'error'
                          ? 'bg-red-600 text-white border-red-600 hover:bg-red-700'
                          : 'bg-gradient-to-r from-red-600 to-orange-600 text-white border-red-600 hover:from-red-700 hover:to-orange-700'
                  } flex items-center gap-2`}
                >
                  <DocumentTextIcon className="h-4 w-4" />
                  {isGeneratingPdf 
                    ? 'Generating...' 
                    : pdfStatus === 'success'
                      ? 'PDF Ready!'
                      : pdfStatus === 'error'
                        ? 'Failed'
                        : 'PDF'
                  }
                </button>
              </div>
            </div>
          </div>
        </form>
      </div>
    </div>
  );
};

export default ComprehensivePumpForm;

/**
 * MOV Equipment P&ID Upload Page
 * Allows P&ID + HMB upload for Motor Operated Valve (MOV) datasheet generation
 * - Upload P&ID diagrams + HMB
 * - Optional third document upload
 * - Automatic MOV detection and classification
 * - Datasheet population (Section 1 & 2 only)
 */

import { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Upload,
  FileText,
  CheckCircle,
  AlertCircle,
  Loader,
  ArrowLeft,
  Settings2,
  FileCheck,
  Download,
  Plus
} from 'lucide-react';
import apiClient from '../../services/api.service';

const MOVEquipmentPage = () => {
  const navigate = useNavigate();
  const pidInputRef = useRef(null);
  const hmbInputRef = useRef(null);
  const otherInputRef = useRef(null);

  // State management
  const [pidFile, setPidFile] = useState(null);
  const [hmbFile, setHmbFile] = useState(null);
  const [otherFile, setOtherFile] = useState(null);
  const [pidDragActive, setPidDragActive] = useState(false);
  const [hmbDragActive, setHmbDragActive] = useState(false);
  const [otherDragActive, setOtherDragActive] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [analysisStage, setAnalysisStage] = useState('');
  const [uploadResult, setUploadResult] = useState(null);
  const [error, setError] = useState('');
  const [htmlPreview, setHtmlPreview] = useState('');
  const [excelData, setExcelData] = useState(null);

  // Cleanup on unmount
  useEffect(() => {
    return () => {
      if (pidFile) URL.revokeObjectURL(URL.createObjectURL(pidFile));
      if (hmbFile) URL.revokeObjectURL(URL.createObjectURL(hmbFile));
      if (otherFile) URL.revokeObjectURL(URL.createObjectURL(otherFile));
    };
  }, [pidFile, hmbFile, otherFile]);

  // File validation and setter
  const validateAndSetFile = (file, setter, label) => {
    const fileExtension = file.name.split('.').pop().toUpperCase();
    if (!['PDF'].includes(fileExtension)) {
      setError(`${label} must be PDF format`);
      return;
    }
    const fileSizeMB = file.size / (1024 * 1024);
    if (fileSizeMB > 50) {
      setError(`${label} file exceeds 50MB limit`);
      return;
    }
    setter(file);
    setError('');
    setUploadResult(null);
  };

  // File change handlers
  const handlePidFileChange = (e) => {
    if (e.target.files?.[0]) validateAndSetFile(e.target.files[0], setPidFile, 'P&ID');
  };

  const handleHmbFileChange = (e) => {
    if (e.target.files?.[0]) validateAndSetFile(e.target.files[0], setHmbFile, 'HMB');
  };

  const handleOtherFileChange = (e) => {
    if (e.target.files?.[0]) validateAndSetFile(e.target.files[0], setOtherFile, 'Other document');
  };

  // Drag handlers
  const handleDrag = (e, setActive) => {
    e.preventDefault();
    e.stopPropagation();
    setActive(e.type === "dragenter" || e.type === "dragover");
  };

  const handleDrop = (e, setter, label, setActive) => {
    e.preventDefault();
    e.stopPropagation();
    setActive(false);
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      validateAndSetFile(e.dataTransfer.files[0], setter, label);
    }
  };

  // Upload and analyze
  const handleUpload = async () => {
    if (!pidFile) {
      setError('Please select a P&ID file');
      return;
    }

    if (!hmbFile) {
      setError('Please select an HMB file');
      return;
    }

    setUploading(true);
    setError('');
    setUploadProgress(0);
    setHtmlPreview('');
    setExcelData(null);
    setAnalysisStage('Uploading files...');

    try {
      const formDataToSend = new FormData();
      formDataToSend.append('pid_file', pidFile);
      formDataToSend.append('hmb_file', hmbFile);
      if (otherFile) formDataToSend.append('other_doc', otherFile);
      formDataToSend.append('equipment_type', 'mov_equipment');

      setUploadProgress(10);
      setAnalysisStage('Uploading files...');

      // Call MOV equipment analysis endpoint (async)
      const response = await apiClient.post(
        '/process-datasheet/datasheets/extract-mov-equipment/',
        formDataToSend,
        {
          headers: {
            'Content-Type': 'multipart/form-data',
            'Accept': 'application/json',
          },
          responseType: 'json',
        }
      );

      const responseData = response.data;

      // Start polling for results
      if (responseData.job_id) {
        pollJobStatus(responseData.job_id);
      } else if (responseData.success) {
        // Immediate response (fallback)
        setHtmlPreview(responseData.html_preview);
        setExcelData({
          base64: responseData.excel_file,
          filename: responseData.filename
        });
        setUploadResult({ success: true });
        setUploadProgress(100);
        setAnalysisStage('Complete!');
        setUploading(false);
      } else {
        throw new Error(responseData.error || 'Analysis failed');
      }

    } catch (err) {
      console.error('MOV equipment upload error:', err);
      setError(err.response?.data?.error || err.message || 'Upload failed. Please try again.');
      setUploadResult({ success: false });
      setUploading(false);
      setTimeout(() => setUploadProgress(0), 2000);
    }
  };

  // ── Soft-coded polling config ──────────────────────────────────────────────
  // Adaptive intervals: fast at first, slows down to reduce server load.
  // Total timeout = sum of all intervals across phases.
  // Increase POLL_PHASES entries or POLL_MAX_TOTAL_MS to allow longer jobs.
  const POLL_PHASES = [
    { upToSeconds: 120, intervalMs: 3000 },   // 0–2 min  : every 3 s
    { upToSeconds: 360, intervalMs: 5000 },   // 2–6 min  : every 5 s
    { upToSeconds: 900, intervalMs: 8000 },   // 6–15 min : every 8 s
  ];
  const POLL_MAX_TOTAL_MS = 15 * 60 * 1000;  // 15 minutes absolute max
  // Per-request timeout for the *status* poll. The endpoint is a tiny cache
  // read on the backend, so 25 s is more than enough — failing fast here lets
  // us simply retry on the next interval instead of hogging axios for 120 s
  // when a gunicorn worker is briefly tied up by the extraction thread.
  const POLL_REQUEST_TIMEOUT_MS = 25000;
  // Number of consecutive transient poll failures (timeout / network / 5xx)
  // we tolerate before surfacing an error. The background job keeps running
  // on the server regardless of our poll failing — we just retry the cheap
  // status read until either it succeeds or we cross the absolute max.
  const POLL_MAX_CONSECUTIVE_ERRORS = 8;
  // Transient errors that should NOT abort the polling loop.
  const isTransientPollError = (err) => {
    if (!err) return false;
    if (err.isTimeout || err.isNetworkError) return true;
    if (err.code === 'ECONNABORTED' || err.code === 'ERR_NETWORK') return true;
    const msg = (err.message || '').toLowerCase();
    if (msg.includes('timeout') || msg.includes('network')) return true;
    const sc = err.response?.status;
    if (sc === 502 || sc === 503 || sc === 504 || sc === 408 || sc === 429) return true;
    return false;
  };
  // ────────────────────────────────────────────────────────────────────────────

  // Poll job status
  const pollJobStatus = async (jobId) => {
    const startTime = Date.now();
    let consecutiveErrors = 0;

    const getInterval = () => {
      const elapsedSec = (Date.now() - startTime) / 1000;
      for (const phase of POLL_PHASES) {
        if (elapsedSec <= phase.upToSeconds) return phase.intervalMs;
      }
      return POLL_PHASES[POLL_PHASES.length - 1].intervalMs;
    };

    const poll = async () => {
      try {
        const statusResponse = await apiClient.get(
          `/process-datasheet/mov-job-status/${jobId}/`,
          { timeout: POLL_REQUEST_TIMEOUT_MS }
        );
        const { status, progress, stage, result, error: jobError } = statusResponse.data;

        // Success — reset the transient-error counter
        consecutiveErrors = 0;

        setUploadProgress(progress || 0);
        setAnalysisStage(stage || 'Processing...');

        if (status === 'completed' && result) {
          if (result.success) {
            setHtmlPreview(result.html_preview);
            setExcelData({
              base64: result.excel_file,
              filename: result.filename
            });
            setUploadResult({ success: true });
            setUploadProgress(100);
            setAnalysisStage('Complete!');
          } else {
            throw new Error(result.error || 'Processing failed');
          }
          setUploading(false);
        } else if (status === 'failed') {
          throw new Error(jobError || 'Processing failed');
        } else if (status === 'processing' || status === 'not_found') {
          // 'not_found' can occur for a brief window right after job start
          // before the worker writes its first cache key — treat as in-flight.
          const elapsed = Date.now() - startTime;
          if (elapsed < POLL_MAX_TOTAL_MS) {
            const elapsedMin = Math.floor(elapsed / 60000);
            const elapsedSec = Math.floor((elapsed % 60000) / 1000);
            setAnalysisStage(stage || `Processing... (${elapsedMin}m ${elapsedSec}s)`);
            setTimeout(poll, getInterval());
          } else {
            throw new Error(`Processing is taking longer than expected (>${POLL_MAX_TOTAL_MS / 60000} min). Please try again.`);
          }
        }

      } catch (err) {
        // Transient network / timeout / 5xx — keep polling, the background
        // job is still running server-side. Only abort after N consecutive
        // failures, or once we exceed the absolute polling budget.
        if (isTransientPollError(err)) {
          consecutiveErrors += 1;
          const elapsed = Date.now() - startTime;
          console.warn(
            `[MOV Poll] Transient error (${consecutiveErrors}/${POLL_MAX_CONSECUTIVE_ERRORS}) — retrying:`,
            err.message
          );
          if (
            consecutiveErrors < POLL_MAX_CONSECUTIVE_ERRORS &&
            elapsed < POLL_MAX_TOTAL_MS
          ) {
            const elapsedMin = Math.floor(elapsed / 60000);
            const elapsedSec = Math.floor((elapsed % 60000) / 1000);
            setAnalysisStage(
              `Processing... (${elapsedMin}m ${elapsedSec}s) — reconnecting`
            );
            setTimeout(poll, getInterval());
            return;
          }
          // Exhausted retries — fall through to error handling
        }

        console.error('Job status polling error:', err);
        setError(err.message || 'Failed to retrieve results');
        setUploadResult({ success: false });
        setUploading(false);
        setTimeout(() => setUploadProgress(0), 2000);
      }
    };

    poll();
  };

  const handleDownloadExcel = () => {
    if (!excelData) return;

    try {
      const binaryString = window.atob(excelData.base64);
      const bytes = new Uint8Array(binaryString.length);
      for (let i = 0; i < binaryString.length; i++) {
        bytes[i] = binaryString.charCodeAt(i);
      }

      const blob = new Blob([bytes], {
        type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
      });
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = excelData.filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      window.URL.revokeObjectURL(url);
    } catch (err) {
      console.error('Download error:', err);
      setError('Failed to download Excel file');
    }
  };

  const handleReset = () => {
    setPidFile(null);
    setHmbFile(null);
    setOtherFile(null);
    setUploadResult(null);
    setHtmlPreview('');
    setExcelData(null);
    setError('');
    setUploadProgress(0);
    setAnalysisStage('');
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 p-6">
      <div className="max-w-6xl mx-auto">
        {/* Header */}
        <div className="mb-8">
          <button
            onClick={() => navigate('/engineering/process/datasheet')}
            className="flex items-center gap-2 text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white mb-4 transition-colors"
          >
            <ArrowLeft className="w-5 h-5" />
            Back to Process Datasheets
          </button>

          <div className="flex items-center gap-3 mb-2">
            <Settings2 className="w-8 h-8 text-blue-600" />
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white">
              MOV Equipment Datasheet Generator
            </h1>
          </div>
          <p className="text-gray-600 dark:text-gray-400">
            Upload P&ID + HMB → AI detects MOV valves → Download "MOV Equipment Data Sheet.xlsx"
          </p>
        </div>

        {/* Main Content */}
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Left Panel - Upload & Form */}
          <div className="lg:col-span-2 space-y-6">
            {/* File Upload Areas */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6">
              <h2 className="text-xl font-semibold text-gray-900 dark:text-white mb-4 flex items-center gap-2">
                <Upload className="w-5 h-5" />
                Upload Files
              </h2>

