      }
    };

    // 7. TEMPERATURE & VISCOSITY IMPACT
    const checkFluidProperties = () => {
      const temp = parseFloat(pumpData.temperature_max || pumpData.temperature);
      const viscosity = parseFloat(pumpData.viscosity_max || pumpData.fluid_viscosity_at_temp);
      
      if (temp > 150) {
        analysis.recommendations.push({
          title: '💡 High Temperature Service',
          message: `Operating temperature: ${temp}°C. Ensure high-temperature seal and bearing design.`,
          suggestion: 'Verify thermal expansion clearances and API 610 high-temperature guidelines.'
        });
      }
      
      if (viscosity && viscosity > 20) {
        analysis.recommendations.push({
          title: '💡 Viscous Fluid Service',
          message: `Fluid viscosity: ${viscosity} cP. Centrifugal pump efficiency degrades with viscosity > 20 cP.`,
          suggestion: 'Apply viscosity correction factors per Hydraulic Institute standards. Consider PD pump above 200 cP.'
        });
      }
    };

    // 8. API 610 COMPLIANCE CHECKS
    const checkAPI610Compliance = () => {
      const complianceItems = [];
      
      // Check if motor classification is specified
      if (pumpData.motor_classification) {
        complianceItems.push(`Motor Classification: ${pumpData.motor_classification}`);
      }
      
      // Check for proper materials
      if (pumpData.casing && pumpData.impeller && pumpData.shaft) {
        complianceItems.push('Material specifications documented');
      }
      
      // Check for mechanical seal
      if (pumpData.mechanical_seal) {
        complianceItems.push(`Mechanical Seal: ${pumpData.mechanical_seal}`);
      }
      
      if (complianceItems.length > 0) {
        analysis.compliance.push({
          title: '✓ API 610 Documentation',
          message: 'Key API 610 requirements documented: ' + complianceItems.join(', ')
        });
      }
    };

    // Execute all checks
    checkNPSH();
    checkEfficiency();
    checkMaterials();
    checkPressureHead();
    checkPowerConsumption();
    checkFlowRange();
    checkFluidProperties();
    checkAPI610Compliance();

    // Render the analysis UI
    return (
      <div className="space-y-4">
        {/* Critical Issues */}
        {analysis.critical.length > 0 && (
          <div className="bg-red-50 border-l-4 border-red-500 p-4 rounded-lg">
            <div className="flex items-start">
              <div className="flex-shrink-0">
                <svg className="h-6 w-6 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
              </div>
              <div className="ml-3 flex-1">
                <h3 className="text-lg font-bold text-red-800 mb-2">Critical Issues Require Immediate Attention</h3>
                {analysis.critical.map((item, idx) => (
                  <div key={idx} className="mb-3">
                    <p className="font-bold text-red-700">{item.title}</p>
                    <p className="text-red-800 mt-1">{item.message}</p>
                    <p className="text-red-900 mt-2 font-semibold bg-red-100 p-2 rounded">
                      ⚡ Action: {item.action}
                    </p>
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Warnings */}
        {analysis.warnings.length > 0 && (
          <div className="bg-yellow-50 border-l-4 border-yellow-500 p-4 rounded-lg">
            <div className="flex items-start">
              <div className="flex-shrink-0">
                <svg className="h-6 w-6 text-yellow-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <div className="ml-3 flex-1">
                <h3 className="text-lg font-bold text-yellow-800 mb-2">Warnings & Concerns</h3>
                {analysis.warnings.map((item, idx) => (
                  <div key={idx} className="mb-3">
                    <p className="font-bold text-yellow-700">{item.title}</p>
                    <p className="text-yellow-800 mt-1">{item.message}</p>
                    {item.action && (
                      <p className="text-yellow-900 mt-2 font-semibold bg-yellow-100 p-2 rounded">
                        💡 Recommendation: {item.action}
                      </p>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Recommendations */}
        {analysis.recommendations.length > 0 && (
          <div className="bg-blue-50 border-l-4 border-blue-500 p-4 rounded-lg">
            <div className="flex items-start">
              <div className="flex-shrink-0">
                <svg className="h-6 w-6 text-blue-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <div className="ml-3 flex-1">
                <h3 className="text-lg font-bold text-blue-800 mb-2">Optimization Recommendations</h3>
                {analysis.recommendations.map((item, idx) => (
                  <div key={idx} className="mb-3">
                    <p className="font-bold text-blue-700">{item.title}</p>
                    <p className="text-blue-800 mt-1">{item.message}</p>
                    {item.suggestion && (
                      <p className="text-blue-900 mt-2 italic bg-blue-100 p-2 rounded">
                        {item.suggestion}
                      </p>
                    )}
                  </div>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* Compliance & Good Status */}
        {analysis.compliance.length > 0 && (
          <div className="bg-green-50 border-l-4 border-green-500 p-4 rounded-lg">
            <div className="flex items-start">
              <div className="flex-shrink-0">
                <svg className="h-6 w-6 text-green-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
              </div>
              <div className="ml-3 flex-1">
                <h3 className="text-lg font-bold text-green-800 mb-2">Compliant & Satisfactory</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                  {analysis.compliance.map((item, idx) => (
                    <div key={idx} className="bg-green-100 p-3 rounded">
                      <p className="font-semibold text-green-800">{item.title}</p>
                      <p className="text-green-700 text-sm mt-1">{item.message}</p>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Overall Quality Score */}
        <div className="bg-gradient-to-r from-purple-50 to-indigo-50 border border-purple-200 p-6 rounded-lg">
          <h3 className="text-lg font-bold text-purple-900 mb-3 flex items-center gap-2">
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
            </svg>
            AI Quality Assessment Summary
          </h3>
          <div className="grid grid-cols-4 gap-4 text-center">
            <div className="bg-white p-3 rounded-lg shadow">
              <div className="text-2xl font-bold text-red-600">{analysis.critical.length}</div>
              <div className="text-xs text-gray-600">Critical</div>
            </div>
            <div className="bg-white p-3 rounded-lg shadow">
              <div className="text-2xl font-bold text-yellow-600">{analysis.warnings.length}</div>
              <div className="text-xs text-gray-600">Warnings</div>
            </div>
            <div className="bg-white p-3 rounded-lg shadow">
              <div className="text-2xl font-bold text-blue-600">{analysis.recommendations.length}</div>
              <div className="text-xs text-gray-600">Recommendations</div>
            </div>
            <div className="bg-white p-3 rounded-lg shadow">
              <div className="text-2xl font-bold text-green-600">{analysis.compliance.length}</div>
              <div className="text-xs text-gray-600">Compliant</div>
            </div>
          </div>
          <div className="mt-4 text-center">
            <div className="text-sm text-purple-800 font-semibold">
              {analysis.critical.length === 0 && analysis.warnings.length === 0 
                ? '🌟 Excellent Design Quality - No critical issues detected'
                : analysis.critical.length > 0 
                ? '⚠️ Critical Issues Detected - Immediate Action Required'
                : '✓ Good Design - Minor optimization opportunities identified'}
            </div>
          </div>
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-16 w-16 border-b-2 border-blue-600 mx-auto mb-4"></div>
          <p className="text-gray-600 text-lg">Loading Pump Data Sheet...</p>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="bg-white rounded-lg shadow-lg p-8 max-w-md">
          <div className="text-red-500 text-6xl mb-4">⚠️</div>
          <h2 className="text-2xl font-bold text-gray-800 mb-2">Error</h2>
          <p className="text-gray-600 mb-6">{error}</p>
          <button
            onClick={() => navigate(-1)}
            className="bg-blue-600 text-white px-6 py-2 rounded-lg hover:bg-blue-700"
          >
            Go Back
          </button>
        </div>
      </div>
    );
  }

  if (!pumpData) {
    return null;
  }

  return (
    <div className="min-h-screen bg-gray-50 py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header Actions */}
        <div className="mb-6 flex justify-between items-center">
          <button
            onClick={() => navigate(-1)}
            className="flex items-center gap-2 text-gray-600 hover:text-gray-800 font-medium"
          >
            <ArrowLeftIcon className="w-5 h-5" />
            Back to Form
          </button>
          
          <div className="flex gap-3">
            <button
              onClick={handleDownloadExcel}
              className="flex items-center gap-2 bg-emerald-600 text-white px-4 py-2 rounded-lg hover:bg-emerald-700 transition-colors"
            >
              <DocumentArrowDownIcon className="w-5 h-5" />
              Download Excel
            </button>
            <button
              onClick={handleDownloadPDF}
              className="flex items-center gap-2 bg-red-600 text-white px-4 py-2 rounded-lg hover:bg-red-700 transition-colors"
            >
              <DocumentArrowDownIcon className="w-5 h-5" />
              Download PDF
            </button>
          </div>
        </div>

        {/* Main Data Sheet - Matching Template Structure */}
        <div className="bg-white rounded-xl shadow-lg overflow-hidden">
          {/* Cover Sheet Section */}
          <div className="bg-gradient-to-r from-blue-700 to-indigo-800 text-white px-8 py-6">
            <div className="flex justify-between items-start">
              <div>
                <h1 className="text-3xl font-bold mb-2">PROCESS DATA SHEET</h1>
                <p className="text-blue-100">Pump Hydraulic Calculation</p>
              </div>
              <div className="text-right">
                <div className="text-sm text-blue-100 mb-1">Page 1 of 2</div>
                <div className="bg-white text-blue-900 px-4 py-1 rounded font-semibold">
                  {displayValue(pumpData.document_class, 'Confidential')}
                </div>
              </div>
            </div>
            
            {/* Document Header Info */}
            <div className="mt-6 grid grid-cols-2 gap-6 text-sm">
              <div>
                <div className="text-blue-100 mb-1">Document No.</div>
                <div className="text-xl font-semibold">{displayValue(pumpData.document_no)}</div>
              </div>
              <div>
                <div className="text-blue-100 mb-1">Revision No.</div>
                <div className="text-xl font-semibold">{displayValue(pumpData.revision, '0')}</div>
              </div>
              <div>
                <div className="text-blue-100 mb-1">Tag No.</div>
                <div className="text-xl font-semibold">{displayValue(pumpData.tag_no)}</div>
              </div>
              <div>
                <div className="text-blue-100 mb-1">Date</div>
                <div className="text-xl font-semibold">
                  {pumpData.created_at ? new Date(pumpData.created_at).toLocaleDateString() : 'N/A'}
                </div>
              </div>
            </div>
          </div>

          {/* Sheet 1 - Main Data Content */}
          <div className="p-8">
            {/* Project Information Section */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-blue-600">
                PROJECT INFORMATION
              </h2>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Company Name</div>
                    <div className="font-semibold text-gray-800">{displayValue(pumpData.company_name, 'Rejlers')}</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Site</div>
                    <div className="font-semibold text-gray-800">{displayValue(pumpData.site)}</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">No. Required</div>
                    <div className="font-semibold text-gray-800">1</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Manufacturer</div>
                    <div className="font-semibold text-gray-800">{displayValue(pumpData.manufacturer)}</div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Unit</div>
                    <div className="font-semibold text-gray-800">{displayValue(pumpData.unit)}</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Service</div>
                    <div className="font-semibold text-gray-800">{displayValue(pumpData.service)}</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Type of Pump</div>
                    <div className="font-semibold text-gray-800">Centrifugal</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Model</div>
                    <div className="font-semibold text-gray-800">{displayValue(pumpData.model)}</div>
                  </div>
                </div>
              </div>
            </div>

            {/* Liquid Characteristics Section */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-blue-600">
                LIQUID CHARACTERISTICS
              </h2>
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-100">
                    <tr>
                      <th className="px-4 py-3 text-left text-sm font-semibold text-gray-700">Parameter</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Maximum</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Minimum</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Unit</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    <tr>
                      <td className="px-4 py-3 font-medium text-gray-800">Liquid Type / Service</td>
                      <td colSpan="2" className="px-4 py-3 text-center text-gray-700">{getLiquidType()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">-</td>
                    </tr>
                    <tr className="bg-gray-50">
                      <td className="px-4 py-3 font-medium text-gray-800">Vapor Pressure</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getVaporPressureMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getVaporPressureMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">bar</td>
                    </tr>
                    <tr>
                      <td className="px-4 py-3 font-medium text-gray-800">Density</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDensityMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDensityMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">kg/m³</td>
                    </tr>
                    <tr className="bg-gray-50">
                      <td className="px-4 py-3 font-medium text-gray-800">Viscosity</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getViscosityMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getViscosityMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">cP</td>
                    </tr>
                    <tr>
                      <td className="px-4 py-3 font-medium text-gray-800">Temperature</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getTemperatureMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getTemperatureMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">°C</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>

            {/* Flow Rate and Operating Conditions */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-blue-600">
                OPERATING CONDITIONS
              </h2>
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-100">
                    <tr>
                      <th className="px-4 py-3 text-left text-sm font-semibold text-gray-700">Parameter</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Maximum</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Normal</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Minimum</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Unit</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    <tr>
                      <td className="px-4 py-3 font-medium text-gray-800">Flow Rate</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getFlowRateMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getFlowRateNormal()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getFlowRateMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">m³/h</td>
                    </tr>
                    <tr className="bg-gray-50">
                      <td className="px-4 py-3 font-medium text-gray-800">Suction Pressure</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getSuctionPressureMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getSuctionPressureNormal()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getSuctionPressureMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">bar</td>
                    </tr>
                    <tr>
                      <td className="px-4 py-3 font-medium text-gray-800">Discharge Pressure</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDischargePressureMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDischargePressureNormal()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDischargePressureMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">bar</td>
                    </tr>
                    <tr className="bg-gray-50">
                      <td className="px-4 py-3 font-medium text-gray-800">Differential Pressure</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDifferentialPressureMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDifferentialPressureNormal()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDifferentialPressureMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">bar</td>
                    </tr>
                    <tr>
                      <td className="px-4 py-3 font-medium text-gray-800">Differential Head</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDifferentialHeadMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDifferentialHeadNormal()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getDifferentialHeadMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">m</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>

            {/* NPSH Section */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-blue-600">
                NET POSITIVE SUCTION HEAD (NPSH)
              </h2>
              <div className="grid grid-cols-2 gap-6">
                <div className="bg-blue-50 p-6 rounded-lg border-2 border-blue-200">
                  <div className="text-sm text-blue-600 font-semibold mb-2">NPSH Available</div>
                  <div className="grid grid-cols-2 gap-4">
                    <div>
                      <div className="text-xs text-gray-500 mb-1">Maximum</div>
                      <div className="text-2xl font-bold text-gray-800">{getNpshAvailableMax()}</div>
                      <div className="text-xs text-gray-500 mt-1">m</div>
                    </div>
                    <div>
                      <div className="text-xs text-gray-500 mb-1">Minimum</div>
                      <div className="text-2xl font-bold text-gray-800">{getNpshAvailableMin()}</div>
                      <div className="text-xs text-gray-500 mt-1">m</div>
                    </div>
                  </div>
                </div>
                <div className="bg-orange-50 p-6 rounded-lg border-2 border-orange-200">
                  <div className="text-sm text-orange-600 font-semibold mb-2">NPSH Required</div>
                  <div className="text-2xl font-bold text-gray-800">{getNpshRequired()}</div>
                  <div className="text-xs text-gray-500 mt-1">m</div>
                </div>
              </div>
            </div>

            {/* Pump Performance Section */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-blue-600">
                PUMP PERFORMANCE
              </h2>
              <div className="overflow-x-auto">
                <table className="min-w-full divide-y divide-gray-200">
                  <thead className="bg-gray-100">
                    <tr>
                      <th className="px-4 py-3 text-left text-sm font-semibold text-gray-700">Parameter</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Maximum</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Normal</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Minimum</th>
                      <th className="px-4 py-3 text-center text-sm font-semibold text-gray-700">Unit</th>
                    </tr>
                  </thead>
                  <tbody className="bg-white divide-y divide-gray-200">
                    <tr>
                      <td className="px-4 py-3 font-medium text-gray-800">Pump Efficiency</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getPumpEfficiencyMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getPumpEfficiencyNormal()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getPumpEfficiencyMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">%</td>
                    </tr>
                    <tr className="bg-gray-50">
                      <td className="px-4 py-3 font-medium text-gray-800">BHP (Brake Horsepower)</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getBhpMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getBhpNormal()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getBhpMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">HP</td>
                    </tr>
                    <tr>
                      <td className="px-4 py-3 font-medium text-gray-800">Absorbed Power</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getAbsorbedPowerMax()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getAbsorbedPowerNormal()}</td>
                      <td className="px-4 py-3 text-center text-gray-700">{getAbsorbedPowerMin()}</td>
                      <td className="px-4 py-3 text-center text-gray-500">kW</td>
                    </tr>
                  </tbody>
                </table>
              </div>
            </div>

            {/* Driver/Motor Data Section */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-blue-600">
                DRIVER / MOTOR DATA
              </h2>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Driver Type</div>
                    <div className="font-semibold text-gray-800">{displayValue(pumpData.driver_type, 'Electric Motor')}</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Motor Rating</div>
                    <div className="font-semibold text-gray-800">{formatNumber(pumpData.motor_rating)} kW</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Motor Voltage</div>
                    <div className="font-semibold text-gray-800">{formatNumber(pumpData.motor_voltage, 0)} V</div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Motor Speed</div>
                    <div className="font-semibold text-gray-800">{formatNumber(pumpData.motor_speed, 0)} RPM</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Motor Efficiency</div>
                    <div className="font-semibold text-gray-800">{formatNumber(pumpData.motor_efficiency)} %</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Motor Classification</div>
                    <div className="font-semibold text-gray-800">{displayValue(pumpData.motor_classification)}</div>
                  </div>
                </div>
              </div>
            </div>

            {/* Construction Materials Section */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-blue-600">
                CONSTRUCTION MATERIALS
              </h2>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-4">
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Casing</div>
                    <div className="font-semibold text-gray-800">{getCasing()}</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Impeller</div>
                    <div className="font-semibold text-gray-800">{getImpeller()}</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Shaft</div>
                    <div className="font-semibold text-gray-800">{getShaft()}</div>
                  </div>
                </div>
                <div className="space-y-4">
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Bearings</div>
                    <div className="font-semibold text-gray-800">{getBearings()}</div>
                  </div>
                  <div className="bg-gray-50 p-4 rounded-lg">
                    <div className="text-sm text-gray-500 mb-1">Mechanical Seal</div>
                    <div className="font-semibold text-gray-800">{getMechanicalSeal()}</div>
                  </div>
                </div>
              </div>
            </div>

            {/* AI-Powered Quality Analysis & Recommendations */}
            <div className="mb-8">
              <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-purple-600 flex items-center gap-2">
                <svg className="w-6 h-6 text-purple-600" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"></path>
                </svg>
                INTELLIGENT QUALITY ANALYSIS & RECOMMENDATIONS
              </h2>
              {generateQualityAnalysis()}
            </div>

            {/* Notes and Remarks Section */}
            {pumpData.general_notes && (
              <div className="mb-8">
                <h2 className="text-xl font-bold text-gray-800 mb-4 pb-2 border-b-2 border-blue-600">
                  NOTES AND REMARKS
                </h2>
                <div className="bg-yellow-50 p-6 rounded-lg border-l-4 border-yellow-400">
                  <p className="text-gray-700 whitespace-pre-wrap">{String(pumpData.general_notes)}</p>
                </div>
              </div>
            )}

            {/* Approval/Signature Section */}
            <div className="mt-8 pt-6 border-t-2 border-gray-200">
              <div className="grid grid-cols-3 gap-6 text-sm">
                <div className="text-center">
                  <div className="border-b-2 border-gray-300 pb-2 mb-2 text-gray-500">Prepared By</div>
                  <div className="font-semibold text-gray-800">
                    {displayUser(pumpData.prepared_by)}
                  </div>
                </div>
                <div className="text-center">
                  <div className="border-b-2 border-gray-300 pb-2 mb-2 text-gray-500">Reviewed By</div>
                  <div className="font-semibold text-gray-800">{displayUser(pumpData.reviewed_by)}</div>
                </div>
                <div className="text-center">
                  <div className="border-b-2 border-gray-300 pb-2 mb-2 text-gray-500">Approved By</div>
                  <div className="font-semibold text-gray-800">{displayUser(pumpData.approved_by)}</div>
                </div>
              </div>
            </div>

            {/* Template Reference Footer */}
            <div className="mt-8 pt-4 border-t border-gray-200 text-center text-xs text-gray-400">
              RAD-PR-TMP-0001, Rev 0 | Template: Pump Data Sheet.xlsx
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PumpDataSheetView;

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { FEATURES_CATALOG } from '../../config/featuresCatalog.config';
import { 
  ArrowLeftIcon,
  ArrowPathIcon,
  CalculatorIcon,
  ChartBarIcon,
  CheckCircleIcon,
  BeakerIcon,
  CogIcon
} from '@heroicons/react/24/outline';

/**
 * Pump Hydraulic Calculation Page
 * AI-powered pump sizing, selection, and hydraulic calculations
 * Soft-coded design for flexibility and maintainability
 */
const PumpHydraulicCalculation = () => {
  const navigate = useNavigate();
  
  // Get module name from centralized config
  const moduleConfig = FEATURES_CATALOG.engineering.features.find(
    feature => feature.id === 'eng-process-datasheet'
  );
  const MODULE_NAME = moduleConfig?.name || 'Process Datasheets';
  
  // State management - soft-coded for easy expansion
  const [calculationMode, setCalculationMode] = useState('');
  const [pumpType, setPumpType] = useState('');
  const [inputData, setInputData] = useState({
    flowRate: '',
    totalHead: '',
    suction: '',
    discharge: '',
    fluid: 'water',
    temperature: '',
    specificGravity: '1.0',
    viscosity: ''
  });

  // Soft-coded calculation modes
  const calculationModes = [
    {
      value: 'sizing',
      label: 'Pump Sizing',
      icon: '📏',
      description: 'Calculate required pump specifications'
    },
    {
      value: 'selection',
      label: 'Pump Selection',
      icon: '🎯',
      description: 'Select optimal pump from database'
    },
    {
      value: 'verification',
      label: 'Design Verification',
      icon: '✓',
      description: 'Verify existing pump design'
    },
    {
      value: 'optimization',
      label: 'Performance Optimization',
      icon: '⚡',
      description: 'Optimize pump performance'
    }
  ];

  // Soft-coded pump types
  const pumpTypes = [
    { 
      value: 'centrifugal', 
      label: 'Centrifugal Pump', 
      icon: '🔄',
      description: 'Most common for general applications'
    },
    { 
      value: 'positive_displacement', 
      label: 'Positive Displacement', 
      icon: '⚙️',
      description: 'For high pressure, viscous fluids'
    },
    { 
      value: 'multistage', 
      label: 'Multistage Centrifugal', 
      icon: '📊',
      description: 'For high head applications'
    },
    { 
      value: 'submersible', 
      label: 'Submersible Pump', 
      icon: '🌊',
      description: 'For submerged applications'
    }
  ];

  // Soft-coded fluid types
  const fluidTypes = [
    { value: 'water', label: 'Water', sg: '1.0' },
    { value: 'seawater', label: 'Seawater', sg: '1.025' },
    { value: 'oil_light', label: 'Light Oil', sg: '0.85' },
    { value: 'oil_medium', label: 'Medium Oil', sg: '0.90' },
    { value: 'diesel', label: 'Diesel', sg: '0.85' },
    { value: 'gasoline', label: 'Gasoline', sg: '0.74' },
    { value: 'crude_oil', label: 'Crude Oil', sg: '0.88' },
    { value: 'custom', label: 'Custom Fluid', sg: '' }
  ];

  // Calculation steps - soft-coded for flexibility
  const calculationSteps = [
    {
      id: 1,
      title: 'Select Calculation Mode',
      description: 'Choose your calculation objective',
      icon: CalculatorIcon,
      status: calculationMode ? 'completed' : 'current'
    },
    {
      id: 2,
      title: 'Choose Pump Type',
      description: 'Select appropriate pump category',
      icon: CogIcon,
      status: pumpType ? 'completed' : calculationMode ? 'current' : 'pending'
    },
    {
      id: 3,
      title: 'Input Parameters',
      description: 'Enter hydraulic requirements',
      icon: BeakerIcon,
      status: 'pending'
    },
    {
      id: 4,
      title: 'AI Calculation',
      description: 'Automated pump calculations',
      icon: ChartBarIcon,
      status: 'pending'
    },
    {
      id: 5,
      title: 'Results & Report',
      description: 'Review calculations and generate report',
      icon: CheckCircleIcon,
      status: 'pending'
    }
  ];

  const handleInputChange = (field, value) => {
    setInputData(prev => ({
      ...prev,
      [field]: value
    }));
    
    // Auto-update specific gravity when fluid type changes
    if (field === 'fluid') {
      const selectedFluid = fluidTypes.find(f => f.value === value);
      if (selectedFluid && selectedFluid.sg) {
        setInputData(prev => ({
          ...prev,
          specificGravity: selectedFluid.sg
        }));
      }
    }
  };

  const isFormValid = () => {
    return calculationMode && 
           pumpType && 
           inputData.flowRate && 
           inputData.totalHead &&
           inputData.fluid;
  };

  return (
    <div className="min-h-screen bg-gray-50 dark:bg-gray-900 p-6">
      {/* Header with Back Button */}
      <div className="max-w-7xl mx-auto mb-8">
        <button
          onClick={() => navigate('/engineering/process/datasheet')}
          className="flex items-center gap-2 text-gray-600 dark:text-gray-400 hover:text-gray-900 dark:hover:text-white mb-4 transition-colors"
        >
          <ArrowLeftIcon className="w-5 h-5" />
          <span>Back to {MODULE_NAME}</span>
        </button>

        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 dark:text-white mb-2">
              Pump Hydraulic Calculation
            </h1>
            <p className="text-gray-600 dark:text-gray-400">
              AI-powered pump sizing, selection, and performance optimization
            </p>
          </div>
          <div className="flex items-center gap-2">
            <span className="px-3 py-1 bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 rounded-full text-sm font-medium">
              AI Powered
            </span>
          </div>
        </div>
      </div>

      <div className="max-w-7xl mx-auto">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          {/* Main Content Area */}
          <div className="lg:col-span-2 space-y-6">
            {/* Step 1: Calculation Mode Selection */}
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6">
              <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
                Step 1: Select Calculation Mode
              </h2>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                {calculationModes.map((mode) => (
                  <button
                    key={mode.value}
                    onClick={() => setCalculationMode(mode.value)}
                    className={`
                      p-4 rounded-lg border-2 transition-all duration-300 text-left
                      ${calculationMode === mode.value
                        ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
                        : 'border-gray-200 dark:border-gray-700 hover:border-blue-300 dark:hover:border-blue-700'}
                    `}
                  >
                    <div className="flex items-start gap-3">
                      <span className="text-3xl">{mode.icon}</span>
                      <div>
                        <div className="font-semibold text-gray-900 dark:text-white">
                          {mode.label}
                        </div>
                        <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                          {mode.description}
                        </p>
                      </div>
                    </div>
                  </button>
                ))}
              </div>
            </div>

            {/* Step 2: Pump Type Selection */}
            {calculationMode && (
              <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 animate-fadeIn">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
                  Step 2: Select Pump Type
                </h2>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {pumpTypes.map((type) => (
                    <button
                      key={type.value}
                      onClick={() => setPumpType(type.value)}
                      className={`
                        p-4 rounded-lg border-2 transition-all duration-300 text-left
                        ${pumpType === type.value
                          ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20'
                          : 'border-gray-200 dark:border-gray-700 hover:border-blue-300 dark:hover:border-blue-700'}
                      `}
                    >
                      <div className="flex items-start gap-3">
                        <span className="text-3xl">{type.icon}</span>
                        <div>
                          <div className="font-semibold text-gray-900 dark:text-white">
                            {type.label}
                          </div>
                          <p className="text-sm text-gray-600 dark:text-gray-400 mt-1">
                            {type.description}
                          </p>
                        </div>
                      </div>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {/* Step 3: Input Parameters */}
            {pumpType && (
              <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 animate-fadeIn">
                <h2 className="text-xl font-bold text-gray-900 dark:text-white mb-4">
                  Step 3: Enter Hydraulic Parameters
                </h2>
                
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                  {/* Flow Rate */}
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      Flow Rate (m³/h) *
                    </label>
                    <input
                      type="number"
                      value={inputData.flowRate}
                      onChange={(e) => handleInputChange('flowRate', e.target.value)}
                      placeholder="e.g., 100"
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>

                  {/* Total Head */}
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      Total Head (m) *
                    </label>
                    <input
                      type="number"
                      value={inputData.totalHead}
                      onChange={(e) => handleInputChange('totalHead', e.target.value)}
                      placeholder="e.g., 50"
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>

                  {/* Suction Pressure */}
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      Suction Pressure (bar)
                    </label>
                    <input
                      type="number"
                      value={inputData.suction}
                      onChange={(e) => handleInputChange('suction', e.target.value)}
                      placeholder="e.g., 1.0"
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>

                  {/* Discharge Pressure */}
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      Discharge Pressure (bar)
                    </label>
                    <input
                      type="number"
                      value={inputData.discharge}
                      onChange={(e) => handleInputChange('discharge', e.target.value)}
                      placeholder="e.g., 6.0"
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>

                  {/* Fluid Type */}
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      Fluid Type *
                    </label>
                    <select
                      value={inputData.fluid}
                      onChange={(e) => handleInputChange('fluid', e.target.value)}
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    >
                      {fluidTypes.map((fluid) => (
                        <option key={fluid.value} value={fluid.value}>
                          {fluid.label}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Temperature */}
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      Temperature (°C)
                    </label>
                    <input
                      type="number"
                      value={inputData.temperature}
                      onChange={(e) => handleInputChange('temperature', e.target.value)}
                      placeholder="e.g., 20"
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>

                  {/* Specific Gravity */}
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      Specific Gravity
                    </label>
                    <input
                      type="number"
                      step="0.001"
                      value={inputData.specificGravity}
                      onChange={(e) => handleInputChange('specificGravity', e.target.value)}
                      placeholder="e.g., 1.0"
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>

                  {/* Viscosity */}
                  <div>
                    <label className="block text-sm font-semibold text-gray-700 dark:text-gray-300 mb-2">
                      Viscosity (cP)
                    </label>
                    <input
                      type="number"
                      value={inputData.viscosity}
                      onChange={(e) => handleInputChange('viscosity', e.target.value)}
                      placeholder="e.g., 1.0"
                      className="w-full px-4 py-2 border border-gray-300 dark:border-gray-600 rounded-lg bg-white dark:bg-gray-700 text-gray-900 dark:text-white focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    />
                  </div>
                </div>

                {/* Calculate Button */}
                <button
                  disabled={!isFormValid()}
                  className={`
                    mt-6 w-full py-3 px-6 rounded-lg font-semibold text-white
                    transition-all duration-300 flex items-center justify-center gap-2
                    ${isFormValid()
                      ? 'bg-gradient-to-r from-blue-500 to-blue-600 hover:shadow-lg hover:from-blue-600 hover:to-blue-700'
                      : 'bg-gray-300 dark:bg-gray-700 cursor-not-allowed'}
                  `}
                >
                  <CalculatorIcon className="w-5 h-5" />
                  Calculate Pump Requirements
                </button>
              </div>
            )}
          </div>

          {/* Progress Sidebar */}
          <div className="lg:col-span-1">
            <div className="bg-white dark:bg-gray-800 rounded-xl shadow-lg p-6 sticky top-6">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white mb-4">
                Calculation Progress
              </h3>
              <div className="space-y-4">
                {calculationSteps.map((step, index) => {
                  const IconComponent = step.icon;
                  const isCompleted = step.status === 'completed';
                  const isCurrent = step.status === 'current';
                  
                  return (
                    <div key={step.id} className="flex gap-3">
                      <div className="flex flex-col items-center">
                        <div className={`
                          w-10 h-10 rounded-full flex items-center justify-center
                          ${isCompleted 
                            ? 'bg-green-100 dark:bg-green-900/30' 
                            : isCurrent
                            ? 'bg-blue-100 dark:bg-blue-900/30'
                            : 'bg-gray-100 dark:bg-gray-700'}
                        `}>
                          <IconComponent className={`
                            w-5 h-5
                            ${isCompleted 
                              ? 'text-green-600 dark:text-green-400' 
                              : isCurrent
                              ? 'text-blue-600 dark:text-blue-400'
                              : 'text-gray-400 dark:text-gray-500'}
                          `} />
                        </div>
                        {index < calculationSteps.length - 1 && (
                          <div className="w-0.5 h-12 bg-gray-200 dark:bg-gray-700 mt-2" />
                        )}
                      </div>
                      <div className="flex-1">
                        <div className={`
                          font-semibold text-sm
                          ${isCompleted || isCurrent
                            ? 'text-gray-900 dark:text-white'
                            : 'text-gray-500 dark:text-gray-400'}
                        `}>
                          {step.title}
                        </div>
                        <div className="text-xs text-gray-500 dark:text-gray-500 mt-1">
                          {step.description}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>

              {/* Info Box */}
              <div className="mt-6 p-4 bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800 rounded-lg">
                <p className="text-xs text-blue-800 dark:text-blue-200">
                  <strong>💡 Calculations Include:</strong><br/>
                  • Required pump power (BHP/kW)<br/>
                  • NPSH available & required<br/>
                  • System curve analysis<br/>
                  • Efficiency calculations<br/>
                  • Pump curve matching<br/>
                  • Vendor recommendations
                </p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default PumpHydraulicCalculation;

/**
 * Pump Hydraulic Calculation Page
 * Form-based datasheet generation with calculations
 */

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  FileText,
  Download,
  Sparkles,
  Upload,
  Loader2
} from 'lucide-react';
import { SparklesIcon } from '@heroicons/react/24/outline';
import apiClient from '../../services/api.service';
import * as XLSX from 'xlsx';

// ─── Soft-coded extraction config ────────────────────────────────────────
// Endpoint, accepted file types and provenance colours all live here so the
// UI behaviour can be tweaked without touching the form / calculation logic.
const PUMP_EXTRACTION_CONFIG = {
  enabled: true,
  endpoint: '/process-datasheet/datasheets/extract-pump-hydraulic/',
  fileFieldName: 'pump_file',                  // multipart field name
  acceptedTypes: '.pdf,application/pdf',
  maxFileSizeMB: 50,
  // Maps backend provenance -> badge styling
  provenanceBadge: {
    text:   { label: 'PDF text',    className: 'bg-emerald-100 text-emerald-700' },
    vision: { label: 'AI Vision',   className: 'bg-indigo-100 text-indigo-700' },
  },
  // Field labels shown in the "extracted fields" summary list
  resultListPreview: 8,
};

const PumpHydraulicPage = () => {
  const navigate = useNavigate();

  const [pumpFormData, setPumpFormData] = useState({
    // PROJECT_INFO Section
    agreement_no: '',
    project_no: '',
    document_no: '',
    revision: 'A',
    document_class: 'Confidential',
    tag_no: '',
    service: '',
    motor_classification: '',
    temperature: '',
    fluid_viscosity_at_temp: '',
    hp: '',
    pump_centerline_elevation: '',
    elevation_source_btl: '',

    // GENERAL_INFO Section (Discharge Pressure Calculations)
    destination_description: 'Cooling Water Tank (06.5- T - 2307)',
    flow: 'Normal',
    destination_pressure: '',
    destination_elevation: '',
    line_friction_loss: '',
    flow_meter_del_p: '',
    other_losses: '',
    control_valve: '',
    misc_item: '',
    contingency: '',
    total_discharge_pressure: '',

    // CONTROL_VALVE_SIZING Section
    density: '',
    cv_max: '',
    cv_min: '',
    cv_ratio: '',
    total_frictional_losses: '',
    dynamic_losses_30_percent: '',
    control_valve_delta_p: '',
    cv_pressure_drop: '',
    cv_rangeability: '',
    cv_ratio_within_range: '',
    cv_pressure_drop_check: '',

    // SUCTION_PRESSURE Section
    source_op_pressure: '',
    suction_elm: '',
    inline_inst_losses: '',
    line_fric_losses: '',
    control_valve_suction: '',
    misc_items_suction: '',
    total_suction_losses: '',
    total_suction_pressure: '',

    // POWER_CONSUMPTION Section
    power_consumption_per_pump: '',
    hydraulic_power: '',
    pump_efficiency: '',
    break_horse_power: '',
    motor_rating: '',
    motor_efficiency: '',
    power_consumption: '',
    type_of_motor: '',

    // NPSH_AVAILABILITY Section
    npsh_availability: '',
    suction_pressure_npsh: '',
    vapor_pressure: '',
    npsha: '',
    safety_margin_npsha: '',
    npsha_with_safety_margin: '',

    // PUMP_CALCULATION_RESULTS Section (5 calculated fields)
    discharge_pressure: '',
    suction_pressure_result: '',
    differential_pressure: '',
    differential_head: '',
    npsha_result: '',

    // MAX_SUCTION_PRESSURE Section (4 fields)
    suction_vessel_max_op_pressure: '',
    suction_el_m: '',
    tl_to_hhll_m: '',
    max_suction_pressure: '',

    // MINIMUM_FLOW Section (9 fields)
    pump_minimum_flow: '',
    fluid_density_mcf: '',
    pump_discharge_pressure_min_flow: '',
    destination_pressure: '',
    el_destination_pump_cl: '',
    mcf_line_friction_losses: '',
    flow_meter_losses: '',
    misc_pressure_drop_mcf: '',
    mcf_cv_pressure_drop: '',

    // MAX_DISCHARGE_PRESSURE Section (6 fields)
    api_610_tolerance_used: '',
    api_tolerance_factor: '',
    shut_off_pressure_factor: '',
    shut_off_differential_pressure: '',
    maximum_discharge_pressure_option_1: '',
    maximum_discharge_pressure_option_2: ''
  });

  const [showPreview, setShowPreview] = useState(false);
  const [error, setError] = useState('');

  // ─── Soft-coded extraction state (additive to the form) ───────────────
  const [extracting, setExtracting] = useState(false);
  const [extractInfo, setExtractInfo] = useState(null);   // { engine, page_count, source_filename, fields, provenance, warnings }
  const [extractError, setExtractError] = useState('');

  const handlePumpExtract = async (event) => {
    const file = event.target.files?.[0];
    event.target.value = '';                              // allow re-selecting the same file
    if (!file) return;

    if (file.size > PUMP_EXTRACTION_CONFIG.maxFileSizeMB * 1024 * 1024) {
      setExtractError(`File too large (max ${PUMP_EXTRACTION_CONFIG.maxFileSizeMB} MB).`);
      return;
    }

    setExtracting(true);
    setExtractError('');
    setExtractInfo(null);

    try {
      const fd = new FormData();
      fd.append(PUMP_EXTRACTION_CONFIG.fileFieldName, file);
      const res = await apiClient.post(
        PUMP_EXTRACTION_CONFIG.endpoint,
        fd,
        { headers: { 'Content-Type': 'multipart/form-data' }, timeout: 180000 },
      );

      const data = res.data || {};
      if (data.status !== 'ok') {
        setExtractError(data.message || 'Extraction failed.');
        return;
      }

      // Merge extracted fields into the form, but never overwrite a value the
      // user has already typed.  This keeps "manual entry" the source of truth.
      const fields = data.fields || {};
      setPumpFormData(prev => {
        const merged = { ...prev };
        Object.entries(fields).forEach(([k, v]) => {
          if (k in merged && (merged[k] === '' || merged[k] === null || merged[k] === undefined)) {
            merged[k] = String(v);
          }
        });
        return merged;
      });

      setExtractInfo({
        engine:          data.engine,
        page_count:      data.page_count,
        source_filename: data.source_filename || file.name,
        fields,
        provenance:      data.provenance || {},
        warnings:        data.warnings || [],
      });
    } catch (e) {
      setExtractError(
        e?.response?.data?.message
        || e?.response?.data?.error
        || e.message
        || 'Extraction failed',
      );
    } finally {
      setExtracting(false);
    }
  };

  // Handle form input changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setPumpFormData(prev => ({
      ...prev,
      [name]: value
    }));

    // Trigger calculations on specific field changes
    if (['destination_pressure', 'destination_elevation', 'line_friction_loss', 'flow_meter_del_p', 
         'other_losses', 'control_valve', 'misc_item', 'contingency'].includes(name)) {
      calculateTotalDischargePressure({ ...pumpFormData, [name]: value });
    }
    
    if (['density', 'cv_max', 'cv_min'].includes(name)) {
      calculateControlValveSizing({ ...pumpFormData, [name]: value });
    }
    
    if (['source_op_pressure', 'suction_elm', 'inline_inst_losses', 'line_fric_losses',
         'control_valve_suction', 'misc_items_suction'].includes(name)) {
      calculateTotalSuctionPressure({ ...pumpFormData, [name]: value });
    }
    
    if (['hydraulic_power', 'pump_efficiency'].includes(name)) {
      calculatePowerConsumption({ ...pumpFormData, [name]: value });
    }
    
    if (['suction_pressure_npsh', 'vapor_pressure', 'npsha'].includes(name)) {
      calculateNPSHA({ ...pumpFormData, [name]: value });
    }
  };

  // Calculation functions
  const calculateTotalDischargePressure = (data) => {
    const sum = (
      parseFloat(data.destination_pressure || 0) +
      parseFloat(data.destination_elevation || 0) +
      parseFloat(data.line_friction_loss || 0) +
      parseFloat(data.flow_meter_del_p || 0) +
      parseFloat(data.other_losses || 0) +
      parseFloat(data.control_valve || 0) +
      parseFloat(data.misc_item || 0) +
      parseFloat(data.contingency || 0)
    );
    setPumpFormData(prev => ({ ...prev, total_discharge_pressure: sum.toFixed(2) }));
  };

  const calculateControlValveSizing = (data) => {
    const cvMax = parseFloat(data.cv_max || 0);
    const cvMin = parseFloat(data.cv_min || 0);
    const ratio = cvMax && cvMin ? (cvMax / cvMin).toFixed(2) : '';
    setPumpFormData(prev => ({ ...prev, cv_ratio: ratio }));
  };

  const calculateTotalSuctionPressure = (data) => {
    const losses = (
      parseFloat(data.inline_inst_losses || 0) +
      parseFloat(data.line_fric_losses || 0) +
      parseFloat(data.control_valve_suction || 0) +
      parseFloat(data.misc_items_suction || 0)
    );
    const total = parseFloat(data.source_op_pressure || 0) + parseFloat(data.suction_elm || 0) - losses;
    setPumpFormData(prev => ({ 
      ...prev, 
      total_suction_losses: losses.toFixed(2),
      total_suction_pressure: total.toFixed(2) 
    }));
  };

  const calculatePowerConsumption = (data) => {
    const hp = parseFloat(data.hydraulic_power || 0);
    const eff = parseFloat(data.pump_efficiency || 100);
    const bhp = eff ? (hp / (eff / 100)).toFixed(2) : '';
    setPumpFormData(prev => ({ ...prev, break_horse_power: bhp }));
  };

  const calculateNPSHA = (data) => {
    const npsha = (
      parseFloat(data.suction_pressure_npsh || 0) -
      parseFloat(data.vapor_pressure || 0)
    );
    const withMargin = npsha + parseFloat(data.safety_margin_npsha || 0);
    setPumpFormData(prev => ({ 
      ...prev, 
      npsha: npsha.toFixed(2),
      npsha_with_safety_margin: withMargin.toFixed(2)
    }));
  };

  const calculateFinalResults = (data) => {
    return {
      discharge_pressure: data.total_discharge_pressure || '',
      suction_pressure_result: data.total_suction_pressure || '',
      differential_pressure: (parseFloat(data.total_discharge_pressure || 0) - parseFloat(data.total_suction_pressure || 0)).toFixed(2),
      differential_head: ((parseFloat(data.total_discharge_pressure || 0) - parseFloat(data.total_suction_pressure || 0)) / (parseFloat(data.density || 1) * 9.81 / 1000)).toFixed(2),
      npsha_result: data.npsha_with_safety_margin || ''
    };
  };

  const handleGeneratePreview = () => {
    setShowPreview(true);
    const finalCalcs = calculateFinalResults(pumpFormData);
    setPumpFormData(prev => ({ ...prev, ...finalCalcs }));
  };

  const downloadTableAsExcel = () => {
    const data = pumpFormData;
    const excelData = [];
    let currentRow = 0;
    const sectionRows = [];
    const totalRows = [];

    // Helper to add section header
    const addSectionHeader = (title) => {
      excelData.push([title, '']);
      sectionRows.push(currentRow);
      currentRow++;
    };

    // Helper to add field
    const addField = (label, value, isTotal = false) => {
      excelData.push([label, value || '']);
      if (isTotal) totalRows.push(currentRow);
      currentRow++;
    };

    // Main Header
    excelData.push(['PUMP HYDRAULIC CALCULATION DATASHEET', '']);
    sectionRows.push(0);
    currentRow++;
    excelData.push(['', '']);
    currentRow++;

    // Section 1: Project Information
    addSectionHeader('1. PROJECT INFORMATION');
    addField('Agreement No', data.agreement_no);
    addField('Project No', data.project_no);
    addField('Document No', data.document_no);
    addField('Revision', data.revision);
    addField('Document Class', data.document_class);
    addField('Tag No', data.tag_no);
    addField('Service', data.service);
    excelData.push(['', '']);
    currentRow++;

    // Section 2: General Information
    addSectionHeader('2. DISCHARGE PRESSURE CALCULATIONS');
    addField('Destination Description', data.destination_description);
    addField('Flow Type', data.flow);
    addField('Destination Pressure (bar)', data.destination_pressure);
    addField('Destination Elevation (bar)', data.destination_elevation);
    addField('Line Friction Loss (bar)', data.line_friction_loss);
    addField('Flow Meter ΔP (bar)', data.flow_meter_del_p);
    addField('Other Losses (bar)', data.other_losses);
    addField('Control Valve (bar)', data.control_valve);
    addField('Misc Item (bar)', data.misc_item);
    addField('Contingency (bar)', data.contingency);
    addField('TOTAL DISCHARGE PRESSURE (bar)', data.total_discharge_pressure, true);
    excelData.push(['', '']);
    currentRow++;

    // Section 3: Control Valve Sizing
    addSectionHeader('3. CONTROL VALVE SIZING');
    addField('Density (kg/m³)', data.density);
    addField('Cv Max', data.cv_max);
    addField('Cv Min', data.cv_min);
    addField('Cv Ratio', data.cv_ratio, true);
    excelData.push(['', '']);
    currentRow++;

    // Section 4: Suction Pressure
    addSectionHeader('4. SUCTION PRESSURE CALCULATIONS');
    addField('Source Operating Pressure (bar)', data.source_op_pressure);
    addField('Suction Elevation (bar)', data.suction_elm);
    addField('Inline Instrument Losses (bar)', data.inline_inst_losses);
    addField('Line Friction Losses (bar)', data.line_fric_losses);
    addField('Control Valve Suction (bar)', data.control_valve_suction);
    addField('Misc Items Suction (bar)', data.misc_items_suction);
    addField('TOTAL SUCTION LOSSES (bar)', data.total_suction_losses, true);
    addField('TOTAL SUCTION PRESSURE (bar)', data.total_suction_pressure, true);
    excelData.push(['', '']);
    currentRow++;

    // Section 5: Power Consumption
    addSectionHeader('5. POWER CONSUMPTION');
    addField('Hydraulic Power (kW)', data.hydraulic_power);
    addField('Pump Efficiency (%)', data.pump_efficiency);
    addField('BREAK HORSE POWER (kW)', data.break_horse_power, true);
    addField('Motor Rating (kW)', data.motor_rating);
    addField('Motor Efficiency (%)', data.motor_efficiency);
    addField('POWER CONSUMPTION (kW)', data.power_consumption, true);
    addField('Type of Motor', data.type_of_motor);
    excelData.push(['', '']);
    currentRow++;

    // Section 6: NPSH Availability
    addSectionHeader('6. NPSH AVAILABILITY');
    addField('Suction Pressure (bar)', data.suction_pressure_npsh);
    addField('Vapor Pressure (bar)', data.vapor_pressure);
    addField('NPSHA (m)', data.npsha, true);
    addField('Safety Margin (m)', data.safety_margin_npsha);
    addField('NPSHA WITH SAFETY MARGIN (m)', data.npsha_with_safety_margin, true);
    excelData.push(['', '']);
    currentRow++;

    // Section 7: Pump Calculation Results
    addSectionHeader('7. PUMP CALCULATION RESULTS');
    addField('Discharge Pressure (bar)', data.discharge_pressure, true);
    addField('Suction Pressure (bar)', data.suction_pressure_result, true);
    addField('Differential Pressure (bar)', data.differential_pressure, true);
    addField('Differential Head (m)', data.differential_head, true);
    addField('NPSHA (m)', data.npsha_result, true);
    excelData.push(['', '']);
    currentRow++;

    // Section 8: Max Suction Pressure
    addSectionHeader('8. MAXIMUM SUCTION PRESSURE');
    addField('Suction Vessel Max Op Pressure (bar)', data.suction_vessel_max_op_pressure);
    addField('Suction Elevation (m)', data.suction_el_m);
    addField('TL to HHLL (m)', data.tl_to_hhll_m);
    addField('MAX SUCTION PRESSURE (bar)', data.max_suction_pressure, true);
    excelData.push(['', '']);
    currentRow++;

    // Section 9: Minimum Flow
    addSectionHeader('9. MINIMUM FLOW CALCULATIONS');
    addField('Pump Minimum Flow (m³/h)', data.pump_minimum_flow);
    addField('Fluid Density MCF (kg/m³)', data.fluid_density_mcf);
    addField('Pump Discharge Pressure Min Flow (bar)', data.pump_discharge_pressure_min_flow);
    addField('Destination Pressure (bar)', data.destination_pressure);
    addField('Elevation Destination to Pump CL (bar)', data.el_destination_pump_cl);
    addField('MCF Line Friction Losses (bar)', data.mcf_line_friction_losses);
    addField('Flow Meter Losses (bar)', data.flow_meter_losses);
    addField('Misc Pressure Drop MCF (bar)', data.misc_pressure_drop_mcf);
    addField('MCF CV Pressure Drop (bar)', data.mcf_cv_pressure_drop, true);
    excelData.push(['', '']);
    currentRow++;

    // Section 10: Max Discharge Pressure
    addSectionHeader('10. MAXIMUM DISCHARGE PRESSURE');
    addField('API 610 Tolerance Used', data.api_610_tolerance_used);
    addField('API Tolerance Factor', data.api_tolerance_factor);
    addField('Shut-off Pressure Factor', data.shut_off_pressure_factor);
    addField('Shut-off Differential Pressure (bar)', data.shut_off_differential_pressure);
    addField('MAX DISCHARGE PRESSURE Option 1 (bar)', data.maximum_discharge_pressure_option_1, true);
    addField('MAX DISCHARGE PRESSURE Option 2 (bar)', data.maximum_discharge_pressure_option_2, true);

    // Create workbook
    const wb = XLSX.utils.book_new();
    const ws = XLSX.utils.aoa_to_sheet(excelData);

    // Apply styling
    ws['!cols'] = [{ width: 50 }, { width: 20 }];

    // Style section headers (blue background)
    sectionRows.forEach(row => {
      const cellRef = XLSX.utils.encode_cell({ r: row, c: 0 });
      if (!ws[cellRef]) ws[cellRef] = { t: 's', v: '' };
      ws[cellRef].s = {
        fill: { fgColor: { rgb: "4472C4" } },
        font: { bold: true, color: { rgb: "FFFFFF" }, sz: 12 },
        alignment: { horizontal: "center", vertical: "center" }
      };
    });

    // Style total rows (yellow background)
    totalRows.forEach(row => {
      const cellRef = XLSX.utils.encode_cell({ r: row, c: 0 });
      const cellRefValue = XLSX.utils.encode_cell({ r: row, c: 1 });
      if (!ws[cellRef]) ws[cellRef] = { t: 's', v: '' };
      if (!ws[cellRefValue]) ws[cellRefValue] = { t: 's', v: '' };
      
      ws[cellRef].s = {
        fill: { fgColor: { rgb: "FFF2CC" } },
        font: { bold: true, sz: 11 }
      };
      ws[cellRefValue].s = {
        fill: { fgColor: { rgb: "FFF2CC" } },
        font: { bold: true, sz: 11 }
      };
    });

    // Add borders to all cells
    const range = XLSX.utils.decode_range(ws['!ref']);
    for (let R = range.s.r; R <= range.e.r; ++R) {
      for (let C = range.s.c; C <= range.e.c; ++C) {
        const cellRef = XLSX.utils.encode_cell({ r: R, c: C });
        if (!ws[cellRef]) ws[cellRef] = { t: 's', v: '' };
        if (!ws[cellRef].s) ws[cellRef].s = {};
        ws[cellRef].s.border = {
          top: { style: 'thin', color: { rgb: 'CCCCCC' } },
          bottom: { style: 'thin', color: { rgb: 'CCCCCC' } },
          left: { style: 'thin', color: { rgb: 'CCCCCC' } },
          right: { style: 'thin', color: { rgb: 'CCCCCC' } }
        };
      }
    }

    XLSX.utils.book_append_sheet(wb, ws, 'Pump Hydraulic Datasheet');
    
    const filename = `Pump_Hydraulic_${data.tag_no || 'Datasheet'}_${new Date().toISOString().split('T')[0]}.xlsx`;
    XLSX.writeFile(wb, filename);
  };

  const renderFormField = (label, name, type = 'text', placeholder = '', required = false) => (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <input
        type={type}
        name={name}
        value={pumpFormData[name]}
        onChange={handleInputChange}
        placeholder={placeholder}
        className="w-full px-3 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
      />
    </div>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-indigo-50 to-purple-50">
      <div className="container mx-auto px-4 py-8">
        {/* Header */}
        <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 mb-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <button
                onClick={() => navigate('/engineering/process/datasheet/smart')}
                className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
              >
                <ArrowLeft className="h-5 w-5 text-gray-600" />
              </button>
              <div>
                <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-2">
                  💧 Pump Hydraulic Calculation
                </h1>
                <p className="text-gray-600 mt-1">
                  Form-based datasheet with automatic calculations
                </p>
              </div>
            </div>
          </div>
        </div>

        {!showPreview ? (
          <>
            {/* Pump Form - All 10 Sections */}
            <div className="bg-white rounded-xl shadow-sm border border-gray-200 p-6 space-y-4">

              {/* ───── Smart PDF prefill (additive, soft-coded) ───── */}
              {PUMP_EXTRACTION_CONFIG.enabled && (
                <div className="bg-gradient-to-r from-indigo-50 to-blue-50 border-2 border-dashed border-indigo-300 rounded-lg p-4">
                  <div className="flex items-start gap-4">
                    <div className="p-2 bg-white rounded-lg shadow-sm">
                      <Upload className="h-6 w-6 text-indigo-600" />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between flex-wrap gap-2">
                        <div>
                          <h3 className="font-semibold text-indigo-900 flex items-center gap-2">
                            <SparklesIcon className="h-4 w-4" />
                            Auto-fill from PFD / pump data PDF
                          </h3>
                          <p className="text-xs text-indigo-700/80 mt-0.5">
                            Upload the source drawing — extracted values populate empty fields only.
                            Already-typed values are preserved.
                          </p>
                        </div>
                        <label
                          className={`px-4 py-2 rounded-lg text-sm font-medium cursor-pointer flex items-center gap-2 transition-all ${
                            extracting
                              ? 'bg-indigo-300 text-white cursor-wait'
                              : 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-sm'
                          }`}
                        >
                          {extracting ? (
                            <>
                              <Loader2 className="h-4 w-4 animate-spin" />
                              Extracting…
                            </>
                          ) : (
                            <>
                              <Upload className="h-4 w-4" />
                              Choose PDF
                            </>
                          )}
                          <input
                            type="file"
                            accept={PUMP_EXTRACTION_CONFIG.acceptedTypes}
                            onChange={handlePumpExtract}
                            disabled={extracting}
                            className="hidden"
                          />
                        </label>
                      </div>

                      {extractError && (
                        <div className="mt-3 px-3 py-2 bg-red-50 border border-red-200 rounded text-xs text-red-700">
                          {extractError}
                        </div>
                      )}

                      {extractInfo && (
                        <div className="mt-3 bg-white border border-indigo-200 rounded-lg p-3 text-xs">
                          <div className="flex items-center justify-between flex-wrap gap-2">
                            <span className="text-slate-600">
                              <span className="font-semibold text-slate-800">{extractInfo.source_filename}</span>
                              {' · '}{extractInfo.page_count} page(s)
