      return;
    }

    // Validate size (50MB)
    const sizeMB = file.size / (1024 * 1024);
    if (sizeMB > 50) {
      setError('File size must be less than 50MB');
      return;
    }

    setUploadedFiles(prev => ({
      ...prev,
      [fileKey]: file
    }));
    setError('');
  };

