    if (e.type === 'dragenter' || e.type === 'dragover') {
      setDragActive(fileKey);
    } else if (e.type === 'dragleave') {
      setDragActive('');
    }
  };

  const handleDrop = (e, fileKey) => {
    e.preventDefault();
    e.stopPropagation();
