];

const REGIONS = [
  'Middle East', 'GCC', 'North Africa', 'Europe', 'North America', 'Asia Pacific'
];

// Validation rules (soft-coded)
const VALIDATION = {
  project_number: { min: 3, max: 100, required: true },
  project_name: { min: 5, max: 300, required: true },
  client_name: { min: 2, max: 200, required: false },
  description: { min: 10, max: 5000, required: false },
};

const INITIAL_FORM_DATA = {
  project_number: '',
  project_name: '',
  client_name: '',
  client_reference: '',
  project_type: 'engineering',
  status: 'planning',
  health_status: 'green',
  cost_center: '',
  project_manager: '',
  project_manager_name: '',
  lead_engineer: '',
  description: '',
  scope_of_work: '',
  start_date: '',
  planned_end_date: '',
  site_location: '',
  country: 'United Arab Emirates',
  region: 'Middle East',
  contract_value: '',
  contract_currency: 'AED',
  payment_terms: '',
  is_billable: true,
  is_internal: false,
  notes: '',
};

// ══════════════════════════════════════════════════════════════════════════════
// MAIN COMPONENT
// ══════════════════════════════════════════════════════════════════════════════

const ProjectCreator = () => {
  const navigate = useNavigate();
  const { id } = useParams();
  const isEditMode = Boolean(id);
  
  // Form state
  const [formData, setFormData] = useState({ ...INITIAL_FORM_DATA });

  const [errors, setErrors] = useState({});
  const [loading, setLoading] = useState(isEditMode);
  const [loadError, setLoadError] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [notification, setNotification] = useState(null);
  
  // Lookups
  const [costCenters, setCostCenters] = useState([]);
  const [users, setUsers] = useState([]);
  
  // Fetch reference data
  useEffect(() => {
    fetchCostCenters();
    fetchUsers();
    if (id) fetchProject();
  }, [id]);

  const fetchProject = async () => {
    try {
      setLoading(true);
      setLoadError(null);
      const response = await apiClient.get(`/procurement/projects/${id}/`);
      const project = response.data || {};
      const populatedForm = Object.fromEntries(
        Object.entries(INITIAL_FORM_DATA).map(([field, defaultValue]) => [
          field,
          project[field] ?? defaultValue,
        ])
      );
      setFormData(populatedForm);
    } catch (error) {
      console.error('Failed to load project:', error);
      setLoadError(error.response?.status === 404 ? 'Project not found or no longer active.' : 'Failed to load project for editing.');
    } finally {
      setLoading(false);
    }
  };
  
  const fetchCostCenters = async () => {
    try {
      const response = await apiClient.get('/procurement/cost-centers/?is_active=true');
      const responseData = response.data?.results || response.data;
      setCostCenters(Array.isArray(responseData) ? responseData : []);
    } catch (error) {
      console.error('Failed to fetch cost centers:', error);
    }
  };
  
  const fetchUsers = async () => {
    try {
      const response = await apiClient.get('/procurement/requisitions/get_approvers/', {
        params: { role: 'any_active' },
      });
      setUsers(Array.isArray(response.data?.users) ? response.data.users : []);
    } catch (error) {
      console.error('Failed to fetch users:', error);
    }
  };
  
  // Auto-generate project number (soft-coded format: PRJ-YYYY-XXX)
  const generateProjectNumber = () => {
    const year = new Date().getFullYear();
    const random = Math.floor(Math.random() * 1000).toString().padStart(3, '0');
    const projectNumber = `PRJ-${year}-${random}`;
    
    setFormData(prev => ({ ...prev, project_number: projectNumber }));
    showNotification('success', 'Project number generated');
  };
  
  // Handle field changes
  const handleChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    
    // Clear error for this field
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: null }));
    }
    
    // Derived logic (soft-coded)
    if (field === 'project_type' && value === 'internal') {
      setFormData(prev => ({ ...prev, is_internal: true, is_billable: false }));
    }
  };
  
  // Validate form (soft-coded validation rules)
  const validateForm = () => {
    const newErrors = {};
    
    // Required fields
    if (!formData.project_number || formData.project_number.length < VALIDATION.project_number.min) {
      newErrors.project_number = `Project number must be at least ${VALIDATION.project_number.min} characters`;
    }
    
    if (!formData.project_name || formData.project_name.length < VALIDATION.project_name.min) {
      newErrors.project_name = `Project name must be at least ${VALIDATION.project_name.min} characters`;
    }
    
    if (formData.project_name && formData.project_name.length > VALIDATION.project_name.max) {
      newErrors.project_name = `Project name must not exceed ${VALIDATION.project_name.max} characters`;
    }
    
    // Date validation
    if (formData.start_date && formData.planned_end_date) {
      if (new Date(formData.planned_end_date) < new Date(formData.start_date)) {
        newErrors.planned_end_date = 'End date must be after start date';
      }
    }
    
    // Financial validation
    if (formData.contract_value && isNaN(parseFloat(formData.contract_value))) {
      newErrors.contract_value = 'Contract value must be a valid number';
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };
  
  // Submit form
  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) {
      showNotification('error', 'Please fix the errors in the form');
      return;
    }
    
    setSubmitting(true);
    
    try {
      // Clean up data before submission
      const payload = {
        ...formData,
        project_number: formData.project_number.trim(),
        project_name: formData.project_name.trim(),
        contract_value: formData.contract_value ? parseFloat(formData.contract_value) : null,
        cost_center: formData.cost_center || null,
        project_manager: formData.project_manager || null,
        lead_engineer: formData.lead_engineer || null,
        start_date: formData.start_date || null,
        planned_end_date: formData.planned_end_date || null,
      };
      
      const response = isEditMode
        ? await apiClient.patch(`/procurement/projects/${id}/`, payload)
        : await apiClient.post('/procurement/projects/', payload);
      
      showNotification('success', isEditMode ? 'Project updated successfully!' : 'Project created successfully!');
      
      // Redirect to project detail page after short delay
      setTimeout(() => {
        navigate(`/procurement/projects/${response.data.id || id}`);
      }, 800);
      
    } catch (error) {
      console.error(`Failed to ${isEditMode ? 'update' : 'create'} project:`, error);
      
      // Extract error messages from response
      if (error.response?.data) {
        const apiErrors = {};
        Object.keys(error.response.data).forEach(key => {
          const value = error.response.data[key];
          apiErrors[key] = Array.isArray(value) ? value[0] : value;
        });
        setErrors(apiErrors);
      }
      
      showNotification('error', error.response?.data?.detail || `Failed to ${isEditMode ? 'update' : 'create'} project`);
    } finally {
      setSubmitting(false);
    }
  };
  
  // Show notification
  const showNotification = (type, message) => {
    setNotification({ type, message });
    setTimeout(() => setNotification(null), 5000);
  };
  
  // Render field group
  const FieldGroup = ({ title, icon: Icon, children }) => (
    <div className="bg-white rounded-lg border border-gray-200 p-6">
      <div className="flex items-center gap-2 mb-4 pb-3 border-b border-gray-200">
        <Icon className="h-5 w-5 text-blue-600" />
        <h3 className="text-lg font-semibold text-gray-900">{title}</h3>
      </div>
      <div className="space-y-4">
        {children}
      </div>
    </div>
  );
  
  // Render input field
  const InputField = ({ label, field, type = 'text', placeholder, required, helpText, rows }) => (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      {rows ? (
        <textarea
          value={formData[field] || ''}
          onChange={(e) => handleChange(field, e.target.value)}
          rows={rows}
          placeholder={placeholder}
          className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 ${
            errors[field] ? 'border-red-500' : 'border-gray-300'
          }`}
        />
      ) : (
        <input
          type={type}
          value={formData[field] || ''}
          onChange={(e) => handleChange(field, e.target.value)}
          placeholder={placeholder}
          className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 ${
            errors[field] ? 'border-red-500' : 'border-gray-300'
          }`}
        />
      )}
      {helpText && !errors[field] && (
        <p className="text-xs text-gray-500 mt-1">{helpText}</p>
      )}
      {errors[field] && (
        <p className="text-xs text-red-600 mt-1 flex items-center gap-1">
          <ExclamationCircleIcon className="h-3 w-3" />
          {errors[field]}
        </p>
      )}
    </div>
  );
  
  // Render select field
  const SelectField = ({ label, field, options, required, helpText }) => (
    <div>
      <label className="block text-sm font-medium text-gray-700 mb-1">
        {label} {required && <span className="text-red-500">*</span>}
      </label>
      <select
        value={formData[field] || ''}
        onChange={(e) => handleChange(field, e.target.value)}
        className={`w-full px-3 py-2 border rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 ${
          errors[field] ? 'border-red-500' : 'border-gray-300'
        }`}
      >
        <option value="">Select...</option>
        {options.map(opt => (
          <option key={opt.value || opt} value={opt.value || opt}>
            {opt.label || opt}
          </option>
        ))}
      </select>
      {helpText && !errors[field] && (
        <p className="text-xs text-gray-500 mt-1">{helpText}</p>
      )}
      {errors[field] && (
        <p className="text-xs text-red-600 mt-1">{errors[field]}</p>
      )}
    </div>
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="text-center">
          <div className="mx-auto h-10 w-10 animate-spin rounded-full border-4 border-blue-100 border-t-blue-600" />
          <p className="mt-3 text-sm font-medium text-gray-600">Loading project...</p>
        </div>
      </div>
    );
  }

  if (loadError) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center px-4">
        <div className="max-w-md rounded-lg border border-red-200 bg-white p-8 text-center shadow-md">
          <ExclamationCircleIcon className="mx-auto h-12 w-12 text-red-500" />
          <h1 className="mt-4 text-xl font-bold text-gray-900">Unable to Edit Project</h1>
          <p className="mt-2 text-sm text-gray-600">{loadError}</p>
          <button type="button" onClick={() => navigate('/procurement/projects')} className="mt-6 rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white hover:bg-blue-700">Back to Projects</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b border-gray-200 sticky top-0 z-10">
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <button
                onClick={() => navigate('/procurement/projects')}
                className="flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors"
              >
                <ArrowLeftIcon className="h-5 w-5" />
                <span className="font-medium">Back to Projects</span>
              </button>
              <div className="h-6 w-px bg-gray-300" />
              <div>
                <h1 className="text-2xl font-bold text-gray-900">{isEditMode ? 'Edit Project' : 'Create New Project'}</h1>
                <p className="text-sm text-gray-600 mt-1">{isEditMode ? 'Update the procurement project information' : 'Set up a new procurement project'}</p>
              </div>
            </div>
            
            {!isEditMode && (
              <button
                type="button"
                onClick={generateProjectNumber}
                className="flex items-center gap-2 px-4 py-2 bg-blue-50 text-blue-600 rounded-lg hover:bg-blue-100 transition-colors"
              >
                <SparklesIcon className="h-4 w-4" />
                Generate Project #
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Notification */}
      {notification && (
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className={`flex items-center gap-3 px-4 py-3 rounded-lg ${
            notification.type === 'success' ? 'bg-green-50 text-green-800' :
            notification.type === 'error' ? 'bg-red-50 text-red-800' :
            'bg-blue-50 text-blue-800'
          }`}>
            {notification.type === 'success' && <CheckCircleIcon className="h-5 w-5" />}
            {notification.type === 'error' && <ExclamationCircleIcon className="h-5 w-5" />}
            {notification.type === 'info' && <InformationCircleIcon className="h-5 w-5" />}
            <span className="font-medium">{notification.message}</span>
          </div>
        </div>
      )}

      {/* Form */}
      <form onSubmit={handleSubmit} className="max-w-7xl mx-auto px-6 py-8">
        <div className="space-y-6">
          {/* Identification */}
          <FieldGroup title="Project Identification" icon={BriefcaseIcon}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <InputField
                label="Project Number"
                field="project_number"
                placeholder="PRJ-2026-001"
                required
                helpText="Unique project identifier (auto-generated or custom)"
              />
              <InputField
                label="Client Reference"
                field="client_reference"
                placeholder="PO-1234"
                helpText="Client's PO or contract number"
              />
            </div>
            
            <InputField
              label="Project Name"
              field="project_name"
              placeholder="e.g., ADNOC Offshore Platform Modification"
              required
              helpText="Clear, descriptive project name"
            />
            
            <InputField
              label="Client Name"
              field="client_name"
              placeholder="e.g., ADNOC, Saudi Aramco"
            />
          </FieldGroup>

          {/* Classification */}
          <FieldGroup title="Classification & Status" icon={DocumentTextIcon}>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
              <SelectField
                label="Project Type"
                field="project_type"
                options={PROJECT_TYPES}
                required
                helpText="Primary project category"
              />
              <SelectField
                label="Status"
                field="status"
                options={PROJECT_STATUSES}
                required
              />
              <SelectField
                label="Health Status"
                field="health_status"
                options={HEALTH_STATUSES}
                required
              />
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg">
                <input
                  type="checkbox"
                  checked={formData.is_billable}
                  onChange={(e) => handleChange('is_billable', e.target.checked)}
                  className="h-4 w-4 text-blue-600 rounded"
                />
                <label className="text-sm font-medium text-gray-700">
                  Client-Billable Project
                </label>
              </div>
              
              <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg">
                <input
                  type="checkbox"
                  checked={formData.is_internal}
                  onChange={(e) => handleChange('is_internal', e.target.checked)}
                  className="h-4 w-4 text-blue-600 rounded"
                />
                <label className="text-sm font-medium text-gray-700">
                  Internal R&D / Overhead Project
                </label>
              </div>
            </div>
          </FieldGroup>

          {/* Organization & Team */}
          <FieldGroup title="Organization & Team" icon={UserGroupIcon}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <SelectField
                label="Cost Center"
                field="cost_center"
                options={costCenters.map(cc => ({ value: cc.id, label: `${cc.code} - ${cc.name}` }))}
                helpText="Budget allocation cost center"
              />
              
              <SelectField
                label="Project Manager"
                field="project_manager"
                options={users.map(u => ({ value: u.id, label: u.full_name || u.email || u.username }))}
                helpText="Primary project manager (from users list)"
              />
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <InputField
                label="PM Name (Fallback)"
                field="project_manager_name"
                placeholder="If PM not in system"
                helpText="Use if project manager is not a system user"
              />
              
              <SelectField
                label="Lead Engineer"
                field="lead_engineer"
                options={users.map(u => ({ value: u.id, label: u.full_name || u.email || u.username }))}
              />
            </div>
          </FieldGroup>

          {/* Scope & Description */}
          <FieldGroup title="Project Scope" icon={DocumentTextIcon}>
            <InputField
              label="Description"
              field="description"
              rows={3}
              placeholder="Brief project overview..."
              helpText="High-level project summary"
            />
            
            <InputField
              label="Scope of Work"
              field="scope_of_work"
              rows={4}
              placeholder="Detailed scope, deliverables, and work breakdown..."
              helpText="Detailed work scope and deliverables"
            />
          </FieldGroup>

          {/* Timeline */}
          <FieldGroup title="Project Timeline" icon={CalendarIcon}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <InputField
                label="Start Date"
                field="start_date"
                type="date"
              />
              
              <InputField
                label="Planned End Date"
                field="planned_end_date"
                type="date"
              />
            </div>
          </FieldGroup>

          {/* Location */}
          <FieldGroup title="Location" icon={MapPinIcon}>
            <InputField
              label="Site Location"
              field="site_location"
              placeholder="e.g., Abu Dhabi Offshore Field"
            />
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <SelectField
                label="Country"
                field="country"
                options={COUNTRIES}
              />
              
              <SelectField
                label="Region"
                field="region"
                options={REGIONS}
              />
            </div>
          </FieldGroup>

          {/* Financial */}
          <FieldGroup title="Financial & Contract" icon={CurrencyDollarIcon}>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <InputField
                label="Contract Value"
                field="contract_value"
                type="number"
                placeholder="0.00"
                helpText="Total contract amount"
              />
              
              <SelectField
                label="Currency"
                field="contract_currency"
                options={CURRENCIES}
              />
            </div>
            
            <InputField
              label="Payment Terms"
              field="payment_terms"
              rows={2}
              placeholder="e.g., Net 30, Milestone-based..."
            />
          </FieldGroup>

          {/* Notes */}
          <FieldGroup title="Additional Notes" icon={DocumentTextIcon}>
            <InputField
              label="Internal Notes"
              field="notes"
              rows={3}
              placeholder="Any additional notes or comments..."
            />
          </FieldGroup>

          {/* Actions */}
          <div className="flex items-center justify-between gap-4 pt-6 border-t border-gray-200">
            <button
              type="button"
              onClick={() => navigate('/procurement/projects')}
              className="px-6 py-3 bg-gray-200 text-gray-700 rounded-lg hover:bg-gray-300 transition-colors font-medium"
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={submitting}
              className="px-8 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-lg hover:from-blue-700 hover:to-indigo-700 transition-all font-medium shadow-lg disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
            >
              {submitting ? (
                <>
                  <div className="animate-spin rounded-full h-5 w-5 border-b-2 border-white"></div>
                  {isEditMode ? 'Updating Project...' : 'Creating Project...'}
                </>
              ) : (
                <>
                  <CheckCircleIcon className="w-5 h-5" />
                  {isEditMode ? 'Update Project' : 'Create Project'}
                </>
              )}
            </button>
          </div>
        </div>
      </form>
    </div>
  );
};

export default ProjectCreator;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import apiClient from '../../services/api.service';
import {
  FolderOpen,
  DollarSign,
  TrendingUp,
  AlertTriangle,
  CheckCircle,
  Clock,
  XCircle,
  Archive,
  FileText,
  BarChart3,
  PieChart,
  Filter,
  Search,
  Plus,
  ExternalLink,
  RefreshCw,
  Download,
  Eye,
  GitMerge
} from 'lucide-react';

// Soft-coded project configuration
const PROJECT_CONFIG = {
  STATUS_COLORS: {
    planning: { bg: 'bg-gray-100', text: 'text-gray-800', icon: Clock },
    active: { bg: 'bg-green-100', text: 'text-green-800', icon: CheckCircle },
    on_hold: { bg: 'bg-yellow-100', text: 'text-yellow-800', icon: Clock },
    completed: { bg: 'bg-blue-100', text: 'text-blue-800', icon: CheckCircle },
    cancelled: { bg: 'bg-red-100', text: 'text-red-800', icon: XCircle },
    archived: { bg: 'bg-gray-100', text: 'text-gray-600', icon: Archive }
  },
  HEALTH_COLORS: {
    green: { bg: 'bg-green-100', text: 'text-green-800', label: 'On Track', barColor: 'bg-green-500' },
    yellow: { bg: 'bg-yellow-100', text: 'text-yellow-800', label: 'At Risk', barColor: 'bg-yellow-500' },
    red: { bg: 'bg-red-100', text: 'text-red-800', label: 'Critical', barColor: 'bg-red-500' }
  },
  BUDGET_THRESHOLDS: {
    warning: 80,
    critical: 95,
    overspend: 100
  }
};

const ProjectDashboard = () => {
  const navigate = useNavigate();
  
  // State management
  const [projects, setProjects] = useState([]);
  const [dashboardStats, setDashboardStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [refreshing, setRefreshing] = useState(false);
  
  // Filter state
  const [filters, setFilters] = useState({
    search: '',
    status: '',
    health_status: '',
    project_type: '',
    active_only: true
  });

  // Fetch dashboard stats
  const fetchDashboardStats = async () => {
    try {
      const response = await apiClient.get('/procurement/projects/dashboard_stats/');
      setDashboardStats(response.data);
    } catch (err) {
      console.error('Error fetching dashboard stats:', err);
    }
  };

  // Fetch projects with filters
  const fetchProjects = async () => {
    try {
      setLoading(true);
      setError(null);
      
      const params = {};
      if (filters.search) params.search = filters.search;
      if (filters.status) params.status = filters.status;
      if (filters.health_status) params.health_status = filters.health_status;
      if (filters.project_type) params.project_type = filters.project_type;
      if (filters.active_only) params.active_only = 'true';
      
      const response = await apiClient.get('/procurement/projects/', { params });
      setProjects(response.data.results || response.data);
    } catch (err) {
      console.error('Error fetching projects:', err);
      setError('Failed to load projects. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Initial load
  useEffect(() => {
    fetchDashboardStats();
    fetchProjects();
  }, []);

  // Refresh on filter change
  useEffect(() => {
    fetchProjects();
  }, [filters]);

  // Manual refresh
  const handleRefresh = async () => {
    setRefreshing(true);
    await Promise.all([fetchDashboardStats(), fetchProjects()]);
    setRefreshing(false);
  };

  // Calculate budget utilization color
  const getBudgetUtilizationColor = (percentage) => {
    if (percentage >= PROJECT_CONFIG.BUDGET_THRESHOLDS.overspend) return 'bg-red-500';
    if (percentage >= PROJECT_CONFIG.BUDGET_THRESHOLDS.critical) return 'bg-orange-500';
    if (percentage >= PROJECT_CONFIG.BUDGET_THRESHOLDS.warning) return 'bg-yellow-500';
    return 'bg-green-500';
  };

  // Format currency
  const formatCurrency = (amount, currency = 'AED') => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency,
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount || 0);
  };

  // KPI Cards Component
  const KPICard = ({ title, value, subtitle, icon: Icon, color, trend }) => (
    <div className="bg-white rounded-lg shadow-md p-6 border-l-4" style={{ borderColor: color }}>
      <div className="flex items-center justify-between">
        <div className="flex-1">
          <p className="text-sm text-gray-600 font-medium">{title}</p>
          <p className="text-3xl font-bold text-gray-900 mt-2">{value}</p>
          {subtitle && <p className="text-sm text-gray-500 mt-1">{subtitle}</p>}
        </div>
        <div className="ml-4">
          <div className="w-14 h-14 rounded-full flex items-center justify-center" style={{ backgroundColor: `${color}20` }}>
            <Icon className="w-7 h-7" style={{ color }} />
          </div>
        </div>
      </div>
      {trend && (
        <div className="mt-4 flex items-center text-sm">
          <TrendingUp className="w-4 h-4 text-green-500 mr-1" />
          <span className="text-green-600 font-medium">{trend}</span>
        </div>
      )}
    </div>
  );

  // Project Card Component
  const ProjectCard = ({ project }) => {
    const statusConfig = PROJECT_CONFIG.STATUS_COLORS[project.status] || PROJECT_CONFIG.STATUS_COLORS.planning;
    const healthConfig = PROJECT_CONFIG.HEALTH_COLORS[project.health_status] || PROJECT_CONFIG.HEALTH_COLORS.green;
    const StatusIcon = statusConfig.icon;
    
    const budgetUtilization = project.budget_utilization || 0;
    const utilizationColor = getBudgetUtilizationColor(budgetUtilization);

    return (
      <div className="bg-white rounded-lg shadow-md hover:shadow-lg transition-shadow border border-gray-200">
        <div className="p-6">
          {/* Header */}
          <div className="flex items-start justify-between mb-4">
            <div className="flex-1">
              <div className="flex items-center gap-2 mb-2">
                <h3 className="text-lg font-bold text-gray-900">{project.project_name}</h3>
                <span className={`px-2 py-1 rounded-full text-xs font-medium ${healthConfig.bg} ${healthConfig.text}`}>
                  {healthConfig.label}
                </span>
              </div>
              <p className="text-sm text-gray-600">
                <span className="font-medium">Project #:</span> {project.project_number}
              </p>
              {project.client_name && (
                <p className="text-sm text-gray-600">
                  <span className="font-medium">Client:</span> {project.client_name}
                </p>
              )}
            </div>
            <span className={`px-3 py-1 rounded-full text-xs font-medium flex items-center gap-1 ${statusConfig.bg} ${statusConfig.text}`}>
              <StatusIcon className="w-3 h-3" />
              {project.status.replace('_', ' ').toUpperCase()}
            </span>
          </div>

          {/* Financial Summary */}
          <div className="grid grid-cols-2 gap-4 mb-4">
            <div>
              <p className="text-xs text-gray-500 mb-1">Contract Value</p>
              <p className="text-lg font-bold text-gray-900">
                {formatCurrency(project.contract_value, project.contract_currency)}
              </p>
            </div>
            <div>
              <p className="text-xs text-gray-500 mb-1">Total Budget</p>
              <p className="text-lg font-bold text-gray-900">
                {formatCurrency(project.total_budget, project.contract_currency)}
              </p>
            </div>
          </div>

          {/* Budget Utilization Bar */}
          <div className="mb-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-medium text-gray-600">Budget Utilization</span>
              <span className={`text-xs font-bold ${budgetUtilization > PROJECT_CONFIG.BUDGET_THRESHOLDS.critical ? 'text-red-600' : 'text-gray-900'}`}>
                {budgetUtilization.toFixed(1)}%
              </span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2.5">
              <div
                className={`h-2.5 rounded-full transition-all ${utilizationColor}`}
                style={{ width: `${Math.min(budgetUtilization, 100)}%` }}
              />
            </div>
            <div className="flex items-center justify-between mt-1 text-xs text-gray-500">
              <span>Spent: {formatCurrency(project.total_spent, project.contract_currency)}</span>
              {budgetUtilization > PROJECT_CONFIG.BUDGET_THRESHOLDS.warning && (
                <span className="flex items-center text-orange-600">
                  <AlertTriangle className="w-3 h-3 mr-1" />
                  Near Limit
                </span>
              )}
            </div>
          </div>

          {/* Progress Bar */}
          <div className="mb-4">
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-medium text-gray-600">Project Progress</span>
              <span className="text-xs font-bold text-gray-900">{project.progress_percentage || 0}%</span>
            </div>
            <div className="w-full bg-gray-200 rounded-full h-2.5">
              <div
                className="bg-blue-500 h-2.5 rounded-full transition-all"
                style={{ width: `${project.progress_percentage || 0}%` }}
              />
            </div>
          </div>

          {/* Action Buttons */}
          <div className="flex items-center gap-2 pt-4 border-t border-gray-200">
            <button
              onClick={() => navigate(`/procurement/projects/${project.id}`)}
              className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center justify-center gap-2 text-sm font-medium"
            >
              <Eye className="w-4 h-4" />
              View Details
            </button>
            <button
              onClick={() => navigate(project.enterprise_project
                ? `/procurement/orders?enterprise_project=${project.enterprise_project}`
                : `/procurement/orders?legacy_project=${project.id}`)}
              className="px-4 py-2 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors flex items-center gap-2 text-sm font-medium"
            >
              <FileText className="w-4 h-4" />
              POs
            </button>
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h1 className="text-3xl font-bold text-gray-900 flex items-center gap-3">
              <FolderOpen className="w-8 h-8 text-blue-600" />
              Project Portfolio Dashboard
            </h1>
            <p className="text-gray-600 mt-2">
              Professional project-based procurement management and financial tracking
            </p>
          </div>
          <div className="flex items-center gap-3">
            <button
              onClick={() => navigate('/procurement/projects/reconciliation')}
              className="px-4 py-2 bg-white border border-teal-300 text-teal-800 rounded-lg hover:bg-teal-50 transition-colors flex items-center gap-2 font-medium"
            >
              <GitMerge className="w-4 h-4" />
              Reconcile Projects
            </button>
            <button
              onClick={() => navigate('/finance/incoming-invoices')}
              className="px-4 py-2 bg-purple-600 text-white rounded-lg hover:bg-purple-700 transition-colors flex items-center gap-2 font-medium"
            >
              <ExternalLink className="w-4 h-4" />
              Invoice Tracker
            </button>
            <button
              onClick={handleRefresh}
              disabled={refreshing}
              className={`px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors flex items-center gap-2 font-medium ${refreshing ? 'opacity-50 cursor-not-allowed' : ''}`}
            >
              <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
              Refresh
            </button>
            <button
              onClick={() => navigate('/procurement/projects/new')}
              className="px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors flex items-center gap-2 font-medium"
            >
              <Plus className="w-4 h-4" />
              New Project
            </button>
          </div>
        </div>
      </div>

      {/* KPI Cards */}
      {dashboardStats && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          <KPICard
            title="Total Projects"
            value={dashboardStats.total_projects || 0}
            subtitle={`${dashboardStats.active_projects || 0} active`}
            icon={FolderOpen}
            color="#3B82F6"
          />
          <KPICard
            title="Active Projects"
            value={dashboardStats.active_projects || 0}
            subtitle={`${dashboardStats.completed_projects || 0} completed`}
            icon={CheckCircle}
            color="#10B981"
          />
          <KPICard
            title="Total Contract Value"
            value={formatCurrency(dashboardStats.total_contract_value)}
            subtitle="All projects"
            icon={DollarSign}
            color="#8B5CF6"
          />
          <KPICard
            title="Health Status"
            value={`${dashboardStats.health_breakdown?.green || 0}`}
            subtitle={`${dashboardStats.health_breakdown?.yellow || 0} at risk, ${dashboardStats.health_breakdown?.red || 0} critical`}
            icon={BarChart3}
            color="#059669"
          />
        </div>
      )}

      {/* Filters */}
      <div className="bg-white rounded-lg shadow-md p-6 mb-8">
        <div className="flex items-center gap-2 mb-4">
          <Filter className="w-5 h-5 text-gray-600" />
          <h2 className="text-lg font-bold text-gray-900">Filters</h2>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4">
          {/* Search */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search projects..."
              value={filters.search}
              onChange={(e) => setFilters({ ...filters, search: e.target.value })}
              className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            />
          </div>

          {/* Status Filter */}
          <select
            value={filters.status}
            onChange={(e) => setFilters({ ...filters, status: e.target.value })}
            className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="">All Statuses</option>
            <option value="planning">Planning</option>
            <option value="active">Active</option>
            <option value="on_hold">On Hold</option>
            <option value="completed">Completed</option>
            <option value="cancelled">Cancelled</option>
            <option value="archived">Archived</option>
          </select>

          {/* Health Filter */}
          <select
            value={filters.health_status}
            onChange={(e) => setFilters({ ...filters, health_status: e.target.value })}
            className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="">All Health Status</option>
            <option value="green">On Track</option>
            <option value="yellow">At Risk</option>
            <option value="red">Critical</option>
          </select>

          {/* Project Type Filter */}
          <select
            value={filters.project_type}
            onChange={(e) => setFilters({ ...filters, project_type: e.target.value })}
            className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
          >
            <option value="">All Types</option>
            <option value="engineering">Engineering Services</option>
            <option value="construction">Construction</option>
            <option value="pmc">PMC</option>
            <option value="feed">FEED</option>
            <option value="detailed_design">Detailed Design</option>
            <option value="commissioning">Commissioning</option>
          </select>

          {/* Active Only Toggle */}
          <label className="flex items-center gap-2 px-4 py-2 border border-gray-300 rounded-lg cursor-pointer hover:bg-gray-50">
            <input
              type="checkbox"
              checked={filters.active_only}
              onChange={(e) => setFilters({ ...filters, active_only: e.target.checked })}
              className="w-4 h-4 text-blue-600 rounded focus:ring-2 focus:ring-blue-500"
            />
            <span className="text-sm font-medium text-gray-700">Active Only</span>
          </label>
        </div>
      </div>

      {/* Projects Grid */}
      {loading ? (
        <div className="flex items-center justify-center py-20">
          <RefreshCw className="w-8 h-8 text-blue-600 animate-spin" />
          <span className="ml-3 text-gray-600 font-medium">Loading projects...</span>
        </div>
      ) : error ? (
        <div className="bg-red-50 border border-red-200 rounded-lg p-6 text-center">
          <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-3" />
          <p className="text-red-700 font-medium">{error}</p>
          <button
            onClick={fetchProjects}
            className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
          >
            Try Again
          </button>
        </div>
      ) : projects.length === 0 ? (
        <div className="bg-white rounded-lg shadow-md p-12 text-center">
          <FolderOpen className="w-16 h-16 text-gray-300 mx-auto mb-4" />
          <h3 className="text-lg font-medium text-gray-900 mb-2">No Projects Found</h3>
          <p className="text-gray-600 mb-6">
            {filters.search || filters.status || filters.health_status || filters.project_type
              ? 'Try adjusting your filters'
              : 'Get started by creating your first project'}
          </p>
          <button
            onClick={() => navigate('/procurement/projects/new')}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors inline-flex items-center gap-2 font-medium"
          >
            <Plus className="w-5 h-5" />
            Create First Project
          </button>
        </div>
      ) : (
        <>
          <div className="flex items-center justify-between mb-4">
            <h2 className="text-lg font-bold text-gray-900">
              {projects.length} Project{projects.length !== 1 ? 's' : ''}
            </h2>
            <button
              onClick={() => {/* TODO: Export functionality */}}
              className="px-4 py-2 bg-white border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors flex items-center gap-2 text-sm font-medium"
            >
              <Download className="w-4 h-4" />
              Export
            </button>
          </div>
          <div className="grid grid-cols-1 lg:grid-cols-2 xl:grid-cols-3 gap-6">
            {projects.map((project) => (
              <ProjectCard key={project.id} project={project} />
            ))}
          </div>
        </>
      )}
    </div>
  );
};

export default ProjectDashboard;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import apiClient from '../../services/api.service';
import {
  ArrowLeft,
  DollarSign,
  TrendingUp,
  AlertTriangle,
  CheckCircle,
  Clock,
  FileText,
  Users,
  Calendar,
  MapPin,
  Briefcase,
  PieChart,
  BarChart3,
  Receipt,
  Package,
  RefreshCw,
  Edit,
  ExternalLink
} from 'lucide-react';

const numberOrZero = (value) => {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : 0;
};

const normalizeFinancialSummary = (data = {}) => {
  const budgets = data.budget_stats || data.budgets || {};
  const purchaseOrders = data.po_stats || data.purchase_orders || {};

  return {
    budget_stats: {
      total_budget: numberOrZero(budgets.total_budget ?? budgets.total_allocated),
      approved_budgets: numberOrZero(budgets.approved_budgets ?? budgets.approved_budget_lines),
      total_spent: numberOrZero(budgets.total_spent),
      remaining_budget: numberOrZero(budgets.remaining_budget ?? budgets.remaining),
      budget_utilization: numberOrZero(budgets.budget_utilization ?? budgets.utilization_percentage),
    },
    po_stats: {
      total_pos: numberOrZero(purchaseOrders.total_pos ?? purchaseOrders.count),
    },
  };
};

const EMPTY_FINANCIAL_SUMMARY = normalizeFinancialSummary();

const ProjectDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();

  const [project, setProject] = useState(null);
  const [financialSummary, setFinancialSummary] = useState(EMPTY_FINANCIAL_SUMMARY);
  const [purchaseOrders, setPurchaseOrders] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [activeTab, setActiveTab] = useState('overview');

  // Fetch project details
  const fetchProjectDetail = async () => {
    try {
      setLoading(true);
      const response = await apiClient.get(`/procurement/projects/${id}/`);
      setProject(response.data);
    } catch (err) {
      console.error('Error fetching project:', err);
      setError('Failed to load project details');
    } finally {
      setLoading(false);
    }
  };

  // Fetch financial summary
  const fetchFinancialSummary = async () => {
    try {
      const response = await apiClient.get(`/procurement/projects/${id}/financial_summary/`);
      setFinancialSummary(normalizeFinancialSummary(response.data));
    } catch (err) {
      console.error('Error fetching financial summary:', err);
      setFinancialSummary(EMPTY_FINANCIAL_SUMMARY);
    }
  };

  // Fetch purchase orders
  const fetchPurchaseOrders = async () => {
    try {
      const response = await apiClient.get(`/procurement/projects/${id}/purchase_orders/`);
      const responseData = response.data?.results || response.data;
      setPurchaseOrders(Array.isArray(responseData) ? responseData : []);
    } catch (err) {
      console.error('Error fetching purchase orders:', err);
    }
  };

  useEffect(() => {
    if (id) {
      fetchProjectDetail();
      fetchFinancialSummary();
      fetchPurchaseOrders();
    }
  }, [id]);

  // Format currency
  const formatCurrency = (amount, currency = 'AED') => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency,
      minimumFractionDigits: 0,
      maximumFractionDigits: 0
    }).format(amount || 0);
  };

  // Format date
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    return new Date(dateString).toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric'
    });
  };

  // Stat Card Component
  const StatCard = ({ title, value, subtitle, icon: Icon, color, trend }) => (
    <div className="bg-white rounded-lg shadow-md p-6 border-l-4" style={{ borderColor: color }}>
      <div className="flex items-start justify-between">
        <div className="flex-1">
          <div className="flex items-center gap-2 mb-2">
            <Icon className="w-5 h-5" style={{ color }} />
            <p className="text-sm text-gray-600 font-medium">{title}</p>
          </div>
          <p className="text-2xl font-bold text-gray-900">{value}</p>
          {subtitle && <p className="text-sm text-gray-500 mt-1">{subtitle}</p>}
        </div>
      </div>
      {trend && (
        <div className="mt-3 flex items-center text-xs">
          <span className={trend > 0 ? 'text-red-600' : 'text-green-600'}>
            {trend > 0 ? '↑' : '↓'} {Math.abs(trend)}% vs budget
          </span>
        </div>
      )}
    </div>
  );

  // Budget Category Card
  const BudgetCategoryCard = ({ budget }) => {
    const utilization = numberOrZero(budget.utilization_percentage);
    const isOverBudget = budget.is_over_budget;
    const barColor = isOverBudget ? 'bg-red-500' : utilization > 80 ? 'bg-yellow-500' : 'bg-green-500';

    return (
      <div className="bg-white rounded-lg border border-gray-200 p-4 hover:shadow-md transition-shadow">
        <div className="flex items-center justify-between mb-3">
          <div>
            <h4 className="font-medium text-gray-900">{(budget.category || 'Uncategorized').replaceAll('_', ' ').toUpperCase()}</h4>
            {budget.sub_category && (
              <p className="text-xs text-gray-500 mt-1">{budget.sub_category}</p>
            )}
          </div>
          {isOverBudget && (
            <span className="px-2 py-1 bg-red-100 text-red-800 rounded-full text-xs font-medium">
              Over Budget
            </span>
          )}
        </div>
        
        <div className="space-y-2 mb-3">
          <div className="flex justify-between text-sm">
            <span className="text-gray-600">Allocated:</span>
            <span className="font-semibold text-gray-900">
              {formatCurrency(budget.allocated_amount, budget.currency)}
            </span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-gray-600">Spent:</span>
            <span className={`font-semibold ${isOverBudget ? 'text-red-600' : 'text-gray-900'}`}>
              {formatCurrency(budget.spent_amount, budget.currency)}
            </span>
          </div>
          <div className="flex justify-between text-sm">
            <span className="text-gray-600">Remaining:</span>
            <span className={`font-semibold ${budget.remaining_amount < 0 ? 'text-red-600' : 'text-green-600'}`}>
              {formatCurrency(budget.remaining_amount, budget.currency)}
            </span>
          </div>
        </div>

        <div className="mb-2">
          <div className="flex items-center justify-between mb-1">
            <span className="text-xs text-gray-500">Utilization</span>
            <span className={`text-xs font-bold ${isOverBudget ? 'text-red-600' : 'text-gray-900'}`}>
              {utilization.toFixed(1)}%
            </span>
          </div>
          <div className="w-full bg-gray-200 rounded-full h-2">
            <div
              className={`h-2 rounded-full transition-all ${barColor}`}
              style={{ width: `${Math.min(utilization, 100)}%` }}
            />
          </div>
        </div>

        {budget.is_approved ? (
          <div className="flex items-center gap-1 text-xs text-green-600 mt-2">
            <CheckCircle className="w-3 h-3" />
            <span>Approved</span>
          </div>
        ) : (
          <div className="flex items-center gap-1 text-xs text-yellow-600 mt-2">
            <Clock className="w-3 h-3" />
            <span>Pending Approval</span>
          </div>
        )}
      </div>
    );
  };

  // Purchase Order Row
  const PurchaseOrderRow = ({ po }) => (
    <tr className="hover:bg-gray-50 cursor-pointer" onClick={() => navigate(`/procurement/orders/${po.id}`)}>
      <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-blue-600">
        {po.po_number}
      </td>
      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
        {po.vendor_name || 'N/A'}
      </td>
      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
        {formatCurrency(po.total_value, po.currency)}
      </td>
      <td className="px-6 py-4 whitespace-nowrap text-sm">
        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
          po.status === 'approved' ? 'bg-green-100 text-green-800' :
          po.status === 'pending' ? 'bg-yellow-100 text-yellow-800' :
          po.status === 'draft' ? 'bg-gray-100 text-gray-800' :
          'bg-red-100 text-red-800'
        }`}>
          {(po.status || 'unknown').toUpperCase()}
        </span>
      </td>
      <td className="px-6 py-4 whitespace-nowrap text-sm">
        <span className={`px-2 py-1 rounded-full text-xs font-medium ${
          po.invoice_status === 'fully_invoiced' ? 'bg-green-100 text-green-800' :
          po.invoice_status === 'partially_invoiced' ? 'bg-blue-100 text-blue-800' :
          po.invoice_status === 'over_invoiced' ? 'bg-red-100 text-red-800' :
          'bg-gray-100 text-gray-800'
        }`}>
          {(po.invoice_status || 'not_invoiced').replace('_', ' ').toUpperCase()}
        </span>
      </td>
      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
        {formatDate(po.created_at)}
      </td>
    </tr>
  );

  if (loading) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <RefreshCw className="w-8 h-8 text-blue-600 animate-spin" />
        <span className="ml-3 text-gray-600 font-medium">Loading project...</span>
      </div>
    );
  }

  if (error || !project) {
    return (
      <div className="min-h-screen bg-gray-50 flex items-center justify-center">
        <div className="bg-white rounded-lg shadow-md p-8 max-w-md text-center">
          <AlertTriangle className="w-12 h-12 text-red-500 mx-auto mb-4" />
          <h2 className="text-xl font-bold text-gray-900 mb-2">Error Loading Project</h2>
          <p className="text-gray-600 mb-6">{error || 'Project not found'}</p>
          <button
            onClick={() => navigate('/procurement/projects')}
            className="px-6 py-3 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            Back to Projects
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-50">
      {/* Header */}
      <div className="bg-white border-b border-gray-200">
        <div className="max-w-7xl mx-auto px-6 py-6">
          <div className="flex items-center justify-between mb-4">
            <button
              onClick={() => navigate('/procurement/projects')}
              className="flex items-center gap-2 text-gray-600 hover:text-gray-900 transition-colors"
            >
              <ArrowLeft className="w-5 h-5" />
              <span className="font-medium">Back to Projects</span>
            </button>
            <div className="flex items-center gap-3">
              <button
                onClick={() => navigate(`/procurement/projects/${id}/edit`)}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors flex items-center gap-2 font-medium"
              >
                <Edit className="w-4 h-4" />
                Edit Project
              </button>
            </div>
          </div>

          <div className="flex items-start justify-between">
            <div className="flex-1">
              <h1 className="text-3xl font-bold text-gray-900 mb-2">{project.project_name}</h1>
              <div className="flex items-center gap-4 text-sm text-gray-600">
                <span className="flex items-center gap-1">
                  <Briefcase className="w-4 h-4" />
                  {project.project_number}
                </span>
                {project.client_name && (
                  <span className="flex items-center gap-1">
                    <Users className="w-4 h-4" />
                    {project.client_name}
                  </span>
                )}
                {project.site_location && (
                  <span className="flex items-center gap-1">
                    <MapPin className="w-4 h-4" />
                    {project.site_location}
                  </span>
                )}
              </div>
            </div>
