                    </div>
                    <div className="flex justify-between text-sm text-gray-500">
                      <span>Discount (line items only)</span>
                      <span>{formData.currency} {(formData.items || []).reduce((sum, item) => sum + Number(item.discount || 0), 0).toFixed(2)}</span>
