  TrashIcon,
  UserGroupIcon,
  XMarkIcon,
} from '@heroicons/react/24/outline';
import apiClient from '../../services/api.service';
import AIVendorCreator from './AIVendorCreator';
import SupplierEditModal from './SupplierEditModal';
import { readVendorDraft } from '../../services/vendorDraft';

const cx = (...classes) => classes.filter(Boolean).join(' ');
const DAY = 86400000;
const REQUIRED_FIELDS = [
  ['vendor_code', 'Vendor code'], ['name', 'Legal name'], ['contact_person', 'Primary contact'],
  ['email', 'Email'], ['phone', 'Phone'], ['address', 'Address'], ['country', 'Country'],
  ['trade_license_number', 'Trade license'], ['vat_number', 'VAT number'], ['categories', 'Category'],
  ['certifications', 'Certifications'],
];
const hasValue = (value) => Array.isArray(value) ? value.length > 0 : value !== null && value !== undefined && String(value).trim() !== '';
const completeness = (supplier) => {
  const missing = REQUIRED_FIELDS.filter(([key]) => !hasValue(supplier?.[key]));
  return { score: Math.round(((REQUIRED_FIELDS.length - missing.length) / REQUIRED_FIELDS.length) * 100), missing };
};
const daysUntil = (date) => date ? Math.ceil((new Date(date).setHours(23, 59, 59, 999) - Date.now()) / DAY) : null;
const normalize = (value) => String(value || '').toLowerCase().replace(/[^a-z0-9]/g, '');
const initials = (name) => String(name || 'S').split(/\s+/).slice(0, 2).map((word) => word[0]).join('').toUpperCase();
const formatDate = (value, fallback = 'Not recorded') => {
  if (!value) return fallback;
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? fallback : date.toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' });
};
const relativeDate = (value) => {
  if (!value) return 'Not recorded';
  const days = Math.max(0, Math.floor((Date.now() - new Date(value).getTime()) / DAY));
  if (days === 0) return 'Today';
  if (days === 1) return '1 day ago';
  return days < 30 ? days + ' days ago' : formatDate(value);
};

const COUNTRY_CODES = {
  'united arab emirates': 'AE', uae: 'AE', ae: 'AE',
  'saudi arabia': 'SA', ksa: 'SA', sa: 'SA', qatar: 'QA', qa: 'QA', oman: 'OM', om: 'OM',
  bahrain: 'BH', bh: 'BH', kuwait: 'KW', kw: 'KW', india: 'IN', in: 'IN',
  germany: 'DE', de: 'DE', france: 'FR', fr: 'FR', italy: 'IT', it: 'IT', spain: 'ES', es: 'ES',
  'united kingdom': 'GB', uk: 'GB', gb: 'GB', england: 'GB',
  'united states': 'US', usa: 'US', us: 'US', canada: 'CA', ca: 'CA',
  china: 'CN', cn: 'CN', japan: 'JP', jp: 'JP', singapore: 'SG', sg: 'SG',
  netherlands: 'NL', nl: 'NL', belgium: 'BE', be: 'BE', sweden: 'SE', se: 'SE',
  norway: 'NO', no: 'NO', finland: 'FI', fi: 'FI', denmark: 'DK', dk: 'DK',
  australia: 'AU', au: 'AU', switzerland: 'CH', ch: 'CH', austria: 'AT', at: 'AT',
};
const countryCode = (country) => {
  const source = String(country || '').trim().toLowerCase();
  return COUNTRY_CODES[source] || COUNTRY_CODES[normalize(source)] || '';
};
const countryFlag = (country) => {
  const code = countryCode(country);
  return code ? String.fromCodePoint(...code.split('').map((character) => 127397 + character.charCodeAt())) : '';
};
const countryName = (country) => {
  const source = String(country || '').trim();
  const code = countryCode(source);
  if (!code) return source;
  if (code === 'AE') return 'UAE';
  try {
    return new Intl.DisplayNames(['en'], { type: 'region' }).of(code) || source;
  } catch {
    return source;
  }
};

const CountryFlag = ({ country }) => {
  const code = countryCode(country);
  if (code === 'AE') {
    return (
      <svg className="h-3.5 w-5 shrink-0 overflow-hidden rounded-[2px] ring-1 ring-slate-300" viewBox="0 0 28 20" role="img" aria-label="United Arab Emirates flag">
        <rect width="28" height="20" fill="#fff" />
        <rect x="0" y="0" width="8" height="20" fill="#ff0000" />
        <rect x="8" y="0" width="20" height="6.667" fill="#00732f" />
        <rect x="8" y="13.333" width="20" height="6.667" fill="#000" />
      </svg>
    );
  }
  if (code) return <span className="country-flag shrink-0 text-sm" aria-hidden="true">{countryFlag(country)}</span>;
  return <GlobeAltIcon className="h-3.5 w-3.5 shrink-0 text-slate-400" aria-hidden="true" />;
};

const SupplierAvatar = ({ supplier, large = false }) => {
  const source = supplier.logo_url || supplier.logo || '';
  return (
    <span className={cx(
      'relative grid shrink-0 place-items-center overflow-hidden border border-slate-200 bg-slate-100 font-semibold text-slate-600',
      large ? 'h-12 w-12 rounded-xl text-sm' : 'h-7 w-7 rounded-md text-[9px]'
    )}>
      <span aria-hidden="true">{initials(supplier.name)}</span>
      {source && <img src={source} alt="" className="absolute inset-0 h-full w-full bg-white object-contain p-0.5" onError={(event) => { event.currentTarget.style.display = 'none'; }} />}
    </span>
  );
};

const governance = (supplier) => {
  const readiness = completeness(supplier);
  const expiryDays = daysUntil(supplier?.icv_expiry_date);
  const expired = expiryDays !== null && expiryDays < 0;
  const expiring = expiryDays !== null && expiryDays >= 0 && expiryDays <= 90;
  const conditions = [];
  if (!supplier?.trade_license_number) conditions.push('Trade license missing');
  if (!supplier?.vat_number) conditions.push('VAT registration missing');
  if (supplier?.is_icv_certified && expired) conditions.push('ICV certificate expired');
  if (!supplier?.is_icv_certified) conditions.push('ICV verification missing');
  if (!supplier?.adnoc_approved) conditions.push('ADNOC approval not recorded');
  let eligibility = 'eligible';
  if (supplier?.status !== 'active' || expired) eligibility = 'not_eligible';
  else if (conditions.length) eligibility = 'conditional';
  const risk = supplier?.status === 'blacklisted' || expired ? 'high'
    : supplier?.status !== 'active' || readiness.score < 60 || conditions.length >= 3 ? 'medium' : 'low';
  return { readiness, expiryDays, expired, expiring, conditions, eligibility, risk };
};

const ToneBadge = ({ tone = 'slate', children }) => {
  const tones = {
    emerald: 'border-emerald-200 bg-emerald-50 text-emerald-700',
    amber: 'border-amber-200 bg-amber-50 text-amber-700',
    red: 'border-red-200 bg-red-50 text-red-700',
    blue: 'border-blue-200 bg-blue-50 text-blue-700',
    slate: 'border-slate-200 bg-slate-50 text-slate-600',
  };
  return <span className={cx('status-badge inline-flex items-center gap-1 rounded-full border px-2 py-0.5', tones[tone])}>{children}</span>;
};

const EligibilityBadge = ({ value, compact = false }) => value === 'eligible'
  ? <ToneBadge tone="emerald"><CheckCircleIcon className="h-3 w-3" />Eligible</ToneBadge>
  : value === 'conditional'
    ? <ToneBadge tone="amber"><ExclamationTriangleIcon className="h-3 w-3" />{compact ? 'Conditional' : 'Eligible with conditions'}</ToneBadge>
    : <ToneBadge tone="red"><XMarkIcon className="h-3 w-3" />{compact ? 'Blocked' : 'Not eligible'}</ToneBadge>;

const Kpi = ({ label, value, icon: Icon, tone, active, onClick }) => (
  <button type="button" onClick={onClick} aria-pressed={active} className={cx('flex min-h-16 items-center gap-2.5 rounded-lg border bg-white px-3 py-2 text-left shadow-sm transition hover:border-blue-300 hover:shadow-md focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-blue-500', active ? 'border-blue-400 ring-1 ring-blue-100' : 'border-slate-200')}>
    <span className={cx('grid h-8 w-8 shrink-0 place-items-center rounded-md', tone)}><Icon className="h-4 w-4" /></span>
    <span><span className="metric-label block">{label}</span><span className="metric-value mt-0.5 block text-slate-950">{value}</span></span>
  </button>
);

ToneBadge.propTypes = {
  tone: PropTypes.oneOf(['emerald', 'amber', 'red', 'blue', 'slate']),
  children: PropTypes.node.isRequired,
};

EligibilityBadge.propTypes = {
  value: PropTypes.oneOf(['eligible', 'conditional', 'not_eligible']).isRequired,
  compact: PropTypes.bool,
};

Kpi.propTypes = {
  label: PropTypes.string.isRequired,
  value: PropTypes.oneOfType([PropTypes.string, PropTypes.number]).isRequired,
  icon: PropTypes.elementType.isRequired,
  tone: PropTypes.string.isRequired,
  active: PropTypes.bool.isRequired,
  onClick: PropTypes.func.isRequired,
};

CountryFlag.propTypes = {
  country: PropTypes.string,
};

SupplierAvatar.propTypes = {
  supplier: PropTypes.shape({
    name: PropTypes.string.isRequired,
    logo: PropTypes.string,
    logo_url: PropTypes.string,
  }).isRequired,
  large: PropTypes.bool,
};

const SupplierManagementWorkspace = () => {
  const [suppliers, setSuppliers] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [search, setSearch] = useState('');
  const [filters, setFilters] = useState({ eligibility: 'all', compliance: 'all', category: 'all', country: 'all', readiness: 'all', risk: 'all' });
  const [activeView, setActiveView] = useState('suppliers');
  const [selected, setSelected] = useState(null);
  const [profileTab, setProfileTab] = useState('overview');
  const [checked, setChecked] = useState([]);
  const [page, setPage] = useState(1);
  const [creator, setCreator] = useState(() => {
    const draft = readVendorDraft();
    return { open: Boolean(draft && !draft.editMode), edit: false, supplier: null };
  });
  const [enrichment, setEnrichment] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);
  const [actionBusy, setActionBusy] = useState(false);

  const fetchSuppliers = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const response = await apiClient.get('/procurement/vendors/', { params: { page_size: 10000 } });
      const rows = Array.isArray(response.data) ? response.data : response.data?.results || [];
      setSuppliers(rows);
      setSelected((current) => current ? rows.find((item) => item.id === current.id) || null : null);
    } catch (requestError) {
      setError(requestError.response?.data?.detail || requestError.message || 'Vendor directory could not be loaded.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => { fetchSuppliers(); }, [fetchSuppliers]);

  useEffect(() => {
    const requestedId = new URLSearchParams(window.location.search).get('vendor');
    if (!requestedId || !suppliers.length || selected) return;
    const requestedSupplier = suppliers.find((supplier) => String(supplier.id) === requestedId);
    if (requestedSupplier) {
      setSelected(requestedSupplier);
      setProfileTab('overview');
    }
  }, [selected, suppliers]);

  const duplicateIds = useMemo(() => {
    const groups = new Map();
    suppliers.forEach((supplier) => {
      [
        ['name', normalize(supplier.name)],
        ['email', normalize(supplier.email)],
        ['license', normalize(supplier.trade_license_number)],
        ['vat', normalize(supplier.vat_number)],
      ].filter(([, value]) => value).forEach(([type, value]) => {
        const key = type + ':' + value;
        groups.set(key, [...(groups.get(key) || []), supplier.id]);
      });
    });
    return new Set([...groups.values()].filter((ids) => ids.length > 1).flat());
  }, [suppliers]);

  const metrics = useMemo(() => {
    const enriched = suppliers.map((supplier) => governance(supplier));
    return {
      total: suppliers.length,
      eligible: enriched.filter((item) => item.eligibility === 'eligible').length,
      review: enriched.filter((item) => item.eligibility !== 'eligible' || item.readiness.score < 75).length,
      expiring: enriched.filter((item) => item.expiring).length,
      completeness: enriched.length ? Math.round(enriched.reduce((sum, item) => sum + item.readiness.score, 0) / enriched.length) : 0,
      highRisk: enriched.filter((item) => item.risk === 'high').length,
    };
  }, [suppliers]);

  const categories = useMemo(() => [...new Set(suppliers.flatMap((supplier) => supplier.categories || []))].sort(), [suppliers]);
  const countries = useMemo(() => [...new Set(suppliers.map((supplier) => supplier.country).filter(Boolean))].sort(), [suppliers]);
  const displayed = useMemo(() => suppliers.filter((supplier) => {
    const state = governance(supplier);
    const haystack = [supplier.name, supplier.vendor_code, supplier.email, supplier.country, supplier.contact_person, ...(supplier.categories || [])].join(' ').toLowerCase();
    if (search && !haystack.includes(search.toLowerCase())) return false;
    if (activeView === 'compliance' && !state.conditions.length) return false;
    if (activeView === 'duplicates' && !duplicateIds.has(supplier.id)) return false;
    if (filters.eligibility !== 'all' && state.eligibility !== filters.eligibility) return false;
    if (filters.compliance === 'expiring' && !state.expiring) return false;
    if (filters.compliance === 'expired' && !state.expired) return false;
    if (filters.compliance === 'missing' && !state.conditions.length) return false;
    if (filters.category !== 'all' && !(supplier.categories || []).includes(filters.category)) return false;
    if (filters.country !== 'all' && supplier.country !== filters.country) return false;
    if (filters.readiness === 'complete' && state.readiness.score < 85) return false;
    if (filters.readiness === 'incomplete' && state.readiness.score >= 85) return false;
    if (filters.risk !== 'all' && state.risk !== filters.risk) return false;
    return true;
  }), [activeView, duplicateIds, filters, search, suppliers]);

  const pageSize = 10;
  const pageCount = Math.max(1, Math.ceil(displayed.length / pageSize));
  const currentPage = Math.min(page, pageCount);
  const pagedSuppliers = displayed.slice((currentPage - 1) * pageSize, currentPage * pageSize);

  useEffect(() => { setPage(1); }, [activeView, filters, search]);

  const exportSuppliers = () => {
    const header = ['Vendor code', 'Legal name', 'Country', 'Contact', 'Email', 'Completeness', 'Eligibility', 'Risk'];
    const rows = displayed.map((supplier) => {
      const state = governance(supplier);
      return [supplier.vendor_code, supplier.name, supplier.country, supplier.contact_person, supplier.email, state.readiness.score + '%', state.eligibility, state.risk];
    });
    const csv = [header, ...rows].map((row) => row.map((cell) => '"' + String(cell || '').replaceAll('"', '""') + '"').join(',')).join('\n');
    const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = 'Vendor_Directory_' + new Date().toISOString().slice(0, 10) + '.csv';
    link.click();
    URL.revokeObjectURL(url);
  };

  const deleteSupplier = async () => {
    if (!confirmDelete) return;
    setActionBusy(true);
    try {
      await apiClient.delete('/procurement/vendors/' + confirmDelete.id + '/');
      setConfirmDelete(null);
      await fetchSuppliers();
    } catch (requestError) {
      setError(requestError.response?.data?.detail || 'Vendor could not be deleted.');
    } finally {
      setActionBusy(false);
    }
  };

  const selectedState = selected ? governance(selected) : null;
  const viewTabs = [
    ['suppliers', 'Vendors', metrics.total],
    ['compliance', 'Compliance reviews', metrics.review],
    ['duplicates', 'Duplicates', duplicateIds.size],
    ['categories', 'Categories', categories.length],
  ];

  return (
    <div className="supplier-workspace min-h-0 bg-slate-50 text-slate-900">
      <div className="supplier-workspace-content w-full px-3 py-3 sm:px-4">
        <header className="flex flex-col gap-3 border-b border-slate-200 pb-3 lg:flex-row lg:items-center lg:justify-between">
          <h1 className="page-title text-slate-950">Vendor management</h1>
          <div className="flex flex-wrap items-center gap-2">
            <button type="button" onClick={fetchSuppliers} className="inline-flex h-10 items-center gap-2 rounded-lg border border-slate-300 bg-white px-3 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-50"><ArrowPathIcon className={cx('h-4 w-4', loading && 'animate-spin')} />Refresh</button>
            <button type="button" onClick={exportSuppliers} className="inline-flex h-10 items-center gap-2 rounded-lg border border-slate-300 bg-white px-3 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-50"><ArrowDownTrayIcon className="h-4 w-4" />Export</button>
            <button type="button" onClick={() => setEnrichment(selected || true)} className="inline-flex h-10 items-center gap-2 rounded-lg border border-slate-300 bg-white px-3 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-50"><SparklesIcon className="h-4 w-4" />Review enrichment</button>
            <button type="button" onClick={() => setCreator({ open: true, edit: false, supplier: null })} className="inline-flex h-10 items-center gap-2 rounded-lg bg-red-600 px-4 text-sm font-semibold text-white shadow-sm hover:bg-red-700"><PlusIcon className="h-4 w-4" />Add vendor</button>
          </div>
        </header>

        <nav className="supplier-view-tabs flex gap-5 overflow-x-auto border-b border-slate-200" aria-label="Vendor workspace views">
          {viewTabs.map(([key, label, count]) => <button key={key} type="button" onClick={() => setActiveView(key)} className={cx('flex h-10 shrink-0 items-center gap-1.5 border-b-2 px-1 text-xs font-semibold', activeView === key ? 'border-blue-600 text-blue-700' : 'border-transparent text-slate-500 hover:text-slate-800')}>{label}<span className="rounded-full bg-slate-100 px-1.5 py-0.5 text-[10px] text-slate-600">{count}</span></button>)}
        </nav>

        <section className="mt-2.5 grid gap-2.5 sm:grid-cols-2 lg:grid-cols-3 2xl:grid-cols-6" aria-label="Vendor governance metrics">
          <Kpi label="Total vendors" value={metrics.total} icon={UserGroupIcon} tone="bg-blue-50 text-blue-600" active={activeView === 'suppliers'} onClick={() => setActiveView('suppliers')} />
          <Kpi label="Eligible for procurement" value={metrics.eligible} icon={CheckCircleIcon} tone="bg-emerald-50 text-emerald-600" active={filters.eligibility === 'eligible'} onClick={() => setFilters((value) => ({ ...value, eligibility: value.eligibility === 'eligible' ? 'all' : 'eligible' }))} />
          <Kpi label="Needs review" value={metrics.review} icon={ExclamationTriangleIcon} tone="bg-amber-50 text-amber-600" active={activeView === 'compliance'} onClick={() => setActiveView('compliance')} />
          <Kpi label="Compliance expiring" value={metrics.expiring} icon={ClockIcon} tone="bg-red-50 text-red-600" active={filters.compliance === 'expiring'} onClick={() => setFilters((value) => ({ ...value, compliance: value.compliance === 'expiring' ? 'all' : 'expiring' }))} />
          <Kpi label="Data completeness (avg)" value={metrics.completeness + '%'} icon={DocumentCheckIcon} tone="bg-sky-50 text-sky-600" active={false} onClick={() => setFilters((value) => ({ ...value, readiness: 'incomplete' }))} />
          <Kpi label="High-risk vendors" value={metrics.highRisk} icon={ShieldCheckIcon} tone="bg-rose-50 text-rose-600" active={filters.risk === 'high'} onClick={() => setFilters((value) => ({ ...value, risk: value.risk === 'high' ? 'all' : 'high' }))} />
        </section>

        {error && <div className="mt-3 flex items-center justify-between rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-800"><span>{error}</span><button type="button" onClick={() => setError('')} aria-label="Dismiss error"><XMarkIcon className="h-5 w-5" /></button></div>}

        <div className="supplier-workspace-directory mt-2.5 grid gap-2.5">
          <section className="min-w-0 overflow-hidden rounded-lg border border-slate-300 bg-white shadow-sm" aria-labelledby="directory-heading">
            <div className="border-b border-slate-300 px-3 py-2.5">
              <div className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between">
                <div><h2 id="directory-heading" className="section-title">Vendor directory ({displayed.length})</h2><p className="metadata">Verified master data and explainable eligibility.</p></div>
                <div className="relative w-full lg:max-w-xl"><MagnifyingGlassIcon className="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-slate-400" /><input value={search} onChange={(event) => setSearch(event.target.value)} className="supplier-search h-9 w-full rounded-lg border border-slate-300 bg-slate-50 pl-9 pr-3 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100" placeholder="Search vendor, code, email, country, category or contact…" /></div>
              </div>
              <div className="mt-2 flex gap-1.5 overflow-x-auto pb-0.5">
                {[
                  ['eligibility', [['all', 'Eligibility'], ['eligible', 'Eligible'], ['conditional', 'Conditional'], ['not_eligible', 'Not eligible']]],
                  ['compliance', [['all', 'Compliance'], ['expiring', 'Expiring'], ['expired', 'Expired'], ['missing', 'Missing data']]],
                  ['category', [['all', 'Category'], ...categories.map((value) => [value, value])]],
                  ['country', [['all', 'Country'], ...countries.map((value) => [value, value])]],
                  ['readiness', [['all', 'Data readiness'], ['complete', 'Complete 85%+'], ['incomplete', 'Incomplete']]],
                  ['risk', [['all', 'Risk'], ['low', 'Low risk'], ['medium', 'Medium risk'], ['high', 'High risk']]],
                ].map(([key, options]) => <label key={key} className="relative shrink-0"><span className="sr-only">{key}</span><select value={filters[key]} onChange={(event) => setFilters((value) => ({ ...value, [key]: event.target.value }))} className="h-7 appearance-none rounded-md border border-slate-300 bg-white pl-2.5 pr-6 text-[11px] font-medium text-slate-600 outline-none focus:border-blue-500">{options.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select><ChevronDownIcon className="pointer-events-none absolute right-1.5 top-1.5 h-3.5 w-3.5 text-slate-400" /></label>)}
                <button type="button" onClick={() => { setFilters({ eligibility: 'all', compliance: 'all', category: 'all', country: 'all', readiness: 'all', risk: 'all' }); setSearch(''); setActiveView('suppliers'); }} className="h-8 shrink-0 rounded-lg px-3 text-[11px] font-semibold text-blue-700 hover:bg-blue-50">Clear filters</button>
              </div>
            </div>

            <div className="supplier-directory-scroll overflow-auto">
              <table className="supplier-directory-table w-full text-left">
                <thead className="table-header"><tr className="supplier-directory-grid">
                  <th className="supplier-selection-column px-2 text-center"><input type="checkbox" aria-label="Select all vendors on this page" checked={pagedSuppliers.length > 0 && pagedSuppliers.every((item) => checked.includes(item.id))} onChange={(event) => setChecked((items) => event.target.checked ? [...new Set([...items, ...pagedSuppliers.map((item) => item.id)])] : items.filter((id) => !pagedSuppliers.some((item) => item.id === id)))} /></th>
                  <th className="supplier-name-column px-2">Vendor</th><th className="px-2">Code</th><th className="px-2">Category</th><th className="px-2">Country</th><th className="numeric px-2">Data completeness</th><th className="px-2">Compliance</th><th className="px-2">Performance</th><th className="px-2">Eligibility</th><th className="px-2">Updated</th>
                </tr></thead>
                <tbody className="table-cell">
                  {loading ? <tr className="supplier-directory-grid supplier-grid-state"><td className="h-56 text-center text-slate-500"><ArrowPathIcon className="mx-auto h-6 w-6 animate-spin" /><p className="mt-2">Loading vendor governance data…</p></td></tr>
                    : displayed.length === 0 ? <tr className="supplier-directory-grid supplier-grid-state"><td className="h-56 text-center text-slate-500"><FunnelIcon className="mx-auto h-7 w-7" /><p className="mt-2 font-semibold">No vendors match this view</p><button type="button" onClick={() => { setSearch(''); setActiveView('suppliers'); }} className="mt-2 text-blue-700 underline">Reset view</button></td></tr>
                    : pagedSuppliers.map((supplier) => {
                      const state = governance(supplier);
                      const isSelected = selected?.id === supplier.id;
                      const readinessTone = state.readiness.score >= 85 ? 'bg-emerald-500' : state.readiness.score >= 65 ? 'bg-amber-500' : 'bg-red-500';
                      const complianceItems = [
                        supplier.trade_license_number ? 'Trade license ✓' : 'Trade license missing',
                        supplier.vat_number ? 'VAT ✓' : 'VAT missing',
                        supplier.is_icv_certified ? 'ICV ✓' : 'ICV missing',
                      ];
                      return <tr key={supplier.id} onClick={() => { setSelected(supplier); setProfileTab('overview'); }} className={cx('supplier-directory-grid cursor-pointer', isSelected && 'supplier-row-selected')}>
                        <td className="supplier-selection-column px-2 text-center" onClick={(event) => event.stopPropagation()}><input type="checkbox" aria-label={'Select ' + supplier.name} checked={checked.includes(supplier.id)} onChange={(event) => setChecked((items) => event.target.checked ? [...items, supplier.id] : items.filter((id) => id !== supplier.id))} /></td>
                        <td className="supplier-name-column min-w-0 px-2"><div className="flex min-w-0 items-center gap-2"><SupplierAvatar supplier={supplier} /><p className="truncate font-semibold text-slate-900" title={supplier.name}>{supplier.name}</p></div></td>
                        <td className="truncate px-2 text-slate-600" title={supplier.vendor_code}>{supplier.vendor_code}</td>
                        <td className="truncate px-2 text-slate-600" title={supplier.categories?.join(', ') || 'Unclassified'}>{supplier.categories?.[0] || 'Unclassified'}</td>
                        <td className="min-w-0 px-2 text-slate-600"><span className="flex items-center gap-1.5"><CountryFlag country={supplier.country} /><span className="truncate" title={countryName(supplier.country) || 'Country missing'}>{countryName(supplier.country) || '—'}</span></span></td>
                        <td className="numeric px-2"><div className="flex items-center justify-end gap-2"><span className="font-semibold tabular-nums">{state.readiness.score}%</span><span className="h-1.5 w-14 overflow-hidden rounded-full bg-slate-200" role="progressbar" aria-label={supplier.name + ' data completeness'} aria-valuenow={state.readiness.score} aria-valuemin="0" aria-valuemax="100"><span className={cx('block h-full rounded-full', readinessTone)} style={{ width: state.readiness.score + '%' }} /></span></div></td>
                        <td className="px-2"><div className="flex flex-wrap gap-1">{complianceItems.slice(0, 2).map((item) => <ToneBadge key={item} tone={item.includes('missing') ? 'red' : 'emerald'}>{item}</ToneBadge>)}</div></td>
                        <td className="px-2"><ToneBadge tone={supplier.rating >= 4 ? 'emerald' : supplier.rating === 3 ? 'slate' : supplier.rating ? 'amber' : 'slate'}>{supplier.rating_display || (supplier.rating ? supplier.rating + '/5' : 'Unrated')}</ToneBadge></td>
                        <td className="px-2"><EligibilityBadge value={state.eligibility} compact /></td>
                        <td className="px-2 text-slate-500"><span className="tabular-nums">{relativeDate(supplier.updated_at)}</span></td>
                      </tr>;
                    })}
                </tbody>
              </table>
            </div>
            <div className="supplier-directory-footer flex flex-wrap items-center justify-between gap-3 border-t border-slate-200 px-4 py-3 text-slate-500">
              <span>{displayed.length ? 'Showing ' + ((currentPage - 1) * pageSize + 1) + '–' + Math.min(currentPage * pageSize, displayed.length) + ' of ' + displayed.length : 'No vendors'}{checked.length ? ' · ' + checked.length + ' selected' : ''}</span>
              <div className="flex items-center gap-2"><span>10 rows per page</span><button type="button" onClick={() => setPage((value) => Math.max(1, value - 1))} disabled={currentPage === 1} aria-label="Previous vendor page" className="grid h-8 w-8 place-items-center rounded-lg border border-slate-300 bg-white disabled:opacity-40"><ArrowLeftIcon className="h-4 w-4" /></button><span className="min-w-14 text-center font-semibold text-slate-700">{currentPage} / {pageCount}</span><button type="button" onClick={() => setPage((value) => Math.min(pageCount, value + 1))} disabled={currentPage === pageCount} aria-label="Next vendor page" className="grid h-8 w-8 place-items-center rounded-lg border border-slate-300 bg-white disabled:opacity-40"><ArrowRightIcon className="h-4 w-4" /></button></div>
            </div>
          </section>

          <aside className="supplier-profile-panel overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm xl:sticky xl:top-4 xl:self-start" aria-label="Contextual vendor profile">
            {!selected ? <div className="supplier-profile-empty grid min-h-[240px] place-items-center p-8 text-center text-slate-500"><div><BuildingOffice2Icon className="mx-auto h-9 w-9" /><p className="mt-3 text-sm font-semibold">Select a vendor</p><p className="mt-1 text-xs">Review identity, evidence and procurement eligibility.</p></div></div> : <>
              <div className="border-b border-slate-200 p-4">
                <div className="flex items-start justify-between gap-3"><div className="flex min-w-0 items-center gap-3"><SupplierAvatar supplier={selected} large /><div className="min-w-0"><h2 className="truncate text-sm font-bold">{selected.name}</h2><div className="mt-1 flex flex-wrap gap-1.5"><ToneBadge tone={selected.status === 'active' ? 'emerald' : selected.status === 'blacklisted' ? 'red' : 'amber'}>{selected.status_display || selected.status}</ToneBadge><EligibilityBadge value={selectedState.eligibility} /></div></div></div><button type="button" onClick={() => setSelected(null)} className="rounded-lg p-1.5 text-slate-400 hover:bg-slate-100" aria-label="Close vendor profile"><XMarkIcon className="h-5 w-5" /></button></div>
                <p className="mt-3 text-[10px] font-semibold uppercase tracking-wide text-slate-400">{selected.vendor_code}</p>
              </div>
              <div className="flex overflow-x-auto border-b border-slate-200 px-2">{['overview', 'compliance', 'contacts', 'performance', 'activity'].map((tab) => <button key={tab} type="button" onClick={() => setProfileTab(tab)} className={cx('h-10 shrink-0 border-b-2 px-2.5 text-[10px] font-semibold capitalize', profileTab === tab ? 'border-blue-600 text-blue-700' : 'border-transparent text-slate-500')}>{tab}</button>)}</div>
              <div className="max-h-[680px] overflow-y-auto p-4">
                {profileTab === 'overview' && <div className="space-y-3">
                  <section><h3 className="text-xs font-bold">Basic information</h3><dl className="mt-3 grid grid-cols-[110px_1fr] gap-x-3 gap-y-2 text-[11px]"><dt className="text-slate-500">Legal name</dt><dd className="font-medium">{selected.name}</dd><dt className="text-slate-500">Vendor code</dt><dd>{selected.vendor_code}</dd><dt className="text-slate-500">Country</dt><dd>{selected.country || 'Not recorded'}</dd><dt className="text-slate-500">Category</dt><dd>{selected.categories?.join(', ') || 'Unclassified'}</dd><dt className="text-slate-500">Primary contact</dt><dd>{selected.contact_person || 'Not recorded'}</dd><dt className="text-slate-500">Owner</dt><dd>{selected.created_by_name || 'Procurement master data'}</dd><dt className="text-slate-500">Last reviewed</dt><dd>{formatDate(selected.updated_at)}</dd></dl></section>
                  <div className="supplier-governance-summary grid gap-3 sm:grid-cols-2 xl:grid-cols-1 2xl:grid-cols-2">
                    <section className="rounded-lg border border-slate-200 p-3"><div className="flex items-center justify-between"><h3 className="text-[11px] font-bold">Data readiness</h3><strong className="text-xs">{selectedState.readiness.score}%</strong></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-blue-600" style={{ width: selectedState.readiness.score + '%' }} /></div><div className="mt-3 space-y-1.5">{selectedState.readiness.missing.slice(0, 4).map(([, label]) => <p key={label} className="flex items-center gap-1.5 text-[10px] text-red-600"><XMarkIcon className="h-3 w-3" />{label} missing</p>)}{!selectedState.readiness.missing.length && <p className="text-[10px] text-emerald-700">All tracked fields complete</p>}</div></section>
                    <section className="rounded-lg border border-slate-200 p-3"><h3 className="text-[11px] font-bold">Procurement eligibility</h3><div className="mt-2"><EligibilityBadge value={selectedState.eligibility} /></div><p className="mt-2 text-[10px] leading-4 text-slate-500">{selectedState.eligibility === 'eligible' ? 'No blocking governance conditions detected.' : selectedState.conditions[0] || 'Vendor status prevents purchasing.'}</p><p className="mt-2 text-[10px]"><strong>Risk:</strong> <span className="capitalize">{selectedState.risk}</span></p></section>
                  </div>
                </div>}
                {profileTab === 'compliance' && <div className="space-y-3">
                  <section className="rounded-lg border border-slate-200 p-3"><h3 className="flex items-center gap-2 text-xs font-bold"><IdentificationIcon className="h-4 w-4 text-blue-600" />ICV verification evidence</h3><dl className="mt-3 grid grid-cols-2 gap-3 text-[10px]"><div><dt className="text-slate-500">Status</dt><dd className="mt-1 font-semibold">{selected.is_icv_certified ? 'Verified' : 'Not verified'}</dd></div><div><dt className="text-slate-500">ICV value</dt><dd className="mt-1 font-semibold">{selected.icv_percentage ? selected.icv_percentage + '%' : 'Not recorded'}</dd></div><div><dt className="text-slate-500">Certificate</dt><dd className="mt-1 font-semibold">{selected.icv_certificate || 'Missing'}</dd></div><div><dt className="text-slate-500">Expiry</dt><dd className="mt-1 font-semibold">{formatDate(selected.icv_expiry_date, 'Missing')}</dd></div><div className="col-span-2"><dt className="text-slate-500">Issuing authority</dt><dd className="mt-1 font-semibold">{selected.icv_issuing_authority || 'Not recorded'}</dd></div></dl></section>
                  <section className="rounded-lg border border-slate-200 p-3"><h3 className="flex items-center gap-2 text-xs font-bold"><ShieldCheckIcon className="h-4 w-4 text-blue-600" />ADNOC verification</h3><p className="mt-2 text-[11px]">{selected.adnoc_approved ? 'Approved in vendor master' : 'Approval evidence not recorded'}</p><p className="mt-1 text-[10px] text-slate-500">{selected.attachments?.length ? selected.attachments.length + ' vendor attachments available for human review.' : 'No supporting attachment is linked.'}</p></section>
                  <section className="rounded-lg border border-amber-200 bg-amber-50 p-3"><h3 className="flex items-center gap-2 text-xs font-bold text-amber-900"><LockClosedIcon className="h-4 w-4" />Bank verification · Restricted</h3><p className="mt-2 text-[10px] leading-4 text-amber-800">Bank-account information is not exposed in this workspace. Finance authorization and an auditable verification workflow are required.</p></section>
                </div>}
                {profileTab === 'contacts' && <dl className="space-y-3 text-[11px]"><div><dt className="text-slate-500">Primary contact</dt><dd className="mt-1 font-semibold">{selected.contact_person || 'Not recorded'}</dd></div><div><dt className="text-slate-500">Email</dt><dd className="mt-1 break-all">{selected.email ? <a className="text-blue-700 underline underline-offset-2" href={'mailto:' + selected.email}>{selected.email}</a> : 'Not recorded'}</dd></div><div><dt className="text-slate-500">Phone</dt><dd className="mt-1">{selected.phone || 'Not recorded'}</dd></div><div><dt className="text-slate-500">Address</dt><dd className="mt-1">{selected.address || 'Not recorded'}</dd></div></dl>}
                {profileTab === 'performance' && <div className="space-y-3 text-[11px]"><section className="rounded-lg border border-slate-200 p-3"><p className="text-slate-500">Current rating</p><p className="mt-1 text-lg font-bold">{selected.rating ? selected.rating + ' / 5' : 'Not rated'}</p><p className="mt-2 leading-5 text-slate-600">{selected.performance_notes || 'No reviewed performance notes are recorded.'}</p></section><section className="rounded-lg border border-slate-200 p-3"><p className="text-slate-500">HSE audit</p><p className="mt-1 font-semibold">{selected.audit_status || 'Not recorded'}</p><p className="mt-1 text-slate-500">Last audit: {formatDate(selected.last_audit_date)}</p></section></div>}
                {profileTab === 'activity' && <div className="space-y-4"><h3 className="text-xs font-bold">Vendor audit history</h3>{[{ label: 'Vendor record updated', at: selected.updated_at, by: 'Master data workflow' }, { label: 'Vendor record created', at: selected.created_at, by: selected.created_by_name || 'Procurement user' }].filter((item) => item.at).map((item) => <div key={item.label} className="flex gap-3"><span className="mt-1 h-2 w-2 shrink-0 rounded-full bg-blue-600" /><div><p className="text-[11px] font-semibold">{item.label}</p><p className="text-[10px] text-slate-500">{formatDate(item.at)} · {item.by}</p></div></div>)}<p className="rounded-lg bg-slate-50 p-3 text-[10px] leading-4 text-slate-500">This history contains every vendor-master event exposed by the current API. Field-level change logging requires the governed audit-ledger service.</p></div>}
              </div>
              <div className="grid grid-cols-3 gap-2 border-t border-slate-200 p-3">
                <button type="button" onClick={() => setCreator({ open: true, edit: true, supplier: selected })} className="inline-flex h-9 items-center justify-center gap-1 rounded-lg bg-blue-600 text-[11px] font-semibold text-white hover:bg-blue-700"><PencilSquareIcon className="h-4 w-4" />Edit</button>
                <button type="button" onClick={() => setEnrichment(selected)} className="inline-flex h-9 items-center justify-center gap-1 rounded-lg border border-slate-300 text-[11px] font-semibold hover:bg-slate-50"><SparklesIcon className="h-4 w-4" />Enrich</button>
                <button type="button" onClick={() => setConfirmDelete(selected)} className="inline-flex h-9 items-center justify-center gap-1 rounded-lg border border-red-200 text-[11px] font-semibold text-red-700 hover:bg-red-50"><TrashIcon className="h-4 w-4" />Delete</button>
              </div>
            </>}
          </aside>
        </div>

      </div>

      {enrichment && <><button type="button" className="fixed inset-0 z-[70] bg-slate-950/35" aria-label="Close enrichment review" onClick={() => setEnrichment(null)} /><aside className="fixed inset-y-0 right-0 z-[80] flex w-full max-w-lg flex-col bg-white shadow-2xl" role="dialog" aria-modal="true" aria-labelledby="enrichment-title"><div className="border-b border-slate-200 p-5"><div className="flex items-start justify-between"><div><p className="text-[10px] font-bold uppercase tracking-widest text-blue-600">Human review required</p><h2 id="enrichment-title" className="mt-1 text-lg font-bold">Data-enrichment suggestions</h2><p className="mt-1 text-xs text-slate-500">No vendor data is changed automatically.</p></div><button type="button" onClick={() => setEnrichment(null)}><XMarkIcon className="h-5 w-5 text-slate-400" /></button></div></div><div className="flex-1 overflow-y-auto bg-slate-50 p-5">{(enrichment === true ? suppliers.filter((item) => completeness(item).score < 85) : [enrichment]).map((supplier) => <button key={supplier.id} type="button" onClick={() => setEnrichment(supplier)} className="mb-3 w-full rounded-xl border border-slate-200 bg-white p-4 text-left shadow-sm"><div className="flex justify-between gap-3"><div><p className="text-sm font-bold">{supplier.name}</p><p className="mt-1 text-[10px] text-slate-500">{completeness(supplier).missing.length} missing tracked fields</p></div><strong className="text-sm text-amber-600">{completeness(supplier).score}%</strong></div>{enrichment !== true && <div className="mt-3 space-y-2">{completeness(supplier).missing.map(([, label]) => <div key={label} className="flex items-center justify-between rounded-lg bg-slate-50 px-3 py-2 text-[10px]"><span>{label}</span><span className="text-slate-400">Awaiting verified evidence</span></div>)}</div>}</button>)}</div><div className="border-t border-slate-200 p-4"><button type="button" disabled className="h-10 w-full rounded-lg bg-slate-200 text-xs font-semibold text-slate-500">Apply reviewed suggestions</button><p className="mt-2 text-center text-[9px] text-slate-400">Enabled only when a trusted source and reviewer decision are recorded.</p></div></aside></>}

      {confirmDelete && <div className="fixed inset-0 z-[90] grid place-items-center bg-slate-950/40 p-4" role="dialog" aria-modal="true"><div className="w-full max-w-md rounded-xl bg-white p-5 shadow-2xl"><h2 className="text-base font-bold">Delete vendor?</h2><p className="mt-2 text-sm text-slate-600">This permanently deletes <strong>{confirmDelete.name}</strong>. Existing procurement references may prevent deletion.</p><div className="mt-5 flex justify-end gap-2"><button type="button" disabled={actionBusy} onClick={() => setConfirmDelete(null)} className="h-9 rounded-lg border border-slate-300 px-4 text-xs font-semibold">Cancel</button><button type="button" disabled={actionBusy} onClick={deleteSupplier} className="h-9 rounded-lg bg-red-600 px-4 text-xs font-semibold text-white">{actionBusy ? 'Deleting…' : 'Delete vendor'}</button></div></div></div>}

      {creator.open && creator.edit && creator.supplier
        ? <SupplierEditModal supplier={creator.supplier} onClose={() => setCreator({ open: false, edit: false, supplier: null })} onSaved={async (updated) => { setSelected(updated); await fetchSuppliers(); }} />
        : <AIVendorCreator isOpen={creator.open} onClose={() => setCreator({ open: false, edit: false, supplier: null })} onVendorCreated={async () => { setCreator({ open: false, edit: false, supplier: null }); await fetchSuppliers(); }} editMode={false} vendorData={null} />}
    </div>
  );
};

export default SupplierManagementWorkspace;

import React, { useState, useEffect, useCallback } from 'react';
import {
  UserGroupIcon,
  PlusIcon,
  MagnifyingGlassIcon,
  FunnelIcon,
  CheckCircleIcon,
  XCircleIcon,
  ClockIcon,
  ShieldCheckIcon,
  BuildingOfficeIcon,
  PhoneIcon,
  EnvelopeIcon,
  GlobeAltIcon,
  SparklesIcon,
  ArrowPathIcon,
  TableCellsIcon,
  Squares2X2Icon,
  ArrowDownIcon,
  ArrowUpIcon,
  DocumentArrowDownIcon,
  PencilSquareIcon,
  TrashIcon,
  ExclamationTriangleIcon,
  PowerIcon,
  EyeIcon,
  XMarkIcon,
  MapPinIcon,
  IdentificationIcon,
  ChevronRightIcon
} from '@heroicons/react/24/outline';
import apiClient from '../../services/api.service';
import { PageControlButtons } from '../../components/Common/PageControlButtons';
import { usePageControls } from '../../hooks/usePageControls';
import { PROCUREMENT_CONFIG, getVendorRating } from '../../config/procurement.config';
import AIVendorCreator from './AIVendorCreator';
import { readVendorDraft, clearVendorDraft } from '../../services/vendorDraft';

// Soft-coded layout configuration
const LAYOUT_CONFIG = {
  cardGridCols: {
    sm: 'sm:grid-cols-2',
    lg: 'lg:grid-cols-3',
    xl: 'xl:grid-cols-4'
  }
};

const COMPLETENESS_FIELDS = [
  { key: 'vendor_code', label: 'Vendor code', group: 'Identity' },
  { key: 'name', label: 'Legal name', group: 'Identity' },
  { key: 'contact_person', label: 'Contact person', group: 'Contact' },
  { key: 'email', label: 'Email', group: 'Contact' },
  { key: 'phone', label: 'Phone', group: 'Contact' },
  { key: 'address', label: 'Address', group: 'Location' },
  { key: 'country', label: 'Country', group: 'Location' },
  { key: 'trade_license_number', label: 'Trade license', group: 'Compliance' },
  { key: 'vat_number', label: 'VAT number', group: 'Compliance' },
  { key: 'categories', label: 'Categories', group: 'Qualification' },
  { key: 'certifications', label: 'Certifications', group: 'Qualification' },
];

const hasVendorValue = (value) => (
  Array.isArray(value) ? value.length > 0 : value !== null && value !== undefined && String(value).trim() !== ''
);

const getVendorCompleteness = (vendor = {}) => {
  const missing = COMPLETENESS_FIELDS.filter(({ key }) => !hasVendorValue(vendor[key]));
  return {
    score: Math.round(((COMPLETENESS_FIELDS.length - missing.length) / COMPLETENESS_FIELDS.length) * 100),
    missing,
  };
};

const isVendorAttentionRequired = (vendor) => {
  const { score } = getVendorCompleteness(vendor);
  const icvExpired = vendor?.icv_expiry_date && new Date(vendor.icv_expiry_date) < new Date();
  return score < 75 || vendor?.status === 'pending' || Boolean(icvExpired);
};

const VendorManagement = () => {
  const [vendors, setVendors] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterRating, setFilterRating] = useState('all');
  const [filterCompleteness, setFilterCompleteness] = useState('all');
  const [activeKpi, setActiveKpi] = useState('total');
  const [recoveredDraft] = useState(readVendorDraft);
  const [showAICreator, setShowAICreator] = useState(() => Boolean(recoveredDraft));
  const [editMode, setEditMode] = useState(() => recoveredDraft?.editMode || false);
  const [selectedVendor, setSelectedVendor] = useState(() => recoveredDraft?.vendorData || null);
  const [detailVendor, setDetailVendor] = useState(null);
  const [enrichmentVendor, setEnrichmentVendor] = useState(undefined);
  const [viewMode, setViewMode] = useState('table'); // 'table' or 'cards'
  const [sortConfig, setSortConfig] = useState({ key: 'name', direction: 'asc' });
  
  // Confirmation modal states
  const [showConfirmModal, setShowConfirmModal] = useState(false);
  const [confirmAction, setConfirmAction] = useState(null);
  const [actionLoading, setActionLoading] = useState(false);

  const pageControls = usePageControls({
    autoRefreshInterval: 60000,
    enableAutoRefresh: !showAICreator,
    features: { autoRefresh: true, fullscreen: true, sidebar: true }
  });

  const fetchVendors = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);

      // Fetch all vendors with large page_size to avoid pagination issues
      // Soft-coded: Use query parameter to get all records
      const response = await apiClient.get('/procurement/vendors/', {
        params: {
          page_size: 1000  // Large enough to get all vendors in one request
        }
      });
      const data = response.data;
      
      // Soft-coded data normalization - ensure array
      let normalizedData = [];
      if (Array.isArray(data)) {
        normalizedData = data;
      } else if (data && Array.isArray(data.results)) {
        normalizedData = data.results;
      } else if (data && typeof data === 'object') {
        normalizedData = [data];
      }
      
      setVendors(normalizedData);
      
      // Log for debugging
      console.log(`✅ Loaded ${normalizedData.length} vendors from API`);
      
    } catch (error) {
      console.error('Error fetching vendors:', error);
      setError({ 
        type: 'network', 
        message: `Failed to load vendors: ${error.message}`,
        action: () => fetchVendors()
      });
      setVendors([]); // Ensure array even on error
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!showAICreator) fetchVendors();
  }, [fetchVendors, pageControls.isRefreshing, showAICreator]);

  // Soft-coded filter logic with safe array handling
  const filteredVendors = Array.isArray(vendors) ? vendors.filter(vendor => {
    // Soft-coded field access with fallbacks
    const name = vendor?.name || '';
    const vendorCode = vendor?.vendor_code || '';
    const status = vendor?.status || '';
    const rating = vendor?.rating || 0;
    const country = vendor?.country || '';
    const email = vendor?.email || '';
    const categories = Array.isArray(vendor?.categories) ? vendor.categories.join(' ') : '';
    const completeness = getVendorCompleteness(vendor).score;
    
    const matchesSearch = name.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         vendorCode.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         country.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         email.toLowerCase().includes(searchTerm.toLowerCase()) ||
                         categories.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = filterStatus === 'all' || status === filterStatus;
    const matchesRating = filterRating === 'all' || rating === parseInt(filterRating);
    const matchesCompleteness = filterCompleteness === 'all'
      || (filterCompleteness === 'complete' && completeness >= 85)
      || (filterCompleteness === 'incomplete' && completeness < 85)
      || (filterCompleteness === 'attention' && isVendorAttentionRequired(vendor));
    return matchesSearch && matchesStatus && matchesRating && matchesCompleteness;
  }) : [];

  const getStatusConfig = (status) => {
    return PROCUREMENT_CONFIG.statuses.vendor[status] || { label: status, color: 'gray', icon: ClockIcon };
  };

  const getStatusBadge = (status) => {
    const config = getStatusConfig(status);
    const colorClasses = {
      green: 'bg-green-100 text-green-800 border-green-200',
      red: 'bg-red-100 text-red-800 border-red-200',
      yellow: 'bg-yellow-100 text-yellow-800 border-yellow-200',
      gray: 'bg-gray-100 text-gray-800 border-gray-200'
    };
    return (
      <span className={`inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium border ${colorClasses[config.color]}`}>
        {config.label}
      </span>
    );
  };

  const getRatingStars = (rating) => {
    if (!rating || rating === 0) return <span className="text-gray-400 text-xs">No rating</span>;
    const config = getVendorRating(rating);
    return (
      <div className="flex items-center space-x-1">
        <span className="text-sm">{config.icon}</span>
        <span className={`text-xs font-medium text-${config.color}-600`}>{config.label}</span>
      </div>
    );
  };

  const handleVendorCreated = async () => {
    // After successful creation, refresh vendor list
    await fetchVendors();
    setShowAICreator(false);
    setEditMode(false);
    setSelectedVendor(null);
  };

  const handleVendorUpdated = async () => {
    // After successful update, refresh vendor list
    await fetchVendors();
    setShowAICreator(false);
    setEditMode(false);
    setSelectedVendor(null);
  };

  const handleEditVendor = (vendor) => {
    setSelectedVendor(vendor);
    setEditMode(true);
    setShowAICreator(true);
  };

  /**
   * Handle vendor deletion with confirmation
   */
  const handleDeleteVendor = (vendor) => {
    setConfirmAction({
      type: 'delete',
      vendor: vendor,
      title: 'Delete Vendor',
      message: `Are you sure you want to delete "${vendor.name}"? This action cannot be undone.`,
      confirmLabel: 'Delete',
      confirmStyle: 'danger',
      onConfirm: async () => {
        try {
          setActionLoading(true);
          await apiClient.delete(`/procurement/vendors/${vendor.id}/`);
          console.log(`✅ Vendor ${vendor.vendor_code} deleted successfully`);
          await fetchVendors(); // Refresh the list
          setShowConfirmModal(false);
          setConfirmAction(null);
        } catch (error) {
          console.error('Error deleting vendor:', error);
          setError({
            type: 'network',
            message: `Failed to delete vendor: ${error.response?.data?.detail || error.message}`,
            action: () => handleDeleteVendor(vendor)
          });
        } finally {
          setActionLoading(false);
        }
      }
    });
    setShowConfirmModal(true);
  };

  /**
   * Handle vendor status toggle (activate/deactivate)
   */
  const handleToggleStatus = (vendor) => {
    const newStatus = vendor.status === 'active' ? 'inactive' : 'active';
    const actionLabel = newStatus === 'active' ? 'Activate' : 'Deactivate';
    
    setConfirmAction({
      type: 'toggle',
      vendor: vendor,
      newStatus: newStatus,
      title: `${actionLabel} Vendor`,
      message: `Are you sure you want to ${actionLabel.toLowerCase()} "${vendor.name}"?`,
      confirmLabel: actionLabel,
      confirmStyle: newStatus === 'active' ? 'success' : 'warning',
      onConfirm: async () => {
        try {
          setActionLoading(true);
          await apiClient.patch(`/procurement/vendors/${vendor.id}/`, {
            status: newStatus
          });
          console.log(`✅ Vendor ${vendor.vendor_code} status updated to ${newStatus}`);
          await fetchVendors(); // Refresh the list
          setShowConfirmModal(false);
          setConfirmAction(null);
        } catch (error) {
          console.error('Error updating vendor status:', error);
          setError({
            type: 'network',
            message: `Failed to update vendor status: ${error.response?.data?.detail || error.message}`,
            action: () => handleToggleStatus(vendor)
          });
        } finally {
          setActionLoading(false);
        }
      }
    });
    setShowConfirmModal(true);
  };

  /**
   * Soft-coded sorting function
   */
  const handleSort = (key) => {
    let direction = 'asc';
    if (sortConfig.key === key && sortConfig.direction === 'asc') {
      direction = 'desc';
    }
    setSortConfig({ key, direction });
  };

  /**
   * Soft-coded export to Excel function
   */
  const handleExportToExcel = () => {
    const headers = ['Vendor Code', 'Vendor Name', 'Category', 'Contact Person', 'Contact Number', 'Email', 'Location', 'ICV', 'ADNOC', 'Tenure (yrs)', 'Trade License', 'VAT Number'];
    const rows = filteredVendors.map(v => [
      v.vendor_code,
      v.name,
      Array.isArray(v.categories) ? v.categories.join(', ') : '',
      v.contact_person || '',
      v.phone || '',
      v.email || '',
      v.address || '',
      v.is_icv_certified ? 'Y' : 'N',
      v.adnoc_approved ? 'Y' : 'N',
      v.vendor_tenure_years || '',
      v.trade_license_number || '',
      v.vat_number || ''
    ]);
    
    const csvContent = [headers, ...rows].map(e => e.join('\t')).join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `Vendors_Export_${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  };

  const applyKpiFilter = (key) => {
    setActiveKpi(key);
    setSearchTerm('');
    setFilterRating('all');
    setFilterStatus(key === 'active' ? 'active' : 'all');
    setFilterCompleteness(
      key === 'attention' ? 'attention' : key === 'complete' ? 'complete' : 'all'
    );
  };

  const VendorStats = () => {
    const safeVendors = Array.isArray(vendors) ? vendors : [];
    const completenessScores = safeVendors.map(vendor => getVendorCompleteness(vendor).score);
    const stats = {
      total: safeVendors.length,
      active: safeVendors.filter(vendor => vendor?.status === 'active').length,
      attention: safeVendors.filter(isVendorAttentionRequired).length,
      complete: completenessScores.filter(score => score >= 85).length,
      average: completenessScores.length
        ? Math.round(completenessScores.reduce((sum, score) => sum + score, 0) / completenessScores.length)
        : 0,
    };
    const cards = [
      {
        key: 'total', label: 'Total Vendors', value: stats.total,
        message: 'Complete supplier master directory', icon: UserGroupIcon,
        iconClass: 'bg-slate-900', accentClass: 'border-[#00a896]',
      },
      {
        key: 'active', label: 'Active Vendors', value: stats.active,
        message: `${stats.active} approved for procurement`, icon: CheckCircleIcon,
        iconClass: 'bg-[#00a896]', accentClass: 'border-[#00a896]',
      },
      {
        key: 'attention', label: 'Needs Attention', value: stats.attention,
        message: 'Missing data, pending review, or expired ICV', icon: ExclamationTriangleIcon,
        iconClass: 'bg-amber-500', accentClass: 'border-amber-400',
      },
      {
        key: 'complete', label: 'Data Complete', value: stats.complete,
        message: `${stats.average}% average completeness`, icon: ShieldCheckIcon,
        iconClass: 'bg-[#73bdc8]', accentClass: 'border-[#73bdc8]',
      },
    ];

    return (
      <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        {cards.map((card) => {
          const Icon = card.icon;
          const selected = activeKpi === card.key;
          return (
            <button
              key={card.key}
              type="button"
              onClick={() => applyKpiFilter(card.key)}
              aria-pressed={selected}
              className={`group rounded-2xl border bg-white p-5 text-left shadow-sm transition-all hover:-translate-y-0.5 hover:shadow-lg focus:outline-none focus:ring-4 focus:ring-[#00a896]/20 ${
                selected ? `${card.accentClass} ring-2 ring-[#00a896]/20` : 'border-slate-200'
              }`}
            >
              <div className="flex items-start justify-between gap-4">
                <div>
                  <p className="text-sm font-semibold text-slate-600">{card.label}</p>
                  <p className="mt-2 text-3xl font-bold tracking-tight text-slate-950">{card.value}</p>
                </div>
                <span className={`rounded-xl p-3 shadow-sm ${card.iconClass}`}>
                  <Icon className="h-6 w-6 text-white" />
                </span>
              </div>
              <div className="mt-4 flex items-center justify-between border-t border-slate-100 pt-3">
                <p className="text-xs leading-5 text-slate-500">{card.message}</p>
                <ChevronRightIcon className="h-4 w-4 flex-none text-slate-300 transition-transform group-hover:translate-x-0.5 group-hover:text-[#00a896]" />
              </div>
            </button>
          );
        })}
      </div>
    );
  };

  const enrichmentTargets = enrichmentVendor === undefined
    ? []
    : enrichmentVendor
      ? [enrichmentVendor]
      : vendors.filter(vendor => getVendorCompleteness(vendor).score < 85);
  const enrichmentMissingFields = enrichmentVendor
    ? getVendorCompleteness(enrichmentVendor).missing
    : [];

  const enrichmentSourceFor = (field) => {
    if (field.group === 'Compliance') return 'Trade license / VAT document';
    if (field.group === 'Qualification') return 'Company profile / certificate';
    if (field.group === 'Contact' || field.group === 'Location') return 'Verified website / company profile';
    return 'Vendor master evidence';
  };

  return (
    <div className="min-h-screen bg-gray-50" style={pageControls.styles.container}>
      <div className="py-6" style={pageControls.styles.content}>
        {/* RADAI vendor workspace header and primary actions */}
        <div className="w-full px-3 sm:px-4">
          <div className="overflow-hidden rounded-3xl bg-gradient-to-r from-slate-950 via-slate-900 to-blue-950 shadow-xl">
            <div className="relative px-6 py-7 lg:px-8">
              <div className="absolute -right-16 -top-20 h-52 w-52 rounded-full bg-[#00a896]/20 blur-3xl" />
              <div className="absolute bottom-0 left-1/3 h-24 w-56 rounded-full bg-[#73bdc8]/10 blur-3xl" />
              <div className="relative flex flex-col gap-6 xl:flex-row xl:items-center xl:justify-between">
                <div>
                  <div className="flex items-center gap-3">
                    <span className="rounded-2xl bg-[#00a896] p-3 shadow-lg shadow-[#00a896]/20">
                      <UserGroupIcon className="h-7 w-7 text-white" />
                    </span>
                    <div>
                      <p className="text-xs font-semibold uppercase tracking-[0.22em] text-[#73bdc8]">RADAI Procurement</p>
                      <h1 className="mt-1 text-3xl font-bold tracking-tight text-white">Vendor Management</h1>
                    </div>
                  </div>
                  <p className="mt-4 max-w-2xl text-sm leading-6 text-slate-300">
                    Manage supplier identity, contacts, compliance, qualifications, and data readiness from one controlled workspace.
                  </p>
                </div>

                <div className="flex flex-col gap-3 sm:flex-row sm:flex-wrap sm:items-center xl:justify-end">
                  {/* <div className="rounded-xl bg-white/95 p-1 shadow-sm">
                    <PageControlButtons
                      isFullscreen={pageControls.isFullscreen}
                      toggleFullscreen={pageControls.toggleFullscreen}
                      sidebarVisible={pageControls.sidebarVisible}
                      toggleSidebar={pageControls.toggleSidebar}
                      autoRefreshEnabled={pageControls.autoRefreshEnabled}
                      toggleAutoRefresh={pageControls.toggleAutoRefresh}
                      isRefreshing={pageControls.isRefreshing}
                      manualRefresh={pageControls.manualRefresh}
                    />
                  </div> */}
                  <button type="button" onClick={handleExportToExcel} className="inline-flex h-11 items-center justify-center rounded-xl border border-white/20 bg-white/10 px-4 text-sm font-semibold text-white transition hover:bg-white/20 focus:outline-none focus:ring-4 focus:ring-white/20">
                    <DocumentArrowDownIcon className="mr-2 h-5 w-5" /> Export
                  </button>
                  <button type="button" onClick={() => setEnrichmentVendor(null)} className="inline-flex h-11 items-center justify-center rounded-xl border border-[#73bdc8]/40 bg-[#73bdc8]/15 px-4 text-sm font-semibold text-[#b9edf0] transition hover:bg-[#73bdc8]/25 focus:outline-none focus:ring-4 focus:ring-[#73bdc8]/20">
                    <SparklesIcon className="mr-2 h-5 w-5" /> AI Enrich
                  </button>
                  <button type="button" onClick={() => { setSelectedVendor(null); setEditMode(false); setShowAICreator(true); }} className="inline-flex h-11 items-center justify-center rounded-xl bg-[#00a896] px-4 text-sm font-semibold text-white shadow-lg shadow-[#00a896]/20 transition hover:bg-[#008f80] focus:outline-none focus:ring-4 focus:ring-[#00a896]/30">
                    <PlusIcon className="mr-2 h-5 w-5" /> Add Vendor
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Statistics */}
        <div className="w-full px-3 sm:px-4 mt-6">
          <VendorStats />
        </div>

        {/* Error Message */}
        {error && (
          <div className="w-full px-3 sm:px-4 mt-6">
            <div className={`rounded-md p-4 ${error.type === 'auth' ? 'bg-yellow-50 border-l-4 border-yellow-400' : 'bg-red-50 border-l-4 border-red-400'}`}>
              <div className="flex">
                <div className="flex-shrink-0">
                  {error.type === 'auth' ? (
                    <svg className="h-5 w-5 text-yellow-400" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 20" fill="currentColor">
                      <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
                    </svg>
                  ) : (
                    <XCircleIcon className="h-5 w-5 text-red-400" />
                  )}
                </div>
                <div className="ml-3 flex-1">
                  <p className={`text-sm font-medium ${error.type === 'auth' ? 'text-yellow-800' : 'text-red-800'}`}>
                    {error.message}
                  </p>
                </div>
                <div className="ml-auto pl-3">
                  <div className="-mx-1.5 -my-1.5 flex">
                    {error.action && (
                      <button
                        type="button"
                        onClick={error.action}
                        className={`inline-flex rounded-md p-1.5 ${error.type === 'auth' ? 'text-yellow-800 hover:bg-yellow-100' : 'text-red-800 hover:bg-red-100'} focus:outline-none focus:ring-2 focus:ring-offset-2 ${error.type === 'auth' ? 'focus:ring-yellow-500' : 'focus:ring-red-500'}`}
                      >
                        <ArrowPathIcon className="h-5 w-5" />
                      </button>
                    )}
                    <button
                      type="button"
                      onClick={() => setError(null)}
                      className={`inline-flex rounded-md p-1.5 ml-2 ${error.type === 'auth' ? 'text-yellow-800 hover:bg-yellow-100' : 'text-red-800 hover:bg-red-100'} focus:outline-none focus:ring-2 focus:ring-offset-2 ${error.type === 'auth' ? 'focus:ring-yellow-500' : 'focus:ring-red-500'}`}
                    >
                      <XCircleIcon className="h-5 w-5" />
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Filters and Search */}
        <div className="w-full px-3 sm:px-4 mt-6">
          <div className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
            <div className="mb-4 flex items-center justify-between gap-4">
              <div>
                <h2 className="text-sm font-bold text-slate-900">Vendor Directory</h2>
                <p className="mt-1 text-xs text-slate-500">Search and filter the supplier master list.</p>
              </div>
              <FunnelIcon className="h-5 w-5 text-[#00a896]" />
            </div>
            <div className="grid grid-cols-1 gap-4 md:grid-cols-2 xl:grid-cols-5">
              {/* Search */}
              <div className="md:col-span-2">
                <label htmlFor="search" className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Search Vendors
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <MagnifyingGlassIcon className="h-5 w-5 text-gray-400" />
                  </div>
                  <input
                    type="text"
                    id="search"
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="block h-11 w-full rounded-xl border border-slate-300 bg-slate-50 pl-10 pr-3 text-sm text-slate-900 placeholder-slate-400 focus:border-[#00a896] focus:bg-white focus:outline-none focus:ring-4 focus:ring-[#00a896]/10"
                    placeholder="Name, code, email, country, or category..."
                  />
                </div>
              </div>

              {/* Status Filter */}
              <div>
                <label htmlFor="status" className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Status
                </label>
                <select
                  id="status"
                  value={filterStatus}
                  onChange={(e) => { setFilterStatus(e.target.value); setActiveKpi('custom'); }}
                  className="block h-11 w-full rounded-xl border border-slate-300 bg-slate-50 px-3 text-sm focus:border-[#00a896] focus:bg-white focus:outline-none focus:ring-4 focus:ring-[#00a896]/10"
                >
                  <option value="all">All Statuses</option>
                  <option value="active">Active</option>
                  <option value="inactive">Inactive</option>
                  <option value="pending">Pending</option>
                  <option value="blacklisted">Blacklisted</option>
                </select>
              </div>

              {/* Rating Filter */}
              <div>
                <label htmlFor="rating" className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Rating
                </label>
                <select
                  id="rating"
                  value={filterRating}
                  onChange={(e) => { setFilterRating(e.target.value); setActiveKpi('custom'); }}
                  className="block h-11 w-full rounded-xl border border-slate-300 bg-slate-50 px-3 text-sm focus:border-[#00a896] focus:bg-white focus:outline-none focus:ring-4 focus:ring-[#00a896]/10"
                >
                  <option value="all">All Ratings</option>
                  <option value="5">⭐⭐⭐⭐⭐ Excellent</option>
                  <option value="4">⭐⭐⭐⭐ Good</option>
                  <option value="3">⭐⭐⭐ Average</option>
                  <option value="2">⭐⭐ Below Average</option>
                  <option value="1">⭐ Poor</option>
                </select>
              </div>

              <div>
                <label htmlFor="completeness" className="mb-1.5 block text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Data Readiness
                </label>
                <select
                  id="completeness"
                  value={filterCompleteness}
                  onChange={(e) => { setFilterCompleteness(e.target.value); setActiveKpi('custom'); }}
                  className="block h-11 w-full rounded-xl border border-slate-300 bg-slate-50 px-3 text-sm focus:border-[#00a896] focus:bg-white focus:outline-none focus:ring-4 focus:ring-[#00a896]/10"
                >
                  <option value="all">All readiness</option>
                  <option value="complete">Complete (85%+)</option>
                  <option value="incomplete">Incomplete</option>
                  <option value="attention">Needs attention</option>
                </select>
              </div>
            </div>

            <div className="mt-4 flex flex-col gap-3 border-t border-slate-100 pt-4 sm:flex-row sm:items-center sm:justify-between">
              <p className="text-sm text-slate-500">
                Showing {filteredVendors.length} of {Array.isArray(vendors) ? vendors.length : 0} vendors
              </p>
              
              <div className="flex items-center gap-2">
                {(searchTerm || filterStatus !== 'all' || filterRating !== 'all' || filterCompleteness !== 'all') && (
                  <button type="button" onClick={() => { setSearchTerm(''); setFilterStatus('all'); setFilterRating('all'); setFilterCompleteness('all'); setActiveKpi('total'); }} className="rounded-lg px-3 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100">
                    Clear filters
                  </button>
                )}
                {/* View Toggle */}
                <div className="inline-flex rounded-md shadow-sm" role="group">
                  <button
                    type="button"
                    onClick={() => setViewMode('table')}
                    className={`px-3 py-2 text-sm font-medium border ${ 
                      viewMode === 'table'
                        ? 'bg-[#00a896] text-white border-[#00a896]'
                        : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                    } rounded-l-md focus:outline-none focus:ring-2 focus:ring-indigo-500`}
                  >
                    <TableCellsIcon className="h-5 w-5" />
                  </button>
                  <button
                    type="button"
                    onClick={() => setViewMode('cards')}
                    className={`px-3 py-2 text-sm font-medium border-t border-b border-r ${
                      viewMode === 'cards'
                        ? 'bg-[#00a896] text-white border-[#00a896]'
                        : 'bg-white text-gray-700 border-gray-300 hover:bg-gray-50'
                    } rounded-r-md focus:outline-none focus:ring-2 focus:ring-indigo-500`}
                  >
                    <Squares2X2Icon className="h-5 w-5" />
                  </button>
                </div>

              </div>
            </div>
          </div>
        </div>

        {/* Vendors List */}
        <div className="w-full px-3 sm:px-4 mt-8">
          {loading ? (
            <div className="text-center py-12">
              <div className="inline-block animate-spin rounded-full h-12 w-12 border-b-2 border-indigo-600"></div>
              <p className="mt-4 text-sm text-gray-500">Loading vendors...</p>
            </div>
          ) : filteredVendors.length === 0 ? (
            <div className="text-center py-12 bg-white rounded-lg shadow">
              <UserGroupIcon className="mx-auto h-12 w-12 text-gray-400" />
              <h3 className="mt-2 text-sm font-medium text-gray-900">No vendors found</h3>
              <p className="mt-1 text-sm text-gray-500">
                {searchTerm || filterStatus !== 'all' || filterRating !== 'all'
                  ? 'Try adjusting your search or filter criteria.'
                  : 'Get started by creating a new vendor.'}
              </p>
            </div>
          ) : viewMode === 'table' ? (
            /* Grouped vendor directory table */
            <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
              <div className="flex items-center justify-between border-b border-slate-200 bg-slate-50/80 px-5 py-3">
                <p className="text-xs font-medium text-slate-500">Click a vendor row to open the full profile.</p>
                <span className="rounded-full bg-[#00a896]/10 px-3 py-1 text-xs font-semibold text-[#008f80]">{filteredVendors.length} vendors</span>
              </div>
              <div className="overflow-x-auto">
                <table className="min-w-[1080px] w-full divide-y divide-slate-200">
                  <thead className="sticky top-0 z-10 bg-slate-50">
                    <tr>
                      <th scope="col" onClick={() => handleSort('name')} className="cursor-pointer px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500 hover:bg-slate-100">
                        <span className="inline-flex items-center gap-1">Vendor &amp; Scope {sortConfig.key === 'name' && (sortConfig.direction === 'asc' ? <ArrowUpIcon className="h-3.5 w-3.5" /> : <ArrowDownIcon className="h-3.5 w-3.5" />)}</span>
                      </th>
                      <th scope="col" className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">Completeness</th>
                      <th scope="col" className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">Primary Contact</th>
                      <th scope="col" className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">Compliance</th>
                      <th scope="col" className="px-5 py-3.5 text-left text-xs font-semibold uppercase tracking-wider text-slate-500">Performance</th>
                      <th scope="col" className="sticky right-0 bg-slate-50 px-5 py-3.5 text-right text-xs font-semibold uppercase tracking-wider text-slate-500">Status &amp; Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-100 bg-white">
                    {filteredVendors
                      .slice()
                      .sort((a, b) => {
                        const aVal = a[sortConfig.key] || '';
                        const bVal = b[sortConfig.key] || '';
                        if (sortConfig.direction === 'asc') return aVal > bVal ? 1 : -1;
                        return aVal < bVal ? 1 : -1;
                      })
                      .map((vendor) => {
                        const completeness = getVendorCompleteness(vendor);
                        const complianceMissing = [
                          !vendor.trade_license_number && 'Trade license',
                          !vendor.vat_number && 'VAT',
                        ].filter(Boolean);
                        return (
                          <tr key={vendor.id} onClick={() => setDetailVendor(vendor)} className="group cursor-pointer transition-colors hover:bg-[#00a896]/[0.035]">
                            <td className="px-5 py-4 align-top">
                              <div className="flex items-start gap-3">
                                <span className="flex h-10 w-10 flex-none items-center justify-center rounded-xl bg-slate-900 text-sm font-bold text-white">
                                  {(vendor.name || 'V').slice(0, 2).toUpperCase()}
                                </span>
                                <div className="min-w-0">
                                  <p className="max-w-[260px] truncate text-sm font-bold text-slate-900">{vendor.name}</p>
                                  <p className="mt-0.5 text-xs font-medium text-[#008f80]">{vendor.vendor_code}</p>
                                  <div className="mt-2 flex max-w-[280px] flex-wrap gap-1">
                                    {(Array.isArray(vendor.categories) ? vendor.categories : []).slice(0, 2).map(category => (
                                      <span key={category} className="rounded-md bg-slate-100 px-2 py-0.5 text-[11px] text-slate-600">{category}</span>
                                    ))}
                                    {(!vendor.categories || vendor.categories.length === 0) && <span className="text-xs text-amber-600">Category missing</span>}
                                  </div>
                                </div>
                              </div>
                            </td>
                            <td className="px-5 py-4 align-top">
                              <div className="flex items-center justify-between gap-3">
                                <span className={`text-sm font-bold ${completeness.score >= 85 ? 'text-emerald-600' : completeness.score >= 60 ? 'text-amber-600' : 'text-rose-600'}`}>{completeness.score}%</span>
                                <span className="text-[11px] text-slate-400">{completeness.missing.length} missing</span>
                              </div>
                              <div className="mt-2 h-2 w-36 overflow-hidden rounded-full bg-slate-100">
                                <div className={`h-full rounded-full ${completeness.score >= 85 ? 'bg-[#00a896]' : completeness.score >= 60 ? 'bg-amber-400' : 'bg-rose-500'}`} style={{ width: `${completeness.score}%` }} />
                              </div>
                              {completeness.missing.length > 0 && <p className="mt-2 max-w-[170px] truncate text-xs text-slate-500" title={completeness.missing.map(field => field.label).join(', ')}>Missing: {completeness.missing[0].label}{completeness.missing.length > 1 ? ` +${completeness.missing.length - 1}` : ''}</p>}
                            </td>
                            <td className="px-5 py-4 align-top text-xs text-slate-600">
                              <p className="font-semibold text-slate-800">{vendor.contact_person || 'Contact missing'}</p>
                              <p className="mt-1 max-w-[210px] truncate">{vendor.email || 'Email missing'}</p>
                              <p className="mt-1">{vendor.phone || 'Phone missing'}</p>
                            </td>
                            <td className="px-5 py-4 align-top">
                              <div className="flex flex-wrap gap-1.5">
                                <span className={`rounded-full px-2 py-1 text-[11px] font-semibold ${vendor.is_icv_certified ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-500'}`}>ICV {vendor.is_icv_certified ? 'Verified' : 'No'}</span>
                                <span className={`rounded-full px-2 py-1 text-[11px] font-semibold ${vendor.adnoc_approved ? 'bg-sky-50 text-sky-700' : 'bg-slate-100 text-slate-500'}`}>ADNOC {vendor.adnoc_approved ? 'Approved' : 'No'}</span>
                              </div>
                              <p className={`mt-2 text-xs ${complianceMissing.length ? 'text-amber-600' : 'text-emerald-600'}`}>{complianceMissing.length ? `${complianceMissing.join(' & ')} missing` : 'Legal identifiers recorded'}</p>
                            </td>
                            <td className="px-5 py-4 align-top">
                              {getRatingStars(vendor.rating)}
                              <p className="mt-2 text-xs text-slate-500">{vendor.vendor_tenure_years ? `${vendor.vendor_tenure_years} years tenure` : 'Tenure not recorded'}</p>
                            </td>
                            <td className="sticky right-0 bg-white px-5 py-4 align-top group-hover:bg-[#f5fbfa]">
                              <div className="flex items-center justify-end gap-2">
                                {getStatusBadge(vendor.status)}
                                <button type="button" onClick={(event) => { event.stopPropagation(); setEnrichmentVendor(vendor); }} className="rounded-lg p-2 text-[#008f80] hover:bg-[#00a896]/10" title="AI enrich vendor"><SparklesIcon className="h-4 w-4" /></button>
                                <button type="button" onClick={(event) => { event.stopPropagation(); setDetailVendor(vendor); }} className="rounded-lg p-2 text-slate-500 hover:bg-slate-100" title="View vendor"><EyeIcon className="h-4 w-4" /></button>
                              </div>
                            </td>
                          </tr>
                        );
                      })}
                  </tbody>
                </table>
              </div>
            </div>
          ) : (
            /* Card View - Responsive Grid */
            <div className={`grid grid-cols-1 gap-6 ${LAYOUT_CONFIG.cardGridCols.sm} ${LAYOUT_CONFIG.cardGridCols.lg} ${LAYOUT_CONFIG.cardGridCols.xl}`}>
              {filteredVendors.map((vendor) => (
                <div key={vendor.id} className="bg-white overflow-hidden shadow-lg rounded-lg hover:shadow-xl transition-shadow duration-200 border-2 border-transparent hover:border-indigo-500">
                  <div className="p-6">
                    {/* Vendor Header */}
                    <div className="flex items-start justify-between">
                      <div className="flex-1">
                        <div className="flex items-center space-x-2">
                          <BuildingOfficeIcon className="h-5 w-5 text-indigo-600" />
                          <h3 className="text-lg font-semibold text-gray-900 truncate">
                            {vendor.name}
                          </h3>
                        </div>
                        <p className="mt-1 text-sm text-gray-500">Code: {vendor.vendor_code}</p>
                      </div>
                      {getStatusBadge(vendor.status)}
                    </div>

                    {/* Rating */}
                    <div className="mt-4">
                      {getRatingStars(vendor.rating)}
                    </div>

                    <button type="button" onClick={() => setDetailVendor(vendor)} className="mt-4 w-full rounded-xl border border-slate-200 bg-slate-50 p-3 text-left hover:border-[#00a896]/40">
                      <div className="flex items-center justify-between"><span className="text-xs font-semibold text-slate-600">Data completeness</span><span className="text-sm font-bold text-[#008f80]">{getVendorCompleteness(vendor).score}%</span></div>
                      <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-slate-200"><div className="h-full rounded-full bg-[#00a896]" style={{ width: `${getVendorCompleteness(vendor).score}%` }} /></div>
                    </button>

                    {/* Contact Info */}
                    <div className="mt-4 space-y-2">
                      {vendor.email && (
                        <div className="flex items-center text-sm text-gray-600">
                          <EnvelopeIcon className="h-4 w-4 mr-2 text-gray-400" />
                          <span className="truncate">{vendor.email}</span>
                        </div>
                      )}
                      {vendor.phone && (
                        <div className="flex items-center text-sm text-gray-600">
                          <PhoneIcon className="h-4 w-4 mr-2 text-gray-400" />
                          <span>{vendor.phone}</span>
                        </div>
                      )}
                      {vendor.country && (
                        <div className="flex items-center text-sm text-gray-600">
                          <GlobeAltIcon className="h-4 w-4 mr-2 text-gray-400" />
                          <span>{vendor.country}</span>
                        </div>
                      )}
                    </div>

                    {/* ICV Badge - Prominent Display for Abu Dhabi Market */}
                    {vendor.is_icv_certified && vendor.icv_percentage && (
                      <div className="mt-4 pt-4 border-t border-gray-200">
                        <div className="bg-gradient-to-r from-red-50 to-orange-50 rounded-lg p-3 border-2 border-red-200">
                          <div className="flex items-center justify-between">
                            <div className="flex items-center space-x-2">
                              <svg className="h-5 w-5 text-red-600" fill="currentColor" viewBox="0 0 24 24">
                                <path d="M3 13h2v-2H3v2zm0 4h2v-2H3v2zm0-8h2V7H3v2zm4 4h14v-2H7v2zm0 4h14v-2H7v2zM7 7v2h14V7H7z"/>
                              </svg>
                              <span className="text-xs font-semibold text-red-900">ICV Certified</span>
                            </div>
                            <span className="text-2xl font-bold text-red-600">{parseFloat(vendor.icv_percentage).toFixed(1)}%</span>
                          </div>
                          {vendor.icv_certificate && (
                            <div className="mt-2 text-xs text-red-700">
                              Cert: {vendor.icv_certificate}
                            </div>
                          )}
                          {vendor.icv_expiry_date && (
                            <div className="mt-1 text-xs text-red-600">
                              Valid until: {new Date(vendor.icv_expiry_date).toLocaleDateString()}
                            </div>
                          )}
                        </div>
                      </div>
                    )}

                    {/* Certifications */}
                    {vendor?.certifications && Array.isArray(vendor.certifications) && vendor.certifications.length > 0 && (
                      <div className="mt-4 pt-4 border-t border-gray-200">
                        <div className="flex items-center space-x-2 mb-2">
                          <ShieldCheckIcon className="h-4 w-4 text-[#00a896]" />
                          <span className="text-xs font-medium text-gray-700">Certifications:</span>
                        </div>
                        <div className="flex flex-wrap gap-1">
                          {vendor.certifications.slice(0, 3).map((cert, idx) => (
                            <span key={idx} className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-[#00a896] bg-opacity-10 text-[#00a896] border border-[#00a896] border-opacity-20">
                              {cert}
                            </span>
                          ))}
                          {vendor.certifications.length > 3 && (
                            <span className="inline-flex items-center px-2 py-0.5 rounded text-xs font-medium bg-gray-100 text-gray-600">
                              +{vendor.certifications.length - 3} more
                            </span>
                          )}
                        </div>
                      </div>
                    )}

                    {/* Actions */}
                    <div className="mt-6 flex flex-col space-y-2">
                      <div className="flex space-x-2">
                        <button type="button" onClick={() => setDetailVendor(vendor)} className="flex-1 inline-flex justify-center items-center px-3 py-2 border border-slate-300 text-sm font-medium rounded-md text-slate-700 bg-white hover:bg-slate-50"><EyeIcon className="h-4 w-4 mr-1" /> View</button>
                        <button type="button" onClick={() => setEnrichmentVendor(vendor)} className="flex-1 inline-flex justify-center items-center px-3 py-2 border border-[#00a896]/30 text-sm font-medium rounded-md text-[#008f80] bg-[#00a896]/5 hover:bg-[#00a896]/10"><SparklesIcon className="h-4 w-4 mr-1" /> AI Enrich</button>
                      </div>
                      <div className="flex space-x-2">
                        <button
                          onClick={() => handleEditVendor(vendor)}
                          className="flex-1 inline-flex justify-center items-center px-3 py-2 border border-indigo-300 shadow-sm text-sm font-medium rounded-md text-indigo-700 bg-white hover:bg-indigo-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500"
                        >
                          <PencilSquareIcon className="h-4 w-4 mr-1" />
                          Edit
                        </button>
                        <button
                          onClick={() => handleToggleStatus(vendor)}
                          className={`flex-1 inline-flex justify-center items-center px-3 py-2 border shadow-sm text-sm font-medium rounded-md focus:outline-none focus:ring-2 focus:ring-offset-2 ${
                            vendor.status === 'active'
                              ? 'border-orange-300 text-orange-700 bg-white hover:bg-orange-50 focus:ring-orange-500'
                              : 'border-green-300 text-green-700 bg-white hover:bg-green-50 focus:ring-green-500'
                          }`}
                        >
                          <PowerIcon className="h-4 w-4 mr-1" />
                          {vendor.status === 'active' ? 'Deactivate' : 'Activate'}
                        </button>
                      </div>
                      <button
                        onClick={() => handleDeleteVendor(vendor)}
                        className="w-full inline-flex justify-center items-center px-3 py-2 border border-red-300 shadow-sm text-sm font-medium rounded-md text-red-700 bg-white hover:bg-red-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-red-500"
                      >
                        <TrashIcon className="h-4 w-4 mr-1" />
                        Delete Vendor
                      </button>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Vendor profile drawer */}
      {detailVendor && (
        <>
          <button type="button" aria-label="Close vendor details" onClick={() => setDetailVendor(null)} className="fixed inset-0 z-[60] cursor-default bg-slate-950/35 backdrop-blur-[2px]" />
          <aside className="fixed inset-y-0 right-0 z-[70] flex w-full max-w-xl flex-col bg-white shadow-2xl" role="dialog" aria-modal="true" aria-labelledby="vendor-detail-title">
            <div className="bg-gradient-to-r from-slate-950 to-blue-950 px-6 py-6 text-white">
              <div className="flex items-start justify-between gap-4">
                <div className="flex min-w-0 items-center gap-3">
                  <span className="flex h-12 w-12 flex-none items-center justify-center rounded-2xl bg-[#00a896] text-base font-bold">{(detailVendor.name || 'V').slice(0, 2).toUpperCase()}</span>
                  <div className="min-w-0">
                    <p className="text-xs font-semibold uppercase tracking-widest text-[#73bdc8]">{detailVendor.vendor_code}</p>
                    <h2 id="vendor-detail-title" className="mt-1 truncate text-xl font-bold">{detailVendor.name}</h2>
                  </div>
                </div>
                <button type="button" onClick={() => setDetailVendor(null)} className="rounded-xl p-2 text-slate-300 hover:bg-white/10 hover:text-white"><XMarkIcon className="h-5 w-5" /></button>
              </div>
              <div className="mt-5 flex items-center gap-3">
                <div className="h-2 flex-1 overflow-hidden rounded-full bg-white/15"><div className="h-full rounded-full bg-[#7fcab5]" style={{ width: `${getVendorCompleteness(detailVendor).score}%` }} /></div>
                <span className="text-sm font-bold">{getVendorCompleteness(detailVendor).score}% complete</span>
              </div>
            </div>

            <div className="flex-1 space-y-5 overflow-y-auto bg-slate-50 p-6">
              <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
                <div className="flex items-center gap-2 text-sm font-bold text-slate-900"><BuildingOfficeIcon className="h-5 w-5 text-[#00a896]" /> Overview</div>
                <div className="mt-4 grid grid-cols-2 gap-4 text-sm">
                  <div><p className="text-xs font-medium text-slate-400">Status</p><div className="mt-1">{getStatusBadge(detailVendor.status)}</div></div>
                  <div><p className="text-xs font-medium text-slate-400">Country</p><p className="mt-1 font-semibold text-slate-800">{detailVendor.country || 'Not recorded'}</p></div>
                  <div className="col-span-2"><p className="text-xs font-medium text-slate-400">Categories</p><div className="mt-2 flex flex-wrap gap-1.5">{(detailVendor.categories || []).map(category => <span key={category} className="rounded-lg bg-[#00a896]/10 px-2.5 py-1 text-xs font-medium text-[#008f80]">{category}</span>)}{(!detailVendor.categories || detailVendor.categories.length === 0) && <span className="text-slate-500">Not recorded</span>}</div></div>
                </div>
              </section>

              <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
                <div className="flex items-center gap-2 text-sm font-bold text-slate-900"><EnvelopeIcon className="h-5 w-5 text-[#00a896]" /> Contact &amp; Location</div>
                <div className="mt-4 space-y-3 text-sm text-slate-700">
                  <p><span className="font-semibold">Contact:</span> {detailVendor.contact_person || 'Not recorded'}</p>
                  <p><span className="font-semibold">Email:</span> {detailVendor.email || 'Not recorded'}</p>
                  <p><span className="font-semibold">Phone:</span> {detailVendor.phone || 'Not recorded'}</p>
                  <p className="flex items-start gap-2"><MapPinIcon className="mt-0.5 h-4 w-4 flex-none text-slate-400" /><span>{detailVendor.address || 'Address not recorded'}</span></p>
                </div>
              </section>

              <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
                <div className="flex items-center gap-2 text-sm font-bold text-slate-900"><IdentificationIcon className="h-5 w-5 text-[#00a896]" /> Legal &amp; Compliance</div>
                <div className="mt-4 grid grid-cols-2 gap-4 text-sm">
                  <div><p className="text-xs text-slate-400">Trade license</p><p className="mt-1 font-semibold text-slate-800">{detailVendor.trade_license_number || 'Missing'}</p></div>
                  <div><p className="text-xs text-slate-400">VAT number</p><p className="mt-1 font-semibold text-slate-800">{detailVendor.vat_number || 'Missing'}</p></div>
                  <div><p className="text-xs text-slate-400">ICV</p><p className="mt-1 font-semibold text-slate-800">{detailVendor.is_icv_certified ? `${detailVendor.icv_percentage || '—'}% certified` : 'Not certified'}</p></div>
                  <div><p className="text-xs text-slate-400">ADNOC</p><p className="mt-1 font-semibold text-slate-800">{detailVendor.adnoc_approved ? 'Approved' : 'Not approved'}</p></div>
                </div>
              </section>

              <section className="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm">
                <div className="flex items-center justify-between"><div className="flex items-center gap-2 text-sm font-bold text-slate-900"><ShieldCheckIcon className="h-5 w-5 text-[#00a896]" /> Data Readiness</div><span className="text-sm font-bold text-[#008f80]">{getVendorCompleteness(detailVendor).score}%</span></div>
                {getVendorCompleteness(detailVendor).missing.length ? (
                  <div className="mt-4 flex flex-wrap gap-2">{getVendorCompleteness(detailVendor).missing.map(field => <span key={field.key} className="rounded-lg bg-amber-50 px-2.5 py-1 text-xs font-medium text-amber-700">{field.label} missing</span>)}</div>
                ) : <p className="mt-3 text-sm text-emerald-600">All tracked master-data fields are complete.</p>}
              </section>
            </div>

            <div className="flex flex-wrap gap-3 border-t border-slate-200 bg-white p-5">
              <button type="button" onClick={() => { setEnrichmentVendor(detailVendor); setDetailVendor(null); }} className="inline-flex flex-1 items-center justify-center rounded-xl border border-[#00a896]/30 bg-[#00a896]/10 px-4 py-2.5 text-sm font-semibold text-[#008f80] hover:bg-[#00a896]/15"><SparklesIcon className="mr-2 h-4 w-4" /> AI Enrich</button>
              <button type="button" onClick={() => { const vendor = detailVendor; setDetailVendor(null); handleEditVendor(vendor); }} className="inline-flex flex-1 items-center justify-center rounded-xl bg-[#00a896] px-4 py-2.5 text-sm font-semibold text-white hover:bg-[#008f80]"><PencilSquareIcon className="mr-2 h-4 w-4" /> Edit Vendor</button>
            </div>
          </aside>
        </>
      )}

      {/* AI enrichment review placeholder */}
      {enrichmentVendor !== undefined && (
        <>
          <button type="button" aria-label="Close AI enrichment review" onClick={() => setEnrichmentVendor(undefined)} className="fixed inset-0 z-[75] cursor-default bg-slate-950/45 backdrop-blur-[2px]" />
          <aside className="fixed inset-y-0 right-0 z-[80] flex w-full max-w-2xl flex-col bg-white shadow-2xl" role="dialog" aria-modal="true" aria-labelledby="enrichment-title">
            <div className="border-b border-slate-200 bg-white px-6 py-5">
              <div className="flex items-start justify-between gap-4">
                <div className="flex items-start gap-3">
                  <span className="rounded-2xl bg-gradient-to-br from-[#00a896] to-[#73bdc8] p-3"><SparklesIcon className="h-6 w-6 text-white" /></span>
                  <div><p className="text-xs font-semibold uppercase tracking-widest text-[#008f80]">Review workspace</p><h2 id="enrichment-title" className="mt-1 text-xl font-bold text-slate-950">AI Enrich {enrichmentVendor ? enrichmentVendor.name : 'Incomplete Vendors'}</h2><p className="mt-1 text-sm text-slate-500">Suggestions require verified evidence and human approval.</p></div>
                </div>
                <button type="button" onClick={() => setEnrichmentVendor(undefined)} className="rounded-xl p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700"><XMarkIcon className="h-5 w-5" /></button>
              </div>
            </div>

            <div className="flex-1 overflow-y-auto bg-slate-50 p-6">
              <div className="mb-5 rounded-2xl border border-[#73bdc8]/40 bg-[#73bdc8]/10 p-4 text-sm text-slate-700"><strong className="text-slate-900">Preview only:</strong> no vendor values will be changed until trusted document and registry sources are connected.</div>
              {enrichmentVendor ? (
                <div className="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm">
                  <div className="grid grid-cols-[28px_1fr_1.25fr_80px] gap-3 border-b border-slate-200 bg-slate-50 px-4 py-3 text-[11px] font-semibold uppercase tracking-wide text-slate-500"><span /><span>Missing field</span><span>Proposed source</span><span>Confidence</span></div>
                  {enrichmentMissingFields.length > 0 ? enrichmentMissingFields.map(field => (
                    <div key={field.key} className="grid grid-cols-[28px_1fr_1.25fr_80px] items-center gap-3 border-b border-slate-100 px-4 py-4 text-sm last:border-0">
                      <input type="checkbox" disabled className="rounded border-slate-300 text-[#00a896]" />
                      <div><p className="font-semibold text-slate-800">{field.label}</p><p className="text-xs text-slate-400">{field.group}</p></div>
                      <p className="text-xs leading-5 text-slate-600">{enrichmentSourceFor(field)}</p>
                      <span className="text-xs font-semibold text-slate-400">Pending</span>
                    </div>
                  )) : <div className="p-8 text-center text-sm text-emerald-600">This vendor is complete across all tracked fields.</div>}
                </div>
              ) : (
                <div className="space-y-3">
                  <div className="flex items-center justify-between"><h3 className="text-sm font-bold text-slate-900">Enrichment queue</h3><span className="text-xs text-slate-500">{enrichmentTargets.length} vendors below 85%</span></div>
                  {enrichmentTargets.slice(0, 12).map(vendor => {
                    const completeness = getVendorCompleteness(vendor);
                    return <button key={vendor.id} type="button" onClick={() => setEnrichmentVendor(vendor)} className="flex w-full items-center justify-between rounded-2xl border border-slate-200 bg-white p-4 text-left shadow-sm transition hover:border-[#00a896]/50 hover:shadow-md"><div><p className="text-sm font-bold text-slate-900">{vendor.name}</p><p className="mt-1 text-xs text-slate-500">{completeness.missing.length} missing fields · {vendor.vendor_code}</p></div><div className="flex items-center gap-3"><span className="text-sm font-bold text-amber-600">{completeness.score}%</span><ChevronRightIcon className="h-4 w-4 text-slate-400" /></div></button>;
                  })}
                  {enrichmentTargets.length === 0 && <div className="rounded-2xl border border-emerald-200 bg-emerald-50 p-8 text-center text-sm text-emerald-700">All vendors meet the 85% completeness threshold.</div>}
                </div>
              )}
            </div>

            <div className="flex items-center justify-between gap-3 border-t border-slate-200 bg-white p-5"><p className="text-xs text-slate-500">Source connectors and field application will be enabled in the enrichment phase.</p><button type="button" disabled className="rounded-xl bg-slate-200 px-4 py-2.5 text-sm font-semibold text-slate-500">Apply selected changes</button></div>
          </aside>
        </>
      )}

      {/* Confirmation Modal */}
      {showConfirmModal && confirmAction && (
        <div className="fixed z-50 inset-0 overflow-y-auto" aria-labelledby="modal-title" role="dialog" aria-modal="true">
          <div className="flex items-end justify-center min-h-screen pt-4 px-4 pb-20 text-center sm:block sm:p-0">
            {/* Background overlay */}
            <div 
              className="fixed inset-0 bg-gray-500 bg-opacity-75 transition-opacity" 
              aria-hidden="true"
              onClick={() => !actionLoading && setShowConfirmModal(false)}
            ></div>

            {/* Center modal */}
            <span className="hidden sm:inline-block sm:align-middle sm:h-screen" aria-hidden="true">&#8203;</span>

            <div className="inline-block align-bottom bg-white rounded-lg px-4 pt-5 pb-4 text-left overflow-hidden shadow-xl transform transition-all sm:my-8 sm:align-middle sm:max-w-lg sm:w-full sm:p-6">
              <div className="sm:flex sm:items-start">
                <div className={`mx-auto flex-shrink-0 flex items-center justify-center h-12 w-12 rounded-full sm:mx-0 sm:h-10 sm:w-10 ${
                  confirmAction.confirmStyle === 'danger' ? 'bg-red-100' :
                  confirmAction.confirmStyle === 'warning' ? 'bg-yellow-100' :
                  'bg-green-100'
                }`}>
                  {confirmAction.confirmStyle === 'danger' ? (
                    <TrashIcon className="h-6 w-6 text-red-600" aria-hidden="true" />
                  ) : confirmAction.confirmStyle === 'warning' ? (
                    <ExclamationTriangleIcon className="h-6 w-6 text-yellow-600" aria-hidden="true" />
                  ) : (
                    <CheckCircleIcon className="h-6 w-6 text-green-600" aria-hidden="true" />
                  )}
                </div>
                <div className="mt-3 text-center sm:mt-0 sm:ml-4 sm:text-left">
                  <h3 className="text-lg leading-6 font-medium text-gray-900" id="modal-title">
                    {confirmAction.title}
                  </h3>
                  <div className="mt-2">
                    <p className="text-sm text-gray-500">
                      {confirmAction.message}
                    </p>
                  </div>
                </div>
              </div>
              <div className="mt-5 sm:mt-4 sm:flex sm:flex-row-reverse">
                <button
                  type="button"
                  disabled={actionLoading}
                  onClick={confirmAction.onConfirm}
                  className={`w-full inline-flex justify-center rounded-md border border-transparent shadow-sm px-4 py-2 text-base font-medium text-white focus:outline-none focus:ring-2 focus:ring-offset-2 sm:ml-3 sm:w-auto sm:text-sm ${
                    confirmAction.confirmStyle === 'danger' 
                      ? 'bg-red-600 hover:bg-red-700 focus:ring-red-500' :
                    confirmAction.confirmStyle === 'warning'
                      ? 'bg-yellow-600 hover:bg-yellow-700 focus:ring-yellow-500'
                      : 'bg-green-600 hover:bg-green-700 focus:ring-green-500'
                  } ${actionLoading ? 'opacity-50 cursor-not-allowed' : ''}`}
                >
                  {actionLoading ? (
                    <>
                      <svg className="animate-spin -ml-1 mr-2 h-4 w-4 text-white" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
                        <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
                        <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
                      </svg>
                      Processing...
                    </>
                  ) : (
                    confirmAction.confirmLabel
                  )}
                </button>
                <button
                  type="button"
                  disabled={actionLoading}
                  onClick={() => setShowConfirmModal(false)}
                  className={`mt-3 w-full inline-flex justify-center rounded-md border border-gray-300 shadow-sm px-4 py-2 bg-white text-base font-medium text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-indigo-500 sm:mt-0 sm:w-auto sm:text-sm ${
                    actionLoading ? 'opacity-50 cursor-not-allowed' : ''
                  }`}
                >
                  Cancel
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* AI Vendor Creator/Editor Modal */}
      <AIVendorCreator
        isOpen={showAICreator}
        onClose={() => {
          clearVendorDraft();
          setShowAICreator(false);
          setEditMode(false);
          setSelectedVendor(null);
        }}
        onVendorCreated={editMode ? handleVendorUpdated : handleVendorCreated}
        editMode={editMode}
        vendorData={selectedVendor}
      />
    </div>
  );
};

