import React, { useCallback, useEffect, useMemo, useState } from 'react'
import {
  XMarkIcon, ArrowPathIcon, SparklesIcon, CheckCircleIcon,
  ArrowDownTrayIcon, ExclamationTriangleIcon, KeyIcon, GlobeAltIcon,
} from '@heroicons/react/24/outline'

import {
  QHSE_IMPORT_CONFIG, PROJECT_COPY,
} from '../../../config/projectControl.config'
import * as PC from '../../../services/projectControl.service'
import useModalAccessibility from '../../../hooks/useModalAccessibility'

const { previewColumns, joinKey, sources, defaultSourceId } = QHSE_IMPORT_CONFIG

const normaliseKey = (v) => String(v ?? '').trim().toLowerCase()

// Session-scoped storage so a tab refresh doesn't drop the token, but it never
// outlives the browser session.
const TOKEN_STORAGE_KEY = 'qhse_import_token'

export default function QhseImportModal({
  open,
  existingProjects = [],
  onClose,
  onImported,             // async ({ created, updated, failed }) => void
}) {
  const [sourceId, setSourceId] = useState(defaultSourceId)
  const [token, setToken] = useState(
    () => sessionStorage.getItem(TOKEN_STORAGE_KEY) || ''
  )
  const [rows, setRows] = useState([])
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState(null)
  const [selected, setSelected] = useState(() => new Set())
  const [running, setRunning] = useState(false)
  const [progress, setProgress] = useState({ done: 0, total: 0 })
  const dialogRef = useModalAccessibility(open, onClose, running)
  const [summary, setSummary] = useState(null)

  const source = useMemo(
    () => sources.find((s) => s.id === sourceId) || sources[0],
    [sourceId]
  )

  // Index of existing Project codes for "Already imported" detection
  const existingIndex = useMemo(() => {
    const m = new Map()
    for (const p of existingProjects) {
      m.set(normaliseKey(p?.[joinKey.projectField]), p)
    }
    return m
  }, [existingProjects])

  const fetchRows = useCallback(async () => {
    // Remote sources need a token before we even try.
    if (source.requiresToken && !token.trim()) {
      setRows([])
      setSelected(new Set())
      setError(null)
      return
    }
    setLoading(true)
    setError(null)
    setSummary(null)
    try {
      const data = await PC.listQhseProjects({
        baseUrl: source.baseUrl,
        token:   source.requiresToken ? token : undefined,
      })
      setRows(data)
      // Default-select rows that are NEW (not yet imported)
      const initial = new Set()
      for (const r of data) {
        const key = normaliseKey(r?.[joinKey.qhseField])
        if (!existingIndex.has(key)) initial.add(key)
      }
      setSelected(initial)
    } catch (e) {
      if (e?.message === 'auth_failed') {
        setError(PROJECT_COPY.importQhseAuthError)
      } else if (e?.message === 'cors_or_network') {
        setError(PROJECT_COPY.importQhseCorsError)
      } else {
        setError(e?.response?.data?.detail || e?.message || 'Failed to load QHSE projects.')
      }
      setRows([])
    } finally {
      setLoading(false)
    }
  }, [existingIndex, source, token])

  useEffect(() => {
    if (open) fetchRows()
  }, [open, fetchRows])

  // Persist token per browser session
  useEffect(() => {
    if (token) sessionStorage.setItem(TOKEN_STORAGE_KEY, token)
    else sessionStorage.removeItem(TOKEN_STORAGE_KEY)
  }, [token])

  if (!open) return null

  const toggleRow = (key) => {
    setSelected((prev) => {
      const next = new Set(prev)
      if (next.has(key)) next.delete(key); else next.add(key)
      return next
    })
  }

  const toggleAll = () => {
    if (selected.size === rows.length) {
      setSelected(new Set())
    } else {
      setSelected(new Set(rows.map((r) => normaliseKey(r?.[joinKey.qhseField]))))
    }
  }

  const handleRun = async () => {
    if (!selected.size) return
    const toImport = rows.filter((r) => selected.has(normaliseKey(r?.[joinKey.qhseField])))
    setRunning(true)
    setProgress({ done: 0, total: toImport.length })
    setSummary(null)
    try {
      const result = await PC.importQhseRows(
        toImport,
        existingProjects,
        ({ done, total }) => setProgress({ done, total }),
      )
      setSummary(result)
      await onImported?.(result)
    } catch (e) {
      setError(e?.message || 'Import failed.')
    } finally {
      setRunning(false)
    }
  }

  return (
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-slate-900/40 backdrop-blur-sm"
      onClick={onClose}
    >
      <div
        ref={dialogRef}
        tabIndex="-1"
        role="dialog"
        aria-modal="true"
        aria-labelledby="qhse-import-title"
        className="relative w-full max-w-5xl max-h-[90vh] overflow-hidden bg-white rounded-2xl shadow-2xl ring-1 ring-slate-200 flex flex-col"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="relative px-6 py-4 border-b border-slate-200 bg-gradient-to-r from-indigo-50 via-violet-50 to-fuchsia-50">
          <div className="flex items-start justify-between gap-3">
            <div className="flex items-center gap-3 min-w-0">
              <span className="inline-flex items-center justify-center h-10 w-10 rounded-lg bg-gradient-to-br from-indigo-500 via-violet-500 to-fuchsia-500 text-white shadow-md shadow-indigo-500/20">
                <SparklesIcon className="h-5 w-5" />
              </span>
              <div className="min-w-0">
                <h2 id="qhse-import-title" className="text-lg font-semibold text-slate-900">{PROJECT_COPY.importQhseTitle}</h2>
                <p className="text-xs text-slate-500 mt-0.5">{PROJECT_COPY.importQhseSubtitle}</p>
              </div>
            </div>
            <button
              type="button"
              onClick={onClose}
              className="p-1.5 rounded-lg text-slate-400 hover:text-slate-700 hover:bg-white/60"
              aria-label="Close"
            >
              <XMarkIcon className="h-5 w-5" />
            </button>
          </div>

          {/* Source picker + optional bearer token (soft-coded from config) */}
          <div className="mt-4 flex flex-col md:flex-row md:items-end gap-3">
            <label className="flex-1 min-w-0">
              <span className="block text-[11px] uppercase tracking-wider text-slate-500 mb-1 font-medium">
                <GlobeAltIcon className="h-3.5 w-3.5 inline-block -mt-0.5 mr-1" />
                {PROJECT_COPY.importQhseSource}
              </span>
              <select
                value={sourceId}
                onChange={(e) => setSourceId(e.target.value)}
                disabled={loading || running}
                className="w-full bg-white border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-800 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
              >
                {sources.map((s) => (
                  <option key={s.id} value={s.id}>
                    {s.label}{s.baseUrl ? ` — ${s.baseUrl}` : ''}
                  </option>
                ))}
              </select>
            </label>
            {source.requiresToken && (
              <label className="flex-[2] min-w-0">
                <span className="block text-[11px] uppercase tracking-wider text-slate-500 mb-1 font-medium">
                  <KeyIcon className="h-3.5 w-3.5 inline-block -mt-0.5 mr-1" />
                  {PROJECT_COPY.importQhseToken}
                </span>
                <input
                  type="password"
                  value={token}
                  onChange={(e) => setToken(e.target.value)}
                  placeholder="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9…"
                  disabled={loading || running}
                  className="w-full bg-white border border-slate-300 rounded-lg px-3 py-2 text-sm text-slate-800 font-mono focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500"
                />
                <span className="text-[11px] text-slate-400 mt-0.5 block">{PROJECT_COPY.importQhseTokenHelp}</span>
              </label>
            )}
          </div>
        </div>

        {/* Body */}
        <div className="flex-1 overflow-auto px-6 py-4">
          {loading ? (
            <div className="py-16 text-center text-slate-500">
              <ArrowPathIcon className="h-6 w-6 mx-auto mb-2 animate-spin text-indigo-500" />
              {PROJECT_COPY.importQhseLoading}
            </div>
          ) : error ? (
            <div role="alert" className="py-16 text-center text-rose-600 max-w-xl mx-auto">
              <ExclamationTriangleIcon className="h-6 w-6 mx-auto mb-2" />
              <p>{error}</p>
              <div className="mt-3">
                <button
                  type="button"
                  onClick={fetchRows}
                  className="text-sm font-medium text-indigo-600 hover:underline"
                >
                  Try again
                </button>
              </div>
            </div>
          ) : source.requiresToken && !token.trim() ? (
            <div className="py-16 text-center text-slate-500">
              <KeyIcon className="h-6 w-6 mx-auto mb-2 text-indigo-400" />
              Paste a bearer token above to load projects from {source.label}.
            </div>
          ) : rows.length === 0 ? (
            <div className="py-16 text-center text-slate-500">{PROJECT_COPY.importQhseEmpty}</div>
          ) : (
            <table className="min-w-full text-sm">
              <thead>
                <tr className="text-left text-xs uppercase tracking-wider text-slate-500 border-b border-slate-200">
                  <th className="px-2 py-2 w-10">
                    <input
                      type="checkbox"
                      aria-label="Select all import rows"
                      checked={selected.size === rows.length}
                      onChange={toggleAll}
                      className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                    />
                  </th>
                  {previewColumns.map((c) => (
                    <th key={c.key} className="px-2 py-2 font-medium">{c.label}</th>
                  ))}
                  <th className="px-2 py-2 font-medium">Status</th>
                </tr>
              </thead>
              <tbody>
                {rows.map((row) => {
                  const key = normaliseKey(row?.[joinKey.qhseField])
                  const exists = existingIndex.has(key)
                  const checked = selected.has(key)
                  return (
                    <tr
                      key={key || row.id}
                      className={`border-b border-slate-100 ${checked ? 'bg-indigo-50/40' : 'hover:bg-slate-50'}`}
                    >
                      <td className="px-2 py-2">
                        <input
                          type="checkbox"
                          aria-label={`Select ${row.name || row.projectName || key} for import`}
                          checked={checked}
                          onChange={() => toggleRow(key)}
                          className="rounded border-slate-300 text-indigo-600 focus:ring-indigo-500"
                        />
                      </td>
                      {previewColumns.map((c) => (
                        <td key={c.key} className="px-2 py-2 text-slate-700 truncate max-w-[220px]" title={String(row[c.key] ?? '')}>
                          {row[c.key] ?? <span className="text-slate-300">—</span>}
                        </td>
                      ))}
                      <td className="px-2 py-2">
                        {exists ? (
                          <span className="inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full bg-amber-100 text-amber-700 ring-1 ring-amber-200">
                            {PROJECT_COPY.importQhseExisting}
                          </span>
                        ) : (
                          <span className="inline-flex items-center gap-1 text-xs px-2 py-0.5 rounded-full bg-emerald-100 text-emerald-700 ring-1 ring-emerald-200">
                            {PROJECT_COPY.importQhseNew}
                          </span>
                        )}
                      </td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          )}

          {/* Summary panel */}
          {summary && (
            <div className="mt-4 p-3 rounded-lg bg-emerald-50 text-emerald-800 ring-1 ring-emerald-100 text-sm">
              <CheckCircleIcon className="h-5 w-5 inline-block mr-1.5 -mt-0.5" />
              {PROJECT_COPY.importQhseDone(summary.created, summary.updated, summary.failed)}
              {summary.errors?.length > 0 && (
                <details className="mt-2 text-xs text-rose-700">
                  <summary className="cursor-pointer">View {summary.errors.length} error(s)</summary>
                  <ul className="mt-1 list-disc pl-5 space-y-0.5">
                    {summary.errors.slice(0, 10).map((e, i) => (
                      <li key={i}>
                        <span className="font-mono">{e.row?.[joinKey.qhseField] || '—'}</span>:{' '}
                        {typeof e.error === 'string' ? e.error : JSON.stringify(e.error)}
                      </li>
                    ))}
                  </ul>
                </details>
              )}
            </div>
          )}
        </div>

        {/* Footer */}
        <div className="px-6 py-3 border-t border-slate-200 bg-slate-50/60 flex items-center justify-between gap-3">
          <div className="text-xs text-slate-500">
            {running
              ? `${progress.done} / ${progress.total} processed`
              : PROJECT_COPY.importQhseSelected(selected.size)}
          </div>
          <div className="flex items-center gap-2">
            <button
              type="button"
              onClick={fetchRows}
              disabled={loading || running}
              className="inline-flex items-center gap-1.5 px-3 py-2 text-sm font-medium text-slate-700 bg-white border border-slate-200 hover:bg-slate-50 rounded-lg disabled:opacity-40"
            >
              <ArrowPathIcon className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
              Refresh
            </button>
            <button
              type="button"
              onClick={onClose}
              className="px-3 py-2 text-sm font-medium text-slate-600 hover:text-slate-900"
            >
              Close
            </button>
            <button
              type="button"
              onClick={handleRun}
              disabled={running || !selected.size || loading}
              className="inline-flex items-center gap-2 px-4 py-2 text-sm font-semibold text-white rounded-lg bg-gradient-to-r from-indigo-600 via-violet-600 to-fuchsia-600 hover:from-indigo-500 hover:via-violet-500 hover:to-fuchsia-500 shadow-md shadow-indigo-500/20 disabled:opacity-40 disabled:cursor-not-allowed"
            >
              <ArrowDownTrayIcon className={`h-4 w-4 ${running ? 'animate-bounce' : ''}`} />
              {running ? PROJECT_COPY.importQhseRunning : PROJECT_COPY.importQhseRun(selected.size)}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}

import React, { useEffect, useState } from "react";
import {
  BarChart,
  Bar,
  XAxis,
  YAxis,
  Tooltip,
  ResponsiveContainer,
  CartesianGrid,
  Cell,
} from "recharts";
import {
  ArrowPathIcon,
  PlusIcon,
  CheckIcon,
} from "@heroicons/react/24/outline";

import * as PC from "../../../services/projectControl.service";
import { COST_KPI_CARDS } from "../../../config/projectControl.config";
import KpiCard from "../components/KpiCard";

const CHART_COLORS = {
  budget: "#6366f1",
  committed: "#0ea5e9",
  spent: "#f59e0b",
  remaining: "#10b981",
};

export default function CostDashboardTab({ project }) {
  const [kpis, setKpis] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [syncing, setSyncing] = useState(false);
  const [syncMessage, setSyncMessage] = useState(null);
  const [wbsNodes, setWbsNodes] = useState([]);
  const [budgets, setBudgets] = useState([]);
  const [ledger, setLedger] = useState([]);
  const [showBudgetForm, setShowBudgetForm] = useState(false);
  const [savingBudget, setSavingBudget] = useState(false);
  const [budgetForm, setBudgetForm] = useState({
    wbs_node: "",
    wbs_code: "",
    wbs_name: "",
    code: "",
    name: "",
    amount: "",
    category: "",
    currency: project.currency || "AED",
  });

  const rows = (value) => (Array.isArray(value) ? value : value?.results || []);

  const reload = () => {
    setLoading(true);
    setError(null);
    Promise.all([
      PC.getCostKpis(project.id),
      PC.listWbsNodes(project.id),
      PC.listBudgetAllocations(project.id),
      PC.listCostLedger(project.id, { status: "posted" }),
    ])
      .then(([nextKpis, nextWbs, nextBudgets, nextLedger]) => {
        setKpis(nextKpis);
        setWbsNodes(rows(nextWbs));
        setBudgets(rows(nextBudgets));
        setLedger(rows(nextLedger));
      })
      .catch((e) =>
        setError(
          e?.response?.data?.error || e?.message || "Failed to load KPIs",
        ),
      )
      .finally(() => setLoading(false));
  };

  useEffect(() => {
    reload(); /* eslint-disable-next-line */
  }, [project.id]);

  const runSync = () => {
    setSyncing(true);
    setSyncMessage(null);
    PC.runFinanceSync(project.id)
      .then((res) => {
        const currencyExceptions =
          res.ledger_totals?.currency_exceptions?.length || 0;
        if (currencyExceptions) {
          setSyncMessage(
            `Ledger rebuilt. ${currencyExceptions} source(s) were excluded because their currency differs from the project currency.`,
          );
          reload();
          return;
        }
        if (res.skipped) {
          setSyncMessage("Finance module not installed — skipped.");
        } else {
          setSyncMessage(
            `Matched ${res.matched_invoices} invoice(s) totalling ${res.total_spent}.`,
          );
        }
        reload();
      })
      .catch((e) =>
        setSyncMessage(e?.response?.data?.error || "Finance sync failed."),
      )
      .finally(() => setSyncing(false));
  };

  const saveBudget = async (event) => {
    event.preventDefault();
    setSavingBudget(true);
    setSyncMessage(null);
    try {
      let wbsId = budgetForm.wbs_node;
      if (!wbsId) {
        const created = await PC.createWbsNode({
          project: project.id,
          code: budgetForm.wbs_code,
          name: budgetForm.wbs_name,
          level: 0,
          sort_order: wbsNodes.length,
        });
        wbsId = created.id;
      }
      await PC.createBudgetAllocation({
        project: project.id,
        wbs_node: wbsId,
        code: budgetForm.code,
        name: budgetForm.name,
        category: budgetForm.category,
        amount: budgetForm.amount,
        currency: budgetForm.currency,
      });
      setShowBudgetForm(false);
      setBudgetForm({
        wbs_node: "",
        wbs_code: "",
        wbs_name: "",
        code: "",
        name: "",
        amount: "",
        category: "",
        currency: project.currency || "AED",
      });
      setSyncMessage(
        "Draft WBS budget created. Approve it before it affects KPIs.",
      );
      reload();
    } catch (e) {
      setSyncMessage(
        e?.response?.data?.amount?.[0] ||
          e?.response?.data?.detail ||
          "Could not create the budget allocation.",
      );
    } finally {
      setSavingBudget(false);
    }
  };

  const approveBudget = async (id) => {
    try {
      await PC.approveBudgetAllocation(id);
      setSyncMessage("Budget approved and posted to the cost ledger.");
      reload();
    } catch (e) {
      setSyncMessage(
        e?.response?.data?.detail || "Could not approve the budget.",
      );
    }
  };

  if (loading)
    return (
      <div className="bg-white border border-slate-200 rounded-xl p-8 text-center text-slate-500">
        Loading cost KPIs…
      </div>
    );
  if (error)
    return (
      <div className="bg-white border border-rose-200 text-rose-700 rounded-xl p-6">
        {error}
      </div>
    );
  if (!kpis) return null;

  const chartData = [
    {
      name: "Budget",
      value: Number(kpis.budget || 0),
      fill: CHART_COLORS.budget,
    },
    {
      name: "Committed",
      value: Number(kpis.committed || 0),
      fill: CHART_COLORS.committed,
    },
    { name: "Spent", value: Number(kpis.spent || 0), fill: CHART_COLORS.spent },
    {
      name: "Remaining",
      value: Number(kpis.remaining || 0),
      fill: CHART_COLORS.remaining,
    },
  ];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between rounded-xl border border-blue-200 bg-gradient-to-r from-white via-white to-blue-50/60 px-5 py-4">
        <div>
          <h2 className="text-sm font-semibold text-slate-900">
            WBS Cost Control
          </h2>
          <p className="mt-1 text-xs text-slate-500">
            KPIs below use posted ledger entries only—not editable Project
            totals.
          </p>
        </div>
        <button
          onClick={() => setShowBudgetForm(true)}
          className="inline-flex items-center gap-2 rounded-lg bg-indigo-600 px-3 py-2 text-xs font-semibold text-white hover:bg-indigo-700"
        >
          <PlusIcon className="h-4 w-4" />
          WBS Budget
        </button>
      </div>
      {/* KPI strip */}
      <div className="grid grid-cols-2 lg:grid-cols-3 xl:grid-cols-6 gap-4">
        {COST_KPI_CARDS.map((card) => (
          <KpiCard
            key={card.key}
            label={card.label}
            value={kpis[card.field]}
            tone={card.tone}
            isCurrency={card.isCurrency}
            isPercent={card.isPercent}
            currency={kpis.currency}
          />
        ))}
      </div>

      {/* Chart + forecast */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <div className="rounded-xl border border-blue-100 bg-gradient-to-br from-white to-blue-50/30 p-5 lg:col-span-2">
          <div className="flex items-center justify-between mb-4">
            <h3 className="text-sm font-semibold text-slate-800">
              Cost Breakdown
            </h3>
            <button
              onClick={runSync}
              disabled={syncing}
              className="text-xs px-3 py-1.5 inline-flex items-center gap-1.5 rounded-md
                         bg-indigo-50 text-indigo-700 hover:bg-indigo-100 disabled:opacity-50"
            >
              <ArrowPathIcon
                className={`h-3.5 w-3.5 ${syncing ? "animate-spin" : ""}`}
              />
              {syncing ? "Syncing…" : "Sync from Finance"}
            </button>
          </div>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={chartData}
                margin={{ top: 10, right: 10, bottom: 10, left: 0 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#f1f5f9" />
                <XAxis
                  dataKey="name"
                  tick={{ fontSize: 12, fill: "#64748b" }}
                />
                <YAxis
                  tick={{ fontSize: 12, fill: "#64748b" }}
                  tickFormatter={(v) => v.toLocaleString()}
                />
                <Tooltip
                  formatter={(v) =>
                    Number(v).toLocaleString(undefined, {
                      style: "currency",
                      currency: kpis.currency || "AED",
                      maximumFractionDigits: 0,
                    })
                  }
                />
                <Bar dataKey="value" radius={[4, 4, 0, 0]}>
                  {chartData.map((entry, idx) => (
                    <Cell key={idx} fill={entry.fill} />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
          {syncMessage && (
            <p className="mt-2 text-xs text-slate-500">{syncMessage}</p>
          )}
        </div>

        <div className="rounded-xl border border-violet-100 bg-gradient-to-br from-white to-violet-50/40 p-5">
          <h3 className="text-sm font-semibold text-slate-800 mb-3">
            Forecast (EVM)
          </h3>
          <div className="space-y-3 text-sm">
            <Row
              label="EAC (forecast)"
              value={
                kpis.forecast?.eac
                  ? Number(kpis.forecast.eac).toLocaleString()
                  : "—"
              }
            />
            <Row label="CPI" value={kpis.forecast?.cpi ?? "—"} />
            <Row label="SPI" value={kpis.forecast?.spi ?? "—"} />
            <Row
              label="Last snapshot"
              value={kpis.forecast?.snapshot_date || "—"}
            />
          </div>
          <p className="text-xs text-slate-400 mt-4">
            Full EVM lights up when Phase 3 is enabled.
          </p>
        </div>
      </div>

      {/* Estimate counts */}
      <div className="grid grid-cols-3 gap-4">
        <KpiCard
          label="Estimates · total"
          value={kpis.estimate_counts?.total}
          tone="indigo"
        />
        <KpiCard
          label="Estimates · approved"
          value={kpis.estimate_counts?.approved}
          tone="green"
        />
        <KpiCard
          label="Estimates · draft"
          value={kpis.estimate_counts?.draft}
          tone="slate"
        />
      </div>

      <div className="grid gap-4 xl:grid-cols-2">
        <section className="overflow-hidden rounded-xl border border-slate-200 bg-white">
          <div className="border-b border-slate-200 px-5 py-4">
            <h3 className="text-sm font-semibold text-slate-800">
              WBS Budget Allocations
            </h3>
            <p className="text-xs text-slate-500">
              Only approved rows post to the ledger.
            </p>
          </div>
          <div className="max-h-72 overflow-auto">
            <table className="min-w-full text-left text-xs">
              <thead className="sticky top-0 bg-slate-50 text-slate-500">
                <tr>
                  <th className="px-4 py-2">WBS</th>
                  <th className="px-4 py-2">Budget</th>
                  <th className="px-4 py-2 text-right">Amount</th>
                  <th className="px-4 py-2">Status</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {budgets.map((row) => (
                  <tr key={row.id}>
                    <td className="px-4 py-3 font-medium">{row.wbs_code}</td>
                    <td className="px-4 py-3">
                      {row.code} · {row.name}
                    </td>
                    <td className="px-4 py-3 text-right">
                      {Number(row.amount).toLocaleString()} {row.currency}
                    </td>
                    <td className="px-4 py-3">
                      {row.status === "draft" ? (
                        <button
                          onClick={() => approveBudget(row.id)}
                          className="inline-flex items-center gap-1 rounded-md bg-emerald-50 px-2 py-1 font-semibold text-emerald-700"
                        >
                          <CheckIcon className="h-3 w-3" />
                          Approve
                        </button>
                      ) : (
                        <span className="rounded-full bg-slate-100 px-2 py-1 font-medium">
                          {row.status}
                        </span>
                      )}
                    </td>
                  </tr>
                ))}
                {!budgets.length && (
                  <tr>
                    <td
                      colSpan="4"
                      className="px-4 py-8 text-center text-slate-400"
                    >
                      No WBS budgets yet.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>
        <section className="overflow-hidden rounded-xl border border-slate-200 bg-white">
          <div className="border-b border-slate-200 px-5 py-4">
            <h3 className="text-sm font-semibold text-slate-800">
              Posted Cost Ledger
            </h3>
            <p className="text-xs text-slate-500">
              {kpis.ledger_entry_count || 0} active entries · source:{" "}
              {kpis.calculation_source}
            </p>
          </div>
          <div className="max-h-72 overflow-auto">
            <table className="min-w-full text-left text-xs">
              <thead className="sticky top-0 bg-slate-50 text-slate-500">
                <tr>
                  <th className="px-4 py-2">Date</th>
                  <th className="px-4 py-2">Type</th>
                  <th className="px-4 py-2">Source</th>
                  <th className="px-4 py-2 text-right">Amount</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-100">
                {ledger.map((row) => (
                  <tr key={row.id}>
