                      Run ledger sync after approving a budget or linking a PO.
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </section>
      </div>

      {showBudgetForm && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/50 p-4">
          <form
            onSubmit={saveBudget}
            className="w-full max-w-2xl rounded-2xl bg-white p-6 shadow-2xl"
          >
            <h2 className="text-lg font-bold text-slate-900">
              Create WBS Budget
            </h2>
            <p className="mt-1 text-sm text-slate-500">
              Create a draft allocation, then approve it from the table.
            </p>
            <div className="mt-5 grid gap-4 sm:grid-cols-2">
              <label className="text-xs font-semibold text-slate-600">
                Existing WBS
                <select
                  value={budgetForm.wbs_node}
                  onChange={(e) =>
                    setBudgetForm({ ...budgetForm, wbs_node: e.target.value })
                  }
                  className="mt-1 w-full rounded-lg border border-slate-300 p-2 text-sm"
                >
                  <option value="">Create a new WBS node</option>
                  {wbsNodes.map((node) => (
                    <option key={node.id} value={node.id}>
                      {node.code} — {node.name}
                    </option>
                  ))}
                </select>
              </label>
              {!budgetForm.wbs_node && (
                <>
                  <label className="text-xs font-semibold text-slate-600">
                    New WBS code
                    <input
                      required
                      value={budgetForm.wbs_code}
                      onChange={(e) =>
                        setBudgetForm({
                          ...budgetForm,
                          wbs_code: e.target.value,
                        })
                      }
                      className="mt-1 w-full rounded-lg border border-slate-300 p-2 text-sm"
                      placeholder="1.2"
                    />
                  </label>
                  <label className="text-xs font-semibold text-slate-600">
                    New WBS name
                    <input
                      required
                      value={budgetForm.wbs_name}
                      onChange={(e) =>
                        setBudgetForm({
                          ...budgetForm,
                          wbs_name: e.target.value,
                        })
                      }
                      className="mt-1 w-full rounded-lg border border-slate-300 p-2 text-sm"
                      placeholder="Procurement"
                    />
                  </label>
                </>
              )}
              <label className="text-xs font-semibold text-slate-600">
                Budget code
                <input
                  required
                  value={budgetForm.code}
                  onChange={(e) =>
                    setBudgetForm({ ...budgetForm, code: e.target.value })
                  }
                  className="mt-1 w-full rounded-lg border border-slate-300 p-2 text-sm"
                  placeholder="BUD-PROC-001"
                />
              </label>
              <label className="text-xs font-semibold text-slate-600">
                Budget name
                <input
                  required
                  value={budgetForm.name}
                  onChange={(e) =>
                    setBudgetForm({ ...budgetForm, name: e.target.value })
                  }
                  className="mt-1 w-full rounded-lg border border-slate-300 p-2 text-sm"
                />
              </label>
              <label className="text-xs font-semibold text-slate-600">
                Category
                <input
                  value={budgetForm.category}
                  onChange={(e) =>
                    setBudgetForm({ ...budgetForm, category: e.target.value })
                  }
                  className="mt-1 w-full rounded-lg border border-slate-300 p-2 text-sm"
                />
              </label>
              <label className="text-xs font-semibold text-slate-600">
                Amount
                <input
                  required
                  min="0.01"
                  step="0.01"
                  type="number"
                  value={budgetForm.amount}
                  onChange={(e) =>
                    setBudgetForm({ ...budgetForm, amount: e.target.value })
                  }
                  className="mt-1 w-full rounded-lg border border-slate-300 p-2 text-sm"
                />
              </label>
            </div>
            <div className="mt-6 flex justify-end gap-2">
              <button
                type="button"
                onClick={() => setShowBudgetForm(false)}
                className="rounded-lg border border-slate-300 px-4 py-2 text-sm"
              >
                Cancel
              </button>
              <button
                disabled={savingBudget}
                className="rounded-lg bg-indigo-600 px-4 py-2 text-sm font-semibold text-white disabled:opacity-50"
              >
                {savingBudget ? "Saving…" : "Create draft"}
              </button>
            </div>
          </form>
        </div>
      )}
    </div>
  );
}

function Row({ label, value }) {
  return (
    <div className="flex items-center justify-between border-b border-slate-100 pb-2 last:border-b-0 last:pb-0">
      <span className="text-slate-500 text-xs uppercase tracking-wider">
        {label}
      </span>
      <span className="text-slate-800 font-medium">{value}</span>
    </div>
  );
}

import React, { useState, useMemo, useEffect } from 'react';
import { Routes, Route, NavLink, useNavigate } from 'react-router-dom';
import { 
  ShieldCheckIcon, 
  ChartBarIcon, 
  DocumentTextIcon, 
  PresentationChartLineIcon,
  TableCellsIcon,
  Bars3Icon,
  SparklesIcon
} from '@heroicons/react/24/outline';
import { Maximize2, Minimize2, RefreshCw } from 'lucide-react';
import { IconButton, Tooltip } from '@mui/material';

// QHSE Components
import DashSummaryCard from './components/Dashboard/DashSummaryCard';
import QHSEOverviewChart from './components/Dashboard/OverviewChart';
import ProjectStatus from './components/Dashboard/ProjectStatus';
import SummaryView from './components/SummayView/Page';
import DetailedView from './components/DetailedView/DetailedView';
import QualityManagement from './QualityManagement';
import HealthSafety from './HealthSafety';
import Environmental from './Environmental';
import Energy from './Energy';
import Projects from './Projects';
import QHSEAIDashboard from '../../components/qhse/QHSEAIDashboard';

// Common Components
import { LoadingState } from './components/Common/LoadingState';
import { ErrorState } from './components/Common/ErrorState';
import { EmptyDataState } from './components/Common/EmptyDataState';
import { MainHeader } from './components/Common/MainHeader';

// Hooks and Utils
import { useQHSERunningProjects } from './hooks/useQHSEProjects';
import { getMonthlyOverviewData, getYearlyOverviewData } from './utils';
import { generateQHSETimelineData } from './utils/chartUtils';

const GeneralQHSE = () => {
  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-slate-50">
      <Routes>
        <Route index element={<QHSEDashboard />} />
        <Route path="/" element={<QHSEDashboard />} />
        <Route path="/summary" element={<SummaryViewWrapper />} />
        <Route path="/detailed" element={<DetailedViewWrapper />} />
        <Route path="/projects" element={<ProjectsWrapper />} />
        <Route path="/quality" element={<QualityManagement />} />
        <Route path="/health-safety" element={<HealthSafety />} />
        {/* SOFT-CODED: Environmental and Energy routes disabled - not related to project quality */}
        {/* <Route path="/environmental" element={<Environmental />} /> */}
        {/* <Route path="/energy" element={<Energy />} /> */}
        <Route path="/ai-dashboard" element={<QHSEAIDashboard />} />
      </Routes>
    </div>
  );
};

// Main Dashboard Component
const QHSEDashboard = () => {
  const navigate = useNavigate();
  const { 
    data: projectsData, 
    loading, 
    isRefreshing, 
    error, 
    refetch, 
    lastUpdated,
    dataLastChanged 
  } = useQHSERunningProjects();

  const [isFullscreen, setIsFullscreen] = useState(false);
  const [autoRefreshEnabled, setAutoRefreshEnabled] = useState(true);
  const [sidebarVisible, setSidebarVisible] = useState(true);

  // Auto-refresh every 30 seconds when enabled
  useEffect(() => {
    if (!autoRefreshEnabled) return;
    
    const interval = setInterval(() => {
      console.log('🔄 Auto-refreshing QHSE data...');
      refetch();
    }, 30000); // 30 seconds
    
    return () => clearInterval(interval);
  }, [autoRefreshEnabled, refetch]);

  // Toggle fullscreen mode
  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
        setIsFullscreen(false);
      }
    }
  };

  // Listen for fullscreen changes
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, []);

  const chartData = useMemo(() => {
    if (!projectsData || projectsData.length === 0) {
      return { monthlyData: [], yearlyData: [], timelineData: [] };
    }
    const qhseTimelineData = generateQHSETimelineData(projectsData);

    return {
      monthlyData: getMonthlyOverviewData(projectsData),
      yearlyData: getYearlyOverviewData(projectsData),
      timelineData: qhseTimelineData
    };
  }, [projectsData]);

  // Loading state
  if (loading) {
    return (
      <div className="p-6">
        <MainHeader />
        <LoadingState message="Loading QHSE data from database..." />
      </div>
    );
  }

  // Error state
  if (error) {
    return (
      <div className="p-6">
        <MainHeader />
        <ErrorState error={error} onRetry={refetch} />
      </div>
    );
  }

  // Empty state
  console.log('🔍 QHSE Dashboard Debug:', {
    projectsData,
    projectsDataType: typeof projectsData,
    isArray: Array.isArray(projectsData),
    length: projectsData?.length,
    hasData: !!(projectsData && projectsData.length > 0)
  });
  
  if (!projectsData || projectsData.length === 0) {
    console.warn('⚠️ Showing EmptyDataState - projectsData:', projectsData);
    return (
      <div className="p-6">
        <MainHeader />
        <EmptyDataState onRetry={refetch} />
      </div>
    );
  }

  // Navigation cards
  const navCards = [
    {
      title: 'Summary View',
      description: 'Overview of all projects with filtering options',
      icon: ChartBarIcon,
      path: '/qhse/general/summary',
      color: 'from-blue-500 to-blue-600',
      iconColor: 'text-blue-500'
    },
    {
      title: 'Detailed View',
      description: 'Comprehensive project data table',
      icon: TableCellsIcon,
      path: '/qhse/general/detailed',
      color: 'from-indigo-500 to-indigo-600',
      iconColor: 'text-indigo-500'
    },
    {
      title: 'Project Management',
      description: 'Create and manage QHSE projects',
      icon: DocumentTextIcon,
      path: '/qhse/general/projects',
      color: 'from-purple-500 to-purple-600',
      iconColor: 'text-purple-500'
    },
    {
      title: 'AI Insights Dashboard',
      description: 'AI-powered predictions and analytics',
      icon: SparklesIcon,
      path: '/qhse/general/ai-dashboard',
      color: 'from-purple-500 to-pink-600',
      iconColor: 'text-purple-500',
      badge: 'NEW'
    }
  ];

  return (
    <>
      <style>{`
        :fullscreen aside,
        :fullscreen header,
        :fullscreen footer {
          display: none !important;
        }
        :fullscreen {
          background: linear-gradient(to bottom right, rgb(239 246 255), white, rgb(248 250 252)) !important;
          padding: 2rem !important;
        }
        :fullscreen main {
          margin-left: 0 !important;
        }
        ${!sidebarVisible ? `
          aside {
            display: none !important;
          }
          main {
            margin-left: 0 !important;
          }
        ` : ''}
      `}</style>
      <div className="p-4 sm:p-6 lg:p-8 max-w-[1920px] mx-auto">
        {/* Header */}
        <MainHeader 
        title="QHSE Dashboard"
        subtitle={`Monitoring ${projectsData.length} Active Projects`}
        lastUpdated={lastUpdated}
        dataLastChanged={dataLastChanged}
        isRefreshing={isRefreshing}
        className="mb-6"
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          {/* Sidebar toggle */}
          <Tooltip title={sidebarVisible ? 'Hide Sidebar' : 'Show Sidebar'}>
            <IconButton
              size="small"
              onClick={() => setSidebarVisible(!sidebarVisible)}
              sx={{ color: sidebarVisible ? 'primary.main' : 'text.secondary' }}
            >
              <Bars3Icon className="w-4 h-4" />
            </IconButton>
          </Tooltip>
          
          {/* Auto-refresh indicator */}
          <Tooltip title={autoRefreshEnabled ? 'Auto-refresh ON (30s)' : 'Auto-refresh OFF'}>
            <IconButton
              size="small"
              onClick={() => setAutoRefreshEnabled(!autoRefreshEnabled)}
              sx={{ color: autoRefreshEnabled ? 'success.main' : 'text.secondary' }}
            >
              <RefreshCw size={16} className={isRefreshing ? 'animate-spin' : ''} />
            </IconButton>
          </Tooltip>
          
          {/* Fullscreen toggle */}
          <Tooltip title={isFullscreen ? 'Exit Fullscreen' : 'Enter Fullscreen'}>
            <IconButton
              size="small"
              onClick={toggleFullscreen}
              sx={{ color: 'text.secondary' }}
            >
              {isFullscreen ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
            </IconButton>
          </Tooltip>
        </div>
      </MainHeader>

      {/* Navigation Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 mb-8">
        {navCards.map((card) => (
          <button
            key={card.path}
            onClick={() => navigate(card.path)}
            className="group relative overflow-hidden rounded-xl bg-white p-6 shadow-lg hover:shadow-2xl transition-all duration-300 border border-gray-200 hover:border-gray-300"
          >
            {card.badge && (
              <div className="absolute top-3 right-3 px-2 py-1 text-xs font-bold text-white bg-gradient-to-r from-purple-500 to-pink-500 rounded-full animate-pulse">
                {card.badge}
              </div>
            )}
            <div className="flex items-start space-x-4">
              <div className={`flex-shrink-0 p-3 rounded-lg bg-gradient-to-br ${card.color} text-white group-hover:scale-110 transition-transform duration-300`}>
                <card.icon className="h-6 w-6" />
              </div>
              <div className="flex-1 text-left">
                <h3 className="text-lg font-semibold text-gray-900 mb-1 group-hover:text-blue-600 transition-colors">
                  {card.title}
                </h3>
                <p className="text-sm text-gray-600">
                  {card.description}
                </p>
              </div>
            </div>
            <div className="absolute bottom-0 left-0 h-1 w-0 bg-gradient-to-r from-blue-500 to-purple-500 group-hover:w-full transition-all duration-500"></div>
          </button>
        ))}
      </div>

      {/* Dashboard Content */}
      <div className="space-y-6">
        {/* Summary Cards */}
        <section className="w-full">
          <DashSummaryCard projectsData={projectsData} />
        </section>

        {/* Charts */}
        <section className="w-full">
          <div className="grid grid-cols-1 gap-6">
            <div className="w-full min-h-[400px]">
              <QHSEOverviewChart 
                monthlyData={chartData.monthlyData} 
                yearlyData={chartData.yearlyData} 
                className="w-full h-full"
              />
            </div>
          </div>
        </section>

        {/* Project Status Table */}
        <section className="w-full">
          <ProjectStatus 
            projectsData={projectsData} 
            loading={loading}
            onRefresh={refetch}
            className="w-full"
          />
        </section>
      </div>
    </div>
    </>
  );
};

// Wrapper components for sub-pages
const SummaryViewWrapper = () => {
  return (
    <div className="p-4 sm:p-6 lg:p-8 max-w-[1920px] mx-auto">
      <SummaryView />
    </div>
  );
};

const DetailedViewWrapper = () => {
  return (
    <div className="p-4 sm:p-6 lg:p-8 max-w-[1920px] mx-auto">
      <DetailedView />
    </div>
  );
};

const ProjectsWrapper = () => {
  return (
    <div className="p-4 sm:p-6 lg:p-8 max-w-[1920px] mx-auto">
      <Projects />
    </div>
  );
};

export default GeneralQHSE;

import React, { useState, useMemo, useCallback } from 'react';
import {
  AlertCircle, TrendingUp, Calendar, AlertTriangle, FileText,
  BarChart3, RefreshCw, Download, Target
} from 'lucide-react';
import { MainHeader } from './components/Common/MainHeader';
import { LoadingState } from './components/Common/LoadingState';
import { ErrorState } from './components/Common/ErrorState';
import { useQHSERunningProjects } from './hooks/useQHSEProjects';
import { withDashboardControls } from '../../hoc/withPageControls';
import { PageControlButtons } from '../../components/PageControlButtons';
import { QHSE_MODULE_LABELS } from '../../config/qhseModules.config';
import {
  calculateHealthSafetyMetrics,
  HEALTH_SAFETY_FEATURES,
  HEALTH_SAFETY_UNAVAILABLE_REASONS as UNAVAILABLE
} from './utils/healthSafetyMetrics';
import {
  SafetyMetricCard, SafetyScoreDisplay, SafetyEmptyState
} from './components/HealthSafety/SafetyComponents';

const HealthSafety = ({ pageControls }) => {
  const { data: projectsData, loading, error, refetch, isRefreshing } = useQHSERunningProjects({
    preserveMissingQualityCounts: true
  });
  const [selectedView, setSelectedView] = useState('overview');
  const safetyMetrics = useMemo(() => calculateHealthSafetyMetrics(projectsData), [projectsData]);

  if (loading || error || !projectsData?.length) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-slate-50 p-6">
        <MainHeader
          title={QHSE_MODULE_LABELS.healthSafety.shortTitle}
          subtitle={QHSE_MODULE_LABELS.healthSafety.description}
          showLiveStatus={false}
        />
        {loading ? <LoadingState message="Loading occupational health and safety data..." />
          : error ? <ErrorState error={error} onRetry={refetch} />
            : <SafetyEmptyState title="Unavailable" message="No project quality records were returned. Safety measures also require incident, injury and exposure evidence; an empty source does not establish zero incidents." />}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-white to-slate-50 p-4 sm:p-6 lg:p-8">
      <MainHeader
        title={QHSE_MODULE_LABELS.healthSafety.shortTitle}
        subtitle={`${projectsData.length} project quality records • Safety metrics unavailable`}
        showLiveStatus={false}
      >
        <div className="flex items-center gap-3">
          <PageControlButtons controls={pageControls} />
          <button
            onClick={refetch}
            disabled={isRefreshing}
            className="inline-flex items-center gap-2 px-4 py-2 bg-white border border-gray-300 rounded-lg text-sm font-medium text-gray-700 hover:bg-gray-50 disabled:opacity-50"
          >
            <RefreshCw size={16} className={isRefreshing ? 'animate-spin' : ''} />
            Refresh
          </button>
          <button className="inline-flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700">
            <Download size={16} />
            Export Report
          </button>
        </div>
      </MainHeader>

      <div className="flex gap-2 mb-6 overflow-x-auto pb-2">
        {[
          { id: 'overview', label: 'Overview', icon: BarChart3 },
          { id: 'incidents', label: 'Incidents', icon: AlertCircle },
          { id: 'risk', label: 'Risk Assessment', icon: AlertTriangle },
          { id: 'performance', label: 'Performance', icon: TrendingUp }
        ].map(view => (
          <button
            key={view.id}
            onClick={() => setSelectedView(view.id)}
            className={`inline-flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${
              selectedView === view.id
                ? 'bg-blue-600 text-white'
                : 'bg-white text-gray-700 hover:bg-gray-50 border border-gray-300'
            }`}
          >
            <view.icon size={16} />
            {view.label}
          </button>
        ))}
      </div>

      <div className={`grid grid-cols-1 md:grid-cols-2 gap-4 mb-6 ${
        HEALTH_SAFETY_FEATURES.enableHighRiskProjects ? 'lg:grid-cols-5' : 'lg:grid-cols-4'
      }`}>
        <div className="bg-white rounded-xl shadow-sm p-6 border border-gray-200 flex items-center justify-center">
          <SafetyScoreDisplay size="md" />
        </div>
        <SafetyMetricCard title="Incident Rate" value={safetyMetrics.incidentRate}
          icon={AlertCircle} color="slate" description={UNAVAILABLE.incidentRate} />
        <SafetyMetricCard title="Open Incidents" value={safetyMetrics.totalIncidents}
          icon={AlertTriangle} color="slate" description={UNAVAILABLE.totalIncidents}
          subtitle="Near misses: Unavailable (records not connected)" />
        <SafetyMetricCard title="Days Without Incident" value={safetyMetrics.daysWithoutIncident}
          icon={Calendar} color="slate" description={UNAVAILABLE.daysWithoutIncident} />
        {HEALTH_SAFETY_FEATURES.enableHighRiskProjects && (
          <SafetyMetricCard title="High Risk Projects" value={null}
            icon={Target} color="slate" description={UNAVAILABLE.highRiskProjects} />
        )}
      </div>

      {selectedView === 'overview' && <OverviewView safetyMetrics={safetyMetrics} />}
      {selectedView === 'incidents' && <IncidentsView />}
      {selectedView === 'risk' && <RiskAssessmentView />}
      {selectedView === 'performance' && <PerformanceView />}
    </div>
  );
};

// Current sources cannot populate safety charts. Keep the panels explicit rather
// than plotting null as zero, or presenting an empty series as a clean record.
const UnavailablePanel = ({ title, reason, icon: Icon, className = '' }) => (
  <section aria-label={title} className={`bg-white rounded-xl shadow-sm p-6 border border-gray-200 ${className}`}>
    <h3 className="text-lg font-semibold text-gray-900 mb-4 flex items-center gap-2">
      {Icon && <Icon className="text-slate-500" size={20} />}
      {title}
    </h3>
    <SafetyEmptyState title="Unavailable" message={reason} />
  </section>
);

const QualityCounts = ({ safetyMetrics }) => (
  <section aria-label="Recorded quality counts" className="bg-white rounded-xl shadow-sm p-6 border border-gray-200">
    <h3 className="text-lg font-semibold text-gray-900 mb-2 flex items-center gap-2">
      <BarChart3 className="text-blue-500" size={20} />
      Recorded quality counts
    </h3>
    <p className="text-sm text-gray-600 mb-4">
      Totals from the {safetyMetrics.totalProjects} loaded project quality records. Corrective actions and observations are not incidents, near misses or injuries. Recorded counts do not certify historical completeness.
    </p>
    <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
      {[
        ['openCARs', 'Open corrective actions'],
        ['closedCARs', 'Closed corrective actions'],
        ['openObservations', 'Open observations'],
        ['closedObservations', 'Closed observations']
      ].map(([key, title]) => {
        const value = safetyMetrics.qualityCounts[key];
        const { knownRecords, totalRecords } = safetyMetrics.qualityCoverage[key];
        return (
          <SafetyMetricCard key={key} title={title} value={value} icon={FileText} color="blue"
            description={value === null
              ? `A complete total is unavailable. Valid counts: ${knownRecords} of ${totalRecords} records.`
              : `Recorded count supplied by ${knownRecords} of ${totalRecords} records.`} />
        );
      })}
    </div>
  </section>
);

