      label: 'Project No', 
      sortable: true, 
      width: '90px',
      configKey: 'projectNo'
    },
    { 
      id: 'projectTitle', 
      label: 'Project Title', 
      sortable: true, 
      width: '170px',
      minWidth: '180px',
      configKey: 'projectTitle'
    },
    { 
      id: 'client', 
      label: 'Client', 
      sortable: true, 
      width: '140px',
      configKey: 'client'
    },
    { 
      id: 'projectManager', 
      label: 'Project Manager', 
      sortable: true, 
      width: '140px',
      configKey: 'projectManager'
    },
    { 
      id: 'projectQualityEng',
      label: 'Quality Engineer', 
      sortable: true, 
      width: '140px',
      configKey: 'projectQualityEng'
    },
    { 
      id: 'qualityBillabilityPercent', 
      label: 'Billability (%)', 
      sortable: true, 
      width: '100px', 
      align: 'center',
      configKey: 'qualityBillabilityPercent' // ✅ This will be hidden via config
    },
    { 
      id: 'carsOpen', 
      label: 'CARs', 
      sortable: true, 
      width: '70px', 
      align: 'center',
      configKey: 'carsOpen'
    },
    { 
      id: 'obsOpen', 
      label: 'OBS', 
      sortable: true, 
      width: '70px', 
      align: 'center',
      configKey: 'obsOpen'
    },
    { 
      id: 'projectKPIsAchievedPercent', 
      label: 'KPIs (%)', 
      sortable: true, 
      width: '85px', 
      align: 'center',
      configKey: 'projectKPIsAchievedPercent'
    },
    { 
      id: 'delayInAuditsNoDays', 
      label: 'Audit Delay', 
      sortable: true, 
      width: '100px', 
      align: 'center',
      configKey: 'delayInAuditsNoDays'
    },
    { 
      id: 'projectCompletionPercent', 
      label: 'Completion (%)', 
      sortable: true, 
      width: '110px', 
      align: 'center',
      configKey: 'projectCompletionPercent'
    },
  ];

  // ✅ Filter columns based on configuration
  const headCells = allHeadCells.filter(cell => 
    !cell.configKey || isQHSEColumnVisible(cell.configKey)
  );

  return (
    <TableHead>
      <TableRow>
        {headCells.map((headCell) => (
          <TableCell
            key={headCell.id}
            sortDirection={orderBy === headCell.id ? order : false}
            align={headCell.align || 'left'}
            className="!bg-gray-50 dark:!bg-slate-800 !border-gray-200 dark:!border-slate-700 !text-gray-900 dark:!text-slate-100"
            sx={{ 
              fontWeight: 600,
              borderBottom: '2px solid',
              width: headCell.width,
              minWidth: headCell.minWidth,
              position: 'sticky',
              top: 0,
              zIndex: 10,
              whiteSpace: 'nowrap',
              padding: '12px 6px',
              fontSize: '0.875rem'
            }}
          >
            {headCell.sortable ? (
              <TableSortLabel
                active={orderBy === headCell.id}
                direction={orderBy === headCell.id ? order : 'asc'}
                onClick={createSortHandler(headCell.id)}
                className="!text-gray-900 dark:!text-slate-100"
                sx={{ 
                  '& .MuiTableSortLabel-icon': {
                    fontSize: '1rem'
                  }
                }}
              >
                {headCell.label}
                {orderBy === headCell.id ? (
                  <Box component="span" sx={visuallyHidden}>
                    {order === 'desc' ? 'sorted descending' : 'sorted ascending'}
                  </Box>
                ) : null}
              </TableSortLabel>
            ) : (
              headCell.label
            )}
          </TableCell>
        ))}
      </TableRow>
    </TableHead>
  );
};

const ProjectStatus = ({ projectsData = [], loading = false, onRefresh }) => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('lg'));
  
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(10);
  const [order, setOrder] = useState('asc');
  const [orderBy, setOrderBy] = useState('displaySrNo');
  const [searchTerm, setSearchTerm] = useState('');
  const [activeFilter, setActiveFilter] = useState('ALL');

  // Enhanced data processing with risk assessment
  const validProjects = useMemo(() => {
    return projectsData
      .filter(hasValidData)
      .map((project, index) => ({
        ...project,
        displaySrNo: index + 1,
        riskLevel: getRiskLevel(project)
      }));
  }, [projectsData]);

  const filteredProjects = useMemo(() => {
    let filtered = validProjects.filter(project =>
      project.projectNo?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      project.projectTitle?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      project.client?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      project.projectManager?.toLowerCase().includes(searchTerm.toLowerCase()) ||
      // ✅ Fix: Use the correct field name from Google Sheets mapping
      project.projectQualityEng?.toLowerCase().includes(searchTerm.toLowerCase())
    );

    // Apply active filter
    if (activeFilter === 'CRITICAL') {
      filtered = filtered.filter(p => p.riskLevel === 'CRITICAL');
    } else if (activeFilter === 'HIGH_RISK') {
      filtered = filtered.filter(p => p.riskLevel === 'HIGH' || p.riskLevel === 'CRITICAL');
    } else if (activeFilter === 'ON_TRACK') {
      filtered = filtered.filter(p => p.riskLevel === 'LOW');
    } else if (activeFilter === 'MEDIUM_RISK') {
      filtered = filtered.filter(p => p.riskLevel === 'MEDIUM');
    }

    return filtered;
  }, [validProjects, searchTerm, activeFilter]);

  const sortedProjects = useMemo(() => {
    const comparator = (a, b) => {
      let aValue = a[orderBy];
      let bValue = b[orderBy];

      if (orderBy.includes('Percent') || orderBy.includes('Days') || orderBy.includes('Open')) {
        aValue = formatNumber(aValue);
        bValue = formatNumber(bValue);
      }

      if (bValue < aValue) {
        return order === 'desc' ? -1 : 1;
      }
      if (bValue > aValue) {
        return order === 'desc' ? 1 : -1;
      }
      return 0;
    };

    return filteredProjects.slice().sort(comparator);
  }, [filteredProjects, order, orderBy]);

  // Enhanced statistics calculations for filter buttons
  const stats = useMemo(() => {
    const total = validProjects.length;
    const critical = validProjects.filter(p => p.riskLevel === 'CRITICAL').length;
    const highRisk = validProjects.filter(p => p.riskLevel === 'HIGH' || p.riskLevel === 'CRITICAL').length;
    const mediumRisk = validProjects.filter(p => p.riskLevel === 'MEDIUM').length;
    const onTrack = validProjects.filter(p => p.riskLevel === 'LOW').length;

    return { total, critical, highRisk, mediumRisk, onTrack };
  }, [validProjects]);

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event) => {
    setRowsPerPage(parseInt(event.target.value, 10));
    setPage(0);
  };

  const handleFilterChange = (filter) => {
    setActiveFilter(filter);
    setPage(0);
  };

  const paginatedProjects = sortedProjects.slice(
    page * rowsPerPage,
    page * rowsPerPage + rowsPerPage
  );

  return (
    <Box sx={{ width: '100%', overflow: 'hidden' }}>
      {/* Heading FIRST */}
      {/* <div className="p-6 border-b border-gray-200 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 rounded-t-xl"> */}
        <Typography 
          variant="h6" 
          component="div" 
          fontWeight={600}
          className="!text-gray-900 dark:!text-slate-100"
        >
          Project Critical Status
        </Typography>
        <Typography 
          variant="body2" 
          className="!text-gray-600 dark:!text-slate-400"
        >
          {filteredProjects.length} projects
          {activeFilter !== 'ALL' && (
            <span> • Filtered by: {activeFilter.replace('_', ' ')}</span>
          )}
        </Typography>
        {/* Info about filter logic */}
        <Typography variant="caption" className="!text-gray-500 dark:!text-slate-400">
          <strong>Critical:</strong> Severe issues. <strong>High Risk:</strong> Notable issues. <strong>On Track:</strong> No major issues.
        </Typography>
      {/* </div> */}

      {/* Filter Buttons SECOND */}
      <Box sx={{ mb: 2, mt: 2, display: 'flex', gap: 1, flexWrap: 'wrap' }}>
        <ButtonGroup variant="outlined" size="small" className="bg-white dark:bg-slate-800">
          <Button 
            variant={activeFilter === 'ALL' ? 'contained' : 'outlined'}
            onClick={() => handleFilterChange('ALL')}
            startIcon={<FilterIcon />}
          >
            All ({stats.total})
          </Button>
          <Button 
            variant={activeFilter === 'CRITICAL' ? 'contained' : 'outlined'}
            color="error"
            onClick={() => handleFilterChange('CRITICAL')}
            startIcon={<CriticalIcon />}
          >
            Critical ({stats.critical})
          </Button>
          <Button 
            variant={activeFilter === 'HIGH_RISK' ? 'contained' : 'outlined'}
            color="warning"
            onClick={() => handleFilterChange('HIGH_RISK')}
            startIcon={<WarningIcon />}
          >
            High Risk ({stats.highRisk})
          </Button>
          {/* Remove Medium if not needed */}
          {/* <Button ...>Medium ({stats.mediumRisk})</Button> */}
          <Button 
            variant={activeFilter === 'ON_TRACK' ? 'contained' : 'outlined'}
            color="success"
            onClick={() => handleFilterChange('ON_TRACK')}
            startIcon={<CheckCircleIcon />}
          >
            On Track ({stats.onTrack})
          </Button>
        </ButtonGroup>
      </Box>

      {/* Main Table */}
      <div className="bg-white dark:bg-slate-900 rounded-xl border border-gray-200 dark:border-slate-800 shadow-lg">
        {/* Header */}
        <div className="p-6 border-b border-gray-200 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 rounded-t-xl">
          <Box 
            display="flex" 
            alignItems="center" 
            justifyContent="space-between" 
            flexWrap="wrap" 
            gap={2}
          >
            {/* <Box>
              <Typography 
                variant="h6" 
                component="div" 
                fontWeight={600}
                className="!text-gray-900 dark:!text-slate-100"
              >
                Project Status Overview
              </Typography>
              <Typography 
                variant="body2" 
                className="!text-gray-600 dark:!text-slate-400"
              >
                {filteredProjects.length} projects
                {activeFilter !== 'ALL' && (
                  <span> • Filtered by: {activeFilter.replace('_', ' ')}</span>
                )}
              </Typography>
            </Box> */}
            
            <Box display="flex" gap={2} alignItems="center">
              <TextField
                size="small"
                placeholder="Search projects..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                className="bg-white dark:bg-slate-700"
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon className="text-gray-500 dark:text-slate-400" />
                    </InputAdornment>
                  ),
                  className: "!text-gray-900 dark:!text-slate-100"
                }}
                sx={{ 
                  minWidth: isMobile ? '200px' : '300px',
                  '& .MuiOutlinedInput-root': {
                    borderRadius: 2,
                    '& fieldset': {
                      borderColor: 'rgb(209 213 219)', // gray-300
                    },
                    '.dark &': {
                      '& fieldset': {
                        borderColor: 'rgb(71 85 105)', // slate-600
                      }
                    }
                  }
                }}
              />
              
              {/* <Tooltip title="Refresh Data">
                <IconButton 
                  onClick={onRefresh} 
                  disabled={loading}
                  className="!bg-blue-600 hover:!bg-blue-700 !text-white"
                >
                  <RefreshIcon />
                </IconButton>
              </Tooltip> */}
            </Box>
          </Box>
        </div>

        {loading && <LinearProgress className="!bg-blue-100 dark:!bg-slate-700" />}

        {/* Table with proper column widths */}
        <TableContainer 
          className="bg-white dark:bg-slate-900"
          sx={{ 
            maxHeight: isMobile ? 500 : 600,
            overflowX: 'auto'
          }}
        >
          <Table 
            stickyHeader 
            size="small"
            sx={{
              tableLayout: 'fixed',
              width: '100%',
              minWidth: '1400px' // Ensure minimum width for all columns
            }}
          >
            <EnhancedTableHead
              order={order}
              orderBy={orderBy}
              onRequestSort={handleRequestSort}
            />
            <TableBody>
              {paginatedProjects.map((project, index) => {
                // Apply subtle row highlighting based on risk
                const getRowClasses = (riskLevel, index) => {
                  const baseClasses = "hover:bg-gray-50 dark:hover:bg-slate-800";
                  switch (riskLevel) {
                    case 'CRITICAL':
                      return `bg-red-50 dark:bg-red-950/20 ${baseClasses}`;
                    case 'HIGH':
                      return `bg-orange-50 dark:bg-orange-950/20 ${baseClasses}`;
                    default:
                      return index % 2 === 0 
                        ? `bg-gray-50 dark:bg-slate-800/50 ${baseClasses}` 
                        : `bg-white dark:bg-slate-900 ${baseClasses}`;
                  }
                };

                return (
                  <TableRow
                    key={`project-${project.displaySrNo}`}
                    className={getRowClasses(project.riskLevel, index)}
                  >
                    {/* Sr.No - Fixed width, centered */}
                    <TableCell 
                      align="center"
                      className="!text-blue-600 dark:!text-blue-400 !border-gray-200 dark:!border-slate-700"
                      sx={{ 
                        fontWeight: 600,
                        fontSize: '0.875rem',
                        padding: '8px 6px'
                      }}
                    >
                      {project.displaySrNo}
                    </TableCell>
                    
                    {/* Project No - Fixed width */}
                    <TableCell 
                      className="!text-gray-900 dark:!text-slate-100 !border-gray-200 dark:!border-slate-700"
                      sx={{ 
                        fontWeight: 500,
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                        padding: '8px 6px'
                      }}
                    >
                      <Typography variant="body2" component="div">
                        {project.projectNo || 'N/A'}
                      </Typography>
                    </TableCell>
                    
                    {/* Project Title - Expandable width */}
                    <TableCell 
                      className="!text-gray-900 dark:!text-slate-100 !border-gray-200 dark:!border-slate-700"
                      sx={{ 
                        minWidth: '200px',
                        wordBreak: 'break-word',
                        whiteSpace: 'normal',
                        padding: '8px 6px'
                      }}
                    >
                      <Typography 
                        variant="body2" 
                        component="div"
                        sx={{ 
                          fontWeight: 500,
                          lineHeight: 1.4,
                          display: '-webkit-box',
                          WebkitLineClamp: 2,
                          WebkitBoxOrient: 'vertical',
                          overflow: 'hidden'
                        }}
                        title={project.projectTitle} // Show full title on hover
                      >
                        {project.projectTitleKey || 'Untitled Project'}
                      </Typography>
                    </TableCell>
                    
                    {/* Client - Fixed width with ellipsis */}
                    <TableCell 
                      className="!text-gray-900 dark:!text-slate-100 !border-gray-200 dark:!border-slate-700"
                      sx={{
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                        padding: '8px 6px'
                      }}
                    >
                      <Typography 
                        variant="body2"
                        title={project.client}
                      >
                        {project.client || 'N/A'}
                      </Typography>
                    </TableCell>
                    
                    {/* Project Manager - Fixed width with ellipsis */}
                    <TableCell 
                      className="!text-gray-900 dark:!text-slate-100 !border-gray-200 dark:!border-slate-700"
                      sx={{
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                        padding: '8px 6px'
                      }}
                    >
                      <Typography 
                        variant="body2"
                        title={project.projectManager}
                      >
                        {project.projectManager || 'N/A'}
                      </Typography>
                    </TableCell>
                    
                    {/* Quality Engineer - Fixed field name */}
                    <TableCell 
                      className="!border-gray-200 dark:!border-slate-700"
                      sx={{
                        overflow: 'hidden',
                        textOverflow: 'ellipsis',
                        whiteSpace: 'nowrap',
                        padding: '8px 6px'
                      }}
                    >
                      <Typography 
                        variant="body2"
                        title={project.projectQualityEng}
                        className={project.projectQualityEng && project.projectQualityEng !== 'N/A' 
                          ? "!text-blue-600 dark:!text-blue-400 !font-medium" 
                          : "!text-gray-500 dark:!text-slate-400"
                        }
                      >
                        {project.projectQualityEng || 'N/A'}
                      </Typography>
                    </TableCell>
                    
                    {/* ✅ SOFT-CODED: Billability column - only show if configured as visible */}
                    {isQHSEColumnVisible('qualityBillabilityPercent') && (
                      <TableCell align="center" className="!border-gray-200 dark:!border-slate-700" sx={{ padding: '8px 4px' }}>
                        <Chip
                          label={formatPercentage(project.qualityBillabilityPercent)}
                          color={getChipColor(project.qualityBillabilityPercent, "billability")}
                          size="small"
                          sx={{ minWidth: '55px', fontWeight: 600, fontSize: '0.75rem' }}
                        />
                      </TableCell>
                    )}
                    
                    <TableCell align="center" className="!border-gray-200 dark:!border-slate-700" sx={{ padding: '8px 4px' }}>
                      <Chip
                        label={formatNumber(project.carsOpen)}
                        color={getChipColor(project.carsOpen, "cars")}
                        size="small"
                        sx={{ minWidth: '40px', fontWeight: 600, fontSize: '0.75rem' }}
                      />
                    </TableCell>
                    
                    <TableCell align="center" className="!border-gray-200 dark:!border-slate-700" sx={{ padding: '8px 4px' }}>
                      <Chip
                        label={formatNumber(project.obsOpen)}
                        color={getChipColor(project.obsOpen, "obs")}
                        size="small"
                        sx={{ minWidth: '40px', fontWeight: 600, fontSize: '0.75rem' }}
                      />
                    </TableCell>
                    
                    <TableCell align="center" className="!border-gray-200 dark:!border-slate-700" sx={{ padding: '8px 4px' }}>
                      <Chip
                        label={formatPercentage(project.projectKPIsAchievedPercent)}
                        color={getChipColor(project.projectKPIsAchievedPercent, "kpi")}
                        size="small"
                        sx={{ minWidth: '50px', fontWeight: 600, fontSize: '0.75rem' }}
                      />
                    </TableCell>
                    
                    <TableCell align="center" className="!border-gray-200 dark:!border-slate-700" sx={{ padding: '8px 4px' }}>
                      <Chip
                        label={`${formatNumber(project.delayInAuditsNoDays)}d`}
                        color={formatNumber(project.delayInAuditsNoDays) > 0 ? "error" : "success"}
                        size="small"
                        sx={{ minWidth: '45px', fontWeight: 600, fontSize: '0.75rem' }}
                      />
                    </TableCell>
                    
                    <TableCell align="center" className="!border-gray-200 dark:!border-slate-700" sx={{ padding: '8px 4px' }}>
                      <Chip
                        label={formatPercentage(project.projectCompletionPercent)}
                        color={getChipColor(project.projectCompletionPercent, "kpi")}
                        size="small"
                        sx={{ minWidth: '55px', fontWeight: 600, fontSize: '0.75rem' }}
                      />
                    </TableCell>
                  </TableRow>
                );
              })}
              
              {paginatedProjects.length === 0 && (
                <TableRow>
                  <TableCell 
                    colSpan={12} 
                    align="center" 
                    className="!text-gray-500 dark:!text-slate-400 !border-gray-200 dark:!border-slate-700"
                    sx={{ py: 6 }}
                  >
                    <Typography variant="h6" className="!text-gray-500 dark:!text-slate-400" gutterBottom>
                      {searchTerm ? 'No projects match your search' : `No ${activeFilter.toLowerCase().replace('_', ' ')} projects found`}
                    </Typography>
                    {searchTerm && (
                      <Typography variant="body2" className="!text-gray-400 dark:!text-slate-500">
                        Try adjusting your search terms or clear the filter
                      </Typography>
                    )}
                  </TableCell>
                </TableRow>
              )}
            </TableBody>
          </Table>
        </TableContainer>

        {/* Enhanced Pagination */}
        <div className="border-t border-gray-200 dark:border-slate-800 bg-gray-50 dark:bg-slate-800 rounded-b-xl">
          <TablePagination
            rowsPerPageOptions={[5, 10, 25, 50, 100]}
            component="div"
            count={filteredProjects.length}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={handleChangePage}
            onRowsPerPageChange={handleChangeRowsPerPage}
            className="!text-gray-900 dark:!text-slate-100"
            sx={{
              '& .MuiTablePagination-toolbar': {
                minHeight: '52px'
              },
              '& .MuiTablePagination-selectLabel, & .MuiTablePagination-displayedRows': {
                fontWeight: 500
              },
              '& .MuiIconButton-root': {
                color: 'inherit'
              }
            }}
          />
        </div>
      </div>
    </Box>
  );
};

export default ProjectStatus;

import React, { useState } from "react";
import { Progress } from "../ui/Progress";
import { Badge } from "../ui/Badge";
import { CheckCircle2, AlertTriangle, Clock, TrendingUp, AlertCircle, User, Shield, FileText, ClipboardCheck, TrendingDown, Building2, Activity } from "lucide-react";

// Enhanced status icon to show QHSE priority status
const getQHSEStatusIcon = (status, qhseScore = 0) => {
  const baseSize = 18;
  const isHighRisk = qhseScore >= 8;
  const pulseClass = isHighRisk ? "animate-pulse" : "";
  
  switch (status) {
    case "QHSE Compliant":
      return <Shield className="text-green-500 hover:text-green-600 transition-colors" size={baseSize} />;
    case "Critical QHSE Issues":
      return <AlertCircle className={`text-red-500 hover:text-red-600 transition-colors ${pulseClass}`} size={baseSize} />;
    case "Quality Issues":
      return <AlertTriangle className={`text-orange-500 hover:text-orange-600 transition-colors ${pulseClass}`} size={baseSize} />;
    case "Audit Required":
      return <ClipboardCheck className={`text-blue-500 hover:text-blue-600 transition-colors ${pulseClass}`} size={baseSize} />;
    case "Documentation Issues":
      return <FileText className="text-yellow-500 hover:text-yellow-600 transition-colors" size={baseSize} />;
    case "Minor Issues":
      return <Clock className="text-blue-500 hover:text-blue-600 transition-colors" size={baseSize} />;
    default:
      return <Shield className="text-gray-400 hover:text-gray-500 transition-colors" size={baseSize} />;
  }
};

// Enhanced badge variant for QHSE status
const getQHSEBadgeVariant = (status) => {
  switch (status) {
    case "Critical QHSE Issues": return "destructive";
    case "Quality Issues": return "warning";
    case "Audit Required": return "secondary";
    case "Documentation Issues": return "secondary";
    case "QHSE Compliant": return "success";
    case "Minor Issues": return "default";
    default: return "default";
  }
};

// ✅ OPTIMIZED: Enhanced tooltip component with QHSE details
const QHSEProjectTooltip = ({ project, children }) => {
  const [showTooltip, setShowTooltip] = useState(false);

  return (
    <div className="relative">
      <div
        onMouseEnter={() => setShowTooltip(true)}
        onMouseLeave={() => setShowTooltip(false)}
        className="cursor-help inline-block"
      >
        {children}
      </div>
      {showTooltip && (
        <div className="absolute z-50 p-3 sm:p-4 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-600 text-gray-900 dark:text-gray-100 text-sm rounded-lg shadow-lg w-64 sm:w-72 md:w-80 max-w-xs sm:max-w-sm md:max-w-md -top-2 left-8 sm:left-8">
          <div className="space-y-2 sm:space-y-3">
            {/* Header with QHSE indicator */}
            <div className="flex items-center gap-2 pb-2 border-b border-gray-200 dark:border-gray-600">
              {getQHSEStatusIcon(project.qhseStatus, project.qhseScore)}
              <div className="flex-1 min-w-0">
                <div className="font-semibold text-gray-900 dark:text-gray-100 flex items-center gap-1 sm:gap-2 flex-wrap">
                  <span className="truncate text-xs sm:text-sm">
                    {project.projectNo && project.projectNo !== "" && project.projectNo !== "N/A" 
                      ? `${project.projectNo} - ${project.name}` 
                      : project.name}
                  </span>
                  {project.qhseScore >= 8 && (
                    <span className="text-xs bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300 px-1 sm:px-2 py-0.5 rounded-full animate-pulse">
                      HIGH RISK
                    </span>
                  )}
                </div>
                <div className="text-xs text-gray-500 dark:text-gray-400">
                  QHSE Priority Project
                </div>
              </div>
            </div>

            {/* ✅ RESPONSIVE: QHSE Priority Metrics */}
            <div className="grid grid-cols-3 gap-1 sm:gap-2 text-xs">
              <div className="text-center p-1.5 sm:p-2 bg-gray-50 dark:bg-gray-700 rounded">
                <div className="font-semibold text-gray-900 dark:text-gray-100 text-xs">QHSE Risk</div>
                <div className={`text-xs sm:text-sm font-bold ${
                  project.qhseScore >= 8 ? "text-red-600" :
                  project.qhseScore >= 5 ? "text-orange-600" :
                  project.qhseScore >= 3 ? "text-yellow-600" : "text-green-600"
                }`}>
                  {project.qhseScore >= 8 ? "CRITICAL" :
                   project.qhseScore >= 5 ? "HIGH" :
                   project.qhseScore >= 3 ? "MEDIUM" : "LOW"}
                </div>
              </div>
              <div className="text-center p-1.5 sm:p-2 bg-gray-50 dark:bg-gray-700 rounded">
                <div className="font-semibold text-gray-900 dark:text-gray-100 text-xs">KPI Status</div>
                <div className={`text-xs sm:text-sm font-bold ${
                  project.kpiStatus >= 90 ? "text-green-600" :
                  project.kpiStatus >= 70 ? "text-blue-600" :
                  project.kpiStatus >= 50 ? "text-yellow-600" : "text-red-600"
                }`}>
                  {Math.round(project.kpiStatus || 0)}%
                </div>
              </div>
              <div className="text-center p-1.5 sm:p-2 bg-gray-50 dark:bg-gray-700 rounded">
                <div className="font-semibold text-gray-900 dark:text-gray-100 text-xs">Quality</div>
                <div className={`text-xs sm:text-sm font-bold ${
                  project.rejectionRate <= 5 ? "text-green-600" :
                  project.rejectionRate <= 15 ? "text-yellow-600" : "text-red-600"
                }`}>
                  {Math.round(100 - (project.rejectionRate || 0))}%
                </div>
              </div>
            </div>

            {/* ✅ RESPONSIVE: QHSE Issues */}
            {project.qhseIssues && project.qhseIssues.length > 0 && (
              <div className="space-y-1 sm:space-y-2 pt-2 border-t border-red-200 dark:border-red-800">
                <div className="flex items-center gap-2">
                  <AlertTriangle size={12} className="text-red-500 flex-shrink-0" />
                  <div className="text-xs text-red-600 dark:text-red-400 uppercase tracking-wide font-semibold">
                    QHSE Issues
                  </div>
                </div>
                <ul className="space-y-1 text-xs max-h-20 sm:max-h-24 overflow-y-auto">
                  {project.qhseIssues.map((issue, idx) => (
                    <li key={idx} className="text-red-600 dark:text-red-400 flex items-start gap-1">
                      <span className="text-red-500 mt-0.5 flex-shrink-0">•</span>
                      <span className="break-words text-xs">{issue}</span>
                    </li>
                  ))}
                </ul>
              </div>
            )}

            {/* ✅ RESPONSIVE: Team Info */}
            {(project.qualityEngineer || project.client) && (
              <div className="space-y-1 sm:space-y-2">
                <div className="text-xs text-gray-500 dark:text-gray-400 uppercase tracking-wide">QHSE Team</div>
                <div className="space-y-1 text-xs sm:text-sm">
                  {project.qualityEngineer && (
                    <div className="flex items-center gap-1 sm:gap-2">
                      <User size={12} className="text-gray-400 flex-shrink-0" />
                      <span className="text-gray-600 dark:text-gray-300 flex-shrink-0">QE:</span>
                      <span className="font-medium truncate">{project.qualityEngineer}</span>
                    </div>
                  )}
                  {project.client && (
                    <div className="flex items-center gap-1 sm:gap-2">
                      <Building2 size={12} className="text-gray-400 flex-shrink-0" />
                      <span className="text-gray-600 dark:text-gray-300 flex-shrink-0">Client:</span>
                      <span className="font-medium truncate">{project.client}</span>
                    </div>
                  )}
                </div>
              </div>
            )}
          </div>
          
          {/* Arrow pointer */}
          <div className="absolute top-4 -left-1 w-2 h-2 bg-white dark:bg-gray-800 border-l border-b border-gray-200 dark:border-gray-600 transform rotate-45"></div>
        </div>
      )}
    </div>
  );
};

const QhseTimeline = ({ timelineData, className = "" }) => {
  // ✅ REAL DATA: Filter and validate projects at component level
  const validProjects = timelineData?.filter(project => 
    project && 
    project.name && 
    project.name !== "" && 
    project.name !== "N/A" &&
    typeof project.qhseScore === 'number'
  ) || [];

  // ✅ DEBUG: Log what we receive from REAL Google Sheets data
  React.useEffect(() => {
    console.log("🛡️ QHSE Timeline - Received LIVE data:", timelineData);
    console.log("✅ Valid projects:", validProjects.length);
    if (validProjects.length > 0) {
      console.log("📋 Sample project:", validProjects[0]);
    }
  }, [timelineData, validProjects]);

  return (
    <div className={`card col-span-1 lg:col-span-1 xl:col-span-3 ${className}`}>
      {/* ✅ FULLY RESPONSIVE: Header Section */}
      <div className="card-header flex-col p-3 sm:p-4 space-y-3">
        {/* ✅ Main Title Row */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
          <div className="flex items-center space-x-2">
            <Shield className="text-blue-600 flex-shrink-0" size={18} />
            <h3 className="card-title font-semibold text-sm sm:text-base truncate">
              QHSE Priority - Quality Attention Required
            </h3> 
          </div>
        </div>
        
        {/* ✅ QHSE-Focused Stats Row */}
        <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-2">
          <div className="flex flex-wrap items-center gap-2 justify-start sm:justify-end flex-1">
            {validProjects.length > 0 ? (
              <>
                {validProjects.filter(p => p.qhseScore >= 8).length > 0 && (
                  <span className="text-xs bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300 px-2 py-1 rounded-full animate-pulse whitespace-nowrap">
                    {validProjects.filter(p => p.qhseScore >= 8).length} critical
                  </span>
                )}
                {validProjects.filter(p => p.qhseScore >= 5 && p.qhseScore < 8).length > 0 && (
                  <span className="text-xs bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300 px-2 py-1 rounded-full whitespace-nowrap">
                    {validProjects.filter(p => p.qhseScore >= 5 && p.qhseScore < 8).length} high risk
                  </span>
                )}
                {validProjects.filter(p => p.qhseScore >= 3 && p.qhseScore < 5).length > 0 && (
                  <span className="text-xs bg-yellow-100 dark:bg-yellow-900/30 text-yellow-700 dark:text-yellow-300 px-2 py-1 rounded-full whitespace-nowrap">
                    {validProjects.filter(p => p.qhseScore >= 3 && p.qhseScore < 5).length} medium
                  </span>
                )}
                <span className="text-xs bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 px-2 py-1 rounded-full whitespace-nowrap">
                  {validProjects.length} showing
                </span>
              </>
            ) : (
              <span className="text-xs bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300 px-2 py-1 rounded-full whitespace-nowrap">
                ✅ All Compliant
              </span>
            )}
          </div>
        </div>
      </div>
      
      {/* ✅ FULLY RESPONSIVE: Card Body */}
      <div className="card-body space-y-2 sm:space-y-3 max-h-48 xs:max-h-56 sm:max-h-64 md:max-h-80 lg:max-h-96 xl:max-h-[28rem] overflow-y-auto p-2 sm:p-3 md:p-4">
        {validProjects.length > 0 ? (
          validProjects.map((project, index) => (
            <div
              key={project.id || index}
              className={`space-y-1.5 sm:space-y-2 p-2 sm:p-3 rounded-lg shadow-sm border hover:shadow-md transition-all duration-200 ${
                project.qhseScore >= 8 ? 
                  'bg-gradient-to-r from-red-50 to-red-25 dark:from-red-900/20 dark:to-red-800/10 border-red-200 dark:border-red-700' :
                project.qhseScore >= 5 ?
                  'bg-gradient-to-r from-orange-50 to-orange-25 dark:from-orange-900/20 dark:to-orange-800/10 border-orange-200 dark:border-orange-700' :
                  'bg-gradient-to-r from-blue-50 to-blue-25 dark:from-blue-900/20 dark:to-blue-800/10 border-blue-200 dark:border-blue-700'
              }`}
            >
              {/* ✅ OPTIMIZED: Project Header */}
              <div className="flex flex-col space-y-1.5 sm:space-y-0 sm:flex-row sm:justify-between sm:items-start">
                <div className="flex items-start gap-x-1.5 sm:gap-x-2 flex-1 min-w-0">
                  <div className="pt-0.5 flex-shrink-0">
                    <QHSEProjectTooltip project={project}>
                      {getQHSEStatusIcon(project.qhseStatus, project.qhseScore)}
                    </QHSEProjectTooltip>
                  </div>
                  <div className="flex-1 min-w-0">
                    {/* Project Title and Badges */}
                    <div className="flex flex-col space-y-1 sm:space-y-0 sm:flex-row sm:items-start sm:gap-2">
                      <span className="font-semibold text-gray-800 dark:text-slate-200 text-xs sm:text-sm leading-tight break-words">
                        {project.projectNo && project.projectNo !== "" && project.projectNo !== "N/A" 
                          ? `${project.projectNo} - ${project.name}` 
                          : project.name}
                      </span>
                      <div className="flex gap-0.5 sm:gap-1 flex-wrap">
                        {/* ✅ OPTIMIZED BADGES - No redundant icons */}
                        {project.carsOpen > 0 && (
                          <span className="inline-flex items-center gap-1 text-xs bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300 px-1 sm:px-2 py-0.5 rounded-full animate-pulse whitespace-nowrap">
                            <AlertTriangle size={12} className="flex-shrink-0" />
                            <span>{project.carsOpen} CARs</span>
                          </span>
                        )}
                        {project.obsOpen > 0 && (
                          <span className="inline-flex items-center gap-1 text-xs bg-orange-100 dark:bg-orange-900 text-orange-700 dark:text-orange-300 px-1 sm:px-2 py-0.5 rounded-full whitespace-nowrap">
                            <AlertCircle size={12} className="flex-shrink-0" />
                            <span>{project.obsOpen} Obs</span>
                          </span>
                        )}
                        {project.auditDelay > 0 && (
                          <span className="inline-flex items-center gap-1 text-xs bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300 px-1 sm:px-2 py-0.5 rounded-full animate-pulse whitespace-nowrap">
                            <Clock size={12} className="flex-shrink-0" />
                            <span>{project.auditDelay}d</span>
                          </span>
                        )}
                        {project.rejectionRate > 0 && (
                          <span className="inline-flex items-center gap-1 text-xs bg-red-100 dark:bg-red-900 text-red-700 dark:text-red-300 px-1 sm:px-2 py-0.5 rounded-full whitespace-nowrap">
                            <TrendingDown size={12} className="flex-shrink-0" />
                            <span>{Math.round(project.rejectionRate)}%</span>
                          </span>
                        )}
                        {project.qualityPlanStatus === "Pending" && (
                          <span className="inline-flex items-center gap-1 text-xs bg-yellow-100 dark:bg-yellow-900 text-yellow-700 dark:text-yellow-300 px-1 sm:px-2 py-0.5 rounded-full whitespace-nowrap">
                            <FileText size={12} className="flex-shrink-0" />
                            <span>QP</span>
                          </span>
                        )}
                      </div>
                    </div>

                    {/* ✅ OPTIMIZED: QHSE-Primary Metrics - Unique icons only */}
                    <div className="flex flex-wrap items-center gap-1 sm:gap-2 mt-1 text-xs">
                      <div className="inline-flex items-center gap-1 text-gray-600 dark:text-slate-400 whitespace-nowrap">
                        <CheckCircle2 size={12} className="flex-shrink-0" />
                        <span>Quality: {Math.round(100 - (project.rejectionRate || 0))}%</span>
                      </div>
                      <div className="inline-flex items-center gap-1 text-gray-600 dark:text-slate-400 whitespace-nowrap">
                        <TrendingUp size={12} className="flex-shrink-0" />
                        <span>Progress: {Math.round(project.progress || 0)}%</span>
                      </div>
                      <div className="inline-flex items-center gap-1 text-gray-600 dark:text-slate-400 whitespace-nowrap">
                        <Activity size={12} className="flex-shrink-0" />
                        <span>KPI: {Math.round(project.kpiStatus || 0)}%</span>
                      </div>
                      {project.qualityEngineer && (
                        <div className="inline-flex items-center gap-1 text-gray-600 dark:text-slate-400 whitespace-nowrap">
                          <User size={12} className="flex-shrink-0" />
                          <span className="truncate max-w-16 sm:max-w-24 md:max-w-32">{project.qualityEngineer}</span>
                        </div>
                      )}
                    </div>
                  </div>
                </div>
                
                {/* ✅ OPTIMIZED: Progress and Risk Score */}
                <div className="flex items-center justify-between sm:justify-end gap-1.5 sm:gap-2 sm:flex-col sm:items-end sm:space-y-1">
                  <span className="text-base sm:text-lg font-bold text-gray-800 dark:text-slate-200 whitespace-nowrap">
                    {Math.round(project.progress || 0)}%
                  </span>
                  <span className={`text-xs px-1 sm:px-2 py-0.5 sm:py-1 rounded-full font-bold whitespace-nowrap ${
                    project.qhseScore >= 8 ? 'bg-red-100 dark:bg-red-900/30 text-red-700 dark:text-red-300' :
                    project.qhseScore >= 5 ? 'bg-orange-100 dark:bg-orange-900/30 text-orange-700 dark:text-orange-300' : 
                    project.qhseScore >= 3 ? 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-700 dark:text-yellow-300' : 
                    'bg-green-100 dark:bg-green-900/30 text-green-700 dark:text-green-300'
                  }`}>
                    Risk: {project.qhseScore || 0}
                  </span>
                </div>
              </div>

              {/* ✅ OPTIMIZED: Progress Bar */}
              <div className="flex items-center space-x-1 sm:space-x-2">
                <Progress
                  value={project.progress || 0}
                  className="flex-1 h-1.5 sm:h-2 rounded-full"
                />
                {project.qhseIssues && project.qhseIssues.length > 0 && (
                  <span className="text-xs text-red-600 dark:text-red-400 font-semibold whitespace-nowrap">
                    {project.qhseIssues.length} issues
                  </span>
                )}
                {project.costOfPoorQualityAED > 0 && (
                  <span className="text-xs text-red-600 dark:text-red-400 font-semibold whitespace-nowrap hidden sm:inline">
                    {project.costOfPoorQualityAED.toLocaleString()} AED
                  </span>
                )}
              </div>

              {/* ✅ OPTIMIZED: QHSE Status - Single icon per status */}
              <div className="text-xs flex flex-col space-y-1 sm:space-y-0 sm:flex-row sm:items-center sm:justify-between">
                <div className="flex items-center gap-x-1 min-w-0">
                  {project.carsOpen > 0 || project.obsOpen > 0 || project.auditDelay > 0 ? (
                    <>
                      <AlertTriangle className="text-red-500 animate-pulse flex-shrink-0" size={14} />
                      <span className="text-red-600 font-bold bg-red-100 dark:bg-red-900/30 px-2 py-1 rounded break-words">
                        URGENT: {project.carsOpen || 0} CARs, {project.obsOpen || 0} Obs
                        {project.auditDelay > 0 && `, ${project.auditDelay}d delay`}
                      </span>
                    </>
                  ) : project.qualityPlanStatus === "Pending" ? (
                    <>
                      <FileText className="text-orange-500 flex-shrink-0" size={14} />
                      <span className="text-orange-600 font-semibold break-words">
                        Quality Plan Pending
                      </span>
                    </>
                  ) : (
                    <>
                      <Shield className="text-green-500 flex-shrink-0" size={14} />
                      <span className="text-green-600 font-semibold">QHSE Compliant</span>
                    </>
                  )}
                </div>
                
                {/* ✅ Quality Engineer Info */}
                {project.qualityEngineer && (
                  <div className="inline-flex items-center gap-1 justify-start sm:justify-end flex-shrink-0">
                    <User size={12} className="text-blue-500 flex-shrink-0" />
                    <span className="text-blue-600 dark:text-blue-400 font-medium truncate max-w-20 sm:max-w-none">
                      {project.qualityEngineer}
                    </span>
                  </div>
                )}
              </div>
            </div>
          ))
        ) : (
          <div className="text-center text-gray-400 py-4 sm:py-6 md:py-8">
            <Shield className="mx-auto mb-2 sm:mb-4 text-3xl sm:text-4xl md:text-6xl text-green-400" />
            <p className="font-medium text-green-600 text-sm sm:text-base md:text-lg">Excellent QHSE Performance!</p>
            <p className="text-xs sm:text-sm text-gray-500 mt-1 sm:mt-2">All projects are QHSE compliant</p>
            <p className="text-xs text-gray-400 mt-1">Data refreshed from Google Sheets</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default QhseTimeline;

import React from 'react'
import { MainHeader } from "../Common/MainHeader"
import { LoadingState } from "../Common/LoadingState"
import { ErrorState } from "../Common/ErrorState"
import { EmptyDataState } from "../Common/EmptyDataState"

import QHSEOverviewChart from "./OverviewChart"
import QhseTimeline from "./QhseTimeline"
import ProjectStatus from "./ProjectStatus"

import { 
  getMonthlyOverviewData, 
  getYearlyOverviewData 
} from "../../utils"
import { generateQHSETimelineData } from "../../utils/chartUtils"
import { PageLayout } from '@/layouts/PageLayout'
import { useQHSERunningProjects } from '../../hooks/excel-data/use-qhse-running-projects'
import DashSummaryCard from './DashSummaryCard'

const DashboardPage = () => {
  // Hooks
  const { theme } = useTheme()
  const { 
    data: projectsData, 
    loading, 
    isRefreshing, 
    error, 
    refetch, 
    lastUpdated,
    dataLastChanged 
  } = useQHSERunningProjects();

  const chartData = React.useMemo(() => {
    if (!projectsData || projectsData.length === 0) {
      return { monthlyData: [], yearlyData: [], timelineData: [] }
    }
    const qhseTimelineData = generateQHSETimelineData(projectsData);

    return {
      monthlyData: getMonthlyOverviewData(projectsData),
      yearlyData: getYearlyOverviewData(projectsData),
      timelineData: qhseTimelineData
    }
  }, [projectsData])

  React.useEffect(() => {
    console.log("🛡️ Dashboard - Generated QHSE timeline data:", chartData.timelineData);
  }, [chartData.timelineData]);

  // Loading state
  if (loading) {
    return (
      <PageLayout>
        <MainHeader />
        <LoadingState message="Loading Google Sheets data..." />
      </PageLayout>
    )
  }

  // Error state
  if (error) {
    return (
      <PageLayout>
        <MainHeader />
        <ErrorState error={error} onRetry={refetch} />
      </PageLayout>
    )
  }

  // Empty state
  if (!projectsData || projectsData.length === 0) {
    return (
      <PageLayout>
        <MainHeader />
        <EmptyDataState />
      </PageLayout>
    )
  }

  // Main dashboard
  return (
    <PageLayout>
      <MainHeader 
        title="QHSE Dashboard"
        subtitle={`Monitoring for Project QHSE pending Activities `}
        lastUpdated={lastUpdated}
        dataLastChanged={dataLastChanged} // ✅ CHANGED: Pass dataLastChanged
        isRefreshing={isRefreshing}
        className="mb-4 sm:mb-5 md:mb-6"
      />
      
      <DashboardContent 
        projectsData={projectsData}
        chartData={chartData}
        loading={loading}
        onRefresh={refetch}
      />
      
      {/* Footer can be added if needed */}
    </PageLayout>
  )
}

const DashboardContent = ({ projectsData, chartData, loading, onRefresh }) => (
  <div className="space-y-4 sm:space-y-5 md:space-y-6 lg:space-y-7 xl:space-y-8">
    {/* Summary Cards Section  */}
    <section className="w-full">
      <DashSummaryCard projectsData={projectsData} />
    </section>
    
    {/* Charts Section  */}
    <section className="w-full">
      <ChartsGrid 
        monthlyData={chartData.monthlyData}
        yearlyData={chartData.yearlyData}
        timelineData={chartData.timelineData}
      />
    </section>
    
    {/* Project Status Section  */}
    <section className="w-full">
