  };

  const handleCloseModal = () => {
    setModalOpen(false);
    setModalTitle('');
    setModalData([]);
    setIsFullScreen(false);
  };

  const toggleFullScreen = () => {
    setIsFullScreen(!isFullScreen);
  };

  // Cards config
  const summaryCards = [
    {
      title: "Total Spot Checks",
