          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-4">
            {summaryCards.map((item, index) => (
              <OverviewCard
                key={index}
                title={item.title}
                value={item.value}
                 valueColor={getValueClasses(item.color)}
                description={item.description}
                icon={item.icon}
