export default SpotCheckSummaryCards;

import React, { useRef, useState, useMemo } from 'react';
import { Card, CardContent } from '../ui/Card';
import { Badge } from '../ui/Badge';
import {
  AlertTriangle,
  Clock,
  BarChart2,
  DollarSign,
  Eye
} from 'lucide-react';

// ✅ CORRECTED: Update thresholds for over-billability focus
const THRESHOLDS = {
  CARS_CRITICAL: 5,
  CARS_HIGH: 3,
  AUDIT_CRITICAL: 10,
  AUDIT_HIGH: 5,
  KPI_CRITICAL: 60,
  KPI_HIGH: 70,
  // ✅ FIXED: Over-billability thresholds (high values are the problem)
  BILLABILITY_CRITICAL: 120,  // Over 120% is critical
  BILLABILITY_HIGH: 100,      // Over 100% is high risk
  OBS_CRITICAL_DELAY: 14,
  OBS_HIGH_DELAY: 7,
  OBS_HIGH_COUNT: 10
};

const iconMap = {
  CARs: <AlertTriangle className="w-7 h-7 text-red-500 drop-shadow" />,
  Audit: <Clock className="w-7 h-7 text-orange-500 drop-shadow" />,
  KPI: <BarChart2 className="w-7 h-7 text-red-500 drop-shadow" />,
  Billability: <DollarSign className="w-7 h-7 text-yellow-500 drop-shadow" />,
  Observations: <Eye className="w-7 h-7 text-orange-500 drop-shadow" />
};

const issueTypeMap = {
  "Critical CARs": "CARs",
  "Audit Delays": "Audit",
  "Poor KPI Performance": "KPI",
  "Billability Issues": "Billability"
};

// ✅ OPTIMIZED: Helper functions moved outside component
const parsePercentage = (value) => {
  if (!value || value === '' || value === 'N/A') return 0;
  const numericValue = parseFloat(value.toString().replace('%', ''));
  return isNaN(numericValue) ? 0 : numericValue;
};

const parseNumber = (value) => {
  if (!value || value === '' || value === 'N/A') return 0;
  const numericValue = Number(value);
  return isNaN(numericValue) ? 0 : numericValue;
};

const CriticalIssues = ({ filteredProjects }) => {
  const [selectedType, setSelectedType] = useState(null);
  const detailsRef = useRef(null);

  // ✅ OPTIMIZED: Memoized critical issues detection
  const criticalIssues = useMemo(() => {
    if (!filteredProjects?.length) return [];

    const issues = [];

    filteredProjects.forEach(project => {
      // Parse values once per project
      const projectData = {
        carsOpen: parseNumber(project.carsOpen),
        carsDelayedClosingNoDays: parseNumber(project.carsDelayedClosingNoDays),
        delayInAuditsNoDays: parseNumber(project.delayInAuditsNoDays),
        projectKPIsAchievedPercent: parsePercentage(project.projectKPIsAchievedPercent),
        qualityBillabilityPercent: parsePercentage(project.qualityBillabilityPercent),
        obsOpen: parseNumber(project.obsOpen),
        obsDelayedClosingNoDays: parseNumber(project.obsDelayedClosingNoDays),
        projectTitle: project.projectTitle || 'Unnamed Project',
        projectNo: project.projectNo || project.srNo || 'No Project Number'
      };

      // ✅ STREAMLINED: CARs Issues
      if (projectData.carsOpen > THRESHOLDS.CARS_CRITICAL) {
        issues.push({
          type: 'CARs',
          severity: 'Critical',
          title: `${projectData.carsOpen} Open CARs`,
          project: projectData.projectTitle,
          projectNo: projectData.projectNo,
          details: projectData.carsDelayedClosingNoDays > 0 
            ? `${projectData.carsDelayedClosingNoDays} days delayed closing`
            : 'Multiple open CARs requiring attention',
          count: projectData.carsOpen,
          sortValue: projectData.carsOpen
        });
      } else if (projectData.carsOpen >= THRESHOLDS.CARS_HIGH) {
        issues.push({
          type: 'CARs',
          severity: 'High',
          title: `${projectData.carsOpen} Open CARs`,
          project: projectData.projectTitle,
          projectNo: projectData.projectNo,
          details: projectData.carsDelayedClosingNoDays > 0 
            ? `${projectData.carsDelayedClosingNoDays} days delayed closing`
            : 'Several open CARs need attention',
          count: projectData.carsOpen,
          sortValue: projectData.carsOpen
        });
      }

      // ✅ STREAMLINED: Audit Issues
      if (projectData.delayInAuditsNoDays > THRESHOLDS.AUDIT_CRITICAL) {
        issues.push({
          type: 'Audit',
          severity: 'Critical',
          title: `Audit Delayed ${projectData.delayInAuditsNoDays} Days`,
          project: projectData.projectTitle,
          projectNo: projectData.projectNo,
          details: 'Critical audit timeline breach requiring immediate action',
          count: projectData.delayInAuditsNoDays,
          sortValue: projectData.delayInAuditsNoDays
        });
      } else if (projectData.delayInAuditsNoDays >= THRESHOLDS.AUDIT_HIGH) {
        issues.push({
          type: 'Audit',
          severity: 'High',
          title: `Audit Delayed ${projectData.delayInAuditsNoDays} Days`,
          project: projectData.projectTitle,
          projectNo: projectData.projectNo,
          details: 'Audit schedule needs attention',
          count: projectData.delayInAuditsNoDays,
          sortValue: projectData.delayInAuditsNoDays
        });
      }

      // ✅ STREAMLINED: KPI Issues
      if (projectData.projectKPIsAchievedPercent > 0) {
        if (projectData.projectKPIsAchievedPercent < THRESHOLDS.KPI_CRITICAL) {
          issues.push({
            type: 'KPI',
            severity: 'Critical',
            title: `KPI Achievement: ${projectData.projectKPIsAchievedPercent}%`,
            project: projectData.projectTitle,
            projectNo: projectData.projectNo,
            details: 'Significantly below acceptable performance threshold',
            count: projectData.projectKPIsAchievedPercent,
            sortValue: 100 - projectData.projectKPIsAchievedPercent
          });
        } else if (projectData.projectKPIsAchievedPercent < THRESHOLDS.KPI_HIGH) {
          issues.push({
            type: 'KPI',
            severity: 'High',
            title: `KPI Achievement: ${projectData.projectKPIsAchievedPercent}%`,
            project: projectData.projectTitle,
            projectNo: projectData.projectNo,
            details: 'Below target performance threshold',
            count: projectData.projectKPIsAchievedPercent,
            sortValue: 100 - projectData.projectKPIsAchievedPercent
          });
        }
      }

      // ✅ CORRECTED: Billability Issues Logic
      if (projectData.qualityBillabilityPercent > 0) {
        if (projectData.qualityBillabilityPercent > THRESHOLDS.BILLABILITY_CRITICAL) {
          issues.push({
            type: 'Billability',
            severity: 'Critical',
            title: `Quality Billability: ${projectData.qualityBillabilityPercent}%`,
            project: projectData.projectTitle,
            projectNo: projectData.projectNo,
            details: 'Critical over-billability - potential scope creep and budget impact',
            count: projectData.qualityBillabilityPercent,
            sortValue: projectData.qualityBillabilityPercent // Higher values = worse
          });
        } else if (projectData.qualityBillabilityPercent > THRESHOLDS.BILLABILITY_HIGH) {
          issues.push({
            type: 'Billability',
            severity: 'High',
            title: `Quality Billability: ${projectData.qualityBillabilityPercent}%`,
            project: projectData.projectTitle,
            projectNo: projectData.projectNo,
            details: 'Over-billability detected - monitor for scope creep',
            count: projectData.qualityBillabilityPercent,
            sortValue: projectData.qualityBillabilityPercent
          });
        }
      }

      // ✅ STREAMLINED: Observation Issues
      if (projectData.obsDelayedClosingNoDays > THRESHOLDS.OBS_CRITICAL_DELAY) {
        issues.push({
          type: 'Observations',
          severity: 'Critical',
          title: `${projectData.obsOpen} Open Observations`,
          project: projectData.projectTitle,
          projectNo: projectData.projectNo,
          details: `${projectData.obsDelayedClosingNoDays} days delayed - critical overdue`,
          count: projectData.obsOpen,
          sortValue: projectData.obsDelayedClosingNoDays
        });
      } else if (projectData.obsDelayedClosingNoDays >= THRESHOLDS.OBS_HIGH_DELAY) {
        issues.push({
          type: 'Observations',
          severity: 'Medium',
          title: `${projectData.obsOpen} Open Observations`,
          project: projectData.projectTitle,
          projectNo: projectData.projectNo,
          details: `${projectData.obsDelayedClosingNoDays} days delayed closing`,
          count: projectData.obsOpen,
          sortValue: projectData.obsDelayedClosingNoDays
        });
      } else if (projectData.obsOpen > THRESHOLDS.OBS_HIGH_COUNT) {
        issues.push({
          type: 'Observations',
          severity: 'High',
          title: `${projectData.obsOpen} Open Observations`,
          project: projectData.projectTitle,
          projectNo: projectData.projectNo,
          details: 'High volume of open observations requiring attention',
          count: projectData.obsOpen,
          sortValue: projectData.obsOpen
        });
      }
    });

    // Sort by severity and then by sort value
    return issues.sort((a, b) => {
      const severityOrder = { 'Critical': 3, 'High': 2, 'Medium': 1 };
      const severityDiff = severityOrder[b.severity] - severityOrder[a.severity];
      if (severityDiff !== 0) return severityDiff;
      return b.sortValue - a.sortValue;
    });
  }, [filteredProjects]);

  // ✅ OPTIMIZED: Memoized summary data
  const issuesData = useMemo(() => [
    {
      title: "Critical CARs",
      bgColor: "bg-gradient-to-br from-red-50 via-white to-red-100 dark:from-red-950 dark:via-slate-900 dark:to-red-900",
      textColor: "text-red-800 dark:text-red-200",
      countColor: "text-red-600 dark:text-red-400",
      borderColor: "border-red-200 dark:border-red-800"
    },
    {
      title: "Audit Delays",
      count: filteredProjects.filter(p => parseNumber(p.delayInAuditsNoDays) > THRESHOLDS.AUDIT_CRITICAL).length,
      description: `Audits delayed >${THRESHOLDS.AUDIT_CRITICAL} days`,
      icon: <Clock className="w-8 h-8 text-orange-500 drop-shadow" />,
      bgColor: "bg-gradient-to-br from-orange-50 via-white to-orange-100",
      textColor: "text-orange-800",
      countColor: "text-orange-600",
      borderColor: "border-orange-200"
    },
    {
      title: "Poor KPI Performance",
      count: filteredProjects.filter(p => {
        const kpiPercent = parsePercentage(p.projectKPIsAchievedPercent);
        return kpiPercent > 0 && kpiPercent < THRESHOLDS.KPI_HIGH;
      }).length,
      description: `KPI achievement <${THRESHOLDS.KPI_HIGH}%`,
      icon: <BarChart2 className="w-8 h-8 text-red-500 drop-shadow" />,
      bgColor: "bg-gradient-to-br from-red-50 via-white to-red-100",
      textColor: "text-red-800",
      countColor: "text-red-600",
      borderColor: "border-red-200"
    },
    {
      title: "Billability Issues",
      // ✅ FIXED: Count projects with over-billability (high values)
      count: filteredProjects.filter(p => {
        const billabilityPercent = parsePercentage(p.qualityBillabilityPercent);
        return billabilityPercent > THRESHOLDS.BILLABILITY_HIGH;
      }).length,
      description: `Quality billability >${THRESHOLDS.BILLABILITY_HIGH}%`, // ✅ FIXED: Show over-billability
      icon: <DollarSign className="w-8 h-8 text-yellow-500 drop-shadow" />,
      bgColor: "bg-gradient-to-br from-yellow-50 via-white to-yellow-100",
      textColor: "text-yellow-800",
      countColor: "text-yellow-600",
      borderColor: "border-yellow-200"
    }
  ], [filteredProjects]);

  // ✅ OPTIMIZED: Memoized filtered details
  const filteredDetails = useMemo(() => 
    selectedType ? criticalIssues.filter(issue => issue.type === selectedType) : criticalIssues,
    [criticalIssues, selectedType]
  );

  const handleViewDetails = (type) => {
    setSelectedType(type);
    setTimeout(() => {
      detailsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, 100);
  };

  // ✅ EARLY RETURN: Show nothing if no projects
  if (!filteredProjects?.length) {
    return null;
  }

  return (
    <div className="space-y-6">
      {/* Summary Cards */}
      <Card>
        <CardContent className="p-6">
          <h3 className="text-lg font-semibold mb-4 text-gray-800 dark:text-gray-100 flex items-center gap-2">
            <AlertTriangle className="w-6 h-6 text-red-500" />
            Critical Issues Overview
          </h3>
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            {issuesData.map((issue, index) => (
              <div
                key={index}
                className={`
                  ${issue.bgColor} dark:bg-gradient-to-br dark:from-gray-900 dark:via-gray-800 dark:to-gray-900
                  p-4 rounded-lg border ${issue.borderColor} dark:border-gray-700
                  hover:shadow-md transition-shadow flex flex-col h-full min-h-[180px]
                `}
              >
                <div className="flex items-center justify-between mb-2">
                  <h4 className={`font-semibold ${issue.textColor} dark:text-gray-100 text-base`}>{issue.title}</h4>
                </div>
                <div className="flex-1 flex flex-col justify-between">
                  <div>
                    <div className="flex items-center gap-2 mb-1">
                      <span>{issue.icon}</span>
                      <p className={`text-3xl font-bold ${issue.countColor} dark:text-white`}>{issue.count}</p>
                    </div>
                    <p className={`text-sm ${issue.textColor} dark:text-gray-300`}>{issue.description}</p>
                  </div>
                  {issue.count > 0 && (
                    <div className="mt-3">
                      <button
                        className="text-xs bg-white dark:bg-gray-800 px-2 py-1 rounded border border-gray-200 dark:border-gray-700 hover:bg-gray-50 dark:hover:bg-gray-700 transition-colors font-medium text-gray-700 dark:text-gray-200"
                        onClick={() => handleViewDetails(issueTypeMap[issue.title])}
                      >
                        View Details →
                      </button>
                    </div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Detailed Critical Issues */}
      {criticalIssues.length > 0 && (
        <Card ref={detailsRef}>
          <CardContent className="p-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between mb-4 gap-2">
              <h3 className="text-lg font-semibold text-gray-800 dark:text-gray-100 flex items-center gap-2">
                <AlertTriangle className="w-6 h-6 text-red-500" />
                Detailed Critical Issues ({filteredDetails.length})
              </h3>
              {selectedType && (
                <button
                  className="text-xs px-3 py-1 rounded bg-gray-100 dark:bg-gray-800 hover:bg-gray-200 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-200 border border-gray-200 dark:border-gray-700 font-medium transition-colors"
                  onClick={() => setSelectedType(null)}
                >
                  Show All ({criticalIssues.length})
                </button>
              )}
            </div>
            <div className="space-y-3 max-h-96 overflow-y-auto">
              {filteredDetails.length === 0 && (
                <div className="text-gray-500 dark:text-gray-400 text-sm text-center py-8">
                  {selectedType ? 
                    `No ${selectedType} issues found in current data.` :
                    '🎉 No critical issues found! All projects are performing well.'
                  }
                </div>
              )}
              {filteredDetails.map((issue, index) => (
                <div
                  key={index}
                  className="p-4 rounded-lg border bg-white dark:bg-gray-900 border-gray-200 dark:border-gray-800 hover:shadow-md transition-shadow flex flex-col sm:flex-row justify-between items-start"
                >
                  <div className="flex items-start space-x-3 flex-1 min-w-0">
                    <span>{iconMap[issue.type]}</span>
                    <div className="min-w-0">
                      <div className="flex items-center space-x-2 mb-1 flex-wrap">
                        <h4 className="font-semibold text-sm text-gray-800 dark:text-gray-100 break-words">{issue.title}</h4>
                        <Badge variant={
                          issue.severity === 'Critical' ? 'destructive' :
                          issue.severity === 'High' ? 'warning' : 'secondary'
                        }>
                          {issue.severity}
                        </Badge>
                      </div>
                      <p className="text-sm font-medium text-gray-700 dark:text-gray-200 break-words">{issue.project}</p>
                      <p className="text-xs opacity-75 text-gray-500 dark:text-gray-400 break-words">Project No: {issue.projectNo}</p>
                      <p className="text-xs mt-1 text-gray-600 dark:text-gray-300 break-words">{issue.details}</p>
                    </div>
                  </div>
                  <div className="text-right mt-3 sm:mt-0 sm:ml-4 flex-shrink-0">
                    <div className="text-lg font-bold text-gray-800 dark:text-gray-100">{issue.count}</div>
                    <div className="text-xs opacity-75 text-gray-500 dark:text-gray-400">{issue.type}</div>
                  </div>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default CriticalIssues;

import React from 'react';
import { Card, CardContent } from '../ui/Card';
import { Badge } from '../ui/Badge';
import {
  Calendar as CalendarIcon,
  Users as UsersIcon,
  TrendingUp as TrendingUpIcon,
  Filter as FilterIcon,
  RefreshCw as RefreshIcon
} from 'lucide-react';

// Month names array (moved from data file since it's static)
const monthNames = [
  'January', 'February', 'March', 'April', 'May', 'June',
  'July', 'August', 'September', 'October', 'November', 'December'
];

const Filters = ({
  selectedYear,
  setSelectedYear,
  selectedMonth,
  setSelectedMonth,
  selectedClient,
  setSelectedClient,
  selectedKPIStatus,
  setSelectedKPIStatus,
  resetFilters,
  filteredProjects,
  getUniqueYears,
  getUniqueClients,
  totalProjects // Add this prop to get total count from Google Sheets
}) => {
  return (
    <Card className="mb-6 dark:bg-gray-900 dark:border-gray-800">
      <CardContent className="p-4">
        <div className="flex flex-col sm:flex-row flex-wrap gap-2 sm:gap-4 gap-y-3 items-center">
          <h3 className="text-lg font-semibold text-gray-900 dark:text-gray-100 flex items-center mb-2 sm:mb-0">
            <FilterIcon className="w-5 h-5 mr-2 text-blue-500" />
            Filters
          </h3>

          {/* Year Filter */}
          <div className="flex items-center space-x-2 w-full sm:w-auto">
            <CalendarIcon className="w-4 h-4 text-blue-500" />
            <label className="text-sm font-medium text-gray-700 dark:text-gray-200">Year:</label>
            <select
              aria-label="Filter by year"
              value={selectedYear}
              onChange={(e) => setSelectedYear(e.target.value)}
              className="w-full sm:w-auto px-3 py-1 border border-gray-300 dark:border-gray-700 rounded-md text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">All Years</option>
              {getUniqueYears().map(year => (
                <option key={year} value={year.toString()}>{year}</option>
              ))}
            </select>
          </div>

          {/* Month Filter */}
          <div className="flex items-center space-x-2 w-full sm:w-auto">
            <CalendarIcon className="w-4 h-4 text-blue-500" />
            <label className="text-sm font-medium text-gray-700 dark:text-gray-200">Month:</label>
            <select
              aria-label="Filter by month"
              value={selectedMonth}
              onChange={(e) => setSelectedMonth(e.target.value)}
              className="w-full sm:w-auto px-3 py-1 border border-gray-300 dark:border-gray-700 rounded-md text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">All Months</option>
              {monthNames.map((month, index) => (
                <option key={index + 1} value={(index + 1).toString()}>{month}</option>
              ))}
            </select>
          </div>

          {/* Client Filter */}
          <div className="flex items-center space-x-2 w-full sm:w-auto">
            <UsersIcon className="w-4 h-4 text-blue-500" />
            <label className="text-sm font-medium text-gray-700 dark:text-gray-200">Client:</label>
            <select
              aria-label="Filter by client"
              value={selectedClient}
              onChange={(e) => setSelectedClient(e.target.value)}
              className="w-full sm:w-auto px-3 py-1 border border-gray-300 dark:border-gray-700 rounded-md text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">All Clients</option>
              {getUniqueClients().map(client => (
                <option key={client} value={client}>{client}</option>
              ))}
            </select>
          </div>

          {/* KPI Status Filter */}
          <div className="flex items-center space-x-2 w-full sm:w-auto">
            <TrendingUpIcon className="w-4 h-4 text-blue-500" />
            <label className="text-sm font-medium text-gray-700 dark:text-gray-200">KPI Status:</label>
            <select
              aria-label="Filter by KPI status"
              value={selectedKPIStatus}
              onChange={(e) => setSelectedKPIStatus(e.target.value)}
              className="w-full sm:w-auto px-3 py-1 border border-gray-300 dark:border-gray-700 rounded-md text-sm bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="all">All Status</option>
              <option value="Green">🟢 Green</option>
              <option value="Yellow">🟡 Yellow</option>
              <option value="Red">🔴 Red</option>
            </select>
          </div>

          {/* Reset Button */}
          <button
            onClick={resetFilters}
            aria-label="Reset all filters"
            className="flex items-center px-4 py-1 w-full sm:w-auto bg-blue-50 dark:bg-gray-800 text-blue-700 dark:text-blue-300 rounded-md text-sm hover:bg-blue-100 dark:hover:bg-gray-700 focus:outline-none focus:ring-2 focus:ring-blue-500 transition-colors"
            title="Reset all filters"
          >
            <RefreshIcon className="w-4 h-4 mr-1" />
            Reset
          </button>

          {/* Results Counter - Now uses Google Sheets data */}
          <div className="flex items-center space-x-2 w-full sm:w-auto">
            <span className="text-xs font-medium text-blue-700 dark:text-blue-200 bg-blue-100 dark:bg-gray-800 px-3 py-1 rounded-full border border-blue-200 dark:border-gray-700">
              📊 {filteredProjects.length} of {totalProjects || 0} projects
            </span>
          </div>
        </div>

        {/* Active Filters Display */}
        {(selectedYear !== "all" || selectedMonth !== "all" || selectedClient !== "all" || selectedKPIStatus !== "all") && (
          <div className="mt-4 pt-4 border-t border-gray-100 dark:border-gray-700">
            <div className="flex flex-wrap items-center gap-2">
              <span className="text-sm font-medium text-gray-700 dark:text-gray-200 flex items-center">
                <FilterIcon className="w-4 h-4 mr-1 text-blue-500" />
                Active Filters:
              </span>
              {selectedYear !== "all" && (
                <Badge variant="blue" className="flex items-center gap-1 dark:bg-gray-800 dark:text-blue-300">
                  <CalendarIcon className="w-3 h-3 text-blue-400" />
                  {selectedYear}
                </Badge>
              )}
              {selectedMonth !== "all" && (
                <Badge variant="blue" className="flex items-center gap-1 dark:bg-gray-800 dark:text-blue-300">
                  <CalendarIcon className="w-3 h-3 text-blue-400" />
                  {monthNames[parseInt(selectedMonth) - 1]}
                </Badge>
              )}
              {selectedClient !== "all" && (
                <Badge variant="blue" className="flex items-center gap-1 dark:bg-gray-800 dark:text-blue-300">
                  <UsersIcon className="w-3 h-3 text-blue-400" />
                  {selectedClient}
                </Badge>
              )}
              {selectedKPIStatus !== "all" && (
                <Badge variant="blue" className="flex items-center gap-1 dark:bg-gray-800 dark:text-blue-300">
                  <TrendingUpIcon className="w-3 h-3 text-blue-400" />
                  {selectedKPIStatus}
                </Badge>
              )}
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
};

export default Filters;

import React, { useState, useEffect } from 'react'
import SummaryCards from './SummayCards'
import Charts from '../charts/Charts'
import CriticalIssues from './CriticalIssues'
import Filters from './Filters'
import { Card, CardContent } from '../ui/Card'
import { useQHSERunningProjects } from '../../hooks/useQHSEProjects'
import { SearchX, BarChart2, Upload, Maximize2, Minimize2, RefreshCw, Plus } from 'lucide-react'
import { Button, IconButton, Tooltip } from '@mui/material'

// Import reusable components (same as DashboardPage)
import {  MainHeader } from "../Common/MainHeader"
import { LoadingState } from "../Common/LoadingState"
import { ErrorState } from "../Common/ErrorState"
import { EmptyDataState } from "../Common/EmptyDataState"
import { PageLayout } from '@/layouts/PageLayout'
import BulkUploadModal from '../Common/BulkUploadModal'
import { ProjectEditModal } from '../Common/ProjectEditModal'

import {
  getUniqueYears,
  getUniqueClients,
  createProjectFilters,
  calculateProjectMetrics,
  generateKPIStatusData,
  // generateManhoursData, // ✅ COMMENTED: Moved to BillabilityPage
  generateAuditStatusData,
  generateCarsObsData,
  generateTimelineData,
  generateQualityPlanStatusData,
  getKPIBadgeVariant
} from '../../utils'

const SummaryView = () => {
  const { data: projectsData, loading, error, lastUpdated, refetch, isRefreshing } = useQHSERunningProjects();

  const [selectedYear, setSelectedYear] = useState("all")
  const [selectedMonth, setSelectedMonth] = useState("all")
  const [selectedClient, setSelectedClient] = useState("all")
  const [selectedKPIStatus, setSelectedKPIStatus] = useState("all")
  const [uploadModalOpen, setUploadModalOpen] = useState(false)
  const [createModalOpen, setCreateModalOpen] = useState(false)
  const [isFullscreen, setIsFullscreen] = useState(false)
  const [autoRefreshEnabled, setAutoRefreshEnabled] = useState(true)

  // Auto-refresh every 30 seconds when enabled
  useEffect(() => {
    if (!autoRefreshEnabled) return;
    
    const interval = setInterval(() => {
      console.log('🔄 Auto-refreshing QHSE data...');
      refetch();
    }, 30000); // 30 seconds
    
    return () => clearInterval(interval);
  }, [autoRefreshEnabled, refetch]);

  // Toggle fullscreen mode
  const toggleFullscreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullscreen(true);
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
        setIsFullscreen(false);
      }
    }
  };

  // Listen for fullscreen changes
  useEffect(() => {
    const handleFullscreenChange = () => {
      setIsFullscreen(!!document.fullscreenElement);
    };
    
    document.addEventListener('fullscreenchange', handleFullscreenChange);
    return () => document.removeEventListener('fullscreenchange', handleFullscreenChange);
  }, [])

  
  // Filter projects using utility function
  const filteredProjects = projectsData ? projectsData.filter(
    createProjectFilters(selectedYear, selectedMonth, selectedClient, selectedKPIStatus)
  ) : [];

  // Reset filters function
  const resetFilters = () => {
    setSelectedYear("all");
    setSelectedMonth("all");
    setSelectedClient("all");
    setSelectedKPIStatus("all");
  };

  // Calculate metrics using utility functions
  const projectMetrics = calculateProjectMetrics(filteredProjects);

  const chartData = {
    kpiStatus: generateKPIStatusData(filteredProjects),
    // manhours: generateManhoursData(filteredProjects), // ✅ COMMENTED: Now available in BillabilityPage
    auditStatus: generateAuditStatusData(filteredProjects),
    carsObs: generateCarsObsData(filteredProjects),
    timeline: generateTimelineData(filteredProjects),
    qualityPlanStatus: generateQualityPlanStatusData(filteredProjects)
  };

  // Debug: Log chart data
  console.log('📊 Chart Data Generated:', {
    kpiStatus: chartData.kpiStatus?.length || 0,
    auditStatus: chartData.auditStatus?.length || 0,
    carsObs: chartData.carsObs?.length || 0,
    timeline: chartData.timeline?.length || 0,
    qualityPlanStatus: chartData.qualityPlanStatus?.length || 0,
    filteredProjectsCount: filteredProjects.length
  });


  // Loading state
  if (loading) {
    return (
      <PageLayout>
        <MainHeader/>
        <LoadingState message="Loading Google Sheets data..." />
      </PageLayout>
    )
  }

  // Error state
  if (error) {
    return (
      <PageLayout>
        <MainHeader 
          title="Dashboard Summary"
          subtitle="Error loading data from Google Sheets"
        />
        <ErrorState error={error} onRetry={refetch} />
      </PageLayout>
    )
  }

  // Empty state (no data at all)
  if (!projectsData || projectsData.length === 0) {
    return (
      <PageLayout>
        <MainHeader/>
        <EmptyDataState />
      </PageLayout>
    )
  }

  
  return (
    <PageLayout>
      {/* Fullscreen mode: hide sidebar CSS */}
      <style>{`
        :fullscreen .sidebar,
        :-webkit-full-screen .sidebar,
        :-moz-full-screen .sidebar,
        :-ms-fullscreen .sidebar {
          display: none !important;
        }
        :fullscreen .main-content,
        :-webkit-full-screen .main-content,
        :-moz-full-screen .main-content,
        :-ms-fullscreen .main-content {
          margin-left: 0 !important;
          width: 100% !important;
        }
      `}</style>
      
      <MainHeader 
        title="Dashboard Summary"
        subtitle="Get a quick overview of all QHSE Activities"
        lastUpdated={lastUpdated}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
          <div className="text-xs text-green-600 dark:text-green-400">
            • Live data ({projectsData.length} projects)
          </div>
          
          {/* Auto-refresh indicator */}
          <Tooltip title={autoRefreshEnabled ? 'Auto-refresh ON (30s)' : 'Auto-refresh OFF'}>
            <IconButton
              size="small"
              onClick={() => setAutoRefreshEnabled(!autoRefreshEnabled)}
              sx={{ color: autoRefreshEnabled ? 'success.main' : 'text.secondary' }}
            >
              <RefreshCw size={16} className={isRefreshing ? 'animate-spin' : ''} />
            </IconButton>
          </Tooltip>
          
          {/* Fullscreen toggle */}
          <Tooltip title={isFullscreen ? 'Exit Fullscreen' : 'Enter Fullscreen'}>
            <IconButton
              size="small"
              onClick={toggleFullscreen}
              sx={{ color: 'text.secondary' }}
            >
              {isFullscreen ? <Minimize2 size={16} /> : <Maximize2 size={16} />}
            </IconButton>
          </Tooltip>
          
          <Button
            variant="outlined"
            size="small"
            startIcon={<Plus size={16} />}
            onClick={() => setCreateModalOpen(true)}
            sx={{
              textTransform: 'none',
              fontSize: '0.75rem',
              px: 2,
              py: 0.5
            }}
          >
            New Project
          </Button>
          
          <Button
            variant="contained"
            size="small"
            startIcon={<Upload size={16} />}
            onClick={() => setUploadModalOpen(true)}
            sx={{
              textTransform: 'none',
              fontSize: '0.75rem',
              px: 2,
              py: 0.5
            }}
          >
            Bulk Upload
          </Button>
        </div>
      </MainHeader>
      
      <SummaryContent 
        projectsData={projectsData}
        filteredProjects={filteredProjects}
        projectMetrics={projectMetrics}
        chartData={chartData}
        selectedYear={selectedYear}
        setSelectedYear={setSelectedYear}
        selectedMonth={selectedMonth}
        setSelectedMonth={setSelectedMonth}
        selectedClient={selectedClient}
        setSelectedClient={setSelectedClient}
        selectedKPIStatus={selectedKPIStatus}
        setSelectedKPIStatus={setSelectedKPIStatus}
        resetFilters={resetFilters}
      />

      {/* Bulk Upload Modal */}
      <BulkUploadModal
        open={uploadModalOpen}
        onClose={() => setUploadModalOpen(false)}
        onSuccess={() => {
          setUploadModalOpen(false);
          refetch(); // Refresh data after upload
        }}
      />

      {/* Create New Project Modal */}
      <ProjectEditModal
        open={createModalOpen}
        onClose={() => setCreateModalOpen(false)}
        mode="create"
        onUpdate={() => {
          setCreateModalOpen(false);
          refetch(); // Refresh data after creating
        }}
      />
    </PageLayout>
  )
}


const SummaryContent = ({ 
  projectsData,
  filteredProjects, 
  projectMetrics, 
  chartData,
  selectedYear,
  setSelectedYear,
  selectedMonth,
  setSelectedMonth,
  selectedClient,
  setSelectedClient,
  selectedKPIStatus,
  setSelectedKPIStatus,
  resetFilters
}) => {
  
  // Handle filtered empty state
  if (filteredProjects.length === 0) {
    return (
      <>
        <FiltersSection 
          projectsData={projectsData}
          filteredProjects={filteredProjects}
          selectedYear={selectedYear}
          setSelectedYear={setSelectedYear}
          selectedMonth={selectedMonth}
          setSelectedMonth={setSelectedMonth}
          selectedClient={selectedClient}
          setSelectedClient={setSelectedClient}
          selectedKPIStatus={selectedKPIStatus}
          setSelectedKPIStatus={setSelectedKPIStatus}
          resetFilters={resetFilters}
        />
        <EmptyDataState 
          title="No projects found"
          message="Try adjusting your filters to see more results."
          troubleshootingSteps={[
            "Check if your filter criteria are too restrictive",
            "Try resetting all filters to see all projects",
            "Verify that projects exist for the selected time period"
          ]}
        />
      </>
    )
  }

  return (
    <>
      <FiltersSection 
        projectsData={projectsData}
        filteredProjects={filteredProjects}
        selectedYear={selectedYear}
        setSelectedYear={setSelectedYear}
        selectedMonth={selectedMonth}
        setSelectedMonth={setSelectedMonth}
        selectedClient={selectedClient}
        setSelectedClient={setSelectedClient}
        selectedKPIStatus={selectedKPIStatus}
        setSelectedKPIStatus={setSelectedKPIStatus}
        resetFilters={resetFilters}
      />
      
      <SummaryCards
        totalProjects={projectMetrics.totalProjects}
        extendedProjects={projectMetrics.extendedProjects}
        totalOpenCARs={projectMetrics.totalOpenCARs}
        totalOpenObs={projectMetrics.totalOpenObs}
        avgProgress={projectMetrics.avgProgress}
        filteredProjects={filteredProjects}
      />

      <ChartsSection chartData={chartData} filteredProjects={filteredProjects} />

      {/* <CriticalIssues filteredProjects={filteredProjects} /> */}
    </>
  )
}

