                                <span className="px-2 py-1 text-xs font-medium bg-gray-100 text-gray-800 rounded">
                                  No Source
                                </span>
                              )}
                            </td>
                            <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                              <button
                                onClick={() => downloadFile(file.s3_key, file.filename)}
                                className="text-indigo-600 hover:text-indigo-900 mr-4"
                              >
                                Download
                              </button>
                              {file.has_pfd_source && (
                                <button
                                  onClick={() => downloadFile(file.pfd_key, file.pfd_key.split('/').pop())}
                                  className="text-blue-600 hover:text-blue-900"
                                >
                                  View Source PFD
                                </button>
                              )}
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </table>
                  </div>
                ) : (
                  <div className="text-center py-12 text-gray-500">
                    <span className="text-4xl mb-4 block">📐</span>
                    <p>No P&ID files found</p>
                    <p className="text-sm mt-2">Convert a PFD to generate P&ID files</p>
                  </div>
                )}
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
};

export default S3PFDBrowser;

import { useEffect, useId, useRef, useState } from "react";
import PropTypes from "prop-types";
import { Link } from "react-router-dom";
import {
  ArrowLeft,
  ArrowRight,
  CheckCircle2,
  Clock3,
  Copy,
  ExternalLink,
  FileText,
  History,
  Lock,
  Mail,
  MoreHorizontal,
  Pencil,
  RefreshCw,
  XCircle,
} from "lucide-react";
import SalesOpportunityHistory from "./SalesOpportunityHistory";
import SalesOpportunityWorkspace from "./SalesOpportunityWorkspace.jsx";
import { opportunityMoney } from "./salesOpportunityRegistration";
import {
  STATUS_LABELS,
  bidLabel,
  deadlineInfo,
  displayDate,
  serviceLine,
  statusLabel,
  typeLabel,
} from "./salesOpportunityRegister.js";
import "./SalesOpportunityDetailPanel.css";

const text = (value) => (typeof value === "string" ? value.trim() : "");
const object = (value) =>
  value && typeof value === "object" && !Array.isArray(value) ? value : {};
const present = (value) =>
  typeof value === "number" && Number.isFinite(value)
    ? String(value)
    : text(value) || "Not provided";
const words = (value) =>
  text(value)
    .replaceAll("_", " ")
    .replace(/\b\w/g, (letter) => letter.toUpperCase());
const lookup = (labels, value) =>
  typeof value === "string" && Object.hasOwn(labels, value)
    ? labels[value]
    : "";
const scopeLabels = {
  feed: "FEED",
  pre_feed: "Pre-FEED",
  epc: "EPC",
  epcm: "EPCM",
  pmc: "PMC",
};
const tabs = ["Overview", "Activity"];
const formatDate = (value, includeTime = false) => {
  const raw = text(value);
  if (!raw) return "Not provided";
  const calendar = /^\d{4}-\d{2}-\d{2}$/.test(raw);
  if (calendar) return displayDate(raw);
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) return "Not provided";
  return new Intl.DateTimeFormat("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
    timeZone: "Asia/Dubai",
    ...(includeTime
      ? { hour: "2-digit", minute: "2-digit", timeZoneName: "short" }
      : {}),
  }).format(date);
};
const percentage = (value) =>
  value !== null &&
  value !== undefined &&
  value !== "" &&
  Number.isFinite(Number(value)) &&
  Number(value) >= 0 &&
  Number(value) <= 100
    ? `${Number(value)}%`
    : "Not provided";
const listText = (values, labels = {}) =>
  Array.isArray(values)
    ? values
        .filter((value) => typeof value === "string" && value.trim())
        .map((value) => lookup(labels, value) || words(value))
        .join(", ")
    : "";
const recordName = (details) =>
  text(details?.full_name) ||
  [text(details?.first_name), text(details?.last_name)]
    .filter(Boolean)
    .join(" ") ||
  text(details?.username);
const initials = (name) =>
  name
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join("")
    .toUpperCase();
const hasIdentity = (value) =>
  ["string", "number"].includes(typeof value) && String(value).trim();
const decisionActor = (record, history) => {
  if (!hasIdentity(record.bid_decided_by)) return "Not provided";
  const id = String(record.bid_decided_by);
  const people = [
    record.owner_details,
    ...(Array.isArray(record.team_members_details)
      ? record.team_members_details
      : []),
  ];
  const canonical = people.find((person) => person && String(person.id) === id);
  if (recordName(canonical)) return recordName(canonical);
  if (
    hasIdentity(record.created_by) &&
    String(record.created_by) === id &&
    text(record.created_by_name)
  )
    return text(record.created_by_name);
  const evidence = history.find(
    (event) =>
      event?.event_type === "bid_decision" &&
      hasIdentity(event.actor) &&
      String(event.actor) === id &&
      object(event.data).decision === record.bid_decision &&
      text(event.actor_name),
  );
  return text(evidence?.actor_name) || "Not provided";
};

function Section({ number, title, children }) {
  const headingId = useId();
  return (
    <section className="sor-detail-section" aria-labelledby={headingId}>
      <h3 id={headingId} className="sor-detail-section-heading">
        <span aria-hidden="true">{number}.</span>
        {title}
      </h3>
      {children}
    </section>
  );
}
Section.propTypes = {
  number: PropTypes.number.isRequired,
  title: PropTypes.string.isRequired,
  children: PropTypes.node.isRequired,
};

function Facts({ rows }) {
  return (
    <dl className="sor-detail-facts">
      {rows.map(([label, value]) => (
        <div key={label}>
          <dt>{label}</dt>
          <dd>{value || "Not provided"}</dd>
        </div>
      ))}
    </dl>
  );
}
Facts.propTypes = { rows: PropTypes.array.isRequired };

export default function SalesOpportunityDetailPanel({
  record,
  loading = false,
  error = "",
  onRetry,
  onOpenFullRecord,
  onEdit,
  onAction,
  actions = [],
  locked = false,
  explorer = false,
  explorerFolder = "",
  onOpenWorkspace,
  onCloseWorkspace,
}) {
  const panelId = useId();
  const contentRef = useRef(null);
  const [selection, setSelection] = useState({
    recordId: null,
    tab: "Overview",
  });
  const [copyNotice, setCopyNotice] = useState("");
  useEffect(() => {
    if (!copyNotice) return undefined;
    const timer = setTimeout(() => setCopyNotice(""), 3500);
    return () => clearTimeout(timer);
  }, [copyNotice]);
  const activeTab = explorer
    ? null
    : selection.recordId === record?.id
      ? selection.tab
      : "Overview";
  const activate = (tab) => {
    setSelection({ recordId: record?.id, tab });
    if (contentRef.current) contentRef.current.scrollTop = 0;
  };
  const moveTab = (event) => {
    const index = tabs.indexOf(activeTab);
    const next =
      event.key === "ArrowRight"
        ? (index + 1) % tabs.length
        : event.key === "ArrowLeft"
          ? (index + tabs.length - 1) % tabs.length
          : event.key === "Home"
            ? 0
            : event.key === "End"
              ? tabs.length - 1
              : -1;
    if (next < 0) return;
    event.preventDefault();
    activate(tabs[next]);
    event.currentTarget.parentElement
      .querySelectorAll('[role="tab"]')
      [next]?.focus();
  };
  if (loading || error || !record)
    return (
      <aside
        className={`sor-detail-panel ${explorer ? "sor-detail-explorer" : ""}`}
        aria-label="Opportunity details"
        aria-busy={loading}
      >
        {explorer && (
          <button
            type="button"
            className="sor-back-register"
            onClick={onCloseWorkspace}
          >
            <ArrowLeft aria-hidden="true" />
            Back to register
          </button>
        )}
        <header className="sor-detail-header">
          <h2 className="sor-detail-empty-title">Opportunity details</h2>
        </header>
        <div className="sor-detail-state">
          {loading ? (
            <>
              <RefreshCw
                className="sor-detail-loading-icon"
                aria-hidden="true"
              />
              <p role="status">Loading opportunity details…</p>
            </>
          ) : error ? (
            <>
              <FileText aria-hidden="true" />
              <p role="alert">
                {text(error) || "Opportunity details could not be loaded."}
              </p>
              {onRetry && (
                <button
                  className="sor-detail-secondary"
                  type="button"
                  onClick={onRetry}
                >
                  <RefreshCw aria-hidden="true" />
                  Retry details
                </button>
              )}
            </>
          ) : (
            <>
              <FileText aria-hidden="true" />
              <p>Select an opportunity to review its details.</p>
            </>
          )}
        </div>
      </aside>
    );

  const safeActions = (Array.isArray(actions) ? actions : []).filter(
    (action) => text(action?.id) && text(action?.label),
  );
  const primary = safeActions.find((action) => !action.danger);
  const secondaryActions = safeActions;
  const owner = text(record.owner_name) || recordName(record.owner_details);
  const client =
    text(record.client_name) || text(record.client_details?.company_name);
  const history = Array.isArray(record.stage_history)
    ? record.stage_history
    : [];
  const sourceEvent = history.find(
    (event) => event?.event_type === "opportunity_created_from_email",
  );
  const source = {
    ...object(record.custom_fields),
    ...object(sourceEvent?.data),
  };
  const analysis = object(source.reviewed_email_analysis);
  const identity = object(source.email_tender_identity);
  const fromEmail =
    record.opportunity_source === "client_email" ||
    Boolean(
      sourceEvent ||
      text(source.source_email_intake_id) ||
      text(source.source_message_id),
    );
  const quotes = Array.isArray(record.quotes)
    ? record.quotes
        .filter((quote) => quote && typeof quote === "object")
        .slice(0, 5)
    : [];
  const activities = Array.isArray(record.activities)
    ? record.activities
        .filter((activity) => activity && typeof activity === "object")
        .slice(0, 10)
    : [];
  const stage = text(record.stage);
  const decision = text(record.bid_decision);
  const deadline = deadlineInfo(text(record.submission_due_date));
  const stageValue = (
    <span
      className={`sor-detail-status sor-detail-status--${Object.hasOwn(STATUS_LABELS, stage) ? stage : "unknown"}`}
    >
      <span aria-hidden="true" />
      {text(statusLabel(stage)) || "Not provided"}
    </span>
  );
  const DecisionIcon =
    decision === "bid" || decision === "conditional_bid"
      ? CheckCircle2
      : decision === "no_bid"
        ? XCircle
        : Clock3;
  const decisionValue = (
    <span
      className={`sor-detail-decision sor-detail-decision--${decision === "bid" ? "go" : decision === "no_bid" ? "no-go" : "pending"}`}
    >
      <DecisionIcon aria-hidden="true" />
      {text(bidLabel(decision)) || "Not provided"}
    </span>
  );
  const deadlineValue = (
    <span className="sor-detail-deadline">
      <span>{displayDate(text(record.submission_due_date))}</span>
      {deadline.label && (
        <span
          className={`sor-detail-deadline-note sor-detail-deadline-note--${deadline.tone || "normal"}`}
        >
          {deadline.label}
        </span>
      )}
    </span>
  );
  const commercialRows = [
    [
      "Estimated value",
      opportunityMoney(record.estimated_value, record.currency),
    ],
    ["Win probability", percentage(record.probability)],
    [
      "Weighted value",
      opportunityMoney(record.weighted_value, record.currency),
    ],
  ];
  const ownerValue = owner ? (
    <span className="sor-detail-owner">
      <span className="sor-detail-avatar" aria-hidden="true">
        {initials(owner)}
      </span>
      <span>{owner}</span>
    </span>
  ) : (
    "Not provided"
  );

  return (
    <aside
      className={`sor-detail-panel ${explorer ? "sor-detail-explorer" : ""}`}
      aria-label="Opportunity details"
    >
      <header className="sor-detail-header">
        {explorer && (
          <button
            type="button"
            className="sor-back-register"
            onClick={onCloseWorkspace}
          >
            <ArrowLeft aria-hidden="true" />
            Back to register
          </button>
        )}
        <div className="sor-detail-topline">
          <div className="sor-detail-identity">
            <span className="sor-detail-code">{present(record.deal_code)}</span>
            <button
              type="button"
              className="sor-detail-icon-button"
              aria-label="Copy VF code"
              onClick={async () => {
                try {
                  await navigator.clipboard.writeText(record.deal_code);
                  setCopyNotice("VF code copied.");
                } catch {
                  setCopyNotice(
                    "Copy is unavailable in this browser. Select the VF code to copy it.",
                  );
                }
              }}
            >
              <Copy aria-hidden="true" />
            </button>
            {record.id && (
              <span className="sor-detail-saved">
                <CheckCircle2 aria-hidden="true" />
