            Continue in SharePoint
          </a>
        ) : storage === "sharepoint" ? (
          <p className="sow-message">
            The SharePoint connection needs administrator setup before a folder
            can be created.
          </p>
        ) : null}
      </dialog>
    </div>
  );
}
