/**
 * Subscription Management Page
 * Displays all subscription plans, features, and user subscriptions
 */
const SubscriptionManagement = () => {
  const navigate = useNavigate();
  const { user } = useSelector((state) => state.auth);
  const [loading, setLoading] = useState(true);
  const [plans, setPlans] = useState([]);
  const [subscriptions, setSubscriptions] = useState([]);
  const [stats, setStats] = useState(null);
  const [activeTab, setActiveTab] = useState('plans');

  // Check admin access
  // Smart admin check using utility function
  const isAdmin = isUserAdmin(user);

  useEffect(() => {
    if (!isAdmin) {
      navigate('/dashboard');
      return;
    }
    loadData();
  }, [isAdmin]);

  const loadData = async () => {
    setLoading(true);
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access');
      const headers = {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      };

      // Load subscription plans
      const plansResponse = await fetch(`${API_BASE_URL}/subscriptions/plans/`, { headers });
      if (plansResponse.ok) {
        const plansData = await plansResponse.json();
        setPlans(plansData.results || plansData);
      }

      // Load user subscriptions
      const subsResponse = await fetch(`${API_BASE_URL}/subscriptions/subscriptions/`, { headers });
      if (subsResponse.ok) {
        const subsData = await subsResponse.json();
        setSubscriptions(subsData.results || subsData);
      }

      // Load dashboard stats
      const statsResponse = await fetch(`${API_BASE_URL}/subscriptions/dashboard/stats/`, { headers });
      if (statsResponse.ok) {
        const statsData = await statsResponse.json();
        setStats(statsData);
      }
    } catch (error) {
      console.error('Error loading subscription data:', error);
    } finally {
      setLoading(false);
    }
  };

  const getPlanBadgeColor = (planType) => {
    const colors = {
      'free': 'bg-gray-100 text-gray-700 border-gray-300',
      'basic': 'bg-blue-100 text-blue-700 border-blue-300',
      'professional': 'bg-purple-100 text-purple-700 border-purple-300',
      'enterprise': 'bg-gradient-to-r from-amber-500 to-orange-600 text-white border-amber-500'
    };
    return colors[planType] || 'bg-gray-100 text-gray-700';
  };

  const getStatusBadge = (status) => {
    const badges = {
      'active': <span className="px-2 py-1 bg-green-100 text-green-700 rounded-full text-xs font-medium">Active</span>,
      'trial': <span className="px-2 py-1 bg-blue-100 text-blue-700 rounded-full text-xs font-medium">Trial</span>,
      'expired': <span className="px-2 py-1 bg-red-100 text-red-700 rounded-full text-xs font-medium">Expired</span>,
      'cancelled': <span className="px-2 py-1 bg-gray-100 text-gray-700 rounded-full text-xs font-medium">Cancelled</span>
    };
    return badges[status] || status;
  };

  if (!isAdmin) {
    return null;
  }

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 to-blue-50 flex items-center justify-center">
        <div className="text-center">
          <ArrowPathIcon className="w-12 h-12 text-blue-600 animate-spin mx-auto mb-4" />
          <p className="text-gray-600">Loading subscription data...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-blue-50 to-indigo-50 py-6 sm:py-8 px-4 sm:px-6 lg:px-8">
      <div className="max-w-7xl mx-auto">
        {/* Header */}
        <div className="mb-6 sm:mb-8">
          <div className="flex items-center justify-between flex-wrap gap-4">
            <div>
              <div className="flex items-center space-x-3 mb-2">
                <CurrencyDollarIcon className="w-10 h-10 text-blue-600" />
                <h1 className="text-2xl sm:text-3xl md:text-4xl font-bold bg-gradient-to-r from-blue-600 via-indigo-600 to-purple-600 bg-clip-text text-transparent">
                  Subscription Management
                </h1>
              </div>
              <p className="text-sm sm:text-base text-gray-600">
                Manage subscription plans, features, and user subscriptions
              </p>
            </div>
            <button
              onClick={loadData}
              className="px-4 py-2 bg-white rounded-lg shadow-md hover:shadow-lg transition-all flex items-center space-x-2 text-sm font-medium text-gray-700 hover:text-blue-600"
            >
              <ArrowPathIcon className="w-4 h-4" />
              <span>Refresh</span>
            </button>
          </div>
        </div>

        {/* Stats Cards */}
        {stats && (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 sm:gap-5 md:gap-6 mb-6 sm:mb-8">
            <div className="bg-white rounded-xl shadow-lg p-6 border-2 border-blue-100 hover:shadow-xl transition-all">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-semibold text-gray-600">Total Plans</p>
                  <p className="text-3xl font-bold text-blue-600">{stats.total_plans || 0}</p>
                  <p className="text-xs text-gray-500 mt-1">{stats.active_plans || 0} active</p>
                </div>
                <div className="w-12 h-12 bg-blue-100 rounded-full flex items-center justify-center">
                  <SparklesIcon className="w-6 h-6 text-blue-600" />
                </div>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-lg p-6 border-2 border-green-100 hover:shadow-xl transition-all">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-semibold text-gray-600">Active Subscriptions</p>
                  <p className="text-3xl font-bold text-green-600">{stats.active_subscriptions || 0}</p>
                  <p className="text-xs text-gray-500 mt-1">{stats.trial_subscriptions || 0} on trial</p>
                </div>
                <div className="w-12 h-12 bg-green-100 rounded-full flex items-center justify-center">
                  <CheckCircleIcon className="w-6 h-6 text-green-600" />
                </div>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-lg p-6 border-2 border-purple-100 hover:shadow-xl transition-all">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-semibold text-gray-600">Total Revenue</p>
                  <p className="text-3xl font-bold text-purple-600">${(stats.total_revenue || 0).toFixed(2)}</p>
                  <p className="text-xs text-gray-500 mt-1">Monthly recurring</p>
                </div>
                <div className="w-12 h-12 bg-purple-100 rounded-full flex items-center justify-center">
                  <CurrencyDollarIcon className="w-6 h-6 text-purple-600" />
                </div>
              </div>
            </div>

            <div className="bg-white rounded-xl shadow-lg p-6 border-2 border-orange-100 hover:shadow-xl transition-all">
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-sm font-semibold text-gray-600">Total Users</p>
                  <p className="text-3xl font-bold text-orange-600">{stats.total_subscribers || 0}</p>
                  <p className="text-xs text-gray-500 mt-1">Subscribed users</p>
                </div>
                <div className="w-12 h-12 bg-orange-100 rounded-full flex items-center justify-center">
                  <UsersIcon className="w-6 h-6 text-orange-600" />
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Tabs */}
        <div className="bg-white rounded-xl shadow-lg mb-6">
          <div className="flex border-b border-gray-200">
            <button
              onClick={() => setActiveTab('plans')}
              className={`px-6 py-4 text-sm font-medium transition-all ${
                activeTab === 'plans'
                  ? 'text-blue-600 border-b-2 border-blue-600 bg-gradient-to-t from-blue-50 to-transparent'
                  : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'
              }`}
            >
              Subscription Plans
            </button>
            <button
              onClick={() => setActiveTab('subscriptions')}
              className={`px-6 py-4 text-sm font-medium transition-all ${
                activeTab === 'subscriptions'
                  ? 'text-blue-600 border-b-2 border-blue-600 bg-gradient-to-t from-blue-50 to-transparent'
                  : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'
              }`}
            >
              User Subscriptions
            </button>
          </div>

          {/* Plans Tab */}
          {activeTab === 'plans' && (
            <div className="p-6">
              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
                {plans.map((plan) => (
                  <div
                    key={plan.id}
                    className={`relative bg-white rounded-xl border-2 p-6 hover:shadow-xl transition-all ${
                      plan.plan_type === 'enterprise' ? 'border-amber-500 bg-gradient-to-br from-amber-50 to-orange-50' : 'border-gray-200'
                    }`}
                  >
                    {/* Plan Badge */}
                    {plan.badge && (
                      <div className="absolute top-4 right-4">
                        <span className={`px-3 py-1 rounded-full text-xs font-bold border-2 ${getPlanBadgeColor(plan.plan_type)}`}>
                          {plan.badge}
                        </span>
                      </div>
                    )}

                    {/* Plan Info */}
                    <div className="mb-4">
                      <h3 className="text-xl font-bold text-gray-900 mb-2">{plan.display_name || plan.name}</h3>
                      <div className="flex items-baseline space-x-2 mb-2">
                        <span className="text-4xl font-bold text-gray-900">${plan.price}</span>
                        <span className="text-gray-600">/{plan.billing_cycle}</span>
                      </div>
                      <p className="text-sm text-gray-600">{plan.description}</p>
                    </div>

                    {/* Limits */}
                    <div className="space-y-2 mb-4 pt-4 border-t border-gray-200">
                      <div className="flex items-center justify-between text-sm">
                        <span className="text-gray-600">Users:</span>
                        <span className="font-semibold text-gray-900">
                          {plan.max_users === -1 ? 'Unlimited' : plan.max_users}
                        </span>
                      </div>
                      <div className="flex items-center justify-between text-sm">
                        <span className="text-gray-600">Storage:</span>
                        <span className="font-semibold text-gray-900">
                          {plan.max_storage_gb === -1 ? 'Unlimited' : `${plan.max_storage_gb} GB`}
                        </span>
                      </div>
                      <div className="flex items-center justify-between text-sm">
                        <span className="text-gray-600">Projects:</span>
                        <span className="font-semibold text-gray-900">
                          {plan.max_projects === -1 ? 'Unlimited' : plan.max_projects}
                        </span>
                      </div>
                      <div className="flex items-center justify-between text-sm">
                        <span className="text-gray-600">API Calls:</span>
                        <span className="font-semibold text-gray-900">
                          {plan.max_api_calls_per_day === -1 ? 'Unlimited' : `${plan.max_api_calls_per_day}/day`}
                        </span>
                      </div>
                    </div>

                    {/* Features */}
                    {plan.features && Object.keys(plan.features).length > 0 && (
                      <div className="pt-4 border-t border-gray-200">
                        <p className="text-xs font-semibold text-gray-600 mb-2">KEY FEATURES:</p>
                        <div className="space-y-1">
                          {Object.entries(plan.features).slice(0, 3).map(([key, value]) => (
                            value && (
                              <div key={key} className="flex items-center space-x-2">
                                <CheckCircleIcon className="w-4 h-4 text-green-500 flex-shrink-0" />
                                <span className="text-xs text-gray-600">{key.replace(/_/g, ' ')}</span>
                              </div>
                            )
                          ))}
                        </div>
                      </div>
                    )}

                    {/* Status */}
                    <div className="mt-4 pt-4 border-t border-gray-200">
                      {plan.is_active ? (
                        <span className="flex items-center space-x-1 text-green-600 text-sm font-medium">
                          <CheckCircleIcon className="w-4 h-4" />
                          <span>Active</span>
                        </span>
                      ) : (
                        <span className="flex items-center space-x-1 text-gray-400 text-sm font-medium">
                          <XCircleIcon className="w-4 h-4" />
                          <span>Inactive</span>
                        </span>
                      )}
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {/* Subscriptions Tab */}
          {activeTab === 'subscriptions' && (
            <div className="p-6">
              <div className="overflow-x-auto">
                <table className="w-full">
                  <thead>
                    <tr className="border-b border-gray-200">
                      <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase">User</th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase">Plan</th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase">Status</th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase">Start Date</th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase">End Date</th>
                      <th className="px-4 py-3 text-left text-xs font-semibold text-gray-600 uppercase">Price</th>
                    </tr>
                  </thead>
                  <tbody>
                    {subscriptions.map((sub) => (
                      <tr key={sub.id} className="border-b border-gray-100 hover:bg-gray-50">
                        <td className="px-4 py-3 text-sm text-gray-900">
                          {sub.user_email || sub.user?.email || `User #${sub.user}`}
                        </td>
                        <td className="px-4 py-3 text-sm">
                          <span className={`px-2 py-1 rounded-full text-xs font-medium ${getPlanBadgeColor(sub.plan_type)}`}>
                            {sub.plan_name || sub.plan?.name}
                          </span>
                        </td>
                        <td className="px-4 py-3">{getStatusBadge(sub.status)}</td>
                        <td className="px-4 py-3 text-sm text-gray-600">
                          {new Date(sub.start_date).toLocaleDateString()}
                        </td>
                        <td className="px-4 py-3 text-sm text-gray-600">
                          {sub.end_date ? new Date(sub.end_date).toLocaleDateString() : 'N/A'}
                        </td>
                        <td className="px-4 py-3 text-sm font-semibold text-gray-900">
                          ${sub.current_price || 0}
                        </td>
                      </tr>
                    ))}
                    {subscriptions.length === 0 && (
                      <tr>
                        <td colSpan="6" className="px-4 py-8 text-center text-gray-500">
                          No subscriptions found
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          )}
        </div>

        {/* Quick Links */}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <a
            href={`${API_BASE_URL.replace('/api', '')}/admin/rbac/subscriptionplan/`}
            target="_blank"
            rel="noopener noreferrer"
            className="p-6 bg-white rounded-xl shadow-lg hover:shadow-xl transition-all border-2 border-blue-100 hover:border-blue-300"
          >
            <div className="flex items-center space-x-3">
              <ServerIcon className="w-8 h-8 text-blue-600" />
              <div>
                <p className="font-bold text-gray-900">Django Admin</p>
                <p className="text-sm text-gray-600">Manage plans in detail</p>
              </div>
            </div>
          </a>

          <button
            onClick={() => window.open(`${API_BASE_URL}/subscriptions/plans/`, '_blank')}
            className="p-6 bg-white rounded-xl shadow-lg hover:shadow-xl transition-all border-2 border-purple-100 hover:border-purple-300 text-left w-full"
          >
            <div className="flex items-center space-x-3">
              <ChartBarIcon className="w-8 h-8 text-purple-600" />
              <div>
                <p className="font-bold text-gray-900">View Plans API</p>
                <p className="text-sm text-gray-600">JSON response of all plans</p>
              </div>
            </div>
          </button>

          <div className="p-6 bg-gradient-to-br from-blue-50 to-indigo-50 rounded-xl shadow-lg border-2 border-blue-200">
            <div className="flex items-center space-x-3">
              <SparklesIcon className="w-8 h-8 text-blue-600" />
              <div>
                <p className="font-bold text-gray-900">Documentation</p>
                <p className="text-sm text-gray-600">backend/apps/rbac/SUBSCRIPTION_GUIDE.md</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SubscriptionManagement;

/**
 * System Health Dashboard
 * Comprehensive monitoring of backend, database, and services
 */
import React, { useState, useEffect } from 'react';
import {
  Box, Card, CardContent, Typography, Grid, Chip, Alert,
  CircularProgress, Button, Table, TableBody, TableCell,
  TableContainer, TableHead, TableRow, Paper, Accordion,
  AccordionSummary, AccordionDetails
} from '@mui/material';
import {
  CheckCircle as HealthyIcon,
  Error as ErrorIcon,
  Warning as WarningIcon,
  Refresh as RefreshIcon,
  ExpandMore as ExpandMoreIcon
} from '@mui/icons-material';

const API_BASE_URL = import.meta.env.VITE_API_URL || '/api/v1';

const SystemHealthDashboard = () => {
  const [loading, setLoading] = useState(false);
  const [healthData, setHealthData] = useState(null);
  const [databaseData, setDatabaseData] = useState(null);
  const [error, setError] = useState(null);
  const [lastChecked, setLastChecked] = useState(null);

  const fetchHealthData = async () => {
    setLoading(true);
    setError(null);

    try {
      // Fetch comprehensive system health
      const healthResponse = await fetch(`${API_BASE_URL}/system-health/`);
      const healthJson = await healthResponse.json();
      setHealthData(healthJson);

      // Fetch database details
      const dbResponse = await fetch(`${API_BASE_URL}/database-check/`);
      const dbJson = await dbResponse.json();
      setDatabaseData(dbJson);

      setLastChecked(new Date());
    } catch (err) {
      setError(`Failed to fetch health data: ${err.message}`);
      console.error('[Health Check Error]', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchHealthData();
    // Auto-refresh every 5 minutes (was 30s)
    const interval = setInterval(fetchHealthData, 300000);
    return () => clearInterval(interval);
  }, []);

  const getStatusIcon = (status) => {
    if (!status) return <WarningIcon color="warning" />;
    
    const statusLower = status.toLowerCase();
    if (statusLower === 'healthy' || statusLower === 'connected' || statusLower === 'loaded' || statusLower === 'configured') {
      return <HealthyIcon color="success" />;
    }
    if (statusLower === 'degraded' || statusLower === 'warning' || statusLower === 'local') {
      return <WarningIcon color="warning" />;
    }
    return <ErrorIcon color="error" />;
  };

  const getStatusColor = (status) => {
    if (!status) return 'warning';
    
    const statusLower = status.toLowerCase();
    if (statusLower === 'healthy' || statusLower === 'connected' || statusLower === 'loaded' || statusLower === 'configured') {
      return 'success';
    }
    if (statusLower === 'degraded' || statusLower === 'warning' || statusLower === 'local') {
      return 'warning';
    }
    return 'error';
  };

  if (loading && !healthData) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', minHeight: 400 }}>
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box sx={{ p: 3 }}>
      {/* Header */}
      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Box>
          <Typography variant="h4" gutterBottom>
            🏥 System Health Dashboard
          </Typography>
          <Typography variant="body2" color="textSecondary">
            {lastChecked && `Last checked: ${lastChecked.toLocaleString()}`}
          </Typography>
        </Box>
        <Button
          variant="contained"
          startIcon={loading ? <CircularProgress size={20} /> : <RefreshIcon />}
          onClick={fetchHealthData}
          disabled={loading}
        >
          Refresh
        </Button>
      </Box>

      {/* Error Alert */}
      {error && (
        <Alert severity="error" sx={{ mb: 3 }}>
          {error}
        </Alert>
      )}

      {/* Overall Status */}
      {healthData && (
        <Card sx={{ mb: 3 }}>
          <CardContent>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
              {getStatusIcon(healthData.overall_status)}
              <Box>
                <Typography variant="h5">
                  Overall Status: {healthData.overall_status?.toUpperCase()}
                </Typography>
                <Typography variant="body2" color="textSecondary">
                  Timestamp: {healthData.timestamp}
                </Typography>
              </Box>
            </Box>
          </CardContent>
        </Card>
      )}

      {/* Services Grid */}
      {healthData?.services && (
        <Grid container spacing={3}>
          {/* Database Service */}
          {healthData.services.database && (
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                    {getStatusIcon(healthData.services.database.status)}
                    <Typography variant="h6">Database</Typography>
                    <Chip 
                      label={healthData.services.database.status?.toUpperCase()} 
                      color={getStatusColor(healthData.services.database.status)}
                      size="small"
                    />
                  </Box>
                  {healthData.services.database.status === 'healthy' && (
                    <Box>
                      <Typography variant="body2"><strong>Type:</strong> {healthData.services.database.type}</Typography>
                      <Typography variant="body2"><strong>Host:</strong> {healthData.services.database.host}</Typography>
                      <Typography variant="body2"><strong>Database:</strong> {healthData.services.database.name}</Typography>
                      <Typography variant="body2">
                        <strong>Connections:</strong> {healthData.services.database.active_connections}/{healthData.services.database.total_connections}
                      </Typography>
                    </Box>
                  )}
                  {healthData.services.database.error && (
                    <Alert severity="error" sx={{ mt: 1 }}>
                      {healthData.services.database.error}
                    </Alert>
                  )}
                </CardContent>
              </Card>
            </Grid>
          )}

          {/* Redis Service */}
          {healthData.services.redis && (
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                    {getStatusIcon(healthData.services.redis.status)}
                    <Typography variant="h6">Redis Cache</Typography>
                    <Chip 
                      label={healthData.services.redis.status?.toUpperCase()} 
                      color={getStatusColor(healthData.services.redis.status)}
                      size="small"
                    />
                  </Box>
                  {healthData.services.redis.cache_working && (
                    <Typography variant="body2" color="success.main">
                      ✅ Cache operations working
                    </Typography>
                  )}
                  {healthData.services.redis.error && (
                    <Alert severity="error" sx={{ mt: 1 }}>
                      {healthData.services.redis.error}
                    </Alert>
                  )}
                </CardContent>
              </Card>
            </Grid>
          )}

          {/* Email Service */}
          {healthData.services.email && (
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                    {getStatusIcon(healthData.services.email.status)}
                    <Typography variant="h6">Email Service</Typography>
                    <Chip 
                      label={healthData.services.email.status?.toUpperCase()} 
                      color={getStatusColor(healthData.services.email.status)}
                      size="small"
                    />
                  </Box>
                  <Typography variant="body2"><strong>Backend:</strong> {healthData.services.email.backend?.split('.').pop()}</Typography>
                  <Typography variant="body2"><strong>Host:</strong> {healthData.services.email.host}</Typography>
                  <Typography variant="body2"><strong>Port:</strong> {healthData.services.email.port}</Typography>
                  <Typography variant="body2"><strong>TLS:</strong> {healthData.services.email.use_tls ? 'Yes' : 'No'}</Typography>
                </CardContent>
              </Card>
            </Grid>
          )}

          {/* Storage Service */}
          {healthData.services.storage && (
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                    {getStatusIcon(healthData.services.storage.status)}
                    <Typography variant="h6">Storage</Typography>
                    <Chip 
                      label={healthData.services.storage.type} 
                      color={getStatusColor(healthData.services.storage.status)}
                      size="small"
                    />
                  </Box>
                  {healthData.services.storage.bucket && (
                    <Typography variant="body2"><strong>Bucket:</strong> {healthData.services.storage.bucket}</Typography>
                  )}
                  {healthData.services.storage.media_root && (
                    <Typography variant="body2" sx={{ wordBreak: 'break-all' }}>
                      <strong>Media Root:</strong> {healthData.services.storage.media_root}
                    </Typography>
                  )}
                </CardContent>
              </Card>
            </Grid>
          )}

          {/* Optional Apps */}
          {healthData.services.optional_apps && (
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, mb: 2 }}>
                    {getStatusIcon(healthData.services.optional_apps.status)}
                    <Typography variant="h6">Optional Apps</Typography>
                    <Chip 
                      label={`${healthData.services.optional_apps.count} Loaded`}
                      color="info"
                      size="small"
                    />
                  </Box>
                  <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 1 }}>
                    {healthData.services.optional_apps.apps?.map((app) => (
                      <Chip key={app} label={app.split('.').pop()} size="small" color="success" variant="outlined" />
                    ))}
                  </Box>
                </CardContent>
              </Card>
            </Grid>
          )}

          {/* Security Settings */}
          {healthData.services.security && (
            <Grid item xs={12} md={6}>
              <Card>
                <CardContent>
                  <Typography variant="h6" gutterBottom>🔒 Security</Typography>
                  <TableContainer>
                    <Table size="small">
                      <TableBody>
                        <TableRow>
                          <TableCell>Debug Mode</TableCell>
                          <TableCell>
                            <Chip 
                              label={healthData.services.security.debug_mode ? 'ON' : 'OFF'} 
                              color={healthData.services.security.debug_mode ? 'warning' : 'success'}
                              size="small"
                            />
                          </TableCell>
                        </TableRow>
                        <TableRow>
                          <TableCell>Allowed Hosts</TableCell>
                          <TableCell>{healthData.services.security.allowed_hosts}</TableCell>
                        </TableRow>
                        <TableRow>
                          <TableCell>CORS Origins</TableCell>
                          <TableCell>{healthData.services.security.cors_origins}</TableCell>
                        </TableRow>
                        <TableRow>
                          <TableCell>Secret Key</TableCell>
                          <TableCell>
                            {healthData.services.security.secret_key_set ? '✅ Set' : '❌ Missing'}
                          </TableCell>
                        </TableRow>
                      </TableBody>
                    </Table>
                  </TableContainer>
                  {healthData.services.security.warning && (
                    <Alert severity="warning" sx={{ mt: 2 }}>
                      {healthData.services.security.warning}
                    </Alert>
                  )}
                </CardContent>
              </Card>
            </Grid>
          )}
        </Grid>
      )}

      {/* Database Details Accordion */}
      {databaseData && (
        <Accordion sx={{ mt: 3 }}>
          <AccordionSummary expandIcon={<ExpandMoreIcon />}>
            <Typography variant="h6">📊 Database Details</Typography>
          </AccordionSummary>
          <AccordionDetails>
            {databaseData.database?.status === 'connected' ? (
              <TableContainer component={Paper}>
                <Table>
                  <TableBody>
                    <TableRow>
                      <TableCell><strong>Status</strong></TableCell>
                      <TableCell>
                        <Chip label="CONNECTED" color="success" size="small" />
                      </TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><strong>Version</strong></TableCell>
                      <TableCell>{databaseData.database.version}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><strong>Database Name</strong></TableCell>
                      <TableCell>{databaseData.database.name}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><strong>Host</strong></TableCell>
                      <TableCell>{databaseData.database.host}:{databaseData.database.port}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><strong>User</strong></TableCell>
                      <TableCell>{databaseData.database.user}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><strong>Database Size</strong></TableCell>
                      <TableCell>{databaseData.database.database_size}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><strong>Tables</strong></TableCell>
                      <TableCell>{databaseData.database.table_count}</TableCell>
                    </TableRow>
                    <TableRow>
                      <TableCell><strong>Connection Timeout</strong></TableCell>
                      <TableCell>{databaseData.database.connection_timeout}s</TableCell>
                    </TableRow>
                  </TableBody>
                </Table>
              </TableContainer>
            ) : (
              <Alert severity="error">
                Database disconnected: {databaseData.database?.error}
              </Alert>
            )}
          </AccordionDetails>
        </Accordion>
      )}
    </Box>
  );
};

export default SystemHealthDashboard;

/**
 * Usage Dashboard - Main Page
 * 
 * Simplified version for usage analytics display
 * Soft-coded to work with available backend endpoints
 */

import React, { useState, useEffect, useMemo } from 'react';
import {
  ChartBarIcon,
  UserGroupIcon,
  CpuChipIcon,
  ClockIcon,
  ArrowTrendingUpIcon,
  BoltIcon,
  SignalIcon,
  SignalSlashIcon,
} from '@heroicons/react/24/outline';
import usageTrackingService from '../services/usageTrackingService';
import useUsageLiveStream from '../hooks/useUsageLiveStream';

// ── Soft-coded constants ───────────────────────────────────────────────
const POLL_FALLBACK_INTERVAL_MS = 300_000;   // legacy 5-min poll (fallback)
const POLL_LIVE_INTERVAL_MS     = 60_000;    // when WS is connected, slow poll
const RECENT_EVENTS_DISPLAY     = 8;

const UsageDashboard = () => {
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [summaryData, setSummaryData] = useState(null);
  const [timeRange, setTimeRange] = useState('daily');
  const [liveEnabled, setLiveEnabled] = useState(true);

  // Real-time WebSocket stream — additive layer; polling stays in place
  // as a failsafe even when the socket is connected.
  const { liveSnapshot, status: wsStatus, stale: wsStale } =
    useUsageLiveStream(liveEnabled);

  const liveKpis     = liveSnapshot?.kpis || null;
  const liveFeatures = liveSnapshot?.top_features || [];
  const liveUsers    = liveSnapshot?.top_users || [];
  const liveEvents   = liveSnapshot?.recent_events || [];

  // Fetch dashboard data
  const fetchDashboardData = async () => {
    try {
      setLoading(true);
      const data = await usageTrackingService.getSummary();
      setSummaryData(data);
      setError(null);
    } catch (err) {
      console.error('Failed to fetch dashboard data:', err);
      setError(err.message || 'Failed to load dashboard data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchDashboardData();

    // Adaptive poll cadence — slow down once realtime stream is healthy,
    // speed up when it's offline so the UI never goes blind.
    const interval = setInterval(
      fetchDashboardData,
      wsStatus === 'connected' && !wsStale
        ? POLL_LIVE_INTERVAL_MS
        : POLL_FALLBACK_INTERVAL_MS,
    );

    return () => clearInterval(interval);
  }, [wsStatus, wsStale]);

  const handleRefresh = () => {
    fetchDashboardData();
  };

  if (loading && !summaryData) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>
          <p className="mt-4 text-gray-600">Loading usage analytics...</p>
        </div>
      </div>
    );
  }

  if (error && !summaryData) {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center max-w-md">
          <div className="bg-red-50 border border-red-200 rounded-lg p-6">
            <h3 className="text-red-800 font-semibold mb-2">Error Loading Dashboard</h3>
            <p className="text-red-600 text-sm">{error}</p>
            <button
              onClick={handleRefresh}
              className="mt-4 px-4 py-2 bg-red-600 text-white rounded-lg hover:bg-red-700 transition"
            >
              Retry
            </button>
          </div>
        </div>
      </div>
    );
  }

  // Summary cards data — prefer realtime KPIs whenever available, fall
  // back to the polled summary so the page is never empty.
  const summaryCards = useMemo(() => ([
    {
      title: 'Active Users (15 min)',
      value: liveKpis?.active_users ?? summaryData?.total_users ?? 0,
      icon: UserGroupIcon,
      color: 'blue',
      live: !!liveKpis,
    },
    {
      title: 'Requests / min',
      value: liveKpis?.requests_per_min ?? summaryData?.active_features ?? 0,
      icon: BoltIcon,
      color: 'amber',
      live: !!liveKpis,
    },
    {
      title: 'Avg Response (ms)',
      value: liveKpis?.avg_response_ms ?? summaryData?.total_sessions ?? 0,
      icon: ClockIcon,
      color: 'purple',
      live: !!liveKpis,
    },
    {
      title: 'Today Requests',
      value: liveKpis?.today_requests ?? summaryData?.total_requests ?? 0,
      icon: ArrowTrendingUpIcon,
      color: 'orange',
      live: !!liveKpis,
    },
  ]), [liveKpis, summaryData]);

  // ── Live status pill colour map ─────────────────────────────────────
  const liveStatusInfo = useMemo(() => {
    if (!liveEnabled)            return { label: 'Live OFF',       cls: 'bg-gray-100 text-gray-600',     Icon: SignalSlashIcon };
    if (wsStatus === 'disabled') return { label: 'Live unavailable', cls: 'bg-gray-100 text-gray-600',   Icon: SignalSlashIcon };
    if (wsStatus === 'connected' && !wsStale)
                                 return { label: 'Live',            cls: 'bg-emerald-100 text-emerald-700 ring-1 ring-emerald-300', Icon: SignalIcon };
    if (wsStatus === 'connected' && wsStale)
                                 return { label: 'Stalled',         cls: 'bg-amber-100 text-amber-700',  Icon: SignalIcon };
    if (wsStatus === 'connecting')
                                 return { label: 'Connecting…',     cls: 'bg-sky-100 text-sky-700',      Icon: SignalIcon };
    return { label: 'Polling',     cls: 'bg-yellow-100 text-yellow-700',  Icon: SignalSlashIcon };
  }, [liveEnabled, wsStatus, wsStale]);
  const LiveStatusIcon = liveStatusInfo.Icon;

  return (
    <div className="min-h-screen bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="mb-8">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 flex items-center">
                <ChartBarIcon className="h-8 w-8 text-blue-600 mr-3" />
                Usage Analytics Dashboard
              </h1>
              <p className="mt-2 text-gray-600">
                Monitor system usage, track user activity, and analyze performance metrics
              </p>
            </div>
            <div className="flex items-center space-x-3">
              {/* Live indicator + toggle */}
              <button
                type="button"
                onClick={() => setLiveEnabled((v) => !v)}
                title="Toggle realtime stream (polling stays as a failsafe)"
                className={`px-3 py-2 rounded-lg text-xs font-semibold flex items-center gap-1.5 transition ${liveStatusInfo.cls}`}
              >
                <LiveStatusIcon className={`h-4 w-4 ${wsStatus === 'connected' && !wsStale ? 'animate-pulse' : ''}`} />
                {liveStatusInfo.label}
                {liveSnapshot?.generated_at && (
                  <span className="ml-1 opacity-70 font-normal">
                    · {new Date(liveSnapshot.generated_at).toLocaleTimeString()}
                  </span>
                )}
              </button>

              {/* Time Range Selector */}
              <select
                value={timeRange}
                onChange={(e) => setTimeRange(e.target.value)}
                className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value="daily">Today</option>
                <option value="weekly">Last 7 Days</option>
                <option value="monthly">Last 30 Days</option>
              </select>

              {/* Refresh Button */}
              <button
                onClick={handleRefresh}
                disabled={loading}
                className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition disabled:opacity-50 disabled:cursor-not-allowed flex items-center"
              >
                <svg
                  className={`h-4 w-4 mr-2 ${loading ? 'animate-spin' : ''}`}
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"
                  />
                </svg>
                Refresh
              </button>
            </div>
          </div>
        </div>

        {/* Summary Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
          {summaryCards.map((card, index) => {
            const Icon = card.icon;
            return (
              <div
                key={index}
                className="bg-white rounded-lg shadow-md p-6 hover:shadow-lg transition relative"
              >
                {card.live && (
                  <span className="absolute top-3 right-3 inline-flex items-center gap-1 text-[10px] font-semibold uppercase tracking-wider text-emerald-600">
                    <span className="h-1.5 w-1.5 rounded-full bg-emerald-500 animate-pulse" />
                    live
                  </span>
                )}
                <div className="flex items-center justify-between mb-4">
                  <div className={`p-3 rounded-lg bg-${card.color}-100`}>
                    <Icon className={`h-6 w-6 text-${card.color}-600`} />
                  </div>
                </div>
                <h3 className="text-gray-600 text-sm font-medium">{card.title}</h3>
                <p className="text-3xl font-bold text-gray-900 mt-2">
                  {Number(card.value).toLocaleString()}
                </p>
              </div>
            );
          })}
        </div>

        {/* Live Activity Stream */}
        {liveEvents.length > 0 && (
          <div className="bg-white rounded-lg shadow-md p-6 mb-8 border-l-4 border-emerald-500">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-bold text-gray-900 flex items-center gap-2">
                <BoltIcon className="h-5 w-5 text-emerald-600" />
                Live Activity Stream
              </h2>
              <span className="text-xs text-gray-500">
                Last {RECENT_EVENTS_DISPLAY} events · updates every few seconds
              </span>
            </div>
            <ul className="divide-y divide-gray-100">
              {liveEvents.slice(0, RECENT_EVENTS_DISPLAY).map((ev, i) => {
                const ok = (ev.response_status || 200) < 400;
                return (
                  <li key={i} className="py-2 flex items-center justify-between text-sm">
                    <div className="flex items-center gap-2 min-w-0">
                      <span className={`h-2 w-2 rounded-full flex-shrink-0 ${ok ? 'bg-emerald-500' : 'bg-rose-500'}`} />
                      <span className="font-medium text-gray-800 truncate max-w-[180px]">
                        {ev.user_full_name || ev.user_email || 'Anonymous'}
                      </span>
                      <span className="text-gray-500 truncate">
                        → {ev.discipline_label || 'Other'}
                      </span>
                    </div>
                    <div className="flex items-center gap-3 text-xs text-gray-500 flex-shrink-0 ml-2">
                      <span>{ev.response_status} · {ev.response_time_ms ?? '—'}ms</span>
                      <span>{ev.timestamp ? new Date(ev.timestamp).toLocaleTimeString() : ''}</span>
                    </div>
                  </li>
                );
              })}
            </ul>
          </div>
        )}

        {/* Top Features (live) */}
        {liveFeatures.length > 0 && (
          <div className="bg-white rounded-lg shadow-md p-6 mb-8">
            <h2 className="text-xl font-bold text-gray-900 mb-4 flex items-center gap-2">
              <CpuChipIcon className="h-5 w-5 text-blue-600" />
              Hot Features (last {liveSnapshot?.window_minutes || 15} min)
            </h2>
            <div className="space-y-3">
              {liveFeatures.map((f, i) => {
                const max = Math.max(...liveFeatures.map((x) => x.count || 0), 1);
                const pct = Math.round(((f.count || 0) / max) * 100);
                return (
                  <div key={i} className="flex items-center justify-between">
                    <span className="text-gray-700 font-medium truncate max-w-xs">
                      {f.discipline_label || f.discipline_key}
                    </span>
                    <div className="flex items-center space-x-3">
                      <div className="w-48 bg-gray-200 rounded-full h-2">
                        <div
                          className="bg-blue-600 h-2 rounded-full transition-all"
                          style={{ width: `${pct}%` }}
                        />
                      </div>
                      <span className="text-gray-600 text-sm w-16 text-right">
                        {f.count} hits
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* Top Departments */}
        {summaryData?.top_departments && summaryData.top_departments.length > 0 && (
          <div className="bg-white rounded-lg shadow-md p-6 mb-8">
            <h2 className="text-xl font-bold text-gray-900 mb-4">Top Departments</h2>
            <div className="space-y-3">
              {summaryData.top_departments.map((dept, index) => (
                <div key={index} className="flex items-center justify-between">
                  <span className="text-gray-700 font-medium">{dept.name}</span>
                  <div className="flex items-center space-x-3">
                    <div className="w-48 bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-blue-600 h-2 rounded-full"
                        style={{ width: `${dept.percentage || 0}%` }}
                      ></div>
                    </div>
                    <span className="text-gray-600 text-sm w-16 text-right">
                      {dept.count} uses
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Top Features */}
        {summaryData?.top_features && summaryData.top_features.length > 0 && (
          <div className="bg-white rounded-lg shadow-md p-6 mb-8">
            <h2 className="text-xl font-bold text-gray-900 mb-4">Most Used Features</h2>
            <div className="space-y-3">
              {summaryData.top_features.map((feature, index) => (
                <div key={index} className="flex items-center justify-between">
                  <span className="text-gray-700 font-medium">{feature.name}</span>
                  <div className="flex items-center space-x-3">
                    <div className="w-48 bg-gray-200 rounded-full h-2">
                      <div
                        className="bg-green-600 h-2 rounded-full"
                        style={{ width: `${feature.percentage || 0}%` }}
                      ></div>
                    </div>
                    <span className="text-gray-600 text-sm w-16 text-right">
                      {feature.count} uses
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* Top Users */}
        {summaryData?.top_users && summaryData.top_users.length > 0 && (
          <div className="bg-white rounded-lg shadow-md p-6 mb-8">
            <h2 className="text-xl font-bold text-gray-900 mb-4">Top Users</h2>
            <div className="overflow-x-auto">
              <table className="min-w-full divide-y divide-gray-200">
                <thead className="bg-gray-50">
                  <tr>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Rank
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      User
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Department
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Total Usage
                    </th>
                    <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                      Last Active
                    </th>
                  </tr>
                </thead>
                <tbody className="bg-white divide-y divide-gray-200">
                  {summaryData.top_users.map((user, index) => (
                    <tr key={index} className="hover:bg-gray-50">
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        #{index + 1}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap">
                        <div className="text-sm font-medium text-gray-900">{user.full_name}</div>
                        <div className="text-sm text-gray-500">{user.email}</div>
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {user.department || 'N/A'}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                        {user.total_count || 0}
                      </td>
                      <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                        {user.last_activity ? new Date(user.last_activity).toLocaleDateString() : 'N/A'}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* Footer Note */}
        <div className="mt-8 text-center text-sm text-gray-500">
          <p>
            {wsStatus === 'connected' && !wsStale
              ? 'Live stream connected · KPIs update in realtime'
              : 'Polling fallback active · auto-refresh every 5 minutes'}
          </p>
          <p className="mt-1">
            Last updated: {new Date().toLocaleString()}
          </p>
        </div>
      </div>
    </div>
  );
};

export default UsageDashboard;

import useAuthenticatedPhoto from '../hooks/useAuthenticatedPhoto'
import { useCurrentProfilePhoto } from '../components/Layout/ProfilePhotoContext'
import './UserDetail.css'
import rbacService from '../services/rbac.service'
import { radaiConfirm, radaiAlert } from '../services/radaiDialog'
/**
 * User Detail Page
 * Comprehensive user profile and activity view
 * Reusable pattern for detail pages across the system
 */

import React, { useEffect, useState } from 'react'
import { useParams, useNavigate } from 'react-router-dom'
import { useSelector } from 'react-redux'
import {
  UserIcon,
  EnvelopeIcon,
  PhoneIcon,
  BuildingOfficeIcon,
  BriefcaseIcon,
  CalendarIcon,
  ShieldCheckIcon,
  KeyIcon,
  ChartBarIcon,
  ClockIcon,
  CheckCircleIcon,
  XCircleIcon,
  ArrowLeftIcon,
  PencilIcon,
  TrashIcon,
  LockClosedIcon,
  UserPlusIcon
} from '@heroicons/react/24/outline'
import { API_BASE_URL } from '../config/api.config'

const normalizeUserProfile = (profile) => {
  const account = profile.user || {}
  const identity = profile.canonical_identity || {}
  return {
    ...profile,
    first_name: identity.first_name || account.first_name || '',
    last_name: identity.last_name || account.last_name || '',
    email: identity.email || account.email || '',
    is_active: account.is_active ?? false,
    is_staff: account.is_staff ?? false,
    is_superuser: account.is_superuser ?? false,
    department: identity.department || profile.department || '',
    job_title: identity.designation || profile.job_title || '',
    employee_number: identity.employee_number || profile.employee_id || '',
    login_account_id: identity.login_account_id || account.id,
    employee_uuid: identity.employee_uuid || profile.canonical_employee,
    access_profile_uuid: identity.access_profile_uuid || profile.id,
  }
}

/**
 * Reusable Detail Page Component
 * This pattern can be replicated for other entities
 */
const UserDetail = () => {
  const { id } = useParams()
  const navigate = useNavigate()
  const { user: currentUser } = useSelector((state) => state.auth)

  const [userData, setUserData] = useState(null)
  const [userModules, setUserModules] = useState([])
  const [userRoles, setUserRoles] = useState([])
  const [userActivity, setUserActivity] = useState([])
  const [activityError, setActivityError] = useState('')
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState(null)
  const [activeTab, setActiveTab] = useState('overview')
  const [photoFailed, setPhotoFailed] = useState(false)
  const sharedPhoto = useCurrentProfilePhoto()
  const isCurrentUser = userData && (String(userData.login_account_id) === String(sharedPhoto.userId) || (userData.email && userData.email === sharedPhoto.email))
  const managedPhoto = useAuthenticatedPhoto(userData && !isCurrentUser ? `/rbac/users/${id}/profile-photo/` : null, userData?.profile_photo)
  const profilePhoto = (isCurrentUser ? sharedPhoto.photo : managedPhoto) || userData?.profile_photo
  const [moduleSearch, setModuleSearch] = useState('')
  const [modulePage, setModulePage] = useState(1)
  useEffect(() => { setPhotoFailed(false) }, [id, profilePhoto])
  useEffect(() => { setModulePage(1); setModuleSearch('') }, [id])
  const matchingModules = userModules.filter(module => [module.name, module.code, module.description, typeof module === 'string' ? module : ''].some(value => String(value || '').toLowerCase().includes(moduleSearch.trim().toLowerCase())))
  const modulePages = Math.max(1, Math.ceil(matchingModules.length / 12))
  const currentModulePage = Math.min(modulePage, modulePages)
  const visibleModules = matchingModules.slice((currentModulePage - 1) * 12, currentModulePage * 12)

  useEffect(() => {
    fetchUserDetails()
  }, [id])

  const fetchUserDetails = async () => {
    try {
      setLoading(true)
      setError(null)
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access')
      const headers = {
        'Authorization': `Bearer ${token}`,
        'Content-Type': 'application/json'
      }

      // Fetch user data
      const userResponse = await fetch(`${API_BASE_URL}/rbac/users/${id}/`, { headers })
      if (!userResponse.ok) throw new Error('Failed to fetch user')
      const user = await userResponse.json()
      setUserData(normalizeUserProfile(user))

      // The profile response includes effective modules and active role assignments.
      setUserModules(Array.isArray(user.modules) ? user.modules : [])
      setUserRoles(Array.isArray(user.roles) ? user.roles : [])
      setUserActivity([])
      setActivityError('')
      try {
        const response = await rbacService.getAuditLogs({resource_type: 'UserProfile', resource_id: id, page_size: 20, ordering: '-timestamp'})
        setUserActivity(response.data?.results || (Array.isArray(response.data) ? response.data : []))
      } catch {
        setActivityError('Account activity is unavailable. Please try again later.')
      }

      setLoading(false)
    } catch (err) {
      console.error('Error fetching user details:', err)
      setError(err.message)
      setLoading(false)
    }
  }

  const handleDelete = async () => {
    if (!(await radaiConfirm('Are you sure you want to delete this user? This action cannot be undone.'))) {
      return
    }

    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access')
      const response = await fetch(`${API_BASE_URL}/rbac/users/${id}/`, {
        method: 'DELETE',
        headers: {
          'Authorization': `Bearer ${token}`
        }
      })

      if (!response.ok) throw new Error('Failed to delete user')

      await radaiAlert('User deleted successfully')
      navigate('/admin/users')
    } catch (err) {
      console.error('Error deleting user:', err)
      await radaiAlert('Failed to delete user')
    }
  }

  const handleToggleStatus = async () => {
    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access')
      const response = await fetch(`${API_BASE_URL}/rbac/users/${id}/`, {
        method: 'PATCH',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        },
        body: JSON.stringify({
          is_active: !userData.is_active
        })
      })

      if (!response.ok) throw new Error('Failed to update status')

      const updated = await response.json()
      setUserData(normalizeUserProfile(updated))
    } catch (err) {
      console.error('Error updating status:', err)
      await radaiAlert('Failed to update user status')
    }
  }

  const handleResetPassword = async () => {
    if (!(await radaiConfirm('Send password reset email to this user?'))) {
      return
    }

    try {
      const token = localStorage.getItem('radai_access_token') || localStorage.getItem('access')
      const response = await fetch(`${API_BASE_URL}/rbac/users/${id}/reset-password/`, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${token}`,
          'Content-Type': 'application/json'
        }
      })

      if (!response.ok) throw new Error('Failed to reset password')

      await radaiAlert('Password reset email sent successfully')
    } catch (err) {
      console.error('Error resetting password:', err)
      await radaiAlert('Failed to send password reset email')
    }
  }

  if (loading) {
    return (
      <div className="user-detail-workspace">
        <div className="ud-container">
          <div className="flex items-center justify-center py-20">
            <div className="relative">
              <div className="animate-spin rounded-full h-16 w-16 border-4 border-blue-200"></div>
              <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-blue-600 absolute top-0"></div>
            </div>
          </div>
        </div>
      </div>
    )
  }

  if (error || !userData) {
    return (
      <div className="user-detail-workspace">
        <div className="ud-container">
          <div className="bg-white rounded-2xl shadow-lg p-12 text-center">
            <XCircleIcon className="w-20 h-20 text-red-500 mx-auto mb-4" />
            <h2 className="text-2xl font-bold text-gray-900 mb-2">User Not Found</h2>
            <p className="text-gray-600 mb-6">{error || 'The user you are looking for does not exist.'}</p>
            <button
              onClick={() => navigate('/admin/users')}
              className="px-6 py-3 bg-blue-600 text-white rounded-xl hover:bg-blue-700 transition-colors font-medium"
            >
              Back to Users
            </button>
          </div>
        </div>
      </div>
    )
  }

  const tabs = [
    { id: 'overview', name: 'Overview', icon: UserIcon },
    { id: 'modules', name: 'Modules & Permissions', icon: KeyIcon },
    { id: 'roles', name: 'Roles', icon: ShieldCheckIcon },
    { id: 'activity', name: 'Activity Log', icon: ChartBarIcon }
  ]

  return (
    <div className="user-detail-workspace">
      <div className="ud-container">
        {/* Header */}
        <div className="ud-header">
          <button
            onClick={() => navigate('/admin/users')}
            className="ud-back"
          >
            <ArrowLeftIcon className="w-5 h-5" />
            Back to Users
          </button>

          <div className="ud-heading">
            <div>
              <h1 className="text-3xl font-bold text-gray-900 mb-2">User Details</h1>
              <p className="text-gray-600">Complete profile and activity information</p>
            </div>
            <div className="ud-actions">
              <button
                onClick={() => navigate('/admin/users')}
                className="ud-primary"
              >
                <PencilIcon className="w-5 h-5" />
                Edit
              </button>
              <button
                onClick={handleToggleStatus}
                className={`px-4 py-2 rounded-xl font-medium transition-all ${
                  userData.is_active
                    ? 'bg-yellow-100 text-yellow-700 hover:bg-yellow-200'
                    : 'bg-green-100 text-green-700 hover:bg-green-200'
                }`}
              >
                {userData.is_active ? 'Deactivate' : 'Activate'}
              </button>
              <button
                onClick={handleResetPassword}
                className="px-4 py-2 bg-purple-100 text-purple-700 rounded-xl hover:bg-purple-200 transition-colors flex items-center gap-2"
              >
                <LockClosedIcon className="w-5 h-5" />
                Reset Password
              </button>
              {currentUser?.is_superuser && (
                <button
                  onClick={handleDelete}
                  className="px-4 py-2 bg-red-100 text-red-700 rounded-xl hover:bg-red-200 transition-colors flex items-center gap-2"
                >
                  <TrashIcon className="w-5 h-5" />
                  Delete
                </button>
              )}
            </div>
          </div>
        </div>

        {/* Profile Card */}
        <div className="ud-profile">
          <div className="flex items-start justify-between">
            <div className="flex items-center gap-6">
              <div className="ud-avatar">
                {profilePhoto && !photoFailed ? <img key={profilePhoto} src={profilePhoto} alt={`${userData.first_name} ${userData.last_name}`} onError={() => setPhotoFailed(true)} /> : <>{userData.first_name?.[0]}{userData.last_name?.[0]}</>}
              </div>
              <div>
                <h2 className="text-3xl font-bold mb-2">
                  {userData.first_name} {userData.last_name}
                </h2>
                <p className="text-blue-100 text-lg mb-3">{userData.email}</p>
                <div className="flex flex-wrap gap-2">
                  {userData.is_superuser && (
                    <span className="px-3 py-1 bg-yellow-400 text-yellow-900 rounded-full text-sm font-semibold">
                      Super Admin
                    </span>
                  )}
                  {userData.is_staff && (
                    <span className="px-3 py-1 bg-purple-400 text-purple-900 rounded-full text-sm font-semibold">
                      Staff
                    </span>
                  )}
                  {userData.is_active ? (
                    <span className="px-3 py-1 bg-green-400 text-green-900 rounded-full text-sm font-semibold flex items-center gap-1">
                      <CheckCircleIcon className="w-4 h-4" />
                      Active
                    </span>
                  ) : (
                    <span className="px-3 py-1 bg-red-400 text-red-900 rounded-full text-sm font-semibold flex items-center gap-1">
                      <XCircleIcon className="w-4 h-4" />
                      Inactive
                    </span>
                  )}
                </div>
              </div>
            </div>
            <div className="text-right">
              <p className="text-blue-100 text-sm mb-1">Employee Number</p>
              <p className="text-2xl font-bold">#{userData.employee_number || 'Not assigned'}</p>
            </div>
          </div>
        </div>

        {/* Tabs */}
        <div className="ud-tabs-panel">
          <div className="ud-tabs">
            <div className="flex" role="tablist" aria-label="User details">
              {tabs.map((tab) => {
                const Icon = tab.icon
                return (
                  <button
                    key={tab.id}
                    role="tab" aria-selected={activeTab === tab.id}
                    onClick={() => setActiveTab(tab.id)}
                    className={`flex-1 px-6 py-4 flex items-center justify-center gap-2 font-medium transition-all ${
                      activeTab === tab.id
                        ? 'bg-blue-50 text-blue-600 border-b-2 border-blue-600'
                        : 'text-gray-600 hover:bg-gray-50'
                    }`}
                  >
                    <Icon className="w-5 h-5" />
                    {tab.name}
                 </button>
                )
              })}
            </div>
          </div>

          <div className="ud-tab-content">
            {/* Overview Tab */}
            {activeTab === 'overview' && (
              <div className="space-y-6">
                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {/* Contact Information */}
                  <div className="ud-panel">
                    <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2">
                      <EnvelopeIcon className="w-5 h-5 text-blue-600" />
                      Contact Information
                    </h3>
                    <div className="space-y-3">
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Email</p>
                        <p className="text-gray-900 font-medium">{userData.email}</p>
                      </div>
                      {userData.phone && (
                        <div>
                          <p className="text-sm text-gray-500 mb-1">Phone</p>
                          <p className="text-gray-900 font-medium">{userData.phone}</p>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Organization Information */}
                  <div className="ud-panel">
                    <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2">
                      <BuildingOfficeIcon className="w-5 h-5 text-purple-600" />
                      Organization
                    </h3>
                    <div className="space-y-3">
                      {userData.organization && (
                        <div>
                          <p className="text-sm text-gray-500 mb-1">Organization</p>
                          <p className="text-gray-900 font-medium">{userData.organization_name || userData.organization.name || userData.organization}</p>
                        </div>
                      )}
                      {userData.department && (
                        <div>
                          <p className="text-sm text-gray-500 mb-1">Department</p>
                          <p className="text-gray-900 font-medium">{userData.department}</p>
                        </div>
                      )}
                      {userData.job_title && (
                        <div>
                          <p className="text-sm text-gray-500 mb-1">Job Title</p>
                          <p className="text-gray-900 font-medium">{userData.job_title}</p>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Account Details */}
                  <div className="ud-panel">
                    <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2">
                      <CalendarIcon className="w-5 h-5 text-green-600" />
                      Account Details
                    </h3>
                    <div className="space-y-3">
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Canonical Employee UUID</p>
                        <p className="break-all font-mono text-sm text-gray-900">{userData.employee_uuid || 'Not linked'}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Login Account ID</p>
                        <p className="font-mono text-sm text-gray-900">{userData.login_account_id || 'Not linked'}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Access Profile UUID</p>
                        <p className="break-all font-mono text-sm text-gray-900">{userData.access_profile_uuid}</p>
                      </div>
                      <div>
                        <p className="text-sm text-gray-500 mb-1">Created At</p>
                        <p className="text-gray-900 font-medium">
                          {new Date(userData.created_at || userData.date_joined).toLocaleDateString('en-US', {
                            year: 'numeric',
                            month: 'long',
                            day: 'numeric',
                            hour: '2-digit',
                            minute: '2-digit'
                          })}
                        </p>
                      </div>
                      {userData.last_login && (
                        <div>
                          <p className="text-sm text-gray-500 mb-1">Last Login</p>
                          <p className="text-gray-900 font-medium">
                            {new Date(userData.last_login).toLocaleDateString('en-US', {
                              year: 'numeric',
                              month: 'long',
                              day: 'numeric',
                              hour: '2-digit',
                              minute: '2-digit'
                            })}
                          </p>
                        </div>
                      )}
                    </div>
                  </div>

                  {/* Statistics */}
                  <div className="ud-panel ud-statistics">
                    <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center gap-2">
                      <ChartBarIcon className="w-5 h-5 text-indigo-600" />
                      Statistics
                    </h3>
                    <div className="grid grid-cols-2 gap-4">
                      <div>
                        <p className="text-2xl font-bold text-blue-600">{userModules.length}</p>
                        <p className="text-sm text-gray-600">Modules</p>
                      </div>
                      <div>
                        <p className="text-2xl font-bold text-purple-600">{userRoles.length}</p>
                        <p className="text-sm text-gray-600">Roles</p>
                      </div>
                      <div>
                        <p className="text-2xl font-bold text-green-600">{activityError ? '?' : userActivity.length}</p>
                        <p className="text-sm text-gray-600">Recent account changes</p>
                      </div>
                      <div>
                        <p className="text-2xl font-bold text-orange-600">
                          {userData.is_active ? 'Active' : 'Inactive'}
                        </p>
                        <p className="text-sm text-gray-600">Status</p>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* Modules Tab */}
            {activeTab === 'modules' && (
              <div>
                <div className="flex items-center justify-between mb-6">
                   <span className="px-4 py-2 bg-blue-100 text-blue-700 rounded-xl font-semibold">
                    {userModules.length} Modules
                  </span>
                </div>
                <div className="ud-module-toolbar">
                  <input type="search" aria-label="Search assigned modules" placeholder="Search modules..." value={moduleSearch} onChange={event => { setModuleSearch(event.target.value); setModulePage(1) }} />
                  <span>{matchingModules.length} of {userModules.length} modules</span>
                </div>
                <ul className="ud-module-list" aria-label="Assigned modules">
                  {visibleModules.map((module, index) => <li key={module.id || module.code || index}>
                    <span className="ud-module-symbol"><KeyIcon /></span>
                    <div><strong>{module.name || module.code || module}</strong>{module.description && <p>{module.description}</p>}</div>
                  </li>)}
                </ul>
                {!matchingModules.length && <p className="ud-module-empty">{userModules.length ? 'No modules match your search.' : 'No modules assigned.'}</p>}
                <div className="ud-module-pagination">
                  <span>Showing {matchingModules.length ? (currentModulePage - 1) * 12 + 1 : 0}&ndash;{Math.min(currentModulePage * 12, matchingModules.length)} of {matchingModules.length}</span>
                  <div><button disabled={currentModulePage === 1} onClick={() => setModulePage(currentModulePage - 1)}>Previous</button><span>Page {currentModulePage} of {modulePages}</span><button disabled={currentModulePage === modulePages} onClick={() => setModulePage(currentModulePage + 1)}>Next</button></div>
                </div>
              </div>
            )}

            {/* Roles Tab */}
            {activeTab === 'roles' && (
              <div>
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-xl font-bold text-gray-900">Assigned Roles</h3>
                  <span className="px-4 py-2 bg-purple-100 text-purple-700 rounded-xl font-semibold">
                    {userRoles.length} Roles
                  </span>
                </div>
                {userRoles.length > 0 ? (
                  <div className="space-y-4">
                    {userRoles.map((role, index) => (
                      <div
                        key={index}
                        className="ud-role"
                      >
                        <div className="flex items-start justify-between">
                          <div>
                            <h4 className="text-lg font-bold text-gray-900 mb-2">
                              {role.name || role}
                            </h4>
                            {role.description && (
                              <p className="text-gray-600 mb-3">{role.description}</p>
                            )}
                            {role.permissions && role.permissions.length > 0 && (
                              <div className="flex flex-wrap gap-2">
                                {role.permissions.slice(0, 5).map((perm, idx) => (
                                  <span
                                    key={idx}
                                    className="px-3 py-1 bg-white rounded-lg text-sm text-gray-700 border border-purple-200"
                                  >
                                    {perm.name || perm}
                                  </span>
                                ))}
                                {role.permissions.length > 5 && (
                                  <span className="px-3 py-1 bg-white rounded-lg text-sm text-gray-500 border border-gray-200">
                                    +{role.permissions.length - 5} more
                                  </span>
                                )}
                              </div>
                            )}
                          </div>
                          <ShieldCheckIcon className="w-8 h-8 text-purple-600" />
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <ShieldCheckIcon className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                    <p className="text-gray-600">No roles assigned</p>
                  </div>
                )}
              </div>
            )}

            {/* Activity Tab */}
            {activeTab === 'activity' && (
              <div>
                <div className="flex items-center justify-between mb-6">
                  <h3 className="text-xl font-bold text-gray-900">Recent Activity</h3>
                  <span className="px-4 py-2 bg-green-100 text-green-700 rounded-xl font-semibold">
                    {userActivity.length} Activities
                  </span>
                </div>
                {userActivity.length > 0 ? (
                  <div className="space-y-3">
                    {userActivity.map((activity, index) => (
                      <div
                        key={index}
                        className="ud-activity"
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-3">
                            <ClockIcon className="w-5 h-5 text-gray-400" />
                            <div>
                              <p className="font-medium text-gray-900">
                                {activity.action || activity.description || 'User activity'}
                              </p>
                              {activity.details && (
                                <p className="text-sm text-gray-600">{activity.details}</p>
                              )}
                            </div>
                          </div>
                          <span className="text-sm text-gray-500">
                            {new Date(activity.created_at || activity.timestamp).toLocaleString()}
                          </span>
                        </div>
                      </div>
                    ))}
                  </div>
                ) : (
                  <div className="text-center py-12">
                    <ChartBarIcon className="w-16 h-16 text-gray-400 mx-auto mb-4" />
                    <p className="text-gray-600">{activityError || 'No account activity recorded'}</p>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

