const initialState = {
  features: [],
  navigation: [],
  categories: [],
  selectedFeature: null,
  loading: false,
  error: null,
  initialized: false
}

const featureSlice = createSlice({
  name: 'features',
  initialState,
  reducers: {
    setSelectedFeature: (state, action) => {
      state.selectedFeature = action.payload
    },
    clearError: (state) => {
      state.error = null
    },
    resetFeatures: (state) => {
      return initialState
    }
  },
  extraReducers: (builder) => {
    builder
      // Fetch features
      .addCase(fetchFeatures.pending, (state) => {
        state.loading = true
        state.error = null
      })
      .addCase(fetchFeatures.fulfilled, (state, action) => {
        state.loading = false
        state.features = action.payload.features || []
        state.initialized = true
      })
      .addCase(fetchFeatures.rejected, (state, action) => {
        state.loading = false
        state.error = action.payload
      })
      
      // Fetch navigation
      .addCase(fetchNavigation.pending, (state) => {
        state.loading = true
      })
      .addCase(fetchNavigation.fulfilled, (state, action) => {
        state.loading = false
        state.navigation = action.payload.navigation || []
      })
      .addCase(fetchNavigation.rejected, (state, action) => {
        state.loading = false
        state.error = action.payload
      })
      
      // Fetch categories
      .addCase(fetchCategories.fulfilled, (state, action) => {
        state.categories = action.payload.categories || []
      })
  }
})

export const { setSelectedFeature, clearError, resetFeatures } = featureSlice.actions

